def _label_format(fmt):
    """Formatos FÍSICOS de etiqueta soportados.

    Por pedido del usuario (2026-05-13): SOLO existen 2 tamaños reales
    en producción — los formatos 150x70 y 100x70 NO EXISTEN físicamente
    y fueron eliminados de toda la base.

    Tamaños válidos:
      • "100x150" → estándar (etiqueta grande, doblada en 2 caras)
      • "100x50"  → etiqueta chica

    NOTA TÉCNICA: la "key" interna ("150x100" y "100x50") es lo que el
    template label_standalone.html usa para aplicar CSS (.label-150x100,
    .label-100x50). El usuario ve "100 × 150 mm" porque es como ILUS
    nombra el papel termico (lado corto × lado largo). Internamente
    Playwright genera el PDF a 150mm × 100mm landscape que es como están
    calibradas las impresoras.
    """
    formats = {
        "100x150": {"key": "150x100", "w": "150mm", "h": "100mm", "label": "100 × 150 mm (estándar)"},
        "100x50":  {"key": "100x50",  "w": "100mm", "h": "50mm",  "label": "100 × 50 mm"},
        # Aliases para compat con código viejo que aún use las keys antiguas:
        "150x100": {"key": "150x100", "w": "150mm", "h": "100mm", "label": "100 × 150 mm (estándar)"},
    }
    return formats.get(fmt, formats["100x150"])


def _label_bulto_data(bulto):
    data = dict(bulto)
    largo = float(data.get("largo_cm") or data.get("largo") or 0)
    ancho = float(data.get("ancho_cm") or data.get("ancho") or 0)
    alto = float(data.get("alto_cm") or data.get("alto") or 0)
    kg = float(data.get("kg") or data.get("peso") or data.get("peso_bruto") or 0)
    data.update({
        "largo": largo,
        "ancho": ancho,
        "alto": alto,
        "largo_cm": largo,
        "ancho_cm": ancho,
        "alto_cm": alto,
        "kg": kg,
        "peso": kg,
        "peso_vol": calc_pv(largo, ancho, alto),
    })
    return data


def build_labels_pdf(product, label_bultos, total_bultos, fmt="150x100"):
    """
    Genera un PDF con una o mas etiquetas usando Playwright (Chromium headless).
    El resultado es pixel-perfect idéntico al HTML preview porque usa
    el mismo template label_standalone.html y el mismo @media print CSS.
    Si Playwright no está instalado, lanza ImportError con instrucción de instalación.
    """
    # Hora Chile para que la etiqueta muestre la fecha correcta al usuario
    fecha        = _now_chile_str("%d-%m-%Y %H:%M")
    label_format = _label_format(fmt)
    enriched     = [_label_bulto_data(b) for b in label_bultos]

    html = render_template(
        "label_standalone.html",
        product      = product,
        bultos       = enriched,
        total_bultos = total_bultos,
        fecha        = fecha,
        qty_per_bulto= {},
        logo_url     = _logo_data_url(),
        fmt          = label_format["key"],
        label_format = label_format,
    )

    # Usa el browser pool — sin overhead de launch/close
    return _pw_pdf(
        html,
        width  = label_format["w"],
        height = label_format["h"],
        wait_fn = (
            "() => {"
            "  const codes = Array.from(document.querySelectorAll('.barcode'));"
            "  return codes.length > 0 && codes.every(c => c.dataset.rendered === '1');"
            "}"
        ),
    )


def build_label_pdf(product, bulto, total_bultos, fmt="150x100"):
    return build_labels_pdf(product, [bulto], total_bultos, fmt)


# ── Mantener la antigua firma por compatibilidad ── (ya no usa reportlab)
def _build_label_pdf_legacy(product, bulto, total_bultos):
    """Fallback ReportLab — ya no se usa, conservado como referencia."""
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas
    from reportlab.pdfbase import pdfmetrics
    from reportlab.graphics.barcode import code128

    W, H    = 150 * mm, 70 * mm
    HALF    = W / 2                 # 75 mm por cara
    HDR_H   = 14 * mm
    META_H  =  8 * mm
    NAME_H  =  9 * mm
    FTR_H   =  5 * mm
    hdr_y   = H - HDR_H
    meta_y  = hdr_y - META_H
    name_y  = meta_y - NAME_H
    body_y  = FTR_H
    body_h  = name_y - body_y      # ≈ 34mm

    BLACK = colors.black
    WHITE = colors.white
    GRAY  = colors.HexColor("#aaaaaa")
    DGRAY = colors.HexColor("#2c2c2c")

    buf   = io.BytesIO()
    c     = canvas.Canvas(buf, pagesize=(W, H))
    fecha = _now_chile_str("%d-%m-%Y %H:%M")  # Hora Chile

    # ── Intenta cargar logo (convertido a blanco via Pillow si está disponible) ──
    logo_img_path = None
    try:
        from PIL import Image as PILImage
        import tempfile
        src = os.path.join(app.static_folder, "Logo.png")
        if os.path.exists(src):
            img = PILImage.open(src).convert("RGBA")
            r, g, b, a = img.split()
            white_bg = PILImage.new("RGBA", img.size, (0, 0, 0, 255))
            # Pintar píxeles no-transparentes de blanco
            white_layer = PILImage.new("RGBA", img.size, (255, 255, 255, 255))
            white_bg.paste(white_layer, mask=a)
            tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            white_bg.save(tmp.name)
            logo_img_path = tmp.name
    except Exception:
        logo_img_path = None

    def draw_half(ox):
        # ══════════════════════════════════════════
        #  HEADER  (negro, 14mm)
        # ══════════════════════════════════════════
        c.setFillColor(BLACK)
        c.rect(ox, hdr_y, HALF, HDR_H, fill=1, stroke=0)

        # Proporciones: SHS izq 40% | ILUS der 60%
        shs_w  = HALF * 0.40
        ilus_w = HALF * 0.60
        shs_cx = ox + shs_w / 2
        ilus_x = ox + shs_w          # borde derecho de SHS = borde izq de ILUS
        ilus_cx = ilus_x + ilus_w / 2

        # Separador interno
        c.setStrokeColor(DGRAY)
        c.setLineWidth(0.6)
        c.line(ilus_x, hdr_y + 1*mm, ilus_x, hdr_y + HDR_H - 1*mm)

        # — Sports Health Solutions (izquierda) —
        c.setFillColor(WHITE)
        c.setFont("Helvetica-Bold", 8)
        c.drawCentredString(shs_cx, hdr_y + 9.2*mm, "SPORTS")
        c.drawCentredString(shs_cx, hdr_y + 5.8*mm, "HEALTH")
        c.setFillColor(GRAY)
        c.setFont("Helvetica-Oblique", 4)
        c.drawCentredString(shs_cx, hdr_y + 2.2*mm, "S O L U T I O N S")

        # — Logo ILUS (derecha) —
        if logo_img_path:
            try:
                lh = HDR_H * 0.78
                lw = ilus_w * 0.82
                c.drawImage(logo_img_path,
                            ilus_cx - lw / 2,
                            hdr_y + (HDR_H - lh) / 2,
                            width=lw, height=lh,
                            preserveAspectRatio=True, mask='auto')
            except Exception:
                _draw_ilus_text(ilus_cx)
        else:
            _draw_ilus_text(ilus_cx)

    def _draw_ilus_text(cx):
        """Fallback: texto ILUS. en blanco cuando no hay imagen."""
        c.setFillColor(WHITE)
        c.setFont("Helvetica-Bold", 18)
        iw = pdfmetrics.stringWidth("ILUS.", "Helvetica-Bold", 18)
        # cx es el centro de la zona ILUS dentro de la cara actual
        c.drawCentredString(cx, hdr_y + 4*mm, "ILUS.")

    def draw_body(ox):
        # ══════════════════════════════════════════
        #  META BAR  (blanco, 8mm)
        # ══════════════════════════════════════════
        c.setFillColor(WHITE)
        c.rect(ox, meta_y, HALF, META_H, fill=1, stroke=0)
        c.setStrokeColor(BLACK)
        c.setLineWidth(0.8)
        c.line(ox, meta_y,          ox + HALF, meta_y)
        c.line(ox, meta_y + META_H, ox + HALF, meta_y + META_H)

        ty = meta_y + META_H / 2 - 1.4*mm

        # Ícono caja (aproximación con rectángulo)
        cx_icon = ox + 5*mm
        c.setFillColor(BLACK)
        c.setLineWidth(0.6)
        c.rect(cx_icon - 1.4*mm, ty + 0.3*mm, 2.8*mm, 2.8*mm, fill=0, stroke=1)

        c.setFont("Helvetica-Bold", 6.5)
        c.setFillColor(BLACK)
        c.drawString(ox + 7.5*mm, ty,
                     f"BULTO {bulto['bulto_num']} DE {total_bultos}")

        # Separador |
        sep_x = ox + HALF * 0.52
        c.setFont("Helvetica", 10)
        c.setFillColor(GRAY)
        c.drawCentredString(sep_x, ty - 0.5*mm, "|")

        c.setFont("Helvetica-Bold", 6.5)
        c.setFillColor(BLACK)
        c.drawString(sep_x + 2.5*mm, ty, "PESO BRUTO")
        c.setFont("Helvetica-Bold", 7)
        c.drawRightString(ox + HALF - 2*mm, ty,
                          f"{float(bulto['peso']):.0f} KG")

        # ══════════════════════════════════════════
        #  NOMBRE PRODUCTO  (blanco, 9mm)
        # ══════════════════════════════════════════
        c.setFillColor(WHITE)
        c.rect(ox, name_y, HALF, NAME_H, fill=1, stroke=0)
        c.setStrokeColor(BLACK)
        c.setLineWidth(0.8)
        c.line(ox, name_y, ox + HALF, name_y)

        nombre = (product["nombre"] or "").upper()
        avail  = HALF - 5*mm
        fs_n   = 7.5
        while pdfmetrics.stringWidth(nombre, "Helvetica-Bold", fs_n) > avail and fs_n > 4.5:
            fs_n -= 0.15
        c.setFont("Helvetica-Bold", fs_n)
        c.setFillColor(BLACK)
        # Si cabe en una línea
        if pdfmetrics.stringWidth(nombre, "Helvetica-Bold", fs_n) <= avail:
            c.drawString(ox + 2.5*mm, name_y + NAME_H/2 - 1.3*mm, nombre)
        else:
            # Partir en dos líneas
            mid = len(nombre) // 2
            cut = nombre.rfind(" ", 0, mid + 10) or mid
            c.setFont("Helvetica-Bold", max(fs_n - 0.3, 5.0))
            c.drawString(ox + 2.5*mm, name_y + NAME_H - 3.8*mm, nombre[:cut].strip())
            c.drawString(ox + 2.5*mm, name_y + 1.8*mm,          nombre[cut:].strip())

        # ══════════════════════════════════════════
        #  BODY  (dims izq 50% | código der 50%)
        # ══════════════════════════════════════════
        dims_w   = HALF * 0.50
        dims_end = ox + dims_w
        bc_x     = dims_end + 0.5*mm          # inicio columna código
        bc_w     = HALF - dims_w - 0.5*mm     # ancho disponible código

        # Separador vertical dims | código
        c.setStrokeColor(BLACK)
        c.setLineWidth(0.8)
        c.line(dims_end, body_y, dims_end, name_y)

        # — Dimensiones (4 filas centradas verticalmente) —
        rows = [
            ("↔",  "LARGO:",     f"{float(bulto['largo']):.0f} cm"),
            ("↕",  "ALTO:",      f"{float(bulto['alto']):.0f} cm"),
            ("⊞",  "ANCHO:",     f"{float(bulto['ancho']):.0f} cm"),
            ("🔒", "PESO VOL.:", f"{float(bulto['peso_vol']):.2f} Vol"),
        ]
        row_h  = body_h / len(rows)
        lbl_x  = ox + 3*mm      # inicio etiqueta (3mm desde borde izq)
        val_x  = dims_end - 1*mm  # valores anclados a la derecha

        for i, (ico, lbl, val) in enumerate(rows):
            ry = name_y - (i + 0.62) * row_h

            # Etiqueta
            c.setFont("Helvetica-Bold", 5.5)
            c.setFillColor(BLACK)
            c.drawString(lbl_x, ry, lbl)

            # Valor (ancla derecha)
            c.setFont("Helvetica-Bold", 6.5)
            c.drawRightString(val_x, ry, val)

        # — Barcode CODE128 —
        bc_val = (product["sku"] or "000")[:30]

        # Reservar espacio: barcode + SKU box + fecha
        sku_h    = body_h * 0.30     # caja SKU negra
        fecha_h  = 3   * mm          # línea de fecha
        bc_h     = body_h - sku_h - fecha_h - 1.5*mm  # altura barras

        bw_pt = 1.0 if len(bc_val) > 20 else (0.85 if len(bc_val) > 12 else 1.0)
        bc_y  = body_y + sku_h + fecha_h + 0.5*mm

        try:
            bar = code128.Code128(bc_val, barWidth=bw_pt,
                                  barHeight=bc_h, humanReadable=False, quiet=False)
            while bar.width > bc_w - 1*mm and bw_pt > 0.35:
                bw_pt -= 0.04
                bar = code128.Code128(bc_val, barWidth=bw_pt,
                                      barHeight=bc_h, humanReadable=False, quiet=False)
            bc_cx = bc_x + bc_w / 2
            bar.drawOn(c, bc_cx - bar.width / 2, bc_y)
        except Exception:
            pass

        # — Caja negra CÓDIGO / SKU —
        sku_y = body_y + fecha_h
        c.setFillColor(BLACK)
        c.rect(bc_x, sku_y, bc_w, sku_h, fill=1, stroke=0)

        c.setFont("Helvetica-Bold", 3.8)
        c.setFillColor(GRAY)
        c.drawCentredString(bc_x + bc_w / 2, sku_y + sku_h - 2.2*mm, "CÓDIGO / SKU")

        sku_val = product["sku"]
        fs_s    = 9.5
        while pdfmetrics.stringWidth(sku_val, "Helvetica-Bold", fs_s) > bc_w - 2*mm and fs_s > 5:
            fs_s -= 0.3
        c.setFont("Helvetica-Bold", fs_s)
        c.setFillColor(WHITE)
        c.drawCentredString(bc_x + bc_w / 2, sku_y + sku_h * 0.20, sku_val)

        # — Fecha bajo el SKU box (horizontal, no interfiere con el barcode) —
        c.setFont("Helvetica", 3.5)
        c.setFillColor(GRAY)
        c.drawCentredString(bc_x + bc_w / 2, body_y + 0.6*mm, fecha)

    # ── Dibuja las dos caras ──────────────────────────────────────────
    draw_half(0)
    draw_body(0)
    draw_half(HALF)
    draw_body(HALF)

    # ── Borde exterior ────────────────────────────────────────────────
    c.setStrokeColor(BLACK)
    c.setLineWidth(0.8)
    c.rect(0, 0, W, H, fill=0, stroke=1)

    # ── Línea de doblez central (punteada) ───────────────────────────
    c.setStrokeColor(colors.HexColor("#999999"))
    c.setLineWidth(0.6)
    c.setDash([2.5, 2.5])
    c.line(HALF, 0, HALF, H)
    c.setDash([])

    # ── Footer: franjas diagonales B&W  (-45°, igual que el HTML) ────
    c.setFillColor(BLACK)
    c.rect(0, 0, W, FTR_H, fill=1, stroke=0)
    c.setFillColor(WHITE)
    sg, sw = 8*mm, 4*mm
    for i in range(-2, int(W / sg) + 4):
        x0 = i * sg
        p  = c.beginPath()
        p.moveTo(x0, 0);            p.lineTo(x0 + sw, 0)
        p.lineTo(x0 + sw + FTR_H, FTR_H); p.lineTo(x0 + FTR_H, FTR_H)
        p.close()
        c.drawPath(p, fill=1, stroke=0)
    c.setStrokeColor(BLACK)
    c.setLineWidth(0.8)
    c.line(0, FTR_H, W, FTR_H)

    c.save()
    buf.seek(0)

    # Limpiar archivo temporal del logo blanco
    if logo_img_path:
        try:
            os.unlink(logo_img_path)
        except Exception:
            pass

    return buf.read()   # fin de _build_label_pdf_legacy


# ─────────────────────────────────────────────
#  Context processor
# ─────────────────────────────────────────────
# _mant_cotizaciones_on() (feature flag del sistema viejo de cotizaciones)
# retirada 2026-07-18 junto con el resto del módulo — ver comentario en el
# bloque original (cerca de "COTIZADOR DE MANTENCIONES") y tk_cotizaciones
# (tickets_module) como sistema vivo.


@app.context_processor
def inject_globals():
    _role = (g.user["role"] if g.user else "") or ""
    # 2026-06-09 (Daniel) — flag único reusable en TODOS los templates:
    # ¿el usuario es un rol de GESTIÓN que puede editar/reagendar visitas?
    # Calculado con el MISMO `_rol_familia()` que usa el backend
    # (`_puede_ot_accion('metadata')`) para que el frontend NUNCA se
    # desincronice de la matriz de permisos real. Familias de gestión:
    # superadmin, admin, supervisor, ejecutivo (ej. Aaron 'ejecutivo_sstt').
    try:
        _puede_gestionar_visitas = _rol_familia(_role) in (
            "superadmin", "admin", "supervisor", "ejecutivo")
    except Exception:
        _puede_gestionar_visitas = (_role in ("superadmin", "admin"))
    # Marca dinámica disponible en TODOS los templates como {{ marca.name }},
    # {{ marca.logo_url }}, etc. Daniel edita comm_client_config en
    # /comunicaciones y cambia inmediatamente en el front (login, footer,
    # emails, etc) sin reiniciar.
    try:
        _marca_ctx = _get_marca()
    except Exception:
        _marca_ctx = {
            "name": "ILUS Fitness",
            "logo_url": "https://ilusfitness.com/cdn/shop/files/Logo_ILUS_Fitness_Blanco_equipamiento_para_gimnasios.png",
            "corp_color": "#DC143C",
        }
    return {
        "has_logo":    os.path.exists(os.path.join(app.static_folder, "Logo.png")),
        "current_user": g.user,
        "permissions":  g.permissions,
        "role_label":   {
                            "superadmin": "Super Administrador",
                            "admin":      "Administrador",
                            "ejecutivo":  "Ejecutivo",
                            "editor":     "Editor",
                            "lector":     "Lector",
                            "vendedor":   "Vendedor",
                            "tecnico":    "Técnico",
                        }.get(_role, "Usuario"),
        # Flag global para todos los templates: True si el usuario es 'tecnico' (solo lectura).
        # Permite ocultar botones de edición/creación/borrado sin tocar cada template.
        "is_tecnico":   (_role == "tecnico"),
        # 2026-08-27: versión NORMALIZADA de lo anterior. `is_tecnico`
        # compara el string exacto, así que NO reconoce 'tecnico_externo'
        # ni 'tecnico_jr' — la misma clase de bug que se endureció en el
        # backend con `_no_tecnico` (2026-08-09). Este usa `_rol_familia()`,
        # igual que la matriz de permisos real. No se toca `is_tecnico`
        # para no cambiarle el comportamiento a las plantillas que ya lo usan.
        "es_tecnico":   _es_rol_tecnico(),
        # 2026-06-09 (Daniel): roles de gestión (admin/supervisor/ejecutivo/
        # superadmin) pueden editar y REAGENDAR visitas. Usado por el modal
        # del calendario para habilitar campos + botón Guardar. Espejo exacto
        # del gate backend `_puede_ot_accion('metadata')`.
        "puede_gestionar_visitas": _puede_gestionar_visitas,
        # is_superadmin global: permite mostrar bloques de diagnóstico (campos
        # crudos del ERP, etc.) SOLO al superadmin, no a operación normal.
        "is_superadmin": (_role == "superadmin"),
        "photo_src":    _photo_src,
        # Modo embebido (iframe): default False; los endpoints que aceptan
        # ?embed=1 pueden sobreescribir pasando embed_mode=True en su render.
        "embed_mode":   False,
        # Google Maps API Key — si está vacía, el frontend hace fallback
        # a input de texto plano (sin autocomplete de direcciones).
        "google_maps_api_key": GOOGLE_MAPS_API_KEY,
        # Marca dinámica (lectura BD comm_client_config + env vars).
        # Disponible en todos los templates como {{ marca.name }} etc.
        "marca": _marca_ctx,
    }


# ─────────────────────────────────────────────
#  API — Búsqueda en ERP externo (SOLO LECTURA)
# ─────────────────────────────────────────────

@app.route("/api/sku-lookup")
@login_required
def sku_lookup():
    """
    Búsqueda exacta por SKU — usada por el escáner de código de barras.
    Responde en <50ms sin recargar la página.
    Devuelve: {status, pid?, sku, nombre, prepare_url?}
    """
    sku = request.args.get("sku", "").strip().upper()
    if not sku:
        return jsonify({"status": "not_found", "sku": ""})

    # ── 1. Buscar en app_products (nuestra BD) ───────────────────────
    hit = mysql_fetchone(
        f"SELECT id, nombre, sku FROM `{PRODUCTS_TABLE}` WHERE UPPER(TRIM(sku)) = %s",
        (sku,)
    )
    if hit:
        return jsonify({
            "status":     "found_app",
            "pid":        hit["id"],
            "sku":        hit["sku"],
            "nombre":     (hit["nombre"] or "").strip(),
            "detail_url": url_for("product_detail", pid=hit["id"]),
            "edit_url":   url_for("edit_product",   pid=hit["id"]),
        })

    # ── 2. Buscar en tabla ERP local ─────────────────────────────────
    erp_hit = None
    try:
        erp_hit = mysql_fetchone(
            f"SELECT UPPER(TRIM(`SKU`)) AS sku, TRIM(COALESCE(`Nombre`,'')) AS nombre "
            f"FROM `{ERP_TABLE}` WHERE UPPER(TRIM(`SKU`)) = %s",
            (sku,)
        )
    except Exception:
        pass

    if erp_hit:
        return jsonify({
            "status":      "found_erp",
            "sku":         erp_hit["sku"],
            "nombre":      (erp_hit["nombre"] or "").strip(),
            "prepare_url": url_for("prepare_product_from_erp", sku=erp_hit["sku"]),
        })

    # ── 3. REST API ERP — búsqueda exacta por código ─────────────────
    try:
        TOKEN = ERP_CONFIG.get("api_token", "")
        body  = _erp_get(
            "/productos",
            {"kopr": sku, "empresa": "01", "fields": "KOPR,NOKOPR", "visible": "true"},
            TOKEN, timeout=6,
        )
        items = body.get("data") or []
        if items:
            p = items[0]
            p_sku  = (p.get("KOPR") or "").strip().upper()
            p_name = (p.get("NOKOPR") or "").strip()
            if p_sku:
                return jsonify({
                    "status":      "found_erp",
                    "sku":         p_sku,
                    "nombre":      p_name,
                    "prepare_url": url_for("prepare_product_from_erp", sku=p_sku),
                })
    except Exception:
        pass

    return jsonify({"status": "not_found", "sku": sku})


@app.route("/api/product-search")
@require_permission("view")
def product_search():
    """
    Typeahead unificado para el formulario de nuevo producto.
    Fuentes: app_products → tabla ERP local → ERP REST API (fallback).

    Devuelve JSON con envelope:
      {
        "items": [{sku, nombre, source, already_exists}, ...],
        "erp_api_ok": bool,        # True si la REST API del ERP respondió OK
        "erp_api_error": str|None  # mensaje del fallo (para diagnóstico)
      }

    Compat retro: si el frontend espera un array plano (versión antigua),
    debe migrarse a leer .items — el envelope no rompe nada porque arrays
    JSON y objetos son distinguibles client-side.

    ════════════════════════════════════════════════════════════════════
    NOTA CRÍTICA (bug 2026-05-19):
    La tabla local `etiquetas` (ERP_TABLE) es un MIRROR de app_products
    via sync_erp_table(), NO un cache del catálogo ERP completo. Por
    eso, cuando la REST API del ERP cae (HTTP 502), la fuente #2 NO
    aporta SKUs "nuevos" — solo devuelve los mismos que ya están en
    app_products. Resultado: TODOS los items aparecían como "Ya
    registrado" cuando en realidad faltaba la fuente externa.
    FIX: devolver erp_api_ok=False para que el frontend muestre banner.
    ════════════════════════════════════════════════════════════════════
    """
    q = request.args.get("q", "").strip()
    if len(q) < 2:
        return jsonify({"items": [], "erp_api_ok": True, "erp_api_error": None})

    like_u  = f"%{q.upper()}%"
    results = []
    seen    = set()
    erp_api_ok = True
    erp_api_error = None

    # ── 1. app_products ──────────────────────────────────────────────
    try:
        rows = mysql_fetchall(
            f"""SELECT sku, nombre FROM `{PRODUCTS_TABLE}`
                WHERE UPPER(sku) LIKE %s OR UPPER(nombre) LIKE %s
                ORDER BY
                  CASE WHEN UPPER(sku) = %s THEN 0 ELSE 1 END,
                  nombre
                LIMIT 10""",
            (like_u, like_u, q.upper()),
        )
        for r in rows:
            sku = (r.get("sku") or "").strip().upper()
            if sku and sku not in seen:
                results.append({"sku": sku, "nombre": (r.get("nombre") or "").strip(),
                                 "source": "app", "already_exists": True})
                seen.add(sku)
    except Exception:
        pass

    # ── 2. Tabla ERP local ───────────────────────────────────────────
    # Esta tabla es un mirror de app_products+app_bultos (ver sync_erp_table).
    # Todo SKU que aparezca aquí ya está registrado por definición.
    try:
        rows2 = mysql_fetchall(
            f"""SELECT UPPER(TRIM(`SKU`)) AS sku,
                       TRIM(COALESCE(`Nombre`,'')) AS nombre
                FROM `{ERP_TABLE}`
                WHERE UPPER(TRIM(`SKU`)) LIKE %s OR UPPER(`Nombre`) LIKE %s
                ORDER BY
                  CASE WHEN UPPER(TRIM(`SKU`)) = %s THEN 0 ELSE 1 END,
                  `Nombre`
                LIMIT 20""",
            (like_u, like_u, q.upper()),
        )
        for r in rows2:
            sku = (r.get("sku") or "").strip().upper()
            if not sku or sku in seen:
                continue
            # Marcamos already_exists=True por defecto: este es un mirror.
            # La verificación final confirma con app_products de todas formas.
            results.append({"sku": sku, "nombre": (r.get("nombre") or "").strip(),
                             "source": "erp", "already_exists": True})
            seen.add(sku)
    except Exception:
        pass

    # ⚡ PERF (Juan Daniel 2026-06-05): el SQL directo a Random es ~70x más
    # rápido que el REST API (MEDIDO: ~14ms vs ~0.8-1.2s). Respetamos el flag
    # global ILUS_ERP_PREFER_SQL (default "1"), igual que ya hacen cubicador y
    # retiros, para que la búsqueda de productos use SQL primero (baja de ~1s+
    # a ~15ms). El REST queda solo como respaldo si se desactiva el flag.
    _PREFER_SQL = (os.environ.get("ILUS_ERP_PREFER_SQL", "1").strip().lower()
                   in ("1", "true", "yes", "on"))

    # ── 3. REST API ERP /productos — SOLO si NO preferimos SQL ───────
    erp_api_tried = False
    if not _PREFER_SQL and len(q) >= 2:
        try:
            TOKEN = ERP_CONFIG.get("api_token", "")
            body  = _erp_get(
                "/productos",
                {
                    "search":  q,            # busca en código Y descripción
                    "empresa": "01",
                    "fields":  "KOPR,NOKOPR",
                    "visible": "true",
                    "venta":   "true",       # solo productos de venta (excluye servicios)
                },
                TOKEN, timeout=3,
            )
            erp_api_tried = True
            existing_skus = {r["sku"] for r in results}
            for p in (body.get("data") or []):
                p_sku  = (p.get("KOPR") or "").strip().upper()
                p_name = (p.get("NOKOPR") or "").strip()
                if not p_sku or p_sku in seen:
                    continue
                already = p_sku in existing_skus
                results.append({
                    "sku":           p_sku,
                    "nombre":        p_name,
                    "source":        "erp-api",
                    "already_exists": already,
                })
                seen.add(p_sku)
                if len(results) >= 25:
                    break
        except Exception as e:
            # REST API caída → marcar flag (sin banner UI; lo maneja fallback SQL).
            erp_api_ok = False
            try:
                msg = str(e)
                if len(msg) > 120:
                    msg = msg[:120] + "..."
                erp_api_error = f"{type(e).__name__}: {msg}"
            except Exception:
                erp_api_error = type(e).__name__

    # ── 4. SQL directo a MAEPR — PRINCIPAL si preferimos SQL, o respaldo si REST cae ──
    # 2026-05-19: si la REST API del ERP no responde, vamos directo al
    # SQL Server de Random (mismo que usa Transporte/Mantenciones). Esto
    # restaura el comportamiento de búsqueda CATÁLOGO completo del ERP.
    # 2026-06-05 (perf): con ILUS_ERP_PREFER_SQL=1 este es el camino PRINCIPAL
    # (~14ms vs ~1s del REST). Por eso la condición incluye _PREFER_SQL.
    if (_PREFER_SQL or not erp_api_ok) and len(q) >= 2:
        try:
            like_sql = f"%{q.upper()}%"
            erp_rows = _random_sql_query(
                f"""
                SELECT TOP 25
                       LTRIM(RTRIM(KOPR))   AS sku,
                       LTRIM(RTRIM(NOKOPR)) AS nombre
                  FROM {ERP_TABLE_PRODUCTS}
                 WHERE UPPER(LTRIM(RTRIM(KOPR)))   LIKE %s
                    OR UPPER(LTRIM(RTRIM(NOKOPR))) LIKE %s
                 ORDER BY KOPR
                """,
                (like_sql, like_sql),
                max_rows=25,
            ) or []
            existing_skus = {r["sku"] for r in results}
            for r in erp_rows:
                p_sku  = (r.get("sku") or "").strip().upper()
                p_name = (r.get("nombre") or "").strip()
                if not p_sku or p_sku in seen:
                    continue
                already = p_sku in existing_skus
                results.append({
                    "sku":           p_sku,
                    "nombre":        p_name,
                    "source":        "erp-sql",
                    "already_exists": already,
                })
                seen.add(p_sku)
                if len(results) >= 25:
                    break
            # SQL respondió OK → la búsqueda funcionó aunque la REST haya caído
            erp_api_ok = True
            erp_api_error = None
            print(f"[product-search] fallback SQL ERP exitoso: {len(erp_rows)} filas para q={q!r}", flush=True)
        except Exception as e2:
            print(f"[product-search] fallback SQL ERP falló: {type(e2).__name__}: {str(e2)[:200]}", flush=True)
            # Quedamos con erp_api_ok=False pero sin banner UI (Daniel pidió quitarlo)

    # ── Verificación final: consulta batch a app_products para todos los SKUs ──
    # Esto corrige casos donde la búsqueda por nombre falló (acentos/case) pero
    # el SKU SÍ existe en la BD (evita mostrar "No registrado" cuando ya está).
    if results:
        try:
            all_skus = list({r["sku"] for r in results})
            ph = ",".join(["%s"] * len(all_skus))
            verified = mysql_fetchall(
                f"SELECT UPPER(TRIM(sku)) AS sku FROM `{PRODUCTS_TABLE}` WHERE UPPER(TRIM(sku)) IN ({ph})",
                tuple(all_skus),
            )
            verified_set = {r["sku"] for r in (verified or [])}
            for r in results:
                r["already_exists"] = r["sku"] in verified_set
        except Exception:
            pass  # si falla la verificación, dejamos los valores anteriores

    # Ordenar: exactos primero, no-existentes primero, luego nombre
    results.sort(key=lambda x: (
        1 if x["already_exists"] else 0,
        0 if x["sku"] == q.upper() else 1,
        x["nombre"].lower()
    ))

    return jsonify({
        "items": results[:20],
        "erp_api_ok": erp_api_ok,
        "erp_api_error": erp_api_error,
    })


# ─────────────────────────────────────────────
#  Auth routes
# ─────────────────────────────────────────────

@app.route("/login", methods=["GET", "POST"])
@rate_limited("login", max_attempts=10, window_seconds=300)
def login():
    if g.user:
        return redirect(url_for("index"))
    next_url = request.args.get("next") or request.form.get("next") or url_for("index")
    # solo_activas=True → filtra WHERE activa=1 LIMIT 5 para el login público
    imgs = _login_images_active(solo_activas=True)
    if request.method == "POST":
        username = request.form.get("username", "").strip().lower()
        password = request.form.get("password", "")
        try:
            user = get_auth_user_by_username(username)
        except Exception as exc:
            _audit("login_error", details={"username": username, "error": str(exc)},
                   status="error")
            print(f"[login] error conectando para {username}: {exc}", flush=True)
            flash("No fue posible conectar con el servidor. Intenta nuevamente en unos segundos.", "danger")
            return render_template("login.html", next_url=next_url, username=username, login_images=imgs, marca=_get_marca())
        if not user or not user["active"] or not check_password_hash(user["password_hash"], password):
            reason = ("no_existe" if not user
                      else "inactivo" if not user["active"]
                      else "password_invalida")
            _audit("login_fail",
                   target_type="user", target_id=(user or {}).get("id"),
                   details={"username": username, "reason": reason},
                   status="fail")
            flash("Usuario o contraseña incorrectos.", "danger")
            return render_template("login.html", next_url=next_url, username=username, login_images=imgs, marca=_get_marca())
        session.clear()
        session["user_id"] = user["id"]
        session.permanent = True   # La cookie dura PERMANENT_SESSION_LIFETIME (1h); se renueva en cada request
        # ── FIX 2026-05-18 ──────────────────────────────────────────
        # CAUSA RAÍZ del bug "Nunca se conectó" para usuarios que SÍ se
        # conectaron: la versión anterior corría en un hilo daemon y llamaba
        # a `mysql_execute()` → `get_db()` → `g._db`. Pero `g` es Flask
        # request-bound; el thread daemon corre FUERA del request context y
        # `get_db()` lanzaba `RuntimeError("Working outside of request context")`.
        # La excepción la atrapaba el except y solo printeaba al stdout, así
        # que el UPDATE NUNCA se ejecutaba para ningún login → todos los
        # usuarios quedaban con last_login_at congelado (el último valor de
        # la versión síncrona, que era 2026-05-15).
        #
        # FIX: hacerlo SÍNCRONO (el UPDATE indexado por PK toma <30ms, no
        # justifica el overhead/complejidad de un thread). Si la BD está
        # zombi peor, mejor que el usuario lo note al loguearse (10s
        # connect_timeout) que tener tracking roto para siempre.
        # Try/except envuelve para que un error de BD NO impida el login.
        # ─────────────────────────────────────────────────────────────
        # ── FIX 2026-05-27 (Daniel — login 6s): UPDATE y audit van a
        # daemon thread CON app.app_context() para que get_db() y mysql_*
        # funcionen sin RuntimeError. Esto ahorra ~1-1.5s de latencia de
        # red MySQL bloqueando el redirect del usuario.
        #
        # El bug previo (login_ok no se grababa) era porque NO se usaba
        # app_context. Ahora SÍ se usa → audit + last_login_at se graban
        # correctamente, pero asincrónicamente.
        # ──────────────────────────────────────────────────────────────
        try:
            ip = (request.headers.get("X-Forwarded-For") or request.remote_addr or "")[:64]
            _uid = user["id"]
            _uname = user["username"]
            _urole = user["role"]
            # ── Alerta de inicio de sesión: ¿dispositivo nuevo? (cookie larga) ──
            _dev_cookie = request.cookies.get("ilus_dev")
            _is_new_device = not _dev_cookie
            _dev_token = _dev_cookie or secrets.token_urlsafe(16)
            _alert_to = (user.get("username") or "")
            _alert_nombre = user.get("nombre") or ""
            _alert_ua = (request.headers.get("User-Agent") or "")[:180]
            try:
                _alert_cuando = _now_chile().strftime("%d/%m/%Y %H:%M hrs")
            except Exception:
                _alert_cuando = ""
            try:
                _alert_action = url_for("forgot_password", _external=True)
            except Exception:
                _alert_action = ""
            import threading as _th_login
            def _login_track_async():
                with app.app_context():
                    # Track last_login + audit en una sola llamada al thread.
                    try:
                        try:
                            mysql_execute(
                                f"UPDATE `{AUTH_TABLE}` SET last_login_at=NOW(), "
                                f"last_login_ip=%s, last_seen_at=NOW(), "
                                f"login_count=COALESCE(login_count,0)+1 WHERE id=%s",
                                (ip, _uid)
                            )
                        except Exception as _e_lst:
                            print(f"[login-track-async] fallback sin last_seen_at: {_e_lst}", flush=True)
                            try:
                                mysql_execute(
                                    f"UPDATE `{AUTH_TABLE}` SET last_login_at=NOW(), "
                                    f"last_login_ip=%s, login_count=COALESCE(login_count,0)+1 "
                                    f"WHERE id=%s",
                                    (ip, _uid)
                                )
                            except Exception as _e_lst2:
                                print(f"[login-track-async] tracking falló: {_e_lst2}", flush=True)
                        print(f"[login-track-async] OK uid={_uid} username={_uname}", flush=True)
                    except Exception as _e_lt_outer:
                        print(f"[login-track-async] outer error: {_e_lt_outer}", flush=True)

                    try:
                        # Daniel 2026-06-17: guardar UA + IP + dispositivo-nuevo en
                        # details para que el HISTORIAL de conexiones muestre desde
                        # qué navegador/dispositivo se conectó cada usuario.
                        _audit("login_ok",
                               target_type="user", target_id=_uid,
                               details={"ua": _alert_ua, "ip": ip,
                                        "new_device": bool(_is_new_device)},
                               user_override={"id": _uid, "username": _uname, "role": _urole})
                    except Exception as _e_au:
                        print(f"[login-track-async] audit falló: {_e_au}", flush=True)

                    # Alerta de login por correo: DESHABILITADA (2026-06-08, Daniel:
                    # "un inicio de sesion no amerita un correo"). NO se le escribe a
                    # los usuarios por iniciar sesion. El tracking de last_login + audit
                    # de mas arriba SI sigue (eso no manda correo).
                    pass  # (para reactivar: restaurar la llamada a _send_login_alert_email)
            _th_login.Thread(target=_login_track_async, daemon=True,
                             name=f"login-track-{_uid}").start()
        except Exception as _e_login_track:
            import traceback as _tb_lt
            print(f"[login-track] FAIL outer uid={user['id']}: {_e_login_track}\n{_tb_lt.format_exc()}", flush=True)
        flash(f"Bienvenido, {user['nombre']}.", "success")
        resp = redirect(next_url)
        try:
            resp.set_cookie("ilus_dev", _dev_token, max_age=60*60*24*365,
                            httponly=True, samesite="Lax", secure=True)
        except Exception:
            pass
        return resp
    # FIX 2026-05-18 (perf): cache privado corto (30s) en GET /login.
    # El HTML cambia muy poco entre requests y antes lo forzábamos a
    # `no-store` que invalidaba el cache del navegador en cada toque.
    # `private, max-age=30` permite back-button instantáneo sin filtrar
    # entre usuarios (Vary: Cookie ya lo segmenta) y ahorra round-trips.
    # POST sigue siendo no-cache porque retornamos render dentro del if
    # de validación, no llega acá.
    resp = make_response(render_template("login.html", next_url=next_url, username="", login_images=imgs, marca=_get_marca()))
    resp.headers["Cache-Control"] = "private, max-age=30"
    resp.headers["Vary"] = "Cookie"
    return resp


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    # ── FIX 2026-05-17 ──────────────────────────────────────────
    # ORDEN crítico: limpiar sesión PRIMERO, audit DESPUÉS.
    # Si la conexión MySQL está zombi (idle largo), _audit() bloquea
    # 5-20s → el usuario percibe "no me bota". Con esta ordenación,
    # la cookie se invalida instantáneamente y el audit es best-effort.
    # ─────────────────────────────────────────────────────────────
    uid = g.user.get("id") if getattr(g, "user", None) else None
    uname = g.user.get("username") if getattr(g, "user", None) else None
    urole = g.user.get("role") if getattr(g, "user", None) else None
    # Limpiar caché de last_seen para que el LED se apague de inmediato
    try:
        if uid is not None:
            with _last_seen_lock:
                _last_seen_cache.pop(uid, None)
    except Exception:
        pass
    session.clear()
    try:
        _audit("logout", target_type="user", target_id=uid,
               user_override={"id": uid, "username": uname, "role": urole} if uid else None)
    except Exception as _e_log:
        print(f"[logout] audit best-effort falló: {_e_log}", flush=True)
    flash("Sesion cerrada.", "success")
    return redirect(url_for("login"))


