ILUS_SOPORTE_EMAIL = "soportetec@sphs.cl"
ILUS_SOPORTE_URL = "https://ilusfitness.com/pages/soporte-tecnico"


def _ilus_email_rows(pairs) -> str:
    """Filas clave/valor (HTML) para el bloque de detalles del correo maestro.
    pairs = [(label, value), ...]. Escapa cada celda. Omite valores vacíos."""
    from markupsafe import escape as _esc
    out = []
    for label, value in (pairs or []):
        if value is None or str(value).strip() == "":
            continue
        out.append(
            '<tr>'
            '<td class="email-detail-label" style="padding:7px 0;font-size:13px;'
            'line-height:19px;color:#282d33;font-weight:700;vertical-align:top;width:150px">'
            f'{_esc(label)}</td>'
            '<td class="email-detail-value" style="padding:7px 0 7px 14px;font-size:13px;'
            f'line-height:19px;color:#515862;vertical-align:top">{_esc(value)}</td>'
            '</tr>'
        )
    return "".join(out)


def _ilus_email_master(ctx: dict) -> str:
    """Render ÚNICO del estándar de correo ILUS. Devuelve documento HTML completo.
    ctx: subject, preheader, status_label, title, subtitle, customer_name,
    message (HTML safe), detail_rows_html (HTML safe), primary_cta_url,
    primary_cta_label, closing_message, support_email, year, logo_url.
    Texto se escapa; message/detail_rows_html/closing los provee el caller (safe)."""
    from markupsafe import escape as _esc
    ctx = dict(ctx or {})
    try:
        _marca = _get_marca()
    except Exception:
        _marca = {}
    logo_url = (ctx.get("logo_url") or _marca.get("logo_url")
                or "https://ilusfitness.com/cdn/shop/files/"
                   "Logo_ILUS_Fitness_Blanco_equipamiento_para_gimnasios.png")
    support_email = (ctx.get("support_email") or ILUS_SOPORTE_EMAIL).strip()
    try:
        year = int(ctx.get("year") or datetime.now().year)
    except Exception:
        year = 2026
    subject       = _esc(ctx.get("subject") or "ILUS")
    preheader     = _esc(ctx.get("preheader") or "")
    status_label  = _esc(ctx.get("status_label") or "")
    title         = _esc(ctx.get("title") or "")
    subtitle      = _esc(ctx.get("subtitle") or "")
    customer_name = _esc(ctx.get("customer_name") or "")
    se            = _esc(support_email)
    message     = ctx.get("message") or ""            # HTML safe (caller)
    detail_rows = ctx.get("detail_rows_html") or ""   # HTML safe (caller)
    cta_url     = (ctx.get("primary_cta_url") or "").strip()
    cta_label   = _esc(ctx.get("primary_cta_label") or "Ver más")
    closing     = ctx.get("closing_message") or ""    # HTML safe (caller)

    badge_html = (f'<tr><td><span style="display:inline-block;background:#fff0f1;'
                  f'border:1px solid #ffd2d5;border-radius:999px;padding:7px 12px;color:#c70010;'
                  f'font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase">'
                  f'{status_label}</span></td></tr>') if status_label else ''
    subtitle_html = (f'<tr><td style="padding-top:10px;font-size:14px;line-height:21px;'
                     f'color:#68707c">{subtitle}</td></tr>') if subtitle else ''
    # ── FIX 2026-07-24 (Daniel, captura de Gmail) — el correo saludaba DOS veces ──
    # El maestro SIEMPRE pintaba "Hola {cliente}," y además casi todas las
    # plantillas editables (transporte, retiros, mantenciones, catálogo…) abren
    # su cuerpo con "Hola {{cliente}},". Resultado visible: "Hola Juan Cardona,"
    # y justo debajo "Hola,". Es sistémico, así que se corrige UNA vez acá en
    # vez de editar plantilla por plantilla — que además no aguantaría que
    # Daniel vuelva a escribir un saludo al editarlas desde /comunicaciones.
    # Regla: si el CUERPO ya saluda, el maestro se calla.
    def _abre_con_saludo(html_msg: str) -> bool:
        import html as _html
        txt = re.sub(r"<[^>]+>", " ", html_msg or "")
        txt = _html.unescape(txt).replace("\xa0", " ").strip().lower()
        return bool(re.match(
            r"^[¡!\s]*(hola|estimad[oa]s?|buen[oa]s?\s+(d[ií]as|tardes|noches))\b", txt))

    saludo_html = (f'<p style="margin:0 0 18px;font-size:15px;line-height:24px;color:#24272c">'
                   f'Hola <strong style="color:#d90012">{customer_name}</strong>,</p>'
                   ) if (customer_name and not _abre_con_saludo(message)) else ''
    detail_html = (f'<tr><td class="email-pad" style="padding:24px 44px 0">'
                   f'<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" '
                   f'style="background:#f6f7f9;border-left:4px solid #e30613;border-radius:5px">'
                   f'<tr><td style="padding:18px 20px"><table role="presentation" width="100%" '
                   f'cellspacing="0" cellpadding="0" border="0">{detail_rows}</table></td></tr>'
                   f'</table></td></tr>') if detail_rows else ''
    cta_html = (f'<tr><td class="email-pad" style="padding:25px 44px 0">'
                f'<table role="presentation" cellspacing="0" cellpadding="0" border="0"><tr>'
                f'<td class="email-button" align="center" bgcolor="#e30613" style="border-radius:5px">'
                f'<a href="{_esc(cta_url)}" target="_blank" style="display:inline-block;padding:14px 24px;'
                f'color:#ffffff;text-decoration:none;font-size:14px;font-weight:700;border-radius:5px">'
                f'{cta_label}</a></td></tr></table></td></tr>') if cta_url else ''
    closing_html = (f'<tr><td class="email-pad" style="padding:22px 44px 36px">'
                    f'<p style="margin:0;font-size:13px;line-height:21px;color:#6b7280">{closing}</p>'
                    f'</td></tr>') if closing else ''

    # Cuerpo: si el caller pasa body_html crudo (wrappers de retiros/mant/interna
    # que ya traen su propio fragmento), se inserta tal cual; si no, el cuerpo
    # estándar saludo + mensaje + detalles + CTA + cierre.
    if ctx.get("body_html"):
        body_block = (f'<tr><td class="email-pad" style="padding:22px 44px 30px">'
                      f'{ctx["body_html"]}</td></tr>')
    else:
        body_block = (f'<tr><td class="email-pad" style="padding:20px 44px 0">{saludo_html}'
                      f'<p style="margin:0;font-size:15px;line-height:24px;color:#454b54">{message}</p>'
                      f'</td></tr>{detail_html}{cta_html}{closing_html}')

    return f"""<!doctype html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light"><title>{subject}</title>
<style>@media only screen and (max-width:640px){{.email-shell{{width:100%!important}}
.email-pad{{padding-left:22px!important;padding-right:22px!important}}
.email-title{{font-size:25px!important;line-height:31px!important}}
.email-detail-label,.email-detail-value{{display:block!important;width:100%!important}}
.email-detail-value{{padding-top:3px!important;padding-left:0!important;text-align:left!important}}
.email-button{{display:block!important;width:100%!important}}}}</style></head>
<body style="margin:0;padding:0;background:#eef0f3;font-family:Arial,Helvetica,sans-serif;color:#15171a">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">{preheader}</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#eef0f3">
<tr><td align="center" style="padding:32px 12px">
<table role="presentation" class="email-shell" width="620" cellspacing="0" cellpadding="0" border="0" style="width:620px;max-width:620px;background:#ffffff;border-collapse:separate;border-spacing:0;border-radius:10px;overflow:hidden;box-shadow:0 12px 35px rgba(15,23,42,.10)">
<tr><td align="center" style="background:#050505;padding:25px 32px 22px;border-bottom:4px solid #e30613">
<a href="https://ilusfitness.com" target="_blank" style="display:inline-block"><img src="{logo_url}" width="306" alt="ILUS Fitness" style="display:block;width:306px;max-width:306px;height:auto;border:0;outline:none;text-decoration:none"></a></td></tr>
<tr><td class="email-pad" style="padding:34px 44px 12px">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">{badge_html}
<tr><td class="email-title" style="padding-top:17px;font-size:30px;line-height:36px;font-weight:800;color:#111111">{title}</td></tr>{subtitle_html}
</table></td></tr>
{body_block}
<tr><td style="background:#101010;padding:30px 32px 27px;border-top:1px solid #252525">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
<tr><td align="center" style="font-size:16px;line-height:22px;font-weight:800;color:#ffffff">¿Necesitas ayuda con tu solicitud?</td></tr>
<tr><td align="center" style="padding-top:8px;font-size:13px;line-height:20px;color:#aeb4bd">Nuestro equipo de soporte técnico puede ayudarte y dar seguimiento a tu caso.</td></tr>
<tr><td align="center" style="padding-top:17px"><table role="presentation" cellspacing="0" cellpadding="0" border="0">
<tr><td align="center" style="border:1px solid #e30613;border-radius:5px">
<a href="{ILUS_SOPORTE_URL}" target="_blank" style="display:inline-block;padding:11px 18px;color:#ffffff;text-decoration:none;font-size:13px;font-weight:700">Crear ticket de soporte</a>
</td></tr></table></td></tr>
<tr><td align="center" style="padding-top:20px;font-size:11px;line-height:18px;color:#646b74">Este correo fue generado automáticamente. No compartas enlaces de seguimiento con terceros.<br>© {year} ILUS Fitness · Equipamiento profesional para alto rendimiento</td></tr>
</table></td></tr>
</table></td></tr></table></body></html>"""


def _ilus_email_html(
    titulo: str,
    subtitulo: str = "",
    saludo: str = "",
    parrafos: list = None,          # lista de strings HTML
    btn_primario_txt: str = "",
    btn_primario_url: str = "",
    btn_secundario_txt: str = "",
    btn_secundario_url: str = "",
    info_lineas: list = None,       # lista de (icono, clave, valor)
) -> str:
    """
    Genera HTML de correo con el diseño oficial ILUS:
    Header negro con logo → banda oscura título/subtítulo → cuerpo blanco → botones → footer negro.
    """
    # 2026-06-14 (Daniel): DELEGA AL MAESTRO ILUS. Se mantiene la firma (9 args)
    # para no tocar los ~10 call-sites (password, accesos, OT pendiente, retiros
    # fallback, recordatorio 24h, prueba Resend); el render usa el nuevo estándar
    # (header negro + logo 180px, footer con botón "Crear ticket de soporte"
    # como único CTA — sin correo visible, SIN "LIKE U STRONG" ni correo viejo).
    parts = []
    if saludo:
        parts.append(f'<p style="margin:0 0 16px;font-size:15px;line-height:24px;color:#24272c">'
                     f'Hola <strong style="color:#d90012">{saludo}</strong>,</p>')
    for _p in (parrafos or []):
        parts.append(f'<p style="margin:0 0 14px;font-size:15px;line-height:24px;color:#454b54">{_p}</p>')
    if info_lineas:
        _rows = _ilus_email_rows([(k, v) for (_ic, k, v) in info_lineas])
        if _rows:
            parts.append('<table role="presentation" width="100%" cellspacing="0" cellpadding="0" '
                         'border="0" style="background:#f6f7f9;border-left:4px solid #e30613;'
                         'border-radius:5px;margin:18px 0"><tr><td style="padding:16px 18px">'
                         '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" '
                         f'border="0">{_rows}</table></td></tr></table>')
    _btns = []
    if btn_primario_txt and btn_primario_url:
        _btns.append(f'<a href="{btn_primario_url}" style="display:inline-block;background:#e30613;'
                     f'color:#fff;padding:13px 24px;text-decoration:none;font-size:14px;'
                     f'border-radius:5px;margin:5px;font-weight:700">{btn_primario_txt}</a>')
    if btn_secundario_txt and btn_secundario_url:
        _btns.append(f'<a href="{btn_secundario_url}" style="display:inline-block;background:#101010;'
                     f'color:#fff;padding:13px 24px;text-decoration:none;font-size:14px;'
                     f'border-radius:5px;margin:5px;font-weight:700">{btn_secundario_txt}</a>')
    if _btns:
        parts.append(f'<div style="text-align:center;margin-top:22px">{"".join(_btns)}</div>')
    return _ilus_email_master({
        "title":     titulo,
        "subtitle":  subtitulo,
        "body_html": "".join(parts),
    })


def _smtp_ipv4(host: str) -> str:
    """Devuelve una IP v4 del host SMTP para evitar fallas por IPv6 en algunos hosting."""
    import socket

    infos = socket.getaddrinfo(host, None, socket.AF_INET, socket.SOCK_STREAM)
    if not infos:
        return host
    return infos[0][4][0]


class _IPv4SMTP(smtplib.SMTP):
    def _get_socket(self, host, port, timeout):
        import socket

        ip = _smtp_ipv4(host)
        return socket.create_connection((ip, port), timeout, self.source_address)


class _IPv4SMTP_SSL(smtplib.SMTP_SSL):
    def _get_socket(self, host, port, timeout):
        import socket

        ip = _smtp_ipv4(host)
        sock = socket.create_connection((ip, port), timeout, self.source_address)
        return self.context.wrap_socket(sock, server_hostname=self._host)


def _open_smtp_client(host: str, port: int, secure: bool, timeout: int = 15, context=None):
    """Abre SMTP forzando IPv4, pero conserva el hostname para TLS/SNI."""
    if secure:
        return _IPv4SMTP_SSL(host, port, context=context, timeout=timeout)
    return _IPv4SMTP(host, port, timeout=timeout)


def _get_resend_cfg() -> dict:
    """
    Devuelve configuración de Resend API.
    Resend es necesario en hosting cloud (Railway, Heroku) porque Gmail/SMTP
    típicamente bloquea o limita conexiones desde rangos IP de proveedores cloud.
    Prioridad: env vars (Railway) → BD (configurado vía front).
    """
    # 1. Env var (Railway / Docker / local .env)
    api_key = os.environ.get("RESEND_API_KEY", "").strip()
    if api_key:
        # 2026-05-27 (Daniel): aceptar AMBOS nombres de variable.
        # Algunos despliegues usan RESEND_FROM_EMAIL en vez de RESEND_FROM_ADDR.
        _from = (os.environ.get("RESEND_FROM_ADDR", "").strip()
                 or os.environ.get("RESEND_FROM_EMAIL", "").strip()
                 or "onboarding@resend.dev")
        return {
            "api_key":   api_key,
            "from_addr": _from,
            "_source":   "env",
        }
    # 2. BD
    try:
        row = mysql_fetchone("SELECT * FROM comm_resend_config ORDER BY id DESC LIMIT 1")
        if row and row.get("api_key"):
            return {
                "api_key":   row["api_key"],
                "from_addr": row.get("from_addr") or "onboarding@resend.dev",
                "_source":   "db",
            }
    except Exception:
        pass
    return {"api_key": "", "from_addr": "", "_source": ""}


def _email_normalize_attachments(attachments):
    """Normaliza adjuntos de email a lista de tuplas (filename, bytes, mimetype).

    Acepta dos formatos de entrada (FIX 2026-06-11 — informe post-servicio):
      - tupla/lista: (filename, contenido_bytes, mimetype)
      - dict:        {"filename":..., "content": bytes, "content_type":...}
        (formato que ya arma mant_reporte_enviar)

    Entradas inválidas se descartan en silencio (best-effort: el email
    sale igual, sin el adjunto roto). Devuelve [] si no hay nada usable.
    """
    out = []
    for a in (attachments or []):
        try:
            if isinstance(a, dict):
                fname = a.get("filename") or a.get("nombre") or "adjunto.bin"
                content = a.get("content") or a.get("bytes")
                mime = a.get("content_type") or a.get("mimetype") or "application/octet-stream"
            elif isinstance(a, (tuple, list)) and len(a) >= 2:
                fname = a[0] or "adjunto.bin"
                content = a[1]
                mime = (a[2] if len(a) >= 3 else None) or "application/octet-stream"
            else:
                continue
            if content is None:
                continue
            if isinstance(content, str):
                content = content.encode("utf-8")
            out.append((str(fname)[:200], bytes(content), str(mime)[:150]))
        except Exception:
            continue
    return out


def _send_via_resend(to, subject: str, html: str, from_addr: str = None,
                     reply_to: str = None, attachments=None, cc=None) -> bool:
    """
    Envía email vía API HTTPS de Resend (no usa puertos SMTP).
    Funciona desde cualquier IP, incluyendo cloud hosting (Railway, Heroku, AWS).

    Args:
      to: destinatario(s) - string o lista
      subject: asunto
      html: cuerpo HTML
      from_addr: opcional "Nombre <email@dominio>"; default Resend config
      reply_to: opcional buzón de respuesta (header Reply-To)
      attachments: opcional, lista de (filename, bytes, mimetype) o dicts
                   {"filename","content","content_type"} (ver
                   _email_normalize_attachments). Resend los recibe en base64.

    En caso de fallo, deja info en `g._last_resend_error` (dict con message/http_code/raw_body).
    """
    import urllib.request as _ur
    import urllib.error as _ue

    cfg = _get_resend_cfg()
    if not cfg.get("api_key"):
        g._last_resend_error = {
            "name": "no_config",
            "message": "RESEND_API_KEY no está configurada (env var o BD).",
            "http_code": 0, "status_code": 0, "raw_body": "",
        }
        return False

    sender = (from_addr or cfg.get("from_addr") or "onboarding@resend.dev").strip()
    recipients = [to] if isinstance(to, str) else list(to)
    payload_dict = {
        "from": sender,
        "to": recipients,
        "subject": subject,
        "html": html,
    }
    if reply_to:
        # Resend acepta string o lista
        payload_dict["reply_to"] = reply_to
    if cc:
        # Ticket con copia (2026-07-11): Resend acepta string o lista.
        payload_dict["cc"] = [c.strip() for c in cc.split(",")] if isinstance(cc, str) else list(cc)
    # Adjuntos (FIX 2026-06-11): Resend acepta [{"filename","content"(base64)}]
    att_norm = _email_normalize_attachments(attachments)
    if att_norm:
        import base64 as _b64
        payload_dict["attachments"] = [
            {"filename": fn, "content": _b64.b64encode(fb).decode("ascii")}
            for fn, fb, _mt in att_norm
        ]
    payload = json.dumps(payload_dict).encode("utf-8")

    req = _ur.Request(
        "https://api.resend.com/emails",
        data=payload,
        headers={
            "Authorization": f"Bearer {cfg['api_key']}",
            "Content-Type":  "application/json",
        },
        method="POST",
    )
    try:
        with _ur.urlopen(req, timeout=20) as resp:
            print(f"[ILUS][RESEND] Email enviado a {recipients} (HTTP {resp.status}, source={cfg.get('_source')})")
            g._last_resend_error = None
            return True
    except _ue.HTTPError as e:
        body = ""
        try:
            body = e.read().decode("utf-8", errors="replace")
        except Exception:
            pass
        try:
            err_data = json.loads(body) if body else {}
        except Exception:
            err_data = {}
        g._last_resend_error = {
            "name":        err_data.get("name", ""),
            "message":     err_data.get("message", str(e)),
            "http_code":   e.code,
            "status_code": e.code,
            "raw_body":    body[:600],
        }
        print(f"[ILUS][RESEND] HTTP {e.code} — {body[:200]}")
        return False
    except Exception as e:
        g._last_resend_error = {
            "name":      "exception",
            "message":   str(e),
            "http_code": 0, "status_code": 0,
            "raw_body":  "",
        }
        print(f"[ILUS][RESEND] Excepción: {e}")
        return False


def _email_log(destinatario, asunto, evento, estado, error_msg=None, metadata=None):
    """Registra cada intento de envío de email para trazabilidad."""
    try:
        actor = ""
        try: actor = current_username() if g.user else "sistema"
        except Exception: actor = "sistema"
        mysql_execute(
            "INSERT INTO email_log (destinatario,asunto,evento,canal,estado,error_msg,actor,metadata) "
            "VALUES (%s,%s,%s,'email',%s,%s,%s,%s)",
            (str(destinatario)[:300], str(asunto)[:500], evento or "manual",
             estado, (error_msg or "")[:1000], actor[:190],
             json.dumps(metadata or {}, ensure_ascii=False)[:1500])
        )
    except Exception as exc:
        print(f"[EMAIL LOG] {exc}")


# ══════════════════════════════════════════════════════════════════════
# CANALES DE COMUNICACIÓN ACTIVOS — env var COMM_CANALES_ACTIVOS
#
# Daniel dio de baja Twilio: WhatsApp y SMS quedan deshabilitados del
# FLUJO automático del sistema (notificaciones de OT, accesos, etc.).
# El CÓDIGO de _send_whatsapp / _send_sms permanece en app.py, los
# endpoints admin de prueba (/api/twilio/test, /comunicaciones/whatsapp/test)
# también — para que Daniel pueda re-activar el canal en el futuro sin
# tocar código (solo env var + reinicio).
#
# Default: "email" (sólo email vía Resend está activo).
# Para reactivar WhatsApp: COMM_CANALES_ACTIVOS="email,whatsapp"
# Para todo:               COMM_CANALES_ACTIVOS="email,sms,whatsapp"
# ══════════════════════════════════════════════════════════════════════

def _canal_activo(canal: str) -> bool:
    """Retorna True si el canal está habilitado globalmente.

    Lee env var COMM_CANALES_ACTIVOS (default: 'email').
    Para que un envío automático se dispare, el canal debe aparecer en
    la lista. Por ejemplo, con COMM_CANALES_ACTIVOS='email':
       _canal_activo('email')    → True
       _canal_activo('whatsapp') → False
       _canal_activo('sms')      → False

    NO toca el kill switch global de BD ni la llave de paso por módulo —
    es un cortacorriente PREVIO. Si el canal está apagado aquí, ni siquiera
    se intenta el envío (no se llama a Twilio, no se loguea como bloqueado).
    """
    try:
        activos = (os.environ.get("COMM_CANALES_ACTIVOS") or "email").lower()
        canales = [c.strip() for c in activos.split(",") if c.strip()]
        return (canal or "").strip().lower() in canales
    except Exception:
        # Conservador: si algo falla, sólo email activo
        return (canal or "").strip().lower() == "email"


def _canales_activos_lista() -> list:
    """Devuelve la lista de canales activos en orden. Útil para diagnóstico/UI."""
    try:
        activos = (os.environ.get("COMM_CANALES_ACTIVOS") or "email").lower()
        return [c.strip() for c in activos.split(",") if c.strip()]
    except Exception:
        return ["email"]


# ══════════════════════════════════════════════════════════════════════
# KILL SWITCH GLOBAL DE COMUNICACIONES
#
# Permite al superadministrador apagar todo envío de email y/o WhatsApp
# sin tocar credenciales (útil cuando el proveedor está caído, durante
# migración, mantenimiento, o para evitar spam masivo accidental).
#
# Tabla: app_kill_switch (key, enabled, updated_by, updated_at)
#   keys: 'email', 'whatsapp'
#
# Funciones:
#   comm_is_enabled('email')  → bool   (default True si no hay registro)
#   comm_set_enabled('email', False, usuario)
#   _send_ilus_email() respeta el switch automáticamente
# ══════════════════════════════════════════════════════════════════════

# Cache en proceso para no consultar BD en cada envío
_COMM_SWITCH_CACHE = {"email": None, "whatsapp": None, "ts": 0}
_COMM_SWITCH_TTL = 30  # segundos


def comm_is_enabled(canal: str) -> bool:
    """Devuelve True si el canal está habilitado. Default True."""
    import time as _t
    now = _t.time()
    # Cache hit
    if (now - _COMM_SWITCH_CACHE["ts"]) < _COMM_SWITCH_TTL and _COMM_SWITCH_CACHE.get(canal) is not None:
        return bool(_COMM_SWITCH_CACHE[canal])
    # Recargar de BD
    try:
        rows = mysql_fetchall(
            "SELECT `key`, enabled FROM app_kill_switch WHERE `key` IN ('email','whatsapp')"
        ) or []
        _COMM_SWITCH_CACHE["ts"] = now
        for r in rows:
            _COMM_SWITCH_CACHE[r["key"]] = bool(r["enabled"])
        # Defaults para keys que no existen
        if _COMM_SWITCH_CACHE.get("email") is None: _COMM_SWITCH_CACHE["email"] = True
        if _COMM_SWITCH_CACHE.get("whatsapp") is None: _COMM_SWITCH_CACHE["whatsapp"] = True
    except Exception:
        # Si la tabla aún no existe, todo habilitado por default
        return True
    return bool(_COMM_SWITCH_CACHE.get(canal, True))


def comm_set_enabled(canal: str, enabled: bool, usuario: str = "sistema") -> bool:
    """Setea el switch. Solo válido para 'email' o 'whatsapp'."""
    if canal not in ("email", "whatsapp"):
        return False
    try:
        # Asegurar tabla existe (idempotente)
        mysql_execute("""
            CREATE TABLE IF NOT EXISTS app_kill_switch (
              `key` VARCHAR(40) PRIMARY KEY,
              enabled TINYINT(1) DEFAULT 1,
              updated_by VARCHAR(190),
              updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
        """)
        mysql_execute(
            "INSERT INTO app_kill_switch (`key`,enabled,updated_by) VALUES (%s,%s,%s) "
            "ON DUPLICATE KEY UPDATE enabled=VALUES(enabled), updated_by=VALUES(updated_by)",
            (canal, 1 if enabled else 0, usuario)
        )
        # Invalidar cache
        _COMM_SWITCH_CACHE["ts"] = 0
        return True
    except Exception as e:
        print(f"[KILL_SWITCH] Error setting {canal}={enabled}: {e}")
        return False


@app.route("/comunicaciones/kill-switch", methods=["GET"])
def comm_kill_switch_get():
    """Devuelve el estado actual del kill switch (cualquier usuario logueado puede leer)."""
    if not g.get("user"):
        return jsonify({"error": "Sin sesión"}), 401
    return jsonify({
        "email":    comm_is_enabled("email"),
        "whatsapp": comm_is_enabled("whatsapp"),
    })


@app.route("/comunicaciones/kill-switch", methods=["POST"])
def comm_kill_switch_set():
    """Cambia el estado del kill switch (solo superadmin).
    Body JSON: {"email": bool, "whatsapp": bool} — campos opcionales."""
    if not (g.get("user") and g.permissions.get("superadmin")):
        return jsonify({"error": "Solo superadmin"}), 403
    d = request.get_json(silent=True) or {}
    user = current_username() or "sistema"
    cambios = {}
    if "email" in d:
        ok = comm_set_enabled("email", bool(d["email"]), user)
        cambios["email"] = {"requested": bool(d["email"]), "ok": ok}
    if "whatsapp" in d:
        ok = comm_set_enabled("whatsapp", bool(d["whatsapp"]), user)
        cambios["whatsapp"] = {"requested": bool(d["whatsapp"]), "ok": ok}
    return jsonify({
        "ok": True,
        "cambios": cambios,
        "estado_actual": {
            "email":    comm_is_enabled("email"),
            "whatsapp": comm_is_enabled("whatsapp"),
        }
    })


# ══════════════════════════════════════════════════════════════════════
# LLAVE DE PASO POR MÓDULO (kill switch granular)
#
# Daniel necesita poder "cerrar la llave" de los correos/WhatsApp/SMS
# de cada módulo (transporte, retiros, mantenciones, comunicación
# interna, general) mientras está en pruebas, sin tocar credenciales.
#
# Tabla: comm_killswitch (modulo, email/whatsapp/sms_bloqueado, motivo)
# Cache: 30s para no consultar BD en cada envío.
#
# Funciones:
#   _modulo_canal_bloqueado(modulo, canal) → bool
#   _comm_killswitch_invalidar() — invalida cache (lo llaman los setters)
# ══════════════════════════════════════════════════════════════════════

_MODULOS_KILLSWITCH_VALIDOS = (
    "transporte",
    "retiros",
    "mantenciones",
    "comunicacion_interna",
    "general",
    "tickets",
    "catalogo",
)

_KILLSWITCH_CACHE = {"data": None, "ts": 0}
_KILLSWITCH_TTL = 30  # segundos


def _comm_killswitch_invalidar():
    """Invalida el caché en memoria. Se llama tras cada cambio (PUT)."""
    _KILLSWITCH_CACHE["ts"] = 0
    _KILLSWITCH_CACHE["data"] = None


def _comm_killswitch_estado():
    """Devuelve dict {modulo: {email_bloqueado, whatsapp_bloqueado,
    sms_bloqueado, motivo, actualizado_por, actualizado_at}} usando caché.
    Si la tabla no existe aún, devuelve dict con todos los módulos en 0.
    """
    import time as _t
    now = _t.time()
    if (_KILLSWITCH_CACHE["data"] is not None
            and (now - _KILLSWITCH_CACHE["ts"]) < _KILLSWITCH_TTL):
        return _KILLSWITCH_CACHE["data"]

    estado = {m: {"email_bloqueado": 0, "whatsapp_bloqueado": 0,
                  "sms_bloqueado": 0, "motivo": "",
                  "actualizado_por": "", "actualizado_at": None}
              for m in _MODULOS_KILLSWITCH_VALIDOS}
    try:
        rows = mysql_fetchall(
            "SELECT modulo, email_bloqueado, whatsapp_bloqueado, sms_bloqueado, "
            "       motivo, actualizado_por, actualizado_at "
            "FROM comm_killswitch"
        ) or []
        for r in rows:
            mod = r.get("modulo") or ""
            if mod not in estado:
                estado[mod] = {"email_bloqueado": 0, "whatsapp_bloqueado": 0,
                               "sms_bloqueado": 0, "motivo": "",
                               "actualizado_por": "", "actualizado_at": None}
            estado[mod]["email_bloqueado"]    = int(r.get("email_bloqueado") or 0)
            estado[mod]["whatsapp_bloqueado"] = int(r.get("whatsapp_bloqueado") or 0)
            estado[mod]["sms_bloqueado"]      = int(r.get("sms_bloqueado") or 0)
            estado[mod]["motivo"]             = r.get("motivo") or ""
            estado[mod]["actualizado_por"]    = r.get("actualizado_por") or ""
            estado[mod]["actualizado_at"]     = r.get("actualizado_at")
    except Exception as exc:
        # Si la tabla aún no existe (primer arranque), nada bloqueado.
        print(f"[KILLSWITCH] No se pudo leer comm_killswitch: {exc}")

    _KILLSWITCH_CACHE["data"] = estado
    _KILLSWITCH_CACHE["ts"]   = now
    return estado


def _modulo_canal_bloqueado(modulo: str, canal: str) -> bool:
    """Devuelve True si el canal está bloqueado para ese módulo.

    Args:
      modulo: 'transporte' | 'retiros' | 'mantenciones' |
              'comunicacion_interna' | 'general'.
              Si no se reconoce, se usa 'general'.
      canal:  'email' | 'whatsapp' | 'sms'.
              Si no se reconoce, devuelve False (no bloquea).

    Es defensivo: cualquier excepción → False (no bloquea por error técnico).
    """
    try:
        mod = (modulo or "general").strip().lower()
        if mod not in _MODULOS_KILLSWITCH_VALIDOS:
            mod = "general"
        canal = (canal or "").strip().lower()
        key = {"email": "email_bloqueado",
               "whatsapp": "whatsapp_bloqueado",
               "sms": "sms_bloqueado"}.get(canal)
        if not key:
            return False
        estado = _comm_killswitch_estado()
        return bool(estado.get(mod, {}).get(key, 0))
    except Exception:
        return False


def _modulo_desde_evento(evento: str) -> str:
    """Heurística para mapear 'evento' (string usado en email_log) al módulo.
    Útil cuando no se pasa 'modulo' explícito al enviar."""
    if not evento:
        return "general"
    e = str(evento).lower()
    if e.startswith("retry_"):
        e = e[6:]
    # Mantenciones
    if any(t in e for t in ("ot_", "visita_", "reporte_", "mant_", "tecnico_",
                            "_visita", "_ot")):
        return "mantenciones"
    # Comunicación interna (accesos, claves, login)
    if any(t in e for t in ("password", "invite", "welcome", "acceso",
                            "login", "inicio_sesion", "cambio_pass",
                            "olvido_contrasena")):
        return "comunicacion_interna"
    # Retiros
    if any(t in e for t in ("retiro", "pickup")):
        return "retiros"
    # Transporte
    if any(t in e for t in ("pedido", "courier", "despacho", "programado",
                            "en_ruta", "en_camino", "entregado", "fallido")):
        return "transporte"
    # Catálogo (envío de manuales PDF)
    if any(t in e for t in ("catalogo_manual", "catalogo_")):
        return "catalogo"
    return "general"


def _send_ilus_email(to_addr: str, subject: str, html_body: str, *,
                     evento: str = None, modulo: str = None,
                     asincrono: bool = False, **kwargs) -> bool:
    """
    Envía un correo HTML usando la configuración SMTP dinámica.
    Prioridad: Resend API (Railway) → SMTP con env vars → SMTP BD → SMTP config.py
    Loguea automáticamente el resultado en email_log.

    KILL SWITCH GLOBAL: si el switch global de email está OFF, devuelve False
    sin intentar enviar. Log queda con razon='kill_switch_off'.

    LLAVE DE PASO POR MÓDULO: si el módulo identificado tiene el canal email
    bloqueado en comm_killswitch, NO envía y deja log con estado='bloqueado'.
    Si no se pasa 'modulo', se infiere del 'evento'. Default: 'general'.

    attachments= (kwarg opcional, 2026-06-11): lista de adjuntos que se pasa
    tal cual a _send_ilus_email_real (tuplas (filename, bytes, mimetype) o
    dicts {"filename","content","content_type"}).

    asincrono= (kwarg opcional, 2026-07-19 — cola de correo en background,
    peritaje "palanca #2 de velocidad percibida"): si True, y NO hay
    'attachments', el correo se ENCOLA en `comm_email_jobs` (origen='cola_v2')
    y un worker perezoso lo envía segundos después — el request no espera al
    SMTP. Retorna True apenas queda encolado (no es "se entregó", es "se
    aceptó para entrega"). SOLO usar en callers fire-and-forget que YA
    ignoraban el retorno (ver lista en el diseño / CLAUDE.md).
    Con asincrono=False (default) el comportamiento es IDÉNTICO al de
    siempre — cero cambios para los ~26 callers existentes.
    Si el encolado falla por cualquier razón (tabla no existe aún por
    ILUS_SKIP_MIGRATIONS=1, BD caída, etc.) o si vienen 'attachments'
    (no se persisten — binarios en MySQL es mala idea), se degrada
    automáticamente al envío SÍNCRONO de siempre. Un correo JAMÁS se
    pierde por un fallo de encolado.
    """
    # 1) KILL SWITCH GLOBAL (todo email)
    if not comm_is_enabled("email"):
        try:
            _email_log(to_addr, subject, evento, 'bloqueado',
                       error_msg='Email deshabilitado por superadmin (kill switch global ON)')
        except Exception: pass
        print(f"[EMAIL][KILL_SWITCH] Bloqueado a {to_addr}: kill switch global OFF")
        return False

    # 2) LLAVE DE PASO POR MÓDULO
    mod_resolved = (modulo or _modulo_desde_evento(evento) or "general").strip().lower()
    if _modulo_canal_bloqueado(mod_resolved, "email"):
        try:
            _email_log(to_addr, subject, evento, 'bloqueado',
                       error_msg=f'Llave de paso cerrada para módulo "{mod_resolved}" — email no enviado',
                       metadata={"modulo": mod_resolved, "killswitch": True})
        except Exception: pass
        print(f"[KILLSWITCH] modulo={mod_resolved} canal=email bloqueado por kill switch — no enviado (to={to_addr})")
        return False

    # 2.5) ENCOLADO ASÍNCRONO (opt-in) — vive DENTRO del choke point, después
    # de las dos llaves de arriba (mismo comportamiento de bloqueo que hoy).
    if asincrono and not kwargs.get("attachments"):
        try:
            kw_persistir = {k: kwargs[k] for k in ("cc", "reply_to") if kwargs.get(k)}
            kw_json = json.dumps(kw_persistir, ensure_ascii=False) if kw_persistir else None
            conn = get_db()
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO comm_email_jobs "
                    "(destinatario, asunto, cuerpo, evento, modulo, kwargs_json, "
                    " origen, status, created_by) "
                    "VALUES (%s,%s,%s,%s,%s,%s,'cola_v2','queued','sistema')",
                    (str(to_addr)[:300], (subject or "")[:500], html_body,
                     evento, mod_resolved, kw_json))
            conn.commit()
            _email_queue_kick()
            return True  # True = encolado con éxito (no "entregado")
        except Exception as exc:
            # FALLBACK DURO: tabla inexistente (ILUS_SKIP_MIGRATIONS=1 sin
            # migrar), BD caída, lo que sea → se envía SÍNCRONO como hoy.
            # Un correo NUNCA se pierde por un fallo de encolado.
            print(f"[EMAIL][QUEUE] Encolado falló, fallback síncrono: {str(exc)[:200]}", flush=True)

    # _send_ilus_email_inner hace el envío real; lo wrappeamos
    sent = False
    err  = None
    try:
        sent = _send_ilus_email_real(to_addr, subject, html_body, **kwargs)
    except Exception as exc:
        err = str(exc)[:1000]
    # Log
    try:
        _email_log(to_addr, subject, evento, 'enviado' if sent else 'fallido',
                   error_msg=err, metadata={"modulo": mod_resolved})
    except Exception: pass
    return sent


# ══════════════════════════════════════════════════════════════════════
# COLA DE CORREO EN BACKGROUND — worker perezoso (peritaje 2026-07-19)
#
# Patrón idéntico a _rl_cleanup_loop (app.py ~4416): flag global a nivel
# de módulo (solo datos, CERO hilo arrancado al importar — compatible con
# --preload), el hilo daemon arranca recién en el primer encolado real.
#
# At-least-once: se prefiere un correo DUPLICADO (raro) sobre uno PERDIDO
# (grave — un cliente que no se entera de su retiro, una OT que no se
# aprueba). Ver `_email_queue_claim_one` (claim atómico) y
# `_email_queue_rescue` (jobs huérfanos de una instancia que murió).
# ══════════════════════════════════════════════════════════════════════

_EMAIL_QW = {"started": False, "lock": threading.Lock()}
_EMAIL_QUEUE_BACKOFF_MIN = [1, 5, 15, 60, 180]  # minutos, por intento (1-indexado)


def _email_queue_kick():
    """Arranque perezoso del worker daemon. Idempotente — el flag global
    asegura que el hilo se cree UNA sola vez por proceso, sin importar
    cuántos encolados concurrentes lo disparen."""
    if _EMAIL_QW["started"]:
        return
    with _EMAIL_QW["lock"]:
        if _EMAIL_QW["started"]:
            return
        try:
            threading.Thread(target=_email_queue_loop, daemon=True,
                             name="email-queue-worker").start()
            _EMAIL_QW["started"] = True
        except Exception as exc:
            print(f"[EMAIL][QUEUE] no se pudo arrancar el worker: {exc}", flush=True)


def _email_queue_loop():
    """Bucle del worker: drena hasta 10 jobs / 60s, duerme 5s si trabajó
    algo (para vaciar backlog rápido) o 15s si no había nada."""
    while True:
        n = 0
        try:
            with app.app_context():
                n = _email_queue_drain(max_jobs=10, max_seconds=60)
        except Exception as exc:
            print(f"[EMAIL][QUEUE] loop error: {exc}", flush=True)
        time.sleep(5 if n else 15)


def _email_queue_drain(max_jobs: int = 10, max_seconds: int = 30) -> int:
    """Reclama y envía hasta max_jobs jobs 'cola_v2' pendientes, o hasta
    max_seconds. Reusado por el worker daemon Y por los crons de respaldo
    (tk_cron_leer_correo, _mantenciones_scheduler_loop) para drenar
    backlog aunque la instancia que encoló haya muerto sin tráfico nuevo.
    Devuelve cuántos jobs procesó (0 = nada pendiente)."""
    try:
        _email_queue_rescue()
    except Exception as exc:
        print(f"[EMAIL][QUEUE] rescue error: {exc}", flush=True)
    deadline = time.monotonic() + max_seconds
    hechos = 0
    while hechos < max_jobs and time.monotonic() < deadline:
        try:
            job = _email_queue_claim_one()
        except Exception as exc:
            print(f"[EMAIL][QUEUE] claim error: {exc}", flush=True)
            break
        if not job:
            break
        try:
            _email_queue_send_job(job)
        except Exception as exc:
            print(f"[EMAIL][QUEUE] send_job error (job_id={job.get('id')}): {exc}", flush=True)
        hechos += 1
    return hechos


def _email_queue_claim_one():
    """Claim atómico UPDATE-then-SELECT, seguro para múltiples instancias
    Cloud Run corriendo el worker en paralelo.

    La transición queued→sending es UN SOLO UPDATE filtrado por status:
    dos instancias no pueden ganar la misma fila (rowcount=0 para la
    segunda). El commit() INMEDIATO después del UPDATE (gotcha conocido
    del proyecto: pool REPEATABLE READ) hace que el SELECT posterior en
    la MISMA conexión vea su propia escritura sin depender de otra
    conexión/snapshot."""
    import socket as _socket
    import uuid as _uuid
    token = f"{_socket.gethostname()}-{os.getpid()}-{_uuid.uuid4().hex[:8]}"
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            "UPDATE comm_email_jobs "
            "   SET status='sending', claimed_by=%s, started_at=NOW(), "
            "       intentos=intentos+1 "
            " WHERE origen='cola_v2' AND status='queued' "
            "   AND (proximo_intento_at IS NULL OR proximo_intento_at <= NOW()) "
            "   AND intentos < max_intentos "
            " ORDER BY id LIMIT 1",
            (token,))
        rowcount = cur.rowcount
    conn.commit()  # CLAVE: hace visible el claim antes de re-leer
    if rowcount != 1:
        return None
    with conn.cursor() as cur:
        cur.execute(
            "SELECT * FROM comm_email_jobs WHERE claimed_by=%s AND status='sending' LIMIT 1",
            (token,))
        return cur.fetchone()


def _email_queue_send_job(job):
    """Envía UN job ya reclamado (status='sending'), respetando el choke
    point completo: re-chequea kill switch global + llave de módulo AL
    MOMENTO DE ENVIAR (pudieron cambiar entre el encolado y el drenado).
    Escribe en email_log el resultado FINAL (enviado/fallido/bloqueado) —
    igual semántica 1-correo=1-entrada que el flujo síncrono de hoy; los
    reintentos intermedios quedan solo en comm_email_jobs.ultimo_error."""
    job_id      = job.get("id")
    destino     = job.get("destinatario") or ""
    asunto      = job.get("asunto") or ""
    cuerpo      = job.get("cuerpo") or ""
    evento      = job.get("evento")
    modulo      = job.get("modulo") or "general"
    intentos    = int(job.get("intentos") or 1)
    max_int     = int(job.get("max_intentos") or 5)

    if not comm_is_enabled("email") or _modulo_canal_bloqueado(modulo, "email"):
        try:
            mysql_execute(
                "UPDATE comm_email_jobs SET status='failed', completed_at=NOW(), "
                "ultimo_error=%s WHERE id=%s",
                ("bloqueado por kill switch al momento de drenar", job_id))
        except Exception:
            pass
        try:
            _email_log(destino, asunto, evento, 'bloqueado',
                       error_msg='Bloqueado por kill switch al drenar la cola',
                       metadata={"modulo": modulo, "job_id": job_id, "async": True})
        except Exception:
            pass
        return

    sent = False
    err  = None
    try:
        kw = json.loads(job.get("kwargs_json") or "{}")
        sent = _send_ilus_email_real(destino, asunto, cuerpo, **kw)
        if not sent:
            err = getattr(g, "_last_email_error", None) or "proveedor devolvió False"
    except Exception as exc:
        err = str(exc)

    err = (str(err)[:500] if err else None)

    if sent:
        try:
            mysql_execute(
                "UPDATE comm_email_jobs SET status='sent', completed_at=NOW(), "
                "ultimo_error=NULL WHERE id=%s",
                (job_id,))
        except Exception:
            pass
        try:
            _email_log(destino, asunto, evento, 'enviado',
                       metadata={"modulo": modulo, "job_id": job_id,
                                 "async": True, "intento": intentos})
        except Exception:
            pass
        return

    if intentos >= max_int:
        try:
            mysql_execute(
                "UPDATE comm_email_jobs SET status='failed', completed_at=NOW(), "
                "ultimo_error=%s WHERE id=%s",
                (err, job_id))
        except Exception:
            pass
        try:
            _email_log(destino, asunto, evento, 'fallido', error_msg=err,
                       metadata={"modulo": modulo, "job_id": job_id, "intentos": intentos})
        except Exception:
            pass
    else:
        backoff_min = _EMAIL_QUEUE_BACKOFF_MIN[min(intentos, len(_EMAIL_QUEUE_BACKOFF_MIN)) - 1]
        try:
            mysql_execute(
                "UPDATE comm_email_jobs SET status='queued', "
                "proximo_intento_at=NOW() + INTERVAL %s MINUTE, "
                "ultimo_error=%s WHERE id=%s",
                (backoff_min, err, job_id))
        except Exception:
            pass
        # Sin email_log aquí: el intento intermedio no es el resultado final.


def _email_queue_rescue():
    """Rescata jobs 'sending' huérfanos — la instancia que los reclamó
    murió a mitad del envío (Cloud Run puede escalar a cero / recicla
    instancias). Umbral 10 min: el peor envío real (SMTP + fallback
    Resend) tarda ~25s, así que 10 min es inequívocamente 'se murió',
    nunca un falso positivo sobre un envío en curso."""
    try:
        mysql_execute(
            "UPDATE comm_email_jobs SET status='queued', proximo_intento_at=NOW(), "
            "claimed_by=NULL "
            "WHERE origen='cola_v2' AND status='sending' "
            "  AND started_at < (NOW() - INTERVAL 10 MINUTE) AND intentos < max_intentos"
        )
    except Exception as exc:
        print(f"[EMAIL][QUEUE] rescue (requeue) error: {exc}", flush=True)
    try:
        mysql_execute(
            "UPDATE comm_email_jobs SET status='failed', completed_at=NOW(), "
            "ultimo_error='instancia terminó durante el envío; intentos agotados' "
            "WHERE origen='cola_v2' AND status='sending' "
            "  AND started_at < (NOW() - INTERVAL 10 MINUTE) AND intentos >= max_intentos"
        )
    except Exception as exc:
        print(f"[EMAIL][QUEUE] rescue (fail) error: {exc}", flush=True)


def _get_brand_cfg() -> dict:
    """Devuelve el branding genérico ILUS, respetando overrides de env vars.

    Se invoca en CADA envío de email/WhatsApp/SMS para que los cambios en
    Railway tomen efecto sin reiniciar la app. Defaults sensatos arriba.
    """
    import os as _os_b
    return {
        "name":          (_os_b.environ.get("ILUS_BRAND_NAME")       or BRAND_CONFIG.get("name")       or "ILUS Fitness").strip(),
        "from_name":     (_os_b.environ.get("ILUS_BRAND_FROM_NAME")  or BRAND_CONFIG.get("from_name")  or "ILUS").strip(),
        "from_email":    (_os_b.environ.get("ILUS_BRAND_FROM_EMAIL") or BRAND_CONFIG.get("from_email") or "no-reply@ilusfitness.com").strip(),
        "reply_to":      (_os_b.environ.get("ILUS_BRAND_REPLY_TO")   or BRAND_CONFIG.get("reply_to")   or "soportetec@sphs.cl").strip(),
        "wa_name":       (_os_b.environ.get("ILUS_BRAND_WA_NAME")    or BRAND_CONFIG.get("wa_name")    or "ILUS").strip(),
        "support_url":   (_os_b.environ.get("ILUS_BRAND_SUPPORT_URL")  or BRAND_CONFIG.get("support_url")   or "https://ilusfitness.com/pages/soporte-tecnico").strip(),
        "support_email": (_os_b.environ.get("ILUS_BRAND_SUPPORT_EMAIL")or BRAND_CONFIG.get("support_email") or "soportetec@sphs.cl").strip(),
    }


# ── CACHE 2026-05-26 (Daniel — performance audit) ─────────────────────
# `_get_marca()` se invoca en TODOS los renders vía context_processor.
# Antes: 2 queries SQL por cada render HTML. Con 30 navegaciones/min eso
# son 60 queries/min innecesarias (la marca casi nunca cambia).
# Cache TTL 300s (5 min): suficientemente fresco para cambios visibles
# desde /comunicaciones y suficientemente largo para eliminar el costo.
# Llamar a _marca_cache_clear() tras editar la marca para forzar refresh.
_MARCA_CACHE = {"data": None, "ts": 0.0}
_MARCA_CACHE_TTL = 300  # 5 minutos


def _marca_cache_clear():
    """Invalida el cache de marca. Llamar tras editar comm_client_config."""
    _MARCA_CACHE["data"] = None
    _MARCA_CACHE["ts"] = 0.0


def _get_marca() -> dict:
    """Marca activa = mezcla de BD (`comm_client_config`) + env vars.
    Cacheada 5 minutos en proceso (ver _MARCA_CACHE).

    FUENTE DE VERDAD: la BD para todo lo visible al cliente final (nombre,
    logo, color, soporte). Las env vars sólo rellenan campos que no están
    en la tabla (from_email técnico, reply_to por defecto, support_url).

    Esto permite que Daniel cambie "ILUS Sport & Health" → "ILUS Fitness"
    desde /comunicaciones sin tocar código ni reiniciar. Igual con el logo
    y el color corporativo. Todas las comunicaciones (email/WhatsApp/SMS)
    invocan esta función en cada envío.

    Returns:
      dict con: name, from_name, from_email, reply_to, wa_name, logo_url,
      support_email, support_url, footer, corp_color, support_phone.
    """
    # ── Cache hit (TTL 5 min) ──
    _now = time.time()
    if _MARCA_CACHE["data"] is not None and (_now - _MARCA_CACHE["ts"]) < _MARCA_CACHE_TTL:
        return _MARCA_CACHE["data"]

    try:
        cc = _get_client_cfg() or {}
    except Exception:
        cc = {}
    try:
        be = _get_brand_cfg() or {}
    except Exception:
        be = {}

    name = (cc.get("company_name") or be.get("name") or "ILUS Fitness").strip()
    # Logo: BD primero, luego CDN ILUS Fitness oficial
    logo = (cc.get("logo_url") or "").strip()
    if not logo:
        logo = "https://ilusfitness.com/cdn/shop/files/Logo_ILUS_Fitness_Blanco_equipamiento_para_gimnasios.png"

    _result = {
        "name":          name,
        # FIX 2026-05-21 (Daniel): `name` (campo "Nombre de empresa" editable
        # en /comunicaciones) tiene prioridad sobre be.get("from_name") que
        # venía de la env var ILUS_BRAND_FROM_NAME. Daniel quiere que cuando
        # cambie el nombre de empresa desde la página, eso se refleje en TODOS
        # los emails sin tocar env vars. Igual para wa_name (WhatsApp si vuelve).
        "from_name":     (name or be.get("from_name") or "ILUS Fitness").strip(),
        "from_email":    (be.get("from_email") or "no-reply@ilusfitness.com").strip(),
        "reply_to":      (cc.get("reply_to") or be.get("reply_to") or "soportetec@sphs.cl").strip(),
        "wa_name":       (name or be.get("wa_name") or "ILUS Fitness").strip(),
        "logo_url":      logo,
        "support_email": (cc.get("support_email") or be.get("support_email") or "soportetec@sphs.cl").strip(),
        "support_url":   (be.get("support_url") or "https://ilusfitness.com/pages/soporte-tecnico").strip(),
        "footer":        f"{name} · Plataforma operacional",
        "corp_color":    (cc.get("corp_color") or "#DC143C").strip(),
        "support_phone": (cc.get("support_phone") or "").strip(),
    }
    # Guardar en cache TTL 5 min
    _MARCA_CACHE["data"] = _result
    _MARCA_CACHE["ts"]   = _now
    return _result


def _brand_subject(tema: str) -> str:
    """Subject estandarizado del email: "{marca} · {tema}".

    Marca dinámica desde `comm_client_config` (vía `_get_marca`) —
    Daniel puede cambiar el nombre de empresa en /comunicaciones
    sin tocar código.
    """
    marca = _get_marca()
    prefijo = marca["from_name"]
    tema = (tema or "").strip()
    # Evitar duplicar prefijo si quien llama ya lo agregó
    if tema.startswith(f"{prefijo} ·") or tema.startswith(f"{prefijo} -"):
        return tema
    return f"{prefijo} · {tema}" if tema else prefijo


def _brand_wa_prefix(asunto: str) -> str:
    """Prefijo WhatsApp/SMS: "🔧 {marca} · {asunto}\\n\\n"

    Marca dinámica desde `comm_client_config` (vía `_get_marca`).
    """
    marca = _get_marca()
    prefijo = marca["wa_name"]
    asunto = (asunto or "").strip()
    if asunto:
        return f"🔧 {prefijo} · {asunto}\n\n"
    return f"🔧 {prefijo}\n\n"


def _apply_test_redirect(to_addr, subject):
    """MODO PRUEBA (2026-06-14): si ILUS_COMM_TEST_TO está seteada, redirige el
    correo a ese buzón (mostrando el destinatario real en el asunto) y devuelve
    (to_addr, subject) ya ajustados. Sin la env var = passthrough exacto (cero
    impacto en producción).

    Se aplica en TODAS las rutas de envío de email para que durante la fase de
    prueba ningún correo alcance a un destinatario real:
      - `_send_ilus_email_real` (cron / OT / recovery / retiros / transporte)
      - `_send_email_dinamico`  (invitación a técnico externo + CC/BCC globales)
    Si se agrega una ruta de envío nueva, debe llamar a este helper.
    """
    _test_to = (os.environ.get("ILUS_COMM_TEST_TO") or "").strip()
    if _test_to and to_addr and str(to_addr).strip().lower() != _test_to.lower():
        _orig_to = to_addr
        to_addr = _test_to
        subject = f"[PRUEBA→{_orig_to}] {subject}"
        print(f"[TEST_MODE] correo redirigido: real={_orig_to} -> {to_addr}", flush=True)
    return to_addr, subject


def _send_ilus_email_real(to_addr: str, subject: str, html_body: str,
                          attachments=None, cc=None, reply_to=None) -> bool:
    """
    Implementación real con fallback configurable por env var.

    reply_to (FIX 2026-07-12 — Tickets/Gmail): override puntual del Reply-To
    de marca (por defecto "soportetec@sphs.cl", compartido por TODOS los
    módulos). Tickets lo necesita apuntando a un buzón específico (el que
    se vaya a integrar con Gmail API para leer respuestas de clientes) sin
    tocar el default global que usan retiros/transporte/mantenciones.

    attachments (FIX 2026-06-11 — informe post-servicio): lista opcional de
    tuplas (filename, bytes, mimetype) — también acepta dicts
    {"filename","content","content_type"} (ver _email_normalize_attachments).
    Se adjuntan con MIMEApplication en SMTP y en base64 vía Resend. Antes
    este kwarg no existía y mant_reporte_enviar caía en TypeError → el
    informe JAMÁS llegaba con su adjunto Word.

    PROVIDER (env var ILUS_EMAIL_PROVIDER):
      - "smtp"   (default): Gmail SMTP primero (sale firmado como
                  daniel.aguilar@sphs.cl, no necesita DNS propio).
                  Resend queda como fallback.
      - "resend" : Resend primero (requiere DNS verificado en Resend
                  para no caer en spam). SMTP fallback.
      - "auto"   : Comportamiento legacy — intenta Resend si está
                  configurado, sino SMTP.

    Decisión 2026-05-21 (Daniel): default = "smtp" porque el DNS de
    ilusfitness.com aún no está configurado y Resend sin dominio
    propio sale como onboarding@resend.dev (cae spam). Cuando
    Joaquín configure los registros DKIM/SPF/DMARC en Resend, basta
    cambiar ILUS_EMAIL_PROVIDER=resend en Railway.

    Branding: el From siempre es genérico (BRAND_CONFIG.from_name +
    from_email). El Reply-To apunta al buzón de soporte.
    """
    # ── MODO PRUEBA (2026-06-14) ─────────────────────────────────────────
    # Redirige a ILUS_COMM_TEST_TO si está seteada (helper compartido). Esta es
    # la ruta principal de envío (cron/OT/recovery/retiros/transporte); la otra
    # ruta, `_send_email_dinamico` (técnico externo), también aplica el helper.
    to_addr, subject = _apply_test_redirect(to_addr, subject)
    marca = _get_marca()
    att_norm = _email_normalize_attachments(attachments)
    provider = (os.environ.get("ILUS_EMAIL_PROVIDER") or "smtp").strip().lower()
    if provider not in ("smtp", "resend", "auto"):
        provider = "smtp"

    resend_cfg = _get_resend_cfg()
    resend_disponible = bool(resend_cfg.get("api_key"))

    # ── Ramificación según provider configurado ─────────────────────────
    intentar_resend_primero = (
        (provider == "resend" and resend_disponible) or
        (provider == "auto"   and resend_disponible)
    )
    intentar_smtp_primero = (provider == "smtp")

    # ── 1. Intento Resend primero SOLO si provider lo pide ──────────────
    if intentar_resend_primero:
        # From genérico de marca — SMTP guardado sólo como fallback si el
        # dominio aún no está verificado en Resend.
        from_for_resend = None
        try:
            smtp_cfg = _get_smtp_cfg()
            brand_email = marca["from_email"] or smtp_cfg.get("from_addr") or resend_cfg.get("from_addr")
            from_name   = marca["from_name"]  or smtp_cfg.get("from_name") or "ILUS Fitness"
            if brand_email:
                from_for_resend = f"{from_name} <{brand_email}>"
        except Exception:
            pass

        if _send_via_resend(to_addr, subject, html_body,
                            from_addr=from_for_resend,
                            reply_to=marca["reply_to"],
                            attachments=att_norm, cc=cc):
            return True
        # Resend falló — guardar error legible y caer a SMTP
        err = getattr(g, "_last_resend_error", None) or {}
        try:
            g._last_email_error = f"Resend: {err.get('message','fallo')} (HTTP {err.get('http_code',0)})"
        except Exception:
            pass
        print(f"[ILUS][EMAIL] Resend falló, intento SMTP como fallback…")

    # ── 2. Fallback a SMTP ──────────────────────────────────────────────
    try:
        cfg = _get_smtp_cfg()
    except Exception:
        cfg = dict(EMAIL_CONFIG)

    # Branding desde la marca (BD), SMTP credentials no se tocan
    from_name     = marca["from_name"]  or cfg.get("from_name") or "ILUS Fitness"
    from_addr_cfg = marca["from_email"] or cfg.get("from_addr") or cfg.get("smtp_user", "")
    reply_to      = reply_to or marca["reply_to"] or cfg.get("reply_to") or ""

    # ── FIX 2026-07-18 (auditoria, parche anti-spam SOLO rama SMTP) ─────
    # Ninguno de los 2 dominios (marca ni cuenta SMTP real) tiene
    # SPF/DKIM/DMARC hoy (verificado por nslookup) -> si el From visible
    # (dominio de marca, ej. ilusfitness.com) NO coincide con el dominio
    # que realmente autentica via SMTP (comm_smtp_config, tipicamente
    # @sphs.cl), Gmail acepta el correo pero lo filtra a spam. Mientras no
    # exista ese DNS, alineamos el From (header Y envelope) al buzon SMTP
    # real, conservando el NOMBRE visible de marca -- ej.
    # "ILUS <daniel.aguilar@sphs.cl>", solo cambia la casilla. Afecta TODOS
    # los modulos que mandan por SMTP (tickets/retiros/transporte/
    # mantenciones/etc.); es intencional, todos comparten el mismo
    # problema de entregabilidad. El Reply-To configurado NO se toca. Si
    # el dia de mañana se configura SPF/DKIM/DMARC del dominio de marca y
    # Daniel cambia ILUS_BRAND_FROM_EMAIL a una casilla DEL MISMO dominio
    # que smtp_user, este parche deja de actuar solo (dominios iguales ->
    # no hace nada, ver comparacion abajo). La rama Resend NO se toca
    # (usa su propio dominio verificado, aparte del SMTP).
    _smtp_user_real = cfg.get("smtp_user", "") or ""

    def _tk_email_dominio(addr):
        return (addr or "").rsplit("@", 1)[-1].strip().lower()

    if _smtp_user_real and _tk_email_dominio(from_addr_cfg) != _tk_email_dominio(_smtp_user_real):
        print(f"[ILUS][EMAIL] From alineado a {_smtp_user_real} "
              f"(dominio de marca sin DNS de autenticacion)")
        from_addr_cfg = _smtp_user_real

    # ── Envío vía SMTP (único método; configurable desde el front) ──────
    # Con adjuntos el contenedor debe ser multipart/mixed (el HTML va en un
    # sub-multipart alternative). Sin adjuntos, igual que siempre.
    if att_norm:
        msg = MIMEMultipart("mixed")
        _alt = MIMEMultipart("alternative")
        _alt.attach(MIMEText(html_body, "html", "utf-8"))
        msg.attach(_alt)
        for _fn, _fb, _fm in att_norm:
            try:
                if _fm and _fm.lower().startswith("text/"):
                    # text/* (ej. .ics): usar MIMEText para PRESERVAR el Content-Type
                    # real (text/calendar). Con MIMEApplication se degradaba a
                    # application/calendar y Gmail/Apple Mail no ofrecían el botón
                    # "Agregar a calendario". Para .ics agregamos method=PUBLISH
                    # (coincide con el METHOD:PUBLISH del VCALENDAR). (review 2026-06-17)
                    _txt = _fb.decode("utf-8", "replace") if isinstance(_fb, (bytes, bytearray)) else str(_fb)
                    _tsub = (_fm.split("/", 1)[1] or "plain")
                    _part = MIMEText(_txt, _tsub, "utf-8")
                    if _tsub == "calendar":
                        try:
                            _part.set_param("method", "PUBLISH")
                        except Exception:
                            pass
                else:
                    _sub = "octet-stream"
                    if _fm and "/" in _fm:
                        _sub = _fm.split("/", 1)[1] or "octet-stream"
                    _part = MIMEApplication(_fb, _subtype=_sub)
                _part.add_header("Content-Disposition", "attachment", filename=_fn)
                msg.attach(_part)
            except Exception as _e_att:
                print(f"[ILUS][EMAIL] adjunto '{_fn}' descartado: {_e_att}")
    else:
        msg = MIMEMultipart("alternative")
        msg.attach(MIMEText(html_body, "html", "utf-8"))
    msg["Subject"] = subject
    msg["From"]    = f"{from_name} <{from_addr_cfg}>"
    msg["To"]      = to_addr
    if reply_to:
        msg["Reply-To"] = reply_to
    # CC (2026-07-11, respuesta de tickets): acepta string "a@x.cl,b@y.cl" o
    # lista. El header Cc es solo display -- el envio real depende de incluir
    # estos destinatarios en la lista de sendmail() mas abajo.
    cc_list = ([c.strip() for c in cc.split(",") if c.strip()] if isinstance(cc, str) else list(cc)) if cc else []
    if cc_list:
        msg["Cc"] = ", ".join(cc_list)

    host      = cfg["smtp_host"]
    port      = int(cfg.get("smtp_port", 587))
    secure    = bool(cfg.get("secure"))
    user      = cfg["smtp_user"]
    passwd    = cfg.get("smtp_pass", "")
    from_addr = from_addr_cfg or user
    todos_destinatarios = [to_addr] + cc_list

    def _try_send(p, sec, timeout=10):
        # Timeout reducido a 10s/intento (antes 30s). Si el endpoint
        # va a fallback Resend, el peor caso total es: SMTP attempt1
        # (10s) + SMTP attempt2 (10s) + Resend (~5s) = ~25s, no minutos.
        # Cuando Gmail rechaza credenciales el LOGIN responde en <1s, así
        # que 10s solo se gasta cuando el socket TLS pelea por handshake.
        if sec:
            with _open_smtp_client(host, p, True, timeout=timeout) as srv:
                srv.login(user, passwd)
                srv.sendmail(from_addr, todos_destinatarios, msg.as_string())
        else:
            with _open_smtp_client(host, p, False, timeout=timeout) as srv:
                srv.ehlo()
                srv.starttls()
                srv.login(user, passwd)
                srv.sendmail(from_addr, todos_destinatarios, msg.as_string())

    # Intentos: puerto configurado → puerto alternativo automático
    attempts = [(port, secure)]
    if port == 587 and not secure:
        attempts.append((465, True))   # fallback SSL si STARTTLS falla
    elif port == 465 and secure:
        attempts.append((587, False))  # fallback STARTTLS si SSL falla

    last_exc = None
    for p, sec in attempts:
        try:
            _try_send(p, sec)
            print(f"[ILUS][EMAIL] Enviado a {to_addr} via :{p} (source={cfg.get('_source','?')})")
            return True
        except Exception as exc:
            last_exc = exc
            print(f"[ILUS][EMAIL] Intento :{p} falló — {exc}")

    # ── 3. Si arrancamos por SMTP y falló, último intento con Resend ────
    # Solo cuando provider="smtp" (default): intentamos Resend como red
    # de respaldo. Esto cubre el caso Railway donde Gmail bloquea SMTP
    # outbound desde IPs cloud.
    if intentar_smtp_primero and resend_disponible:
        print(f"[ILUS][EMAIL] SMTP falló — último intento con Resend como respaldo")
        from_for_resend = None
        try:
            brand_email = marca["from_email"] or cfg.get("from_addr") or resend_cfg.get("from_addr")
            from_name_r = marca["from_name"]  or cfg.get("from_name") or "ILUS Fitness"
            if brand_email:
                from_for_resend = f"{from_name_r} <{brand_email}>"
        except Exception:
            pass
        if _send_via_resend(to_addr, subject, html_body,
                            from_addr=from_for_resend,
                            reply_to=marca["reply_to"],
                            attachments=att_norm, cc=cc):
            print(f"[ILUS][EMAIL] Enviado a {to_addr} via Resend (fallback de SMTP)")
            return True

    try:
        g._last_email_error = str(last_exc)
    except Exception:
        pass
    print(f"[ILUS][EMAIL] Todos los intentos fallaron para {to_addr}: {last_exc}")
    return False


def _password_strength_errors(password: str) -> list[str]:
    """Politica minima para claves creadas desde enlaces publicos."""
    errors = []
    if len(password or "") < 12:
        errors.append("La contraseña debe tener al menos 12 caracteres.")
    if not re.search(r"[a-z]", password or ""):
        errors.append("Incluye al menos una letra minuscula.")
    if not re.search(r"[A-Z]", password or ""):
        errors.append("Incluye al menos una letra mayuscula.")
    if not re.search(r"\d", password or ""):
        errors.append("Incluye al menos un numero.")
    if not re.search(r"[^A-Za-z0-9]", password or ""):
        errors.append("Incluye al menos un simbolo.")
    return errors


def _issue_password_token(user_id: int, minutes: int = 60) -> tuple[str, datetime]:
    """Crea un token de un solo uso e invalida enlaces anteriores del usuario."""
    token = secrets.token_urlsafe(64)
    expires = datetime.utcnow() + timedelta(minutes=minutes)
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            f"UPDATE `{RESETS_TABLE}` SET used=1 WHERE user_id=%s AND used=0",
            (user_id,),
        )
        cur.execute(
            f"INSERT INTO `{RESETS_TABLE}` (user_id, token, expires_at) VALUES (%s,%s,%s)",
            (user_id, token, expires),
        )
    conn.commit()
    return token, expires


def _send_password_access_email(
    to_addr: str,
    to_name: str,
    action_url: str,
    *,
    actor_name: str = "ILUS",
    mode: str = "reset",
    minutes: int = 60,
    skip_diagnose: bool = False,
    tpl_estado: str = None,
) -> bool:
    """Envía correo para crear o cambiar clave con token seguro.

    NOTA IMPORTANTE: NO se valida SMTP previamente. El flujo real
    (`_send_ilus_email_real`) intenta primero Resend (HTTPS, funciona desde
    Railway) y si falla cae a SMTP. Validar SMTP antes hacía que incluso con
    Resend configurado este email NO se enviara — el diagnose SMTP timeaba
    en Railway y Resend nunca se intentaba. El parámetro `skip_diagnose`
    se mantiene por retrocompatibilidad pero ya no controla nada.

    `tpl_estado` (FIX 2026-07-25, auditoría Comunicaciones): antes esta
    función SIEMPRE mapeaba mode=="reset" -> estado 'olvido_contrasena',
    tanto para el self-service "olvidé mi clave" (correcto) COMO para el
    cambio de clave INICIADO POR UN ADMIN (_notify_user_access,
    email_purpose="change") -- que en /comunicaciones tiene su PROPIA
    plantilla editable separada, 'cambio_clave' ("Solicitud para cambiar la
    contraseña del usuario"). Resultado: 'cambio_clave' quedaba huérfana --
    Daniel podía editarla en la UI y el cambio NUNCA se reflejaba en el
    correo real, que siempre usaba el texto de 'olvido_contrasena'. Con este
    parámetro opcional, el caller puede fijar el estado exacto; si no se
    pasa, se conserva el comportamiento histórico (setup/reset) para no
    romper otros callers."""
    _ = skip_diagnose  # noqa: F841 (mantener firma para callers existentes)

    is_setup     = mode == "setup"
    # ── Plantilla editable desde /comunicaciones (con respaldo hardcodeado) ──
    _tpl_estado = tpl_estado or ("usuario_nuevo" if is_setup else "olvido_contrasena")
    # FIX 2026-07-25 (auditoría Comunicaciones): 'olvido_contrasena' y
    # 'cambio_clave' declaran {{ip_acceso}} pero nunca se pasaba -- quedaba
    # blanco (barrido de seguridad). Best-effort: esta función también corre
    # en threads daemon SIN contexto de request (ver _notify_user_access ->
    # _send_bg con solo app_context), así que `request.remote_addr` puede
    # no existir; degradamos a "" en ese caso (nunca rompe el envío).
    try:
        _ip_acceso = request.remote_addr or ""
    except Exception:
        _ip_acceso = ""
    _db = _render_comm_template(_tpl_estado, "email", {
        "nombre_usuario": to_name, "email_usuario": to_addr, "rol": "",
        "link_acceso": action_url, "creado_por": actor_name,
        "fecha_hora": _now_chile().strftime("%d/%m/%Y %H:%M"),
        "ip_acceso": _ip_acceso,
    })
    # ── GUARDA: un correo de acción SIN el enlace no sirve para nada ──────
    # Bug real reportado por Daniel (2026-08-05): pedía "olvidé mi contraseña",
    # el correo llegaba, pero "no manda ningún botón, solamente dice que
    # alguien actualizó la contraseña". Causa: la plantilla guardada en la BD
    # no traía {{link_acceso}}, así que el usuario recibía un aviso sin forma
    # de actuar y quedaba encerrado fuera del sistema.
    #
    # Esta función SIEMPRE manda un correo con un token de un solo uso: si el
    # cuerpo renderizado no contiene ese enlace, la plantilla está mal (le
    # borraron el botón, o quedó sembrada una versión de "aviso" en lugar de
    # una de "acción"). En ese caso se descarta y se cae al texto hardcodeado
    # de abajo, que sí lleva botón. Degradar es correcto acá; mandar un correo
    # sin salida, no.
    if _db and action_url and action_url not in (_db[1] or ""):
        print(f"[ILUS][EMAIL] plantilla '{_tpl_estado}' no incluye el enlace de "
              f"acción; se usa el texto por defecto para no dejar al usuario "
              f"sin botón.", flush=True)
        _db = None
    if _db:
        _asunto, _cuerpo = _db
        sent = _send_ilus_email(to_addr, _brand_subject(_asunto),
                                _comm_render_email_document(_asunto, _cuerpo),
                                evento="password_access", modulo="comunicacion_interna")
        if not sent and not getattr(g, "_last_email_error", ""):
            g._last_email_error = (
                "No se pudo enviar el correo. Verifica en /comunicaciones "
                "que Resend o SMTP estén configurados correctamente."
            )
        return sent
    marca        = _get_marca()
    marca_nombre = marca["name"]
    titulo  = "Crear contraseña de acceso" if is_setup else "Cambio de contraseña solicitado"
    subject = _brand_subject(
        "Crea tu contraseña de acceso" if is_setup else "Cambio seguro de contraseña"
    )
    button = "Crear mi contraseña" if is_setup else "Restablecer contraseña"
    intro = (
        f"<strong>{actor_name}</strong> creó una cuenta para ti en el sistema {marca_nombre}."
        if is_setup
        else f"Recibimos una solicitud para cambiar la contraseña de tu cuenta {marca_nombre}."
    )
    html_body = _ilus_email_html(
        titulo=titulo,
        subtitulo="Acceso seguro con enlace de un solo uso",
        saludo=to_name,
        parrafos=[
            intro,
            "Por seguridad, la contraseña no se envía ni se escribe manualmente. "
            "Debes definirla desde el botón de este correo.",
            f"Este enlace vence en <strong>{minutes} minutos</strong>, solo puede usarse una vez "
            "y reemplaza cualquier enlace anterior.",
            f'Si no esperabas este correo, ignóralo o avísale al administrador.<br>'
            f'<span style="font-size:11px;color:#777">Enlace directo: '
            f'<a href="{action_url}" style="color:{marca["corp_color"]}">{action_url}</a></span>',
        ],
        btn_primario_txt=button,
        btn_primario_url=action_url,
        info_lineas=[
            ("", "Cuenta", to_addr),
            ("", "Solicitado por", actor_name),
        ],
    )
    sent = _send_ilus_email(to_addr, subject, html_body,
                            evento="password_access", modulo="comunicacion_interna")
    if not sent and not getattr(g, "_last_email_error", ""):
        g._last_email_error = (
            "No se pudo enviar el correo. Verifica en /comunicaciones "
            "que Resend o SMTP estén configurados correctamente."
        )
    return sent


def _send_login_alert_email(to_addr: str, to_name: str, *, ip: str = "",
                            user_agent: str = "", cuando: str = "",
                            action_url: str = "") -> bool:
    """Alerta de inicio de sesión por correo. DESHABILITADA 2026-06-08 (Daniel:
    "un inicio de sesión no amerita un correo"). Se deja la función por si se
    reactiva en el futuro, pero hoy NO envía nada a nadie."""
    return False  # ← no enviar correos de inicio de sesion a los usuarios
    if not to_addr or "@" not in to_addr:
        return False
    # ── Plantilla editable desde /comunicaciones (con respaldo hardcodeado) ──
    _db = _render_comm_template("inicio_sesion", "email", {
        "nombre_usuario": to_name, "email_usuario": to_addr,
        "ip_acceso": ip or "", "fecha_hora": cuando or "",
        "link_acceso": action_url or "",
    })
    if _db:
        _asunto, _cuerpo = _db
        return _send_ilus_email(to_addr, _brand_subject(_asunto),
                                _comm_render_email_document(_asunto, _cuerpo),
                                evento="login_alert", modulo="comunicacion_interna")
    try:
        marca_nombre = _get_marca()["name"]
    except Exception:
        marca_nombre = "ILUS Fitness"
    info = []
    if cuando:     info.append(("", "Fecha y hora", cuando))
    if ip:         info.append(("", "Dirección IP", ip))
    if user_agent: info.append(("", "Dispositivo", user_agent))
    info.append(("", "Cuenta", to_addr))
    html_body = _ilus_email_html(
        titulo="Nuevo inicio de sesión",
        subtitulo="Detectamos un acceso desde un dispositivo nuevo",
        saludo=to_name,
        parrafos=[
            f"Acabamos de registrar un inicio de sesión en tu cuenta {marca_nombre} "
            "desde un dispositivo o navegador que no habíamos visto antes.",
            "Si fuiste tú, no necesitas hacer nada — este aviso es solo por tu seguridad.",
            "Si <strong>no</strong> reconoces este acceso, cambia tu contraseña de "
            "inmediato y avísale al administrador.",
        ],
        btn_primario_txt=("Cambiar mi contraseña" if action_url else ""),
        btn_primario_url=action_url,
        info_lineas=info,
    )
    return _send_ilus_email(to_addr, _brand_subject("Nuevo inicio de sesión"), html_body,
                            evento="login_alert", modulo="comunicacion_interna")


def _portal_login_url():
    try:
        return url_for("login", _external=True)
    except RuntimeError:
        # Sin request context (background thread) — url_for necesita request o SERVER_NAME.
        # login_url solo se usa en cuerpos informativos (WhatsApp/manual), no en tokens;
        # retornar "" es seguro y no interrumpe el envío de email.
        sn = app.config.get("SERVER_NAME") or os.environ.get("FLASK_SERVER_NAME", "")
        return f"https://{sn}/login" if sn else ""


def _send_access_notification_email(to_addr: str, to_name: str, login_url: str, *, actor_name: str = "ILUS") -> bool:
    """Notifica que el acceso al portal fue habilitado, sin compartir la clave."""
    html_body = _ilus_email_html(
        titulo="Acceso al portal ILUS habilitado",
        subtitulo="Ya puedes ingresar a la aplicacion",
        saludo=to_name,
        parrafos=[
            f"<strong>{actor_name}</strong> habilito tus credenciales de acceso al portal ILUS.",
            "Por seguridad, este correo no incluye tu contraseña. Usa la clave entregada por el administrador "
            "o solicita un cambio de contraseña desde el portal cuando el correo este disponible.",
            "Presiona el boton para ir a la aplicacion.",
        ],
        btn_primario_txt="Ingresar al portal",
        btn_primario_url=login_url,
        info_lineas=[
            ("", "Cuenta", to_addr),
            ("", "Portal", login_url),
        ],
    )
    sent = _send_ilus_email(to_addr, _brand_subject("Acceso al portal habilitado"), html_body,
                            evento="acceso_habilitado", modulo="comunicacion_interna")
    if not sent and not getattr(g, "_last_email_error", ""):
        g._last_email_error = "No se pudo enviar la notificacion de acceso por email."
    return sent


def _notify_user_access(username: str, nombre: str, phone: str = "", *,
                        mode: str = "manual", action_url: str = "",
                        email_purpose: str = "invite") -> dict:
    """
    Envia notificaciones email/WhatsApp sobre acceso o creacion/cambio de clave.

    email_purpose:
      - 'invite' (default): cuenta nueva → email "Crea tu contraseña" (mode=setup, 24h)
      - 'change': cambio solicitado por UN ADMIN → plantilla 'cambio_clave' (60min)
      - 'forgot': el propio usuario apretó "Olvidé mi contraseña" → plantilla
                  'olvido_contrasena' (60min)
                  Gmail los trata como mensajes distintos (subject distinto), evita threading
                  con la invitación previa y el usuario distingue claramente cada acción.

    Por qué 'forgot' existe (bug reportado por Daniel, 2026-08-05): el flujo
    self-service mandaba email_purpose='change', o sea la plantilla del
    admin. En producción esa plantilla quedó sembrada con la variante de
    AVISO ("Tu contraseña ILUS fue actualizada", sin botón ni enlace) en vez
    de la de ACCIÓN. Resultado: el usuario pedía recuperar su clave y recibía
    un correo diciéndole que su contraseña ya había sido cambiada, sin forma
    de hacer nada. Las dos plantillas describen situaciones distintas y ahora
    cada flujo usa la suya.
    """
    actor = g.user["nombre"] if getattr(g, "user", None) else "ILUS"
    login_url = _portal_login_url()
    result = {"email": None, "whatsapp": None, "errors": []}

    try:
        if mode == "token" and action_url:
            if email_purpose in ("change", "forgot"):
                # Cada flujo con su plantilla: 'cambio_clave' cuando lo inicia un
                # admin, 'olvido_contrasena' cuando el usuario aprieta "Olvidé mi
                # contraseña". Antes ambos usaban 'cambio_clave' y el self-service
                # terminaba mandando el aviso equivocado (ver docstring).
                result["email"] = _send_password_access_email(
                    username, nombre, action_url,
                    actor_name=actor, mode="reset", minutes=60,
                    tpl_estado=("olvido_contrasena" if email_purpose == "forgot"
                                else "cambio_clave"),
                )
            else:
                result["email"] = _send_invitation_email(username, nombre, action_url, actor)
        else:
            result["email"] = _send_access_notification_email(username, nombre, login_url, actor_name=actor)
        if not result["email"]:
            result["errors"].append(getattr(g, "_last_email_error", "") or "No se pudo enviar email.")
    except Exception as exc:
        result["email"] = False
        result["errors"].append(f"Email: {exc}")

    # WhatsApp se intenta SÓLO si el canal está activo globalmente
    # (env var COMM_CANALES_ACTIVOS). Daniel dio de baja Twilio, así
    # que por default queda en silencio. El email vía Resend ya partió
    # arriba — eso es lo importante para el flujo de acceso.
    if phone and _canal_activo("whatsapp"):
        try:
            wa_cfg = _get_wa_cfg()
            if wa_cfg.get("account_sid") and wa_cfg.get("auth_token") and wa_cfg.get("from_number"):
                marca = _get_marca()
                firma = f"\n— {marca['name']}"
                # 'forgot' entra acá igual que 'change': el texto sirve para
                # ambos. Si quedara afuera caería en la rama de "Bienvenido /
                # crea tu contraseña (7 días)", que es de cuenta nueva y da
                # una vigencia equivocada.
                if mode == "token" and action_url and email_purpose in ("change", "forgot"):
                    body = (
                        _brand_wa_prefix("Recupera tu contraseña")
                        + f"Hola {nombre}, recibimos una solicitud para cambiar tu contraseña.\n\n"
                          f"Define tu nueva clave aquí (válido 60 min, un solo uso):\n{action_url}\n\n"
                          f"Si no fuiste tú, ignora este mensaje."
                        + firma
                    )
                elif mode == "token" and action_url:
                    body = (
                        _brand_wa_prefix(f"Bienvenido a {marca['name']}")
                        + f"Hola {nombre}, habilitamos tu acceso al portal {marca['name']}.\n\n"
                          f"Crea tu contraseña aquí (válido 7 días):\n{action_url}\n\n"
                          f"Portal: {login_url}"
                        + firma
                    )
                else:
                    body = (
                        _brand_wa_prefix("Acceso habilitado")
                        + f"Hola {nombre}, tus credenciales del portal {marca['name']} están listas.\n\n"
                          f"Ingresa aquí: {login_url}\n"
                          f"Por seguridad, este mensaje no incluye tu contraseña."
                        + firma
                    )
                sid = _send_whatsapp(wa_cfg["account_sid"], wa_cfg["auth_token"], wa_cfg["from_number"], phone, body,
                                     modulo="comunicacion_interna")
                result["whatsapp"] = sid
            else:
                result["whatsapp"] = False
                result["errors"].append("WhatsApp no está configurado.")
        except Exception as exc:
            result["whatsapp"] = False
            result["errors"].append(f"WhatsApp: {exc}")
    elif phone:
        # Canal apagado por config (COMM_CANALES_ACTIVOS). No es un error,
        # el flujo principal va por email. Dejamos rastro discreto en log.
        result["whatsapp"] = False
        print(f"[notify_user_access] WhatsApp omitido (canal off via COMM_CANALES_ACTIVOS) phone={phone[:6]}***",
              flush=True)
    return result


def _access_notification_flash(result: dict, *, token_mode: bool = False) -> tuple[str, str]:
    """Construye un mensaje corto para el admin segun los canales que respondieron."""
    channels = []
    if result.get("email"):
        channels.append("email")
    if result.get("whatsapp"):
        channels.append("WhatsApp")
    if channels:
        action = "enlace seguro enviado" if token_mode else "notificacion de acceso enviada"
        return f"{action.capitalize()} por {', '.join(channels)}.", "success"
    errors = [str(e) for e in result.get("errors", []) if e]
    detail = " ".join(errors[:2]) or "Revisa SMTP o WhatsApp en Comunicaciones."
    return f"Usuario guardado, pero no salio la notificacion. {detail}", "warning"


