def _accion_meta(modulo, accion):
    """Devuelve dict {label, tipo, icon} para una acción. Default si no existe."""
    return (PERMISSIONS_META.get(modulo, {}) or {}).get(accion) or {
        "label": accion.replace("_", " ").title(),
        "tipo": "submodulo",
        "icon": "bi-check2",
    }


def _get_roles_disponibles():
    """
    Devuelve la lista de roles activos desde roles_dinamicos.
    Se usa para poblar dropdowns de creación/edición de usuario.
    Si la tabla aún no existe (primer arranque), devuelve los roles del sistema hardcoded.
    """
    try:
        rows = mysql_fetchall(
            "SELECT slug,nombre,color,is_system FROM roles_dinamicos WHERE activo=1 "
            "ORDER BY is_system DESC, nombre"
        )
        if rows:
            return [dict(r) for r in rows]
    except Exception:
        pass
    # Fallback si la tabla aún no fue inicializada
    return [
        {"slug":"superadmin", "nombre":"Super Administrador", "color":"#dc2626", "is_system":1},
        {"slug":"admin",      "nombre":"Administrador",      "color":"#2563eb", "is_system":1},
        {"slug":"editor",     "nombre":"Editor",             "color":"#ea580c", "is_system":1},
        {"slug":"lector",     "nombre":"Solo lectura",       "color":"#6b7280", "is_system":1},
    ]


def _es_rol_valido(slug):
    """True si el slug existe en roles_dinamicos activos. Solo superadmin puede asignar 'superadmin'."""
    if not slug:
        return False
    try:
        row = mysql_fetchone(
            "SELECT 1 FROM roles_dinamicos WHERE slug=%s AND activo=1 LIMIT 1", (slug,)
        )
        return bool(row)
    except Exception:
        return slug in {"superadmin","admin","editor","lector","vendedor","ejecutivo"}


def get_role_permissions(slug):
    """Devuelve dict {modulo:{accion:bool}} para un rol dado."""
    if slug == "superadmin":
        return {m: {a: True for a in cfg["acciones"]} for m, cfg in PERMISSIONS_MATRIX.items()}
    rows = mysql_fetchall(
        "SELECT modulo,accion,permitido FROM rol_permisos WHERE rol_slug=%s", (slug,)
    )
    perms = {m: {a: False for a in cfg["acciones"]} for m, cfg in PERMISSIONS_MATRIX.items()}
    for r in rows:
        if r["modulo"] in perms and r["accion"] in perms[r["modulo"]]:
            perms[r["modulo"]][r["accion"]] = bool(r["permitido"])
    return perms


def has_role_permission(slug, modulo, accion):
    """Verifica si un rol dinámico tiene un permiso específico."""
    if slug == "superadmin":
        return True
    row = mysql_fetchone(
        "SELECT permitido FROM rol_permisos WHERE rol_slug=%s AND modulo=%s AND accion=%s",
        (slug, modulo, accion)
    )
    return bool(row and row.get("permitido"))


# Roles nativos del sistema — protegidos por SLUG (no por is_system). NUNCA
# se eliminan. Cualquier slug fuera de este set es gestionable/eliminable por
# el admin, incluido un duplicado legacy con is_system=1 mal puesto.
# (Daniel 2026-06-04 — 'no puedo eliminar un rol' / 'doble Super Administrador'.)
_PROTECTED_ROLE_SLUGS = frozenset({
    "superadmin", "admin", "editor", "mantenciones",
    "transporte", "vendedor", "lector",
})


@app.route("/admin/roles")
@require_permission("admin")
def admin_roles():
    """Vista UNIFICADA: usuarios + lista de roles dinámicos + matriz editable."""
    users = mysql_fetchall(
        f"SELECT id,username,nombre,role,active FROM `{AUTH_TABLE}` ORDER BY nombre", ()
    )
    roles = mysql_fetchall(
        "SELECT * FROM roles_dinamicos WHERE activo=1 ORDER BY is_system DESC, nombre"
    )
    perms_by_role = {}
    for r in roles:
        perms_by_role[r["slug"]] = get_role_permissions(r["slug"])
    # Pre-clasifico cada acción por tipo (submodulo / bloqueo) para que el
    # template renderice 2 grupos visuales sin tener que llamar a Python.
    matrix_grouped = {}
    for mod_key, mod_cfg in PERMISSIONS_MATRIX.items():
        subs, blocks = [], []
        for accion in mod_cfg["acciones"]:
            meta = _accion_meta(mod_key, accion)
            entry = {"key": accion, **meta}
            (subs if meta["tipo"] == "submodulo" else blocks).append(entry)
        matrix_grouped[mod_key] = {
            **mod_cfg,
            "submodulos": subs,
            "bloqueos":   blocks,
        }
    roles_ctx = []
    for _r in roles:
        _rd = dict(_r)
        # is_protected → el template oculta "Eliminar rol" para los 7 nativos.
        # Los demás (custom/legacy/duplicado) SÍ muestran el botón.
        _rd["is_protected"] = _rd.get("slug") in _PROTECTED_ROLE_SLUGS
        roles_ctx.append(_rd)
    return render_template("admin_roles.html",
        users=[dict(u) for u in users],
        roles=roles_ctx,
        matrix=PERMISSIONS_MATRIX,
        matrix_grouped=matrix_grouped,
        perms=perms_by_role,
    )


@app.route("/admin/tecnicos-clasificacion")
@require_permission("admin")
def admin_tecnicos_clasificacion():
    """Interno vs Externo de cada técnico — QUÉ ve el sistema y POR QUÉ.

    2026-08-27. Daniel pidió 3 veces que Daniel Pulgar e Isabel Milling
    dejaran de salir entre los INTERNOS del monitor, y las 3 veces le
    respondí que cambiara roles a mano — sin poder decirle exactamente
    cuál, porque desde el código no se ve el dato real. Esta pantalla
    existe para cortar ese ida y vuelta: muestra, técnico por técnico, el
    rol guardado, si tiene ficha de proveedor externo y con qué nombre
    calza, y el veredicto final con su motivo. Desde acá se corrige en un
    clic, sin depender de nadie.

    Usa EXACTAMENTE el mismo criterio que `_ot_tv_datos` para clasificar
    (rol `tecnico_externo*` o ficha en `mant_tecnicos_externos`), así que
    lo que se ve acá es lo que va a mostrar el monitor — no una segunda
    lógica que se pueda desincronizar.
    """
    filas = []
    try:
        rows = mysql_fetchall(
            "SELECT au.id, au.username, COALESCE(au.nombre, au.username) AS nombre, "
            "       au.role, au.active, "
            "       te.id            AS prov_por_id, "
            "       te.razon_social  AS prov_por_id_nombre, "
            "       ten.id           AS prov_por_nombre, "
            "       ten.razon_social AS prov_por_nombre_rs "
            "  FROM app_users au "
            "  LEFT JOIN mant_tecnicos_externos te  ON te.user_id = au.id "
            "  LEFT JOIN mant_tecnicos_externos ten "
            "         ON ten.user_id IS NULL "
            "        AND LOWER(TRIM(COALESCE(au.nombre, au.username))) IN ( "
            "              LOWER(TRIM(ten.razon_social)), "
            "              LOWER(TRIM(ten.contacto_nombre)) ) "
            " WHERE LOWER(au.role) LIKE %s "
            " ORDER BY au.active DESC, nombre", ("tecnico%",)) or []
    except Exception as e:
        print(f"[admin_tec_clasif] {e}", flush=True)
        rows = []

    for r in rows:
        rol = (r.get("role") or "").lower()
        por_rol = rol.startswith("tecnico_externo")
        por_id = bool(r.get("prov_por_id"))
        por_nombre = bool(r.get("prov_por_nombre"))
        externo = por_rol or por_id or por_nombre
        if por_rol:
            motivo = f"Su rol es «{r.get('role')}»"
        elif por_id:
            motivo = ("Tiene ficha de proveedor enlazada: "
                      f"{r.get('prov_por_id_nombre') or '—'}")
        elif por_nombre:
            motivo = ("Su nombre calza con el proveedor "
                      f"«{r.get('prov_por_nombre_rs') or '—'}» (ficha sin enlazar)")
        else:
            motivo = f"Su rol es «{r.get('role')}» y no tiene ficha de proveedor"
        filas.append({**r, "externo": externo, "motivo": motivo})

    # Roles realmente existentes, para no ofrecer uno que el PUT rechace.
    try:
        _rr = mysql_fetchall(
            "SELECT slug FROM roles_dinamicos WHERE activo=1 AND slug LIKE %s "
            " ORDER BY slug", ("tecnico%",)) or []
        roles_tecnicos = [x["slug"] for x in _rr]
    except Exception:
        roles_tecnicos = []
    for _r in ("tecnico", "tecnico_externo"):
        if _r not in roles_tecnicos:
            roles_tecnicos.append(_r)

    return render_template("admin/tecnicos_clasificacion.html",
                           filas=filas, roles_tecnicos=sorted(roles_tecnicos))


@app.route("/admin/roles/<int:uid>", methods=["PUT"])
@require_permission("admin")
def admin_roles_update(uid):
    """Asigna rol a un usuario (acepta cualquier rol activo registrado)."""
    d = request.get_json(silent=True) or {}
    role = d.get("role", "")
    valid_rows = mysql_fetchall("SELECT slug FROM roles_dinamicos WHERE activo=1")
    valid = {r["slug"] for r in valid_rows} | {"superadmin"}
    if role not in valid:
        return jsonify({"error":"Rol no válido"}), 400
    if g.user and g.user["id"] == uid and not g.permissions.get("superadmin"):
        return jsonify({"error":"No puedes cambiar tu propio rol"}), 403
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(f"UPDATE `{AUTH_TABLE}` SET role=%s WHERE id=%s", (role, uid))
        conn.commit()
        # Refresco de sesión (2026-06-01): el usuario afectado tiene su rol
        # cacheado en la cookie de sesión. Bumpeamos la época de auth para que
        # en su próxima navegación re-lea el rol/permisos frescos de la BD,
        # sin tener que cerrar sesión a mano.
        try: _cache_signal_bump("auth")
        except Exception: pass
        _audit("user_role_change", target_type="user", target_id=uid,
               details={"nuevo_rol": role})
        return jsonify({"ok":True})
    finally:
        conn.close()


