@app.route("/admin/roles/matrix", methods=["POST"])
@require_permission("admin")
def admin_roles_matrix_save():
    """Guarda la matriz completa (form: rol_slug.modulo.accion=on)."""
    rol_slug = (request.form.get("rol_slug") or "").strip()
    if not rol_slug:
        return jsonify({"error":"Rol no especificado"}), 400
    if rol_slug == "superadmin":
        return jsonify({"error":"superadmin tiene acceso total y no es editable"}), 400
    permisos_recibidos = set()
    for k,v in request.form.items():
        if k.startswith("p_"):
            try:
                _, modulo, accion = k.split(".",2)
                permisos_recibidos.add((modulo, accion))
            except ValueError: continue
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            # Borra y reinsertar (más simple)
            cur.execute("DELETE FROM rol_permisos WHERE rol_slug=%s", (rol_slug,))
            for modulo, cfg in PERMISSIONS_MATRIX.items():
                for accion in cfg["acciones"]:
                    permitido = 1 if (modulo, accion) in permisos_recibidos else 0
                    cur.execute(
                        "INSERT INTO rol_permisos (rol_slug,modulo,accion,permitido) "
                        "VALUES (%s,%s,%s,%s)",
                        (rol_slug, modulo, accion, permitido)
                    )
        conn.commit()
        # CRÍTICO: invalidar caché para que el cambio aplique en próximo request
        invalidate_role_cache(rol_slug)
        _audit("role_matrix_save",
               target_type="role", target_id=rol_slug,
               details={"permisos_count": len(permisos_recibidos)})
        return jsonify({"ok":True, "rol":rol_slug,
                        "permisos":len(permisos_recibidos)})
    finally:
        conn.close()


@app.route("/admin/roles/nuevo", methods=["POST"])
@require_permission("admin")
def admin_rol_crear():
    """Crea un nuevo rol dinámico."""
    nombre = (request.form.get("nombre") or "").strip()
    color  = (request.form.get("color") or "#6b7280").strip()[:20]
    descripcion = (request.form.get("descripcion") or "").strip()[:300]
    if not nombre:
        flash("Nombre del rol obligatorio.", "danger")
        return redirect(url_for("admin_roles_matrix"))
    slug = re.sub(r"[^a-z0-9_]","", nombre.lower().replace(" ","_"))[:60]
    if not slug:
        flash("Nombre inválido.", "danger")
        return redirect(url_for("admin_roles_matrix"))
    try:
        mysql_execute(
            "INSERT INTO roles_dinamicos (slug,nombre,descripcion,color,is_system) VALUES (%s,%s,%s,%s,0)",
            (slug, nombre, descripcion, color)
        )
        # AUTO-INICIALIZAR la matriz de permisos: insertar 1 fila por (módulo,acción)
        # con permitido=0. Así el admin ve TODA la matriz en la UI al editar el rol,
        # en vez de una matriz vacía sin acciones disponibles para marcar.
        try:
            filas = []
            for modulo, info in PERMISSIONS_MATRIX.items():
                for accion in info.get("acciones", []):
                    filas.append((slug, modulo, accion, 0))
            if filas:
                conn_init = get_mysql()
                try:
                    with conn_init.cursor() as cur:
                        cur.executemany(
                            "INSERT IGNORE INTO rol_permisos "
                            "(rol_slug, modulo, accion, permitido) VALUES (%s,%s,%s,%s)",
                            filas
                        )
                    conn_init.commit()
                except Exception as e_seed:
                    print(f"[admin_rol_crear] seed permisos falló: {e_seed}", flush=True)
                finally:
                    try: conn_init.close()
                    except Exception: pass
        except Exception as e_init:
            print(f"[admin_rol_crear] init permisos error: {e_init}", flush=True)

        flash(f"✅ Rol \"{nombre}\" creado con {sum(len(m['acciones']) for m in PERMISSIONS_MATRIX.values())} permisos inicializados (todos en 'no'). Marca los que quieras autorizar.", "success")
    except Exception as exc:
        print(f"[admin_rol_crear] error: {exc}", flush=True)
        flash("Error al crear rol. Revisa el log del servidor.", "danger")
    return redirect(url_for("admin_roles_matrix"))


@app.route("/admin/roles/<slug>/eliminar", methods=["POST"])
@require_permission("admin")
def admin_rol_eliminar(slug):
    """Elimina un rol dinámico.

    2026-06-04 (Daniel — 'no puedo eliminar un rol' + 'doble Super
    Administrador'): la protección pasó de la bandera `is_system` al SLUG
    canónico. Antes, un 'Super Administrador' DUPLICADO quedaba marcado
    is_system=1 y por eso NO se podía borrar. Ahora protegemos solo los 7
    slugs nativos ({_PROTECTED_ROLE_SLUGS}); cualquier otro rol (custom,
    legacy o duplicado) SÍ se elimina, aunque tenga is_system mal seteado.
    """
    slug = (slug or "").strip()
    if slug in _PROTECTED_ROLE_SLUGS:
        flash("Ese es un rol nativo del sistema y no se puede eliminar.", "danger")
        return redirect(url_for("admin_roles_matrix"))
    row = mysql_fetchone("SELECT nombre FROM roles_dinamicos WHERE slug=%s", (slug,))
    if not row:
        flash("Rol no encontrado.", "danger")
        return redirect(url_for("admin_roles_matrix"))
    # Destino de reasignación de usuarios. A prueba de LOCKOUT: si este rol es
    # un DUPLICADO por nombre de un rol canónico que sí existe (p.ej. el
    # 'Super Administrador' duplicado), mandamos sus usuarios a ese rol
    # canónico — NO a 'lector' — para no degradar admins reales por error.
    # Si no hay match canónico, caen a 'lector' (comportamiento histórico).
    destino = "lector"
    try:
        dup = mysql_fetchone(
            "SELECT slug FROM roles_dinamicos "
            " WHERE LOWER(TRIM(nombre)) = (SELECT LOWER(TRIM(nombre)) "
            "                                FROM roles_dinamicos WHERE slug=%s) "
            "   AND slug <> %s AND slug IN "
            "       ('superadmin','admin','editor','mantenciones','transporte','vendedor','lector') "
            " ORDER BY is_system DESC LIMIT 1",
            (slug, slug),
        )
        if dup and dup.get("slug"):
            destino = dup["slug"]
    except Exception:
        destino = "lector"
    mysql_execute(f"UPDATE `{AUTH_TABLE}` SET role=%s WHERE role=%s", (destino, slug))
    mysql_execute("DELETE FROM rol_permisos WHERE rol_slug=%s", (slug,))
    mysql_execute("DELETE FROM roles_dinamicos WHERE slug=%s", (slug,))
    # Refrescar sesión de los usuarios reasignados + invalidar caché de rol.
    try: _cache_signal_bump("auth")
    except Exception: pass
    try: invalidate_role_cache(slug)
    except Exception: pass
    try: invalidate_role_cache(destino)
    except Exception: pass
    flash(f"Rol \"{slug}\" eliminado. Los usuarios que lo tenían pasaron a \"{destino}\".", "success")
    return redirect(url_for("admin_roles_matrix"))


@app.route("/admin/roles/diagnostico")
@require_permission("admin")
def admin_roles_diagnostico():
    """Diagnóstico SEGURO (read-only) de roles — Daniel 2026-06-01.
    Muestra las filas REALES de roles_dinamicos + cuántos usuarios tiene cada
    rol + duplicados por nombre. Para depurar el 'doble Super Administrador'
    sin tocar datos. Solo superadmin."""
    if not (g.permissions or {}).get("superadmin"):
        return jsonify({"error": "Solo superadmin"}), 403
    roles = mysql_fetchall(
        "SELECT id, slug, nombre, color, is_system, activo, created_at "
        "FROM roles_dinamicos ORDER BY nombre, id"
    ) or []
    ucounts = mysql_fetchall(
        f"SELECT role AS slug, COUNT(*) AS n FROM `{AUTH_TABLE}` GROUP BY role"
    ) or []
    cnt = {r["slug"]: int(r["n"]) for r in ucounts}
    # Duplicados por nombre (case-insensitive)
    by_name = {}
    for r in roles:
        by_name.setdefault((r["nombre"] or "").strip().lower(), []).append(r["slug"])
    dups = {k: v for k, v in by_name.items() if len(v) > 1}
    out = []
    for r in roles:
        out.append({
            "id":        r["id"],
            "slug":      r["slug"],
            "nombre":    r["nombre"],
            "is_system": bool(r["is_system"]),
            "activo":    bool(r["activo"]),
            "usuarios":  cnt.get(r["slug"], 0),
            "eliminable": (not r["is_system"]),
        })
    # Usuarios cuyo rol NO existe en roles_dinamicos (huérfanos) — útil saberlo
    slugs_existentes = {r["slug"] for r in roles}
    huerfanos = {s: n for s, n in cnt.items() if s not in slugs_existentes and s != "superadmin"}
    return jsonify({
        "ok": True,
        "total_roles": len(roles),
        "roles": out,
        "duplicados_por_nombre": dups,
        "usuarios_por_rol": cnt,
        "roles_huerfanos_con_usuarios": huerfanos,
        "nota": "is_system=true → NO eliminable. 'usuarios' = cuántas cuentas "
                "tienen ese rol (revisar antes de borrar/mergear). Si hay "
                "'duplicados_por_nombre', son varias filas con el mismo nombre.",
    })


