@app.route("/cubicador/sync-nombre", methods=["POST"])
@login_required
def cubicador_sync_nombre():
    """Actualiza el nombre de un producto en nuestra BD con el nombre del ERP."""
    if not g.permissions.get("cubicador"):
        return jsonify({"error": "sin permiso"}), 403
    sku        = request.form.get("sku", "").strip().upper()
    nombre_erp = request.form.get("nombre_erp", "").strip()
    if not sku or not nombre_erp:
        return jsonify({"error": "datos incompletos"}), 400
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            f"UPDATE `{PRODUCTS_TABLE}` SET nombre=%s WHERE UPPER(TRIM(sku))=%s",
            (nombre_erp, sku)
        )
    conn.commit()
    _invalidate_listing_cache()
    return jsonify({"ok": True, "sku": sku, "nombre": nombre_erp})


# ═══════════════════════════════════════════════════════════════
#  MÓDULO: ASIGNAR Y COTIZAR
# ═══════════════════════════════════════════════════════════════

# ── Credenciales FedEx Rate API (env vars; placeholders solo si faltan) ─
# FEDEX_RATE_CLIENT_ID, FEDEX_RATE_CLIENT_SECRET, FEDEX_ACCOUNT deben
# setearse en Railway → Variables. Si faltan, los endpoints de cotización
# FedEx devuelven 503 amigable en vez de crashear.
FEDEX_RATE_CLIENT_ID     = os.environ.get("FEDEX_RATE_CLIENT_ID", "").strip()
FEDEX_RATE_CLIENT_SECRET = os.environ.get("FEDEX_RATE_CLIENT_SECRET", "").strip()
FEDEX_ACCOUNT            = os.environ.get("FEDEX_ACCOUNT", "").strip()
FEDEX_ORIGIN_POSTAL      = os.environ.get("FEDEX_ORIGIN_POSTAL", "9276181").strip()
FEDEX_ORIGIN_CITY        = os.environ.get("FEDEX_ORIGIN_CITY", "Maipu").strip()
# Declared value (seguro de carga) en la Ship API. FedEx Chile doméstico
# rechaza ciertas monedas en este campo ("El tipo de moneda que seleccionó no
# es válido"), por eso se OMITE por defecto y la OT se crea sin valor declarado
# (cobertura estándar del courier). Para reactivar el seguro, setear
# FEDEX_DECLARED_CURRENCY a una moneda que la cuenta acepte (ej. "CLP" o "USD").
FEDEX_DECLARED_CURRENCY  = os.environ.get("FEDEX_DECLARED_CURRENCY", "").strip().upper()
FEDEX_OAUTH_URL          = "https://apis.fedex.com/oauth/token"
FEDEX_RATE_URL           = "https://apis.fedex.com/rate/v1/rates/quotes"

if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET and FEDEX_ACCOUNT):
    print("[ILUS][FEDEX] Credenciales FedEx Rate API NO configuradas — "
          "cotización FedEx deshabilitada. Setear FEDEX_RATE_CLIENT_ID, "
          "FEDEX_RATE_CLIENT_SECRET, FEDEX_ACCOUNT en Railway → Variables.",
          flush=True)

# Cache del token OAuth (dura ~3600 s)
_fedex_token_cache = {"token": None, "expires_at": 0}
_fedex_token_lock  = threading.Lock()


def _fedex_get_token() -> str:
    """Obtiene un Bearer token de FedEx (con cache para evitar re-autenticar en cada request)."""
    import requests as _req
    # Fail-fast si las credenciales no están seteadas — evita request 401 inútil.
    if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET):
        raise RuntimeError("FedEx Rate API no configurada (faltan FEDEX_RATE_CLIENT_ID/SECRET)")
    with _fedex_token_lock:
        now = time.time()
        if _fedex_token_cache["token"] and now < _fedex_token_cache["expires_at"] - 30:
            return _fedex_token_cache["token"]
        resp = _req.post(
            FEDEX_OAUTH_URL,
            data={
                "grant_type":    "client_credentials",
                "client_id":     FEDEX_RATE_CLIENT_ID,
                "client_secret": FEDEX_RATE_CLIENT_SECRET,
            },
            timeout=15,
        )
        resp.raise_for_status()
        j = resp.json()
        _fedex_token_cache["token"]      = j["access_token"]
        _fedex_token_cache["expires_at"] = now + int(j.get("expires_in", 3600))
        return _fedex_token_cache["token"]


# ═══════════════════════════════════════════════════════════════════════════
#  DIAGNÓSTICO DE ERRORES DE LA FEDEX RATE API
# ═══════════════════════════════════════════════════════════════════════════
# 2026-09-01 (logs de producción: "400 Client Error: Bad Request for url:
# https://apis.fedex.com/rate/v1/rates/quotes"): el `raise_for_status()` pelado
# tiraba a la basura el CUERPO de la respuesta, que es justo donde FedEx explica
# QUÉ campo está mal (`errors[].code` / `errors[].message`). Sin ese cuerpo el
# error es indiagnosticable. Estos helpers lo rescatan para el log del backend
# y, aparte, arman un mensaje amigable para el usuario (REGLA #4: nunca devolver
# detalles internos —ni la URL de la API— al cliente).

# Mensaje único que ve el usuario cuando el motivo real no le sirve de nada.
FEDEX_MSG_GENERICO = ("No pudimos cotizar con FedEx en este momento. "
                      "Intenta de nuevo o elige otro courier.")

# Códigos de error de FedEx que SÍ le sirven al operador porque hablan del dato
# que él ingresó (destino, peso, dimensiones). El resto (autorización, caída del
# servicio, error interno) se traduce al mensaje genérico: no puede hacer nada
# con eso y expondría internals.
_FEDEX_CODIGOS_UTILES = (
    "POSTAL", "ZIP", "CITY", "STATE", "PROVINCE", "COUNTRY", "ADDRESS",
    "WEIGHT", "DIMENSION", "PACKAGE", "DESTINATION", "ORIGIN",
)


class FedexRateError(Exception):
    """Error controlado del cotizador FedEx.

    Guarda a propósito DOS textos distintos (REGLA #4):
      - el texto de la excepción → detalle técnico, SOLO para el log del backend.
      - `mensaje_usuario`        → lo único que puede viajar al navegador.
    """

    def __init__(self, mensaje_tecnico: str, mensaje_usuario: str = ""):
        super().__init__(mensaje_tecnico)
        self.mensaje_usuario = (mensaje_usuario or "").strip() or FEDEX_MSG_GENERICO


def _fedex_sanitizar_log(texto) -> str:
    """Quita credenciales del texto antes de mandarlo al log (REGLA #4).

    Tapa el client id/secret, el número de cuenta y cualquier Bearer token que
    se pudiera colar en el cuerpo devuelto por FedEx.
    """
    out = str(texto or "")
    for secreto in (FEDEX_RATE_CLIENT_SECRET, FEDEX_RATE_CLIENT_ID, FEDEX_ACCOUNT):
        if secreto and len(secreto) >= 4:
            out = out.replace(secreto, "«oculto»")
    try:
        out = re.sub(r"(?i)bearer\s+[A-Za-z0-9._\-]+", "Bearer «oculto»", out)
    except Exception:
        pass
    return out


def _fedex_errores_de_respuesta(resp):
    """Extrae los errores que FedEx devuelve en el cuerpo de una respuesta HTTP.

    Devuelve (lista de {code, message}, cuerpo crudo sanitizado y truncado).
    Nunca revienta: si el cuerpo no es JSON, la lista vuelve vacía y queda el
    crudo para el log.
    """
    try:
        crudo = (resp.text or "")[:2000]
    except Exception:
        crudo = ""
    errores = []
    try:
        payload = resp.json()
        brutos = payload.get("errors") or []
        if isinstance(brutos, dict):
            brutos = [brutos]
        for e in brutos:
            if not isinstance(e, dict):
                continue
            errores.append({
                "code":    str(e.get("code") or "").strip(),
                "message": str(e.get("message") or "").strip(),
            })
    except Exception:
        pass
    return errores, _fedex_sanitizar_log(crudo)


def _fedex_mensaje_usuario(errores) -> str:
    """Traduce los errores de FedEx a un texto que el operador pueda accionar.

    Si FedEx explicó algo del dato ingresado (ej. código postal inválido), se
    propaga ESE texto —sanitizado— porque le sirve para corregir. Cualquier otra
    cosa (auth, error interno, servicio caído) sale como mensaje genérico.
    """
    for e in (errores or []):
        code = (e.get("code") or "").upper()
        msg  = (e.get("message") or "").strip()
        if not msg:
            continue
        if any(clave in code for clave in _FEDEX_CODIGOS_UTILES):
            msg = _fedex_sanitizar_log(msg)[:220]
            return f"FedEx rechazó la cotización: {msg}"
    return FEDEX_MSG_GENERICO


def _fedex_calc_rate(peso_pred_kg: float, postal_destino: str,
                     es_residencial: bool = False) -> dict:
    """
    Llama a la FedEx Rate API y devuelve dict con tarifa, tiempo de tránsito, etc.
    Peso facturable = max(peso_pred_kg, 0.5) redondeado a 1 decimal.
    """
    import requests as _req
    token     = _fedex_get_token()
    peso_fact = max(round(peso_pred_kg, 1), 0.5)

    body = {
        "accountNumber": {"value": FEDEX_ACCOUNT},
        "requestedShipment": {
            "shipper": {
                "address": {
                    "city":                FEDEX_ORIGIN_CITY,
                    "postalCode":          FEDEX_ORIGIN_POSTAL,
                    "countryCode":         "CL",
                    "streetLines":         ["Aurora de Chile 2486"],
                    "residential":         False,
                    "stateOrProvinceCode": "",
                }
            },
            "recipient": {
                "address": {
                    "city":                "",
                    "postalCode":          str(postal_destino),
                    "countryCode":         "CL",
                    "streetLines":         [""],
                    "residential":         es_residencial,
                    "stateOrProvinceCode": "",
                }
            },
            "pickupType":      "DROPOFF_AT_FEDEX_LOCATION",
            "packagingType":   "YOUR_PACKAGING",
            "rateRequestType": ["ACCOUNT", "LIST"],
            "requestedPackageLineItems": [{
                "groupPackageCount": 1,
                "physicalPackaging": "YOUR_PACKAGING",
                "weight": {"units": "KG", "value": peso_fact},
            }],
        },
        "carrierCodes":            ["FDXE"],
        "returnLocalizedDateTime": True,
        "webSiteCountryCode":      "CL",
    }

    resp = _req.post(
        FEDEX_RATE_URL,
        json=body,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type":  "application/json",
            "X-locale":      "es_CL",
        },
        timeout=20,
    )
    # Antes acá había un `resp.raise_for_status()` pelado: perdía el cuerpo de la
    # respuesta y dejaba solo "400 Bad Request for url: ...". Ahora se rescata el
    # detalle de FedEx para el log y se levanta un error controlado.
    if resp.status_code >= 400:
        errores, crudo = _fedex_errores_de_respuesta(resp)
        detalle = "; ".join(
            f"{e['code']}: {e['message']}".strip(": ")
            for e in errores if (e["code"] or e["message"])
        )
        print(
            f"[FEDEX] Rate API HTTP {resp.status_code} — "
            f"peso_fact={peso_fact}kg postal_destino={postal_destino} "
            f"residencial={es_residencial} · "
            f"errores=[{_fedex_sanitizar_log(detalle) or 'sin detalle en el cuerpo'}]",
            flush=True,
        )
        if not errores:
            # Cuerpo no-JSON o sin `errors[]`: se loguea crudo (ya sanitizado)
            # porque es la única pista disponible.
            print(f"[FEDEX] Rate API cuerpo crudo: {crudo or '(vacío)'}", flush=True)
        raise FedexRateError(
            f"FedEx Rate HTTP {resp.status_code}: "
            f"{_fedex_sanitizar_log(detalle) or crudo[:300] or 'sin cuerpo'}",
            _fedex_mensaje_usuario(errores),
        )

    data  = resp.json()
    rates = data.get("output", {}).get("rateReplyDetails", [])
    if not rates:
        # Contrato histórico: se devuelve dict con clave "error" (no se levanta
        # excepción) para no romper a quien haga `if "error" in result`.
        print(f"[FEDEX] Rate API 200 sin tarifas — peso_fact={peso_fact}kg "
              f"postal_destino={postal_destino} residencial={es_residencial}",
              flush=True)
        return {"error": "FedEx no devolvió tarifas para este envío. "
                         "Revisa el peso y el destino, o elige otro courier."}

    # Elegir primer rate con detalles
    best = next((r for r in rates if r.get("ratedShipmentDetails")), rates[0])
    rated_details = best.get("ratedShipmentDetails", [{}])
    detail = (
        next((d for d in rated_details if d.get("rateType") == "ACCOUNT"), None)
        or next((d for d in rated_details if d.get("rateType") == "LIST"), None)
        or (rated_details[0] if rated_details else {})
    )

    total  = float(detail.get("totalNetCharge", detail.get("totalNetFedExCharge", 0)))
    moneda = detail.get("currency", "CLP")

    recargos_raw = detail.get("shipmentRateDetail", {}).get("surCharges", [])
    recargos = [
        {"nombre": rc.get("description", rc.get("type", "")), "monto": float(rc.get("amount", 0))}
        for rc in recargos_raw
    ]

    transit_raw = best.get("operationalDetail", {}).get("transitTime", "")
    transit_map = {
        "ONE_DAY":    "1 día hábil",
        "TWO_DAYS":   "2 días hábiles",
        "THREE_DAYS": "3 días hábiles",
        "FOUR_DAYS":  "4 días hábiles",
        "FIVE_DAYS":  "5 días hábiles",
    }

    return {
        "servicio":        best.get("serviceType", "FEDEX_GROUND"),
        "tarifa":          total,
        "moneda":          moneda,
        "tiempo_transito": transit_map.get(transit_raw, transit_raw or "—"),
        "peso_facturable": peso_fact,
        "recargos":        recargos,
    }


# ═══════════════════════════════════════════════════════════════════════════
#  FEDEX TRACK API — credenciales y polling (independiente del Rate API)
# ═══════════════════════════════════════════════════════════════════════════
# FedEx genera credenciales SEPARADAS para Rate y Track. Mismo OAuth flow
# (client_credentials), distinto client_id/secret. Por eso usamos otro cache.
# Setear en Cloud Run → Variables:
#   FEDEX_TRACK_CLIENT_ID, FEDEX_TRACK_CLIENT_SECRET
# (FEDEX_ACCOUNT es el mismo de Rate; ya está definido más arriba).
FEDEX_TRACK_CLIENT_ID     = os.environ.get("FEDEX_TRACK_CLIENT_ID", "").strip()
FEDEX_TRACK_CLIENT_SECRET = os.environ.get("FEDEX_TRACK_CLIENT_SECRET", "").strip()
FEDEX_TRACK_URL           = "https://apis.fedex.com/track/v1/trackingnumbers"

if not (FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET):
    print("[ILUS][FEDEX] Credenciales FedEx Track API NO configuradas — "
          "polling de estados FedEx deshabilitado. Setear FEDEX_TRACK_CLIENT_ID, "
          "FEDEX_TRACK_CLIENT_SECRET en Cloud Run → Variables.", flush=True)

_fedex_track_token_cache = {"token": None, "expires_at": 0}
_fedex_track_token_lock  = threading.Lock()


def _fedex_track_get_token() -> str:
    """OAuth client_credentials para el Track API. Cache 60min."""
    import requests as _req
    if not (FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET):
        raise RuntimeError("FedEx Track API no configurada "
                           "(faltan FEDEX_TRACK_CLIENT_ID/SECRET)")
    with _fedex_track_token_lock:
        now = time.time()
        if (_fedex_track_token_cache["token"]
                and now < _fedex_track_token_cache["expires_at"] - 30):
            return _fedex_track_token_cache["token"]
        resp = _req.post(
            FEDEX_OAUTH_URL,
            data={
                "grant_type":    "client_credentials",
                "client_id":     FEDEX_TRACK_CLIENT_ID,
                "client_secret": FEDEX_TRACK_CLIENT_SECRET,
            },
            timeout=15,
        )
        resp.raise_for_status()
        j = resp.json()
        _fedex_track_token_cache["token"]      = j["access_token"]
        _fedex_track_token_cache["expires_at"] = now + int(j.get("expires_in", 3600))
        return _fedex_track_token_cache["token"]


# Mapping códigos de estado FedEx → ESTADOS_ENTREGA de ILUS.
# Fuente: docs FedEx Track API REST v1 (latestStatusDetail.code / derivedCode).
# NO es exhaustivo (FedEx documenta ~40 códigos cortos); son los que se han
# visto en producción de ILUS. Cualquier código nuevo que aparezca queda
# logueado por _fedex_estado_a_ilus en vez de fallar en silencio, para poder
# ampliar esta tabla con casos reales.
_FEDEX_STATUS_MAP = {
    # Pre-shipment
    "OC": 'Entregado a transporte', # Order Created — etiqueta creada, FedEx lo tiene en su sistema
    "PU": 'Entregado a transporte', # Picked Up
    "AR": 'Entregado a transporte', # Arrived at FedEx location
    "AF": 'Entregado a transporte',# At FedEx facility
    "DP": 'En ruta',               # Departed FedEx location
    # In transit
    "IT": 'En ruta',               # In Transit
    "IX": 'En ruta',               # In transit (intl)
    "OD": 'En ruta',               # Out for Delivery
    "OF": 'En ruta',               # At FedEx Origin Facility
    "OF_DT": 'En ruta',
    # Delivered
    "DL": 'Entregado',
    "POD": 'Entregado',
    # Exceptions / failures
    "DE": 'Entrega fallida',       # Delivery Exception
    "CA": 'Devolución',            # Shipment Canceled
    "RS": 'Devolución',            # Returned to Shipper
    "DY": 'En ruta',               # Delay
    "SE": 'Entrega fallida',       # Shipment Exception
    "HL": 'En ruta',               # Hold at Location
    "CC": 'En ruta',               # Customs / Clearance Delay
}


def _fedex_estado_a_ilus(status_code: str, description: str = "",
                          derived_code: str = "") -> str:
    """Traduce el estado de FedEx (Track API) a uno de ESTADOS_ENTREGA de ILUS.

    FIX 2026-08-07 (bug de locale). La llamada a la Track API manda a propósito
    `X-locale: es_CL` para que `statusByLocale` venga en español y se le pueda
    mostrar tal cual al cliente. El problema: el fallback de esta función
    (cuando el código corto NO está en _FEDEX_STATUS_MAP) comparaba esa
    descripción contra palabras en INGLÉS. Con el locale en español esas
    comparaciones nunca hacían match, así que cualquier código de FedEx que
    ILUS todavía no conociera caía SIEMPRE en el default 'En ruta' — en
    silencio. Un rechazo o una excepción no catalogada se leía como "va en
    camino" y el cliente recibía el correo equivocado.

    Fuentes de verdad, en orden:
      1. `status_code` (latestStatusDetail.code) — estable, no depende del locale.
      2. `derived_code` (latestStatusDetail.derivedCode) — otro código corto,
         también locale-independiente; se traía del payload pero nunca se
         usaba para clasificar, solo para el texto mostrado.
      3. Recién ahí, el texto libre — en español (lo que de verdad llega con
         es_CL) y en inglés (compatibilidad).

    ORDEN DE LAS COMPROBACIONES DE TEXTO (importante): los fallos se evalúan
    ANTES que "entregado". Una descripción como "No entregado - destinatario
    ausente" contiene la palabra "entregado": preguntando primero por ella, un
    envío FALLIDO se marcaría como Entregado y le saldría al cliente el correo
    de "tu pedido llegó". Es el error más caro de los dos, así que gana el fallo.

    Si nada permite clasificar, se loguea el código desconocido antes de caer
    al default (antes esto era 100% silencioso).
    """
    sc = (status_code or "").strip().upper()
    if sc in _FEDEX_STATUS_MAP:
        return _FEDEX_STATUS_MAP[sc]
    dc = (derived_code or "").strip().upper()
    if dc in _FEDEX_STATUS_MAP:
        return _FEDEX_STATUS_MAP[dc]

    desc = (description or "").lower()

    # ── 1) FALLOS PRIMERO (ver nota de orden en el docstring) ──
    if ("excepción" in desc or "excepcion" in desc or "rechaz" in desc
            or "no se pudo entregar" in desc or "no entregado" in desc
            or "domicilio cerrado" in desc or "negocio cerrado" in desc
            or "destinatario no disponible" in desc or "destinatario ausente" in desc
            or "exception" in desc or "delivery refused" in desc
            or "undeliverable" in desc or "not delivered" in desc):
        return 'Entrega fallida'

    # ── 2) Entregado ──
    if "entregado" in desc or "delivered" in desc:
        return 'Entregado'

    # ── 3) En ruta ──
    if ("en tránsito" in desc or "en transito" in desc or "salió de" in desc
            or "salio de" in desc or "llegó a" in desc or "llego a" in desc
            or "en reparto" in desc or "en camino" in desc
            or "vehículo de fedex" in desc or "vehiculo de fedex" in desc
            or "in transit" in desc or "departed" in desc or "arrived" in desc
            or "out for delivery" in desc or "on fedex vehicle" in desc):
        return 'En ruta'

    # ── 4) Ya lo tiene el transportista ──
    if ("recolectado" in desc or "recogido" in desc
            or "en posesión de fedex" in desc or "en posesion de fedex" in desc
            or "etiqueta creada" in desc or "información de envío" in desc
            or "informacion de envio" in desc
            or "picked up" in desc or "in fedex possession" in desc
            or "label created" in desc or "shipment information" in desc):
        return 'Entregado a transporte'

    if sc or dc:
        print(f"[fedex][estado] código FedEx sin mapear en _FEDEX_STATUS_MAP: "
              f"code={sc!r} derivedCode={dc!r} desc={(description or '')[:100]!r} "
              f"— usando default 'En ruta', revisar y ampliar el mapa",
              flush=True)
    return 'En ruta'   # default seguro: si FedEx tiene algo, está moviéndose


# ═══════════════════════════════════════════════════════════════════════════
#  FEDEX SHIP API + PICKUP API — crear envíos, etiquetas y retiros
# ═══════════════════════════════════════════════════════════════════════════
# Endpoint y servicios FedEx para Chile doméstico (intra-country).
FEDEX_SHIP_URL          = "https://apis.fedex.com/ship/v1/shipments"
FEDEX_SHIP_CANCEL_URL   = "https://apis.fedex.com/ship/v1/shipments/cancel"
FEDEX_PICKUP_AVAIL_URL  = "https://apis.fedex.com/pickup/v1/pickups/availabilities"
FEDEX_PICKUP_CREATE_URL = "https://apis.fedex.com/pickup/v1/pickups"
FEDEX_PICKUP_CANCEL_URL = "https://apis.fedex.com/pickup/v1/pickups/cancel"

# Servicio doméstico CL recomendado por FedEx CL para envíos intra-country.
FEDEX_DEFAULT_SERVICE_CL = "FEDEX_PRIORITY"


def _fedex_postal_cl(postal_code) -> str:
    """FedEx CL Ship/Pickup espera código postal chileno de 7 dígitos.
    Acepta None, strings con guiones o espacios — extrae solo dígitos. Si entran
    menos de 7 dígitos (formato viejo de 4), los rellena a la derecha con ceros
    para acercarse al formato actual (ej. "9276" → "9276000"). Devuelve "" si
    no hay nada o si el valor es "0000…" (FedEx rechaza códigos compuestos solo
    por ceros como inválidos).
    """
    s = "".join(c for c in str(postal_code or "") if c.isdigit())
    if not s or set(s) == {"0"}:
        return ""
    return (s + "0000000")[:7]


def _fedex_clean_str(s, max_len=None) -> str:
    """Limpia un string para enviar a FedEx (sin saltos de línea, recorta).
    FedEx rechaza strings con \\n/\\r y limita la mayoría a 35-60 chars.
    """
    if s is None:
        return ""
    out = str(s).replace("\n", " ").replace("\r", " ").strip()
    while "  " in out:
        out = out.replace("  ", " ")
    if max_len and len(out) > max_len:
        out = out[:max_len].rstrip()
    return out


def _fedex_split_address(direccion: str, max_per_line: int = 35):
    """Divide una dirección larga en hasta 2 líneas para streetLines de FedEx.
    FedEx limita cada línea a 35 chars. Si entra en una sola, devuelve [str].
    FedEx rechaza streetLines con cadenas vacías — si no hay dirección, devuelve
    ["Sin dirección"] como placeholder (FedEx CL acepta esto para domestic).
    """
    d = _fedex_clean_str(direccion)
    if not d:
        return ["Sin direccion"]
    if len(d) <= max_per_line:
        return [d]
    # Partir por la última coma/espacio antes del límite
    cut = d[:max_per_line].rfind(",")
    if cut < 10:
        cut = d[:max_per_line].rfind(" ")
    if cut < 10:
        cut = max_per_line
    line1 = d[:cut].strip(" ,")
    line2 = _fedex_clean_str(d[cut:].strip(" ,"), max_per_line)
    return [line1, line2] if line2 else [line1]


# Parser de etiquetas FedEx extraído a módulo aislado y testeable
# (tests/test_fedex_parse.py). Wrappers delgados para no romper los callers.
def _fedex_label_from_doc(doc):
    return _fxlabels.label_from_doc(doc)


def _fedex_parse_ship_response(data, label_format="PDF", expected_pieces=0):
    """Delegado a fedex_labels.parse_ship_response (función pura, ver módulo)."""
    return _fxlabels.parse_ship_response(
        data, label_format=label_format, expected_pieces=expected_pieces)


def _fedex_create_shipment(
    *,
    recipient: dict,
    packages: list,
    reference: str = "",
    ship_date: str = None,
    service_type: str = None,
    label_format: str = "PDF",         # PDF | ZPLII | EPL2 | PNG
    label_stock: str = "STOCK_4X6",    # STOCK_4X6 = térmica 100x150mm pura | PAPER_4X6 = hoja con marco
    notify_email: str = "",
    notify_name: str = "",
    pickup_type: str = "USE_SCHEDULED_PICKUP",
    # Auto-fallback a OTs individuales si FedEx solo devuelve 1 etiqueta para
    # >1 bultos (FedEx CL doméstico a veces no entrega las N etiquetas en MPS,
    # ni como N PDFs separados ni como PDF multipágina). En ese caso cancela
    # la MPS recién creada y hace N llamadas con 1 paquete c/u para garantizar
    # que las N etiquetas (1/N, 2/N, …, N/N) realmente bajen.
    auto_fallback_individual: bool = True,
) -> dict:
    """Crea un envío FedEx y devuelve tracking number + etiqueta en base64.

    Args:
        recipient: dict con keys: nombre, empresa, telefono, email, direccion,
                   comuna, region, cod_postal.
        packages:  list[dict] con keys: peso_kg, largo, ancho, alto, valor,
                   referencia (str opcional).
        reference: Customer reference (factura ILUS, ej. "FAC 12345").
        ship_date: 'YYYY-MM-DD' (default: hoy).
        service_type: FEDEX_PRIORITY | FEDEX_GROUND | FIRST_OVERNIGHT (default CL).
        label_format: PDF (default), ZPLII para Zebra térmica.
        notify_email/notify_name: si presentes, FedEx manda notificaciones al
                                  destinatario en cada hito.
        pickup_type: USE_SCHEDULED_PICKUP (Alison agenda retiro) |
                     DROPOFF_AT_FEDEX_LOCATION (se lleva a sucursal).

    Returns:
        dict {
            ok: True/False,
            master_tracking_number: str (TN principal),
            piece_trackings: [str, ...] (TN por bulto),
            label_b64: str (etiqueta master en base64),
            piece_labels: [{tn, label_b64}, ...] (por bulto si multi-bulto),
            shipment_id: str (transactionId de FedEx),
            raw: dict (respuesta cruda para debug),
            error: str (si ok=False),
            error_code: str (código FedEx si lo hay),
        }
    """
    import requests as _req
    _missing = [v for v, k in [("FEDEX_RATE_CLIENT_ID", FEDEX_RATE_CLIENT_ID),
                                ("FEDEX_RATE_CLIENT_SECRET", FEDEX_RATE_CLIENT_SECRET),
                                ("FEDEX_ACCOUNT", FEDEX_ACCOUNT)] if not k]
    if _missing:
        return {"ok": False, "error": f"FedEx Ship API no configurada — faltan variables de entorno: {', '.join(_missing)}"}
    if not recipient or not isinstance(recipient, dict):
        return {"ok": False, "error": "recipient es obligatorio"}
    if not packages or not isinstance(packages, list):
        return {"ok": False, "error": "packages es obligatorio"}

    import datetime as _dt
    ship_date = ship_date or _dt.date.today().strftime("%Y-%m-%d")
    service_type = service_type or FEDEX_DEFAULT_SERVICE_CL
    token = _fedex_get_token()

    rec_nombre   = _fedex_clean_str(recipient.get("nombre"), 70) or "Cliente"
    rec_empresa  = _fedex_clean_str(recipient.get("empresa"), 70) or rec_nombre
    # FedEx CL domestic requiere dígitos solamente (7-15 chars), sin "+" ni espacios.
    rec_tel      = "".join(c for c in str(recipient.get("telefono") or "") if c.isdigit())
    if not rec_tel or rec_tel == "0":
        # Sin teléfono: usar el de bodega ILUS como fallback (FedEx requiere ≥7 dígitos)
        rec_tel = "".join(c for c in str(ILUS_REMITENTE.get("telefono") or "562294659700") if c.isdigit())
    elif len(rec_tel) < 7:
        # Agregar prefijo país sin "+" — ej: 9XXXXXXXX → 569XXXXXXXX
        rec_tel = "56" + rec_tel.lstrip("0") or "562294659700"
    # FedEx exige máximo 15 dígitos
    rec_tel = rec_tel[:15]
    rec_email    = _fedex_clean_str(recipient.get("email"), 80)
    rec_dir      = _fedex_split_address(recipient.get("direccion"))
    rec_comuna_raw = (recipient.get("comuna") or "").strip()
    # Si llegó un código (2-4 chars), resolver contra TABCM del ERP.
    if 2 <= len(rec_comuna_raw) <= 4:
        try:
            resolved = _resolve_comuna_erp(rec_comuna_raw) or ""
            # Si _resolve_comuna_erp devolvió lo mismo que entró (no encontró
            # match en TABCM), intentamos con la tabla externa de Chile
            # (cl_codigos_postales) que conoce 481 comunas.
            if (not resolved or resolved.upper() == rec_comuna_raw.upper()):
                try:
                    cand = _cl_resolve_short_code(rec_comuna_raw,
                                                  region_hint=recipient.get("region"))
                    if cand:
                        resolved = cand
                except Exception:
                    pass
            if resolved:
                rec_comuna_raw = resolved
        except Exception:
            pass
    rec_comuna   = _fedex_clean_str(rec_comuna_raw, 35) or "Santiago"
    # Código postal de destino: primero el que viene en el recipient; si está
    # vacío o inválido, caer al mapping comuna → CP de Chile. Cadena de fallbacks:
    #   1) recipient.cod_postal (lo más confiable si vino del cliente)
    #   2) tabla oficial _codigo_postal_chile (planilla FedEx 2025, 481 comunas)
    #   3) dict hardcoded _comuna_to_postal (38 comunas grandes) — último recurso
    # FedEx CL rechaza el envío con "código postal no válido para el país" si no
    # llega un CP de 7 dígitos coherente con CL.
    #
    # 2026-08-13 (bug real, FCV 11275/Paine): estos dos pasos estaban al revés.
    # _comuna_to_postal es un dict viejo tipeado a mano con 56 comunas; al
    # comparar contra la planilla oficial FedEx 2025 (cl_codigos_postales.py,
    # 481 comunas) 34 de esas 56 tienen el código MAL — incluida Paine
    # (9680000 vs el oficial 9540000) y hasta Santiago mismo. Como este paso
    # corría primero, el código incorrecto ganaba siempre para esas 34 comunas
    # y la tabla oficial nunca llegaba a intervenir. FedEx rechazaba el envío
    # con "código postal no válido para el país" porque 9680000 no es un CP
    # real de Chile para FedEx.
    rec_postal   = _fedex_postal_cl(recipient.get("cod_postal"))
    if not rec_postal:
        try:
            cp_ext = _codigo_postal_chile(rec_comuna)
            if cp_ext:
                rec_postal = _fedex_postal_cl(cp_ext)
        except Exception:
            pass
    if not rec_postal:
        # Último recurso: dict viejo, solo si la tabla oficial no conoce la comuna.
        rec_postal = _fedex_postal_cl(_comuna_to_postal(rec_comuna))

    shipper_dir = _fedex_split_address(ILUS_REMITENTE.get("bodega") or ILUS_REMITENTE["direccion"])

    # Armar requestedPackageLineItems
    rpl = []
    for idx, pkg in enumerate(packages, start=1):
        peso = max(round(float(pkg.get("peso_kg") or 0), 1), 0.5)
        largo = max(int(round(float(pkg.get("largo") or 10))), 1)
        ancho = max(int(round(float(pkg.get("ancho") or 10))), 1)
        alto  = max(int(round(float(pkg.get("alto")  or 10))), 1)
        valor = float(pkg.get("valor") or 0)
        item = {
            # MPS: cada bulto es un paquete distinto. sequenceNumber 1-based +
            # groupPackageCount=1 + totalPackageCount (abajo) son OBLIGATORIOS
            # para que FedEx devuelva la etiqueta de CADA pieza (no solo la master).
            "sequenceNumber":    idx,
            "groupPackageCount": 1,
            "itemDescriptionForClearance": _fedex_clean_str(pkg.get("descripcion") or reference or "Mercaderia", 50),
            "weight":     {"units": "KG", "value": peso},
            "dimensions": {"length": largo, "width": ancho, "height": alto, "units": "CM"},
        }
        # Valor declarado (seguro): OPCIONAL. Se incluye sólo si se configuró
        # una moneda aceptada por la cuenta (FEDEX_DECLARED_CURRENCY). Si no, se
        # omite para evitar el rechazo "El tipo de moneda no es válido" que
        # bloquea la creación de la OT en Chile doméstico.
        if FEDEX_DECLARED_CURRENCY and valor > 0:
            item["declaredValue"] = {"amount": f"{valor:.2f}", "currency": FEDEX_DECLARED_CURRENCY}
        if reference:
            item["customerReferences"] = [
                {"customerReferenceType": "CUSTOMER_REFERENCE", "value": _fedex_clean_str(reference, 30)},
                {"customerReferenceType": "INVOICE_NUMBER",     "value": _fedex_clean_str(reference, 30)},
            ]
        rpl.append(item)

    body = {
        "labelResponseOptions": "LABEL",
        "accountNumber": {"value": FEDEX_ACCOUNT},
        "requestedShipment": {
            "shipper": {
                "contact": {
                    "personName":  _fedex_clean_str(ILUS_REMITENTE["nombre"], 35),
                    # FedEx CL: dígitos solamente, sin "+" (ej. 56229465970)
                    "phoneNumber": "".join(c for c in str(ILUS_REMITENTE["telefono"]) if c.isdigit()),
                    "companyName": _fedex_clean_str(ILUS_REMITENTE["nombre"], 35),
                },
                "address": {
                    "streetLines": shipper_dir,
                    "city":        "Quilicura",
                    # Chile doméstico: stateOrProvinceCode debe omitirse o quedar vacío.
                    # Usar "CL" (código de país) causa rechazo en Ship API.
                    "postalCode":  _fedex_postal_cl(FEDEX_ORIGIN_POSTAL),
                    "countryCode": "CL",
                },
            },
            "recipients": [{
                "contact": {
                    "personName":   rec_nombre,
                    "phoneNumber":  rec_tel,
                    "companyName":  rec_empresa,
                    **({"emailAddress": rec_email} if rec_email else {}),
                },
                "address": {
                    "streetLines": rec_dir,
                    "city":        rec_comuna,
                    # Chile doméstico: stateOrProvinceCode debe omitirse o quedar vacío.
                    "countryCode": "CL",
                    **({"postalCode": rec_postal} if rec_postal else {}),
                },
            }],
            "shipDatestamp":    ship_date,
            "serviceType":      service_type,
            "packagingType":    "YOUR_PACKAGING",
            "pickupType":       pickup_type,
            "blockInsightVisibility": False,
            "shippingChargesPayment": {"paymentType": "SENDER"},
            # MPS: total de paquetes del envío. Sin esto FedEx trata el request
            # como mono-bulto y solo devuelve la etiqueta master ("1 of N").
            "totalPackageCount": len(rpl),
            "labelSpecification": {
                "imageType":     label_format,
                "labelStockType": label_stock,
            },
            "requestedPackageLineItems": rpl,
        },
    }

    # Notificación al destinatario (si dio email)
    if notify_email:
        body["requestedShipment"]["emailNotificationDetail"] = {
            "aggregationType": "PER_PACKAGE",
            "emailNotificationRecipients": [{
                "name":                           _fedex_clean_str(notify_name or rec_nombre, 50),
                "emailNotificationRecipientType": "RECIPIENT",
                "emailAddress":                   notify_email,
                "notificationFormatType":         "HTML",
                "notificationType":               "EMAIL",
                "locale":                         "es_CL",
                "notificationEventType": [
                    "ON_SHIPMENT", "ON_TENDER", "ON_DELIVERY", "ON_EXCEPTION",
                ],
            }],
        }

    try:
        resp = _req.post(
            FEDEX_SHIP_URL, json=body,
            headers={
                "Authorization":  f"Bearer {token}",
                "Content-Type":   "application/json",
                "X-locale":       "es_CL",
            }, timeout=30,
        )
    except Exception as e_net:
        return {"ok": False, "error": f"Red FedEx: {str(e_net)[:140]}"}

    try:
        data = resp.json()
    except Exception:
        return {"ok": False, "error": f"FedEx no devolvió JSON (HTTP {resp.status_code})"}

    if resp.status_code >= 400:
        errs = data.get("errors") or []
        msg = "; ".join(e.get("message", "") for e in errs if e.get("message"))[:280]
        return {
            "ok": False,
            "error": msg or f"FedEx HTTP {resp.status_code}",
            "error_code": (errs[0].get("code") if errs else None),
            "raw": data,
        }

    parsed = _fedex_parse_ship_response(data, label_format=label_format,
                                        expected_pieces=len(packages))
    if not parsed.get("ok"):
        return {"ok": False, "error": parsed.get("error") or "FedEx no devolvió etiquetas",
                "raw": data}
    master_tn        = parsed["master_tracking_number"]
    piece_trackings  = parsed["piece_trackings"]
    piece_labels     = parsed["piece_labels"]
    master_label_b64 = parsed["master_label_b64"]
    debug            = parsed["debug"]

    # ── Auto-fallback CRÍTICO: MPS sin todas las etiquetas → N OTs individuales
    # Si FedEx CL doméstico devolvió menos etiquetas que bultos (típicamente 1
    # etiqueta para N), cancelamos esta MPS y hacemos N llamadas con 1 paquete
    # cada una. Cada llamada SÍ devuelve su etiqueta (es un mono-bulto), así que
    # el resultado final es N TNs + N etiquetas (1/N, 2/N, ..., N/N).
    # auto_fallback_individual=False evita recursión cuando entramos desde
    # _fedex_create_individual_pieces.
    n_packages = len(packages)
    if (auto_fallback_individual and n_packages > 1
            and len(piece_labels) < n_packages):
        try:
            print(f"[FEDEX FALLBACK] MPS entregó {len(piece_labels)} etiquetas "
                  f"para {n_packages} bultos — disparando OTs individuales", flush=True)
        except Exception:
            pass
        # Cancelar la MPS mal armada para evitar cargo duplicado.
        try:
            _fedex_cancel_shipment(master_tn)
        except Exception as e_cancel:
            try:
                print(f"[FEDEX FALLBACK] no se pudo cancelar MPS {master_tn}: "
                      f"{type(e_cancel).__name__}", flush=True)
            except Exception:
                pass
        ind_res = _fedex_create_individual_pieces(
            recipient=recipient,
            packages=packages,
            reference=reference,
            ship_date=ship_date,
            service_type=service_type,
            label_format=label_format,
            label_stock=label_stock,
            notify_email=notify_email,
            notify_name=notify_name,
            pickup_type=pickup_type,
        )
        # Si el fallback funcionó (al menos 1 OT individual creada), devolvemos
        # eso. Si falló totalmente, devolvemos el resultado MPS original con
        # warning para que el operador re-emita manualmente.
        if ind_res.get("ok"):
            ind_res["_fallback_from_mps"] = {
                "original_master_tn": master_tn,
                "mps_labels":         len(piece_labels),
                "mps_pieces":         n_packages,
            }
            return ind_res
        # Si el fallback falló, dejamos el MPS original (con 1 etiqueta) para
        # que al menos algo se vea, pero marcamos el debug.
        debug["fallback_individual_error"] = ind_res.get("error", "")[:160]

    return {
        "ok":                       True,
        "master_tracking_number":   master_tn,
        "piece_trackings":          piece_trackings,
        "label_b64":                master_label_b64,
        "piece_labels":             piece_labels,
        "shipment_id":              data.get("transactionId") or "",
        "service_type":             service_type,
        "label_format":             label_format,
        "_debug":                   debug,
    }


def _fedex_create_individual_pieces(
    *,
    recipient: dict,
    packages: list,
    reference: str = "",
    ship_date: str = None,
    service_type: str = None,
    label_format: str = "PDF",
    label_stock: str = "STOCK_4X6",
    notify_email: str = "",
    notify_name: str = "",
    pickup_type: str = "USE_SCHEDULED_PICKUP",
) -> dict:
    """Crea N OTs FedEx SEPARADAS, una por bulto (1 paquete cada llamada).

    Modo de operación cuando FedEx CL no entrega las N etiquetas en MPS.
    Cada bulto se transforma en un envío independiente con SU propio tracking
    y SU propia etiqueta — el cliente recibe N etiquetas con N TNs y FedEx
    los procesa por separado. Resultado combinado para que el caller (que
    espera el formato MPS) no necesite saber qué pasó por debajo:
        master_tracking_number = primer TN
        piece_trackings        = [TN1, TN2, ..., TNn]
        piece_labels           = [{tracking_number, label_b64}, ...]
        _mode                  = "individual"

    Costo: 1 llamada por bulto (N llamadas FedEx). Cada una tiene su tarifa
    base. Es MÁS caro que un MPS verdadero, pero garantiza las etiquetas.
    """
    if not packages:
        return {"ok": False, "error": "packages vacío"}
    all_pieces  = []   # tracking numbers
    all_labels  = []   # [{tracking_number, label_b64}, ...]
    raw_labels  = []   # [label_b64, ...] (para debug / si pides el master)
    errors      = []
    n_tot = len(packages)
    for idx, pkg in enumerate(packages, start=1):
        # Referencia por bulto: "FCV 12345 1/3"
        ref_i = (reference or "").strip()
        if ref_i:
            ref_i = f"{ref_i} {idx}/{n_tot}"
        # OJO: notificación por email solo en la 1ª pieza (evita N emails al
        # cliente).
        ne = notify_email if idx == 1 else ""
        nn = notify_name  if idx == 1 else ""
        res_i = _fedex_create_shipment(
            recipient=recipient,
            packages=[pkg],
            reference=ref_i,
            ship_date=ship_date,
            service_type=service_type,
            label_format=label_format,
            label_stock=label_stock,
            notify_email=ne,
            notify_name=nn,
            pickup_type=pickup_type,
            auto_fallback_individual=False,   # crítico: evita recursión
        )
        if not res_i.get("ok"):
            errors.append({
                "bulto": f"{idx}/{n_tot}",
                "error": (res_i.get("error") or "")[:140],
            })
            continue
        tn_i = res_i.get("master_tracking_number") or ""
        if not tn_i:
            errors.append({"bulto": f"{idx}/{n_tot}",
                           "error": "FedEx no devolvió tracking number"})
            continue
        all_pieces.append(tn_i)
        # Etiqueta: preferir piece_labels[0], si no, el master_label_b64.
        pl = res_i.get("piece_labels") or []
        b64_i = ""
        if pl and pl[0].get("label_b64"):
            b64_i = pl[0]["label_b64"]
        elif res_i.get("label_b64"):
            b64_i = res_i["label_b64"]
        if b64_i:
            all_labels.append({"tracking_number": tn_i, "label_b64": b64_i})
            raw_labels.append(b64_i)
    if not all_pieces:
        # Todos fallaron — devolver el primer error como mensaje.
        first_err = (errors[0]["error"] if errors else "FedEx no creó ningún envío")
        return {"ok": False, "error": first_err, "_errors_individual": errors}
    return {
        "ok":                       True,
        "master_tracking_number":   all_pieces[0],
        "piece_trackings":          all_pieces,
        "label_b64":                raw_labels[0] if raw_labels else "",
        "piece_labels":             all_labels,
        "shipment_id":              "",
        "service_type":             service_type or "",
        "label_format":             label_format,
        "_mode":                    "individual",
        "_n_requested":             n_tot,
        "_n_succeeded":             len(all_pieces),
        "_errors_individual":       errors,
    }


def _fedex_cancel_shipment(tracking_number: str) -> dict:
    """Cancela un envío FedEx (mismo día) por tracking number.

    Returns: {ok: bool, cancelled: bool, error?: str}
    """
    import requests as _req
    if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET and FEDEX_ACCOUNT):
        return {"ok": False, "error": "FedEx Ship API no configurada"}
    tn = "".join(c for c in str(tracking_number or "") if c.isalnum())
    if not tn:
        return {"ok": False, "error": "tracking_number requerido"}
    token = _fedex_get_token()
    try:
        resp = _req.put(
            FEDEX_SHIP_CANCEL_URL,
            json={
                "accountNumber":     {"value": FEDEX_ACCOUNT},
                "senderCountryCode": "CL",
                "deletionControl":   "DELETE_ALL_PACKAGES",
                "trackingNumber":    tn,
            },
            headers={
                "Authorization":  f"Bearer {token}",
                "Content-Type":   "application/json",
                "X-locale":       "es_CL",
            }, timeout=20,
        )
    except Exception as e_net:
        return {"ok": False, "error": f"Red FedEx: {str(e_net)[:140]}"}
    try:
        data = resp.json()
    except Exception:
        return {"ok": False, "error": f"FedEx no devolvió JSON (HTTP {resp.status_code})"}
    if resp.status_code >= 400:
        errs = data.get("errors") or []
        msg = "; ".join(e.get("message", "") for e in errs if e.get("message"))[:280]
        return {"ok": False, "error": msg or f"FedEx HTTP {resp.status_code}", "raw": data}
    return {
        "ok":         True,
        "cancelled":  (data.get("output", {}) or {}).get("cancelledShipment", True),
        "raw":        data,
    }


def _fedex_cancel_window(ship_created_at):
    """Ventana de cancelación de una OT FedEx (Fase 3 cronómetro).

    Regla: FedEx permite cancelar el MISMO día calendario en Chile en que se
    creó la OT, hasta las 16:00 hora Chile (corte operativo de Quilicura).
    Después de esa hora el envío entra a la red y debe gestionarse manualmente.

    Args:
        ship_created_at: datetime de creación (naive UTC desde MySQL NOW()
        o aware en cualquier zona).

    Returns:
        dict {deadline_iso, deadline_ms, expired, seconds_left} o None si
        no hay fecha de creación.
    """
    if not ship_created_at:
        return None
    try:
        from datetime import time as _time, timezone as _tz_utc
        ts = ship_created_at
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=_tz_utc.utc)
        ship_cl = ts.astimezone(_TZ_CL)
        deadline_cl = datetime.combine(ship_cl.date(), _time(16, 0), tzinfo=_TZ_CL)
        now_cl = _now_chile()
        seconds_left = int((deadline_cl - now_cl).total_seconds())
        return {
            "deadline_iso": deadline_cl.isoformat(),
            "deadline_ms":  int(deadline_cl.timestamp() * 1000),
            "expired":      seconds_left <= 0,
            "seconds_left": seconds_left,
        }
    except Exception as e:
        print(f"[fedex_cancel_window] error: {e}", flush=True)
        return None


def _fedex_pickup_check(
    *,
    address: dict,
    dispatch_date: str,
    ready_time: str = "09:00:00",
    close_time: str = "18:00:00",
    weight_kg: float = 1.0,
    dims: dict = None,
) -> dict:
    """Consulta horarios disponibles para retiro FedEx en Chile.

    Args:
        address: dict {direccion, comuna, cod_postal}
        dispatch_date: 'YYYY-MM-DD'
        ready_time/close_time: 'HH:MM:SS'

    Returns: {ok, options: [{type, cutoff, ready_window}], raw}
    """
    import requests as _req
    if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET and FEDEX_ACCOUNT):
        return {"ok": False, "error": "FedEx Pickup API no configurada"}
    token = _fedex_get_token()
    dims = dims or {"length": 10, "width": 10, "height": 10, "units": "CM"}
    body = {
        "pickupAddress": {
            "streetLines":         _fedex_split_address(address.get("direccion")),
            "city":                _fedex_clean_str(address.get("comuna"), 35) or "Quilicura",
            "stateOrProvinceCode": "CL",
            "postalCode":          _fedex_postal_cl(address.get("cod_postal")),
            "countryCode":         "CL",
        },
        "dispatchDate":      dispatch_date,
        "packageReadyTime":  ready_time,
        "customerCloseTime": close_time,
        "pickupRequestType": ["SAME_DAY", "FUTURE_DAY"],
        "shipmentAttributes": {
            "serviceType":     FEDEX_DEFAULT_SERVICE_CL,
            "weight":          {"units": "KG", "value": max(float(weight_kg or 1.0), 0.5)},
            "packagingType":   "YOUR_PACKAGING",
            "dimensions":      dims,
        },
        "numberOfBusinessDays":   1,
        "packageDetails":         [{"packageSpecialServices": {"specialServiceTypes": ["SIGNATURE_OPTION"]}}],
        "associatedAccountNumber": FEDEX_ACCOUNT,
        "carriers":              ["FDXE"],
        "countryRelationship":    "DOMESTIC",
    }
    try:
        resp = _req.post(FEDEX_PICKUP_AVAIL_URL, json=body,
                         headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                         timeout=20)
        data = resp.json()
    except Exception as e_net:
        return {"ok": False, "error": f"FedEx Pickup: {str(e_net)[:140]}"}
    if resp.status_code >= 400:
        errs = data.get("errors") or []
        msg = "; ".join(e.get("message", "") for e in errs if e.get("message"))[:280]
        return {"ok": False, "error": msg or f"FedEx HTTP {resp.status_code}", "raw": data}
    out = (data.get("output", {}) or {})
    opts = out.get("options") or out.get("availableOptions") or []
    return {"ok": True, "options": opts, "raw": data}


def _fedex_pickup_create(
    *,
    contact: dict,
    address: dict,
    ready_dt: str,           # 'YYYY-MM-DDTHH:MM:SS'
    close_time: str = "18:00:00",
    package_count: int = 1,
    total_weight_kg: float = 1.0,
    dims: dict = None,
    notify_email: str = "",
    delivery_instructions: str = "",
) -> dict:
    """Crea una solicitud de retiro FedEx.

    Returns: {ok, pickup_confirmation_code, location, scheduled_date, raw}
    """
    import requests as _req
    if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET and FEDEX_ACCOUNT):
        return {"ok": False, "error": "FedEx Pickup API no configurada"}
    token = _fedex_get_token()
    dims = dims or {"length": 30, "width": 30, "height": 30, "units": "CM"}
    body = {
        "associatedAccountNumber": {"value": FEDEX_ACCOUNT},
        "originDetail": {
            "pickupLocation": {
                "contact": {
                    "companyName": _fedex_clean_str(contact.get("empresa") or ILUS_REMITENTE["nombre"], 35),
                    "personName":  _fedex_clean_str(contact.get("nombre")  or "Despacho", 35),
                    "phoneNumber": _fedex_clean_str(contact.get("telefono") or ILUS_REMITENTE["telefono"], 15),
                },
                "address": {
                    "streetLines":         _fedex_split_address(address.get("direccion") or ILUS_REMITENTE["bodega"]),
                    "city":                _fedex_clean_str(address.get("comuna") or "Quilicura", 35),
                    "stateOrProvinceCode": "CL",
                    "postalCode":          _fedex_postal_cl(address.get("cod_postal") or FEDEX_ORIGIN_POSTAL),
                    "countryCode":         "CL",
                },
                "deliveryInstructions": _fedex_clean_str(delivery_instructions, 80),
            },
            "readyDateTimestamp": ready_dt,
            "customerCloseTime":  close_time,
        },
        "totalWeight":  {"units": "KG", "value": max(float(total_weight_kg or 1.0), 0.5)},
        "dimensions":   dims,
        "carrierCode":  "FDXE",
        "packageCount": int(package_count or 1),
        "accountAddressOfRecord": {
            "streetLines": _fedex_split_address(ILUS_REMITENTE["bodega"]),
        },
    }
    if notify_email:
        body["pickupNotificationDetail"] = {
            "emailDetails": [{"address": notify_email, "locale": "es_CL"}],
            "format":       "HTML",
            "userMessage":  "Retiro solicitado desde ILUS Fitness",
        }
    try:
        resp = _req.post(FEDEX_PICKUP_CREATE_URL, json=body,
                         headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                         timeout=25)
        data = resp.json()
    except Exception as e_net:
        return {"ok": False, "error": f"FedEx Pickup: {str(e_net)[:140]}"}
    if resp.status_code >= 400:
        errs = data.get("errors") or []
        msg = "; ".join(e.get("message", "") for e in errs if e.get("message"))[:280]
        return {"ok": False, "error": msg or f"FedEx HTTP {resp.status_code}", "raw": data}
    out = (data.get("output", {}) or {})
    return {
        "ok":                       True,
        "pickup_confirmation_code": out.get("pickupConfirmationCode") or "",
        "location":                 out.get("location") or "",
        "scheduled_date":           out.get("scheduledDate") or "",
        "raw":                      data,
    }


