def _comuna_to_postal(comuna: str):
    """Convierte nombre de comuna a código postal CL. Devuelve None si no se conoce."""
    if not comuna:
        return None
    key = (comuna.strip().upper()
           .replace("Ñ","N").replace("Á","A").replace("É","E")
           .replace("Í","I").replace("Ó","O").replace("Ú","U"))
    return _COMUNA_POSTAL.get(key)


@app.route("/asignar", methods=["GET"])
@login_required
def asignar_cotizar():
    """Página principal del módulo Asignar y Cotizar.

    Forzamos headers anti-caché para que el navegador NUNCA sirva una
    versión vieja del HTML. Crítico porque este template es el que más
    JavaScript inline tiene y donde más sufrimos por caché del usuario.
    """
    if not g.permissions.get("cubicador"):
        flash("No tienes acceso al módulo Asignar y Cotizar.", "danger")
        return redirect(url_for("index"))
    resp = make_response(render_template("cubicador/asignar.html"))
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


# ── Cache server-side del cubicador ERP ──────────────────────────────────────
# Memoria por worker (gunicorn). TTL corto (5 min) — los documentos del ERP
# no cambian con frecuencia y el operador típicamente busca el mismo doc
# varias veces seguidas (cubicar, ajustar, agregar al manifiesto).
# Reduce búsqueda repetida de ~3-4s a <50ms.
_CUB_DOC_CACHE = {}       # key=f"{tido}|{nudo}" → (epoch_expires, hdr, lineas)
_CUB_DOC_CACHE_TTL = 300  # 5 min
_CUB_DOC_CACHE_MAX = 200  # evicción FIFO simple si crece de más

def _cub_doc_cache_get(key):
    import time as _t
    row = _CUB_DOC_CACHE.get(key)
    if not row:
        return None
    exp, hdr, lineas = row
    if exp < _t.time():
        _CUB_DOC_CACHE.pop(key, None)
        return None
    return hdr, lineas

def _cub_doc_cache_put(key, hdr, lineas):
    import time as _t
    if len(_CUB_DOC_CACHE) >= _CUB_DOC_CACHE_MAX:
        # Eviccionar el más viejo
        try:
            oldest = min(_CUB_DOC_CACHE.items(), key=lambda kv: kv[1][0])[0]
            _CUB_DOC_CACHE.pop(oldest, None)
        except Exception:
            _CUB_DOC_CACHE.clear()
    _CUB_DOC_CACHE[key] = (_t.time() + _CUB_DOC_CACHE_TTL, hdr, lineas)

def _cub_doc_cache_invalidate(tido, nudo):
    """Llamado cuando el documento se persiste (ediciones aguas abajo del cubicador).
    Mantiene el cache fresco aunque sea un sistema READ-ONLY."""
    try:
        key = f"{(tido or '').upper()}|{nudo}"
        _CUB_DOC_CACHE.pop(key, None)
    except Exception:
        pass


@app.route("/api/asignar/documento", methods=["POST"])
@login_required
def api_asignar_documento():
    """
    Busca un documento en el ERP y devuelve header + líneas con datos de cubicaje.
    POST JSON: { tido, nudo, prefetch?, no_cache? }
    Campos de respuesta alineados con lo que usa asignar.html.

    Cache: respuesta server-side cacheada 5 min. ?prefetch=1 marca que el
    cliente está prefetcheando — el cache sigue grabándose, pero no contamos
    estadística de uso.
    """
    if not g.permissions.get("cubicador"):
        return jsonify({"error": "Sin permiso"}), 403

    data = request.get_json(silent=True) or {}
    tido = (data.get("tido") or "FCV").strip().upper()
    nudo = str(data.get("nudo") or "").strip()
    no_cache = bool(data.get("no_cache"))

    if not nudo:
        return jsonify({"error": "Número de documento requerido"}), 400

    cache_key = f"{tido}|{nudo}"
    hdr_l = None if no_cache else _cub_doc_cache_get(cache_key)
    if hdr_l:
        hdr, lineas = hdr_l
        # Marca para diagnóstico — el frontend puede mostrar "⚡ desde cache"
        _from_cache = True
    else:
        try:
            hdr, lineas = _cubicador_fetch(tido, nudo)
        except ConnectionError as ce:
            return jsonify({"error": str(ce)}), 503
        except Exception as ex:
            return jsonify({"error": f"Error al consultar ERP: {ex}"}), 500
        if hdr is not None:
            _cub_doc_cache_put(cache_key, hdr, lineas)
        _from_cache = False

    if hdr is None:
        # Devolvemos diagnóstico del motor para que el frontend pueda mostrar
        # exactamente qué variantes de NUDO se probaron contra el ERP.
        try:
            erp_diag = _ERP._doc_cached(f"{tido}|{nudo}")
        except Exception:
            erp_diag = None
        return jsonify({
            "error": f"No se encontró {tido} N° {nudo} en el ERP Random",
            "diagnostics": {
                "nudo_tried": erp_engine.nudo_variants(
                    erp_engine.TIDO_NUDO_MAP[tido][1](nudo) if tido in erp_engine.TIDO_NUDO_MAP else nudo
                ),
                "tido": tido,
                "nudo": nudo,
                "hint": "Verifica que el documento existe en el ERP Random (la app probó todas las variantes de padding que conoce)."
            }
        }), 404

    # Extraer valor de ZZ Envío (tarifa de despacho cargada en el documento)
    zzenvio_valor = 0.0
    for l in lineas:
        if l["sku"].upper() == "ZZENVIO":
            zzenvio_valor = float(l.get("vaneli", 0))
            break

    # Saldo editable persistente (2026-07-22, Daniel): si Daniel ya guardó un
    # saldo para este documento (ej. despacho parcializado — solo queda 1 item
    # de N por enviar), usar ESE valor en vez del total crudo del ERP. Si nunca
    # se editó, comportamiento idéntico a hoy (valor del ERP tal cual).
    zzenvio_es_saldo = False
    _zz_row = _zz_saldo_get(tido, nudo)
    if _zz_row is not None:
        zzenvio_valor    = float(_zz_row.get("zz_envio_saldo") or 0)
        zzenvio_es_saldo = True

    lineas_out = []
    tot_qty = tot_kg = tot_pv = tot_vol = tot_pred = tot_bultos = 0.0

    for l in lineas:
        if l.get("es_zz"):
            continue
        # 2026-06-14 (Daniel): excluir líneas de DESCUENTO (SKU 'DE' /
        # "DESCUENTO VENTAS"). No son ítems físicos: no se cubican ni se
        # envían, y su "cantidad" es el monto del descuento (ensucia totales,
        # bultos y predominante). Solo se filtra en la salida (ERP read-only).
        if (l.get("sku") or "").strip().upper() == "DE":
            continue
        qty          = l["cantidad"]
        peso_kg_u    = l["peso_kg_u"]
        peso_vol_u   = l["peso_vol_u"]
        pred_u       = l["pred_u"]
        pred_tot     = l["pred_tot"]
        bultos_u     = int(l["total_bultos"])
        bultos_total = bultos_u * int(qty) if l["tiene_bultos"] else 0

        tot_qty    += qty
        tot_kg     += l["peso_kg_tot"]
        tot_pv     += l["peso_vol_tot"]
        tot_vol    += l["vol_tot"]
        tot_pred   += pred_tot
        tot_bultos += bultos_total

        lineas_out.append({
            # Nombres exactos que lee asignar.html
            "sku":             l["sku"],
            "descripcion_erp": l["descripcion_erp"] or l["nombre_app"],
            "cantidad":        qty,
            "total_bultos":    bultos_u,          # bultos por unidad
            "bultos_tot":      bultos_total,       # bultos totales
            "tiene_ficha":     l["tiene_ficha"],
            "tiene_bultos":    l["tiene_bultos"],
            # id interno del producto (ya resuelto en _cubicador_fetch via
            # join con la tabla de productos) -- faltaba reenviarlo al front.
            # Sin esto, la fila "sin ficha" no puede abrir el editor de
            # medidas (necesita el pid para crear/actualizar la ficha).
            "app_id":          l.get("app_id"),
            # Bodega de origen de ESTA línea + su nombre legible (2026-08-17).
            # El front pinta un chip ámbar en la fila del producto cuando no
            # es la principal, para que se vea CUÁL equipo hay que ir a buscar
            # a otra bodega y no solo que "el documento tiene algo raro".
            "bodega":          (l.get("bodega") or "").strip(),
            "bodega_nombre":   _tr_bodega_nombre(l.get("bodega")),
            "bodega_alerta":   bool((l.get("bodega") or "").strip()
                                    and _tr_bodega_norm(l.get("bodega"))
                                        != _tr_bodega_norm(TR_BODEGA_PRINCIPAL)),
            "peso_kg_u":       round(peso_kg_u,  3),
            "peso_vol_u":      round(peso_vol_u, 3),
            "vol_u":           round(l["vol_u"], 1),   # cm³/u
            "pred_u":          round(pred_u,     3),
            "pred_tot":        round(pred_tot,   3),
            # Saldo por línea (fórmula oficial Random MAEDDO, ya calculado en
            # _cubicador_fetch: CAPRCO1 - CAPRAD1 - CAPREX1 - CAPRNC1, forzado a 0
            # si ESLIDO marca despacho total). READ-ONLY: solo lo exponemos al front
            # para el badge "con saldo / sin saldo". > 0 = con saldo, 0 = entregado.
            "saldo":               (round(float(l["saldo"]), 3)
                                    if l.get("saldo") is not None else None),
            "cantidad_despachada": (round(float(l["cantidad_despachada"]), 3)
                                    if l.get("cantidad_despachada") is not None else None),
        })

    # ── Enriquecer header desde OBSERVACIONES (OBDO) cuando el ERP dejó campos
    #    vacíos (típico en boletas a consumidor final: el contacto va en el OBDO,
    #    ej. "Teniente Montt 1980 ñuñoa - 976787263 - correo@x.com"). Así la
    #    factura SIEMPRE llega con datos y el cubicador puede cotizar la comuna.
    try:
        _parsed = _parse_obdo(hdr.get("observaciones") or "")
        if not (hdr.get("email") or "").strip() and _parsed["email"]:
            hdr["email"] = _parsed["email"]
        if not (hdr.get("telefono") or "").strip() and _parsed["telefono"]:
            hdr["telefono"] = _parsed["telefono"]
        if not (hdr.get("direccion") or "").strip() and _parsed["direccion"]:
            hdr["direccion"] = _parsed["direccion"]
        if not (hdr.get("comuna") or "").strip():
            _com = _parsed["comuna"] or _detect_comuna(hdr.get("direccion") or "")
            if _com:
                hdr["comuna"] = _com
    except Exception as _e_enrich:
        print(f"[asignar_documento] enriquecer OBDO falló: {_e_enrich}", flush=True)

    # ── RESOLVER DE CLIENTE 2026-05-27 (Daniel — fix CF en /asignar) ──
    # MISMO resolver que usa el cubicador: si el nombre es CF pero hay RUT
    # real, consulta MAEEN.NOKOEN por RTEN. Resuelve 'Cristian Rossi Medina'
    # en BLV 21577 en vez de 'Consumidor final'.
    #
    # ⚡ PERF 2026-06-05 (Daniel): _cubicador_fetch() YA corre este mismo
    # resolver y deja la marca hdr["_resolver_diag"]. Si está presente (y no
    # venimos de cache, donde igual ya se resolvió), OMITIMOS la segunda
    # llamada para no duplicar el trabajo (consulta MAEEN). Solo re-resolvemos
    # si por algún motivo el header llegó sin esa marca.
    if hdr.get("_resolver_diag") is not None:
        # Ya resuelto aguas arriba: solo aplicamos el fallback de nombre vacío.
        if not (hdr.get("cliente_nombre") or "").strip():
            hdr["cliente_nombre"] = "Cliente no informado por ERP"
    else:
        try:
            _hdr_res = dict(hdr)
            _hdr_res["lineas_raw"] = lineas or []
            _res = resolve_erp_customer(_hdr_res, tido=tido, nudo=nudo)
            if _res and not _is_cf_name(_res.get("customer_name")):
                hdr["cliente_nombre"] = _res["customer_name"]
                if _res.get("customer_rut"):     hdr["cliente_rut"] = _res["customer_rut"]
                if _res.get("customer_email"):   hdr["email"] = hdr.get("email") or _res["customer_email"]
                if _res.get("customer_phone"):   hdr["telefono"] = hdr.get("telefono") or _res["customer_phone"]
                if _res.get("dispatch_address"): hdr["direccion"] = hdr.get("direccion") or _res["dispatch_address"]
                if _res.get("dispatch_commune"): hdr["comuna"] = hdr.get("comuna") or _res["dispatch_commune"]
            hdr["_resolver_diag"] = {
                "source": _res.get("source") if _res else "none",
                "confidence": _res.get("confidence") if _res else "low",
                "chain": _res.get("fallback_chain") if _res else [],
            }
            # Solo ahora, si SIGUE vacío, ponemos texto canónico limpio
            if not (hdr.get("cliente_nombre") or "").strip():
                hdr["cliente_nombre"] = "Cliente no informado por ERP"
        except Exception as _e_res2:
            print(f"[asignar_documento] resolver falló: {_e_res2}", flush=True)
            if not (hdr.get("cliente_nombre") or "").strip():
                hdr["cliente_nombre"] = "Cliente no informado por ERP"

    # ═══ NORMALIZACIÓN FINAL del header en /asignar ═════════════════════
    # Última barrera: cualquier placeholder que se haya colado (BOLETA,
    # ERP_ENVIO, CONSUMIDOR FINAL, SIN COMUNA) se limpia antes de devolver.
    _nom = _erp_clean(hdr.get("cliente_nombre"))
    hdr["cliente_nombre"] = _nom or "Cliente no informado por ERP"
    if _erp_is_placeholder_rut(hdr.get("cliente_rut")):
        hdr["cliente_rut"] = ""
    hdr["direccion"]     = _erp_clean(hdr.get("direccion"))
    hdr["comuna"]        = _erp_clean(hdr.get("comuna"))
    hdr["telefono"]      = _erp_clean(hdr.get("telefono"))
    hdr["email"]         = _erp_clean(hdr.get("email"))
    hdr["observaciones"] = _erp_clean(hdr.get("observaciones"))

    # ── Resolver CÓDIGO de comuna del ERP → nombre real (fix Osorno 2026-06-15)
    # El ERP guarda el código CMEN corto (ej. "OSO"); si llega así, el cubicador
    # mostraba "OSO" y la cotización de couriers + el código postal NO hacían
    # match → "Sin cobertura". Lo decodificamos vía TABCM (READ-ONLY, solo
    # SELECT). Heurística "parece código": ≤4 chars y sin espacios; los nombres
    # normales ("Osorno", "Lo Barnechea") pasan intactos. Degrada al valor
    # original si TABCM no resuelve.
    _com_cod = (hdr.get("comuna") or "").strip()
    if _com_cod and len(_com_cod) <= 4 and " " not in _com_cod:
        try:
            _com_nom = _resolve_comuna_erp(_com_cod, pais_code="CL")
            if _com_nom and _com_nom.strip() and _com_nom.strip().upper() != _com_cod.upper():
                print(f"[asignar_documento] comuna '{_com_cod}' → '{_com_nom.strip()}' (TABCM)", flush=True)
                hdr["comuna"] = _com_nom.strip()
        except Exception as _e_com:
            print(f"[asignar_documento] resolver comuna '{_com_cod}' falló: {_e_com}", flush=True)

    # ── Respetar la dirección que YA editó un humano (2026-07-29, Daniel:
    # "algo lo está actualizando a la dirección del documento... debemos
    # respetar la dirección que cambia Alison"). Root cause real: esta misma
    # pantalla (Asignar y Cotizar) siempre pre-rellenaba con el dato CRUDO
    # del ERP — si el operador reabría el documento para otro ajuste, veía
    # (y sin querer volvía a guardar) la dirección genérica del ERP en vez de
    # la que ya había corregido. Si el compromiso ya existe y tiene el
    # candado direccion_editada_manual=1, el header devuelto usa esos datos
    # guardados en vez de los del ERP — el ERP nunca vuelve a "ganar".
    try:
        _com_guardado = mysql_fetchone(
            "SELECT direccion, comuna, region, cod_postal, telefono, email, "
            "direccion_referencia FROM transport_commitments "
            "WHERE tido=%s AND nudo=%s AND direccion_editada_manual=1",
            (tido, nudo),
        )
        if _com_guardado:
            for _campo in ("direccion", "comuna", "region", "cod_postal", "telefono", "email"):
                if _com_guardado.get(_campo):
                    hdr[_campo] = _com_guardado[_campo]
            hdr["direccion_referencia"] = _com_guardado.get("direccion_referencia") or ""
            hdr["direccion_bloqueada_por_edicion"] = True
    except Exception as _e_dirlock:
        print(f"[asignar_documento] chequeo direccion_editada_manual falló: {_e_dirlock}", flush=True)

    postal_destino = _comuna_to_postal(hdr.get("comuna", ""))

    # ── Desglose de stock (físico/devengado/comprometido) por SKU (2026-07-25,
    # Daniel: "poder ver el saldo... con respecto al comprometido y el
    # devengado, cuánto es el stock físico"). El "saldo" de arriba es saldo
    # DEL DOCUMENTO (CAPRCO1-CAPRAD1-CAPREX1-CAPRNC1, cuánto falta despachar
    # de ESTA factura); esto es el STOCK GLOBAL del producto en bodega (MAEPR),
    # un concepto distinto y complementario. 1 sola consulta batch para todas
    # las líneas del documento (evita N round-trips al ERP). READ-ONLY.
    try:
        _skus_doc = [l.get("sku") for l in lineas_out if l.get("sku")]
        _stock_map = get_erp_stock_by_skus(_skus_doc) if _skus_doc else {}
        for _l in lineas_out:
            _l["stock"] = _stock_map.get((_l.get("sku") or "").strip().upper())
    except Exception as _e_stock:
        print(f"[asignar_documento] desglose de stock falló: {_e_stock}", flush=True)
        for _l in lineas_out:
            _l.setdefault("stock", None)

    return jsonify({
        "ok":     True,
        "header": {**hdr, "postal_destino": postal_destino},
        "lineas": lineas_out,
        # Resumen de bodegas del documento (2026-08-17, Daniel: "cuando llame
        # a la factura por el Asignar y Cotizar... que el usuario sepa que hay
        # una excepción, ya que el 98% sale de la 02"). Se calcula sobre las
        # líneas de PRODUCTO que ya vienen resueltas arriba -- sin consultar
        # nada extra. El front lo usa para el aviso grande del encabezado.
        "bodegas": _tr_bodegas_analizar([l.get("bodega") for l in lineas_out]),
        "totales": {
            "total_qty":    int(tot_qty),
            "total_bultos": int(tot_bultos),
            "peso_kg":      round(tot_kg,   3),
            "peso_pv":      round(tot_pv,   3),
            "vol_cm3":      round(tot_vol,  1),
            "peso_pred":    round(tot_pred, 3),
        },
        "tipos_doc":       TIPOS_DOC_CUBICADOR,
        "zzenvio_valor":   round(zzenvio_valor, 0),
        "zzenvio_es_saldo": zzenvio_es_saldo,
        "from_cache":      _from_cache,
    })


@app.route("/api/asignar/zzenvio-saldo", methods=["PUT"])
@login_required
def api_asignar_zzenvio_saldo():
    """Guarda el saldo EDITADO de ZZ Envío para un documento (2026-07-22,
    Daniel): con despachos parcializados, el ZZ Envío del ERP (total de la
    factura) deja de representar lo que falta por enviar. Este saldo queda
    GUARDADO — la próxima vez que se busque el mismo documento (acá o en
    cualquier otra consulta), _zz_saldo_get() lo devuelve en vez del valor
    crudo del ERP.

    POST/PUT JSON: { tido, nudo, saldo, valor_original? }
    valor_original: el zzenvio_valor que traía el ERP en el momento del
    PRIMER guardado — se preserva como referencia auditable; en guardados
    posteriores del MISMO documento no se pisa (solo se actualiza el saldo).
    """
    if not g.permissions.get("cubicador"):
        return jsonify({"error": "Sin permiso"}), 403

    data  = request.get_json(silent=True) or {}
    tido  = (data.get("tido") or "").strip().upper()
    nudo  = (data.get("nudo") or "").strip()
    if not tido or not nudo:
        return jsonify({"error": "tido y nudo son requeridos"}), 400
    try:
        saldo = max(0.0, float(data.get("saldo", 0) or 0))
    except (TypeError, ValueError):
        return jsonify({"error": "saldo inválido"}), 400
    try:
        valor_original = float(data.get("valor_original", saldo) or saldo)
    except (TypeError, ValueError):
        valor_original = saldo

    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO transport_zz_saldo "
                "  (tido, nudo, zz_envio_original, zz_envio_saldo, updated_by) "
                "VALUES (%s,%s,%s,%s,%s) "
                "ON DUPLICATE KEY UPDATE "
                "  zz_envio_saldo = VALUES(zz_envio_saldo), "
                "  updated_by     = VALUES(updated_by)",
                (tido, nudo, round(valor_original, 2), round(saldo, 2), current_username()),
            )
        conn.commit()
    except Exception as e:
        print(f"[zz-saldo] guardar falló {tido}/{nudo}: {e}", flush=True)
        return jsonify({"error": "No se pudo guardar el saldo"}), 500

    _tr_log("documento", f"{tido}{nudo}", "zz envío saldo editado",
             f"nuevo saldo={round(saldo,2)}")
    return jsonify({"ok": True, "saldo": round(saldo, 2)})


@app.route("/api/asignar/tarifa-fedex", methods=["POST"])
@login_required
def api_asignar_tarifa_fedex():
    """
    Consulta la tarifa FedEx para el envío.
    POST JSON: { peso_pred, zona_id, es_residencial, es_remoto, valor_neto }
      zona_id: 1=RM, 2=V/VI/VII, 3=VIII/IX, 4=XIV/X, 5=XI/XII, 6=I/II/III/IV
    Responde: { ok, costo_total, detalle:{servicio, tiempo_transito, peso_facturable, recargos} }
    """
    if not g.permissions.get("cubicador"):
        return jsonify({"error": "Sin permiso"}), 403

    data       = request.get_json(silent=True) or {}
    peso_pred  = float(data.get("peso_pred", 0) or 0)
    zona_id    = str(data.get("zona_id", "1")).strip()
    es_resid   = bool(data.get("es_residencial", False))
    es_remoto  = bool(data.get("es_remoto", False))
    valor_neto = float(data.get("valor_neto", 0) or 0)

    if peso_pred <= 0:
        return jsonify({"error": "Peso predominante debe ser mayor a 0"}), 400

    # Mapear zona_id → postal de referencia para la API FedEx
    _ZONA_POSTAL = {
        "1": "8320000",   # RM Santiago
        "2": "2340000",   # Valparaíso
        "3": "4030000",   # Concepción
        "4": "5480000",   # Puerto Montt
        "5": "6200000",   # Punta Arenas
        "6": "1240000",   # Antofagasta
    }
    postal_dest = _ZONA_POSTAL.get(zona_id, "8320000")

    try:
        result = _fedex_calc_rate(peso_pred, postal_dest, es_residencial=es_resid)
        if "error" in result:
            return jsonify({"error": result["error"]}), 422

        costo_base = result["tarifa"]
        # Recargos adicionales según opciones marcadas
        recargo_resid  = 4200 if es_resid  else 0
        recargo_remoto = 6800 if es_remoto else 0
        costo_total    = costo_base + recargo_resid + recargo_remoto

        return jsonify({
            "ok":          True,
            "costo_total": round(costo_total, 0),
            "detalle": {
                "servicio":        result["servicio"],
                "tiempo_transito": result["tiempo_transito"],
                "peso_facturable": result["peso_facturable"],
                "costo_base":      round(costo_base, 0),
                "recargo_resid":   recargo_resid,
                "recargo_remoto":  recargo_remoto,
                "recargos_fedex":  result.get("recargos", []),
                "moneda":          result["moneda"],
                "zona_id":         zona_id,
            },
        })
    except FedexRateError as ex:
        # El detalle técnico (código y mensaje de FedEx) ya quedó en el log de
        # _fedex_calc_rate con prefijo [FEDEX]; acá se agrega el contexto del
        # endpoint. Al cliente viaja SOLO texto amigable (REGLA #4).
        print(f"[FEDEX] tarifa-fedex zona={zona_id} peso_pred={peso_pred} "
              f"residencial={es_resid} remoto={es_remoto} → {ex}", flush=True)
        return jsonify({"error": ex.mensaje_usuario}), 502
    except Exception as ex:
        import traceback
        # Log completo al backend, mensaje amigable al usuario: el `str(ex)` de
        # requests incluye la URL interna de la API de FedEx y no debe salir.
        print(f"[FEDEX ERROR] tarifa-fedex zona={zona_id} peso_pred={peso_pred}: "
              f"{_fedex_sanitizar_log(ex)}\n"
              f"{_fedex_sanitizar_log(traceback.format_exc())}", flush=True)
        msg = FEDEX_MSG_GENERICO
        if "no configurada" in str(ex).lower():
            # Caso típico: faltan las credenciales en el entorno. Se avisa qué
            # hacer, sin nombrar variables ni endpoints internos.
            msg = ("La cotización con FedEx no está disponible (falta configurar "
                   "la integración). Avisa a soporte o elige otro courier.")
        return jsonify({"error": msg}), 502


# ════════════════════════════════════════════════════════════════
#  COTIZADOR INTEGRAL DE COURIERS — todos los couriers en paralelo
# ════════════════════════════════════════════════════════════════
#  POST /api/asignar/cotizar-couriers
#
#  Devuelve cotización lado-a-lado de TODOS los couriers activos
#  para un peso + comuna + valor dado. FedEx vía API (live), el resto
#  vía tabla transport_courier_comunas. Paralelizado con
#  ThreadPoolExecutor — objetivo <2s.
# ────────────────────────────────────────────────────────────────

@app.route("/api/asignar/cotizar-couriers", methods=["POST"])
@login_required
def api_asignar_cotizar_couriers():
    """Cotiza TODOS los couriers activos en paralelo para el envío dado.

    Body JSON:
      {
        "peso_kg": 173.89,
        "peso_pred_kg": 173.89,   # opcional, si difiere del peso real
        "comuna": "Lo Barnechea",
        "es_residencial": false,
        "valor_neto": 1571566
      }

    Response:
      {
        "ok": true,
        "comuna_resuelta": "Lo Barnechea",
        "peso_facturable": 174,
        "cotizaciones": [
          {
            "courier_id": 1,
            "courier_nombre": "FedEx",
            "tiene_cobertura": true,
            "fuente": "api"|"tabla"|"no_cobertura",
            "precio": 126933,
            "moneda": "CLP",
            "tiempo_transito": "1-2 días",
            "servicio": "FedEx Standard",
            "logo_url": "...",
            "subtotal": 126933,
            "mensaje": null
          },
          ...
        ],
        "recomendado_id": 2   # el más barato con cobertura
      }
    """
    # 2026-07-26 (bug reportado por Daniel: "el cotizar envío no sale sin
    # tarifa"): este endpoint lo invoca en proceso _invocar_comparador() de
    # cubicador_plus.py desde /cubicador/api/cotizar, que a su vez lo usa el
    # wizard de Cotizaciones de Transporte y Distribución
    # (_modal_cotizacion_logistica.html). Antes exigía SOLO 'cubicador' —
    # un usuario con permiso 'transporte'/'logistica_cotizaciones' (que sí
    # puede abrir ese wizard) caía en un 403 silencioso justo al cotizar el
    # flete. Se amplía al mismo OR que ya usa
    # logistica_cotizaciones._lc_tiene_permiso.
    if not (g.permissions.get("cubicador") or g.permissions.get("transporte")
            or g.permissions.get("logistica_cotizaciones") or g.permissions.get("superadmin")):
        return jsonify({"error": "Sin permiso"}), 403

    import concurrent.futures as _cf
    import time as _t_start

    t0 = _t_start.time()
    data       = request.get_json(silent=True) or {}
    peso_kg    = float(data.get("peso_kg") or 0)
    peso_pred  = float(data.get("peso_pred_kg") or peso_kg or 0)
    comuna     = (data.get("comuna") or "").strip()
    # 2026-08-04 (Shipit): sin esto no hay forma de saber si el envío tiene
    # más de 1 bulto -- la restricción que más le preocupa a Daniel. Si no
    # llega (caller viejo, o cubicaje sin dato), se asume 1 -- el caso más
    # común -- pero queda marcado en 'trace' para que quede claro que no se
    # verificó el dato real (ver _shipit_cotizacion_dict).
    try:
        n_bultos_raw = data.get("n_bultos")
        n_bultos = int(n_bultos_raw) if n_bultos_raw not in (None, "", 0) else None
    except (TypeError, ValueError):
        n_bultos = None
    # Defensa: si llega un CÓDIGO ERP de comuna (ej. "OSO"), resolverlo a
    # nombre ("Osorno") vía TABCM para que el match con transport_courier_comunas
    # funcione. Nombres normales (con espacio o >4 chars) pasan intactos.
    if comuna and len(comuna) <= 4 and " " not in comuna:
        try:
            _cr = _resolve_comuna_erp(comuna, pais_code="CL")
            if _cr and _cr.strip():
                comuna = _cr.strip()
        except Exception as _e_cr:
            print(f"[cotizar-couriers] resolver comuna falló: {_e_cr}", flush=True)
    es_resid   = bool(data.get("es_residencial", False))
    valor_neto = float(data.get("valor_neto", 0) or 0)
    # Contexto del documento para audit trail (opcional)
    doc_tido   = (data.get("tido") or "").strip() or None
    doc_nudo   = (data.get("nudo") or "").strip() or None

    if not comuna:
        return jsonify({"error": "Comuna requerida para cotizar"}), 400

    # Sin datos REALES de peso/cubicaje (documento sin líneas, o con líneas
    # pero sin ficha técnica registrada → peso_kg_u=0) → NO fabricar una
    # cotización con el piso de 0.5kg de abajo. Eso mostraría precios
    # completos y creíbles de couriers para un envío que no existe.
    # Daniel 2026-06-16: VD 10131 (0 productos en cubicaje) mostraba
    # cotizaciones reales igual. El front ya no debería ni llamar a este
    # endpoint en ese caso, pero esta es la defensa de fondo (cualquier
    # otro caller queda protegido también).
    if peso_kg <= 0 and peso_pred <= 0:
        return jsonify({
            "ok": True, "cotizaciones": [], "recomendado_id": None,
            "peso_facturable": 0, "comuna_resuelta": comuna,
            "mensaje": "Sin datos de peso/cubicaje para cotizar: el documento no tiene "
                       "productos con ficha técnica registrada.",
        })

    # El peso facturable es max(peso_pred, peso_kg, 0.5)
    peso_fact = max(peso_pred, peso_kg, 0.5)

    if peso_fact <= 0:
        return jsonify({"error": "Peso debe ser mayor a 0"}), 400

    # 1) Couriers activos + tarifas de la comuna en UN solo round-trip
    # Esto evita 9 queries serializadas (200ms cada una = 1.8s ahorrados).
    try:
        couriers = mysql_fetchall(
            "SELECT id, nombre, logo_url, logo_square_url, tipo "
            "FROM transport_couriers WHERE activo=1 ORDER BY nombre"
        ) or []
    except Exception as e:
        return jsonify({"error": f"Error cargando couriers: {e}"}), 500

    if not couriers:
        return jsonify({"ok": True, "cotizaciones": [], "recomendado_id": None,
                        "peso_facturable": round(peso_fact, 1),
                        "comuna_resuelta": comuna,
                        "mensaje": "No hay couriers activos configurados."})

    # Pre-cargar tarifas de la comuna para TODOS los couriers en una query
    # → mapa {courier_id: {precios_json, dias_transito, zona}}
    try:
        tarifa_rows = mysql_fetchall(
            "SELECT courier_id, precios_json, dias_transito, zona "
            "FROM transport_courier_comunas "
            "WHERE LOWER(TRIM(comuna))=LOWER(TRIM(%s))",
            (comuna,)
        ) or []
        tarifa_map = {r['courier_id']: r for r in tarifa_rows}
    except Exception as e:
        print(f"[cotizar-couriers] error pre-load tarifas: {e}", flush=True)
        tarifa_map = {}

    # Capturar el app actual para que los hilos pushen su propio app_context (sólo FedEx)
    _flask_app = app

    # Helper: resolver precio desde precios_json + peso, devolviendo TRACE completo.
    # Sin hit MySQL — usa precios_json ya cargado en memoria.
    def _resolve_precio_con_trace(precios_json_raw, peso_kg):
        """Devuelve dict { precio, bracket_aplicado, bracket_upper, formula,
                            json_brackets_disponibles, advertencias } o None."""
        if not precios_json_raw:
            return None
        try:
            precios = json.loads(precios_json_raw)
        except Exception:
            return None
        brackets = []
        for key, price in precios.items():
            if price is None:
                continue
            try:
                upper = _parse_peso_upper(key)
                brackets.append((upper, float(price), str(key)))
            except Exception:
                pass
        if not brackets:
            return None
        brackets.sort(key=lambda x: x[0])
        match = None
        formula = ""
        for upper, price, key_orig in brackets:
            if peso_kg <= upper:
                match = (upper, price, key_orig)
                formula = f"Bracket exact match: {peso_kg}kg <= {upper}kg (key='{key_orig}')"
                break
        if match is None:
            upper, price, key_orig = brackets[-1]
            match = (upper, price, key_orig)
            formula = f"Sobre bracket máximo: usa último (key='{key_orig}')"

        upper, price, key_orig = match
        advs = []
        if peso_kg >= 5 and price < 1000:
            advs.append(
                f"Precio sospechosamente bajo: ${int(price)} para {peso_kg}kg "
                f"(podría ser precio/kg en lugar de total) — verificar tabla"
            )
        elif peso_kg >= 50 and price < 5000:
            advs.append(
                f"Precio bajo para peso alto: ${int(price)} para {peso_kg}kg "
                f"(~${price/peso_kg:.0f}/kg) — verificar tabla"
            )
        elif peso_kg >= 10 and price > 0 and (price / peso_kg) < 50:
            advs.append(
                f"Tarifa <$50/kg: ${int(price)} para {peso_kg}kg → verificar tabla"
            )

        return {
            "precio": float(price),
            "bracket_aplicado": key_orig,
            "bracket_upper": float(upper),
            "formula": formula,
            "json_brackets_disponibles": [b[2] for b in brackets],
            "advertencias": advs,
        }

    # Helper: arma la cotización con el modelo NUEVO (tabla macro, sin margen/IVA).
    # 'precio' = base de tabla + seguro 1,2% (igual que la macro de SPHS).
    _ETD_MACRO = {'felca': '2-4 días', 'milling': '2-4 días',
                  'clickex': '24-48 h', 'fedex_directo': '1-2 días'}

    # A partir de esta brecha (%) contra la tarifa PROPIA del courier, la regla
    # comercial se avisa en pantalla. No cambia el precio: solo transparenta
    # cuánto está resignando ILUS en ese envío (hallazgo 2026-07-25).
    _BRECHA_REGLA_AVISO_PCT = 15.0

    def _macro_cotizacion_dict(cid, nombre, logo, slug, r):
        base, seguro, precio = r["base"], r["seguro"], r["precio"]

        # ── REGLA COMERCIAL ≠ ESTIMACIÓN (2026-07-25) ────────────────────
        # Felca y Milling derivan SIEMPRE su precio de FedEx Directo
        # (Milling −5%, Felca −10%, commits 553ee2c/216b7e4). Eso NO es una
        # proyección técnica: es la política de precios que fijó Daniel y es
        # tan firme como una tabla. transporte_tarifas sigue enviando
        # 'estimado': True por compatibilidad, así que acá distinguimos por
        # 'es_regla_comercial'/'fuente'/'modo'. Si se tratan como estimación,
        # el Cotizador descarta justo a los dos couriers más baratos.
        es_regla = (
            bool(r.get("es_regla_comercial"))
            or (r.get("fuente") == "regla")
            or (r.get("modo") == "regla_fedex")
        )
        # 'estimado' de verdad = proyección sin tabla NI regla detrás.
        estimado = bool(r.get("estimado")) and not es_regla

        # ── CONFIDENCIALIDAD ABSOLUTA (Daniel, 2026-07-25, textual): "que
        # fuera como simple casualidad... no debe haber código, comentario,
        # seña en el front, nada que nos indique esa pequeña diferencia."
        # Antes esta función mandaba un % "disimulado" (jitter por documento)
        # y un texto "~10% más económico" — SIGUE siendo una seña. Ahora un
        # precio 'regla' se trata, de cara al cliente/JSON/frontend, EXACTAMENTE
        # igual que un precio de tabla real: mismo 'fuente', mismo formato de
        # 'formula' (transporte_tarifas.py ya genera el tramo con el MISMO
        # formato "{lo}-{hi} kg × {tasa}" que una fila negociada real — ver
        # _descuento_comuna_pct), mismo 'servicio'. NINGÚN campo que distinga
        # "regla" del resto sale de esta función. Lo único que se conserva
        # puertas adentro (nunca en el dict de retorno) es el trace interno de
        # transporte_tarifas.py, para quien mantenga el motor.
        servicio_txt = "Estimado (sin tarifa cargada)" if estimado else "Standard"

        desglose = {
            "precio_costo": base, "precio_venta": precio,
            "margen_pct": 0, "margen_clp": 0, "iva_pct": 0, "iva_clp": 0,
            "seguro_clp": seguro,
        }
        formula = f"Tabla SPHS: {r['tramo']} → ${base:,}".replace(",", ".")
        if seguro:
            formula += f" + seguro 1,2% ${seguro:,}".replace(",", ".")
        formula += f" = ${precio:,}".replace(",", ".")

        # ── Advertencias: solo las que son CIERTAS ───────────────────────
        advertencias = []
        nota = None
        if estimado:
            advertencias.append("Tarifa estimada: aún sin tabla propia para esta comuna/peso")
        # Para 'regla' NO se agrega nota ni advertencia: de cara afuera es una
        # tarifa de tabla más.

        # fuente_top/fuente_trace: 'regla' se reporta como 'tabla' — misma
        # razón de arriba. es_regla sigue existiendo como variable LOCAL de
        # Python (para el cálculo de 'formula'/'servicio_txt' más arriba),
        # pero no cruza al dict que se devuelve.
        if estimado:
            fuente_top, fuente_trace = "estimado", "estimado"
        else:
            fuente_top, fuente_trace = "tabla", "tabla_macro"

        return {
            "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
            "tiene_cobertura": True, "fuente": fuente_top,
            "precio": precio, "precio_costo": base, "moneda": "CLP",
            "tiempo_transito": _ETD_MACRO.get(slug, "—"),
            "servicio": servicio_txt,
            "subtotal": precio, "desglose": desglose, "mensaje": None,
            "es_estimado": estimado,
            # OJO — confidencialidad (Daniel, 2026-07-25, textual: "no debe
            # haber código, comentario, seña en el front, nada"): este JSON lo
            # puede inspeccionar cualquiera con la pestaña de Red del
            # navegador abierta. Por eso NINGÚN campo que distinga 'regla' de
            # 'tabla' sale de acá: ni regla_pct, ni derivado_de, ni
            # es_regla_comercial, ni precio_tabla_propia/brecha (con 'precio'
            # alcanzaría para reconstruir el % con una división). El bracket
            # y la fórmula usan el 'tramo' real, con el MISMO formato que una
            # fila de tabla negociada (ver transporte_tarifas.py).
            "nota_precio": nota,
            "trace": {
                "bracket": r["tramo"], "bracket_upper": None, "formula": formula,
                "fuente": fuente_trace,
                "validado": False,
                "advertencias": advertencias,
                "nota": nota,
                "json_brackets_disponibles": [], "peso_usado": peso_fact,
                "comuna_db": r["comuna_tabla"], "desglose": desglose,
            },
        }

    def _no_cobertura_dict(cid, nombre, logo):
        return {
            "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
            "tiene_cobertura": False, "fuente": "no_cobertura",
            "mensaje": f"Sin cobertura para {comuna}",
            "trace": {"bracket": None, "bracket_upper": None,
                      "formula": f"Sin tarifa en tabla para {comuna}",
                      "fuente": "no_cobertura", "validado": False,
                      "advertencias": [f"Sin cobertura para {comuna}"],
                      "json_brackets_disponibles": [], "peso_usado": peso_fact,
                      "comuna_db": None},
        }

    # 2026-08-04 (Shipit): a diferencia del resto de couriers de esta
    # función (tabla local en transporte_tarifas.py), Shipit es una API
    # real — llama a POST /v/rates. Se muestra como UNA sola ficha de
    # courier (Daniel: "como un solo courier, no mezclado con
    # Chilexpress/Starken por dentro") con el precio más barato como
    # 'precio' (para ordenar igual que el resto), pero conserva en
    # 'operadores_shipit' el desglose de TODOS los operadores que Shipit
    # devolvió, cada uno rotulado "(vía Shipit)" — pedido explícito:
    # "me interesa siempre separar las cosas y evidenciar... cuánto vale
    # cada servicio" + "contener todos ahi por si activo mas courriers".
    #
    # Bloquea ANTES de llamar a la API si el envío no cumple las
    # restricciones de Shipit (>1 bulto, >15kg), con mensajes ESPECÍFICOS
    # por regla (shipit_client.verificar_restricciones) — nunca un texto
    # genérico ("no vayas a mandar algo genérico, algo específico").
    # 2026-08-05 (bug real, encontrado en logs de producción tras el primer
    # deploy: "[shipit] error leyendo shipit_comunas: Working outside of
    # application context"): _shipit_commune_id() lee MySQL vía g._db, que
    # exige contexto de aplicación Flask. _cotizar_uno corre dentro del
    # ThreadPoolExecutor del punto 3 más abajo, y un hilo worker NO hereda
    # ese contexto -- por eso Shipit SIEMPRE fallaba en "falta homologar
    # comuna de origen" en producción, silenciosamente, mientras el resto de
    # couriers sobrevivía porque transporte_tarifas.py tiene fallback a
    # archivo local ante el mismo error. Se resuelven ambos commune_id ACÁ,
    # en el hilo del request (con contexto vivo), antes de entrar al pool, y
    # se capturan por closure -- dentro del hilo solo queda la llamada HTTP
    # (_shipit_request), que no toca Flask ni MySQL.
    _shipit_es_activo = any(
        'shipit' in _ttar._strip(c['nombre'] or '').lower() for c in couriers
    )
    _shipit_origin_id = _shipit_destiny_id = None
    if _shipit_es_activo:
        try:
            _shipit_origin_id, _ = _shipit_commune_id(_tr_sender_cfg().get("city") or "Quilicura")
            _shipit_destiny_id, _ = _shipit_commune_id(comuna)
        except Exception as _e_shipit_comuna:
            print(f"[shipit] error resolviendo comunas: {_e_shipit_comuna}", flush=True)

    # 2026-08-25 (Clickex): mismo cuidado que con Shipit arriba -- lee la
    # tarifa cacheada (clickex_tarifas, vía MySQL/Flask) ACÁ, en el hilo del
    # request, ANTES de entrar al ThreadPoolExecutor. Adentro del pool NO
    # hay contexto de aplicación Flask (el bug real de Shipit, documentado
    # arriba) así que _clickex_cotizacion_dict solo lee esta variable
    # capturada por closure -- no vuelve a tocar MySQL.
    #
    # A propósito NO se llama a _clickex_sync_tarifas() (que sí golpea la
    # API en vivo) en cada cotización: eso agregaría latencia de red al
    # flujo interactivo del operador por un precio que casi no cambia. La
    # sincronización en vivo la disparan los Excel de tarifas (pedido
    # explícito de Daniel: "que me entregue la tarifa que obtenga la API")
    # y el diagnóstico admin (?accion=sync_tarifas) -- acá se lee la caché
    # que esos dos ya mantienen fresca.
    _clickex_es_activo = any(
        'clickex' in _ttar._strip(c['nombre'] or '').lower() for c in couriers
    )
    _clickex_tarifa_resultado = _clickex_tarifa_comuna(comuna) if _clickex_es_activo else None

    def _clickex_cotizacion_dict(cid, nombre, logo):
        import clickex_client as _clc

        problemas = _clc.verificar_restricciones(peso_fact)
        if problemas:
            return {
                "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
                "tiene_cobertura": False, "fuente": "restriccion_clickex",
                "mensaje": " · ".join(problemas),
                "trace": {"bracket": None, "bracket_upper": None,
                          "formula": " · ".join(problemas),
                          "fuente": "restriccion_clickex", "validado": False,
                          "advertencias": problemas,
                          "json_brackets_disponibles": [], "peso_usado": peso_fact,
                          "comuna_db": None},
            }

        if not _clickex_tarifa_resultado:
            return _no_cobertura_dict(cid, nombre, logo)

        precio = round(_clickex_tarifa_resultado["costo_neto"] or 0)
        sla = _clickex_tarifa_resultado.get("sla_dias")
        formula = f"Clickex API (matriz negociada): {comuna} = ${precio:,}".replace(",", ".")

        return {
            "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
            "tiene_cobertura": True, "fuente": "api_clickex",
            "precio": precio, "moneda": "CLP",
            "tiempo_transito": f"{sla} día(s)" if sla else "—",
            "servicio": "Standard (vía Clickex)",
            "subtotal": precio, "desglose": None, "mensaje": None,
            "trace": {
                "bracket": "Clickex API", "bracket_upper": None, "formula": formula,
                "fuente": "api_clickex", "validado": False,
                "advertencias": [], "json_brackets_disponibles": [],
                "peso_usado": peso_fact, "comuna_db": comuna,
            },
        }

    def _shipit_cotizacion_dict(cid, nombre, logo):
        import shipit_client as _shc

        bultos_asumidos = n_bultos is None
        n_efectivo = n_bultos if n_bultos is not None else 1
        advertencias_base = []
        if bultos_asumidos:
            advertencias_base.append(
                "No se recibió la cantidad real de bultos: se asumió 1 "
                "(el caso más común) sin verificar el dato."
            )

        def _dict_error(mensaje, fuente="error", advertencias=None):
            return {
                "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
                "tiene_cobertura": False, "fuente": fuente, "mensaje": mensaje,
                "trace": {
                    "bracket": None, "bracket_upper": None, "formula": mensaje,
                    "fuente": fuente, "validado": False,
                    "advertencias": (advertencias or []) + advertencias_base,
                    "json_brackets_disponibles": [], "peso_usado": peso_fact,
                    "comuna_db": None,
                },
            }

        problemas = _shc.verificar_restricciones(n_efectivo, peso_fact)
        if problemas:
            return _dict_error(" · ".join(problemas), fuente="restriccion_shipit",
                                advertencias=problemas)

        origin_id, destiny_id = _shipit_origin_id, _shipit_destiny_id
        if not origin_id:
            return _dict_error(
                "Shipit: falta homologar la comuna de origen (bodega) — "
                "sincroniza comunas desde Diagnóstico > Shipit.")

        if not destiny_id:
            return _no_cobertura_dict(cid, nombre, logo)

        # Dimensiones: ILUS no cubica largo/ancho/alto por bulto hoy (solo
        # peso y bultos totales) — se usa la misma caja de referencia
        # 30x30x30cm que ya usa /transporte/api/diagnostico/shipit, como
        # aproximación documentada hasta que el cubicador registre
        # dimensiones reales por bulto.
        payload, errores = _shc.build_rate_payload(
            length=30, width=30, height=30, weight=peso_fact,
            origin_id=origin_id, destiny_id=destiny_id,
        )
        if errores:
            return _dict_error("Shipit: " + "; ".join(errores))

        r = _shipit_request("POST", _shc.EP_RATES, payload=payload, timeout=8)
        if not r.get("ok"):
            return _dict_error(f"Shipit: {r.get('error') or 'error al cotizar'}")

        filas = _shc.parse_rates_response(r.get("data"))
        disponibles = [f for f in filas if f.get("disponible") and f.get("precio")]
        if not disponibles:
            return _no_cobertura_dict(cid, nombre, logo)

        disponibles.sort(key=lambda f: f["precio"])
        mas_barato = disponibles[0]

        # Shipit devuelve los nombres en minúscula y con guion bajo
        # ("chilexpress", "fazt_nd", "bluexpress"). Se muestran tal cual
        # quedaron en pantalla ("Fazt_Nd" — Daniel, 2026-08-05), así que se
        # limpian antes de salir: guion bajo → espacio y capitalización.
        def _op_nombre(raw):
            return (raw or "—").replace("_", " ").title()

        operadores = [
            {
                "operador": _op_nombre(f["courier"]),
                "operador_display": f"{_op_nombre(f['courier'])} (vía Shipit)",
                "servicio": f["servicio"], "precio": f["precio"], "dias": f["dias"],
                "es_mas_barato": (f is mas_barato),
            }
            for f in disponibles
        ]

        formula = (f"Shipit API: {_op_nombre(mas_barato['courier'])} "
                   f"{mas_barato['servicio']} = "
                   f"${int(mas_barato['precio']):,}".replace(",", "."))

        return {
            "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
            "tiene_cobertura": True, "fuente": "api_shipit",
            "precio": mas_barato["precio"], "moneda": "CLP",
            "tiempo_transito": f"{mas_barato['dias']} día(s)" if mas_barato.get("dias") else "—",
            "servicio": f"{mas_barato['courier'].title()} (vía Shipit)",
            "subtotal": mas_barato["precio"], "desglose": None, "mensaje": None,
            "operadores_shipit": operadores,
            "trace": {
                "bracket": "Shipit API", "bracket_upper": None, "formula": formula,
                "fuente": "api_shipit", "validado": False,
                "advertencias": advertencias_base,
                "json_brackets_disponibles": [], "peso_usado": peso_fact,
                "comuna_db": comuna,
            },
        }

    # 2) Función worker que cotiza UN courier — TODO con tabla del macro.
    #    FedEx usa la tabla "FedEx Directo" (Daniel: sin API por ahora).
    #    Solo se muestran: FedEx, Felca, Milling, Clickex, Shipit. Starken y
    #    Blue Express tienen tabla real cargada (148 y 342 comunas) pero
    #    Daniel pidió explícitamente dejarlos apagados (2026-07-25) — no
    #    destrabar sin que lo pida de nuevo.
    def _cotizar_uno(c):
        cid       = c['id']
        nombre    = c['nombre'] or ''
        is_fedex   = ('fedex' in _ttar._strip(nombre).lower())
        is_shipit  = ('shipit' in _ttar._strip(nombre).lower())
        is_clickex = ('clickex' in _ttar._strip(nombre).lower())
        logo      = c.get('logo_url') or c.get('logo_square_url')

        if is_shipit:
            try:
                d = _shipit_cotizacion_dict(cid, nombre, logo)
            except Exception as ex_each:
                print(f"[cotizar courier {nombre}] error: {ex_each}", flush=True)
                d = {
                    "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
                    "tiene_cobertura": False, "fuente": "error",
                    "mensaje": "Error al cotizar",
                }
            d["_slug"] = "shipit"
            return d

        if is_clickex:
            try:
                d = _clickex_cotizacion_dict(cid, nombre, logo)
            except Exception as ex_each:
                print(f"[cotizar courier {nombre}] error: {ex_each}", flush=True)
                d = {
                    "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
                    "tiene_cobertura": False, "fuente": "error",
                    "mensaje": "Error al cotizar",
                }
            d["_slug"] = "clickex"
            return d

        slug = 'fedex_directo' if is_fedex else _ttar.slug_para_courier(nombre)

        if slug not in ('felca', 'milling', 'fedex_directo'):
            return None

        try:
            r = _ttar.cotizar(slug, comuna, peso_fact, valor_neto)
            d = _macro_cotizacion_dict(cid, nombre, logo, slug, r) if r \
                else _no_cobertura_dict(cid, nombre, logo)
        except Exception as ex_each:
            print(f"[cotizar courier {nombre}] error: {ex_each}", flush=True)
            d = {
                "courier_id": cid, "courier_nombre": nombre, "logo_url": logo,
                "tiene_cobertura": False, "fuente": "error",
                "mensaje": "Error al cotizar",
            }
        d["_slug"] = slug
        return d

    # 3) Ejecutar TODAS las cotizaciones en paralelo
    cotizaciones = []
    max_workers = min(len(couriers), 8) or 1
    with _cf.ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures = {pool.submit(_cotizar_uno, c): c for c in couriers}
        try:
            for fut in _cf.as_completed(futures, timeout=10):
                try:
                    cotizaciones.append(fut.result(timeout=0.5))
                except Exception as e_fut:
                    c = futures[fut]
                    cotizaciones.append({
                        "courier_id": c['id'],
                        "courier_nombre": c['nombre'],
                        "logo_url": c.get('logo_url'),
                        "tiene_cobertura": False,
                        "fuente": "error",
                        "mensaje": f"Timeout o error: {e_fut}",
                    })
        except _cf.TimeoutError:
            # Si superamos el timeout global, marcamos los que no respondieron
            for fut, c in futures.items():
                if not fut.done():
                    cotizaciones.append({
                        "courier_id": c['id'],
                        "courier_nombre": c['nombre'],
                        "logo_url": c.get('logo_url'),
                        "tiene_cobertura": False,
                        "fuente": "timeout",
                        "mensaje": "Tiempo de cotización excedido",
                    })

    # Filtrar couriers excluidos (None) y DEDUPLICAR por servicio (_slug): si hay
    # dos couriers en la BD que mapean al mismo servicio (ej. "Milling" y "Melling"),
    # se conserva solo uno — preferimos el que tenga cobertura/logo.
    cotizaciones = [c for c in cotizaciones if c]
    _por_slug = {}
    for c in cotizaciones:
        sl = c.get("_slug") or c.get("courier_nombre")
        prev = _por_slug.get(sl)
        if prev is None:
            _por_slug[sl] = c
        else:
            # preferir el que tiene cobertura; si empatan, el que tiene logo
            mejor = c if (c.get("tiene_cobertura") and not prev.get("tiene_cobertura")) else prev
            if mejor is prev and not prev.get("logo_url") and c.get("logo_url"):
                mejor = c
            _por_slug[sl] = mejor
    cotizaciones = list(_por_slug.values())

    # 4) Ordenar (con cobertura primero, sin cobertura al final) y elegir recomendado
    con_cobertura = [c for c in cotizaciones if c.get('tiene_cobertura')]
    sin_cobertura = [c for c in cotizaciones if not c.get('tiene_cobertura')]
    con_cobertura.sort(key=lambda c: float(c.get('subtotal') or c.get('precio') or 99999999))
    cotizaciones_ord = con_cobertura + sin_cobertura

    recomendado_id = con_cobertura[0]['courier_id'] if con_cobertura else None

    # 5) Marcar tarifas VALIDADAS (consulta única) + INSERT audit por cada cotización.
    #    Esto produce el audit trail completo. Si la tabla audit no existe → silencioso.
    try:
        # Set de tarifas marcadas como validadas para esta comuna (1 sola query)
        validated_keys = set()
        try:
            rows_val = mysql_fetchall(
                "SELECT DISTINCT courier_id, bracket_aplicado "
                "FROM courier_tariff_audit "
                "WHERE LOWER(TRIM(comuna))=LOWER(TRIM(%s)) AND validado=1",
                (comuna,)
            ) or []
            for rv in rows_val:
                validated_keys.add((rv['courier_id'], rv['bracket_aplicado']))
        except Exception:
            pass

        cotizado_por = current_username() or 'sistema'
        for c in cotizaciones_ord:
            trace = c.get('trace') or {}
            cid = c.get('courier_id')
            bracket = trace.get('bracket')
            # Marcar validado si está en el set
            if cid and bracket and (cid, bracket) in validated_keys:
                trace['validado'] = True
                c['trace'] = trace
            # Insertar audit con desglose costo+margen+IVA completo
            try:
                audit_id = _audit_cotizacion(
                    courier_id=cid,
                    courier_nombre=c.get('courier_nombre'),
                    comuna=comuna,
                    peso_kg=peso_kg,
                    peso_pred_kg=peso_pred,
                    bracket_aplicado=bracket or '—',
                    precio_calculado=c.get('precio'),     # precio venta (con margen+IVA)
                    formula_aplicada=trace.get('formula', ''),
                    fuente=c.get('fuente', 'tabla'),
                    validado=trace.get('validado', False),
                    notas=(c.get('mensaje') or None),
                    documento_tido=doc_tido,
                    documento_nudo=doc_nudo,
                    cotizado_por=cotizado_por,
                    desglose=c.get('desglose'),           # ← componentes auditables
                )
                if audit_id:
                    c['audit_id'] = audit_id
            except Exception as ex_aud:
                print(f"[cotizar-couriers] audit error courier={cid}: {ex_aud}", flush=True)
    except Exception as ex_outer:
        print(f"[cotizar-couriers] error audit pass: {ex_outer}", flush=True)

    elapsed = round(_t_start.time() - t0, 3)
    return jsonify({
        "ok":               True,
        "comuna_resuelta":  comuna,
        "peso_facturable":  round(peso_fact, 1),
        "cotizaciones":     cotizaciones_ord,
        "recomendado_id":   recomendado_id,
        "total_couriers":   len(cotizaciones),
        "tiempo_seg":       elapsed,
    })


