def _tr_log(entity_type, entity_id, accion, detalle=""):
    """Registra un evento de trazabilidad en transport_logs."""
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO transport_logs (entity_type,entity_id,accion,detalle,usuario) "
                "VALUES (%s,%s,%s,%s,%s)",
                (entity_type, entity_id, accion, detalle, current_username())
            )
        conn.commit()
    except Exception:
        pass


def _tr_ship_snapshot(item_id, accion, data=None):
    """Agrega un snapshot append-only al respaldo FedEx del item (ship_history_json).

    Es el 'respaldo de que fue cambiado' que pidió Daniel: cada vez que una OT
    FedEx se crea, cancela o re-emite, queda un registro inmutable con el TN
    viejo/nuevo, bultos, usuario y hora Chile. NO falla la operación si el
    respaldo no se puede escribir (deja rastro en stdout).
    """
    try:
        import json as _jp
        row = mysql_fetchone(
            "SELECT ship_history_json FROM transport_manifest_items WHERE id=%s",
            (item_id,))
        hist = []
        if row and row.get("ship_history_json"):
            try:
                hist = _jp.loads(row["ship_history_json"]) or []
            except Exception:
                hist = []
        snap = {"ts": _now_chile_str("%Y-%m-%d %H:%M:%S"),
                "accion": accion, "usuario": current_username()}
        snap.update(data or {})
        hist.append(snap)
        hist = hist[-50:]   # cap: conservar los 50 eventos más recientes
        mysql_execute(
            "UPDATE transport_manifest_items SET ship_history_json=%s WHERE id=%s",
            (_jp.dumps(hist, ensure_ascii=False), item_id))
    except Exception as e:
        print(f"[_tr_ship_snapshot] item {item_id}: {e}", flush=True)


def _tr_fedex_ot_activa(commitment_id):
    """¿Este documento ya tiene una OT/guía FedEx emitida y vigente?

    Daniel 2026-07-22: una vez generada la OT en FedEx, los bultos NO se
    pueden cambiar desde ILUS — habría que cambiarlos también en FedEx y
    quedarían descuadrados (la guía ya se emitió con N bultos). Se bloquea
    la edición en vez de solo marcar la etiqueta como desfasada.

    Devuelve el master_tracking_number (str) si hay OT activa, o None.
    Una OT cancelada (ship_cancelled_at) NO cuenta: ahí sí se puede editar.
    """
    try:
        row = mysql_fetchone(
            "SELECT master_tracking_number FROM transport_manifest_items "
            "WHERE commitment_id=%s AND master_tracking_number IS NOT NULL "
            "  AND master_tracking_number<>'' AND ship_cancelled_at IS NULL "
            "LIMIT 1",
            (commitment_id,))
        return (row or {}).get("master_tracking_number") or None
    except Exception as e:
        # Ante un fallo de consulta NO bloqueamos la edición (degradar abierto):
        # es preferible permitir editar que dejar al operador trabado por un
        # error transitorio de BD. Queda el log para diagnóstico.
        print(f"[tr_fedex_ot_activa] cid={commitment_id}: {e}", flush=True)
        return None


def _tr_fedex_mark_stale(commitment_id, old_bultos, new_bultos):
    """Si cambian los bultos de una factura con OT FedEx activa, marca su etiqueta
    como DESFASADA (no la re-emite: el operador decide con el botón 'Re-emitir').

    Decisión Daniel 2026-06-13: no gastar crédito FedEx automáticamente. Solo se
    marca + loguea + respalda; la re-emisión real es explícita.

    Returns: cantidad de items marcados desfasados.
    """
    try:
        if old_bultos is None or new_bultos is None or int(old_bultos) == int(new_bultos):
            return 0
        items = mysql_fetchall(
            "SELECT id, master_tracking_number FROM transport_manifest_items "
            "WHERE commitment_id=%s AND master_tracking_number IS NOT NULL "
            "  AND master_tracking_number<>'' AND ship_cancelled_at IS NULL "
            "  AND COALESCE(ship_label_outdated,0)=0",
            (commitment_id,)) or []
        for it in items:
            mysql_execute(
                "UPDATE transport_manifest_items SET ship_label_outdated=1 WHERE id=%s",
                (it["id"],))
            _tr_log("manifest_item", it["id"], "Etiqueta FedEx desfasada",
                    f"bultos {old_bultos}→{new_bultos}; TN {it['master_tracking_number']} "
                    "requiere re-emisión")
            _tr_ship_snapshot(it["id"], "bultos_cambiados", {
                "old_bultos": int(old_bultos), "new_bultos": int(new_bultos),
                "tn": it["master_tracking_number"],
                "resultado": "etiqueta marcada desfasada (pendiente re-emitir)"})
        return len(items)
    except Exception as e:
        print(f"[_tr_fedex_mark_stale] commitment {commitment_id}: {e}", flush=True)
        return 0


def _tr_event(manifest_item_id, estado, fuente='manual',
              comentario=None, lat=None, lng=None, payload_json=None,
              commitment_id=None, notify_cliente=True):
    """Registra UN evento de tracking en transport_tracking_events (append-only).

    Esta tabla es la línea de tiempo visible en el tracking público del cliente
    final y la base para auditoría/OTIF futura. Es complementaria a
    `transport_logs` (auditoría interna): `transport_logs` es opaco al cliente;
    `transport_tracking_events` es lo que se publica.

    Args:
        manifest_item_id: id en transport_manifest_items.
        estado: uno de ESTADOS_ENTREGA (no se valida acá; el caller decide).
        fuente: 'manual' | 'chofer' | 'fedex' | 'aftership' | 'sistema'.
        comentario: texto libre (visible al cliente — no incluyas datos internos).
        lat, lng: coordenadas opcionales (chofer marca entrega in-situ).
        payload_json: raw del courier o info adicional (NO visible al cliente).
        commitment_id: para denormalizar y acelerar el query público; si no se
            pasa, se intenta resolver con un SELECT.

    Returns:
        id del evento creado, o None si falló.
    """
    try:
        if commitment_id is None and manifest_item_id:
            r = mysql_fetchone(
                "SELECT commitment_id FROM transport_manifest_items WHERE id=%s",
                (manifest_item_id,)
            )
            commitment_id = (r or {}).get("commitment_id")
        usuario = current_username() if fuente in ('manual', 'chofer') else None
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO transport_tracking_events "
                "(manifest_item_id, commitment_id, estado, fuente, "
                " lat, lng, usuario, comentario, payload_json) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                (manifest_item_id, commitment_id, estado, fuente,
                 lat, lng, usuario, comentario,
                 (json.dumps(payload_json, ensure_ascii=False)
                  if isinstance(payload_json, (dict, list)) else payload_json))
            )
            evt_id = cur.lastrowid
        conn.commit()
        # ── Propagar el estado del manifiesto al compromiso — FUENTE ÚNICA
        # DE VERDAD (2026-07-27, Daniel: "el seguimiento de una factura debe
        # ser único y absoluto — si cambia en el manifiesto, cambia en todos
        # lados, y las BD no deben ser distintas"). Antes SOLO 'Entregado' se
        # propagaba (fix 2026-07-25) — el Monitor podía mostrar 'Pendiente'
        # mientras el manifiesto ya decía 'En preparación'/'En ruta'/etc.
        # Ahora CUALQUIER estado_entrega válido (ESTADOS_ENTREGA) pisa
        # transport_commitments.estado, sea cual sea la fuente (manual,
        # chofer, fedex, simpliroute, sistema). updated_by queda como
        # 'sistema:<fuente>' (nunca 'sync'), por lo que el próximo sync de
        # saldo del ERP NO lo va a pisar (ver el guard `AND updated_by=
        # 'sync'` del CASE del UPSERT en _tr_bulk_sync_erp_mysql) — el saldo
        # financiero del ERP solo manda mientras el documento no tiene
        # todavía movimiento operativo real en un manifiesto.
        # ESTADOS_ENTREGA_VALIDOS (no ESTADOS_ENTREGA): una 'Entrega fallida'
        # reportada por el courier también debe propagarse al documento del
        # Monitor, si no el Monitor y la ficha muestran cosas distintas.
        if estado in ESTADOS_ENTREGA_VALIDOS and commitment_id:
            try:
                with conn.cursor() as cur2:
                    cur2.execute(
                        "UPDATE transport_commitments SET estado=%s, "
                        "updated_by=%s WHERE id=%s",
                        (estado, f"sistema:{fuente}"[:190], commitment_id)
                    )
                conn.commit()
            except Exception as _ce:
                print(f"[tr_event] no se pudo propagar estado '{estado}' al commitment: {_ce}", flush=True)
        # Notificación al cliente (best-effort, no bloquea si falla).
        # 2026-06-14 (Daniel) — estados que notifican al cliente:
        #   En preparación        → al asignar la factura a un manifiesto
        #   Entregado a transporte → al generar la etiqueta FedEx
        #   En ruta / Entregado    → cambios detectados desde FedEx (autopoll)
        #   Entrega fallida/Problema → FedEx reportó problema de entrega, o un
        #                              supervisor marcó "Problema" a mano
        # El anti-spam (600s) en _tr_notificar_cliente evita duplicados.
        if (notify_cliente and commitment_id and
                estado in ('En preparación', 'Entregado a transporte',
                           'En ruta', 'Entregado', 'Entrega fallida', 'Problema')):
            try:
                _tr_notificar_cliente(commitment_id, estado, comentario=comentario)
            except Exception as _ne:
                print(f"[tr_notify] {_ne}", flush=True)
        return evt_id
    except Exception as _ev_err:
        print(f"[tr_event] no se pudo registrar evento: {_ev_err}", flush=True)
        return None


def _tr_notificar_cliente(commitment_id, estado, comentario=None, forzar=False):
    """Envía email al cliente cuando su despacho cambia a un estado clave.
    Best-effort: si no hay email, no envía. Usa el sistema de comunicaciones
    ILUS (branding global, kill switch global y por módulo).
    Anti-spam: solo envía si el último estado notificado es distinto al actual
    (controla con caché in-memory de 5 min — basta para evitar duplicados por
    re-eventos del cron FedEx).
    forzar=True (2026-07-26, reenvío manual desde el modal de detalle): salta
    el anti-spam a propósito — un operador pidió explícitamente reenviar el
    correo de seguimiento, no es un evento automático repetido."""
    # Anti-spam: caché simple
    import time as _t
    if not hasattr(_tr_notificar_cliente, "_cache"):
        _tr_notificar_cliente._cache = {}
    cache = _tr_notificar_cliente._cache
    key = (commitment_id, estado)
    now = _t.time()
    # Limpia entradas viejas
    for k in list(cache.keys()):
        if now - cache[k] > 600:
            cache.pop(k, None)
    if key in cache and not forzar:
        return  # ya notificado recientemente
    cache[key] = now

    c = mysql_fetchone(
        "SELECT id, tido, nudo, cliente_nombre, email, public_token, "
        "       comuna, direccion, fecha_entrega, costo_envio "
        "FROM transport_commitments WHERE id=%s", (commitment_id,))
    if not c or not (c.get("email") or "").strip():
        return
    tok = _tr_ensure_public_token(commitment_id)
    if not tok:
        return
    # FIX 2026-07-25 (Daniel: "los correos de transporte... no está asociado
    # a la realidad"): antes esta función armaba las variables del correo con
    # datos fijos/incompletos -- courier SIEMPRE "FedEx" (mal para Felca/
    # Milling/otros) y sin tracking/direccion/fecha/costo reales. Las
    # plantillas editables en /comunicaciones (TPL_DEFAULTS del front)
    # muestran placeholders como {{numero_seguimiento}}, {{fecha_entrega}},
    # {{direccion_entrega}}, {{costo_envio}}, {{nombre_cliente}} -- si Daniel
    # los usó al editar, salían LITERALES sin reemplazar porque esas keys no
    # existían en `_vars`. Se resuelve el courier/tracking real con la MISMA
    # consulta que ya usa _tracking_payload() para el seguimiento público.
    _mi = mysql_fetchone("""
        SELECT tm.courier, COALESCE(tmi.master_tracking_number, tmi.tracking_number) AS tracking
        FROM transport_manifest_items tmi
        LEFT JOIN transport_manifests tm ON tm.id = tmi.manifest_id
        WHERE tmi.commitment_id=%s
        ORDER BY tmi.id DESC LIMIT 1
    """, (commitment_id,))
    # Sin manifiesto todavía (ej: recién "En preparación") no sabemos el
    # courier real -- mejor un texto neutro que afirmar "FedEx" a ciegas.
    courier_real = ((_mi or {}).get("courier") or "").strip() or "nuestro equipo de despacho"
    tracking_real = ((_mi or {}).get("tracking") or "").strip()
    direccion_real = ", ".join(x for x in [c.get("direccion"), c.get("comuna")] if (x or "").strip())
    fecha_entrega_real = str(c.get("fecha_entrega") or "")[:10]
    costo_envio_real = (f"${int(c['costo_envio']):,}".replace(",", ".")
                        if c.get("costo_envio") else "")
    # FIX 2026-07-24: el fallback anterior devolvía "/t/<tok>" RELATIVO cuando
    # esto corre fuera de un request (cron / hilo daemon) — y un link relativo
    # dentro de un correo NO funciona: el cliente hacía clic y no llegaba a
    # ninguna parte. _public_base_url() ya resuelve esto (usa request.url_root
    # si hay request, y si no, ILUS_PUBLIC_BASE_URL con default a la URL de
    # Cloud Run). Mismo patrón que ya usa Retiros para su link de seguimiento.
    # Crítico ahora que el estado lo va a actualizar un poller en background.
    track_url = f"{_public_base_url()}/t/{tok}"
    # 2026-08-13 (Daniel + auditoría de ChatGPT: "no quiero que solicites el
    # RUT"): además del link directo, se incluye el código corto como
    # respaldo por si el cliente no tiene el correo a mano y quiere volver
    # a /seguimiento a escribirlo manualmente.
    tracking_code = _tr_ensure_tracking_code(commitment_id) or ""
    # FIX 2026-07-26 (Daniel: "el número de seguimiento debería ser 22703" +
    # "para que no nos pisemos con las facturas que vienen con el mismo
    # correlativo"): tido-nudo (mismo patrón de simpliroute_client.py
    # campo "reference") identifica el documento SIEMPRE, con guion -- igual
    # formato que usa ahora _tracking_payload() para el tracking público.
    doc = f"{c.get('tido') or ''}-{c.get('nudo') or ''}".strip("-")
    # Identificador de seguimiento que se muestra al cliente: el tracking
    # REAL del courier si existe: si no (caso normal para Felca/Milling, que
    # no emiten guía clásica sino visita SimpliRoute), cae al mismo doc
    # tipo+número -- nunca se deja vacío.
    seguimiento_display = tracking_real or doc
    cliente = c.get("cliente_nombre") or ""
    from markupsafe import escape as _esc
    # ── Copywriting (Daniel 2026-07-26): cada estado con su propio momento
    # narrativo -- nunca la misma estructura de frase repetida, y sin nombrar
    # sistemas/couriers internos salvo que sea información realmente útil
    # para el cliente (el nombre del courier SÍ se conserva en la fila de
    # detalle "Courier", pero no en el cuerpo prosa). Tono ILUS: directo,
    # cálido, profesional -- mismo que cotizaciones/retiros.
    if estado == 'En preparación':
        asunto = _brand_subject(f"Tu pedido {doc} está en preparación")
        status_label = "Pedido en preparación"
        titulo = "Estamos alistando tu pedido"
        cuerpo = ("Ya tenemos tu pedido en bodega y lo estamos preparando con cuidado "
                  "para el despacho. Apenas esté listo para salir, te avisamos.")
        cta_label = "Seguir mi pedido"
    elif estado == 'Entregado a transporte':
        asunto = _brand_subject(f"Tu pedido {doc} ya salió de bodega")
        status_label = "Pedido despachado"
        titulo = "Tu pedido salió de bodega"
        cuerpo = ("Tu pedido ya salió de nuestras instalaciones y quedó en camino a ti. "
                  "Desde aquí iremos actualizando cada avance en tu seguimiento.")
        cta_label = "Ver seguimiento en vivo"
    elif estado == 'En ruta':
        asunto = _brand_subject(f"Tu pedido {doc} va en camino")
        status_label = "En camino"
        titulo = "Tu pedido va en camino"
        cuerpo = ("Buenas noticias: tu pedido salió a reparto y viene en camino "
                  "hacia tu dirección.")
        cta_label = "Ver seguimiento en vivo"
    elif estado in ('Entrega fallida', 'Problema'):
        asunto = _brand_subject(f"No pudimos entregar tu pedido {doc}")
        status_label = "Problema con la entrega"
        titulo = "No pudimos completar tu entrega"
        _motivo_txt = (comentario or "").strip()
        cuerpo = ("Tuvimos un inconveniente al intentar entregar tu pedido"
                  + (f": {_motivo_txt}." if _motivo_txt else ".")
                  + " Ya estamos coordinando una nueva fecha contigo. "
                    "Si tienes dudas, escríbenos.")
        cta_label = "Ver detalle"
    else:   # Entregado
        asunto = _brand_subject(f"¡Tu pedido {doc} llegó a destino!")
        status_label = "Entregado"
        titulo = "¡Tu pedido llegó a destino!"
        cuerpo = ("Confirmamos la entrega de tu pedido. Si algo no calza con lo "
                  "recibido, escríbenos y lo resolvemos.")
        cta_label = "Ver comprobante de entrega"
    # ── Plantilla EDITABLE (comm_templates / módulo 'transporte') ─────────
    # Si Daniel editó la plantilla en /comunicaciones, su ASUNTO y MENSAJE
    # mandan; si no existe / está apagada / vacía, cae al texto de arriba
    # (REGLA #4.2: el correo nunca deja de salir). El armazón (status, título,
    # botón de seguimiento, courier) se conserva siempre desde el maestro.
    _message_html = str(_esc(cuerpo))   # default: texto fijo, escapado
    _slug = {
        'En preparación':         'programado',
        'Entregado a transporte': 'en_ruta',
        'En ruta':                'en_camino',
        'Entregado':              'entregado',
        'Entrega fallida':        'fallido',
        'Problema':               'fallido',
    }.get(estado, 'entregado')
    try:
        _vars = {
            "cliente":            cliente,
            "nombre_cliente":     cliente,
            "documento":          doc,
            "id_pedido":          doc,
            "track_url":          track_url,
            "courier":            courier_real,
            "comentario":         comentario or "",
            "fecha_entrega":      fecha_entrega_real,
            "direccion_entrega":  direccion_real,
            "costo_envio":        costo_envio_real,
            "numero_seguimiento": seguimiento_display,
            "motivo_falla":       comentario or "El courier no pudo completar la entrega",
        }
        _tpl = _render_comm_template(_slug, "email", _vars, modulo="transporte")
        if _tpl:
            _asu, _cue = _tpl
            if (_asu or "").strip():
                asunto = _brand_subject(_asu.strip())
            if (_cue or "").strip():
                _message_html = _cue   # HTML editable → NO escapar
    except Exception as _e_tpl:
        print(f"[tr_notify] plantilla editable no usada: {_e_tpl}", flush=True)
    # FIX 2026-07-26: el "comentario" que dispara este correo casi siempre es
    # texto OPERATIVO interno (ej. "Reenvío manual solicitado" del botón de
    # reenvío, o el status crudo de FedEx/SimpliRoute) -- no algo que el
    # cliente deba leer entre comillas. Solo en un estado de FALLA el
    # comentario es el motivo real que el cliente necesita conocer.
    if estado in ('Entrega fallida', 'Problema') and (comentario or "").strip():
        _closing = f"«{_esc(comentario)}»"
    else:
        _closing = ("Conserva este correo como referencia. El enlace de seguimiento es personal "
                    "y contiene información asociada a tu pedido.")
    # FIX 2026-07-26 (Daniel: "el número de seguimiento debería ser 22703"):
    # una sola fila de identificador -- si hay tracking real del courier se
    # muestra como "N° de seguimiento"; si no, "N° de documento" con el mismo
    # tido-nudo que ya se usa en el asunto/título (nunca se duplica el mismo
    # dato con dos etiquetas distintas).
    _id_row = ("N° de seguimiento", seguimiento_display) if tracking_real else ("N° de documento", doc)
    html = _ilus_email_master({
        "subject":           asunto,
        "preheader":         cuerpo[:100],
        "status_label":      status_label,
        "title":             titulo,
        "subtitle":          "Actualización de despacho · ILUS Fitness",
        "customer_name":     cliente,
        "message":           _message_html,
        "detail_rows_html":  _ilus_email_rows([r for r in [
                                 _id_row,
                                 ("Courier", courier_real),
                                 ("Dirección de entrega", direccion_real) if direccion_real else None,
                                 ("Entrega estimada", fecha_entrega_real) if fecha_entrega_real else None,
                                 ("Código de seguimiento ILUS", tracking_code) if tracking_code else None,
                             ] if r]),
        "primary_cta_url":   track_url,
        "primary_cta_label": cta_label,
        "closing_message":   _closing,
    })
    _send_ilus_email(c["email"].strip(), asunto, html,
                     evento=f"tracking_{estado.lower().replace(' ','_')}",
                     modulo="transporte", asincrono=True)


def _ilus_email_html_tracking(titulo, cliente, doc, cuerpo, track_url, comentario=None):
    """COMPAT: delega en el maestro ILUS. (Antes tenía su propia plantilla con
    el correo viejo; quedó sin uso al migrar _tr_notificar_cliente, pero se
    mantiene la firma por si algún caller externo la usa.)"""
    from markupsafe import escape as _esc
    return _ilus_email_master({
        "title":             titulo,
        "subtitle":          "Actualización de despacho · ILUS Fitness",
        "customer_name":     cliente or "",
        "message":           str(_esc(cuerpo or "")),
        "detail_rows_html":  _ilus_email_rows([("N° de documento", doc)]),
        "primary_cta_url":   track_url,
        "primary_cta_label": "Ver seguimiento en vivo",
        "closing_message":   (f"«{_esc(comentario)}»" if comentario else ""),
    })


def _tr_ensure_public_token(commitment_id):
    """Garantiza que el commitment tenga su token público (lo crea lazy si falta).

    El token vive en transport_commitments.public_token (URL-safe, 40 chars).
    Lo atamos al commitment, NO al manifest_item, para que el link sobreviva si
    la factura se mueve de un manifiesto a otro. Devuelve el token (o None si
    falló crearlo).
    """
    try:
        r = mysql_fetchone(
            "SELECT public_token FROM transport_commitments WHERE id=%s",
            (commitment_id,)
        )
        if not r:
            return None
        tok = (r.get("public_token") or "").strip()
        if tok:
            return tok
        # Generar y persistir. UNIQUE KEY garantiza unicidad; si llegásemos a
        # colisionar (probabilidad ~0 con 40 chars URL-safe), reintenta.
        for _ in range(3):
            new_tok = secrets.token_urlsafe(30)[:40]
            try:
                mysql_execute(
                    "UPDATE transport_commitments SET public_token=%s WHERE id=%s",
                    (new_tok, commitment_id)
                )
                return new_tok
            except Exception:
                continue
        return None
    except Exception as _tok_err:
        print(f"[tr_token] no se pudo generar token: {_tok_err}", flush=True)
        return None


# Alfabeto sin caracteres ambiguos al dictarlo/tipearlo a mano (sin 0/O,
# 1/I/L). 32 símbolos → 8 caracteres random ≈ 32^8 ≈ 1.1 billones de
# combinaciones, protegido además por rate-limit en /seguimiento.
_TR_TRACKING_CODE_ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"


def _tr_generar_tracking_code() -> str:
    """Genera un código tipo 'ILUS-7K9M-42QF' (8 chars random en 2 bloques)."""
    chars = "".join(secrets.choice(_TR_TRACKING_CODE_ALPHABET) for _ in range(8))
    return f"ILUS-{chars[:4]}-{chars[4:]}"


def _tr_normalizar_tracking_code(raw: str) -> str:
    """Normaliza lo que el cliente tipeó: mayúsculas, sin espacios/guiones/
    prefijo 'ILUS'. El alfabeto de generación (_TR_TRACKING_CODE_ALPHABET)
    ya excluye 0/1/I/L/O a propósito -- ningún código real los contiene,
    así que no hace falta (ni conviene) "corregir" esos caracteres acá:
    mapearlos entre sí no ayudaría a matchear nada, porque ninguno de los
    dos existe jamás en un código real."""
    s = (raw or "").strip().upper()
    s = re.sub(r"[^A-Z0-9]", "", s)
    if s.startswith("ILUS"):
        s = s[4:]
    return s


def _tr_ensure_tracking_code(commitment_id):
    """Garantiza que el commitment tenga su código corto de seguimiento
    (lo crea lazy si falta). Mismo criterio que _tr_ensure_public_token:
    vive en transport_commitments, no en el manifest_item, para sobrevivir
    reasignaciones. Devuelve el código (ej. 'ILUS-7K9M-42QF') o None si falló.
    """
    try:
        r = mysql_fetchone(
            "SELECT tracking_code FROM transport_commitments WHERE id=%s",
            (commitment_id,)
        )
        if not r:
            return None
        code = (r.get("tracking_code") or "").strip()
        if code:
            return code
        for _ in range(5):
            new_code = _tr_generar_tracking_code()
            try:
                mysql_execute(
                    "UPDATE transport_commitments SET tracking_code=%s WHERE id=%s",
                    (new_code, commitment_id)
                )
                return new_code
            except Exception:
                continue
        return None
    except Exception as _code_err:
        print(f"[tr_tracking_code] no se pudo generar código: {_code_err}", flush=True)
        return None


def _norm_comuna_key(s: str) -> str:
    return (s or "").upper().replace("Ñ", "N").replace("Á", "A").replace("É", "E") \
        .replace("Í", "I").replace("Ó", "O").replace("Ú", "U")


def _detect_comuna(text: str) -> str:
    """Detecta una comuna chilena conocida dentro de texto libre (OBDO/dirección).
    Devuelve el nombre de la comuna (title-case) o '' si no encuentra."""
    if not text:
        return ""
    norm = _norm_comuna_key(text)
    best = ""
    for key in _COMUNA_POSTAL:  # claves ya normalizadas (upper, sin acentos)
        if len(key) < 4:
            continue
        if key in norm and len(key) > len(best):
            best = key
    return best.title() if best else ""


def _parse_obdo(obdo: str) -> dict:
    """Parsea texto libre OBDO: 'Nombre - dirección [comuna] - teléfono - email'.

    Extrae nombre cuando el ERP devuelve cliente genérico (BOLETA/CONSUMIDOR
    FINAL/PARTICULAR) en boletas — el dato real va en OBDO/TEXTO1.
    """
    import re as _re
    result = {"direccion": "", "telefono": "", "email": "", "comuna": "", "nombre": ""}
    if not obdo:
        return result
    original = obdo
    email_m = _re.search(r'[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}', obdo)
    if email_m:
        result["email"] = email_m.group(0)
        obdo = obdo.replace(email_m.group(0), "")
    phone_m = _re.search(r'\b[\+56]*\s*[29]\d{7,8}\b', obdo)
    if phone_m:
        result["telefono"] = phone_m.group(0).strip()
        obdo = obdo.replace(phone_m.group(0), "")
    # Intentar separar nombre + dirección. Heurística: si arranca con
    # palabras alfabéticas (no dígitos), el primer trozo antes de un
    # separador típico (/, -, –, ,) o salto de línea ES el nombre.
    rest = _re.sub(r'[-–]+\s*$', '', obdo).strip(' -–\n')
    name_dir_m = _re.match(
        r'^\s*([A-Za-zÁÉÍÓÚÑáéíóúñ][A-Za-zÁÉÍÓÚÑáéíóúñ\.\' ]{1,60})\s*[/\-–,\n]\s*(.+)$',
        rest
    )
    if name_dir_m:
        candidato = name_dir_m.group(1).strip()
        resto     = name_dir_m.group(2).strip()
        # Si el candidato tiene pinta de calle (Av., Calle, Pasaje, etc.) NO es nombre
        if not _re.match(r'^(av\.?|avenida|calle|psje\.?|pasaje|camino|ruta|carretera|los|las|el|la)\b',
                         candidato, _re.IGNORECASE):
            result["nombre"]    = candidato
            result["direccion"] = resto
        else:
            result["direccion"] = rest
    else:
        result["direccion"] = rest
    result["comuna"] = _detect_comuna(original)
    return result


# Tokens de ruido típicos en la parte local de un email (no son nombre).
_EMAIL_NOISE_TOKENS = {
    "fb", "ig", "tw", "site", "web", "mail", "email", "cl", "com", "net",
    "gmail", "hotmail", "yahoo", "outlook", "live", "icloud", "duocuc",
}
# Buzones genéricos: no representan a una persona.
_EMAIL_GENERIC_LOCAL = {
    "info", "ventas", "contacto", "compras", "hola", "soporte", "admin",
    "noreply", "no-reply", "cobranza", "facturacion", "pagos", "gerencia",
}


def _name_from_email(email: str) -> str:
    """Deriva un nombre legible desde la parte local de un email cuando el ERP
    NO entrega entidad (boletas web a consumidor final, ~75% de las BLV).

    Ej: 'scarleth.ortiz.urra@gmail.com' -> 'Scarleth Ortiz Urra'.
    Devuelve '' si la parte local no parece nombre de persona
    (buzón genérico tipo 'ventas@', o un handle puramente numérico)."""
    if not email or "@" not in email:
        return ""
    import re as _re
    local = email.split("@", 1)[0].strip().lower()
    if not local or local in _EMAIL_GENERIC_LOCAL:
        return ""
    out = []
    for p in _re.split(r"[._\-+]+", local):
        p = _re.sub(r"\d+$", "", p)          # 'juan2024' -> 'juan'
        if len(p) >= 2 and p.isalpha() and p not in _EMAIL_NOISE_TOKENS:
            out.append(p.capitalize())
    nombre = " ".join(out[:3])
    return nombre if len(nombre) >= 3 else ""


# ════════════════════════════════════════════════════════════════════════
# NORMALIZADOR ERP RANDOM — UNA SOLA FUENTE DE VERDAD
# ════════════════════════════════════════════════════════════════════════
# Decisión arquitectónica Daniel 2026-05-31:
# - Cubicador, Asignar/Cotizar, Transporte y Manifiestos deben leer DATOS
#   LIMPIOS del ERP. Nunca propagar placeholders como "BOLETA" (RUT),
#   "ERP_ENVIO" (dirección), "CONSUMIDOR FINAL" (nombre), etc.
# - Esta lista es la blacklist canónica. Cualquier valor que comparado en
#   uppercase + trim entra acá → se trata como vacío.
# ════════════════════════════════════════════════════════════════════════

ERP_PLACEHOLDERS = {
    # Nombres genéricos
    "BOLETA", "BOLETA DE VENTA", "CONSUMIDOR FINAL", "CONSUMIDORFINAL",
    "CLIENTE FINAL", "CLIENTE GENERICO", "CLIENTE GENÉRICO", "GENERICO",
    "GENÉRICO", "PARTICULAR", "VARIOS", "PUBLICO GENERAL", "PÚBLICO GENERAL",
    # Direcciones placeholder
    "ERP_ENVIO", "ERP ENVIO", "ENVIO", "ENVÍO", "DESPACHO", "RETIRO",
    "RETIRO EN TIENDA", "RETIRO EN BODEGA", "SIN DIRECCION", "SIN DIRECCIÓN",
    # Comunas vacías
    "SIN COMUNA", "S/I", "N/A", "NA", "NULL", "NONE",
    # RUTs falsos
    "11111111-1", "111111111", "1-9", "00000001-9", "0-0",
    "00.000.001-9", "99.999.999-9",
    # Email/teléfono dummy
    "EMAIL@EJEMPLO.CL", "EMAIL@EJEMPLO.COM", "0", "00000000",
}

# RUTs base genéricos del ERP Random (cuerpo sin DV)
ERP_PLACEHOLDER_RUT_BASES = {"1", "11", "99", "999", "9999", "0", "00000001"}


def _erp_is_placeholder(value) -> bool:
    """True si el valor es un placeholder del ERP (debería tratarse como vacío)."""
    if value is None:
        return True
    s = str(value).strip()
    if not s:
        return True
    return s.upper() in ERP_PLACEHOLDERS


def _erp_clean(value, fallback=""):
    """Devuelve el valor o fallback si es placeholder/vacío."""
    if _erp_is_placeholder(value):
        return fallback
    return str(value).strip()


def _erp_is_placeholder_rut(rut: str) -> bool:
    """True si el RUT es un placeholder del ERP."""
    if not rut:
        return True
    s = str(rut).strip().upper()
    if s in ERP_PLACEHOLDERS:
        return True
    # Limpiar puntos/guiones y verificar cuerpo
    import re as _re
    clean = _re.sub(r'[^\dkK]', '', s)
    if not clean or len(clean) < 8:
        return True
    cuerpo = clean[:-1].lstrip("0") or "0"
    return cuerpo in ERP_PLACEHOLDER_RUT_BASES


# Texto canónico cuando el ERP no entrega cliente real. UNA sola constante
# para que todos los caminos usen exactamente el mismo string.
ERP_NO_CLIENT = "Cliente no informado por ERP"


def _erp_is_placeholder_name(name) -> bool:
    """True si NO es un nombre de cliente real: placeholder del ERP, el texto
    canónico ERP_NO_CLIENT (en cualquier capitalización), o un código numérico
    puro (ej. SUENDO '000411', que el ERP usa como subcliente, NO como nombre)."""
    if _erp_is_placeholder(name):
        return True
    s = str(name).strip()
    if not s:
        return True
    if s.lower() == ERP_NO_CLIENT.lower():
        return True
    import re as _re
    # Código numérico puro (dígitos, puntos, guiones, espacios) → no es nombre
    if _re.fullmatch(r'[\d.\-\s]+', s):
        return True
    return False


def _clasif_from_skus(skus):
    """Determina la clasificación de un compromiso según sus SKUs ZZ."""
    skus = [s.strip().upper() for s in skus if s]
    if not skus: return "despacho"
    if all(s == "ZZRETIRO" for s in skus): return "retiro"
    if any(s == "ZZINSTALACION" for s in skus): return "instalacion"
    if any(s in ("ZZSERVTEC", "ZZINGREPUESTO", "ZZINGARREQUIP") for s in skus): return "mantencion"
    return "despacho"


# Orden determinístico de ramos (no depende del orden de aparición de los
# SKUs en el documento) — despacho primero por ser el más común. Compartido
# entre _clasifs_from_skus_multi y cualquier código que necesite ordenar
# ramos de forma consistente (ej. la grilla del Monitor en PR-B).
_ORDEN_RAMOS = {"despacho": 0, "instalacion": 1, "mantencion": 2, "retiro": 3, "garantia": 4}


def _clasifs_from_skus_multi(skus):
    """Fase 1, PR-B (2026-08-01) — decisión de Daniel (2026-07-31): una
    factura con ZZENVIO+ZZINSTALACION debe generar DOS asignaciones
    independientes, no una. `_clasif_from_skus` (arriba) NO se toca: sigue
    siendo la fuente de transport_commitments.clasificacion (1 valor por
    documento, para no romper nada que ya dependa de esa columna histórica).

    Esta función es la que usan los 4 write-sites de PR-B para decidir
    CUÁNTOS manifest_items crear: devuelve TODOS los ramos presentes en vez
    de colapsar a uno con prioridad.

    Devuelve una lista ORDENADA (ver _ORDEN_RAMOS) y sin duplicados, ej.
    ["despacho","instalacion"]. Nunca vacía: sin SKUs ZZ reconocidos, cae a
    ["despacho"] — mismo default que _clasif_from_skus.
    """
    skus = [s.strip().upper() for s in skus if s]
    ramos = set()
    for sku in skus:
        if sku == "ZZRETIRO":
            ramos.add("retiro")
        elif sku == "ZZINSTALACION":
            ramos.add("instalacion")
        elif sku in ("ZZSERVTEC", "ZZINGREPUESTO", "ZZINGARREQUIP"):
            ramos.add("mantencion")
        elif sku.startswith("ZZ"):
            # ZZENVIO y cualquier otro SKU ZZ no reconocido específicamente
            # -- mismo fallback que _clasif_from_skus.
            ramos.add("despacho")
    if not ramos:
        ramos.add("despacho")
    return sorted(ramos, key=lambda r: _ORDEN_RAMOS.get(r, 99))


def _tr_ramos_de_commitment(commitment_id):
    """Ramos presentes en un commitment YA guardado, leyendo su columna
    `zz_skus` persistida (VARCHAR compacto tipo "ZZENVIO,ZZRETIRO", ya
    poblada por el sync — ver app.py:2652-2659) -- NO vuelve a tocar el ERP.
    Usada por los 4 write-sites de PR-B para decidir cuántas asignaciones
    crear al mandar un documento a un manifiesto."""
    row = mysql_fetchone(
        "SELECT zz_skus FROM transport_commitments WHERE id=%s", (commitment_id,))
    zz_skus_raw = (row.get("zz_skus") if row else "") or ""
    skus = [s.strip() for s in zz_skus_raw.split(",") if s.strip()]
    return _clasifs_from_skus_multi(skus)


# Etiqueta legible por ramo -- para armar mensajes de error/aviso sin repetir
# el mismo mapeo en cada write-site (PR-B, 2026-08-01).
_RAMO_LABELS = {
    "despacho": "despacho", "instalacion": "instalación", "retiro": "retiro",
    "mantencion": "mantención", "garantia": "garantía",
}


def _tr_ramo_label(ramo):
    return _RAMO_LABELS.get(ramo, ramo or "despacho")


def _tr_nudo_display(nudo):
    """Número de documento SIN ceros a la izquierda, solo para MOSTRAR.

    Daniel 2026-08-02: "quería también eliminar lo que son todos los ceros a
    la izquierda de la factura, boleta, guía, notas de venta, todo".
    '0000011149' -> '11149'.

    ⚠️ NUNCA usar el resultado para buscar, comparar ni construir claves: el
    nudo real conserva el padding del ERP y es parte de la clave única
    (tido, nudo) de transport_commitments -- perder el padding fue
    exactamente la causa raíz de los commitments duplicados (BLV 22719/
    22727/22728, ver nudo_canonico en _tr_fetch_from_erp).

    Las notas de venta traen prefijo de letras ('VD00010223'): se conserva el
    prefijo y solo se recortan los ceros del bloque de dígitos.
    """
    s = str(nudo if nudo is not None else "").strip()
    if not s:
        return ""
    import re as _re_nd
    return _re_nd.sub(r"^([^0-9]*)0+(\d)", r"\1\2", s)


# SKUs que identifican cada ramo -- mismo mapeo que _clasifs_from_skus_multi,
# pero expresado como fragmento SQL parametrizado (Monitor, 2026-08-01,
# Daniel: reestructuración por ramo). Se usa para NO depender solo de
# transport_commitments.clasificacion (columna de 1 solo valor, colapsada por
# prioridad -- ver _clasif_from_skus) al filtrar por ramo: un documento con
# zz_skus='ZZENVIO,ZZINSTALACION' tiene clasificacion='instalacion' (gana
# prioridad) y quedaría invisible en el filtro de Despacho si solo se mirara
# esa columna. Acá se agrega un OR contra zz_skus para que aparezca en AMBOS.
# Bodega PRINCIPAL de despacho (2026-08-02, Daniel: "la bodega dos, que es la
# principal... la bodega doce, que es del gimnasio"). Cualquier documento cuyo
# producto salga de otra bodega se marca con advertencia en la fila del
# Monitor. Configurable por entorno para no tener que tocar código si la
# empresa cambia de bodega principal.
TR_BODEGA_PRINCIPAL = os.environ.get("ILUS_TR_BODEGA_PRINCIPAL", "2").strip()

# ── Nombres de bodega (2026-08-17, Daniel) ───────────────────────────────
# Textual: "todas las ventas salen de la bodega 02 pero existen bodegas de
# liquidacion 15, Incidencias 13, Motion Vitacura 06 y Motion la dehesa 05.
# Repuestos 18... que el usuario sepa que hay una excepcion ya que el 98%
# sale de la 02".
#
# Hasta hoy la advertencia mostraba SOLO el número ("BOD 06"), que no le dice
# nada a quien prepara el despacho. Con el nombre, la persona entiende de una
# que ese equipo NO está en la bodega principal y que tiene que ir a buscarlo
# a otro lado (o coordinar el traslado) antes de dar el despacho por armado.
#
# La clave es el número SIN ceros a la izquierda: el ERP devuelve "02"/"06" y
# acá se compara normalizado (ver _tr_bodega_norm). La 12 sale del caso
# histórico del 2026-08-02 (bodega del gimnasio).
TR_BODEGAS_NOMBRES = {
    "2":  "Principal",
    "5":  "Motion La Dehesa",
    "6":  "Motion Vitacura",
    # La 12 ya avisaba (cualquier bodega != principal avisa). Daniel pidió
    # explícitamente nombrarla el 2026-08-17 — es el gimnasio propio de ILUS,
    # y fue el caso que originó toda esta advertencia el 2026-08-02 (FCV
    # 0000011149: "esa factura la sacaron no de la bodega dos, que es la
    # principal, sino de la bodega doce, que es del gimnasio").
    "12": "Gimnasio ILUS",
    "13": "Incidencias",
    "15": "Liquidación",
    "18": "Repuestos",
}


def _tr_bodega_norm(codigo):
    """Código de bodega comparable: '02' → '2', '  06 ' → '6', '' → ''.

    El ERP rellena con ceros a la izquierda. Comparar '02' contra '2' daba
    advertencia en TODAS las filas, incluida la bodega principal (bug real
    del 2026-08-02). Se normaliza SIEMPRE antes de comparar o de buscar el
    nombre.
    """
    s = str(codigo or "").strip()
    return s.lstrip("0") or ("0" if s else "")


def _tr_bodega_nombre(codigo):
    """Nombre legible de una bodega: '06' → 'Motion Vitacura'.

    Devuelve '' si el código no está en el diccionario — una bodega nueva del
    ERP no puede romper la pantalla ni inventarle un nombre. En ese caso la
    UI muestra solo el número, que sigue siendo información útil.
    """
    return TR_BODEGAS_NOMBRES.get(_tr_bodega_norm(codigo), "")


def _tr_bodega_label(codigo):
    """Etiqueta completa para la UI: '06' → 'Bodega 06 · Motion Vitacura'.

    Se conserva el código TAL COMO VINO del ERP (con sus ceros) porque es lo
    que la persona va a ver en Random si lo va a chequear; el nombre es la
    ayuda, no el reemplazo.
    """
    cod = str(codigo or "").strip()
    if not cod:
        return ""
    nom = _tr_bodega_nombre(cod)
    return f"Bodega {cod} · {nom}" if nom else f"Bodega {cod}"


def _tr_bodegas_analizar(bodegas):
    """Analiza las bodegas de origen de un documento y arma la advertencia.

    Pedido de Daniel (2026-08-17): "necesito que me avisaras cuando una
    factura cuente con una bodega distinta a la bodega 02, que le avise al
    usuario para que sepa que no debe avanzar sacando el producto de la
    bodega 02 siendo que tiene que sacar lo de una bodega distinta".

    `bodegas` acepta lo que haya a mano, sin que el caller tenga que
    normalizar: el string separado por comas que guarda
    transport_commitments.bodegas ("02,06"), o una lista de códigos.

    Devuelve SIEMPRE el mismo dict (nunca None, nunca lanza) para que la UI
    no tenga que preguntar si vino o no:
      alerta      -> bool: hay al menos una bodega distinta a la principal
      principal   -> código normalizado de la bodega principal
      codigos     -> lista de códigos tal como vinieron, sin repetir
      excepciones -> [{codigo, nombre, label}] solo las distintas a la principal
      resumen     -> texto corto listo para un badge ("Motion Vitacura")
      mensaje     -> frase completa para una alerta o un tooltip
    """
    if isinstance(bodegas, str):
        crudos = [b.strip() for b in bodegas.split(",") if b.strip()]
    elif bodegas:
        crudos = [str(b).strip() for b in bodegas if str(b or "").strip()]
    else:
        crudos = []

    # Sin repetir, conservando el orden en que llegaron (el ERP ya los ordena).
    vistos, codigos = set(), []
    for c in crudos:
        n = _tr_bodega_norm(c)
        if n not in vistos:
            vistos.add(n)
            codigos.append(c)

    principal = _tr_bodega_norm(TR_BODEGA_PRINCIPAL)
    excepciones = [{
        "codigo": c,
        "nombre": _tr_bodega_nombre(c),
        "label":  _tr_bodega_label(c),
    } for c in codigos if _tr_bodega_norm(c) != principal]

    if excepciones:
        # El nombre manda en el resumen (es lo que la persona reconoce); si la
        # bodega no está en el diccionario, cae al número.
        partes = [e["nombre"] or f"Bodega {e['codigo']}" for e in excepciones]
        resumen = " · ".join(partes)
        detalle = ", ".join(e["label"] for e in excepciones)
        mensaje = (
            f"Este documento tiene producto en {detalle}. "
            f"No lo saques de la bodega {TR_BODEGA_PRINCIPAL.zfill(2)} — "
            f"revisa en el ERP de dónde sale cada equipo antes de despachar."
        )
    else:
        resumen = ""
        mensaje = ""

    return {
        "alerta":      bool(excepciones),
        "principal":   principal,
        "codigos":     codigos,
        "excepciones": excepciones,
        "resumen":     resumen,
        "mensaje":     mensaje,
    }

