@app.route("/transporte/manifiestos/<int:mid>/etiquetas-fedex/pdf")
@_tr_required
def tr_manifiesto_etiquetas_fedex_pdf(mid):
    """PDF único concatenando TODAS las etiquetas FedEx (4x6 PDF) del manifiesto.

    Lee `ship_label_b64` de cada item con OT FedEx creada (formato PDF),
    los une página por página con pypdf y devuelve un solo PDF para imprimir
    en bloque. Items sin etiqueta o con formato no-PDF (ZPL/PNG/EPL) se
    omiten silenciosamente — quedan reportados en el log.
    """
    manifiesto = mysql_fetchone(
        "SELECT id, correlativo, courier FROM transport_manifests WHERE id=%s", (mid,))
    if not manifiesto:
        return "Manifiesto no encontrado", 404

    rows = mysql_fetchall(
        "SELECT mi.id, c.tido, c.nudo, mi.master_tracking_number, "
        "       mi.ship_label_b64, mi.ship_labels_json, mi.ship_label_format, "
        "       mi.piece_trackings_json, mi.ship_bultos, "
        "       mi.ship_cancelled_at "
        "FROM transport_manifest_items mi "
        "LEFT JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.manifest_id=%s "
        "ORDER BY mi.orden, mi.id", (mid,)) or []

    if not rows:
        return "Manifiesto sin items", 400

    # Junta TODAS las etiquetas (una por bulto) de los items vivos y arma un
    # único PDF 4×6 (cada página recortada al tamaño térmico).
    all_labels = []
    omitidos = []
    for r in rows:
        if r.get("ship_cancelled_at"):
            omitidos.append(f"{r['tido']}{r['nudo']} (cancelado)")
            continue
        labs = _fedex_item_labels(r)
        if not labs:
            omitidos.append(f"{r['tido']}{r['nudo']} (sin etiqueta)")
            continue
        all_labels.extend(labs)

    if not all_labels:
        msg = "No hay etiquetas FedEx para imprimir."
        if omitidos:
            msg += " Omitidos: " + ", ".join(omitidos[:5])
            if len(omitidos) > 5:
                msg += f" (+{len(omitidos)-5} más)"
        return msg, 400

    try:
        data, incluidos, _omit_render = _fedex_labels_to_4x6_pdf(all_labels)
    except Exception as e:
        print(f"[etiquetas-fedex pdf] {type(e).__name__}: {e}", flush=True)
        return f"Error generando PDF: {type(e).__name__}", 500
    if not data:
        return "No se pudieron rasterizar las etiquetas.", 500

    _tr_log("manifest", mid, "etiquetas fedex pdf",
            f"{incluidos} etiquetas · {len(omitidos)} items omitidos")

    corr = manifiesto.get("correlativo") or mid
    fname = f"etiquetas_fedex_manifiesto_{corr}.pdf"
    return Response(data, mimetype="application/pdf", headers={
        "Content-Disposition": f'inline; filename="{fname}"'
    })


def _fedex_label_to_png_datauri(label_b64, label_fmt="PDF", dpi=203):
    """Rasteriza una etiqueta FedEx (PDF) a PNG y devuelve un data-URI listo
    para <img>. Esto permite mostrarla en una página HTML de EXACTAMENTE
    100×150 mm (4×6") y que al imprimir salga "cortada" al tamaño de la
    etiqueta térmica — sin que el navegador la escale a carta/A4.

    dpi=203 = densidad estándar de impresora térmica Zebra (4×6" → 812×1218 px),
    así el barcode queda nítido y escaneable.

    Args:
        label_b64: etiqueta en base64 (como viene de ship_label_b64).
        label_fmt: 'PDF' | 'PNG' | 'ZPLII' | 'EPL2'.

    Returns:
        (datauri, None) en éxito · (None, "motivo") si no se pudo rasterizar.
    """
    import base64 as _b64
    if not label_b64:
        return None, "sin etiqueta"
    fmt = (label_fmt or "PDF").upper()
    try:
        raw = _b64.b64decode(label_b64)
    except Exception:
        return None, "etiqueta corrupta"

    # PNG ya viene como imagen — se embebe directo.
    if fmt == "PNG":
        return "data:image/png;base64," + label_b64, None

    # ZPL/EPL son lenguajes de impresora térmica, no se rasterizan acá.
    if fmt in ("ZPLII", "EPL2"):
        return None, f"formato {fmt} (térmico, no previsualizable)"

    # PDF → PNG. Primario: pypdfium2 (autocontenido, no necesita poppler — clave
    # porque el build de prod por buildpacks NO instala poppler-utils). Fallback:
    # pdf2image/poppler (solo si está disponible, ej. build con Dockerfile).
    img, err = _pdf_first_page_to_pil(raw, dpi=dpi)
    if img is None:
        return None, err or "no se pudo rasterizar"
    try:
        # Auto-recorte: FedEx a veces entrega la etiqueta 4×6 dentro de una hoja
        # carta (8.5×11) con el resto en blanco. Recortamos al contenido real
        # para que SIEMPRE salga "cortada" al tamaño de la etiqueta, sin importar
        # el labelStockType con que se generó.
        img = _autocrop_white(img)
        out = io.BytesIO()
        img.save(out, format="PNG")
        out.seek(0)
        b64png = _b64.b64encode(out.getvalue()).decode("ascii")
        return "data:image/png;base64," + b64png, None
    except Exception as e:
        return None, f"PNG falló: {type(e).__name__}"


def _pdf_first_page_to_pil(raw_pdf_bytes, dpi=203):
    """Rasteriza la 1ª página de un PDF a una imagen PIL. Devuelve (img, None) o
    (None, motivo). Intenta pypdfium2 (sin dependencia de sistema) y, si no está,
    cae a pdf2image/poppler.
    """
    _err1 = "n/a"
    # 1) pypdfium2 — wheel autocontenido con PDFium embebido.
    try:
        import pypdfium2 as _pdfium
        pdf = _pdfium.PdfDocument(raw_pdf_bytes)
        try:
            page = pdf[0]
            bmp = page.render(scale=dpi / 72.0)
            return bmp.to_pil(), None
        finally:
            try:
                pdf.close()
            except Exception:
                pass
    except Exception as e_pdfium:
        _err1 = type(e_pdfium).__name__
    # 2) Fallback pdf2image/poppler.
    try:
        from pdf2image import convert_from_bytes
        paginas = convert_from_bytes(raw_pdf_bytes, dpi=dpi, fmt="png",
                                     first_page=1, last_page=1)
        if paginas:
            return paginas[0], None
        return None, "PDF sin páginas"
    except Exception as e_p2i:
        return None, f"render falló (pdfium:{_err1} / poppler:{type(e_p2i).__name__})"


def _pdf_all_pages_to_pil(raw_pdf_bytes, dpi=203, max_pages=200):
    """Rasteriza TODAS las páginas de un PDF a imágenes PIL. Devuelve (list[PIL], None)
    o (None, motivo). Mismo fallback que _pdf_first_page_to_pil (pdfium → poppler).

    Crítico para FedEx CL doméstico: a veces entrega multi-pieza como UN PDF
    multipágina (en lugar de N PDFs en pieceResponses). Sin esto, solo veíamos
    el bulto 1. max_pages evita un PDF maligno colgando el server.
    """
    _err1 = "n/a"
    # 1) pypdfium2.
    try:
        import pypdfium2 as _pdfium
        pdf = _pdfium.PdfDocument(raw_pdf_bytes)
        try:
            n = min(len(pdf), max_pages)
            out = []
            for i in range(n):
                bmp = pdf[i].render(scale=dpi / 72.0)
                out.append(bmp.to_pil())
            return out, None
        finally:
            try:
                pdf.close()
            except Exception:
                pass
    except Exception as e_pdfium:
        _err1 = type(e_pdfium).__name__
    # 2) Fallback pdf2image/poppler.
    try:
        from pdf2image import convert_from_bytes
        paginas = convert_from_bytes(raw_pdf_bytes, dpi=dpi, fmt="png",
                                     first_page=1, last_page=max_pages)
        if paginas:
            return list(paginas), None
        return None, "PDF sin páginas"
    except Exception as e_p2i:
        return None, f"render falló (pdfium:{_err1} / poppler:{type(e_p2i).__name__})"


def _pdf_count_pages(raw_pdf_bytes):
    """Cuenta páginas de un PDF. Delegado a fedex_labels (única fuente)."""
    return _fxlabels.pdf_count_pages(raw_pdf_bytes)


def _pdf_split_pages_b64(raw_pdf_bytes):
    """Parte un PDF multipágina en N PDFs de 1 pág (base64). Delegado a
    fedex_labels (única fuente, usa pypdfium2 — sin dependencia de cryptography)."""
    return _fxlabels.pdf_split_pages_b64(raw_pdf_bytes)


def _autocrop_white(img, pad_px=10, thresh=24):
    """Recorta los márgenes blancos de una imagen, dejando solo el contenido.
    Usado para que una etiqueta FedEx 4×6 embebida en una hoja carta quede
    recortada al tamaño real de la etiqueta. Si todo es blanco, devuelve la
    imagen original sin tocar.

    pad_px: margen de seguridad (px) alrededor del contenido detectado.
    thresh: umbral de "no-blanco" (0-255). Más alto = más tolerante a grises
            tenues / antialias.
    """
    try:
        from PIL import Image as _PILImage, ImageChops
        rgb = img.convert("RGB")
        bg = _PILImage.new("RGB", rgb.size, (255, 255, 255))
        diff = ImageChops.difference(rgb, bg)
        # Amplifica el diff y resta el umbral para ignorar antialiasing tenue.
        diff = ImageChops.add(diff, diff, 2.0, -thresh)
        bbox = diff.getbbox()
        if not bbox:
            return img
        l, t, r, b = bbox
        l = max(0, l - pad_px); t = max(0, t - pad_px)
        r = min(rgb.width,  r + pad_px); b = min(rgb.height, b + pad_px)
        # Sanity: si el recorte es absurdamente pequeño (<20% del área), no
        # recortamos (mejor mostrar todo que una franja).
        if (r - l) * (b - t) < 0.20 * rgb.width * rgb.height:
            return img
        return img.crop((l, t, r, b))
    except Exception:
        return img


def _fedex_item_labels(row):
    """Devuelve TODAS las etiquetas FedEx de un item (una por bulto en multi-pieza).

    Lee ship_labels_json [{tracking_number,label_b64}]; si no existe (OTs creadas
    antes de guardar todas las piezas), cae a la única etiqueta master en
    ship_label_b64. Devuelve list[dict] {tracking_number, label_b64, fmt}.

    CRÍTICO: si el master ship_label_b64 es un PDF MULTIPÁGINA (FedEx CL
    doméstico mete las N etiquetas de un MPS en un solo PDF), lo expandimos
    en N entries. Esto repara TODAS las OTs históricas en BD sin necesidad
    de re-emitir; antes solo se veía el bulto 1.
    """
    import json as _jp, base64 as _b64
    fmt = (row.get("ship_label_format") or "PDF")
    fmt_u = (fmt or "PDF").upper()
    out = []
    raw_json = row.get("ship_labels_json")
    if raw_json:
        try:
            for it in (_jp.loads(raw_json) or []):
                b64 = (it.get("label_b64") or "").strip()
                if b64:
                    out.append({"tracking_number": it.get("tracking_number") or "",
                                "label_b64": b64, "fmt": fmt})
        except Exception:
            out = []
    if not out:
        b64 = (row.get("ship_label_b64") or "").strip()
        if b64:
            out.append({"tracking_number": row.get("master_tracking_number") or "",
                        "label_b64": b64, "fmt": fmt})

    # ── Expansión multipágina (fix retroactivo) ─────────────────────────────
    # Si tenemos UNA sola entrada PDF que en realidad es multipágina, partimos.
    # Cubre OTs viejas guardadas antes del fallback C, sin tocar la BD.
    if len(out) == 1 and fmt_u == "PDF":
        b64 = out[0]["label_b64"]
        try:
            raw_pdf = _b64.b64decode(b64)
        except Exception:
            raw_pdf = b""
        if raw_pdf:
            n_pages = _pdf_count_pages(raw_pdf)
            # Multipágina = el master FedEx trae las N etiquetas dentro.
            # Si ship_bultos está seteado, validamos coherencia (puede ser =N
            # o vacío). Si n_pages es > 1 lo expandimos siempre, porque la
            # única razón realista de un PDF multipágina en este flujo es MPS.
            if n_pages > 1:
                splits = _pdf_split_pages_b64(raw_pdf)
                if len(splits) == n_pages:
                    # tracking numbers piezas: si el row trae piece_trackings_json
                    # usamos esos; si no, dejamos el master como hint para todos
                    # (el cliente verá "X of N" en la etiqueta).
                    piece_tns = []
                    try:
                        pt_raw = row.get("piece_trackings_json")
                        if pt_raw:
                            piece_tns = _jp.loads(pt_raw) or []
                    except Exception:
                        piece_tns = []
                    master_tn = out[0]["tracking_number"]
                    out = []
                    for i, b in enumerate(splits):
                        tn_i = piece_tns[i] if i < len(piece_tns) else master_tn
                        out.append({"tracking_number": tn_i,
                                    "label_b64": b, "fmt": fmt})
    return out


def _fedex_labels_to_4x6_pdf(labels, dpi=203):
    """Arma un PDF multipágina donde cada página es UNA etiqueta FedEx
    rasterizada, auto-recortada y encajada en 4×6" (100×150 mm) exactos.

    Resuelve dos cosas a la vez: que la descarga salga "cortada" (no en hoja
    carta) y que traiga TODOS los bultos (una página por etiqueta).

    labels: list[{label_b64, fmt, tracking_number}].
    Returns: (pdf_bytes, n_incluidas, omitidas:list[str]) o (None, 0, [...]).
    """
    import base64 as _b64
    from PIL import Image as _PILImage
    W, H = int(4 * dpi), int(6 * dpi)   # 812×1218 @ 203 dpi
    pages, omit = [], []

    def _fit_and_append(pil_img):
        """Encaja una imagen en lienzo blanco 4×6 manteniendo proporción."""
        img2 = _autocrop_white(pil_img)
        canvas = _PILImage.new("RGB", (W, H), (255, 255, 255))
        src = img2.convert("RGB")
        scale = min(W / src.width, H / src.height)
        nw, nh = max(1, int(src.width * scale)), max(1, int(src.height * scale))
        src = src.resize((nw, nh), _PILImage.LANCZOS)
        canvas.paste(src, ((W - nw) // 2, (H - nh) // 2))
        pages.append(canvas)

    for i, lab in enumerate(labels, start=1):
        fmt = (lab.get("fmt") or "PDF").upper()
        try:
            raw = _b64.b64decode(lab["label_b64"])
        except Exception:
            omit.append(f"bulto {i}: base64 inválido")
            continue
        if fmt == "PDF":
            # CRÍTICO: PDF puede ser multipágina (FedEx CL doméstico mete las N
            # etiquetas de un MPS en un solo PDF). Rasterizamos TODAS las páginas
            # para que el output tenga una hoja por bulto.
            imgs, err = _pdf_all_pages_to_pil(raw, dpi=dpi)
            if not imgs:
                omit.append(f"bulto {i}: {err or 'no rasterizable'}")
                continue
            for pg in imgs:
                _fit_and_append(pg)
        elif fmt == "PNG":
            try:
                _fit_and_append(_PILImage.open(io.BytesIO(raw)))
            except Exception as e:
                omit.append(f"bulto {i}: {type(e).__name__}")
        else:
            omit.append(f"bulto {i}: formato {fmt}")
    if not pages:
        return None, 0, omit
    buf = io.BytesIO()
    pages[0].save(buf, format="PDF", save_all=True,
                  append_images=pages[1:], resolution=float(dpi))
    return buf.getvalue(), len(pages), omit


@app.route("/transporte/manifiestos/<int:mid>/etiquetas-fedex/print")
@_tr_required
def tr_manifiesto_etiquetas_fedex_print(mid):
    """Vista imprimible de las etiquetas FedEx del manifiesto — estilo módulo
    ILUS de etiquetas (toolbar + selector "qué imprimir" + Ctrl+P).

    Cada etiqueta oficial FedEx se rasteriza a PNG y se muestra en una página
    HTML de EXACTAMENTE 100×150 mm, de modo que al imprimir salga cortada al
    tamaño térmico 4×6" tal como la entrega FedEx (sin escalado del navegador).
    """
    manifiesto = mysql_fetchone(
        "SELECT id, correlativo, courier FROM transport_manifests WHERE id=%s", (mid,))
    if not manifiesto:
        flash("Manifiesto no encontrado", "danger")
        return redirect(url_for("transporte_index"))

    rows = mysql_fetchall(
        "SELECT mi.id, c.tido, c.nudo, mi.master_tracking_number, "
        "       mi.ship_label_b64, mi.ship_labels_json, mi.ship_label_format, "
        "       mi.piece_trackings_json, mi.ship_bultos, "
        "       mi.ship_cancelled_at, c.cliente_nombre, c.comuna "
        "FROM transport_manifest_items mi "
        "LEFT JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.manifest_id=%s "
        "ORDER BY mi.orden, mi.id", (mid,)) or []

    etiquetas = []   # una por BULTO (multi-pieza)
    omitidas  = []   # (doc, motivo) para mostrar aviso
    for r in rows:
        doc = f"{r.get('tido') or ''}{r.get('nudo') or ''}".strip() or f"#{r['id']}"
        if r.get("ship_cancelled_at"):
            omitidas.append({"doc": doc, "motivo": "OT cancelada"})
            continue
        labels = _fedex_item_labels(r)
        if not labels:
            omitidas.append({"doc": doc, "motivo": "sin etiqueta FedEx"})
            continue
        n_tot = len(labels)
        for i, lab in enumerate(labels, start=1):
            datauri, err = _fedex_label_to_png_datauri(lab["label_b64"], lab["fmt"])
            if not datauri:
                omitidas.append({"doc": f"{doc} (bulto {i}/{n_tot})",
                                 "motivo": err or "no previsualizable"})
                continue
            etiquetas.append({
                "item_id":     r["id"],
                "doc":         doc,
                "cliente":     r.get("cliente_nombre") or "—",
                "comuna":      r.get("comuna") or "",
                "tracking":    lab["tracking_number"] or r.get("master_tracking_number") or "",
                "bulto_num":   i,
                "bulto_total": n_tot,
                "img":         datauri,
            })

    _tr_log("manifest", mid, "etiquetas fedex print",
            f"{len(etiquetas)} etiquetas · {len(omitidas)} omitidas")

    return render_template(
        "transporte/etiquetas_fedex_print.html",
        manifiesto = manifiesto,
        etiquetas  = etiquetas,
        omitidas   = omitidas,
        titulo     = f"Etiquetas FedEx · Manifiesto {manifiesto.get('correlativo') or mid}",
        pdf_url    = url_for("tr_manifiesto_etiquetas_fedex_pdf", mid=mid),
    )


@app.route("/transporte/items/<int:item_id>/etiqueta-fedex/print")
@_tr_required
def tr_item_etiqueta_fedex_print(item_id):
    """Vista imprimible (100×150 mm) de la etiqueta FedEx de UN item.
    Reusa el mismo template que la versión por manifiesto."""
    r = mysql_fetchone(
        "SELECT mi.id, c.tido, c.nudo, mi.master_tracking_number, "
        "       mi.ship_label_b64, mi.ship_labels_json, mi.ship_label_format, "
        "       mi.piece_trackings_json, mi.ship_bultos, "
        "       mi.ship_cancelled_at, c.cliente_nombre, c.comuna "
        "FROM transport_manifest_items mi "
        "LEFT JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.id=%s", (item_id,))
    if not r:
        flash("Item no encontrado", "danger")
        return redirect(url_for("transporte_index"))

    doc = f"{r.get('tido') or ''}{r.get('nudo') or ''}".strip() or f"#{r['id']}"
    etiquetas, omitidas = [], []
    if r.get("ship_cancelled_at"):
        omitidas.append({"doc": doc, "motivo": "OT cancelada"})
    else:
        labels = _fedex_item_labels(r)
        if not labels:
            omitidas.append({"doc": doc, "motivo": "sin etiqueta FedEx"})
        else:
            n_tot = len(labels)
            for i, lab in enumerate(labels, start=1):
                datauri, err = _fedex_label_to_png_datauri(lab["label_b64"], lab["fmt"])
                if datauri:
                    etiquetas.append({
                        "item_id":  r["id"], "doc": doc,
                        "cliente":  r.get("cliente_nombre") or "—",
                        "comuna":   r.get("comuna") or "",
                        "tracking": lab["tracking_number"] or r.get("master_tracking_number") or "",
                        "bulto_num":   i,
                        "bulto_total": n_tot,
                        "img":      datauri,
                    })
                else:
                    omitidas.append({"doc": f"{doc} (bulto {i}/{n_tot})",
                                     "motivo": err or "no previsualizable"})

    return render_template(
        "transporte/etiquetas_fedex_print.html",
        manifiesto = None,
        etiquetas  = etiquetas,
        omitidas   = omitidas,
        titulo     = f"Etiqueta FedEx · {doc}",
        pdf_url    = url_for("tr_etiqueta_fedex", item_id=item_id),
    )


@app.route("/transporte/factura/<int:commitment_id>/n-bultos", methods=["POST"])
@_tr_required
def tr_factura_set_bultos(commitment_id):
    """Captura/edita el número de bultos de una factura desde la pantalla de
    etiquetas. Valida que los bultos eliminados no estén ya escaneados.
    Regenera las filas en transport_labels (crea las nuevas, borra las
    excedentes, actualiza bulto_total en las existentes). Idempotente.

    Body JSON: {"n_bultos": 14}
    Response: {"ok": True, "n_bultos": 14, "previo": 1, "total_etiquetas": N}
    """
    body = request.get_json(silent=True) or {}
    try:
        nuevo = int(body.get("n_bultos", 0))
    except Exception:
        return jsonify({"ok": False, "error": "n_bultos inválido"}), 400
    if nuevo < 1 or nuevo > 999:
        return jsonify({"ok": False, "error": "Debe estar entre 1 y 999"}), 400
    try:
        requested_manifest_id = int(body.get("manifest_id") or 0)
    except Exception:
        return jsonify({"ok": False, "error": "manifest_id inválido"}), 400
    try:
        expected_n_bultos = int(body.get("expected_n_bultos") or 0)
    except Exception:
        return jsonify({"ok": False, "error": "expected_n_bultos inválido"}), 400

    fac = mysql_fetchone(
        "SELECT id, COALESCE(n_bultos,1) AS n_bultos, nudo "
        "FROM transport_commitments WHERE id=%s",
        (commitment_id,)
    )
    if not fac:
        return jsonify({"ok": False, "error": "Factura no encontrada"}), 404

    # GATE (Daniel 2026-07-25): la corrección de bultos desde acá SOLO aplica
    # a Felca/Milling. FedEx es un proceso aparte (OT/API con su propio
    # "Re-emitir") y esta corrección no debe tocarlo. Defensa en profundidad:
    # el botón ya se oculta en el HTML si el courier no califica, pero el
    # backend valida igual por si llega la petición por otra vía.
    if requested_manifest_id:
        mrow = mysql_fetchone(
            "SELECT manifest_id FROM transport_manifest_items "
            "WHERE commitment_id=%s AND manifest_id=%s "
            "ORDER BY id DESC LIMIT 1",
            (commitment_id, requested_manifest_id),
        )
        if not mrow:
            return jsonify({
                "ok": False,
                "error": "La factura no pertenece al manifiesto indicado.",
            }), 409
    else:
        mrow = mysql_fetchone(
            "SELECT manifest_id FROM transport_manifest_items "
            "WHERE commitment_id=%s ORDER BY id DESC LIMIT 1",
            (commitment_id,),
        )
    manifest_id = mrow["manifest_id"] if mrow else None
    courier = ""
    if manifest_id:
        mfrow = mysql_fetchone(
            "SELECT courier FROM transport_manifests WHERE id=%s", (manifest_id,)
        )
        courier = (mfrow.get("courier") if mfrow else "") or ""
    if not _tr_courier_permite_editar_bultos(courier):
        return jsonify({
            "ok": False,
            "error": ("La corrección de bultos desde acá solo está disponible "
                      "para Felca y Milling. " +
                      (f"Esta factura es de {courier}: " if courier else "Esta factura aún no tiene courier asignado: ") +
                      "usa el proceso correspondiente."),
        }), 403

    policy = _tr_bultos_edit_policy(
        commitment_id, courier=courier, manifest_id=manifest_id
    )
    if not policy["editable"]:
        return jsonify({
            "ok": False,
            "error": policy["reason"] or "Las etiquetas ya no se pueden editar.",
            "manifest_estado": policy["manifest_estado"],
            "estado_entrega": policy["estado_entrega"],
        }), 409

    actual = int(fac.get("n_bultos") or 1)
    if expected_n_bultos and expected_n_bultos != actual:
        return jsonify({
            "ok": False,
            "error": (
                f"Otro usuario cambió los bultos de {expected_n_bultos} a {actual}. "
                "Recarga las etiquetas antes de volver a editar."
            ),
            "n_bultos_actual": actual,
        }), 409
    if nuevo == actual:
        return jsonify({"ok": True, "n_bultos": nuevo, "previo": actual, "sin_cambio": True})

    # Si bajamos, validar que los bultos a eliminar no estén ya capturados.
    if nuevo < actual:
        try:
            ocupados = mysql_fetchall(
                "SELECT bulto_num, estado FROM transport_labels "
                "WHERE commitment_id=%s AND manifest_id=%s AND bulto_num > %s "
                "  AND estado IS NOT NULL AND estado <> 'generada'",
                (commitment_id, manifest_id or 0, nuevo),
            ) or []
        except Exception:
            ocupados = []
        if ocupados:
            nums = ", ".join(str(o["bulto_num"]) for o in ocupados)
            return jsonify({
                "ok": False,
                "error": (f"No se puede bajar a {nuevo}: los bultos {nums} "
                          "ya fueron procesados (escaneados/en ruta/entregados). "
                          "Revierte esos estados primero o sube el número.")
            }), 409

    # Update del n_bultos en la factura
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE transport_commitments SET n_bultos=%s "
                "WHERE id=%s AND COALESCE(n_bultos,1)=%s",
                (nuevo, commitment_id, actual),
            )
            if cur.rowcount != 1:
                conn.rollback()
                return jsonify({
                    "ok": False,
                    "error": (
                        "Los bultos cambiaron mientras estabas editando. "
                        "Recarga las etiquetas e intenta nuevamente."
                    ),
                }), 409
            # Borrar excedentes si bajamos
            if nuevo < actual:
                cur.execute(
                    "DELETE FROM transport_labels "
                    "WHERE commitment_id=%s AND manifest_id=%s AND bulto_num > %s",
                    (commitment_id, manifest_id or 0, nuevo),
                )
            # Actualizar bulto_total en las filas existentes
            cur.execute(
                "UPDATE transport_labels SET bulto_total=%s "
                "WHERE commitment_id=%s AND manifest_id=%s",
                (nuevo, commitment_id, manifest_id or 0),
            )
        conn.commit()
    except Exception as e:
        print(f"[tr_factura_set_bultos] DB error: {e}", flush=True)
        return jsonify({"ok": False, "error": "Error al guardar"}), 500

    # Crear las filas nuevas en transport_labels (si subimos) — manifest_id
    # y courier ya se resolvieron arriba, para el gate de Felca/Milling.
    fac_struct = _tr_etiqueta_facturas([commitment_id])
    if fac_struct:
        _tr_upsert_labels(fac_struct, manifest_id=manifest_id, courier=courier)

    _tr_log("commitment", commitment_id, "n_bultos capturado",
            f"{actual} → {nuevo} (manifiesto: {manifest_id or 's/asignar'}, "
            f"courier: {courier or 's/asignar'}) por {current_username()}")

    # Si la factura ya tiene OT FedEx activa, su etiqueta quedó desfasada.
    n_desfasadas = _tr_fedex_mark_stale(commitment_id, actual, nuevo)

    return jsonify({
        "ok": True,
        "n_bultos": nuevo,
        "previo": actual,
        "doc": (fac.get("nudo") or "").strip(),
        "fedex_desfasada": n_desfasadas > 0,
    })


def _tr_recalc_totales_manifiesto(cur, mid):
    """Recalcula los totales PERSISTIDOS del manifiesto a partir de sus items
    vivos. FUENTE ÚNICA DE VERDAD: la llaman agregar, quitar y cualquier flujo
    que cambie los items, para que total_items y costo_total del listado/KPIs
    nunca queden desfasados (antes el borrado no recalculaba costo_total → los
    montos quedaban viejos). Recibe un cursor abierto (corre en la misma
    transacción del caller)."""
    cur.execute("""
        UPDATE transport_manifests m SET
          total_items = (SELECT COUNT(*) FROM transport_manifest_items
                         WHERE manifest_id = m.id),
          costo_total = (SELECT COALESCE(SUM(c.costo_zz), 0)
                         FROM transport_manifest_items mi
                         JOIN transport_commitments c ON c.id = mi.commitment_id
                         WHERE mi.manifest_id = m.id)
        WHERE m.id = %s
    """, (mid,))


def _tr_next_manifest_correlativo_candidato(cur):
    """Un candidato MAN-YYYY-NNNN (no lo inserta). El caller reintenta con un
    candidato nuevo si choca contra el UNIQUE de `correlativo` (mismo patrón
    anti-race de tr_crear_manifiesto, extraído para no duplicarlo).

    FIX 2026-07-28 (levantamiento del "llamado de manifiesto"): había un
    SEGUNDO generador de correlativo en tr_asignar_a_manifiesto que producía
    el formato viejo 'MAN0001' (inconsistente con 'MAN-2026-0001' del resto
    del sistema, hallazgo H2) con un COUNT sin protección de carrera, y
    encima leía el resultado con `cur.fetchone()[0]` — con DictCursor (todo
    el pool usa DictCursor) eso lanza KeyError. Ese era el motivo real por
    el que el botón "Crear manifiesto" del panel del Monitor devolvía 500
    SIEMPRE (hallazgo H1, confirmado leyendo el código: no hay ningún
    `current_user` importado en todo app.py, así que la línea de abajo
    también lanzaba NameError).
    """
    from datetime import datetime as _dt
    cur.execute(
        "SELECT COUNT(*)+1 AS n FROM transport_manifests "
        "WHERE YEAR(created_at)=YEAR(NOW())"
    )
    n = (cur.fetchone() or {}).get("n", 1)
    return f"MAN-{_dt.now().year}-{int(n):04d}"


def _tr_manifiesto_guard_actividad(mid):
    """Guarda compartida de tr_agregar_item / tr_quitar_item (FIX 2026-07-25,
    revisión adversarial, hallazgo ALTA): antes, un manifiesto ya subido a
    un courier (o con prueba de entrega firmada) podía recibir un POST/
    DELETE de items SIN ningún chequeo, desincronizando el seguimiento que
    ya ve el cliente. Replica el mismo patrón 403/409-con-aviso que ya usa
    tr_manifiesto_eliminar (arriba en este archivo): bloquea para
    no-superadmin, y para superadmin deja pasar pero deja un aviso
    logueado (visible en el historial del manifiesto, `logs` en
    manifiesto_detalle.html) y devuelto en la respuesta JSON.

    Reusa el motor de SOLO LECTURA _lc_manifiesto_tiene_actividad de
    logistica_cotizaciones.py -- Regla #4.2: no duplica la consulta, y el
    import es perezoso (mismo criterio que usa logistica_cotizaciones.py
    para leer helpers de app.py) porque ese módulo se registra al final de
    app.py, después de que estas rutas ya quedaron definidas.

    Devuelve (bloqueo, aviso):
      - bloqueo: tupla (response, status) lista para `return`, o None si
        puede seguir.
      - aviso: string a incluir en la respuesta JSON si un superadmin
        pasó por encima de la guarda, o None si no aplica.
    """
    try:
        from logistica_cotizaciones import _lc_manifiesto_tiene_actividad
        tiene, motivo = _lc_manifiesto_tiene_actividad(mid)
    except Exception:
        tiene, motivo = False, None
    if not tiene:
        return None, None
    if not bool(g.permissions.get("superadmin")):
        return (jsonify({
            "ok": False,
            "error": f"Este manifiesto {motivo}: solo un superadministrador puede "
                     "agregar o quitar facturas.",
        }), 403), None
    aviso = (f"Editado por superadministrador aunque el manifiesto {motivo} "
             "— puede desincronizar el seguimiento que ya ve el cliente.")
    _tr_log("manifest", mid, "aviso", aviso)
    return None, aviso


@app.route("/transporte/api/manifiestos/items-todos")
@_tr_required
def tr_manifiestos_items_todos():
    """Lista TODOS los documentos que están hoy en algún manifiesto activo
    (no cerrado/cancelado), para el Monitor (2026-07-26, pedido Daniel):
    "en el monitor en gestión deberían estar todos los productos que están
    en los manifiestos, con la opción de eliminarlo... siempre tiene que
    avisar si hay duplicidad". Marca cada fila con `duplicado` (>1 manifiesto
    activo) para que el frontend lo resalte. Solo lectura de nuestras
    propias tablas MySQL (transport_manifests/transport_manifest_items/
    transport_commitments) — no toca el ERP.
    """
    rows = mysql_fetchall("""
        SELECT mi.id AS item_id, mi.manifest_id, mi.estado_entrega,
               m.correlativo, m.estado AS manifest_estado, m.fecha AS manifest_fecha,
               m.courier,
               c.id AS commitment_id, c.tido, c.nudo, c.cliente_nombre,
               c.comuna, COALESCE(c.n_bultos, 1) AS n_bultos,
               COALESCE(c.costo_zz, 0) AS costo_zz,
               (SELECT COUNT(*) FROM transport_manifest_items mi2
                JOIN transport_manifests m2 ON m2.id = mi2.manifest_id
                WHERE mi2.commitment_id = mi.commitment_id
                  AND m2.estado NOT IN ('Cerrado','Cancelado')) AS n_manifiestos_activos
        FROM transport_manifest_items mi
        JOIN transport_manifests m ON m.id = mi.manifest_id
        JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE m.estado NOT IN ('Cerrado','Cancelado')
        ORDER BY (SELECT COUNT(*) FROM transport_manifest_items mi3
                  JOIN transport_manifests m3 ON m3.id = mi3.manifest_id
                  WHERE mi3.commitment_id = mi.commitment_id
                    AND m3.estado NOT IN ('Cerrado','Cancelado')) DESC,
                 c.nudo, m.correlativo
    """) or []
    out = []
    for r in rows:
        out.append({
            "item_id":        r["item_id"],
            "manifest_id":    r["manifest_id"],
            "correlativo":    r["correlativo"],
            "manifest_estado": r["manifest_estado"],
            "courier":        r["courier"],
            "estado_entrega": r.get("estado_entrega"),
            "commitment_id":  r["commitment_id"],
            "doc":            _doc_label(r.get('tido'), r.get('nudo')),
            "cliente":        r.get("cliente_nombre") or "—",
            "comuna":         r.get("comuna") or "",
            "n_bultos":       r.get("n_bultos") or 1,
            "costo_zz":       float(r.get("costo_zz") or 0),
            "duplicado":      (r.get("n_manifiestos_activos") or 0) > 1,
            "n_manifiestos_activos": r.get("n_manifiestos_activos") or 0,
        })
    return jsonify({"ok": True, "items": out,
                     "n_duplicados": sum(1 for x in out if x["duplicado"])})


@app.route("/transporte/manifiestos/<int:mid>/items", methods=["POST"])
@_tr_required
def tr_agregar_item(mid):
    _bloqueo, _aviso = _tr_manifiesto_guard_actividad(mid)
    if _bloqueo:
        return _bloqueo
    _body = request.get_json(silent=True, force=True) or {}
    cid = _body.get("commitment_id")
    if not cid:
        return jsonify({"error": "commitment_id requerido"}), 400
    # 2026-07-26 (pedido Daniel): "debería reconocer que la 22703 está hasta
    # en varios manifiestos... siempre tiene que avisar si hay duplicidad".
    # Antes NO existía ningún chequeo (uq_item solo es único por
    # manifest_id+commitment_id, así que la MISMA factura podía agregarse a
    # N manifiestos distintos sin aviso). Ahora: si el documento ya está en
    # OTRO manifiesto, se avisa ANTES de insertar (409 con el detalle) — el
    # frontend re-envía con confirm_dup=1 si el operador decide seguir
    # igual (ej: se dividió el despacho a propósito). No bloquea duro.
    _confirm_dup = bool(_body.get("confirm_dup"))
    # PR-B (Fase 1, 2026-08-01): `ramo` opcional en el body -- permite a un
    # caller que YA sabe qué ramo quiere (ej. una ficha futura con selector
    # de ramo) desambiguar un documento con 2+ ramos sin pasar por
    # lineas-pendientes. Si no se manda, se resuelve automático (ver
    # _tr_plan_ramo_manifest_item): funciona igual que siempre para
    # documentos de 1 solo ramo (la inmensa mayoría).
    _ramo_solicitado = (_body.get("ramo") or "").strip().lower() or None

    _doc_info = mysql_fetchone(
        "SELECT tido, nudo FROM transport_commitments WHERE id=%s", (cid,))
    _doc_lbl = (f"{_doc_info.get('tido') or ''} {_doc_info.get('nudo') or ''}".strip()
                if _doc_info else f"commitment_id={cid}")

    _ramos_doc = _tr_ramos_de_commitment(cid)
    _items_existentes = _tr_items_existentes_de_commitment(cid)
    _plan = _tr_plan_ramo_manifest_item(_ramos_doc, _items_existentes, mid, _ramo_solicitado)

    if _plan["accion"] == "conflicto_multi_ramo":
        return jsonify(_tr_resp_conflicto_multi_ramo(_plan, _doc_lbl)), 409

    # 2026-07-26 (pedido Daniel): "debería reconocer que la 22703 está hasta
    # en varios manifiestos... siempre tiene que avisar si hay duplicidad".
    # PR-B: este chequeo ahora es POR RAMO (antes era "cualquier otro
    # manifiesto, sin importar ramo" -- eso bloqueaba con un mensaje confuso
    # el flujo NUEVO y legítimo de completar el segundo ramo de un documento
    # en un manifiesto distinto). El frontend re-envía con confirm_dup=1 si
    # el operador decide seguir igual (ej: se dividió el despacho a propósito).
    if _plan["accion"] == "duplicado" and not _confirm_dup:
        return jsonify({
            "ok": False,
            "error": "duplicado",
            "msg": f"El documento {_doc_lbl} ({_tr_ramo_label(_plan['ramo'])}) ya está "
                   "en otro manifiesto.",
            "duplicados": [{"manifest_id": _plan["otro_manifest_id"], "ramo": _plan["ramo"]}],
        }), 409

    # Defensivo: _plan["ramo"] nunca debería venir vacío (_tr_ramos_de_commitment
    # jamás devuelve una lista vacía), pero el fallback a "despacho" se
    # mantiene igual que en el resto de los write-sites -- ningún item nuevo
    # debe poder quedar con ramo=NULL/vacío.
    _ramo = _plan["ramo"] or "despacho"
    _era_duplicado = _plan["accion"] == "duplicado"
    # FIX 2026-07-28 (levantamiento "llamado de manifiesto", H3): este
    # `conn.close()` cerraba la conexión SCOPED AL REQUEST (get_db() cachea
    # en g._db, y teardown_appcontext ya la cierra sola al final) y DESPUÉS
    # seguía usándola vía mysql_fetchone/_tr_log más abajo en esta misma
    # función. get_db() no reabre porque "_db" ya está en g -- devuelve la
    # conexión cerrada tal cual, así que esas llamadas posteriores fallaban.
    # El item SÍ quedaba insertado (el commit ya había corrido), pero la
    # request completa reventaba después, sin auditoría y devolviendo
    # "Error de conexión" al operador aunque la factura ya se hubiera
    # agregado. Mismo patrón correcto que ya usa tr_quitar_item al lado:
    # no cerrar acá, dejar que teardown_appcontext lo haga.
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            "INSERT IGNORE INTO transport_manifest_items (manifest_id,commitment_id,ramo) "
            "VALUES (%s,%s,%s)", (mid, cid, _ramo)
        )
        # FASE 2 (2026-07-31): snapshot de productos de este despacho para
        # poder trackear estado/SLA por SKU. SELECT explícito (no lastrowid)
        # porque este INSERT IGNORE puede no-opear si el documento ya estaba
        # en este mismo manifiesto -- _tr_populate_item_lines es idempotente
        # de todas formas (UNIQUE KEY), así que da igual si ya existían.
        cur.execute(
            "SELECT id FROM transport_manifest_items WHERE manifest_id=%s AND commitment_id=%s AND ramo=%s",
            (mid, cid, _ramo)
        )
        _item_row = cur.fetchone()
        if _item_row:
            _tr_populate_item_lines(cur, _item_row["id"], cid)
        _tr_recalc_totales_manifiesto(cur, mid)
    conn.commit()
    # Trazabilidad legible: documento + cliente (no solo el id).
    _info = mysql_fetchone(
        "SELECT tido, nudo, cliente_nombre FROM transport_commitments WHERE id=%s", (cid,))
    if _info:
        _doc = f"{_info.get('tido') or ''} {_info.get('nudo') or ''}".strip()
        _detalle = f"{_doc} ({_tr_ramo_label(_ramo)}) · {_info.get('cliente_nombre') or '—'}"
    else:
        _detalle = f"commitment_id={cid} ({_tr_ramo_label(_ramo)})"
    _tr_log("manifest", mid, "factura agregada", _detalle)
    if _era_duplicado:
        _tr_log("manifest", mid, "aviso",
                 f"factura agregada ({_tr_ramo_label(_ramo)}) aunque ya estaba en otro "
                 f"manifiesto (#{_plan['otro_manifest_id']}) con el mismo ramo")
    resp = {"ok": True, "ramo": _ramo}
    # Info para el frontend: si el documento tiene MÁS ramos sin asignar
    # todavía (ej. se acaba de agregar despacho pero instalación sigue
    # pendiente), avisar -- no bloquea, solo informa (ver "Líneas pendientes"
    # para completar el resto).
    _ramos_restantes = [r for r in _ramos_doc
                         if r != _ramo and r not in {it.get("ramo") for it in _items_existentes}]
    if _ramos_restantes:
        resp["ramos_pendientes_otros"] = _ramos_restantes
    if _aviso:
        resp["aviso"] = _aviso
    return jsonify(resp)


@app.route("/transporte/manifiestos/<int:mid>/items/<int:item_id>", methods=["DELETE"])
@_tr_required
def tr_quitar_item(mid, item_id):
    # FIX 2026-08-27 (Daniel, mismo día del pedido de Alison: "ella quiere
    # también eliminar los que no tengan gestión con el transporte"). Antes
    # esta función abría con _tr_manifiesto_guard_actividad(mid), que mira si
    # el MANIFIESTO tiene actividad en CUALQUIERA de sus documentos -- no en
    # el que se está quitando. Eso bloqueaba (solo superadmin) hasta quitar
    # una factura sin ningún tracking propio, con tal de que OTRA factura del
    # mismo manifiesto ya estuviera en curso con el courier. Y de paso tapaba
    # por completo la ruta de "quitar duplicada" de más abajo (tr_eliminar
    # nunca llegaba a evaluarse: el guard cortaba antes, con 403).
    #
    # El riesgo real que ese guard quería evitar -- desincronizar el
    # seguimiento que ya ve el cliente -- ya está cubierto, factura por
    # factura, por los candados de MÁS ABAJO en esta misma función: estado
    # terminal (no se puede "des-entregar"), tracking propio + sin duplicada
    # en otro lado (bloqueado sin excepción), y tracking propio + duplicada
    # confirmada (tr_eliminar/superadmin con confirmación). Un guard aparte a
    # nivel de TODO el manifiesto es redundante para "quitar" -- sigue
    # aplicando tal cual a "agregar" (tr_agregar_item, tr_asignar_a_manifiesto,
    # tr_lineas_pendientes_enviar_manifiesto), que es un riesgo distinto
    # (sumar documentos a un manifiesto ya despachado) y no se toca acá.
    _aviso = None
    # Capturar datos del item ANTES de borrar, para una trazabilidad legible
    # (qué factura, de qué cliente, cuánto flete, cuántos bultos se quitaron).
    info = mysql_fetchone(
        "SELECT mi.commitment_id, mi.simpliroute_visit_id, mi.master_tracking_number, "
        "       mi.tracking_number, mi.estado_entrega, "
        "       c.tido, c.nudo, c.cliente_nombre, "
        "       COALESCE(c.costo_zz, 0) AS costo_zz, COALESCE(c.n_bultos, 1) AS n_bultos "
        "FROM transport_manifest_items mi "
        "JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.id=%s AND mi.manifest_id=%s",
        (item_id, mid)
    )

    # FIX 2026-07-28 (Daniel: "eso es muy grave"). No se puede "des-entregar" un
    # pedido: si ya llegó a un estado terminal, quitarlo del manifiesto dejaría al
    # cliente viendo un pedido en preparación que en realidad ya recibió.
    # La evidencia (firma/fotos/timeline) ya no se pierde — ver
    # _ensure_transport_evidencia_perdurable() — pero igual no tiene sentido
    # operativo sacar del manifiesto algo que el courier ya entregó.
    _estado_actual = (info or {}).get("estado_entrega") or ""
    if _estado_actual in ESTADOS_ENTREGA_TERMINALES:
        return jsonify({
            "ok": False,
            "error": f"Este documento ya está en estado «{_estado_actual}» y no se "
                     f"puede quitar del manifiesto. Su entrega ya quedó registrada "
                     f"con evidencia; sacarlo dejaría al cliente con información falsa.",
        }), 409
    # FIX 2026-07-27 (Daniel: "bloquea la edición también" -- una vez que la
    # factura ya está en gestión con el courier -- OT FedEx o visita
    # SimpliRoute creada -- ya no se puede quitar del manifiesto ni editar.
    # Antes esta ruta borraba silenciosamente la visita de SimpliRoute y
    # seguía con el borrado del item; ahora se bloquea de entrada (el
    # frontend ya deshabilita el botón, esto es el mismo candado del lado
    # del servidor para que no se pueda saltar por API directa).
    # FIX 2026-07-29 (Daniel, en vivo): el candado solo miraba
    # master_tracking_number (OT creada vía Ship API automático) —
    # tracking_number (el que carga "Pegar TNs desde Excel"/"Cargar Excel de
    # OTs", una OT ya creada A MANO en el portal FedEx) quedaba SIN
    # protección: se podía quitar del manifiesto una factura que ya tenía
    # tracking real asignado. Se agrega al mismo candado.
    _aviso_duplicado = None
    _duplicado_detalle_log = None
    if info and (info.get("master_tracking_number") or info.get("tracking_number")
                 or info.get("simpliroute_visit_id")):
        # REGLA ACORDADA CON DANIEL (2026-08-22, "vamos afinando"; pedido de
        # nuevo 2026-08-27: "que Alison pueda borrar facturas que no tengan
        # movimiento"; ampliado el mismo día -- "no son duplicados, quiero
        # que ella pueda dejar limpio, se ensució mucho los manifiestos": no
        # hace falta que la otra copia YA esté entregada, alcanza con que la
        # misma factura esté repetida en OTRO manifiesto activo). El candado
        # de arriba mira SOLO esta copia -- pero la misma factura (mismo
        # commitment_id) puede estar repetida en varios manifiestos (badge
        # "N despachos"). Si existe en otro manifiesto no eliminado, esta
        # copia es prescindible -- se puede elegir cuál de las dos dejar.
        # Si hay una copia YA entregada, se prioriza mostrar esa (es la más
        # útil para decidir); si no, se muestra la más reciente igual.
        duplicada = mysql_fetchone(
            "SELECT m2.id AS manifest_id, m2.correlativo, "
            "       mi2.master_tracking_number, mi2.tracking_number, "
            "       mi2.estado_entrega, c2.delivered_at "
            "FROM transport_manifest_items mi2 "
            "JOIN transport_manifests m2    ON m2.id = mi2.manifest_id "
            "JOIN transport_commitments c2  ON c2.id = mi2.commitment_id "
            "WHERE mi2.commitment_id = %s AND mi2.id != %s "
            "  AND (m2.eliminado = 0 OR m2.eliminado IS NULL) "
            "ORDER BY (mi2.estado_entrega = 'Entregado') DESC, mi2.id DESC LIMIT 1",
            (info["commitment_id"], item_id)
        )
        if not duplicada:
            # Caso general: sigue en gestión activa con el courier, sin otra
            # copia en ningún otro manifiesto -- el candado de siempre aplica
            # sin excepción (REGLA #4.2: no relajar lo que no se acordó).
            return jsonify({
                "ok": False,
                "error": "Esta factura ya está en gestión con el courier (OT/visita creada) "
                         "y no se puede quitar del manifiesto.",
            }), 409

        # Hay otra copia de la misma factura en otro manifiesto activo.
        # Permiso: Alison y Daniel (operador o superior) -- mismo flag
        # granular que ya gobierna borrar manifiestos completos (tr_eliminar,
        # /admin/roles -> Transporte -> "Eliminar manifiestos y pedidos"),
        # para no multiplicar permisos por una variante del mismo gesto de
        # limpieza.
        if not (g.permissions.get("superadmin") or g.permissions.get("tr_eliminar")):
            return jsonify({
                "ok": False,
                "error": "No tienes permiso para quitar facturas duplicadas de un manifiesto. "
                         "Pide que un superadministrador te habilite \"Eliminar manifiestos y "
                         "pedidos\" en Usuarios y roles.",
            }), 403

        body = request.get_json(silent=True) or {}
        _ya_entregada_en_otro = (duplicada.get("estado_entrega") == "Entregado")
        _fecha_ent = duplicada.get("delivered_at")
        _fecha_txt = chile_fmt_filter(_fecha_ent, "%d/%m/%Y %H:%M") if _fecha_ent else "fecha no registrada"
        _tracking_dup = duplicada.get("master_tracking_number") or duplicada.get("tracking_number") or "—"
        _estado_dup = duplicada.get("estado_entrega") or "Pendiente"
        if _ya_entregada_en_otro:
            _msg_duplicada = (f"Esta factura ya fue ENTREGADA en el manifiesto "
                               f"{duplicada.get('correlativo')} el {_fecha_txt} (tracking {_tracking_dup}). "
                               f"Esta es una copia duplicada que quedó sin despachar en este manifiesto.")
        else:
            _msg_duplicada = (f"Esta factura también está en el manifiesto "
                               f"{duplicada.get('correlativo')} (estado: {_estado_dup}, "
                               f"tracking {_tracking_dup}). Son dos copias del mismo documento — "
                               f"puedes quitar esta copia y dejar la otra activa.")
        if not body.get("confirmado"):
            return jsonify({
                "ok": False,
                "requiere_confirmacion": True,
                "duplicada_manifiesto": duplicada.get("correlativo"),
                "duplicada_manifiesto_id": duplicada.get("manifest_id"),
                "duplicada_fecha": _fecha_txt if _ya_entregada_en_otro else "",
                "duplicada_estado": _estado_dup,
                "duplicada_ya_entregada": _ya_entregada_en_otro,
                "duplicada_tracking": _tracking_dup,
                "error": _msg_duplicada,
            }), 409

        # Confirmado: se quita esta copia, pero la etiqueta/OT propia de ESTA
        # copia NO se anula sola en FedEx -- "nada irreversible sin decisión
        # humana" (memoria del 22-08). Se avisa con el tracking para que se
        # anule a mano si no se va a usar.
        _tracking_propio = info.get("master_tracking_number") or info.get("tracking_number")
        if _tracking_propio:
            _aviso_duplicado = (
                f"Esta copia tenía el tracking {_tracking_propio} — si no se va a usar, "
                f"anúlalo manualmente en FedEx (no se cancela automáticamente)."
            )
        _duplicado_detalle_log = (
            f"COPIA DUPLICADA (la entrega real ya está registrada en otro manifiesto)"
            if _ya_entregada_en_otro else
            f"COPIA DUPLICADA (repetida en manifiesto {duplicada.get('correlativo')}, "
            f"estado ahí: {_estado_dup})"
        )

    # FIX 2026-07-26 — antes de borrar el item, si ya tenía una visita creada
    # en SimpliRoute, hay que borrarla ALLÁ también. Si no, al re-preparar el
    # mismo pedido queda una visita "fantasma" duplicada en SimpliRoute con el
    # mismo nombre de cliente (reportado por Daniel: "tenía dos fichas con mi
    # nombre"), porque el item viejo nunca se limpiaba del lado del courier.
    _visit_id_borrado = (info.get("simpliroute_visit_id") or "").strip() if info else ""
    _simpliroute_borrado_ok = None
    if _visit_id_borrado:
        man_courier = mysql_fetchone(
            "SELECT courier FROM transport_manifests WHERE id=%s", (mid,))
        courier = (man_courier.get("courier") or "").strip() if man_courier else ""
        token = _simpliroute_token_for_courier(courier)
        if token:
            try:
                import simpliroute_client as _src
                r = _simpliroute_request(
                    "POST", _src.EP_BULK_DELETE, token,
                    payload={"visits": [int(_visit_id_borrado)]}, timeout=20)
                _simpliroute_borrado_ok = bool(r.get("ok"))
                if not _simpliroute_borrado_ok:
                    print(f"[simpliroute] no se pudo borrar visita {_visit_id_borrado} "
                          f"(item {item_id}): {r.get('error')}", flush=True)
            except Exception as e:
                _simpliroute_borrado_ok = False
                print(f"[simpliroute] excepción al borrar visita {_visit_id_borrado} "
                      f"(item {item_id}): {e}", flush=True)

    # ── Auditoría ANTES de borrar (REGLA #5: "audit log en TODA acción
    #    destructiva; antes de borrar, no después"). Estaba después del DELETE:
    #    si el proceso se caía entremedio, el borrado quedaba sin rastro.
    #    Trazabilidad legible: "FCV 10599 · Cipax Limitada · flete $559.478 · 114 bultos"
    if info:
        doc = f"{info.get('tido') or ''} {info.get('nudo') or ''}".strip()
        cli = info.get("cliente_nombre") or "—"
        flete = int(info.get("costo_zz") or 0)
        nb = info.get("n_bultos") or 1
        detalle = (f"{doc} · {cli} · flete ${flete:,}".replace(",", ".")
                   + f" · {nb} bulto/s")
        if _estado_actual:
            detalle += f" · estado al quitar: {_estado_actual}"
    else:
        detalle = f"item_id={item_id}"
    if _visit_id_borrado:
        detalle += (f" · visita SimpliRoute {_visit_id_borrado} "
                    f"{'borrada' if _simpliroute_borrado_ok else 'NO se pudo borrar (revisar manual)'}")
    if _duplicado_detalle_log:
        detalle += f" · {_duplicado_detalle_log}"
    _tr_log("manifest", mid, "factura quitada", detalle)

    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            "DELETE FROM transport_manifest_items WHERE id=%s AND manifest_id=%s",
            (item_id, mid)
        )
        # Recalcular TODOS los totales (antes solo total_items → costo_total
        # quedaba viejo). Ahora montos del listado/KPIs siempre cuadran.
        _tr_recalc_totales_manifiesto(cur, mid)
        # Totales nuevos para devolver al frontend.
        cur.execute(
            "SELECT total_items, costo_total FROM transport_manifests WHERE id=%s", (mid,))
        _tot = cur.fetchone() or {}
    conn.commit()
    resp = {
        "ok": True,
        "total_items": (_tot.get("total_items") if _tot else None),
        "costo_total": float(_tot.get("costo_total") or 0) if _tot else None,
    }
    _avisos_finales = [a for a in (_aviso, _aviso_duplicado) if a]
    if _avisos_finales:
        resp["aviso"] = " ".join(_avisos_finales)
    return jsonify(resp)


@app.route("/transporte/manifiestos/<int:mid>/items/<int:item_id>/estado", methods=["PUT"])
@_tr_required
def tr_estado_entrega(mid, item_id):
    body = request.get_json(silent=True) or {}
    estado = body.get("estado_entrega", "")
    if estado not in ESTADOS_ENTREGA:
        return jsonify({"error": "estado inválido"}), 400

    # Protección GENERAL (decisión Daniel 2026-07-25, amplía la de 2026-06-14):
    # una vez el pedido queda "Entregado a transporte", las APIs (FedEx Track,
    # SimpliRoute, chofer) toman el control del estado de entrega — este
    # endpoint es el único camino MANUAL (usuario humano vía UI) y por eso
    # queda restringido a admin/superadmin SIN IMPORTAR el courier (antes solo
    # se exigía para items con tracking FedEx; los demás couriers quedaban
    # abiertos a cualquier usuario con permiso 'transporte', lo cual ya no
    # aplica). Los procesos automáticos (poller FedEx, chofer, sistema) NO
    # pasan por este endpoint — actualizan estado_entrega vía
    # `_tr_apply_carrier_status()` con fuente='fedex'/'chofer'/'sistema', así
    # que no quedan bloqueados por esta guarda.
    _u = getattr(g, "user", None) or {}
    if (_u.get("role") or "") not in ("admin", "superadmin"):
        return jsonify({
            "ok": False,
            "error": ("El cambio manual del estado de entrega es exclusivo de "
                      "un supervisor (admin/superadmin). Las APIs de transporte "
                      "actualizan el estado automáticamente."),
        }), 403

    comentario = (body.get("comentario") or "").strip() or None

    # "Problema" (antes "Entrega fallida") es el único estado 100% manual y
    # exige motivo obligatorio: el correo al cliente depende de contarle
    # cuál fue el problema (pedido explícito de Daniel 2026-07-25).
    if estado in ("Problema", "Entrega fallida") and not comentario:
        return jsonify({
            "ok": False,
            "error": "Para marcar 'Problema' debes indicar el motivo (obligatorio) — se incluye en el correo al cliente.",
        }), 400

    # Verifica que el item exista DENTRO de este manifiesto — el UPDATE
    # manual que reemplazamos abajo llevaba el mismo WHERE id=... AND
    # manifest_id=...; sin este chequeo previo, _tr_apply_carrier_status()
    # (que solo filtra por id) aceptaría un item_id válido de OTRO
    # manifiesto pasado por error/URL manipulada.
    if not mysql_fetchone(
        "SELECT id FROM transport_manifest_items WHERE id=%s AND manifest_id=%s",
        (item_id, mid)
    ):
        return jsonify({"ok": False, "error": "item no encontrado en este manifiesto"}), 404

    # 2026-08-01: migrado al choke-point único (antes hacía su propio
    # UPDATE + _tr_log + _tr_event). Mismo resultado observable: fuente=
    # 'manual' está exenta de la guarda anti-retroceso de
    # _tr_apply_carrier_status (esa guarda solo aplica a FUENTES_AUTOMATICAS
    # = fedex/simpliroute), así que un admin sigue pudiendo reabrir un
    # estado terminal (ej. 'Problema' desde 'Entregado') igual que antes.
    # notify_cliente queda en su default (True), igual que la llamada
    # anterior a _tr_event().
    _tr_apply_carrier_status(item_id, estado, fuente='manual', comentario=comentario)
    return jsonify({"ok": True})


@app.route("/transporte/manifiestos/<int:mid>/estado", methods=["PUT"])
@_tr_required
def tr_estado_manifiesto(mid):
    estado = (request.get_json(silent=True) or {}).get("estado", "")
    validos = ["En preparación", "En curso", "Cerrado", "Entregado completo"]
    if estado not in validos:
        return jsonify({"error": "estado inválido"}), 400
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute("UPDATE transport_manifests SET estado=%s WHERE id=%s", (estado, mid))
    conn.commit()
    _tr_log("manifest", mid, "estado cambiado", estado)
    return jsonify({"ok": True})


# ═══════════════════════════════════════════════════════════════════════════
#  TRACKING FASE 1 — núcleo + tracking público + prueba de entrega
# ═══════════════════════════════════════════════════════════════════════════

@app.route("/transporte/manifiestos/<int:mid>/items/<int:item_id>/entrega",
           methods=["POST"])
@_tr_required
def tr_registrar_entrega(mid, item_id):
    """Registra la prueba de entrega completa: receptor + firma + foto + GPS.

    Marca el estado como 'Entregado', cachea delivered_at en el commitment y
    publica el evento al tracking del cliente. Es idempotente: si ya existe
    una prueba para este item, se reemplaza (no se duplica).

    Body JSON:
      receptor_nombre (required), receptor_rut, receptor_relacion,
      firma_data_url (canvas base64), fotos[] (data URLs),
      lat, lng, accuracy_m, notas.
    """
    body = request.get_json(silent=True, force=True) or {}
    receptor = (body.get("receptor_nombre") or "").strip()
    if not receptor:
        return jsonify({"error": "receptor requerido"}), 400
    receptor_rut = (body.get("receptor_rut") or "").strip() or None
    relacion = (body.get("receptor_relacion") or "").strip() or None
    firma_data = (body.get("firma_data_url") or "").strip() or None
    fotos_in = body.get("fotos") or []
    if not isinstance(fotos_in, list):
        fotos_in = [fotos_in]
    lat = body.get("lat"); lng = body.get("lng")
    accuracy = body.get("accuracy_m")
    notas = (body.get("notas") or "").strip() or None

    # Verificar que el item exista y traer commitment_id
    item = mysql_fetchone(
        "SELECT id, commitment_id FROM transport_manifest_items "
        "WHERE id=%s AND manifest_id=%s",
        (item_id, mid)
    )
    if not item:
        return jsonify({"error": "item no encontrado"}), 404
    commitment_id = item["commitment_id"]

    # Subir firma a Cloudinary (fallback al data URL si no hay credenciales).
    firma_url = ""
    if firma_data:
        firma_url = _subir_firma_cloudinary(
            firma_data, item_id, f"transp_receptor_{item_id}"
        ) or firma_data

    # Subir fotos (hasta 5). data URL → Cloudinary. Si Cloudinary no está
    # disponible, guardamos el data URL crudo (LONGTEXT lo soporta).
    fotos_urls = []
    for idx, raw in enumerate(fotos_in[:5]):
        if not raw or not isinstance(raw, str):
            continue
        if not raw.startswith("data:") and raw.startswith("http"):
            fotos_urls.append(raw)
            continue
        try:
            pid = f"transp_entrega_{item_id}_{idx}_{int(time.time())}"
            res = _uploader_upload(raw, public_id=pid, folder="ilus/transporte/entregas", resource_type="image")
            fotos_urls.append(res.get("secure_url") or raw)
        except Exception as _up_err:
            print(f"[tr_entrega] foto {idx} no se pudo subir: {_up_err}",
                  flush=True)
            fotos_urls.append(raw)

    conn = get_db()
    with conn.cursor() as cur:
        # Upsert prueba de entrega (UNIQUE KEY uq_item garantiza 1:1).
        cur.execute("""
            INSERT INTO transport_delivery_proof
              (manifest_item_id, commitment_id, receptor_nombre, receptor_rut,
               receptor_relacion, firma_url, fotos_json,
               lat, lng, accuracy_m, usuario, notas)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON DUPLICATE KEY UPDATE
              receptor_nombre = VALUES(receptor_nombre),
              receptor_rut    = VALUES(receptor_rut),
              receptor_relacion = VALUES(receptor_relacion),
              firma_url       = VALUES(firma_url),
              fotos_json      = VALUES(fotos_json),
              lat             = VALUES(lat),
              lng             = VALUES(lng),
              accuracy_m      = VALUES(accuracy_m),
              usuario         = VALUES(usuario),
              notas           = VALUES(notas),
              entregado_at    = NOW()
        """, (
            item_id, commitment_id, receptor, receptor_rut, relacion,
            firma_url, json.dumps(fotos_urls, ensure_ascii=False),
            lat, lng, accuracy, current_username(), notas
        ))
    conn.commit()

    # 2026-08-01: migrado al choke-point único (antes hacía su propio UPDATE
    # de estado_entrega + UPDATE de delivered_at + _tr_log + _tr_event). El
    # estado siempre pasa a 'Entregado' → _tr_apply_carrier_status() ya
    # cachea delivered_at en el commitment con el mismo COALESCE de antes, no
    # hace falta repetirlo acá. lat/lng se preservan (antes solo llegaban a
    # _tr_event(), que _tr_apply_carrier_status() ahora también acepta).
    _tr_apply_carrier_status(item_id, 'Entregado', fuente='manual',
                             comentario=f"Recibido por: {receptor}",
                             lat=lat, lng=lng)
    return jsonify({"ok": True, "fotos": len(fotos_urls),
                    "firma": bool(firma_url)})


@app.route("/transporte/api/items/<int:item_id>/link-cliente", methods=["GET"])
@_tr_required
def tr_get_link_cliente(item_id):
    """Devuelve el link público de tracking del cliente para este item.

    Genera el token lazy si aún no existe. Retorna también el commitment_id
    y el doc, para que el modal del operador muestre contexto al copiar el link.
    """
    item = mysql_fetchone(
        "SELECT tmi.id, tmi.commitment_id, tc.tido, tc.nudo, tc.cliente_nombre "
        "FROM transport_manifest_items tmi "
        "JOIN transport_commitments tc ON tc.id = tmi.commitment_id "
        "WHERE tmi.id=%s LIMIT 1",
        (item_id,)
    )
    if not item:
        return jsonify({"error": "item no encontrado"}), 404
    tok = _tr_ensure_public_token(item["commitment_id"])
    if not tok:
        return jsonify({"error": "no se pudo generar token"}), 500
    url = url_for("tr_public_tracking", token=tok, _external=True)
    return jsonify({
        "ok": True,
        "url": url,
        "token": tok,
        "doc": _doc_label(item.get('tido'), item.get('nudo')),
        "cliente": item.get("cliente_nombre") or "",
    })


@app.route("/transporte/api/items/<int:item_id>/link-cliente/regenerar",
           methods=["POST"])
@_tr_required
def tr_regenerar_link_cliente(item_id):
    """Regenera el token público (caso fuga del link). Solo superadmin.

    El link viejo deja de funcionar inmediatamente. El nuevo se devuelve
    en la respuesta.
    """
    if not bool((getattr(g, "permissions", None) or {}).get("superadmin")):
        return jsonify({"error": "permiso denegado"}), 403
    item = mysql_fetchone(
        "SELECT commitment_id FROM transport_manifest_items WHERE id=%s",
        (item_id,)
    )
    if not item:
        return jsonify({"error": "item no encontrado"}), 404
    new_tok = secrets.token_urlsafe(30)[:40]
    try:
        mysql_execute(
            "UPDATE transport_commitments SET public_token=%s WHERE id=%s",
            (new_tok, item["commitment_id"])
        )
    except Exception as _e:
        return jsonify({"error": f"no se pudo regenerar: {_e}"}), 500
    _tr_log("commitment", item["commitment_id"], "token regenerado", "")
    url = url_for("tr_public_tracking", token=new_tok, _external=True)
    return jsonify({"ok": True, "url": url, "token": new_tok})


# ── Tracking público (sin login) ─────────────────────────────────────────
# Rate limit por token + cache de polling (mismo patrón que retiros)
_TRACK_RL: dict = {}        # token → [timestamps]
_TRACK_RL_MAX = 60
_TRACK_RL_WINDOW = 60.0

def _track_rate_ok(token):
    """Rate-limit por token: 60 req/min. Igual que retiros."""
    import time as _time
    now = _time.time()
    cutoff = now - _TRACK_RL_WINDOW
    bucket = [t for t in (_TRACK_RL.get(token) or []) if t >= cutoff]
    if len(bucket) >= _TRACK_RL_MAX:
        _TRACK_RL[token] = bucket
        return False
    bucket.append(now)
    _TRACK_RL[token] = bucket
    return True

_TRACK_POLL_CACHE: dict = {}    # token → {payload, ts}
_TRACK_POLL_TTL = 10.0          # segundos


def _mask_address(direccion, comuna):
    """Enmascara la dirección para tracking público: muestra el nombre de la
    calle pero oculta el número exacto + dpto. Evita filtrar la dirección
    completa a cualquiera con el link.

    Estrategia: solo enmascara el ÚLTIMO número de cada segmento separado por
    coma (street nº, depto nº). Conserva nombres tipo "Av. 11 de Septiembre"
    intactos, porque ahí el número es parte del nombre, no del número de calle.
    """
    if not direccion:
        return (comuna or "").strip()
    import re as _re
    partes = []
    for seg in str(direccion).split(","):
        seg = seg.strip()
        if not seg:
            continue
        # Reemplaza solo el ÚLTIMO grupo de dígitos del segmento (probable nº)
        m = list(_re.finditer(r"\d{1,6}", seg))
        if m:
            last = m[-1]
            seg = seg[:last.start()] + "···" + seg[last.end():]
        partes.append(seg.strip())
    base = ", ".join(partes)
    base = _re.sub(r"\s{2,}", " ", base).strip(" ,")
    comuna = (comuna or "").strip()
    return f"{base}, {comuna}".strip(", ").strip()


def _tr_logo_de_courier(nombre):
    """URL del logo de un courier a partir de su nombre. '' si no hay.

    El nombre del courier está guardado con variantes en distintas tablas
    ("Transporte Felca" vs "Transportes Felca" — el mismo desajuste que hace
    fallar el filtro de Manifiestos), así que el match NO puede ser exacto:
    se compara sin distinguir mayúsculas y por contención en ambos sentidos.

    Nunca lanza: si algo falla, devuelve '' y la vista muestra el nombre en
    texto, como antes.
    """
    n = (nombre or "").strip().lower()
    if not n:
        return ""
    try:
        filas = mysql_fetchall(
            "SELECT nombre, logo_url FROM transport_couriers "
            "WHERE logo_url IS NOT NULL AND logo_url <> ''") or []
    except Exception:
        return ""
    for f in filas:
        c = (f.get("nombre") or "").strip().lower()
        if c and (c == n or c in n or n in c):
            return f.get("logo_url") or ""
    return ""


def _tracking_payload(token):
    """Construye el payload completo del tracking público.
    Devuelve dict o None si el token no existe."""
    c = mysql_fetchone("""
        SELECT id, tido, nudo, cliente_nombre, comuna, direccion, region,
               estado, delivered_at, fecha_emision, fecha_entrega,
               COALESCE(n_bultos, 1) AS n_bultos
        FROM transport_commitments WHERE public_token=%s LIMIT 1
    """, (token,))
    if not c:
        return None
    cid = c["id"]
    # 2026-08-13 (auditoría de ChatGPT sobre este archivo, Daniel: "el
    # seguimiento debe ser amigable"): FIX REAL -- antes esto traía solo el
    # ÚLTIMO manifest_item (ORDER BY id DESC LIMIT 1). En un pedido dividido
    # en más de un despacho (reasignación de manifiesto, o el ERP separó el
    # documento en dos), el cliente podía ver "Entregado" cuando en realidad
    # SOLO el ítem más reciente había llegado y el resto seguía en camino --
    # o al revés, ver "En ruta" cuando el ítem representativo elegido al azar
    # aún no había avanzado pese a que otro sí. Se traen TODOS los items y se
    # elige el REPRESENTATIVO de forma conservadora: primero cualquier ítem
    # en alerta (Problema/Entrega fallida/Devolución -- eso SIEMPRE debe
    # verse, sin importar qué tan avanzado esté el resto), y si no hay
    # ninguno en alerta, el de estado MENOS avanzado (nunca le decimos
    # "llegó" al cliente si una parte de su pedido sigue en camino).
    items_mi = mysql_fetchall("""
        SELECT tmi.id AS item_id, tmi.estado_entrega, tmi.manifest_id,
               tm.courier, tm.correlativo
        FROM transport_manifest_items tmi
        LEFT JOIN transport_manifests tm ON tm.id = tmi.manifest_id
        WHERE tmi.commitment_id=%s
        ORDER BY tmi.id ASC
    """, (cid,)) or []

    def _mi_prioridad(item):
        est = item.get("estado_entrega") or "En preparación"
        if est in ("Problema", "Entrega fallida", "Devolución"):
            return (0, 0)
        step = ESTADOS_ENTREGA_META.get(est, {}).get("step", 1)
        return (1, step)

    mi = min(items_mi, key=_mi_prioridad) if items_mi else None
    # Cuántos despachos distintos tiene este pedido -- dato real (no
    # inventado) para avisar al cliente que su compra viene en más de una
    # parte, en vez de dejarlo adivinar por qué el estado "salta".
    multi_envio_total = len(items_mi) if len(items_mi) > 1 else 0

    # 2026-08-13 (auditoría de ChatGPT: "el cliente no ve qué productos están
    # viajando... el backend ya conoce SKU/descripción/cantidad"): se listan
    # los productos REALES del documento (transport_commitment_lines, ya
    # poblada -- ver [[ot_clasificacion_catalogo_hallazgo]]), excluyendo las
    # líneas de servicio ZZ* (flete/instalación/etc, no son productos que el
    # cliente reciba en la caja) con el MISMO criterio de prefijo que ya usa
    # el resto del proyecto (cubicador, erp_engine, tickets_module).
    productos_raw = mysql_fetchall("""
        SELECT koprct, nokopr, cantidad
        FROM transport_commitment_lines
        WHERE commitment_id=%s AND cantidad > 0
        ORDER BY id ASC
    """, (cid,)) or []
    productos = [
        {"sku": p.get("koprct") or "", "nombre": (p.get("nokopr") or "").strip() or p.get("koprct") or "",
         "cantidad": int(p.get("cantidad") or 0)}
        for p in productos_raw
        if not (p.get("koprct") or "").strip().upper().startswith("ZZ")
    ]
    # Timeline (toda la historia, ordenada por fecha)
    eventos_raw = mysql_fetchall("""
        SELECT estado, fuente, ts_utc, comentario, lat, lng
        FROM transport_tracking_events
        WHERE commitment_id=%s
        ORDER BY ts_utc ASC, id ASC
    """, (cid,)) or []
    eventos = []
    for e in eventos_raw:
        est = e.get("estado") or ""
        meta = ESTADOS_ENTREGA_META.get(est, {})
        com_raw = (e.get("comentario") or "").strip()
        # FIX 2026-07-26 (Daniel: timeline "certero" para el cliente, no ruido
        # operativo interno): el comentario que guarda _tr_event puede traer
        # jerga de sistemas internos (nombres de couriers, "visita creada en
        # SimpliRoute", etc.) útil para auditoría pero irrelevante -o
        # confuso- para el cliente final. Se traduce/oculta SOLO acá (en el
        # payload público) -- la fila real en transport_tracking_events NO se
        # toca, sigue completa para el equipo (manifiesto_detalle.html).
        # El motivo real de una entrega fallida/Problema SÍ debe verse
        # siempre: ahí el cliente necesita saber qué pasó.
        if est in ('Problema', 'Entrega fallida'):
            com_public = com_raw
        else:
            com_public = _COMENTARIO_PUBLICO_MAP.get(com_raw, com_raw)
        eventos.append({
            "estado":     est,
            "color":      meta.get("color", "secondary"),
            "icon":       meta.get("icon", "bi-circle"),
            "fuente":     e.get("fuente") or "manual",
            # FIX 2026-07-27 (Daniel: "dice que fue entregado a las 15:28,
            # son las 11:30 en Santiago"): antes se mandaba str(ts_utc)[:19]
            # -- un STRING crudo en UTC. El template público (public_tracking.
            # html línea ~648) le aplica "| chile_fmt", que SOLO convierte
            # objetos datetime reales (un string ya no tiene tzinfo y el
            # filtro lo devuelve intacto) -- por eso se veía la hora UTC.
            # Se manda el datetime object tal cual para que Jinja SÍ pueda
            # convertirlo. NO pre-formatear a string acá.
            "ts":         e.get("ts_utc"),
            "comentario": com_public,
        })
    # FIX 2026-07-26 (Daniel: "se repite el mensaje" -- 'En preparación' dos
    # veces con fechas distintas): cada reasignación de manifiesto dispara un
    # evento nuevo vía _tr_event -- dato real e importante para auditoría,
    # pero al cliente solo le importa el AVANCE real de su pedido, no que
    # internamente se haya reasignado dos veces. Se colapsan entradas
    # CONSECUTIVAS con el mismo estado, quedándonos con la más reciente (para
    # que la fecha mostrada sea la vigente). NO se borra nada de la tabla
    # transport_tracking_events -- esto es solo la lista que se arma para
    # mostrar (la comparten tanto la vista HTML como /t/<token>/status).
    _deduped = []
    for _ev in eventos:
        if _deduped and _deduped[-1]["estado"] == _ev["estado"]:
            _deduped[-1] = _ev   # conserva el más reciente de la racha
        else:
            _deduped.append(_ev)
    eventos = _deduped
    # FIX 2026-07-30 (Daniel: "que se vea abajo la distancia de hora de un
    # cambio a otro" en el timeline público) -- delta entre cada evento y el
    # anterior, calculado en Python (los ts son datetime reales, restarlos en
    # Jinja no es directo). Vacío en el primer evento (no hay "anterior").
    _prev_ts = None
    for _ev in eventos:
        _ts = _ev.get("ts")
        if _prev_ts is not None and _ts is not None:
            try:
                _secs = (_ts - _prev_ts).total_seconds()
            except Exception:
                _secs = None
            if _secs is not None and _secs >= 0:
                if _secs < 3600:
                    _mins = max(1, int(_secs // 60))
                    _ev["delta_txt"] = f"+{_mins} min"
                elif _secs < 86400:
                    _hrs = int(_secs // 3600)
                    _mins = int((_secs % 3600) // 60)
                    _ev["delta_txt"] = f"+{_hrs} h" + (f" {_mins} min" if _mins else "")
                else:
                    _dias = int(_secs // 86400)
                    _hrs = int((_secs % 86400) // 3600)
                    _ev["delta_txt"] = f"+{_dias} día" + ("s" if _dias != 1 else "") + (f" {_hrs} h" if _hrs else "")
            else:
                _ev["delta_txt"] = ""
        else:
            _ev["delta_txt"] = ""
        _prev_ts = _ts if _ts is not None else _prev_ts
    # Prueba de entrega (si existe)
    proof = None
    if mi:
        p = mysql_fetchone("""
            SELECT receptor_nombre, receptor_relacion, firma_url,
                   fotos_json, entregado_at
            FROM transport_delivery_proof WHERE manifest_item_id=%s LIMIT 1
        """, (mi["item_id"],))
        if p:
            try:
                fotos = json.loads(p.get("fotos_json") or "[]")
            except Exception:
                fotos = []
            # Enmascarar nombre del receptor: "Juan P." (primer nombre + inicial)
            rname = (p.get("receptor_nombre") or "").strip()
            partes = rname.split()
            if len(partes) >= 2:
                rname_short = f"{partes[0]} {partes[-1][0]}."
            else:
                rname_short = rname
            proof = {
                "receptor":      rname_short,
                "relacion":      p.get("receptor_relacion") or "",
                "firma_url":     p.get("firma_url") or "",
                "fotos":         fotos,
                # Igual que arriba: datetime real, NO string -- lo convierte
                # el "| chile_fmt" del template (public_tracking.html).
                "entregado_at":  p.get("entregado_at"),
            }
    estado_actual = (mi or {}).get("estado_entrega") or "En preparación"
    meta_actual = ESTADOS_ENTREGA_META.get(estado_actual, {})
    # FIX 2026-07-26 (Daniel: "el número de seguimiento debería ser 22703" --
    # para Felca/Milling casi nunca hay tracking number real de courier, usan
    # visita SimpliRoute en vez de guía clásica). tido-nudo (mismo patrón que
    # simpliroute_client.py campo "reference") identifica el pedido SIEMPRE,
    # y evita pisarse entre tipos de documento con el mismo correlativo (una
    # factura 22703 y una boleta 22703 son cosas distintas).
    # Los ceros de relleno del ERP se quitan: esta pantalla la ve el CLIENTE
    # FINAL, y "BLV-0000022886" no es un número que nadie reconozca ni pueda
    # dictar por teléfono (Daniel, 2026-08-05: "la boleta está llena de
    # ceros"). El guion como separador se conserva a propósito, por lo que
    # explica el comentario de arriba.
    _doc_id = f"{c.get('tido') or ''}-{nudo_fmt_filter(c.get('nudo'))}".strip("-")
    return {
        "ok": True,
        "doc":           _doc_id,
        "cliente":       c.get("cliente_nombre") or "",
        "destino":       _mask_address(c.get("direccion"), c.get("comuna")),
        "region":        c.get("region") or "",
        "courier":       (mi or {}).get("courier") or "",
        # Logo del transportista para la página del cliente (2026-08-05,
        # Daniel: "los logos con imágenes, tenemos las imágenes en los
        # couriers, así que aprovechémosla"). Antes se mostraba el nombre
        # como texto plano. Match tolerante a variantes del nombre porque el
        # mismo courier está guardado de más de una forma ("Transporte
        # Felca" / "Transportes Felca") -- el mismo problema que rompe el
        # filtro de Manifiestos. Si no hay logo, la vista cae al texto.
        "courier_logo":  _tr_logo_de_courier((mi or {}).get("courier")),
        "manifiesto":    (mi or {}).get("correlativo") or "",
        "estado":        estado_actual,
        "estado_color":  meta_actual.get("color", "secondary"),
        "estado_icon":   meta_actual.get("icon", "bi-circle"),
        "estado_step":   meta_actual.get("step", 1),
        "eventos":       eventos,
        "proof":         proof,
        # Datetime real (no string) -- el template lo convierte con "| chile_fmt".
        "entregado_at":  c.get("delivered_at"),
        # Resumen de un vistazo (Daniel 2026-07-24: "que me entregue un resumen,
        # con letras más grandes, lo que importa"). Ya se leían de la tabla pero
        # no llegaban al template.
        "bultos":        int(c.get("n_bultos") or 1),
        "fecha_emision": str(c.get("fecha_emision") or "")[:10],
        "fecha_entrega": str(c.get("fecha_entrega") or "")[:10],
        # Live driver location (Uber-style): solo si está "En ruta" y hay
        # chofer asignado con ping reciente. Privacidad: solo lat/lng + ETA
        # estimada, nunca nombre/RUT/patente del chofer.
        "driver_live":   _tracking_driver_live(c["id"], estado_actual),
        # 2026-08-13: cuántos despachos distintos tiene este pedido (0 si es
        # uno solo). Dato real, derivado de items_mi arriba -- ver comentario
        # de _mi_prioridad.
        "multi_envio_total": multi_envio_total,
        # 2026-08-13: productos reales del pedido (SKU/nombre/cantidad), sin
        # líneas de servicio ZZ*. Lista vacía si el documento no tiene líneas
        # sincronizadas todavía -- el template cae al conteo de bultos.
        "productos":     productos,
    }


def _tracking_payload_json_safe(payload):
    """Copia de _tracking_payload() lista para servir como JSON crudo.

    FIX 2026-07-28 (Daniel: "algunas fechas vienen en inglés"): _tracking_payload()
    devuelve a propósito datetime objects reales -- ver comentario en esa función
    ("NO pre-formatear acá") -- para que render_template() (vista /t/<token>) los
    formatee con el filtro Jinja "| chile_fmt". Pero tr_public_tracking_status()
    (el polling JSON de /t/<token>/status) llama jsonify() directo sobre ese mismo
    dict, y Flask serializa un datetime crudo en RFC 1123 EN INGLÉS ("Mon, 28 Jul
    2026 15:28:00 GMT") porque ahí no pasa por Jinja. Convertimos acá los mismos
    campos a texto en hora Chile ANTES de jsonify -- en una copia, para no tocar
    el dict que use el render_template (mismo patrón que FIX SEV-8a/8b de esta
    noche en tr_get_tracking_fedex / _tr_buscar_detalle)."""
    if not payload:
        return payload
    out = dict(payload)
    if out.get("entregado_at"):
        out["entregado_at"] = chile_fmt_filter(out["entregado_at"], "%d/%m/%Y %H:%M:%S")
    if out.get("proof"):
        proof = dict(out["proof"])
        if proof.get("entregado_at"):
            proof["entregado_at"] = chile_fmt_filter(proof["entregado_at"], "%d/%m/%Y %H:%M:%S")
        out["proof"] = proof
    if out.get("eventos"):
        out["eventos"] = [
            {**ev, "ts": chile_fmt_filter(ev["ts"], "%d/%m/%Y %H:%M:%S") if ev.get("ts") else ev.get("ts")}
            for ev in out["eventos"]
        ]
    return out


def _tracking_driver_live(commitment_id, estado_actual):
    """Devuelve la posición en vivo del chofer si está en ruta hacia esta factura.
    Solo cuando estado='En ruta' (privacidad: no se expone GPS si ya entregó
    o si aún está en preparación). Devuelve None si no aplica.
    """
    if estado_actual != 'En ruta':
        return None
    # Manifest activo de este commitment
    mi = mysql_fetchone("""
        SELECT mi.manifest_id, c.dest_lat, c.dest_lng
        FROM transport_manifest_items mi
        JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE mi.commitment_id=%s ORDER BY mi.id DESC LIMIT 1
    """, (commitment_id,))
    if not mi or not mi.get("manifest_id"):
        return None
    # Chofer asignado al manifest
    drv = mysql_fetchone(
        "SELECT driver_id FROM transport_manifest_drivers WHERE manifest_id=%s",
        (mi["manifest_id"],))
    if not drv:
        return None
    # Último ping reciente (<5 min)
    ping = mysql_fetchone("""
        SELECT lat, lng, ts, TIMESTAMPDIFF(SECOND, ts, NOW()) AS age_s
        FROM transport_driver_pings
        WHERE driver_id=%s AND ts > DATE_SUB(NOW(), INTERVAL 5 MINUTE)
        ORDER BY id DESC LIMIT 1
    """, (drv["driver_id"],))
    if not ping:
        return None
    # Distancia estimada (haversine, si hay coords de destino) -- SIEMPRE
    # con las coordenadas REALES, antes de difuminar nada. Difuminar y
    # después medir distancia habría introducido error en la ETA a cambio
    # de nada (el ETA no se le muestra a nadie más que al propio cliente).
    dist_m = None
    if mi.get("dest_lat") and mi.get("dest_lng"):
        dist_m = _haversine_m(ping["lat"], ping["lng"],
                              mi["dest_lat"], mi["dest_lng"])
    # 2026-08-13 (auditoría de ChatGPT: "se entregan coordenadas exactas del
    # conductor al navegador... conviene entregar ubicación aproximada").
    # Se difumina la posición ANTES de que salga al navegador: redondeo a
    # ~100m (3 decimales) + ruido aleatorio de hasta ~150m, distinto en cada
    # sondeo (el cliente vuelve a pedir esto cada 30s) -- así ni siquiera
    # juntando varias lecturas se puede reconstruir la posición exacta real
    # del chofer. El destino NO se difumina: ya es la dirección que el
    # propio cliente dio para su entrega, no es un dato ajeno.
    import random as _rnd
    lat_fuzz = round(float(ping["lat"]) + _rnd.uniform(-0.0013, 0.0013), 3)
    lng_fuzz = round(float(ping["lng"]) + _rnd.uniform(-0.0013, 0.0013), 3)
    return {
        "lat": lat_fuzz,
        "lng": lng_fuzz,
        "dest_lat": float(mi["dest_lat"]) if mi.get("dest_lat") else None,
        "dest_lng": float(mi["dest_lng"]) if mi.get("dest_lng") else None,
        "age_s": int(ping["age_s"] or 0),
        "dist_m": int(dist_m) if dist_m else None,
        # ETA grosera asumiendo 25 km/h promedio (urbano)
        "eta_min": (int(dist_m / 1000.0 / 25.0 * 60) if dist_m else None),
    }


@app.route("/t/<token>")
def tr_public_tracking(token):
    """Vista pública de tracking del cliente (sin login).
    El token vive en transport_commitments.public_token.
    """
    # Validación cheap del formato del token (evita queries con basura)
    if not token or len(token) < 16 or len(token) > 80 \
            or not re.match(r"^[A-Za-z0-9_\-]+$", token):
        abort(404)
    payload = _tracking_payload(token)
    if not payload:
        abort(404)
    return render_template(
        "transporte/public_tracking.html",
        token=token, data=payload,
        gmaps_key=GOOGLE_MAPS_API_KEY,
    )


@app.route("/t/<token>/status")
def tr_public_tracking_status(token):
    """JSON ligero para el polling del tracking público (cada 30s)."""
    if not token or len(token) < 16 or len(token) > 80 \
            or not re.match(r"^[A-Za-z0-9_\-]+$", token):
        return jsonify({"ok": False, "error": "invalid_token"}), 400
    if not _track_rate_ok(token):
        return jsonify({"ok": False, "error": "rate_limited",
                        "retry_after": int(_TRACK_RL_WINDOW)}), 429
    import time as _time
    ent = _TRACK_POLL_CACHE.get(token)
    if ent and (_time.time() - ent["ts"]) < _TRACK_POLL_TTL:
        return jsonify(ent["payload"])
    payload = _tracking_payload(token)
    if not payload:
        return jsonify({"ok": False, "error": "not_found"}), 404
    # FIX 2026-07-28: ver _tracking_payload_json_safe() -- evita que jsonify()
    # serialice los datetime crudos de _tracking_payload() en inglés (RFC 1123).
    payload = _tracking_payload_json_safe(payload)
    _TRACK_POLL_CACHE[token] = {"payload": payload, "ts": _time.time()}
    # Limpieza barata si crece mucho
    if len(_TRACK_POLL_CACHE) > 500:
        cutoff = _time.time() - _TRACK_POLL_TTL * 3
        for k in list(_TRACK_POLL_CACHE.keys()):
            if _TRACK_POLL_CACHE[k]["ts"] < cutoff:
                _TRACK_POLL_CACHE.pop(k, None)
    return jsonify(payload)


# ─────────────────────────────────────────────────────────────────────────────
#  BUSCADOR PÚBLICO DE TRANSPORTE (sin login)
#  El cliente entra a /seguimiento, pone su Nº de factura (o tracking FedEx)
#  + opcionalmente RUT, y lo redirigimos al tracking bonito /t/<token>.
# ─────────────────────────────────────────────────────────────────────────────

_PUBLIC_SEARCH_WINDOW = 60   # 60s
_PUBLIC_SEARCH_MAX    = 12   # 12 búsquedas / min / IP (anti-scraping)

def _public_search_rate_ok(ip):
    """Delega en _rl_check (persistido en app_rate_limits, cross-worker /
    cross-instancia Cloud Run). El parámetro `ip` ya no se usa acá — el
    identificador real lo resuelve _rl_identifier() dentro de _rl_check
    (cae a IP vía _rl_client_ip() porque este endpoint es público, sin
    login, así que g.user nunca está seteado). Se mantiene el parámetro
    en la firma para no tocar el call site."""
    return _rl_check("public_search", _PUBLIC_SEARCH_MAX, _PUBLIC_SEARCH_WINDOW)


def _norm_rut(s):
    """Normaliza un RUT a solo dígitos + dv en mayúscula. Ej '12.345.678-K' → '12345678K'."""
    if not s:
        return ""
    return "".join(c for c in str(s).upper() if c.isalnum())


@app.route("/seguimiento-legado", methods=["GET"])
def tr_public_seguimiento_form():
    """FIX 2026-07-30 (Daniel, en vivo: "no sé cómo acceder al seguimiento...
    habíamos hablado de eso, que coloque BLV o FCV y el número"): esta ruta
    y seguimiento_lookup_page() (más abajo) estaban AMBAS registradas en
    "/seguimiento" -- una colisión real de rutas. Werkzeug resolvía siempre
    a favor de la que se registra primero (esta, por orden de aparición en
    el archivo), así que seguimiento_lookup_page() -- la versión con
    doc_type (BLV/FCV) + RUT obligatorio, la que Daniel recordaba haber
    pedido -- quedaba MUERTA, invisible en producción sin que nada lo
    avisara. Se mueve esta versión (RUT opcional, más flexible pero menos
    segura -- puede devolver el pedido más reciente que matchee el número
    SIN verificar identidad) a una ruta aparte, sin enlazarla desde ningún
    lado, en vez de borrarla (Regla #4.2) por si se necesita su matcheo
    por tracking number más adelante.
    """
    return render_template("transporte/public_seguimiento.html",
                           error=None, q="", rut="")


@app.route("/seguimiento-legado", methods=["POST"])
def tr_public_seguimiento_buscar():
    """Busca un envío por Nº de factura, tracking FedEx, o ambos.
    Si encuentra match → redirige a /t/<token> (la vista bonita ya existente).
    Si no encuentra → vuelve al form con un error amigable.
    """
    ip = (request.headers.get("X-Forwarded-For") or request.remote_addr or "?").split(",")[0].strip()
    if not _public_search_rate_ok(ip):
        return render_template("transporte/public_seguimiento.html",
                               error="Has hecho muchas búsquedas seguidas. Espera un minuto y vuelve a intentarlo.",
                               q="", rut=""), 429
    q_raw   = (request.form.get("q") or "").strip()
    rut_raw = (request.form.get("rut") or "").strip()
    q = "".join(c for c in q_raw.upper() if c.isalnum())
    rut_norm = _norm_rut(rut_raw)
    if len(q) < 4:
        return render_template("transporte/public_seguimiento.html",
                               error="Ingresa tu Nº de factura o de seguimiento (mínimo 4 caracteres).",
                               q=q_raw, rut=rut_raw)

    # Buscamos por (a) tracking FedEx, (b) nudo (Nº doc), (c) nudo+tido concatenado.
    # Si el cliente dio RUT, lo usamos también como filtro de seguridad.
    rows = mysql_fetchall("""
        SELECT id, tido, nudo, cliente_rut, cliente_nombre, public_token
        FROM transport_commitments
        WHERE (
              REPLACE(UPPER(COALESCE(nudo,'')),  ' ', '') = %s
           OR REPLACE(UPPER(CONCAT(COALESCE(tido,''), COALESCE(nudo,''))), ' ', '') = %s
           OR id IN (
                SELECT commitment_id FROM transport_manifest_items
                WHERE REPLACE(UPPER(COALESCE(master_tracking_number,'')),' ','') = %s
                   OR REPLACE(UPPER(COALESCE(tracking_number,'')),' ','') = %s
              )
        )
        ORDER BY id DESC
        LIMIT 5
    """, (q, q, q, q)) or []

    if not rows:
        return render_template("transporte/public_seguimiento.html",
                               error="No encontramos ese envío. Revisa que el número esté correcto o pregunta a quien te lo emitió.",
                               q=q_raw, rut=rut_raw)

    # Si el cliente puso RUT, filtramos por él (match exacto normalizado).
    if rut_norm:
        match = [r for r in rows if _norm_rut(r.get("cliente_rut")) == rut_norm]
        if not match:
            return render_template("transporte/public_seguimiento.html",
                                   error="El RUT no coincide con este envío. Si crees que es un error, contáctanos.",
                                   q=q_raw, rut=rut_raw)
        cand = match[0]
    else:
        cand = rows[0]   # más reciente

    tok = (cand.get("public_token") or "").strip() or _tr_ensure_public_token(cand["id"])
    if not tok:
        return render_template("transporte/public_seguimiento.html",
                               error="No pudimos generar el link de seguimiento. Intenta de nuevo.",
                               q=q_raw, rut=rut_raw), 500
    return redirect(url_for("tr_public_tracking", token=tok))


# ═══════════════════════════════════════════════════════════════════════════
#  SEGUIMIENTO público — el cliente busca por factura/boleta + RUT
# ═══════════════════════════════════════════════════════════════════════════
# A diferencia de /t/<token> (link directo), aquí el cliente NO necesita link:
# escribe su nº de documento + RUT, lo encontramos, y le mostramos su estado.
# La validación cruzada (doc + RUT) evita que cualquiera escriba un nº y vea
# datos de otro. Rate-limited 10 intentos/hora por IP para frenar enumeración.

@app.route("/seguimiento")
def seguimiento_lookup_page():
    """Página pública del módulo Seguimiento. 2026-08-13: el formulario
    principal pide solo el código de seguimiento ILUS (ver
    seguimiento_por_codigo) -- ya no pide RUT. seguimiento_buscar (doc+RUT)
    sigue vivo como respaldo, no se borra (REGLA #4.2)."""
    return render_template("transporte/seguimiento_lookup.html",
                           error=None, prefill=None)


@app.route("/seguimiento/buscar", methods=["POST"])
@rate_limited("seguimiento_lookup", max_attempts=10, window_seconds=3600)
def seguimiento_buscar():
    """Busca el commitment por (tido?, nudo, rut) y redirige a /t/<token>.

    Acepta también búsqueda flexible (sin tido — el sistema barre BLV/FEV/GDV)
    para que el cliente no tenga que conocer la jerga interna del documento.
    """
    form = request.form
    doc_type   = (form.get("doc_type") or "").strip().upper()
    doc_number = (form.get("doc_number") or "").strip()
    raw_rut    = (form.get("customer_rut") or "").strip()
    # Limpieza tolerante: quita "N°", "Nº", puntos, espacios extra
    doc_number = re.sub(r"[Nn][°ºo]\s*", "", doc_number).strip()
    doc_number = re.sub(r"[^A-Za-z0-9]", "", doc_number)

    if not doc_number or not raw_rut:
        return render_template("transporte/seguimiento_lookup.html",
                               error="Ingresa el número de documento y tu RUT.",
                               prefill={"doc_type": doc_type,
                                        "doc_number": doc_number,
                                        "customer_rut": raw_rut}), 400

    rut_norm = normalizar_rut(raw_rut)
    if not rut_norm or len(rut_norm) < 8:
        return render_template("transporte/seguimiento_lookup.html",
                               error="El RUT no tiene un formato válido.",
                               prefill={"doc_type": doc_type,
                                        "doc_number": doc_number,
                                        "customer_rut": raw_rut}), 400

    # Buscar el commitment con tolerancia: por nudo, O por tracking del
    # courier (2026-07-30: se sumó esta rama al consolidar acá la búsqueda
    # que traía la ruta vieja de /seguimiento-legado, sin bajar la barra de
    # seguridad -- el RUT sigue siendo obligatorio en ambos casos).
    where = ["(nudo = %s OR id IN ("
             "SELECT commitment_id FROM transport_manifest_items "
             "WHERE tracking_number=%s OR master_tracking_number=%s))"]
    params = [doc_number, doc_number, doc_number]
    if doc_type:
        where.append("tido = %s")
        params.append(doc_type)
    # Match RUT: el cliente puede escribirlo con o sin puntos/DV. Normalizamos.
    # Comparamos los últimos N dígitos del cuerpo del RUT (sin DV) para robustez
    # frente a variantes de formato guardadas históricamente.
    where.append(
        "REPLACE(REPLACE(REPLACE(UPPER(IFNULL(cliente_rut,'')),'.',''),'-',''),' ','') "
        " LIKE %s"
    )
    rut_clean = re.sub(r"[^0-9Kk]", "", rut_norm).upper()
    params.append(f"%{rut_clean}%")

    sql = ("SELECT id, public_token, tido, nudo "
           "FROM transport_commitments WHERE " + " AND ".join(where) +
           " ORDER BY id DESC LIMIT 1")
    row = mysql_fetchone(sql, tuple(params))
    if not row:
        return render_template("transporte/seguimiento_lookup.html",
                               error=("No encontramos ese documento con ese RUT. "
                                      "Verifica los datos o contacta a soporte."),
                               prefill={"doc_type": doc_type,
                                        "doc_number": doc_number,
                                        "customer_rut": raw_rut}), 404

    # Lazy-generar token y redirigir a la página de tracking del cliente
    tok = _tr_ensure_public_token(row["id"])
    if not tok:
        return render_template("transporte/seguimiento_lookup.html",
                               error=("Tuvimos un problema técnico generando "
                                      "tu link. Intenta de nuevo en unos minutos."),
                               prefill=None), 500
    return redirect(url_for("tr_public_tracking", token=tok))


# ═══════════════════════════════════════════════════════════════════════════
#  SEGUIMIENTO SIN RUT (2026-08-13) — Daniel, viendo /seguimiento en vivo:
#  "no quiero que solicites el RUT... necesito que sea amigable". Auditoría
#  de ChatGPT sobre el código real confirmó que el RUT era prescindible: el
#  token largo del link directo ya es el mecanismo de seguridad real; para
#  cuando el cliente escribe a mano, un código corto y aleatorio (que NO es
#  predecible ni correlativo, a diferencia del número de factura) alcanza
#  igual de bien y es mucho menos incómodo de pedir.
#
#  seguimiento_buscar() (doc+RUT, arriba) NO se borra -- REGLA #4.2 -- queda
#  como respaldo interno/legado, simplemente ya no es lo que ofrece la UI
#  principal de /seguimiento.
# ═══════════════════════════════════════════════════════════════════════════

@app.route("/seguimiento/codigo", methods=["POST"])
@rate_limited("seguimiento_codigo", max_attempts=10, window_seconds=3600)
def seguimiento_por_codigo():
    """Busca el commitment por tracking_code (sin RUT) y redirige a /t/<token>."""
    raw = (request.form.get("tracking_code") or "").strip()
    code_norm = _tr_normalizar_tracking_code(raw)
    if len(code_norm) < 6:
        return render_template("transporte/seguimiento_lookup.html",
                               error="Ingresa tu código de seguimiento ILUS completo.",
                               prefill={"tracking_code": raw}), 400

    row = mysql_fetchone(
        "SELECT id, public_token FROM transport_commitments "
        "WHERE REPLACE(REPLACE(UPPER(IFNULL(tracking_code,'')),'ILUS-',''),'-','') = %s "
        "LIMIT 1",
        (code_norm,)
    )
    if not row:
        return render_template("transporte/seguimiento_lookup.html",
                               error=("No encontramos ese código. Revisa que esté "
                                      "completo o usa \"No encuentro mi código\"."),
                               prefill={"tracking_code": raw}), 404

    tok = _tr_ensure_public_token(row["id"])
    if not tok:
        return render_template("transporte/seguimiento_lookup.html",
                               error=("Tuvimos un problema técnico generando "
                                      "tu link. Intenta de nuevo en unos minutos."),
                               prefill=None), 500
    return redirect(url_for("tr_public_tracking", token=tok))


@app.route("/seguimiento/recuperar", methods=["GET"])
def seguimiento_recuperar_page():
    """Página 'No encuentro mi código': el cliente escribe su correo."""
    return render_template("transporte/seguimiento_recuperar.html", enviado=False)


@app.route("/seguimiento/recuperar", methods=["POST"])
@rate_limited("seguimiento_recuperar", max_attempts=5, window_seconds=3600)
def seguimiento_recuperar_enviar():
    """Manda por correo los enlaces de seguimiento activos para ese email.

    Respuesta SIEMPRE genérica ("si existe, te lo mandamos"), exista o no un
    pedido con ese correo -- evita que alguien use este formulario para
    confirmar si un email específico compró en ILUS (anti-enumeración, mismo
    criterio que pidió ChatGPT en la auditoría)."""
    email_raw = (request.form.get("email") or "").strip().lower()
    if email_raw and re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email_raw):
        try:
            rows = mysql_fetchall(
                "SELECT id, tido, nudo FROM transport_commitments "
                "WHERE LOWER(IFNULL(email,''))=%s "
                "ORDER BY id DESC LIMIT 8",
                (email_raw,)
            ) or []
            if rows:
                items_html = []
                for r in rows:
                    tok = _tr_ensure_public_token(r["id"])
                    code = _tr_ensure_tracking_code(r["id"])
                    if not tok:
                        continue
                    doc = f"{r.get('tido') or ''}-{r.get('nudo') or ''}".strip("-")
                    url = f"{_public_base_url()}/t/{tok}"
                    items_html.append(
                        f'<tr><td style="padding:10px 0;border-bottom:1px solid #eee">'
                        f'<a href="{url}" style="color:#c70010;font-weight:700;'
                        f'text-decoration:none">Pedido {doc}</a>'
                        + (f'<div style="color:#68707c;font-size:12px;margin-top:2px">'
                           f'Código: {code}</div>' if code else '')
                        + '</td></tr>'
                    )
                if items_html:
                    html = _ilus_email_master({
                        "subject":          _brand_subject("Tus enlaces de seguimiento"),
                        "preheader":        "Aquí están los enlaces para seguir tus pedidos.",
                        "title":            "Tus enlaces de seguimiento",
                        "subtitle":         "Seguimiento de despacho · ILUS Fitness",
                        "message":          ("Encontramos "
                                              + (f"{len(items_html)} pedidos" if len(items_html) != 1 else "1 pedido")
                                              + " asociados a este correo. Toca cualquiera para ver el estado en vivo:"),
                        "detail_rows_html": "".join(items_html),
                        "closing_message":  ("Si no reconoces esta solicitud, ignora este correo — "
                                              "nadie más puede ver tu pedido sin este enlace."),
                    })
                    _send_ilus_email(email_raw,
                                     _brand_subject("Tus enlaces de seguimiento"),
                                     html, evento="seguimiento_recuperar",
                                     modulo="transporte", asincrono=True)
        except Exception as _e_rec:
            print(f"[seguimiento_recuperar] falló: {_e_rec}", flush=True)
    # Misma respuesta exista o no un pedido con ese correo.
    return render_template("transporte/seguimiento_recuperar.html", enviado=True)


# ═══════════════════════════════════════════════════════════════════════════
#  FEDEX TRACK API — endpoints (asignar tracking + poll on-demand + cron)
# ═══════════════════════════════════════════════════════════════════════════

@app.route("/transporte/api/items/<int:item_id>/tracking-fedex", methods=["POST"])
@_tr_required
def tr_set_tracking_fedex(item_id):
    """Asocia un nº de tracking FedEx a este item y consulta el estado en vivo.

    Body JSON: { tracking_number: "780123456789" }

    Flow:
      1) Guarda tracking_number en el item.
      2) Llama a FedEx Track API.
      3) Aplica el estado venido al item (cambia estado_entrega si difiere) +
         INSERT evento con fuente='fedex'.
      4) Devuelve {ok, estado, estado_anterior, eta, last_event}.

    Si la API de FedEx falla, el tracking_number igual queda guardado para que
    el cron lo procese después.
    """
    body = request.get_json(silent=True, force=True) or {}
    tn = (body.get("tracking_number") or "").strip()
    if not tn or len(tn) < 10 or len(tn) > 30:
        return jsonify({"error": "tracking_number inválido"}), 400
    item = mysql_fetchone(
        "SELECT id, commitment_id FROM transport_manifest_items WHERE id=%s",
        (item_id,)
    )
    if not item:
        return jsonify({"error": "item no encontrado"}), 404

    # Persistir tracking_number primero (aunque FedEx falle, queda guardado)
    try:
        mysql_execute(
            "UPDATE transport_manifest_items SET tracking_number=%s WHERE id=%s",
            (tn, item_id)
        )
    except Exception as _e_save:
        return jsonify({"error": f"no se pudo guardar: {_e_save}"}), 500

    # Consultar FedEx en vivo (best-effort)
    try:
        results = _fedex_track_lookup([tn])
    except Exception as _e_fx:
        msg = str(_e_fx)
        # No revelar internal stuff al cliente
        if "FedEx Track API no configurada" in msg:
            return jsonify({
                "ok": True, "saved": True,
                "warning": "Tracking guardado. FedEx Track API no está "
                           "configurada en el servidor — el cron no podrá "
                           "actualizar estados automáticamente.",
            })
        return jsonify({
            "ok": True, "saved": True,
            "warning": f"Tracking guardado, pero FedEx no respondió: {msg[:140]}",
        })

    if not results:
        return jsonify({"ok": True, "saved": True,
                        "warning": "Tracking guardado. FedEx aún no tiene "
                                   "información de este envío."})

    r = results[0]
    comentario = r.get("last_event") or r.get("status_label") or ""
    apply_res = _tr_apply_carrier_status(
        item_id, r["estado_ilus"], fuente='fedex',
        tracking_number=tn,
        payload={"fedex": {
            "status_code":  r.get("status_code"),
            "status_label": r.get("status_label"),
            "eta":          r.get("eta"),
            "scans":        (r.get("scans") or [])[:10],
        }},
        comentario=comentario or None,
    )
    return jsonify({
        "ok":          True,
        "saved":       True,
        "changed":     apply_res.get("changed", False),
        "estado":      apply_res.get("nuevo", r["estado_ilus"]),
        "anterior":    apply_res.get("anterior", ""),
        "fedex_code":  r.get("status_code"),
        "fedex_label": r.get("status_label"),
        "eta":         r.get("eta"),
        "last_event":  comentario,
    })


@app.route("/transporte/api/manifiestos/<int:mid>/trackings-masivo", methods=["POST"])
@_tr_required
def tr_trackings_masivo(mid):
    """Asigna tracking numbers FedEx a múltiples items del manifiesto en una llamada.

    Body JSON: { items: [{ item_id: 123, tracking_number: "..." }, ...] }
    Guarda los TNs, hace batch-query a FedEx Track API, aplica estados.
    Devuelve { ok, resultados: [{ item_id, tracking_number, estado, changed, error }] }
    """
    body = request.get_json(silent=True, force=True) or {}
    raw_items = body.get("items", [])

    if not raw_items or not isinstance(raw_items, list):
        return jsonify({"error": "Se requiere items[]"}), 400
    if len(raw_items) > 50:
        return jsonify({"error": "Máximo 50 items por llamada"}), 400

    validated = []
    for entry in (raw_items or []):
        try:
            iid = int(entry.get("item_id") or 0)
        except (TypeError, ValueError):
            iid = 0
        tn = "".join(c for c in str(entry.get("tracking_number") or "").strip() if c.isalnum())
        if iid > 0 and 10 <= len(tn) <= 30:
            validated.append({"item_id": iid, "tracking_number": tn})

    if not validated:
        return jsonify({"error": "No hay tracking numbers válidos (mín. 10 chars)"}), 400

    # Verify all items belong to this manifest — trae también el tracking YA
    # guardado (FIX 2026-07-29, Daniel en vivo: "bloquea la subida a menos
    # que podamos... enviarlo" — este flujo pegaba el TN nuevo SIN mirar si
    # el item ya tenía uno, a diferencia de "Cargar Excel de OTs" que sí
    # exige confirmación explícita para reemplazar). Mismo criterio acá.
    item_ids = [v["item_id"] for v in validated]
    _ph = ",".join(["%s"] * len(item_ids))
    db_items = mysql_fetchall(
        f"SELECT id, tracking_number FROM transport_manifest_items "
        f"WHERE id IN ({_ph}) AND manifest_id=%s",
        tuple(item_ids) + (mid,)
    )
    valid_tn = {r["id"]: (r.get("tracking_number") or "").strip().upper() for r in (db_items or [])}
    confirm_re_envio = bool(body.get("confirm_re_envio"))

    resultados = []
    tn_to_iid = {}   # tracking_number → item_id (para correlacionar respuesta FedEx)

    for entry in validated:
        iid = entry["item_id"]
        tn  = entry["tracking_number"]
        if iid not in valid_tn:
            resultados.append({"item_id": iid, "tracking_number": tn,
                                "error": "item no pertenece a este manifiesto"})
            continue
        _tn_actual = valid_tn[iid]
        if _tn_actual and _tn_actual != tn.upper() and not confirm_re_envio:
            resultados.append({"item_id": iid, "tracking_number": tn,
                                "error": f"Este item ya tiene la OT {_tn_actual} — "
                                         "requiere confirmar reemplazo.",
                                "requiere_confirmacion": True, "ot_anterior": _tn_actual})
            continue
        try:
            mysql_execute(
                "UPDATE transport_manifest_items SET tracking_number=%s WHERE id=%s",
                (tn, iid)
            )
            resultados.append({"item_id": iid, "tracking_number": tn, "_saved": True})
            tn_to_iid[tn] = iid
        except Exception as e_save:
            resultados.append({"item_id": iid, "tracking_number": tn,
                                "error": str(e_save)[:120]})

    # Batch FedEx Track API query for all saved TNs
    if tn_to_iid:
        try:
            track_results = _fedex_track_lookup(list(tn_to_iid.keys()))
        except Exception as e_fx:
            # Not fatal — TNs are saved; cron will poll later
            warn_msg = ("FedEx Track API no configurada — el estado se actualizará al siguiente cron."
                        if "FedEx Track API no configurada" in str(e_fx)
                        else f"FedEx no respondió ({str(e_fx)[:80]})")
            for r in resultados:
                if r.get("_saved"):
                    r.pop("_saved", None)
                    r["ok"] = True
                    r["changed"] = False
                    r["warning"] = warn_msg
            return jsonify({"ok": True, "resultados": resultados})

        # Apply states from FedEx response
        fedex_by_tn = {t["tracking_number"]: t for t in (track_results or [])}
        for r in resultados:
            if not r.get("_saved"):
                continue
            r.pop("_saved", None)
            t = fedex_by_tn.get(r["tracking_number"])
            if not t:
                r["ok"] = True
                r["changed"] = False
                r["estado"] = None
                r["warning"] = "FedEx aún no tiene info de este envío."
                continue
            apply_res = _tr_apply_carrier_status(
                r["item_id"], t["estado_ilus"], fuente="fedex",
                tracking_number=t["tracking_number"],
                payload={"fedex": {
                    "status_code":  t.get("status_code"),
                    "status_label": t.get("status_label"),
                    "eta":          t.get("eta"),
                }},
                comentario=t.get("last_event") or t.get("status_label") or None,
            )
            r["ok"]      = True
            r["estado"]  = apply_res.get("nuevo", t["estado_ilus"])
            r["changed"] = apply_res.get("changed", False)

    # Any entry still marked _saved didn't get a FedEx response
    for r in resultados:
        if r.get("_saved"):
            r.pop("_saved", None)
            r["ok"] = True
            r["changed"] = False
            r["estado"] = None

    return jsonify({"ok": True, "resultados": resultados})


@app.route("/transporte/api/items/<int:item_id>/tracking-fedex", methods=["GET"])
@_tr_required
def tr_get_tracking_fedex(item_id):
    """Devuelve el último tracking conocido para este item (sin pollear FedEx).
    El front lo usa para pintar el modal de tracking si ya hay datos guardados.
    """
    r = mysql_fetchone(
        "SELECT id, tracking_number, last_carrier_poll_at, last_carrier_status, "
        "       last_carrier_source, estado_entrega "
        "FROM transport_manifest_items WHERE id=%s",
        (item_id,)
    )
    if not r:
        return jsonify({"error": "no encontrado"}), 404
    return jsonify({
        "ok":                True,
        "tracking_number":   r.get("tracking_number") or "",
        # FIX SEV-8a 2026-07-28: last_carrier_poll_at venía en UTC crudo
        # (str(...)[:19]) sin pasar por chile_fmt -- se pintaba tal cual en
        # el modal de tracking (transporte_manifiesto_detalle.js) 4 horas
        # adelantado respecto a la hora de Santiago.
        "last_poll":         (chile_fmt_filter(r.get("last_carrier_poll_at"), "%d/%m/%Y %H:%M:%S")
                               if r.get("last_carrier_poll_at") else ""),
        "last_status":       r.get("last_carrier_status") or "",
        "source":            r.get("last_carrier_source") or "",
        "estado_entrega":    r.get("estado_entrega") or "",
        "fedex_configurado": bool(FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET),
    })


# ═══════════════════════════════════════════════════════════════════════════
#  FEDEX SHIP API — endpoints: crear / cancelar OT, descargar etiqueta
# ═══════════════════════════════════════════════════════════════════════════

def _tr_item_para_ship(item_id):
    """Recupera todos los datos necesarios para crear un envío FedEx
    a partir de un item del manifiesto. Devuelve (item, recipient, packages).
    """
    it = mysql_fetchone("""
        SELECT mi.id, mi.commitment_id, mi.manifest_id, mi.tracking_number,
               mi.master_tracking_number, mi.ship_created_at,
               c.tido, c.nudo, c.cliente_nombre, c.cliente_rut,
               c.direccion, c.comuna, c.region, c.cod_postal,
               c.telefono, c.email,
               COALESCE(c.peso_export, 0)     AS peso_total,
               COALESCE(c.n_bultos, 1)        AS n_bultos,
               COALESCE(c.valor_bruto, 0)     AS valor_total,
               COALESCE(c.peso_predominante,0) AS peso_pred,
               c.productos_json
        FROM transport_manifest_items mi
        JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE mi.id=%s
    """, (item_id,))
    if not it:
        return None, None, None

    recipient = {
        "nombre":     it.get("cliente_nombre") or "Cliente",
        "empresa":    it.get("cliente_nombre") or "",
        "telefono":   it.get("telefono") or "",
        "email":      it.get("email") or "",
        "direccion":  it.get("direccion") or "",
        "comuna":     it.get("comuna") or "",
        "region":     it.get("region") or "",
        "cod_postal": it.get("cod_postal") or "",
    }

    n = max(int(it.get("n_bultos") or 1), 1)
    peso_total = float(it.get("peso_total") or it.get("peso_pred") or 0) or 1.0
    valor_total = float(it.get("valor_total") or 0)
    peso_por_bulto  = round(peso_total / n, 2) if n > 0 else peso_total
    valor_por_bulto = round(valor_total / n, 2) if n > 0 else 0
    referencia = (f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip()

    # Dimensiones por bulto: si no hay info real, asumimos caja media (40x40x40 cm).
    # TODO: si tenemos dimensiones reales por bulto en productos_json, usarlas.
    packages = [{
        "peso_kg":      peso_por_bulto,
        "largo":        40,
        "ancho":        40,
        "alto":         40,
        "valor":        valor_por_bulto,
        "descripcion":  f"Mercaderia {referencia}",
        "referencia":   referencia,
    } for _ in range(n)]

    return it, recipient, packages


@app.route("/transporte/api/diagnostico/fedex", methods=["GET"])
@_tr_required
def tr_diag_fedex():
    """Diagnóstico de credenciales FedEx Ship/Rate API (solo admin/superadmin).

    Responde la pregunta '¿por qué FedEx dice que falta configuración?' SIN
    exponer los valores secretos. Reporta:
      - app_usa: lo que el PROCESO vivo está usando (globales leídas al arrancar)
      - os_environ_ahora: lo que el CONTENEDOR tiene en os.environ en este momento
        (si difiere de app_usa, las vars se cambiaron sin reiniciar el proceso)
      - faltan: qué variables obligatorias están vacías
      - token_test (solo con ?token=1): prueba REAL contra FedEx para confirmar
        que las credenciales no solo están presentes sino que son VÁLIDAS.

    Nunca devuelve el valor de un secreto: solo set/len/preview enmascarado.
    """
    u = getattr(g, "user", None) or {}
    if (u.get("role") or "") not in ("admin", "superadmin"):
        return jsonify({"ok": False, "error": "Solo admin/superadmin"}), 403

    def _mask(v):
        v = (v or "")
        if not v:
            return {"set": False, "len": 0, "preview": ""}
        prev = (v[:2] + "…" + v[-2:]) if len(v) >= 6 else "•••"
        # Detecta espacios accidentales al inicio/fin (causa típica de fallo).
        return {"set": True, "len": len(v), "preview": prev,
                "espacios_extra": (v != v.strip())}

    obligatorias = ("FEDEX_RATE_CLIENT_ID", "FEDEX_RATE_CLIENT_SECRET", "FEDEX_ACCOUNT")
    extras       = ("FEDEX_ORIGIN_POSTAL", "FEDEX_ORIGIN_CITY")

    app_vals = {
        "FEDEX_RATE_CLIENT_ID":     _mask(FEDEX_RATE_CLIENT_ID),
        "FEDEX_RATE_CLIENT_SECRET": _mask(FEDEX_RATE_CLIENT_SECRET),
        "FEDEX_ACCOUNT":            _mask(FEDEX_ACCOUNT),
        "FEDEX_ORIGIN_POSTAL":      _mask(FEDEX_ORIGIN_POSTAL),
        "FEDEX_ORIGIN_CITY":        _mask(FEDEX_ORIGIN_CITY),
    }
    env_now = {k: _mask(os.environ.get(k, "")) for k in (obligatorias + extras)}

    # Nombres (NUNCA valores) de cualquier variable FEDEX_* presente en el
    # contenedor. Detecta el caso "Daniel la guardó con otro nombre" (typo de
    # nombre del secret) que de otro modo quedaría invisible.
    fedex_keys = sorted([k for k in os.environ if "FEDEX" in k.upper()])

    faltan = [k for k in obligatorias if not app_vals[k]["set"]]
    configurado = (len(faltan) == 0)

    # ¿La env del contenedor difiere de lo que la app cargó al arrancar?
    desfasado = any(
        env_now[k]["set"] != app_vals[k]["set"] or env_now[k]["len"] != app_vals[k]["len"]
        for k in obligatorias
    )

    out = {
        "ok": True,
        "configurado": configurado,
        "faltan": faltan,
        "app_usa": app_vals,
        "os_environ_ahora": env_now,
        "fedex_keys_en_entorno": fedex_keys,
        "desfase_env_vs_proceso": desfasado,
        "nota": ("Las credenciales se leen UNA sola vez al arrancar el proceso. "
                 "Si cambiaste las env vars hay que generar una nueva revisión "
                 "(redeploy o cambio de variable en Cloud Run) para que tomen "
                 "efecto. En este proyecto el deploy inyecta las credenciales "
                 "FedEx desde los secrets de GitHub FEDEX_RATE_CLIENT_ID / "
                 "FEDEX_RATE_CLIENT_SECRET / FEDEX_ACCOUNT: deben existir ahí "
                 "para sobrevivir un deploy (la consola de Cloud Run se borra)."),
    }

    if (request.args.get("token") or "") == "1":
        if not configurado:
            out["token_test"] = {"ok": False,
                                 "error": "Credenciales incompletas; no se probó token."}
        else:
            try:
                _fedex_token_cache["token"] = None
                _fedex_token_cache["expires_at"] = 0
                tok = _fedex_get_token()
                out["token_test"] = {"ok": bool(tok),
                                     "msg": "FedEx aceptó las credenciales (token OK)."}
            except Exception as e:
                out["token_test"] = {"ok": False,
                                     "error": f"FedEx rechazó las credenciales: {str(e)[:240]}"}

    return jsonify(out)


# ═══════════════════════════════════════════════════════════════════════════
#  LABORATORIO DE COTIZACIÓN FEDEX (diagnóstico, SOLO superadmin, SOLO lectura)
# ═══════════════════════════════════════════════════════════════════════════
# 2026-09-01 (caso FCV 11431 · Copiapó · 13 bultos · 1.127,451 kg):
#   - la tabla interna "FedEx Directo" cotiza $448.621
#   - FedEx cobró de verdad $736.020 con el servicio "FedEx Carga Prioritaria"
#   - nuestra Rate API devuelve FEDEX_PRIORITY_EXPRESS (paquetería) a ~$6.650/kg
#     y rechaza con HTTP 400 el bulto único de 1.127 kg.
# No sabemos QUÉ combinación de request reproduce los $736.020: hay al menos
# cuatro sospechosos independientes (serviceType de CARGA vs paquetería,
# multibulto real vs bulto único, rateRequestType ACCOUNT vs LIST, y el código
# postal real vs la aproximación por zona). Adivinar de a uno editando
# _fedex_calc_rate y desplegando es carísimo en tiempo.
#
# Este endpoint permite mandar VARIANTES del request a la Rate API real desde
# el navegador y ver la respuesta CRUDA completa (todos los rateReplyDetails,
# todos los serviceType, todos los surCharges) para descubrir empíricamente la
# combinación correcta ANTES de tocar el cotizador de producción.
#
# Garantías (no negociables):
#   · SOLO superadmin.
#   · SOLO cotiza (POST a /rate/v1/rates/quotes). NUNCA crea envíos, NUNCA
#     pide etiquetas, NUNCA escribe en MySQL ni en el ERP (REGLA #4.1).
#   · NUNCA expone credenciales: el número de cuenta viaja enmascarado y TODA
#     la respuesta pasa por _fedex_sanitizar_log antes de salir (REGLA #4).
#   · Reusa _fedex_get_token() — no duplica el OAuth.
#   · No modifica ni reemplaza _fedex_calc_rate ni /api/asignar/tarifa-fedex:
#     convive con ellos (REGLA #4.2).

# Variantes precargadas, ordenadas por probabilidad de reproducir los $736.020.
# Cada una cambia UNA cosa respecto de la anterior para poder atribuir la
# diferencia de precio a una causa concreta.
_FEDEX_LAB_VARIANTES = {
    # A — la hipótesis principal: dejar que FedEx ofrezca TODOS sus servicios
    # (sin serviceType ni carrierCodes), con los 13 bultos reales declarados,
    # pidiendo tarifa de cuenta. Si "FedEx Carga Prioritaria" existe para el
    # par Santiago→Copiapó, tiene que aparecer acá con su enum real.
    "A": {
        "descripcion": "Multibulto real + SIN serviceType + SIN carrierCodes + ACCOUNT/LIST",
        "service_type": None, "carrier_codes": None,
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": True,
    },
    # B — igual que A pero fijando el enum que, por descripción, corresponde a
    # "FedEx Carga Prioritario (D6)". Si A no lo lista, B dirá si es que el
    # servicio no está habilitado o si es que FedEx no lo ofrece para ese lane.
    "B": {
        "descripcion": "Multibulto real + serviceType FEDEX_PRIORITY_FREIGHT (D6)",
        "service_type": "FEDEX_PRIORITY_FREIGHT", "carrier_codes": None,
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": True,
    },
    # C — la variante express de carga, "FedEx Carga Prioritario Express (D5)".
    "C": {
        "descripcion": "Multibulto real + serviceType FEDEX_PRIORITY_EXPRESS_FREIGHT (D5)",
        "service_type": "FEDEX_PRIORITY_EXPRESS_FREIGHT", "carrier_codes": None,
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": True,
    },
    # D — CONTROL del efecto ACCOUNT vs LIST: mismo request de A pero pidiendo
    # solo tarifa pública. La diferencia contra A es, exactamente, lo que vale
    # nuestra tarifa negociada. Si A y D dan lo MISMO, la cuenta no tiene
    # tarifas negociadas expuestas por API y ese es un problema comercial, no
    # de código.
    "D": {
        "descripcion": "CONTROL tarifa pública: multibulto real + solo LIST",
        "service_type": None, "carrier_codes": None,
        "rate_request_types": ["LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": True,
    },
    # E — CONTROL del efecto multibulto: reproduce el request de HOY
    # (_fedex_calc_rate), un bulto único con el peso total. Sirve para capturar
    # el mensaje de error EXACTO del 400 y confirmar que el límite de 68 kg por
    # pieza es la causa.
    "E": {
        "descripcion": "CONTROL bulto único (lo que hace hoy _fedex_calc_rate)",
        "service_type": None, "carrier_codes": ["FDXE"],
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "DROPOFF_AT_FEDEX_LOCATION",
        "con_dimensiones": False, "forzar_bulto_unico": True,
    },
    # F — CONTROL del efecto de las dimensiones: mismos 13 bultos pero sin
    # declarar medidas. Aísla cuánto del precio lo pone el peso dimensional
    # (nuestro divisor interno es 4000; el de FedEx Express suele ser 5000).
    "F": {
        "descripcion": "CONTROL sin dimensiones: multibulto real, solo pesos",
        "service_type": None, "carrier_codes": None,
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": False,
    },
    # G — CONTROL del reparto: 13 bultos IGUALES de peso_total/13 y cajas
    # 40x40x40, que es lo que hoy arma _tr_item_para_ship para la Ship API.
    # Comparado con A dice si vale la pena leer app_bultos para cotizar.
    "G": {
        "descripcion": "CONTROL reparto parejo (lo que hace hoy _tr_item_para_ship)",
        "service_type": None, "carrier_codes": None,
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": True, "forzar_reparto_parejo": True,
    },
}


def _fedex_lab_bultos_de_doc(tido, nudo):
    """Devuelve los bultos FÍSICOS REALES de un documento del ERP.

    Cruce local: líneas del documento (_cubicador_fetch, solo SELECT al ERP)
    × filas de `app_bultos` (MySQL de ILUS). El ERP Random NUNCA tiene medidas
    por bulto y NUNCA se escribe (REGLA #4.1).

    OJO con la trampa conocida: peso_kg_u / peso_vol_u / vol_u de la línea son
    AGREGADOS SUM de TODA la ficha, no medidas de un bulto. Acá NO se usan:
    cada bulto sale de su propia fila de app_bultos.

    Devuelve (bultos, avisos) donde bultos es
    [{"sku", "peso", "largo", "ancho", "alto", "bulto_num"}].
    """
    avisos = []
    try:
        _hdr, lineas = _cubicador_fetch(tido, nudo, fast=True)
    except Exception as e:
        return [], [f"No se pudo leer {tido} {nudo} del ERP: {str(e)[:180]}"]

    # Solo carga real: las líneas ZZ (flete/servicio) y los descuentos no viajan.
    lineas_carga = [l for l in (lineas or [])
                    if not l.get("es_zz") and not l.get("es_descuento")]

    app_ids = sorted({l["app_id"] for l in lineas_carga
                      if l.get("tiene_bultos") and l.get("app_id")})
    if not app_ids:
        return [], [f"{tido} {nudo}: ninguna línea tiene bultos cargados en la ficha."]

    ph = ",".join(["%s"] * len(app_ids))
    filas = mysql_fetchall(
        f"SELECT product_id, bulto_num, largo, ancho, alto, peso "
        f"FROM `{BULTOS_TABLE}` WHERE product_id IN ({ph}) "
        f"ORDER BY product_id, bulto_num",
        tuple(app_ids),
    ) or []

    por_pid = {}
    for f in filas:
        por_pid.setdefault(f["product_id"], []).append(f)

    bultos = []
    for l in lineas_carga:
        pid = l.get("app_id")
        if not l.get("tiene_bultos") or not pid:
            avisos.append(f"SKU {l.get('sku')}: sin medidas en la ficha — NO entra al request.")
            continue
        filas_ficha = por_pid.get(pid) or []
        if not filas_ficha:
            avisos.append(f"SKU {l.get('sku')}: la línea dice tener bultos pero app_bultos no devolvió filas.")
            continue
        # Los bultos de app_bultos son los de UNA unidad de venta: se repiten
        # tantas veces como unidades físicas lleve la línea. El multiplicador
        # correcto es bultos_equivalentes, NUNCA cantidad (SKUs que se venden
        # de a par duplicarían el peso — bug real FCV 11225).
        veces_f = float(l.get("bultos_equivalentes") or 1) or 1.0
        veces = max(int(round(veces_f)), 1)
        if abs(veces_f - veces) > 0.01:
            avisos.append(f"SKU {l.get('sku')}: bultos_equivalentes={veces_f} no es entero, se redondeó a {veces}.")
        for _ in range(veces):
            for fb in filas_ficha:
                bultos.append({
                    "sku":       l.get("sku"),
                    "bulto_num": int(fb["bulto_num"]),
                    "peso":      float(fb["peso"]  or 0),
                    "largo":     float(fb["largo"] or 0),
                    "ancho":     float(fb["ancho"] or 0),
                    "alto":      float(fb["alto"]  or 0),
                })
    return bultos, avisos


def _fedex_lab_normalizar_bultos(bultos, con_dimensiones=True):
    """Convierte la lista interna de bultos a requestedPackageLineItems.

    Un elemento por bulto (groupPackageCount=1 + sequenceNumber 1-based), que
    es lo que FedEx exige para multibulto real — el mismo patrón que ya usa
    _fedex_create_shipment para la Ship API.
    """
    items = []
    for idx, b in enumerate(bultos, start=1):
        peso = max(round(float(b.get("peso") or 0), 1), 0.5)
        item = {
            "sequenceNumber":    idx,
            "groupPackageCount": 1,
            "weight": {"units": "KG", "value": peso},
        }
        if con_dimensiones:
            largo = max(int(round(float(b.get("largo") or 0))), 1)
            ancho = max(int(round(float(b.get("ancho") or 0))), 1)
            alto  = max(int(round(float(b.get("alto")  or 0))), 1)
            item["dimensions"] = {"length": largo, "width": ancho,
                                  "height": alto, "units": "CM"}
        items.append(item)
    return items


def _fedex_lab_resumen(data):
    """Resume la respuesta de FedEx: un renglón por servicio ofrecido, con su
    precio, su rateType (ACCOUNT = negociada / LIST = pública) y sus recargos
    desglosados. Es lo que hay que mirar para encontrar los $736.020.
    """
    out = []
    for r in (data.get("output", {}).get("rateReplyDetails") or []):
        for d in (r.get("ratedShipmentDetails") or []):
            srd = d.get("shipmentRateDetail") or {}
            out.append({
                "servicio":         r.get("serviceType"),
                "servicio_nombre":  r.get("serviceName"),
                "rate_type":        d.get("rateType"),
                "rated_type_usado": d.get("ratedWeightMethod"),
                "moneda":           d.get("currency"),
                "total_neto":       d.get("totalNetCharge"),
                "total_base":       d.get("totalBaseCharge"),
                "total_recargos":   d.get("totalSurcharges"),
                "total_descuentos": d.get("totalDiscounts"),
                "peso_facturado":   (srd.get("totalBillingWeight") or {}),
                "dim_divisor":      srd.get("dimDivisor"),
                "recargos": [
                    {"tipo": s.get("type"), "desc": s.get("description"),
                     "monto": s.get("amount")}
                    for s in (srd.get("surCharges") or [])
                ],
                "transito": (r.get("operationalDetail") or {}).get("transitTime")
                            or r.get("commit", {}).get("dateDetail", {}).get("dayFormat"),
            })
    out.sort(key=lambda x: (float(x.get("total_neto") or 0)))
    return out


@app.route("/transporte/api/diagnostico/fedex-rate-lab", methods=["GET", "POST"])
@login_required
def tr_diag_fedex_rate_lab():
    """Laboratorio de cotización FedEx — SOLO superadmin, SOLO lectura.

    Manda una variante del request a la Rate API REAL y devuelve la respuesta
    CRUDA completa + un resumen legible por servicio. No crea envíos.

    USO RÁPIDO DESDE EL NAVEGADOR (variantes precargadas):
      /transporte/api/diagnostico/fedex-rate-lab?variante=A&tido=FCV&nudo=11431&comuna=COPIAPO
      ...&variante=todas   → corre A..G una tras otra y devuelve el comparativo
      ...&variante=A&postal=1530000   → fuerza un código postal específico

    USO AVANZADO (POST JSON, para armar un request a mano):
      {
        "tido": "FCV", "nudo": "11431",        # opcional: saca los bultos reales
        "comuna": "COPIAPO",                    # o "postal_destino": "1530000"
        "calle_destino": "Los Carrera 1234",
        "ciudad_destino": "Copiapo",
        "residencial": false,
        "valor_declarado": 12345678, "moneda_declarada": "CLP",
        "service_type": "FEDEX_PRIORITY_FREIGHT",   # o null = que FedEx ofrezca todo
        "carrier_codes": null,                      # o ["FDXE"]
        "rate_request_types": ["ACCOUNT", "LIST"],
        "pickup_type": "USE_SCHEDULED_PICKUP",
        "con_dimensiones": true,
        "bultos": [{"peso": 390, "largo": 120, "ancho": 80, "alto": 60}, ...],
        "peso_total": 1127.451, "n_bultos": 13      # fallback si no hay bultos
      }
    """
    import json as _json
    import requests as _req

    # ── Gate: SOLO superadmin ────────────────────────────────────────────
    if not g.permissions.get("superadmin"):
        return jsonify({"ok": False, "error": "Solo superadmin"}), 403

    if not (FEDEX_RATE_CLIENT_ID and FEDEX_RATE_CLIENT_SECRET and FEDEX_ACCOUNT):
        return jsonify({"ok": False,
                        "error": "La cotización con FedEx no está configurada. "
                                 "Revisa /transporte/api/diagnostico/fedex."}), 503

    body_in = request.get_json(silent=True, force=True) or {}
    args    = request.args

    def _p(clave, default=None):
        """Parámetro: primero el JSON del POST, después el query string."""
        if clave in body_in:
            return body_in.get(clave)
        return args.get(clave, default)

    # ── Destino ──────────────────────────────────────────────────────────
    comuna  = (_p("comuna") or "").strip()
    postal  = _fedex_postal_cl(_p("postal_destino") or _p("postal") or "")
    avisos  = []
    if not postal and comuna:
        postal = _fedex_postal_cl(_codigo_postal_chile(comuna))
        if postal:
            avisos.append(f"Código postal {postal} resuelto desde la comuna '{comuna}' "
                          f"(tabla oficial FedEx cl_codigos_postales).")
    if not postal:
        return jsonify({"ok": False,
                        "error": "Falta el destino: manda 'postal_destino' o 'comuna'."}), 400

    ciudad_dest = _fedex_clean_str(_p("ciudad_destino") or comuna, 35)
    calle_dest  = _fedex_split_address(_p("calle_destino") or "")
    residencial = str(_p("residencial", "false")).strip().lower() in ("1", "true", "si", "sí")

    # ── Origen (por defecto la bodega real de ILUS Fitness) ──────────────
    postal_org = _fedex_postal_cl(_p("postal_origen") or FEDEX_ORIGIN_POSTAL)
    ciudad_org = _fedex_clean_str(_p("ciudad_origen") or FEDEX_ORIGIN_CITY, 35)
    calle_org  = _fedex_split_address(_p("calle_origen")
                                      or ILUS_REMITENTE.get("bodega") or "")

    # ── Bultos ───────────────────────────────────────────────────────────
    bultos = _p("bultos") or []
    tido   = (_p("tido") or "").strip().upper()
    nudo   = (_p("nudo") or "").strip()
    if not bultos and tido and nudo:
        bultos, avisos_doc = _fedex_lab_bultos_de_doc(tido, nudo)
        avisos.extend(avisos_doc)
    if not bultos:
        # Último recurso: reparto parejo con lo que el operador declare.
        peso_total = float(_p("peso_total", 0) or 0)
        n_bultos   = max(int(float(_p("n_bultos", 1) or 1)), 1)
        if peso_total <= 0:
            return jsonify({"ok": False,
                            "error": "Sin bultos: manda 'bultos', o 'tido'+'nudo', "
                                     "o 'peso_total'+'n_bultos'."}), 400
        bultos = [{"sku": "(reparto parejo)", "bulto_num": i + 1,
                   "peso": round(peso_total / n_bultos, 2),
                   "largo": 40, "ancho": 40, "alto": 40} for i in range(n_bultos)]
        avisos.append(f"Sin desglose real: {n_bultos} bultos parejos de "
                      f"{round(peso_total / n_bultos, 2)} kg y cajas 40×40×40 cm.")
    if len(bultos) > 100:
        return jsonify({"ok": False, "error": "Máximo 100 bultos por consulta."}), 400

    peso_total_real = round(sum(float(b.get("peso") or 0) for b in bultos), 3)
    valor_declarado = float(_p("valor_declarado", 0) or 0)
    moneda_decl     = (_p("moneda_declarada") or "CLP").strip().upper()

    # ── Qué variantes correr ─────────────────────────────────────────────
    var_pedida = (str(_p("variante") or "").strip().upper())
    if var_pedida in ("TODAS", "ALL", "*"):
        claves = list(_FEDEX_LAB_VARIANTES.keys())
    elif var_pedida in _FEDEX_LAB_VARIANTES:
        claves = [var_pedida]
    elif var_pedida:
        return jsonify({"ok": False,
                        "error": f"Variante '{var_pedida}' no existe. "
                                 f"Opciones: {', '.join(_FEDEX_LAB_VARIANTES)} o 'todas'."}), 400
    else:
        claves = [None]   # variante libre: se arma con lo que vino en el body

    try:
        token = _fedex_get_token()
    except Exception as e:
        print(f"[FEDEX][LAB] token: {_fedex_sanitizar_log(e)}", flush=True)
        return jsonify({"ok": False,
                        "error": "FedEx no aceptó las credenciales. "
                                 "Revisa /transporte/api/diagnostico/fedex?token=1"}), 502

    def _sanear(obj):
        """Sanitiza credenciales de cualquier estructura antes de devolverla
        al navegador (REGLA #4): serializa, tapa secretos, vuelve a parsear.
        """
        try:
            return _json.loads(_fedex_sanitizar_log(_json.dumps(obj, ensure_ascii=False)))
        except Exception:
            return {"_no_serializable": _fedex_sanitizar_log(str(obj))[:4000]}

    resultados = []
    for clave in claves:
        cfg = dict(_FEDEX_LAB_VARIANTES.get(clave) or {})
        # Cualquier clave presente en el JSON del POST pisa a la variante
        # precargada (así se puede correr "A pero con otro pickupType").
        # Solo desde el body: por query string estos campos serían strings y
        # carrier_codes/rate_request_types tienen que viajar como listas.
        for k in ("service_type", "carrier_codes", "rate_request_types",
                  "pickup_type", "con_dimensiones"):
            if k in body_in:
                cfg[k] = body_in.get(k)
        service_type = cfg.get("service_type")
        carrier_codes = cfg.get("carrier_codes")
        rrt = cfg.get("rate_request_types") or ["ACCOUNT", "LIST"]
        pickup = cfg.get("pickup_type") or "USE_SCHEDULED_PICKUP"
        con_dims = bool(cfg.get("con_dimensiones", True))

        bultos_var = bultos
        if cfg.get("forzar_bulto_unico"):
            bultos_var = [{"sku": "(bulto único)", "bulto_num": 1,
                           "peso": peso_total_real, "largo": 40, "ancho": 40, "alto": 40}]
        elif cfg.get("forzar_reparto_parejo"):
            n = len(bultos)
            bultos_var = [{"sku": "(parejo)", "bulto_num": i + 1,
                           "peso": round(peso_total_real / n, 2),
                           "largo": 40, "ancho": 40, "alto": 40} for i in range(n)]

        rpl = _fedex_lab_normalizar_bultos(bultos_var, con_dimensiones=con_dims)
        if valor_declarado > 0:
            reparto = round(valor_declarado / len(rpl), 2)
            for it in rpl:
                it["declaredValue"] = {"amount": reparto, "currency": moneda_decl}

        shipment = {
            "shipper": {"address": {
                "city":        ciudad_org,
                "postalCode":  postal_org,
                "countryCode": "CL",
                "streetLines": calle_org,     # nunca [""] — FedEx lo rechaza
                "residential": False,
            }},
            "recipient": {"address": {
                "city":        ciudad_dest or "Santiago",
                "postalCode":  postal,
                "countryCode": "CL",
                "streetLines": calle_dest,    # placeholder "Sin direccion" si no hay
                "residential": residencial,
            }},
            "pickupType":                pickup,
            "packagingType":             "YOUR_PACKAGING",
            "rateRequestType":           rrt,
            "totalPackageCount":         len(rpl),   # obligatorio en multibulto
            "requestedPackageLineItems": rpl,
        }
        if service_type:
            shipment["serviceType"] = service_type

        body = {
            "accountNumber":            {"value": FEDEX_ACCOUNT},
            "requestedShipment":        shipment,
            "returnLocalizedDateTime":  True,
            "webSiteCountryCode":       "CL",
        }
        if carrier_codes:
            body["carrierCodes"] = carrier_codes

        item = {
            "variante":      clave or "(libre)",
            "descripcion":   cfg.get("descripcion", "Variante armada a mano desde el body"),
            "service_type":  service_type,
            "carrier_codes": carrier_codes,
            "rate_request_types": rrt,
            "pickup_type":   pickup,
            "con_dimensiones": con_dims,
            "n_bultos":      len(rpl),
            "peso_total_kg": round(sum(i["weight"]["value"] for i in rpl), 2),
        }

        try:
            resp = _req.post(
                FEDEX_RATE_URL,
                json=body,
                headers={"Authorization": f"Bearer {token}",
                         "Content-Type":  "application/json",
                         "X-locale":      "es_CL"},
                timeout=30,
            )
        except Exception as e:
            print(f"[FEDEX][LAB] variante={clave} red: {_fedex_sanitizar_log(e)}", flush=True)
            item.update({"ok": False, "http": None,
                         "error": "No hubo respuesta de FedEx (timeout o red)."})
            resultados.append(item)
            continue

        item["http"] = resp.status_code
        if resp.status_code >= 400:
            errores, crudo = _fedex_errores_de_respuesta(resp)
            detalle = "; ".join(f"{e['code']}: {e['message']}".strip(": ")
                                for e in errores if (e["code"] or e["message"]))
            print(f"[FEDEX][LAB] variante={clave} HTTP {resp.status_code} · "
                  f"postal={postal} bultos={len(rpl)} peso={item['peso_total_kg']}kg · "
                  f"errores=[{_fedex_sanitizar_log(detalle) or 'sin detalle'}]", flush=True)
            item.update({
                "ok": False,
                # Diagnóstico superadmin: acá SÍ interesa el detalle exacto de
                # FedEx (es la única pista del 400), ya sanitizado de secretos.
                "errores_fedex": _sanear(errores),
                "cuerpo_crudo":  crudo,
                "mensaje_operador": _fedex_mensaje_usuario(errores),
            })
            resultados.append(item)
            continue

        try:
            data = resp.json()
        except Exception:
            item.update({"ok": False, "error": "FedEx respondió 200 con un cuerpo no-JSON.",
                         "cuerpo_crudo": _fedex_sanitizar_log((resp.text or "")[:2000])})
            resultados.append(item)
            continue

        resumen = _fedex_lab_resumen(data)
        item.update({
            "ok": True,
            "servicios_ofrecidos": sorted({(r.get("servicio") or "?") for r in resumen}),
            "resumen": resumen,
            "mas_barato": resumen[0] if resumen else None,
            "respuesta_cruda": _sanear(data),
        })
        if not resumen:
            item["ok"] = False
            item["error"] = "FedEx respondió 200 pero sin ninguna tarifa para este envío."
        resultados.append(item)

    return jsonify({
        "ok": True,
        "solo_lectura": "Este endpoint solo cotiza. No crea envíos ni escribe nada.",
        "destino":  {"comuna": comuna, "postal": postal, "ciudad": ciudad_dest,
                     "residencial": residencial},
        "origen":   {"ciudad": ciudad_org, "postal": postal_org, "calle": calle_org},
        "carga":    {"n_bultos": len(bultos), "peso_total_kg": peso_total_real,
                     "valor_declarado": valor_declarado,
                     "bultos": bultos[:100]},
        "avisos":   avisos,
        "variantes_disponibles": {k: v["descripcion"] for k, v in _FEDEX_LAB_VARIANTES.items()},
        "resultados": resultados,
        "cuenta_fedex_usada": (FEDEX_ACCOUNT[:2] + "…" + FEDEX_ACCOUNT[-2:]) if len(FEDEX_ACCOUNT) >= 6 else "•••",
    })


@app.route("/transporte/api/items/<int:item_id>/crear-ot-fedex", methods=["POST"])
@_tr_required
def tr_crear_ot_fedex(item_id):
    """Crea un envío FedEx para este item: pide TN + etiqueta a FedEx, los guarda
    y deja el TN listo para Track API.

    Body opcional: {
        service_type:  "FEDEX_PRIORITY" (default),
        label_format:  "PDF" | "ZPLII" (default PDF),
        pickup_type:   "USE_SCHEDULED_PICKUP" | "DROPOFF_AT_FEDEX_LOCATION",
        notificar:     true/false (mandar email al destinatario),
    }
    """
    body = request.get_json(silent=True, force=True) or {}
    it, recipient, packages = _tr_item_para_ship(item_id)
    if not it:
        return jsonify({"error": "item no encontrado"}), 404
    if it.get("master_tracking_number") and not body.get("forzar"):
        return jsonify({
            "error": "Esta factura ya tiene OT FedEx",
            "master_tracking_number": it["master_tracking_number"],
        }), 409

    notify_email = recipient["email"] if body.get("notificar") else ""

    res = _fedex_create_shipment(
        recipient=recipient,
        packages=packages,
        reference=(f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip(),
        service_type=body.get("service_type"),
        label_format=(body.get("label_format") or "PDF"),
        label_stock=(body.get("label_stock") or "STOCK_4X6"),
        pickup_type=(body.get("pickup_type") or "USE_SCHEDULED_PICKUP"),
        notify_email=notify_email,
        notify_name=recipient.get("nombre"),
    )

    if not res.get("ok"):
        # Guardar el error para debug
        try:
            mysql_execute(
                "UPDATE transport_manifest_items SET ship_error=%s WHERE id=%s",
                ((res.get("error") or "")[:600], item_id)
            )
        except Exception:
            pass
        _tr_log("manifest_item", item_id, "OT FedEx error",
                (res.get("error") or "FedEx no respondió")[:200])
        return jsonify({
            "ok":    False,
            "error": res.get("error") or "FedEx no respondió",
            "error_code": res.get("error_code"),
        }), 502

    import json as _jp
    master_tn = res["master_tracking_number"]
    piece_tns = res.get("piece_trackings") or []
    label_b64 = res.get("label_b64") or ""
    label_fmt = res.get("label_format") or "PDF"
    piece_labels = res.get("piece_labels") or []

    n_b = len(piece_tns) if piece_tns else int(it.get("n_bultos") or 1)
    try:
        mysql_execute("""
            UPDATE transport_manifest_items
            SET master_tracking_number=%s,
                tracking_number=%s,
                piece_trackings_json=%s,
                ship_label_b64=%s,
                ship_labels_json=%s,
                ship_label_format=%s,
                ship_bultos=%s,
                ship_label_outdated=0,
                ship_created_at=NOW(),
                ship_cancelled_at=NULL,
                ship_error=NULL,
                last_carrier_source='fedex'
            WHERE id=%s
        """, (
            master_tn, master_tn,
            _jp.dumps(piece_tns) if piece_tns else None,
            label_b64 or None,
            _jp.dumps(piece_labels) if piece_labels else None,
            label_fmt,
            n_b,
            item_id,
        ))
    except Exception as e_save:
        return jsonify({
            "ok":    False,
            "error": f"Envío creado en FedEx (TN {master_tn}) pero falló al guardar: {str(e_save)[:120]}",
            "master_tracking_number": master_tn,
        }), 500

    _tr_ship_snapshot(item_id, "ot_creada", {"tn": master_tn, "bultos": n_b})
    _tr_log("manifest_item", item_id, "OT FedEx creada",
            f"TN {master_tn} ({len(piece_tns)} bulto/s)")
    # 2026-06-14 (Daniel): al generar la etiqueta FedEx el pedido pasa a
    # "Entregado a transporte" (delegado a FedEx) y se avisa al cliente.
    # _tr_apply_carrier_status solo emite/notifica si el estado CAMBIÓ (dedup).
    try:
        _tr_apply_carrier_status(item_id, 'Entregado a transporte', fuente='sistema',
                                 comentario='Etiqueta FedEx generada',
                                 notify_cliente=True)
    except Exception as _e_ot_ev:
        print(f"[tr_event ot_fedex] item={item_id}: {_e_ot_ev}", flush=True)

    return jsonify({
        "ok":                      True,
        "master_tracking_number":  master_tn,
        "piece_trackings":         piece_tns,
        "n_bultos":                len(piece_tns),
        "label_format":            label_fmt,
        "has_label":               bool(label_b64),
        "label_url":               url_for("tr_etiqueta_fedex", item_id=item_id),
    })


@app.route("/transporte/api/manifiestos/<int:mid>/crear-ots-fedex-masivo", methods=["POST"])
@_tr_required
def tr_crear_ots_fedex_masivo(mid):
    """Crea OTs FedEx para TODOS los items del manifiesto que aún no la tengan
    (o para los item_ids específicos del body).

    Body opcional: {
        item_ids: [1,2,3],   // si vacío, todos los sin OT
        service_type, label_format, label_stock, pickup_type, notificar
    }

    Returns: { ok, resultados: [{item_id, ok, master_tracking_number?, error?}] }
    """
    body = request.get_json(silent=True, force=True) or {}
    target_ids = body.get("item_ids") or []

    if target_ids:
        items = mysql_fetchall(
            "SELECT id FROM transport_manifest_items "
            "WHERE manifest_id=%s AND id IN ({})".format(",".join(["%s"] * len(target_ids))),
            (mid,) + tuple(int(x) for x in target_ids)
        )
    else:
        items = mysql_fetchall(
            "SELECT id FROM transport_manifest_items "
            "WHERE manifest_id=%s "
            "  AND (master_tracking_number IS NULL OR master_tracking_number='')",
            (mid,)
        )

    if not items:
        return jsonify({"error": "No hay items elegibles en este manifiesto"}), 400
    if len(items) > 30:
        return jsonify({"error": "Demasiados items (máx. 30 por lote)"}), 400

    resultados = []
    common_opts = {
        "service_type":  body.get("service_type"),
        "label_format":  body.get("label_format") or "PDF",
        "label_stock":   body.get("label_stock")  or "STOCK_4X6",
        "pickup_type":   body.get("pickup_type")  or "USE_SCHEDULED_PICKUP",
        "notificar":     bool(body.get("notificar")),
    }

    for it_row in items:
        iid = it_row["id"]
        it, recipient, packages = _tr_item_para_ship(iid)
        if not it:
            resultados.append({"item_id": iid, "ok": False, "error": "item no encontrado"})
            continue
        if it.get("master_tracking_number"):
            resultados.append({"item_id": iid, "ok": True, "skipped": True,
                               "master_tracking_number": it["master_tracking_number"]})
            continue
        notify_email = recipient["email"] if common_opts["notificar"] else ""
        res = _fedex_create_shipment(
            recipient=recipient,
            packages=packages,
            reference=(f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip(),
            service_type=common_opts["service_type"],
            label_format=common_opts["label_format"],
            label_stock=common_opts["label_stock"],
            pickup_type=common_opts["pickup_type"],
            notify_email=notify_email,
            notify_name=recipient.get("nombre"),
        )
        if not res.get("ok"):
            try:
                mysql_execute(
                    "UPDATE transport_manifest_items SET ship_error=%s WHERE id=%s",
                    ((res.get("error") or "")[:600], iid)
                )
            except Exception:
                pass
            _tr_log("manifest_item", iid, "OT FedEx error (masivo)",
                    (res.get("error") or "FedEx no respondió")[:200])
            resultados.append({
                "item_id":    iid,
                "ok":         False,
                "error":      res.get("error") or "FedEx no respondió",
                "error_code": res.get("error_code"),
            })
            continue
        master_tn = res["master_tracking_number"]
        piece_tns = res.get("piece_trackings") or []
        n_b = len(piece_tns) if piece_tns else int(it.get("n_bultos") or 1)
        import json as _jp
        try:
            mysql_execute("""
                UPDATE transport_manifest_items
                SET master_tracking_number=%s,
                    tracking_number=%s,
                    piece_trackings_json=%s,
                    ship_label_b64=%s,
                    ship_labels_json=%s,
                    ship_label_format=%s,
                    ship_bultos=%s,
                    ship_label_outdated=0,
                    ship_created_at=NOW(),
                    ship_cancelled_at=NULL,
                    ship_error=NULL,
                    last_carrier_source='fedex'
                WHERE id=%s
            """, (
                master_tn, master_tn,
                _jp.dumps(piece_tns) if piece_tns else None,
                res.get("label_b64") or None,
                _jp.dumps(res.get("piece_labels") or []) if res.get("piece_labels") else None,
                res.get("label_format") or "PDF",
                n_b,
                iid,
            ))
        except Exception as e_save:
            resultados.append({
                "item_id": iid, "ok": False,
                "error":   f"FedEx OK ({master_tn}) pero falló guardar: {str(e_save)[:80]}",
                "master_tracking_number": master_tn,
            })
            continue
        _tr_ship_snapshot(iid, "ot_creada", {"tn": master_tn, "bultos": n_b, "via": "masivo"})
        _tr_log("manifest_item", iid, "OT FedEx creada (masivo)",
                f"TN {master_tn} ({len(piece_tns)} bulto/s)")
        # 2026-06-14 (Daniel) — FIX: el OT MASIVO no notificaba (a diferencia
        # del unitario), por eso no llegaba el correo de las OT creadas en lote.
        # Igual que el unitario, pasamos el item a "Entregado a transporte" y
        # avisamos al cliente. _tr_apply_carrier_status hace dedup (solo si
        # cambió) y respeta el kill switch.
        try:
            _tr_apply_carrier_status(iid, 'Entregado a transporte', fuente='sistema',
                                     comentario='Etiqueta FedEx generada (masivo)',
                                     notify_cliente=True)
        except Exception as _e_ot_ev_m:
            print(f"[tr_event ot_fedex masivo] item={iid}: {_e_ot_ev_m}", flush=True)
        resultados.append({
            "item_id":                iid,
            "ok":                     True,
            "master_tracking_number": master_tn,
            "n_bultos":               len(piece_tns),
        })

    n_ok    = sum(1 for r in resultados if r.get("ok") and not r.get("skipped"))
    n_skip  = sum(1 for r in resultados if r.get("skipped"))
    n_err   = sum(1 for r in resultados if not r.get("ok"))
    return jsonify({
        "ok": True, "total": len(resultados),
        "creadas":  n_ok, "ya_tenian": n_skip, "errores": n_err,
        "resultados": resultados,
    })


@app.route("/transporte/api/items/<int:item_id>/etiqueta-fedex", methods=["GET"])
@_tr_required
def tr_etiqueta_fedex(item_id):
    """Descarga la etiqueta FedEx de un item.

    Por defecto devuelve un PDF 4×6 (100×150 mm) con UNA página por bulto
    (multi-pieza), auto-recortado para que salga cortado al tamaño térmico.
    Con ?original=1 devuelve el archivo crudo tal cual lo entregó FedEx
    (útil para impresión térmica directa o debug).
    """
    r = mysql_fetchone(
        "SELECT ship_label_b64, ship_labels_json, ship_label_format, "
        "       master_tracking_number, piece_trackings_json, ship_bultos, "
        "       ship_cancelled_at, commitment_id "
        "FROM transport_manifest_items WHERE id=%s",
        (item_id,)
    )
    if not r:
        return jsonify({"error": "item no encontrado"}), 404
    label_b64 = r.get("ship_label_b64") or ""
    label_fmt = (r.get("ship_label_format") or "PDF").upper()
    master_tn = r.get("master_tracking_number") or "etiqueta"
    if not label_b64:
        # FIX 2026-07-30 (hallazgo real en logs de producción: este botón
        # ["Descargar etiqueta oficial FedEx", morado] se abre con
        # window.open() directo sobre esta API -- al no haber etiqueta
        # (típicamente porque la OT se canceló, que borra ship_label_b64,
        # ver tr_reemitir_ot_fedex/tr_item_fedex_cancelar_ot) el usuario veía
        # el JSON crudo de este error en una pestaña nueva, sin ningún
        # contexto -- para alguien no técnico eso lee como "el botón no
        # funciona". Su hermano, "Imprimir etiqueta cortada" (tr_item_
        # etiqueta_fedex_print), ya maneja este caso con una página HTML
        # amigable ("OT cancelada") -- se reusa el MISMO patrón acá.
        motivo = "OT cancelada" if r.get("ship_cancelled_at") else "sin etiqueta FedEx"
        doc = ""
        try:
            _c = mysql_fetchone(
                "SELECT tido, nudo FROM transport_commitments WHERE id=%s",
                (r.get("commitment_id"),))
            if _c:
                doc = f"{_c.get('tido') or ''}{_c.get('nudo') or ''}".strip()
        except Exception:
            pass
        return render_template(
            "transporte/etiquetas_fedex_print.html",
            manifiesto=None, etiquetas=[],
            omitidas=[{"doc": doc or f"#{item_id}", "motivo": motivo}],
            titulo=f"Etiqueta FedEx · {doc or ('#' + str(item_id))}",
            pdf_url=None,
        ), 404
    import base64 as _b64

    original = (request.args.get("original") or "") in ("1", "true", "yes")

    # Modo 4×6 (default): rasteriza + recorta + arma PDF con todos los bultos.
    if not original and label_fmt in ("PDF", "PNG"):
        labels = _fedex_item_labels(r)
        try:
            pdf_bytes, n_inc, _omit = _fedex_labels_to_4x6_pdf(labels)
        except Exception as e:
            pdf_bytes, n_inc = None, 0
            print(f"[etiqueta-fedex 4x6] {type(e).__name__}: {e}", flush=True)
        if pdf_bytes and n_inc:
            fname = f"fedex_{master_tn}_4x6_{n_inc}bultos.pdf"
            return Response(pdf_bytes, mimetype="application/pdf",
                            headers={"Content-Disposition": f'inline; filename="{fname}"'})
        # Si por algún motivo falló, cae al crudo abajo.

    # Modo original / fallback: archivo crudo tal cual FedEx.
    try:
        raw = _b64.b64decode(label_b64)
    except Exception:
        return jsonify({"error": "Etiqueta corrupta en BD"}), 500
    mime = {
        "PDF":   "application/pdf",
        "PNG":   "image/png",
        "ZPLII": "application/zpl",
        "EPL2":  "application/x-epl",
    }.get(label_fmt, "application/octet-stream")
    ext = {"PDF": "pdf", "PNG": "png", "ZPLII": "zpl", "EPL2": "epl"}.get(label_fmt, "bin")
    fname = f"fedex_{master_tn}.{ext}"
    return Response(
        raw, mimetype=mime,
        headers={"Content-Disposition": f'inline; filename="{fname}"'}
    )


def _fedex_parse_scans(scans):
    """Normaliza los scanEvents crudos de la Track API a una lista limpia para UI:
    [{fecha, hora, fecha_txt, descripcion, ubicacion, tipo}], de más reciente a
    más antiguo (como los muestra FedEx)."""
    out = []
    for sc in (scans or []):
        if not isinstance(sc, dict):
            continue
        raw_dt = (sc.get("date") or "")  # ej '2026-06-13T11:31:00-04:00'
        # FIX 2026-07-29 (Daniel: "las fechas salen en inglés... quiero
        # día, mes, año, y la hora de Santiago"): antes se cortaba el texto
        # crudo del ISO sin interpretar la zona horaria embebida (que puede
        # ser de un hub fuera de Chile). _fedex_iso_a_chile() la parsea de
        # verdad y convierte a hora Santiago.
        fecha_txt = _fedex_iso_a_chile(raw_dt)
        loc = sc.get("scanLocation") or {}
        ciudad = (loc.get("city") or "").strip()
        pais   = (loc.get("countryCode") or "").strip()
        ubic = ", ".join([p for p in (ciudad.title() if ciudad else "", pais) if p])
        desc = (sc.get("eventDescription") or sc.get("derivedStatus")
                or sc.get("exceptionDescription") or "").strip()
        out.append({
            "fecha_txt": fecha_txt,
            "descripcion": desc,
            "ubicacion": ubic,
            "tipo": sc.get("eventType") or "",
        })
    return out


@app.route("/transporte/api/items/<int:item_id>/tracking-detalle", methods=["GET"])
@_tr_required
def tr_item_tracking_detalle(item_id):
    """Detalle completo de seguimiento de un item para el modal de tracking:
    estado actual + stepper, pesos (real/vol/predominante), tarifa, bultos,
    timeline de eventos ILUS y — best-effort — los scans en vivo de FedEx.
    """
    row = mysql_fetchone("""
        SELECT mi.id, mi.estado_entrega, mi.master_tracking_number, mi.tracking_number,
               mi.ship_bultos,
               mi.ship_created_at, mi.last_carrier_status, mi.last_carrier_poll_at,
               mi.commitment_id, tm.courier, tm.correlativo,
               c.tido, c.nudo, c.cliente_nombre, c.comuna, c.region,
               COALESCE(c.peso_real, 0)         AS peso_real,
               COALESCE(c.peso_vol, 0)          AS peso_vol,
               COALESCE(c.peso_predominante, 0) AS peso_pred,
               COALESCE(c.peso_export, 0)       AS peso_export,
               COALESCE(c.volumen_m3, 0)        AS volumen_m3,
               COALESCE(c.n_bultos, 1)          AS n_bultos,
               COALESCE(c.zz_envio, 0)          AS zz_envio,
               COALESCE(c.costo_courier, 0)     AS costo_courier,
               COALESCE(c.valor_bruto, 0)       AS valor_bruto
        FROM transport_manifest_items mi
        LEFT JOIN transport_manifests tm   ON tm.id = mi.manifest_id
        LEFT JOIN transport_commitments c  ON c.id = mi.commitment_id
        WHERE mi.id=%s
    """, (item_id,))
    if not row:
        return jsonify({"ok": False, "error": "item no encontrado"}), 404

    estado = row.get("estado_entrega") or "En preparación"
    meta = ESTADOS_ENTREGA_META.get(estado, {})
    # 2026-08-13 (Daniel, screenshot de este mismo modal: "FCV 0000011275"):
    # este endpoint se armó antes de _doc_label (2026-08-05) y quedó con el
    # nudo crudo del ERP (ceros a la izquierda hasta 10 dígitos). Mismo fix
    # que ya tienen los demás call sites de "doc" en el módulo.
    doc = _doc_label(row.get('tido'), row.get('nudo'))

    # Timeline de eventos ILUS (alto nivel).
    eventos_raw = mysql_fetchall("""
        SELECT estado, fuente, ts_utc, comentario
        FROM transport_tracking_events
        WHERE manifest_item_id=%s
        ORDER BY ts_utc DESC, id DESC
    """, (item_id,)) or []
    eventos = []
    for e in eventos_raw:
        est = e.get("estado") or ""
        m = ESTADOS_ENTREGA_META.get(est, {})
        eventos.append({
            "estado":     est,
            "color":      m.get("color", "secondary"),
            "icon":       m.get("icon", "bi-circle"),
            "fuente":     e.get("fuente") or "manual",
            # FIX 2026-07-27: mismo bug de hora UTC cruda que en
            # _tracking_payload -- convertir a Chile antes de mostrar.
            "ts":         chile_fmt_filter(e.get("ts_utc"), "%d/%m/%Y %H:%M:%S") if e.get("ts_utc") else "",
            "comentario": e.get("comentario") or "",
        })

    # Scans en vivo de FedEx (best-effort; no rompe si la API falla).
    # FIX 2026-07-29 (Daniel, en vivo: OT cargada por Excel masivo --
    # tracking_number-- no mostraba ruta FedEx ni tiempos porque acá solo
    # se miraba master_tracking_number. Mismo criterio ya usado en
    # tr_refrescar_tracking_item: "Lee master_tracking_number (preferido)
    # o tracking_number").
    fedex_scans, eta, fedex_label = [], "", ""
    tn = row.get("master_tracking_number") or row.get("tracking_number") or ""
    if tn and FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET:
        try:
            res = _fedex_track_lookup([tn])
            if res:
                r0 = res[0]
                fedex_scans = _fedex_parse_scans(r0.get("scans"))
                eta = r0.get("eta") or ""
                fedex_label = r0.get("status_label") or ""
        except Exception as _e_fx:
            print(f"[tracking-detalle] FedEx live falló: {str(_e_fx)[:120]}", flush=True)

    pred = float(row.get("peso_pred") or 0)
    real = float(row.get("peso_real") or 0)
    vol  = float(row.get("peso_vol") or 0)
    if not pred:
        pred = max(real, vol)
    cobrado = float(row.get("zz_envio") or 0)
    costo   = float(row.get("costo_courier") or 0)

    return jsonify({
        "ok": True,
        "item_id":   item_id,
        # 2026-07-29 (modal FedEx consolidado): el frontend necesita el
        # commitment_id para traer productos/evidencia/tiempos desde
        # /transporte/api/buscar/<cid> (_tr_buscar_detalle). Additivo.
        "commitment_id": row.get("commitment_id"),
        "doc":       doc or f"#{item_id}",
        "cliente":   row.get("cliente_nombre") or "—",
        "comuna":    row.get("comuna") or "",
        "region":    row.get("region") or "",
        "courier":   row.get("courier") or "",
        "manifiesto": row.get("correlativo") or "",
        "tracking":  tn,
        "estado":        estado,
        "estado_color":  meta.get("color", "secondary"),
        "estado_icon":   meta.get("icon", "bi-circle"),
        "estado_step":   meta.get("step", 1),
        "bultos":        int(row.get("ship_bultos") or row.get("n_bultos") or 1),
        "ship_created_at": str(row.get("ship_created_at") or "")[:19],
        # FIX 2026-07-29 (Daniel: "las fechas salen en inglés... quiero la
        # hora de Santiago"): last_carrier_poll_at es UTC naive (MySQL) -- se
        # convierte con el mismo chile_fmt_filter que usa el resto de la app
        # (Regla #6), en vez de truncar el string crudo.
        "ultimo_poll":   chile_fmt_filter(row.get("last_carrier_poll_at"), "%d/%m/%Y %H:%M") if row.get("last_carrier_poll_at") else "",
        "pesos": {
            "real": round(real, 2), "vol": round(vol, 2),
            "predominante": round(pred, 2),
            "mayor_es": "vol" if vol > real else "real",
            "volumen_m3": round(float(row.get("volumen_m3") or 0), 3),
        },
        "tarifa": {
            "cobrado": cobrado, "costo": costo,
            "margen": cobrado - costo,
            "valor_bruto": float(row.get("valor_bruto") or 0),
        },
        "eta":           _fedex_iso_a_chile(eta),
        "fedex_label":   fedex_label,
        "eventos":       eventos,
        "fedex_scans":   fedex_scans,
    })


@app.route("/transporte/api/items/<int:item_id>/labels-debug", methods=["GET"])
@_tr_required
def tr_labels_debug(item_id):
    """Diagnóstico de etiquetas multi-bulto: cuántas piezas tiene la OT vs.
    cuántas etiquetas guardamos realmente. Para depurar el caso 'trae 1 de N'."""
    import json as _jp
    r = mysql_fetchone(
        "SELECT id, master_tracking_number, ship_bultos, piece_trackings_json, "
        "       ship_labels_json, ship_label_b64, ship_label_format, ship_created_at "
        "FROM transport_manifest_items WHERE id=%s", (item_id,))
    if not r:
        return jsonify({"ok": False, "error": "item no encontrado"}), 404

    def _count_json(s):
        if not s:
            return 0
        try:
            v = _jp.loads(s)
            return len(v) if isinstance(v, list) else 0
        except Exception:
            return -1

    labels = _fedex_item_labels(r)
    piece_tns = []
    try:
        piece_tns = _jp.loads(r.get("piece_trackings_json") or "[]")
    except Exception:
        pass
    return jsonify({
        "ok": True,
        "item_id":              item_id,
        "master_tracking":      r.get("master_tracking_number") or "",
        "ship_bultos":          r.get("ship_bultos"),
        "ship_created_at":      str(r.get("ship_created_at") or "")[:19],
        "piece_trackings":      piece_tns,
        "n_piece_trackings":    len(piece_tns),
        "n_labels_en_json":     _count_json(r.get("ship_labels_json")),
        "tiene_master_label":   bool(r.get("ship_label_b64")),
        "n_labels_efectivas":   len(labels),   # lo que mostraría la vista de impresión
        "label_format":         r.get("ship_label_format") or "",
        "diagnostico": (
            "OK: una etiqueta por bulto" if len(labels) >= int(r.get("ship_bultos") or 1)
            else f"FALTAN: {int(r.get('ship_bultos') or 1)} bultos pero {len(labels)} etiqueta(s). "
                 "Re-emite con 'Actualizar etiquetas multi-bulto' (ya con el fix de totalPackageCount)."
        ),
    })


@app.route("/transporte/api/items/<int:item_id>/cancelar-ot-fedex", methods=["POST"])
@_tr_required
def tr_cancelar_ot_fedex(item_id):
    """Cancela la OT FedEx del item (mismo día). Marca el item como cancelado
    y limpia la etiqueta. NO borra el tracking number (queda en histórico)."""
    r = mysql_fetchone(
        "SELECT master_tracking_number, ship_created_at, ship_cancelled_at "
        "FROM transport_manifest_items WHERE id=%s", (item_id,))
    if not r:
        return jsonify({"error": "item no encontrado"}), 404
    tn = r.get("master_tracking_number") or ""
    if not tn:
        return jsonify({"error": "Este item no tiene OT FedEx creada"}), 400
    if r.get("ship_cancelled_at"):
        return jsonify({"error": "OT ya cancelada"}), 409
    # Ventana de cancelación: mismo día Chile hasta 16:00.
    cw = _fedex_cancel_window(r.get("ship_created_at"))
    if cw and cw.get("expired"):
        return jsonify({
            "ok": False,
            "expired": True,
            "error": "La OT FedEx ya no se puede cancelar desde el sistema "
                     "(corte 16:00 hora Chile del mismo día). Coordina con "
                     "FedEx directamente si necesitas detener el envío.",
        }), 409
    res = _fedex_cancel_shipment(tn)
    if not res.get("ok"):
        _tr_log("manifest_item", item_id, "OT FedEx cancelación fallida",
                f"TN {tn}: {(res.get('error') or '')[:160]}")
        return jsonify({"ok": False, "error": res.get("error") or "FedEx no respondió"}), 502
    try:
        mysql_execute(
            "UPDATE transport_manifest_items "
            "SET ship_cancelled_at=NOW(), ship_label_b64=NULL, ship_label_outdated=0 "
            "WHERE id=%s",
            (item_id,)
        )
    except Exception as e_save:
        return jsonify({"ok": False, "error": f"Cancelada en FedEx pero falló BD: {e_save}"}), 500
    _tr_ship_snapshot(item_id, "ot_cancelada", {"tn": tn})
    _tr_log("manifest_item", item_id, "OT FedEx cancelada", f"TN {tn}")
    return jsonify({"ok": True, "cancelled": True, "tracking_number": tn})


@app.route("/transporte/api/items/<int:item_id>/reemitir-ot-fedex", methods=["POST"])
@_tr_required
def tr_reemitir_ot_fedex(item_id):
    """Re-emite la etiqueta FedEx tras un cambio de bultos: cancela la OT vigente
    y crea una nueva con el conteo de bultos ACTUAL, dejando respaldo del TN viejo.

    Flujo (todo o nada práctico):
      1. Bloquea si la ventana de cancelación (16:00 Chile) ya expiró — decisión
         Daniel: la OT vieja quedaría activa y cobrable, hay que coordinar con FedEx.
      2. Cancela el TN viejo en FedEx.
      3. Crea el envío nuevo con los bultos actuales.
      4. Pisa la fila con el TN/etiqueta nuevos, limpia el flag de desfase y
         registra ambos TN en el respaldo (ship_history_json) + audit log.

    Si el paso 2 funciona pero el 3 falla, el item queda con la OT vieja cancelada
    y sin OT activa (se avisa claramente para recrear manualmente).
    """
    body = request.get_json(silent=True, force=True) or {}
    r = mysql_fetchone(
        "SELECT master_tracking_number, ship_created_at, ship_cancelled_at, "
        "       ship_bultos, ship_label_format "
        "FROM transport_manifest_items WHERE id=%s", (item_id,))
    if not r:
        return jsonify({"ok": False, "error": "item no encontrado"}), 404
    old_tn = r.get("master_tracking_number") or ""
    if not old_tn:
        return jsonify({"ok": False, "error": "Este item no tiene OT FedEx que re-emitir"}), 400
    if r.get("ship_cancelled_at"):
        return jsonify({"ok": False,
            "error": "La OT ya está cancelada; usa 'Crear OT' para emitir una nueva"}), 409

    # 1) Bloqueo fuera de ventana (no dejar OT vieja huérfana cobrable).
    cw = _fedex_cancel_window(r.get("ship_created_at"))
    if cw and cw.get("expired"):
        return jsonify({"ok": False, "expired": True,
            "error": "No se puede re-emitir: la OT vieja ya no es cancelable en FedEx "
                     "(corte 16:00 hora Chile del mismo día) y quedaría activa y cobrable. "
                     "Coordina con FedEx para anularla y luego crea una OT nueva."}), 409

    # 2) Cancelar la OT vieja en FedEx.
    cancel_res = _fedex_cancel_shipment(old_tn)
    if not cancel_res.get("ok"):
        _tr_log("manifest_item", item_id, "Re-emisión abortada",
                f"no se pudo cancelar TN {old_tn}: {(cancel_res.get('error') or '')[:160]}")
        return jsonify({"ok": False,
            "error": "No se pudo cancelar la OT vieja en FedEx; no se re-emitió. "
                     + (cancel_res.get("error") or "")}), 502
    _tr_ship_snapshot(item_id, "reemision_cancela_vieja",
                      {"old_tn": old_tn, "old_bultos": r.get("ship_bultos")})

    # 3) Crear la OT nueva con los bultos actuales.
    it, recipient, packages = _tr_item_para_ship(item_id)
    if not it:
        mysql_execute(
            "UPDATE transport_manifest_items "
            "SET ship_cancelled_at=NOW(), ship_label_b64=NULL, ship_label_outdated=0 "
            "WHERE id=%s", (item_id,))
        _tr_log("manifest_item", item_id, "Re-emisión incompleta",
                f"TN {old_tn} cancelado pero el item no está disponible para recrear")
        return jsonify({"ok": False,
            "error": "Cancelamos la OT vieja, pero el item ya no está disponible para "
                     "recrear. Crea la OT manualmente."}), 500

    res = _fedex_create_shipment(
        recipient=recipient,
        packages=packages,
        reference=(f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip(),
        service_type=body.get("service_type"),
        label_format=(body.get("label_format") or r.get("ship_label_format") or "PDF"),
        label_stock=(body.get("label_stock") or "STOCK_4X6"),
        pickup_type=(body.get("pickup_type") or "USE_SCHEDULED_PICKUP"),
        notify_email=(recipient["email"] if body.get("notificar") else ""),
        notify_name=recipient.get("nombre"),
    )
    if not res.get("ok"):
        mysql_execute(
            "UPDATE transport_manifest_items "
            "SET ship_cancelled_at=NOW(), ship_label_b64=NULL, ship_label_outdated=0, "
            "    ship_error=%s WHERE id=%s",
            ((res.get("error") or "")[:600], item_id))
        _tr_log("manifest_item", item_id, "Re-emisión fallida",
                f"TN {old_tn} cancelado; FedEx rechazó la nueva: {(res.get('error') or '')[:160]}")
        return jsonify({"ok": False,
            "error": "Cancelamos la OT vieja pero FedEx rechazó la nueva: "
                     + (res.get("error") or "") + " — crea la OT de nuevo cuando se resuelva."}), 502

    import json as _jp
    new_tn = res["master_tracking_number"]
    piece_tns = res.get("piece_trackings") or []
    n_b = len(piece_tns) if piece_tns else int(it.get("n_bultos") or 1)
    try:
        mysql_execute("""
            UPDATE transport_manifest_items
            SET master_tracking_number=%s, tracking_number=%s, piece_trackings_json=%s,
                ship_label_b64=%s, ship_labels_json=%s, ship_label_format=%s, ship_bultos=%s,
                ship_created_at=NOW(), ship_cancelled_at=NULL, ship_label_outdated=0,
                ship_error=NULL, last_carrier_source='fedex'
            WHERE id=%s
        """, (
            new_tn, new_tn,
            _jp.dumps(piece_tns) if piece_tns else None,
            res.get("label_b64") or None,
            _jp.dumps(res.get("piece_labels") or []) if res.get("piece_labels") else None,
            res.get("label_format") or "PDF",
            n_b, item_id,
        ))
    except Exception as e_save:
        return jsonify({"ok": False,
            "error": f"Re-emitida en FedEx (TN {new_tn}) pero falló al guardar: {str(e_save)[:120]}",
            "master_tracking_number": new_tn}), 500

    _tr_ship_snapshot(item_id, "reemision_crea_nueva",
                      {"old_tn": old_tn, "new_tn": new_tn, "bultos": n_b})
    _tr_log("manifest_item", item_id, "OT FedEx re-emitida",
            f"TN {old_tn} cancelado → TN {new_tn} ({n_b} bulto/s)")
    return jsonify({"ok": True,
                    "master_tracking_number": new_tn,
                    "old_tracking_number": old_tn,
                    "n_bultos": n_b,
                    "label_url": url_for("tr_etiqueta_fedex", item_id=item_id)})


@app.route("/transporte/api/manifiestos/<int:mid>/actualizar-etiquetas-fedex", methods=["POST"])
@_tr_required
def tr_actualizar_etiquetas_fedex(mid):
    """Re-emite las OTs FedEx de los items de un manifiesto que les faltan las
    etiquetas por bulto (creadas antes del fix multi-pieza, solo tienen la master).

    Detecta items con multi-bulto incompleto:
        ship_bultos > 1 AND ship_labels_json IS NULL AND no cancelados.

    Para cada uno: cancela la OT vieja en FedEx y crea una nueva (mismo recipient,
    mismos bultos). La nueva guarda TODAS las piezas en ship_labels_json. El TN
    master cambia — por eso se devuelve la lista de cambios para que el operador
    descarte cualquier etiqueta vieja impresa.

    Body opcional: { only_item_ids: [123, 456] } para limitar a un subconjunto.
    """
    body = request.get_json(silent=True, force=True) or {}
    only = body.get("only_item_ids")
    only_clause, only_params = "", ()
    if isinstance(only, list) and only:
        placeholders = ",".join(["%s"] * len(only))
        only_clause = f" AND mi.id IN ({placeholders})"
        only_params = tuple(only)

    # Items multi-bulto donde NO tenemos una etiqueta por cada pieza:
    # ship_labels_json nula/vacía, o con menos elementos que ship_bultos.
    rows = mysql_fetchall(
        "SELECT mi.id, c.tido, c.nudo, mi.master_tracking_number, mi.ship_bultos, "
        "       mi.ship_created_at, "
        "       CASE WHEN mi.ship_labels_json IS NULL OR mi.ship_labels_json='' "
        "            THEN 0 ELSE JSON_LENGTH(mi.ship_labels_json) END AS n_labels "
        "FROM transport_manifest_items mi "
        "LEFT JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.manifest_id=%s "
        "  AND mi.master_tracking_number IS NOT NULL "
        "  AND mi.master_tracking_number <> '' "
        "  AND mi.ship_cancelled_at IS NULL "
        "  AND COALESCE(mi.ship_bultos, 1) > 1 "
        "  AND ( mi.ship_labels_json IS NULL OR mi.ship_labels_json = '' "
        "        OR JSON_LENGTH(mi.ship_labels_json) < COALESCE(mi.ship_bultos, 1) ) "
        + only_clause +
        " ORDER BY mi.orden, mi.id",
        (mid,) + only_params) or []

    if not rows:
        return jsonify({"ok": True, "actualizadas": 0,
                        "msg": "No hay etiquetas que actualizar — todos los envíos ya tienen una etiqueta por bulto."})

    actualizadas = []   # [{item_id, doc, old_tn, new_tn, n_bultos}]
    errores = []        # [{item_id, doc, error, expired?}]
    for r in rows:
        iid = r["id"]
        doc = f"{r.get('tido') or ''}{r.get('nudo') or ''}".strip() or f"#{iid}"
        old_tn = r["master_tracking_number"]
        # Ventana de cancelación (mismo día 16:00 Chile).
        cw = _fedex_cancel_window(r.get("ship_created_at"))
        if cw and cw.get("expired"):
            errores.append({"item_id": iid, "doc": doc, "old_tn": old_tn,
                            "expired": True,
                            "error": "OT fuera de ventana de cancelación FedEx (16:00 Chile). "
                                     "Coordina con FedEx para anularla y crea OT nueva manual."})
            continue
        # Cancelar vieja.
        cancel_res = _fedex_cancel_shipment(old_tn)
        if not cancel_res.get("ok"):
            errores.append({"item_id": iid, "doc": doc, "old_tn": old_tn,
                            "error": "No se pudo cancelar TN viejo: "
                                     + (cancel_res.get("error") or "")[:140]})
            _tr_log("manifest_item", iid, "Actualizar etiquetas abortado",
                    f"no canceló {old_tn}: {(cancel_res.get('error') or '')[:140]}")
            continue
        _tr_ship_snapshot(iid, "reemision_cancela_vieja",
                          {"old_tn": old_tn, "via": "actualizar_etiquetas",
                           "old_bultos": r.get("ship_bultos")})
        # Crear nueva con los bultos actuales.
        it, recipient, packages = _tr_item_para_ship(iid)
        if not it:
            mysql_execute(
                "UPDATE transport_manifest_items "
                "SET ship_cancelled_at=NOW(), ship_label_b64=NULL, ship_labels_json=NULL, "
                "    ship_label_outdated=0 WHERE id=%s", (iid,))
            errores.append({"item_id": iid, "doc": doc, "old_tn": old_tn,
                            "error": "Cancelada la vieja, pero el item ya no está disponible "
                                     "para recrear."})
            continue
        res = _fedex_create_shipment(
            recipient=recipient, packages=packages,
            reference=(f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip(),
            label_stock="STOCK_4X6",
        )
        if not res.get("ok"):
            mysql_execute(
                "UPDATE transport_manifest_items "
                "SET ship_cancelled_at=NOW(), ship_label_b64=NULL, ship_labels_json=NULL, "
                "    ship_label_outdated=0, ship_error=%s WHERE id=%s",
                ((res.get("error") or "")[:600], iid))
            errores.append({"item_id": iid, "doc": doc, "old_tn": old_tn,
                            "error": "Cancelada la vieja pero FedEx rechazó la nueva: "
                                     + (res.get("error") or "")[:140]})
            continue
        import json as _jp
        new_tn = res["master_tracking_number"]
        piece_tns = res.get("piece_trackings") or []
        n_b = len(piece_tns) if piece_tns else int(it.get("n_bultos") or 1)
        try:
            mysql_execute("""
                UPDATE transport_manifest_items
                SET master_tracking_number=%s, tracking_number=%s, piece_trackings_json=%s,
                    ship_label_b64=%s, ship_labels_json=%s, ship_label_format=%s,
                    ship_bultos=%s, ship_created_at=NOW(), ship_cancelled_at=NULL,
                    ship_label_outdated=0, ship_error=NULL, last_carrier_source='fedex'
                WHERE id=%s
            """, (
                new_tn, new_tn,
                _jp.dumps(piece_tns) if piece_tns else None,
                res.get("label_b64") or None,
                _jp.dumps(res.get("piece_labels") or []) if res.get("piece_labels") else None,
                res.get("label_format") or "PDF",
                n_b, iid,
            ))
        except Exception as e_save:
            errores.append({"item_id": iid, "doc": doc, "old_tn": old_tn, "new_tn": new_tn,
                            "error": f"FedEx OK (TN {new_tn}) pero falló al guardar: {str(e_save)[:100]}"})
            continue
        _tr_ship_snapshot(iid, "reemision_crea_nueva",
                          {"old_tn": old_tn, "new_tn": new_tn, "bultos": n_b,
                           "via": "actualizar_etiquetas"})
        _tr_log("manifest_item", iid, "Etiquetas actualizadas",
                f"TN {old_tn} → {new_tn} ({n_b} bulto/s con todas las piezas)")
        actualizadas.append({"item_id": iid, "doc": doc, "old_tn": old_tn,
                             "new_tn": new_tn, "n_bultos": n_b})

    _tr_log("manifest", mid, "actualizar etiquetas fedex",
            f"{len(actualizadas)} OK · {len(errores)} con error")
    return jsonify({
        "ok": True,
        "actualizadas": len(actualizadas),
        "errores":      len(errores),
        "detalle":      actualizadas,
        "errores_detalle": errores,
    })




@app.route("/transporte/api/pickup/fedex/disponibilidad", methods=["POST"])
@_tr_required
def tr_pickup_fedex_disponibilidad():
    """Consulta horarios disponibles para retiro FedEx en bodega.

    Body: {
        fecha:        'YYYY-MM-DD',
        ready_time:   'HH:MM:SS' (default 09:00:00),
        close_time:   'HH:MM:SS' (default 18:00:00),
        peso_kg:      float,
        direccion, comuna, cod_postal  // si vacío, usa bodega ILUS
    }
    """
    body = request.get_json(silent=True, force=True) or {}
    import datetime as _dt
    fecha = body.get("fecha") or _dt.date.today().strftime("%Y-%m-%d")
    res = _fedex_pickup_check(
        address={
            "direccion":  body.get("direccion") or ILUS_REMITENTE["bodega"],
            "comuna":     body.get("comuna")    or "Quilicura",
            "cod_postal": body.get("cod_postal") or FEDEX_ORIGIN_POSTAL,
        },
        dispatch_date=fecha,
        ready_time=body.get("ready_time") or "09:00:00",
        close_time=body.get("close_time") or "18:00:00",
        weight_kg=float(body.get("peso_kg") or 1.0),
    )
    if not res.get("ok"):
        return jsonify({"ok": False, "error": res.get("error") or "FedEx no respondió"}), 502
    return jsonify(res)


@app.route("/transporte/api/pickup/fedex/crear", methods=["POST"])
@_tr_required
def tr_pickup_fedex_crear():
    """Agenda un retiro FedEx en la bodega ILUS.

    Body: {
        manifest_id?:           int (asocia el pickup al manifiesto),
        fecha:                  'YYYY-MM-DD',
        ready_time:             'HH:MM:SS' (default 09:00:00),
        close_time:             'HH:MM:SS' (default 18:00:00),
        package_count:          int,
        total_weight_kg:        float,
        direccion, comuna, cod_postal, instrucciones,
        contacto: { nombre, telefono, empresa? },
        notify_email?:          str,
    }
    """
    body = request.get_json(silent=True, force=True) or {}
    fecha = body.get("fecha")
    if not fecha:
        return jsonify({"error": "fecha es obligatoria"}), 400
    ready_time = body.get("ready_time") or "09:00:00"
    close_time = body.get("close_time") or "18:00:00"
    contacto   = body.get("contacto") or {}

    # FedEx usa 'YYYY-MM-DDTHH:MM:SS' para readyDateTimestamp
    ready_dt = f"{fecha}T{ready_time}"

    res = _fedex_pickup_create(
        contact={
            "nombre":   contacto.get("nombre")   or "Despacho ILUS",
            "telefono": contacto.get("telefono") or ILUS_REMITENTE["telefono"],
            "empresa":  contacto.get("empresa")  or ILUS_REMITENTE["nombre"],
        },
        address={
            "direccion":  body.get("direccion") or ILUS_REMITENTE["bodega"],
            "comuna":     body.get("comuna")    or "Quilicura",
            "cod_postal": body.get("cod_postal") or FEDEX_ORIGIN_POSTAL,
        },
        ready_dt=ready_dt,
        close_time=close_time,
        package_count=int(body.get("package_count") or 1),
        total_weight_kg=float(body.get("total_weight_kg") or 1.0),
        notify_email=body.get("notify_email") or "",
        delivery_instructions=body.get("instrucciones") or "",
    )
    if not res.get("ok"):
        return jsonify({"ok": False, "error": res.get("error") or "FedEx no respondió"}), 502

    import json as _jp
    pcc = res.get("pickup_confirmation_code") or ""
    loc = res.get("location") or ""
    sched = res.get("scheduled_date") or fecha
    mid = body.get("manifest_id")
    user = (session.get("usuario") or "")[:120] if "session" in globals() else None

    pickup_id = None
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                INSERT INTO transp_fedex_pickups
                    (manifest_id, pickup_confirmation_code, location, scheduled_date,
                     ready_time, close_time, package_count, total_weight_kg,
                     contact_name, contact_phone, contact_email,
                     origin_address, origin_comuna, origin_cod_postal,
                     delivery_instructions, estado, created_by, raw_response)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                        %s, %s, %s, %s, 'Programado', %s, %s)
            """, (
                mid, pcc, loc, sched,
                ready_time, close_time,
                int(body.get("package_count") or 1),
                float(body.get("total_weight_kg") or 1.0),
                (contacto.get("nombre") or "")[:120],
                (contacto.get("telefono") or "")[:40],
                (body.get("notify_email") or "")[:120],
                (body.get("direccion") or ILUS_REMITENTE["bodega"])[:300],
                (body.get("comuna") or "Quilicura")[:80],
                (body.get("cod_postal") or FEDEX_ORIGIN_POSTAL)[:10],
                (body.get("instrucciones") or "")[:120],
                user,
                _jp.dumps(res.get("raw") or {})[:65000],
            ))
            pickup_id = cur.lastrowid
        conn.commit()
        if mid and pickup_id:
            mysql_execute(
                "UPDATE transport_manifest_items SET fedex_pickup_id=%s "
                "WHERE manifest_id=%s AND fedex_pickup_id IS NULL",
                (pickup_id, mid)
            )
    except Exception as e_save:
        return jsonify({
            "ok": False,
            "error": f"Pickup creado en FedEx (PCC {pcc}) pero falló BD: {str(e_save)[:120]}",
            "pickup_confirmation_code": pcc,
        }), 500

    return jsonify({
        "ok":                       True,
        "pickup_id":                pickup_id,
        "pickup_confirmation_code": pcc,
        "location":                 loc,
        "scheduled_date":           sched,
    })


@app.route("/transporte/api/pickup/fedex/<int:pickup_id>/cancelar", methods=["POST"])
@_tr_required
def tr_pickup_fedex_cancelar(pickup_id):
    """Cancela un retiro FedEx programado."""
    r = mysql_fetchone(
        "SELECT id, pickup_confirmation_code, location, scheduled_date, estado "
        "FROM transp_fedex_pickups WHERE id=%s", (pickup_id,))
    if not r:
        return jsonify({"error": "pickup no encontrado"}), 404
    if r.get("estado") == "Cancelado":
        return jsonify({"error": "Pickup ya cancelado"}), 409
    res = _fedex_pickup_cancel(
        pickup_confirmation_code=r["pickup_confirmation_code"],
        scheduled_date=str(r["scheduled_date"]),
        location=r.get("location") or "SCLA",
    )
    if not res.get("ok"):
        return jsonify({"ok": False, "error": res.get("error") or "FedEx no respondió"}), 502
    try:
        mysql_execute(
            "UPDATE transp_fedex_pickups SET estado='Cancelado', cancelled_at=NOW() "
            "WHERE id=%s", (pickup_id,)
        )
    except Exception as e_save:
        return jsonify({"ok": False, "error": f"Cancelado en FedEx pero falló BD: {e_save}"}), 500
    return jsonify({"ok": True, "cancelled": True})


import threading as _th_cron
_CRON_INTERNO = _th_cron.local()


def _tr_correr_cron_interno(nombre, view_fn):
    """Ejecuta un endpoint de cron desde un hilo del propio proceso.

    Por qué existe (2026-08-05): los endpoints /transporte/cron/* estaban
    escritos para que Cloud Scheduler los llamara por HTTP, pero Cloud
    Scheduler NUNCA se configuró en el proyecto — no hay un solo job. O sea
    que existían y no los llamaba nadie: el saldo y la guía por producto solo
    se refrescaban si alguien apretaba "Actualizar ahora" a mano.

    En vez de duplicar su lógica (que es larga y ya está probada), se los
    invoca tal cual dentro de un contexto de request falso. Se marca el hilo
    como interno para saltar el chequeo de token, y la marca se limpia
    SIEMPRE en el finally.

    Devuelve el JSON del endpoint como dict, o {"error": ...}. Nunca lanza.
    """
    try:
        _CRON_INTERNO.autorizado = True
        with app.test_request_context(f"/cron-interno/{nombre}"):
            resp = view_fn()
        # Los endpoints devuelven jsonify(...) o (jsonify(...), status)
        if isinstance(resp, tuple):
            resp = resp[0]
        return resp.get_json(silent=True) if hasattr(resp, "get_json") else {"ok": True}
    except Exception as e:
        return {"error": f"{type(e).__name__}: {e}"}
    finally:
        _CRON_INTERNO.autorizado = False


def _fedex_cron_token_required(token_received):
    """Permite proteger el cron con ILUS_CRON_TOKEN (token único de los crons
    de ILUS) o el histórico FEDEX_CRON_TOKEN. Si no se setea ninguno, solo
    permite localhost (más estricto).

    2026-07-24: se agregó ILUS_CRON_TOKEN porque Cloud Scheduler quedó
    configurado con ese token único para TODOS los crons (SimpliRoute y FedEx)
    y este endpoint respondía 403 al job de FedEx. Se acepta cualquiera de los
    dos: quien tenga FEDEX_CRON_TOKEN puesto sigue funcionando igual."""
    # Llamada INTERNA desde el scheduler del propio proceso (no entró por la
    # red): se autoriza sin token. La marca es un flag de hilo que solo pone
    # _tr_correr_cron_interno y siempre se limpia en su finally, así que no
    # hay forma de que una petición HTTP real lo herede. (2026-08-05: el
    # sondeo de saldo/guía por producto pasó a colgar del hilo transp-cron
    # porque Cloud Scheduler nunca se configuró y nadie llamaba al endpoint.)
    if getattr(_CRON_INTERNO, "autorizado", False):
        return True
    esperados = [t for t in ((os.environ.get("ILUS_CRON_TOKEN") or "").strip(),
                             (os.environ.get("FEDEX_CRON_TOKEN") or "").strip()) if t]
    if esperados:
        return bool(token_received) and token_received in esperados
    # Sin token configurado: solo aceptar desde 127.0.0.1
    return request.remote_addr in ("127.0.0.1", "::1", "localhost")


def _cron_extract_token(header_name="X-Cron-Token"):
    """Extrae el token de un endpoint de cron desde el request, priorizando
    SIEMPRE el header sobre el query string.

    2026-08-07 (hallazgo de seguridad): Cloud Run registra la URL COMPLETA
    de cada request en sus logs de acceso de Cloud Logging -- incluido el
    query string. Si Cloud Scheduler llama estos endpoints con `?token=...`
    en vez de mandar el token por header, el token queda expuesto en texto
    plano para cualquiera con acceso de lectura a esos logs.

    El query string se mantiene como fallback de EMERGENCIA por
    compatibilidad -- no se sabe desde el código si los jobs de Cloud
    Scheduler ya están configurados con el header o todavía con `?token=`
    (esa configuración vive en GCP, no en este repo) -- pero cada uso por
    esa vía insegura queda logueado como advertencia para que se note en
    Cloud Logging y se pueda confirmar si hace falta migrar el job.

    Cloud Scheduler SÍ soporta headers HTTP custom en la configuración de
    "HTTP target" de cada job. Una vez que se confirme que TODOS los jobs
    mandan el token por header, se puede desactivar este fallback poniendo
    la variable de entorno `CRON_ALLOW_QUERY_TOKEN=0` en Cloud Run -- sin
    tocar código ni volver a desplegar.
    """
    header_tok = (request.headers.get(header_name) or "").strip()
    if header_tok:
        return header_tok
    query_tok = (request.args.get("token") or "").strip()
    if query_tok:
        allow_query = (os.environ.get("CRON_ALLOW_QUERY_TOKEN") or "1").strip().lower() not in ("0", "false", "no")
        if not allow_query:
            print(f"[cron-token][BLOQUEADO] {request.path} mandó el token por "
                  f"?token= con CRON_ALLOW_QUERY_TOKEN=0 -- rechazado. Debe "
                  f"mandarse por header {header_name}.", flush=True)
            return ""
        print(f"[cron-token][INSEGURO] {request.path} recibió el token por "
              f"query string (?token=) en vez del header {header_name} -- "
              f"queda expuesto en los logs de acceso de Cloud Run. Migrar "
              f"el job de Cloud Scheduler a mandarlo por header.", flush=True)
    return query_tok


def _fedex_poll_batch(limit=25, dry=False):
    """Lógica PURA de un ciclo de polling FedEx (sin HTTP/auth). La comparten
    el endpoint manual (tr_cron_fedex_poll) y el hilo daemon automático
    (_fedex_track_poll_loop).

    Selecciona hasta `limit` items con tracking_number, NO en estado terminal,
    nunca polleados o polleados hace > 15 min. Consulta la Track API en batch
    y aplica el estado a cada item (que registra el evento en
    transport_tracking_events y actualiza estado_entrega).

    Returns: dict {ok, polled, changed, items, msg?, error?}
    """
    if not (FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET):
        return {"ok": False, "error": "FedEx Track API no configurada",
                "polled": 0, "changed": 0, "items": []}

    limit = min(int(limit or 25), 30)
    rows = mysql_fetchall("""
        SELECT id, tracking_number, piece_trackings_json
        FROM transport_manifest_items
        WHERE tracking_number IS NOT NULL AND tracking_number <> ''
          AND estado_entrega NOT IN ('Entregado', 'Devolución')
          AND (last_carrier_poll_at IS NULL
               OR last_carrier_poll_at < DATE_SUB(NOW(), INTERVAL 15 MINUTE))
        ORDER BY last_carrier_poll_at IS NULL DESC, last_carrier_poll_at ASC
        LIMIT %s
    """, (limit,)) or []
    if not rows:
        return {"ok": True, "polled": 0, "changed": 0,
                "items": [], "msg": "nada que pollear"}

    if dry:
        return {"ok": True, "polled": 0, "changed": 0,
                "items": [{"id": r["id"], "tn": r["tracking_number"]} for r in rows],
                "msg": "dry-run"}

    # ── Piezas por item ──────────────────────────────────────────────────
    # FIX 2026-07-31 (multi-bulto): cuando FedEx CL no soporta MPS real,
    # _fedex_create_individual_pieces crea N envíos independientes y guarda
    # TODOS los tracking numbers en piece_trackings_json, pero la columna
    # tracking_number se queda solo con el PRIMERO. Este poller consultaba
    # únicamente esa columna, así que marcaba el despacho como "Entregado" en
    # cuanto llegaba el bulto 1, con los otros todavía en tránsito. Y como
    # "Entregado" es terminal, ningún poll posterior podía corregirlo.
    #
    # Ahora se consultan TODAS las piezas y el estado se decide agregando:
    # "Entregado" solo si están entregadas todas.
    item_pieces = {}          # item_id -> [tn, ...] (todas las piezas)
    for r in rows:
        tns_item = []
        _pt_raw = r.get("piece_trackings_json")
        if _pt_raw:
            try:
                tns_item = [str(t).strip() for t in (json.loads(_pt_raw) or []) if str(t).strip()]
            except Exception:
                tns_item = []
        # Filas viejas (piece_trackings_json NULL) y mono-bulto: la columna basta.
        if not tns_item:
            tns_item = [r["tracking_number"]]
        # FIX 2026-08-01: si el tracking_number vigente NO está en la lista de
        # piezas, el JSON quedó OBSOLETO y hay que ignorarlo. Pasa de verdad:
        # "Asignar OT" (tr_set_tracking_fedex) y la carga masiva de OTs por
        # Excel (tr_trackings_masivo) reescriben SOLO la columna, sin tocar
        # piece_trackings_json. Sin esta comprobación el poller se quedaba
        # consultando los TN viejos/cancelados para siempre y nunca veía el
        # nuevo — regresión introducida al empezar a priorizar el JSON.
        _tn_col = (r.get("tracking_number") or "").strip()
        if _tn_col and _tn_col not in tns_item:
            tns_item = [_tn_col]
        item_pieces[r["id"]] = tns_item

    uniq_tns = list(dict.fromkeys(tn for _tns in item_pieces.values() for tn in _tns))

    # Chunking explícito de 30: es el tope de la Track API. _fedex_track_lookup
    # ya trunca a 30 pero en SILENCIO — con multi-bulto es fácil pasarse (30
    # items x 3 bultos = 90 TNs) y perder piezas sin enterarse.
    tn_status = {}
    try:
        for _i in range(0, len(uniq_tns), 30):
            for _res in _fedex_track_lookup(uniq_tns[_i:_i + 30]):
                tn_status[_res.get("tracking_number")] = _res
    except Exception as _e_fx:
        return {"ok": False,
                "error": f"FedEx Track API falló: {str(_e_fx)[:200]}",
                "polled": 0, "changed": 0, "items": []}

    # Si ninguna pieza está entregada aún, el estado agregado es el del bulto
    # más "atrasado" según esta prioridad. 'Problema' queda fuera a propósito:
    # es manual-only (solo un supervisor lo pone), nunca sale de un poller.
    # 'Devolución' también queda fuera: es terminal, y un bulto devuelto no
    # debe cerrar el despacho entero sin que lo mire una persona.
    _PRIORIDAD_NO_TERMINAL = ["Entrega fallida", "En ruta",
                              "Entregado a transporte", "En preparación"]

    changed_count = 0
    items_log = []
    n_multibulto = 0
    for item_id, tns_item in item_pieces.items():
        piezas = [tn_status.get(t) for t in tns_item]
        conocidas = [p for p in piezas if p]
        if not conocidas:
            continue   # FedEx no reportó nada de este envío; se reintenta luego

        n_total = len(tns_item)
        n_entregadas = sum(1 for p in piezas if p and p.get("estado_ilus") == "Entregado")

        if n_total <= 1:
            # Mono-bulto (la mayoría): comportamiento IDÉNTICO al de siempre.
            r = conocidas[0]
            estado_final = r["estado_ilus"]
            comentario = r.get("last_event") or r.get("status_label") or ""
        else:
            n_multibulto += 1
            if n_entregadas == n_total:
                estado_final = "Entregado"
                comentario = f"Los {n_total} bultos fueron entregados"
            else:
                _pendientes = [p for p in piezas
                               if not (p and p.get("estado_ilus") == "Entregado")]
                _est_pend = [p.get("estado_ilus") for p in _pendientes if p]
                _n_devueltas = _est_pend.count("Devolución")

                # FIX 2026-08-01: sin esta rama, un envío que FedEx está
                # DEVOLVIENDO entero (códigos CA/RS) caía en el fallback y se
                # reportaba como "En ruta" — el cliente recibía "tu pedido va
                # en camino" mientras el paquete volvía a origen. Y como no
                # había ningún bulto entregado, tampoco entraba en la alerta
                # de parciales: quedaba invisible para todos.
                # OJO (Fable, revisión de lógica 2026-08-01): exigir que TODAS
                # las piezas estén reportadas (len(conocidas) == n_total) es lo
                # que impide cerrar en "Devolución" — estado TERMINAL, ningún
                # poller lo corrige después — cuando FedEx todavía no indexó
                # uno de los bultos. Con una pieza desconocida no hay certeza
                # de devolución total: se espera al próximo poll.
                if (n_entregadas == 0 and _est_pend
                        and len(conocidas) == n_total
                        and _n_devueltas == len(_est_pend)):
                    estado_final = "Devolución"
                    comentario = (f"El courier está devolviendo "
                                  f"{'el envío completo' if n_total > 1 else 'el envío'} "
                                  f"({n_total} bultos)")
                else:
                    # Gana el estado más urgente entre los bultos que faltan.
                    # Si ninguno calza con la lista, NO se asume "En ruta"
                    # (sería inventar): se usa el estado real de la primera
                    # pieza pendiente conocida.
                    estado_final = None
                    for _cand in _PRIORIDAD_NO_TERMINAL:
                        if _cand in _est_pend:
                            estado_final = _cand
                            break
                    if estado_final is None:
                        if _n_devueltas:
                            # Parte entregada, parte devuelta y nada más en
                            # movimiento. No es "En ruta" (no se mueve nada) ni
                            # "Devolución" (sí llegó parte). 'Entrega fallida'
                            # es el estado honesto disponible: algo no se pudo
                            # entregar. Y no es terminal, así que el despacho
                            # sigue gestionable. ('Problema' queda descartado:
                            # es manual-only, nunca sale de un poller.)
                            estado_final = "Entrega fallida"
                        else:
                            estado_final = next(
                                (e for e in _est_pend
                                 if e and e not in ("Entregado", "Devolución")),
                                "En ruta")
                    if _n_devueltas:
                        # No es "esperar": esos bultos ya no van a llegar.
                        comentario = (f"{n_entregadas} de {n_total} bultos entregados · "
                                      f"{_n_devueltas} en devolución — requiere revisión")
                    else:
                        comentario = (f"{n_entregadas} de {n_total} bultos entregados "
                                      f"— a la espera del resto")

        # Persistir el conteo de bultos para que sea CONSULTABLE (alerta de
        # "envío estancado"). `parcial_desde` marca cuándo quedó a medias:
        # se setea la primera vez que se detecta el parcial y NO se pisa en
        # los polls siguientes — si no, cada consulta reiniciaría el contador
        # de días y el envío nunca se vería como estancado. Se limpia solo
        # cuando deja de estar parcial (llegaron todos, o todavía ninguno).
        # Solo multi-bulto: un envío de un bulto no puede quedar "a medias", y
        # escribirle bultos_total=1 en cada corrida eran ~25-30 UPDATE inútiles
        # cada 15 minutos sobre la mayoría de la tabla.
        try:
            if n_total > 1:
                # Parcial = algo llegó pero no todo, O algo se devolvió mientras
                # el resto sigue pendiente. El segundo caso importa: sin él, un
                # envío con bultos devueltos y ninguno entregado no entraba en
                # la alerta y quedaba invisible.
                _n_dev = sum(1 for p in piezas
                             if p and p.get("estado_ilus") == "Devolución")
                _es_parcial = (n_entregadas < n_total
                               and (n_entregadas > 0 or _n_dev > 0)
                               and estado_final != "Devolución")
                if _es_parcial:
                    mysql_execute(
                        "UPDATE transport_manifest_items "
                        "SET bultos_total=%s, bultos_entregados=%s, "
                        "    parcial_desde=COALESCE(parcial_desde, NOW()) "
                        "WHERE id=%s",
                        (n_total, n_entregadas, item_id)
                    )
                else:
                    mysql_execute(
                        "UPDATE transport_manifest_items "
                        "SET bultos_total=%s, bultos_entregados=%s, parcial_desde=NULL "
                        "WHERE id=%s",
                        (n_total, n_entregadas, item_id)
                    )
        except Exception as _e_bult:
            print(f"[fedex_poll] no se pudo guardar el conteo de bultos "
                  f"del item {item_id}: {_e_bult}", flush=True)

        apply_res = _tr_apply_carrier_status(
            item_id, estado_final, fuente='fedex',
            payload={"fedex": {
                "n_bultos":     n_total,
                "n_entregados": n_entregadas,
                "pieces": [
                    {"tracking_number": _t,
                     "status_code":  (_p or {}).get("status_code"),
                     "status_label": (_p or {}).get("status_label"),
                     "eta":          (_p or {}).get("eta"),
                     "scans":        ((_p or {}).get("scans") or [])[:5]}
                    for _t, _p in zip(tns_item, piezas)
                ],
            }},
            comentario=comentario or None,
            # 2026-06-14 (Daniel, 2ª decisión): el poller automático AHORA SÍ
            # avisa al cliente cuando FedEx cambia el estado (en ruta/entregado/
            # entrega fallida). Es la base de la detección 24/7: con Cloud
            # Scheduler despertando este poll, los cambios de madrugada también
            # se notifican. El gate de _tr_event filtra los estados; el
            # anti-spam (600s) evita duplicados por re-polls.
            notify_cliente=True,
        )
        if apply_res.get("changed"):
            changed_count += 1
        items_log.append({
            "id":           item_id,
            "tn":           tns_item[0],
            "n_bultos":     n_total,
            "n_entregados": n_entregadas,
            "changed":      apply_res.get("changed", False),
            "estado":       apply_res.get("nuevo"),
            "anterior":     apply_res.get("anterior"),
        })
    # "polled" cuenta ITEMS procesados (no tracking numbers): el loop daemon
    # corta con `if polled == 0: break`, así que tiene que seguir reflejando
    # "cuánto trabajo había", no cuántas piezas se consultaron.
    return {"ok": True, "polled": len(rows), "changed": changed_count,
            "items": items_log, "multibulto": n_multibulto,
            "tns_consultados": len(uniq_tns)}


@app.route("/transporte/cron/fedex-track-poll", methods=["GET", "POST"])
def tr_cron_fedex_poll():
    """Polling masivo de los items con tracking FedEx que aún no están en
    estado terminal. Invocable manualmente o por Cloud Scheduler externo.
    (El polling automático interno corre en _fedex_track_poll_loop.)

    Seguridad: protegido con FEDEX_CRON_TOKEN (header X-Cron-Token; el query
    ?token= es fallback de compatibilidad, ver _cron_extract_token).
    Si no se configura el token, solo acepta requests desde 127.0.0.1.

    Query params:
      - limit (default 25, max 30 por límite FedEx por request)
      - dry  (1 = solo lista, no actualiza)

    Returns: { ok, polled, changed, items, msg }
    """
    tok = _cron_extract_token()
    if not _fedex_cron_token_required(tok):
        return jsonify({"error": "forbidden"}), 403

    limit = min(int(request.args.get("limit") or 25), 30)
    dry   = request.args.get("dry") in ("1", "true", "yes")
    res = _fedex_poll_batch(limit=limit, dry=dry)
    status = 200 if res.get("ok") else (503 if "no configurada" in (res.get("error") or "") else 502)
    return jsonify(res), status


# ─────────────────────────────────────────────────────────────────────────────
#  AUTO-POLLER FEDEX (hilo daemon interno) — estados que se mueven solos
#  ---------------------------------------------------------------------------
#  Cada FEDEX_AUTOPOLL_INTERVAL_MIN (default 20) dispara _fedex_poll_batch para
#  actualizar los estados de los envíos FedEx activos. NO manda correos al
#  cliente (el poll usa notify_cliente=False; decisión de Daniel 2026-06-14).
#
#  Lock por LEASE en tabla fedex_poll_lock: con 2 workers Gunicorn (y/o varias
#  instancias de Cloud Run) solo UNO corre cada ciclo. El UPDATE condicional es
#  atómico (InnoDB bloquea la fila), así no se duplican consultas a FedEx.
#
#  Cloud Run escala a 0 sin tráfico → el hilo vive mientras la instancia esté
#  arriba (horas laborales). El estado vive en MySQL; al re-levantar, sigue.
#  Si se necesita 24/7 garantizado, el endpoint /transporte/cron/fedex-track-poll
#  ya existe para un Cloud Scheduler externo (no requiere tocar este hilo).
# ─────────────────────────────────────────────────────────────────────────────
def _ensure_fedex_poll_lock_table():
    """Tabla idempotente para coordinar el auto-poll cross-worker (lease lock)."""
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS fedex_poll_lock (
                    id           INT PRIMARY KEY,
                    locked_until DATETIME     DEFAULT NULL,
                    worker_id    INT          DEFAULT 0,
                    last_run     DATETIME     DEFAULT NULL,
                    last_result  VARCHAR(255) DEFAULT NULL
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
            """)
            # Fila única id=1 (INSERT IGNORE = idempotente).
            cur.execute("INSERT IGNORE INTO fedex_poll_lock (id) VALUES (1)")
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"[fedex-autopoll] no se pudo asegurar fedex_poll_lock: {e}", flush=True)


def _fedex_poll_acquire_lease(lease_seconds=600):
    """Intenta tomar el lease del poll. UPDATE condicional ATÓMICO: solo gana el
    worker que encuentra el lock libre o vencido. Devuelve True si ganó."""
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute("""
                UPDATE fedex_poll_lock
                SET locked_until = DATE_ADD(NOW(), INTERVAL %s SECOND),
                    worker_id    = %s,
                    last_run     = NOW()
                WHERE id = 1
                  AND (locked_until IS NULL OR locked_until < NOW())
            """, (lease_seconds, os.getpid()))
            won = (cur.rowcount == 1)
        conn.commit()
        conn.close()
        return won
    except Exception as e:
        print(f"[fedex-autopoll] lease error: {e}", flush=True)
        return False


def _fedex_poll_release_lease(result_msg=""):
    """Libera el lease al terminar (lo deja vencido para que el próximo ciclo
    pueda re-tomarlo de inmediato) y guarda un resumen del último resultado."""
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE fedex_poll_lock SET locked_until=NULL, last_result=%s "
                "WHERE id=1 AND worker_id=%s",
                ((result_msg or "")[:255], os.getpid())
            )
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"[fedex-autopoll] release error: {e}", flush=True)


def _fedex_autopoll_enabled():
    """Auto-poll habilitado si hay credenciales Track API y no se apagó por env.
    Apagar con FEDEX_AUTOPOLL=off (o 0/false)."""
    flag = (os.environ.get("FEDEX_AUTOPOLL", "on") or "on").strip().lower()
    if flag in ("0", "off", "false", "no"):
        return False
    return bool(FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET)


def _fedex_track_poll_loop():
    """Hilo daemon: cada FEDEX_AUTOPOLL_INTERVAL_MIN dispara el polling de
    estados FedEx. Toma el lease antes de correr (anti-doble-worker). Corre
    varios batches por ciclo hasta agotar los items elegibles o un máximo,
    con pausa entre batches para respetar el rate-limit de FedEx Track API."""
    import time as _time
    try:
        interval_min = int(os.environ.get("FEDEX_AUTOPOLL_INTERVAL_MIN", "20"))
    except Exception:
        interval_min = 20
    interval_min = max(5, min(interval_min, 120))   # entre 5 y 120 min
    MAX_BATCHES_POR_CICLO = 6                        # hasta ~180 envíos/ciclo

    _ensure_fedex_poll_lock_table()
    print(f"[fedex-autopoll] arrancado pid={os.getpid()} "
          f"(cada {interval_min} min · enabled={_fedex_autopoll_enabled()})", flush=True)

    # Primer ciclo: esperar 2 min tras el boot (deja que la app levante y
    # evita correr durante el arranque/migraciones).
    _time.sleep(120)

    while True:
        try:
            if not _fedex_autopoll_enabled():
                _time.sleep(interval_min * 60)
                continue

            # Lease de 10 min: cubre la ejecución del ciclo sin bloquear de más.
            if not _fedex_poll_acquire_lease(lease_seconds=600):
                # Otro worker está corriendo este ciclo. Saltar.
                _time.sleep(interval_min * 60)
                continue

            total_polled = total_changed = 0
            msg = "sin items"
            try:
                # FIX 2026-07-29 (hallado en chequeo de salud: "[fedex-autopoll]
                # loop error: Working outside of application context" cada
                # ciclo): _fedex_poll_batch usa mysql_fetchall()/get_db(), que
                # exige contexto Flask -- sin este `with`, cada ciclo fallaba
                # en silencio y el estado FedEx nunca se actualizaba solo.
                # Mismo patron que _simpliroute_poll_loop (fix 2026-07-28).
                with app.app_context():
                    for _ in range(MAX_BATCHES_POR_CICLO):
                        res = _fedex_poll_batch(limit=30, dry=False)
                        if not res.get("ok"):
                            print(f"[fedex-autopoll] batch error: {res.get('error')}", flush=True)
                            break
                        p = res.get("polled", 0)
                        total_polled  += p
                        total_changed += res.get("changed", 0)
                        if p == 0:
                            break          # ya no quedan items que pollear
                        _time.sleep(3)     # respeta rate-limit FedEx entre batches
                if total_polled:
                    msg = f"polled={total_polled} changed={total_changed}"
                    print(f"[fedex-autopoll] ciclo OK · {msg}", flush=True)
            finally:
                _fedex_poll_release_lease(msg)

            _time.sleep(interval_min * 60)
        except Exception as e:
            print(f"[fedex-autopoll] loop error: {e}", flush=True)
            _time.sleep(300)   # 5 min ante error inesperado


def _start_fedex_poll_scheduler_once():
    """Arranca el hilo del auto-poller (evita doble arranque por nombre)."""
    import threading as _th
    nombre = "fedex-autopoll"
    for t in _th.enumerate():
        if t.name == nombre and t.is_alive():
            return
    try:
        t = _th.Thread(target=_fedex_track_poll_loop, daemon=True, name=nombre)
        t.start()
    except Exception as e:
        print(f"[fedex-autopoll] no se pudo arrancar: {e}", flush=True)


try:
    _start_fedex_poll_scheduler_once()
except Exception as _e_fxpoll:
    print(f"[fedex-autopoll] startup error: {_e_fxpoll}", flush=True)


# ═══════════════════════════════════════════════════════════════════════════
#  POLLER SIMPLIROUTE — trae el estado de entrega de vuelta (Daniel 2026-07-24)
#  -------------------------------------------------------------------------
#  Cierra el círculo de la integración: hasta acá ILUS SUBÍA las visitas, pero
#  nadie escribía el estado de vuelta. Este poller consulta SimpliRoute y
#  actualiza el estado del item + guarda la prueba de entrega (firma, fotos,
#  GPS, hora) para que la trazabilidad la brinde ILUS y no el transportista.
#
#  Se mantiene SEPARADO del poller de FedEx a propósito: distinta credencial
#  (una por courier vs una global), distinta clave de consulta, y así un 401
#  de un transportista no deja sin actualizar a FedEx ni al revés.
#
#  Eficiencia: 1 sola llamada por (cuenta, fecha) usando
#  GET /v1/routes/visits/?planned_date=... — la doc de SimpliRoute recomienda
#  ese endpoint justamente para trackear en tiempo real. Un día con 2
#  manifiestos = 2 requests, no 1 por factura.
# ═══════════════════════════════════════════════════════════════════════════

def _ensure_simpliroute_poll_lock_table():
    """Lease lock propio (NO se comparte con FedEx). Idempotente."""
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS simpliroute_poll_lock (
                    id           INT PRIMARY KEY,
                    locked_until DATETIME     DEFAULT NULL,
                    worker_id    INT          DEFAULT 0,
                    last_run     DATETIME     DEFAULT NULL,
                    last_result  VARCHAR(255) DEFAULT NULL
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
            """)
            cur.execute("INSERT IGNORE INTO simpliroute_poll_lock (id) VALUES (1)")
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"[sr-autopoll] no se pudo asegurar simpliroute_poll_lock: {e}", flush=True)


def _sr_poll_acquire_lease(lease_seconds=600):
    """UPDATE condicional atómico: solo un worker corre el ciclo."""
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute("""
                UPDATE simpliroute_poll_lock
                SET locked_until = DATE_ADD(NOW(), INTERVAL %s SECOND),
                    worker_id    = %s,
                    last_run     = NOW()
                WHERE id = 1
                  AND (locked_until IS NULL OR locked_until < NOW())
            """, (lease_seconds, os.getpid()))
            won = (cur.rowcount == 1)
        conn.commit()
        conn.close()
        return won
    except Exception as e:
        print(f"[sr-autopoll] lease error: {e}", flush=True)
        return False


def _sr_poll_release_lease(result_msg=""):
    try:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE simpliroute_poll_lock SET locked_until=NULL, last_result=%s "
                "WHERE id=1 AND worker_id=%s",
                ((result_msg or "")[:255], os.getpid()))
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"[sr-autopoll] release error: {e}", flush=True)


def _sr_ingest_pod(item_id, commitment_id, visit):
    """Guarda la prueba de entrega que entrega SimpliRoute (firma, fotos, GPS,
    hora) en transport_delivery_proof. Upsert por manifest_item_id (esa tabla
    tiene UNIQUE uq_dp_item), así re-pollear no duplica filas.

    NO pisa una prueba cargada a mano por el chofer de ILUS: si ya existe una
    fila con firma y esta viene sin firma, se conserva la existente.
    """
    import simpliroute_client as _src
    import json as _json
    pod = _src.extract_pod(visit)
    if not pod:
        return False
    try:
        prev = mysql_fetchone(
            "SELECT id, firma_url FROM transport_delivery_proof WHERE manifest_item_id=%s",
            (item_id,))
        if prev and (prev.get("firma_url") or "").strip() and not pod.get("firma_url"):
            pod["firma_url"] = prev["firma_url"]   # no degradar una firma existente
        # checkout_time viene ISO-8601 con Z; MySQL DATETIME no acepta la 'T'/'Z'.
        entregado = (pod.get("entregado_at") or "").replace("T", " ").replace("Z", "")[:19] or None
        mysql_execute("""
            INSERT INTO transport_delivery_proof
              (manifest_item_id, commitment_id, receptor_nombre, receptor_relacion,
               firma_url, fotos_json, lat, lng, entregado_at, usuario, notas)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON DUPLICATE KEY UPDATE
              firma_url    = COALESCE(VALUES(firma_url), firma_url),
              fotos_json   = VALUES(fotos_json),
              lat          = COALESCE(VALUES(lat), lat),
              lng          = COALESCE(VALUES(lng), lng),
              entregado_at = COALESCE(VALUES(entregado_at), entregado_at),
              notas        = VALUES(notas)
        """, (item_id, commitment_id, pod["receptor_nombre"][:180], "Transportista",
              pod.get("firma_url"),
              _json.dumps(pod.get("fotos") or [], ensure_ascii=False),
              pod.get("lat"), pod.get("lng"), entregado,
              "simpliroute", (pod.get("notas") or "")[:2000] or None))
        return True
    except Exception as e:
        print(f"[sr-poll] no se pudo guardar POD item={item_id}: {e}", flush=True)
        return False


def _sr_normalizar_reference(ref):
    """Normaliza una 'reference' tido-nudo para comparar de forma tolerante.

    FIX 2026-07-28 (Daniel: caso BLV 22738 / Felca): el mismo documento
    puede existir en transport_commitments con el nudo CON ceros a la
    izquierda ('0000022738') y SIN ellos ('22738') -- dos filas de
    commitment distintas para lo que humanamente es "el mismo pedido". La
    reference que viaja a SimpliRoute usa el nudo tal cual esté guardado, así
    que "BLV-22738" y "BLV-0000022738" son strings DISTINTOS que nunca
    calzaban en una comparación exacta, aunque se refieran al mismo despacho.
    Se normaliza quitando los ceros a la izquierda de la parte numérica final.

    FIX 2026-08-07 (Daniel: caso BLV 22890/22877, "esto es lo que estamos
    vendiendo, no puede fallar" — 30 envíos congelados 4 días, 9 de ellos ya
    entregados en la calle). La versión anterior SOLO quitaba los ceros
    cuando la reference traía guion: una reference sin guion —el "nudo
    pelado", que es EXACTAMENTE el formato con que el courier carga sus
    visitas por Excel ("Id de referencia" = 22890)— salía intacta. Así,
    el fallback del nudo pelado buscaba "0000022890" (el nudo de la BD, que
    viene del ERP con ceros) contra visitas indexadas como "22890": MISS
    eterno. El parche del caso BLV 22738 que dependía de este fallback fue
    código muerto desde el día que se escribió, salvo para nudos guardados
    sin ceros (que fue justo ese caso — por eso pareció funcionar).
    Confirmado contra la API real: ILUS sube "BLV-0000022890" (pending para
    siempre) y Felca opera "22890" (completed) — dos universos de visitas
    en la misma cuenta que esta función es la única encargada de unir.
    """
    ref = (ref or "").strip()
    if "-" not in ref:
        return str(int(ref)) if ref.isdigit() else ref
    tido, nudo = ref.rsplit("-", 1)
    nudo = nudo.strip()
    if nudo.isdigit():
        nudo = str(int(nudo))
    return f"{tido}-{nudo}"


def _sr_visita_pertenece_a_otro_manifiesto(commitment_id, manifest_id_actual, visit_id_candidato):
    """True si `visit_id_candidato` ya está guardado en OTRA fila de
    transport_manifest_items del MISMO commitment pero de un manifiesto
    distinto -- esa fila es la dueña legítima de esa visita.

    BUG REAL (2026-08-10, Daniel: caso FCV 11240, manifiesto 17 vs 41).
    _simpliroute_poll_batch reconcilia visitas por 'reference' (tido-nudo)
    para rescatar casos donde SimpliRoute recreó la visita con un id nuevo
    (ver casos BLV 22738/22890, FCV 11137 en las funciones que llaman esto).
    Ese rescate es correcto cuando solo hay UNA fila de ILUS de por medio.
    Pero si el mismo commitment vive en DOS manifiestos (confirm_dup lo
    permite: la subida vieja falló de verdad y se re-agregó a uno nuevo),
    la reference es la MISMA para ambas filas -- y sin este freno, el
    manifiesto VIEJO le "robaba" al NUEVO el visit_id vigente, heredando su
    fecha/estado aunque nunca tuvo ese despacho. Antes de adoptar una visita
    por reference hay que verificar que nadie más (en otro manifiesto) ya
    la tenga guardada -- si la tiene, esa es la vigente y este item debe
    quedarse como está.
    """
    if not visit_id_candidato:
        return False
    fila = mysql_fetchone("""
        SELECT id FROM transport_manifest_items
         WHERE commitment_id=%s AND manifest_id<>%s AND simpliroute_visit_id=%s
         LIMIT 1
    """, (commitment_id, manifest_id_actual, str(visit_id_candidato)))
    return bool(fila)


def _simpliroute_reconciliar_huerfanos(limit=200, dry=False):
    """Vincula items SIN simpliroute_visit_id a una visita que YA EXISTE en
    SimpliRoute, buscándola por 'reference' (tido-nudo, ver
    simpliroute_client.build_visit_payload) en las visitas de HOY y AYER de
    la cuenta del courier.

    Por qué hace falta (Daniel 2026-07-28, caso Felca/Rafael Naranjo): el
    poller normal (_simpliroute_poll_batch) SOLO puede consultar visit_ids
    que ya tiene guardados en transport_manifest_items -- si SimpliRoute
    repite/duplica una ruta al día siguiente (o alguien recrea la visita
    allá), nace un id NUEVO que ILUS nunca subió ni conoce, y sin este
    parche esa visita queda invisible para siempre (0 candidatos, 0
    actualizaciones, aunque el chofer sí esté entregando en vivo).

    dry=True → solo reporta qué encontraría, no escribe nada.

    BUG REAL (2026-08-10, Daniel: caso FCV 11240 / manifiesto 17 vs 41 —
    "no puede decir entregado en el manifiesto antiguo... como lo actualicé
    en el otro manifiesto, se está ligando la información"). El mismo
    commitment puede quedar en DOS manifiestos a la vez (tr_asignar_a_manifiesto
    lo permite con confirm_dup — caso legítimo: la subida del manifiesto
    viejo falló de verdad y Daniel lo re-agregó a uno nuevo). Esta función
    buscaba huérfanos SOLO por 'reference' (tido-nudo), sin mirar si esa
    misma reference YA tenía una fila CON visita activa en otro manifiesto.
    Si el manifiesto viejo quedó huérfano (su subida original nunca llegó a
    SimpliRoute) y el nuevo sí subió bien, este reconciliador terminaba
    pegándole al item VIEJO el visit_id que en realidad pertenece al
    despacho NUEVO — y el poller normal, acto seguido, le copiaba encima
    estado_entrega/fecha del despacho de hoy. El manifiesto viejo mentía.
    Ahora se excluyen los commitments que ya tienen otra fila con visita
    activa en OTRO manifiesto: esa es la copia vigente, y la vieja debe
    quedar tal cual (huérfana, honesta) en vez de heredar datos ajenos.
    """
    import simpliroute_client as _src
    import datetime as _dt
    out = {"ok": True, "revisados": 0, "vinculados": 0, "errores": [], "items": []}
    try:
        cands = mysql_fetchall("""
            SELECT mi.id AS item_id, tm.courier, c.tido, c.nudo
              FROM transport_manifest_items mi
              JOIN transport_manifests tm ON tm.id = mi.manifest_id
              JOIN transport_commitments c ON c.id = mi.commitment_id
             WHERE (mi.simpliroute_visit_id IS NULL OR mi.simpliroute_visit_id = '')
               AND (mi.estado_entrega IS NULL
                    OR mi.estado_entrega NOT IN ('Entregado','Devolución'))
               AND tm.fecha >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
               AND NOT EXISTS (
                    SELECT 1 FROM transport_manifest_items mi2
                     WHERE mi2.commitment_id = mi.commitment_id
                       AND mi2.manifest_id <> mi.manifest_id
                       AND mi2.simpliroute_visit_id IS NOT NULL
                       AND mi2.simpliroute_visit_id <> ''
               )
             ORDER BY tm.fecha DESC
             LIMIT %s
        """, (int(limit),)) or []
    except Exception as e:
        print(f"[sr-autopoll] consulta de huerfanos fallo: {e}", flush=True)
        return {"ok": False, "error": f"consulta de huerfanos fallo: {e}",
                "revisados": 0, "vinculados": 0}

    cands = [c for c in cands if _simpliroute_courier_integra(c.get("courier"))]
    if not cands:
        out["msg"] = "Sin items huerfanos que revisar."
        return out
    out["revisados"] = len(cands)

    por_courier = {}
    for c in cands:
        por_courier.setdefault((c.get("courier") or "").strip(), []).append(c)

    # 2026-07-31: misma fecha Chile (no UTC) que el fix de _simpliroute_poll_batch,
    # mismo motivo (near-medianoche UTC ya rodo al dia siguiente en Chile).
    _hoy_cl = _now_chile().date()
    fechas = [_hoy_cl.isoformat(), (_hoy_cl - _dt.timedelta(days=1)).isoformat()]

    for courier, items in por_courier.items():
        token = _simpliroute_token_for_courier(courier)
        if not token:
            # 2026-08-07: antes era un `continue` MUDO — asimétrico con el
            # poller principal, que sí registra el error. Como
            # _simpliroute_courier_integra() acepta por NOMBRE aunque el
            # token no exista, un courier sin token entraba a "revisados" y
            # se saltaba sin dejar rastro: parecía revisado y no lo estaba.
            out["errores"].append(
                f"{courier}: integra SimpliRoute pero no tiene token configurado "
                f"({len(items)} item(s) sin revisar)")
            continue
        por_ref = {}
        for it in items:
            ref = f"{(it.get('tido') or '').strip()}-{(it.get('nudo') or '').strip()}".strip("-")
            if ref:
                por_ref[_sr_normalizar_reference(ref)] = it
            # Cubre visitas recreadas a mano con el nudo pelado como
            # reference (sin el prefijo del tido) -- ver caso BLV 22738.
            nudo_solo = _sr_normalizar_reference((it.get("nudo") or "").strip())
            if nudo_solo and nudo_solo not in por_ref:
                por_ref[nudo_solo] = it

        for fecha_s in fechas:
            if not por_ref:
                break
            r = _simpliroute_request(
                "GET", f"{_src.EP_VISITS}?planned_date={fecha_s}", token, timeout=45)
            if not r.get("ok"):
                out["errores"].append(f"{courier} {fecha_s}: {r.get('error')}")
                continue
            visitas = r.get("data")
            visitas = visitas if isinstance(visitas, list) else []
            for v in visitas:
                if not isinstance(v, dict):
                    continue
                ref = _sr_normalizar_reference((v.get("reference") or "").strip())
                it = por_ref.get(ref)
                if not it:
                    continue
                vid = v.get("id")
                if not vid:
                    continue
                registro = {"item_id": it["item_id"], "reference": ref,
                            "visit_id": vid, "fecha": fecha_s}
                if dry:
                    out["items"].append(registro)
                    por_ref.pop(ref, None)
                    continue
                try:
                    mysql_execute(
                        "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
                        "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW() "
                        "WHERE id=%s",
                        (str(vid), v.get("tracking_id") or "", it["item_id"]))
                    out["vinculados"] += 1
                    registro["changed"] = True
                    out["items"].append(registro)
                    _tr_log("manifest_item", it["item_id"],
                            "Visita SimpliRoute reconciliada automaticamente",
                            f"encontrada por reference={ref} -> visit_id={vid} "
                            f"(planned_date {fecha_s})")
                except Exception as e:
                    out["errores"].append(f"item {it['item_id']}: no se pudo guardar ({e})")
                por_ref.pop(ref, None)

    return out


def _simpliroute_poll_batch(limit=400, dry=False):
    """Un ciclo de polling. Devuelve dict con el resumen (nunca lanza).

    dry=True → solo reporta qué haría, no escribe nada.
    """
    import simpliroute_client as _src
    import datetime as _dt_mod
    out = {"ok": True, "consultados": 0, "actualizados": 0, "pod": 0,
           "grupos": 0, "errores": [], "items": [],
           "huerfanos": {}}
    try:
        out["huerfanos"] = _simpliroute_reconciliar_huerfanos(dry=dry)
    except Exception as e:
        out["huerfanos"] = {"ok": False, "error": f"reconciliacion fallo: {e}"}
    try:
        cands = mysql_fetchall("""
            SELECT mi.id AS item_id, mi.manifest_id, mi.commitment_id, mi.simpliroute_visit_id,
                   mi.estado_entrega, tm.fecha, tm.courier, c.tido, c.nudo
              FROM transport_manifest_items mi
              JOIN transport_manifests tm ON tm.id = mi.manifest_id
              LEFT JOIN transport_commitments c ON c.id = mi.commitment_id
             WHERE mi.simpliroute_visit_id IS NOT NULL
               AND mi.simpliroute_visit_id <> ''
               AND (mi.estado_entrega IS NULL
                    OR mi.estado_entrega NOT IN ('Entregado','Devolución'))
               AND tm.fecha >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
             ORDER BY tm.fecha DESC, mi.id ASC
             LIMIT %s
        """, (int(limit),)) or []
    except Exception as e:
        print(f"[sr-autopoll] consulta de candidatos falló: {e}", flush=True)
        return {"ok": False, "error": f"consulta de candidatos falló: {e}",
                "consultados": 0, "actualizados": 0, "pod": 0, "grupos": 0, "errores": [str(e)]}

    if not cands:
        out["msg"] = "Sin visitas pendientes de actualizar."
        return out
    out["consultados"] = len(cands)

    # Agrupar por (courier, fecha) → 1 request por grupo
    grupos = {}
    for c in cands:
        f = c.get("fecha")
        fecha_s = f.isoformat() if hasattr(f, "isoformat") else str(f or "")[:10]
        grupos.setdefault(((c.get("courier") or "").strip(), fecha_s), []).append(c)
    out["grupos"] = len(grupos)

    for (courier, fecha_s), items in grupos.items():
        token = _simpliroute_token_for_courier(courier)
        if not token or not fecha_s:
            out["errores"].append(f"{courier or '(sin courier)'}: sin token o sin fecha")
            continue
        r = _simpliroute_request(
            "GET", f"{_src.EP_VISITS}?planned_date={fecha_s}", token, timeout=45)
        if not r.get("ok"):
            out["errores"].append(f"{courier} {fecha_s}: {r.get('error')}")
            continue
        data = r.get("data")
        visitas = data if isinstance(data, list) else []
        por_id = {str(v.get("id")): v for v in visitas if isinstance(v, dict) and v.get("id")}

        def _sr_rank(v):
            # 2026-07-31 (Daniel, caso FCV 11137 / BLV 22721 / BLV 22734):
            # SimpliRoute puede tener DOS visitas vivas con la misma
            # reference -- la que subio la API de ILUS (queda "pending"
            # para siempre, abandonada) y otra que el despachador
            # gestiono de verdad (con checkout). Antes, `por_ref.setdefault`
            # se quedaba con la que apareciera PRIMERO en la respuesta
            # (normalmente la vieja pending), y la real, ya entregada,
            # nunca se consideraba -- el item quedaba atascado sin avisar.
            # Ahora se prioriza SIEMPRE la visita mas avanzada (terminal >
            # pending), sin importar el orden en que llego.
            st = (v.get("status") or "").lower()
            if st in (_src.SR_STATUS_COMPLETED, _src.SR_STATUS_FAILED, _src.SR_STATUS_PARTIAL):
                return 2
            if v.get("checkout_time"):
                return 2
            return 1 if st == _src.SR_STATUS_PENDING else 0

        por_ref = {}
        # 2026-07-29 (Daniel, caso BLV 22729): agrupa TODAS las visitas que
        # comparten reference (no solo la primera) — necesario para el
        # tie-breaker de abajo, que corta el ping-pong infinito cuando
        # SimpliRoute tiene DOS visitas vivas con la misma reference
        # (duplicado real en SimpliRoute, ej. Alison recreó la visita a mano
        # sin cancelar la original). Antes esto alternaba entre ambos
        # visit_id en cada ciclo del poller, spameando la trazabilidad con
        # "Visita SimpliRoute reemplazada automaticamente" sin fin.
        por_ref_todas = {}
        for v in visitas:
            if isinstance(v, dict) and (v.get("reference") or "").strip():
                _ref_k = _sr_normalizar_reference((v.get("reference") or "").strip())
                _actual = por_ref.get(_ref_k)
                if _actual is None or _sr_rank(v) > _sr_rank(_actual):
                    por_ref[_ref_k] = v
                por_ref_todas.setdefault(_ref_k, []).append(v)

        # FIX 2026-07-28 (Daniel: caso BLV 22738): la visita de REEMPLAZO
        # puede quedar agendada para HOY aunque el manifiesto sea de otra
        # fecha (fecha_s) -- si no se trae también el listado de hoy, la
        # búsqueda por reference nunca la encuentra y el poller solo ve la
        # visita vieja (que sigue "viva" en su fecha original, atascada).
        # 2026-07-31 (Daniel, caso FCV 11137 / BLV 22721 / BLV 22734): usar
        # _now_chile() y NO date.today() -- este ultimo toma la fecha del
        # SERVIDOR (UTC), y entre ~20:00-23:59 hora Chile el reloj UTC ya
        # rodo al dia siguiente. La visita real (entregada "hoy" en Chile)
        # quedaba en la fecha de AYER en UTC y el fetch de "hoy" nunca la
        # encontraba -- mismo bug de fondo que SEV-8d (KPIs), ver
        # _hoy_chile_rango_utc().
        hoy_s = _now_chile().date().isoformat()
        if hoy_s != fecha_s:
            r_hoy_grupo = _simpliroute_request(
                "GET", f"{_src.EP_VISITS}?planned_date={hoy_s}", token, timeout=45)
            if r_hoy_grupo.get("ok"):
                data_hoy = r_hoy_grupo.get("data")
                for v in (data_hoy if isinstance(data_hoy, list) else []):
                    if isinstance(v, dict) and (v.get("reference") or "").strip():
                        _ref_k = _sr_normalizar_reference((v.get("reference") or "").strip())
                        _actual = por_ref.get(_ref_k)
                        if _actual is None or _sr_rank(v) > _sr_rank(_actual):
                            por_ref[_ref_k] = v
                        # 2026-07-31: tambien se agrega a por_ref_todas -- si no,
                        # el tie-breaker anti ping-pong de abajo no sabe que esta
                        # visita de HOY tambien "compite" por la misma reference
                        # y podria bloquear el cambio hacia ella.
                        por_ref_todas.setdefault(_ref_k, []).append(v)

        # ── Índice de los últimos 7 días, PEREZOSO y por grupo ────────────
        # FIX 2026-08-07 (Daniel: BLV 22890 entregado el 06-08 a las 15:29 y
        # ILUS diciendo "Retirado" al día siguiente). El bucle de arriba solo
        # consulta DOS fechas: la del manifiesto y HOY. Una entrega de AYER
        # (o del viernes, mirada el lunes) no está en ninguna de las dos, así
        # que la visita real entregada era invisible apenas rodaba la
        # medianoche — el rescate de 7 días que ya existía más abajo solo
        # corre cuando el visit_id guardado NO resuelve, y la visita fantasma
        # de ILUS siempre resuelve (pending eterno), o sea nunca corría.
        #
        # Este índice se carga UNA vez por (courier, ciclo) y SOLO si algún
        # item lo necesita (visita resuelta que sigue sin avanzar): 7
        # peticiones por grupo en el peor caso, no 7 por item. Indexa por
        # reference normalizada quedándose con la visita MÁS avanzada
        # (_sr_rank mayor) de cada reference.
        _idx7 = {"cargado": False, "por_ref": {}}

        def _indice_7d():
            if _idx7["cargado"]:
                return _idx7["por_ref"]
            _idx7["cargado"] = True
            _ya = {fecha_s, hoy_s}
            for _delta in range(0, 7):
                _f = (_now_chile().date() - _dt_mod.timedelta(days=_delta)).isoformat()
                if _f in _ya:
                    continue
                _ya.add(_f)
                _r7 = _simpliroute_request(
                    "GET", f"{_src.EP_VISITS}?planned_date={_f}", token, timeout=45)
                if not _r7.get("ok"):
                    continue
                _d7 = _r7.get("data")
                for _v in (_d7 if isinstance(_d7, list) else []):
                    if isinstance(_v, dict) and (_v.get("reference") or "").strip():
                        _k = _sr_normalizar_reference((_v.get("reference") or "").strip())
                        _prev = _idx7["por_ref"].get(_k)
                        if _prev is None or _sr_rank(_v) > _sr_rank(_prev):
                            _idx7["por_ref"][_k] = _v
            # Las dos fechas ya cargadas también compiten en el índice.
            for _k, _v in por_ref.items():
                _prev = _idx7["por_ref"].get(_k)
                if _prev is None or _sr_rank(_v) > _sr_rank(_prev):
                    _idx7["por_ref"][_k] = _v
            return _idx7["por_ref"]

        for it in items:
            vid = str(it.get("simpliroute_visit_id") or "")
            _vid_original = vid   # para saber después si hubo re-vinculación
            ref_it = f"{(it.get('tido') or '').strip()}-{(it.get('nudo') or '').strip()}".strip("-")
            ref_it = _sr_normalizar_reference(ref_it)

            # FIX 2026-07-28 (Daniel: caso BLV 22738 / Felca): priorizar SIEMPRE
            # la visita por 'reference' (tido-nudo) por sobre el visit_id
            # guardado. SimpliRoute puede dejar la visita VIEJA viva (en
            # 'pending', nunca la completan) mientras la entrega real ocurre
            # bajo una visita NUEVA con id distinto -- si se busca solo por id
            # guardado, la vieja "sí existe" y el poller nunca se entera de
            # que ya no es la vigente.
            visita_ref = por_ref.get(ref_it) if ref_it else None
            # FIX 2026-07-28 (confirmado con datos reales, caso BLV 22738):
            # si alguien re-crea la visita a mano DIRECTO en SimpliRoute
            # (ej. Alison, cuando la original quedó atascada), suele escribir
            # la referencia como el NUDO PELADO ('22738'), sin el prefijo del
            # tido ('BLV-22738') que usa la subida automática de ILUS. Si la
            # forma con tido no trae una visita nueva, probar también la
            # forma pelada antes de rendirse.
            if not visita_ref or str(visita_ref.get("id")) == vid:
                _nudo_solo = _sr_normalizar_reference((it.get("nudo") or "").strip())
                if _nudo_solo and _nudo_solo != ref_it:
                    _visita_bare = por_ref.get(_nudo_solo)
                    if _visita_bare and str(_visita_bare.get("id")) != vid:
                        visita_ref = _visita_bare
            # Tie-breaker anti ping-pong (2026-07-29): si el visit_id YA
            # GUARDADO sigue estando entre las visitas vivas con esta misma
            # reference, no lo cambiamos aunque por_ref haya resuelto OTRA
            # (caso de dos visitas duplicadas con la misma reference en
            # SimpliRoute — sin esto, cada ciclo del poller "corregía" hacia
            # el que apareciera primero en la respuesta, y el próximo ciclo
            # revertía, generando el ping-pong infinito).
            # EXCEPCION 2026-07-31 (caso FCV 11137 / BLV 22721 / BLV 22734):
            # el tie-breaker de arriba, tal cual, tambien bloqueaba el cambio
            # cuando la visita GUARDADA es un duplicado abandonado ("pending"
            # para siempre) y la real (con checkout, ya entregada) aparecio
            # despues -- el item quedaba "Entregado a transporte" para
            # siempre aunque SimpliRoute ya mostrara la entrega. Se permite
            # el cambio igual cuando la visita_ref candidata esta MAS
            # avanzada (rank mayor) que la guardada -- solo se bloquea el
            # ping-pong entre visitas de rango IGUAL.
            _matches_ref = por_ref_todas.get(ref_it) or []
            _vid_actual = next((m for m in _matches_ref if str(m.get("id")) == vid), None)
            if vid and _vid_actual is not None:
                if not visita_ref or _sr_rank(visita_ref) <= _sr_rank(_vid_actual):
                    visita_ref = None

            if visita_ref and str(visita_ref.get("id")) != vid:
                nuevo_id = str(visita_ref.get("id") or "")
                # BUG REAL (2026-08-10, caso FCV 11240): si esta visita ya es
                # de OTRA fila del mismo commitment en OTRO manifiesto, esa
                # es la vigente -- no se adopta acá (ver
                # _sr_visita_pertenece_a_otro_manifiesto).
                if _sr_visita_pertenece_a_otro_manifiesto(
                        it.get("commitment_id"), it.get("manifest_id"), nuevo_id):
                    pass
                # 2026-08-07: el UPDATE va detrás de `dry` — antes no lo
                # estaba, y no escribía en dry-run SOLO porque el match de
                # arriba fallaba siempre (bug del normalizador). Con el
                # normalizador arreglado, un dry-run sin esta guarda habría
                # empezado a escribir en producción. En memoria el reemplazo
                # se adopta igual, para que el dry reporte lo que HARÍA.
                elif not dry:
                    try:
                        mysql_execute(
                            "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
                            "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW() "
                            "WHERE id=%s",
                            (nuevo_id, visita_ref.get("tracking_id") or "", it["item_id"]))
                        _tr_log("manifest_item", it["item_id"],
                                "Visita SimpliRoute reemplazada automaticamente",
                                f"visit_id viejo {vid} sigue vivo pero superado -> nuevo {nuevo_id} "
                                f"(reference={ref_it})")
                        vid = nuevo_id
                    except Exception as e:
                        out["errores"].append(
                            f"item {it['item_id']}: encontrada visita nueva {nuevo_id} "
                            f"pero no se pudo guardar ({e})")
                else:
                    vid = nuevo_id

            visita = por_id.get(vid)
            if not visita and visita_ref and str(visita_ref.get("id")) == vid:
                visita = visita_ref
            if not visita:
                # BUG REAL (Daniel 2026-07-25, caso VD 6371 / MAN-2026-0011):
                # el listado GET /v1/routes/visits/?planned_date=<fecha del
                # MANIFIESTO> deja de encontrar la visita en cuanto el
                # despachador la REPROGRAMA a otra fecha dentro de SimpliRoute
                # (ej. al asignarle chofer/vehículo con "Rafael 4000"). Antes
                # esto se trataba como "no está, reintentar el próximo ciclo"
                # y quedaba en loop infinito porque planned_date nunca vuelve
                # a coincidir. Fallback: pedir la visita DIRECTO por su id
                # (retrieve de DRF), que no depende de qué fecha tenga hoy.
                r_uno = _simpliroute_request(
                    "GET", f"{_src.EP_VISITS}{vid}/", token, timeout=20)
                if r_uno.get("ok") and isinstance(r_uno.get("data"), dict):
                    visita = r_uno["data"]
                else:
                    # FIX 2026-07-28 (Daniel: caso BLV 22738 / Felca — el
                    # chofer entregaba en vivo y el manifiesto/Monitor nunca
                    # se enteraban). El visit_id guardado por ILUS puede
                    # quedar OBSOLETO: SimpliRoute puede reemplazar la visita
                    # por una NUEVA (id distinto) sin avisar -- ni "reprogramar
                    # fecha" (eso mueve la MISMA visita) ni "borrar" (eso
                    # devolvía 404 antes de este fix, y aquí simplemente se
                    # abandonaba con un error). Antes de rendirse: buscar una
                    # visita viva con la MISMA reference (tido-nudo) entre las
                    # de este grupo, y si no aparece, en las de HOY (por si el
                    # reemplazo quedó planificado para otra fecha). Si se
                    # encuentra, se re-vincula el item a la visita nueva.
                    ref_it = _sr_normalizar_reference(f"{(it.get('tido') or '').strip()}-{(it.get('nudo') or '').strip()}".strip("-"))
                    visita_nueva = None
                    if ref_it:
                        visita_nueva = next(
                            (v for v in visitas
                             if isinstance(v, dict) and _sr_normalizar_reference((v.get("reference") or "").strip()) == ref_it
                             and str(v.get("id")) != vid),
                            None)
                        # 2026-07-30 (Daniel: caso FCV 11137 / BLV 22721 / BLV
                        # 22734 -- entregados de verdad en SimpliRoute pero
                        # ILUS los mostraba "Entregado a transporte" por horas,
                        # sin ningun error): antes solo se probaba HOY como
                        # fecha de reemplazo. Si el despachador reprograma la
                        # visita a OTRO dia dentro de la ventana de 7 dias que
                        # ya usa la query de candidatos, ese caso quedaba
                        # igual de atascado que el que este bloque intenta
                        # arreglar. Se amplia la busqueda a los ultimos 7 dias
                        # (mismo horizonte que la seleccion de candidatos).
                        if not visita_nueva:
                            _dias_probados = {fecha_s}
                            for _delta in range(0, 7):
                                _fecha_probar = (_now_chile().date() - _dt_mod.timedelta(days=_delta)).isoformat()
                                if _fecha_probar in _dias_probados:
                                    continue
                                _dias_probados.add(_fecha_probar)
                                r_otro = _simpliroute_request(
                                    "GET", f"{_src.EP_VISITS}?planned_date={_fecha_probar}",
                                    token, timeout=45)
                                if not r_otro.get("ok"):
                                    continue
                                visitas_otro = r_otro.get("data")
                                visitas_otro = visitas_otro if isinstance(visitas_otro, list) else []
                                visita_nueva = next(
                                    (v for v in visitas_otro
                                     if isinstance(v, dict)
                                     and _sr_normalizar_reference((v.get("reference") or "").strip()) == ref_it
                                     and str(v.get("id")) != vid),
                                    None)
                                if visita_nueva:
                                    break
                    # BUG REAL (2026-08-10, caso FCV 11240): si la visita de
                    # reemplazo ya es de OTRA fila del mismo commitment en
                    # OTRO manifiesto, esa es la vigente -- no se adopta acá
                    # (cae al mismo tratamiento que "sin reemplazo" de abajo).
                    if visita_nueva and _sr_visita_pertenece_a_otro_manifiesto(
                            it.get("commitment_id"), it.get("manifest_id"),
                            str(visita_nueva.get("id") or "")):
                        visita_nueva = None
                    if visita_nueva:
                        nuevo_id = str(visita_nueva.get("id") or "")
                        try:
                            mysql_execute(
                                "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
                                "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW() "
                                "WHERE id=%s",
                                (nuevo_id, visita_nueva.get("tracking_id") or "", it["item_id"]))
                            _tr_log("manifest_item", it["item_id"],
                                    "Visita SimpliRoute reemplazada automaticamente",
                                    f"visit_id viejo {vid} ya no existia -> nuevo {nuevo_id} "
                                    f"(reference={ref_it})")
                            visita = visita_nueva
                            vid = nuevo_id
                        except Exception as e:
                            out["errores"].append(
                                f"item {it['item_id']}: encontrada visita nueva {nuevo_id} "
                                f"pero no se pudo guardar ({e})")
                            continue
                    else:
                        # Ahora sí: no existe / fue borrada / token sin acceso,
                        # y tampoco hay una visita de reemplazo por reference
                        # en los ultimos 7 dias. 2026-07-30: ANTES esto se
                        # abandonaba en silencio cuando r_uno.status era 404 --
                        # el item quedaba atascado en "Entregado a transporte"
                        # indefinidamente, sin ningun rastro en logs/errores/UI
                        # (la trazabilidad "fallaba en silencio", ver caso real
                        # Daniel 2026-07-30). Ahora SIEMPRE queda constancia:
                        # se persiste en simpliroute_error (visible para quien
                        # audite la BD) y en el log de auditoria del item, aun
                        # cuando no se cuenta como "error" del ciclo (para no
                        # cambiar el comportamiento de out['errores'] que ya
                        # consumen otras partes del poller).
                        _motivo_404 = (f"Visita SimpliRoute {vid} no encontrada (404) y sin "
                                       f"reemplazo por reference={ref_it} en los ultimos 7 dias")
                        # 2026-08-07: status 0 es lo que _simpliroute_request
                        # devuelve ante TIMEOUT o fallo de RED — tratarlo como
                        # 404 escribía en simpliroute_error el texto mentiroso
                        # "no encontrada (404)" cuando en realidad nunca hubo
                        # respuesta. Ahora la falla de red cuenta como error
                        # del ciclo (visible en el log) y NO persiste un
                        # diagnóstico falso sobre el item.
                        if r_uno.get("status") == 0:
                            out["errores"].append(
                                f"{courier} visita {vid}: sin respuesta de SimpliRoute "
                                f"(timeout/red) — {r_uno.get('error')}")
                            continue
                        if r_uno.get("status") != 404:
                            out["errores"].append(
                                f"{courier} visita {vid}: {r_uno.get('error')}")
                        else:
                            try:
                                mysql_execute(
                                    "UPDATE transport_manifest_items SET simpliroute_error=%s WHERE id=%s",
                                    (_motivo_404[:500], it["item_id"]))
                                _tr_log("manifest_item", it["item_id"],
                                        "SimpliRoute: visita no resuelta",
                                        _motivo_404)
                            except Exception:
                                pass
                        continue
            # ── RESCATE DE VISITA ESTANCADA (2026-08-07, caso BLV 22890) ──
            # La visita resuelta EXISTE pero no avanza (pending). Hasta hoy
            # ese caso era un punto muerto: estado_ilus_from_visit(pending)
            # devuelve None, no se escribe nada, no se cuenta nada, y el
            # rescate de 7 días de arriba nunca corría porque solo se dispara
            # cuando la visita NO resuelve. Acá se consulta el índice de 7
            # días buscando una visita MÁS AVANZADA con la misma reference
            # (forma tido-nudo o nudo pelado). Estrictamente más avanzada
            # (_sr_rank MAYOR, nunca igual): eso preserva el anti ping-pong
            # del caso BLV 22729 y usa la misma excepción del caso FCV 11137.
            if visita is not None and _sr_rank(visita) < 2:
                _i7 = _indice_7d()
                _mejor = None
                for _clave in (ref_it,
                               _sr_normalizar_reference((it.get("nudo") or "").strip())):
                    if not _clave:
                        continue
                    _cand = _i7.get(_clave)
                    if (_cand and str(_cand.get("id")) != str(visita.get("id"))
                            and _sr_rank(_cand) > _sr_rank(visita)):
                        if _mejor is None or _sr_rank(_cand) > _sr_rank(_mejor):
                            _mejor = _cand
                # BUG REAL (2026-08-10, caso FCV 11240): igual que los otros
                # dos rescates de esta función -- si _mejor ya es de OTRA fila
                # del mismo commitment en OTRO manifiesto, esa es la vigente.
                if _mejor is not None and _sr_visita_pertenece_a_otro_manifiesto(
                        it.get("commitment_id"), it.get("manifest_id"),
                        str(_mejor.get("id") or "")):
                    _mejor = None
                if _mejor is not None:
                    nuevo_id = str(_mejor.get("id") or "")
                    if not dry:
                        try:
                            mysql_execute(
                                "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
                                "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW() "
                                "WHERE id=%s",
                                (nuevo_id, _mejor.get("tracking_id") or "", it["item_id"]))
                            _tr_log("manifest_item", it["item_id"],
                                    "Visita SimpliRoute reemplazada automaticamente",
                                    f"visit_id {vid} seguia pending; en los ultimos 7 dias "
                                    f"existe {nuevo_id} mas avanzada (reference={ref_it})")
                            vid = nuevo_id
                            visita = _mejor
                        except Exception as e:
                            out["errores"].append(
                                f"item {it['item_id']}: visita estancada, encontrada "
                                f"{nuevo_id} pero no se pudo guardar ({e})")
                    else:
                        vid = nuevo_id
                        visita = _mejor

            estado_ilus, comentario = _src.estado_ilus_from_visit(visita)
            registro = {"item_id": it["item_id"], "visit_id": vid,
                        "sr_status": visita.get("status"),
                        "estado_ilus": estado_ilus, "comentario": comentario}

            # Contador de atascados (2026-08-07): items cuya visita sigue sin
            # avanzar con el manifiesto ya vencido hace más de un día. 30
            # items estuvieron 4 días congelados y el log era indistinguible
            # de "no hay nada que hacer" — este número es lo que corta eso.
            try:
                _f_mi = it.get("fecha")
                _f_mi = _f_mi if hasattr(_f_mi, "toordinal") else None
                if (_sr_rank(visita) < 2 and _f_mi
                        and (_now_chile().date() - _f_mi).days >= 1):
                    out["atascados"] = out.get("atascados", 0) + 1
            except Exception:
                pass

            if dry:
                out["items"].append(registro)
                continue
            if estado_ilus:
                # 2026-08-07: dos razones para NO mandar correo al cliente,
                # ambas de Daniel el mismo día:
                #
                # (1) RE-VINCULACIÓN ("te encargo que se actualicen los
                #     despachos, espero que NO enviemos correos, ya está
                #     cerrado el paso"): si el estado nuevo viene de haber
                #     cambiado la visita seguida (el destrabe de las visitas
                #     congeladas), el cliente ya vivió su entrega — un correo
                #     ahora solo confunde. El estado igual se corrige y queda
                #     trazado.
                # (2) ALCANCE VIEJO: checkout hace más de 24 h — mismo
                #     criterio aunque no haya habido re-vinculación.
                #
                # Un cambio fresco por el flujo normal (la MISMA visita
                # avanzó hoy) sigue avisando como siempre.
                _notify = True
                if vid != _vid_original:
                    _notify = False
                    registro["notify_omitido"] = "alcance por re-vinculacion de visita"
                else:
                    try:
                        _co = (visita.get("checkout_time") or "").strip()
                        if _co:
                            from datetime import datetime as _dt_ck, timezone as _tz_ck
                            _co_dt = _dt_ck.fromisoformat(_co.replace("Z", "+00:00"))
                            if _co_dt.tzinfo is None:
                                _co_dt = _co_dt.replace(tzinfo=_tz_ck.utc)
                            _edad_h = (_dt_ck.now(_tz_ck.utc) - _co_dt).total_seconds() / 3600.0
                            if _edad_h > 24:
                                _notify = False
                                registro["notify_omitido"] = f"checkout hace {_edad_h:.0f} h"
                    except Exception:
                        pass
                res = _tr_apply_carrier_status(
                    it["item_id"], estado_ilus,
                    fuente="simpliroute",
                    tracking_number=None,   # NO tocar: esa columna es de FedEx
                    comentario=comentario,
                    notify_cliente=_notify,
                )
                if res.get("changed"):
                    out["actualizados"] += 1
                    registro["changed"] = True
            # La prueba de entrega se guarda cuando la visita ya terminó,
            # incluso si el estado no cambió (ej. re-poll del mismo entregado).
            if (visita.get("status") or "").lower() in ("completed", "partial"):
                if _sr_ingest_pod(it["item_id"], it.get("commitment_id"), visita):
                    out["pod"] += 1
            out["items"].append(registro)

    return out


def _simpliroute_autopoll_enabled():
    """Activo si hay al menos un token configurado y no se apagó por env."""
    flag = (os.environ.get("SIMPLIROUTE_AUTOPOLL", "on") or "on").strip().lower()
    if flag in ("0", "off", "false", "no"):
        return False
    return any((os.environ.get(v) or "").strip() for v in SIMPLIROUTE_TOKENS_ENV.values())


def _simpliroute_poll_loop():
    """Hilo daemon: cada SIMPLIROUTE_AUTOPOLL_INTERVAL_MIN (default 10) trae
    los estados. Intervalo más corto que FedEx porque una ruta de reparto se
    mueve mucho más rápido que un envío internacional."""
    import time as _time
    try:
        interval_min = int(os.environ.get("SIMPLIROUTE_AUTOPOLL_INTERVAL_MIN", "10"))
    except Exception:
        interval_min = 10
    interval_min = max(5, min(interval_min, 60))

    _ensure_simpliroute_poll_lock_table()
    print(f"[sr-autopoll] arrancado pid={os.getpid()} (cada {interval_min} min · "
          f"enabled={_simpliroute_autopoll_enabled()})", flush=True)
    _time.sleep(150)   # deja que la app levante (y desfasa del poller FedEx)

    while True:
        try:
            if _simpliroute_autopoll_enabled() and _sr_poll_acquire_lease(600):
                msg = "ciclo interrumpido"   # si el batch revienta, el lease
                                             # igual se libera con este texto
                try:
                    # FIX 2026-07-28 (Daniel: manifiestos/Monitor no se
                    # actualizaban): _simpliroute_poll_batch usa get_db()/g,
                    # que exige contexto Flask -- sin este `with`, cada ciclo
                    # fallaba en silencio con "Working outside of application
                    # context" (el error se tragaba y se veia como
                    # "consultados=0", indistinguible de "no hay nada que
                    # hacer"). Mismo patron que _mant_cron_run_with_lock.
                    with app.app_context():
                        res = _simpliroute_poll_batch()
                    msg = (f"consultados={res.get('consultados', 0)} "
                           f"actualizados={res.get('actualizados', 0)} "
                           f"pod={res.get('pod', 0)} grupos={res.get('grupos', 0)}")
                    # 2026-08-07: atascados SIEMPRE visible (aun en 0). 30
                    # items pasaron 4 días congelados con un log idéntico a
                    # "no hay nada que hacer" — este número es la alarma.
                    msg += f" atascados={res.get('atascados', 0)}"
                    if res.get("errores"):
                        # El CONTENIDO, no solo el conteo: "errores=3" no le
                        # sirve a nadie a las 2 AM mirando logs.
                        _errs = res["errores"]
                        msg += (f" errores={len(_errs)} :: "
                                + " | ".join(str(e)[:160] for e in _errs[:3]))
                    huer = res.get("huerfanos") or {}
                    if huer.get("revisados") or huer.get("vinculados"):
                        msg += (f" | huerfanos: revisados={huer.get('revisados', 0)} "
                                f"vinculados={huer.get('vinculados', 0)}")
                        if huer.get("errores"):
                            msg += f" errores={len(huer['errores'])}"
                    print(f"[sr-autopoll] {msg}", flush=True)
                finally:
                    _sr_poll_release_lease(msg)
        except Exception as e:
            print(f"[sr-autopoll] ciclo falló: {e}", flush=True)
        _time.sleep(interval_min * 60)


def _start_simpliroute_poll_scheduler_once():
    import threading as _th
    nombre = "simpliroute-autopoll"
    for t in _th.enumerate():
        if t.name == nombre and t.is_alive():
            return
    try:
        _th.Thread(target=_simpliroute_poll_loop, daemon=True, name=nombre).start()
    except Exception as e:
        print(f"[sr-autopoll] no se pudo arrancar: {e}", flush=True)


# NOTA: el arranque del hilo NO va aquí. Este bloque usa funciones que se
# definen más abajo en el archivo (_simpliroute_token_for_courier,
# _simpliroute_request, SIMPLIROUTE_TOKENS_ENV, ~27650). En runtime ya existen,
# pero para no depender de eso el scheduler se arranca al FINAL del archivo,
# cuando todo el módulo está cargado. Ver _start_simpliroute_poll_scheduler_once().


@app.route("/transporte/cron/simpliroute-poll", methods=["GET", "POST"])
def tr_cron_simpliroute_poll():
    """Polling de estados SimpliRoute. Invocable por Cloud Scheduler externo
    (para garantizar 24/7 aunque Cloud Run escale a 0) o a mano.

    Seguridad: mismo token que el cron de FedEx (FEDEX_CRON_TOKEN) o
    ILUS_CRON_TOKEN, por header X-Cron-Token (el query ?token= es fallback
    de compatibilidad, ver _cron_extract_token). Sin token configurado,
    solo acepta desde localhost.

    Query: ?dry=1 (no escribe) · ?limit=N
    """
    tok = _cron_extract_token()
    esperado = ((os.environ.get("ILUS_CRON_TOKEN") or "").strip()
                or (os.environ.get("FEDEX_CRON_TOKEN") or "").strip())
    if esperado:
        if tok != esperado:
            return jsonify({"error": "forbidden"}), 403
    elif request.remote_addr not in ("127.0.0.1", "::1", "localhost"):
        return jsonify({"error": "forbidden"}), 403

    try:
        limit = min(int(request.args.get("limit") or 400), 800)
    except Exception:
        limit = 400
    dry = (request.args.get("dry") or "") in ("1", "true", "yes")
    res = _simpliroute_poll_batch(limit=limit, dry=dry)
    return jsonify(res), (200 if res.get("ok") else 502)


@app.route("/transporte/webhook/simpliroute", methods=["POST"])
def tr_webhook_simpliroute_recibir():
    """Webhook de SimpliRoute (2026-08-07, Daniel: "vamos con el webhook").

    SimpliRoute nos avisa apenas un chofer hace checkout de una visita
    (evento 'visit_checkout_detailed'), en vez de esperar hasta 10 minutos
    al próximo ciclo del poller programado.

    IMPORTANTE — por qué este endpoint NO lee datos del payload para
    escribir en la base: la doc pública de SimpliRoute no publica el
    esquema exacto del payload (confirmado cruzando documentation.
    simpliroute.com, el SDK de Node y el paquete de PyPI — ninguno lo trae
    completo, ver _simpliroute_registrar_webhook). En vez de confiar campos
    que no están garantizados, este endpoint usa el payload SOLO como aviso
    de "algo cambió" y dispara el MISMO _simpliroute_poll_batch ya probado
    en producción (con todos sus parches de reference/rank/rescate de 7
    días, ver _sr_normalizar_reference), que vuelve a preguntarle a
    SimpliRoute el estado real con nuestro propio token antes de tocar
    cualquier fila. Si el payload viniera en un formato irreconocible, no
    se pierde nada: el poller programado (cada ~10 min) lo agarra igual.

    Seguridad: header X-ILUS-Webhook-Secret == SIMPLIROUTE_WEBHOOK_SECRET.
    Sin ese secreto configurado, se rechaza TODO — a diferencia de los cron
    jobs internos (que aceptan localhost sin token), este endpoint es
    alcanzable desde internet, así que no hay un "modo sin token" seguro.

    Responde 200 de inmediato (SimpliRoute reintenta 3 veces hasta 120s si
    no recibe 200) y corre el poll en un hilo aparte para no bloquear la
    respuesta.
    """
    secreto_esperado = (os.environ.get("SIMPLIROUTE_WEBHOOK_SECRET") or "").strip()
    secreto_recibido = (request.headers.get("X-ILUS-Webhook-Secret") or "").strip()
    if not secreto_esperado or secreto_recibido != secreto_esperado:
        print(f"[sr-webhook] rechazado: secreto ausente o incorrecto (ip={request.remote_addr})",
              flush=True)
        return jsonify({"error": "forbidden"}), 403

    body = request.get_json(silent=True) or {}
    pista = body.get("reference") or body.get("name") or body.get("id") or "(sin pista identificable)"
    # Log del payload crudo (truncado): con la doc incompleta, el primer
    # evento real en vivo es la única forma de confirmar el esquema real.
    print(f"[sr-webhook] evento recibido, pista={pista!r} payload={str(body)[:500]}", flush=True)

    def _correr_en_hilo():
        try:
            with app.app_context():
                if _sr_poll_acquire_lease(600):
                    msg = "ciclo interrumpido (webhook)"
                    try:
                        res = _simpliroute_poll_batch()
                        msg = (f"consultados={res.get('consultados', 0)} "
                               f"actualizados={res.get('actualizados', 0)} "
                               f"pod={res.get('pod', 0)} atascados={res.get('atascados', 0)}")
                    finally:
                        _sr_poll_release_lease(f"webhook: {msg}")
                    print(f"[sr-webhook] {msg}", flush=True)
                else:
                    # Ya hay un ciclo en vuelo (programado u otro webhook) —
                    # ese ciclo re-consulta las listas completas por fecha,
                    # así que este evento igual queda cubierto, no se pierde.
                    print("[sr-webhook] poll ya en curso, se omite (cubierto por el ciclo en vuelo)",
                          flush=True)
        except Exception as e:
            print(f"[sr-webhook] error al procesar: {e}", flush=True)

    import threading as _th
    _th.Thread(target=_correr_en_hilo, daemon=True, name="sr-webhook-trigger").start()
    return jsonify({"ok": True}), 200


@app.route("/admin/simpliroute-webhooks", methods=["GET", "POST"])
def admin_simpliroute_webhooks():
    """Panel técnico (JSON, no HTML) para dar de alta/revisar/baja el webhook
    de SimpliRoute en la cuenta de CADA courier (Felca y Milling tienen
    tokens/cuentas separadas — hay que registrar en cada una por separado).

    Uso único de configuración, no operación diaria — por eso es JSON y no
    tiene pantalla propia. Protegido por rol admin/superadmin (sesión).

    GET  → lista lo que SimpliRoute tiene registrado hoy, por courier.
    POST {"accion": "registrar"|"eliminar", "courier": "felca"|"milling"}
         → devuelve la respuesta CRUDA de la API (ver comentario en
           _simpliroute_registrar_webhook: el body exacto de alta no está
           100% documentado, así que un 400 con el error de DRF es la forma
           de corregir el nombre de campo en el próximo intento).
    """
    u = getattr(g, "user", None) or {}
    if (u.get("role") or "") not in ("admin", "superadmin"):
        return jsonify({"ok": False, "error": "Solo admin"}), 403

    secreto = (os.environ.get("SIMPLIROUTE_WEBHOOK_SECRET") or "").strip()
    if not secreto:
        return jsonify({"ok": False, "error": "Falta configurar SIMPLIROUTE_WEBHOOK_SECRET "
                                                "(Railway/Cloud Run env vars)"}), 500

    url_destino = url_for("tr_webhook_simpliroute_recibir", _external=True)

    if request.method == "GET":
        out = {}
        for courier, env_var in SIMPLIROUTE_TOKENS_ENV.items():
            tok = (os.environ.get(env_var) or "").strip()
            if not tok:
                out[courier] = {"token_configurado": False}
                continue
            out[courier] = {"token_configurado": True,
                             "respuesta": _simpliroute_listar_webhooks(tok)}
        return jsonify({"ok": True, "url_webhook": url_destino, "couriers": out})

    body = request.get_json(silent=True) or {}
    accion = (body.get("accion") or "").strip().lower()
    courier = (body.get("courier") or "").strip().lower()
    env_var = SIMPLIROUTE_TOKENS_ENV.get(courier)
    if not env_var:
        return jsonify({"ok": False, "error": f"courier desconocido: {courier!r} "
                                                f"(usar uno de: {', '.join(SIMPLIROUTE_TOKENS_ENV)})"}), 400
    tok = (os.environ.get(env_var) or "").strip()
    if not tok:
        return jsonify({"ok": False, "error": f"sin token de SimpliRoute configurado para {courier}"}), 400

    if accion == "registrar":
        r = _simpliroute_registrar_webhook(tok, url_destino, secreto)
        return jsonify({"ok": r.get("ok", False), "respuesta": r}), (200 if r.get("ok") else 502)
    if accion == "eliminar":
        r = _simpliroute_eliminar_webhook(tok)
        return jsonify({"ok": r.get("ok", False), "respuesta": r}), (200 if r.get("ok") else 502)
    return jsonify({"ok": False, "error": "accion inválida (usar 'registrar' o 'eliminar')"}), 400


@app.route("/transporte/api/items/<int:item_id>/refrescar-tracking", methods=["POST"])
@_tr_required
def tr_refrescar_tracking_item(item_id):
    """Refresca el estado FedEx de UN item desde la UI (admin → "Refrescar").

    Lee master_tracking_number (preferido) o tracking_number, llama a la
    Track API, aplica el estado venido al item (puede cambiar estado_entrega,
    genera evento append-only y log de auditoría), y devuelve el resultado para
    refrescar la fila sin recargar.
    """
    r = mysql_fetchone(
        "SELECT id, master_tracking_number, tracking_number "
        "FROM transport_manifest_items WHERE id=%s", (item_id,))
    if not r:
        return jsonify({"ok": False, "error": "item no encontrado"}), 404
    tn = (r.get("master_tracking_number") or r.get("tracking_number") or "").strip()
    if not tn:
        return jsonify({"ok": False, "error": "Este item no tiene tracking number"}), 400
    try:
        results = _fedex_track_lookup([tn])
    except Exception as e:
        return jsonify({"ok": False, "error": f"FedEx Track API: {str(e)[:200]}"}), 502
    if not results:
        return jsonify({"ok": True, "tn": tn,
                        "warning": "FedEx aún no tiene información de este envío"})
    fx = results[0]
    apply_res = _tr_apply_carrier_status(
        item_id, fx["estado_ilus"], fuente='fedex',
        payload={"fedex": {
            "status_code":  fx.get("status_code"),
            "status_label": fx.get("status_label"),
            "eta":          fx.get("eta"),
            "scans":        (fx.get("scans") or [])[:10],
        }},
        comentario=(fx.get("last_event") or fx.get("status_label") or None),
    )
    return jsonify({
        "ok":           True,
        "tn":           tn,
        "changed":      apply_res.get("changed", False),
        "estado":       apply_res.get("nuevo", fx["estado_ilus"]),
        "anterior":     apply_res.get("anterior", ""),
        "fedex_code":   fx.get("status_code"),
        "fedex_label":  fx.get("status_label"),
        "eta":          fx.get("eta"),
        "last_event":   fx.get("last_event") or "",
    })


@app.route("/transporte/api/manifiestos/<int:mid>/refrescar-tracking", methods=["POST"])
@_tr_required
def tr_refrescar_tracking_manifiesto(mid):
    """Refresca el tracking FedEx de TODOS los items vivos del manifiesto.

    Solo procesa items con master_tracking_number / tracking_number, no
    cancelados y no en estado terminal (Entregado/Devolución). Hace batch
    a la Track API (hasta 30 TN por request) y aplica los estados.
    """
    if not (FEDEX_TRACK_CLIENT_ID and FEDEX_TRACK_CLIENT_SECRET):
        return jsonify({"ok": False, "error": "FedEx Track API no configurada"}), 503
    rows = mysql_fetchall(
        "SELECT id, COALESCE(NULLIF(master_tracking_number,''), tracking_number) AS tn "
        "FROM transport_manifest_items "
        "WHERE manifest_id=%s "
        "  AND COALESCE(NULLIF(master_tracking_number,''), tracking_number) IS NOT NULL "
        "  AND COALESCE(NULLIF(master_tracking_number,''), tracking_number) <> '' "
        "  AND ship_cancelled_at IS NULL "
        "  AND estado_entrega NOT IN ('Entregado', 'Devolución') "
        "ORDER BY id", (mid,)) or []
    if not rows:
        return jsonify({"ok": True, "polled": 0, "changed": 0,
                        "msg": "No hay envíos activos para refrescar"})

    # Batch en lotes de 30 (límite FedEx).
    by_tn = {r["tn"]: r["id"] for r in rows}
    all_tns = list(by_tn.keys())
    polled = 0
    changed_count = 0
    items_log = []
    errores = []
    for i in range(0, len(all_tns), 30):
        lote = all_tns[i:i+30]
        try:
            results = _fedex_track_lookup(lote)
        except Exception as e:
            errores.append(f"Lote {i//30+1}: {str(e)[:120]}")
            continue
        polled += len(results)
        for fx in results:
            tn = fx.get("tracking_number")
            item_id = by_tn.get(tn)
            if not item_id:
                continue
            apply_res = _tr_apply_carrier_status(
                item_id, fx["estado_ilus"], fuente='fedex',
                payload={"fedex": {
                    "status_code":  fx.get("status_code"),
                    "status_label": fx.get("status_label"),
                    "eta":          fx.get("eta"),
                    "scans":        (fx.get("scans") or [])[:5],
                }},
                comentario=(fx.get("last_event") or fx.get("status_label") or None),
            )
            if apply_res.get("changed"):
                changed_count += 1
            items_log.append({
                "id":      item_id, "tn": tn,
                "changed": apply_res.get("changed", False),
                "estado":  apply_res.get("nuevo"),
                "label":   fx.get("status_label"),
            })
    _tr_log("manifest", mid, "refresh tracking masivo",
            f"polled={polled} changed={changed_count}")
    return jsonify({
        "ok":      True,
        "polled":  polled,
        "changed": changed_count,
        "items":   items_log,
        "errores": errores,
    })


# ═══════════════════════════════════════════════════════════════════════════
#  APP DEL CHOFER (FASE 2) — login RUT+PIN, captura por escaneo QR, ruta
# ═══════════════════════════════════════════════════════════════════════════

def _chofer_actual():
    """Devuelve el dict del chofer logueado, o None. Lee de sesión."""
    did = session.get("driver_id")
    if not did:
        return None
    return mysql_fetchone(
        "SELECT id, nombre, rut, telefono, patente, activo "
        "FROM transport_drivers WHERE id=%s AND activo=1",
        (did,)
    )


def _chofer_required(view):
    """Decorador: exige sesión de chofer. Redirige a /chofer/login si no hay."""
    @wraps(view)
    def wrapped(*a, **kw):
        if not session.get("driver_id"):
            if "/api/" in request.path or request.is_json:
                return jsonify({"error": "no_auth", "login": url_for("chofer_login")}), 401
            return redirect(url_for("chofer_login"))
        drv = _chofer_actual()
        if not drv:
            session.pop("driver_id", None)
            return redirect(url_for("chofer_login"))
        g.chofer = drv
        return view(*a, **kw)
    return wrapped


@app.route("/chofer/login", methods=["GET", "POST"])
@rate_limited("chofer_login", max_attempts=12, window_seconds=600)
def chofer_login():
    """Login del chofer con RUT + PIN. Sesión propia (driver_id)."""
    if request.method == "GET":
        if session.get("driver_id"):
            return redirect(url_for("chofer_home"))
        return render_template("chofer/login.html", error=None)
    rut_raw = (request.form.get("rut") or "").strip()
    pin     = (request.form.get("pin") or "").strip()
    rut_norm = normalizar_rut(rut_raw)
    if not rut_norm or not pin:
        return render_template("chofer/login.html",
                               error="Ingresa tu RUT y tu PIN."), 400
    drv = mysql_fetchone(
        "SELECT id, nombre, pin_hash, activo FROM transport_drivers WHERE rut=%s",
        (rut_norm,)
    )
    if not drv or not drv.get("activo"):
        return render_template("chofer/login.html",
                               error="RUT no registrado o inactivo. "
                                     "Contacta a tu coordinador."), 401
    if not check_password_hash(drv.get("pin_hash") or "", pin):
        return render_template("chofer/login.html",
                               error="PIN incorrecto. Intenta de nuevo."), 401
    session["driver_id"] = drv["id"]
    session.permanent = True
    try:
        mysql_execute("UPDATE transport_drivers SET last_login_at=NOW() WHERE id=%s",
                      (drv["id"],))
    except Exception:
        pass
    return redirect(url_for("chofer_home"))


@app.route("/chofer/logout")
def chofer_logout():
    session.pop("driver_id", None)
    return redirect(url_for("chofer_login"))


