@app.route("/transporte/manifiestos/<int:mid>/firma/enviar", methods=["POST"])
@_tr_required
def tr_manifiesto_firma_enviar(mid):
    """Envía el PDF del manifiesto de firma por correo (marca ILUS
    genérica — Regla #11), reusando el mismo render + PDF que
    tr_manifiesto_firma_pdf (vía _tr_manifiesto_firma_bytes, sin
    duplicar HTML). 2026-07-26, pedido de Daniel: botón 'Enviar por
    correo' dentro del modal del manifiesto de firma. Valida
    destinatarios con el MISMO patrón que lc_enviar (logistica_cotizaciones.py)."""
    if not comm_is_enabled("email"):
        return jsonify({"ok": False, "error": "El envío de correos está desactivado globalmente."})

    body = request.get_json(silent=True) or {}
    destinatarios_in = body.get("destinatarios") or []
    if not isinstance(destinatarios_in, list) or not destinatarios_in:
        return jsonify({"ok": False, "error": "Agrega al menos un destinatario."}), 400

    buenos, malos, vistos = [], [], set()
    for e in destinatarios_in[:15]:
        e = (str(e) or "").strip()
        if not e:
            continue
        if not _EMAIL_RE.match(e):
            malos.append(e)
        elif e.lower() not in vistos:
            vistos.add(e.lower())
            buenos.append(e)
    if malos:
        return jsonify({"ok": False, "error": "Hay correos inválidos: " + ", ".join(malos[:5])}), 400
    if not buenos:
        return jsonify({"ok": False, "error": "No hay destinatarios válidos."}), 400

    try:
        manifiesto, items, pdf_bytes, fname = _tr_manifiesto_firma_bytes(mid)
    except ValueError as e:
        msg = str(e)
        return jsonify({"ok": False, "error": msg}), (404 if "no encontrado" in msg else 400)
    except PDFEngineUnavailable:
        return jsonify({"ok": False, "error": "El envío no está disponible en este entorno (motor PDF)."}), 503
    except Exception as e:
        print(f"[tr_manifiesto_firma_enviar] pdf mid={mid}: {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo generar el PDF para adjuntar."}), 503

    import html as _html_esc
    correlativo = manifiesto.get("correlativo") or mid
    n_docs = len(items)
    mensaje = (body.get("mensaje") or "").strip()
    subject = _brand_subject(
        f"Manifiesto de entrega N° {correlativo} — {n_docs} documento(s)")

    cuerpo = (
        f"<p>Estimados,</p>"
        f"<p>Adjuntamos el manifiesto de entrega <strong>N° {_html_esc.escape(str(correlativo))}</strong>, "
        f"con <strong>{n_docs} documento{'s' if n_docs != 1 else ''}</strong> de despacho.</p>"
        + (f"<p>{_html_esc.escape(mensaje)}</p>" if mensaje else "")
        + "<p>Quedamos atentos a sus comentarios.</p>"
    )
    try:
        html_body = _ilus_email_master({
            "subject": subject,
            "title": f"Manifiesto de entrega N° {correlativo}",
            "subtitle": f"{n_docs} documento(s)",
            "message": cuerpo,
        })
    except Exception as e:
        print(f"[tr_manifiesto_firma_enviar] _ilus_email_master falló mid={mid}: {e}", flush=True)
        html_body = cuerpo

    adj = [(fname, pdf_bytes, "application/pdf")]
    enviados, fallidos = [], []
    for dest in buenos:
        try:
            ok = _send_ilus_email(dest, subject, html_body, modulo="transporte", attachments=adj)
        except Exception as e:
            print(f"[tr_manifiesto_firma_enviar] enviar {dest}: {e}", flush=True)
            ok = False
        (enviados if ok else fallidos).append(dest)

    user = current_username() or "sistema"
    _tr_log("manifest", mid, "documento firma correo",
            f"enviados={enviados} fallidos={fallidos}")

    if not enviados:
        return jsonify({"ok": False, "error": "No se pudo enviar a ningún destinatario."}), 502
    return jsonify({"ok": True, "enviados": enviados, "fallidos": fallidos})


def _tr_manifiesto_retiro_get(mid):
    """Retorna el registro de retiro (chofer/RUT/patente/firma) de un
    manifiesto, o None si aún no se ha capturado."""
    try:
        return mysql_fetchone(
            "SELECT * FROM transport_manifest_retiro WHERE manifest_id=%s", (mid,))
    except Exception:
        return None


def _tr_find_courier_row(courier_nombre):
    """Encuentra la ficha del courier (transport_couriers) a partir del texto
    libre guardado en transport_manifests.courier. Primero intenta match
    exacto (normalizado), luego un LIKE tolerante en ambas direcciones (mismo
    criterio laxo usado para los alias Felca/Milling/Melling en la
    integración SimpliRoute), porque el texto libre trae inconsistencias de
    ortografía conocidas. Devuelve la fila completa (id, email, etc.) o None.
    Factorizado 2026-07-26 para reusar el mismo match en _tr_courier_email y
    en la resolución de courier_id para el roster de choferes — NO duplicar."""
    if not courier_nombre:
        return None
    nombre = courier_nombre.strip()
    if not nombre:
        return None
    row = mysql_fetchone(
        "SELECT * FROM transport_couriers WHERE LOWER(TRIM(nombre))=LOWER(TRIM(%s)) LIMIT 1",
        (nombre,)
    )
    if row:
        return row
    row = mysql_fetchone(
        "SELECT * FROM transport_couriers WHERE LOWER(nombre) LIKE %s LIMIT 1",
        (f"%{nombre.lower()}%",)
    )
    if row:
        return row
    row = mysql_fetchone(
        "SELECT * FROM transport_couriers WHERE %s LIKE CONCAT('%%', LOWER(nombre), '%%') LIMIT 1",
        (nombre.lower(),)
    )
    if row:
        return row
    return None


def _tr_courier_email(courier_nombre):
    """Busca el correo declarado en la ficha del courier a partir del texto
    libre guardado en transport_manifests.courier. Ver _tr_find_courier_row."""
    row = _tr_find_courier_row(courier_nombre)
    if row and row.get("email"):
        return row["email"]
    return None


def _tr_ensure_manifest_retiro_token(mid):
    """Garantiza que el manifiesto tenga su token público de firma remota
    (lo crea lazy si falta). Vive en transport_manifests.retiro_token
    (URL-safe, hasta 40 chars). Mismo patrón EXACTO que
    _tr_ensure_public_token (transport_commitments), adaptado a manifiestos —
    NO se reusa la función de commitments directo porque apunta a otra
    tabla/columna. Devuelve el token (o None si falló crearlo)."""
    try:
        r = mysql_fetchone(
            "SELECT retiro_token FROM transport_manifests WHERE id=%s", (mid,))
        if not r:
            return None
        tok = (r.get("retiro_token") or "").strip()
        if tok:
            return tok
        for _ in range(3):
            new_tok = secrets.token_urlsafe(30)[:40]
            try:
                mysql_execute(
                    "UPDATE transport_manifests SET retiro_token=%s WHERE id=%s",
                    (new_tok, mid)
                )
                return new_tok
            except Exception:
                continue
        return None
    except Exception as _tok_err:
        print(f"[tr_retiro_token] no se pudo generar token mid={mid}: {_tok_err}", flush=True)
        return None


def _tr_firma_cipher():
    """Cifrado autenticado (Fernet) para la firma canvas del retiro de
    transporte. Deriva la clave desde FLASK_SECRET_KEY (no agrega secretos
    nuevos al repo ni a la BD) — mismo patrón que otros HMAC de firma en la
    app (ej. _ot_firma_key). Devuelve None si el paquete `cryptography` no
    está instalado (fallback: se guarda sin cifrar, mejor que perder la
    firma por completo)."""
    try:
        from cryptography.fernet import Fernet as _Fernet
    except Exception:
        return None
    secret = app.secret_key or "ilus-transport-firma-fallback"
    secret_b = secret.encode("utf-8") if isinstance(secret, str) else secret
    key = base64.urlsafe_b64encode(hashlib.sha256(b"ilus-transport-firma-v1:" + secret_b).digest())
    try:
        return _Fernet(key)
    except Exception:
        return None


_TR_FIRMA_ENC_PREFIX = "fernet:"


def _tr_firma_encrypt_data_url(data_url):
    """Cifra el data URL (PNG base64) de la firma canvas antes de guardarlo
    en transport_manifest_retiro.firma_canvas. Si no hay cipher disponible,
    devuelve el data URL tal cual (mejor guardarlo plano que perderlo)."""
    if not data_url or not str(data_url).startswith("data:image/"):
        return data_url or ""
    cipher = _tr_firma_cipher()
    if not cipher:
        return data_url
    token = cipher.encrypt(data_url.encode("utf-8")).decode("ascii")
    return _TR_FIRMA_ENC_PREFIX + token


def _tr_firma_decrypt_if_needed(value):
    """Inverso de _tr_firma_encrypt_data_url — usado si en algún momento se
    necesita mostrar la firma real (ej. en el PDF o en un panel de
    auditoría). Devuelve "" si no se pudo descifrar."""
    value = value or ""
    if not value.startswith(_TR_FIRMA_ENC_PREFIX):
        return value
    cipher = _tr_firma_cipher()
    if not cipher:
        return ""
    try:
        token = value[len(_TR_FIRMA_ENC_PREFIX):].encode("ascii")
        return cipher.decrypt(token).decode("utf-8")
    except Exception:
        return ""


def _tr_manifiesto_retiro_guardar(mid, manifiesto, chofer_nombre, chofer_rut,
                                   chofer_telefono, patente, firma_nombre,
                                   ip_origen, registrado_por, firma_canvas=None):
    """Guarda (o actualiza) el registro de retiro de bodega de un manifiesto
    y dispara el envío automático best-effort del PDF firmado al correo del
    courier. Factorizado 2026-07-26 para que lo use TANTO el operador desde
    el modal interno (tr_manifiesto_retiro) COMO el chofer desde el link
    público sin login (tr_firma_retiro_publico) — misma lógica, no duplicar.

    firma_canvas (opcional, 2026-07-26): PNG data URL de la firma dibujada a
    mano en el link público. Se guarda cifrada (Fernet) + su hash SHA256 de
    auditoría, en transport_manifest_retiro.firma_canvas/firma_hash. No
    reemplaza firma_nombre (el nombre tecleado sigue siendo obligatorio).
    Devuelve (ok: bool, resp_dict, http_status)."""
    firma_canvas_enc = None
    firma_hash = None
    if firma_canvas and str(firma_canvas).startswith("data:image/"):
        firma_hash = hashlib.sha256(firma_canvas.encode("utf-8")).hexdigest()
        firma_canvas_enc = _tr_firma_encrypt_data_url(firma_canvas)
    try:
        conn = get_mysql()
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO transport_manifest_retiro "
                    "(manifest_id, chofer_nombre, chofer_rut, chofer_telefono, patente, "
                    " firma_nombre, firma_canvas, firma_hash, ip_origen, registrado_por) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) "
                    "ON DUPLICATE KEY UPDATE "
                    "chofer_nombre=VALUES(chofer_nombre), chofer_rut=VALUES(chofer_rut), "
                    "chofer_telefono=VALUES(chofer_telefono), patente=VALUES(patente), "
                    "firma_nombre=VALUES(firma_nombre), "
                    "firma_canvas=COALESCE(VALUES(firma_canvas), firma_canvas), "
                    "firma_hash=COALESCE(VALUES(firma_hash), firma_hash), "
                    "ip_origen=VALUES(ip_origen), "
                    "registrado_por=VALUES(registrado_por)",
                    (mid, chofer_nombre, chofer_rut, chofer_telefono, patente,
                     firma_nombre, firma_canvas_enc, firma_hash,
                     (ip_origen or "")[:60], registrado_por)
                )
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        print(f"[tr_manifiesto_retiro_guardar] guardar mid={mid}: {type(e).__name__}: {e}", flush=True)
        return False, {"ok": False, "error": "No se pudo guardar el registro de retiro."}, 500

    _tr_log("manifest", mid, "retiro registrado",
            f"chofer={chofer_nombre} rut={chofer_rut} patente={patente} por={registrado_por or 'chofer (link público)'}")

    # FIX 2026-07-27 (Daniel: "una vez firmado... que cambie todo como
    # entregado al transportista"): la firma de retiro (interna o por link
    # público) ES la confirmación real de que el courier se llevó la
    # mercadería -- debe disparar el mismo cambio de estado que ya usan
    # FedEx/SimpliRoute (_tr_apply_carrier_status, el único choke-point,
    # no se duplica) para TODOS los items del manifiesto que sigan en
    # 'En preparación'. Items que ya avanzaron más (en ruta/entregado) no
    # se tocan -- nunca retroceder un estado.
    try:
        _items_para_avanzar = mysql_fetchall(
            "SELECT id FROM transport_manifest_items "
            "WHERE manifest_id=%s AND estado_entrega='En preparación'",
            (mid,)
        ) or []
        for _it in _items_para_avanzar:
            _tr_apply_carrier_status(
                _it["id"], "Entregado a transporte", fuente="sistema",
                comentario=f"Retiro confirmado y firmado por {chofer_nombre}",
                notify_cliente=True,
            )
    except Exception as _e_avance:
        print(f"[tr_manifiesto_retiro_guardar] avance de estado mid={mid}: {_e_avance}", flush=True)

    enviado_a = None
    aviso = None
    try:
        email = _tr_courier_email(manifiesto.get("courier"))
        if email:
            correlativo = manifiesto.get("correlativo") or mid
            _, items, pdf_bytes, fname = _tr_manifiesto_firma_bytes(mid)
            n_docs = len(items)
            subject = _brand_subject(
                f"Manifiesto de retiro N° {correlativo} firmado — {n_docs} factura(s)")
            import html as _html_esc
            cuerpo = (
                f"<p>Estimados,</p>"
                f"<p>Se registró el retiro de bodega del manifiesto "
                f"<strong>N° {_html_esc.escape(str(correlativo))}</strong> "
                f"({n_docs} factura{'s' if n_docs != 1 else ''}).</p>"
                f"<p>Retirado por <strong>{_html_esc.escape(chofer_nombre)}</strong>, "
                f"RUT {_html_esc.escape(chofer_rut)}, patente {_html_esc.escape(patente)}.</p>"
                f"<p>Adjuntamos el manifiesto firmado.</p>"
            )
            try:
                html_body = _ilus_email_master({
                    "subject": subject,
                    "title": f"Manifiesto de retiro N° {correlativo}",
                    "subtitle": f"{n_docs} factura(s)",
                    "message": cuerpo,
                })
            except Exception:
                html_body = cuerpo
            ok = _send_ilus_email(email, subject, html_body, modulo="transporte",
                                   attachments=[(fname, pdf_bytes, "application/pdf")])
            if ok:
                enviado_a = email
                _tr_log("manifest", mid, "retiro correo enviado", f"a={email}")
            else:
                aviso = f"No se pudo enviar el correo a {email}."
        else:
            aviso = "El registro quedó guardado, pero no hay correo configurado en la ficha del courier para enviarlo automáticamente."
    except Exception as e:
        print(f"[tr_manifiesto_retiro_guardar] correo mid={mid}: {type(e).__name__}: {e}", flush=True)
        aviso = "El registro quedó guardado, pero el envío automático de correo falló."

    resp = {"ok": True, "enviado_a": enviado_a}
    if aviso:
        resp["aviso"] = aviso
    return True, resp, 200


@app.route("/transporte/manifiestos/<int:mid>/retiro", methods=["GET", "POST"])
@_tr_required
def tr_manifiesto_retiro(mid):
    """Captura de retiro de bodega (2026-07-26, Daniel): quién se llevó la
    mercadería (chofer, RUT, teléfono, patente) + firma digital simple
    (nombre tecleado, NO canvas). Al guardar, intenta mandar automáticamente
    el PDF del manifiesto de firma al correo declarado en la ficha del
    courier (transport_couriers.email). El correo es best-effort: si falla
    o no hay email configurado, el registro igual queda guardado.

    GET también devuelve courier_id (para el selector de choferes guardados
    del roster, ver /transporte/couriers/<cid>/choferes) y link_firma (link
    público de firma remota para el chofer, generado lazy)."""
    manifiesto = mysql_fetchone("SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not manifiesto:
        return jsonify({"ok": False, "error": "Manifiesto no encontrado"}), 404

    if request.method == "GET":
        retiro = _tr_manifiesto_retiro_get(mid)
        courier_row = _tr_find_courier_row(manifiesto.get("courier"))
        tok = _tr_ensure_manifest_retiro_token(mid)
        link_firma = (_public_base_url() + "/firma-retiro/" + tok) if tok else None
        # FIX 2026-07-27 (Daniel: "comparativa con el camión, para restringir
        # el manifiesto según su límite de peso/volumen"): se manda el total
        # real del manifiesto para que el frontend compare contra la
        # capacidad del chofer/camión elegido (peso_max_kg/volumen_max_m3 en
        # su perfil del roster) antes de dejar confirmar el retiro.
        _mi_items = _tr_manifiesto_items_export(mid) or []
        peso_total_kg = round(sum(_peso_a_declarar(it) for it in _mi_items), 2)
        volumen_total_m3 = round(sum(float(it.get("volumen_m3") or 0) for it in _mi_items), 3)
        return jsonify({
            "ok": True,
            "retiro": retiro,
            "courier_id": courier_row["id"] if courier_row else None,
            "link_firma": link_firma,
            "peso_total_kg": peso_total_kg,
            "volumen_total_m3": volumen_total_m3,
        })

    body = request.get_json(silent=True) or {}
    chofer_nombre   = (body.get("chofer_nombre") or "").strip()
    chofer_rut      = (body.get("chofer_rut") or "").strip()
    chofer_telefono = (body.get("chofer_telefono") or "").strip()
    patente         = (body.get("patente") or "").strip()
    firma_nombre    = (body.get("firma_nombre") or "").strip()

    faltantes = []
    if not chofer_nombre: faltantes.append("nombre del chofer")
    if not chofer_rut: faltantes.append("RUT del chofer")
    if not patente: faltantes.append("patente")
    if not firma_nombre: faltantes.append("firma (nombre de confirmación)")
    if faltantes:
        return jsonify({"ok": False,
                         "error": "Faltan datos obligatorios: " + ", ".join(faltantes)}), 400

    ok, resp, status = _tr_manifiesto_retiro_guardar(
        mid, manifiesto, chofer_nombre, chofer_rut, chofer_telefono, patente,
        firma_nombre, request.remote_addr, current_username())
    return jsonify(resp), status


_RETIRO_TOKEN_RE = re.compile(r"^[A-Za-z0-9_\-]+$")


@app.route("/firma-retiro/<token>", methods=["GET"])
def tr_firma_retiro_publico(token):
    """Página pública SIN LOGIN para que el chofer firme el retiro desde su
    celular (link generado en el modal interno y enviado por SMS/WhatsApp
    fuera de la app — ver GET /transporte/manifiestos/<mid>/retiro). Mismo
    patrón de validación de token que tr_public_tracking (/t/<token>)."""
    if not token or len(token) < 16 or len(token) > 80 or not _RETIRO_TOKEN_RE.match(token):
        abort(404)
    manifiesto = mysql_fetchone(
        "SELECT id, correlativo, courier FROM transport_manifests WHERE retiro_token=%s", (token,))
    if not manifiesto:
        abort(404)
    mid = manifiesto["id"]
    resumen = mysql_fetchone(
        "SELECT COUNT(*) AS n_docs, COALESCE(SUM(COALESCE(c.n_bultos,1)),0) AS n_bultos "
        "FROM transport_manifest_items mi "
        "JOIN transport_commitments c ON c.id = mi.commitment_id "
        "WHERE mi.manifest_id=%s", (mid,))
    n_docs = (resumen or {}).get("n_docs") or 0
    n_bultos = (resumen or {}).get("n_bultos") or 0
    courier_row = _tr_find_courier_row(manifiesto.get("courier"))
    courier_id = courier_row["id"] if courier_row else None
    retiro_existente = _tr_manifiesto_retiro_get(mid)
    choferes = []
    if courier_id:
        choferes = mysql_fetchall(
            "SELECT id, nombre, rut, telefono, patente FROM transport_drivers "
            "WHERE courier_id=%s AND activo=1 ORDER BY nombre", (courier_id,)
        ) or []
    return render_template(
        "transporte/firma_retiro_publico.html",
        token=token,
        manifiesto=manifiesto,
        n_docs=n_docs,
        n_bultos=n_bultos,
        courier_id=courier_id,
        choferes=choferes,
        retiro=retiro_existente,
    )


@app.route("/firma-retiro/<token>", methods=["POST"])
def tr_firma_retiro_publico_guardar(token):
    """Guarda el retiro capturado por el chofer desde el link público. Misma
    validación de token + misma función de guardado que el modal interno
    (_tr_manifiesto_retiro_guardar) — NO se duplica la lógica."""
    if not token or len(token) < 16 or len(token) > 80 or not _RETIRO_TOKEN_RE.match(token):
        return jsonify({"ok": False, "error": "Link inválido o expirado."}), 404
    manifiesto = mysql_fetchone(
        "SELECT * FROM transport_manifests WHERE retiro_token=%s", (token,))
    if not manifiesto:
        return jsonify({"ok": False, "error": "Link inválido o expirado."}), 404
    mid = manifiesto["id"]

    body = request.get_json(silent=True) or {}
    chofer_nombre   = (body.get("chofer_nombre") or "").strip()
    chofer_rut      = (body.get("chofer_rut") or "").strip()
    chofer_telefono = (body.get("chofer_telefono") or "").strip()
    patente         = (body.get("patente") or "").strip()
    firma_nombre    = (body.get("firma_nombre") or "").strip()
    # Firma real dibujada a mano (canvas), 2026-07-26 — obligatoria SOLO en
    # el link público (el modal interno de escritorio sigue sin canvas).
    firma_canvas    = (body.get("firma_canvas") or "").strip()

    faltantes = []
    if not chofer_nombre: faltantes.append("nombre del chofer")
    if not chofer_rut: faltantes.append("RUT del chofer")
    if not patente: faltantes.append("patente")
    if not firma_nombre: faltantes.append("firma (nombre de confirmación)")
    if not firma_canvas or not firma_canvas.startswith("data:image/"):
        faltantes.append("firma dibujada")
    if faltantes:
        return jsonify({"ok": False,
                         "error": "Faltan datos obligatorios: " + ", ".join(faltantes)}), 400

    ok, resp, status = _tr_manifiesto_retiro_guardar(
        mid, manifiesto, chofer_nombre, chofer_rut, chofer_telefono, patente,
        firma_nombre, request.remote_addr, None, firma_canvas=firma_canvas)

    # Best-effort: si el chofer no estaba en el roster del courier, se
    # ofrece agregarlo desde el propio formulario público (ver JS del
    # template) — aquí solo se guarda si el frontend pide guardar_chofer=1.
    if ok and body.get("guardar_chofer"):
        courier_row = _tr_find_courier_row(manifiesto.get("courier"))
        if courier_row:
            try:
                _tr_courier_chofer_upsert(courier_row["id"], chofer_nombre, chofer_rut,
                                           chofer_telefono, patente)
            except Exception as e:
                print(f"[tr_firma_retiro_publico_guardar] roster mid={mid}: {e}", flush=True)

    return jsonify(resp), status


# ══════════════════════════════════════════════════════════════════════════
#  SIMPLIROUTE — integración por API (Daniel 2026-07-22)
#  Sube las facturas de un manifiesto como "visitas" a SimpliRoute, para que
#  el transportista (Felca / Milling) ya las tenga cargadas y solo asigne la
#  ruta — antes tenía que subir el Excel a mano.
#  Contrato y builder de payloads: simpliroute_client.py (módulo puro).
# ══════════════════════════════════════════════════════════════════════════

# Cada transportista tiene su PROPIA cuenta de SimpliRoute → un token por
# courier (verificado 2026-07-22: Milling id 371237, Felca id 491482 son
# cuentas distintas). REGLA #4: nunca hardcodear — se leen de env vars, con
# los nombres que Daniel ya configuró en Cloud Run.
SIMPLIROUTE_TOKENS_ENV = {
    "milling": "SIMPLIROUTE_API_TOKEN_MILLING",
    # FIX 2026-07-27 (Daniel: "no veo las acciones de milling"): hay
    # manifiestos con el courier guardado como "Transportes Melling" (alias
    # legacy mal escrito, ver ~línea 2670). "milling" NO es substring de
    # "melling" (letras distintas en la 2ª posición), así que el match
    # fallaba en silencio y TODAS las acciones de SimpliRoute (subir, ver
    # seguimiento, cancelar, reprogramar, reenviar) quedaban deshabilitadas
    # para esos manifiestos. Se agrega el alias con el MISMO token.
    "melling": "SIMPLIROUTE_API_TOKEN_MILLING",
    "felca":   "SIMPLIROUTE_API_TOKEN_RAFA",   # la cuenta de Felca es de Rafael
}


def _simpliroute_token_for_courier(courier_nombre):
    """Token de SimpliRoute del courier, o None si ese courier no integra.

    Match por SUBSTRING en minúsculas para tolerar las variantes del nombre
    ('Transportes Milling', 'Milling', 'transportes felca'…), igual criterio
    que la auto-detección de formato del export Excel.
    """
    nom = (courier_nombre or "").strip().lower()
    if not nom:
        return None
    for clave, env_var in SIMPLIROUTE_TOKENS_ENV.items():
        if clave in nom:
            return (os.environ.get(env_var) or "").strip() or None
    return None


def _simpliroute_courier_integra(courier_nombre):
    """¿Este courier trabaja con SimpliRoute? (independiente de si hay token)"""
    nom = (courier_nombre or "").strip().lower()
    return any(clave in nom for clave in SIMPLIROUTE_TOKENS_ENV)


def _simpliroute_request(method, path, token, *, payload=None, timeout=30):
    """Llamada HTTP a SimpliRoute. NUNCA lanza: siempre devuelve dict con `ok`.

    Mismo contrato defensivo que _fedex_create_shipment: el caller nunca tiene
    que envolver esto en try/except.
    """
    import requests as _req
    import simpliroute_client as _src

    if not token:
        return {"ok": False, "error": "Falta el token de SimpliRoute para este courier.",
                "status": 0}
    url = _src.BASE_URL + path
    headers = {"Authorization": f"Token {token}", "Content-Type": "application/json"}
    try:
        resp = _req.request(method, url, headers=headers, json=payload, timeout=timeout)
    except Exception as e:
        return {"ok": False, "status": 0,
                "error": f"No se pudo conectar con SimpliRoute: {type(e).__name__}"}
    try:
        body = resp.json()
    except Exception:
        body = resp.text
    if resp.status_code >= 400:
        return {"ok": False, "status": resp.status_code,
                "error": _src.extract_error_message(resp.status_code, body),
                "raw": body}
    return {"ok": True, "status": resp.status_code, "data": body}


# ── Webhooks de SimpliRoute (2026-08-07, Daniel: "vamos con el webhook") ──
# Alta/baja/listado del webhook en la CUENTA de cada courier (Felca, Milling
# tienen tokens/cuentas separadas -> hay que registrar en cada una).
#
# El endpoint POST /v1/addons/webhooks/ y el body del DELETE
# ({"webhook": "<evento>"}) están confirmados contra documentation.simpliroute.com
# (2026-08-07). El body EXACTO del POST de alta NO está publicado ahí -- se
# prueba con los nombres de campo más consistentes con el resto de la API
# (mismo campo "webhook" que usa el DELETE) y, si SimpliRoute lo rechaza,
# devuelve el error de DRF con los nombres de campo reales: por eso
# _simpliroute_registrar_webhook() devuelve la respuesta CRUDA de la API sin
# interpretarla, para poder corregir en un intento si el primero falla en
# vez de asumir éxito a ciegas.
SIMPLIROUTE_WEBHOOK_EVENTO = "visit_checkout_detailed"


def _simpliroute_listar_webhooks(token):
    return _simpliroute_request("GET", "/v1/addons/webhooks/", token, timeout=20)


def _simpliroute_registrar_webhook(token, url_destino, secreto, evento=SIMPLIROUTE_WEBHOOK_EVENTO):
    payload = {
        "webhook": evento,
        "url": url_destino,
        "headers": {"X-ILUS-Webhook-Secret": secreto},
    }
    return _simpliroute_request("POST", "/v1/addons/webhooks/", token, payload=payload, timeout=20)


def _simpliroute_eliminar_webhook(token, evento=SIMPLIROUTE_WEBHOOK_EVENTO):
    return _simpliroute_request("DELETE", "/v1/addons/webhooks/", token, payload={"webhook": evento}, timeout=20)


# ══════════════════════════════════════════════════════════════════════
#  SHIPIT (2026-08-04) — agregador de couriers, pedido del área comercial
#  vía Daniel: sumar Shipit ADEMÁS de FedEx/Felca/Milling/Clickex, nunca en
#  reemplazo (Regla #4.2). Fase 1 del plan: solo cotizar tarifa (POST
#  /v/rates). Ficha del courier: UNA sola entrada "Shipit" en
#  transport_couriers (no una por Chilexpress/Starken/etc.) — pero cada
#  cotización expone el desglose real de cuánto cobra cada operador por
#  dentro (Daniel: "me interesa separar las cosas y evidenciar... cuánto
#  vale cada servicio"), tal cual lo entrega la API (un precio por courier
#  en el array 'prices').
#
#  Credenciales: GitHub Secrets → env.yaml → Cloud Run (Regla #4), ya
#  inyectadas en deploy.yml. Auth por 2 headers, NO por la contraseña del
#  panel (esa solo sirve para generar el token en Configuración → API).
# ══════════════════════════════════════════════════════════════════════
SHIPIT_API_TOKEN = os.environ.get("SHIPIT_API_TOKEN", "").strip()
SHIPIT_API_EMAIL = os.environ.get("SHIPIT_API_EMAIL", "").strip()


def _shipit_request(method, path, *, payload=None, timeout=20):
    """Llamada HTTP a Shipit. NUNCA lanza: siempre devuelve dict con `ok`.

    Mismo contrato defensivo que _simpliroute_request/_fedex_create_shipment
    — el caller nunca tiene que envolver esto en try/except.
    """
    import requests as _req
    import shipit_client as _shc

    if not (SHIPIT_API_TOKEN and SHIPIT_API_EMAIL):
        return {"ok": False, "status": 0,
                "error": "Shipit no está configurado (falta SHIPIT_API_TOKEN/SHIPIT_API_EMAIL)."}
    url = _shc.BASE_URL + path
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/vnd.shipit.v4",
        "X-Shipit-Email": SHIPIT_API_EMAIL,
        "X-Shipit-Access-Token": SHIPIT_API_TOKEN,
    }
    try:
        resp = _req.request(method, url, headers=headers, json=payload, timeout=timeout)
    except Exception as e:
        return {"ok": False, "status": 0,
                "error": f"No se pudo conectar con Shipit: {type(e).__name__}"}
    try:
        body = resp.json()
    except Exception:
        body = resp.text
    if resp.status_code >= 400:
        return {"ok": False, "status": resp.status_code,
                "error": _shc.extract_error_message(resp.status_code, body),
                "raw": body}
    return {"ok": True, "status": resp.status_code, "data": body}


def _ensure_shipit_comunas_table():
    """Caché local de GET /v/communes -- tabla NUEVA, se crea SIEMPRE, incluso
    con ILUS_SKIP_MIGRATIONS=1 (mismo gotcha que _ensure_transport_zz_saldo_table:
    init_transporte_tables() no corre en producción).

    Por qué existe: POST /v/rates exige origin_id/destiny_id NUMÉRICOS propios
    de Shipit -- no los códigos de comuna del ERP. Cachear evita golpear
    /v/communes (300+ filas) en cada cotización.
    """
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS shipit_comunas (
                    id            INT PRIMARY KEY,
                    nombre        VARCHAR(120) NOT NULL,
                    region_id     INT,
                    is_available  TINYINT(1) DEFAULT 0,
                    updated_at    DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    INDEX idx_nombre (nombre)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
            """)
        conn.commit()
    except Exception as e:
        print(f"[shipit] no se pudo crear shipit_comunas: {e}", flush=True)
    finally:
        conn.close()


def _ensure_shipit_courier():
    """Siembra la ficha "Shipit" en transport_couriers + su tope de peso.

    SIEMPRE corre en boot (mismo motivo que arriba: init_transporte_tables()
    no corre en producción). Idempotente: no duplica la fila si ya existe, y
    NO pisa peso_max_bulto/peso_max_guia si alguien ya los editó a mano
    (columnas != 0) -- solo los fija la primera vez.

    peso_max_bulto=15: límite operativo que Daniel confirmó usar 2026-08-04
    (Centro de Ayuda Shipit, retiro con flota propia "héroe"), sin esperar
    confirmación del ejecutivo -- acepta que equipos más pesados (ej. barras
    de 20 kg) queden fuera de Shipit y se coticen por otro courier. Esta
    columna es INFORMATIVA para la ficha; el bloqueo real de la cotización
    lo hace shipit_client.verificar_restricciones().
    """
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM transport_couriers WHERE LOWER(nombre)='shipit'")
            if not cur.fetchone():
                cur.execute(
                    "INSERT INTO transport_couriers (nombre, tipo, activo) VALUES (%s, %s, 1)",
                    ("Shipit", "nacional")
                )
            cur.execute(
                "UPDATE transport_couriers SET peso_max_bulto=15, peso_max_guia=15 "
                "WHERE LOWER(nombre)='shipit' AND peso_max_bulto=0 AND peso_max_guia=0"
            )
        conn.commit()
    except Exception as e:
        print(f"[shipit] no se pudo sembrar la ficha del courier: {e}", flush=True)
    finally:
        conn.close()


def _shipit_sync_comunas():
    """Trae GET /v/communes y guarda/actualiza shipit_comunas (UPSERT por id).

    READ-ONLY sobre Shipit (GET). Nunca lanza -- devuelve
    {ok, n, error}. Pensado para correr manual desde un endpoint de
    diagnóstico admin (la lista de comunas cambia poco, no necesita cron).
    """
    import shipit_client as _shc
    r = _shipit_request("GET", _shc.EP_COMMUNES)
    if not r.get("ok"):
        return {"ok": False, "n": 0, "error": r.get("error")}
    data = r.get("data")
    if not isinstance(data, list):
        return {"ok": False, "n": 0,
                "error": "Respuesta inesperada de Shipit (se esperaba una lista de comunas)."}
    conn = get_mysql()
    n = 0
    try:
        with conn.cursor() as cur:
            for c in data:
                if not isinstance(c, dict) or not c.get("id"):
                    continue
                cur.execute(
                    "INSERT INTO shipit_comunas (id, nombre, region_id, is_available) "
                    "VALUES (%s, %s, %s, %s) "
                    "ON DUPLICATE KEY UPDATE nombre=VALUES(nombre), "
                    "region_id=VALUES(region_id), is_available=VALUES(is_available)",
                    (c.get("id"), (c.get("name") or "").strip(), c.get("region_id"),
                     1 if c.get("is_available") else 0)
                )
                n += 1
        conn.commit()
    except Exception as e:
        return {"ok": False, "n": n, "error": f"Error guardando comunas: {e}"}
    return {"ok": True, "n": n, "error": None}


def _shipit_commune_id(nombre_comuna):
    """commune_id de Shipit para una comuna (del ERP o de la bodega ILUS).

    Lee de la caché local shipit_comunas (poblada por _shipit_sync_comunas).
    Devuelve (id, is_available) -- (None, False) si no hay caché o no hay
    match. Nunca lanza.
    """
    import shipit_client as _shc
    try:
        rows = mysql_fetchall(
            "SELECT id, nombre, is_available FROM shipit_comunas "
            "WHERE LOWER(nombre) LIKE %s",
            (f"%{_shc.normalizar_comuna(nombre_comuna).lower()}%",)
        ) or []
    except Exception as e:
        print(f"[shipit] error leyendo shipit_comunas: {e}", flush=True)
        return None, False
    # find_commune_id espera el shape crudo de /v/communes -- rows ya calza
    # (id, name, is_available) salvo el nombre de la llave 'nombre' vs 'name'.
    comunas = [{"id": r["id"], "name": r["nombre"], "is_available": bool(r["is_available"])}
               for r in rows]
    return _shc.find_commune_id(nombre_comuna, comunas)


@app.route("/transporte/api/diagnostico/shipit", methods=["GET", "POST"])
@login_required
def tr_diagnostico_shipit():
    """Diagnóstico admin de la integración Shipit (Fase 1: solo cotizar).

    GET  -> estado de configuración + cuántas comunas hay cacheadas.
    POST -> sincroniza comunas (?accion=sync_comunas) o cotiza de prueba
            (?accion=cotizar con body {comuna, peso_kg, largo, ancho, alto}).
    Mismo patrón que /transporte/api/diagnostico/simpliroute -- admin/superadmin.
    """
    if not (g.permissions.get("superadmin") or g.permissions.get("admin")):
        return jsonify({"error": "Solo admin/superadmin"}), 403

    import shipit_client as _shc

    if request.method == "GET":
        try:
            n_comunas = (mysql_fetchone("SELECT COUNT(*) AS n FROM shipit_comunas") or {}).get("n", 0)
        except Exception:
            n_comunas = 0
        origin_id, origin_disp = _shipit_commune_id("Quilicura")
        return jsonify({
            "ok": True,
            "configurado": bool(SHIPIT_API_TOKEN and SHIPIT_API_EMAIL),
            "comunas_cacheadas": n_comunas,
            "origen_bodega": {"comuna": "Quilicura", "commune_id": origin_id, "disponible": origin_disp},
            "restricciones": {"max_bultos": _shc.MAX_BULTOS, "max_peso_kg": _shc.MAX_PESO_KG},
        })

    accion = (request.args.get("accion") or "").strip()
    if accion == "sync_comunas":
        r = _shipit_sync_comunas()
        return jsonify(r), (200 if r.get("ok") else 502)

    if accion == "cotizar":
        data = request.get_json(silent=True) or {}
        comuna_destino = (data.get("comuna") or "").strip()
        peso_kg = data.get("peso_kg")
        n_bultos = data.get("n_bultos", 1)
        if not comuna_destino:
            return jsonify({"error": "Falta 'comuna'"}), 400

        problemas = _shc.verificar_restricciones(n_bultos, peso_kg)
        if problemas:
            return jsonify({"ok": True, "cotizable": False, "restricciones": problemas, "prices": []})

        origin_id, origin_disp = _shipit_commune_id("Quilicura")
        destiny_id, destiny_disp = _shipit_commune_id(comuna_destino)
        if not origin_id:
            return jsonify({"ok": False, "error": "Comuna de origen (bodega Quilicura) sin homologar -- "
                                                    "corre 'sync_comunas' primero."}), 409
        if not destiny_id:
            return jsonify({"ok": True, "cotizable": False,
                            "restricciones": [f"Shipit no tiene cobertura para {comuna_destino}."], "prices": []})

        payload, errores = _shc.build_rate_payload(
            length=data.get("largo", 30), width=data.get("ancho", 30), height=data.get("alto", 30),
            weight=peso_kg, origin_id=origin_id, destiny_id=destiny_id,
        )
        if errores:
            return jsonify({"ok": False, "error": "; ".join(errores)}), 400

        r = _shipit_request("POST", _shc.EP_RATES, payload=payload)
        if not r.get("ok"):
            return jsonify({"ok": False, "error": r.get("error")}), (r.get("status") or 502)
        prices = _shc.parse_rates_response(r["data"])
        return jsonify({"ok": True, "cotizable": True, "restricciones": [], "prices": prices})

    return jsonify({"error": "accion inválida (sync_comunas | cotizar)"}), 400


@app.route("/transporte/api/shipit/direccion", methods=["POST"])
@login_required
def tr_shipit_direccion():
    """Separa una dirección en calle + número para Shipit. READ-ONLY.

    Shipit exige `street` y `number` en campos SEPARADOS; ILUS guarda la
    dirección como un solo texto libre. La regla de separación vive en
    shipit_client.split_street_number() (módulo puro, 17 tests) y NO se
    duplica ni acá ni en el frontend: este endpoint es solo la ventanilla
    para que la pantalla la consulte.

    No toca la BD ni el ERP: transforma el texto que recibe y responde.

    Body:  {"direccion": "Los Aromos 145 depto 402"}
    Resp:  {"ok": true, "calle": "Los Aromos", "numero": "145",
            "problemas": ["..."], "bloqueada": false}

      · bloqueada=true  -> no se pudo armar el par calle+número con
        confianza. La pantalla pide completarlo a mano ANTES de generar la
        guía: un número adivinado produce una guía VÁLIDA hacia la dirección
        EQUIVOCADA y nadie se entera hasta que el cliente reclama.
      · bloqueada=false con `problemas` -> se pudo separar, pero conviene
        que alguien confirme el número.

    Mismos permisos que /api/asignar/cotizar-couriers: quien cotiza es quien
    despacha.
    """
    if not (g.permissions.get("cubicador") or g.permissions.get("transporte")
            or g.permissions.get("logistica_cotizaciones") or g.permissions.get("superadmin")):
        return jsonify({"ok": False, "error": "Sin permiso"}), 403
    try:
        import shipit_client as _shc
        data = request.get_json(silent=True) or {}
        direccion = (data.get("direccion") or "").strip()
        if not direccion:
            return jsonify({"ok": False, "error": "Falta 'direccion'"}), 400
        r = _shc.clasificar_direccion(direccion)
        r["ok"] = True
        r["direccion"] = direccion[:300]
        return jsonify(r)
    except Exception as e:
        print(f"[tr_shipit_direccion] CRASH: {e}", flush=True)
        return jsonify({"ok": False, "error": "Error interno",
                        "error_codigo": "INTERNAL_CRASH"}), 500


# ══════════════════════════════════════════════════════════════════════
#  Integración Clickex (2026-08-25) -- API real compartida por el
#  ejecutivo (MBM). Mismo patrón que Shipit arriba: módulo puro
#  (clickex_client.py) + esta capa de red + caché en BD de la matriz de
#  tarifas ya negociada.
#
#  Pedido de Daniel (vía chat, 2026-08-24): "instalemos y activemos
#  Clickex con la API... que se pueda cotizar, se pueda llamar a crear un
#  pedido, se pueda consultar los estados y se pueda traer los precios".
#  Límite confirmado: 25 kg (sin límite de dimensiones -- a diferencia de
#  Shipit, ver clickex_client.MAX_PESO_KG).
#
#  ⚠️ Fase 1 (esta): cotizar (matriz de tarifas), traer precios y
#  consultar estado -- todo READ-ONLY sobre la API de Clickex. La
#  creación de envío real (POST /shipmentsAdd) queda CONSTRUIDA en
#  clickex_client.build_shipment_payload() / parse_shipment_response() y
#  con su capa de red lista acá abajo, pero SIN ningún botón que la
#  dispare todavía -- ni siquiera Shipit (más madura) tiene esa pieza en
#  producción. Crear un envío real cuesta dinero y despacha un courier de
#  verdad: se conecta a un flujo real recién cuando Daniel lo confirme
#  viendo la app despierto, no en una corrida nocturna sin supervisión.
#
#  Credenciales: GitHub Secrets → env.yaml → Cloud Run (Regla #4), ya
#  inyectadas en deploy.yml. Auth por x-api-key (todos los endpoints) +
#  username/password (matriz de tarifas y creación de envío).
# ══════════════════════════════════════════════════════════════════════
CLICKEX_API_USERNAME = os.environ.get("CLICKEX_API_USERNAME", "").strip()
CLICKEX_API_PASSWORD = os.environ.get("CLICKEX_API_PASSWORD", "").strip()
CLICKEX_API_KEY = os.environ.get("CLICKEX_API_KEY", "").strip()


def _clickex_request(method, path, *, payload=None, headers_extra=None, timeout=20):
    """Llamada HTTP a Clickex. NUNCA lanza: siempre devuelve dict con `ok`.

    Mismo contrato defensivo que _shipit_request/_simpliroute_request. Los
    endpoints que exigen username/password (matriz de tarifas, crear envío)
    los agregan vía `headers_extra`; tracking solo necesita la api key.
    """
    import requests as _req
    import clickex_client as _clc

    if not CLICKEX_API_KEY:
        return {"ok": False, "status": 0,
                "error": "Clickex no está configurado (falta CLICKEX_API_KEY)."}
    url = _clc.BASE_URL + path
    # BUG REAL (2026-08-25, verificado con curl vs requests desde este mismo
    # equipo Y desde Cloud Run en produccion): el servidor de Clickex (o un
    # WAF delante) corta la conexion en seco -- "RemoteDisconnected" -- ante
    # el User-Agent por defecto de la libreria requests
    # ("python-requests/X.X.X"), pero responde 200 normal a curl. Se manda
    # un User-Agent explicito que no delate la libreria HTTP.
    headers = {
        "Content-Type": "application/json",
        "x-api-key": CLICKEX_API_KEY,
        "User-Agent": "ILUS-Fitness/1.0 (+https://ilusfitness.com)",
    }
    if headers_extra:
        headers.update(headers_extra)
    try:
        resp = _req.request(method, url, headers=headers, json=payload, timeout=timeout)
    except Exception as e:
        return {"ok": False, "status": 0,
                "error": f"No se pudo conectar con Clickex: {type(e).__name__}"}
    try:
        body = resp.json()
    except Exception:
        body = resp.text
    if resp.status_code >= 400:
        return {"ok": False, "status": resp.status_code,
                "error": _clc.extract_error_message(resp.status_code, body),
                "raw": body}
    return {"ok": True, "status": resp.status_code, "data": body}


def _clickex_seller_headers():
    """Headers username/password para los endpoints que identifican al
    seller (matriz de tarifas, crear envío). Vacío si no están configurados
    -- _clickex_request ya valida CLICKEX_API_KEY por separado."""
    if not (CLICKEX_API_USERNAME and CLICKEX_API_PASSWORD):
        return None
    return {"username": CLICKEX_API_USERNAME, "password": CLICKEX_API_PASSWORD}


def _ensure_clickex_tarifas_table():
    """Caché local de GET /sellerShipmentMatrixCosts -- tabla NUEVA, se crea
    SIEMPRE, incluso con ILUS_SKIP_MIGRATIONS=1 (mismo gotcha documentado en
    _ensure_shipit_comunas_table: init_transporte_tables() no corre en prod).

    Por qué existe: la matriz trae ~37 filas y no cambia seguido -- cachear
    evita golpear la API en cada descarga de Excel/cotización.
    """
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS clickex_tarifas (
                    id                  INT AUTO_INCREMENT PRIMARY KEY,
                    comuna              VARCHAR(120) NOT NULL,
                    comuna_normalizada  VARCHAR(120) NOT NULL,
                    sla_dias            INT,
                    costo_neto          DECIMAL(10,2),
                    updated_at          DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    UNIQUE KEY uq_comuna_normalizada (comuna_normalizada),
                    INDEX idx_comuna (comuna)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
            """)
        conn.commit()
    except Exception as e:
        print(f"[clickex] no se pudo crear clickex_tarifas: {e}", flush=True)
    finally:
        conn.close()


def _clickex_sync_tarifas():
    """Trae GET /sellerShipmentMatrixCosts y guarda/actualiza clickex_tarifas
    (UPSERT por comuna_normalizada). READ-ONLY sobre Clickex. Nunca lanza --
    devuelve {ok, n, error}."""
    import clickex_client as _clc
    headers = _clickex_seller_headers()
    if not headers:
        return {"ok": False, "n": 0,
                "error": "Clickex no está configurado (falta CLICKEX_API_USERNAME/CLICKEX_API_PASSWORD)."}
    r = _clickex_request("GET", _clc.EP_MATRIX_COSTS, headers_extra=headers)
    if not r.get("ok"):
        return {"ok": False, "n": 0, "error": r.get("error")}
    tarifas = _clc.parse_matrix_costs_response(r.get("data"))
    if not tarifas:
        return {"ok": False, "n": 0,
                "error": "Respuesta inesperada de Clickex (se esperaba una lista de tarifas)."}
    conn = get_mysql()
    n = 0
    try:
        with conn.cursor() as cur:
            for t in tarifas:
                cur.execute(
                    "INSERT INTO clickex_tarifas (comuna, comuna_normalizada, sla_dias, costo_neto) "
                    "VALUES (%s, %s, %s, %s) "
                    "ON DUPLICATE KEY UPDATE comuna=VALUES(comuna), sla_dias=VALUES(sla_dias), "
                    "costo_neto=VALUES(costo_neto)",
                    (t["comuna"], t["comuna_normalizada"], t["sla_dias"], t["costo_neto"])
                )
                n += 1
        conn.commit()
    except Exception as e:
        return {"ok": False, "n": n, "error": f"Error guardando tarifas: {e}"}
    return {"ok": True, "n": n, "error": None}


def _clickex_tarifa_comuna(nombre_comuna):
    """Tarifa de Clickex para una comuna (del ERP o de la bodega ILUS).

    Lee de la caché local clickex_tarifas (poblada por _clickex_sync_tarifas).
    Devuelve dict {comuna, sla_dias, costo_neto} o None si no hay cobertura
    cacheada. Nunca lanza.
    """
    import clickex_client as _clc
    target = _clc.normalizar_comuna(nombre_comuna)
    if not target:
        return None
    try:
        row = mysql_fetchone(
            "SELECT comuna, sla_dias, costo_neto FROM clickex_tarifas "
            "WHERE comuna_normalizada = %s",
            (target,)
        )
    except Exception as e:
        print(f"[clickex] error leyendo clickex_tarifas: {e}", flush=True)
        return None
    if not row:
        return None
    return {"comuna": row["comuna"], "sla_dias": row["sla_dias"],
            "costo_neto": float(row["costo_neto"]) if row["costo_neto"] is not None else None}


def _ensure_clickex_limite_peso():
    """Fija el tope de 25 kg confirmado por Daniel (2026-08-24) en la ficha
    del courier Clickex -- SOLO la primera vez (no pisa si alguien ya lo
    editó a mano), mismo criterio que _ensure_shipit_courier(). La fila del
    courier "Clickex" ya existe desde antes (sembrada en _defaults más
    arriba en este archivo) -- acá solo se actualiza el límite de peso.
    """
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE transport_couriers SET peso_max_bulto=25, peso_max_guia=25 "
                "WHERE LOWER(nombre)='clickex' AND peso_max_bulto=0 AND peso_max_guia=0"
            )
        conn.commit()
    except Exception as e:
        print(f"[clickex] no se pudo fijar el limite de peso: {e}", flush=True)
    finally:
        conn.close()


@app.route("/transporte/api/diagnostico/clickex", methods=["GET", "POST"])
@login_required
def tr_diagnostico_clickex():
    """Diagnóstico admin de la integración Clickex (Fase 1: tarifas + tracking).

    GET  -> estado de configuración + cuántas comunas hay cacheadas.
    POST -> sincroniza tarifas (?accion=sync_tarifas), cotiza de prueba
            (?accion=cotizar con body {comuna, peso_kg}) o consulta un
            tracking real (?accion=tracking con body {tracking}).
    Mismo patrón que /transporte/api/diagnostico/shipit -- admin/superadmin.
    """
    if not (g.permissions.get("superadmin") or g.permissions.get("admin")):
        return jsonify({"error": "Solo admin/superadmin"}), 403

    import clickex_client as _clc

    if request.method == "GET":
        try:
            n_comunas = (mysql_fetchone("SELECT COUNT(*) AS n FROM clickex_tarifas") or {}).get("n", 0)
        except Exception:
            n_comunas = 0
        return jsonify({
            "ok": True,
            "configurado": bool(CLICKEX_API_KEY and CLICKEX_API_USERNAME and CLICKEX_API_PASSWORD),
            "comunas_cacheadas": n_comunas,
            "restricciones": {"max_peso_kg": _clc.MAX_PESO_KG},
        })

    accion = (request.args.get("accion") or "").strip()
    if accion == "sync_tarifas":
        r = _clickex_sync_tarifas()
        return jsonify(r), (200 if r.get("ok") else 502)

    if accion == "cotizar":
        data = request.get_json(silent=True) or {}
        comuna_destino = (data.get("comuna") or "").strip()
        peso_kg = data.get("peso_kg")
        if not comuna_destino:
            return jsonify({"error": "Falta 'comuna'"}), 400

        problemas = _clc.verificar_restricciones(peso_kg) if peso_kg else []
        if problemas:
            return jsonify({"ok": True, "cotizable": False, "restricciones": problemas, "tarifa": None})

        tarifa = _clickex_tarifa_comuna(comuna_destino)
        if not tarifa:
            return jsonify({"ok": True, "cotizable": False,
                            "restricciones": [f"Clickex no tiene cobertura cacheada para {comuna_destino} "
                                               f"(corre 'sync_tarifas' primero si es una comuna nueva)."],
                            "tarifa": None})
        return jsonify({"ok": True, "cotizable": True, "restricciones": [], "tarifa": tarifa})

    if accion == "tracking":
        data = request.get_json(silent=True) or {}
        tracking = (data.get("tracking") or "").strip()
        if not tracking:
            return jsonify({"error": "Falta 'tracking'"}), 400
        r = _clickex_request("GET", _clc.EP_TRACKING.format(tracking=tracking))
        if not r.get("ok"):
            return jsonify({"ok": False, "error": r.get("error")}), (r.get("status") or 502)
        return jsonify({"ok": True, "resultado": _clc.parse_tracking_response(r["data"])})

    return jsonify({"error": "accion inválida (sync_tarifas | cotizar | tracking)"}), 400


def _tr_manifiesto_items_simpliroute(mid):
    """Items del manifiesto con lo que necesita SimpliRoute.

    Helper PARALELO a _tr_manifiesto_items_export (no lo modifica) para no
    arriesgar el formato del Excel que el transportista ya usa. Agrega: el id
    del item (para mapear la respuesta), el estado de sincronización previo
    (evitar duplicados) y las coordenadas con fallback dest_lat/dest_lng.
    """
    return mysql_fetchall("""
        SELECT mi.id AS item_id,
               mi.simpliroute_visit_id, mi.simpliroute_tracking_id,
               c.id AS commitment_id, c.tido, c.nudo, c.cliente_nombre,
               c.comuna, c.region, c.direccion, c.telefono, c.email, c.notas,
               COALESCE(c.peso_export, 0)       AS peso_export,
               COALESCE(NULLIF(c.peso_export, 0),
                        NULLIF(c.peso_real, 0), 0) AS peso_kg,
               COALESCE(c.peso_vol, 0)          AS peso_vol_kg,
               COALESCE(c.peso_predominante, 0) AS peso_predominante,
               COALESCE(c.n_bultos, 1)          AS n_bultos,
               COALESCE(c.direccion_lat, c.dest_lat) AS direccion_lat,
               COALESCE(c.direccion_lng, c.dest_lng) AS direccion_lng
          FROM transport_manifest_items mi
          JOIN transport_commitments c ON c.id = mi.commitment_id
         WHERE mi.manifest_id = %s
         ORDER BY mi.orden, mi.id
    """, (mid,)) or []


@app.route("/transporte/api/diagnostico/simpliroute", methods=["GET"])
@_tr_required
def tr_simpliroute_diagnostico():
    """Estado de la integración por courier. ?probar=1 hace un GET real a
    /v1/accounts/me/ para confirmar que el token está vivo."""
    import simpliroute_client as _src
    probar = (request.args.get("probar") or "").strip() == "1"
    out = []
    for clave, env_var in SIMPLIROUTE_TOKENS_ENV.items():
        tok = (os.environ.get(env_var) or "").strip()
        fila = {
            "courier": clave, "env_var": env_var,
            "token_configurado": bool(tok),
            # Nunca exponer el token completo (REGLA #4)
            "token_preview": (tok[:4] + "…" + tok[-4:]) if len(tok) > 12 else ("—" if not tok else "…"),
        }
        if probar and tok:
            r = _simpliroute_request("GET", _src.EP_ME, tok, timeout=15)
            fila["conexion_ok"] = r.get("ok", False)
            if r.get("ok"):
                d = r.get("data") or {}
                fila["cuenta"] = {"id": d.get("id"), "email": d.get("email")}
            else:
                fila["error"] = r.get("error")
        out.append(fila)
    return jsonify({"ok": True, "couriers": out})


@app.route("/transporte/api/diagnostico/simpliroute/flota", methods=["GET"])
@_tr_required
def tr_simpliroute_diagnostico_flota():
    """SOLO LECTURA. Por que el Router del courier no toma las visitas de ILUS.

    2026-08-20. Sintoma medido en produccion: las visitas SI se crean (27 vivas
    en la cuenta de Felca), pero NADIE las planifica nunca. Se rescataron 25 al
    19-ago y al dia siguiente seguian en 'pending' sin chofer. En cambio, las
    visitas que el propio Felca carga por Excel SI se rutean y se entregan.

    La hipotesis a confirmar o descartar: en SimpliRoute el optimizador solo
    asigna una visita a un vehiculo que tenga TODAS las habilidades que la
    visita exige. El Excel que Felca usa manda la COMUNA en la columna
    "Habilidades requeridas"; la API de ILUS no manda `skills_required`. Si los
    vehiculos de Rafael estan configurados por zona, las visitas de ILUS
    quedarian fuera de toda ruta -- exactamente el sintoma.

    Este endpoint NO escribe nada. Solo hace GET a la API del courier para
    responder tres preguntas que ILUS nunca se hizo:
      1. Que vehiculos tiene la cuenta y que habilidades/capacidades declaran.
      2. Como se ve una visita que SI se ruteo, comparada con una de ILUS.
      3. Que habilidades usan de verdad las visitas del courier.

    Query params:
      courier : clave del courier (default "felca")
      fecha   : YYYY-MM-DD a inspeccionar (default hoy Chile)

    Permiso: superadmin. Expone datos internos de la cuenta de un tercero
    (patentes, nombres de chofer), no es para operacion diaria.
    """
    import simpliroute_client as _src

    if not bool(g.permissions.get("superadmin")):
        return jsonify({"ok": False,
                        "error": "Solo un superadministrador puede ver el diagnostico de flota."}), 403

    clave = (request.args.get("courier") or "felca").strip().lower()
    env_var = SIMPLIROUTE_TOKENS_ENV.get(clave)
    if not env_var:
        return jsonify({"ok": False,
                        "error": f"Courier desconocido: {clave}. "
                                 f"Validos: {', '.join(sorted(SIMPLIROUTE_TOKENS_ENV))}"}), 400
    token = (os.environ.get(env_var) or "").strip()
    if not token:
        return jsonify({"ok": False, "error": f"Falta {env_var} en el entorno."}), 503

    fecha = (request.args.get("fecha") or "").strip() or _now_chile().date().isoformat()

    out = {"ok": True, "courier": clave, "fecha": fecha, "hoy": _now_chile().date().isoformat()}

    # ── 1. LA FLOTA. Aca esta la respuesta: que exige cada vehiculo. ──────
    rv = _simpliroute_request("GET", "/v1/routes/vehicles/", token, timeout=25)
    if not rv.get("ok"):
        out["vehiculos_error"] = rv.get("error") or "no se pudo leer la flota"
        out["vehiculos"] = []
    else:
        data = rv.get("data")
        flota = data if isinstance(data, list) else (data or {}).get("results") or []
        vehiculos = []
        for v in flota:
            if not isinstance(v, dict):
                continue
            vehiculos.append({
                "id":         v.get("id"),
                "nombre":     v.get("name") or v.get("license_plate"),
                "patente":    v.get("license_plate"),
                # ESTO es lo que decide si una visita entra o no a su ruta.
                "skills":     v.get("skills") or v.get("skills_required") or [],
                "capacidad":   v.get("capacity"),
                "capacidad_2": v.get("capacity_2"),
                "capacidad_3": v.get("capacity_3"),
                "inicia":     v.get("shift_start") or v.get("start_time"),
                "termina":    v.get("shift_end") or v.get("end_time"),
                "activo":     v.get("is_active", v.get("active")),
            })
        out["vehiculos"] = vehiculos
        out["n_vehiculos"] = len(vehiculos)
        # El dato que decide todo: la flota exige habilidades, si o no.
        _skills_flota = set()
        for v in vehiculos:
            for sk in (v.get("skills") or []):
                _skills_flota.add(str(sk))
        out["skills_de_la_flota"] = sorted(_skills_flota)
        out["la_flota_exige_habilidades"] = bool(_skills_flota)

    # ── 2. LAS VISITAS DEL DIA, separadas por quien las creo ──────────────
    # ILUS guarda el visit_id de todo lo que sube: lo que este en la cuenta y
    # NO este en nuestra tabla, lo cargo el courier por su cuenta (Excel).
    rvis = _simpliroute_request("GET", f"{_src.EP_VISITS}?planned_date={fecha}",
                                token, timeout=45)
    if not rvis.get("ok"):
        out["visitas_error"] = rvis.get("error") or "no se pudo leer las visitas"
        return jsonify(out)

    data = rvis.get("data")
    visitas = data if isinstance(data, list) else (data or {}).get("results") or []

    ids_ilus = set()
    try:
        filas = mysql_fetchall(
            "SELECT NULLIF(TRIM(simpliroute_visit_id), '') AS vid "
            "FROM transport_manifest_items "
            "WHERE NULLIF(TRIM(simpliroute_visit_id), '') IS NOT NULL") or []
        ids_ilus = {str(f["vid"]).strip() for f in filas if f.get("vid")}
    except Exception as e:
        out["aviso_bd"] = f"No se pudo leer los visit_id de ILUS: {type(e).__name__}"

    def _resumen(v):
        """Los campos que deciden si el optimizador la puede asignar."""
        ruta = v.get("route") if isinstance(v.get("route"), dict) else None
        return {
            "id":            str(v.get("id") or ""),
            "title":         v.get("title"),
            "reference":     v.get("reference"),
            "status":        v.get("status"),
            "planned_date":  v.get("planned_date"),
            # ── los sospechosos ──
            "skills_required": v.get("skills_required") or [],
            "load":            v.get("load"),
            "load_2":          v.get("load_2"),
            "load_3":          v.get("load_3"),
            "window_start":    v.get("window_start"),
            "window_end":      v.get("window_end"),
            "duration":        v.get("duration"),
            "priority":        v.get("priority"),
            "tags":            v.get("tags") or [],
            "lat":             v.get("latitude"),
            "lng":             v.get("longitude"),
            "direccion":       v.get("address"),
            # ── el veredicto: la tomo alguien? ──
            "tiene_ruta":      bool(ruta),
            "chofer":          (ruta or {}).get("driver_name"),
        }

    # CORRECCION 2026-08-20: clasificar por el FORMATO de la reference, no
    # por si el visit_id esta en nuestra base. Tener el visit_id guardado NO
    # significa que la creamos: _simpliroute_reconciliar_huerfanos ADOPTA las
    # visitas que carga el courier (las busca por reference y les escribe el
    # visit_id). Con el criterio viejo, las entregas de Felca se contaban como
    # nuestras y el diagnostico mostraba a ILUS mucho mejor de lo que esta --
    # justo el error que este endpoint existe para no cometer.
    de_ilus, del_courier = [], []
    for v in visitas:
        if not isinstance(v, dict):
            continue
        r = _resumen(v)
        r["origen"] = _sr_quien_creo_la_visita(v.get("reference"))
        # `adoptada`: la cargo el courier y despues ILUS la reconocio como
        # suya. Se conserva el dato (REGLA #4.2) pero ya no decide el bucket.
        r["adoptada_por_ILUS"] = r["id"] in ids_ilus
        (de_ilus if r["origen"] == "ILUS" else del_courier).append(r)

    def _stats(lista):
        con_ruta = [x for x in lista if x["tiene_ruta"]]
        con_skills = [x for x in lista if x["skills_required"]]
        return {
            "total": len(lista),
            "entregadas": sum(1 for x in lista if x.get("status") == "completed"),
            "adoptadas_por_ILUS": sum(1 for x in lista if x.get("adoptada_por_ILUS")),
            "con_ruta_asignada": len(con_ruta),
            "sin_ruta": len(lista) - len(con_ruta),
            "declaran_skills": len(con_skills),
            "skills_usadas": sorted({str(sk) for x in lista for sk in (x["skills_required"] or [])}),
            "estados": {e: sum(1 for x in lista if x["status"] == e)
                        for e in sorted({x["status"] for x in lista if x.get("status")})},
        }

    out["creadas_por_ILUS"]    = _stats(de_ilus)
    out["creadas_por_COURIER"] = _stats(del_courier)
    out["muestra_ILUS"]        = de_ilus[:5]
    out["muestra_COURIER"]     = del_courier[:5]

    # ── 3. EL VEREDICTO, en una linea legible ────────────────────────────
    a, b = out["creadas_por_ILUS"], out["creadas_por_COURIER"]
    pistas = []
    if out.get("la_flota_exige_habilidades") and a["total"] and not a["declaran_skills"]:
        pistas.append(
            "La flota exige habilidades (" + ", ".join(out["skills_de_la_flota"][:6]) +
            ") y NINGUNA visita de ILUS declara skills_required. "
            "El optimizador no puede asignarlas a ningun vehiculo.")
    if b["total"] and b["declaran_skills"] and a["total"] and not a["declaran_skills"]:
        pistas.append(
            "Las visitas que carga el propio courier SI declaran habilidades "
            "(" + ", ".join(b["skills_usadas"][:6]) + ") y las de ILUS no. "
            "Esa es la diferencia entre las que se rutean y las que no.")
    if a["total"] and not a["con_ruta_asignada"] and b["con_ruta_asignada"]:
        pistas.append(
            f"En {fecha}: {b['con_ruta_asignada']} de {b['total']} visitas del courier "
            f"tienen ruta, y 0 de {a['total']} de ILUS.")
    if not pistas:
        pistas.append("Sin diferencia evidente en este dia. Probar otra fecha "
                      "con entregas reales del courier.")
    out["veredicto"] = pistas

    return jsonify(out)


@app.route("/transporte/api/manifiestos/<int:mid>/subir-simpliroute", methods=["POST"])
@_tr_required
def tr_manifiesto_subir_simpliroute(mid):
    """Sube TODAS las facturas del manifiesto a SimpliRoute como visitas.

    Idempotente: los items que ya tienen simpliroute_visit_id se saltan (no se
    duplican si se presiona el botón dos veces).

    Estrategia de envío: la API acepta un array (bulk nativo), PERO no está
    documentado qué pasa si una visita del lote es inválida. Por eso se replica
    el patrón `auto_fallback_individual` de FedEx: se intenta el lote completo
    y, si falla o vuelven menos visitas de las enviadas, se reintenta 1×1 para
    aislar al culpable y guardar el error por item.
    """
    import simpliroute_client as _src

    man = mysql_fetchone("SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not man:
        return jsonify({"error": "Manifiesto no encontrado"}), 404

    courier = (man.get("courier") or "").strip()
    if not _simpliroute_courier_integra(courier):
        return jsonify({
            "error": f"El courier «{courier}» no trabaja con SimpliRoute. "
                     f"Esta subida es solo para Transportes Felca y Transportes Milling."
        }), 400
    token = _simpliroute_token_for_courier(courier)
    if not token:
        return jsonify({
            "error": f"Falta configurar el token de SimpliRoute de «{courier}» "
                     f"(variable de entorno). Avisa al administrador."
        }), 503

    # ── planned_date = EL DÍA EN QUE SE SUBE, no el día del manifiesto ──────
    # FIX 2026-08-18 (levantamiento urgente: "suben desde el botón y no
    # aparece en SimpliRoute"). Causa raíz encontrada con evidencia en vivo:
    # la visita se creaba con la fecha del MANIFIESTO, que es el día en que
    # Alison lo armó en ILUS -- no el día en que se entrega la carga al
    # transporte. Cuando el manifiesto se sube al día siguiente (lo normal),
    # la visita nacía en un día YA CERRADO y quedaba invisible para el
    # despachador, en estado 'pending' para siempre.
    #
    # Casos reales medidos contra la API el 2026-08-18:
    #   · FCV 11286 -- manifiesto 13/08, subido el 14/08 -> planned_date
    #     13/08 -> 4,4 DÍAS en 'pending', nunca entregado.
    #   · FCV 11273 -- manifiesto 17/08, subido el 18/08 -> planned_date
    #     17/08 -> 'pending'.
    #   · BLV 23088 (control) -- visita creada por el propio Felca con la
    #     fecha del día -> 'completed', entregada. Ninguna visita creada por
    #     ILUS llegó nunca a entregarse.
    #
    # Criterio de Daniel (2026-08-18), textual: "el día que se suben a
    # SimpliRoute, porque ahí se estaría entregando al transporte". Subir =
    # entregar la carga. Por eso la fecha es HOY (hora Chile), y si difiere
    # de la del manifiesto se avisa explícitamente en la respuesta -- nunca
    # se cambia en silencio.
    _fecha = man.get("fecha")
    fecha_manifiesto = (_fecha.isoformat() if hasattr(_fecha, "isoformat")
                        else str(_fecha or "").strip())
    planned_date = _sr_planned_date_hoy()
    fecha_cambiada = bool(fecha_manifiesto and fecha_manifiesto != planned_date)

    items = _tr_manifiesto_items_simpliroute(mid)
    if not items:
        return jsonify({"error": "El manifiesto no tiene facturas para subir."}), 400

    pendientes = [it for it in items if not (it.get("simpliroute_visit_id") or "").strip()]
    ya_subidos = len(items) - len(pendientes)
    if not pendientes:
        return jsonify({"ok": True, "total": len(items), "creadas": 0,
                        "ya_estaban": ya_subidos, "errores": 0, "resultados": [],
                        "mensaje": "Todas las facturas de este manifiesto ya estaban en SimpliRoute."})

    payloads, saltados = _src.build_visits_batch(pendientes, planned_date=planned_date)

    resultados = []
    for iid, motivo in saltados:
        resultados.append({"item_id": iid, "ok": False, "error": f"Datos incompletos: {motivo}"})
        try:
            mysql_execute("UPDATE transport_manifest_items SET simpliroute_error=%s WHERE id=%s",
                          (f"Datos incompletos: {motivo}"[:500], iid))
        except Exception:
            pass

    def _persistir_ok(item_id, visita):
        try:
            mysql_execute(
                "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
                "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW(), "
                "simpliroute_error=NULL WHERE id=%s",
                (str(visita.get("id") or "")[:40], str(visita.get("tracking_id") or "")[:60], item_id))
        except Exception as e:
            print(f"[simpliroute] no se pudo persistir item {item_id}: {e}", flush=True)

    def _persistir_error(item_id, msg):
        try:
            mysql_execute("UPDATE transport_manifest_items SET simpliroute_error=%s WHERE id=%s",
                          (str(msg)[:500], item_id))
        except Exception:
            pass

    # ── Envío por lotes de 25 (tamaño máximo no documentado por SimpliRoute) ──
    CHUNK = 25
    for i in range(0, len(payloads), CHUNK):
        lote = payloads[i:i + CHUNK]
        r = _simpliroute_request("POST", _src.EP_VISITS, token,
                                 payload=[p for _, p in lote],
                                 timeout=60 if len(lote) > 10 else 30)
        visitas = _src.parse_visits_response(r.get("data")) if r.get("ok") else []

        if r.get("ok") and len(visitas) == len(lote):
            for (iid, _p), visita in zip(lote, visitas):
                _persistir_ok(iid, visita)
                resultados.append({"item_id": iid, "ok": True,
                                   "visit_id": visita.get("id"),
                                   "tracking_id": visita.get("tracking_id")})
            continue

        # Fallback 1×1: el lote falló o vino incompleto → aislar al culpable.
        print(f"[simpliroute] lote de {len(lote)} falló o vino incompleto "
              f"(ok={r.get('ok')}, recibidas={len(visitas)}) → reintento individual",
              flush=True)
        for iid, p in lote:
            r1 = _simpliroute_request("POST", _src.EP_VISITS, token, payload=p, timeout=30)
            if r1.get("ok"):
                v = (_src.parse_visits_response(r1.get("data")) or [{}])[0]
                _persistir_ok(iid, v)
                resultados.append({"item_id": iid, "ok": True,
                                   "visit_id": v.get("id"),
                                   "tracking_id": v.get("tracking_id")})
            else:
                msg = r1.get("error") or "Error desconocido"
                _persistir_error(iid, msg)
                resultados.append({"item_id": iid, "ok": False, "error": msg})

    creadas = sum(1 for x in resultados if x.get("ok"))
    errores = sum(1 for x in resultados if not x.get("ok"))
    # La fecha usada queda en la trazabilidad SIEMPRE: es el dato que
    # explica en qué día del tablero del courier cayó cada visita, y fue
    # justo lo que faltó para diagnosticar el problema de agosto 2026.
    _tr_log("manifest", mid, "subida a SimpliRoute",
            f"courier={courier}; creadas={creadas}; errores={errores}; "
            f"ya_estaban={ya_subidos}; fecha_visita={planned_date}"
            + (f" (manifiesto {fecha_manifiesto})" if fecha_cambiada else ""))

    # 2026-07-25 (fix Daniel: MAN-2026-0011 se quedaba en "En preparación" pese
    # a que SimpliRoute ya mostraba la visita asignada a chofer/vehículo).
    # Mismo patrón que FedEx (línea ~25517): al subir la visita con éxito el
    # pedido pasa a "Entregado a transporte" (delegado al transportista) y se
    # avisa al cliente. Antes de este fix, el item quedaba en "En preparación"
    # hasta que el poller viera on_its_way/completed/failed/partial — es decir,
    # el estado NUNCA reflejaba que ya estaba asignado/en manos del courier.
    for x in resultados:
        if not x.get("ok"):
            continue
        try:
            # ── notify_cliente=False (2026-08-23, decisión de Daniel) ──────
            # El estado interno SÍ pasa a 'Entregado a transporte' (el item
            # quedó delegado al courier y el tablero lo tiene que reflejar),
            # pero al cliente NO se le avisa en este punto.
            #
            # POR QUÉ. El correo de ese estado le dice al cliente:
            #   "Tu pedido ya salió de nuestras instalaciones y quedó en
            #    camino a ti."
            # Crear la visita en SimpliRoute NO significa nada de eso. Medido
            # contra la API real el 20-08-2026 sobre los días 13, 14, 19 y 20:
            # de 15 visitas creadas por ILUS, CERO se entregaron jamás — el
            # despachador del courier puede no meterlas nunca en una ruta y la
            # carga sigue en bodega. Le estábamos prometiendo al cliente un
            # movimiento que no ocurrió.
            #
            # Con FedEx es distinto y por eso FedEx NO se toca (ver
            # app.py:32937 y :33082): ahí el aviso se dispara al generar la
            # etiqueta, y eso sí significa que FedEx ya tiene el envío en su
            # sistema (status OC = Order Created).
            #
            # El cliente NO queda en silencio: el poller de SimpliRoute corre
            # cada 10 min por Cloud Scheduler y avisa cuando el estado avanza
            # de verdad -- 'En ruta' cuando el chofer va en camino
            # (on_its_way), 'Entregado' al completarse. Ver
            # _simpliroute_poll_batch, que ya manda con notify_cliente=True
            # para los avances frescos del día.
            _tr_apply_carrier_status(x["item_id"], 'Entregado a transporte', fuente='sistema',
                                     comentario='Visita creada en SimpliRoute',
                                     notify_cliente=False)
        except Exception as _e_sr_ev:
            print(f"[tr_event sr_subida] item={x.get('item_id')}: {_e_sr_ev}", flush=True)

    # ── Avisos honestos para quien aprieta el botón ────────────────────────
    # 2026-08-18. Antes la respuesta decía "creadas=1, errores=0" y todos
    # asumían que el courier ya la tenía en su ruta. No es así: una visita
    # recién creada queda SIN PLANIFICAR (status 'pending', sin chofer) hasta
    # que el despachador la mete en una ruta. Ese matiz es exactamente lo que
    # hizo que 4 despachos se perdieran en agosto sin que nadie se enterara.
    avisos = []
    if fecha_cambiada:
        avisos.append(
            f"La visita se programó para HOY ({planned_date}), no para la fecha "
            f"del manifiesto ({fecha_manifiesto}): subir es entregar la carga al "
            f"transporte, y una fecha pasada queda invisible en su tablero."
        )
    if creadas:
        avisos.append(
            f"{creadas} visita(s) quedaron creadas pero AÚN SIN PLANIFICAR en "
            f"{courier}. Recién aparecen en la ruta cuando el despachador las "
            f"asigna a un chofer. Si en un par de horas siguen sin moverse, "
            f"conviene llamarlos."
        )

    return jsonify({
        "ok": True, "total": len(items), "creadas": creadas,
        "ya_estaban": ya_subidos, "errores": errores, "resultados": resultados,
        "courier": courier, "fecha": planned_date,
        "fecha_manifiesto": fecha_manifiesto,
        "fecha_cambiada": fecha_cambiada,
        "avisos": avisos,
    })


# ══════════════════════════════════════════════════════════════════════
#  Modal consolidado "Ver seguimiento y acciones" (Felca/Milling, SimpliRoute)
#  2026-07-26 (pedido de Daniel): un solo modal con historial/tracking +
#  cancelar visita + reprogramar fecha + reenviar individual. Reutiliza
#  SIEMPRE los mismos choke-points ya existentes (_simpliroute_request,
#  EP_BULK_DELETE, build_visit_payload, _tr_apply_carrier_status) — no se
#  duplica ninguna llamada HTTP al courier.
# ══════════════════════════════════════════════════════════════════════

@app.route("/transporte/api/items/<int:item_id>/simpliroute/cancelar", methods=["POST"])
@_tr_required
def tr_item_simpliroute_cancelar(item_id):
    """Cancela/anula la visita de SimpliRoute de UN item puntual.

    Reutiliza el MISMO patrón de borrado que ya usa tr_quitar_item cuando se
    quita una factura del manifiesto (EP_BULK_DELETE) — no se reimplementa la
    llamada HTTP. Tras cancelar, limpia simpliroute_visit_id/tracking_id del
    item para que quede "sin visita" y se pueda reenviar después.
    """
    import simpliroute_client as _src
    mi = mysql_fetchone("""
        SELECT mi.id, mi.commitment_id, mi.simpliroute_visit_id, mi.manifest_id,
               mi.estado_entrega, tm.courier
        FROM transport_manifest_items mi
        LEFT JOIN transport_manifests tm ON tm.id = mi.manifest_id
        WHERE mi.id=%s
    """, (item_id,))
    if not mi:
        return jsonify({"ok": False, "error": "Item no encontrado"}), 404

    vid = (mi.get("simpliroute_visit_id") or "").strip()
    if not vid:
        return jsonify({"ok": False,
                         "error": "Este pedido no tiene una visita activa en "
                                  "SimpliRoute para cancelar."}), 400

    token = _simpliroute_token_for_courier(mi.get("courier"))
    if not token:
        return jsonify({"ok": False,
                         "error": "Falta configurar el token de SimpliRoute de "
                                  "este courier."}), 503

    try:
        r = _simpliroute_request("POST", _src.EP_BULK_DELETE, token,
                                  payload={"visits": [int(vid)]}, timeout=20)
    except Exception as e:
        print(f"[simpliroute] excepción cancelando visita {vid} (item {item_id}): {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo conectar con SimpliRoute. Intenta de nuevo."}), 502

    if not r.get("ok"):
        return jsonify({"ok": False,
                         "error": r.get("error") or "SimpliRoute rechazó la cancelación."}), 502

    mysql_execute(
        "UPDATE transport_manifest_items SET simpliroute_visit_id=NULL, "
        "simpliroute_tracking_id=NULL, simpliroute_synced_at=NULL, "
        "simpliroute_error=NULL WHERE id=%s", (item_id,))
    _tr_log("manifest_item", item_id, "visita SimpliRoute cancelada",
            f"visita {vid} anulada manualmente desde el modal de seguimiento")

    # FIX 2026-07-28 (auditoría de trazabilidad, SEV-4): cancelar la visita
    # dejaba el item CLAVADO en 'Entregado a transporte' para siempre — el
    # poller (_simpliroute_poll_batch) solo mira items CON simpliroute_visit_id,
    # y acá lo acabamos de limpiar. El cliente seguía viendo "tu pedido salió
    # de bodega" sin ningún seguimiento activo detrás. Además, esto dejaba
    # tr_item_simpliroute_reenviar sin efecto: como el estado ya era 'Entregado
    # a transporte', _tr_apply_carrier_status() calculaba changed=False y no
    # avisaba al cliente de la recoordinación.
    # Si el item YA estaba en un estado terminal (Entregado/Devolución) no lo
    # revertimos — cancelar la visita en ese punto es solo housekeeping, no
    # implica que el pedido "vuelva a bodega".
    estado_actual = (mi.get("estado_entrega") or "").strip()
    if estado_actual in ESTADOS_ENTREGA_TERMINALES:
        print(f"[simpliroute] item {item_id} ya estaba en estado terminal "
              f"{estado_actual!r}; se limpió la visita {vid} sin tocar el estado", flush=True)
    else:
        try:
            _tr_apply_carrier_status(item_id, 'En preparación', fuente='sistema',
                                     comentario='Visita SimpliRoute cancelada',
                                     notify_cliente=True)
        except Exception as _e_sr_cancel:
            print(f"[tr_event sr_cancelacion] item={item_id}: {_e_sr_cancel}", flush=True)

    return jsonify({"ok": True, "visit_id": vid})


@app.route("/transporte/api/items/<int:item_id>/simpliroute/reprogramar", methods=["PATCH"])
@_tr_required
def tr_item_simpliroute_reprogramar(item_id):
    """Intenta reprogramar la fecha planificada de la visita en SimpliRoute.

    SUPUESTO SIN VERIFICAR: SimpliRoute es Django REST Framework y los
    ViewSets DRF estándar suelen soportar PATCH parcial contra
    /v1/routes/visits/<id>/ — esto NO estaba probado en este proyecto antes
    de este cambio. Si la API rechaza el cambio (405/400/lo que sea), se
    informa HONESTAMENTE al usuario — nunca se reporta éxito falso. La fecha
    del manifiesto en ILUS no se toca: esto es informativo del lado del
    courier, no reasigna el item entre manifiestos.
    """
    import simpliroute_client as _src
    body = request.get_json(silent=True) or {}
    fecha = (body.get("fecha") or "").strip()
    if not fecha:
        return jsonify({"ok": False, "error": "Falta la fecha nueva."}), 400
    try:
        datetime.strptime(fecha, "%Y-%m-%d")
    except ValueError:
        return jsonify({"ok": False, "error": "Fecha inválida (formato esperado AAAA-MM-DD)."}), 400

    mi = mysql_fetchone("""
        SELECT mi.id, mi.simpliroute_visit_id, tm.courier
        FROM transport_manifest_items mi
        LEFT JOIN transport_manifests tm ON tm.id = mi.manifest_id
        WHERE mi.id=%s
    """, (item_id,))
    if not mi:
        return jsonify({"ok": False, "error": "Item no encontrado"}), 404

    vid = (mi.get("simpliroute_visit_id") or "").strip()
    if not vid:
        return jsonify({"ok": False,
                         "error": "Este pedido no tiene una visita activa en "
                                  "SimpliRoute para reprogramar."}), 400

    token = _simpliroute_token_for_courier(mi.get("courier"))
    if not token:
        return jsonify({"ok": False,
                         "error": "Falta configurar el token de SimpliRoute de "
                                  "este courier."}), 503

    try:
        r = _simpliroute_request("PATCH", f"{_src.EP_VISITS}{vid}/", token,
                                  payload={"planned_date": fecha}, timeout=20)
    except Exception as e:
        print(f"[simpliroute] excepción reprogramando visita {vid} (item {item_id}): {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo conectar con SimpliRoute. Intenta de nuevo."}), 502

    if not r.get("ok"):
        return jsonify({
            "ok": False,
            "error": "SimpliRoute rechazó la reprogramación por API "
                     f"({r.get('error') or 'error desconocido'}). Esta cuenta/plan "
                     "puede no soportar cambiar la fecha vía API — reprograma "
                     "manualmente desde el portal de SimpliRoute.",
        }), 502

    _tr_log("manifest_item", item_id, "visita SimpliRoute reprogramada",
            f"visita {vid} → nueva fecha {fecha}")

    return jsonify({"ok": True, "visit_id": vid, "fecha": fecha})


def _sr_visita_sin_entregar(v):
    """¿Esta visita sigue sin entregarse? (antes: _sr_visita_sin_planificar)

    CORRECCIÓN 2026-08-20, con medición contra la API real. El criterio
    anterior era "pending Y sin `route`", asumiendo que `route` aparece
    cuando el despachador asigna la visita a un vehículo. Medido en la
    cuenta de Felca ese día: de 7 visitas ENTREGADAS (status 'completed'),
    las 7 vienen con `route` en null. Felca no usa el módulo Router --
    marca las entregas directo desde la aplicación del chofer.

    O sea que `route` no distingue nada en esta cuenta, y el criterio viejo
    marcaba como "congelada" CADA entrega normal que todavía no ocurría.
    Una herramienta que grita por todo se aprende a ignorar.

    El criterio honesto es el estado, y nada más: 'pending' significa que el
    courier todavía no la tocó. Cualquier otro estado (on_its_way, completed,
    failed, partial, canceled) significa que ya pasó algo con ella.

    Lo que convierte a una visita pendiente en un PROBLEMA no es este
    predicado -- es que su día ya pasó. Eso lo decide quien llama (ver
    `vencida` en tr_simpliroute_visitas_congeladas).
    """
    if not isinstance(v, dict):
        return False
    return (v.get("status") or "").strip().lower() == "pending"


def _sr_quien_creo_la_visita(referencia):
    """'ILUS' | 'COURIER' | 'DESCONOCIDO' — según el FORMATO de la reference.

    2026-08-20, el hallazgo que explica todo. Medido contra la API real sobre
    los días 13, 14, 19 y 20 de agosto en la cuenta de Felca:

        reference con prefijo   (FCV-11303, BLV-23140)  -> la creó ILUS
            0 entregadas, 15 pendientes
        reference número pelado (11281, 23069)           -> la cargó Felca
            7 entregadas, 4 pendientes

    NINGUNA visita creada por ILUS se ha entregado jamás. Las entregas que el
    sistema registraba como éxito eran visitas del propio courier que ILUS
    adoptó después (_simpliroute_reconciliar_huerfanos las busca por
    reference y les escribe el visit_id en transport_manifest_items).

    ⚠️ POR ESO no sirve preguntarle a la base "¿es nuestra?": tener el
    visit_id guardado NO significa que la creamos nosotros. El único dato que
    lo distingue es el formato de la reference, porque el Excel del courier
    pone el nudo pelado en "Id de referencia" y build_visit_payload arma
    "TIDO-NUDO".
    """
    ref = (referencia or "").strip()
    if not ref:
        return "DESCONOCIDO"
    import re as _re
    if _re.match(r"^[A-Za-z]{2,4}-", ref):
        return "ILUS"
    if ref.replace("0", "").strip().isdigit() or ref.isdigit():
        return "COURIER"
    return "DESCONOCIDO"


@app.route("/transporte/api/simpliroute/visitas-congeladas", methods=["GET"])
@_tr_required
def tr_simpliroute_visitas_congeladas():
    """Visitas que ILUS creó en SimpliRoute y que siguen SIN PLANIFICAR.

    2026-08-18. Nace del levantamiento urgente: Alison subía los despachos
    con el botón, ILUS decía "creadas=1, errores=0", y la carga nunca salía.
    Medido contra la API ese día: las visitas existían pero estaban en
    'pending' sin chofer, varias con la fecha del manifiesto (un día ya
    cerrado) -- FCV 11286 llevaba 4,4 días así. Nadie tenía forma de verlo
    sin abrir cada pedido de a uno.

    SOLO LECTURA: lista y explica. No reprograma ni cancela nada -- para eso
    está el botón de rescate, que es una acción deliberada y auditada.

    Consulta el estado EN VIVO contra SimpliRoute (reusa _simpliroute_request,
    no duplica la llamada). Si la consulta de un item falla, ese item se
    reporta como 'desconocido' en vez de romper la respuesta entera.
    """
    import simpliroute_client as _src

    # 90 dias por default, no 14. Bug encontrado al ejecutar el rescate real
    # el 2026-08-18: BLV 22912 y BLV 22909 llevaban 14 dias congeladas y se
    # habian CAIDO SOLAS del listado justo al cumplirse la ventana. Los casos
    # mas viejos son los mas urgentes -- son los que llevan mas tiempo sin
    # llegarle al cliente -- y eran precisamente los que se escondian.
    # Una ventana angosta aca no ahorra nada: el costo real son las llamadas
    # a la API del courier, y esas ya estan topadas por el LIMIT 100.
    dias = request.args.get("dias", type=int) or 90
    dias = max(1, min(dias, 365))

    filas = mysql_fetchall("""
        SELECT mi.id AS item_id, mi.simpliroute_visit_id, mi.simpliroute_synced_at,
               tm.id AS manifest_id, tm.correlativo, tm.courier, tm.fecha AS fecha_manifiesto,
               c.tido, c.nudo, c.cliente_nombre, c.comuna
        FROM transport_manifest_items mi
        JOIN transport_manifests   tm ON tm.id = mi.manifest_id
        LEFT JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE NULLIF(TRIM(mi.simpliroute_visit_id), '') IS NOT NULL
          AND mi.estado_entrega NOT IN ('Entregado', 'Devolución')
          AND tm.fecha >= DATE_SUB(CURDATE(), INTERVAL %s DAY)
        ORDER BY tm.fecha ASC, mi.id ASC
        LIMIT 100
    """, (dias,)) or []

    hoy = _now_chile().date()
    congeladas, revisadas, sin_respuesta = [], 0, 0

    for f in filas:
        token = _simpliroute_token_for_courier(f.get("courier"))
        if not token:
            continue
        vid = (f.get("simpliroute_visit_id") or "").strip()
        r = _simpliroute_request("GET", f"{_src.EP_VISITS}{vid}/", token, timeout=15)
        revisadas += 1
        if not r.get("ok"):
            sin_respuesta += 1
            continue
        v = r.get("data")
        if not _sr_visita_sin_entregar(v):
            continue

        pd = (v.get("planned_date") or "").strip()
        try:
            dias_atras = (hoy - datetime.strptime(pd, "%Y-%m-%d").date()).days if pd else None
        except ValueError:
            dias_atras = None

        congeladas.append({
            "item_id": f["item_id"],
            "manifest_id": f["manifest_id"],
            "correlativo": f.get("correlativo"),
            "courier": f.get("courier"),
            "doc": _doc_label(f.get("tido"), f.get("nudo")),
            "cliente": f.get("cliente_nombre") or "—",
            "comuna": f.get("comuna") or "—",
            "visit_id": vid,
            "planned_date": pd,
            # Negativo = programada a futuro (normal). Positivo = quedó en un
            # día que ya pasó: ese es el caso grave, el tablero ya cerró.
            "dias_en_el_pasado": dias_atras,
            "vencida": bool(dias_atras is not None and dias_atras > 0),
            # Quien la creo, segun el FORMATO de la reference (2026-08-20).
            # Es el dato que explica el caso entero: las visitas con prefijo
            # (nuestras) no se entregan nunca; las de numero pelado (que carga
            # el courier) si. Ver _sr_quien_creo_la_visita.
            "origen": _sr_quien_creo_la_visita(v.get("reference")),
            "reference": (v.get("reference") or "").strip(),
        })

    vencidas = sum(1 for c in congeladas if c["vencida"])
    de_ilus = sum(1 for c in congeladas if c["origen"] == "ILUS")
    if not congeladas:
        resumen = "Todos los pedidos activos ya fueron entregados o el courier los tomó."
    else:
        # 2026-08-20: se dejo de decir "sin planificar". En esta cuenta el
        # courier no usa el modulo de rutas -- entrega directo desde la app --
        # asi que "planificada" no significa nada aca. Lo que si significa
        # algo es: sigue sin entregarse, y su dia ya paso.
        resumen = f"{len(congeladas)} pedido(s) siguen sin entregar"
        if vencidas:
            resumen += f", {vencidas} con la fecha ya vencida"
        resumen += "."

    return jsonify({
        "ok": True,
        "hoy": hoy.isoformat(),
        "revisadas": revisadas,
        "sin_respuesta": sin_respuesta,
        "congeladas": congeladas,
        "total_congeladas": len(congeladas),
        "total_vencidas": vencidas,
        "total_creadas_por_ILUS": de_ilus,
        "total_cargadas_por_COURIER": len(congeladas) - de_ilus,
        "dias_ventana": dias,
        "tope_alcanzado": len(filas) >= 100,
        "resumen": resumen,
    })


def _sr_fecha_rescate(valor, hoy):
    """Valida la fecha a la que se reprograma un rescate. Devuelve (fecha, error).

    2026-08-18. El rescate nacio reprogramando siempre a HOY, y eso lo hacia
    inutil despues del horario: a las 19:30 el tablero del despachador del dia
    ya cerro, asi que la visita "rescatada" a hoy amanecia vencida otra vez --
    el mismo bug que se estaba arreglando, en version diaria.

    Reglas:
      - Sin valor -> hoy (comportamiento previo, no se rompe ningun caller).
      - NUNCA al pasado: programar hacia atras es exactamente lo que dejaba las
        visitas invisibles. Es el error que este endpoint existe para reparar.
      - Tope de 30 dias: un dedazo tipo 2027-08-19 mandaria la carga a un ano
        que nadie va a mirar, y quedaria igual de perdida.
    """
    import datetime as _dt

    crudo = (str(valor or "")).strip()
    if not crudo:
        return hoy.isoformat(), None
    try:
        f = _dt.date.fromisoformat(crudo)
    except ValueError:
        return None, "Fecha inválida. Usa el formato AAAA-MM-DD."
    if f < hoy:
        return None, ("No se puede reprogramar al pasado — es justamente lo que "
                      "dejó estas visitas invisibles.")
    if (f - hoy).days > 30:
        return None, "La fecha está a más de 30 días. Revisa que no sea un error."
    return f.isoformat(), None


@app.route("/transporte/api/simpliroute/rescatar-congeladas", methods=["POST"])
@_tr_required
def tr_simpliroute_rescatar_congeladas():
    """Reprograma las visitas que quedaron atrapadas en un día vencido.

    2026-08-18. Acción de rescate para los despachos que se perdieron por el
    bug de la fecha (ver tr_manifiesto_subir_simpliroute). Reusa el MISMO
    PATCH que tr_item_simpliroute_reprogramar -- no reimplementa la llamada.

    Acepta `fecha` (AAAA-MM-DD) para elegir el día destino; sin ella, HOY.
    Rescatar "a hoy" a las 19:30 no sirve de nada: el tablero del despachador
    ya cerró y la visita amanece vencida de nuevo.

    Deliberadamente ACOTADO: solo toca visitas que (a) siguen en 'pending' y
    (b) su fecha YA VENCIÓ. Una visita programada a futuro, o que el courier
    ya tomó (cualquier estado distinto de 'pending'), no se toca nunca.

    2026-08-20: se quitó "no tienen chofer asignado" de este criterio. Medido
    contra la API, en la cuenta de Felca las visitas ENTREGADAS también vienen
    sin `route` -- el courier no usa el módulo de rutas, marca la entrega
    directo desde la app. Ese campo no distinguía nada acá.

    Cada reprogramación queda en la trazabilidad del item.
    """
    import simpliroute_client as _src

    body = request.get_json(silent=True) or {}
    item_ids = body.get("item_ids") or []
    if not isinstance(item_ids, list) or not item_ids:
        return jsonify({"ok": False,
                        "error": "Indica qué visitas rescatar (item_ids)."}), 400
    try:
        item_ids = [int(x) for x in item_ids][:100]
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "item_ids inválidos."}), 400

    hoy = _now_chile().date()
    destino_str, _err_fecha = _sr_fecha_rescate(body.get("fecha"), hoy)
    if _err_fecha:
        return jsonify({"ok": False, "error": _err_fecha}), 400
    _ph = ",".join(["%s"] * len(item_ids))
    filas = mysql_fetchall(f"""
        SELECT mi.id AS item_id, mi.simpliroute_visit_id, tm.courier,
               c.tido, c.nudo
        FROM transport_manifest_items mi
        JOIN transport_manifests   tm ON tm.id = mi.manifest_id
        LEFT JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE mi.id IN ({_ph})
          AND NULLIF(TRIM(mi.simpliroute_visit_id), '') IS NOT NULL
    """, tuple(item_ids)) or []

    resultados = []
    for f in filas:
        iid = f["item_id"]
        vid = (f.get("simpliroute_visit_id") or "").strip()
        doc = _doc_label(f.get("tido"), f.get("nudo"))
        token = _simpliroute_token_for_courier(f.get("courier"))
        if not token:
            resultados.append({"item_id": iid, "doc": doc, "ok": False,
                               "error": "Sin token para este courier."})
            continue

        # Re-verificar contra la API ANTES de tocar: el estado pudo cambiar
        # entre que se listó y que se apretó el botón, y no queremos mover
        # una visita que el courier ya planificó en el intertanto.
        rv = _simpliroute_request("GET", f"{_src.EP_VISITS}{vid}/", token, timeout=15)
        if not rv.get("ok"):
            resultados.append({"item_id": iid, "doc": doc, "ok": False,
                               "error": "No se pudo leer la visita en SimpliRoute."})
            continue
        v = rv.get("data") if isinstance(rv.get("data"), dict) else {}
        if not _sr_visita_sin_entregar(v):
            _estado = (v.get("status") or "—").strip() or "—"
            resultados.append({"item_id": iid, "doc": doc, "ok": False,
                               "error": f"Ya no está libre (estado '{_estado}') "
                                        f"— el courier la tomó. No se tocó."})
            continue
        if (v.get("planned_date") or "").strip() == destino_str:
            resultados.append({"item_id": iid, "doc": doc, "ok": False,
                               "error": f"Ya está programada para el {destino_str}."})
            continue

        r = _simpliroute_request("PATCH", f"{_src.EP_VISITS}{vid}/", token,
                                 payload={"planned_date": destino_str}, timeout=20)
        if not r.get("ok"):
            resultados.append({"item_id": iid, "doc": doc, "ok": False,
                               "error": r.get("error") or "SimpliRoute rechazó el cambio."})
            continue

        _tr_log("manifest_item", iid, "visita SimpliRoute rescatada",
                f"visita {vid}: {v.get('planned_date') or '—'} → {destino_str} "
                f"(estaba sin planificar en un dia vencido)")
        resultados.append({"item_id": iid, "doc": doc, "ok": True,
                           "visit_id": vid, "fecha_anterior": v.get("planned_date"),
                           "fecha": destino_str})

    ok_n = sum(1 for x in resultados if x.get("ok"))
    return jsonify({
        "ok": True, "fecha": destino_str, "hoy": hoy.isoformat(),
        "rescatadas": ok_n,
        "sin_cambio": len(resultados) - ok_n,
        "resultados": resultados,
    })


def _sr_planned_date_hoy():
    """La fecha con que nace una visita nueva en SimpliRoute: HOY, hora Chile.

    2026-08-18. Fuente unica de verdad. Existe porque el bug de PR #162 tenia
    DOS puertas y solo se cerro una: la subida del manifiesto ya usaba hoy,
    pero el reenvio (boton manual + redespacho automatico) seguia usando la
    fecha del MANIFIESTO, o sea un dia normalmente ya cerrado en el tablero
    del despachador. La visita nacia invisible, igual que FCV 11286.

    Hora Chile y NO UTC: una subida a las 21:30 en Chile es 01:30 UTC del dia
    siguiente -- el mismo bug con otro disfraz (REGLA #6).

    Criterio de Daniel: "el dia que se suben a SimpliRoute, porque ahi se
    estaria entregando al transporte". Subir = entregar la carga al courier.
    """
    return _now_chile().date().isoformat()


def _tr_simpliroute_reenviar_item(item_id, *, fuente_evento='sistema',
                                  comentario_evento=None, planned_date=None):
    """Recrea la visita SimpliRoute de UN item. FUNCIÓN COMPARTIDA.

    Extraída 2026-08-05 de lo que antes era el cuerpo de la ruta
    tr_item_simpliroute_reenviar: la usan tanto el botón manual como el
    redespacho automático (ver _tr_redespacho_automatico), así que la lógica
    de armar y mandar la visita vive UNA sola vez.

    Devuelve dict {ok, error?, visit_id?, tracking_id?} — NUNCA un Response de
    Flask, para poder llamarse desde código que no está atendiendo un request
    HTTP (el poller de estados, por ejemplo).
    """
    import simpliroute_client as _src
    mi = mysql_fetchone("""
        SELECT mi.id, mi.manifest_id, mi.simpliroute_visit_id, tm.courier, tm.fecha
        FROM transport_manifest_items mi
        LEFT JOIN transport_manifests tm ON tm.id = mi.manifest_id
        WHERE mi.id=%s
    """, (item_id,))
    if not mi:
        return {"ok": False, "error": "Item no encontrado"}
    if (mi.get("simpliroute_visit_id") or "").strip():
        return {"ok": False,
                "error": "Este pedido ya tiene una visita activa en "
                         "SimpliRoute. Cancélala primero si quieres re-crearla."}

    courier = (mi.get("courier") or "").strip()
    if not _simpliroute_courier_integra(courier):
        return {"ok": False, "error": f"El courier «{courier}» no trabaja con SimpliRoute."}
    token = _simpliroute_token_for_courier(courier)
    if not token:
        return {"ok": False,
                "error": "Falta configurar el token de SimpliRoute de este courier."}

    # La visita NACE con la fecha de hoy, no con la del manifiesto. Ese era
    # el bug de PR #162 entrando por la otra puerta: el manifiesto suele ser
    # de dias atras, y una visita en un dia cerrado no la ve nadie.
    # `planned_date` explicito solo lo usa el redespacho automatico, que
    # necesita el MISMO dia habil que ya le prometio al cliente.
    planned_date = (str(planned_date or "").strip() or _sr_planned_date_hoy())

    items = _tr_manifiesto_items_simpliroute(mi["manifest_id"])
    it = next((x for x in items if x.get("item_id") == item_id), None)
    if not it:
        return {"ok": False,
                "error": "No se encontraron los datos de esta factura para armar la visita."}

    payload, errores = _src.build_visit_payload(it, planned_date=planned_date)
    if errores:
        return {"ok": False, "error": "Datos incompletos: " + "; ".join(errores)}

    try:
        r = _simpliroute_request("POST", _src.EP_VISITS, token, payload=payload, timeout=30)
    except Exception as e:
        print(f"[simpliroute] excepción reenviando item {item_id}: {e}", flush=True)
        return {"ok": False, "error": "No se pudo conectar con SimpliRoute. Intenta de nuevo."}

    if not r.get("ok"):
        try:
            mysql_execute("UPDATE transport_manifest_items SET simpliroute_error=%s WHERE id=%s",
                          (str(r.get("error") or "Error desconocido")[:500], item_id))
        except Exception:
            pass
        return {"ok": False, "error": r.get("error") or "SimpliRoute rechazó la visita."}

    visita = (_src.parse_visits_response(r.get("data")) or [{}])[0]
    mysql_execute(
        "UPDATE transport_manifest_items SET simpliroute_visit_id=%s, "
        "simpliroute_tracking_id=%s, simpliroute_synced_at=NOW(), "
        "simpliroute_error=NULL WHERE id=%s",
        (str(visita.get("id") or "")[:40], str(visita.get("tracking_id") or "")[:60], item_id))
    _tr_log("manifest_item", item_id, "reenviado a SimpliRoute",
            f"nueva visita {visita.get('id')}")
    try:
        _tr_apply_carrier_status(item_id, 'Entregado a transporte', fuente=fuente_evento,
                                 comentario=comentario_evento or 'Visita re-creada en SimpliRoute',
                                 notify_cliente=True)
    except Exception as _e:
        print(f"[tr_event sr_reenvio] item={item_id}: {_e}", flush=True)

    return {"ok": True, "visit_id": visita.get("id"), "tracking_id": visita.get("tracking_id")}


@app.route("/transporte/api/items/<int:item_id>/simpliroute/reenviar", methods=["POST"])
@_tr_required
def tr_item_simpliroute_reenviar(item_id):
    """Reenvía UN item puntual a SimpliRoute como visita nueva (botón manual).

    Útil cuando la visita se acaba de cancelar (endpoint de arriba) o cuando
    la subida original del manifiesto falló y el item quedó con
    simpliroute_error. La lógica real vive en _tr_simpliroute_reenviar_item
    (compartida con el redespacho automático) — esta ruta solo traduce su
    resultado a una respuesta HTTP.
    """
    r = _tr_simpliroute_reenviar_item(item_id, fuente_evento='sistema')
    if not r.get("ok"):
        status = 404 if r.get("error") == "Item no encontrado" else \
                 400 if "ya tiene una visita" in (r.get("error") or "") else \
                 400 if "no trabaja con SimpliRoute" in (r.get("error") or "") else \
                 503 if "Falta configurar" in (r.get("error") or "") else \
                 400 if "Datos incompletos" in (r.get("error") or "") else 502
        return jsonify(r), status
    return jsonify(r)


@app.route("/transporte/api/items/<int:item_id>/simpliroute/desvincular-duplicado", methods=["POST"])
@_tr_required
def tr_item_simpliroute_desvincular_duplicado(item_id):
    """Desvincula LOCALMENTE la visita SimpliRoute de un item, SIN llamar a la
    API externa (a diferencia de .../cancelar, que sí la borra en SimpliRoute).

    BUG REAL (2026-08-10, Daniel: caso FCV 11240, manifiesto 17 vs 41 —
    "no puede decir entregado en el manifiesto antiguo... como lo actualicé
    en el otro manifiesto, se está ligando la información"). Cuando el mismo
    commitment queda en dos manifiestos (confirm_dup permite esto: la subida
    del manifiesto viejo falló de verdad y se re-agregó a uno nuevo que sí
    subió bien), _simpliroute_reconciliar_huerfanos podía pegarle al item del
    manifiesto VIEJO el mismo visit_id del NUEVO (arreglado hoy para que no
    vuelva a pasar — ver esa función). Ese visit_id sigue siendo una visita
    REAL que SimpliRoute gestiona para el despacho nuevo: llamar a
    .../cancelar la borraría también ahí. Este endpoint solo corrige la fila
    local equivocada, dejando la visita intacta donde de verdad corresponde.

    Por seguridad exige que el visit_id esté REALMENTE compartido con otra
    fila del mismo commitment en OTRO manifiesto — si no lo está, no es un
    caso de vinculación cruzada y no se puede usar para abandonar un
    seguimiento real (para eso está /cancelar).
    """
    mi = mysql_fetchone("""
        SELECT mi.id, mi.commitment_id, mi.manifest_id, mi.simpliroute_visit_id,
               mi.estado_entrega
        FROM transport_manifest_items mi
        WHERE mi.id=%s
    """, (item_id,))
    if not mi:
        return jsonify({"ok": False, "error": "Item no encontrado"}), 404

    vid = (mi.get("simpliroute_visit_id") or "").strip()
    if not vid:
        return jsonify({"ok": False, "error": "Este item no tiene una visita vinculada."}), 400

    compartido = mysql_fetchone("""
        SELECT mi2.id, mi2.manifest_id
        FROM transport_manifest_items mi2
        WHERE mi2.commitment_id=%s AND mi2.id<>%s
          AND mi2.simpliroute_visit_id=%s
        LIMIT 1
    """, (mi["commitment_id"], item_id, vid))
    if not compartido:
        return jsonify({"ok": False,
                         "error": "Esta visita no está compartida con otro manifiesto -- no es "
                                  "un caso de vinculación cruzada. Si quieres anular el "
                                  "seguimiento, usa «Cancelar visita»."}), 400

    mysql_execute(
        "UPDATE transport_manifest_items SET simpliroute_visit_id=NULL, "
        "simpliroute_tracking_id=NULL, simpliroute_synced_at=NULL, "
        "simpliroute_error=NULL WHERE id=%s", (item_id,))
    _tr_log("manifest_item", item_id, "vinculación cruzada de SimpliRoute corregida",
            f"visita {vid} desvinculada LOCALMENTE (sigue activa en el manifiesto "
            f"#{compartido['manifest_id']}, item {compartido['id']} -- esa es la vigente); "
            f"no se llamó a la API de SimpliRoute")

    estado_actual = (mi.get("estado_entrega") or "").strip()
    if estado_actual not in ESTADOS_ENTREGA_TERMINALES:
        try:
            _tr_apply_carrier_status(
                item_id, 'En preparación', fuente='sistema',
                comentario='Vinculación cruzada de SimpliRoute corregida (la visita real '
                           'sigue en otro manifiesto)',
                notify_cliente=False)
        except Exception as _e_desv:
            print(f"[tr_event sr_desvinc] item={item_id}: {_e_desv}", flush=True)

    return jsonify({"ok": True, "visit_id_liberado": vid,
                     "sigue_activa_en_manifiesto": compartido["manifest_id"]})


@app.route("/transporte/manifiestos/<int:mid>/export", methods=["GET"])
@_tr_required
def tr_manifiesto_export(mid):
    """Exporta el manifiesto como Excel de carga masiva según el courier:
      - fedex       → plantilla bulk FedEx (36 columnas)
      - simplyroute → plantilla SimplyRoute ("Felca y Milling")
      - generic     → planilla básica de respaldo

    Remitente FIJO (_tr_sender_cfg). Decisión de Daniel: tel/email faltantes
    NO bloquean el export — solo se resaltan en rojo (solo alertar).
    """
    try:
        return _tr_manifiesto_export_impl(mid)
    except Exception as e:
        import traceback, html as _htmlmod
        tb = traceback.format_exc()
        print(f"[manifiesto_export {mid}] ERROR:\n{tb}", flush=True)
        msg = _htmlmod.escape(f"{type(e).__name__}: {e}")
        # Página de error amigable (no extiende base.html para evitar cascada)
        return (f"""<!doctype html><html><head><meta charset="utf-8">
<title>Error exportando manifiesto</title>
<style>body{{font-family:system-ui,sans-serif;max-width:760px;margin:60px auto;padding:0 24px;color:#0a0a0a}}
.box{{background:#fff;border:1px solid #fee2e2;border-left:5px solid #dc2626;border-radius:12px;
padding:24px;box-shadow:0 6px 22px -10px rgba(220,38,38,.18)}}
h1{{color:#dc2626;font-size:1.25rem;margin:0 0 12px}}
pre{{background:#fee2e2;color:#7f1d1d;padding:10px 14px;border-radius:8px;font-size:.85rem;
overflow-x:auto;margin:14px 0 0}}
a{{color:#dc2626;font-weight:700;text-decoration:none}}
a:hover{{text-decoration:underline}}</style></head><body>
<div class="box">
<h1>⚠ No se pudo generar el export del manifiesto #{mid}</h1>
<p>El manifiesto está guardado, pero hubo un error al armar el Excel. Manda esta captura a soporte:</p>
<pre>{msg}</pre>
<p style="margin-top:18px"><a href="/transporte/manifiestos/{mid}">← Volver al manifiesto</a></p>
</div></body></html>""", 500)


@app.route("/transporte/api/manifiestos/<int:mid>/avisar-courier", methods=["POST"])
@_tr_required
def tr_manifiesto_avisar_courier(mid):
    """Le manda al courier el Excel del manifiesto -- el canal que SI entrega.

    ════════════════════════════════════════════════════════════════════
    POR QUE EXISTE ESTE BOTON (2026-08-20)
    ════════════════════════════════════════════════════════════════════
    Medido contra la API real de SimpliRoute, cuenta de Felca, sobre los dias
    13, 14, 19 y 20 de agosto:

        visitas creadas por ILUS (reference "FCV-11303")
            0 entregadas, 15 pendientes
        visitas cargadas por el courier con SU Excel (reference "11281")
            7 entregadas, 4 pendientes

    NINGUNA visita creada por ILUS se entrego jamas. Las entregas que el
    sistema registraba como exito eran del propio courier, adoptadas despues
    por la reconciliacion. Alison lo venia diciendo hace semanas: "aun no
    sube nada a transportes felca".

    La causa NO es el payload -- se descartaron con evidencia la conexion, la
    fecha, las habilidades y el peso. Es que la carga que mandamos por
    integracion queda FUERA del flujo de trabajo del courier: el trabaja desde
    el Excel que el mismo sube, y nadie le avisa que llegaron visitas por API.

    Este endpoint cierra ese hueco por el unico camino con entregas
    comprobadas: le manda EL MISMO Excel que el ya usa, adjunto al correo, y
    le arma a Alison un mensaje de WhatsApp listo para enviar.

    NO reemplaza la subida por API (REGLA #4.2: ese boton sigue donde estaba).
    Son dos canales; este es el que hoy funciona.

    ════════════════════════════════════════════════════════════════════
    LO QUE NO HACE
    ════════════════════════════════════════════════════════════════════
    NO manda el WhatsApp solo. Devuelve el link `wa.me` y Alison decide. Un
    mensaje a nombre de la empresa hacia un tercero es una accion deliberada
    de una persona, no el efecto colateral de un clic.

    Y NUNCA declara enviado un correo que no salio: si la llave de paso del
    modulo esta cerrada (marcha blanca), lo dice explicitamente y deja el
    WhatsApp igual disponible.

    Body opcional: {"solo_preview": true} -> arma todo y NO manda el correo.
    """
    man = mysql_fetchone("SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not man:
        return jsonify({"ok": False, "error": "Manifiesto no encontrado."}), 404

    courier = (man.get("courier") or "").strip()
    if not courier:
        return jsonify({"ok": False,
                        "error": "El manifiesto no tiene courier asignado."}), 400

    body = request.get_json(silent=True) or {}
    solo_preview = bool(body.get("solo_preview"))

    # ── Datos de contacto del courier ────────────────────────────────
    c = mysql_fetchone(
        "SELECT nombre, contacto, telefono, email FROM transport_couriers "
        "WHERE LOWER(nombre)=LOWER(%s) LIMIT 1", (courier,)) or {}
    email_courier = (c.get("email") or "").strip()
    telefono      = (c.get("telefono") or "").strip()
    contacto      = (c.get("contacto") or "").strip()

    # ── Que se le manda: los items del manifiesto ────────────────────
    items = mysql_fetchall("""
        SELECT COALESCE(cm.n_bultos, 1) AS n_bultos
          FROM transport_manifest_items mi
          LEFT JOIN transport_commitments cm ON cm.id = mi.commitment_id
         WHERE mi.manifest_id = %s
    """, (mid,)) or []
    n_docs = len(items)
    n_bultos = sum(int(i.get("n_bultos") or 1) for i in items)
    if not n_docs:
        return jsonify({"ok": False,
                        "error": "Este manifiesto no tiene pedidos que mandar."}), 400

    _f = man.get("fecha")
    fecha_label = (_f.strftime("%d/%m/%Y") if hasattr(_f, "strftime")
                   else _now_chile().date().strftime("%d/%m/%Y"))
    correlativo = man.get("correlativo") or f"MAN-{mid}"

    # ── El mensaje y el link de WhatsApp (siempre, aunque el correo falle) ──
    texto = _tr_texto_aviso_courier(
        courier=courier, correlativo=correlativo, n_docs=n_docs,
        n_bultos=n_bultos, fecha_label=fecha_label, contacto=contacto or None)
    link_wa = _tr_link_whatsapp(telefono, texto)

    resp = {
        "ok": True,
        "courier": courier,
        "contacto": contacto or None,
        "n_docs": n_docs,
        "n_bultos": n_bultos,
        "fecha": fecha_label,
        "texto_whatsapp": texto,
        "link_whatsapp": link_wa,
        "telefono": telefono or None,
        "email_courier": email_courier or None,
        "avisos": [],
    }
    if not link_wa and telefono:
        resp["avisos"].append(
            f"El teléfono guardado de {courier} («{telefono}») no sirve para "
            f"WhatsApp. Corrígelo en Couriers.")
    elif not telefono:
        resp["avisos"].append(
            f"{courier} no tiene teléfono guardado. Agrégalo en Couriers para "
            f"poder avisarle por WhatsApp.")

    if solo_preview:
        resp["correo_enviado"] = False
        resp["avisos"].append("Vista previa: no se mandó ningún correo.")
        return jsonify(resp)

    # ── El Excel: EL MISMO que el courier ya trabaja ─────────────────
    if not email_courier:
        resp["correo_enviado"] = False
        resp["avisos"].append(
            f"{courier} no tiene correo guardado, así que no se pudo mandar el "
            f"Excel. Agrégalo en Couriers, o baja el archivo con «Exportar "
            f"carga masiva» y mándalo tú.")
        return jsonify(resp)

    try:
        adjunto = _tr_manifiesto_export_impl(mid, devolver_bytes=True)
    except Exception as e:
        print(f"[avisar_courier] mid={mid}: no se pudo generar el Excel: {e}",
              flush=True)
        adjunto = None
    if not isinstance(adjunto, tuple):
        resp["correo_enviado"] = False
        resp["avisos"].append(
            "No se pudo generar el Excel del manifiesto. Prueba con «Exportar "
            "carga masiva»; si eso también falla, avísale a Daniel.")
        return jsonify(resp)

    xlsx_bytes, xlsx_nombre = adjunto
    cuerpo = (
        f"<p>Hola{(' ' + contacto) if contacto else ''},</p>"
        f"<p>Va la carga del manifiesto <strong>{correlativo}</strong>: "
        f"<strong>{n_docs}</strong> pedido(s), <strong>{n_bultos}</strong> "
        f"bulto(s), para el <strong>{fecha_label}</strong>.</p>"
        f"<p>Adjuntamos el Excel con el formato de SimpliRoute para que lo "
        f"subas directamente.</p>"
    )
    enviado = False
    try:
        enviado = _send_ilus_email(
            email_courier,
            _brand_subject(f"Carga para retirar — {correlativo}"),
            cuerpo,
            evento="manifiesto_avisar_courier",
            modulo="transporte",
            attachments=[(xlsx_nombre, xlsx_bytes,
                          "application/vnd.openxmlformats-officedocument."
                          "spreadsheetml.sheet")],
        )
    except Exception as e:
        print(f"[avisar_courier] mid={mid}: fallo el envio: {e}", flush=True)
        enviado = False

    resp["correo_enviado"] = bool(enviado)
    if enviado:
        _tr_log("manifest", mid, "manifiesto enviado al courier",
                f"Excel {xlsx_nombre} enviado a {email_courier} "
                f"({n_docs} doc, {n_bultos} bultos) por {current_username()}")
    else:
        # Nunca un verde sobre un correo que no salio.
        resp["avisos"].append(
            f"El correo a {courier} NO salió — puede ser que el canal del "
            f"módulo Transporte esté apagado. Manda el Excel por WhatsApp con "
            f"«Exportar carga masiva», o avísale a Daniel.")
    return jsonify(resp)


def _tr_texto_aviso_courier(*, courier, correlativo, n_docs, n_bultos, fecha_label,
                            contacto=None):
    """Mensaje para mandarle al courier por WhatsApp. Funcion PURA.

    2026-08-20. Nace del hallazgo de esta noche: medido contra la API, NINGUNA
    visita creada por ILUS se entrego jamas (0 de 15), mientras que las que el
    courier carga con su propio Excel si (7 de 11). No es un problema de
    payload: es que la carga que mandamos por integracion queda fuera del
    flujo de trabajo del courier y el no se entera de que llego.

    Este texto cierra ese hueco por el canal que el courier SI lee. Va con el
    Excel adjunto en el correo -- el mismo formato que el ya trabaja.

    REGLA #11: firma de marca, no el correo personal del operador.
    """
    partes = [f"🔧 {ILUS_BRAND} · Carga lista para retirar"]
    if contacto:
        partes.append(f"Hola {contacto},")
    partes.append(
        f"Te dejamos {n_docs} pedido(s) — {n_bultos} bulto(s) — para el "
        f"{fecha_label}.")
    partes.append(f"Manifiesto {correlativo}.")
    partes.append("Te mandamos el Excel al correo para que lo subas a SimpliRoute.")
    partes.append(f"— {ILUS_BRAND}")
    return "\n\n".join(partes)


def _tr_link_whatsapp(telefono, texto):
    """https://wa.me/<fono>?text=<texto> — o None si el fono no sirve.

    Se abre en el navegador de Alison con el mensaje ya escrito; ella decide
    si lo manda. NO se manda nada solo: mandar en nombre de la empresa a un
    tercero es una accion deliberada de una persona, no un efecto colateral
    de apretar un boton.
    """
    import re as _re
    import urllib.parse as _up

    fono = _re.sub(r"[^0-9]", "", str(telefono or ""))
    if not fono:
        return None
    if len(fono) == 9 and fono.startswith("9"):
        fono = "56" + fono              # celular chileno sin codigo de pais
    elif len(fono) == 8:
        fono = "569" + fono
    if len(fono) < 11:
        return None
    return "https://wa.me/" + fono + "?text=" + _up.quote(texto or "")


def _tr_manifiesto_export_impl(mid, *, devolver_bytes=False):
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment
    except Exception:
        flash("openpyxl no está instalado en el servidor.", "danger")
        return redirect(url_for("tr_manifiesto_detalle", mid=mid))
    from io import BytesIO
    from flask import send_file

    man = mysql_fetchone("SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not man:
        flash("Manifiesto no encontrado", "danger")
        return redirect(url_for("tr_manifiestos"))

    items = _tr_manifiesto_items_export(mid)
    if not items:
        flash("Este manifiesto no tiene items para exportar.", "warning")
        return redirect(url_for("tr_manifiesto_detalle", mid=mid))

    # Peso a declarar: única fuente de verdad en _peso_a_declarar() (módulo),
    # compartida con _tr_manifiesto_items_firma — ver ese docstring para el
    # porqué de la prioridad (override manual > predominante > max real/vol).
    _peso_declarar = _peso_a_declarar

    # Defensivo: si la columna formato_export aún no existe (ensure no corrió
    # o falló), no rompemos el export — caemos a la auto-detección por nombre.
    try:
        fmt_row = mysql_fetchone(
            "SELECT formato_export FROM transport_couriers WHERE LOWER(nombre)=LOWER(%s) LIMIT 1",
            (man.get("courier") or "",)
        )
        formato = ((fmt_row or {}).get("formato_export") or "").strip().lower()
    except Exception as _e_fmt:
        print(f"[manif_export] formato_export SELECT falló: {_e_fmt}", flush=True)
        formato = ""

    # Auto-detección por nombre del courier (robusto: no depende del seed
    # de init_transporte_tables, que en prod está skipeado). Daniel pidió que
    # el export SIEMPRE produzca el formato correcto para cargar al sistema
    # externo (SimplyRoute / FedEx Bulk / Clickex).
    if not formato or formato == "generic":
        _cname = (man.get("courier") or "").strip().lower()
        if "fedex" in _cname:
            formato = "fedex"
        elif "clickex" in _cname:
            formato = "clickex"
        elif "felca" in _cname or "milling" in _cname or "melling" in _cname:
            formato = "simplyroute"
        else:
            formato = "generic"

    wb = openpyxl.Workbook()
    ws = wb.active
    HDR_FILL  = PatternFill("solid", fgColor="0A0A0A")
    HDR_FONT  = Font(color="FFFFFF", bold=True)
    MISS_FILL = PatternFill("solid", fgColor="FEE2E2")  # rojo claro = dato faltante

    def _hdr(headers):
        for ci, h in enumerate(headers, 1):
            cell = ws.cell(1, ci, h)
            cell.font = HDR_FONT
            cell.fill = HDR_FILL
            cell.alignment = Alignment(horizontal="center", wrap_text=True)

    def _falta(v):
        return not str(v or "").strip()

    # Sanitiza strings para Excel: openpyxl lanza IllegalCharacterError si un
    # texto trae caracteres de control (llegan desde el ERP en notas/dirección/
    # observaciones). Los quitamos antes de escribir la celda. (Daniel 30/05/2026)
    import re as _re_xc
    _ILLEGAL_XLSX = _re_xc.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f]")
    def _xc(v):
        return _ILLEGAL_XLSX.sub("", v) if isinstance(v, str) else v

    # Helpers FedEx: la plantilla oficial limita ciertos campos a 35 chars
    # (senderContactName, senderLine1, senderLine2, recipientContactName,
    # recipientLine1, recipientLine2). Hay que truncar/dividir inteligente
    # para que FedEx no rechace la carga masiva.
    FEDEX_MAX = 35

    def _trunc(v, n=FEDEX_MAX):
        s = (v or "").strip()
        return s[:n]

    def _split_address(addr, n=FEDEX_MAX):
        """Divide una dirección larga en (line1, line2) sin cortar palabras.
        Si cabe en n chars → (addr, ''). Si no, busca el último espacio/coma
        antes del límite y rompe ahí; el resto va a line2 (también truncado a n).
        """
        s = (addr or "").strip()
        if len(s) <= n:
            return s, ""
        # Buscar último separador natural antes del límite
        cut = -1
        for sep in (", ", " - ", " "):
            cut = s.rfind(sep, 0, n)
            if cut > n // 2:  # evita cortes demasiado tempranos
                break
        if cut <= n // 2:
            cut = n  # fallback: corte duro
        line1 = s[:cut].rstrip(" ,-")
        line2 = s[cut:].lstrip(" ,-")[:n]
        return line1, line2

    if formato == "fedex":
        ws.title = "FedEx"
        s = _tr_sender_cfg()
        _hdr([
            "reference", "senderContactName", "senderCompany", "senderContactNumber",
            "senderEmail", "senderLine1", "senderLine2", "senderPostcode", "senderState",
            "senderCity", "senderCountry", "recipientContactName", "recipientCompany",
            "recipientContactNumber", "recipientEmail", "recipientLine1", "recipientLine2",
            "recipientLine3", "recipientPostcode", "recipientState", "recipientCity",
            "recipientCountry", "packageType", "numberOfPackages", "packageWeight",
            "weightUnits", "length", "width", "height", "serviceType", "currencyType",
            "recipientDeliveryNotification", "recipientExceptionNotification",
            "recipientShipAlertNotification", "recipientNotificationLanguageCode",
            "senderExceptionNotification",
        ])

        # DividirTextoInteligente — réplica exacta del helper VBA de Daniel.
        # Divide un texto en 2 partes respetando palabras y un límite máx por
        # parte. Si cabe entero, parte2='' (igual que la macro).
        def _dividir_texto_inteligente(txt, maxlen=FEDEX_MAX):
            s = (txt or "").strip()
            if len(s) <= maxlen:
                return s, ""
            cut = -1
            for sep in (" ", ", ", " - "):
                c = s.rfind(sep, 0, maxlen + 1)
                if c > maxlen // 2:
                    cut = c
                    break
            if cut <= maxlen // 2:
                cut = maxlen
            p1 = s[:cut].rstrip(" ,-")
            p2 = s[cut:].lstrip(" ,-")[:maxlen]
            return p1, p2

        # Sender FIJO — exactamente como columnas 2..11 de la macro VBA.
        sender_name  = _trunc(s["name"])
        sender_l1    = _trunc(s["line1"])
        sender_l2    = _trunc(s.get("line2", ""))

        # recipientEmail (col 15) — POR DEFECTO es dinámico: el correo REAL
        # del cliente (igual que siempre). Daniel 2026-06-16 (corrección):
        # la sustitución por un correo interno es SOLO para las pruebas de
        # carga masiva de ESTA sesión (evita que un cliente real reciba
        # notificaciones automáticas de FedEx — cols 32-35 — de un despacho
        # de prueba que no reconoce). NO es el comportamiento permanente.
        # Activar con ILUS_FEDEX_TEST_MODE=1 (apagado por defecto — mismo
        # patrón que ILUS_COMM_TEST_TO); quitar la env var cuando termine la
        # prueba y el export vuelve a mandar el correo real del cliente.
        _fedex_test_mode = os.environ.get("ILUS_FEDEX_TEST_MODE", "").strip().lower() in (
            "1", "true", "on", "yes", "si", "sí"
        )
        fedex_test_notify_email = os.environ.get(
            "ILUS_FEDEX_RECIPIENT_NOTIFY_EMAIL", "alison.mellado@sphs.cl"
        ).strip()

        for ri, it in enumerate(items, 2):
            nbult = max(1, int(it.get("n_bultos") or 1))
            peso_tot  = _peso_declarar(it)
            # PackageWeight (col 25) = peso TOTAL / nbultos = peso por bulto.
            # Mismo cálculo que la macro VBA línea: peso / bultos.
            ppp   = round(peso_tot / nbult, 3) if nbult else peso_tot
            # Recipient: nombre va a col 12 + col 13 (recipientCompany) si excede.
            rcp_l12, rcp_l13 = _dividir_texto_inteligente(it.get("cliente_nombre") or "")
            # Dirección: cols 16, 17, 18 — la macro VBA solo divide en 2, no
            # llena la 18. Mantenemos compatibilidad.
            # REVERTIDO 2026-07-22 (Daniel): la macro VBA original
            # (agregarfedexdirecto) llama DividirTextoInteligente SOLO con
            # frmAgregar.txtDireccion.Value — la dirección va SOLA, sin la
            # comuna pegada. Un primer Excel de referencia (01-04-2026)
            # sugería lo contrario ("Blasia 245, VIÑA DEL MAR"), pero un
            # segundo Excel más reciente (22-07-2026, "Zapallar 664", sin
            # comuna) y la macro confirman que esa concatenación era un caso
            # puntual, no la regla — se saca para que quede igual a la macro.
            _dir_raw    = (it.get("direccion") or "").strip()
            _comuna_raw = (it.get("comuna") or "").strip()
            rcp_l16, rcp_l17 = _dividir_texto_inteligente(_dir_raw)
            # Código postal del destinatario: tabla oficial FedEx por comuna
            # (réplica de BuscarCodigoPostal de la macro). Si falla, intenta
            # con cod_postal del item (lo que el ERP haya guardado) como
            # último recurso. Si tampoco, queda vacío y se marca en rojo.
            comuna_dest = _comuna_raw
            cp_dest = _codigo_postal_chile(comuna_dest) or (it.get("cod_postal") or "").strip()
            # ServiceType — réplica condición VBA: bultos < 68 → PRIORITY,
            # sino FREIGHT. (En la macro Daniel usa nbultos como umbral; lo
            # respetamos textualmente).
            service_type = "FEDEX_PRIORITY" if nbult < 68 else "FEDEX_PRIORITY_FREIGHT"
            # recipientEmail: correo real del cliente por defecto (dinámico);
            # solo en modo prueba se sustituye por el interno (ver arriba).
            recipient_email = fedex_test_notify_email if _fedex_test_mode else (it.get("email") or "")
            row = [
                it.get("nudo") or "",                                 # 1  reference
                sender_name, s["company"], s["phone"], s["email"],    # 2-5 sender contact
                sender_l1, sender_l2,                                 # 6-7 sender lines
                s["postcode"], s["state"], s["city"], s["country"],   # 8-11 sender geo
                rcp_l12, rcp_l13,                                     # 12-13 recipient name (split)
                it.get("telefono") or "", recipient_email,            # 14-15 recipient contact
                rcp_l16, rcp_l17, "",                                 # 16-18 recipient lines
                cp_dest, "CL",                                        # 19-20 recipient postcode/state
                _trunc(comuna_dest, 35), "CL",                        # 21-22 recipient city/country
                "YOUR_PACKAGING", nbult, ppp, "KGS",                  # 23-26 package
                1, 1, 1,                                              # 27-29 dimensions (cm)
                service_type, "CLP",                                  # 30-31 service + currency
                "Y", "Y", "Y", "ES", "Y",                             # 32-36 notifications
            ]
            for ci, v in enumerate(row, 1):
                ws.cell(ri, ci, _xc(v))
            # Resaltar campos críticos faltantes para que Daniel corrija antes de subir.
            if _falta(it.get("telefono")): ws.cell(ri, 14).fill = MISS_FILL
            # El correo faltante solo importa fuera de modo prueba (en modo
            # prueba la celda siempre trae el correo interno, nunca falta).
            if not _fedex_test_mode and _falta(it.get("email")):
                ws.cell(ri, 15).fill = MISS_FILL
            if not cp_dest:                ws.cell(ri, 19).fill = MISS_FILL  # FedEx rechaza sin CP
            if _falta(comuna_dest):        ws.cell(ri, 21).fill = MISS_FILL

    elif formato == "simplyroute":
        ws.title = "Felca y Milling"
        _hdr([
            "Título*   Requerido", "Dirección completa*   Requerido", "Carga",
            "Hora inicial", "Hora final", "Tiempo de servicio", "Notas", "Latitud",
            "Longitud", "Id de referencia", "Habilidades requeridas", "Habilidades KILOS",
            "Persona de contacto", "Teléfono de contacto", "Hora inicial 2", "Hora final 2",
            "Carga 2", "Carga 3", "Prioridad", "SMS", "Correo electrónico de contacto",
            "Carga pick", "Carga pick 2", "Carga pick 3", "Fecha programada", "Tipo de visita",
        ])
        for ri, it in enumerate(items, 2):
            nombre = (it.get("cliente_nombre") or "").strip()
            # 2026-08-17: sin los ceros de relleno del ERP. Este Excel es el que
            # se carga a mano en el panel de SimpliRoute, así que el "Título" y
            # el "Id de referencia" son literalmente lo que el despachador de
            # Felca ve y teclea. Tiene que coincidir con el número impreso en la
            # etiqueta de la caja (que desde hoy también va sin ceros) y con lo
            # que manda la conexión directa (simpliroute_client._nudo_limpio).
            nudo   = nudo_fmt_filter(it.get("nudo"))
            comuna = (it.get("comuna") or "").strip()
            dirc   = (it.get("direccion") or "").strip()
            peso   = round(_peso_declarar(it), 2)
            titulo = (f"{nudo} - {nombre}").strip(" -")
            row = [
                titulo, (f"{dirc} ,{comuna}").strip(" ,"),
                max(1, int(it.get("n_bultos") or 1)),
                "09:00:00", "23:59:00", 3, (it.get("notas") or ""), "", "",
                nudo, comuna, peso, nombre, it.get("telefono") or "",
                "", "", "", "", "", "", it.get("email") or "",
                "", "", "", "", "",
            ]
            for ci, v in enumerate(row, 1):
                ws.cell(ri, ci, _xc(v))
            if _falta(it.get("telefono")): ws.cell(ri, 14).fill = MISS_FILL
            if _falta(it.get("email")):    ws.cell(ri, 21).fill = MISS_FILL

    elif formato == "clickex":
        ws.title = "Clickex"
        # Formato Clickex (11 cols, tomado del .xlsx que entrega Clickex).
        _hdr([
            "Cliente", "Direccion", "Depto/Casa", "Comuna", "Referencia",
            "Telefono", "Correo", "Orden Seller", "Peso Total",
            "Monto Declarado", "Bultos",
        ])
        s = _tr_sender_cfg()
        seller = s.get("company") or "Sport and Health Solutions SPA"
        for ri, it in enumerate(items, 2):
            nbult = max(1, int(it.get("n_bultos") or 1))
            peso  = round(_peso_declarar(it), 2)
            valor = float(it.get("valor_bruto") or 0)
            row = [
                it.get("cliente_nombre") or "",
                it.get("direccion") or "",
                "",  # Depto/Casa (campo libre opcional)
                it.get("comuna") or "",
                it.get("nudo") or "",   # Referencia interna = nº documento
                it.get("telefono") or "",
                it.get("email") or "",
                seller,
                peso,
                valor,
                nbult,
            ]
            for ci, v in enumerate(row, 1):
                ws.cell(ri, ci, _xc(v))
            if _falta(it.get("telefono")): ws.cell(ri, 6).fill = MISS_FILL
            if _falta(it.get("email")):    ws.cell(ri, 7).fill = MISS_FILL

    else:  # generic
        ws.title = "Manifiesto"
        _hdr(["Documento", "Cliente", "Comuna", "Dirección", "Teléfono", "Email",
              "Peso (kg)", "Bultos"])
        for ri, it in enumerate(items, 2):
            row = [
                (f"{it.get('tido') or ''} {it.get('nudo') or ''}").strip(),
                it.get("cliente_nombre") or "", it.get("comuna") or "",
                it.get("direccion") or "", it.get("telefono") or "",
                it.get("email") or "", round(_peso_declarar(it), 2),
                max(1, int(it.get("n_bultos") or 1)),
            ]
            for ci, v in enumerate(row, 1):
                ws.cell(ri, ci, _xc(v))
            if _falta(it.get("telefono")): ws.cell(ri, 5).fill = MISS_FILL
            if _falta(it.get("email")):    ws.cell(ri, 6).fill = MISS_FILL

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    try:
        _tr_log("manifest", mid, "exportado", f"formato={formato} items={len(items)}")
    except Exception:
        pass
    safe_corr = (man.get("correlativo") or f"MAN{mid}").replace("/", "-")
    # Nombre estilo macro de Daniel: "Felca_30052026_13.24.xlsx",
    # "DocumentosFedEx_30052026_13.26.xlsx", "Clickex_..", "Milling_..".
    from datetime import datetime as _dt_now
    _stamp = _dt_now.now().strftime("%d%m%Y_%H.%M")
    if formato == "fedex":
        _fname = f"DocumentosFedEx_{_stamp}.xlsx"
    elif formato in ("simplyroute", "clickex"):
        # Para SimplyRoute usamos el nombre del courier (Felca/Milling); Clickex su propio.
        _parts = (man.get("courier") or "").strip().split()
        _courier = (_parts[-1] if _parts else "") or ("Clickex" if formato == "clickex" else "Manifiesto")
        _courier_clean = _courier.replace("/", "-").replace(" ", "_")
        _fname = f"{_courier_clean}_{_stamp}.xlsx"
    else:
        _fname = f"{safe_corr}_{formato}.xlsx"
    # 2026-08-20: mismo archivo, dos destinos. `devolver_bytes` lo pide el
    # boton "Mandar la carga al courier", que necesita adjuntarlo a un correo
    # en vez de bajarlo al navegador. Es EL MISMO Excel que el courier ya
    # usa y que demostradamente si se rutea -- no una variante nueva.
    if devolver_bytes:
        return buf.getvalue(), _fname
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True,
        download_name=_fname,
    )


# ═══════════════════════════════════════════════════════════════════════════
#  PANTALLA "DESPACHO AL COURIER" — pasos numerados con semáforo
#  (2026-08-22, pedido de Daniel: "enumerado y con semáforo, indicando que
#   todo está bien según los pasos que vas haciendo", como en Retiros)
#
#  REGLA DE ORO de esta pantalla: un paso solo se pinta VERDE cuando ILUS
#  puede demostrar la condición con un dato. Si no se pudo comprobar, se
#  pinta "sin comprobar" — JAMÁS verde. El caso que motivó todo esto: durante
#  meses la ficha decía "Ya subido a SimpliRoute" con un check verde, y
#  medido contra la API real el 20-08-2026, de 15 visitas creadas por ILUS
#  CERO se entregaron nunca. "Subida" no es "despachada": son dos pasos
#  distintos y acá se muestran separados (paso 4 vs paso 5).
#
#  100% ADITIVO: no se modifica ninguna ruta, endpoint ni botón existente.
# ═══════════════════════════════════════════════════════════════════════════

# Después de esta hora, subir al courier ya no alcanza su tablero del día.
# (hora Chile; mismo criterio que usa el rescate de visitas congeladas)
SR_HORA_CORTE_SUBIDA_H = 16
# A partir de esta hora, una visita que sigue sin ruta ya es un problema:
# el despachador del courier no la va a tomar hoy.
SR_HORA_LIMITE_PLANIFICACION_H = 17

# Estados crudos de SimpliRoute → castellano (REGLA #6/#0: nunca sale una
# palabra en inglés a pantalla).
_SR_ESTADO_ES = {
    "pending":     "Sin planificar",
    "on_its_way":  "En ruta",
    "in_progress": "En ruta",
    "completed":   "Entregada",
    "failed":      "No se pudo entregar",
    "partial":     "Entregada en parte",
    "canceled":    "Cancelada por el courier",
    "cancelled":   "Cancelada por el courier",
}


def _dsp_estado_courier_es(status_crudo):
    """Traduce el status de SimpliRoute. Si es uno que no conocemos, se
    devuelve tal cual pero marcado -- mejor mostrar algo raro que mentir."""
    s = (status_crudo or "").strip().lower()
    if not s:
        return "Sin dato"
    return _SR_ESTADO_ES.get(s, f"Estado no reconocido ({s})")


def _dsp_peor(estados):
    """El PEOR estado de una lista. El manifiesto completo siempre toma el
    peor de sus pedidos: 4 verdes y 3 trabados NO es un manifiesto verde."""
    for e in ("trabado", "sin_comprobar", "esperando", "ahora", "pendiente", "ok"):
        if e in estados:
            return e
    return "pendiente"


@app.route("/transporte/manifiestos/<int:mid>/despacho")
@_tr_required
def tr_manifiesto_despacho(mid):
    """Pantalla de pasos + semáforo para el despacho al courier."""
    man = mysql_fetchone(
        "SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not man or man.get("eliminado"):
        flash("Manifiesto no encontrado", "danger")
        return redirect(url_for("tr_manifiestos"))
    return render_template("transporte/manifiesto_despacho.html", manifiesto=man)


@app.route("/transporte/api/manifiestos/<int:mid>/despacho/estado")
@_tr_required
def tr_manifiesto_despacho_estado(mid):
    """SOLO LECTURA. Estado de los 6 pasos del despacho.

    ?live=0  → todo sale de MySQL, rápido. El paso 5 vuelve "sin_comprobar"
               (no se inventa: si no preguntamos, no sabemos).
    ?live=1  → además consulta cada visita a SimpliRoute para resolver el
               paso 5 de verdad. Reusa _simpliroute_request y
               _sr_visita_sin_entregar -- no abre otro canal HTTP.

    No escribe nada, ni en MySQL ni en el ERP ni en SimpliRoute.
    """
    import simpliroute_client as _src
    import datetime as _dt

    live = (request.args.get("live") or "0").strip() == "1"

    man = mysql_fetchone("SELECT * FROM transport_manifests WHERE id=%s", (mid,))
    if not man or man.get("eliminado"):
        return jsonify({"ok": False, "error": "Manifiesto no encontrado"}), 404

    ahora = _now_chile()
    hoy = ahora.date()
    corte_pasado = ahora.hour >= SR_HORA_CORTE_SUBIDA_H

    courier = (man.get("courier") or "").strip()
    integra = _simpliroute_courier_integra(courier)
    token = _simpliroute_token_for_courier(courier) if integra else None

    fila_courier = mysql_fetchone(
        "SELECT nombre, contacto, telefono, email, logo_url "
        "FROM transport_couriers WHERE LOWER(TRIM(nombre))=LOWER(TRIM(%s)) LIMIT 1",
        (courier,)) or {}

    items = mysql_fetchall("""
        SELECT mi.id AS item_id, mi.commitment_id, mi.estado_entrega,
               mi.simpliroute_visit_id, mi.simpliroute_error,
               mi.simpliroute_synced_at,
               mi.master_tracking_number, mi.tracking_number,
               c.tido, c.nudo, c.cliente_nombre, c.comuna, c.direccion,
               c.telefono, c.email,
               COALESCE(c.n_bultos, 1) AS n_bultos
        FROM transport_manifest_items mi
        JOIN transport_commitments c ON c.id = mi.commitment_id
        WHERE mi.manifest_id=%s
        ORDER BY mi.orden, mi.id
    """, (mid,)) or []

    total = len(items)
    n_bultos_total = sum(int(i.get("n_bultos") or 1) for i in items)

    # ── PASO 1 · Carga lista ────────────────────────────────────────────
    sin_bultos = [i for i in items if not i.get("n_bultos")]
    if total == 0:
        p1 = ("trabado", "Sin facturas",
              "Este manifiesto todavía no tiene facturas. Agrega al menos una "
              "antes de subir al courier.")
    elif sin_bultos:
        p1 = ("esperando", f"{len(sin_bultos)} sin bultos",
              f"Hay {len(sin_bultos)} factura(s) sin bultos declarados. Se van a "
              f"subir como 1 bulto cada una. Si son más, corrígelo antes de subir.")
    else:
        p1 = ("ok", f"{total} facturas · {n_bultos_total} bultos",
              "Listo. La carga está completa.")

    # ── PASO 2 · Transportista y fecha ──────────────────────────────────
    fecha_man = man.get("fecha")
    fecha_man_label = fecha_man.strftime("%d/%m/%Y") if fecha_man else "—"
    if not integra:
        p2 = ("trabado", "Otro camino",
              f"{courier or 'Este transportista'} no rutea con SimpliRoute. Para "
              f"este transportista el camino es descargar el Excel y mandárselo "
              f"por correo.")
    elif not token:
        p2 = ("trabado", "Sin conexión",
              f"No podemos entrar a la cuenta de {courier}: falta la clave de "
              f"acceso en el servidor. Avísale a Daniel. Mientras tanto, usa "
              f"«Exportar carga masiva».")
    elif corte_pasado:
        p2 = ("esperando", "Ya cerró el día",
              f"Son las {ahora.strftime('%H:%M')}. El tablero de hoy de {courier} "
              f"ya cerró: si subes ahora, la carga recién se va a ver mañana. "
              f"Conviene programarla para el próximo día hábil.")
    elif fecha_man and fecha_man != hoy:
        p2 = ("esperando", "Revisa la fecha",
              f"El manifiesto es del {fecha_man_label} y hoy es "
              f"{hoy.strftime('%d/%m/%Y')}. La visita se crea con la fecha de HOY, "
              f"porque hoy es el día en que le entregas la carga al transportista. "
              f"Una fecha que ya pasó queda invisible en su tablero.")
    else:
        p2 = ("ok", courier or "—",
              f"La visita se va a crear con fecha de hoy, {hoy.strftime('%d/%m/%Y')}.")

    # ── PASO 3 · Datos de entrega ───────────────────────────────────────
    sin_dir = [i for i in items
               if not (i.get("direccion") or "").strip()
               or not (i.get("comuna") or "").strip()]
    sin_tel = [i for i in items if not (i.get("telefono") or "").strip()]
    if total == 0:
        p3 = ("pendiente", "—", "Primero agrega facturas.")
    elif sin_dir:
        p3 = ("trabado", f"{len(sin_dir)} sin dirección",
              f"{len(sin_dir)} factura(s) no tienen dirección o comuna. Esas no se "
              f"van a subir: el courier no puede rutear un destino sin dirección.")
    elif sin_tel:
        p3 = ("esperando", f"{len(sin_tel)} sin teléfono",
              f"A {len(sin_tel)} factura(s) les falta el teléfono. Si el chofer no "
              f"encuentra el lugar, no va a tener a quién llamar.")
    else:
        p3 = ("ok", f"{total} de {total} con dirección",
              "Todas tienen dirección, comuna y contacto.")

    # ── PASO 4 · Subida al courier ──────────────────────────────────────
    subidos = [i for i in items if (i.get("simpliroute_visit_id") or "").strip()]
    con_error = [i for i in items if (i.get("simpliroute_error") or "").strip()]
    n_sub = len(subidos)
    if total == 0:
        p4 = ("pendiente", "—", "Primero agrega facturas.")
    elif con_error:
        p4 = ("trabado", f"{len(con_error)} con error",
              f"{len(con_error)} factura(s) no se pudieron subir. Revisa el detalle "
              f"de cada una más abajo y reintenta.")
    elif n_sub == 0:
        _listo_para_subir = p1[0] == "ok" and p2[0] in ("ok", "esperando") and p3[0] != "trabado"
        p4 = ("ahora" if _listo_para_subir else "pendiente", "Pendiente",
              f"Todavía no subes nada. Cuando aprietes el botón, ILUS crea una "
              f"visita por factura en la cuenta de {courier}.")
    elif n_sub < total:
        p4 = ("esperando", f"Subidas {n_sub} de {total}",
              f"Se subieron {n_sub} de {total}. Faltan {total - n_sub}.")
    else:
        p4 = ("ok", f"Subidas {total} de {total}",
              f"Las {total} visitas existen en la cuenta de {courier}. "
              f"Subida no es lo mismo que despachada: falta el paso 5.")

    # ── PASO 5 · El courier la planificó (el que hoy es invisible) ──────
    # Solo se resuelve de verdad con live=1. Sin consultar, es "sin_comprobar".
    por_item_p5 = {}
    sin_respuesta = 0
    if live and token and subidos:
        for it in subidos:
            vid = (it.get("simpliroute_visit_id") or "").strip()
            r = _simpliroute_request("GET", f"{_src.EP_VISITS}{vid}/", token, timeout=15)
            if not r.get("ok"):
                sin_respuesta += 1
                por_item_p5[it["item_id"]] = {
                    "estado": "sin_comprobar", "consultada_ok": False,
                    "estado_courier": "No pudimos preguntarle a " + (courier or "el courier"),
                    "planificada": None, "chofer": None,
                    "planned_date": None, "planned_date_label": None,
                    "dias_vencida": 0,
                }
                continue
            v = r.get("data") or {}
            sin_entregar = _sr_visita_sin_entregar(v)
            pd_raw = (v.get("planned_date") or "").strip()
            pd = None
            try:
                pd = _dt.date.fromisoformat(pd_raw) if pd_raw else None
            except Exception:
                pd = None
            dias_vencida = (hoy - pd).days if (pd and pd < hoy) else 0
            ruta = v.get("route") if isinstance(v.get("route"), dict) else None
            chofer = (ruta or {}).get("driver_name") or None

            if not sin_entregar:
                est = "ok"
            elif dias_vencida > 0:
                est = "trabado"
            elif ahora.hour >= SR_HORA_LIMITE_PLANIFICACION_H:
                est = "trabado"
            else:
                est = "esperando"

            por_item_p5[it["item_id"]] = {
                "estado": est, "consultada_ok": True,
                "estado_courier": _dsp_estado_courier_es(v.get("status")),
                "planificada": (not sin_entregar) or bool(chofer),
                "chofer": chofer,
                "planned_date": pd.isoformat() if pd else None,
                "planned_date_label": pd.strftime("%d/%m/%Y") if pd else None,
                "dias_vencida": dias_vencida,
            }

    if total == 0:
        p5 = ("pendiente", "—", "Primero agrega facturas.")
    elif n_sub == 0:
        p5 = ("pendiente", "—", "Todavía no hay visitas creadas.")
    elif not live:
        p5 = ("sin_comprobar", "Sin comprobar",
              "No le hemos preguntado a " + (courier or "el courier") + " todavía. "
              "Aprieta «Comprobar ahora».")
    else:
        _ests = [v["estado"] for v in por_item_p5.values()]
        _peor5 = _dsp_peor(_ests) if _ests else "sin_comprobar"
        _n_trab = sum(1 for e in _ests if e == "trabado")
        _n_ok5 = sum(1 for e in _ests if e == "ok")
        if _peor5 == "trabado":
            p5 = ("trabado", f"{_n_trab} trabadas",
                  f"{_n_trab} visita(s) siguen sin que nadie de {courier} las meta "
                  f"en una ruta. Este paso NO lo hace ILUS: lo hace el despachador "
                  f"del courier.")
        elif _peor5 == "sin_comprobar":
            p5 = ("sin_comprobar", f"{sin_respuesta} sin respuesta",
                  f"No pudimos comprobar {sin_respuesta} visita(s). No sabemos si "
                  f"{courier} las tomó.")
        elif _peor5 == "esperando":
            p5 = ("esperando", f"{_n_ok5} de {n_sub} con ruta",
                  f"Esperando que {courier} las planifique. Todavía dentro de lo normal.")
        else:
            p5 = ("ok", f"{_n_ok5} de {n_sub} con ruta",
                  f"{courier} ya las metió en ruta.")

    # ── PASO 6 · Entregada al cliente ───────────────────────────────────
    n_entregados = sum(1 for i in items if (i.get("estado_entrega") or "") == "Entregado")
    n_problema = sum(1 for i in items
                     if (i.get("estado_entrega") or "") in ("Problema", "Entrega fallida"))
    if total == 0:
        p6 = ("pendiente", "—", "Primero agrega facturas.")
    elif n_problema:
        p6 = ("trabado", f"{n_problema} con problema",
              f"{n_problema} entrega(s) fallaron o tienen un problema reportado.")
    elif n_entregados == total:
        p6 = ("ok", f"{total} de {total} entregadas",
              "Manifiesto completo: todos los pedidos llegaron al cliente.")
    elif n_entregados:
        p6 = ("esperando", f"{n_entregados} de {total} entregadas",
              f"Van {n_entregados} de {total}.")
    else:
        p6 = ("pendiente", "Sin entregas aún",
              "Ninguna entrega confirmada todavía.")

    _defs = [
        (1, "carga",        "Carga lista en bodega",
         "Las facturas que van en este despacho, con sus bultos contados.", p1),
        (2, "courier",      "Transportista y fecha",
         "A quién le entregas la carga y con qué fecha aparece en su tablero.", p2),
        (3, "datos",        "Datos de entrega completos",
         "Dirección, comuna y un teléfono. Sin eso el courier no puede rutear.", p3),
        (4, "subida",       "Subida al courier",
         "Crea la visita de cada factura en la cuenta del courier.", p4),
        (5, "planificada",  "El courier la planificó",
         "Este paso NO lo hace ILUS. Lo hace el despachador del courier cuando "
         "mete la visita en la ruta de un chofer. Hasta que eso pase, la carga "
         "no sale de bodega.", p5),
        (6, "entregada",    "Entregada al cliente",
         "El chofer marcó la entrega y quedó la firma o la foto.", p6),
    ]
    pasos = [{"n": n, "clave": clave, "titulo": tit, "subtitulo": sub,
              "estado": est[0], "badge": est[1], "detalle": est[2]}
             for (n, clave, tit, sub, est) in _defs]

    # ── Estado por pedido ───────────────────────────────────────────────
    pedidos = []
    for it in items:
        iid = it["item_id"]
        _sub_ok = bool((it.get("simpliroute_visit_id") or "").strip())
        _err = (it.get("simpliroute_error") or "").strip()
        _ee = (it.get("estado_entrega") or "")
        _falta_dir = (not (it.get("direccion") or "").strip()
                      or not (it.get("comuna") or "").strip())

        e1 = "ok" if it.get("n_bultos") else "esperando"
        e2 = p2[0]
        e3 = "trabado" if _falta_dir else ("esperando" if not (it.get("telefono") or "").strip() else "ok")
        if _err:
            e4 = "trabado"
        elif _sub_ok:
            e4 = "ok"
        else:
            e4 = "pendiente"
        v5 = por_item_p5.get(iid)
        e5 = v5["estado"] if v5 else ("pendiente" if not _sub_ok else "sin_comprobar")
        if _ee == "Entregado":
            e6 = "ok"
        elif _ee in ("Problema", "Entrega fallida"):
            e6 = "trabado"
        elif _ee in ("En ruta", "Entregado a transporte"):
            e6 = "esperando"
        else:
            e6 = "pendiente"

        _mapa = {1: e1, 2: e2, 3: e3, 4: e4, 5: e5, 6: e6}
        # El paso ACTUAL es el primero que no está ok; si todos ok, es el 6.
        _actual = next((k for k in range(1, 7) if _mapa[k] != "ok"), 6)
        _estado_pedido = _dsp_peor(list(_mapa.values()))

        if _err:
            titular = "No se pudo subir"
            detalle = _err[:300]
        elif v5 and v5["estado"] == "trabado":
            _d = v5.get("dias_vencida") or 0
            titular = f"Esperando a {courier}" + (f" · {_d} día(s)" if _d else "")
            detalle = ("La visita está creada pero nadie la metió en una ruta"
                       + (f", y su fecha ({v5['planned_date_label']}) ya pasó."
                          if v5.get("planned_date_label") and _d else "."))
        elif v5 and v5["estado"] == "sin_comprobar":
            titular = "Sin comprobar"
            detalle = f"No pudimos preguntarle a {courier} por esta visita."
        elif _falta_dir:
            titular = "Falta la dirección"
            detalle = "Sin dirección o comuna, esta factura no se puede subir."
        elif _ee == "Entregado":
            titular = "Entregada"
            detalle = "El cliente ya la recibió."
        elif _sub_ok:
            titular = "Subida, esperando ruta"
            detalle = f"La visita existe en {courier}. Falta que la planifiquen."
        else:
            titular = "Lista para subir"
            detalle = "Todavía no se crea la visita en el courier."

        pedidos.append({
            "item_id": iid,
            "commitment_id": it.get("commitment_id"),
            # _doc_label quita los ceros de relleno del ERP ("0000011329" ->
            # "11329"). Pedido de Daniel el 05-08: "la factura tiene cualquier
            # cero, sería ideal que no tuviera". Se reusa el helper que ya
            # existe para que esta pantalla diga el número igual que el resto
            # de la app, y no aparezca un formato nuevo.
            "doc": _doc_label(it.get("tido"), it.get("nudo")),
            "cliente": it.get("cliente_nombre") or "—",
            "comuna": it.get("comuna") or "—",
            "n_bultos": int(it.get("n_bultos") or 1),
            "paso_actual": _actual,
            "estado": _estado_pedido,
            "pasos": {str(k): v for k, v in _mapa.items()},
            "titular": titular,
            "detalle": detalle,
            "visita": v5,
        })

    resumen = {
        "ok":            sum(1 for p in pedidos if p["estado"] == "ok"),
        "esperando":     sum(1 for p in pedidos if p["estado"] in ("esperando", "ahora")),
        "trabados":      sum(1 for p in pedidos if p["estado"] == "trabado"),
        "sin_comprobar": sum(1 for p in pedidos if p["estado"] == "sin_comprobar"),
        "pendientes":    sum(1 for p in pedidos if p["estado"] == "pendiente"),
    }
    _peor_global = _dsp_peor([p["estado"] for p in pedidos]) if pedidos else "pendiente"
    _peor_paso = next((p["n"] for p in pasos if p["estado"] == _peor_global), None)

    # El veredicto NUNCA es verde por "se crearon N visitas sin errores".
    if resumen["trabados"]:
        _nom = next((p["titulo"] for p in pasos if p["n"] == _peor_paso), "")
        veredicto = {
            "estado": "trabado",
            "texto": f"{resumen['trabados']} de {total} pedidos están trabados"
                     + (f" en el paso {_peor_paso} — {_nom}." if _peor_paso else "."),
        }
    elif resumen["sin_comprobar"]:
        veredicto = {
            "estado": "sin_comprobar",
            "texto": f"No pudimos comprobar {resumen['sin_comprobar']} de {total} "
                     f"pedidos. No sabemos si {courier} los tomó.",
        }
    elif resumen["esperando"]:
        veredicto = {
            "estado": "esperando",
            "texto": f"{resumen['esperando']} de {total} pedidos están esperando "
                     f"que {courier} los planifique.",
        }
    elif total and n_entregados == total:
        veredicto = {"estado": "ok",
                     "texto": f"Manifiesto completo: los {total} pedidos llegaron al cliente."}
    elif total and resumen["ok"] == total:
        veredicto = {"estado": "ok",
                     "texto": f"Los {total} pedidos ya tienen chofer asignado en {courier}."}
    else:
        veredicto = {"estado": "pendiente",
                     "texto": "Todavía no arranca el despacho de este manifiesto."}

    return jsonify({
        "ok": True,
        "live": live,
        "hoy": hoy.isoformat(),
        "hoy_label": hoy.strftime("%d/%m/%Y"),
        "hora_chile": ahora.strftime("%H:%M"),
        "corte_pasado": corte_pasado,
        "courier": {
            "nombre": courier or "—",
            "integra": bool(integra),
            "token_ok": bool(token),
            "telefono": (fila_courier.get("telefono") or "").strip() or None,
            "contacto": (fila_courier.get("contacto") or "").strip() or None,
            "email": (fila_courier.get("email") or "").strip() or None,
        },
        "manifiesto": {
            "id": mid,
            "correlativo": man.get("correlativo") or f"#{mid}",
            "fecha": fecha_man.isoformat() if fecha_man else None,
            "fecha_label": fecha_man_label,
            "n_items": total,
            "n_bultos": n_bultos_total,
        },
        "pasos": pasos,
        "pedidos": pedidos,
        "resumen": resumen,
        "veredicto": veredicto,
        "sin_respuesta": sin_respuesta,
    })


# ── MANIFIESTOS: asignar compromiso desde drag-drop ──────────────────────────

@app.route("/transporte/api/manifiestos/asignar", methods=["POST"])
@_tr_required
def tr_asignar_a_manifiesto():
    """Asigna uno o más compromisos a un manifiesto (crea si mid=None).

    FIX 2026-07-28 (levantamiento del "llamado de manifiesto" — Daniel:
    "el llamado de manifiesto lo veo un poco desordenado"). Este endpoint es
    el que usa el Panel Manifiesto del Monitor (arrastre, botón 📋, FAB) —
    el camino que Daniel más usa — y tenía 5 defectos confirmados leyendo
    el código, corregidos todos acá:
      H1  (CRÍTICO) el botón "Crear manifiesto" devolvía 500 SIEMPRE:
          `cur.fetchone()[0]` con DictCursor lanza KeyError, y
          `current_user.correo` era NameError (no existe ese nombre en
          todo app.py). Se reemplaza por current_username() + el mismo
          generador de correlativo (con reintento anti-race) que ya usa
          tr_crear_manifiesto.
      H2  el correlativo salía en formato viejo 'MAN0001', distinto del
          'MAN-2026-0001' que usa el resto del sistema.
      H6  no avisaba si el documento ya estaba en OTRO manifiesto (sí lo
          hace tr_agregar_item desde 2026-07-26); ahora avisa igual acá.
      H10 no aplicaba el guard de "manifiesto ya en gestión con el
          courier" al agregar a un manifiesto EXISTENTE.
      H11 solo recalculaba total_items, dejando costo_total desactualizado
          (por eso el listado y la ficha podían mostrar montos distintos).
    """
    data         = request.get_json(silent=True) or {}
    commitment_ids = data.get("commitment_ids", [])
    mid          = data.get("manifest_id")     # None → crear nuevo
    # PR-B (2026-08-01): normalizar a int temprano -- antes `mid` solo se
    # usaba en SQL parametrizado (MySQL coerciona string/int igual), pero
    # ahora también se compara en Python puro contra
    # transport_manifest_items.manifest_id (int) dentro de
    # _tr_plan_ramo_manifest_item -- si el frontend mandara "5" (string) en
    # vez de 5, esa comparación fallaría en silencio y el candado de ramos
    # nunca dispararía.
    try:
        mid = int(mid) if mid not in (None, "") else None
    except (TypeError, ValueError):
        return jsonify({"error": "manifest_id inválido"}), 400
    confirm_dup  = bool(data.get("confirm_dup"))

    if not commitment_ids:
        return jsonify({"error": "sin compromisos"}), 400

    # H10: si se agrega a un manifiesto EXISTENTE que ya está en gestión con
    # el courier (o con prueba de entrega firmada), aplica la misma guarda
    # que ya protege a tr_agregar_item/tr_quitar_item.
    aviso_actividad = None
    if mid:
        _bloqueo, aviso_actividad = _tr_manifiesto_guard_actividad(mid)
        if _bloqueo:
            return _bloqueo

    # PR-B (Fase 1, 2026-08-01): "duplicado" es ramo-aware. Antes (H6) se
    # avisaba "ya está en otro manifiesto" para CUALQUIER otro ramo del
    # mismo documento -- eso bloqueaba (con un mensaje que ni mencionaba
    # ramo) el flujo NUEVO y legítimo de asignar cada ramo a su propio
    # manifiesto. Ahora se distingue:
    #   - mismo ramo ya en OTRO manifiesto  = "duplicado" legacy (preexistente,
    #     confirm_dup lo saltea, igual que siempre).
    #   - 2+ ramos sin asignar y sin forma de saber cuál se quiere = ambiguo
    #     (este endpoint no tiene granularidad de línea -- ver
    #     "Líneas pendientes" para ese caso).
    # Nota (corrección 2026-08-01, Daniel en vivo): un ramo DISTINTO del
    # mismo documento en ESTE manifiesto destino ya NO es un conflicto --
    # despacho+instalación normalmente van en el mismo viaje.
    try:
        _cids_int = sorted({int(x) for x in commitment_ids})
    except (TypeError, ValueError):
        return jsonify({"error": "commitment_ids inválido"}), 400

    _items_batch = _tr_items_existentes_batch(_cids_int)
    _planes = {cid: _tr_plan_ramo_manifest_item(_tr_ramos_de_commitment(cid), _items_batch.get(cid, []), mid)
               for cid in _cids_int}

    _conflictos_bloqueantes = [(cid, p) for cid, p in _planes.items()
                                if p["accion"] == "conflicto_multi_ramo"]
    if _conflictos_bloqueantes:
        _doc_rows = mysql_fetchall(
            "SELECT id, tido, nudo FROM transport_commitments WHERE id IN (" +
            ",".join(["%s"] * len(_conflictos_bloqueantes)) + ")",
            tuple(cid for cid, _ in _conflictos_bloqueantes)
        ) or []
        _doc_by_id = {r["id"]: f"{r.get('tido') or ''} {r.get('nudo') or ''}".strip() for r in _doc_rows}
        _detalle = [
            {"commitment_id": cid, "doc": _doc_by_id.get(cid, ""), **_tr_resp_conflicto_multi_ramo(p)}
            for cid, p in _conflictos_bloqueantes
        ]
        return jsonify({
            "ok": False,
            "error": "ramo_conflicto",
            "msg": f"{len(_conflictos_bloqueantes)} documento(s) tienen un conflicto de ramo -- "
                   "revisa el detalle de cada uno.",
            "conflictos": _detalle,
        }), 409

    if not confirm_dup:
        _duplicados = [(cid, p) for cid, p in _planes.items() if p["accion"] == "duplicado"]
        if _duplicados:
            _doc_rows = mysql_fetchall(
                "SELECT id, tido, nudo FROM transport_commitments WHERE id IN (" +
                ",".join(["%s"] * len(_duplicados)) + ")",
                tuple(cid for cid, _ in _duplicados)
            ) or []
            _doc_by_id = {r["id"]: r for r in _doc_rows}
            return jsonify({
                "ok": False,
                "error": "duplicado",
                "msg": f"{len(_duplicados)} documento(s) ya están en otro manifiesto (mismo ramo).",
                "duplicados": [
                    {"commitment_id": cid,
                     "doc": f"{(_doc_by_id.get(cid) or {}).get('tido','')} "
                            f"{(_doc_by_id.get(cid) or {}).get('nudo','')}".strip(),
                     "ramo": p["ramo"], "manifest_id": p["otro_manifest_id"]}
                    for cid, p in _duplicados
                ],
            }), 409

    conn = get_db()
    with conn.cursor() as cur:
        # crear manifiesto nuevo si no se indicó uno — mismo generador
        # anti-race que tr_crear_manifiesto (ver _tr_next_manifest_correlativo_candidato).
        if not mid:
            courier = data.get("courier", "Por asignar")
            fecha   = data.get("fecha") or __import__("datetime").date.today().isoformat()
            correlativo = None
            for _intento in range(5):
                candidato = _tr_next_manifest_correlativo_candidato(cur)
                try:
                    cur.execute(
                        """INSERT INTO transport_manifests (correlativo, fecha, courier, created_by)
                           VALUES (%s,%s,%s,%s)""",
                        (candidato, fecha, courier, current_username()),
                    )
                    correlativo = candidato
                    mid = cur.lastrowid
                    break
                except Exception as e_corr:
                    msg = str(e_corr)
                    if ("1062" in msg or "Duplicate entry" in msg) and "correlativo" in msg:
                        conn.rollback()
                        continue
                    raise
            if mid is None:
                conn.rollback()
                return jsonify({
                    "ok": False,
                    "error": "No se pudo generar un correlativo único para el manifiesto, "
                             "intenta de nuevo.",
                }), 409
        else:
            correlativo = None

        added, dupes = 0, 0
        nuevos_items = []  # (manifest_item_id, commitment_id) recién asignados
        # PR-B: usa el ramo que ya decidió _tr_plan_ramo_manifest_item arriba
        # (precalculado ANTES de crear/tocar el manifiesto -- no se
        # recalcula acá para no divergir del pre-chequeo que ya descartó
        # conflictos ambiguos) -- por eso alcanza con `.get("ramo")`.
        for cid in _cids_int:
            ramo_final = _planes.get(cid, {}).get("ramo") or "despacho"
            try:
                cur.execute(
                    """INSERT IGNORE INTO transport_manifest_items
                       (manifest_id, commitment_id, ramo) VALUES (%s,%s,%s)""",
                    (mid, cid, ramo_final),
                )
                if cur.rowcount:
                    added += 1
                    nuevos_items.append((cur.lastrowid, cid))
                else:
                    dupes += 1
            except Exception:
                dupes += 1

        # H11: recalcular TODOS los totales (antes solo total_items, y
        # costo_total quedaba viejo — mismo fix que ya se aplicó a
        # tr_quitar_item/tr_agregar_item, ahora también acá).
        _tr_recalc_totales_manifiesto(cur, mid)

    conn.commit()

    # 2026-06-14 (Daniel): avisar al cliente "tu pedido está en preparación" por
    # cada factura RECIÉN asignada. El item nace 'En preparación' (default del
    # ENUM), así que emitimos el evento de notificación directo (no hay cambio
    # de estado que dispare _tr_apply_carrier_status). El anti-spam (600s) +
    # clave por commitment evita duplicados si la factura tiene varias líneas.
    for _mi_id, _cid in nuevos_items:
        try:
            _tr_event(_mi_id, 'En preparación', fuente='sistema',
                      commitment_id=_cid, notify_cliente=True)
        except Exception as _e_prep:
            print(f"[tr_event preparacion] item={_mi_id}: {_e_prep}", flush=True)

    # Auditoría (H: antes A no dejaba NINGÚN registro de "se agregaron N
    # facturas" — a diferencia de tr_agregar_item, que sí loguea legible).
    if added:
        _tr_log("manifest", mid, "facturas agregadas (panel)",
                f"{added} agregada(s), {dupes} ya estaban en este manifiesto")

    resp = {"ok": True, "manifest_id": mid, "correlativo": correlativo,
            "added": added, "duplicados": dupes}
    if aviso_actividad:
        resp["aviso"] = aviso_actividad
    return jsonify(resp)


# ════════════════════════════════════════════════════════════════════════
#  CUBICADOR → MANIFIESTO
#  Endpoint para enviar el resultado de la cotización del cubicador
#  directamente a un manifiesto (existente o nuevo).
# ════════════════════════════════════════════════════════════════════════

@app.route("/transporte/api/manifiestos/abiertos", methods=["GET"])
@_tr_required
def tr_manifiestos_abiertos():
    """Devuelve manifiestos abiertos para el selector del cubicador.

    Estados considerados "abiertos": 'En preparación', 'En curso'.

    Query params:
      ?courier=Nombre  → filtra ESTRICTAMENTE los del mismo courier.
                         Decisión Daniel (2026-05-31): Clickex no puede mezclar
                         con Milling/Felca. Cada manifiesto = un solo courier.
      ?strict=0        → modo legacy: solo ORDENA por courier preferido pero
                         devuelve todos (para vistas administrativas).
    """
    courier_pref = (request.args.get("courier") or "").strip()
    strict = request.args.get("strict", "1") != "0"  # default estricto
    try:
        if strict and courier_pref:
            rows = mysql_fetchall("""
                SELECT id, correlativo, fecha, courier, estado,
                       COALESCE(total_items, 0) AS total_items,
                       COALESCE(costo_total, 0) AS costo_total
                  FROM transport_manifests
                 WHERE estado IN ('En preparación','En curso')
                   AND LOWER(TRIM(courier)) = LOWER(TRIM(%s))
                 ORDER BY fecha DESC, id DESC
                 LIMIT 50
            """, (courier_pref,)) or []
            # Conteo de "otros couriers" para mostrar info al operador
            other_row = mysql_fetchone("""
                SELECT COUNT(*) AS n FROM transport_manifests
                 WHERE estado IN ('En preparación','En curso')
                   AND LOWER(TRIM(courier)) <> LOWER(TRIM(%s))
            """, (courier_pref,)) or {}
            other_count = int(other_row.get("n") or 0)
        else:
            rows = mysql_fetchall("""
                SELECT id, correlativo, fecha, courier, estado,
                       COALESCE(total_items, 0) AS total_items,
                       COALESCE(costo_total, 0) AS costo_total
                  FROM transport_manifests
                 WHERE estado IN ('En preparación','En curso')
                 ORDER BY (courier=%s) DESC, fecha DESC, id DESC
                 LIMIT 50
            """, (courier_pref,)) or []
            other_count = 0
    except Exception as e:
        return jsonify({"error": f"Error consultando manifiestos: {e}"}), 500

    for r in rows:
        # Normalizar fecha a YYYY-MM-DD para el frontend
        if r.get("fecha"):
            r["fecha"] = r["fecha"].isoformat() if hasattr(r["fecha"], "isoformat") else str(r["fecha"])
    return jsonify({
        "ok": True,
        "manifiestos": rows,
        "courier_filtro": courier_pref if strict else "",
        "strict": strict,
        "otros_courier_count": other_count,
    })


@app.route("/transporte/api/cubicador/enviar-manifiesto", methods=["POST"])
@_tr_required
def tr_cubicador_enviar_manifiesto():
    """Flujo unificado: desde el cubicador, persiste el commitment (tido,nudo)
    y lo adjunta a un manifiesto existente o crea uno nuevo.

    Body JSON:
      tido, nudo:        documento del cubicador (obligatorio)
      courier:           nombre del courier (obligatorio, ej. 'FedEx')
      costo_cotizado:    costo a guardar en transport_commitments.costo_zz
      manifest_id:       ID si va a manifiesto existente, None para crear nuevo
      fecha:             solo si crea nuevo (YYYY-MM-DD)
      notas:             solo si crea nuevo (opcional)
    """
    data = request.get_json(silent=True) or {}
    tido = (data.get("tido") or "").strip().upper()
    nudo = str(data.get("nudo") or "").strip()
    courier = (data.get("courier") or "").strip()[:80]
    costo_cot = data.get("costo_cotizado")
    mid_in = data.get("manifest_id")

    if not tido or not nudo:
        return jsonify({"error": "tido y nudo son obligatorios"}), 400
    if not courier:
        return jsonify({"error": "Selecciona un courier antes de enviar"}), 400

    # ── Validaciones OBLIGATORIAS antes de asignar a manifiesto (Daniel
    # 2026-07-22): "validar que el teléfono sea chileno y obligatorio, porque
    # si no, después la otra llamada [a FedEx] da error". Se exigen recién en
    # este paso (asignar a manifiesto), NO al buscar/cotizar el documento —
    # así no se traba la cotización exploratoria, solo el envío real.
    telefono_in  = (data.get("telefono") or "").strip()
    email_in     = (data.get("email") or "").strip()
    direccion_in = (data.get("direccion") or "").strip()
    lat_in       = data.get("direccion_lat")
    lng_in       = data.get("direccion_lng")

    # FIX 2026-08-12 (Daniel, con captura real: Felca bloqueado pidiendo
    # Teléfono en /asignar): "el teléfono es elemental e indispensable para
    # FedEx... si selecciona Felca o Milling se pueda avanzar, deja esa
    # restricción solo para FedEx ya que FedEx sí o sí lo solicita". El
    # teléfono pasa a ser obligatorio SOLO cuando el courier elegido es
    # FedEx -- esta es la validación real (el frontend solo da feedback
    # anticipado, ver el mismo fix en cubicador_asignar.js).
    if "fedex" in courier.lower():
        if not telefono_in:
            return jsonify({"error": "El teléfono de contacto es obligatorio para asignar a manifiesto con FedEx."}), 400
        _tel_ok, _tel_res = validar_telefono_chileno(telefono_in)
        if not _tel_ok:
            return jsonify({"error": _tel_res}), 400
        telefono_in = _tel_res  # normalizado (+56...)
    elif telefono_in:
        # Si lo mandaron igual (aunque no sea obligatorio), se valida el
        # formato -- no se guarda un teléfono con formato inválido.
        _tel_ok, _tel_res = validar_telefono_chileno(telefono_in)
        if not _tel_ok:
            return jsonify({"error": _tel_res}), 400
        telefono_in = _tel_res

    if not email_in:
        return jsonify({"error": "El correo de contacto es obligatorio para asignar a manifiesto."}), 400
    _email_ok, _email_res = validar_email(email_in)
    if not _email_ok:
        return jsonify({"error": _email_res}), 400
    email_in = _email_res or email_in

    if not direccion_in:
        return jsonify({"error": "La dirección es obligatoria para asignar a manifiesto."}), 400
    try:
        _lat_f = float(lat_in) if lat_in not in (None, "") else None
        _lng_f = float(lng_in) if lng_in not in (None, "") else None
    except (TypeError, ValueError):
        _lat_f = _lng_f = None
    # Daniel 2026-07-29: la georreferenciación con Google YA NO es requisito
    # para asignar a manifiesto — bloqueaba en seco a la operadora cuando
    # Google no reconocía una dirección real (boletas a consumidor final,
    # direcciones rurales). "El usuario tiene la responsabilidad de verificar
    # la dirección... si la cambia es responsabilidad del usuario." La
    # dirección en sí SIGUE siendo obligatoria (ver check de direccion_in
    # arriba); lo que se eliminó es la exigencia de lat/lng. Si no vienen
    # coords, se deja constancia en notas (ver _direccion_manual más abajo)
    # sin bloquear el flujo.
    _direccion_manual = bool(data.get("direccion_manual")) or (_lat_f is None or _lng_f is None)

    # 0) Validar coherencia courier ↔ manifiesto destino.
    #    Decisión Daniel (2026-05-31): un manifiesto = un solo courier. Si el
    #    operador elige FedEx pero apunta a un manifiesto de Clickex, rechazar
    #    explícito (no autocorregir silencioso).
    if mid_in:
        try:
            _man_row = mysql_fetchone(
                "SELECT courier, estado FROM transport_manifests WHERE id=%s",
                (int(mid_in),)
            )
            if not _man_row:
                return jsonify({"error": f"Manifiesto #{mid_in} no existe."}), 404
            _man_courier = (_man_row.get("courier") or "").strip()
            if _man_courier and _man_courier.lower() != courier.lower():
                return jsonify({
                    "error": (
                        f"El manifiesto seleccionado es de courier "
                        f"\"{_man_courier}\" y estás cotizando con \"{courier}\". "
                        f"Crea un manifiesto nuevo o elige uno de {courier}."
                    ),
                    "courier_manifiesto": _man_courier,
                    "courier_cotizado": courier,
                }), 409
            if (_man_row.get("estado") or "").strip() not in ("En preparación", "En curso"):
                return jsonify({
                    "error": f"Manifiesto #{mid_in} está en estado "
                             f"\"{_man_row.get('estado')}\" — no se pueden agregar items."
                }), 409
        except ValueError:
            return jsonify({"error": "manifest_id inválido"}), 400
        except Exception as e_check:
            print(f"[cub_enviar_manif] check coherencia courier falló: {e_check}", flush=True)
            # No bloqueamos por errores transitorios de check — el flujo sigue.

    # 1) Upsert commitment desde ERP (helper existente, ya probado)
    try:
        comm_id, err = _tr_fetch_from_erp(tido, nudo)
    except Exception as e_erp:
        print(f"[cub_enviar_manif] _tr_fetch_from_erp reventó: {e_erp}", flush=True)
        return jsonify({"error": f"No se pudo leer el documento del ERP: {e_erp}"}), 502
    if err:
        return jsonify({"error": f"ERP: {err}"}), 404
    if not comm_id:
        return jsonify({"error": "No se pudo registrar el documento en el sistema."}), 500

    # 2) Persistir costo del courier (lo que paga SPHS). Se guarda en costo_courier
    #    (para el match cobrado-vs-costo del manifiesto) y también en costo_zz (legacy).
    try:
        if costo_cot is not None and float(costo_cot) > 0:
            mysql_execute(
                "UPDATE transport_commitments SET costo_zz=%s, costo_courier=%s WHERE id=%s",
                (float(costo_cot), float(costo_cot), comm_id)
            )
    except Exception as e_cost:
        print(f"[cub_enviar_manif] no se pudo guardar costo: {e_cost}", flush=True)

    # 2c) Autorización / motivo / garantía (control financiero, visión Daniel).
    #     Obligatorio cuando el envío va a pérdida o sin precio. No fatal si falla.
    _autoriz = (data.get("autorizado_por") or "").strip()[:190]
    _motivo  = (data.get("motivo_envio") or "").strip()[:500]
    _garant  = 1 if data.get("es_garantia") else 0
    if _autoriz or _motivo or _garant:
        try:
            mysql_execute(
                "UPDATE transport_commitments SET autorizado_por=%s, motivo_envio=%s, "
                "es_garantia=%s WHERE id=%s",
                (_autoriz or None, _motivo or None, _garant, comm_id)
            )
        except Exception as e_auth:
            print(f"[cub_enviar_manif] no se pudo guardar autorización: {e_auth}", flush=True)

    # 2c-bis) Operador REAL dentro del agregador + calle/número de Shipit
    #     (2026-08-05). Shipit cotiza contra Starken / Chilexpress / Global
    #     Tracking / Blue Express y hasta hoy ILUS se quedaba SIEMPRE con el
    #     más barato (`disponibles[0]`). Daniel, textual: "siento que me está
    #     obligando a escoger Global Tracking, solamente porque es más
    #     barato". Ahora la pantalla deja elegir, y acá se guarda con quién se
    #     despachó de verdad. El manifiesto sigue siendo de "Shipit" (un
    #     manifiesto = un courier, decisión 2026-05-31): esto es el operador
    #     de adentro, no otro courier.
    #     `courier_operador_manual` distingue la decisión humana del default,
    #     para poder medir después si elegir a mano mejora el cumplimiento.
    #     `shipit_calle`/`shipit_numero` vienen de
    #     shipit_client.split_street_number() o de la corrección a mano en
    #     pantalla. `direccion` NO se pisa: sigue siendo el texto declarado.
    #     No es fatal: si falla, el documento igual entra al manifiesto.
    try:
        _op        = (data.get("courier_operador") or "").strip()[:80]
        _op_svc    = (data.get("courier_operador_servicio") or "").strip()[:80]
        _op_manual = 1 if data.get("courier_operador_manual") else 0
        _sh_calle  = (data.get("shipit_calle") or "").strip()[:200]
        _sh_num    = (data.get("shipit_numero") or "").strip()[:20]
        _os, _ov = [], []
        if _op:
            _os += ["courier_operador=%s", "courier_operador_servicio=%s",
                    "courier_operador_manual=%s"]
            _ov += [_op, _op_svc or None, _op_manual]
        if _sh_calle and _sh_num:
            _os += ["shipit_calle=%s", "shipit_numero=%s"]
            _ov += [_sh_calle, _sh_num]
        if _os:
            _ov.append(comm_id)
            mysql_execute(
                f"UPDATE transport_commitments SET {', '.join(_os)} WHERE id=%s",
                tuple(_ov))
    except Exception as e_op:
        print(f"[cub_enviar_manif] no se pudo guardar operador/dirección Shipit: {e_op}", flush=True)

    # 2d) Persistir cubicaje declarado (peso real/vol/volumen/predominante + bultos).
    #     Datos que el operador VE en el cubicador → quedan declarados en el
    #     commitment y corren aguas abajo (manifiesto, etiquetas, KPIs). No fatal.
    _fedex_desfasada = False
    try:
        _pr = float(data.get("peso_real") or 0)
        _pv = float(data.get("peso_vol") or 0)
        _vm = float(data.get("volumen_m3") or 0)
        _pp = float(data.get("peso_predominante") or 0)
        _nb = data.get("n_bultos")
        _sets, _vals = [], []
        if _pr > 0: _sets.append("peso_real=%s");         _vals.append(_pr)
        if _pv > 0: _sets.append("peso_vol=%s");          _vals.append(_pv)
        if _vm > 0: _sets.append("volumen_m3=%s");        _vals.append(_vm)
        if _pp > 0: _sets.append("peso_predominante=%s"); _vals.append(_pp)
        _nb_nuevo = None
        if _nb not in (None, ""):
            _nb_nuevo = max(1, int(float(_nb)))
            _sets.append("n_bultos=%s"); _vals.append(_nb_nuevo)
        if _sets:
            _vals.append(comm_id)
            mysql_execute(
                f"UPDATE transport_commitments SET {', '.join(_sets)} WHERE id=%s",
                tuple(_vals)
            )
        # FIX 2026-07-30 (Daniel/Alison, caso real FCV 11148 en MAN-2026-0008):
        # re-cubicar un documento para corregir los bultos actualizaba
        # transport_commitments.n_bultos, pero NUNCA avisaba si ya existía una
        # OT FedEx activa con OTRO conteo de bultos — a diferencia del editor
        # de "bultos y medidas" de la ficha del manifiesto (línea ~23172), que
        # sí llama a _tr_fedex_mark_stale. Resultado: la etiqueta FedEx vieja
        # (con el bulto incorrecto) seguía siendo la única activa, sin que
        # apareciera nunca el botón "Re-emitir OT". Se compara contra
        # ship_bultos (lo que FedEx REALMENTE tiene) en vez del n_bultos
        # anterior, para detectar el desfase incluso si esta es la 2ª vez que
        # se re-cubica el mismo documento con el mismo valor corregido.
        if _nb_nuevo is not None:
            try:
                _ot_activa = mysql_fetchone(
                    "SELECT ship_bultos FROM transport_manifest_items "
                    "WHERE commitment_id=%s AND master_tracking_number IS NOT NULL "
                    "  AND master_tracking_number<>'' AND ship_cancelled_at IS NULL "
                    "ORDER BY id DESC LIMIT 1", (comm_id,))
                if _ot_activa and _ot_activa.get("ship_bultos") is not None:
                    _n_desfasadas = _tr_fedex_mark_stale(
                        comm_id, int(_ot_activa["ship_bultos"]), _nb_nuevo)
                    _fedex_desfasada = _n_desfasadas > 0
            except Exception as e_stale:
                print(f"[cub_enviar_manif] check fedex desfasada falló: {e_stale}", flush=True)
    except Exception as e_cub:
        print(f"[cub_enviar_manif] no se pudo guardar cubicaje: {e_cub}", flush=True)

    # 2e) Persistir DATOS DEL HEADER del frontend (lo que el operador VE/EDITA en
    #     el cubicador). Garantiza que la factura llegue COMPLETA al manifiesto
    #     sin depender de qué vía (REST/SQL) repobló el commitment, y conserva
    #     las ediciones del operador. Solo campos no vacíos (no pisa con vacío).
    try:
        _hdr_map = {
            "cliente_nombre": (data.get("cliente_nombre") or "").strip()[:200],
            "cliente_rut":    (data.get("cliente_rut") or "").strip()[:20],
            # email/telefono/direccion: usar los valores YA validados/normalizados
            # arriba (validar_telefono_chileno / validar_email), no los crudos de
            # data — así el commitment guarda el teléfono en formato +56... .
            "email":          email_in[:150],
            "telefono":       telefono_in[:50],
            "direccion":      direccion_in[:300],
            "comuna":         (data.get("comuna") or "").strip()[:100],
            # Región (2026-07-22): antes NO se guardaba desde el cubicador —
            # el campo existía en la tabla y lo usa el export de carga masiva,
            # pero solo se llenaba editando el modal del manifiesto. Ahora el
            # front la completa al validar la dirección con Google.
            "region":         (data.get("region") or "").strip()[:80],
            # Dirección georreferenciada (Daniel 2026-07-22): ya se exigió arriba
            # que _lat_f/_lng_f existan antes de llegar hasta acá.
            "direccion_lat":      _lat_f,
            "direccion_lng":      _lng_f,
            "direccion_place_id": (data.get("direccion_place_id") or "").strip()[:200] or None,
            "direccion_referencia": (data.get("direccion_referencia") or "").strip()[:200] or None,
        }
        _hs, _hv = [], []
        for col, val in _hdr_map.items():
            if val not in (None, ""):
                _hs.append(f"{col}=%s"); _hv.append(val)
        # Candado anti-resync (2026-07-29): "Asignar y Cotizar" es donde el
        # operador DECLARA la dirección real ("yo necesito que es de asignar
        # y cotizar lo que se declare" — Daniel). Desde este punto, ningún
        # resync del ERP vuelve a pisar direccion/comuna/telefono/email.
        _hs.append("direccion_editada_manual=1")
        _vn = data.get("valor_neto")
        if _vn not in (None, "") and float(_vn) > 0:
            _hs.append("valor_neto=%s"); _hv.append(float(_vn))
        if _hs:
            _hv.append(comm_id)
            mysql_execute(
                f"UPDATE transport_commitments SET {', '.join(_hs)} WHERE id=%s",
                tuple(_hv)
            )
    except Exception as e_hdr:
        print(f"[cub_enviar_manif] no se pudo guardar header: {e_hdr}", flush=True)

    # 2e-bis) Nota de dirección NO geovalidada (Daniel 2026-07-27) — deja
    # rastro visible de que el operador confirmó a mano en vez de elegir una
    # sugerencia de Google, para que quede claro por qué falta lat/lng.
    if _direccion_manual:
        try:
            mysql_execute(
                "UPDATE transport_commitments SET notas = TRIM(CONCAT(COALESCE(notas,''), "
                "CASE WHEN COALESCE(notas,'')='' THEN '' ELSE '\n' END, "
                "'[AUTO] Dirección confirmada MANUALMENTE por el operador — Google no la reconoció.')) "
                "WHERE id=%s", (comm_id,)
            )
        except Exception:
            pass  # no fatal — la nota es informativa

    # 2f) Productos declarados (árbol manifiesto → factura → productos). Se guardan
    #     como JSON aparte de transport_commitment_lines (que alimenta el saldo).
    try:
        _prods = data.get("productos")
        if isinstance(_prods, list) and _prods:
            import json as _json_mod
            _clean = []
            for p in _prods[:200]:
                if not isinstance(p, dict):
                    continue
                _clean.append({
                    "koprct":   str(p.get("sku") or p.get("koprct") or "")[:40],
                    "nokopr":   str(p.get("nombre") or p.get("descripcion_erp") or p.get("nokopr") or "")[:300],
                    "cantidad": p.get("cantidad") or 0,
                    "saldo":    p.get("saldo"),
                })
            mysql_execute(
                "UPDATE transport_commitments SET productos_json=%s WHERE id=%s",
                (_json_mod.dumps(_clean, ensure_ascii=False), comm_id)
            )
    except Exception as e_prod:
        print(f"[cub_enviar_manif] no se pudo guardar productos: {e_prod}", flush=True)

    # 2b) Persistir notas de entrega (visible para el courier; alimenta la
    #     columna "Notas" del export SimplyRoute). No es fatal si falla.
    notas_entrega = (data.get("notas_entrega") or "").strip()
    if notas_entrega:
        try:
            mysql_execute(
                "UPDATE transport_commitments SET notas=%s WHERE id=%s",
                (notas_entrega[:2000], comm_id)
            )
        except Exception as e_notas:
            print(f"[cub_enviar_manif] no se pudo guardar notas_entrega: {e_notas}", flush=True)

    # 3) Resolver manifest_id (crear si hace falta) y agregar el item.
    conn = get_db()
    correlativo = None
    added = False
    try:
        with conn.cursor() as cur:
            if not mid_in:
                # Crear manifiesto nuevo
                fecha_in = (data.get("fecha") or "").strip()
                if not fecha_in:
                    fecha_in = datetime.now().date().isoformat()
                notas = (data.get("notas") or "").strip()[:500]
                # Correlativo MAN-AAAA-NNNN (sincronizado con tr_crear_manifiesto)
                # RACE CONDITION FIX 2026-07-19 (Daniel): mismo fix que
                # tr_crear_manifiesto — reintenta con un COUNT fresco hasta 5
                # veces si el UNIQUE de 'correlativo' choca por concurrencia,
                # en vez de dejar pasar el IntegrityError (1062) como 500 crudo.
                mid = None
                correlativo = None
                max_intentos = 5
                for _intento in range(max_intentos):
                    cur.execute(
                        "SELECT COUNT(*)+1 AS n FROM transport_manifests "
                        "WHERE YEAR(created_at)=YEAR(NOW())"
                    )
                    _r = cur.fetchone() or {}
                    n = int(_r.get("n", 1))
                    correlativo = f"MAN-{datetime.now().year}-{n:04d}"
                    try:
                        cur.execute(
                            """INSERT INTO transport_manifests
                               (correlativo, fecha, courier, notas, created_by)
                               VALUES (%s,%s,%s,%s,%s)""",
                            (correlativo, fecha_in, courier, notas, current_username())
                        )
                        mid = cur.lastrowid
                        break
                    except Exception as e_corr:
                        msg = str(e_corr)
                        if ("1062" in msg or "Duplicate entry" in msg) and "correlativo" in msg:
                            conn.rollback()
                            continue
                        raise
                if mid is None:
                    conn.rollback()
                    return jsonify({
                        "error": "No se pudo generar un correlativo único para el manifiesto, intenta de nuevo."
                    }), 409
                try: _tr_log("manifest", mid, "creado (cubicador)",
                            f"courier={courier} fecha={fecha_in}")
                except Exception: pass
            else:
                # Validar manifiesto existente
                mid = int(mid_in)
                row = mysql_fetchone(
                    "SELECT estado, correlativo FROM transport_manifests WHERE id=%s",
                    (mid,)
                )
                if not row:
                    return jsonify({"error": "Manifiesto no encontrado"}), 404
                if row["estado"] in ("Cerrado", "Entregado completo"):
                    return jsonify({
                        "error": "El manifiesto está cerrado y no acepta más items."
                    }), 409
                correlativo = row["correlativo"]

            # 4) Adjuntar item (idempotente por UNIQUE)
            # PR-B (Fase 1, 2026-08-01): ramo resuelto vía _tr_ramos_de_commitment
            # `ramo` en el body es opcional -- mismo mecanismo de
            # desambiguación que tr_agregar_item.
            #
            # FIX 2026-08-12 (Daniel, con captura real FCV 11216, despacho +
            # instalación: "el documento tiene 2 ramos sin asignar... usa
            # Líneas pendientes" -- "necesito modifica esa regla y que
            # avance"). Este flujo (cubicador/asignar) no tiene granularidad
            # de línea para elegir UN ramo, así que antes bloqueaba en seco
            # cualquier documento con 2+ ramos pendientes. Pero desde la
            # corrección del 2026-08-01 ("despachamos e instalamos juntos")
            # ambos ramos YA pueden convivir sin fricción en el mismo
            # manifiesto -- lo único que faltaba era dejar de exigir que el
            # operador elija uno cuando en realidad quiere los dos. Ahora,
            # ante "conflicto_multi_ramo", se asignan TODOS los ramos
            # pendientes al mismo manifiesto destino en vez de rechazar.
            _ramo_solicitado_cub = (data.get("ramo") or "").strip().lower() or None
            _ramos_doc_cub = _tr_ramos_de_commitment(comm_id)
            _items_cub = _tr_items_existentes_de_commitment(comm_id)
            _plan_cub = _tr_plan_ramo_manifest_item(_ramos_doc_cub, _items_cub, mid, _ramo_solicitado_cub)
            _nuevos_items_cub = []  # (item_id, ramo) recién insertados -- para notificar/loggear todos
            if _plan_cub["accion"] == "conflicto_multi_ramo":
                for _ramo_pend in _plan_cub["pendientes"]:
                    cur.execute(
                        "INSERT IGNORE INTO transport_manifest_items "
                        "(manifest_id, commitment_id, ramo) VALUES (%s,%s,%s)",
                        (mid, comm_id, _ramo_pend)
                    )
                    if cur.rowcount:
                        _nuevos_items_cub.append((cur.lastrowid, _ramo_pend))
                added = bool(_nuevos_items_cub)
                _new_item_id = _nuevos_items_cub[0][0] if _nuevos_items_cub else None
                _ramo_cub = ", ".join(_plan_cub["pendientes"])
            else:
                _ramo_cub = _plan_cub.get("ramo") or "despacho"
                cur.execute(
                    "INSERT IGNORE INTO transport_manifest_items "
                    "(manifest_id, commitment_id, ramo) VALUES (%s,%s,%s)",
                    (mid, comm_id, _ramo_cub)
                )
                added = bool(cur.rowcount)
                _new_item_id = cur.lastrowid if added else None
                if added:
                    _nuevos_items_cub.append((_new_item_id, _ramo_cub))

            # 5) Recalcular totales del manifiesto
            cur.execute("""
                UPDATE transport_manifests m SET
                  total_items = (SELECT COUNT(*) FROM transport_manifest_items
                                  WHERE manifest_id = m.id),
                  costo_total = (SELECT COALESCE(SUM(c.costo_zz), 0)
                                   FROM transport_manifest_items mi
                                   JOIN transport_commitments c ON c.id = mi.commitment_id
                                  WHERE mi.manifest_id = m.id)
                WHERE m.id = %s
            """, (mid,))
        conn.commit()
    except Exception as e_tx:
        try: conn.rollback()
        except Exception: pass
        return jsonify({"error": f"Error al adjuntar al manifiesto: {e_tx}"}), 500

    try:
        _tr_log(
            "manifest", mid,
            "item agregado (cubicador)" if added else "item duplicado (cubicador)",
            f"commitment_id={comm_id} tido={tido} nudo={nudo} courier={courier}"
        )
    except Exception: pass

    # 2026-06-14 (Daniel): "tu pedido está en preparación" al asignar desde el
    # cubicador (solo si la factura se agregó nueva, no en duplicados). Se
    # notifica UN evento por cada ramo recién insertado (normalmente 1, pero
    # 2 si el documento traía despacho+instalación pendientes, ver fix
    # 2026-08-12) -- el anti-spam por commitment de _tr_event evita que el
    # cliente reciba dos correos idénticos por el mismo despacho.
    for _item_id_prep, _ramo_prep in _nuevos_items_cub:
        try:
            _tr_event(_item_id_prep, 'En preparación', fuente='sistema',
                      commitment_id=comm_id, notify_cliente=True)
        except Exception as _e_prep2:
            print(f"[tr_event preparacion cub] item={_item_id_prep}: {_e_prep2}", flush=True)

    return jsonify({
        "ok": True,
        "manifest_id": mid,
        "correlativo": correlativo,
        "commitment_id": comm_id,
        "added": added,
        "duplicate": not added,
        "ramo": _ramo_cub,
        "fedex_desfasada": _fedex_desfasada,
    })


# ── COURIERS — helper functions ──────────────────────────────────────────────

def _parse_peso_upper(col_header) -> float:
    """Converts a weight column header to its upper bound in kg."""
    s = str(col_header).strip().replace(',', '.').replace(' ', '').lower()
    # Special cases
    if '+' in s or 'mas' in s or 'more' in s:
        return 999999.0
    # Range like "100al499", "500-1999", "1001-5000"
    for sep in ['-', 'al']:
        if sep in s:
            parts = s.split(sep)
            try:
                return float(parts[-1])
            except Exception:
                pass
    # Single number
    try:
        return float(s)
    except Exception:
        return 999999.0


# ══════════════════════════════════════════════════════════════════════════
#  COURIERS — MARGEN + IVA (criterio Daniel 22/05/2026)
#
#  El Excel maestro de tarifas representa el COSTO que ILUS paga al courier.
#  El precio final al cliente es:
#      subtotal_neto = costo × (1 + margen_pct/100)
#      precio_venta  = subtotal_neto × (1 + iva_pct/100)
#
#  Defaults: margen 30%, IVA 19% (Chile).
#  Ambos configurables vía env vars:
#      ILUS_COURIER_MARGEN_PCT (default 30)
#      ILUS_IVA_PCT            (default 19)
#  Esto permite ajustar el margen sin redeploy de código si Daniel
#  decide cambiar la política comercial.
# ══════════════════════════════════════════════════════════════════════════
def _courier_margen_iva_cfg() -> dict:
    """Lee config margen/IVA de env vars o defaults."""
    try:
        mpct = float(os.environ.get("ILUS_COURIER_MARGEN_PCT", "30") or 30)
    except Exception:
        mpct = 30.0
    try:
        ipct = float(os.environ.get("ILUS_IVA_PCT", "19") or 19)
    except Exception:
        ipct = 19.0
    return {"margen_pct": mpct, "iva_pct": ipct}


def _courier_aplicar_margen_iva(precio_costo: float, *, margen_pct: float = None,
                                 iva_pct: float = None) -> dict:
    """Aplica margen comercial + IVA al precio de costo del courier.

    Returns dict con desglose completo (cada componente redondeado a CLP):
        {
            "precio_costo":  36317,    # del Excel (lo que ILUS paga al courier)
            "margen_pct":    30.0,
            "margen_clp":    10895,
            "subtotal_neto": 47212,    # costo + margen (lo que ILUS factura sin IVA)
            "iva_pct":       19.0,
            "iva_clp":       8970,
            "precio_venta":  56182,    # lo que paga el cliente (con IVA)
        }
    """
    cfg = _courier_margen_iva_cfg()
    mpct = float(margen_pct if margen_pct is not None else cfg["margen_pct"])
    ipct = float(iva_pct    if iva_pct    is not None else cfg["iva_pct"])
    costo = float(precio_costo or 0)
    margen_clp = costo * (mpct / 100.0)
    subtotal_neto = costo + margen_clp
    iva_clp = subtotal_neto * (ipct / 100.0)
    precio_venta = subtotal_neto + iva_clp
    return {
        "precio_costo":  round(costo, 0),
        "margen_pct":    mpct,
        "margen_clp":    round(margen_clp, 0),
        "subtotal_neto": round(subtotal_neto, 0),
        "iva_pct":       ipct,
        "iva_clp":       round(iva_clp, 0),
        "precio_venta":  round(precio_venta, 0),
    }


def _courier_tarifa_lookup(courier_id: int, comuna: str, peso_kg: float,
                            return_trace: bool = False):
    """
    Returns the price (float) for a given courier+commune+weight.

    LEGACY: cuando ``return_trace=False`` mantiene la firma antigua (devuelve
    solo el precio o None). Esto evita romper callers existentes.

    NUEVO: con ``return_trace=True`` devuelve un dict con TODO el detalle del
    cálculo — bracket aplicado, fórmula, fuente, advertencias. Imprescindible
    para auditoría (FedEx puede revisar cualquier cotización histórica).

        {
          "precio": 105237,
          "bracket_aplicado": "100+",
          "bracket_upper": 999999.0,
          "formula": "Bracket exact match",
          "fuente": "tabla",
          "validado": True,            # ← si la tarifa fue marcada manualmente
          "peso_usado": 173.89,
          "comuna_normalizada": "lo barnechea",
          "comuna_db": "Lo Barnechea",
          "json_brackets_disponibles": ["1","5","10","25","50","100","100+"],
          "advertencias": ["..."],
        }
    """
    comuna_norm = (comuna or '').strip().lower()
    row = mysql_fetchone(
        "SELECT comuna, precios_json, dias_transito FROM transport_courier_comunas "
        "WHERE courier_id=%s AND LOWER(TRIM(comuna))=LOWER(TRIM(%s))",
        (courier_id, comuna)
    )

    def _trace_empty(reason: str, fuente: str = "no_cobertura"):
        if not return_trace:
            return None
        return {
            "precio": None,
            "bracket_aplicado": None,
            "bracket_upper": None,
            "formula": reason,
            "fuente": fuente,
            "validado": False,
            "peso_usado": float(peso_kg),
            "comuna_normalizada": comuna_norm,
            "comuna_db": None,
            "json_brackets_disponibles": [],
            "advertencias": [reason],
        }

    if not row or not row.get('precios_json'):
        return _trace_empty(f"Sin tarifa para '{comuna}' (courier_id={courier_id})")

    try:
        precios = json.loads(row['precios_json'])
    except Exception as ex_json:
        return _trace_empty(f"precios_json inválido: {ex_json}", fuente="error")

    # Build sorted bracket list — guardamos también la KEY original para trace
    brackets = []  # [(upper:float, price:float, key_original:str)]
    for key, price in precios.items():
        if price is None:
            continue
        try:
            upper = _parse_peso_upper(key)
            brackets.append((upper, float(price), str(key)))
        except Exception:
            pass
    brackets.sort(key=lambda x: x[0])
    if not brackets:
        return _trace_empty("No hay brackets numéricos válidos en precios_json", fuente="error")

    # Buscar el bracket aplicable
    bracket_match = None
    formula = ""
    for upper, price, key_orig in brackets:
        if peso_kg <= upper:
            bracket_match = (upper, price, key_orig)
            formula = f"Bracket exact match: peso {peso_kg}kg <= {upper}kg (key='{key_orig}')"
            break
    if bracket_match is None:
        # Sobre el bracket máximo → usar el último (último precio definido)
        upper, price, key_orig = brackets[-1]
        bracket_match = (upper, price, key_orig)
        formula = f"Sobre bracket máximo: usa último (key='{key_orig}', upper={upper}kg)"

    upper, price, key_orig = bracket_match

    # ── Validación: ¿es validado manualmente? ───────────────────────
    validado_flag = False
    fuente_aplicada = "tabla"
    try:
        last_audit = mysql_fetchone(
            "SELECT validado, fuente FROM courier_tariff_audit "
            "WHERE courier_id=%s AND LOWER(TRIM(comuna))=LOWER(TRIM(%s)) "
            "  AND bracket_aplicado=%s AND validado=1 "
            "ORDER BY cotizacion_at DESC LIMIT 1",
            (courier_id, comuna, key_orig)
        )
        if last_audit:
            validado_flag = True
            fuente_aplicada = last_audit.get('fuente') or 'validado_excel'
    except Exception:
        # tabla puede no existir aún (primer arranque) — ignorar
        pass

    # ── Detección de tarifas SOSPECHOSAS ────────────────────────────
    # Si el precio resultante es muy bajo en relación al peso, alertar.
    # Reglas defensivas:
    #   - Precio < $1.000 para peso > 5 kg → muy probablemente está en $/kg en lugar de total
    #   - Precio < (peso × $50) → ratio absurdo (<$50/kg sospechoso)
    #   - Precio < $5.000 para peso > 50 kg → sospechoso
    advertencias = []
    if peso_kg >= 5 and price < 1000:
        advertencias.append(
            f"Precio sospechosamente bajo: ${int(price)} para {peso_kg}kg "
            f"(podría ser precio/kg en lugar de total) — verificar tabla"
        )
    elif peso_kg >= 50 and price < 5000:
        advertencias.append(
            f"Precio bajo para peso alto: ${int(price)} para {peso_kg}kg "
            f"(~${price/peso_kg:.0f}/kg) — verificar tabla"
        )
    elif peso_kg >= 10 and price > 0 and (price / peso_kg) < 50:
        advertencias.append(
            f"Tarifa <$50/kg: ${int(price)} para {peso_kg}kg → verificar tabla"
        )

    if not return_trace:
        return float(price)

    return {
        "precio": float(price),
        "bracket_aplicado": key_orig,
        "bracket_upper": upper,
        "formula": formula,
        "fuente": fuente_aplicada,
        "validado": validado_flag,
        "peso_usado": float(peso_kg),
        "comuna_normalizada": comuna_norm,
        "comuna_db": row.get('comuna'),
        "json_brackets_disponibles": [b[2] for b in brackets],
        "advertencias": advertencias,
    }


def _audit_cotizacion(*, courier_id, courier_nombre, comuna, peso_kg, peso_pred_kg,
                       bracket_aplicado, precio_calculado, formula_aplicada,
                       fuente, validado=False, notas=None,
                       documento_tido=None, documento_nudo=None,
                       cotizado_por=None, desglose=None) -> int:
    """Inserta una fila en courier_tariff_audit y devuelve el id.

    No-throw: si la tabla todavía no existe (primer arranque) o hay error,
    silencioso → devuelve None. El audit nunca debe tirar la cotización.

    Args:
        precio_calculado: histórico — equivale al precio_venta (lo que ve el cliente).
        desglose: dict de _courier_aplicar_margen_iva() para guardar componentes
                  costo/margen/iva separados (auditable por FedEx).
    """
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Construir el INSERT con o sin columnas de desglose dependiendo de
            # si existen (migración idempotente — la primera vez no existirán).
            d = desglose or {}
            pcosto = int(d.get("precio_costo")) if d.get("precio_costo") is not None else None
            pventa = int(d.get("precio_venta")) if d.get("precio_venta") is not None else None
            mpct   = float(d.get("margen_pct")) if d.get("margen_pct") is not None else None
            mclp   = int(d.get("margen_clp")) if d.get("margen_clp") is not None else None
            ipct   = float(d.get("iva_pct")) if d.get("iva_pct") is not None else None
            iclp   = int(d.get("iva_clp")) if d.get("iva_clp") is not None else None
            try:
                cur.execute(
                    """INSERT INTO courier_tariff_audit
                       (cotizado_por, documento_tido, documento_nudo, comuna,
                        peso_kg, peso_pred_kg, courier_id, courier_nombre,
                        bracket_aplicado, precio_calculado, formula_aplicada,
                        fuente, validado, notas,
                        precio_costo, margen_pct, margen_clp,
                        iva_pct, iva_clp, precio_venta)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                               %s,%s,%s,%s,%s,%s)""",
                    (
                        cotizado_por or current_username() or 'sistema',
                        documento_tido, documento_nudo, (comuna or '')[:120],
                        float(peso_kg or 0), float(peso_pred_kg or peso_kg or 0),
                        int(courier_id) if courier_id else None,
                        (courier_nombre or '')[:120],
                        (bracket_aplicado or '')[:40],
                        int(round(precio_calculado)) if precio_calculado is not None else None,
                        (formula_aplicada or '')[:200],
                        (fuente or 'tabla')[:40],
                        1 if validado else 0,
                        notas,
                        pcosto, mpct, mclp, ipct, iclp, pventa,
                    )
                )
            except Exception:
                # Fallback: las columnas nuevas (precio_costo, margen_*, iva_*,
                # precio_venta) aún no aplicaron — INSERT con schema legacy.
                cur.execute(
                    """INSERT INTO courier_tariff_audit
                       (cotizado_por, documento_tido, documento_nudo, comuna,
                        peso_kg, peso_pred_kg, courier_id, courier_nombre,
                        bracket_aplicado, precio_calculado, formula_aplicada,
                        fuente, validado, notas)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (
                        cotizado_por or current_username() or 'sistema',
                        documento_tido, documento_nudo, (comuna or '')[:120],
                        float(peso_kg or 0), float(peso_pred_kg or peso_kg or 0),
                        int(courier_id) if courier_id else None,
                        (courier_nombre or '')[:120],
                        (bracket_aplicado or '')[:40],
                        int(round(precio_calculado)) if precio_calculado is not None else None,
                        (formula_aplicada or '')[:200],
                        (fuente or 'tabla')[:40],
                        1 if validado else 0,
                        notas,
                    )
                )
            audit_id = cur.lastrowid
        conn.commit()
        return audit_id
    except Exception as ex_audit:
        print(f"[_audit_cotizacion] error: {ex_audit}", flush=True)
        return None


# ── COURIERS ─────────────────────────────────────────────────────────────────

@app.route("/transporte/couriers")
@_tr_required
def tr_couriers():
    # Mes en curso en hora Chile (REGLA #6): el conteo de despachos del mes
    # tiene que cortar cuando cambia el mes ACÁ, no en UTC — si no, los
    # despachos de las últimas horas del último día del mes caen en el
    # siguiente.
    _hoy_cl = _now_chile().date()
    _mes_ini = _hoy_cl.replace(day=1)
    _mes_fin = (_mes_ini + timedelta(days=32)).replace(day=1)

    # Todo en UNA consulta: es la lista de couriers, no una ficha. Una
    # consulta por tarjeta multiplicaría los viajes a la base por cada courier.
    #
    # · Los datos del contrato van como subconsultas correlacionadas (no como
    #   JOIN): esta consulta ya agrupa por c.id para contar tarifas y comunas,
    #   y sumar un JOIN a contratos multiplicaría las filas del GROUP BY además
    #   de chocar con ONLY_FULL_GROUP_BY. Correlacionadas contra c.id son
    #   válidas dentro del GROUP BY y baratas (courier_id está indexado por su
    #   clave foránea), y los couriers son unas pocas decenas de filas.
    #
    # · total_contratos cuenta TODOS los documentos guardados (es lo que dice
    #   la tarjeta: "N documentos guardados"). Los campos de vigencia salen
    #   del contrato VIGENTE más reciente; si no hay ninguno vigente quedan en
    #   NULL y la tarjeta muestra "Sin registrar" — que es la verdad, no un
    #   dato inventado.
    #
    # · despachos_mes se cruza por NOMBRE porque transport_manifests guarda el
    #   courier como texto, no con clave foránea. Se normaliza con LOWER+TRIM
    #   para que "Milling " y "milling" sumen juntos. OJO: dos fichas
    #   duplicadas de la misma empresa (el caso Melling/Milling) reparten sus
    #   despachos entre ambas hasta que se fusionen.
    couriers = mysql_fetchall(
        """SELECT c.*,
           COUNT(DISTINCT t.id) AS total_tarifas,
           COUNT(DISTINCT cc.id) AS total_comunas,
           COUNT(DISTINCT CASE
             WHEN cc.precios_json IS NOT NULL AND cc.precios_json <> ''
              AND cc.precios_json <> '{}' AND cc.precios_json <> '[]'
             THEN cc.id END) AS comunas_con_precio,
           (SELECT COUNT(*) FROM transport_courier_contratos k
             WHERE k.courier_id = c.id)                    AS total_contratos,
           (SELECT k.tipo FROM transport_courier_contratos k
             WHERE k.courier_id = c.id AND k.vigente = 1
             ORDER BY k.fecha_inicio DESC, k.created_at DESC, k.id DESC
             LIMIT 1)                                      AS contrato_tipo,
           (SELECT k.fecha_inicio FROM transport_courier_contratos k
             WHERE k.courier_id = c.id AND k.vigente = 1
             ORDER BY k.fecha_inicio DESC, k.created_at DESC, k.id DESC
             LIMIT 1)                                      AS contrato_inicio,
           (SELECT k.fecha_fin FROM transport_courier_contratos k
             WHERE k.courier_id = c.id AND k.vigente = 1
             ORDER BY k.fecha_inicio DESC, k.created_at DESC, k.id DESC
             LIMIT 1)                                      AS contrato_fin,
           (SELECT k.archivo_url FROM transport_courier_contratos k
             WHERE k.courier_id = c.id AND k.vigente = 1
             ORDER BY k.fecha_inicio DESC, k.created_at DESC, k.id DESC
             LIMIT 1)                                      AS contrato_archivo_url,
           (SELECT k.nombre FROM transport_courier_contratos k
             WHERE k.courier_id = c.id AND k.vigente = 1
             ORDER BY k.fecha_inicio DESC, k.created_at DESC, k.id DESC
             LIMIT 1)                                      AS contrato_nombre,
           COALESCE(MAX(dm.n), 0)                          AS despachos_mes
           FROM transport_couriers c
           LEFT JOIN transport_courier_tarifas t ON t.courier_id=c.id AND t.activo=1
           LEFT JOIN transport_courier_comunas cc ON cc.courier_id=c.id
           LEFT JOIN (
                SELECT LOWER(TRIM(m.courier)) AS courier_key, COUNT(*) AS n
                  FROM transport_manifest_items mi
                  JOIN transport_manifests m ON m.id = mi.manifest_id
                 WHERE (m.eliminado IS NULL OR m.eliminado = 0)
                   AND m.fecha >= %s AND m.fecha < %s
                 GROUP BY LOWER(TRIM(m.courier))
           ) dm ON dm.courier_key = LOWER(TRIM(c.nombre))
           GROUP BY c.id ORDER BY c.activo DESC, c.nombre""",
        (_mes_ini, _mes_fin)
    )
    return render_template("transporte/couriers.html", couriers=couriers)


@app.route("/transporte/couriers/nuevo", methods=["POST"])
@_tr_required
def tr_courier_nuevo():
    d = request.form
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            """INSERT INTO transport_couriers
               (nombre,rut,contacto,telefono,email,tipo,notas,
                peso_max_bulto,peso_max_guia,vol_max_bulto,factor_vol)
               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
            (
                d.get("nombre","").strip(),
                d.get("rut","").strip(),
                d.get("contacto","").strip(),
                d.get("telefono","").strip(),
                d.get("email","").strip(),
                d.get("tipo","nacional"),
                d.get("notas","").strip(),
                float(d.get("peso_max_bulto") or 0),
                float(d.get("peso_max_guia") or 0),
                float(d.get("vol_max_bulto") or 0),
                float(d.get("factor_vol") or 5000),
            ),
        )
    conn.commit()
    _invalidate_couriers_cache()
    flash("Courier creado correctamente.", "success")
    return redirect(url_for("tr_couriers"))


@app.route("/transporte/couriers/import-tariffs", methods=["POST"])
@_tr_required
def tr_couriers_import_tariffs():
    """Importa tarifas de couriers desde Excel multi-hoja.

    Sube un archivo Excel (.xlsx) con una hoja por courier. Cada hoja debe
    tener columnas: Comuna/Destino, Sucursal, Zona, Días Tránsito, y luego
    columnas numéricas (1, 2, ..., 99) y/o rangos ("100-499", "500-1999"...).

    Soporta el formato de Libro1.xlsx (FedEx/Clickex/Felca/Milling).
    Reemplaza todas las tarifas existentes del courier (DELETE + INSERT).
    """
    if not g.permissions.get("transporte_admin") and not g.permissions.get("superadmin"):
        flash("Necesitás permiso de transporte admin.", "danger")
        return redirect(url_for("tr_couriers"))

    if "file" not in request.files:
        flash("Debes seleccionar un archivo Excel.", "warning")
        return redirect(url_for("tr_couriers"))

    f = request.files["file"]
    if not f.filename:
        flash("Archivo vacío.", "warning")
        return redirect(url_for("tr_couriers"))
    if not f.filename.lower().endswith((".xlsx", ".xlsm")):
        flash("Solo .xlsx / .xlsm.", "warning")
        return redirect(url_for("tr_couriers"))

    # Guardar temporal
    import tempfile
    import courier_tariff_import as cti
    try:
        with tempfile.NamedTemporaryFile(suffix=".xlsx", delete=False) as tmp:
            f.save(tmp.name)
            tmp_path = tmp.name
        conn = get_db()
        result = cti.import_excel_to_db(tmp_path, conn)
        os.unlink(tmp_path)
        _invalidate_couriers_cache()
        total = sum(result.values())
        flash(
            f"Tarifas importadas: " +
            ", ".join(f"{k}={v}" for k, v in result.items()) +
            f" ({total} comunas total).",
            "success"
        )
    except Exception as e:
        print(f"[tr_couriers_import_tarifas] error: {e}", flush=True)
        flash("Error importando tarifas. Revisa el archivo y vuelve a intentar.", "danger")
    return redirect(url_for("tr_couriers"))


@app.route("/transporte/couriers/<int:cid>", methods=["GET"])
@_tr_required
def tr_courier_ficha(cid):
    # El SELECT histórico usaba MAX(cc.updated_at). En entornos donde la
    # columna nunca se agregó (ILUS_SKIP_MIGRATIONS=1 + ALTER que se perdió)
    # eso revienta con 'Unknown column'. Lo hacemos defensivo: detectamos si
    # la columna existe y armamos el SELECT con esa info.
    try:
        _has_upd = mysql_fetchone(
            "SELECT 1 AS y FROM information_schema.COLUMNS "
            "WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='transport_courier_comunas' "
            "AND COLUMN_NAME='updated_at' LIMIT 1"
        )
    except Exception:
        _has_upd = None
    _max_upd = "MAX(cc.updated_at)" if _has_upd else "NULL"
    courier = mysql_fetchone(f"""
        SELECT c.*,
               COUNT(DISTINCT cc.id) AS total_comunas,
               COUNT(DISTINCT ct.id) AS total_contratos,
               {_max_upd}            AS ultima_importacion
        FROM transport_couriers c
        LEFT JOIN transport_courier_comunas cc ON cc.courier_id=c.id
        LEFT JOIN transport_courier_contratos ct ON ct.courier_id=c.id AND ct.vigente=1
        WHERE c.id=%s GROUP BY c.id
    """, (cid,))
    if not courier:
        flash("Courier no encontrado.", "danger")
        return redirect(url_for("tr_couriers"))

    contratos = mysql_fetchall(
        "SELECT * FROM transport_courier_contratos WHERE courier_id=%s ORDER BY vigente DESC, created_at DESC",
        (cid,)
    ) or []

    comunas_sample = mysql_fetchall(
        "SELECT comuna, zona, region, dias_transito, precios_json FROM transport_courier_comunas "
        "WHERE courier_id=%s ORDER BY region, comuna LIMIT 10", (cid,)
    ) or []

    regions = mysql_fetchall(
        "SELECT DISTINCT region FROM transport_courier_comunas WHERE courier_id=%s AND region!='' ORDER BY region", (cid,)
    ) or []
    zonas = mysql_fetchall(
        "SELECT DISTINCT zona FROM transport_courier_comunas WHERE courier_id=%s AND zona!='' ORDER BY zona", (cid,)
    ) or []

    # Choferes internos del courier (2026-08-06): antes solo activo=1 -- ahora
    # se listan TODOS (activos e inactivos) porque la ficha necesita poder
    # reactivar a un chofer desactivado (acción heredada del viejo menú admin
    # "Choferes" que Daniel pidió sacar del sidebar). El selector de "chofer
    # guardado" en captura de retiro (tr_courier_choferes_listar, GET
    # /choferes) sigue filtrando activo=1 -- NO se tocó, sigue igual.
    # NO trae contrato_doc_url/contrato_vencimiento -- Daniel aclaró
    # (2026-08-06) que "el contrato de prestación de servicio" es del
    # courier (transport_courier_contratos, variable `contratos` de acá
    # abajo), no de cada chofer.
    choferes = mysql_fetchall(
        "SELECT id, nombre, rut, telefono, patente, peso_max_kg, volumen_max_m3, activo, "
        "       licencia_clase, licencia_vencimiento, licencia_doc_url, "
        "       seguro_carga_vigente, seguro_carga_vencimiento, seguro_carga_doc_url, "
        "       foto_url "
        "FROM transport_drivers WHERE courier_id=%s ORDER BY activo DESC, nombre", (cid,)
    ) or []
    # Vencimientos → estado visual (ámbar "por vencer" / rojo "vencido", Regla
    # #2) + copia JSON-safe para prefill del modal de edición (fechas en ISO
    # para <input type=date> -- ese input nativo siempre se muestra en el
    # locale del navegador del usuario, la Regla #6 no aplica a su atributo
    # value crudo, solo a fechas mostradas como texto).
    choferes_json = []
    for ch in choferes:
        ch["estado_licencia"] = _tr_estado_vencimiento(ch.get("licencia_vencimiento"))
        ch["estado_seguro"] = _tr_estado_vencimiento(ch.get("seguro_carga_vencimiento"))
        ch["licencia_apta_camion_pequeno"] = _tr_licencia_apta_camion_pequeno(ch.get("licencia_clase"))
        choferes_json.append({
            "id": ch["id"], "nombre": ch["nombre"] or "",
            "rut": rut_fmt_filter(ch["rut"]) if ch.get("rut") else "",
            "telefono": ch["telefono"] or "", "patente": ch["patente"] or "",
            "peso_max_kg": float(ch["peso_max_kg"]) if ch.get("peso_max_kg") else None,
            "volumen_max_m3": float(ch["volumen_max_m3"]) if ch.get("volumen_max_m3") else None,
            "activo": bool(ch["activo"]),
            "licencia_clase": ch.get("licencia_clase") or "",
            "licencia_vencimiento": ch["licencia_vencimiento"].isoformat() if ch.get("licencia_vencimiento") else "",
            "licencia_doc_url": ch.get("licencia_doc_url") or "",
            "seguro_carga_vigente": bool(ch.get("seguro_carga_vigente")),
            "seguro_carga_vencimiento": ch["seguro_carga_vencimiento"].isoformat() if ch.get("seguro_carga_vencimiento") else "",
            "seguro_carga_doc_url": ch.get("seguro_carga_doc_url") or "",
            "foto_url": ch.get("foto_url") or "",
        })

    # Couriers activos para la acción "Cambiar de transporte" (heredada del
    # viejo menú admin) -- reusa tr_choferes_set_courier, que no cambió.
    couriers_todos = mysql_fetchall(
        "SELECT id, nombre FROM transport_couriers WHERE activo=1 ORDER BY nombre"
    ) or []

    return render_template("transporte/courier_ficha.html",
        courier=courier,
        contratos=contratos,
        comunas_sample=comunas_sample,
        regions=[r['region'] for r in regions],
        zonas=[z['zona'] for z in zonas],
        choferes=choferes,
        choferes_json=choferes_json,
        couriers_todos=couriers_todos,
        licencia_clases_chile=LICENCIA_CLASES_CHILE,
        licencia_camion_pequeno=sorted(LICENCIA_CAMION_PEQUENO),
    )


@app.route("/transporte/couriers/<int:cid>", methods=["PUT"])
@_tr_required
def tr_courier_editar(cid):
    d = request.get_json(silent=True) or {}
    campos = [
        "nombre=%s", "nombre_fantasia=%s", "rut=%s", "giro=%s",
        "contacto=%s", "contacto_cargo=%s", "telefono=%s", "email=%s",
        "tipo=%s", "notas=%s", "activo=%s",
        "peso_max_bulto=%s", "peso_max_guia=%s", "vol_max_bulto=%s", "factor_vol=%s",
        "logo_url=%s", "website=%s", "direccion=%s",
    ]
    valores = [
        d.get("nombre","").strip(),
        (d.get("nombre_fantasia") or "").strip(),
        d.get("rut","").strip(),
        (d.get("giro") or "").strip(),
        d.get("contacto","").strip(),
        (d.get("contacto_cargo") or "").strip(),
        d.get("telefono","").strip(),
        d.get("email","").strip(),
        d.get("tipo","nacional"),
        d.get("notas","").strip(),
        1 if d.get("activo", True) else 0,
        float(d.get("peso_max_bulto") or 0),
        float(d.get("peso_max_guia") or 0),
        float(d.get("vol_max_bulto") or 0),
        float(d.get("factor_vol") or 5000),
        d.get("logo_url","").strip(),
        (d.get("website") or "").strip(),
        (d.get("direccion") or "").strip(),
    ]

    # responsable_ilus SOLO se toca si viene en el cuerpo. NO se puede meter en
    # la lista fija de arriba: la pantalla arma el cuerpo con un set FIJO de
    # campos (_crPayloadCourier en couriers.html), así que la acción de
    # habilitar/deshabilitar y cualquier edición hecha antes de que el modal
    # tenga el campo mandarían el cuerpo SIN esta clave. Con un %s fijo eso
    # sería un NULL y borraría en silencio el responsable ya asignado, cada
    # vez. Ausente = no se toca; presente y vacío = se limpia a propósito.
    if "responsable_ilus" in d:
        campos.append("responsable_ilus=%s")
        valores.append((str(d.get("responsable_ilus") or "").strip()[:190]) or None)

    valores.append(cid)
    conn = get_db()
    with conn.cursor() as cur:
        # Los nombres de columna salen de esta lista literal del código, nunca
        # del cuerpo de la petición; los VALORES siempre van parametrizados
        # con %s (REGLA #4).
        cur.execute(
            "UPDATE transport_couriers SET " + ", ".join(campos) + " WHERE id=%s",
            tuple(valores),
        )
    conn.commit()
    _invalidate_couriers_cache()
    return jsonify({"ok": True})


@app.route("/transporte/couriers/<int:cid>", methods=["DELETE"])
@_tr_required
def tr_courier_eliminar(cid):
    """Eliminar courier.

    ?hard=1 → borra de verdad (con sus comunas/tarifas/contratos por
              ON DELETE CASCADE). Para depurar duplicados como
              'Transportes Mellín' (legacy de Milling).
    Sin hard → soft-delete (activo=0, preserva historial).

    Los manifiestos referencian al courier por NOMBRE (string), no por FK,
    así que el hard-delete no rompe manifiestos históricos.
    """
    hard = request.args.get("hard") in ("1", "true", "yes")
    row = mysql_fetchone("SELECT nombre FROM transport_couriers WHERE id=%s", (cid,))
    if not row:
        return jsonify({"error": "no_encontrado"}), 404
    conn = get_db()
    with conn.cursor() as cur:
        if hard:
            cur.execute("DELETE FROM transport_couriers WHERE id=%s", (cid,))
            accion = "courier eliminado (hard)"
        else:
            cur.execute("UPDATE transport_couriers SET activo=0 WHERE id=%s", (cid,))
            accion = "courier desactivado"
    conn.commit()
    _invalidate_couriers_cache()
    try:
        _tr_log("commitment", cid, accion, row.get("nombre") or "")
    except Exception:
        pass
    return jsonify({"ok": True, "hard": hard, "nombre": row.get("nombre")})


@app.route("/transporte/couriers/seed-logos", methods=["POST"])
@_tr_required
def tr_couriers_seed_logos():
    """Asocia logos oficiales + websites a los couriers conocidos por nombre.
    Solo setea si el campo está vacío (no pisa cambios manuales). Idempotente.
    Logos descargados localmente a static/img/couriers/ para no depender de CDN.
    """
    # URLs directas de CDN estables (Wikimedia para FedEx; Brandfetch para los
    # couriers chilenos — fondo transparente, 512px). El navegador del cliente
    # las carga; si una falla, el front cae al placeholder con iniciales.
    _BF = "https://cdn.brandfetch.io"
    seeds = {
        "fedex":       {"logo": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/FedEx_Express.svg/320px-FedEx_Express.svg.png", "web": "https://www.fedex.com/es-cl/"},
        "starken":     {"logo": f"{_BF}/starken.cl/w/400/h/400",      "web": "https://www.starken.cl/"},
        "chilexpress": {"logo": f"{_BF}/chilexpress.cl/w/400/h/400",  "web": "https://www.chilexpress.cl/"},
        "blue":        {"logo": f"{_BF}/blue.cl/w/400/h/400",         "web": "https://www.blue.cl/"},
        "clickex":     {"logo": f"{_BF}/clickex.cl/w/400/h/400",      "web": "https://clickex.cl/"},
        "enviame":     {"logo": f"{_BF}/enviame.io/w/400/h/400",      "web": "https://enviame.io/"},
        "envíame":     {"logo": f"{_BF}/enviame.io/w/400/h/400",      "web": "https://enviame.io/"},
        # 2026-08-05: Shipit se sumó al comparador, así que también entra acá.
        # Felca y Milling NO se pueden sembrar: son empresas chilenas chicas
        # sin logo en ningún CDN público. Sus logos se cargan a mano desde la
        # ficha del courier (POST /transporte/couriers/<id>/logo).
        "shipit":      {"logo": f"{_BF}/shipit.cl/w/400/h/400",       "web": "https://shipit.cl/"},
    }
    actualizados = []
    rows = mysql_fetchall("SELECT id, nombre, logo_url, website FROM transport_couriers") or []
    for r in rows:
        nom = (r.get("nombre") or "").strip().lower()
        match = None
        for kw, data in seeds.items():
            if kw in nom:
                match = data
                break
        if not match:
            continue
        sets, params = [], []
        if not (r.get("logo_url") or "").strip():
            sets.append("logo_url=%s"); params.append(match["logo"])
        if not (r.get("website") or "").strip():
            sets.append("website=%s"); params.append(match["web"])
        if sets:
            params.append(r["id"])
            try:
                mysql_execute(f"UPDATE transport_couriers SET {', '.join(sets)} WHERE id=%s",
                              tuple(params))
                actualizados.append(r["nombre"])
            except Exception as e:
                print(f"[seed-logos] {r['nombre']}: {e}", flush=True)
    _invalidate_couriers_cache()
    return jsonify({"ok": True, "actualizados": actualizados})


@app.route("/transporte/couriers/<int:cid>/logo/archivo", methods=["POST"])
@_tr_required
def tr_courier_subir_logo(cid):
    """Sube el logo de un courier desde la ficha/tarjeta y lo deja en logo_url.

    ⚠ La URL termina en /logo/archivo, NO en /logo: esa última ya está tomada
    por tr_courier_logo() (más abajo), que guarda una URL escrita a mano y la
    usa la pestaña "Logos" de la ficha del courier. Al registrarse primero,
    esta función tapaba a la otra -- Flask no avisa porque los nombres de
    función difieren -- y los tres botones "Guardar" de esa pestaña
    respondían 400 (mandan JSON, acá se espera multipart). Bug real
    introducido y detectado el mismo día (2026-08-05).

    Existe porque el seed automático (tr_couriers_seed_logos) solo cubre a los
    couriers con presencia en un CDN público. Los transportistas chilenos
    chicos con los que trabaja ILUS -- Felca, Milling -- no están en ninguno:
    su logo es un archivo que tiene Daniel. Antes la única vía era pegar una
    URL a mano en el campo "Logo URL", lo que obligaba a hospedar la imagen
    en otro lado primero.

    Sube a GCS con el mismo helper que las fotos de producto (_cloud_upload →
    /f/<key>), así que no depende de un CDN externo que pueda caerse ni de un
    disco local (Cloud Run lo pierde en cada deploy).
    """
    file = request.files.get("logo") or request.files.get("file")
    if not file or not file.filename:
        return jsonify({"ok": False, "error": "No se recibió ninguna imagen."}), 400
    if not allowed_file(file.filename):
        return jsonify({"ok": False, "error": "Formato no permitido. Usa JPG, PNG o WEBP."}), 400

    row = mysql_fetchone("SELECT id, nombre FROM transport_couriers WHERE id=%s", (cid,))
    if not row:
        return jsonify({"ok": False, "error": "El courier no existe."}), 404

    # Daniel, 2026-08-05: "guardarla no Cloudinary, yo quiero que sea en Google
    # Cloud. No trabajes más con Cloudinary". Este chequeo previo se conserva
    # para dar un 503 con mensaje claro; _cloud_upload() ya no tiene salida a
    # Cloudinary en ningún caso.
    if not _gcs_ready():
        print("[courier-logo] GCS no disponible; no se sube el logo.", flush=True)
        return jsonify({"ok": False, "error": _STORAGE_OFF_MSG}), 503

    try:
        ts = int(datetime.now().timestamp())
        url = _cloud_upload(file, public_id=f"courier{cid}_{ts}", folder="ilus/couriers")
    except Exception as e:
        print(f"[courier-logo] error subiendo logo de {row['nombre']}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo subir la imagen. Intenta de nuevo."}), 500

    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("UPDATE transport_couriers SET logo_url=%s WHERE id=%s", (url, cid))
        conn.commit()
    except Exception as e:
        print(f"[courier-logo] error guardando logo_url de {row['nombre']}: {e}", flush=True)
        return jsonify({"ok": False, "error": "La imagen se subió pero no se pudo guardar."}), 500

    _invalidate_couriers_cache()
    return jsonify({"ok": True, "url": url, "courier": row["nombre"]})


@app.route("/transporte/couriers/<int:cid>/api", methods=["GET"])
@_tr_required
def tr_courier_api_data(cid):
    """Returns full courier data as JSON for the ficha page."""
    courier = mysql_fetchone("SELECT * FROM transport_couriers WHERE id=%s", (cid,))
    if not courier:
        return jsonify({"error": "Not found"}), 404
    courier_out = dict(courier)
    # FIX 2026-07-28 (Daniel: "algunas fechas vienen en inglés"): SELECT *
    # trae created_at/updated_at (DATETIME) -- jsonify() los serializaba
    # crudos en RFC 1123 inglés ("Mon, 28 Jul 2026..."). Mismo patrón que
    # el resto de los fixes de esta noche (chile_fmt_filter antes de jsonify).
    for _campo in ("created_at", "updated_at"):
        if courier_out.get(_campo):
            courier_out[_campo] = chile_fmt_filter(courier_out[_campo], "%d/%m/%Y %H:%M:%S")
    return jsonify(courier_out)


