@app.route("/transporte/couriers/<int:cid>/logo", methods=["POST"])
@_tr_required
def tr_courier_logo(cid):
    """Guarda el logo a partir de una URL. Acepta JSON {logo_url, logo_type}.

    2026-08-05 — Daniel: "¿de qué manera se puede guardar el logo como imagen
    y no como un link?" / "no se guardan las imágenes en Google Storage".

    ANTES: se guardaba el texto de la URL tal cual. El logo quedaba en manos de
    un tercero: si esa web lo movía, lo renombraba o se caía, el logo
    desaparecía de TODAS las pantallas de ILUS a la vez — comparador,
    manifiesto y el seguimiento que ve el cliente final.

    AHORA: la imagen se BAJA y se guarda en Google Storage, y se registra la
    dirección propia (/f/…). El link externo se usa una sola vez, para traerla.

    Si la descarga falla (la web bloquea, no es una imagen, pesa demasiado), se
    guarda la URL como antes y se avisa en la respuesta. Es preferible un logo
    dependiente de un tercero a no poder guardar nada — pero el operador se
    entera de la diferencia en vez de creer que quedó en Google.
    """
    d = request.get_json(silent=True) or {}
    logo_url  = (d.get("logo_url") or "").strip()
    logo_type = d.get("logo_type", "principal")

    col_map = {"principal": "logo_url", "square": "logo_square_url", "label": "logo_label_url"}
    col = col_map.get(logo_type, "logo_url")

    aviso = ""
    guardada_en_google = False
    # Las que ya son nuestras (/f/…) no se vuelven a bajar: ya están en Google.
    if logo_url and not logo_url.startswith("/f/"):
        try:
            ts = int(datetime.now().timestamp())
            logo_url = _bajar_imagen_a_gcs(
                logo_url, public_id=f"courier{cid}_{logo_type}_{ts}")
            guardada_en_google = True
        except Exception as e:
            aviso = (f"El logo quedó apuntando a la web original porque no se "
                     f"pudo copiar a Google: {e}")
            print(f"[courier-logo] no se pudo bajar a GCS (cid={cid}): {e}", flush=True)

    conn = get_db()
    try:
        with conn.cursor() as cur:
            for c_def in ["logo_square_url VARCHAR(400)", "logo_label_url VARCHAR(400)",
                          "nombre_fantasia VARCHAR(120)", "giro VARCHAR(150)",
                          "contacto_cargo VARCHAR(120)", "renovacion_automatica TINYINT(1) DEFAULT 0"]:
                try:
                    cur.execute(f"ALTER TABLE transport_couriers ADD COLUMN {c_def}")
                except Exception:
                    pass
            cur.execute(f"UPDATE transport_couriers SET {col}=%s WHERE id=%s", (logo_url, cid))
        conn.commit()
        _invalidate_couriers_cache()
        return jsonify({"ok": True, "logo_url": logo_url,
                        "en_google": guardada_en_google, "aviso": aviso})
    finally:
        conn.close()


@app.route("/transporte/couriers/<int:cid>/comunas/paginated", methods=["GET"])
@_tr_required
def tr_courier_comunas_paginated(cid):
    """Returns paginated, filterable commune pricing."""
    page   = max(1, request.args.get("page", 1, type=int))
    per    = 25
    search = (request.args.get("q") or "").strip()
    region = (request.args.get("region") or "").strip()
    zona   = (request.args.get("zona") or "").strip()

    conditions = ["courier_id=%s"]
    params = [cid]
    if search:
        conditions.append("LOWER(comuna) LIKE LOWER(%s)")
        params.append(f"%{search}%")
    if region:
        conditions.append("region=%s")
        params.append(region)
    if zona:
        conditions.append("zona=%s")
        params.append(zona)

    where  = " AND ".join(conditions)
    total  = (mysql_fetchone(f"SELECT COUNT(*) AS n FROM transport_courier_comunas WHERE {where}", params) or {}).get("n", 0)
    offset = (page - 1) * per
    rows   = mysql_fetchall(
        f"SELECT codigo, sucursal, comuna, zona, region, dias_transito, precios_json "
        f"FROM transport_courier_comunas WHERE {where} ORDER BY region, comuna LIMIT %s OFFSET %s",
        params + [per, offset]
    ) or []

    result = []
    for r in rows:
        item = dict(r)
        if r.get("precios_json"):
            try:
                item["precios"] = json.loads(r["precios_json"])
            except Exception:
                item["precios"] = {}
        else:
            item["precios"] = {}
        del item["precios_json"]
        result.append(item)

    return jsonify({
        "rows":  result,
        "total": total,
        "page":  page,
        "pages": max(1, (total + per - 1) // per),
        "per":   per,
    })


# ── COURIERS: IMPORT / EXPORT / LOOKUP / COMUNAS ─────────────────────────────

@app.route("/transporte/couriers/import", methods=["POST"])
@_tr_required
def transporte_couriers_import():
    """Import commune-based pricing from Excel."""
    import openpyxl, math

    file = request.files.get('file')
    if not file:
        return jsonify({"ok": False, "error": "No se recibió archivo"}), 400

    try:
        wb = openpyxl.load_workbook(file, data_only=True)
    except Exception as exc:
        return jsonify({"ok": False, "error": f"No se pudo leer el Excel: {exc}"}), 400

    # Map sheet names to courier names
    # 'milling' apuntaba a 'Transportes Melling' (con E), que es como quedó
    # escrito el nombre la primera vez. Cada importación de Excel recreaba esa
    # ficha mal escrita y terminamos con DOS couriers para la misma empresa,
    # con las tarifas partidas entre ambos (Daniel, 2026-08-05: "tengo dos
    # transportes que son el mismo... que predomine Transportes Milling").
    # Corregido acá para que no vuelva a nacer el duplicado; las dos fichas ya
    # existentes se unen con /transporte/couriers/fusionar.
    SHEET_MAP = {
        'felca':   'Transporte Felca',
        'milling': 'Transportes Milling',
        'clickex': 'Clickex',
    }

    conn = get_db()
    total_inserted = 0
    results = []

    try:
        with conn.cursor() as cur:
            for sheet_name in wb.sheetnames:
                courier_name = SHEET_MAP.get(sheet_name.lower().strip())
                if not courier_name:
                    results.append({"sheet": sheet_name, "skipped": True, "reason": "Hoja no reconocida"})
                    continue

                # Get or create courier
                cur.execute("SELECT id FROM transport_couriers WHERE LOWER(nombre)=LOWER(%s)", (courier_name,))
                row = cur.fetchone()
                if row:
                    courier_id = row['id']
                else:
                    cur.execute("INSERT INTO transport_couriers (nombre, tipo) VALUES (%s, 'nacional')", (courier_name,))
                    courier_id = cur.lastrowid

                ws = wb[sheet_name]
                header = [ws.cell(1, c).value for c in range(1, ws.max_column + 1)]

                is_clickex = sheet_name.lower().strip() == 'clickex'

                if is_clickex:
                    # Clickex: Región(0), Destino(1), Días(2), Lu-Sa(3-8), then prices from col 9
                    meta_cols = 9
                    comunas_col = 1    # "Destino"
                    region_col  = 0
                    dias_col    = 2
                    dias_entrega_cols = list(range(3, 9))  # Lu Ma Mi Ju Vi Sa
                    dias_names = ['Lu','Ma','Mi','Ju','Vi','Sa']
                else:
                    # Felca/Milling: Codigo(0), Sucursal(1), Comuna(2), ZONA(3), Dias(4), prices from col 5
                    meta_cols = 5
                    comunas_col = 2
                    sucursal_col = 1
                    codigo_col = 0
                    zona_col = 3
                    dias_col = 4

                price_headers = header[meta_cols:]

                # Delete existing data for this courier
                cur.execute("DELETE FROM transport_courier_comunas WHERE courier_id=%s", (courier_id,))

                inserted = 0
                for row_data in ws.iter_rows(min_row=2, values_only=True):
                    if all(v is None for v in row_data):
                        continue

                    if is_clickex:
                        region = str(row_data[region_col] or '').strip()
                        comuna = str(row_data[comunas_col] or '').strip()
                        dias_str = str(row_data[dias_col] or '').strip() if row_data[dias_col] is not None else ''
                        # Dias entrega
                        dias_list = []
                        for i, dn in zip(dias_entrega_cols, dias_names):
                            v = row_data[i]
                            if v and str(v).strip() not in ('', 'None'):
                                dias_list.append(dn)
                        dias_entrega = ','.join(dias_list)
                        sucursal = ''
                        codigo = ''
                        zona = ''
                    else:
                        codigo = str(row_data[codigo_col] or '').strip()
                        sucursal = str(row_data[sucursal_col] or '').strip()
                        comuna = str(row_data[comunas_col] or '').strip()
                        zona = str(row_data[zona_col] or '').strip()
                        dias_val = row_data[dias_col]
                        dias_str = '' if dias_val in ('#N/A', None) else str(dias_val).strip()
                        region = ''
                        dias_entrega = ''

                    if not comuna:
                        continue

                    # Build prices dict
                    price_data = row_data[meta_cols:]
                    precios = {}
                    for ph, pv in zip(price_headers, price_data):
                        if ph is None:
                            continue
                        key = str(ph).strip()
                        if pv is None or str(pv).strip() in ('#N/A', 'N/A', ''):
                            continue
                        try:
                            val_f = float(pv)
                            if not math.isnan(val_f):
                                precios[key] = round(val_f, 2)
                        except (TypeError, ValueError):
                            pass

                    if not precios:
                        continue

                    cur.execute("""
                        INSERT INTO transport_courier_comunas
                            (courier_id, codigo, sucursal, comuna, zona, region, dias_transito, dias_entrega, precios_json)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                        ON DUPLICATE KEY UPDATE
                            codigo=VALUES(codigo), sucursal=VALUES(sucursal),
                            zona=VALUES(zona), region=VALUES(region),
                            dias_transito=VALUES(dias_transito), dias_entrega=VALUES(dias_entrega),
                            precios_json=VALUES(precios_json)
                    """, (courier_id, codigo, sucursal, comuna, zona, region, dias_str, dias_entrega, json.dumps(precios, ensure_ascii=False)))
                    inserted += 1

                total_inserted += inserted
                results.append({"sheet": sheet_name, "courier": courier_name, "courier_id": courier_id, "inserted": inserted})

        conn.commit()
        return jsonify({"ok": True, "total": total_inserted, "results": results})
    except Exception as exc:
        import traceback; traceback.print_exc()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        conn.close()


_XLSX_ILEGAL = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f]")


def _xlsx_cell(v):
    """Deja un valor listo para escribirlo en una celda de Excel.

    Dos cosas, ambas por bugs reales:

    1. openpyxl lanza IllegalCharacterError si el texto trae caracteres de
       control. Llegan desde el ERP en notas, direcciones y observaciones.
       (Ya existía una versión de esto, pero ANIDADA dentro de otra función:
       transporte_couriers_export la llamaba desde fuera de su alcance y
       reventaba con NameError, o sea que "Exportar tarifas" estaba roto.
       Esta versión vive a nivel de módulo para que cualquiera la use.)

    2. Excel interpreta como FÓRMULA cualquier celda que empiece con = + - @
       (o tab/retorno). Un nombre de comuna o de cliente que empiece así se
       ejecutaría al abrir el archivo. Se le antepone un apóstrofo, que Excel
       usa justamente para forzar "esto es texto" y no se ve en la celda.
    """
    if not isinstance(v, str):
        return v
    v = _XLSX_ILEGAL.sub("", v)
    if v[:1] in ("=", "+", "-", "@", "\t", "\r"):
        return "'" + v
    return v


def _sh_llenar_hoja_tarifario_shipit(ws, nombre, red_fill, blanco_font, pesos=None, limite=None):
    """Llena `ws` con la lista de precios de Shipit, cotizada EN VIVO contra
    su API (Shipit no tiene tabla de comunas propia como Felca/Milling/
    FedEx: es un agregador que compara operadores por viaje). Compartida por
    tr_tarifario_de_un_courier_xlsx (tarifario individual, que le pasa los
    `pesos`/`limite` que vengan en la query string) y
    transporte_couriers_export (el consolidado "Exportar tarifas", que usa
    los valores por defecto) para no duplicar la lógica de cotización.

    BUG REAL (2026-08-10, Daniel: "esto no es la realidad, no está Shipit").
    El consolidado armaba una hoja por courier a partir de
    transport_courier_comunas -- como Shipit no tiene filas ahí, quedaba
    afuera en silencio. Esta función es lo que faltaba para incluirlo.

    Devuelve True si escribió filas, False si no se pudo cotizar nada (para
    que el llamador decida si vale la pena dejar la hoja).
    """
    import concurrent.futures as _cf
    import shipit_client as _shc
    import time as _t_dl
    from openpyxl.styles import Font, Alignment
    from openpyxl.utils import get_column_letter

    pesos = list(pesos) if pesos else [1, 3, 5, 10, 15]
    pesos = sorted({p for p in pesos if 0 < p <= _shc.MAX_PESO_KG})[:6]
    limite = limite if limite else min(40, max(1, 200 // max(1, len(pesos))))

    comunas = mysql_fetchall(
        "SELECT TRIM(comuna) AS comuna, COUNT(*) AS n FROM transport_commitments "
        "WHERE comuna IS NOT NULL AND TRIM(comuna) <> '' "
        "GROUP BY TRIM(comuna) ORDER BY n DESC LIMIT %s", (limite,)) or []
    if not comunas or not pesos:
        return False

    origen_id, _ = _shipit_commune_id(_tr_sender_cfg().get("city") or "Quilicura")
    destinos = {}
    for c in comunas:
        try:
            destinos[c["comuna"]], _ = _shipit_commune_id(c["comuna"])
        except Exception:
            destinos[c["comuna"]] = None
    if not origen_id:
        return False

    _deadline = _t_dl.monotonic() + 60
    tareas = [(c["comuna"], p) for c in comunas for p in pesos if destinos.get(c["comuna"])]

    def _cotizar(par):
        comuna, peso = par
        if _t_dl.monotonic() > _deadline:
            return par, None
        payload, errores = _shc.build_rate_payload(
            length=30, width=30, height=30, weight=peso,
            origin_id=origen_id, destiny_id=destinos[comuna])
        if errores:
            return par, None
        r = _shipit_request("POST", _shc.EP_RATES, payload=payload, timeout=8)
        if not r.get("ok"):
            return par, None
        disp = [x for x in _shc.parse_rates_response(r.get("data"))
                if x.get("disponible") and x.get("precio")]
        if not disp:
            return par, None
        disp.sort(key=lambda x: x["precio"])
        return par, disp[0]

    res = {}
    if tareas:
        with _cf.ThreadPoolExecutor(max_workers=8) as pool:
            for par, val in pool.map(_cotizar, tareas):
                res[par] = val

    ws.cell(1, 1, f"Lista de precios — {nombre}").font = Font(bold=True, size=14)
    ws.cell(2, 1, f"Cotizado en vivo el {chile_fmt_filter(datetime.now(), '%d/%m/%Y %H:%M')} "
                  f"· origen: bodega {_tr_sender_cfg().get('city') or 'Quilicura'} · 1 bulto")
    ws.cell(3, 1, "Shipit compara varios operadores y cobra el más barato disponible. "
                  "Estos precios son los vigentes al momento de generar el archivo.")
    enc = ["Comuna", "Envíos ILUS"] + [f"{p:g} kg" for p in pesos] + ["Operador (peso menor)"]
    for ci, h in enumerate(enc, 1):
        c = ws.cell(5, ci, h)
        c.font, c.fill = blanco_font, red_fill
        c.alignment = Alignment(horizontal="center", wrap_text=True)
    huvo_datos = False
    for ri, com in enumerate(comunas, 6):
        ws.cell(ri, 1, _xlsx_cell(com["comuna"]))
        ws.cell(ri, 2, com["n"])
        operador = ""
        for pi, p in enumerate(pesos):
            fila = res.get((com["comuna"], p))
            celda = ws.cell(ri, 3 + pi)
            if fila:
                celda.value = round(fila["precio"])
                celda.number_format = '$#,##0'
                huvo_datos = True
                if not operador:
                    operador = (fila["courier"] or "").replace("_", " ").title()
            else:
                celda.value = "—"
        ws.cell(ri, 3 + len(pesos), _xlsx_cell(operador))
    ws.freeze_panes = "A6"
    for ci in range(1, len(enc) + 1):
        ws.column_dimensions[get_column_letter(ci)].width = 24 if ci in (1, len(enc)) else 13
    return huvo_datos


def _clx_llenar_hoja_tarifario_clickex(ws, nombre, red_fill, blanco_font):
    """Llena `ws` con la matriz de tarifas de Clickex, traída EN VIVO desde
    su API (pedido de Daniel, 2026-08-25: "necesito que en la plantilla del
    courier, cuando consulte de bajar el Excel, necesito que me entregue la
    tarifa que obtenga la API"). A diferencia de Shipit (que cotiza por
    envío simulando pesos), Clickex ya tiene una matriz de tarifas
    PRE-NEGOCIADA por comuna -- no hace falta simular nada, se vuelca la
    matriz completa tal como la devuelve GET /sellerShipmentMatrixCosts.

    Devuelve True si escribió filas, False si no se pudo traer nada (mismo
    contrato que _sh_llenar_hoja_tarifario_shipit, para que el llamador
    decida si vale la pena dejar la hoja).
    """
    from openpyxl.styles import Font, Alignment
    from openpyxl.utils import get_column_letter

    sync = _clickex_sync_tarifas()
    if not sync.get("ok"):
        return False

    tarifas = mysql_fetchall(
        "SELECT comuna, sla_dias, costo_neto FROM clickex_tarifas ORDER BY comuna"
    ) or []
    if not tarifas:
        return False

    ws.cell(1, 1, f"Lista de precios — {nombre}").font = Font(bold=True, size=14)
    ws.cell(2, 1, f"Traído en vivo desde la API de Clickex el "
                  f"{chile_fmt_filter(datetime.now(), '%d/%m/%Y %H:%M')}")
    ws.cell(3, 1, "Tarifa plana pre-negociada por comuna (matriz del seller autenticado).")
    enc = ["Comuna", "SLA (días)", "Tarifa neta"]
    for ci, h in enumerate(enc, 1):
        c = ws.cell(5, ci, h)
        c.font, c.fill = blanco_font, red_fill
        c.alignment = Alignment(horizontal="center", wrap_text=True)
    for ri, t in enumerate(tarifas, 6):
        ws.cell(ri, 1, _xlsx_cell(t["comuna"]))
        ws.cell(ri, 2, t["sla_dias"])
        celda = ws.cell(ri, 3, float(t["costo_neto"]) if t["costo_neto"] is not None else None)
        celda.number_format = '$#,##0'
    ws.freeze_panes = "A6"
    for ci in range(1, len(enc) + 1):
        ws.column_dimensions[get_column_letter(ci)].width = 24 if ci == 1 else 14
    return True


@app.route("/transporte/couriers/export", methods=["GET"])
@_tr_required
def transporte_couriers_export():
    """Export all courier pricing as Excel, one sheet per courier.

    BUG REAL (2026-08-10, Daniel, con el archivo descargado en la mano:
    "esto no es la realidad, no está Shipit"). Shipit no tiene filas en
    transport_courier_comunas (cotiza en vivo, no tiene tabla) así que
    quedaba afuera de este export en silencio -- se agrega su hoja cotizando
    su API en vivo, igual que ya hace el tarifario individual (mismo
    helper: _sh_llenar_hoja_tarifario_shipit).
    """
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    from io import BytesIO

    couriers = mysql_fetchall(
        "SELECT id, nombre FROM transport_couriers WHERE activo=1 ORDER BY nombre"
    ) or []

    wb = openpyxl.Workbook()
    wb.remove(wb.active)

    RED_FILL = PatternFill("solid", fgColor="CC0000")
    WHITE_FONT = Font(color="FFFFFF", bold=True)

    for c in couriers:
        if "shipit" in (c['nombre'] or "").lower():
            ws = wb.create_sheet(title=c['nombre'][:31])
            try:
                if not _sh_llenar_hoja_tarifario_shipit(ws, c['nombre'], RED_FILL, WHITE_FONT):
                    wb.remove(ws)
            except Exception as e:
                print(f"[couriers export] Shipit en vivo falló: {e}", flush=True)
                wb.remove(ws)
            continue

        if "clickex" in (c['nombre'] or "").lower():
            ws = wb.create_sheet(title=c['nombre'][:31])
            try:
                if not _clx_llenar_hoja_tarifario_clickex(ws, c['nombre'], RED_FILL, WHITE_FONT):
                    wb.remove(ws)
            except Exception as e:
                print(f"[couriers export] Clickex en vivo falló: {e}", flush=True)
                wb.remove(ws)
            continue

        rows = mysql_fetchall(
            "SELECT codigo, sucursal, comuna, zona, region, dias_transito, dias_entrega, precios_json "
            "FROM transport_courier_comunas WHERE courier_id=%s ORDER BY region, comuna",
            (c['id'],)
        ) or []
        if not rows:
            continue

        ws = wb.create_sheet(title=c['nombre'][:31])

        # Collect all weight keys
        all_keys = []
        for r in rows:
            if r.get('precios_json'):
                try:
                    keys = list(json.loads(r['precios_json']).keys())
                    for k in keys:
                        if k not in all_keys:
                            all_keys.append(k)
                except Exception:
                    pass

        # Headers
        headers = ['Codigo','Sucursal','Comuna','Zona','Region','Dias Transito','Dias Entrega'] + all_keys
        for ci, h in enumerate(headers, 1):
            cell = ws.cell(1, ci, h)
            cell.font = WHITE_FONT
            cell.fill = RED_FILL
            cell.alignment = Alignment(horizontal='center')

        for ri, r in enumerate(rows, 2):
            precios = {}
            if r.get('precios_json'):
                try: precios = json.loads(r['precios_json'])
                except Exception: pass

            row_vals = [
                r.get('codigo',''), r.get('sucursal',''), r.get('comuna',''),
                r.get('zona',''), r.get('region',''), r.get('dias_transito',''), r.get('dias_entrega','')
            ] + [precios.get(k,'') for k in all_keys]

            for ci, v in enumerate(row_vals, 1):
                ws.cell(ri, ci, _xlsx_cell(v))

    if not wb.sheetnames:
        ws = wb.create_sheet("Sin datos")
        ws.cell(1,1,"No hay tarifas importadas aún.")

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)

    from flask import send_file
    return send_file(
        buf,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name='ILUS_Tarifas_Couriers.xlsx'
    )


@app.route("/transporte/couriers/<int:cid>/tarifario.xlsx", methods=["GET"])
@_tr_required
def tr_tarifario_de_un_courier_xlsx(cid):
    """Tarifario de UN solo courier, en su propio archivo.

    Daniel, 2026-08-05: "en la parte de los couriers deja la tarifa de cada
    uno, no todos juntos". Además de ser lo que se necesita para trabajar con
    un transportista puntual, resuelve el problema de confidencialidad del
    Excel comparado: al no poner a FedEx en la misma planilla que Felca y
    Milling, ya no se puede deducir la política de precios dividiendo
    columnas. Este archivo SÍ se puede compartir con el courier al que
    corresponde.

    Dos casos:
      · Couriers con tabla negociada → se vuelca su tabla tal cual.
      · Shipit → no tiene tabla (es un agregador, cotiza en vivo), así que
        se le CONSTRUYE la lista consultando su API para las comunas donde
        ILUS más despacha, con varios pesos. Es la "lista de precios de
        Shipit" que no existía por ningún lado.
    """
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    from io import BytesIO

    courier = mysql_fetchone(
        "SELECT id, nombre FROM transport_couriers WHERE id=%s", (cid,))
    if not courier:
        return jsonify({"error": "Ese courier no existe."}), 404
    nombre = courier["nombre"] or "Courier"
    es_shipit = "shipit" in nombre.lower()
    es_clickex = "clickex" in nombre.lower()

    wb = openpyxl.Workbook()
    RED = PatternFill("solid", fgColor="CC0000")
    VERDE = PatternFill("solid", fgColor="DCFCE7")
    BLANCO = Font(color="FFFFFF", bold=True)
    ws = wb.active
    ws.title = nombre[:31]

    if es_shipit:
        import shipit_client as _shc

        # La validación de query params (con sus 400 propios) se queda ACÁ,
        # donde tiene sentido devolver un error HTTP -- el resto de la
        # cotización vive en _sh_llenar_hoja_tarifario_shipit, compartida con
        # el consolidado (transporte_couriers_export) para no tener dos
        # copias de la misma lógica divergiendo con el tiempo (encontrado en
        # code review 2026-08-10: la función nueva decía "compartida" pero
        # esta ruta seguía con su propia copia).
        try:
            pesos = [float(p) for p in (request.args.get("pesos") or "1,3,5,10,15").split(",") if p.strip()]
        except ValueError:
            return jsonify({"error": "Parámetro 'pesos' inválido"}), 400
        pesos = sorted({p for p in pesos if 0 < p <= _shc.MAX_PESO_KG})[:6]
        if not pesos:
            return jsonify({"error": f"Shipit solo acepta hasta {_shc.MAX_PESO_KG:g} kg por bulto."}), 400
        try:
            limite = max(1, min(int(request.args.get("limite") or 40), 120))
        except ValueError:
            limite = 40
        limite = min(limite, max(1, 200 // len(pesos)))

        if not _sh_llenar_hoja_tarifario_shipit(ws, nombre, RED, BLANCO, pesos=pesos, limite=limite):
            return jsonify({"error": "No se pudo cotizar Shipit: sin comunas con historial "
                                      "o sin respuesta de su API. Intenta de nuevo."}), 404
    elif es_clickex:
        # Matriz pre-negociada por comuna, traída en vivo -- no hay pesos ni
        # límite que pedir por query string (a diferencia de Shipit, que
        # cotiza por envío simulado). Ver _clx_llenar_hoja_tarifario_clickex.
        if not _clx_llenar_hoja_tarifario_clickex(ws, nombre, RED, BLANCO):
            return jsonify({"error": "No se pudo traer la tarifa de Clickex desde su API. "
                                      "Intenta de nuevo en unos segundos."}), 404
    else:
        filas = mysql_fetchall(
            "SELECT codigo, sucursal, comuna, zona, region, dias_transito, dias_entrega, precios_json "
            "FROM transport_courier_comunas WHERE courier_id=%s ORDER BY region, comuna",
            (cid,)) or []
        ws.cell(1, 1, f"Tarifario — {nombre}").font = Font(bold=True, size=14)
        ws.cell(2, 1, f"{len(filas)} comunas · generado el "
                      f"{chile_fmt_filter(datetime.now(), '%d/%m/%Y %H:%M')}")
        if not filas:
            ws.cell(4, 1, "Este courier todavía no tiene tarifas cargadas. "
                          "Impórtalas desde un Excel en su ficha.")
        else:
            tramos = []
            for r in filas:
                if r.get("precios_json"):
                    try:
                        for k in json.loads(r["precios_json"]):
                            if k not in tramos:
                                tramos.append(k)
                    except Exception:
                        pass
            enc = ["Comuna", "Zona", "Región", "Días tránsito"] + [f"{k} kg" for k in tramos]
            for ci, h in enumerate(enc, 1):
                c = ws.cell(4, ci, h)
                c.font, c.fill = BLANCO, RED
                c.alignment = Alignment(horizontal="center", wrap_text=True)
            for ri, r in enumerate(filas, 5):
                precios = {}
                if r.get("precios_json"):
                    try:
                        precios = json.loads(r["precios_json"])
                    except Exception:
                        pass
                base = [r.get("comuna"), r.get("zona"), r.get("region"), r.get("dias_transito")]
                for ci, v in enumerate(base, 1):
                    ws.cell(ri, ci, _xlsx_cell(v if v is not None else ""))
                for pi, k in enumerate(tramos):
                    celda = ws.cell(ri, 5 + pi)
                    v = precios.get(k)
                    if v not in (None, ""):
                        try:
                            celda.value = float(v)
                            celda.number_format = '$#,##0'
                        except (TypeError, ValueError):
                            celda.value = _xlsx_cell(v)
            ws.freeze_panes = "A5"
            for ci in range(1, len(enc) + 1):
                ws.column_dimensions[get_column_letter(ci)].width = 22 if ci <= 3 else 12

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    from flask import send_file
    _slug = "".join(ch if ch.isalnum() else "_" for ch in nombre)[:40]
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True,
        download_name=f"ILUS_Tarifario_{_slug}_{datetime.now():%Y%m%d}.xlsx",
    )


def _doc_label(tido, nudo):
    """Número de documento como lo escribe una persona: "FCV 11212".

    El ERP guarda el correlativo con ceros a la izquierda hasta 10 dígitos
    ("0000011212"), que es un detalle de su formato interno y no algo que
    nadie diga en voz alta. En el modal de seguimiento salía crudo y Daniel
    lo pidió limpio (2026-08-05: "la factura tiene cualquier cero, sería
    ideal que no tuviera").

    Se conserva el valor original si al quitar los ceros no queda nada (un
    documento "0000000000"): es preferible mostrar algo raro a mostrar vacío.
    Misma regla que ya usaba 'nudo_display' en el detalle del compromiso.
    """
    _t = str(tido or "").strip()
    _n = str(nudo or "").strip()
    _n = _n.lstrip("0") or _n
    return f"{_t} {_n}".strip()


def _tr_brackets_con_precio(precios_json_raw):
    """Cuántos tramos de peso con precio real tiene una fila de tarifa.

    Es la medida de "qué tan amplia" es una tarifa: una comuna con 20 tramos
    cargados vale más que la misma comuna con 3. Se usa para decidir cuál fila
    sobrevive al fusionar dos couriers duplicados.
    """
    if not precios_json_raw:
        return 0
    try:
        precios = json.loads(precios_json_raw)
    except Exception:
        return 0
    if not isinstance(precios, dict):
        return 0
    return sum(1 for v in precios.values() if v not in (None, "", 0))


def _tr_columna_existe(tabla, columna):
    """¿La tabla tiene esa columna? 1 SELECT barato a information_schema.

    Se usa antes de tocar columnas que se agregaron por migración y que en
    producción pueden no existir (ILUS_SKIP_MIGRATIONS=1). Preguntar primero
    es más limpio que dejar reventar el UPDATE dentro de una transacción.
    """
    try:
        return bool(mysql_fetchone(
            "SELECT 1 AS y FROM information_schema.COLUMNS "
            "WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s AND COLUMN_NAME=%s LIMIT 1",
            (tabla, columna)))
    except Exception:
        return False


def _tr_fusionar_couriers(id_destino, id_origen, ejecutar=False,
                          renombrar_manifiestos=False):
    """Fusiona dos fichas de courier que en realidad son la misma empresa.

    Caso que lo motivó (Daniel, 2026-08-05): "tengo dos transportes que son el
    mismo, Melling y Milling son el mismo. Deja la lista de precios más amplia
    y que predomine Transportes Milling."

    Qué hace:
      · Las comunas que solo tiene el ORIGEN se mueven al DESTINO.
      · Las comunas que están en LOS DOS: gana la que tenga más tramos de peso
        con precio cargado ("la lista más amplia"). Si empatan, se conserva la
        del destino y la del origen se descarta.
      · Las tarifas, los contratos y los choferes del ORIGEN también se mueven
        al DESTINO (ver abajo).
      · El origen se DESACTIVA (activo=0), NO se borra: los manifiestos
        históricos referencian al courier por NOMBRE, así que borrar la fila
        dejaría documentos viejos apuntando a algo que ya no existe.

    2026-08-05 — QUÉ LE FALTABA
    ---------------------------
    La versión anterior movía SOLO las comunas. Las tarifas, los contratos y
    los choferes del origen se quedaban colgando de una ficha desactivada: no
    se borraban, pero desaparecían de la vista, y la tarjeta del sobreviviente
    seguía diciendo "Sin contrato" aunque el contrato estuviera cargado en la
    ficha absorbida. Ahora se mueven en la MISMA transacción.

    LOS MANIFIESTOS HISTÓRICOS
    --------------------------
    transport_manifests guarda el courier como TEXTO, no con clave foránea.
    Fusionar las fichas no cambia esos textos: los manifiestos viejos siguen
    diciendo «Melling». No quedan huérfanos (nunca apuntaron a un id), pero sí
    quedan repartidos entre los dos nombres, así que los despachos del mes y
    los filtros por courier los cuentan por separado.

    Por eso `renombrar_manifiestos` existe y viene APAGADO por default:
    reescribir el histórico es una decisión de Daniel, no del barrido. El
    informe SIEMPRE dice cuántos manifiestos quedarían con el nombre viejo,
    se renombren o no.

    Con ejecutar=False no toca NADA: solo devuelve el informe de lo que haría.
    Eso permite mirar el resultado antes de decidir. Nunca lanza.
    """
    informe = {"ok": False, "ejecutado": False, "destino": None, "origen": None,
               "comunas_movidas": 0, "comunas_reemplazadas": 0,
               "comunas_descartadas": 0, "detalle": [], "error": None,
               "tarifas_movidas": 0, "contratos_movidos": 0, "choferes_movidos": 0,
               "manifiestos_nombre_viejo": 0, "manifiestos_renombrados": 0}
    try:
        d = mysql_fetchone("SELECT id, nombre, activo FROM transport_couriers WHERE id=%s", (id_destino,))
        o = mysql_fetchone("SELECT id, nombre, activo FROM transport_couriers WHERE id=%s", (id_origen,))
        if not d or not o:
            informe["error"] = "Alguno de los dos couriers no existe."
            return informe
        if int(id_destino) == int(id_origen):
            informe["error"] = "Son el mismo courier."
            return informe
        informe["destino"] = {"id": d["id"], "nombre": d["nombre"]}
        informe["origen"] = {"id": o["id"], "nombre": o["nombre"]}

        com_o = mysql_fetchall(
            "SELECT id, comuna, precios_json FROM transport_courier_comunas WHERE courier_id=%s",
            (id_origen,)) or []
        com_d = mysql_fetchall(
            "SELECT id, comuna, precios_json FROM transport_courier_comunas WHERE courier_id=%s",
            (id_destino,)) or []
        por_comuna_d = {(r["comuna"] or "").strip().lower(): r for r in com_d}

        # Se decide TODO primero y se escribe después, en UNA transacción.
        # mysql_execute hace commit por sentencia: si la fusión se cortara a
        # la mitad quedarían tarifas borradas sin su reemplazo, y no hay forma
        # de recuperarlas. Acá o pasa todo o no pasa nada.
        plan = []   # (accion, id_fila_origen, id_fila_destino, precios_json)
        for r in com_o:
            clave = (r["comuna"] or "").strip().lower()
            gemela = por_comuna_d.get(clave)
            n_o = _tr_brackets_con_precio(r.get("precios_json"))
            if not gemela:
                informe["comunas_movidas"] += 1
                informe["detalle"].append(
                    {"comuna": r["comuna"], "accion": "se mueve", "tramos": n_o})
                plan.append(("mover", r["id"], None, None))
                continue
            n_d = _tr_brackets_con_precio(gemela.get("precios_json"))
            if n_o > n_d:
                informe["comunas_reemplazadas"] += 1
                informe["detalle"].append(
                    {"comuna": r["comuna"], "accion": "reemplaza a la del destino",
                     "tramos": n_o, "tramos_destino": n_d})
                # NO se borra la fila del destino: se le copia la lista más
                # amplia y se descarta la del origen. Así la fila que sobrevive
                # conserva su id y su historial.
                plan.append(("ampliar", r["id"], gemela["id"], r.get("precios_json")))
            else:
                informe["comunas_descartadas"] += 1
                informe["detalle"].append(
                    {"comuna": r["comuna"], "accion": "se descarta (el destino es igual o más amplio)",
                     "tramos": n_o, "tramos_destino": n_d})
                plan.append(("descartar", r["id"], None, None))

        # Lo demás que cuelga del origen y que ANTES se quedaba invisible en la
        # ficha desactivada. Se cuenta siempre (la vista previa lo muestra) y
        # se mueve al ejecutar.
        def _cuenta(sql, params):
            try:
                return int((mysql_fetchone(sql, params) or {}).get("n") or 0)
            except Exception:
                return 0

        informe["tarifas_movidas"] = _cuenta(
            "SELECT COUNT(*) AS n FROM transport_courier_tarifas WHERE courier_id=%s",
            (id_origen,))
        informe["contratos_movidos"] = _cuenta(
            "SELECT COUNT(*) AS n FROM transport_courier_contratos WHERE courier_id=%s",
            (id_origen,))
        # transport_drivers.courier_id se agregó por migración: puede no existir.
        _hay_choferes = _tr_columna_existe("transport_drivers", "courier_id")
        if _hay_choferes:
            informe["choferes_movidos"] = _cuenta(
                "SELECT COUNT(*) AS n FROM transport_drivers WHERE courier_id=%s",
                (id_origen,))

        # Manifiestos históricos que nombran al courier absorbido (texto, no FK).
        informe["manifiestos_nombre_viejo"] = _cuenta(
            "SELECT COUNT(*) AS n FROM transport_manifests "
            "WHERE LOWER(TRIM(courier)) = LOWER(TRIM(%s))",
            (o["nombre"] or "",))

        if ejecutar:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    for accion, id_o, id_d, precios in plan:
                        if accion == "mover":
                            cur.execute("UPDATE transport_courier_comunas SET courier_id=%s "
                                        "WHERE id=%s", (id_destino, id_o))
                        elif accion == "ampliar":
                            cur.execute("UPDATE transport_courier_comunas SET precios_json=%s "
                                        "WHERE id=%s", (precios, id_d))
                            cur.execute("DELETE FROM transport_courier_comunas WHERE id=%s", (id_o,))
                        else:
                            cur.execute("DELETE FROM transport_courier_comunas WHERE id=%s", (id_o,))
                    # Tarifas, contratos y choferes: se REASIGNAN, nunca se
                    # borran (REGLA #4.2). Van en la MISMA transacción que las
                    # comunas: o la ficha queda fusionada entera, o no se
                    # fusiona nada. A medio camino sería peor que no empezar.
                    cur.execute("UPDATE transport_courier_tarifas SET courier_id=%s "
                                "WHERE courier_id=%s", (id_destino, id_origen))
                    cur.execute("UPDATE transport_courier_contratos SET courier_id=%s "
                                "WHERE courier_id=%s", (id_destino, id_origen))
                    if _hay_choferes:
                        cur.execute("UPDATE transport_drivers SET courier_id=%s "
                                    "WHERE courier_id=%s", (id_destino, id_origen))
                    if renombrar_manifiestos and (o["nombre"] or "").strip():
                        cur.execute(
                            "UPDATE transport_manifests SET courier=%s "
                            "WHERE LOWER(TRIM(courier)) = LOWER(TRIM(%s))",
                            (d["nombre"], o["nombre"]))
                        informe["manifiestos_renombrados"] = cur.rowcount or 0
                    cur.execute("UPDATE transport_couriers SET activo=0 WHERE id=%s", (id_origen,))
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            _invalidate_couriers_cache()
            informe["ejecutado"] = True
            _audit("courier_fusion", target_type="courier", target_id=id_destino,
                   details={"absorbido": o["nombre"], "sobrevive": d["nombre"],
                            "movidas": informe["comunas_movidas"],
                            "reemplazadas": informe["comunas_reemplazadas"],
                            "descartadas": informe["comunas_descartadas"],
                            "tarifas": informe["tarifas_movidas"],
                            "contratos": informe["contratos_movidos"],
                            "choferes": informe["choferes_movidos"],
                            "manifiestos_renombrados": informe["manifiestos_renombrados"]})
        informe["ok"] = True
        return informe
    except Exception as e:
        print(f"[fusion-courier] error: {e}", flush=True)
        informe["error"] = "No se pudo completar la fusión."
        return informe


@app.route("/transporte/couriers/fusionar", methods=["GET", "POST"])
@_tr_required
def tr_couriers_fusionar():
    """Fusiona dos fichas de courier duplicadas (misma empresa, dos filas).

    GET  -> detecta duplicados por nombre normalizado y muestra qué haría,
            SIN tocar nada. Es la vista que hay que mirar antes de decidir.
    POST -> ejecuta la fusión indicada (destino_id, origen_id). Solo superadmin.

    Los duplicados se detectan con el MISMO criterio que ya usa el motor de
    tarifas para cotizar (transporte_tarifas.slug_para_courier): si dos fichas
    resuelven al mismo slug, para el sistema ya son el mismo courier -- solo
    que la lista los muestra dos veces y las tarifas quedan partidas.
    """
    couriers = mysql_fetchall(
        "SELECT id, nombre, activo FROM transport_couriers ORDER BY id") or []
    grupos = {}
    for c in couriers:
        slug = _ttar.slug_para_courier(c["nombre"] or "")
        if not slug:
            continue
        grupos.setdefault(slug, []).append(c)
    duplicados = {s: cs for s, cs in grupos.items() if len(cs) > 1}

    if request.method == "GET":
        # Para cada grupo duplicado se propone quién sobrevive: el que ya está
        # activo y, entre ellos, el que tenga más comunas cargadas.
        #
        # OJO — la propuesta es solo eso, una propuesta. Daniel pidió que
        # predomine un nombre concreto ("que predomine Transportes Milling") y
        # ese criterio no se puede deducir de los datos: puede perfectamente
        # ganar el otro si tiene más comunas cargadas. Por eso cada propuesta
        # viaja con `opciones`: las dos fichas con sus números, para que la
        # pantalla pueda ofrecer invertir la dirección antes de confirmar. El
        # POST ya acepta destino_id/origen_id explícitos, así que invertir es
        # solo mandarlos al revés.
        propuestas = []
        for slug, cs in duplicados.items():
            enriquecidos = []
            for c in cs:
                n = (mysql_fetchone(
                    "SELECT COUNT(*) AS n FROM transport_courier_comunas WHERE courier_id=%s",
                    (c["id"],)) or {}).get("n", 0)
                # Cuánta historia real carga cada nombre: los manifiestos
                # guardan el courier como texto, así que este número dice qué
                # nombre está usando de verdad la operación.
                nm = (mysql_fetchone(
                    "SELECT COUNT(*) AS n FROM transport_manifests "
                    "WHERE LOWER(TRIM(courier)) = LOWER(TRIM(%s))",
                    (c["nombre"] or "",)) or {}).get("n", 0)
                nk = (mysql_fetchone(
                    "SELECT COUNT(*) AS n FROM transport_courier_contratos WHERE courier_id=%s",
                    (c["id"],)) or {}).get("n", 0)
                enriquecidos.append(dict(c, comunas=n, manifiestos=nm, contratos=nk))
            enriquecidos.sort(key=lambda x: (int(x.get("activo") or 0), x["comunas"]), reverse=True)
            destino = enriquecidos[0]
            for origen in enriquecidos[1:]:
                propuestas.append({
                    "slug": slug,
                    "sobrevive": destino,
                    "se_absorbe": origen,
                    "opciones": enriquecidos,
                    "simulacion": _tr_fusionar_couriers(destino["id"], origen["id"], ejecutar=False),
                })
        return jsonify({"ok": True, "duplicados": len(propuestas), "propuestas": propuestas})

    if not g.permissions.get("superadmin"):
        return jsonify({"ok": False, "error": "Solo superadmin puede fusionar couriers."}), 403
    data = request.get_json(silent=True) or {}
    try:
        destino_id = int(data.get("destino_id"))
        origen_id = int(data.get("origen_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "Faltan destino_id / origen_id."}), 400
    # Reescribir el nombre del courier en los manifiestos históricos es opcional
    # y viene apagado: es tocar el histórico, y esa decisión es de Daniel.
    r = _tr_fusionar_couriers(
        destino_id, origen_id, ejecutar=True,
        renombrar_manifiestos=bool(data.get("renombrar_manifiestos")))
    return jsonify(r), (200 if r.get("ok") else 400)


@app.route("/transporte/couriers/diagnostico-direcciones.xlsx", methods=["GET"])
@_tr_required
def tr_diagnostico_direcciones_xlsx():
    """Excel con las direcciones que Shipit va a rechazar, para corregirlas ANTES.

    Shipit exige calle y número SEPARADOS. En ILUS la dirección es un solo
    texto libre, así que hay que partirla (shipit_client.split_street_number).
    Este diagnóstico corre esa función sobre el historial real y responde la
    única pregunta que importa antes de la primera carga masiva: ¿cuántas
    direcciones no se pueden separar con certeza?

    Es READ-ONLY: no modifica ni una fila. Devuelve una hoja "Resumen" con los
    porcentajes y una hoja "Para corregir" con el detalle, lista para repartir.

    Se hace en Excel y no en pantalla a propósito: el resultado no es para
    mirar, es para que alguien vaya corrigiendo direcciones una por una.
    """
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    import shipit_client as _shc

    try:
        limite = max(1, min(int(request.args.get("limite") or 5000), 20000))
    except ValueError:
        limite = 5000

    filas = mysql_fetchall(
        "SELECT tido, nudo, cliente_nombre, comuna, direccion "
        "FROM transport_commitments "
        "WHERE direccion IS NOT NULL AND TRIM(direccion) <> '' "
        "ORDER BY id DESC LIMIT %s",
        (limite,)
    ) or []
    if not filas:
        return jsonify({"error": "No hay direcciones cargadas todavía."}), 404

    ok, con_aviso, bloqueadas = [], [], []
    for f in filas:
        calle, numero, problemas = _shc.split_street_number(f.get("direccion"))
        registro = dict(f, calle=calle, numero=numero,
                        problema=" · ".join(problemas) if problemas else "")
        if not problemas:
            ok.append(registro)
        elif numero:                      # se resolvió, pero conviene revisar
            con_aviso.append(registro)
        else:                             # sin número: Shipit lo rechaza
            bloqueadas.append(registro)

    total = len(filas)
    wb = openpyxl.Workbook()
    RED = PatternFill("solid", fgColor="CC0000")
    BLANCO = Font(color="FFFFFF", bold=True)

    ws = wb.active
    ws.title = "Resumen"
    ws.cell(1, 1, "¿Cuántas direcciones puede procesar Shipit?").font = Font(bold=True, size=14)
    ws.cell(2, 1, f"Generado el {chile_fmt_filter(datetime.now(), '%d/%m/%Y %H:%M')} · "
                  f"{total} direcciones revisadas (las más recientes)")
    ws.cell(3, 1, "Shipit exige calle y número por separado. Las direcciones bloqueadas "
                  "hay que corregirlas antes de despachar por Shipit.")
    fila_res = [
        ("Se separan sin problema", len(ok), "Listas para Shipit"),
        ("Se separan, pero conviene revisar", len(con_aviso),
         "El texto venía sin puntuación clara; el número elegido puede no ser el correcto"),
        ("BLOQUEADAS: sin número reconocible", len(bloqueadas),
         "Shipit las va a rechazar. Hay que completarlas a mano"),
    ]
    for ci, h in enumerate(["Situación", "Direcciones", "%", "Qué significa"], 1):
        c = ws.cell(5, ci, h)
        c.font, c.fill = BLANCO, RED
        c.alignment = Alignment(horizontal="center")
    for ri, (etiqueta, n, detalle) in enumerate(fila_res, 6):
        ws.cell(ri, 1, etiqueta)
        ws.cell(ri, 2, n)
        ws.cell(ri, 3, (n / total) if total else 0).number_format = "0.0%"
        ws.cell(ri, 4, detalle)
    for ci, w in enumerate([36, 14, 10, 70], 1):
        ws.column_dimensions[get_column_letter(ci)].width = w

    ws2 = wb.create_sheet("Para corregir")
    encabezados = ["Documento", "Cliente", "Comuna", "Dirección actual",
                   "Calle detectada", "N°", "Qué pasa"]
    for ci, h in enumerate(encabezados, 1):
        c = ws2.cell(1, ci, h)
        c.font, c.fill = BLANCO, RED
        c.alignment = Alignment(horizontal="center")
    # Primero las bloqueadas (las urgentes), después las que solo avisan.
    for ri, r in enumerate(bloqueadas + con_aviso, 2):
        vals = [
            f"{r.get('tido') or ''} {r.get('nudo') or ''}".strip(),
            r.get("cliente_nombre") or "", r.get("comuna") or "",
            r.get("direccion") or "", r.get("calle") or "",
            r.get("numero") or "", r.get("problema") or "",
        ]
        for ci, v in enumerate(vals, 1):
            ws2.cell(ri, ci, _xlsx_cell(v))
    ws2.freeze_panes = "A2"
    for ci, w in enumerate([16, 28, 18, 42, 32, 8, 80], 1):
        ws2.column_dimensions[get_column_letter(ci)].width = w
    if not (bloqueadas or con_aviso):
        ws2.cell(2, 1, "Ninguna dirección quedó bloqueada. Todo listo para Shipit.")

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    from flask import send_file
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True,
        download_name=f"ILUS_Direcciones_Shipit_{datetime.now():%Y%m%d}.xlsx",
    )


@app.route("/transporte/couriers/tarifario-comparado.xlsx", methods=["GET"])
@_tr_required
def tr_tarifario_comparado_xlsx():
    """Excel comparativo: cuánto cobra CADA courier por la misma comuna y peso.

    Pedido de Daniel (2026-08-05): "compárteme la lista de precios en un excel
    ... no veo muy atractivo los precios de Shipit, veo más barato Clickex".
    Esto es lo que permite responderlo con datos y no con una impresión: se
    cotiza la MISMA comuna y el MISMO peso en todos los couriers y se deja el
    delta a la vista.

    · Las comunas salen del historial REAL de ILUS (transport_commitments),
      ordenadas por cantidad de envíos: no tiene sentido comparar 727 comunas
      si el 90% del volumen se va en 40.
    · Los precios de Clickex/Felca/Milling/FedEx salen de las tablas locales
      (instantáneo). Solo Shipit se cotiza contra su API en vivo, así que el
      tiempo total lo manda la cantidad de llamadas: comunas × pesos.
    · Los pesos sobre el tope de Shipit no se consultan (se marcan como no
      aplicables) para no gastar llamadas en algo que ya sabemos que rechaza.

    Query params (todos opcionales):
      pesos=1,3,5,10,15   hasta 6 pesos en kg
      limite=40           cuántas comunas (máx 120)
    """
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    import concurrent.futures as _cf
    import shipit_client as _shc

    # ── Parámetros acotados ──────────────────────────────────────────
    try:
        pesos = [float(p) for p in (request.args.get("pesos") or "1,3,5,10,15").split(",") if p.strip()]
    except ValueError:
        return jsonify({"error": "Parámetro 'pesos' inválido"}), 400
    pesos = sorted({p for p in pesos if p > 0})[:6]
    if not pesos:
        return jsonify({"error": "Indica al menos un peso"}), 400
    try:
        limite = max(1, min(int(request.args.get("limite") or 40), 120))
    except ValueError:
        limite = 40
    # El costo real es comunas × pesos, no cada factor por separado: con
    # limite=120 y 6 pesos daban 720 llamadas a Shipit, muy por encima de los
    # 90 s de gunicorn (Dockerfile) -- el árbitro mata el worker y se lleva
    # sus 8 hilos, o sea la mitad de la capacidad de la instancia. Se acota
    # el PRODUCTO a 200 cotizaciones.
    MAX_COTIZACIONES = 200
    limite = min(limite, max(1, MAX_COTIZACIONES // len(pesos)))

    # ── Comunas por volumen real de ILUS ─────────────────────────────
    filas_comuna = mysql_fetchall(
        "SELECT TRIM(comuna) AS comuna, COUNT(*) AS n "
        "FROM transport_commitments "
        "WHERE comuna IS NOT NULL AND TRIM(comuna) <> '' "
        "GROUP BY TRIM(comuna) ORDER BY n DESC LIMIT %s",
        (limite,)
    ) or []
    if not filas_comuna:
        return jsonify({"error": "No hay comunas con historial de envíos todavía."}), 404

    # BUG REAL (2026-08-10, Daniel: "hay transportes que nada que ver...
    # necesito que solo me entregues los transportes que están activos").
    # Esta lista estaba fija en el código (Clickex/Felca/Milling/FedEx) sin
    # mirar el interruptor Habilitado/Deshabilitado de cada courier -- un
    # courier desactivado (ej. Clickex, "hasta que compartan la API") seguía
    # apareciendo acá igual. Ahora sale de los couriers realmente activos,
    # mapeados a su tabla de tarifas con el mismo traductor que ya usa el
    # resto del motor (transporte_tarifas.slug_para_courier). Shipit no
    # entra por acá a propósito: no tiene tabla, se cotiza aparte más abajo
    # (columna "Shipit").
    _couriers_activos = mysql_fetchall(
        "SELECT nombre FROM transport_couriers WHERE activo=1 ORDER BY nombre") or []
    SLUGS = []
    _slugs_vistos = set()
    for _ca in _couriers_activos:
        _slug = _ttar.slug_para_courier(_ca.get("nombre") or "")
        if not _slug or _slug in _slugs_vistos:
            continue
        _slugs_vistos.add(_slug)
        SLUGS.append((_slug, _ttar.NOMBRE.get(_slug, _ca.get("nombre") or _slug)))

    # Precalentar la caché de tarifas ANTES de abrir hilos: _ttar._load lee
    # MySQL y dentro de un hilo no hay contexto Flask (mismo bug que rompió
    # Shipit en el comparador el 2026-08-05).
    for slug, _ in SLUGS:
        try:
            _ttar.cotizar(slug, filas_comuna[0]["comuna"], 1, 0)
        except Exception:
            pass

    # Clickex, igual que Shipit, se cotiza en vivo (2026-08-25, pedido de
    # Daniel) -- pero a diferencia de Shipit su matriz es plana por comuna
    # (sin tramos de peso), así que basta sincronizarla UNA vez acá, fuera
    # de los hilos, y leerla de la caché en el loop de abajo. Si el sync
    # falla, el bloque de abajo hace fallback silencioso a _ttar.cotizar
    # (la tabla estática vieja) para no dejar la columna vacía.
    _clickex_en_vivo = _clickex_sync_tarifas().get("ok", False)

    # Los commune_id de Shipit también se resuelven acá, en el hilo del
    # request, por el mismo motivo.
    origen_id, _ = _shipit_commune_id(_tr_sender_cfg().get("city") or "Quilicura")
    destino_ids = {}
    for f in filas_comuna:
        try:
            destino_ids[f["comuna"]], _ = _shipit_commune_id(f["comuna"])
        except Exception:
            destino_ids[f["comuna"]] = None

    # ── Cotizar Shipit en paralelo (solo lo que la API puede responder) ──
    tareas = [
        (f["comuna"], p) for f in filas_comuna for p in pesos
        if destino_ids.get(f["comuna"]) and origen_id
        and not _shc.verificar_restricciones(1, p)
    ]

    # Tope de tiempo global: aunque el producto esté acotado, la API de Shipit
    # ha respondido hasta en 14 s. Pasado el deadline las cotizaciones que
    # falten salen como "Sin cobertura" y el Excel se entrega igual, en vez de
    # que gunicorn mate el worker a los 90 s.
    import time as _t_dl
    _deadline = _t_dl.monotonic() + 60

    def _cotizar_shipit(par):
        comuna, peso = par
        if _t_dl.monotonic() > _deadline:
            return par, None
        payload, errores = _shc.build_rate_payload(
            length=30, width=30, height=30, weight=peso,
            origin_id=origen_id, destiny_id=destino_ids[comuna],
        )
        if errores:
            return par, None
        # 8 s, igual que la pantalla interactiva del comparador.
        r = _shipit_request("POST", _shc.EP_RATES, payload=payload, timeout=8)
        if not r.get("ok"):
            return par, None
        disp = [x for x in _shc.parse_rates_response(r.get("data"))
                if x.get("disponible") and x.get("precio")]
        if not disp:
            return par, None
        disp.sort(key=lambda x: x["precio"])
        return par, disp[0]

    shipit_res = {}
    if tareas:
        with _cf.ThreadPoolExecutor(max_workers=8) as pool:
            for par, val in pool.map(_cotizar_shipit, tareas):
                shipit_res[par] = val

    # ── Armar el Excel ───────────────────────────────────────────────
    wb = openpyxl.Workbook()
    wb.remove(wb.active)
    RED  = PatternFill("solid", fgColor="CC0000")
    VERDE = PatternFill("solid", fgColor="DCFCE7")
    BLANCO = Font(color="FFFFFF", bold=True)

    resumen = []
    for peso in pesos:
        ws = wb.create_sheet(title=f"{peso:g} kg"[:31])
        headers = (["Comuna", "Envíos ILUS", "Shipit", "Operador Shipit"]
                   + [n for _, n in SLUGS] + ["Más barato", "Shipit vs. más barato"])
        for ci, h in enumerate(headers, 1):
            cell = ws.cell(1, ci, h)
            cell.font, cell.fill = BLANCO, RED
            cell.alignment = Alignment(horizontal="center", wrap_text=True)

        gana_shipit = 0
        comparables = 0
        for ri, f in enumerate(filas_comuna, 2):
            comuna = f["comuna"]
            sh = shipit_res.get((comuna, peso))
            precios = {}
            for slug, nombre in SLUGS:
                if slug == "clickex" and _clickex_en_vivo:
                    t = _clickex_tarifa_comuna(comuna)
                    precios[nombre] = round(t["costo_neto"]) if t and t.get("costo_neto") is not None else None
                    continue
                try:
                    r = _ttar.cotizar(slug, comuna, peso, 0)
                except Exception:
                    r = None
                # Solo el precio final: el resto del dict de transporte_tarifas
                # trae detalle comercial interno que no sale de la app.
                precios[nombre] = round(r["precio"]) if r else None

            sh_precio = round(sh["precio"]) if sh else None
            if sh_precio is None and not _shc.verificar_restricciones(1, peso):
                sh_txt, sh_op = "Sin cobertura", ""
            elif sh_precio is None:
                sh_txt, sh_op = f"No aplica (>{_shc.MAX_PESO_KG:g} kg)", ""
            else:
                sh_txt, sh_op = sh_precio, (sh["courier"] or "").replace("_", " ").title()

            candidatos = {n: v for n, v in precios.items() if v}
            if sh_precio:
                candidatos["Shipit"] = sh_precio
            mejor_nombre = min(candidatos, key=candidatos.get) if candidatos else ""
            mejor_valor = candidatos.get(mejor_nombre)
            if sh_precio and mejor_valor:
                comparables += 1
                if mejor_nombre == "Shipit":
                    gana_shipit += 1
                delta = sh_precio - mejor_valor
            else:
                delta = ""

            vals = ([comuna, f["n"], sh_txt, sh_op]
                    + [precios[n] for _, n in SLUGS]
                    + [f"{mejor_nombre} ({mejor_valor:,})".replace(",", ".") if mejor_valor else "",
                       delta])
            for ci, v in enumerate(vals, 1):
                c = ws.cell(ri, ci, _xlsx_cell(v) if v is not None else "")
                if isinstance(v, (int, float)) and ci not in (2,):
                    c.number_format = '$#,##0'
            if mejor_nombre == "Shipit":
                ws.cell(ri, 3).fill = VERDE

        ws.freeze_panes = "A2"
        for ci in range(1, len(headers) + 1):
            ws.column_dimensions[get_column_letter(ci)].width = 22 if ci in (1, 4, 9, 10) else 14
        resumen.append((peso, gana_shipit, comparables))

    ws = wb.create_sheet(title="Resumen", index=0)
    ws.cell(1, 1, "Comparación de tarifas por courier — ILUS").font = Font(bold=True, size=14)
    ws.cell(2, 1, f"Generado el {chile_fmt_filter(datetime.now(), '%d/%m/%Y %H:%M')} · "
                  f"{len(filas_comuna)} comunas con más envíos · origen: bodega Quilicura")
    ws.cell(3, 1, "Precios netos de cada courier para la misma comuna y el mismo peso. "
                  "Shipit se cotiza en vivo contra su API; el resto sale de las tablas negociadas.")
    # Este archivo nació para compartirse por correo, y pone las tarifas de
    # todos los couriers en la MISMA fila. Comparando columnas se puede
    # reconstruir la política de precios de ILUS, que es información
    # reservada. El aviso es el piso; si además hay que restringir columnas
    # según quién descarga, eso lo decide Daniel (es política comercial, no
    # una decisión técnica).
    _av = ws.cell(4, 1, "USO INTERNO ILUS — NO COMPARTIR CON COURIERS NI CON CLIENTES")
    _av.font = Font(bold=True, color="CC0000")
    for ci, h in enumerate(["Peso", "Comunas donde Shipit es el más barato", "Comunas comparables", "% "], 1):
        c = ws.cell(5, ci, h)
        c.font, c.fill = BLANCO, RED
    for ri, (peso, gana, total) in enumerate(resumen, 6):
        ws.cell(ri, 1, f"{peso:g} kg")
        ws.cell(ri, 2, gana)
        ws.cell(ri, 3, total)
        ws.cell(ri, 4, round(gana / total * 100) / 100 if total else 0).number_format = "0%"
    for ci, w in enumerate([16, 38, 22, 10], 1):
        ws.column_dimensions[get_column_letter(ci)].width = w

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    from flask import send_file
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True,
        download_name=f"ILUS_Tarifas_Comparadas_{datetime.now():%Y%m%d}.xlsx",
    )


@app.route("/transporte/couriers/lookup", methods=["GET"])
@_tr_required
def transporte_couriers_lookup():
    """API: GET ?courier_id=X&comuna=Y&peso=Z → returns price."""
    courier_id = request.args.get('courier_id', type=int)
    comuna     = (request.args.get('comuna') or '').strip()
    peso       = request.args.get('peso', type=float)

    if not all([courier_id, comuna, peso]):
        return jsonify({"ok": False, "error": "Faltan parámetros: courier_id, comuna, peso"}), 400

    # ── Shipit no tiene tabla de tarifas: cotiza EN VIVO ──────────────────
    # Daniel, 2026-08-05: "no me sale la lista de precios de Shipit". Y no va
    # a salir nunca por esta vía: Shipit es un agregador, su precio depende
    # del operador que responda en el momento, así que no hay Excel que
    # importar. Antes esta calculadora devolvía "No se encontró tarifa", que
    # hacía parecer que faltaba cargar algo. Ahora consulta la API real y
    # devuelve el precio del operador más barato, con su nombre.
    _c = mysql_fetchone("SELECT nombre FROM transport_couriers WHERE id=%s", (courier_id,))
    if _c and "shipit" in (_c["nombre"] or "").lower():
        import shipit_client as _shc
        problemas = _shc.verificar_restricciones(1, peso)
        if problemas:
            return jsonify({"ok": False, "error": " · ".join(problemas)}), 200
        origen_id, _ = _shipit_commune_id(_tr_sender_cfg().get("city") or "Quilicura")
        destino_id, _ = _shipit_commune_id(comuna)
        if not origen_id:
            return jsonify({"ok": False, "error": "Falta sincronizar las comunas de Shipit "
                                                  "(Diagnóstico > Shipit)."}), 200
        if not destino_id:
            return jsonify({"ok": False, "error": f"Shipit no tiene cobertura para «{comuna}»."}), 200
        payload, errores = _shc.build_rate_payload(
            length=30, width=30, height=30, weight=peso,
            origin_id=origen_id, destiny_id=destino_id)
        if errores:
            return jsonify({"ok": False, "error": "; ".join(errores)}), 200
        r = _shipit_request("POST", _shc.EP_RATES, payload=payload, timeout=12)
        if not r.get("ok"):
            return jsonify({"ok": False, "error": r.get("error") or "Shipit no respondió."}), 200
        disp = [x for x in _shc.parse_rates_response(r.get("data"))
                if x.get("disponible") and x.get("precio")]
        if not disp:
            return jsonify({"ok": False, "error": f"Ningún operador de Shipit cubre «{comuna}» "
                                                  f"con {peso} kg."}), 200
        disp.sort(key=lambda x: x["precio"])
        mejor = disp[0]
        return jsonify({
            "ok": True, "precio": mejor["precio"], "comuna_matched": comuna,
            "partial_match": False,
            "operador": (mejor["courier"] or "").replace("_", " ").title(),
            "en_vivo": True,
            "operadores": [
                {"operador": (x["courier"] or "").replace("_", " ").title(),
                 "precio": x["precio"], "dias": x["dias"]}
                for x in disp
            ],
        })

    price = _courier_tarifa_lookup(courier_id, comuna, peso)
    if price is None:
        # Try partial match
        row = mysql_fetchone(
            "SELECT comuna, precios_json FROM transport_courier_comunas "
            "WHERE courier_id=%s AND LOWER(comuna) LIKE LOWER(%s) LIMIT 1",
            (courier_id, f"%{comuna}%")
        )
        if row:
            try:
                precios = json.loads(row['precios_json'])
                brackets = sorted(
                    [(float(_parse_peso_upper(k)), float(v)) for k, v in precios.items() if v is not None],
                    key=lambda x: x[0]
                )
                for upper, price in brackets:
                    if peso <= upper:
                        return jsonify({"ok": True, "precio": price, "comuna_matched": row['comuna'], "partial_match": True})
                return jsonify({"ok": True, "precio": brackets[-1][1], "comuna_matched": row['comuna'], "partial_match": True})
            except Exception:
                pass
        return jsonify({"ok": False, "error": f"No se encontró tarifa para '{comuna}' en este courier"}), 404

    return jsonify({"ok": True, "precio": price, "comuna": comuna, "peso": peso})


@app.route("/transporte/couriers/comunas", methods=["GET"])
@_tr_required
def transporte_couriers_comunas():
    """API: GET ?courier_id=X → list of communes for that courier."""
    courier_id = request.args.get('courier_id', type=int)
    if not courier_id:
        return jsonify([])
    rows = mysql_fetchall(
        "SELECT comuna, zona, region, dias_transito FROM transport_courier_comunas "
        "WHERE courier_id=%s ORDER BY region, comuna",
        (courier_id,)
    ) or []
    return jsonify(rows)


