@app.route("/comunicaciones/whatsapp/test", methods=["POST"])
@_require_superadmin
def comm_wa_test():
    d     = request.get_json(silent=True) or {}
    saved = _get_wa_cfg()
    sid   = (d.get("account_sid") or saved.get("account_sid") or "").strip()
    tok   = (d.get("auth_token")  or saved.get("auth_token")  or "").strip()
    frm   = (d.get("from_number") or saved.get("from_number") or "").strip()
    to    = (d.get("to") or "").strip()
    if not all([sid, tok, frm, to]):
        return jsonify({"error": "Completa: Account SID, Auth Token, From y destinatario"}), 400
    body = (f"✅ Prueba de WhatsApp — ILUS Comunicaciones\n"
            f"Enviado por: {current_username()}")
    body = (d.get("body") or "").strip() or body
    try:
        msg_sid = _send_whatsapp(sid, tok, frm, to, body)
        _comm_log_entry("whatsapp", to, "Prueba WA", "ok", msg_sid)
        return jsonify({"ok": True, "msg_sid": msg_sid})
    except Exception as exc:
        detail = str(exc)
        code = getattr(exc, "code", None) or getattr(exc, "status", None)
        more_info = getattr(exc, "more_info", "") or ""
        suggestions = []
        if "not installed" in detail.lower() or "twilio" in detail.lower() and "instal" in detail.lower():
            suggestions.append("Instala Twilio en el mismo Python que ejecuta la app y reinicia el servidor.")
        if str(code) in {"21211", "21614"} or "not a valid phone number" in detail.lower():
            suggestions.append("Revisa que el destinatario tenga formato internacional, por ejemplo +56912345678.")
        if str(code) in {"63015", "63016"} or "sandbox" in detail.lower():
            suggestions.append("En sandbox, el destinatario debe enviar primero el codigo join al numero +1 415 523 8886.")
        if str(code) in {"20003", "20404"} or "authenticate" in detail.lower() or "credentials" in detail.lower():
            suggestions.append("Revisa Account SID y Auth Token desde el Dashboard de Twilio.")
        if frm.startswith("whatsapp:+14155238886"):
            suggestions.append("Estas usando sandbox Twilio; confirma que el telefono destino ya se unio al sandbox.")
        _comm_log_entry("whatsapp", to, "Prueba WA", "error", detail)
        return jsonify({
            "error": detail,
            "code": code,
            "more_info": more_info,
            "suggestions": suggestions,
        }), 500


# Módulos válidos para plantillas — mantener sincronizado con el frontend
_COMM_MODULOS_VALIDOS = (
    "transporte",
    "transporte_cotizaciones",
    "retiros",
    "mantenciones",
    "comunicacion_interna",
    "general",
    "tickets",
    "catalogo",
)


@app.route("/comunicaciones/templates", methods=["GET"])
@_require_superadmin
def comm_templates_get():
    """Devuelve plantillas agrupadas por estado.
    Filtra por ?modulo=transporte (default), retiros, mantenciones,
    comunicacion_interna o general."""
    modulo = (request.args.get("modulo") or "transporte").strip()
    if modulo not in _COMM_MODULOS_VALIDOS:
        modulo = "transporte"
    rows = mysql_fetchall(
        "SELECT * FROM comm_templates WHERE modulo=%s ORDER BY estado, canal",
        (modulo,),
    ) or []
    legacy_tokens = ("Dropit", "direccion_origen", "direccion_destino", "link_tracking", "nombre_conductor")
    if modulo == "transporte" and any(
        any(tok in ((r.get("asunto") or "") + " " + (r.get("cuerpo") or "")) for tok in legacy_tokens)
        for r in rows
    ):
        _comm_seed_default_templates(overwrite=True)
        rows = mysql_fetchall(
            "SELECT * FROM comm_templates WHERE modulo=%s ORDER BY estado, canal",
            (modulo,),
        ) or []
    data = {}
    for r in rows:
        est = r["estado"]
        if est not in data:
            data[est] = {}
        data[est][r["canal"]] = {
            "id":     r["id"],
            "asunto": r.get("asunto") or "",
            "cuerpo": r.get("cuerpo") or "",
            "activo": r.get("activo", 1),
            # Daniel 2026-08-24: control por plantilla de quién recibe copia
            # interna (antes hardcodeado en código, ver _notificar_equipo_retiros).
            "copia_interna_emails": r.get("copia_interna_emails") or "",
        }
    return jsonify(data)


@app.route("/comunicaciones/templates/<estado>/<canal>", methods=["PUT"])
@_require_superadmin
def comm_template_save(estado, canal):
    """Guarda/actualiza una plantilla para estado + canal en un módulo dado.
    Body opcional: { modulo: 'transporte' | 'retiros' | 'mantenciones' |
                              'comunicacion_interna' | 'general' }"""
    if canal not in ("email", "whatsapp"):
        return jsonify({"error": "Canal inválido"}), 400
    d      = request.get_json(silent=True) or {}
    modulo = (d.get("modulo") or "transporte").strip()
    if modulo not in _COMM_MODULOS_VALIDOS:
        modulo = "transporte"
    asunto = d.get("asunto", "")
    cuerpo = d.get("cuerpo", "")
    # Daniel 2026-08-24: "cada plantilla, pueda yo agregar cuáles son las
    # copias" — lista de emails que reciben copia interna al disparar ESTA
    # plantilla. Normaliza + valida cada dirección; una inválida rechaza el
    # guardado completo con mensaje claro (mejor que guardar basura en
    # silencio y que el correo interno falle después, sin avisar a nadie).
    #
    # FIX (review): distinguir "el body NO trae este campo" (ej. el botón
    # Restaurar solo manda asunto/cuerpo desde TPL_DEFAULTS, que nunca tuvo
    # copia_interna_emails) de "lo trae vacío a propósito" (el usuario borró
    # el campo). Antes, "no viene" se trataba igual que "vaciar" → Restaurar
    # borraba en silencio la config de copias cada vez que alguien
    # restauraba el TEXTO de una plantilla. Ahora: si la clave no está en el
    # body, la columna copia_interna_emails NI SE TOCA (se preserva lo que
    # ya había guardado).
    _trae_copia = "copia_interna_emails" in d
    copia_interna_emails = None
    if _trae_copia:
        _copia_raw = (d.get("copia_interna_emails") or "").strip()
        if _copia_raw:
            _partes = [p.strip().lower() for p in re.split(r"[,;\s]+", _copia_raw) if p.strip()]
            _malos = [p for p in _partes if not _EMAIL_RE.match(p)]
            if _malos:
                return jsonify({"error": f"Email(s) inválido(s) en 'Copia interna': {', '.join(_malos[:3])}"}), 400
            copia_interna_emails = ", ".join(dict.fromkeys(_partes))[:800]
    user   = current_username()
    conn   = get_db()
    with conn.cursor() as cur:
        if _trae_copia:
            cur.execute(
                """INSERT INTO comm_templates (modulo, estado, canal, asunto, cuerpo, updated_by, copia_interna_emails)
                   VALUES (%s,%s,%s,%s,%s,%s,%s)
                   ON DUPLICATE KEY UPDATE
                     asunto=VALUES(asunto), cuerpo=VALUES(cuerpo), updated_by=VALUES(updated_by),
                     copia_interna_emails=VALUES(copia_interna_emails)""",
                (modulo, estado, canal, asunto, cuerpo, user, copia_interna_emails)
            )
        else:
            # No se toca copia_interna_emails: en INSERT nace NULL (fila nueva,
            # no hay nada que preservar); en UPDATE se omite del SET, así que
            # conserva lo que ya tenía guardado.
            cur.execute(
                """INSERT INTO comm_templates (modulo, estado, canal, asunto, cuerpo, updated_by)
                   VALUES (%s,%s,%s,%s,%s,%s)
                   ON DUPLICATE KEY UPDATE
                     asunto=VALUES(asunto), cuerpo=VALUES(cuerpo), updated_by=VALUES(updated_by)""",
                (modulo, estado, canal, asunto, cuerpo, user)
            )
    conn.commit()
    # Audit log del cambio
    try:
        _audit(
            "comm_template_save",
            target_type="comm_template",
            target_id=f"{modulo}:{estado}:{canal}",
            details={"modulo": modulo, "estado": estado, "canal": canal,
                     "asunto_len": len(asunto or ""), "cuerpo_len": len(cuerpo or ""),
                     "copia_interna_emails": copia_interna_emails or ""},
        )
    except Exception:
        pass
    return jsonify({"ok": True})


@app.route("/comunicaciones/templates/copia-interna/aplicar-a-todas", methods=["POST"])
@_require_superadmin
def comm_template_copia_interna_aplicar_todas():
    """Copia el mismo 'copia_interna_emails' a TODAS las plantillas de email
    de un módulo de una sola vez (Daniel 2026-08-24: "controlar que se
    repitan en todas las plantillas de retiros"). Body: {modulo, emails}."""
    d = request.get_json(silent=True) or {}
    modulo = (d.get("modulo") or "").strip()
    if modulo not in _COMM_MODULOS_VALIDOS:
        return jsonify({"error": "Módulo inválido"}), 400
    _copia_raw = (d.get("emails") or "").strip()
    copia_interna_emails = None
    if _copia_raw:
        _partes = [p.strip().lower() for p in re.split(r"[,;\s]+", _copia_raw) if p.strip()]
        _malos = [p for p in _partes if not _EMAIL_RE.match(p)]
        if _malos:
            return jsonify({"error": f"Email(s) inválido(s): {', '.join(_malos[:3])}"}), 400
        copia_interna_emails = ", ".join(dict.fromkeys(_partes))[:800]
    n = mysql_execute_returning_rowcount(
        "UPDATE comm_templates SET copia_interna_emails=%s, updated_by=%s "
        "WHERE modulo=%s AND canal='email'",
        (copia_interna_emails, current_username(), modulo)
    )
    try:
        _audit("comm_template_copia_interna_bulk", target_type="comm_template", target_id=modulo,
               details={"modulo": modulo, "emails": copia_interna_emails or "", "filas": n})
    except Exception:
        pass
    return jsonify({"ok": True, "filas_actualizadas": n})


