def _erp_buscar_clientes(q, limit=20):
    """
    Busca clientes en el ERP por RUT o razón social.
    Normaliza el RUT (con/sin puntos) para máxima compatibilidad.

    FIX 2026-05-19: el ERP Random es SQL Server, no MySQL — `HEBDOC` no
    existe en su schema. Buscamos directo en MAEEN (entidad/cliente):
        - NOKOEN / NOKOENAMP  → razón social
        - RTEN               → RUT base (sin DV)
    """
    if not q:
        return []
    q_upper      = q.upper()
    q_like       = f"%{q_upper}%"
    q_sin_puntos = q.replace(".", "").replace(" ", "").replace("-", "")
    q_sin_like   = f"%{q_sin_puntos}%"
    # RTEN del ERP = RUT base SIN dígito verificador. Si el usuario escribe el
    # RUT con DV ('77.017.350-K'), buscamos también por el cuerpo ('77017350').
    q_cuerpo      = _rut_cuerpo(q)
    q_cuerpo_like = f"%{q_cuerpo}%" if (q_cuerpo and len(q_cuerpo) >= 6) else q_sin_like
    try:
        top_n = max(1, min(int(limit or 20), 200))
    except (TypeError, ValueError):
        top_n = 20
    try:
        # FIX 2026-08-08: antes filtrabamos "AND TIEN IN ('C','A')" -- un RUT
        # de PERSONA NATURAL puede tener otro TIEN y ese filtro lo excluia en
        # silencio (el query corria bien, 0 filas, sin error visible). Mismo
        # bug ya diagnosticado y corregido en tk_api_erp_buscar_cliente
        # (tickets_module.py) -- aca replicamos el mismo patron: TIEN como
        # criterio de ORDEN (empresas primero), nunca como filtro.
        rows = _random_sql_query(
            f"""
            SELECT DISTINCT TOP {top_n}
                   LTRIM(RTRIM(COALESCE(en.NOKOENAMP, en.NOKOEN, ''))) AS razon_social,
                   LTRIM(RTRIM(COALESCE(en.RTEN, '')))                 AS rut,
                   CASE WHEN LTRIM(RTRIM(COALESCE(en.TIEN,''))) IN ('C','A')
                        THEN 0 ELSE 1 END                               AS ord_tien
              FROM MAEEN en
             WHERE (
                   UPPER(LTRIM(RTRIM(COALESCE(en.NOKOEN,    '')))) LIKE %s
                OR UPPER(LTRIM(RTRIM(COALESCE(en.NOKOENAMP, '')))) LIKE %s
                OR LTRIM(RTRIM(COALESCE(en.RTEN, '')))             LIKE %s
                OR LTRIM(RTRIM(COALESCE(en.RTEN, '')))             LIKE %s
             )
             ORDER BY ord_tien, razon_social
            """,
            (q_like, q_like, q_like, q_cuerpo_like),
            max_rows=top_n,
        )
        if not rows:
            return []
        return [{"razon_social": r.get("razon_social") or "",
                 "rut":          r.get("rut") or ""}
                for r in rows if r.get("razon_social")]
    except PermissionError as pe:
        print(f"[erp-buscar-clientes-sql] bloqueado por seguridad: {pe}", flush=True)
        return []
    except Exception as e:
        print(f"[erp-buscar-clientes-sql] error: {e}", flush=True)
        return []


@app.route("/mantenciones/api/clientes/autocomplete")
@_mant_required
def mant_clientes_autocomplete():
    """
    Autocomplete unificado: busca en clientes locales (mant_clientes) + ERP.
    Devuelve lista ordenada con origen (local/erp) para mostrar en dropdown.
    """
    q = request.args.get("q", "").strip()
    if len(q) < 2:
        return jsonify([])

    # 1) Buscar en clientes locales (siempre disponible)
    q_like = f"%{q}%"
    locales = mysql_fetchall(
        """SELECT id, razon_social, rut, contacto_email, estado,
                  ciudad AS region, comuna, direccion, contacto_tel AS telefono
           FROM mant_clientes
           WHERE razon_social LIKE %s OR rut LIKE %s
           ORDER BY razon_social LIMIT 15""",
        (q_like, q_like)
    )
    resultados = []
    ids_rut_vistos = set()
    for r in locales:
        rut = (r.get("rut") or "").strip()
        resultados.append({
            "id":           r["id"],
            "razon_social": r["razon_social"],
            "rut":          rut,
            "email":        r.get("contacto_email",""),
            "region":       r.get("region",""),
            "comuna":       r.get("comuna",""),
            "direccion":    r.get("direccion",""),
            "telefono":     r.get("telefono",""),
            "estado":       r.get("estado",""),
            "origen":       "local",
        })
        if rut: ids_rut_vistos.add(rut)

    # 2) Buscar en ERP vía REST API /entidades (funciona desde Railway)
    TOKEN = ERP_CONFIG.get("api_token", "")
    try:
        body     = _erp_get("/entidades", {"search": q, "empresa": "01", "limit": "30"}, TOKEN, timeout=8)
        ent_list = body.get("data") or (body if isinstance(body, list) else [])
        for e in ent_list[:25]:
            rut    = (e.get("RTEN")   or "").strip()
            nombre = (e.get("NOKOEN") or "").strip()
            if not nombre:
                continue
            if rut and rut in ids_rut_vistos:
                continue
            # Capturar región, comuna, dirección y teléfono si el ERP los entrega
            region  = (e.get("NOKOREG")  or e.get("NOKOREGIO") or e.get("REGION") or "").strip()
            comuna  = (e.get("NOKOCOMU") or e.get("NOKOCOMUNADE") or e.get("COMUNA") or e.get("NOKOMUNNE") or "").strip()
            dir_    = (e.get("DIEN")     or e.get("DIRESP") or e.get("DIENDESP") or e.get("DIENDE") or "").strip()
            tel     = (e.get("FOEN")     or e.get("FONOEN") or e.get("TELEN")  or "").strip()
            resultados.append({
                "id":           None,
                "razon_social": nombre,
                "rut":          rut,
                "email":        (e.get("EMAIL") or e.get("COREN") or "").strip(),
                "region":       region,
                "comuna":       comuna,
                "direccion":    dir_,
                "telefono":     tel,
                "giro":         (e.get("GIEN") or e.get("GIRO") or "").strip(),
                "estado":       "",
                "origen":       "erp",
            })
            if rut: ids_rut_vistos.add(rut)
    except Exception:
        # Fallback: MySQL directo si REST falla (p.ej. entorno local)
        erp_rows = _erp_buscar_clientes(q, limit=15)
        for r in erp_rows:
            rut = (r.get("rut") or "").strip()
            if rut in ids_rut_vistos:
                continue
            resultados.append({
                "id":           None,
                "razon_social": r["razon_social"],
                "rut":          rut,
                "email":        "",
                "region":       "",
                "comuna":       "",
                "direccion":    "",
                "telefono":     "",
                "estado":       "",
                "origen":       "erp",
            })
            if rut: ids_rut_vistos.add(rut)

    # Ordenar locales primero, luego ERP
    resultados.sort(key=lambda x: (0 if x["origen"]=="local" else 1, x["razon_social"].lower()))
    return jsonify(resultados[:20])


_MANT_IMG_EXTS = ("jpg", "jpeg", "png", "webp", "gif", "heic", "heif", "bmp")


def _contrato_fechas(t):
    """Extrae fechas (dd/mm/aaaa, dd-mm-aaaa, 'd de mes de aaaa') → ['YYYY-MM-DD',...] ordenadas."""
    import re
    out = []
    meses = {"enero":1,"febrero":2,"marzo":3,"abril":4,"mayo":5,"junio":6,"julio":7,
             "agosto":8,"septiembre":9,"setiembre":9,"octubre":10,"noviembre":11,"diciembre":12}
    for m in re.finditer(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b', t or ""):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if y < 100: y += 2000
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2100:
            out.append(f"{y:04d}-{mo:02d}-{d:02d}")
    for m in re.finditer(r'\b(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})', t or "", re.I):
        d = int(m.group(1)); mo = meses.get(m.group(2).lower()); y = int(m.group(3))
        if mo and 1 <= d <= 31 and 2000 <= y <= 2100:
            out.append(f"{y:04d}-{mo:02d}-{d:02d}")
    return sorted(set(out))


def _contrato_equipos(t):
    """Detecta equipos fitness mencionados en el texto (heurístico). El ERP es la fuente real."""
    import re
    kws = r'(trotadora|caminadora|cinta de correr|el[ií]ptic[ao]|bicicleta|spinning|remo|' \
          r'multiestaci[oó]n|prensa|press|polea|smith|mancuerna|banco|escaladora|stepper|crossover)'
    out = []
    noise = re.compile(r'mantenci[oó]n|gratuit|vigencia|monto|cl[aá]usula|contrato|'
                       r'\brut\b|comuna|raz[oó]n social|frecuencia', re.I)
    for ln in (t or "").split("\n"):
        l = ln.strip()
        if not l or len(l) > 120 or noise.search(l):
            continue
        if re.search(kws, l, re.I):
            qm = re.search(r'\b(\d{1,3})\b', l)
            out.append({"nombre": l[:90], "marca": None, "modelo": None, "sku": None,
                        "cantidad": min(int(qm.group(1)), 99) if qm else 1,
                        "notas": "Detectado en el contrato"})
        if len(out) >= 30:
            break
    return out


# ════════════════════════════════════════════════════════════════════════
#  IDENTIDAD PROPIA DE ILUS — para EXCLUIRLA al leer un contrato
#  ───────────────────────────────────────────────────────────────────────
#  Un contrato siempre tiene DOS partes: ILUS (el ARRENDADOR/PRESTADOR) y el
#  CLIENTE. El lector tomaba el PRIMER match de cada dato y terminaba guardando
#  datos de ILUS como si fueran del cliente (caso real: el correo del
#  representante de ILUS, felipe.gomez@sphs.cl, caía en el campo dirección).
#  Estos marcadores permiten reconocer y descartar lo que es de ILUS.
# ════════════════════════════════════════════════════════════════════════
_ILUS_RUT_CUERPOS    = {"76996964"}                      # 76.996.964-0 (ILUS_REMITENTE)
_ILUS_EMAIL_DOMINIOS = ("sphs.cl", "ilusfitness.com", "ilus.cl")
_ILUS_DIR_TOKENS     = ("apoquindo 4499", "frei montalva 9770", "eduardo frei montalva")
_ILUS_TEL_DIGITOS    = ("229465970", "56229465970")


def _norm_txt(s):
    """minúsculas, sin tildes/ñ, espacios colapsados — para comparar identidades."""
    import unicodedata, re as _re
    s = (s or "").lower()
    s = "".join(c for c in unicodedata.normalize("NFD", s)
                if unicodedata.category(c) != "Mn")
    return _re.sub(r"\s+", " ", s).strip()


def _es_rut_ilus(rut):
    c = _rut_cuerpo(rut or "")
    return bool(c) and c in _ILUS_RUT_CUERPOS


def _es_email_ilus(email):
    e = _norm_txt(email).rstrip(".")
    return bool(e) and any(("@" + d) in e or e.endswith(d) for d in _ILUS_EMAIL_DOMINIOS)


def _es_nombre_ilus(nombre):
    """True si el nombre/razón social corresponde a ILUS (no al cliente)."""
    import re as _re
    n = _norm_txt(nombre)
    if not n:
        return False
    if any(tok in n for tok in ("sport and health", "sports and health",
                                "health solution", "health solutions", "sport & health")):
        return True
    # 'ilus'/'sphs' SOLO como palabra suelta (evita falsos positivos: 'ilusión').
    return bool(_re.search(r"\b(ilus|sphs)\b", n))


def _es_direccion_ilus(direccion):
    d = _norm_txt(direccion)
    return bool(d) and any(tok in d for tok in _ILUS_DIR_TOKENS)


def _es_tel_ilus(tel):
    import re as _re
    dig = _re.sub(r"\D", "", tel or "")
    return bool(dig) and dig in _ILUS_TEL_DIGITOS


def _marcador_ilus_cerca(texto, ini, fin, radio=90):
    """True si la ventana alrededor de [ini,fin] contiene marcadores de ILUS:
    nombre legal, dirección conocida o un ROL de prestador (arrendador/vendedor/
    comodante). Permite descartar un correo o RUT que es de ILUS aunque su
    dominio/cuerpo NO esté en la lista (p.ej. el gmail del representante de ILUS,
    o un RUT de holding). Los roles del cliente (arrendatario/comodatario/
    comprador/mandante) NO cuentan, así no se descarta al cliente."""
    import re as _re
    ventana = (texto or "")[max(0, ini - radio):fin + radio]
    if _es_nombre_ilus(ventana) or _es_direccion_ilus(ventana):
        return True
    return bool(_re.search(r"arrendador|prestador|comodante|vendedor", ventana, _re.I))


def _parece_email(s):
    import re as _re
    return bool(_re.search(r"[\w.\-]+@[\w\-]+\.[\w]{2,}", s or ""))


def _parece_rut(s):
    import re as _re
    return bool(_re.search(r"\b\d{1,2}[.\s]?\d{3}[.\s]?\d{3}\s*-\s*[\dkK]\b", s or ""))


def _valida_direccion(s):
    """Devuelve una dirección VÁLIDA y limpia, o None.

    Bloquea el bug clásico: una dirección NUNCA puede ser un correo, un RUT
    suelto o la dirección de ILUS. Debe tener al menos una letra (no solo
    números/símbolos)."""
    import re as _re
    d = (s or "").strip(" .:-,|")
    if not d or len(d) < 5:
        return None
    if "@" in d or _parece_email(d):
        return None                       # ← correo en dirección: rechazado
    if _es_direccion_ilus(d):
        return None
    if not _re.search(r"[A-Za-zÁÉÍÓÚÑáéíóúñ]", d):
        return None                       # sin letras → no es una dirección
    # un RUT/teléfono suelto con casi nada de texto tampoco es dirección
    if _parece_rut(d) and len(_re.sub(r"[^A-Za-zÁÉÍÓÚÑáéíóúñ]", "", d)) < 4:
        return None
    return _re.sub(r"\s+", " ", d)[:120]


def _valida_comuna(s):
    """Comuna/ciudad/región: alfabética (letras/espacios), 3-40 chars, sin
    dígitos ni '@'. Corta arrastres ('Viña del Mar Ciudad…'). Devuelve None si
    no parece un nombre de lugar (p.ej. quedó un correo o un RUT)."""
    import re as _re
    c = (s or "").strip(" .:-,|")
    c = _re.split(r"\b(?:ciudad|regi[oó]n|provincia|chile)\b", c, 1, _re.I)[0].strip(" .,-")
    if not c or len(c) < 3 or len(c) > 40:
        return None
    if "@" in c or _re.search(r"\d", c):
        return None
    if not _re.fullmatch(r"[A-Za-zÁÉÍÓÚÑáéíóúñ ]+", c):
        return None
    return c.title()


def _contrato_partes(t):
    """Separa la comparecencia en (bloque_cliente, bloque_ilus, modo).

    En contratos tipo 'comparecencia' las dos partes se describen al inicio:
    una 'por una parte' (ILUS) y la otra 'por la otra' (el cliente). Cortamos en
    'por la otra' y clasificamos cada bloque por marcadores de identidad de ILUS
    (nombre legal, RUT propio, rol 'arrendador/prestador', dirección conocida),
    así da igual el orden en que aparezcan.

    Si no detecta la estructura → modo='plano' y bloque_cliente = texto completo
    (igual se aplica validación + exclusión de ILUS sobre cada campo)."""
    import re as _re
    if not t:
        return "", "", "plano"
    mc = _re.search(r"\bcomparecen\b", t, _re.I)
    cuerpo = t[mc.start():] if mc else t
    mfin = _re.search(r"\b(los comparecientes|quienes exponen|exponen que|expone que|"
                      r"acuerdan|acordando|vienen en celebrar|han convenido|"
                      r"se ha convenido|PRIMERO\s*[:.])", cuerpo, _re.I)
    pre = cuerpo[:mfin.start()] if mfin else cuerpo[:2000]
    # Conector que separa a la 2ª parte (el cliente). Las redacciones reales
    # varían: "por la otra", "de la otra parte", "en segundo lugar", etc.
    msplit = _re.search(r"\bpor\s+la\s+otra\b|\bde\s+la\s+otra\s+parte\b|"
                        r"\bde\s+otra\s+parte\b|\bpor\s+la\s+segunda\b|"
                        r"\ben\s+segundo\s+lugar\b|\bla\s+segunda\s+parte\b|"
                        r"\bla\s+contraparte\b|\by\s+por\s+la\s+otra\b", pre, _re.I)
    if not msplit:
        return t, "", "plano"
    bloque_a = pre[:msplit.start()]
    bloque_b = pre[msplit.end():]

    def _puntaje_ilus(b):
        n = 0
        if _es_nombre_ilus(b):
            n += 2
        for r in _re.findall(r"\b\d{1,2}[.\s]?\d{3}[.\s]?\d{3}\s*-\s*[\dkK]\b", b):
            if _es_rut_ilus(r):
                n += 3
        if _re.search(r"arrendador|prestador|vendedor|comodante|mandatari", b, _re.I):
            n += 1
        if _es_direccion_ilus(b):
            n += 1
        return n

    if _puntaje_ilus(bloque_a) >= _puntaje_ilus(bloque_b):
        return bloque_b, bloque_a, "comparecencia"   # cliente = la otra parte (B)
    return bloque_a, bloque_b, "comparecencia"        # cliente = A


def _contrato_extraer_determinista(texto):
    """Extrae datos de un contrato (texto plano) con reglas/regex. CERO IA, CERO tokens.

    Inteligente respecto a las DOS partes: aísla el bloque del CLIENTE (no el de
    ILUS), valida el tipo de cada dato (una dirección no puede ser un correo) y
    excluye la identidad propia de ILUS (RUT 76.996.964-0, dominios @sphs.cl,
    nombre legal, direcciones de oficina/bodega)."""
    import re
    t = texto or ""
    low = t.lower()
    cli = {"razon_social": None, "rut": None, "direccion": None, "comuna": None,
           "ciudad": None, "region": None, "contacto_nombre": None, "contacto_cargo": None,
           "contacto_email": None, "contacto_tel": None}
    ct = {"nombre": None, "numero": None, "tipo_contrato": None,
          "vigencia_inicio": None, "vigencia_fin": None, "es_indefinido": False,
          "frecuencia_meses": None, "visitas_anuales": None,
          "monto_mensual": None, "costo_por_mant": None, "costo_total": None,
          "moneda": "CLP", "incluye_mant_gratis": False, "incluye_repuestos": False,
          "resumen": None, "clausulas_criticas": [], "alertas": []}

    avisos = []  # transparencia: qué se filtró de ILUS / qué falta del cliente

    # ── Aislar el bloque del CLIENTE (no el de ILUS) ──
    seg_cli, seg_ilus, modo = _contrato_partes(t)
    base = seg_cli or t                       # de dónde extraer los datos del cliente
    base_flat = re.sub(r'\s+', ' ', base)     # sin saltos de línea: el PDF parte
                                              # las frases ("...PARADERO 5\nACHUPALLAS")
    if modo == "comparecencia":
        avisos.append("Se identificaron dos partes; se excluyeron los datos de "
                      "ILUS (arrendador/prestador) y se tomaron los del cliente.")
    if "�" in t:
        avisos.append("Algunos caracteres especiales (ñ, tildes) no se leyeron "
                      "bien en este PDF; verifica comuna/dirección o sube el .docx original.")

    _RUT_RE   = r'\b\d{1,2}[.\s]?\d{3}[.\s]?\d{3}\s*-\s*[\dkK]\b'
    _EMAIL_RE = r'[\w.\-]{1,64}@[\w\-]{1,63}\.[\w.\-]{2,24}'   # cuantif. acotado (anti-ReDoS)

    # ── RUTs: excluye el de ILUS; los adyacentes a marcadores de ILUS (RUT de
    #    holding/representante) van al final. El endpoint cruza con el ERP para
    #    confirmar cuál es el cliente.
    def _ruts_ordenados(s):
        cerca, lejos = [], []
        for mm in re.finditer(_RUT_RE, s or ""):
            r = mm.group(0).replace(" ", "")
            if _es_rut_ilus(r):
                continue
            (cerca if _marcador_ilus_cerca(s, mm.start(), mm.end()) else lejos).append(r)
        return lejos + cerca
    ruts = list(dict.fromkeys(_ruts_ordenados(base) + _ruts_ordenados(t)))
    if ruts:
        cli["rut"] = ruts[0]
    elif not re.search(_RUT_RE, t):
        avisos.append("No se detectó RUT en dígitos (puede venir escrito en palabras).")
    if re.search(r'\b(ambos|los|las)\s+arrendatari|\bcoarrendatari', low):
        avisos.append("El contrato menciona más de un cliente (arrendatarios); "
                      "se precargó el primero — revisa el resto.")

    # ── Correo del CLIENTE: excluye dominios de ILUS Y correos pegados a un
    #    marcador de ILUS (p.ej. el correo externo del representante del
    #    arrendador). Así el bug "correo de ILUS como cliente" no vuelve por la
    #    puerta de un dominio fuera de la lista.
    def _emails_cliente(s):
        out = []
        for mm in re.finditer(_EMAIL_RE, s or ""):
            e = mm.group(0).rstrip(".")
            if _es_email_ilus(e) or _marcador_ilus_cerca(s, mm.start(), mm.end()):
                continue
            out.append(e)
        return out
    email_final = (_emails_cliente(base) or _emails_cliente(t) or [None])[0]
    if email_final:
        cli["contacto_email"] = email_final
    elif re.search(_EMAIL_RE, t):
        avisos.append("El correo del documento parece de ILUS (no del cliente); "
                      "ingresa el correo del cliente.")

    # ── Teléfono del CLIENTE (excluye el de ILUS) ──
    for s in (base, t):
        hit = next((m.group(0).strip() for m in
                    re.finditer(r'(\+?56\s?9\s?\d{4}\s?\d{4}|\b9\d{8}\b)', s or "")
                    if not _es_tel_ilus(m.group(0))), None)
        if hit:
            cli["contacto_tel"] = hit
            break

    # ── Razón social del cliente ──
    rs = None
    # 1) etiquetado explícito ("Razón social: X")
    m = re.search(r'raz[oó]n\s+social\s*[:\s]\s*([A-ZÁÉÍÓÚÑ0-9][^\n]{3,80})', base, re.I)
    if m and not _es_nombre_ilus(m.group(1)):
        rs = m.group(1)
    # 2) nombre en MAYÚSCULAS seguido de su RUT / Rol único / "persona jurídica"
    #    o terminado en sufijo societario (SpA/LTDA/EIRL/SA). SIN re.I: el nombre
    #    legal va en mayúsculas y así no se confunde con texto suelto en minúscula.
    if not rs:
        for pat in (
            r'\b([A-ZÑÁÉÍÓÚ][A-ZÑÁÉÍÓÚ0-9&. ]{3,69}?)\s*,?\s*'
            r'(?:RUT\b|R\.U\.T|Rol\s+[úuÚU]nico|persona\s+jur|sociedad\s+del|,\s*c[ée]dula)',
            r'\b([A-ZÑÁÉÍÓÚ][A-ZÑÁÉÍÓÚ0-9&. ]{2,69}?\b(?:SpA|LTDA|LIMITADA|EIRL|E\.I\.R\.L|S\.?P\.?A|S\.A\.?))\b',
        ):
            m = re.search(pat, base_flat)
            if m and not _es_nombre_ilus(m.group(1)):
                rs = m.group(1)
                break
    if rs:
        cli["razon_social"] = re.sub(r'\s+', ' ', rs).strip(' .,:-')

    # ── Representante / contacto del cliente (nombre + cargo) ──
    _CARGOS = (r'gerente\s+general|gerente|administrador(?:a)?(?:\s+general)?|'
               r'representante\s+legal|director(?:a)?(?:\s+general)?|presidente|'
               r'jefe\s+de\s+operaciones|due[nñ][oa]|propietari[oa]|encargad[oa]')
    # cargo (puede ir entre "representada por (su)" y "don/doña")
    mc = re.search(r'representad[oa]s?\s+por\s+'
                   r'(?:su\s+|el\s+|la\s+|en\s+(?:su\s+)?calidad\s+de\s+)?'
                   r'(' + _CARGOS + r')\b', base_flat, re.I)
    if mc:
        cli["contacto_cargo"] = re.sub(r'\s+', ' ', mc.group(1)).strip().title()
    # nombre (tolera un cargo opcional antes de don/doña)
    m = re.search(r'representad[oa]s?\s+por\s+'
                  r'(?:(?:su|el|la|en\s+(?:su\s+)?calidad\s+de)\s+)?'
                  r'(?:(?:' + _CARGOS + r')[,\s]+)?'
                  r'(?:don|do[nñ]a|sr\.?|sra\.?|se[nñ]or[a]?)\s+'
                  r'([A-ZÑÁÉÍÓÚ][A-ZÑÁÉÍÓÚ ]{4,55}?)\s*'
                  r'(?=,|\bc[ée]dula\b|\bc\.?i\.?\b|\brut\b|chilen[oa]\b)', base_flat, re.I)
    if m and not _es_nombre_ilus(m.group(1)):
        cli["contacto_nombre"] = re.sub(r'\s+', ' ', m.group(1)).strip(' .,:-').title()

    # ── Domicilio del cliente (corta antes de Comuna/Ciudad/Región/etc.) ──
    #    Cubre prosa ("domiciliados [para estos efectos] en X, Comuna…") y
    #    etiqueta ("Domicilio: X" / "Dirección: X"). _valida_direccion rechaza
    #    correos/RUT/dirección de ILUS.
    _STOP_DIR = (r'(?=,?\s*(?:comuna|ciudad|regi[oó]n|provincia)\b|\ben\s+adelante\b|'
                 r'\bde\s+paso\b|\bfrecuencia\b|\bmantenc|\bvalor\b|\bmonto\b|\btel|'
                 r'\bcorreo\b|\brut\b|\bgiro\b|;|$)')
    m = re.search(r'(?:domiciliad[oa]s?\b[^,]{0,40}?\ben|domicili[ao]|direcci[oó]n)'
                  r'\s*[:\s]?\s*(.{5,80}?)' + _STOP_DIR, base_flat, re.I)
    if m:
        d = _valida_direccion(m.group(1))
        if d:
            cli["direccion"] = d

    # ── Comuna / Ciudad / Región del cliente ──
    #    Se busca sobre `base` (con saltos de línea): en contratos etiquetados la
    #    comuna está en su propia línea, y el \n evita arrastrar la frase siguiente
    #    (ej: "Comuna Iquique\nSe incluyen 2 mantenciones" → 'Iquique', no None).
    _STOP_LUG = (r'(?=,|;|\.|\n|\bciudad\b|\bregi[oó]n\b|\bprovincia\b|\bchile\b|'
                 r'\bfrecuencia\b|\bmantenc|\bvalor\b|\bmonto\b|\btel|\bcorreo\b|'
                 r'\brut\b|\bgiro\b|\bde\s+paso\b|\ben\s+adelante\b|\bse\s+incluye|$)')

    def _campo_lugar(label_re):
        m2 = re.search(r'\b' + label_re + r'\b\s*[:\s]\s*'
                       r'(?:de\s+|del\s+|metropolitana\s+de\s+)?'
                       r'([A-Za-zÁÉÍÓÚÑáéíóúñ .]{3,30}?)' + _STOP_LUG, base, re.I)
        return _valida_comuna(m2.group(1)) if m2 else None

    cmn = _campo_lugar('comuna')
    if cmn: cli["comuna"] = cmn
    cd = _campo_lugar('ciudad')
    if cd: cli["ciudad"] = cd
    rg = _campo_lugar(r'regi[oó]n')
    if rg: cli["region"] = rg

    freq_map = {"mensual": 1, "bimestral": 2, "trimestral": 3, "cuatrimestral": 4,
                "semestral": 6, "anual": 12}
    # 1) "frecuencia/servicio/mantención <palabra>" tiene prioridad (evita confundir
    #    con "monto mensual"); 2) palabra suelta (mensual solo si no es de pago);
    #    3) "cada N meses" manda explícito.
    mfreq = re.search(r'(?:frecuencia|servicio|mantenci[oó]n(?:es)?)\s+'
                      r'(?:ser[aá]n?\s+)?(?:de\s+)?(?:tipo\s+|car[aá]cter\s+)?'
                      r'(mensual|bimestral|trimestral|cuatrimestral|semestral|anual)', low)
    if mfreq:
        ct["frecuencia_meses"] = freq_map[mfreq.group(1)]
    else:
        for k in ("trimestral", "cuatrimestral", "semestral", "bimestral", "anual", "mensual"):
            if k == "mensual" and re.search(r'(monto|pago|valor|cuota|abono|arriendo|renta)\s+mensual', low):
                continue
            if k in low:
                ct["frecuencia_meses"] = freq_map[k]
                break
    m = re.search(r'cada\s+(\d{1,2})\s+mes', low)
    if m: ct["frecuencia_meses"] = int(m.group(1))
    m = re.search(r'(\d{1,2})\s+visitas?\s+(?:al\s+a[nñ]o|anuales)', low)
    if m: ct["visitas_anuales"] = int(m.group(1))

    # Montos clasificados por CONTEXTO: el mayor suele ser una multa/penalización,
    # no el valor del contrato → se excluyen multa/interés/indemnización.
    montos, montos_mult, monto_mensual_ctx = [], [], None
    for mm in re.finditer(r'\$\s?([\d.]{4,})', t):
        x = mm.group(1).replace('.', '')
        if not x.isdigit():
            continue
        val = int(x)
        # Ventana HACIA ATRÁS: en español el descriptor precede al monto
        # ("la renta mensual de $X", "una multa de $X"). Mirar hacia adelante
        # contaminaría con la frase siguiente (la multa que viene después).
        ctx = low[max(0, mm.start() - 60):mm.end()]
        if re.search(r'multa|penaliz|indemniz|incumplimiento|cl[aá]usula\s+penal|'
                     r'sanci[oó]n|inter[eé]s', ctx):
            montos_mult.append(val)
            continue
        montos.append(val)
        if monto_mensual_ctx is None and re.search(r'mensual|renta|arriendo|cuota', ctx):
            monto_mensual_ctx = val
    if montos:
        ct["costo_total"] = max(montos)
        ct["monto_mensual"] = monto_mensual_ctx or (min(montos) if "mensual" in low else None)
    elif montos_mult:
        avisos.append("Solo se detectaron montos de multa/penalización; "
                      "verifica el valor real del contrato.")
    if re.search(r'\buf\b', low):
        ct["moneda"] = "UF"

    fechas = _contrato_fechas(t)
    if fechas:
        ct["vigencia_inicio"] = fechas[0]
        if len(fechas) > 1:
            ct["vigencia_fin"] = fechas[-1]
    elif re.search(r'\bdos mil\s+(?:diez|veinte|veinti|treinta|once|doce|trece|catorce|'
                   r'quince|diecis|diecio|diecin)', low):
        avisos.append("Las fechas vienen escritas en palabras; ingrésalas a mano.")
    if "indefinid" in low:
        ct["es_indefinido"] = True

    mg = re.search(r'mantenci[oó]n(?:es)?\s+gratuit', low)
    if (mg and not re.search(r'\bno\b', low[max(0, mg.start() - 15):mg.start()])) or "sin costo" in low:
        ct["incluye_mant_gratis"] = True
    mr = re.search(r'(?:incluye[n]?|incluid[oa]s?)[^.\n]{0,40}repuesto', low)
    if mr and not re.search(r'\bno\b', low[max(0, mr.start() - 12):mr.start()]):
        ct["incluye_repuestos"] = True

    if "preventiv" in low and "correctiv" in low: ct["tipo_contrato"] = "Mixto"
    elif "preventiv" in low: ct["tipo_contrato"] = "Preventivo"
    elif "correctiv" in low: ct["tipo_contrato"] = "Correctivo"
    elif "leasing" in low: ct["tipo_contrato"] = "Leasing"
    elif "comodato" in low: ct["tipo_contrato"] = "Comodato"
    elif "arrend" in low or "arriendo" in low: ct["tipo_contrato"] = "Arriendo"
    elif "mantenci" in low or "servicio t" in low: ct["tipo_contrato"] = "Mantención"
    # 'Garantía' solo si es el OBJETO del contrato, no una cláusula ("boleta de garantía").
    elif re.search(r'contrato\s+de\s+garant', low): ct["tipo_contrato"] = "Garantía"

    # Plazo escrito en meses ("vigente por 14 meses") — útil cuando las fechas
    # vienen en palabras y no se pudieron parsear.
    mpl = re.search(r'(?:vigente|vigencia|plazo|duraci[oó]n|durar[aá]n?)\s+'
                    r'(?:de\s+|por\s+un\s+per[ií]odo\s+de\s+|por\s+)?(\d{1,3})\s+mes', low)
    if mpl:
        avisos.append(f"Plazo del contrato detectado: {int(mpl.group(1))} meses.")

    ct["nombre"] = f"Contrato {ct['tipo_contrato']}" if ct["tipo_contrato"] else "Contrato de mantención"
    ct["resumen"] = ("Datos leídos del documento por el Agente ILUS (sin IA). "
                     "Verifica y completa lo que falte; el RUT trae el resto desde el ERP.")

    # Score / riesgo DETERMINISTA (sin IA): por completitud + condiciones comerciales.
    score = 40
    alertas, clausulas, mejoras = [], [], []
    if ct["frecuencia_meses"]: score += 15
    else: alertas.append("No se detectó la frecuencia de mantención.")
    if ct["vigencia_inicio"]: score += 10
    else: alertas.append("No se detectó la vigencia del contrato.")
    if ct["costo_total"] or ct["monto_mensual"]: score += 15
    else: alertas.append("No se detectó el valor del contrato.")
    if ct["incluye_repuestos"]:
        score += 10; clausulas.append("Incluye repuestos.")
    if ct["incluye_mant_gratis"]:
        score -= 10
        clausulas.append("Incluye mantenciones gratuitas (costo para nosotros).")
        mejoras.append("Controlar las mantenciones gratuitas para no exceder lo pactado.")
    if not cli["rut"]:
        alertas.append("No se detectó el RUT en el documento.")
    score = max(5, min(100, score))
    ct["score"] = score
    ct["nivel_riesgo"] = "alto" if score < 45 else ("medio" if score < 70 else "bajo")
    ct["clausulas_criticas"] = clausulas
    # avisos de transparencia (qué se filtró de ILUS / qué falta) van PRIMERO
    ct["alertas"] = avisos + alertas
    ct["mejoras_prioritarias"] = mejoras or ["Completar los datos faltantes del contrato y del cliente."]

    return {"cliente": cli, "contrato": ct, "equipos": _contrato_equipos(t), "_ruts": ruts}


def _contrato_match_erp(rut, razon=None):
    """Cruza un RUT (o razón social) con BD local + ERP (read-only). Devuelve el _erp_match."""
    if rut:
        cuerpo = _rut_cuerpo(rut)
        if cuerpo and len(cuerpo) >= 6:
            local = mysql_fetchone(
                "SELECT * FROM mant_clientes "
                "WHERE REPLACE(REPLACE(REPLACE(rut,'.',''),'-',''),' ','') LIKE %s LIMIT 1",
                (f"%{cuerpo}%",))
            if local:
                return {"origen": "local", "id": local["id"],
                        "razon_social": local.get("razon_social"),
                        "rut": local.get("rut"), "estado": local.get("estado")}
        rows = _erp_buscar_clientes(rut, limit=1)
        if rows:
            return {"origen": "erp", "id": None,
                    "razon_social": rows[0]["razon_social"], "rut": rows[0]["rut"]}
    if razon and len(razon) >= 4:
        rows = _erp_buscar_clientes(razon, limit=1)
        if rows:
            return {"origen": "erp", "id": None,
                    "razon_social": rows[0]["razon_social"], "rut": rows[0]["rut"]}
    return {}


@app.route("/mantenciones/api/agente-contrato", methods=["POST"])
@_mant_required
def mant_agente_contrato():
    """
    AGENTE ILUS DE CONTRATOS — DETERMINISTA, CERO IA.
    - PDF / Word: se leen con código y se extraen RUT, razón social, montos,
      fechas, frecuencia, contacto, etc. con reglas (regex/heurística).
    - El RUT detectado se cruza con el ERP (read-only) para datos oficiales.
    - FOTO / imagen: no se lee con código (eso sería IA); se responde
      requiere_rut=True para pedir el RUT y traer todo del ERP.
    """
    f = request.files.get("archivo")
    if not f or not f.filename:
        return jsonify({"error": "Sin archivo"}), 400

    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in ("pdf", "doc", "docx") + _MANT_IMG_EXTS:
        return jsonify({"error": "Formato no válido. Usa PDF, Word o imagen (JPG/PNG)."}), 400

    # FOTO / imagen: sin OCR (sería IA). Pedimos el RUT y traemos todo del ERP.
    if ext in _MANT_IMG_EXTS:
        return jsonify({"ok": True, "motor": "agente-ilus", "requiere_rut": True,
                        "mensaje": "📸 Para leer una foto necesito el RUT. Escríbelo y traigo "
                                   "los datos del cliente y su universo de productos desde el ERP."})

    # PDF / WORD → extraer texto con código
    tmp_path = os.path.join(MANT_UPLOADS, f"tmp_{int(time.time())}_{secure_filename(f.filename)}")
    f.save(tmp_path)
    texto = ""
    try:
        if ext == "pdf":
            import pdfplumber
            with pdfplumber.open(tmp_path) as pdf:
                texto = "\n".join(p.extract_text() or "" for p in pdf.pages[:20])
        else:
            import docx as _docx
            doc = _docx.Document(tmp_path)
            # cap de párrafos/celdas: el .docx no tiene el límite de 20 páginas
            # del PDF; evita procesar documentos enormes.
            texto = "\n".join(p.text for p in doc.paragraphs[:4000])
            for _tb in doc.tables[:60]:
                for _row in _tb.rows:
                    texto += "\n" + " | ".join(c.text for c in _row.cells)
                if len(texto) > 250000:
                    break
    except Exception as e:
        print(f"[agente-contrato] lectura: {e}", flush=True)
        if ext == "doc":
            # .doc binario antiguo: python-docx solo abre .docx (OOXML).
            return jsonify({"ok": True, "motor": "agente-ilus", "requiere_rut": True,
                            "mensaje": "El formato Word antiguo (.doc) no se puede leer aquí. "
                                       "Guárdalo como .docx o PDF, o escribe el RUT y traigo "
                                       "todo del cliente desde el ERP."})
        return jsonify({"error": "No se pudo leer el archivo. Prueba con el PDF o escribe el RUT."}), 500
    finally:
        try: os.remove(tmp_path)
        except Exception: pass

    if not texto.strip():
        return jsonify({"ok": True, "motor": "agente-ilus", "requiere_rut": True,
                        "mensaje": "No pude extraer texto (puede ser un PDF escaneado). "
                                   "Escribe el RUT y traigo todo del ERP."})

    # Cota de tamaño: los datos del cliente están al inicio del documento; evita
    # que un archivo enorme/adversarial sature el worker (la extracción es síncrona).
    if len(texto) > 200000:
        texto = texto[:200000]

    resultado = _contrato_extraer_determinista(texto)

    # Elegir el RUT que el ERP reconozca como cliente: un contrato suele traer el
    # RUT del prestador (ILUS) y el del cliente; nos quedamos con el del cliente.
    ruts = resultado.pop("_ruts", [])
    cli = resultado.get("cliente") or {}
    candidatos = []
    for r in ([cli.get("rut")] if cli.get("rut") else []) + ruts:
        if r and r not in candidatos:
            candidatos.append(r)
    match = {}
    for r in candidatos:
        m = _contrato_match_erp(r, None)
        if m:
            match = m
            cli["rut"] = r
            break
    if not match:
        match = _contrato_match_erp(None, cli.get("razon_social"))
    if match.get("razon_social") and not cli.get("razon_social"):
        cli["razon_social"] = match["razon_social"]
    resultado["cliente"] = cli
    resultado["_erp_match"] = match
    resultado["motor"] = "agente-ilus"
    return jsonify({"ok": True, "resultado": resultado})


@app.route("/mantenciones/api/ots/reset", methods=["POST"])
@_mant_required
def mant_ots_reset():
    """Reseteo masivo de OTs (visitas) — SOLO superadmin, con respaldo previo.

    Daniel 30/05/2026: limpiar el sistema para una ronda de prueba completa.
    Seguridad (no negociable):
      - Solo superadmin.
      - Exige confirm_text == 'BORRAR OT' escrito a mano.
      - Respalda TODAS las visitas a mant_visitas_backup ANTES de borrar
        (red de seguridad → reversible).
      - DELETE de mant_visitas (cascade limpia fotos/tareas/repuestos/tiempos).
      - Audit log.
    NO toca contratos, clientes ni equipos.
    """
    if not (getattr(g, "permissions", {}) or {}).get("superadmin"):
        return jsonify({"error": "Solo el superadministrador puede resetear las OTs."}), 403
    d = request.get_json(silent=True) or {}
    if (d.get("confirm_text") or "").strip().upper() != "BORRAR OT":
        return jsonify({"error": "Confirmación inválida. Escribe exactamente: BORRAR OT"}), 400

    try:
        r = mysql_fetchone("SELECT COUNT(*) AS n FROM mant_visitas")
        total_n = int((r or {}).get("n") or 0)
    except Exception:
        total_n = 0
    if total_n == 0:
        return jsonify({"ok": True, "borradas": 0,
                        "mensaje": "No había OTs registradas. El sistema ya estaba limpio."})

    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            # Respaldo (reversible). Tabla espejo; INSERT IGNORE evita colisión
            # de PK si se resetea más de una vez (los id son crecientes).
            cur.execute("CREATE TABLE IF NOT EXISTS mant_visitas_backup LIKE mant_visitas")
            cur.execute("INSERT IGNORE INTO mant_visitas_backup SELECT * FROM mant_visitas")
            # Borrado: cascade limpia tablas hijas con FK ON DELETE CASCADE.
            cur.execute("DELETE FROM mant_visitas")
        conn.commit()
    finally:
        conn.close()

    try:
        _mant_log("sistema", 0, "ots_reset",
                  f"RESET OTs por {current_username()}: {total_n} visitas respaldadas "
                  f"en mant_visitas_backup y borradas (cascade).")
    except Exception:
        pass
    return jsonify({"ok": True, "borradas": total_n,
                    "mensaje": f"{total_n} OTs respaldadas y borradas. Sistema limpio para tu ronda de prueba."})


# ══════════════════════════════════════════════════════════════════════
# DIAGNÓSTICO + REPARACIÓN — bug histórico fecha_fin en fecha_realizada
# (FIX 2026-07-15). Antes del fix, _mant_lev_crear_ot_core guardaba el fin
# de un rango multi-día (data["fecha_fin"]) en la columna fecha_realizada
# en vez de en su propia columna. Mismo patrón que mant_ots_reset arriba:
# dry-run de solo lectura primero (GET diagnóstico), botón "Aplicar"
# separado (POST reparar), audit log ANTES de tocar cada fila, 100% manual
# (nunca se llama desde el arranque ni desde otro endpoint).
# ══════════════════════════════════════════════════════════════════════

@app.route("/mantenciones/api/admin/diagnostico-fecha-fin-corrupta", methods=["GET"])
@_mant_required
def mant_admin_diagnostico_fecha_fin_corrupta():
    """Diagnóstico SOLO LECTURA (superadmin) de la corrupción de datos
    causada por el bug de _mant_lev_crear_ot_core (ver comentario del
    bloque arriba). NO escribe nada.

    Huella EXACTA del bug: una OT que sigue en estado 'programada' NUNCA
    debería tener fecha_realizada poblada -- esa columna solo se llena al
    CERRAR la OT (ver mant_lev_cerrar). La reparación real vive en el POST
    hermano /mantenciones/api/admin/reparar-fecha-fin (también superadmin).
    """
    if not (getattr(g, "permissions", {}) or {}).get("superadmin"):
        return jsonify({"ok": False, "error": "Solo el superadministrador puede ver este diagnóstico."}), 403
    try:
        filas = mysql_fetchall(
            "SELECT id, numero_ot, cliente_id, fecha_programada, fecha_realizada, "
            "       estado, created_at "
            "  FROM mant_visitas "
            " WHERE estado = 'programada' AND fecha_realizada IS NOT NULL "
            " ORDER BY created_at DESC"
        ) or []
        out = []
        for f in filas:
            _fp = f.get("fecha_programada")
            _fr = f.get("fecha_realizada")
            _ca = f.get("created_at")
            out.append({
                "id": f.get("id"),
                "numero_ot": f.get("numero_ot"),
                "cliente_id": f.get("cliente_id"),
                "fecha_programada": _fp.isoformat() if hasattr(_fp, "isoformat") else (str(_fp) if _fp is not None else None),
                "fecha_realizada": _fr.isoformat() if hasattr(_fr, "isoformat") else (str(_fr) if _fr is not None else None),
                "estado": f.get("estado"),
                "created_at": _ca.isoformat() if hasattr(_ca, "isoformat") else (str(_ca) if _ca is not None else None),
            })
        return jsonify({"ok": True, "total": len(out), "filas": out})
    except Exception as e:
        print(f"[diagnostico_fecha_fin] {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo generar el diagnóstico."}), 500


@app.route("/mantenciones/api/admin/reparar-fecha-fin", methods=["POST"])
@_mant_required
def mant_admin_reparar_fecha_fin():
    """Repara los datos históricos corrompidos por el bug de
    _mant_lev_crear_ot_core (ver diagnóstico GET hermano,
    /mantenciones/api/admin/diagnostico-fecha-fin-corrupta). SOLO superadmin.

    Para cada fila que calza EXACTAMENTE la huella del bug
    (estado='programada' AND fecha_realizada IS NOT NULL) mueve el valor de
    fecha_realizada a fecha_fin y limpia fecha_realizada a NULL. Nunca toca
    una OT que de verdad fue cerrada (esas tienen estado <> 'programada',
    o si volvieran a 'programada' por algún flujo futuro, ya no tendrían
    fecha_realizada IS NOT NULL a menos que se repita el bug -- ya corregido).

    Audit log en mant_logs (entidad='visita', accion='reparar_fecha_fin_corrupta')
    ANTES de aplicar cada UPDATE (Regla #5). Todo en una sola transacción.
    Acción 100% manual: no se llama desde el arranque ni desde ningún otro
    endpoint -- solo se dispara si alguien golpea esta URL a propósito.
    """
    if not (getattr(g, "permissions", {}) or {}).get("superadmin"):
        return jsonify({"ok": False, "error": "Solo el superadministrador puede ejecutar esta reparación."}), 403
    try:
        filas = mysql_fetchall(
            "SELECT id, numero_ot, cliente_id, fecha_programada, fecha_realizada, "
            "       estado, created_at "
            "  FROM mant_visitas "
            " WHERE estado = 'programada' AND fecha_realizada IS NOT NULL "
            " ORDER BY created_at DESC"
        ) or []
        if not filas:
            return jsonify({"ok": True, "reparadas": 0, "detalle": [],
                            "mensaje": "No hay OTs con la huella del bug. Nada que reparar."})

        conn = get_mysql()
        reparadas = 0
        detalle = []
        try:
            with conn.cursor() as cur:
                for f in filas:
                    vid = f.get("id")
                    # Re-verifica CADA fila DENTRO de la transacción -- no
                    # confiar en el SELECT de arriba si algo cambió entre el
                    # diagnóstico y el click de "Aplicar" (ej. la OT se cerró
                    # justo en el medio y ya tiene una fecha_realizada legítima).
                    cur.execute(
                        "SELECT id FROM mant_visitas "
                        " WHERE id=%s AND estado='programada' AND fecha_realizada IS NOT NULL",
                        (vid,)
                    )
                    if not cur.fetchone():
                        continue
                    _fr = f.get("fecha_realizada")
                    _fr_str = _fr.isoformat() if hasattr(_fr, "isoformat") else str(_fr)
                    # Audit ANTES de aplicar el cambio (Regla #5).
                    cur.execute(
                        "INSERT INTO mant_logs (entidad,entidad_id,accion,detalle,usuario) "
                        "VALUES (%s,%s,%s,%s,%s)",
                        ("visita", vid, "reparar_fecha_fin_corrupta",
                         f"OT {f.get('numero_ot')}: fecha_realizada corrupta ({_fr_str}) "
                         f"movida a fecha_fin; fecha_realizada limpiada a NULL.",
                         current_username())
                    )
                    # El valor se copia LADO SQL (fecha_fin=fecha_realizada) --
                    # evita cualquier problema de formato/zona horaria al
                    # rearmar la fecha desde Python.
                    cur.execute(
                        "UPDATE mant_visitas SET fecha_fin = fecha_realizada, "
                        "       fecha_realizada = NULL "
                        " WHERE id=%s",
                        (vid,)
                    )
                    reparadas += 1
                    detalle.append({"id": vid, "numero_ot": f.get("numero_ot"),
                                     "fecha_fin_reparada": _fr_str})
            conn.commit()
        finally:
            conn.close()
        return jsonify({"ok": True, "reparadas": reparadas, "detalle": detalle,
                        "mensaje": f"{reparadas} OT(s) reparada(s): fecha_realizada corrupta movida a fecha_fin."})
    except Exception as e:
        print(f"[reparar_fecha_fin] {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo completar la reparación."}), 500


@app.route("/mantenciones/api/clientes/<int:cid>/generar-calendario", methods=["POST"])
@_mant_required
def mant_generar_calendario(cid):
    """
    Genera visitas de mantención automáticas basadas en el contrato activo del cliente.
    Devuelve preview (dry_run=true) o guarda en DB.

    2026-05-22 — Daniel: la creación masiva debe ser EXPLICITA. Si el body
    no trae `confirm: true` Y dry_run=false, forzamos dry_run igual para
    proteger contra clicks accidentales o agentes IA. La única forma de
    crear es: {dry_run: false, confirm: true}.
    """
    d        = request.get_json(silent=True) or {}
    dry_run  = d.get("dry_run", True)
    confirm  = bool(d.get("confirm", False))
    # Si el caller quiere crear pero no confirmó, forzamos preview
    if not dry_run and not confirm:
        dry_run = True
    desde_str= d.get("desde")     # YYYY-MM-DD
    meses    = int(d.get("meses", 12))
    tipo     = d.get("tipo", "preventiva")
    tecnico  = d.get("tecnico", "")

    # Obtener frecuencia del contrato activo
    ct = mysql_fetchone(
        """SELECT * FROM mant_contratos
           WHERE cliente_id=%s AND estado IN ('vigente','indefinido')
           ORDER BY created_at DESC LIMIT 1""",
        (cid,)
    )
    cliente = mysql_fetchone(
        "SELECT razon_social, dia_mantencion_pref FROM mant_clientes WHERE id=%s", (cid,))
    if not ct:
        return jsonify({"error": "Sin contrato activo para este cliente"}), 404

    frecuencia = ct.get("ai_frecuencia_sug") or ct.get("frecuencia_meses") or 3
    desde = datetime.strptime(desde_str, "%Y-%m-%d").date() if desde_str else datetime.now().date()

    # PLANIFICADOR 2026-06-10: la fecha EMITIDA respeta el día preferido del
    # cliente (U.Católica = día 12) + regla 'mover a día hábil'. El cursor
    # `fecha_actual` avanza CRUDO (misma regla de oro que el motor del agente).
    _dia_pref = (cliente or {}).get("dia_mantencion_pref")
    _R_cal = _reglas_cargar()

    visitas_preview = []
    fecha_actual = desde
    while fecha_actual <= desde + timedelta(days=meses * 30):
        _fa = _mant_fecha_ajustada(fecha_actual, _dia_pref, _R_cal) or fecha_actual
        visitas_preview.append({
            "fecha":    str(_fa),
            "titulo":   f"Mantención {tipo.capitalize()} — {cliente['razon_social'] if cliente else ''}",
            "tipo":     tipo,
            "tecnico":  tecnico,
            "contrato_id": ct["id"],
        })
        # Siguiente visita
        mes = fecha_actual.month + frecuencia
        anio = fecha_actual.year
        while mes > 12:
            mes -= 12
            anio += 1
        try:
            fecha_actual = fecha_actual.replace(year=anio, month=mes)
        except ValueError:
            fecha_actual = fecha_actual.replace(year=anio, month=mes, day=28)

    if dry_run:
        return jsonify({
            "ok": True,
            "dry_run": True,
            "preview": visitas_preview,
            "preview_count": len(visitas_preview),
            "frecuencia": frecuencia,
            "requires_confirm": True,
            "mensaje": ("Vista previa. Para crear las OTs envía de nuevo "
                        "con dry_run=false y confirm=true."),
        })

    # Guardar visitas — solo si llegó confirm=true (validado arriba)
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            for v in visitas_preview:
                cur.execute(
                    """INSERT INTO mant_visitas
                       (cliente_id,contrato_id,titulo,fecha_programada,tipo,estado,created_by)
                       VALUES (%s,%s,%s,%s,%s,'programada',%s)""",
                    (cid, v["contrato_id"], v["titulo"], v["fecha"], v["tipo"], current_username())
                )
        conn.commit()
        _mant_log("cliente", cid, "calendario_generado",
                  f"{len(visitas_preview)} visitas (confirm=true por {current_username()})")
        return jsonify({"ok": True, "creadas": len(visitas_preview)})
    finally:
        conn.close()


@app.route("/mantenciones/api/contratos/<int:ctid>/ai-editar", methods=["PUT"])
@_mant_required
def mant_contrato_ai_editar(ctid):
    """Guarda los campos del análisis IA editados manualmente por el usuario."""
    d = request.get_json(silent=True) or {}
    editable_fields = [
        "nombre", "fecha_inicio", "fecha_vencimiento", "es_indefinido",
        "monto_mensual", "monto_anual", "frecuencia_meses", "ai_frecuencia_sug",
        "notas", "estado", "sla_horas", "incluye_repuestos", "incluye_mant_gratis",
        "costo_por_mant", "costo_total", "nivel_riesgo",
        "ai_tipo_contrato", "ai_cobertura", "ai_vigencia_inicio", "ai_vigencia_fin",
    ]
    sets = [f"{f}=%s" for f in editable_fields if f in d]
    vals = [d[f] for f in editable_fields if f in d]
    # Guardar snapshot editable como JSON también
    sets.append("ai_editable=%s")
    vals.append(json.dumps(d, ensure_ascii=False))
    if not sets:
        return jsonify({"error": "Sin campos"}), 400
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(f"UPDATE mant_contratos SET {','.join(sets)} WHERE id=%s", vals + [ctid])
        conn.commit()
        _mant_log("contrato", ctid, "ai_editado_manual")
        return jsonify({"ok": True})
    finally:
        conn.close()


