@app.route("/cotizaciones")
@_mant_required
@_no_tecnico
def cotizaciones_hub_list():
    """Cotizaciones (central) — 2026-07-12: entrada ÚNICA de cotizaciones.
    Hasta 2026-07-18 unía dos sistemas (tk_cotizaciones + el viejo módulo
    mant_cotizaciones de Mantenciones); el sistema viejo fue jubilado esa
    fecha con autorización explícita de Daniel (datos conservados en
    mant_cotizaciones, sin UI). El hub queda sirviendo SOLO tk_cotizaciones
    (tickets_module), el sistema vivo."""
    filtro_q = (request.args.get("q") or "").strip()

    tk_rows = mysql_fetchall(
        "SELECT id, numero_cotizacion AS numero, estado, empresa, rut, total, "
        "       created_at, ticket_id "
        "  FROM tk_cotizaciones "
        " ORDER BY created_at DESC LIMIT 200"
    ) or []

    unificado = []
    for r in tk_rows:
        r = dict(r)
        unificado.append({
            "origen": "ticket", "origen_label": "Ticket",
            "id": r["id"], "numero": r.get("numero") or f"TK-COT-{r['id']}",
            "estado": r.get("estado"), "empresa": r.get("empresa") or "—",
            "rut": r.get("rut") or "—", "total": r.get("total") or 0,
            "created_at": r.get("created_at"),
            "url": url_for("tk_cotizaciones_list"),
        })

    if filtro_q:
        fq = filtro_q.lower()
        unificado = [
            u for u in unificado
            if fq in (u["numero"] or "").lower()
            or fq in (u["empresa"] or "").lower()
            or fq in (u["rut"] or "").lower()
        ]

    unificado.sort(key=lambda u: u["created_at"] or datetime.min, reverse=True)

    return render_template(
        "clientes_hub/cotizaciones.html",
        cotizaciones=unificado, filtro_q=filtro_q,
    )


def _checkwms_get(path: str, params: dict, timeout: int = 60) -> dict | None:
    """GET de solo lectura contra CheckWMS (sistema de bodega externo).

    La API es inconsistente con el nombre de sus headers de auth entre
    endpoints (usu_uid_usu/ins_uid_ins en unos, uidUsuMe/uidInsMe en
    otros) -- se mandan ambas variantes para no depender de cuál usa cada
    endpoint. Sin credenciales configuradas (CHECKWMS_UID_INS/UID_ERP)
    devuelve None de inmediato (fail-soft, el módulo Incidencias sigue
    funcionando 100% manual sin esto).

    timeout alto a propósito: GetStockTrazabilidad devuelve ~5,4 MB y
    tarda 15-35 s (medido 2026-08-03). Con 12 s NUNCA alcanzaba a
    responder -- ese era el bug de "CheckWMS no disponible"."""
    if not (CHECKWMS_CONFIG.get("uid_ins") and CHECKWMS_CONFIG.get("uid_erp")):
        return None
    import requests as _req
    try:
        resp = _req.get(
            CHECKWMS_CONFIG["base_url"].rstrip("/") + path,
            params=params,
            headers={
                "usu_uid_usu": CHECKWMS_CONFIG["uid_erp"],
                "ins_uid_ins": CHECKWMS_CONFIG["uid_ins"],
                "uidUsuMe":    CHECKWMS_CONFIG["uid_erp"],
                "uidInsMe":    CHECKWMS_CONFIG["uid_ins"],
                "Accept":      "application/json",
            },
            timeout=timeout,
        )
        resp.raise_for_status()
        return resp.json()
    except Exception as _e:
        print(f"[checkwms] error consultando {path}: {_e}", flush=True)
        return None


# Cache del dump completo de trazabilidad. Necesario porque el parámetro
# `codUa` de la API CUELGA la conexión (verificado 2026-08-03: 60 s sin
# responder con filtro vs 15-35 s sin filtro). Se trae todo una vez y se
# filtra en Python. ~10.400 filas / 5,4 MB, TTL 10 min.
_CHECKWMS_TRAZA = {"ts": 0, "rows": None, "lock": threading.Lock()}
_CHECKWMS_TRAZA_TTL = 3600   # 1 hora (Daniel 2026-08-03)


def _checkwms_trazabilidad_rows(forzar: bool = False) -> list | None:
    """Filas de GetStockTrazabilidad, cacheadas. None si no se pudo traer."""
    now = time.time()
    if (not forzar and _CHECKWMS_TRAZA["rows"] is not None
            and (now - _CHECKWMS_TRAZA["ts"]) < _CHECKWMS_TRAZA_TTL):
        return _CHECKWMS_TRAZA["rows"]
    with _CHECKWMS_TRAZA["lock"]:
        # Doble chequeo: otro hilo pudo refrescar mientras esperábamos.
        if (not forzar and _CHECKWMS_TRAZA["rows"] is not None
                and (time.time() - _CHECKWMS_TRAZA["ts"]) < _CHECKWMS_TRAZA_TTL):
            return _CHECKWMS_TRAZA["rows"]
        data = _checkwms_get("/api/ext/GetStockTrazabilidad", {})
        if data is None:
            return _CHECKWMS_TRAZA["rows"]   # sirve lo viejo si existe
        rows = ((data or {}).get("body") or {}).get("response") or []
        _CHECKWMS_TRAZA.update({"ts": time.time(), "rows": rows})
        return rows


# Cache del REPORTE DE STOCK (GetReporteStock). Es el endpoint que usa la
# pantalla "Reporte Stock" del WMS: stock ACTUAL por bodega/ubicación, ~2,1 MB
# en ~4 s (mucho más rápido y liviano que GetStockTrazabilidad). Es la fuente
# correcta para "¿dónde está esta UA hoy?" -- trazabilidad solo tiene
# movimientos desde jun-2026, por eso UA1008453 aparecía en el WMS pero no
# en la app (bug reportado por Daniel 2026-08-03).
_CHECKWMS_STOCK = {"ts": 0, "rows": None, "lock": threading.Lock()}
_CHECKWMS_STOCK_TTL = 3600   # 1 hora (Daniel 2026-08-03)


def _checkwms_stock_rows(forzar: bool = False) -> list | None:
    """Filas de GetReporteStock (stock actual), cacheadas 10 min."""
    now = time.time()
    if (not forzar and _CHECKWMS_STOCK["rows"] is not None
            and (now - _CHECKWMS_STOCK["ts"]) < _CHECKWMS_STOCK_TTL):
        return _CHECKWMS_STOCK["rows"]
    with _CHECKWMS_STOCK["lock"]:
        if (not forzar and _CHECKWMS_STOCK["rows"] is not None
                and (time.time() - _CHECKWMS_STOCK["ts"]) < _CHECKWMS_STOCK_TTL):
            return _CHECKWMS_STOCK["rows"]
        data = _checkwms_get("/api/ext/GetReporteStock", {}, timeout=45)
        if data is None:
            return _CHECKWMS_STOCK["rows"]
        rows = ((data or {}).get("body") or {}).get("response") or []
        _CHECKWMS_STOCK.update({"ts": time.time(), "rows": rows})
        return rows


def _checkwms_norm_ua(codigo: str) -> str:
    """Normaliza lo que el usuario escribe al formato real del WMS.
    La planilla legacy guardaba 'UA:1012965', 'UA1012965' o sólo el
    número -- todas deben llegar a 'UA1012965'."""
    s = (codigo or "").strip().upper().replace(" ", "").replace(":", "")
    if not s:
        return ""
    if s.startswith("UAPCKM") or s.startswith("UA"):
        return s
    return "UA" + s if s.isdigit() else s


def _checkwms_respaldo_erp(doc_ref: str, fecha_wms: str) -> dict:
    """Cruza un movimiento de CheckWMS contra el ERP Random (2026-08-03,
    Daniel: "identificar qué salió primero" -- detectar salidas de bodega
    sin documento de respaldo, o con documento declarado DESPUÉS de que
    el producto ya salió físicamente).

    `doc_ref` viene tal cual lo entrega CheckWMS, ej. "FCV-0000011155"
    (tido="FCV", nudo="0000011155") -- el propio WMS ya indica a qué
    documento del ERP corresponde el movimiento, no hace falta adivinar.
    SOLO LECTURA vía erp_engine.fetch_document (Regla #4.1). Nunca lanza:
    ante cualquier error del ERP, devuelve alerta=None (no bloquea la
    búsqueda de UA por esto)."""
    if not doc_ref or "-" not in doc_ref:
        return {"doc_ref": doc_ref, "encontrado": None, "alerta": None}
    tido, nudo = doc_ref.split("-", 1)
    tido, nudo = tido.strip(), nudo.strip()
    try:
        doc = erp_engine.get_client().fetch_document(tido, nudo)
    except Exception as _e:
        print(f"[checkwms_respaldo_erp] error ERP doc {doc_ref}: {_e}", flush=True)
        return {"doc_ref": doc_ref, "encontrado": None, "alerta": None}

    if not doc:
        return {"doc_ref": doc_ref, "encontrado": False,
                "alerta": f"El movimiento referencia el documento {doc_ref}, pero NO existe en el ERP Random."}

    fecha_erp = str(doc.get("fecha") or "")[:10]
    alerta = None
    if fecha_erp and fecha_wms:
        try:
            f_erp = datetime.strptime(fecha_erp, "%Y-%m-%d").date()
            f_wms = datetime.fromisoformat(fecha_wms[:19]).date()
            if f_wms < f_erp:
                alerta = (f"Salió de bodega el {f_wms.strftime('%d/%m/%Y')} pero el documento "
                          f"{doc_ref} en Random es del {f_erp.strftime('%d/%m/%Y')} -- "
                          "salió antes de estar declarado.")
        except (TypeError, ValueError):
            pass
    return {
        "doc_ref": doc_ref, "encontrado": True, "fecha_erp": fecha_erp,
        "cliente_erp": doc.get("cliente_nombre"), "alerta": alerta,
    }


def _inc_presencia_erp(sku: str) -> dict:
    """¿Existe este SKU en el ERP Random, y tiene stock en bodega 13?

    Daniel (2026-08-03): "el que manda es el ERP... necesito saber si falta
    en alguno de los sistemas". Solo lectura (Regla #4.1). Nunca lanza:
    si el ERP no responde devuelve existe=None (desconocido, no "falta")."""
    sku = (sku or "").strip()
    if not sku:
        return {"existe": None, "stock_b13": None}
    try:
        row = _random_sql_one(
            "SELECT TOP 1 LTRIM(RTRIM(pr.KOPR)) AS sku, "
            "  (SELECT SUM(st.STFI1) FROM MAEST st "
            "     WHERE LTRIM(RTRIM(st.KOPR))=LTRIM(RTRIM(pr.KOPR)) "
            "       AND LTRIM(RTRIM(st.KOBO))=%s) AS stock_b13 "
            "  FROM MAEPR pr WHERE LTRIM(RTRIM(pr.KOPR))=%s",
            (INC_BODEGA_ERP, sku))
    except Exception as _e:
        print(f"[_inc_presencia_erp] ERP no disponible: {_e}", flush=True)
        return {"existe": None, "stock_b13": None}
    if not row:
        return {"existe": False, "stock_b13": None}
    try:
        st = float(row.get("stock_b13")) if row.get("stock_b13") is not None else None
    except (TypeError, ValueError):
        st = None
    return {"existe": True, "stock_b13": st}


def _inc_clasificacion_sku(sku: str) -> dict:
    """Clasificación de un SKU REUSANDO las tablas del Catálogo (Daniel
    2026-08-03: "nosotros tenemos la clasificación de productos... las
    tablas se deben reusar"). NO se crea taxonomía nueva.

    cat_productos.clase_producto -> cat_clases_producto.slug, y de ahí
    `modelo_precio`, que es exactamente la distinción que Daniel necesita:

      · 'horas' -> EQUIPO (rack, banco, selector de pesos, bici, trotadora):
        la incidencia NO debería repetirse en el mismo SKU salvo que sean
        dos fallas distintas.
      · 'fijo'  -> REPETIBLE (piso, accesorio): cantidad × precio; el mismo
        defecto en 500 unidades es normal y NO es una duplicación.

    Sin clasificar -> repetible=None (la UI no afirma nada y pide
    clasificar el producto en el Catálogo)."""
    sku = (sku or "").strip()
    if not sku:
        return {"clase": None, "clase_nombre": None, "repetible": None}
    try:
        row = mysql_fetchone(
            "SELECT p.clase_producto AS slug, c.nombre, c.modelo_precio "
            "  FROM cat_productos p "
            "  LEFT JOIN cat_clases_producto c ON c.slug = p.clase_producto "
            " WHERE p.sku = %s LIMIT 1", (sku,))
    except Exception as _e:
        print(f"[_inc_clasificacion_sku] {_e}", flush=True)
        return {"clase": None, "clase_nombre": None, "repetible": None}
    if not row or not row.get("slug"):
        return {"clase": None, "clase_nombre": None, "repetible": None}
    modelo = (row.get("modelo_precio") or "").strip().lower()
    return {
        "clase": row.get("slug"),
        "clase_nombre": row.get("nombre") or row.get("slug"),
        "repetible": (modelo == "fijo") if modelo else None,
    }


def _inc_clasificacion_skus_batch(skus) -> dict:
    """Versión BATCH de _inc_clasificacion_sku(): una sola consulta con
    IN(...) en vez de 1 query por SKU. Se usa en pantallas que listan
    MUCHOS equipos a la vez (ej. la tabla de Equipos de la ficha del
    cliente, para decidir por fila si se ofrece "Imprimir etiqueta" —
    Daniel 2026-08-30: "el número de serie deberá ser impreso y generar
    etiquetas, siempre excluyendo los pisos y los accesorios").

    Mismo puente y misma regla que la función singular (NO se duplica
    lógica de negocio, solo se agrupa la consulta): modelo_precio='fijo'
    -> repetible=True (piso/accesorio); sin clasificar -> repetible=None.

    Devuelve {sku: {"clase":..., "clase_nombre":..., "repetible":...}}.
    Los SKU sin clasificación NO aparecen en el dict (mismo criterio que
    usa el caller: `.get(sku, {}).get("repetible")` da None = sin dato).
    """
    skus_norm = sorted({(s or "").strip() for s in (skus or []) if (s or "").strip()})
    if not skus_norm:
        return {}
    try:
        ph = ",".join(["%s"] * len(skus_norm))
        rows = mysql_fetchall(
            f"SELECT p.sku AS sku, p.clase_producto AS slug, c.nombre, c.modelo_precio "
            f"  FROM cat_productos p "
            f"  LEFT JOIN cat_clases_producto c ON c.slug = p.clase_producto "
            f" WHERE p.sku IN ({ph})",
            tuple(skus_norm)
        ) or []
    except Exception as _e:
        print(f"[_inc_clasificacion_skus_batch] {_e}", flush=True)
        return {}
    out = {}
    for row in rows:
        sku = (row.get("sku") or "").strip()
        if not sku or not row.get("slug"):
            continue
        modelo = (row.get("modelo_precio") or "").strip().lower()
        out[sku] = {
            "clase": row.get("slug"),
            "clase_nombre": row.get("nombre") or row.get("slug"),
            "repetible": (modelo == "fijo") if modelo else None,
        }
    return out


@app.route("/mantenciones/api/incidencias/buscar-ua", methods=["GET"])
@_mant_required
@_no_tecnico
def mant_api_incidencias_buscar_ua():
    """Autocompleta SKU/descripción del modal de Incidencias buscando el
    código UA en CheckWMS (2026-08-03, Daniel: integración real vía API),
    y cruza el documento contra el ERP Random para detectar salidas de
    bodega sin respaldo o declaradas tarde."""
    codigo = _checkwms_norm_ua(request.args.get("codigo") or "")
    if not codigo:
        return jsonify({"ok": False, "error": "Falta el código UA."}), 400

    def _ua(r):
        return (r.get("ua") or "").strip().upper()

    # 1) STOCK ACTUAL (GetReporteStock) -- fuente principal: es lo que
    #    muestra la pantalla "Reporte Stock" del WMS y cubre TODA la
    #    existencia, no solo movimientos recientes.
    stock_todas = _checkwms_stock_rows() or []
    stock_rows = [r for r in stock_todas if _ua(r) == codigo]

    # 2) MOVIMIENTOS (GetStockTrazabilidad) -- complementario: de dónde
    #    vino, con qué OT/documento. Solo desde jun-2026.
    traza_todas = _checkwms_trazabilidad_rows() or []
    traza_rows = [r for r in traza_todas if _ua(r) == codigo]

    if not stock_rows and not traza_rows:
        if not stock_todas and not traza_todas:
            return jsonify({"ok": False,
                            "error": "CheckWMS no respondió. Reintenta en un minuto."}), 502
        return jsonify({"ok": True, "found": False,
                        "codigo_normalizado": codigo,
                        "total_uas": len({_ua(r) for r in stock_todas} | {_ua(r) for r in traza_todas})})

    base = stock_rows[0] if stock_rows else traza_rows[0]
    mov = traza_rows[0] if traza_rows else {}
    fecha_wms = mov.get("fechaFin") or mov.get("feInicioOT")
    respaldo = _checkwms_respaldo_erp(mov.get("doc") or "", fecha_wms) if mov else None

    # Una UA puede agrupar VARIOS SKU distintos (un pallet, una OT con
    # varias líneas). Daniel: "si la UA >1 deberán desglosar en las UA
    # necesarias" -- se devuelve el desglose para que la UI avise.
    skus, vistos = [], set()
    for x in (stock_rows or traza_rows):
        k = (x.get("codigo") or "").strip()
        if k and k not in vistos:
            vistos.add(k)
            skus.append({"sku": k, "descripcion": x.get("descripcion"),
                         "sol": x.get("stFisico") if stock_rows else x.get("sol"),
                         "ejec": x.get("disponible") if stock_rows else x.get("ejec")})

    # Clasificación + chequeo de duplicado (Daniel 2026-08-03: un equipo no
    # debería repetir incidencia; un piso/accesorio sí). Reusa el Catálogo.
    sku_base = (base.get("codigo") or "").strip()
    clasif = _inc_clasificacion_sku(sku_base)
    duplicado = None
    if sku_base and clasif.get("repetible") is False:
        excluir = request.args.get("excluir_id")
        try:
            excluir = int(excluir) if excluir else None
        except (TypeError, ValueError):
            excluir = None
        try:
            previas = mysql_fetchall(
                "SELECT id, motivo, estado, created_at FROM mant_incidencias "
                " WHERE sku=%s AND (%s IS NULL OR id<>%s) "
                " ORDER BY created_at DESC LIMIT 5",
                (sku_base, excluir, excluir)) or []
        except Exception as _e:
            print(f"[buscar-ua duplicado] {_e}", flush=True)
            previas = []
        if previas:
            duplicado = {
                "n": len(previas),
                "previas": [{"id": p["id"], "motivo": p.get("motivo"),
                             "estado": p.get("estado")} for p in previas],
            }

    return jsonify({
        "ok": True, "found": True,
        "sku": base.get("codigo"), "descripcion": base.get("descripcion"),
        "bodega": base.get("bodega"), "ubicacion": base.get("ubicacion"),
        "familia": base.get("familia"),
        "stock_fisico": base.get("stFisico"), "disponible": base.get("disponible"),
        "en_stock": bool(stock_rows),
        "ot": mov.get("ot"), "estado": mov.get("estado"),
        "cliente": mov.get("entidad"), "fecha": fecha_wms,
        "tipo_ot": mov.get("tipoOT"),
        "items_relacionados": len(stock_rows or traza_rows),
        "skus_en_ua": skus,
        "respaldo_erp": respaldo,
        "clasificacion": clasif,
        # Presencia en AMBOS sistemas (Daniel 2026-08-03: "verificar si está
        # en ambos sistemas o al menos en uno... y que se acompañe todo el
        # rato de si falta en uno de los sistemas").
        "presencia": {
            "wms": bool(stock_rows),
            "wms_bodega": base.get("bodega"),
            "erp": _inc_presencia_erp(sku_base),
        },
        "duplicado": duplicado,
    })


INC_BODEGA_WMS = "BODEGA 13"   # ver memoria checkwms_integracion_ua
INC_BODEGA_ERP = "13"          # MAEST.KOBO -- misma bodega en Random


@app.route("/mantenciones/api/incidencias/conciliacion", methods=["GET"])
@_mant_required
@_no_tecnico
def mant_api_incidencias_conciliacion():
    """Conciliación Bodega 13 ↔ Incidencias ↔ ERP Random.

    Reproduce lo que hacían las macros VBA que Daniel usaba en Excel
    (`Cargar_ListView1_FaltantesEnMySQL` y `Cargar_ListView2_
    ComparacionAvanzada`), pero contra las fuentes vivas:

      1. En Bodega 13 del WMS y SIN incidencia registrada  -> "falta registrar"
      2. Incidencia cuya UA ya no está en Bodega 13        -> "salió de bodega"
      3. Incidencia cuyo SKU no existe en el ERP           -> "no existe en ERP"
      4. Diferencia de cantidad por SKU (WMS vs suma incidencias)

    Daniel (2026-08-03): "el que manda es el ERP, entonces necesito saber
    si falta en alguno de los sistemas" -- por eso cada hallazgo dice
    exactamente EN QUÉ sistema está y en cuál no. Nunca bloquea: si una
    fuente no responde, se informa y se concilia con las que sí."""
    # ── Fuente 1: stock actual del WMS, solo Bodega 13 ──
    stock = _checkwms_stock_rows() or []
    wms_b13 = [r for r in stock
               if (r.get("bodega") or "").strip().upper() == INC_BODEGA_WMS]
    wms_ok = bool(stock)

    wms_por_ua, wms_por_sku = {}, {}
    for r in wms_b13:
        ua = (r.get("ua") or "").strip().upper()
        sku = (r.get("codigo") or "").strip()
        if ua:
            wms_por_ua[ua] = r
        if sku:
            try:
                q = float(r.get("stFisico") or 0)
            except (TypeError, ValueError):
                q = 0
            e = wms_por_sku.setdefault(sku, {"cant": 0, "desc": r.get("descripcion"), "uas": []})
            e["cant"] += q
            if ua:
                e["uas"].append(ua)

    # ── Fuente 2: incidencias registradas ──
    try:
        incs = mysql_fetchall(
            "SELECT id, sku, descripcion, cantidad, motivo, estado, recomendacion "
            "  FROM mant_incidencias WHERE estado='abierta'") or []
    except Exception as _e:
        print(f"[conciliacion] error MySQL: {_e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo leer las incidencias."}), 500

    inc_por_ua, inc_por_sku = {}, {}
    for i in incs:
        ua = _checkwms_norm_ua(i.get("recomendacion") or "")
        if ua:
            inc_por_ua.setdefault(ua, []).append(i)
        sku = (i.get("sku") or "").strip()
        if sku:
            e = inc_por_sku.setdefault(sku, {"cant": 0, "ids": []})
            e["cant"] += int(i.get("cantidad") or 0)
            e["ids"].append(i["id"])

    # ── Fuente 3: ERP Random, MAEST bodega 13 (solo lectura, Regla #4.1) ──
    erp_por_sku, erp_ok = {}, False
    try:
        filas = _random_sql_query(
            "SELECT LTRIM(RTRIM(KOPR)) AS sku, SUM(STFI1) AS cant "
            "  FROM MAEST WHERE LTRIM(RTRIM(KOBO))=%s GROUP BY LTRIM(RTRIM(KOPR))",
            (INC_BODEGA_ERP,), max_rows=5000) or []
        for f in filas:
            try:
                erp_por_sku[(f.get("sku") or "").strip()] = float(f.get("cant") or 0)
            except (TypeError, ValueError):
                pass
        erp_ok = True
    except Exception as _e:
        print(f"[conciliacion] ERP no disponible: {_e}", flush=True)

    # ══ Hallazgos, en el ORDEN DE PRIORIDAD que pidió Daniel (2026-08-03):
    #    "prioridad a comparar nuestra BD es contra el ERP y luego el WMS,
    #     y después alertar si no hay motivos".
    #    CheckWMS y Random son bases DISTINTAS: cada diferencia se reporta
    #    por separado para poder gestionarla contra la fuente correcta.
    hallazgos = []

    # Los SKU que empiezan con ZZ son SERVICIOS (ZZENVIO, ZZRETIRO,
    # ZZINSTALACION, ZZTRASLADO...), no productos físicos: en el ERP
    # arrastran saldos negativos por su naturaleza contable y nunca están
    # en una bodega. Compararlos como stock genera puro ruido -- mismo
    # criterio que ya rige en Transporte ("los servicios no mueven, los
    # productos sí"). Verificado en producción 2026-08-04: 4 de los 45
    # hallazgos eran exactamente esto.
    def _es_servicio(sku):
        return (sku or "").strip().upper().startswith("ZZ")

    skus_todos = {s for s in (set(inc_por_sku) | set(erp_por_sku) | set(wms_por_sku))
                  if not _es_servicio(s)}

    # ── P1) NUESTRA BD vs ERP RANDOM (el ERP manda) ──
    if erp_ok:
        for sku in sorted(skus_todos):
            reg = inc_por_sku.get(sku, {}).get("cant", 0)
            erp = erp_por_sku.get(sku)
            if erp is None:
                if reg:   # lo tenemos declarado y el ERP no lo conoce
                    hallazgos.append({
                        "tipo": "no_en_erp", "gravedad": "error", "orden": 1,
                        "sku": sku,
                        "descripcion": (wms_por_sku.get(sku) or {}).get("desc"),
                        "ids": inc_por_sku.get(sku, {}).get("ids", []),
                        "nuestra_bd": reg, "erp": None,
                        "detalle": (f"Tenemos {reg:g} unidad(es) declarada(s), pero el SKU "
                                    f"no tiene stock en la bodega {INC_BODEGA_ERP} del ERP Random."),
                    })
                continue
            if abs(erp - reg) > 0.001:
                hallazgos.append({
                    "tipo": "dif_erp", "gravedad": "error", "orden": 0,
                    "sku": sku,
                    "descripcion": (wms_por_sku.get(sku) or {}).get("desc"),
                    "nuestra_bd": reg, "erp": erp, "wms": (wms_por_sku.get(sku) or {}).get("cant"),
                    "delta": reg - erp,
                    "ids": inc_por_sku.get(sku, {}).get("ids", []),
                    "detalle": (f"ERP Random dice {erp:g} y nosotros tenemos {reg:g} "
                                f"declarada(s). Diferencia de {abs(reg - erp):g}."),
                })

    # ── P2) NUESTRA BD vs CheckWMS (otra base) ──
    if wms_ok:
        for sku in sorted(skus_todos):
            reg = inc_por_sku.get(sku, {}).get("cant", 0)
            w = wms_por_sku.get(sku)
            if w is None:
                continue
            if abs(w["cant"] - reg) > 0.001:
                hallazgos.append({
                    "tipo": "dif_wms", "gravedad": "warn", "orden": 2,
                    "sku": sku, "descripcion": w["desc"],
                    "nuestra_bd": reg, "wms": w["cant"],
                    "erp": erp_por_sku.get(sku) if erp_ok else None,
                    "delta": reg - w["cant"],
                    "ids": inc_por_sku.get(sku, {}).get("ids", []),
                    "detalle": (f"CheckWMS (Bodega {INC_BODEGA_WMS.split()[-1]}) dice {w['cant']:g} "
                                f"y nosotros tenemos {reg:g} declarada(s)."),
                })

    # ── P3) SIN MOTIVO — lo esencial para poder gestionar ──
    for i in incs:
        if _es_servicio(i.get("sku")):
            continue   # los ZZ son servicios: no llevan motivo de falla
        if len((i.get("motivo") or "").strip()) < 10:
            hallazgos.append({
                "tipo": "sin_motivo", "gravedad": "warn", "orden": 3,
                "sku": i.get("sku"), "descripcion": i.get("descripcion"),
                "ua": _checkwms_norm_ua(i.get("recomendacion") or "") or None,
                "ids": [i["id"]],
                "detalle": ("Sin motivo declarado — no se puede gestionar sin saber qué pasó."
                            if not (i.get("motivo") or "").strip()
                            else "El motivo es demasiado breve para entender la falla."),
            })

    # ── P4) En bodega pero sin incidencia registrada ──
    if wms_ok:
        for ua, r in wms_por_ua.items():
            if ua not in inc_por_ua:
                hallazgos.append({
                    "tipo": "falta_registrar", "gravedad": "warn", "orden": 4,
                    "ua": ua, "sku": r.get("codigo"), "descripcion": r.get("descripcion"),
                    "ubicacion": r.get("ubicacion"),
                    "detalle": f"Está en {INC_BODEGA_WMS} del WMS pero no tiene incidencia registrada.",
                })

    # ── P5) UA que ya salió de la bodega de incidencias ──
    if wms_ok:
        for ua, lista in inc_por_ua.items():
            if ua not in wms_por_ua:
                otra = next((s for s in stock if (s.get("ua") or "").strip().upper() == ua), None)
                hallazgos.append({
                    "tipo": "fuera_de_bodega", "gravedad": "info", "orden": 5,
                    "ua": ua, "sku": lista[0].get("sku"),
                    "descripcion": lista[0].get("descripcion"),
                    "ids": [x["id"] for x in lista],
                    "detalle": (f"Ya no está en {INC_BODEGA_WMS} — ahora aparece en "
                                f"{otra.get('bodega')} ({otra.get('ubicacion')}). ¿Se resolvió?"
                                if otra else
                                "No aparece en el stock actual del WMS en ninguna bodega."),
                })

    hallazgos.sort(key=lambda h: (h.get("orden", 9), -abs(h.get("delta") or 0), h.get("sku") or ""))

    return jsonify({
        "ok": True,
        "fuentes": {
            "wms": {"ok": wms_ok, "uas": len(wms_por_ua), "bodega": INC_BODEGA_WMS},
            "erp": {"ok": erp_ok, "skus": len(erp_por_sku), "bodega": INC_BODEGA_ERP},
            "incidencias": {"ok": True, "abiertas": len(incs)},
        },
        "total": len(hallazgos),
        "resumen": {
            "dif_erp":        sum(1 for h in hallazgos if h["tipo"] == "dif_erp"),
            "no_en_erp":      sum(1 for h in hallazgos if h["tipo"] == "no_en_erp"),
            "dif_wms":        sum(1 for h in hallazgos if h["tipo"] == "dif_wms"),
            "sin_motivo":     sum(1 for h in hallazgos if h["tipo"] == "sin_motivo"),
            "falta_registrar": sum(1 for h in hallazgos if h["tipo"] == "falta_registrar"),
            "fuera_de_bodega": sum(1 for h in hallazgos if h["tipo"] == "fuera_de_bodega"),
        },
        "hallazgos": hallazgos[:300],
    })


