# DRILL-DOWN POR DÍA — Calendario con métricas
#
# Modal "click en un día" del calendario para ver el detalle completo:
#  - Lista de visitas del día
#  - Duración planificada vs real
#  - Heatmap por técnico
#  - Resumen: total, completadas, overrun promedio
# ══════════════════════════════════════════════════════════════════════

def _mant_calendario_role_where():
    """Filtro por rol compartido entre TODOS los endpoints de calendario que
    listan `mant_visitas` (día / mes / futuros). Extraído 2026-07-15 desde
    `mant_calendario_dia_drill` (Regla #5 — una sola fuente de verdad, no
    duplicar el filtro de seguridad al agregar el endpoint de mes) — el
    comentario original de seguridad se conserva íntegro más abajo.

    🔐 SEGURIDAD 2026-05-22 (Aaron Urbina — brecha calendario-listado):
    Aplicar filtro por rol coherente con `mant_ots_list` y
    `mant_visitas_api`. Si el rol no puede ver la OT en el listado,
    tampoco debe verla como visita del día/mes.

    Devuelve (extra_where_sql, extra_params) — extra_where_sql arranca con
    " AND (...)" o " AND 1=0 " o "" (admin/superadmin/supervisor sin filtro).
    """
    _u = getattr(g, "user", None) or {}
    _role_raw = (_u.get("role") or "").lower()
    _role_fam = _rol_familia(_role_raw)
    _uid = _u.get("id")
    _extra_where = ""
    _extra_params = []
    if _role_fam in ("admin", "superadmin", "supervisor"):
        pass
    elif _role_fam == "ejecutivo":
        username_actual = (_u.get("username") or "").strip()
        nombre_actual = (_u.get("nombre") or "").strip()
        _has_cbu = False
        try:
            _col_check = mysql_fetchone(
                "SELECT COUNT(*) AS n FROM INFORMATION_SCHEMA.COLUMNS "
                " WHERE TABLE_SCHEMA = DATABASE() "
                "   AND TABLE_NAME = 'mant_visitas' "
                "   AND COLUMN_NAME = 'created_by_user_id'"
            )
            _has_cbu = bool((_col_check or {}).get("n"))
        except Exception:
            _has_cbu = False
        clauses = []
        if _has_cbu and _uid:
            clauses.append("v.created_by_user_id=%s")
            _extra_params.append(int(_uid))
        if username_actual:
            clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            _extra_params.append(username_actual)
        if nombre_actual and nombre_actual.lower() != username_actual.lower():
            clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            _extra_params.append(nombre_actual)
        if _uid:
            clauses.append("v.tecnico_user_id=%s")
            _extra_params.append(int(_uid))
            clauses.append(
                "v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
                "         WHERE tecnico_user_id=%s)"
            )
            _extra_params.append(int(_uid))
        if clauses:
            _extra_where = " AND (" + " OR ".join(clauses) + ") "
        else:
            _extra_where = " AND 1=0 "
    elif _role_fam == "tecnico":
        if _uid:
            _extra_where = (
                " AND (v.tecnico_user_id=%s OR EXISTS("
                "  SELECT 1 FROM mant_visita_tecnicos vt "
                "   WHERE vt.visita_id=v.id AND vt.tecnico_user_id=%s)) "
            )
            _extra_params.extend([int(_uid), int(_uid)])
        else:
            _extra_where = " AND 1=0 "
    else:
        _extra_where = " AND 1=0 "
    return _extra_where, _extra_params


@app.route("/mantenciones/api/calendario/dia/<string:fecha>", methods=["GET"])
@_mant_required
def mant_calendario_dia_drill(fecha):
    """Devuelve el detalle de un día específico (todas las visitas + métricas).

    Path param: fecha en formato YYYY-MM-DD
    """
    import re as _re
    if not _re.match(r"^\d{4}-\d{2}-\d{2}$", fecha):
        return jsonify({"ok": False, "error": "Formato fecha inválido (use YYYY-MM-DD)"}), 400

    try:
        _extra_where, _extra_params = _mant_calendario_role_where()

        # Visitas del día con sus técnicos.
        # 2026-06-09 (Daniel — tablero interactivo): el técnico mostrado debe
        # reflejar la asignación REAL (`v.tecnico_user_id` → app_users, fuente
        # de verdad nueva), con fallback a la tabla legacy `mant_tecnicos`. Así,
        # al reasignar desde el tablero, el nuevo técnico aparece de inmediato.
        visitas = mysql_fetchall(
            "SELECT v.id, v.numero_ot, v.cliente_id, v.titulo, v.tipo, v.estado, "
            "       v.fecha_programada, v.hora_inicio, v.hora_fin, "
            "       v.hora_real_inicio, v.hora_real_fin, "
            "       v.duracion_planificada_min, v.duracion_real_min, "
            "       v.pausada_total_min, v.costo, v.costo_real, "
            "       v.satisfaccion_estrellas, v.tecnico_user_id, "
            "       c.razon_social AS cliente_nombre, c.comuna, "
            "       COALESCE(t.id, v.tecnico_user_id) AS tecnico_id, "
            "       COALESCE(au.nombre, au.username, t.nombre) AS tecnico_nombre, "
            "       (SELECT COUNT(*) FROM mant_visita_tareas WHERE visita_id=v.id) AS n_tareas, "
            "       (SELECT COUNT(*) FROM mant_visita_tareas WHERE visita_id=v.id AND completada=1) AS n_completas "
            "  FROM mant_visitas v "
            "  JOIN mant_clientes c ON c.id=v.cliente_id "
            "  LEFT JOIN mant_tecnicos t ON t.id=v.tecnico_id "
            "  LEFT JOIN app_users au ON au.id=v.tecnico_user_id "
            f" WHERE v.fecha_programada=%s {_extra_where} "
            " ORDER BY v.hora_inicio, v.id",
            (fecha, *_extra_params)
        ) or []
        visitas = [dict(v) for v in visitas]

        # Calcular delta y overrun por visita
        for v in visitas:
            plan = v.get("duracion_planificada_min")
            real = v.get("duracion_real_min")
            if plan is None and v.get("hora_inicio") and v.get("hora_fin"):
                # Calcular plan desde hora_inicio/hora_fin si no está
                try:
                    from datetime import timedelta as _td
                    hi = v["hora_inicio"]
                    hf = v["hora_fin"]
                    # MySQL puede devolver como timedelta
                    if isinstance(hi, _td) and isinstance(hf, _td):
                        plan = int((hf - hi).total_seconds() // 60)
                        v["duracion_planificada_min"] = plan
                except Exception: pass
            if plan and real:
                v["delta_min"] = real - plan
                v["overrun_pct"] = round((real - plan) * 100.0 / plan, 1)
            else:
                v["delta_min"] = None
                v["overrun_pct"] = None

        # 🔧 FIX 2026-06-09 (Daniel — bug "Object of type timedelta is not JSON
        # serializable" al abrir un día con 2+ visitas): las columnas TIME de
        # MySQL (hora_inicio/hora_fin) llegan como `timedelta` de PyMySQL y
        # `jsonify` NO las sabe serializar → el endpoint reventaba con 500 y el
        # modal mostraba "No se pudo cargar". Convertimos a 'HH:MM' string AQUÍ
        # (después del cálculo de plan, que sí necesita el timedelta crudo).
        # hora_real_inicio/fin son DATETIME → Flask las serializa solo.
        for v in visitas:
            for _campo in ("hora_inicio", "hora_fin"):
                _val = v.get(_campo)
                if _val is None:
                    continue
                if hasattr(_val, "total_seconds"):   # timedelta (TIME de PyMySQL)
                    _tot = int(_val.total_seconds())
                    _h, _m = divmod(_tot // 60, 60)
                    v[_campo] = f"{int(_h):02d}:{int(_m):02d}"
                elif not isinstance(_val, str):
                    v[_campo] = str(_val)[:5]

        # KPIs del día
        n_total = len(visitas)
        n_completadas = sum(1 for v in visitas if v.get("estado") == "completada")
        n_canceladas = sum(1 for v in visitas if v.get("estado") == "cancelada")
        n_en_curso = sum(1 for v in visitas if v.get("estado") in ("en_curso","programada") and v.get("hora_real_inicio"))
        n_pendientes = n_total - n_completadas - n_canceladas - n_en_curso

        # Duración total planificada vs real
        dur_plan_total = sum(v.get("duracion_planificada_min") or 0 for v in visitas)
        dur_real_total = sum(v.get("duracion_real_min") or 0 for v in visitas if v.get("duracion_real_min"))
        overrun_global = None
        if dur_plan_total > 0 and dur_real_total > 0:
            overrun_global = round((dur_real_total - dur_plan_total) * 100.0 / dur_plan_total, 1)

        # Agrupar por técnico (para heatmap)
        tecnicos_dia = {}
        for v in visitas:
            tid = v.get("tecnico_id")
            tname = v.get("tecnico_nombre") or "Sin asignar"
            if tid not in tecnicos_dia:
                tecnicos_dia[tid] = {
                    "id": tid, "nombre": tname,
                    "visitas": [], "n_visitas": 0,
                    "dur_plan_min": 0, "dur_real_min": 0,
                }
            tecnicos_dia[tid]["visitas"].append({
                "id": v["id"], "numero_ot": v.get("numero_ot"),
                "hora_inicio": str(v.get("hora_inicio") or ""),
                "hora_fin": str(v.get("hora_fin") or ""),
                "estado": v.get("estado"),
                "overrun_pct": v.get("overrun_pct"),
            })
            tecnicos_dia[tid]["n_visitas"] += 1
            tecnicos_dia[tid]["dur_plan_min"] += v.get("duracion_planificada_min") or 0
            tecnicos_dia[tid]["dur_real_min"] += v.get("duracion_real_min") or 0

        # PLANIFICADOR 2026-06-10: avisar si el día es feriado (banner tablero).
        _feriado_nombre = None
        try:
            from cl_feriados import feriados_chile
            _feriado_nombre = feriados_chile(int(fecha[:4])).get(fecha)
        except Exception:
            pass
        return jsonify({
            "ok": True,
            "fecha": fecha,
            "feriado": _feriado_nombre,
            "visitas": visitas,
            "kpis": {
                "total": n_total,
                "completadas": n_completadas,
                "canceladas": n_canceladas,
                "en_curso": n_en_curso,
                "pendientes": n_pendientes,
                "dur_plan_min_total": dur_plan_total,
                "dur_real_min_total": dur_real_total,
                "overrun_pct_global": overrun_global,
            },
            "tecnicos": list(tecnicos_dia.values()),
        })
    except Exception as e:
        return jsonify({"ok": False, "error": f"Error al consultar: {e}"}), 500


@app.route("/mantenciones/api/calendario/mes/<int:anio>/<int:mes>", methods=["GET"])
@_mant_required
def mant_calendario_mes(anio, mes):
    """Calendario MENSUAL para el mini-calendario del modal "Generar OT" de
    Tickets (Daniel 2026-07-15: "necesito saber que esta agendado en el mes,
    sin salir del modal"). Reusa la MISMA lógica de filtrado por rol que
    `mant_calendario_dia_drill` vía `_mant_calendario_role_where()`,
    extendida a un rango `fecha_programada BETWEEN primer..ultimo día del
    mes` — no duplica la query de seguridad (Regla #5).

    Path params: anio (int), mes (int, 1-12).

    Shape de respuesta — ver contrato completo en el reporte del agente.
    """
    import calendar as _calmod
    from datetime import date as _date
    if mes < 1 or mes > 12:
        return jsonify({"ok": False, "error": "Mes inválido (use 1-12)"}), 400
    if anio < 2000 or anio > 2100:
        return jsonify({"ok": False, "error": "Año inválido"}), 400
    try:
        _primer_dia = _date(anio, mes, 1)
        _ultimo_num = _calmod.monthrange(anio, mes)[1]
        _ultimo_dia = _date(anio, mes, _ultimo_num)

        _extra_where, _extra_params = _mant_calendario_role_where()

        # Misma query base de mant_calendario_dia_drill, extendida a rango de
        # mes + LEFT JOIN a tk_tickets (vínculo 1:1 vía tk_tickets.visita_id,
        # UNIQUE index uq_tk_tickets_visita — ver tickets_module.py
        # _ensure_tk_tickets_visita_link) para exponer el ticket relacionado.
        visitas = mysql_fetchall(
            "SELECT v.id, v.numero_ot, v.cliente_id, v.titulo, v.tipo, v.estado, "
            "       v.fecha_programada, v.fecha_fin, v.hora_inicio, v.hora_fin, v.tecnico_user_id, "
            "       c.razon_social AS cliente_nombre, c.comuna, "
            "       COALESCE(t.id, v.tecnico_user_id) AS tecnico_id, "
            "       COALESCE(au.nombre, au.username, t.nombre) AS tecnico_nombre, "
            "       tk.id AS ticket_id, tk.numero_ticket "
            # 2026-08-29 (Daniel: "el calendario de OT del modal y del
            # monitor deben ser el mismo"): el panel OT2.0 y el Monitor ya
            # usan LEFT JOIN a clientes (ven trabajo interno sin cliente).
            # Este era el unico calendario con JOIN interno -- una OT de
            # bodega (cliente_id NULL a proposito) desaparecia del mes,
            # aunque el detector de choque SI la veia (query separada, sin
            # este join) -- de ahi la incoherencia "el dia se ve libre pero
            # igual avisa choque".
            "  FROM mant_visitas v "
            "  LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
            "  LEFT JOIN mant_tecnicos t ON t.id=v.tecnico_id "
            "  LEFT JOIN app_users au ON au.id=v.tecnico_user_id "
            "  LEFT JOIN tk_tickets tk ON tk.visita_id=v.id "
            f" WHERE v.fecha_programada BETWEEN %s AND %s {_extra_where} "
            " ORDER BY v.fecha_programada, v.hora_inicio, v.id",
            (_primer_dia.isoformat(), _ultimo_dia.isoformat(), *_extra_params)
        ) or []
        visitas = [dict(v) for v in visitas]

        # Equipos por visita (Daniel 2026-08-12: "que se indique qué máquina"
        # en el popover de "misma franja" del calendario) -- 1 sola query
        # batch por TODOS los ids del mes, no una por visita (evita N+1).
        # mant_visita_tareas.maquina_id es la fuente universal de "qué equipo
        # toca esta OT" para cualquier tipo (no solo levantamiento) desde el
        # Paso 1 de "separar el levantamiento" (2026-08-12).
        equipos_por_visita = {}
        _ids = [v["id"] for v in visitas]
        if _ids:
            _ph = ",".join(["%s"] * len(_ids))
            _eq_rows = mysql_fetchall(
                f"SELECT DISTINCT t.visita_id, m.nombre "
                f"  FROM mant_visita_tareas t "
                f"  JOIN mant_maquinas m ON m.id = t.maquina_id "
                f" WHERE t.visita_id IN ({_ph}) ",
                tuple(_ids)
            ) or []
            for _r in _eq_rows:
                equipos_por_visita.setdefault(_r["visita_id"], []).append(_r["nombre"])

        # Serializar TIME->str y DATE->str (mismo fix 2026-06-09 que
        # mant_calendario_dia_drill: hora_inicio/hora_fin llegan como
        # timedelta de PyMySQL; fecha_programada es un date de PyMySQL, se
        # normaliza a 'YYYY-MM-DD' para usarla de key en el dict `dias`).
        for v in visitas:
            for _campo in ("hora_inicio", "hora_fin"):
                _val = v.get(_campo)
                if _val is None:
                    continue
                if hasattr(_val, "total_seconds"):   # timedelta (TIME de PyMySQL)
                    _tot = int(_val.total_seconds())
                    _h, _m = divmod(_tot // 60, 60)
                    v[_campo] = f"{int(_h):02d}:{int(_m):02d}"
                elif not isinstance(_val, str):
                    v[_campo] = str(_val)[:5]
            _fp = v.get("fecha_programada")
            v["fecha_programada"] = _fp.isoformat() if hasattr(_fp, "isoformat") else str(_fp)
            _ff = v.get("fecha_fin")
            if _ff is not None:
                v["fecha_fin"] = _ff.isoformat() if hasattr(_ff, "isoformat") else str(_ff)

        # Feriados del mes (1 sola llamada, no por-día como en el endpoint de día).
        try:
            from cl_feriados import feriados_chile as _feriados_chile
            _feriados_anio = _feriados_chile(anio) or {}
        except Exception:
            _feriados_anio = {}

        dias = {}
        for v in visitas:
            fecha_key = v["fecha_programada"]
            if fecha_key not in dias:
                dias[fecha_key] = {
                    "feriado": _feriados_anio.get(fecha_key),
                    "visitas": [],
                }
            dias[fecha_key]["visitas"].append({
                "visita_id": v["id"],
                "numero_ot": v.get("numero_ot"),
                "ticket_id": v.get("ticket_id"),
                "numero_ticket": v.get("numero_ticket"),
                "cliente_id": v.get("cliente_id"),
                "cliente_nombre": v.get("cliente_nombre"),
                "titulo": v.get("titulo"),
                "tipo": v.get("tipo"),
                "estado": v.get("estado"),
                "hora_inicio": v.get("hora_inicio"),
                "hora_fin": v.get("hora_fin"),
                "fecha_fin": v.get("fecha_fin"),
                "tecnico_id": v.get("tecnico_id"),
                "tecnico_nombre": v.get("tecnico_nombre"),
                "equipos": equipos_por_visita.get(v["id"], []),
            })
        for fk in dias:
            dias[fk]["n_visitas"] = len(dias[fk]["visitas"])

        n_canceladas = sum(1 for v in visitas if v.get("estado") == "cancelada")
        n_completadas = sum(1 for v in visitas if v.get("estado") == "completada")

        return jsonify({
            "ok": True,
            "anio": anio, "mes": mes,
            "dias": dias,
            "kpis": {
                "total_mes": len(visitas),
                "dias_con_ot": len(dias),
                "completadas": n_completadas,
                "canceladas": n_canceladas,
            },
        })
    except Exception as e:
        return jsonify({"ok": False, "error": f"Error al consultar calendario del mes: {e}"}), 500


@app.route("/mantenciones/api/calendario/choque", methods=["GET"])
@_mant_required
def mant_calendario_choque():
    """Detección de choque de horario para 1 o MÁS técnicos a la vez, dado
    un fecha/hora propuestos — construido para el modal "Generar OT" de
    Tickets (Daniel 2026-07-15: "poder ver quien esta agendado, con que OT,
    en caso de no chocar los calendarios"). Reusa `_validar_disponibilidad_visita`
    (línea ~38233, ya existente) por cada técnico solicitado — Regla #5, no
    se duplica la query de solapamiento.

    Query params (GET):
      tecnico_ids        CSV de IDs de técnico (app_users.id), ej. "7,9,12"
      tecnico_id         alternativa singular (equivalente a tecnico_ids=<id>)
      fecha               YYYY-MM-DD (obligatorio)
      fecha_fin            YYYY-MM-DD (opcional) — fin del rango si la OT
                           que se está creando/moviendo TAMBIÉN abarca
                           varios días (FIX 2026-07-15, choque multi-día).
                           Si se omite, se chequea un solo día (fecha),
                           igual que antes de que este parámetro existiera.
      hora_ini             HH:MM (opcional)
      hora_fin             HH:MM (opcional)
      exclude_visita_id   opcional, int — excluye esa visita del choque
                           (para reagendar una OT existente sin que choque
                           consigo misma)

    Shape de respuesta — NO cambia con fecha_fin (mismas claves de siempre,
    ver contrato completo en el reporte del agente) — fecha_fin solo afina
    la lógica interna de qué cuenta como choque.
    """
    import re as _re
    fecha = (request.args.get("fecha") or "").strip()
    if not _re.match(r"^\d{4}-\d{2}-\d{2}$", fecha):
        return jsonify({"ok": False, "error": "Formato fecha inválido (use YYYY-MM-DD)"}), 400

    fecha_fin_q = (request.args.get("fecha_fin") or "").strip() or None
    if fecha_fin_q and not _re.match(r"^\d{4}-\d{2}-\d{2}$", fecha_fin_q):
        return jsonify({"ok": False, "error": "Formato fecha_fin inválido (use YYYY-MM-DD)"}), 400

    hora_ini = (request.args.get("hora_ini") or "").strip() or None
    hora_fin = (request.args.get("hora_fin") or "").strip() or None

    ids_raw = (request.args.get("tecnico_ids") or "").strip()
    if not ids_raw:
        ids_raw = (request.args.get("tecnico_id") or "").strip()
    tecnico_ids = []
    for _p in ids_raw.split(","):
        _p = _p.strip()
        if _p.isdigit():
            tecnico_ids.append(int(_p))
    if not tecnico_ids:
        return jsonify({"ok": False, "error": "Falta tecnico_id o tecnico_ids"}), 400

    exclude_visita_id = None
    _exc_raw = (request.args.get("exclude_visita_id") or "").strip()
    if _exc_raw.isdigit():
        exclude_visita_id = int(_exc_raw)

    try:
        resultados = []
        _feriado = None
        hay_choque = False
        for tid in tecnico_ids:
            adv = _validar_disponibilidad_visita(
                tid, fecha, hora_ini, hora_fin, exclude_visita_id=exclude_visita_id,
                fecha_fin=fecha_fin_q)
            if _feriado is None and adv.get("feriado"):
                _feriado = adv["feriado"]
            choque = adv.get("choque")
            if choque:
                hay_choque = True
            resultados.append({
                "tecnico_id": tid,
                "tecnico_nombre": (choque or {}).get("tecnico_nombre"),
                "choque": bool(choque),
                "visitas_choque": (choque or {}).get("visitas", []),
            })

        # Completar el nombre del técnico cuando NO hubo choque (en ese caso
        # _validar_disponibilidad_visita no consulta app_users) — 1 SELECT
        # liviano, sin duplicar la query de solapamiento.
        _faltan_nombre = [r["tecnico_id"] for r in resultados if not r["tecnico_nombre"]]
        if _faltan_nombre:
            _rows = mysql_fetchall(
                "SELECT id, COALESCE(nombre, username) AS nm FROM app_users "
                f" WHERE id IN ({','.join(['%s'] * len(_faltan_nombre))})",
                tuple(_faltan_nombre)
            ) or []
            _nombres = {r["id"]: r["nm"] for r in _rows}
            for r in resultados:
                if not r["tecnico_nombre"]:
                    r["tecnico_nombre"] = _nombres.get(r["tecnico_id"])

        return jsonify({
            "ok": True,
            "fecha": fecha, "hora_inicio": hora_ini, "hora_fin": hora_fin,
            "feriado": _feriado,
            "hay_choque": hay_choque,
            "tecnicos": resultados,
        })
    except Exception as e:
        return jsonify({"ok": False, "error": f"Error al consultar choque: {e}"}), 500


# ══════════════════════════════════════════════════════════════════════
# CRONÓMETRO POR TAREA — start / pause / resume / complete
#
# Cada acción del usuario inserta una fila en mant_tarea_tiempo y
# actualiza el estado de la tarea (mant_visita_tareas.estado_trabajo).
# Cuando se completa la PRIMERA tarea o la ÚLTIMA, también se ajustan
# hora_real_inicio / hora_real_fin de la visita.
#
# Endpoints:
#   POST /mantenciones/api/tareas/<tid>/cronometro
#        body: {accion: iniciar|pausar|reanudar|completar, nota?, geo?}
#   GET  /mantenciones/api/tareas/<tid>/cronometro
#        → estado actual + eventos recientes
#   GET  /mantenciones/api/visitas/<vid>/cronometro-resumen
#        → tiempo agregado de toda la visita
# ══════════════════════════════════════════════════════════════════════

def _crono_seg_desde_ultimo(tarea_id):
    """Devuelve los segundos transcurridos desde el último 'iniciar' o
    'reanudar' (sin pausar/completar posterior). 0 si no hay segmento abierto.
    """
    row = mysql_fetchone(
        "SELECT `timestamp` FROM mant_tarea_tiempo "
        " WHERE tarea_id=%s AND accion IN ('iniciar','reanudar') "
        " ORDER BY id DESC LIMIT 1",
        (tarea_id,)
    )
    if not row or not row.get("timestamp"):
        return 0
    try:
        from datetime import datetime as _dt
        ts = row["timestamp"]
        if isinstance(ts, str):
            ts = _dt.fromisoformat(ts)
        return max(0, int((_dt.now() - ts).total_seconds()))
    except Exception:
        return 0


def _crono_total_seg(tarea_id):
    """Suma todos los segmentos cerrados (pausar/completar) de la tarea."""
    row = mysql_fetchone(
        "SELECT COALESCE(SUM(duracion_segmento_seg),0) AS total "
        "  FROM mant_tarea_tiempo "
        " WHERE tarea_id=%s AND duracion_segmento_seg IS NOT NULL",
        (tarea_id,)
    )
    return int((row or {}).get("total") or 0)


@app.route("/mantenciones/api/tareas/<int:tid>/cronometro", methods=["POST"])
@_mant_required
def mant_tarea_cronometro(tid):
    """Iniciar / pausar / reanudar / completar tarea.

    Body JSON: {accion: 'iniciar'|'pausar'|'reanudar'|'completar', nota?, geo?}
    """
    d = request.get_json(silent=True) or {}
    accion = (d.get("accion") or "").strip().lower()
    if accion not in ("iniciar", "pausar", "reanudar", "completar"):
        return jsonify({"ok": False, "error": "Acción inválida"}), 400

    nota = (d.get("nota") or "").strip()[:300] or None
    geo  = (d.get("geo")  or "").strip()[:50]  or None
    user = current_username()

    # Tarea actual
    tarea = mysql_fetchone(
        "SELECT t.id, t.visita_id, t.titulo, t.completada, t.estado_trabajo, "
        "       t.pausada_acumulado_seg, t.iniciado_at "
        "  FROM mant_visita_tareas t WHERE t.id=%s",
        (tid,)
    )
    if not tarea:
        return jsonify({"ok": False, "error": "Tarea no encontrada"}), 404
    tarea = dict(tarea)
    vid   = tarea["visita_id"]

    # 🔐 SEGURIDAD (2026-05-17): si es técnico/tecnico_externo, validar
    # ownership por la visita asociada a la tarea (endpoint usa <tid>, no <vid>).
    u_curr = getattr(g, "user", None) or {}
    role_curr = (u_curr.get("role") or "").lower()
    if role_curr in ("tecnico", "tecnico_externo"):
        uid_curr = u_curr.get("id")
        ok_owner = None
        if uid_curr:
            ok_owner = mysql_fetchone(
                "SELECT 1 AS x FROM mant_visitas "
                " WHERE id=%s AND tecnico_user_id=%s "
                "UNION ALL "
                "SELECT 1 FROM mant_visita_tecnicos "
                " WHERE visita_id=%s AND tecnico_user_id=%s "
                "LIMIT 1",
                (vid, uid_curr, vid, uid_curr)
            )
        if not ok_owner:
            print(
                f"[SECURITY] {uid_curr} ({u_curr.get('username')}) intento "
                f"cronometro tid={tid} (vid={vid}) sin asignacion (role={role_curr})",
                flush=True
            )
            return jsonify({"ok": False, "error": "No estás asignado a esta OT"}), 403

    estado_actual = tarea.get("estado_trabajo") or "pendiente"

    # Validaciones de transición
    if accion == "iniciar" and estado_actual not in ("pendiente", "pausada"):
        return jsonify({"ok": False, "error": f"No se puede iniciar (estado actual: {estado_actual})"}), 409
    if accion == "pausar" and estado_actual != "en_curso":
        return jsonify({"ok": False, "error": "Solo se puede pausar una tarea en curso"}), 409
    if accion == "reanudar" and estado_actual != "pausada":
        return jsonify({"ok": False, "error": "Solo se puede reanudar una tarea pausada"}), 409
    if accion == "completar" and estado_actual == "completada":
        return jsonify({"ok": False, "error": "La tarea ya está completada"}), 409

    # Tecnico (intentar deducir desde visita)
    tecnico_id = None
    try:
        trow = mysql_fetchone(
            "SELECT tecnico_id FROM mant_visita_tecnicos WHERE visita_id=%s LIMIT 1",
            (vid,)
        )
        if trow and trow.get("tecnico_id"):
            tecnico_id = int(trow["tecnico_id"])
        else:
            vrow = mysql_fetchone("SELECT tecnico_id FROM mant_visitas WHERE id=%s", (vid,))
            if vrow and vrow.get("tecnico_id"):
                tecnico_id = int(vrow["tecnico_id"])
    except Exception:
        pass

    # Calcular segundos del segmento actual cuando se cierra
    seg_segmento = None
    if accion in ("pausar", "completar"):
        seg_segmento = _crono_seg_desde_ultimo(tid)

    # Insertar evento
    mysql_execute(
        "INSERT INTO mant_tarea_tiempo (tarea_id, visita_id, tecnico_id, accion, "
        "                               duracion_segmento_seg, nota, geo, creado_por) "
        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
        (tid, vid, tecnico_id, accion, seg_segmento, nota, geo, user)
    )

    # Actualizar tarea según acción
    if accion == "iniciar":
        # Marcar iniciado_at sólo la primera vez
        if not tarea.get("iniciado_at"):
            mysql_execute(
                "UPDATE mant_visita_tareas SET estado_trabajo='en_curso', "
                "       iniciado_at=NOW() WHERE id=%s",
                (tid,)
            )
        else:
            mysql_execute(
                "UPDATE mant_visita_tareas SET estado_trabajo='en_curso' WHERE id=%s",
                (tid,)
            )
        # ¿Primera tarea de la visita en iniciarse?  → marcar hora_real_inicio
        try:
            otras_iniciadas = mysql_fetchone(
                "SELECT COUNT(*) AS n FROM mant_visita_tareas "
                " WHERE visita_id=%s AND iniciado_at IS NOT NULL AND id<>%s",
                (vid, tid)
            )
            visita_row = mysql_fetchone(
                "SELECT hora_real_inicio FROM mant_visitas WHERE id=%s", (vid,)
            )
            if (otras_iniciadas or {}).get("n", 0) == 0 and not (visita_row or {}).get("hora_real_inicio"):
                mysql_execute(
                    "UPDATE mant_visitas SET hora_real_inicio=NOW(), "
                    "       estado=CASE WHEN estado='programada' THEN 'en_curso' ELSE estado END "
                    " WHERE id=%s",
                    (vid,)
                )
        except Exception:
            pass

    elif accion == "pausar":
        mysql_execute(
            "UPDATE mant_visita_tareas "
            "   SET estado_trabajo='pausada', "
            "       pausada_acumulado_seg = COALESCE(pausada_acumulado_seg,0) + %s "
            " WHERE id=%s",
            (seg_segmento or 0, tid)
        )

    elif accion == "reanudar":
        mysql_execute(
            "UPDATE mant_visita_tareas SET estado_trabajo='en_curso' WHERE id=%s",
            (tid,)
        )

    elif accion == "completar":
        # Sumar duración total acumulada (segmentos cerrados) en minutos
        total_seg = _crono_total_seg(tid)
        # Sumar el segmento que recién cerramos (si la tarea estaba en_curso)
        if estado_actual == "en_curso" and seg_segmento:
            total_seg += seg_segmento
        duracion_min = max(1, round(total_seg / 60.0)) if total_seg else None
        mysql_execute(
            "UPDATE mant_visita_tareas "
            "   SET estado_trabajo='completada', "
            "       completada=1, "
            "       completada_at=NOW(), "
            "       completada_por=%s, "
            "       duracion_min=COALESCE(%s, duracion_min) "
            " WHERE id=%s",
            (user, duracion_min, tid)
        )

        # ¿Todas las tareas de la visita completadas? → cerrar visita
        try:
            stats = mysql_fetchone(
                "SELECT COUNT(*) AS total, "
                "       SUM(CASE WHEN completada=1 THEN 1 ELSE 0 END) AS completas "
                "  FROM mant_visita_tareas WHERE visita_id=%s",
                (vid,)
            ) or {}
            if stats.get("total") and stats.get("total") == stats.get("completas"):
                # Calcular duracion_real_min desde hora_real_inicio
                vis = mysql_fetchone(
                    "SELECT hora_real_inicio FROM mant_visitas WHERE id=%s", (vid,)
                )
                dur_real = None
                if vis and vis.get("hora_real_inicio"):
                    try:
                        from datetime import datetime as _dt
                        hi = vis["hora_real_inicio"]
                        if isinstance(hi, str):
                            hi = _dt.fromisoformat(hi)
                        dur_real = max(1, int((_dt.now() - hi).total_seconds() / 60))
                    except Exception:
                        pass
                mysql_execute(
                    "UPDATE mant_visitas "
                    "   SET hora_real_fin=NOW(), "
                    "       duracion_real_min=COALESCE(%s, duracion_real_min) "
                    " WHERE id=%s",
                    (dur_real, vid)
                )
        except Exception:
            pass

    # Log
    try:
        mysql_execute(
            "INSERT INTO mant_logs (entidad, entidad_id, accion, detalle, usuario) "
            "VALUES ('tarea', %s, %s, %s, %s)",
            (tid, f"cronometro_{accion}", tarea.get("titulo") or f"tid={tid}", user)
        )
    except Exception:
        pass

    # Estado actualizado para devolver al frontend
    tarea_upd = mysql_fetchone(
        "SELECT id, estado_trabajo, iniciado_at, completada, completada_at, "
        "       duracion_min, duracion_estimada_min, pausada_acumulado_seg "
        "  FROM mant_visita_tareas WHERE id=%s",
        (tid,)
    ) or {}
    return jsonify({
        "ok": True,
        "accion": accion,
        "tarea": {
            "id": tid,
            "estado_trabajo": (tarea_upd or {}).get("estado_trabajo"),
            "iniciado_at": str((tarea_upd or {}).get("iniciado_at") or "") or None,
            "completada": bool((tarea_upd or {}).get("completada")),
            "completada_at": str((tarea_upd or {}).get("completada_at") or "") or None,
            "duracion_min": (tarea_upd or {}).get("duracion_min"),
            "duracion_estimada_min": (tarea_upd or {}).get("duracion_estimada_min"),
            "pausada_acumulado_seg": (tarea_upd or {}).get("pausada_acumulado_seg"),
        },
        "duracion_segmento_seg": seg_segmento,
        "duracion_total_seg": _crono_total_seg(tid),
    })


@app.route("/mantenciones/api/tareas/<int:tid>/cronometro", methods=["GET"])
@_mant_required
def mant_tarea_cronometro_get(tid):
    """Devuelve estado actual del cronómetro + últimos 20 eventos."""
    tarea = mysql_fetchone(
        "SELECT id, visita_id, titulo, completada, estado_trabajo, "
        "       iniciado_at, completada_at, duracion_min, duracion_estimada_min, "
        "       pausada_acumulado_seg "
        "  FROM mant_visita_tareas WHERE id=%s",
        (tid,)
    )
    if not tarea:
        return jsonify({"ok": False, "error": "Tarea no encontrada"}), 404

    # 🔐 SEGURIDAD (2026-05-17): tarea pertenece a una visita — verificar
    # ownership si el actor es técnico/tecnico_externo (endpoint sin <vid>).
    vid_chk = dict(tarea).get("visita_id")
    u_curr = getattr(g, "user", None) or {}
    role_curr = (u_curr.get("role") or "").lower()
    if role_curr in ("tecnico", "tecnico_externo") and vid_chk:
        uid_curr = u_curr.get("id")
        ok_owner = None
        if uid_curr:
            ok_owner = mysql_fetchone(
                "SELECT 1 AS x FROM mant_visitas "
                " WHERE id=%s AND tecnico_user_id=%s "
                "UNION ALL "
                "SELECT 1 FROM mant_visita_tecnicos "
                " WHERE visita_id=%s AND tecnico_user_id=%s "
                "LIMIT 1",
                (vid_chk, uid_curr, vid_chk, uid_curr)
            )
        if not ok_owner:
            print(
                f"[SECURITY] {uid_curr} ({u_curr.get('username')}) intento "
                f"cronometro_get tid={tid} (vid={vid_chk}) sin asignacion",
                flush=True
            )
            return jsonify({"ok": False, "error": "No estás asignado a esta OT"}), 403

    eventos = mysql_fetchall(
        "SELECT id, accion, `timestamp`, duracion_segmento_seg, nota, creado_por "
        "  FROM mant_tarea_tiempo WHERE tarea_id=%s ORDER BY id DESC LIMIT 20",
        (tid,)
    ) or []
    seg_abierto = 0
    if (dict(tarea).get("estado_trabajo")) == "en_curso":
        seg_abierto = _crono_seg_desde_ultimo(tid)
    return jsonify({
        "ok": True,
        "tarea": {
            **dict(tarea),
            "iniciado_at": str(dict(tarea).get("iniciado_at") or "") or None,
            "completada_at": str(dict(tarea).get("completada_at") or "") or None,
        },
        "eventos": [
            {
                "id": e["id"], "accion": e["accion"],
                "timestamp": str(e.get("timestamp") or ""),
                "duracion_segmento_seg": e.get("duracion_segmento_seg"),
                "nota": e.get("nota"),
                "creado_por": e.get("creado_por"),
            } for e in eventos
        ],
        "duracion_total_seg": _crono_total_seg(tid),
        "segmento_abierto_seg": seg_abierto,
    })


@app.route("/mantenciones/api/visitas/<int:vid>/cronometro-resumen", methods=["GET"])
@_mant_required
@_ot_can_view
def mant_visita_cronometro_resumen(vid):
    """Resumen de tiempo de toda la visita (todas las tareas)."""
    visita = mysql_fetchone(
        "SELECT id, numero_ot, hora_real_inicio, hora_real_fin, "
        "       duracion_real_min, duracion_planificada_min, pausada_total_min "
        "  FROM mant_visitas WHERE id=%s",
        (vid,)
    )
    if not visita:
        return jsonify({"ok": False, "error": "Visita no encontrada"}), 404
    tareas = mysql_fetchall(
        "SELECT id, titulo, estado_trabajo, iniciado_at, completada_at, "
        "       duracion_min, duracion_estimada_min, pausada_acumulado_seg, "
        "       completada "
        "  FROM mant_visita_tareas WHERE visita_id=%s ORDER BY orden, id",
        (vid,)
    ) or []
    tareas = [dict(t) for t in tareas]
    # Sumar todas las duraciones reales
    real_total_min = 0
    estimado_total_min = 0
    for t in tareas:
        if t.get("duracion_min"):
            real_total_min += int(t["duracion_min"])
        elif t.get("estado_trabajo") == "en_curso":
            # Tiempo vivo: sumar todos los segmentos cerrados + segmento abierto
            real_total_min += round((_crono_total_seg(t["id"]) + _crono_seg_desde_ultimo(t["id"])) / 60.0)
        if t.get("duracion_estimada_min"):
            estimado_total_min += int(t["duracion_estimada_min"])

    return jsonify({
        "ok": True,
        "visita": {
            "id": visita["id"],
            "numero_ot": visita.get("numero_ot"),
            "hora_real_inicio": str(visita.get("hora_real_inicio") or "") or None,
            "hora_real_fin": str(visita.get("hora_real_fin") or "") or None,
            "duracion_real_min": visita.get("duracion_real_min"),
            "duracion_planificada_min": visita.get("duracion_planificada_min"),
        },
        "tareas_resumen": {
            "n_total": len(tareas),
            "n_completadas": sum(1 for t in tareas if t.get("completada")),
            "n_en_curso":    sum(1 for t in tareas if t.get("estado_trabajo") == "en_curso"),
            "n_pausadas":    sum(1 for t in tareas if t.get("estado_trabajo") == "pausada"),
            "real_min_total": real_total_min,
            "estimado_min_total": estimado_total_min,
        },
        "tareas": [
            {
                "id": t["id"], "titulo": t.get("titulo"),
                "estado_trabajo": t.get("estado_trabajo"),
                "duracion_min": t.get("duracion_min"),
                "duracion_estimada_min": t.get("duracion_estimada_min"),
                "completada": bool(t.get("completada")),
            } for t in tareas
        ],
    })


# ══════════════════════════════════════════════════════════════════════
# FLUJO DE OT: programada → en_curso → completada (con 3 firmas)
#
# Reglas:
#   - INICIAR (programada → en_curso): solo el técnico asignado
#     (visita.tecnico_user_id) o un admin/supervisor.
#   - FIRMAR: 3 firmas obligatorias para cerrar.
#       firma_cliente   → cualquier usuario puede capturar (el cliente firma
#                         en el dispositivo del técnico).
#       firma_tecnico   → solo el usuario cuyo id == visita.tecnico_user_id.
#       firma_supervisor→ solo el usuario cuyo id == visita.created_by_id
#                         (quien asignó la OT) o un admin/superadmin.
#   - CERRAR: requiere las 3 firmas presentes. Si falta alguna → 400.
# ══════════════════════════════════════════════════════════════════════

def _ot_es_admin_o_super():
    """True si el usuario actual puede actuar como supervisor de cualquier OT."""
    if not g.permissions:
        return False
    return bool(g.permissions.get("superadmin") or g.permissions.get("admin"))


def _ot_visita_basic(vid):
    """Lee la OT con campos necesarios para validar permisos de acción."""
    return mysql_fetchone(
        "SELECT id, estado, tecnico_user_id, created_by, "
        "       firma_cliente_url, firma_tecnico_url, firma_supervisor_url, "
        "       fecha_programada, fecha_fin, hora_inicio, hora_fin "
        "  FROM mant_visitas WHERE id=%s",
        (vid,)
    )


# 🔴 CANDADO DE VENTANA HORARIA (Daniel 2026-08-26): "quisiera establecer un
# bloqueo a las OT... para que solamente se realicen durante el horario y el
# día que se va a realizar. Esto es medio delicado, revísalo 5 veces."
#
# Tolerancia confirmada por Daniel: 60 minutos antes y después de la hora
# programada. Este es el candado exacto que la auditoría de Fase 0 encontró
# ausente: "ningún endpoint valida fecha/hora antes de iniciar, ni siquiera
# se trae de la base" — ahora sí se trae (ver `_ot_visita_basic` arriba) y
# sí se valida, en HORA CHILE (nunca UTC crudo — ese fue justo el riesgo
# que la propia auditoría marcó como pendiente de confirmar).
_OT_VENTANA_TOLERANCIA_MIN = 60


def _ot_hora_a_time(valor):
    """Normaliza una hora de MySQL a `datetime.time` (o None).

    Las columnas TIME llegan como `timedelta` por el driver, y las horas
    escritas a mano pueden llegar como texto 'HH:MM'. Cualquiera de los dos
    hacía explotar `datetime.combine()`.
    """
    if valor is None or isinstance(valor, dt_time):
        return valor
    if isinstance(valor, timedelta):
        _seg = int(valor.total_seconds()) % 86400
        return dt_time(_seg // 3600, (_seg % 3600) // 60, _seg % 60)
    if isinstance(valor, datetime):
        return valor.time()
    _txt = str(valor).strip()
    if not _txt:
        return None
    try:
        _p = [int(x) for x in _txt.split(":")[:3]]
        while len(_p) < 3:
            _p.append(0)
        return dt_time(_p[0] % 24, _p[1] % 60, _p[2] % 60)
    except (ValueError, IndexError):
        return None


def _ot_dentro_ventana_horario(v):
    """¿Puede iniciarse esta OT AHORA, según su fecha/hora programada?

    Revisado con calma (no es una validación trivial):
    1. Sin `fecha_programada` → no bloquea (no hay contra qué comparar;
       fail-open aquí es correcto, no fail-closed — una OT mal cargada sin
       fecha no debe dejar a un técnico sin poder trabajar nunca).
    2. Rango de días: hoy debe estar entre `fecha_programada` y
       `fecha_fin` (si no hay fecha_fin, el rango es de un solo día).
    3. Si el día es válido pero NO hay hora_inicio/hora_fin cargada, se
       permite todo el día (no se inventa una ventana que nadie declaró).
    4. Si hay horario, se exige estar dentro de
       [hora_inicio - tolerancia, hora_fin + tolerancia]. Sin hora_fin, el
       límite superior es hora_inicio + tolerancia (una visita puntual, no
       un rango).
    5. TODO en hora Chile (`_now_chile()`), nunca `date.today()`/`CURDATE()`
       crudos — esos son UTC en este proyecto (REGLA #6) y adelantarían el
       corte hasta 3-4 horas antes de la medianoche real en Chile.

    Devuelve (permitido: bool, motivo: str|None).
    """
    fecha_prog = v.get("fecha_programada")
    if not fecha_prog:
        return True, None

    ahora = _now_chile()
    hoy = ahora.date()
    fecha_fin = v.get("fecha_fin") or fecha_prog

    if hoy < fecha_prog:
        return False, (
            f"Esta OT está programada para el {fecha_prog.strftime('%d/%m/%Y')}"
            + (f" al {fecha_fin.strftime('%d/%m/%Y')}" if fecha_fin != fecha_prog else "")
            + ". Todavía no llega la fecha.")
    if hoy > fecha_fin:
        return False, (
            f"Esta OT estaba programada para el "
            f"{'del ' + fecha_prog.strftime('%d/%m/%Y') + ' al ' if fecha_fin != fecha_prog else ''}"
            f"{fecha_fin.strftime('%d/%m/%Y')} y ya pasó. Pide que la reprogramen "
            f"si todavía hay que hacerla.")

    # MySQL devuelve las columnas TIME como `timedelta`, no como `time` --
    # sin normalizar, `datetime.combine()` y `.strftime()` revientan con 500
    # y el técnico se queda sin poder tocar el botón "Iniciar OT" (error real
    # en producción, 2026-09-01). Normalizamos acá, en el único lugar que las
    # usa, en vez de confiar en el tipo que traiga el driver.
    h_ini, h_fin = _ot_hora_a_time(v.get("hora_inicio")), _ot_hora_a_time(v.get("hora_fin"))
    if not h_ini and not h_fin:
        return True, None    # día correcto, sin horario declarado -> todo el día

    # Margen configurable (regla `ot_ventana_tolerancia_min`, ver
    # _REGLAS_DEFAULTS). En 0 se desactiva el corte por HORA y solo manda el
    # control por DÍA de arriba — que es lo que de verdad pidió Daniel:
    # "que solamente se realicen durante el horario y el día". Llegar tarde
    # es normal en terreno; trabajar OTRO día no.
    try:
        _tol_min = int((_reglas_cargar() or {}).get("ot_ventana_tolerancia_min",
                                                    _OT_VENTANA_TOLERANCIA_MIN))
    except Exception:
        _tol_min = _OT_VENTANA_TOLERANCIA_MIN
    if _tol_min <= 0:
        return True, None

    tol = timedelta(minutes=_tol_min)
    # Los límites de horario solo aplican en el primer/último día del rango
    # (una OT de varios días no debe exigir "hora_inicio" el día 2).
    if h_ini and hoy == fecha_prog:
        limite_ini = datetime.combine(hoy, h_ini) - tol
        if ahora.replace(tzinfo=None) < limite_ini:
            return False, (
                f"Esta OT parte a las {h_ini.strftime('%H:%M')} y todavía es "
                f"muy temprano (el margen es de {_tol_min} min). Si hay que "
                f"adelantarla, pide que le cambien la hora.")
    ref_fin_hora = h_fin or h_ini
    if ref_fin_hora and hoy == fecha_fin:
        limite_fin = datetime.combine(hoy, ref_fin_hora) + tol
        if ahora.replace(tzinfo=None) > limite_fin:
            return False, (
                f"Esta OT tenía horario hasta las "
                f"{ref_fin_hora.strftime('%H:%M')} y ya pasó el margen de "
                f"{_tol_min} min. Si la vas a hacer igual, pide que le "
                f"ajusten la hora — así queda registrado el cambio real.")
    return True, None


@app.route("/mantenciones/api/visitas/<int:vid>/iniciar", methods=["POST"])
@_mant_required
@_tecnico_owns_visita
def mant_visita_iniciar(vid):
    """Cambia el estado de 'programada' a 'en_curso'. Solo el técnico asignado
    (o un admin/supervisor) puede iniciar el trabajo. Setea hora_real_inicio
    si todavía no estaba."""
    v = _ot_visita_basic(vid)
    if not v:
        return jsonify({"ok": False, "error": "OT no encontrada"}), 404
    if v["estado"] not in ("programada",):
        return jsonify({"ok": False, "error": f"La OT ya está en estado '{v['estado']}'. Solo se puede iniciar desde 'programada'."}), 400
    uid = (g.user or {}).get("id")
    if not uid:
        return jsonify({"ok": False, "error": "Sesión inválida"}), 401
    # 🔐 2026-05-18 — La verificación de "técnico asignado o superadmin"
    # ya la hace el decorador @_tecnico_owns_visita (strict). Acá solo
    # validamos coherencia adicional (ej. hay técnico asignado de verdad).
    asignado = v.get("tecnico_user_id")
    if not asignado:
        # Permitir si es superadmin (puede iniciar OTs sin asignar)
        _u = getattr(g, "user", None) or {}
        if (_u.get("role") or "").lower() != "superadmin":
            return jsonify({"ok": False, "error": "Esta OT no tiene técnico asignado todavía. Pide al supervisor que asigne uno."}), 400

    # 🔴 CANDADO DE VENTANA HORARIA (Daniel 2026-08-26, ver el docstring
    # completo de `_ot_dentro_ventana_horario`). superadmin pasa igual —
    # misma excepción que los dos candados vecinos de esta función.
    _permitido, _motivo_ventana = _ot_dentro_ventana_horario(v)
    if not _permitido and (getattr(g, "user", None) or {}).get("role", "").lower() != "superadmin":
        return jsonify({"ok": False, "error_codigo": "FUERA_DE_VENTANA",
                        "error": _motivo_ventana}), 400

    # 🔴 CANDADO DEL ANEXO (Daniel 2026-08-26): "si no fue firmado, no puede
    # realizar el trabajo". Único punto de bloqueo real -- exactamente el
    # mismo candado que ya existe arriba para "sin técnico asignado", no un
    # segundo mecanismo que se pueda desincronizar. superadmin puede pasar
    # igual (misma excepción que el candado de técnico asignado, arriba).
    _anexo_pend = _anexo_bloquea_ot(vid)
    if _anexo_pend and (getattr(g, "user", None) or {}).get("role", "").lower() != "superadmin":
        return jsonify({
            "ok": False, "error_codigo": "ANEXO_SIN_FIRMAR",
            "error": f"El Anexo de Servicios N° {_anexo_pend} de esta OT todavía no "
                     f"está firmado por el proveedor. No se puede iniciar el trabajo "
                     f"hasta que firme.",
        }), 400

    mysql_execute(
        "UPDATE mant_visitas "
        "   SET estado='en_curso', "
        "       hora_real_inicio=COALESCE(hora_real_inicio, NOW()) "
        " WHERE id=%s",
        (vid,)
    )
    try:
        mysql_execute(
            "INSERT INTO mant_logs (entidad, entidad_id, accion, detalle, usuario) "
            "VALUES ('visita', %s, 'iniciada', %s, %s)",
            (vid, "OT pasada a en_curso", current_username())
        )
    except Exception:
        pass
    # Sincronizar estado del ticket vinculado (si lo hay): OT en curso.
    # Aditivo -- nunca debe romper el inicio de la OT.
    try:
        _tk_set_estado_automatico = globals().get("_tk_set_estado_automatico")
        if _tk_set_estado_automatico:
            _tk_row = mysql_fetchone("SELECT id FROM tk_tickets WHERE visita_id=%s", (vid,))
            if _tk_row:
                _tk_set_estado_automatico(
                    _tk_row["id"], "ot_in_progress",
                    "Técnico inició la OT en terreno", visita_id=vid)
    except Exception as _e_tk_est:
        print(f"[mant_visita_iniciar] sync estado ticket fallo vid={vid}: {_e_tk_est}", flush=True)
    return jsonify({"ok": True, "estado": "en_curso"})


@app.route("/mantenciones/api/visitas/<int:vid>/firmar", methods=["POST"])
@_mant_required
def mant_visita_firmar(vid):
    """Guarda una de las 3 firmas (cliente / tecnico / supervisor).
    Body: {"tipo": "cliente"|"tecnico"|"supervisor",
           "firma": "data:image/png;base64,...",
           "nombre": "Juan Pérez"  // solo para cliente }

    🔐 SEGURIDAD 2026-05-18: no se aplica decorador genérico porque cada
    `tipo` de firma tiene su propia regla de quién puede hacerla:
      - cliente   → técnico asignado + superadmin (el técnico captura la
                    firma del cliente en su dispositivo).
      - tecnico   → solo el técnico asignado + superadmin.
      - supervisor→ admin/superadmin + creador de la OT.
    Las validaciones por-tipo están más abajo. Aquí filtramos por la
    acción genérica 'ver' (cualquiera con vista válida puede ENTRAR al
    endpoint, pero recibe 403 si el tipo no le corresponde).
    """
    if not _puede_ot_accion(vid, "ver"):
        u = getattr(g, "user", None) or {}
        return _ot_403_response(
            vid, (u.get("role") or "").lower(),
            u.get("id"), u.get("username"), accion="ver",
        )
    v = _ot_visita_basic(vid)
    if not v:
        return jsonify({"ok": False, "error": "OT no encontrada"}), 404
    d = request.get_json(silent=True) or {}
    tipo = (d.get("tipo") or "").strip().lower()
    firma = (d.get("firma") or "").strip()
    if tipo not in ("cliente", "tecnico", "supervisor"):
        return jsonify({"ok": False, "error": "tipo debe ser cliente|tecnico|supervisor"}), 400
    if not firma or not firma.startswith("data:image/"):
        return jsonify({"ok": False, "error": "firma vacía o formato inválido (debe ser data URL de imagen)"}), 400
    uid = (g.user or {}).get("id")
    if not uid:
        return jsonify({"ok": False, "error": "Sesión inválida"}), 401

    # Validaciones de identidad por tipo de firma (matriz 2026-05-18)
    if tipo == "tecnico":
        # Solo técnico asignado + superadmin (acción 'ejecutar').
        if not _puede_ot_accion(vid, "ejecutar"):
            return jsonify({"ok": False, "error": "Solo el técnico asignado puede firmar como técnico."}), 403
        # 2026-08-08 (Daniel, geocerca de levantamiento): "si el técnico firma
        # ya se bloquea la OT" — la firma del técnico es el único candado de
        # fecha/gestión que existe (nada de auto-extender fechas). Si quedan
        # equipos a medio capturar (borrador), se avisa y se deja elegir:
        # volver a terminarlos o firmar igual (quedan fuera de la ficha).
        try:
            _borr = mysql_fetchall(
                "SELECT li.id, li.nombre_snap FROM mant_levantamiento_items li "
                "  JOIN mant_levantamientos lv ON lv.id = li.levantamiento_id "
                " WHERE ( lv.visita_id = %s "
                "      OR lv.id = (SELECT levantamiento_id FROM mant_visitas WHERE id=%s) ) "
                "   AND COALESCE(li.es_borrador,0) = 1 "
                "   AND li.maquina_id IS NULL "
                " LIMIT 20", (vid, vid)) or []
        except Exception:
            _borr = []  # columna es_borrador aun no existe (skip-migrations) -> no bloquea
        if _borr and not d.get("confirmar_borradores"):
            return jsonify({
                "ok": False, "error_codigo": "LEV_BORRADORES_PENDIENTES",
                "n": len(_borr),
                "nombres": [(b.get("nombre_snap") or "(sin nombre)") for b in _borr],
                "error": f"Tienes {len(_borr)} equipo(s) a medio capturar. Si firmas ahora, "
                         f"no llegarán a la ficha del cliente.",
            }), 409
        if _borr:
            try:
                _mant_log("visita", vid, "firma_con_borradores",
                          f"{current_username()} firmó con {len(_borr)} equipo(s) en "
                          f"borrador — descartados de la ficha del cliente.")
            except Exception:
                pass
    elif tipo == "supervisor":
        # admin/superadmin + creador de la OT (acción 'firmar_creador').
        if not _puede_ot_accion(vid, "firmar_creador"):
            return jsonify({"ok": False, "error": "Solo el supervisor que asignó esta OT (o un admin) puede firmar."}), 403
    elif tipo == "cliente":
        # El cliente firma en el dispositivo del técnico → solo el técnico
        # asignado + superadmin pueden capturarla. Antes no se validaba y
        # cualquier rol con permiso 'mantenciones' podía falsificar la firma
        # del cliente desde otra sesión (IDOR).
        if not _puede_ot_accion(vid, "ejecutar"):
            return jsonify({"ok": False, "error": "Solo el técnico asignado puede capturar la firma del cliente."}), 403

    nombre = (d.get("nombre") or "").strip()[:200] or None
    # 2026-05-18 — Si no llegó `nombre`, usar el display name del firmante
    # (excepto cliente, donde el campo es responsabilidad del operador en sitio).
    _u_sig = getattr(g, "user", None) or {}
    _default_nom = (_u_sig.get("nombre") or _u_sig.get("username") or "")[:200] or None

    if tipo == "cliente":
        mysql_execute(
            "UPDATE mant_visitas SET firma_cliente_url=%s, firma_cliente_nombre=%s, "
            "       firma_cliente_at=NOW() WHERE id=%s",
            (firma, nombre, vid)
        )
    elif tipo == "tecnico":
        mysql_execute(
            "UPDATE mant_visitas SET firma_tecnico_url=%s, firma_tecnico_user_id=%s, "
            "       firma_tecnico_nombre=%s, firma_tecnico_at=NOW() WHERE id=%s",
            (firma, uid, (nombre or _default_nom), vid)
        )
    else:  # supervisor
        mysql_execute(
            "UPDATE mant_visitas SET firma_supervisor_url=%s, firma_supervisor_user_id=%s, "
            "       firma_supervisor_nombre=%s, firma_supervisor_at=NOW() WHERE id=%s",
            (firma, uid, (nombre or _default_nom), vid)
        )

    try:
        mysql_execute(
            "INSERT INTO mant_logs (entidad, entidad_id, accion, detalle, usuario) "
            "VALUES ('visita', %s, 'firma', %s, %s)",
            (vid, f"Firma capturada — tipo={tipo}", current_username())
        )
    except Exception:
        pass
    return jsonify({"ok": True, "tipo": tipo})


# ══════════════════════════════════════════════════════════════════════
# CIERRE DE OT — captura causa raíz, satisfacción y comentario
# Requiere: las 3 firmas (cliente, técnico, supervisor) presentes.
# ══════════════════════════════════════════════════════════════════════

def _ot_levantamiento_de(visita_o_vid):
    """Resuelve el levantamiento_id de una OT mirando SIEMPRE ambos sentidos
    del vínculo (mant_visitas.levantamiento_id ↔ mant_levantamientos.visita_id).

    Acepta un dict de visita (con 'id' y opcionalmente 'levantamiento_id') o
    directamente un vid (int). SOLO LECTURA — nunca escribe en la BD.

    FIX 2026-08-10 (OT-2026-00042): el enlace queda a veces poblado en un
    solo sentido (dato legacy / desincronización histórica). Varios call
    sites del módulo miraban solo el campo forward (`v.get("levantamiento_id")`)
    y por eso no encontraban levantamientos que sí existían por el lado
    reverse — esta función centraliza el patrón bidireccional que ya usaban
    _ot_validar_cierre R5 y el gate de firma técnica (`WHERE lv.visita_id=%s
    OR lv.id=%s`).

    Ojo: si el dict recibido no trae la columna `levantamiento_id` en su
    SELECT original (algunos callers hacen SELECT parcial), no asumimos que
    `.get()` refleja el valor real — si la key no está presente EN ABSOLUTO
    se re-consulta el campo forward por id antes de caer al fallback reverse.
    """
    try:
        _MISSING = object()
        if isinstance(visita_o_vid, dict):
            vid = visita_o_vid.get("id")
            _raw = visita_o_vid.get("levantamiento_id", _MISSING)
            if _raw is not _MISSING:
                if _raw:
                    return _raw
                # La key está presente y es None/0 -> ya sabemos que el
                # forward es vacío, no hace falta re-consultarlo.
            elif vid:
                try:
                    _row = mysql_fetchone(
                        "SELECT levantamiento_id FROM mant_visitas WHERE id=%s",
                        (vid,)
                    )
                    if _row and _row.get("levantamiento_id"):
                        return _row["levantamiento_id"]
                except Exception:
                    pass
        else:
            vid = visita_o_vid
            if vid:
                try:
                    _row = mysql_fetchone(
                        "SELECT levantamiento_id FROM mant_visitas WHERE id=%s",
                        (vid,)
                    )
                    if _row and _row.get("levantamiento_id"):
                        return _row["levantamiento_id"]
                except Exception:
                    pass
        if not vid:
            return None
        try:
            _rev = mysql_fetchone(
                "SELECT id FROM mant_levantamientos WHERE visita_id=%s "
                " ORDER BY id DESC LIMIT 1", (vid,)
            )
            if _rev:
                return _rev["id"]
        except Exception:
            pass
        return None
    except Exception:
        return None


def _ot_equipos_y_fotos(vid):
    """Fuente única de 'equipos y fotos' de una OT. Combina:
      - mant_visita_tareas / mant_visita_fotos (checklist clásico)
      - mant_levantamiento_items / mant_levantamiento_fotos (vía
        _ot_levantamiento_de, resolviendo el link en ambos sentidos)

    SOLO LECTURA. Devuelve dict con: equipos, fotos, eq_fotos_idx, lev_items,
    lev_fotos_idx, lev_fotos_huerfanas, n_fotos_total (deduplicado por
    foto_hash, MISMO criterio que ya usa _ot_validar_cierre R5 — con
    COALESCE(foto_hash, CONCAT('id:', id)) para no penalizar fotos
    históricas sin hash).
    """
    out = {
        "equipos": [], "fotos": [], "eq_fotos_idx": {},
        "lev_items": [], "lev_fotos_idx": {}, "lev_fotos_huerfanas": [],
        "n_fotos_total": 0,
    }
    try:
        equipos = mysql_fetchall(
            "SELECT DISTINCT m.id, m.nombre, m.sku, m.serie, m.foto_url, "
            "       m.marca, m.modelo "
            "  FROM mant_visita_tareas vt "
            "  JOIN mant_maquinas m ON m.id = vt.maquina_id "
            " WHERE vt.visita_id=%s AND vt.maquina_id IS NOT NULL "
            "   AND COALESCE(m.estado,'activo') != 'baja' "
            " ORDER BY m.nombre", (vid,)
        ) or []
        out["equipos"] = [dict(e) for e in equipos]
    except Exception:
        pass

    try:
        fotos = mysql_fetchall(
            "SELECT id, tarea_id, maquina_id, archivo_path, cloudinary_url, "
            "       tipo_foto, tomada_at, foto_hash "
            "  FROM mant_visita_fotos WHERE visita_id=%s ORDER BY tomada_at",
            (vid,)
        ) or []
        out["fotos"] = [dict(f) for f in fotos]
        for f in out["fotos"]:
            mid = f.get("maquina_id")
            if mid:
                out["eq_fotos_idx"].setdefault(mid, []).append(f)
    except Exception:
        pass

    _lev_id = _ot_levantamiento_de(vid)
    if _lev_id:
        try:
            lev_items = mysql_fetchall(
                "SELECT * FROM mant_levantamiento_items "
                " WHERE levantamiento_id=%s AND COALESCE(nombre_snap,'') <> '' "
                "   AND COALESCE(es_borrador,0) = 0 "
                "   AND COALESCE(estado_capturado,'') <> 'no_encontrado' "
                " ORDER BY id ASC", (_lev_id,)
            ) or []
        except Exception:
            try:
                lev_items = mysql_fetchall(
                    "SELECT * FROM mant_levantamiento_items "
                    " WHERE levantamiento_id=%s AND COALESCE(nombre_snap,'') <> '' "
                    " ORDER BY id ASC", (_lev_id,)
                ) or []
            except Exception:
                lev_items = []
        out["lev_items"] = [dict(i) for i in lev_items]
        _ids_items = {int(i["id"]) for i in out["lev_items"] if i.get("id") is not None}
        try:
            _lev_fotos = mysql_fetchall(
                "SELECT id, item_id, cloudinary_url, tipo_foto, descripcion, foto_hash "
                "  FROM mant_levantamiento_fotos WHERE levantamiento_id=%s "
                " ORDER BY id ASC", (_lev_id,)
            ) or []
        except Exception:
            _lev_fotos = []
        for _f in _lev_fotos:
            _f = dict(_f)
            _iid = _f.get("item_id")
            if _iid is not None and int(_iid) in _ids_items:
                out["lev_fotos_idx"].setdefault(_iid, []).append(_f)
            else:
                out["lev_fotos_huerfanas"].append(_f)

    try:
        _f1 = mysql_fetchone(
            "SELECT COUNT(DISTINCT COALESCE(foto_hash, CONCAT('id:', id))) AS n "
            "  FROM mant_visita_fotos WHERE visita_id=%s", (vid,)
        ) or {}
        _n1 = int(_f1.get("n") or 0)
    except Exception:
        _n1 = 0
    _n2 = 0
    if _lev_id:
        try:
            _f2 = mysql_fetchone(
                "SELECT COUNT(DISTINCT COALESCE(foto_hash, CONCAT('id:', id))) AS n "
                "  FROM mant_levantamiento_fotos WHERE levantamiento_id=%s", (_lev_id,)
            ) or {}
            _n2 = int(_f2.get("n") or 0)
        except Exception:
            _n2 = 0
    out["n_fotos_total"] = _n1 + _n2
    return out


def _ot_es_levantamiento(v):
    """True si la OT captura fichas de equipo (o sea: si tiene levantamiento).

    ÚNICA fuente de verdad. Daniel 2026-08-08: "hay un arroz con mango con
    esto de las OT con lo del levantamiento; cuando escojo algo diferente ahí
    es donde falla... yo escogí Inspección, nunca escogí levantamiento".

    Tenía razón: NO basta con mirar tipo=='levantamiento'. Una OT de
    inspección / preventiva / instalación TAMBIÉN captura fichas, y el propio
    _ensure_levantamiento_para_visita le crea un levantamiento por eso mismo.
    Mirar solo el tipo dejaba a esas OT en tierra de nadie: se comportaban
    como levantamiento para unas cosas y no para otras.

    FIX 2026-08-10 (OT-2026-00042): antes solo miraba el campo forward
    `v.get("levantamiento_id")` — si el link estaba SOLO en el sentido
    reverse (mant_levantamientos.visita_id), esta función daba False aunque
    el levantamiento existiera y tuviera datos. Ahora usa
    _ot_levantamiento_de(v), que resuelve ambos sentidos. Se cachea el
    resultado en el propio dict `v` (memoria de esta request, NUNCA se hace
    UPDATE a la BD) para no repetir la query reverse en llamadas
    subsecuentes sobre el mismo dict dentro del mismo request — esta función
    se llama en un hot path (varias veces por request en algunos endpoints).
    """
    if not v:
        return False
    try:
        if (v.get("tipo") or "").strip().lower() == "levantamiento":
            return True
        if v.get("levantamiento_id"):
            return True
        _lev_id = _ot_levantamiento_de(v)
        if _lev_id:
            if isinstance(v, dict):
                v["levantamiento_id"] = _lev_id
            return True
        return False
    except Exception:
        return False


def _ot_tarea_no_trabajable_sql(alias=""):
    """Tarea que no dibuja tarjeta en pantalla = imposible de trabajar.

    Regla de fondo (una sola, dos causas): si el técnico NO puede ver la
    tarjeta del equipo, no puede abrir la tarea, ni fotografiarla, ni
    marcarla. Exigirla para cerrar es un candado sin llave — la OT queda
    trabada haga lo que haga quien esté en terreno.

    CAUSA 1 · tarea sin maquina_id (huérfana)
    PASO 1 del plan "el levantamiento es un tipo más" (2026-08-12): antes
    este filtro solo se aplicaba `if es_levantamiento`, como si el problema
    de las tareas huérfanas fuera exclusivo del levantamiento. No lo es —
    una tarea sin maquina_id no dibuja tarjeta en NINGÚN tipo de OT, así que
    el técnico no puede abrirla, fotografiarla ni marcarla sin importar el
    tipo. Por eso este helper se usa SIEMPRE, incondicional al tipo.

    CAUSA 2 · la máquina está dada de baja (o ya no existe)
    FIX 2026-08-20 (Daniel, caso OT-2026-00058 Deportes Vitacura: "esas 36
    tareas no sé de dónde las sacaste!!!"). Diagnóstico real medido en
    producción: 4 trotadoras (ids 6444-6447, series 65206047-0905-1 a -4)
    fueron dadas de baja. mant_ot_ejecutar filtra los equipos de baja al
    armar la pantalla (FIX 2026-05-16) — correcto, un equipo de baja no se
    trabaja. Pero el validador de cierre contaba mant_visita_tareas SIN ese
    filtro, así que las 44 tareas de esos 4 equipos seguían exigiéndose
    mientras sus tarjetas ya no se dibujaban. Daniel veía 7 trotadoras
    completas en pantalla y el contador le decía 36 obligatorias pendientes:
    las dos cifras eran ciertas y ninguna se podía conciliar a mano.

    La condición se ancla al MISMO criterio que usa la pantalla para dibujar
    (`COALESCE(estado,'activo') <> 'baja'`), no a una lista de causas — si
    mañana la pantalla deja de dibujar por otro motivo, el lugar a tocar es
    uno solo y los dos quedan alineados por construcción.

    Las tareas NO se borran ni se marcan (REGLA #4.2): siguen existiendo,
    visibles y auditables. Solo dejan de ser un candado infranqueable. El
    cierre además informa cuántas se excluyeron así — ver
    `_ot_tareas_excluidas_por_baja()`, para que "la OT cerró" nunca sea una
    forma silenciosa de saltarse trabajo dando de baja un equipo.

    El `alias` es OBLIGATORIO cuando la consulta hace JOIN con otra tabla
    que TAMBIÉN tiene columna `maquina_id` (ej. mant_visita_fotos) — sin el
    alias correcto la columna queda ambigua → MySQL error 1052 → 500 en el
    cierre de TODA OT, no solo levantamiento. El subquery usa su propio
    alias `_mmx` por la misma razón: varias de estas consultas ya hacen
    JOIN con mant_maquinas como `m`.
    """
    return (
        f" AND {alias}maquina_id IS NOT NULL "
        f" AND EXISTS (SELECT 1 FROM mant_maquinas _mmx "
        f"              WHERE _mmx.id = {alias}maquina_id "
        f"                AND COALESCE(_mmx.estado,'activo') <> 'baja') "
    )


def _ot_tareas_excluidas_por_baja(vid):
    """Cuántas tareas de la OT no se exigen porque su equipo está de baja.

    Existe para que la exclusión sea VISIBLE, no silenciosa: el cierre la
    informa como aviso (nunca como bloqueo). Sin esto, dar de baja un equipo
    sería una forma tranquila de hacer desaparecer trabajo pendiente sin que
    quede rastro en la pantalla de cierre.
    """
    try:
        r = mysql_fetchone(
            "SELECT COUNT(*) AS n, COUNT(DISTINCT t.maquina_id) AS equipos "
            "  FROM mant_visita_tareas t "
            " WHERE t.visita_id=%s AND t.maquina_id IS NOT NULL "
            "   AND COALESCE(t.completada,0)=0 "
            "   AND NOT EXISTS (SELECT 1 FROM mant_maquinas _mmx "
            "                    WHERE _mmx.id = t.maquina_id "
            "                      AND COALESCE(_mmx.estado,'activo') <> 'baja')",
            (vid,)
        ) or {}
        return int(r.get("n") or 0), int(r.get("equipos") or 0)
    except Exception:
        return 0, 0


def _ot_maquinas_excluidas_cierre(vid):
    """Set de maquina_id que NO deben bloquear el cierre de una OT: equipos
    marcados 'saltado' o 'falla_detectada' (ya quedaron documentados/con
    incidencia registrada). ÚNICA fuente de verdad — FIX 2026-08-08 (Daniel,
    caso OT-56: "todo está gestionado pero aún dice 18 tareas obligatorias"):
    esta regla vivía copiada en 3 lugares (aquí, el gate de firmar-revision,
    y el JS del frontend) y el gate de firmar-revision se quedó con una
    copia vieja que solo excluía 'saltado' — un equipo marcado
    'falla_detectada' (gestionado, con incidencia registrada) seguía
    bloqueando la firma con sus tareas obligatorias "pendientes". Ahora
    ambos endpoints llaman a esta única función.
    """
    excluir_maquinas = set()
    try:
        rows_excl = mysql_fetchall(
            "SELECT maquina_id FROM mant_visita_equipos "
            " WHERE visita_id=%s "
            "   AND estado_revision IN ('saltado','falla_detectada')",
            (vid,)
        ) or []
        for r in rows_excl:
            if r.get("maquina_id"):
                excluir_maquinas.add(int(r["maquina_id"]))
    except Exception:
        # Tabla nueva — si aún no se creó, no excluimos nada (comp. atrás).
        excluir_maquinas = set()
    return excluir_maquinas


_OT_DIAG_MIN_CHARS = 20

# Títulos de ítems de checklist que YA son un diagnóstico. Se comparan sobre el
# título normalizado (sin acentos ni mayúsculas). Cubre las plantillas reales de
# ILUS: "Diagnóstico y recomendación", "Observaciones adicionales",
# "Falla reportada por el cliente".
_OT_DIAG_TITULOS_RE = re.compile(
    r"(diagnostic|recomendacion|observacion|falla\s+reportada|estado\s+final)", re.I
)


def _ot_diagnostico_efectivo(vid, solo_lectura_v=None):
    """El diagnóstico REAL de la OT: el escrito a mano, o el que se compone con
    el trabajo que el técnico YA hizo en el checklist.

    ══════════════════════════════════════════════════════════════════════
    Daniel (2026-08-29, después de que Isabel Milling y Daniel Pulgar se
    toparan con lo mismo en terreno): *"necesito un cambio definitivo, que no
    molestemos a los técnicos por esas pendejadas"*.
    ══════════════════════════════════════════════════════════════════════
    El caso que lo motiva es la OT-2026-00147: 72/72 tareas obligatorias
    completas —incluyendo un ítem "Diagnóstico y recomendación" contestado en
    CADA una de las 9 máquinas— y aun así el candado la rechazaba, porque ese
    trabajo se guarda en `mant_visita_tareas.valor_json` y en
    `mant_visita_equipos.diagnostico_texto`, mientras la regla interrogaba una
    tercera columna (`mant_visitas.diagnostico`) que nadie había llenado.

    O sea: el técnico SÍ diagnosticó. Pedirle que lo reescriba a mano en un
    campo aparte es exactamente la pendejada que hay que matar.

    Prioridad:
      1. `mant_visitas.diagnostico` escrito a mano — si existe, manda siempre.
         Nunca se pisa ni se "mejora" lo que una persona escribió.
      2. Composición automática con lo ya registrado, en este orden:
         a) diagnóstico por equipo (`mant_visita_equipos.diagnostico_texto`),
            que además ya es obligatorio cuando el veredicto es observación o
            falla;
         b) respuestas de los ítems de checklist cuyo título es un diagnóstico
            (ver _OT_DIAG_TITULOS_RE).

    Returns: (texto, origen) — origen ∈ {'manual', 'compuesto', 'vacio'}.
    El texto compuesto NO se escribe en la base acá: esta función solo
    responde "¿hay diagnóstico?". Quien decide persistirlo es el cierre.
    """
    v = solo_lectura_v
    if v is None:
        v = mysql_fetchone(
            "SELECT diagnostico FROM mant_visitas WHERE id=%s", (vid,)) or {}
    manual = (v.get("diagnostico") or "").strip()
    if len(manual) >= _OT_DIAG_MIN_CHARS:
        return manual, "manual"

    partes = []

    # (a) Diagnóstico por equipo — el que el técnico deja al cerrar cada máquina.
    try:
        for r in mysql_fetchall(
            "SELECT COALESCE(m.nombre, CONCAT('Equipo #', ve.maquina_id)) AS nombre, "
            "       ve.diagnostico_estado, ve.diagnostico_texto "
            "  FROM mant_visita_equipos ve "
            "  LEFT JOIN mant_maquinas m ON m.id = ve.maquina_id "
            " WHERE ve.visita_id=%s "
            "   AND COALESCE(TRIM(ve.diagnostico_texto),'') <> '' "
            " ORDER BY nombre", (vid,)
        ) or []:
            _est = (r.get("diagnostico_estado") or "").strip()
            _pref = {"aprobado": "OK", "observacion": "Observación",
                     "falla": "Falla"}.get(_est, "")
            partes.append(
                f"{r['nombre']}{(' — ' + _pref) if _pref else ''}: "
                f"{(r.get('diagnostico_texto') or '').strip()}"
            )
    except Exception as _e_de:
        print(f"[_ot_diagnostico_efectivo][equipos] vid={vid}: {_e_de}", flush=True)

    # (b) Ítems del checklist que ya SON un diagnóstico.
    if not partes:
        try:
            for r in mysql_fetchall(
                "SELECT COALESCE(m.nombre, '') AS nombre, t.titulo, t.tipo_respuesta, "
                "       t.valor_json "
                "  FROM mant_visita_tareas t "
                "  LEFT JOIN mant_maquinas m ON m.id = t.maquina_id "
                " WHERE t.visita_id=%s AND COALESCE(t.completada,0)=1 "
                "   AND COALESCE(t.valor_json,'') <> '' "
                " ORDER BY t.maquina_id, t.orden, t.id", (vid,)
            ) or []:
                if not _OT_DIAG_TITULOS_RE.search(r.get("titulo") or ""):
                    continue
                try:
                    vj = r["valor_json"]
                    vj = json.loads(vj) if isinstance(vj, str) else (vj or {})
                except Exception:
                    continue
                if not isinstance(vj, dict):
                    continue
                # Mismas formas que guarda mant_visita_tarea_respuesta:
                #   texto → {texto}, lista → {opcion}, sino/verificacion → {valor}
                txt = (vj.get("texto") or vj.get("opcion") or vj.get("valor") or "")
                txt = str(txt).strip()
                if not txt or txt.lower() in ("na", "n/a", "-"):
                    continue
                _eq = (r.get("nombre") or "").strip()
                partes.append(f"{_eq + ' — ' if _eq else ''}{r['titulo']}: {txt}")
        except Exception as _e_dt:
            print(f"[_ot_diagnostico_efectivo][tareas] vid={vid}: {_e_dt}", flush=True)

    if partes:
        compuesto = " · ".join(partes)[:5000]
        if len(compuesto) >= _OT_DIAG_MIN_CHARS:
            return compuesto, "compuesto"

    # Nada compuesto alcanza: devolvemos lo manual aunque sea corto, para que
    # quien avise al técnico pueda decirle cuánto le falta.
    return manual, ("manual" if manual else "vacio")


def _ot_validar_diagnostico_y_fotos(vid, excluir_maquinas=None):
    """R2 (diagnóstico ≥20 caracteres) + R3 (foto por tarea con
    requiere_foto=1). Devuelve una lista de razones bloqueantes (vacía si
    pasa). Exime OT tipo levantamiento (mismo criterio de siempre — su
    diagnóstico se autogenera al cerrar).

    2026-08-27 (Daniel, explícito: "sí es necesario... necesitamos
    diagnosticar los equipos... que tomamos las fotos necesarias"): se
    extrae de `_ot_validar_cierre` (R1-R5, que sigue intacta para el cierre
    legacy) para poder exigir ESTAS DOS reglas en la firma del TÉCNICO
    (`firmar-revision`), no en la aprobación del supervisor — es la lección
    ya aprendida del caso OT-58: el candado debe vivir donde el técnico
    todavía puede resolverlo él mismo, antes de irse del sitio. No incluye
    R1 (checklist, ya exigido aparte en firmar-revision) ni R4 (firmas,
    no aplica todavía en ese punto del flujo).
    """
    v = mysql_fetchone(
        "SELECT id, tipo, diagnostico, levantamiento_id, cliente_id "
        "  FROM mant_visitas WHERE id=%s", (vid,))
    if not v:
        return ["OT no encontrada"]

    razones = []
    # 🧹 LIMPIEZA 2026-08-29 (Daniel: "necesito limpiar el código y que no se
    # comporte como levantamiento"). Acá se usaba _ot_es_levantamiento(v), que
    # devuelve True para CUALQUIER OT que tenga un vínculo a un levantamiento
    # -- y hasta el 2026-08-12 ese vínculo se creaba también en preventivas,
    # instalaciones e inspecciones. Consecuencia medida por la auditoría de
    # esta noche: si una OT de Visita Técnica quedó enlazada, se eximía del
    # diagnóstico para siempre; si no, se le exigía. La misma OT, el mismo
    # trabajo, distinto veredicto según cómo quedó escrito un campo que el
    # técnico nunca vio. Eso es lo que Daniel llamó "levantamiento por letras".
    #
    # Acá la exención pasa a depender del TIPO DECLARADO de la OT, que es lo
    # que la persona eligió al crearla y lo que se ve en pantalla. Una OT de
    # levantamiento sigue exenta (su diagnóstico se autogenera al cerrar);
    # cualquier otro tipo responde por su diagnóstico, tenga o no un
    # levantamiento colgando. _ot_es_levantamiento NO se toca: sigue siendo
    # correcta para lo suyo (¿esta OT captura fichas de equipo?), que es una
    # pregunta distinta de ¿esta OT necesita diagnóstico?.
    es_levantamiento = (v.get("tipo") or "").strip().lower() == "levantamiento"
    if excluir_maquinas is None:
        excluir_maquinas = _ot_maquinas_excluidas_cierre(vid)

    if not es_levantamiento:
        # 2026-08-29: ya no se interroga la columna cruda, sino el diagnóstico
        # EFECTIVO -- que incluye el trabajo de diagnóstico que el técnico ya
        # hizo por equipo o en el checklist. Ver _ot_diagnostico_efectivo:
        # nace de que la OT-2026-00147 tenía las 9 máquinas diagnosticadas y
        # el candado igual la rechazaba por mirar el lugar equivocado.
        diag, _origen_diag = _ot_diagnostico_efectivo(vid, solo_lectura_v=v)
        if len(diag) < _OT_DIAG_MIN_CHARS:
            razones.append(
                "Diagnóstico obligatorio: debe explicar qué se hizo "
                "(mínimo 20 caracteres) antes de firmar."
            )

    # 🔴 FIX 2026-08-31 (Daniel, urgente, OT-2026-00125 Daniel Pulgar: un
    # "Wall Ball" -- sin electrónica -- traía un ítem "Medición voltaje (V)"
    # con requiere_foto=1, heredado de una plantilla eléctrica genérica. El
    # técnico YA podía marcar el valor numérico como "N/A" (fix 2026-08-27,
    # caso Isabel Milling, ver mant_visita_tarea_respuesta tipo 'numero'),
    # pero esta consulta seguía exigiendo la FOTO igual, sin mirar si la
    # tarea ya se respondió como N/A -- un candado sin llave: no hay foto
    # posible de una medición que no existe. Se excluye toda tarea marcada
    # N/A -- pero 'na' NO se guarda igual para todos los tipos: 'numero' y
    # 'serie' usan {"na": true}, mientras 'sino' usa {"valor": "na"} (ver
    # mant_visita_tarea_respuesta, cada tipo normaliza a su manera) -- se
    # chequean AMBAS formas para no dejar la misma clase de bug abierta en
    # 'sino' (encontrado al revisar OT-2026-00131, mismo patrón). No se
    # toca la plantilla en sí (root cause de por qué "Wall Ball" heredó
    # ese ítem queda aparte).
    tareas_sin_foto = []
    try:
        if excluir_maquinas:
            _ph = ",".join(["%s"] * len(excluir_maquinas))
            tareas_sin_foto = mysql_fetchall(
                "SELECT t.id, t.titulo "
                "FROM mant_visita_tareas t "
                "LEFT JOIN mant_visita_fotos f ON f.tarea_id=t.id "
                f"WHERE t.visita_id=%s AND t.requiere_foto=1 "
                f"  AND (t.maquina_id IS NULL OR t.maquina_id NOT IN ({_ph})) "
                + _ot_tarea_no_trabajable_sql("t.") +
                " AND NOT (t.valor_json IS NOT NULL AND (JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.na')) = 'true' OR JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.valor')) = 'na')) "
                "GROUP BY t.id, t.titulo "
                "HAVING COUNT(f.id) = 0",
                (vid, *list(excluir_maquinas))
            ) or []
        else:
            tareas_sin_foto = mysql_fetchall(
                "SELECT t.id, t.titulo "
                "FROM mant_visita_tareas t "
                "LEFT JOIN mant_visita_fotos f ON f.tarea_id=t.id "
                "WHERE t.visita_id=%s AND t.requiere_foto=1 "
                + _ot_tarea_no_trabajable_sql("t.") +
                " AND NOT (t.valor_json IS NOT NULL AND (JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.na')) = 'true' OR JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.valor')) = 'na')) "
                "GROUP BY t.id, t.titulo "
                "HAVING COUNT(f.id) = 0",
                (vid,)
            ) or []
    except Exception as _e_r3:
        # FAIL-OPEN deliberado (mismo criterio que R3/R5 en _ot_validar_cierre,
        # fix 2026-08-22): un problema de infraestructura no debe trabar al
        # técnico en terreno.
        print(f"[_ot_validar_diagnostico_y_fotos][R3] vid={vid}: {_e_r3}", flush=True)
        tareas_sin_foto = []

    if tareas_sin_foto:
        nombres = [t.get("titulo") or f"#{t['id']}" for t in tareas_sin_foto[:5]]
        suf = "" if len(tareas_sin_foto) <= 5 else f" y {len(tareas_sin_foto)-5} más"
        razones.append(
            f"Falta foto en {len(tareas_sin_foto)} tarea(s): {', '.join(nombres)}{suf}"
        )

    return razones


def _ot_validar_cierre(vid):
    """FASE 5 — Validación de cierre auditable de OT con 4 reglas que el
    usuario aprobó. Devuelve dict con resultado:
      {"puede_cerrar": bool, "razones": [list de razones bloqueantes]}

    Reglas (todas obligatorias salvo que la OT sea de tipo levantamiento
    que tiene sus propias reglas más laxas):
      R1. Checklist 100% completado (todas las tareas con estado_trabajo='completada')
      R2. Diagnóstico obligatorio (mant_visitas.diagnostico no vacío, mín 20 chars)
      R3. Foto obligatoria por cada tarea con requiere_foto=1 (debe tener ≥1 foto)
      R4. Las 3 firmas presentes (cliente, técnico, supervisor)

    Las OT tipo 'levantamiento' eximen R2 (diagnóstico autogenerado al cerrar).
    """
    v = mysql_fetchone(
        # cliente_id incluido (2026-08-10): _ot_es_interna(v) más abajo (R4)
        # ahora también mira "cliente_id IS NULL" — sin esta columna en el
        # SELECT, esa condición no puede evaluarse (fail-closed correcto,
        # pero deja sin efecto la exención para OT de Capacitación/Control
        # de Calidad sin cliente).
        "SELECT id, tipo, estado, diagnostico, levantamiento_id, cliente_id, "
        "       firma_cliente_url, firma_tecnico_url, firma_supervisor_url "
        "  FROM mant_visitas WHERE id=%s",
        (vid,)
    )
    if not v:
        return {"puede_cerrar": False, "razones": ["OT no encontrada"]}

    razones = []
    # FIX 2026-05-22 (Daniel — caso Vitacura OT 161/162/163): tratamos como
    # "levantamiento" (reglas de cierre más laxas: sin diagnóstico, sin
    # checklist obligatorio) TANTO las OT tipo='levantamiento' COMO las
    # que tienen levantamiento_id poblado (creadas desde el modal del
    # cliente con dropdown distinto a 'levantamiento'). En ambos casos el
    # foco es capturar datos del equipo (fotos, marca/modelo/serie), no
    # ejecutar un checklist clínico.
    es_levantamiento = _ot_es_levantamiento(v)

    # ── 2026-05-21 (Daniel) — Trazabilidad por equipo ──────────────────
    # Si la OT es tipo 'levantamiento', el técnico puede SALTAR equipos
    # (con razón + observación). Las tareas de un equipo saltado NO
    # bloquean el cierre. Tampoco bloquean las del equipo marcado como
    # 'falla_detectada' (ya quedó registrada la incidencia).
    excluir_maquinas = _ot_maquinas_excluidas_cierre(vid)

    # R1 — Checklist 100% completado (excluyendo tareas de equipos saltados/con falla)
    #
    # FIX 2026-08-08 (Daniel, caso OT-2026-00056 — "no entiendo por qué sigue
    # bloqueada... necesito realizar las OT sin restricción"): además se
    # excluyen las tareas HUÉRFANAS (maquina_id NULL) cuando la OT captura
    # fichas por levantamiento. Motivo: al generar una OT desde un Ticket cuyos
    # equipos aún no tienen ficha, se crea 1 tarea obligatoria con foto por
    # equipo SIN maquina_id (app.py ~84752). Sin maquina_id no se dibuja
    # tarjeta de equipo: el técnico NO PUEDE abrirla, ni subirle foto, ni
    # marcarla. Exigir una tarea que es imposible de trabajar es un bloqueo
    # por construcción — el técnico queda trabado en terreno haga lo que haga.
    # El trabajo real de esas OT queda en el levantamiento (items + fotos), y
    # el informe SÍ lo documenta (ver _ot_es_levantamiento en la selección de
    # template del PDF). Las tareas NO se borran (REGLA #4.2): siguen
    # existiendo y visibles, solo dejan de ser un candado infranqueable.
    # PASO 1b (2026-08-12): el filtro de huérfanas ya NO depende del tipo —
    # ver _ot_tarea_no_trabajable_sql().
    _huerf_sql = _ot_tarea_no_trabajable_sql()
    if excluir_maquinas:
        _ph = ",".join(["%s"] * len(excluir_maquinas))
        _chk_base = (
            f"FROM mant_visita_tareas WHERE visita_id=%s "
            f"  AND (maquina_id IS NULL OR maquina_id NOT IN ({_ph}))"
        )
        _chk_params = (vid, *list(excluir_maquinas))
    else:
        _chk_base = "FROM mant_visita_tareas WHERE visita_id=%s"
        _chk_params = (vid,)
    chk_row = mysql_fetchone(
        "SELECT COUNT(*) AS total, "
        " SUM(CASE WHEN estado_trabajo='completada' OR completada=1 THEN 1 ELSE 0 END) AS done "
        + _chk_base + _huerf_sql,
        _chk_params
    ) or {}
    # PASO 1c (2026-08-12, CRÍTICO): total_bruto es el MISMO COUNT pero SIN
    # el filtro de huérfanas. Con el filtro de 1b ya incondicional, `total`
    # (filtrado) puede dar 0 en una OT que SÍ tiene tareas (todas huérfanas)
    # — usar `total` ahí dispararía el mensaje falso "La OT no tiene tareas
    # asignadas" en una OT que en realidad está trabada por tareas
    # imposibles de trabajar, no por falta de tareas. `total`/`done` (ya
    # filtrados) se reservan para el mensaje de "Checklist incompleto".
    chk_row_bruto = mysql_fetchone(
        "SELECT COUNT(*) AS total " + _chk_base,
        _chk_params
    ) or {}
    total = int(chk_row.get("total") or 0)
    done = int(chk_row.get("done") or 0)
    total_bruto = int(chk_row_bruto.get("total") or 0)
    # R1a — Tareas de checklist (preventivas/correctivas)
    if total_bruto == 0 and not excluir_maquinas and not es_levantamiento:
        razones.append("La OT no tiene tareas asignadas — agrega un checklist antes de cerrar.")
    elif done < total:
        razones.append(
            f"Checklist incompleto: {done}/{total} tareas completadas. "
            f"Faltan {total - done} por marcar."
        )

    # R1b — Revisión de equipos para levantamientos (2026-06-12 Daniel)
    # Para OT tipo levantamiento, cada equipo en plan (aplica_mantencion=1)
    # debe tener una entrada en mant_visita_equipos (verificado / con_cambios /
    # saltado / falla_detectada). Equipos fuera del plan quedan exentos.
    if es_levantamiento:
        try:
            # PASO 6 (2026-08-12, plan "el levantamiento es un tipo más"):
            # el universo de "equipos en plan" se acota de TODAS las
            # máquinas del cliente a SOLO los equipos DE ESTA OT -- un
            # cliente con 200 máquinas y una OT de 3 equipos generaba 197
            # revisiones que nadie encargó (pedido explícito de Daniel).
            # Universo nuevo: unión de mant_visita_tareas.maquina_id de
            # ESTA visita_id + mant_levantamiento_items.maquina_id del
            # levantamiento vinculado a ESTA OT, ambos con
            # maquina_id IS NOT NULL. Se conserva el filtro
            # aplica_mantencion, m.estado != 'baja' tal cual, y el
            # NOT EXISTS contra mant_visita_equipos. NO se incluye
            # mant_visita_equipos en la unión del universo -- eso dejaría
            # la regla comparando "los que tienen fila y no tienen fila"
            # (siempre 0), eliminándola de hecho (Regla #4.2 -- no se
            # quita una regla sin permiso explícito).
            _lev_id_r1b = v.get("levantamiento_id")
            _pend = mysql_fetchone(
                "SELECT COUNT(*) AS cnt "
                "  FROM mant_maquinas m "
                " WHERE m.id IN ( "
                "       SELECT maquina_id FROM mant_visita_tareas "
                "        WHERE visita_id=%s AND maquina_id IS NOT NULL "
                "       UNION "
                "       SELECT maquina_id FROM mant_levantamiento_items "
                "        WHERE levantamiento_id=%s AND maquina_id IS NOT NULL "
                "   ) "
                "   AND m.aplica_mantencion = 1 "
                "   AND m.estado != 'baja' "
                "   AND NOT EXISTS ( "
                "       SELECT 1 FROM mant_visita_equipos ve "
                "        WHERE ve.visita_id = %s AND ve.maquina_id = m.id "
                "   )",
                (vid, _lev_id_r1b, vid)
            )
            _pend_cnt = int((_pend or {}).get("cnt") or 0)
            if _pend_cnt > 0:
                razones.append(
                    f"Levantamiento incompleto: {_pend_cnt} equipo(s) en plan sin revisar. "
                    "Documenta cada uno o márcalos como 'saltado' antes de cerrar."
                )
        except Exception as _lev_e:
            print(f"[_ot_validar_cierre][lev_equip_check] {_lev_e}", flush=True)

    # R2 — Diagnóstico obligatorio (excepto levantamiento)
    if not es_levantamiento:
        diag = (v.get("diagnostico") or "").strip()
        if len(diag) < 20:
            razones.append(
                "Diagnóstico obligatorio: debe explicar qué se hizo (mínimo 20 caracteres)."
            )

    # R3 — Foto obligatoria por tarea con requiere_foto=1 (excluyendo saltados)
    # Mismo criterio de huérfanas que R1 (ver comentario largo allá): una tarea
    # sin maquina_id no tiene tarjeta en pantalla, así que el técnico no tiene
    # NINGUNA forma de subirle la foto. Exigírsela lo deja trabado sin salida.
    #
    # 🔴 FIX 2026-08-22: era la ÚNICA de las 5 reglas sin try/except. Su
    # consulta hace LEFT JOIN + GROUP BY + HAVING; si falla (pool saturado,
    # timeout), la excepción subía y reventaba con 500 la validación
    # COMPLETA — el técnico ni siquiera podía VER qué le faltaba. R5, que
    # cuenta fotos, ya fallaba a favor del técnico desde que se escribió.
    # Acá se iguala el criterio: si no se puede comprobar, no se inventa un
    # bloqueo, pero queda en el log para que no pase inadvertido.
    tareas_sin_foto = []
    try:
      if excluir_maquinas:
        _ph = ",".join(["%s"] * len(excluir_maquinas))
        tareas_sin_foto = mysql_fetchall(
            "SELECT t.id, t.titulo "
            "FROM mant_visita_tareas t "
            "LEFT JOIN mant_visita_fotos f ON f.tarea_id=t.id "
            f"WHERE t.visita_id=%s AND t.requiere_foto=1 "
            f"  AND (t.maquina_id IS NULL OR t.maquina_id NOT IN ({_ph})) "
            + _ot_tarea_no_trabajable_sql("t.") +
            " AND NOT (t.valor_json IS NOT NULL AND (JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.na')) = 'true' OR JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.valor')) = 'na')) "
            "GROUP BY t.id, t.titulo "
            "HAVING COUNT(f.id) = 0",
            (vid, *list(excluir_maquinas))
        ) or []
      else:
        tareas_sin_foto = mysql_fetchall(
            "SELECT t.id, t.titulo "
            "FROM mant_visita_tareas t "
            "LEFT JOIN mant_visita_fotos f ON f.tarea_id=t.id "
            "WHERE t.visita_id=%s AND t.requiere_foto=1 "
            + _ot_tarea_no_trabajable_sql("t.") +
            " AND NOT (t.valor_json IS NOT NULL AND (JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.na')) = 'true' OR JSON_UNQUOTE(JSON_EXTRACT(t.valor_json, '$.valor')) = 'na')) "
            "GROUP BY t.id, t.titulo "
            "HAVING COUNT(f.id) = 0",
            (vid,)
        ) or []
    except Exception as _e_r3:
        print(f"[validar_cierre][R3] vid={vid} no se pudo verificar fotos "
              f"por tarea: {_e_r3}", flush=True)
        tareas_sin_foto = []

    if tareas_sin_foto:
        nombres = [t.get("titulo") or f"#{t['id']}" for t in tareas_sin_foto[:5]]
        suf = "" if len(tareas_sin_foto) <= 5 else f" y {len(tareas_sin_foto)-5} más"
        razones.append(
            f"Falta foto en {len(tareas_sin_foto)} tarea(s): {', '.join(nombres)}{suf}"
        )

    # R4 — Las 3 firmas (en trabajo interno no hay cliente que firme)
    if not v.get("firma_cliente_url") and not _ot_es_interna(v):
        razones.append("Falta firma del cliente.")
    if not v.get("firma_tecnico_url"):    razones.append("Falta firma del técnico.")
    if not v.get("firma_supervisor_url"): razones.append("Falta firma del supervisor.")

    # ── R5 — EVIDENCIA FOTOGRÁFICA MÍNIMA DE LA OT (Daniel 2026-08-09) ──
    # "No quiero que el técnico cierre la OT sin fotos... veo OT sin fotos."
    #
    # R3 (arriba) solo mira tareas con requiere_foto=1: si la plantilla del
    # checklist no marcó ninguna, R3 pasa con 0 fotos y la OT se cierra sin
    # una sola evidencia. Esto pone un piso a nivel de OT COMPLETA.
    #
    # Se suman las DOS fuentes reales de fotos, porque según el tipo de OT el
    # técnico carga en una u otra:
    #   · mant_visita_fotos          → fotos del checklist / tareas
    #   · mant_levantamiento_fotos   → fotos de los equipos capturados en terreno
    # Sin sumar la segunda, toda OT de levantamiento quedaría bloqueada
    # injustamente aunque el técnico haya fotografiado cada equipo.
    n_fotos_ot = 0
    try:
        _min_fotos = int((_reglas_cargar() or {}).get("ot_min_fotos_cierre") or 0)
    except Exception:
        _min_fotos = 0
    if _min_fotos > 0:
        try:
            # Se cuentan fotos ÚNICAS, no filas (Daniel 2026-08-09: "¿será
            # posible que reconozca si suben la misma foto 4 veces?"). Con
            # COUNT(DISTINCT foto_hash) cuatro copias de la misma imagen
            # cuentan como 1 sola evidencia. COALESCE con el id hace que las
            # filas SIN hash (fotos históricas, anteriores a esta migración)
            # sigan contando como únicas: no se castiga trabajo ya hecho.
            _f1 = mysql_fetchone(
                "SELECT COUNT(DISTINCT COALESCE(foto_hash, CONCAT('id:', id))) AS n "
                "  FROM mant_visita_fotos WHERE visita_id=%s", (vid,)
            ) or {}
            _f2 = mysql_fetchone(
                "SELECT COUNT(DISTINCT COALESCE(lf.foto_hash, CONCAT('id:', lf.id))) AS n "
                "  FROM mant_levantamiento_fotos lf "
                "  JOIN mant_levantamientos lv ON lv.id = lf.levantamiento_id "
                " WHERE lv.visita_id = %s OR lv.id = %s",
                (vid, v.get("levantamiento_id") or 0)
            ) or {}
            n_fotos_ot = int(_f1.get("n") or 0) + int(_f2.get("n") or 0)
            if n_fotos_ot < _min_fotos:
                razones.append(
                    f"Evidencia fotográfica insuficiente: la OT tiene {n_fotos_ot} foto(s) "
                    f"distinta(s) y se exigen al menos {_min_fotos}. "
                    "Sube fotos reales del trabajo antes de cerrar "
                    "(repetir la misma imagen no cuenta)."
                )
        except Exception as _fot_e:
            # FAIL-OPEN deliberado: si el conteo falla (tabla ausente en un
            # entorno, timeout, etc.) NO dejamos al técnico trabado en terreno
            # por un problema de infraestructura. Se registra y se sigue.
            print(f"[_ot_validar_cierre][min_fotos] {_fot_e}", flush=True)

    # Aviso (NUNCA bloqueo) de las tareas que quedaron fuera del conteo por
    # tener el equipo dado de baja — ver _ot_tarea_no_trabajable_sql(). Van
    # en `avisos` y no en `razones` a propósito: `razones` es la lista de lo
    # que impide cerrar, y esto no impide nada; solo deja constancia de que
    # la OT cerró con trabajo no ejecutado sobre equipos retirados.
    _n_baja, _eq_baja = _ot_tareas_excluidas_por_baja(vid)
    avisos = []
    if _n_baja:
        avisos.append(
            f"{_n_baja} tarea(s) de {_eq_baja} equipo(s) dados de baja no se "
            f"exigen para cerrar: sus tarjetas ya no se dibujan en la OT, "
            f"así que nadie puede marcarlas. Si el equipo sigue en la sala, "
            f"restáuralo desde la papelera del cliente y vuelven a pedirse."
        )

    return {
        "puede_cerrar": len(razones) == 0,
        "razones": razones,
        "avisos": avisos,
        "total_tareas": total,
        "tareas_completadas": done,
        "tareas_sin_foto": len(tareas_sin_foto),
        "tiene_diagnostico": bool((v.get("diagnostico") or "").strip()),
        "firmas_ok": all([v.get("firma_cliente_url"), v.get("firma_tecnico_url"), v.get("firma_supervisor_url")]),
        "equipos_excluidos": len(excluir_maquinas),
        "tareas_excluidas_baja": _n_baja,
        "equipos_baja": _eq_baja,
        "fotos_ot": n_fotos_ot,
        "min_fotos_ot": _min_fotos,
    }


@app.route("/mantenciones/api/visitas/<int:vid>/validacion-cierre", methods=["GET"])
@_mant_required
@_ot_can_view
def mant_visita_validacion_cierre(vid):
    """Endpoint que devuelve si la OT cumple las 4 reglas de cierre.
    El frontend lo llama para mostrar el estado del cierre antes de
    intentar cerrar — feedback inmediato al técnico."""
    return jsonify({"ok": True, **_ot_validar_cierre(vid)})


@app.route("/mantenciones/api/visitas/<int:vid>/cerrar", methods=["POST"])
@_mant_required
@_tecnico_owns_visita
def mant_visita_cerrar(vid):
    """Cierra la visita aplicando las 4 reglas de cierre auditable (FASE 5).
    Bloquea cierre si falta alguna:
      R1. Checklist 100% completado
      R2. Diagnóstico (mín 20 chars, excepto levantamientos)
      R3. Foto en tareas requiere_foto=1
      R4. Las 3 firmas (cliente, técnico, supervisor)
    """
    v = _ot_visita_basic(vid)
    if not v:
        return jsonify({"ok": False, "error": "OT no encontrada"}), 404

    d = request.get_json(silent=True) or {}

    # Si llega un diagnóstico en este request, guardarlo ANTES de validar
    # (para que el técnico pueda cerrar en un solo paso con el modal)
    diag_nuevo = (d.get("diagnostico") or "").strip()
    if diag_nuevo:
        mysql_execute(
            "UPDATE mant_visitas SET diagnostico=%s WHERE id=%s",
            (diag_nuevo[:5000], vid)
        )

    # Aplicar las 4 reglas de cierre auditable
    validacion = _ot_validar_cierre(vid)
    if not validacion["puede_cerrar"]:
        return jsonify({
            "ok": False,
            "error": "No se puede cerrar la OT — faltan requisitos:",
            "error_codigo": "CIERRE_BLOQUEADO",
            "razones": validacion["razones"],
            "validacion": validacion,
        }), 400

    causa = (d.get("causa_raiz") or "").strip().lower() or None
    if causa and causa not in ("desgaste","mal_uso","falta_mantencion","defecto_fabrica","accidente","otro"):
        causa = "otro"
    estrellas = d.get("satisfaccion_estrellas")
    try:
        estrellas = int(estrellas) if estrellas not in (None, "") else None
        if estrellas is not None and (estrellas < 1 or estrellas > 5):
            estrellas = max(1, min(5, estrellas))
    except (TypeError, ValueError):
        estrellas = None
    comentario = (d.get("comentario") or "").strip()[:1000] or None
    user = current_username()
    mysql_execute(
        "UPDATE mant_visitas "
        "   SET estado='cerrada', "
        "       cerrada_at=NOW(), "
        "       cerrada_por=%s, "
        "       causa_raiz=COALESCE(%s, causa_raiz), "
        "       satisfaccion_estrellas=COALESCE(%s, satisfaccion_estrellas), "
        "       satisfaccion_comentario=COALESCE(%s, satisfaccion_comentario), "
        "       hora_real_fin=COALESCE(hora_real_fin, NOW()) "
        " WHERE id=%s",
        (user, causa, estrellas, comentario, vid)
    )
    try:
        mysql_execute(
            "INSERT INTO mant_logs (entidad, entidad_id, accion, detalle, usuario) "
            "VALUES ('visita', %s, 'cerrada', %s, %s)",
            (vid,
             f"OT cerrada (auditable) — causa: {causa or '—'} · "
             f"estrellas: {estrellas or '—'} · "
             f"{validacion['tareas_completadas']}/{validacion['total_tareas']} tareas · "
             f"firmas: {'OK' if validacion['firmas_ok'] else 'INCOMPLETO'}",
             user)
        )
    except Exception:
        pass
    # ── 2026-05-21 (Daniel) — Trazabilidad por equipo ──────────────────
    # Al cerrar la OT, todo equipo que esté en mant_visita_tareas pero
    # que NO tenga fila en mant_visita_equipos se inserta como
    # 'verificado' (default). Esto deja audit trail aunque el técnico
    # haya cerrado sin tocar nada en ese equipo.
    try:
        mysql_execute(
            "INSERT IGNORE INTO mant_visita_equipos "
            "  (visita_id, maquina_id, estado_revision, revisado_at, revisado_por) "
            "SELECT DISTINCT vt.visita_id, vt.maquina_id, 'verificado', NOW(), %s "
            "  FROM mant_visita_tareas vt "
            " WHERE vt.visita_id=%s AND vt.maquina_id IS NOT NULL",
            (user, vid)
        )
    except Exception as _e_vme:
        print(f"[ot_cerrar] mant_visita_equipos autofill error: {_e_vme}", flush=True)

    # ── Promoción levantamiento → ficha de equipo (async, no bloquea) ──
    # Aplica cuando la visita es tipo='levantamiento' O tiene levantamiento_id
    # poblado (caso Vitacura — preventiva creada desde modal del cliente).
    # El wrapper interno (_promover_levantamiento_a_maquina) hace el filtro
    # fino y descarta silenciosamente si no corresponde.
    # 2026-06-23: _lev_promover_full_async además MATERIALIZA los equipos
    # descubiertos en terreno (items sin maquina_id) antes de promover.
    _lev_promover_full_async(vid, usuario=user)
    # Sincronizar estado del ticket vinculado (si lo hay). Aditivo -- nunca
    # debe romper el cierre de la OT si falla.
    try:
        _tk_set_estado_automatico = globals().get("_tk_set_estado_automatico")
        if _tk_set_estado_automatico:
            _tk_row = mysql_fetchone("SELECT id FROM tk_tickets WHERE visita_id=%s", (vid,))
            if _tk_row:
                _tk_set_estado_automatico(
                    _tk_row["id"], "resolved",
                    "OT cerrada con las 3 firmas y checklist completo", visita_id=vid)
    except Exception as _e_tk_est:
        print(f"[mant_visita_cerrar] sync estado ticket fallo vid={vid}: {_e_tk_est}", flush=True)
    return jsonify({
        "ok": True,
        "estado": "cerrada",
        "validacion": validacion,
        "mensaje": "OT cerrada exitosamente con auditoría completa.",
    })


# ══════════════════════════════════════════════════════════════════════
# TRAZABILIDAD POR EQUIPO EN VISITA (2026-05-21 Daniel)
# Permite que el técnico SALTE un equipo durante el levantamiento sin
# completar sus tareas, marque "con cambios" o "falla detectada", o
# deje una observación libre. Cada decisión queda con audit trail.
# ══════════════════════════════════════════════════════════════════════

# 2026-08-12 (Daniel — "mínimo ~10 caracteres, mismo estándar que ya usa
# el proyecto para motivos obligatorios"): unifica el mínimo de la
# observación de saltar/marcar equipo con el resto de motivos obligatorios
# del proyecto (garantía retroactiva, "sin costo", etc. — todos exigen 10).
# Antes esta pantalla pedía solo 5; quedaba más laxo que el resto sin razón.
_MOTIVO_MIN_CHARS = 10

# Razones válidas para saltar un equipo. Cualquier otra cae como 'otro'.
_RAZONES_SALTADO_VALIDAS = (
    "no_encontrado", "dado_de_baja", "danado_inaccesible",
    "cliente_lo_quito", "otro",
    # 2026-05-31 (Fase 3 — cobertura de tareas): causales ampliadas. Una tarea/
    # equipo no ejecutado debe quedar con una causal clara + observación
    # obligatoria (ya exigida, mín. 5 chars). No se borran las antiguas (compat).
    "sin_acceso", "cliente_no_permite", "equipo_en_uso", "sin_energia",
    "requiere_repuesto", "reagendar", "no_aplica",
)

# Estados válidos para el campo estado_revision.
_ESTADOS_REVISION_VALIDOS = (
    "verificado", "con_cambios", "saltado", "falla_detectada"
)


def _ot_visita_equipo_link_ok(vid, mid):
    """Valida que el equipo `mid` pertenezca realmente a la visita `vid`
    (ya sea via mant_visita_tareas o mant_visita_equipos previo). Evita
    que un técnico marque equipos ajenos a su OT (IDOR)."""
    try:
        r = mysql_fetchone(
            "SELECT 1 FROM mant_visita_tareas "
            " WHERE visita_id=%s AND maquina_id=%s LIMIT 1",
            (vid, mid)
        )
        if r:
            return True
        # Fallback: ya estaba registrado en mant_visita_equipos
        r2 = mysql_fetchone(
            "SELECT 1 FROM mant_visita_equipos "
            " WHERE visita_id=%s AND maquina_id=%s LIMIT 1",
            (vid, mid)
        )
        return bool(r2)
    except Exception:
        return False


@app.route(
    "/mantenciones/api/visitas/<int:vid>/equipos/<int:mid>/saltar",
    methods=["POST"]
)
@_mant_required
@_tecnico_owns_visita
def mant_visita_equipo_saltar(vid, mid):
    """El técnico salta un equipo durante la OT: registra razón +
    observación obligatoria (mín 10 chars — mismo estándar que el resto
    del proyecto para motivos obligatorios, ver _MOTIVO_MIN_CHARS).
    Idempotente vía upsert.
    """
    if not _ot_visita_equipo_link_ok(vid, mid):
        return jsonify({"ok": False, "error": "Equipo no pertenece a esta OT"}), 404

    d = request.get_json(silent=True) or {}
    razon_raw = (d.get("razon") or "").strip().lower()
    razon = razon_raw if razon_raw in _RAZONES_SALTADO_VALIDAS else "otro"
    obs = (d.get("observacion") or "").strip()
    if len(obs) < _MOTIVO_MIN_CHARS:
        return jsonify({
            "ok": False,
            "error": f"La observación es obligatoria (mínimo {_MOTIVO_MIN_CHARS} caracteres)."
        }), 400
    obs = obs[:2000]  # cap razonable

    user = current_username()
    try:
        mysql_execute(
            "INSERT INTO mant_visita_equipos "
            "  (visita_id, maquina_id, estado_revision, razon_saltado, "
            "   observacion_tecnico, revisado_at, revisado_por) "
            "VALUES (%s, %s, 'saltado', %s, %s, NOW(), %s) "
            "ON DUPLICATE KEY UPDATE "
            "  estado_revision='saltado', "
            "  razon_saltado=VALUES(razon_saltado), "
            "  observacion_tecnico=VALUES(observacion_tecnico), "
            "  revisado_at=NOW(), "
            "  revisado_por=VALUES(revisado_por)",
            (vid, mid, razon, obs, user)
        )
    except Exception as e:
        print(f"[visita_equipo_saltar] error vid={vid} mid={mid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar el saltado"}), 500

    # Audit log
    try:
        _mant_log(
            "visita", vid, "equipo_saltado",
            f"Equipo #{mid} saltado por {user} — razón: {razon} · {obs[:150]}"
        )
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "visita_id": vid,
        "maquina_id": mid,
        "estado_revision": "saltado",
        "razon": razon,
        "observacion": obs,
        "revisado_por": user,
    })


@app.route(
    "/mantenciones/api/visitas/<int:vid>/equipos/<int:mid>/marcar",
    methods=["POST"]
)
@_mant_required
@_tecnico_owns_visita
def mant_visita_equipo_marcar(vid, mid):
    """Cambia el estado de revisión del equipo en la visita sin requerir
    completar tareas. Estados: verificado | con_cambios | saltado |
    falla_detectada. Si es 'falla_detectada' o 'saltado', exige
    observación mín 5 chars.
    """
    if not _ot_visita_equipo_link_ok(vid, mid):
        return jsonify({"ok": False, "error": "Equipo no pertenece a esta OT"}), 404

    d = request.get_json(silent=True) or {}
    estado = (d.get("estado_revision") or "").strip().lower()
    if estado not in _ESTADOS_REVISION_VALIDOS:
        return jsonify({
            "ok": False,
            "error": f"estado_revision inválido (debe ser uno de: "
                     f"{', '.join(_ESTADOS_REVISION_VALIDOS)})"
        }), 400

    obs = (d.get("observacion") or "").strip()[:2000]
    razon_raw = (d.get("razon") or "").strip().lower()
    razon = razon_raw if razon_raw in _RAZONES_SALTADO_VALIDAS else None

    # Obs obligatoria para estados problemáticos (mismo estándar de 10
    # caracteres que el resto del proyecto — ver _MOTIVO_MIN_CHARS).
    if estado in ("saltado", "falla_detectada") and len(obs) < _MOTIVO_MIN_CHARS:
        return jsonify({
            "ok": False,
            "error": f"La observación es obligatoria para este estado (mín {_MOTIVO_MIN_CHARS} caracteres)."
        }), 400

    user = current_username()
    try:
        mysql_execute(
            "INSERT INTO mant_visita_equipos "
            "  (visita_id, maquina_id, estado_revision, razon_saltado, "
            "   observacion_tecnico, revisado_at, revisado_por) "
            "VALUES (%s, %s, %s, %s, %s, NOW(), %s) "
            "ON DUPLICATE KEY UPDATE "
            "  estado_revision=VALUES(estado_revision), "
            "  razon_saltado=VALUES(razon_saltado), "
            "  observacion_tecnico=COALESCE(VALUES(observacion_tecnico), observacion_tecnico), "
            "  revisado_at=NOW(), "
            "  revisado_por=VALUES(revisado_por)",
            (vid, mid, estado, razon, (obs or None), user)
        )
    except Exception as e:
        print(f"[visita_equipo_marcar] error vid={vid} mid={mid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar el estado"}), 500

    try:
        _mant_log(
            "visita", vid, "equipo_estado_revision",
            f"Equipo #{mid} → {estado} por {user}"
            + (f" · razón={razon}" if razon else "")
            + (f" · {obs[:120]}" if obs else "")
        )
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "visita_id": vid,
        "maquina_id": mid,
        "estado_revision": estado,
        "razon": razon,
        "observacion": obs or None,
        "revisado_por": user,
    })


@app.route(
    "/mantenciones/api/visitas/<int:vid>/equipos/<int:mid>/observacion",
    methods=["POST"]
)
@_mant_required
@_tecnico_owns_visita
def mant_visita_equipo_observacion(vid, mid):
    """Guarda observación libre del técnico sobre este equipo en esta
    visita, sin cambiar el estado_revision (queda como esté, default
    'verificado'). Pensado para el textarea siempre visible en
    ot_ejecutar.html con auto-save al perder foco.
    """
    if not _ot_visita_equipo_link_ok(vid, mid):
        return jsonify({"ok": False, "error": "Equipo no pertenece a esta OT"}), 404

    d = request.get_json(silent=True) or {}
    obs = (d.get("observacion") or "").strip()[:2000]
    user = current_username()
    try:
        if obs:
            # Hay observación: INSERT si no existe (sin tocar estado si ya existe).
            mysql_execute(
                "INSERT INTO mant_visita_equipos "
                "  (visita_id, maquina_id, estado_revision, "
                "   observacion_tecnico, revisado_at, revisado_por) "
                "VALUES (%s, %s, 'verificado', %s, NOW(), %s) "
                "ON DUPLICATE KEY UPDATE "
                "  observacion_tecnico=VALUES(observacion_tecnico), "
                "  revisado_at=NOW(), "
                "  revisado_por=VALUES(revisado_por)",
                (vid, mid, obs, user)
            )
        else:
            # Obs vacía: solo borra la obs en fila existente, no crea fila nueva.
            mysql_execute(
                "UPDATE mant_visita_equipos "
                "SET observacion_tecnico=NULL, revisado_at=NOW(), revisado_por=%s "
                "WHERE visita_id=%s AND maquina_id=%s",
                (user, vid, mid)
            )
    except Exception as e:
        print(f"[visita_equipo_observacion] error vid={vid} mid={mid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar la observación"}), 500

    # No logueamos cada keystroke; solo si la observación es nueva o se vació.
    return jsonify({
        "ok": True,
        "visita_id": vid,
        "maquina_id": mid,
        "observacion": obs or "",
        "revisado_por": user,
    })


# Estados válidos del diagnóstico técnico por equipo. Ver
# _ensure_mant_visita_equipos_diagnostico_cols para el porqué de mantenerlo
# separado de _ESTADOS_REVISION_VALIDOS.
_DIAGNOSTICO_ESTADOS_VALIDOS = ("aprobado", "observacion", "falla")


@app.route(
    "/mantenciones/api/visitas/<int:vid>/equipos/<int:mid>/diagnostico",
    methods=["POST"]
)
@_mant_required
@_tecnico_owns_visita
def mant_visita_equipo_diagnostico(vid, mid):
    """Diagnóstico técnico del equipo en esta visita: aprobado / observación
    / falla + texto. Es el "¿qué está aprobado y desaprobado?" que Daniel
    pidió poder resumir en la OT (2026-08-12) — DISTINTO de estado_revision
    (que es el flujo de saltar/verificar la visita del equipo, no el
    veredicto técnico sobre su estado). Ver comentario en
    _ensure_mant_visita_equipos_diagnostico_cols.

    'aprobado' no exige texto (puede ser un simple visto bueno). 'observacion'
    y 'falla' exigen texto (mín _MOTIVO_MIN_CHARS) para quedar trazable en
    el resumen de la visita, mismo estándar que el resto de motivos
    obligatorios del proyecto.

    BORRADOR: modelo sujeto a revisión de Daniel una vez que vea el flujo
    funcionando.
    """
    if not _ot_visita_equipo_link_ok(vid, mid):
        return jsonify({"ok": False, "error": "Equipo no pertenece a esta OT"}), 404

    d = request.get_json(silent=True) or {}
    estado = (d.get("estado") or "").strip().lower()
    if estado not in _DIAGNOSTICO_ESTADOS_VALIDOS:
        return jsonify({
            "ok": False,
            "error": f"estado inválido (debe ser uno de: "
                     f"{', '.join(_DIAGNOSTICO_ESTADOS_VALIDOS)})"
        }), 400

    texto = (d.get("texto") or "").strip()
    if estado in ("observacion", "falla") and len(texto) < _MOTIVO_MIN_CHARS:
        return jsonify({
            "ok": False,
            "error": f"Describe el diagnóstico (mínimo {_MOTIVO_MIN_CHARS} caracteres)."
        }), 400
    texto = texto[:3000]

    user = current_username()
    try:
        mysql_execute(
            "INSERT INTO mant_visita_equipos "
            "  (visita_id, maquina_id, estado_revision, "
            "   diagnostico_estado, diagnostico_texto, revisado_at, revisado_por) "
            "VALUES (%s, %s, 'verificado', %s, %s, NOW(), %s) "
            "ON DUPLICATE KEY UPDATE "
            "  diagnostico_estado=VALUES(diagnostico_estado), "
            "  diagnostico_texto=VALUES(diagnostico_texto), "
            "  revisado_at=NOW(), "
            "  revisado_por=VALUES(revisado_por)",
            (vid, mid, estado, (texto or None), user)
        )
    except Exception as e:
        print(f"[visita_equipo_diagnostico] error vid={vid} mid={mid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar el diagnóstico"}), 500

    try:
        _mant_log(
            "visita", vid, "equipo_diagnostico",
            f"Equipo #{mid} diagnóstico → {estado} por {user}"
            + (f" · {texto[:150]}" if texto else "")
        )
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "visita_id": vid,
        "maquina_id": mid,
        "diagnostico_estado": estado,
        "diagnostico_texto": texto or None,
        "revisado_por": user,
    })


@app.route(
    "/mantenciones/api/visitas/<int:vid>/equipos-estado",
    methods=["GET"]
)
@_mant_required
@_ot_can_view
def mant_visita_equipos_estado(vid):
    """Devuelve el estado de revisión de cada equipo en la visita.
    Usado por ot_ejecutar.html para pintar los badges al cargar.
    """
    rows = mysql_fetchall(
        "SELECT maquina_id, estado_revision, razon_saltado, "
        "       observacion_tecnico, revisado_at, revisado_por, "
        "       diagnostico_estado, diagnostico_texto "
        "  FROM mant_visita_equipos WHERE visita_id=%s",
        (vid,)
    ) or []
    out = {}
    for r in rows:
        out[str(r["maquina_id"])] = {
            "estado_revision":      r.get("estado_revision") or "verificado",
            "razon_saltado":        r.get("razon_saltado") or "",
            "observacion_tecnico":  r.get("observacion_tecnico") or "",
            "revisado_at":          str(r["revisado_at"])[:19] if r.get("revisado_at") else "",
            "revisado_por":         r.get("revisado_por") or "",
            "diagnostico_estado":   r.get("diagnostico_estado") or "",
            "diagnostico_texto":    r.get("diagnostico_texto") or "",
        }
    return jsonify({"ok": True, "equipos": out})


@app.route(
    "/mantenciones/api/maquinas/<int:mid>/revisiones",
    methods=["GET"]
)
@_mant_required
def mant_maquina_revisiones(mid):
    """Devuelve TODAS las revisiones que ha tenido este equipo en visitas
    (timeline cronológico). Usado por el modal de ficha técnica del equipo
    (tab "Revisiones"). Incluye cambios de serial detectados en el
    audit log para enriquecer el historial.
    """
    # Permisos: técnico solo ve si la máquina está en una OT asignada.
    u = getattr(g, "user", None) or {}
    role_u = (u.get("role") or "").lower()
    if role_u in ("tecnico", "tecnico_externo"):
        uid = u.get("id")
        autorizado = mysql_fetchone(
            "SELECT 1 FROM mant_visita_tareas vt "
            "  JOIN mant_visitas v ON v.id = vt.visita_id "
            " WHERE vt.maquina_id=%s "
            "   AND (v.tecnico_user_id=%s "
            "        OR v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
            "                    WHERE tecnico_user_id=%s)) "
            " LIMIT 1",
            (mid, uid, uid)
        )
        if not autorizado:
            return jsonify({"ok": False, "error": "Equipo no asignado a tus OTs"}), 403

    # Datos de cada revisión, joineando con la visita y técnico.
    rows = mysql_fetchall(
        "SELECT ve.id, ve.visita_id, ve.estado_revision, ve.razon_saltado, "
        "       ve.observacion_tecnico, ve.revisado_at, ve.revisado_por, "
        "       v.numero_ot, v.tipo AS visita_tipo, v.fecha_programada, "
        "       v.estado AS visita_estado, "
        "       (SELECT COUNT(*) FROM mant_visita_fotos f "
        "          WHERE f.visita_id=v.id AND f.maquina_id=%s) AS fotos_count "
        "  FROM mant_visita_equipos ve "
        "  JOIN mant_visitas v ON v.id = ve.visita_id "
        " WHERE ve.maquina_id=%s "
        " ORDER BY COALESCE(ve.revisado_at, v.fecha_programada) DESC, ve.id DESC "
        " LIMIT 100",
        (mid, mid)
    ) or []

    timeline = []
    counters = {
        "total": 0, "verificado": 0, "con_cambios": 0,
        "saltado": 0, "falla_detectada": 0,
    }
    for r in rows:
        estado = (r.get("estado_revision") or "verificado").lower()
        counters["total"] += 1
        counters[estado] = counters.get(estado, 0) + 1
        timeline.append({
            "visita_id":     r["visita_id"],
            "numero_ot":     r.get("numero_ot") or f"VS-{r['visita_id']:05d}",
            "tipo_visita":   r.get("visita_tipo") or "",
            "estado_visita": r.get("visita_estado") or "",
            "fecha":         str(r["fecha_programada"])[:10] if r.get("fecha_programada") else "",
            "revisado_at":   str(r["revisado_at"])[:16] if r.get("revisado_at") else "",
            "revisado_por":  r.get("revisado_por") or "",
            "estado_revision": estado,
            "razon_saltado": r.get("razon_saltado") or "",
            "observacion":   r.get("observacion_tecnico") or "",
            "fotos_count":   int(r.get("fotos_count") or 0),
            "url_ot":        f"/mantenciones/ot/{r['visita_id']}",
        })

    # Última revisión = primer elemento del timeline (mayor fecha)
    ultima = timeline[0] if timeline else None

    return jsonify({
        "ok": True,
        "maquina_id": mid,
        "ultima_revision": ultima,
        "contadores": counters,
        "timeline": timeline,
    })


# ── VISITAS / AGENDA ──────────────────────────────────────────────────

@app.route("/mantenciones/api/visitas", methods=["GET"])
@_mant_required
def mant_visitas_api():
    """
    Devuelve visitas enriquecidas para el calendario inteligente.
    Cada evento incluye: cliente, dirección, técnicos N:N, horario, costo,
    modalidad_cobro y prioridad (FASE 8).

    Filtros opcionales:
      start, end, cliente_id, tecnico_id  (existentes)
      modalidad_cobro  (FASE 8: pagado|garantia|sin_costo|interno)
      prioridad        (FASE 8: baja|media|alta|urgente)
      tipo             (FASE 8: tipo OT específico)
      estado           (FASE 8: filtrar por estado)
    """
    desde = request.args.get("start", "")
    hasta = request.args.get("end", "")
    cid   = request.args.get("cliente_id")
    tid   = request.args.get("tecnico_id")
    mod   = (request.args.get("modalidad_cobro") or "").strip().lower()
    pri   = (request.args.get("prioridad") or "").strip().lower()
    tipo_f = (request.args.get("tipo") or "").strip().lower()
    estado_f = (request.args.get("estado") or "").strip().lower()
    where, params = [], []
    # 🔐 SEGURIDAD (2026-05-17 / refuerzo 2026-05-22 Aaron Urbina):
    # Filtramos el calendario por rol con el MISMO criterio que el listado
    # (`mant_ots_list`). Si el rol no puede ver una OT en el listado,
    # tampoco debe verla como evento en el calendario.
    #
    # BRECHA detectada 2026-05-22 (Daniel): el calendario mostraba TODAS
    # las OTs incluso a ejecutivos, mientras el listado las filtraba. Aaron
    # entraba a OTs ajenas vía calendario aunque no aparecían en su lista.
    # Esto era un IDOR de lectura.
    #
    # Reglas (coherentes con _puede_ot_accion('ver') y mant_ots_list):
    #  - admin / supervisor / superadmin → ven TODO (sin filtro)
    #  - ejecutivo → solo creadas por él (created_by_user_id, created_by
    #    por username y por nombre) O asignadas a él (tecnico_user_id,
    #    colaborador en mant_visita_tecnicos)
    #  - tecnico / tecnico_externo → solo asignadas (principal o colab.)
    #  - resto (lector/editor/etc.) → nada (1=0) — el decorador
    #    @_mant_required ya las debería bloquear; cinturón + tirantes.
    u = getattr(g, "user", None) or {}
    role_raw = (u.get("role") or "").lower()
    role_fam = _rol_familia(role_raw)
    uid = u.get("id")
    if role_fam in ("admin", "superadmin", "supervisor"):
        pass  # Sin filtro de rol — ven todo
    elif role_fam == "ejecutivo":
        # Mismo criterio que el listado en mant_ots_list
        username_actual = (u.get("username") or "").strip()
        nombre_actual = (u.get("nombre") or "").strip()
        # Detectar columna `created_by_user_id` (post-migración)
        _has_cbu = False
        try:
            _col_check = mysql_fetchone(
                "SELECT COUNT(*) AS n FROM INFORMATION_SCHEMA.COLUMNS "
                " WHERE TABLE_SCHEMA = DATABASE() "
                "   AND TABLE_NAME = 'mant_visitas' "
                "   AND COLUMN_NAME = 'created_by_user_id'"
            )
            _has_cbu = bool((_col_check or {}).get("n"))
        except Exception:
            _has_cbu = False
        clauses = []
        if _has_cbu and uid:
            clauses.append("v.created_by_user_id=%s")
            params.append(int(uid))
        if username_actual:
            clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            params.append(username_actual)
        if nombre_actual and nombre_actual.lower() != username_actual.lower():
            clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            params.append(nombre_actual)
        if uid:
            clauses.append("v.tecnico_user_id=%s")
            params.append(int(uid))
            clauses.append(
                "v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
                "         WHERE tecnico_user_id=%s)"
            )
            params.append(int(uid))
        if clauses:
            where.append("(" + " OR ".join(clauses) + ")")
        else:
            where.append("1=0")
    elif role_fam == "tecnico":
        if uid:
            where.append(
                "(v.tecnico_user_id=%s OR EXISTS("
                "  SELECT 1 FROM mant_visita_tecnicos vt "
                "   WHERE vt.visita_id=v.id AND vt.tecnico_user_id=%s))"
            )
            params.extend([int(uid), int(uid)])
        else:
            # Sin uid no puede ver nada
            where.append("1=0")
    else:
        # Rol desconocido — denegar lectura (defense in depth)
        where.append("1=0")
    # FIX 2026-07-15: antes filtraba solo por fecha_programada >= desde, así
    # que una OT multi-día ya iniciada (fecha_programada < desde <= fecha_fin)
    # desaparecía del fetch aunque siguiera vigente en el rango visible. Mismo
    # criterio COALESCE(fecha_fin, fecha_programada) que _validar_disponibilidad_visita
    # (línea ~38266). `hasta` queda igual (se sigue filtrando por el inicio).
    if desde: where.append("COALESCE(v.fecha_fin, v.fecha_programada) >= %s"); params.append(desde[:10])
    if hasta: where.append("v.fecha_programada <= %s"); params.append(hasta[:10])
    if cid:   where.append("v.cliente_id=%s"); params.append(int(cid))
    if tid:   where.append(
        "v.id IN (SELECT visita_id FROM mant_visita_tecnicos WHERE tecnico_id=%s)"
    ); params.append(int(tid))
    # FASE 8: filtros nuevos (validados contra ENUMs)
    if mod in ("pagado", "garantia", "sin_costo", "interno"):
        where.append("v.modalidad_cobro=%s"); params.append(mod)
    if pri in ("baja", "media", "alta", "urgente"):
        where.append("v.prioridad=%s"); params.append(pri)
    if tipo_f:
        where.append("v.tipo=%s"); params.append(tipo_f)
    if estado_f:
        where.append("v.estado=%s"); params.append(estado_f)

    sql = ("""SELECT v.*, c.razon_social, c.direccion, c.comuna, c.region,
                (SELECT COUNT(*) FROM mant_visita_tareas WHERE visita_id=v.id) AS n_tareas,
                (SELECT COUNT(*) FROM mant_visita_tareas WHERE visita_id=v.id AND completada=1) AS n_completas
                FROM mant_visitas v
                JOIN mant_clientes c ON c.id=v.cliente_id""")
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY v.fecha_programada, v.hora_inicio LIMIT 500"
    rows = mysql_fetchall(sql, tuple(params)) or []
    rows = [dict(r) for r in rows]

    # Cargar técnicos N:N de todas las visitas en una sola query
    tecs_por_visita = {}
    if rows:
        vids = [r["id"] for r in rows]
        ph = ",".join(["%s"] * len(vids))
        tec_rows = mysql_fetchall(
            f"""SELECT vt.visita_id, t.id, t.nombre, t.especialidad, t.nivel,
                       t.es_externo, t.foto_url
                  FROM mant_visita_tecnicos vt
                  JOIN mant_tecnicos t ON t.id=vt.tecnico_id
                 WHERE vt.visita_id IN ({ph})
                 ORDER BY t.nombre""",
            tuple(vids)
        ) or []
        for tr in tec_rows:
            tecs_por_visita.setdefault(tr["visita_id"], []).append({
                "id":           tr["id"],
                "nombre":       tr["nombre"],
                "especialidad": tr["especialidad"],
                "nivel":        tr["nivel"],
                "es_externo":   bool(tr.get("es_externo")),
                "foto_url":     tr.get("foto_url"),
            })

    # Colores por TIPO (mantención preventiva, correctiva, etc.) — FASE 8 expandido
    TIPO_COLOR = {
        "preventiva":     "#16a34a",  # verde
        "correctiva":     "#dc2626",  # rojo
        "garantia":       "#2563eb",  # azul (tipo legacy)
        "inspeccion":     "#f59e0b",  # ámbar
        "levantamiento":  "#7c2d12",  # marrón rojizo
        "instalacion":    "#0891b2",  # cyan
        "visita_tecnica": "#6366f1",  # índigo
        "visita_correctiva": "#be123c",  # rojo oscuro
        "cambio_equipo":  "#9333ea",  # violeta
        "desinstalacion": "#737373",  # gris
        "capacitacion":   "#ca8a04",  # mostaza
        "repuesto":       "#0d9488",  # teal
        "revision_interna": "#475569",  # slate
    }
    EST_BORDER = {
        "creada":              "#94a3b8",
        "programada":          "#0f172a",
        "asignada":            "#3b82f6",
        "en_curso":            "#f59e0b",
        "en_ejecucion":        "#f59e0b",
        "pendiente_info":      "#a855f7",
        "pendiente_repuesto":  "#ec4899",
        "pendiente_aprobacion":"#fb7185",
        "completada":          "#166534",
        "cerrada":             "#15803d",
        "cancelada":           "#9ca3af",
        "anulada":             "#6b7280",
        "reagendada":          "#7c3aed",
    }
    # FASE 8: colores por MODALIDAD DE COBRO (banda lateral del evento)
    MODALIDAD_COLOR = {
        "pagado":    "#16a34a",  # verde — ingreso confirmado
        "garantia":  "#dc2626",  # rojo — atención costo cubierto
        "sin_costo": "#9ca3af",  # gris — operación gratuita
        "interno":   "#7c3aed",  # violeta — operación ILUS
    }
    # FASE 8: prioridad — borde grueso colorido
    PRIORIDAD_COLOR = {
        "baja":    "#10b981",
        "media":   "#3b82f6",
        "alta":    "#f59e0b",
        "urgente": "#dc2626",
    }

    # 🔧 PERF (N+1 -> batch, auditoria 2026-07-18): el fallback de tecnico_id
    # legacy hacía 1 mysql_fetchone POR CADA visita sin técnicos N:N (hasta
    # 500 queries). Igual que la carga N:N de arriba, se recolectan todos los
    # tecnico_id legacy que hacen falta y se cargan con UNA sola query IN,
    # mapeando en memoria. Resultado por visita idéntico al de antes.
    legacy_tecnico_ids = sorted({
        r["tecnico_id"] for r in rows
        if not tecs_por_visita.get(r["id"]) and r.get("tecnico_id")
    })
    tecnicos_legacy_por_id = {}
    if legacy_tecnico_ids:
        ph_leg = ",".join(["%s"] * len(legacy_tecnico_ids))
        leg_rows = mysql_fetchall(
            f"""SELECT id,nombre,especialidad,nivel,es_externo,foto_url
                  FROM mant_tecnicos WHERE id IN ({ph_leg})""",
            tuple(legacy_tecnico_ids)
        ) or []
        tecnicos_legacy_por_id = {lr["id"]: dict(lr) for lr in leg_rows}

    events = []
    for r in rows:
        tecs = tecs_por_visita.get(r["id"], [])
        # Si no hay técnicos N:N pero sí hay tecnico_id legacy, fallback
        if not tecs and r.get("tecnico_id"):
            t_legacy = tecnicos_legacy_por_id.get(r["tecnico_id"])
            if t_legacy:
                tecs = [dict(t_legacy)]
        # Para visitas viejas con solo el campo texto `tecnico`
        elif not tecs and r.get("tecnico"):
            tecs = [{"id": None, "nombre": r["tecnico"], "especialidad": None,
                     "nivel": None, "es_externo": False, "foto_url": None}]

        # Helper para serializar hora (puede venir como timedelta o string)
        def _h(v):
            if v is None: return None
            if hasattr(v, "total_seconds"):
                t = int(v.total_seconds())
                return f"{t//3600:02d}:{(t%3600)//60:02d}"
            s = str(v)
            return s[:5] if len(s) >= 5 else s

        events.append({
            "id":          r["id"],
            "title":       r["titulo"] or (r.get("tipo","").capitalize() + " programada"),
            "fecha":       str(r["fecha_programada"]) if r["fecha_programada"] else None,
            "fecha_fin":   (str(r["fecha_fin"]) if r.get("fecha_fin") else None),
            "hora_inicio": _h(r.get("hora_inicio")),
            "hora_fin":    _h(r.get("hora_fin")),
            "tipo":        r.get("tipo"),
            "estado":      r.get("estado"),
            "descripcion": (r.get("descripcion") or "")[:300],
            "costo":       float(r.get("costo") or 0),
            "cliente": {
                "id":           r["cliente_id"],
                "razon_social": r["razon_social"],
                "direccion":    r.get("direccion") or "",
                "comuna":       r.get("comuna") or "",
                "region":       r.get("region") or "",
            },
            "tecnicos":    tecs,
            "n_tecnicos":  len(tecs),
            # FASE 8: campos nuevos en payload
            "modalidad_cobro": r.get("modalidad_cobro") or "pagado",
            "prioridad":       r.get("prioridad") or "media",
            "numero_ot":       r.get("numero_ot") or "",
            "levantamiento_id":r.get("levantamiento_id"),
            # RITMO 2026-06-11: el front necesita distinguir históricas y la
            # cobertura REAL (antes mostraba badge "Contrato" para todo porque
            # estos campos no viajaban). SIN defaults: null se respeta.
            "es_retroactiva":     bool(r.get("es_retroactiva")),
            "cubierto_por":       r.get("cubierto_por"),
            "estado_facturacion": r.get("estado_facturacion"),
            "fecha_realizada":    (str(r["fecha_realizada"])[:10]
                                   if r.get("fecha_realizada") else ""),
            "color_tipo":      TIPO_COLOR.get(r.get("tipo"), "#6b7280"),
            "color_borde":     EST_BORDER.get(r.get("estado"), "#0f172a"),
            "color_modalidad": MODALIDAD_COLOR.get(r.get("modalidad_cobro") or "pagado", "#9ca3af"),
            "color_prioridad": PRIORIDAD_COLOR.get(r.get("prioridad") or "media", "#3b82f6"),
            # 2026-07-15: % de avance del checklist (mant_visita_tareas), para
            # el strip de progreso + badge "hecho/total" del calendario grande.
            "n_tareas":    r.get("n_tareas") or 0,
            "n_tareas_ok": r.get("n_completas") or 0,
            "avance_pct":  round(100 * (r.get("n_completas") or 0) / r["n_tareas"]) if r.get("n_tareas") else None,
        })
    return jsonify(events)


@app.route("/mantenciones/api/clientes/<int:cid>/ritmo-mantencion", methods=["GET"])
@_mant_required
def mant_cliente_ritmo_mantencion(cid):
    """RITMO DE MANTENCIÓN (2026-06-11): ventana de 12 meses (mes actual
    incluido, orden cronológico ASC) con recomendadas vs realizadas vs
    agendadas por mes, para el gráfico de ritmo de la ficha del cliente.

    Reusa la MISMA cadena del Agente intel (_cliente_inteligencia):
      frecuencia: contrato.frecuencia_meses → ai_frecuencia_sug → regla
                  'frecuencia_default_meses' (3).
      ancla:      contrato.fecha_inicio → contrato.created_at → primera
                  visita realizada. Robusto SIN contrato (estimado:true).
    El mes de cada proyección = mes de la fecha AJUSTADA (día preferido +
    día hábil — regla de oro de _mant_fecha_ajustada).

    SIEMPRE responde 200: errores como {ok:false, error:'mensaje amigable'}
    (nunca 500 con detalles internos)."""
    from datetime import datetime as _dt
    # Mismos universos de estados que el planificador anual:
    _REALIZADA = ("completada", "cerrada")
    _AGENDADA = ("programada", "reagendada", "asignada", "en_curso",
                 "en_ejecucion", "pendiente_info", "pendiente_repuesto",
                 "pendiente_aprobacion")
    _MES_ABBR = ["Ene", "Feb", "Mar", "Abr", "May", "Jun",
                 "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"]
    try:
        try:
            cli = mysql_fetchone(
                "SELECT id, dia_mantencion_pref FROM mant_clientes WHERE id=%s", (cid,))
        except Exception:
            # Pre-migración: dia_mantencion_pref aún no existe
            cli = mysql_fetchone("SELECT id FROM mant_clientes WHERE id=%s", (cid,))
        if not cli:
            return jsonify({"ok": False, "error": "Cliente no encontrado."})
        cli = dict(cli)
        R = _reglas_cargar()
        hoy = _dt.now().date()

        # Ventana: 12 meses terminando en el mes actual (ASC).
        primero_mes_actual = hoy.replace(day=1)
        ventana = [_intel_add_months(primero_mes_actual, -(11 - i)) for i in range(12)]
        idx = {(d.year, d.month): i for i, d in enumerate(ventana)}
        meses = [{
            "ym": f"{d.year:04d}-{d.month:02d}",
            "label": f"{_MES_ABBR[d.month - 1]} {d.year % 100:02d}",
            "recomendadas": 0, "realizadas": 0, "historicas": 0,
            "agendadas": 0, "atrasadas": 0,
        } for d in ventana]

        # Visitas del cliente (fallback si es_retroactiva aún no migró).
        try:
            vis = mysql_fetchall(
                "SELECT estado, fecha_programada, fecha_realizada, es_retroactiva "
                "  FROM mant_visitas WHERE cliente_id=%s", (cid,)) or []
        except Exception:
            vis = mysql_fetchall(
                "SELECT estado, fecha_programada, fecha_realizada "
                "  FROM mant_visitas WHERE cliente_id=%s", (cid,)) or []
        vis = [dict(v) for v in vis]

        fechas_realizadas = []
        for v in vis:
            est = (v.get("estado") or "").lower()
            f = (_intel_as_date(v.get("fecha_realizada"))
                 or _intel_as_date(v.get("fecha_programada")))
            if not f:
                continue
            i = idx.get((f.year, f.month))
            if est in _REALIZADA:
                fechas_realizadas.append(f)
                if i is not None:
                    meses[i]["realizadas"] += 1
                    if v.get("es_retroactiva"):
                        meses[i]["historicas"] += 1
            elif est in _AGENDADA and i is not None:
                meses[i]["agendadas"] += 1
                if f < hoy:
                    meses[i]["atrasadas"] += 1
        fechas_realizadas.sort()

        # Cadena frecuencia/ancla — criterio EXACTO de _cliente_inteligencia.
        ct = mysql_fetchone(
            "SELECT * FROM mant_contratos WHERE cliente_id=%s "
            "  AND estado IN ('vigente','indefinido') "
            "ORDER BY created_at DESC LIMIT 1", (cid,))
        if not ct:
            ct = mysql_fetchone(
                "SELECT * FROM mant_contratos WHERE cliente_id=%s "
                "ORDER BY created_at DESC LIMIT 1", (cid,))
        ct = dict(ct) if ct else None

        frecuencia = None; freq_origen = "regla_default"
        if ct and ct.get("frecuencia_meses"):
            frecuencia = int(ct["frecuencia_meses"]); freq_origen = "contrato"
        elif ct and ct.get("ai_frecuencia_sug"):
            frecuencia = int(ct["ai_frecuencia_sug"]); freq_origen = "sugerida"
        if not frecuencia:
            frecuencia = int(R.get("frecuencia_default_meses") or 3)
        frecuencia = max(1, frecuencia)

        f_ini = _intel_as_date(ct.get("fecha_inicio")) if ct else None
        if ct and not f_ini:
            f_ini = _intel_as_date(ct.get("created_at"))
        f_fin = _intel_as_date(ct.get("fecha_vencimiento")) if ct else None
        ancla = f_ini or (fechas_realizadas[0] if fechas_realizadas else None)

        # recomendadas: cursor desde el ancla con _intel_add_months (avanza
        # CRUDO, cero deriva); cada proyección se cuenta en el mes de su
        # fecha AJUSTADA. esperadas = proyecciones con fecha <= hoy.
        esperadas = 0
        if ancla:
            dia_pref = cli.get("dia_mantencion_pref")
            fin_ventana = _intel_add_months(primero_mes_actual, 1)
            cursor = _intel_add_months(ancla, frecuencia)
            # Fast-forward para anclas muy viejas (saltos de `frecuencia`)
            if cursor and cursor < ventana[0]:
                saltos = _intel_meses_entre(cursor, ventana[0]) // frecuencia
                if saltos > 1:
                    cursor = _intel_add_months(cursor, (saltos - 1) * frecuencia)
            guard = 0
            while cursor and cursor < fin_ventana and guard < 60:
                guard += 1
                if f_fin and cursor > f_fin:
                    break
                fa = _mant_fecha_ajustada(cursor, dia_pref, R) or cursor
                i = idx.get((fa.year, fa.month))
                if i is not None:
                    meses[i]["recomendadas"] = min(2, meses[i]["recomendadas"] + 1)
                    if fa <= hoy:
                        esperadas += 1
                cursor = _intel_add_months(cursor, frecuencia)
        else:
            freq_origen = "sin_datos"

        realizadas_ventana = sum(m["realizadas"] for m in meses)
        pct = (min(100, int(round(100.0 * realizadas_ventana / esperadas)))
               if esperadas else 100)
        return jsonify({
            "ok": True,
            "meses": meses,
            "cumplimiento": {
                "esperadas": esperadas,
                "realizadas": realizadas_ventana,
                "pct": pct,
                "estimado": freq_origen != "contrato",
                "frecuencia_meses": (frecuencia if ancla else None),
                "frecuencia_origen": freq_origen,
            },
        })
    except Exception as e:
        print(f"[ritmo_mantencion] cid={cid}: {e}", flush=True)
        return jsonify({"ok": False,
                        "error": "No se pudo calcular el ritmo de mantención."})


# ══════════════════════════════════════════════════════════════════════
# MANTENCIONES HISTÓRICAS — backdating + cálculo de próxima visita
#
# Caso de uso: el cliente migra al sistema con historial. Hay que registrar
# visitas que YA ocurrieron (estado=completada, fecha_realizada anterior)
# y el sistema sugiere automáticamente la PRÓXIMA según la frecuencia
# del contrato.
#
# Ejemplo:
#   - Contrato: cada 3 meses
#   - Última mantención hecha: 2025-12-15
#   - Hoy: 2026-05-11
#   - Sugerencia: próxima = 2025-12-15 + 3 meses = 2026-03-15
#                 (ya pasó → marcar VENCIDA y proponer hoy + 7 días)
#                 si no había vencido → proponer la fecha calculada
# ══════════════════════════════════════════════════════════════════════

def _sugerir_proxima_visita(ultima_fecha, frecuencia_meses=None, contrato_id=None):
    """Calcula la próxima visita ideal.
    Si la próxima ya pasó, sugiere fecha de catch-up (hoy + 7 días).
    Devuelve dict con detalles."""
    from datetime import date, datetime, timedelta
    import calendar as _cal

    # Normalizar última fecha a date
    if isinstance(ultima_fecha, datetime):
        ultima_d = ultima_fecha.date()
    elif isinstance(ultima_fecha, date):
        ultima_d = ultima_fecha
    elif isinstance(ultima_fecha, str):
        try: ultima_d = datetime.strptime(ultima_fecha[:10], "%Y-%m-%d").date()
        except Exception: return None
    else:
        return None

    # Obtener frecuencia del contrato si no vino
    if not frecuencia_meses and contrato_id:
        try:
            row = mysql_fetchone(
                "SELECT frecuencia_meses, ai_frecuencia_sug FROM mant_contratos WHERE id=%s",
                (contrato_id,)
            )
            if row:
                frecuencia_meses = row.get("frecuencia_meses") or row.get("ai_frecuencia_sug") or 0
        except Exception:
            pass

    if not frecuencia_meses or frecuencia_meses <= 0:
        return {
            "proxima_ideal": None,
            "sin_frecuencia": True,
            "mensaje": "El contrato no tiene frecuencia definida — asigna una para que el sistema sugiera próximas visitas.",
        }

    # Sumar N meses a la última fecha
    año = ultima_d.year
    mes = ultima_d.month + int(frecuencia_meses)
    while mes > 12:
        mes -= 12
        año += 1
    # Ajustar día si el mes destino tiene menos días (ej: 31 enero + 1 mes = 28/29 feb)
    dia_max = _cal.monthrange(año, mes)[1]
    dia = min(ultima_d.day, dia_max)
    proxima_ideal = date(año, mes, dia)
    hoy = date.today()
    dias_vencimiento = (proxima_ideal - hoy).days

    estado = "futura"
    fecha_sugerida = proxima_ideal
    if dias_vencimiento < 0:
        estado = "vencida"
        # Catch-up: hoy + 7 días (ventana razonable)
        fecha_sugerida = hoy + timedelta(days=7)
    elif dias_vencimiento <= 15:
        estado = "proxima"

    return {
        "ultima_fecha": ultima_d.isoformat(),
        "frecuencia_meses": int(frecuencia_meses),
        "proxima_ideal": proxima_ideal.isoformat(),
        "fecha_sugerida": fecha_sugerida.isoformat(),
        "dias_vencimiento": dias_vencimiento,
        "estado": estado,  # vencida | proxima | futura
        "mensaje": (
            f"Última mantención: {ultima_d.strftime('%d/%m/%Y')} · "
            f"Frecuencia: cada {int(frecuencia_meses)} mes(es) · "
            + (f"Próxima IDEAL era {proxima_ideal.strftime('%d/%m/%Y')} "
               f"(VENCIDA hace {-dias_vencimiento} días) → "
               f"sugerencia: {fecha_sugerida.strftime('%d/%m/%Y')}"
               if estado == "vencida"
               else f"Próxima: {fecha_sugerida.strftime('%d/%m/%Y')}"
                    + (f" (en {dias_vencimiento} días)" if dias_vencimiento > 0 else " (HOY)"))
        ),
    }


@app.route("/mantenciones/api/clientes/<int:cid>/sugerir-proxima", methods=["GET"])
@_mant_required
def mant_sugerir_proxima(cid):
    """Devuelve la próxima visita sugerida basada en la última mantención
    completada del cliente + frecuencia del contrato más reciente.

    Útil para mostrar al usuario antes de crear una visita futura."""
    # Última visita completada del cliente
    ultima = mysql_fetchone(
        "SELECT fecha_realizada, fecha_programada, contrato_id "
        "  FROM mant_visitas "
        " WHERE cliente_id=%s AND estado='completada' "
        " ORDER BY COALESCE(fecha_realizada, fecha_programada) DESC LIMIT 1",
        (cid,)
    )

    # Frecuencia del contrato vigente más reciente
    contrato = mysql_fetchone(
        "SELECT id, frecuencia_meses, ai_frecuencia_sug "
        "  FROM mant_contratos "
        " WHERE cliente_id=%s AND estado IN ('vigente','indefinido') "
        " ORDER BY created_at DESC LIMIT 1",
        (cid,)
    )

    if not ultima:
        # Sin historial → sugerir hoy + 7 días como fecha tentativa
        from datetime import date, timedelta
        return jsonify({
            "ok": True,
            "sin_historial": True,
            "fecha_sugerida": (date.today() + timedelta(days=7)).isoformat(),
            "mensaje": "Sin historial previo — sugerencia: comenzar dentro de 7 días.",
            "frecuencia_meses": (contrato.get("frecuencia_meses") if contrato else None),
        })

    freq = None
    if contrato:
        freq = contrato.get("frecuencia_meses") or contrato.get("ai_frecuencia_sug")
    ultima_fecha = ultima.get("fecha_realizada") or ultima.get("fecha_programada")

    sug = _sugerir_proxima_visita(ultima_fecha, freq, ultima.get("contrato_id"))
    if not sug:
        return jsonify({"ok": False, "error": "No se pudo calcular"}), 500
    sug["ok"] = True
    return jsonify(sug)


@app.route("/mantenciones/api/clientes/<int:cid>/dia-preferido", methods=["GET"])
@_mant_required
def mant_cliente_dia_preferido(cid):
    """Día del mes preferido del cliente + fecha sugerida para el modal
    'Nueva visita' (BUG2).

    Devuelve `dia_mantencion_pref` (1-28 o null) y `sugerida` = próxima fecha
    en ese día del mes: ESTE mes si el día aún no pasó (dia_pref >= hoy.day),
    si no el mes siguiente. La fecha se ajusta a día hábil con la MISMA lógica
    del motor (`_mant_fecha_ajustada` → cl_feriados + fines de semana).

    Si el cliente no tiene día preferido → {ok:true, dia_mantencion_pref:null,
    sugerida:null}. Cualquier error se reporta como 200 {ok:false, error}.
    """
    try:
        cli = mysql_fetchone(
            "SELECT id, dia_mantencion_pref FROM mant_clientes WHERE id=%s",
            (cid,),
        )
        if not cli:
            return jsonify({"ok": False, "error": "Cliente no encontrado."}), 200

        dia_pref = cli.get("dia_mantencion_pref")
        try:
            dia_pref = int(dia_pref) if dia_pref is not None else None
        except (TypeError, ValueError):
            dia_pref = None
        if not dia_pref or not (1 <= dia_pref <= 28):
            return jsonify({
                "ok": True,
                "dia_mantencion_pref": None,
                "sugerida": None,
            })

        # ── Próxima fecha en el día preferido (este mes o el siguiente) ──
        hoy = _now_chile().date()
        if dia_pref >= hoy.day:
            objetivo = hoy.replace(day=dia_pref)
        else:
            # Mes siguiente (con rollover de año). dia_pref<=28 → día válido.
            if hoy.month == 12:
                objetivo = hoy.replace(year=hoy.year + 1, month=1, day=dia_pref)
            else:
                objetivo = hoy.replace(month=hoy.month + 1, day=dia_pref)

        # Ajuste a día hábil con la lógica existente del motor.
        R = _reglas_cargar()
        ajustada = _mant_fecha_ajustada(objetivo, dia_pref, R) or objetivo

        return jsonify({
            "ok": True,
            "dia_mantencion_pref": dia_pref,
            "sugerida": ajustada.isoformat(),
        })
    except Exception as exc:
        print(f"[ILUS][dia-preferido] cid={cid}: {exc}", flush=True)
        return jsonify({
            "ok": False,
            "error": "No se pudo calcular el día preferido.",
        }), 200


@app.route("/mantenciones/api/clientes/<int:cid>/visita-historica", methods=["POST"])
@_mant_required
def mant_visita_historica(cid):
    """Registra una mantención que YA ocurrió (backdating) y calcula próxima.

    Body JSON:
      fecha_realizada: 'YYYY-MM-DD' (obligatoria, fecha del pasado)
      tipo: 'preventiva' | 'correctiva' | 'garantia' | 'inspeccion'
      tecnico: string
      titulo: string opcional
      observaciones: string opcional
      costo: número opcional
      contrato_id: int opcional (si no, usa el vigente más reciente)
      crear_proxima: bool — si true, además crea automáticamente la próxima
                            visita programada en la fecha sugerida
    """
    d = request.get_json(silent=True) or {}
    from datetime import date, datetime

    fecha_real_str = (d.get("fecha_realizada") or "").strip()
    if not fecha_real_str:
        return jsonify({"ok": False, "error": "fecha_realizada requerida"}), 400
    try:
        fecha_real = datetime.strptime(fecha_real_str[:10], "%Y-%m-%d").date()
    except Exception:
        return jsonify({"ok": False, "error": "fecha_realizada con formato inválido (usa YYYY-MM-DD)"}), 400

    if fecha_real > date.today():
        return jsonify({
            "ok": False,
            "error": "La fecha realizada no puede ser futura. Usa el módulo de programar visita."
        }), 400

    # Verificar cliente
    cliente = mysql_fetchone("SELECT id FROM mant_clientes WHERE id=%s", (cid,))
    if not cliente:
        return jsonify({"ok": False, "error": "Cliente no encontrado"}), 404

    # Contrato (opcional — toma el vigente si no viene)
    contrato_id = d.get("contrato_id")
    if not contrato_id:
        ct = mysql_fetchone(
            "SELECT id FROM mant_contratos "
            "WHERE cliente_id=%s AND estado IN ('vigente','indefinido') "
            "ORDER BY created_at DESC LIMIT 1", (cid,)
        )
        if ct:
            contrato_id = ct.get("id")

    titulo = (d.get("titulo") or "Mantención histórica").strip()[:200]
    tipo = (d.get("tipo") or "preventiva").strip().lower()
    if tipo not in ("preventiva", "correctiva", "garantia", "inspeccion"):
        tipo = "preventiva"
    tecnico = (d.get("tecnico") or "").strip()[:200]
    observ  = (d.get("observaciones") or "").strip()
    costo   = float(d.get("costo") or 0)

    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO mant_visitas
                   (cliente_id, contrato_id, titulo, fecha_programada, fecha_realizada,
                    tipo, estado, tecnico, observaciones, costo, created_by)
                   VALUES (%s,%s,%s,%s,%s,%s,'completada',%s,%s,%s,%s)""",
                (cid, contrato_id, titulo, fecha_real, fecha_real,
                 tipo, tecnico, observ, costo, current_username())
            )
            vid_historica = cur.lastrowid
        conn.commit()
        try:
            _mant_log("visita", vid_historica, "registrada_historica",
                      f"Mantención de {fecha_real.strftime('%d/%m/%Y')} retroactiva")
        except Exception: pass
    finally:
        conn.close()

    # ─── Calcular próxima sugerida ───
    freq = None
    if contrato_id:
        ctr = mysql_fetchone(
            "SELECT frecuencia_meses, ai_frecuencia_sug FROM mant_contratos WHERE id=%s",
            (contrato_id,)
        )
        if ctr:
            freq = ctr.get("frecuencia_meses") or ctr.get("ai_frecuencia_sug")

    sugerencia = _sugerir_proxima_visita(fecha_real, freq, contrato_id) or {}

    # ─── Si se pidió, crear automáticamente la próxima ───
    proxima_creada = None
    if d.get("crear_proxima") and sugerencia.get("fecha_sugerida"):
        try:
            conn2 = get_mysql()
            with conn2.cursor() as cur:
                cur.execute(
                    """INSERT INTO mant_visitas
                       (cliente_id, contrato_id, titulo, fecha_programada,
                        tipo, estado, created_by)
                       VALUES (%s,%s,%s,%s,%s,'programada',%s)""",
                    (cid, contrato_id,
                     f"Mantención preventiva (sugerida por sistema)",
                     sugerencia["fecha_sugerida"], tipo, current_username())
                )
                proxima_creada = cur.lastrowid
            conn2.commit()
            conn2.close()
            try:
                _mant_log("visita", proxima_creada, "programada_auto",
                          f"Generada por sistema tras mantención histórica {vid_historica}")
            except Exception: pass
        except Exception as e:
            print(f"[mant_visita_historica] error creando próxima: {e}")

    return jsonify({
        "ok": True,
        "visita_historica_id": vid_historica,
        "proxima_creada_id": proxima_creada,
        "sugerencia": sugerencia,
        "mensaje": (f"Mantención del {fecha_real.strftime('%d/%m/%Y')} registrada. "
                    + (sugerencia.get("mensaje","") if sugerencia else "")),
    })


