    if row.get("resolucion") != "pendiente":
        return jsonify({"ok": False,
                        "error": f"Sugerencia ya resuelta: {row.get('resolucion')}"
                        }), 409

    ok = _sugerencia_resolver(sid, 'rechazada', motivo=motivo)
