def _anexo_dict(row):
    """Fila de mant_anexos → dict con precio_items ya decodificado."""
    import json as _json
    d = dict(row)
    try:
        d["precio_items"] = _json.loads(d.get("precio_items_json") or "[]")
    except Exception:
        d["precio_items"] = []
    return d


@app.route("/ot/<int:vid>/anexos", methods=["GET"])
@_mant_required
@_ot_can_view
def ot2_anexos_list(vid):
    """Anexos ligados a esta OT — para la ficha administrativa.

    Visible solo para gestión (el decorador @_ot_can_view ya excluye a un
    técnico no asignado; el candado de "solo administración, nunca técnico"
    que pidió Daniel se aplica acá explícitamente, porque un TÉCNICO
    asignado SÍ pasa @_ot_can_view — ver la propia OT es distinto de ver
    las condiciones comerciales que se pactaron con el proveedor)."""
    if _es_rol_tecnico():
        return jsonify({"ok": False, "error": "Los anexos son de uso administrativo."}), 403
    rows = mysql_fetchall(
        "SELECT id, numero, estado, proveedor_nombre, token, token_expira_at, "
        "       firmado_at, enviado_at, created_at "
        "  FROM mant_anexos WHERE ot_id=%s ORDER BY numero DESC", (vid,)) or []
    return jsonify({"ok": True, "anexos": [dict(r) for r in rows]})


@app.route("/ot/api/anexos", methods=["POST"])
@_mant_required
def ot2_api_anexo_crear():
    """Crea un anexo en borrador. No envía nada todavía."""
    if _es_rol_tecnico():
        return jsonify({"ok": False, "error": "Los anexos son de uso administrativo."}), 403
    d = request.get_json(silent=True) or {}
    proveedor = (d.get("proveedor_nombre") or "").strip()[:200]
    if not proveedor:
        return _ot2_err("Falta el nombre del proveedor.", "PROVEEDOR_REQUERIDO")
    objetivo = (d.get("objetivo_servicio") or "").strip()
    if not objetivo:
        return _ot2_err("Falta el objetivo del servicio.", "OBJETIVO_REQUERIDO")
    items = d.get("precio_items") or []
    if not isinstance(items, list) or not items:
        return _ot2_err("Agrega al menos un ítem de precio.", "PRECIO_REQUERIDO")
    try:
        items = [{"concepto": str(it.get("concepto") or "")[:120],
                  "monto": int(it.get("monto") or 0)} for it in items]
    except (TypeError, ValueError):
        return _ot2_err("Algún monto no es válido.", "MONTO_INVALIDO")

    vid = d.get("ot_id")
    try:
        vid = int(vid) if vid else None
    except (TypeError, ValueError):
        vid = None

    import json as _json
    try:
        conn = get_mysql()
        conn.autocommit(False)
        cur = conn.cursor()
        numero = _next_anexo_numero_atomic(conn)
        cur.execute(
            "INSERT INTO mant_anexos "
            "  (numero, ot_id, tecnico_externo_id, proveedor_nombre, proveedor_rut, "
            "   proveedor_direccion, "
            "   cliente_nombre, objetivo_servicio, precio_items_json, "
            "   fecha_inicio, fecha_termino, niveles_servicio, hitos_pago, "
            "   alcance_servicio, clausulas_adicionales, created_by) "
            "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
            (numero, vid, d.get("tecnico_externo_id") or None,
             proveedor, (d.get("proveedor_rut") or "").strip()[:20] or None,
             (d.get("proveedor_direccion") or "").strip()[:400] or None,
             (d.get("cliente_nombre") or "").strip()[:200] or None,
             objetivo, _json.dumps(items),
             d.get("fecha_inicio") or None, d.get("fecha_termino") or None,
             (d.get("niveles_servicio") or "").strip() or _ANEXO_NIVELES_DEFECTO,
             (d.get("hitos_pago") or "").strip() or _ANEXO_HITOS_DEFECTO,
             (d.get("alcance_servicio") or "").strip() or _ANEXO_ALCANCE_DEFECTO,
             (d.get("clausulas_adicionales") or "").strip() or _ANEXO_CLAUSULAS_DEFECTO,
             current_username()))
        aid = cur.lastrowid
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        print(f"[anexo_crear] {e}", flush=True)
        return _ot2_err("No pudimos crear el anexo.", "ERROR_INTERNO", http=500)
    finally:
        try: conn.close()
        except Exception: pass

    try:
        _mant_log("anexo", aid, "creado", f"N°{numero} · {proveedor}"
                  + (f" · OT {vid}" if vid else ""))
    except Exception:
        pass
    return jsonify({"ok": True, "anexo_id": aid, "numero": numero})


@app.route("/ot/api/anexos/<int:aid>/enviar", methods=["POST"])
@_mant_required
def ot2_api_anexo_enviar(aid):
    """Genera el token y envía el enlace de firma al proveedor.

    Canal: correo siempre; WhatsApp opcional vía deep-link (mismo patrón
    honesto que la firma remota de OT — el servidor NO envía WhatsApp por
    su cuenta, arma el link y quien lo manda es una persona)."""
    if _es_rol_tecnico():
        return jsonify({"ok": False, "error": "Los anexos son de uso administrativo."}), 403
    a = mysql_fetchone("SELECT * FROM mant_anexos WHERE id=%s", (aid,))
    if not a:
        return jsonify({"ok": False, "error": "Anexo no encontrado"}), 404
    if a["estado"] not in ("borrador",):
        return jsonify({"ok": False, "error": f"Este anexo ya está en estado "
                        f"'{a['estado']}' — no se puede reenviar así."}), 400

    d = request.get_json(silent=True) or {}
    email_destino = (d.get("email") or "").strip()[:200]
    telefono = (d.get("telefono") or "").strip()

    token = secrets.token_urlsafe(30)[:40]
    expira = datetime.utcnow() + timedelta(days=15)
    try:
        mysql_execute(
            "UPDATE mant_anexos SET token=%s, token_expira_at=%s, estado='enviado', "
            "  enviado_at=NOW(), enviado_por=%s WHERE id=%s",
            (token, expira, current_username(), aid))
    except Exception as e:
        print(f"[anexo_enviar] {e}", flush=True)
        return _ot2_err("No pudimos generar el enlace.", "ERROR_INTERNO", http=500)

    # 🔔 Daniel 2026-08-26: "notificar por correo que se creó una nueva OT
    # para el técnico, y adjunto tiene que ir el link para que firme el
    # anexo... si eso no [pasa] no puede realizar el trabajo, ni siquiera
    # vería la OT". Un solo correo cumple las dos cosas: avisa la OT nueva
    # Y trae el link que la desbloquea — no dos correos separados que se
    # puedan desincronizar. Los datos de la OT son opcionales (un anexo
    # puede no estar ligado a una OT todavía) para no romper ese caso.
    _ot_ctx = ""
    _v = None
    if a.get("ot_id"):
        try:
            _v = mysql_fetchone(
                "SELECT v.numero_ot, v.titulo, c.razon_social "
                "  FROM mant_visitas v LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
                " WHERE v.id=%s", (a["ot_id"],))
        except Exception:
            _v = None
        if _v:
            _ot_ctx = (f"<p>Se te asignó la orden de trabajo "
                       f"<b>{_v.get('numero_ot') or ('#' + str(a['ot_id']))}</b>"
                       + (f" — {_v['titulo']}" if _v.get("titulo") else "")
                       + (f" (cliente: {_v['razon_social']})" if _v.get("razon_social") else "")
                       + ".</p>")

    link = url_for("ot2_anexo_firma_publica", token=token, _external=True)

    # 🆕 Daniel 2026-08-29 (por voz, probando el wizard de OT 2.0 en vivo):
    # pidió una plantilla EDITABLE (comm_templates) para este correo, con el
    # link del anexo Y el link a la orden de trabajo preseleccionada — antes
    # salía 100% hardcodeado en Python. Solo aplica cuando el anexo SÍ está
    # ligado a una OT (a['ot_id']): sin OT no hay nada que enlazar y seguimos
    # con el flujo de siempre, más abajo.
    #
    # El link a la OT apunta a la ficha normal (mant_ot_ficha), NO a un
    # mecanismo nuevo: esa pantalla YA está protegida por el mismo candado
    # _anexo_bloquea_ot que usa _puede_ot_accion (~línea 50992) para
    # 'ver'/'ejecutar'/etc — si el proveedor entra antes de firmar, el
    # sistema lo bloquea solo. No hace falta (ni conviene) inventar un token
    # de acceso sin sesión para esto.
    _tpl_anexo = None
    if a.get("ot_id") and _v:
        _link_ot = url_for("mant_ot_ficha", vid=a["ot_id"], _external=True)
        _variables_anexo = {
            "proveedor_nombre": a.get("proveedor_nombre") or "",
            "numero_anexo": a["numero"],
            "numero_ot": _v.get("numero_ot") or f"#{a['ot_id']}",
            "ot_titulo": _v.get("titulo") or "",
            "cliente_nombre": _v.get("razon_social") or "",
            "link_anexo": link,
            "link_ot": _link_ot,
        }
        try:
            _tpl_anexo = _render_comm_template("anexo_nueva_ot", "email",
                                               _variables_anexo, modulo="mantenciones")
        except Exception as _e_tpl:
            print(f"[anexo_enviar] plantilla no disponible, uso HTML inline: {_e_tpl}", flush=True)

    enviado_correo = False
    if email_destino:
        try:
            if _tpl_anexo:
                _asunto_base, _cuerpo_tpl = _tpl_anexo
                _asunto_base = (_asunto_base or "").strip() or \
                    f"Nueva orden de trabajo — firma el Anexo N° {a['numero']}"
                _html_final = _comm_render_email_document(
                    _asunto_base, _cuerpo_tpl,
                    subtitle=f"Anexo N° {a['numero']}")
                _send_ilus_email(email_destino, _brand_subject(_asunto_base), _html_final)
            else:
                # Fallback hardcodeado histórico — se mantiene TAL CUAL (REGLA
                # #4.2): garantiza que el correo SIEMPRE sale aunque la
                # plantilla no exista, esté apagada, o el anexo no tenga OT.
                _send_ilus_email(
                    email_destino,
                    _brand_subject(f"Nueva orden de trabajo — firma el Anexo N° {a['numero']}"),
                    f"<p>Hola,</p>"
                    f"{_ot_ctx}"
                    f"<p><b>Antes de poder empezar</b> necesitamos que revises y firmes "
                    f"el Anexo de Servicios N° {a['numero']} con las condiciones del trabajo. "
                    f"Mientras no esté firmado, no podrás ver ni iniciar la orden de trabajo.</p>"
                    f'<p><a href="{link}">Revisar y firmar el Anexo N° {a["numero"]}</a></p>'
                    f"<p>El enlace vence en 15 días.</p>")
            enviado_correo = True
        except Exception as e:
            print(f"[anexo_enviar] correo: {e}", flush=True)

    wa_link = None
    if telefono:
        import urllib.parse as _up
        msg = (f"🔧 ILUS · Anexo de Servicios N° {a['numero']}\n\n"
               f"Antes de iniciar el trabajo, necesitamos que revises y firmes "
               f"el anexo:\n{link}\n\n— ILUS Fitness")
        wa_link = f"https://wa.me/{re.sub(r'[^0-9]', '', telefono)}?text={_up.quote(msg)}"

    try:
        _mant_log("anexo", aid, "enviado",
                  f"correo={'sí' if enviado_correo else 'no'} · wa_link={'sí' if wa_link else 'no'}")
    except Exception:
        pass
    return jsonify({"ok": True, "link": link, "correo_enviado": enviado_correo,
                    "whatsapp_link": wa_link})


def _anexo_fecha_d(v):
    """DATE de mant_anexos → dd/mm/aaaa (REGLA #6). Son columnas DATE puras,
    sin zona horaria que convertir — mismo criterio que el resto del
    proyecto para este tipo de campo (ver `_d()` en el reporte Excel)."""
    try:
        return v.strftime("%d/%m/%Y") if v else "—"
    except Exception:
        return "—"


def _anexo_publico_payload(a):
    return {
        "numero": a["numero"],
        "fecha": chile_fmt_filter(a.get("created_at"), "%d/%m/%Y") if a.get("created_at") else "—",
        "proveedor_nombre": a.get("proveedor_nombre") or "",
        "proveedor_rut": a.get("proveedor_rut") or "",
        "proveedor_direccion": a.get("proveedor_direccion") or "",
        "objetivo_servicio": a.get("objetivo_servicio") or "",
        "cliente_nombre": a.get("cliente_nombre") or "",
        "precio_items": a.get("precio_items") or [],
        "fecha_inicio": _anexo_fecha_d(a.get("fecha_inicio")),
        "fecha_termino": _anexo_fecha_d(a.get("fecha_termino")),
        "niveles_servicio": a.get("niveles_servicio") or "",
        "hitos_pago": a.get("hitos_pago") or "",
        "alcance_servicio": a.get("alcance_servicio") or "",
        "clausulas_adicionales": a.get("clausulas_adicionales") or "",
    }


def _anexo_precio_texto(items):
    """Mismo formato que usa `_anexo_render_canonico` (no se toca esa función
    -- es la base del hash de verificación, y ya puede haber anexos firmados
    en producción que dependen de su salida exacta). Esta es una copia
    aislada, solo para el documento imprimible/PDF, donde cambiar el texto
    no invalida ninguna firma ya hecha."""
    items = items or []
    return " - ".join(
        f"${int(it.get('monto') or 0):,}".replace(",", ".") + f" ({it.get('concepto','')})"
        for it in items) or "—"


def _anexo_pdf_header_footer_native(numero, cliente_nombre=""):
    """Header/footer NATIVOS de Playwright para el PDF del Anexo de Servicios
    -- MISMO mecanismo que ya usa `_ot_pdf_header_footer_native` (ver ese
    comentario, OT-2026-00058): `display_header_footer` + header_template/
    footer_template hace que Chromium repita este HTML en TODA página física
    real, a diferencia de un `<div class="doc-header">` incrustado en el
    flujo del documento, que solo aparece en la primera hoja.

    2026-08-30 (Daniel, viendo el PDF real: "el header no continúa como
    corresponde... la página dos no tiene header, así que esto se tiene que
    repetir constante por hojas"): el Anexo tenía el header como bloque
    normal del documento (`.doc-header` en anexo_documento.html) -- se
    reemplaza por este mecanismo nativo, calcado del compacto de la OT
    (`_ot_pdf_header_footer_native(grande=False)`), con "ANEXO DE SERVICIOS"
    en vez de "ORDEN DE TRABAJO". Todo estilo va INLINE a propósito: el
    header/footer corre aislado, sin acceso al <style> del documento
    principal (mismo criterio ya documentado ahí)."""
    import html as _html
    numero_txt = _html.escape(str(numero or ""))
    cliente_txt = _html.escape((cliente_nombre or "").strip())
    logo_ilus = _logo_data_url() or ""
    logo_shs = _logo_shs_pdf_data_url() or ""

    # 🔴 2026-08-31 (Daniel: "el logo de ILUS sale desproporcionado, sale
    # más pequeño... hazlo crecer un 80% más"): 11mm→20mm (+82%), y el
    # cuadro blanco de SHS crece a la par (13.4mm→24mm) para que sigan
    # viéndose como un mismo conjunto -- no se agranda uno solo y se
    # desbalancea el header. El padding sube de 3mm a 4mm para que el
    # logo más grande no quede pegado al borde de su propia franja negra.
    # 🔴 2026-09-01 (Daniel, viendo el PDF real de nuevo: "necesito que el
    # logo de ILUS lo hagas crecer un 80%, que se vea tan grande como el
    # de Sport Health"): 20mm→30mm. El PNG de ILUS trae más aire/margen
    # transparente alrededor de la marca que el de SHS, así que a igual
    # altura de contenedor se ve más chico -- para compensar eso de raíz
    # habría que recortar el archivo de imagen (fuera del alcance de un
    # cambio de código); mientras tanto se sube la altura del contenedor.
    _ilus_logo_html = (
        f'<img src="{logo_ilus}" style="height:28mm;max-width:90mm;object-fit:contain;">'
        if logo_ilus else
        '<span style="font-weight:900;font-size:15px;color:#ffffff;'
        'letter-spacing:.02em;">ILUS<span style="color:#dc2626;">.</span></span>'
    )
    _shs_logo_html = (
        '<div style="height:26mm;background:#ffffff;border-radius:1mm;'
        'box-sizing:border-box;padding:1.5mm 3mm;display:flex;align-items:center;'
        f'justify-content:center;"><img src="{logo_shs}" '
        'style="height:22mm;width:auto;object-fit:contain;"></div>'
        if logo_shs else ""
    )
    header_html = (
        '<div style="width:100%;font-family:Arial,Helvetica,sans-serif;">'
        '<div style="background:#0a0a0a;padding:4mm 12mm;box-sizing:border-box;'
        'display:flex;justify-content:space-between;align-items:center;'
        '-webkit-print-color-adjust:exact;print-color-adjust:exact;">'
        f'<div style="display:flex;align-items:center;gap:3mm;">'
        f'{_shs_logo_html}{_ilus_logo_html}</div>'
        '<div style="text-align:right;max-width:100mm;min-width:0;overflow:hidden;">'
        '<div style="font-size:10px;font-weight:800;color:#ffffff;'
        'letter-spacing:-.01em;">ANEXO DE SERVICIOS</div>'
        f'<div style="font-size:13px;font-weight:900;color:#dc2626;'
        f'line-height:1.15;">N&#176; {numero_txt}</div>'
        + (f'<div style="font-size:8.5px;font-weight:700;color:#e5e7eb;'
           'line-height:1.2;margin-top:.5mm;white-space:nowrap;overflow:hidden;'
           f'text-overflow:ellipsis;">{cliente_txt}</div>' if cliente_txt else '') +
        '</div></div>'
        '<div style="height:1.4mm;background:linear-gradient(90deg,#dc2626 0 25%,'
        '#0a0a0a 25% 100%);-webkit-print-color-adjust:exact;'
        'print-color-adjust:exact;"></div>'
        '</div>'
    )
    footer_html = (
        '<div style="width:100%;font-size:7px;font-family:Arial,Helvetica,sans-serif;'
        'color:#6b7280;padding:3px 12mm 0;box-sizing:border-box;display:flex;'
        'justify-content:space-between;align-items:center;border-top:1.5px solid #dc2626;">'
        '<span><b style="color:#0a0a0a">ILUS Fitness</b> · Sport and Health Solutions SPA · '
        'soportetec@sphs.cl</span>'
        f'<span><b style="color:#0a0a0a">Anexo N&#176; {numero_txt}</b> · Página '
        '<span class="pageNumber"></span> de <span class="totalPages"></span></span>'
        '</div>'
    )
    return header_html, footer_html


@app.route("/ot/api/anexos/<int:aid>/pdf", methods=["GET"])
@_mant_required
def ot2_api_anexo_pdf(aid):
    """Descarga el Anexo en PDF con fidelidad al Word real que Daniel firma
    hoy con los proveedores (Isabel Milling, Daniel Pulgar): fecha arriba a
    la derecha, título centrado, párrafos justificados Objetivo/Precio/
    Duración/Niveles/Hitos/Alcance, firma al pie -- MISMO layout, no una
    interpretación libre (pedido explícito de Daniel, 2026-08-26 noche).

    Ojo: esto NO reemplaza `anexo_firma.html` (esa sigue siendo la
    experiencia de FIRMA del proveedor, diseñada con Fable -- no se toca).
    Este PDF es el documento para archivo/contabilidad, generado con el
    mismo motor Playwright que ya usa el resto del proyecto (_pw_pdf)."""
    if _es_rol_tecnico():
        return jsonify({"ok": False, "error": "Los anexos son de uso administrativo."}), 403
    a = mysql_fetchone("SELECT * FROM mant_anexos WHERE id=%s", (aid,))
    if not a:
        return jsonify({"ok": False, "error": "Anexo no encontrado"}), 404
    a = _anexo_dict(a)
    payload = _anexo_publico_payload(a)
    firma = None
    if a.get("estado") == "firmado":
        firma = {
            "firmante_nombre": a.get("firmante_nombre") or a.get("proveedor_nombre"),
            "firmante_rut": a.get("firmante_rut") or a.get("proveedor_rut"),
            "firma_url": a.get("firma_url"),
            "firmado_en": chile_fmt_filter(a.get("firmado_at"), "%d/%m/%Y %H:%M") if a.get("firmado_at") else "",
        }
    # 🆕 2026-08-31 (Daniel: "los productos los estipulen en una tabla, que
    # me pueda evidenciar tanto SKU, descripción y cantidad"): distinto del
    # desglose de PRECIO por concepto (precio_items_json, ya existía) --
    # esto son los equipos físicos a los que aplica el servicio. Se reusan
    # los equipos YA asociados a la OT (mant_visita_tareas.maquina_id, "la
    # fuente universal de qué equipo tiene una OT", ver comentario en
    # app.py ~68765) en vez de pedirle a alguien que los vuelva a tipear a
    # mano -- si el anexo no tiene OT (proveedor sin OT ligada todavía),
    # simplemente no sale la tabla, no se inventa una captura manual nueva.
    productos = []
    if a.get("ot_id"):
        try:
            productos = mysql_fetchall(
                "SELECT DISTINCT m.sku, m.nombre, COALESCE(m.cantidad,1) AS cantidad "
                "  FROM mant_visita_tareas t "
                "  JOIN mant_maquinas m ON m.id = t.maquina_id "
                " WHERE t.visita_id=%s AND t.maquina_id IS NOT NULL "
                " ORDER BY m.nombre", (a["ot_id"],)) or []
            productos = [dict(p) for p in productos]
        except Exception as e:
            print(f"[anexo_pdf] productos de la OT: {e}", flush=True)
            productos = []
    html = render_template(
        "ot2/anexo_documento.html",
        anexo=payload,
        precio_txt=_anexo_precio_texto(payload.get("precio_items")),
        firma=firma,
        productos=productos,
        generado_en=_now_chile_str("%d/%m/%Y %H:%M"),
    )
    try:
        # 2026-08-30 (Daniel: "el header no continúa... la página dos no
        # tiene header, así que esto se tiene que repetir constante por
        # hojas"): header/footer nativos de Chromium (ver
        # _anexo_pdf_header_footer_native) -- se repiten en TODA página
        # física real, no solo en la primera. margin.top ~26mm da espacio
        # real al header (~20mm de alto); bottom 14mm al footer de una
        # línea (mismas medidas ya probadas en el compacto de la OT).
        _hdr, _ftr = _anexo_pdf_header_footer_native(a.get("numero"), a.get("cliente_nombre"))
        data = _pw_pdf(html, page_format="Letter",
                        margin={"top": "40mm", "right": "14mm", "bottom": "16mm", "left": "14mm"},
                        header_template=_hdr, footer_template=_ftr)
    except PDFEngineUnavailable as e:
        return (f"Motor PDF no disponible: {e}", 503)
    except Exception as e:
        print(f"[anexo_pdf] {e}", flush=True)
        return ("No pudimos generar el PDF del anexo.", 500)

    try:
        _mant_log("anexo", aid, "pdf_descargado", f"N°{a['numero']}")
    except Exception:
        pass
    # 🔴 2026-08-31 (Daniel: "el nombre no ayuda en nada... necesito que
    # diga anexo, ILUS, número tal"): nombre genérico "anexo-servicios-148"
    # no dice a qué OT/cliente pertenece cuando hay varios PDF descargados
    # en la misma carpeta -- se arma con el cliente (mismo slug ya usado
    # para familias de checklist, reutilizado acá).
    _cli_slug = _slugify_familia_checklist(a.get("cliente_nombre") or "")
    fname = f"Anexo-ILUS-{a['numero']}" + (f"-{_cli_slug}" if _cli_slug else "") + ".pdf"
    return Response(data, mimetype="application/pdf",
                     headers={"Content-Disposition": f'inline; filename="{fname}"'})


@app.route("/ot/api/anexos/preview-pdf", methods=["POST"])
@_mant_required
def ot2_api_anexo_preview_pdf():
    """Vista previa del Anexo ANTES de crear la OT (Daniel, textual: "necesito
    un visor en PDF de cómo va a quedar el documento... agrega un PDF al
    paso diez"). El wizard todavía no tiene ot_id ni numero real en este
    punto -- a diferencia de ot2_api_anexo_pdf (aid), esto NO toca
    mant_anexos ni graba nada: solo renderiza la MISMA plantilla
    (ot2/anexo_documento.html) con los datos que el usuario ya escribió en
    el paso Anexo, para que vea el documento exacto que se generaría al
    crear la OT. numero/fecha se muestran como placeholder porque todavía
    no existen de verdad."""
    if _es_rol_tecnico():
        return jsonify({"ok": False, "error": "Los anexos son de uso administrativo."}), 403
    d = request.get_json(silent=True) or {}
    proveedor = (d.get("proveedor_nombre") or "").strip()[:200]
    if not proveedor:
        return _ot2_err("Falta el nombre del proveedor.", "PROVEEDOR_REQUERIDO")
    objetivo = (d.get("objetivo_servicio") or "").strip()
    if not objetivo:
        return _ot2_err("Falta el objetivo del servicio.", "OBJETIVO_REQUERIDO")
    items_in = d.get("precio_items") or []
    try:
        items = [{"concepto": str(it.get("concepto") or "")[:120],
                  "monto": int(it.get("monto") or 0)} for it in (items_in if isinstance(items_in, list) else [])]
    except (TypeError, ValueError):
        items = []
    # _anexo_fecha_d() espera un objeto date/datetime (columna DATE real de
    # mant_anexos) -- acá todavía no existe fila en la tabla, así que las
    # fechas llegan como texto ISO 'YYYY-MM-DD' desde el wizard (S.fecha).
    # Se parsean a mano en vez de reusar ese helper sobre un string crudo
    # (fallaría en silencio y mostraría "—" siempre).
    def _iso_a_dmy(s):
        try:
            return datetime.strptime((s or "")[:10], "%Y-%m-%d").strftime("%d/%m/%Y")
        except Exception:
            return "—"
    payload = {
        "numero": "(vista previa)",
        "fecha": _now_chile_str("%d/%m/%Y"),
        "proveedor_nombre": proveedor,
        "proveedor_rut": (d.get("proveedor_rut") or "").strip()[:20],
        "objetivo_servicio": objetivo,
        "cliente_nombre": (d.get("cliente_nombre") or "").strip()[:200],
        "precio_items": items,
        "fecha_inicio": _iso_a_dmy(d.get("fecha_inicio")),
        "fecha_termino": _iso_a_dmy(d.get("fecha_termino")),
        "niveles_servicio": _ANEXO_NIVELES_DEFECTO,
        "hitos_pago": _ANEXO_HITOS_DEFECTO,
        "alcance_servicio": _ANEXO_ALCANCE_DEFECTO,
        "clausulas_adicionales": _ANEXO_CLAUSULAS_DEFECTO,
    }
    html = render_template(
        "ot2/anexo_documento.html",
        anexo=payload,
        precio_txt=_anexo_precio_texto(payload.get("precio_items")),
        firma=None,
        generado_en=_now_chile_str("%d/%m/%Y %H:%M"),
        es_vista_previa=True,
    )
    try:
        _hdr, _ftr = _anexo_pdf_header_footer_native("(vista previa)", payload.get("cliente_nombre"))
        data = _pw_pdf(html, page_format="Letter",
                        margin={"top": "40mm", "right": "14mm", "bottom": "16mm", "left": "14mm"},
                        header_template=_hdr, footer_template=_ftr)
    except PDFEngineUnavailable as e:
        return (f"Motor PDF no disponible: {e}", 503)
    except Exception as e:
        print(f"[anexo_preview_pdf] {e}", flush=True)
        return ("No pudimos generar la vista previa del PDF.", 500)
    _cli_slug_prev = _slugify_familia_checklist(payload.get("cliente_nombre") or "")
    _fname_prev = "Anexo-ILUS-vista-previa" + (f"-{_cli_slug_prev}" if _cli_slug_prev else "") + ".pdf"
    return Response(data, mimetype="application/pdf",
                     headers={"Content-Disposition": f'inline; filename="{_fname_prev}"'})


@app.route("/firmar-anexo/<token>", methods=["GET"])
def ot2_anexo_firma_publica(token):
    """Página pública (sin login) donde el proveedor lee y firma el anexo."""
    if not _ot_tv_token_valido(token):
        return render_template("ot2/anexo_firma.html", valido=False, ya_firmado=False)
    a = mysql_fetchone("SELECT * FROM mant_anexos WHERE token=%s", (token,))
    if not a:
        return render_template("ot2/anexo_firma.html", valido=False, ya_firmado=False)
    a = _anexo_dict(a)
    vencido = a.get("token_expira_at") and datetime.utcnow() > a["token_expira_at"]
    if vencido and a["estado"] not in ("firmado",):
        return render_template("ot2/anexo_firma.html", valido=False, ya_firmado=False)

    if a["estado"] == "firmado":
        return render_template(
            "ot2/anexo_firma.html", valido=True, ya_firmado=True,
            anexo=_anexo_publico_payload(a),
            firma={"firmante_nombre": a.get("firmante_nombre"),
                   "firmante_rut": a.get("firmante_rut"),
                   "firmado_en": chile_fmt_filter(a.get("firmado_at")) if a.get("firmado_at") else ""})

    if a["estado"] == "enviado":
        try:
            mysql_execute("UPDATE mant_anexos SET estado='visto' WHERE id=%s AND estado='enviado'",
                         (a["id"],))
        except Exception:
            pass
    return render_template(
        "ot2/anexo_firma.html", valido=True, ya_firmado=False,
        anexo=_anexo_publico_payload(a),
        submit_url=url_for("ot2_anexo_firma_submit", token=token))


@app.route("/firmar-anexo/<token>", methods=["POST"])
def ot2_anexo_firma_submit(token):
    """El proveedor firma. Token-gated, sin login (mismo patrón que /firmar-ot/).

    La página (`ot2/anexo_firma.html`) manda un POST de FORMULARIO normal
    (progressive enhancement: funciona incluso si algo del JS de captura
    falla) con estos campos exactos: firmante_nombre, firmante_rut,
    firma_png (dataURL), doc_hash (SHA-256 calculado en el navegador sobre
    el texto que el firmante realmente leyó), firmado_en_iso, dispositivo,
    declaracion_aceptada.
    """
    if not _ot_tv_token_valido(token):
        return jsonify({"ok": False, "error": "Enlace inválido."}), 400
    a = mysql_fetchone("SELECT * FROM mant_anexos WHERE token=%s", (token,))
    if not a:
        return jsonify({"ok": False, "error": "Enlace inválido."}), 404
    if a["estado"] == "firmado":
        return jsonify({"ok": False, "error": "Este anexo ya fue firmado."}), 400
    if a.get("token_expira_at") and datetime.utcnow() > a["token_expira_at"]:
        return jsonify({"ok": False, "error": "El enlace venció."}), 400

    d = request.form or {}
    nombre = (d.get("firmante_nombre") or "").strip()[:200]
    rut = (d.get("firmante_rut") or "").strip()[:20]
    firma_data_url = d.get("firma_png") or ""
    hash_cliente = (d.get("doc_hash") or "").strip()[:64]
    firmado_cliente = (d.get("firmado_en_iso") or "").strip()[:60]
    dispositivo = (d.get("dispositivo") or "").strip()[:200]
    if not str(d.get("declaracion_aceptada") or "").strip():
        return jsonify({"ok": False, "error": "Falta aceptar la declaración del anexo."}), 400
    if not nombre or not rut:
        return jsonify({"ok": False, "error": "Falta nombre o RUT de quien firma."}), 400
    if not firma_data_url.startswith("data:"):
        return jsonify({"ok": False, "error": "Falta la firma."}), 400

    a_full = _anexo_dict(a)
    # Dos huellas con propósito distinto -- no son redundantes:
    # `doc_hash` (servidor) = "estos DATOS no cambiaron desde que se firmó".
    # `hash_cliente` (navegador) = "el firmante vio y firmó ESTE texto exacto".
    doc_hash = _anexo_hash(a_full)
    firma_url = _subir_firma_storage(firma_data_url, a["id"], "proveedor_anexo")
    ip = ((request.headers.get("X-Forwarded-For") or "").split(",")[0].strip()
          or request.remote_addr or "")[:64]
    ua = (request.headers.get("User-Agent") or "")[:400]

    try:
        mysql_execute(
            "UPDATE mant_anexos SET estado='firmado', documento_hash=%s, "
            "  documento_hash_cliente=%s, firmado_en_cliente=%s, "
            "  firmante_nombre=%s, firmante_rut=%s, firma_url=%s, "
            "  firmado_at=NOW(), firmado_ip=%s, firmado_user_agent=%s "
            " WHERE id=%s AND estado IN ('enviado','visto')",
            (doc_hash, hash_cliente or None, firmado_cliente or None,
             nombre, rut, firma_url, ip, ua, a["id"]))
    except Exception as e:
        print(f"[anexo_firmar] {e}", flush=True)
        return jsonify({"ok": False, "error": "No pudimos guardar la firma."}), 500

    try:
        _mant_log("anexo", a["id"], "firmado",
                  f"{nombre} ({rut}) · hash_srv={doc_hash[:12]}… · "
                  f"hash_cli={(hash_cliente or '—')[:12]} · ip={ip} · {dispositivo}")
    except Exception:
        pass

    # 📧 2026-08-31 (Daniel, urgente: "que nos avise que ya se firmó el
    # anexo"): antes de esto, firmar el anexo no notificaba a NADIE -- la
    # única forma de enterarse era entrar a revisar uno por uno. Se avisa
    # a quien lo envió (a['enviado_por'], username -- en este proyecto es
    # el email real, ej. daniel.aguilar@sphs.cl) y si no hay o no parece un
    # email, cae al buzón de soporte genérico (REGLA #11). Best-effort: un
    # correo que falla NO debe revertir la firma ya guardada.
    try:
        _dest_aviso = (a.get("enviado_por") or a.get("created_by") or "").strip()
        if "@" not in _dest_aviso:
            _brand_aviso = _get_brand_cfg()
            _dest_aviso = _brand_aviso.get("support_email") or "soportetec@sphs.cl"
        _ot_link_aviso = url_for("mant_ot_ficha", vid=a["ot_id"], _external=True) if a.get("ot_id") else None
        _cuerpo_aviso = (
            _mant_email_hero("Anexo firmado",
                             f"N° {a['numero']}",
                             f"{a.get('proveedor_nombre') or 'El proveedor'} ya firmó") +
            _mant_email_field("Proveedor", nombre or a.get("proveedor_nombre") or "—", accent=True) +
            _mant_email_field("RUT firmante", rut or "—") +
            _mant_email_field("Fecha", chile_fmt_filter(datetime.now())) +
            ('<p style="font-size:14px;color:#374151;line-height:1.65;margin:16px 0">'
             'Ya puedes revisar el anexo firmado y, si corresponde, despachar la '
             'orden de trabajo asociada.</p>' if a.get("ot_id") else "") +
            (_mant_email_cta("Ver orden de trabajo", _ot_link_aviso) if _ot_link_aviso else "")
        )
        _send_ilus_email(
            _dest_aviso,
            _brand_subject(f"Anexo N° {a['numero']} firmado — {a.get('proveedor_nombre') or ''}".strip()),
            _comm_render_email_document(
                f"Anexo N° {a['numero']} firmado", _cuerpo_aviso,
                subtitle=a.get("proveedor_nombre") or ""))
    except Exception as _e_aviso:
        print(f"[anexo_firmar] aviso de firma no se pudo enviar: {_e_aviso}", flush=True)

    return jsonify({"ok": True, "mensaje": "Anexo firmado correctamente."})


def _anexo_bloquea_ot(vid):
    """¿Hay un anexo ligado a esta OT que todavía no está firmado?

    Única fuente de verdad para el candado de `mant_visita_iniciar`. Un
    anexo en 'borrador' (nunca se envió) NO bloquea — recién bloquea desde
    que se manda a firmar, que es cuando existe un compromiso real
    pendiente con el proveedor."""
    try:
        row = mysql_fetchone(
            "SELECT numero FROM mant_anexos WHERE ot_id=%s "
            "  AND estado IN ('enviado','visto') LIMIT 1", (vid,))
        return row["numero"] if row else None
    except Exception as e:
        print(f"[anexo_bloquea] {e}", flush=True)
        return None    # fail-open a propósito: un error de BD acá no debe
                        # dejar a TODOS los técnicos sin poder trabajar.


def _ot2_filtros_export(args):
    """WHERE + params + descripción legible de los filtros del panel OT 2.0.

    ⚠️ DEUDA CONOCIDA (2026-08-26): `ot2_panel` arma su WHERE inline y no usa
    esta función. Lo correcto sería extraerlo allá y que ambos consuman una
    sola fuente (como hace `_tk_list_where` con el listado de tickets y sus
    reportes CSV) — se dejó para después a propósito, porque `ot2_panel` es
    la pantalla que Daniel usa a diario y refactorizarla la misma semana del
    lanzamiento del monitor era riesgo innecesario.
    Mientras tanto: si se agrega un filtro al panel, agregarlo TAMBIÉN acá.

    🔴 Incluye SIEMPRE `_mant_calendario_role_where()`. Sin eso el Excel se
    convierte en la puerta de atrás de la brecha que ese filtro tapa — y peor
    que una pantalla, porque el archivo sale del sistema.
    """
    where, params, desc = [], [], []

    origen = (args.get("origen") or "reales").strip().lower()
    if origen == "automaticas":
        where.append("(v.numero_ot IS NULL OR TRIM(v.numero_ot) = '')")
        desc.append("automáticas")
    else:
        origen = "reales"
        where.append("v.numero_ot IS NOT NULL AND TRIM(v.numero_ot) <> ''")

    q = (args.get("q") or "").strip()[:120]
    if q:
        like = f"%{q}%"
        where.append("(v.numero_ot LIKE %s OR v.titulo LIKE %s "
                     " OR c.razon_social LIKE %s OR au.nombre LIKE %s)")
        params += [like, like, like, like]
        desc.append(f'búsqueda "{q}"')

    f_tipo = (args.get("tipo") or "").strip().lower()
    if f_tipo and f_tipo in _ot_tipos_todos():
        where.append("v.tipo = %s")
        params.append(f_tipo)
        desc.append(_TIPO_OT_LABEL.get(f_tipo, f_tipo))

    f_tec = (args.get("tecnico") or "").strip()
    if f_tec:
        try:
            where.append("v.tecnico_user_id = %s")
            params.append(int(f_tec))
            desc.append("un técnico")
        except (TypeError, ValueError):
            pass

    fase = (args.get("fase") or "").strip().lower()
    if fase and fase in _OT2_FASES:
        estados = _OT2_FASE_A_ESTADOS.get(fase) or ()
        if estados:
            where.append("v.estado IN (" + ",".join(["%s"] * len(estados)) + ")")
            params += list(estados)
            desc.append(_OT2_FASE_LABELS.get(fase, fase))

    # ── Centro de costo (Daniel, 27-08-2026): "qué OT están comprometidas
    # con centros de costo diferentes a Servicio Técnico". `cc=no_sstt` es
    # el segmento que le importa -- Logística, Comercial o SIN DEFINIR (un
    # centro sin definir tampoco es atribuible a SSTT por defecto). También
    # se admite un centro puntual (`cc=logistica`) para el que quiera mirar
    # uno solo.
    cc_filtro = (args.get("cc") or "").strip().lower()
    if cc_filtro == "no_sstt":
        where.append("(v.centro_costo IN ('logistica','comercial') OR v.centro_costo IS NULL)")
        desc.append("fuera de Servicio Técnico")
    elif cc_filtro in dict(_OT2_CENTROS_COSTO):
        where.append("v.centro_costo = %s")
        params.append(cc_filtro)
        desc.append(dict(_OT2_CENTROS_COSTO).get(cc_filtro, cc_filtro))

    # ── Rango de fechas (Daniel, 27-08-2026): sobre v.fecha_programada,
    # igual que la columna que ya se muestra y ordena en la hoja "OT".
    # `desde`/`hasta` (YYYY-MM-DD) mandan si vienen; si no, `periodo=mes`
    # acota al mes en curso (hora Chile). Sin ninguno de los dos: TODO el
    # histórico -- el comportamiento de siempre, para no romper el botón
    # "Reporte Excel" que ya está en producción sin este parámetro.
    desde_s = (args.get("desde") or "").strip()
    hasta_s = (args.get("hasta") or "").strip()
    periodo = (args.get("periodo") or "").strip().lower()
    _desde = _hasta = None
    if desde_s or hasta_s:
        try:
            if desde_s:
                _desde = datetime.strptime(desde_s, "%Y-%m-%d").date()
            if hasta_s:
                _hasta = datetime.strptime(hasta_s, "%Y-%m-%d").date()
        except ValueError:
            _desde = _hasta = None
    elif periodo == "mes":
        _hoy_cl = _now_chile().date()
        _desde = _hoy_cl.replace(day=1)
        _hasta = _hoy_cl
    if _desde:
        where.append("v.fecha_programada >= %s")
        params.append(_desde)
    if _hasta:
        where.append("v.fecha_programada <= %s")
        params.append(_hasta)
    if _desde or _hasta:
        if _desde and _hasta:
            desc.append(f"{_desde.strftime('%d/%m/%Y')}–{_hasta.strftime('%d/%m/%Y')}")
        elif _desde:
            desc.append(f"desde {_desde.strftime('%d/%m/%Y')}")
        else:
            desc.append(f"hasta {_hasta.strftime('%d/%m/%Y')}")

    sql = " WHERE " + " AND ".join(where) if where else ""
    role_sql, role_params = _mant_calendario_role_where()
    sql += role_sql
    params += list(role_params)
    return sql, params, desc, origen


_OT2_EXPORT_LIMIT = 10000     # techo de protección, igual que los CSV de tickets


@app.route("/ot/reporte.xlsx", methods=["GET"])
@_mant_required
@_no_tecnico
def ot2_reporte_xlsx():
    """Reporte Excel de las OT con los filtros que están activos en pantalla.

    Daniel (26-08-2026): *"algo potente con datos realmente buenos"*, con una
    hoja por centro de costo para rendir el dinero que se pierde por
    decisiones que NO son de Servicio Técnico.

    🔒 FIX 2026-08-27 (mismo hallazgo de la auditoría de finanzas de esta
    noche — ot_ficha.html:954, VISITA_COSTO, mant_intel_panel): este reporte
    llevaba `v.costo` (precio cobrado al cliente) y, desde hoy, también
    `costo_proveedor`/`costo_despacho`/margen — el mismo dato que en la
    pantalla de la OT solo se muestra si `puede_metadata`, NUNCA a un
    técnico. El comentario viejo decía "NO @_no_tecnico, un técnico puede
    bajar LO SUYO" porque `_mant_calendario_role_where()` ya acota las
    filas — pero acotar FILAS no basta cuando la fuga es de COLUMNAS
    financieras dentro de esas mismas filas. Se agrega `@_no_tecnico`,
    igual criterio que el resto de los endpoints financieros de esta noche.
    El botón "Reporte Excel" del panel se oculta a técnico en el template
    para no mostrar un link que el backend va a rechazar.
    """
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
        from io import BytesIO
    except Exception:
        flash("Falta la librería openpyxl para generar el Excel.", "danger")
        return redirect(url_for("ot2_panel"))

    where_sql, params, filtros_desc, origen = _ot2_filtros_export(request.args)

    _sql_reporte = (
        "SELECT v.id, v.numero_ot, v.titulo, v.tipo, v.estado, v.prioridad, "
        "       v.fecha_programada, v.fecha_realizada, v.hora_inicio, "
        "       v.direccion_visita, v.costo, v.centro_costo, v.zz_codigo, "
        "       v.zz_monto, v.modalidad_cobro, v.cubierto_por, "
        "       v.estado_facturacion, v.factura_tido, v.factura_nudo, "
        "       v.costo_proveedor, v.costo_despacho, "
        "       v.created_by, v.created_at, v.cerrada_at, "
        "       c.razon_social, c.rut AS cliente_rut, "
        "       c.direccion AS cliente_direccion, c.comuna AS cliente_comuna, "
        "       COALESCE(au.nombre, au.username) AS tecnico_nombre, "
        "       au.role AS tecnico_role, te.id AS tecnico_proveedor_id, "
        "       tk.numero_ticket, "
        "       COALESCE(tar.n_tareas, 0)    AS n_tareas, "
        "       COALESCE(tar.n_completas, 0) AS n_completas "
        "  FROM mant_visitas v "
        "  LEFT JOIN mant_clientes c  ON c.id = v.cliente_id "
        "  LEFT JOIN app_users     au ON au.id = v.tecnico_user_id "
        "  LEFT JOIN mant_tecnicos_externos te ON te.user_id = au.id "
        "  LEFT JOIN tk_tickets    tk ON tk.visita_id = v.id "
    )
    try:
        rows = mysql_fetchall(
            _sql_reporte + _OT2_JOIN_TAREAS + where_sql
            + " ORDER BY v.fecha_programada DESC, v.numero_ot DESC LIMIT %s",
            tuple(params) + (_OT2_EXPORT_LIMIT,)) or []
    except Exception as e:
        print(f"[ot2_reporte_xlsx] query: {e}", flush=True)
        flash("No pudimos generar el reporte.", "danger")
        return redirect(url_for("ot2_panel"))

    _now = _now_chile()
    fecha_gen = _now.strftime("%d/%m/%Y %H:%M")
    alcance = (" · ".join(filtros_desc)) if filtros_desc else "todas las OT"

    BLACK, LGRAY, AMBER, GREENL, REDL, BLUEL = \
        "0A0A0A", "F5F5F5", "FFF8E1", "DCFCE7", "FEE2E2", "DBEAFE"
    thin = Side(style="thin", color="E5E7EB")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    def _hdr(cell, val):
        cell.value = val
        cell.font = Font(bold=True, color="FFFFFF", size=9)
        cell.fill = PatternFill("solid", fgColor=BLACK)
        cell.alignment = Alignment(horizontal="center", vertical="center",
                                   wrap_text=True)
        cell.border = border

    def _d(v):
        """DATE/TIME puro: sin conversión de zona (no la tiene)."""
        try:
            return v.strftime("%d/%m/%Y") if v else ""
        except Exception:
            return ""

    def _dt_cl(v):
        """DATETIME en UTC → hora Chile (REGLA #6). NO usar _d() acá: escribiría
        UTC crudo y rompería la regla."""
        try:
            return chile_fmt_filter(v) if v else ""
        except Exception:
            return ""

    wb = openpyxl.Workbook()

    # ── Hoja 1: OT ────────────────────────────────────────────────────
    ws = wb.active
    ws.title = "OT"
    headers = ["N° OT", "Ticket", "Cliente", "RUT", "Comuna", "Dirección",
               "Título", "Tipo", "Prioridad", "Estado", "Fase", "Técnico",
               "Int/Ext", "Fecha programada", "Hora", "Fecha realizada",
               "Tareas", "% avance", "Centro de costo", "Línea ZZ",
               "Monto ZZ", "Costo",
               # 2026-08-27 (Daniel): "que sepa dónde van las cosas... qué OT
               # están comprometidas con centros de costo diferentes a
               # Servicio Técnico" -- costo proveedor + costo despacho
               # (campo nuevo de esta noche) + margen, misma fórmula que
               # `recalcular()` en ot_ejecutar.html: margen = costo -
               # (costo_proveedor + costo_despacho).
               "Costo proveedor", "Costo despacho", "Margen", "% margen",
               "Cobertura", "Estado facturación",
               "Documento", "Creada por", "Creada", "Cerrada",
               "Observaciones (revisar)"]
    NCOLS = len(headers)
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=NCOLS)
    tcell = ws.cell(row=1, column=1,
                    value=f"ILUS Fitness · Órdenes de Trabajo  —  {alcance}"
                          f"  —  generado {fecha_gen}")
    tcell.font = Font(bold=True, size=13, color="FFFFFF")
    tcell.fill = PatternFill("solid", fgColor=BLACK)
    ws.row_dimensions[1].height = 26
    for ci, h in enumerate(headers, 1):
        _hdr(ws.cell(row=2, column=ci), h)
    ws.row_dimensions[2].height = 30

    hoy = _now.date()
    # Se adelanta acá (antes vivía solo en la Hoja 3) para mostrar la
    # etiqueta legible ("Servicio Técnico") en la Hoja 1 también, en vez
    # del código crudo ("sstt") que mostraba antes.
    _LBL_CC = dict(_OT2_CENTROS_COSTO)
    por_tecnico, por_centro = {}, {}
    # Totales globales para la hoja "Resumen" (Daniel, 27-08-2026): "cuánto
    # dinero total está fuera de Servicio Técnico". "sstt" es el único
    # centro que Daniel SÍ considera propio de Servicio Técnico -- vacío/
    # NULL cuenta como "fuera" porque tampoco es atribuible por defecto.
    fin_tot = {"cobrado": 0.0, "proveedor": 0.0, "despacho": 0.0, "margen": 0.0,
               "no_sstt_ot": 0, "no_sstt_cobrado": 0.0, "no_sstt_margen": 0.0}
    r = 3
    for f in rows:
        estado = (f.get("estado") or "").lower()
        # 🔧 FIX 2026-08-27: _OT2_ESTADO_META guarda TUPLAS (label, css_class,
        # icon, fase) -- ver el patrón real en `ot2_panel` línea ~73745
        # (`f["estado_label"], ..., f["estado_fase"] = meta`). Este reporte
        # lo trataba como dict (`meta.get(...)`), lo que reventaba con
        # AttributeError apenas llegaba una fila con estado real -- nunca
        # se había probado con datos, solo con `rows` vacío.
        _meta_t = _OT2_ESTADO_META.get(estado)
        if _meta_t:
            estado_label, fase = _meta_t[0], (_meta_t[3] or "")
        else:
            estado_label, fase = (estado or "—"), ""
        n_t = int(f.get("n_tareas") or 0)
        n_c = int(f.get("n_completas") or 0)
        pct = int(round(n_c * 100.0 / n_t)) if n_t else 0
        externo = bool(f.get("tecnico_proveedor_id")) or \
            (f.get("tecnico_role") or "").lower() == "tecnico_externo"
        tec = f.get("tecnico_nombre") or "— sin asignar —"

        # Banderas de calidad de dato: lo que hay que ir a revisar.
        obs = []
        if not f.get("tecnico_nombre"):
            obs.append("Sin técnico asignado")
        if not f.get("fecha_programada"):
            obs.append("Sin fecha programada")
        elif (f.get("fecha_programada") < hoy
              and estado not in ("cerrada", "completada", "cancelada", "anulada")):
            obs.append("Programada vencida sin cerrar")
        if n_t and n_c < n_t and estado in ("cerrada", "completada"):
            obs.append("Cerrada con tareas incompletas")
        if not f.get("centro_costo"):
            obs.append("Sin centro de costo")
        if not f.get("numero_ticket"):
            obs.append("Sin ticket de origen")

        # Margen = costo (precio cliente) - (costo_proveedor + costo_despacho).
        # Misma fórmula que `recalcular()` en ot_ejecutar.html (2026-08-27).
        # "—" solo cuando NO hay ningún dato financiero declarado; si hay
        # costo proveedor/despacho pero no precio, el margen igual se
        # calcula (da negativo) porque eso también es información real: un
        # trabajo con costo pero sin cobro declarado.
        _tiene_finanzas = (f.get("costo") is not None
                            or f.get("costo_proveedor") is not None
                            or f.get("costo_despacho") is not None)
        _precio = float(f.get("costo") or 0)
        _cprov = float(f.get("costo_proveedor") or 0)
        _cdesp = float(f.get("costo_despacho") or 0)
        margen = margen_pct = None
        if _tiene_finanzas:
            margen = _precio - (_cprov + _cdesp)
            margen_pct = (margen / _precio * 100.0) if _precio > 0 else None
            fin_tot["cobrado"] += _precio
            fin_tot["proveedor"] += _cprov
            fin_tot["despacho"] += _cdesp
            fin_tot["margen"] += margen
            if (f.get("centro_costo") or "") != "sstt":
                fin_tot["no_sstt_ot"] += 1
                fin_tot["no_sstt_cobrado"] += _precio
                fin_tot["no_sstt_margen"] += margen
            if margen < 0:
                obs.append("Margen negativo")

        vals = [
            f.get("numero_ot") or "", f.get("numero_ticket") or "",
            f.get("razon_social") or "", f.get("cliente_rut") or "",
            f.get("cliente_comuna") or "",
            (f.get("direccion_visita") or f.get("cliente_direccion") or ""),
            f.get("titulo") or "",
            _TIPO_OT_LABEL.get((f.get("tipo") or "").lower(), f.get("tipo") or ""),
            f.get("prioridad") or "", estado_label,
            _OT2_FASE_LABELS.get(fase, fase), tec,
            "Externo" if externo else "Interno",
            _d(f.get("fecha_programada")), _ot_tv_hhmm(f.get("hora_inicio")) or "",
            _d(f.get("fecha_realizada")), f"{n_c}/{n_t}" if n_t else "",
            pct, _LBL_CC.get(f.get("centro_costo"), f.get("centro_costo") or ""),
            f.get("zz_codigo") or "",
            float(f.get("zz_monto")) if f.get("zz_monto") is not None else None,
            float(f.get("costo")) if f.get("costo") is not None else None,
            (float(f.get("costo_proveedor")) if f.get("costo_proveedor") is not None else None),
            (float(f.get("costo_despacho")) if f.get("costo_despacho") is not None else None),
            margen,
            (round(margen_pct, 1) if margen_pct is not None else None),
            f.get("cubierto_por") or "", f.get("estado_facturacion") or "",
            ((f.get("factura_tido") or "") + " " + (f.get("factura_nudo") or "")).strip(),
            f.get("created_by") or "", _dt_cl(f.get("created_at")),
            _dt_cl(f.get("cerrada_at")), " · ".join(obs),
        ]

        bg = LGRAY if r % 2 == 0 else "FFFFFF"
        for ci, val in enumerate(vals, 1):
            cell = ws.cell(row=r, column=ci, value=val)
            cell.font = Font(size=9, bold=(ci == 1))
            cell.alignment = Alignment(
                horizontal="center" if ci in (1, 2, 13, 14, 15, 16, 17, 18) else "left",
                vertical="center", wrap_text=(ci in (6, 7, NCOLS)))
            cell.border = border
            fill = bg
            if ci == 11:      # semáforo por fase, reusando el mapa del panel
                fill = {"pend": AMBER, "ejec": BLUEL, "comp": GREENL,
                        "cerr": LGRAY}.get(fase, bg)
            elif ci == NCOLS and obs:
                fill = AMBER
            cell.fill = PatternFill("solid", fgColor=fill)
            if ci in (21, 22, 23, 24, 25) and val is not None:
                cell.number_format = '"$"#,##0'
                if ci == 25 and val < 0:   # Margen negativo — salta a la vista
                    cell.fill = PatternFill("solid", fgColor=REDL)
                    cell.font = Font(size=9, bold=True, color="DC2626")
            elif ci == 26 and val is not None:
                cell.number_format = '0.0"%"'
        r += 1

        # Agregados en Python — sin consultas extra. Reusa _cprov/_cdesp ya
        # calculados arriba para el margen (evita divergencia entre hojas).
        k = (tec, "Externo" if externo else "Interno")
        a = por_tecnico.setdefault(k, {"total": 0, "cerradas": 0, "abiertas": 0,
                                       "tareas_ok": 0, "tareas_tot": 0, "monto": 0.0,
                                       "margen": 0.0})
        a["total"] += 1
        a["tareas_ok"] += n_c
        a["tareas_tot"] += n_t
        a["monto"] += float(f.get("zz_monto") or f.get("costo") or 0)
        if margen is not None:
            a["margen"] += margen
        if estado in ("cerrada", "completada"):
            a["cerradas"] += 1
        else:
            a["abiertas"] += 1

        cc = f.get("centro_costo") or "(sin centro)"
        b = por_centro.setdefault(cc, {"total": 0, "monto": 0.0, "garantia": 0,
                                       "costo_proveedor": 0.0, "costo_despacho": 0.0,
                                       "margen": 0.0, "con_margen": 0})
        b["total"] += 1
        b["monto"] += float(f.get("zz_monto") or f.get("costo") or 0)
        b["costo_proveedor"] += _cprov
        b["costo_despacho"] += _cdesp
        if margen is not None:
            b["margen"] += margen
            b["con_margen"] += 1
        if (f.get("cubierto_por") or "").lower() == "garantia":
            b["garantia"] += 1

    widths = [15, 12, 30, 13, 15, 34, 30, 18, 11, 16, 14, 22, 10, 15, 8, 15,
              9, 9, 16, 16, 13, 13, 14, 14, 14, 11, 12, 17, 16, 16, 16, 16, 40]
    for ci, w in enumerate(widths[:NCOLS], 1):
        ws.column_dimensions[get_column_letter(ci)].width = w
    ws.freeze_panes = "C3"
    ws.auto_filter.ref = f"A2:{get_column_letter(NCOLS)}{max(2, r - 1)}"

    # ── Hoja 2: Por técnico ───────────────────────────────────────────
    ws2 = wb.create_sheet("Por técnico")
    h2 = ["Técnico", "Tipo", "OT totales", "Cerradas", "Abiertas",
          "Tareas hechas", "Tareas totales", "% avance", "Monto asociado",
          "Margen"]
    for ci, h in enumerate(h2, 1):
        _hdr(ws2.cell(row=1, column=ci), h)
    r2 = 2
    for (tec, tipo), a in sorted(por_tecnico.items(), key=lambda x: -x[1]["total"]):
        pct = int(round(a["tareas_ok"] * 100.0 / a["tareas_tot"])) if a["tareas_tot"] else 0
        for ci, val in enumerate([tec, tipo, a["total"], a["cerradas"], a["abiertas"],
                                  a["tareas_ok"], a["tareas_tot"], pct, a["monto"],
                                  a["margen"]], 1):
            c = ws2.cell(row=r2, column=ci, value=val)
            c.font = Font(size=9)
            c.border = border
            c.fill = PatternFill("solid", fgColor=LGRAY if r2 % 2 == 0 else "FFFFFF")
            if ci in (9, 10):
                c.number_format = '"$"#,##0'
        r2 += 1
    for ci, w in enumerate([26, 10, 12, 11, 11, 14, 14, 11, 16, 16], 1):
        ws2.column_dimensions[get_column_letter(ci)].width = w
    ws2.freeze_panes = "A2"

    # ── Hoja 3: Por centro de costo ───────────────────────────────────
    # La que sustenta el informe de Daniel: cuánto se va en trabajos que NO
    # son atribuibles a Servicio Técnico (convenios de Comercial, Logística).
    # 2026-08-27: se agregan costo proveedor/despacho + margen (mismos
    # campos nuevos de esta noche) y una fila de totales "fuera de SSTT"
    # -- la pregunta exacta de Daniel: "cuánto dinero hay en juego".
    ws3 = wb.create_sheet("Por centro de costo")
    h3 = ["Centro de costo", "OT", "Monto asociado (cobrado)",
          "Costo proveedor", "Costo despacho", "Margen total", "En garantía"]
    for ci, h in enumerate(h3, 1):
        _hdr(ws3.cell(row=1, column=ci), h)
    r3 = 2
    _fuera_sstt = {"total": 0, "monto": 0.0, "costo_proveedor": 0.0,
                   "costo_despacho": 0.0, "margen": 0.0, "garantia": 0}
    for cc, b in sorted(por_centro.items(), key=lambda x: -x[1]["monto"]):
        for ci, val in enumerate([_LBL_CC.get(cc, cc), b["total"], b["monto"],
                                  b["costo_proveedor"], b["costo_despacho"],
                                  b["margen"], b["garantia"]], 1):
            c = ws3.cell(row=r3, column=ci, value=val)
            c.font = Font(size=9, bold=(ci == 1))
            c.border = border
            c.fill = PatternFill("solid", fgColor=(
                REDL if cc == "(sin centro)" else
                LGRAY if r3 % 2 == 0 else "FFFFFF"))
            if ci in (3, 4, 5, 6):
                c.number_format = '"$"#,##0'
        r3 += 1
        # "sstt" (o vacío ya normalizado a "(sin centro)") queda excluido:
        # es justo lo que Daniel SÍ considera Servicio Técnico.
        if cc != "sstt":
            _fuera_sstt["total"] += b["total"]
            _fuera_sstt["monto"] += b["monto"]
            _fuera_sstt["costo_proveedor"] += b["costo_proveedor"]
            _fuera_sstt["costo_despacho"] += b["costo_despacho"]
            _fuera_sstt["margen"] += b["margen"]
            _fuera_sstt["garantia"] += b["garantia"]
    r3 += 1
    for ci, val in enumerate(
        ["TOTAL fuera de Servicio Técnico", _fuera_sstt["total"],
         _fuera_sstt["monto"], _fuera_sstt["costo_proveedor"],
         _fuera_sstt["costo_despacho"], _fuera_sstt["margen"],
         _fuera_sstt["garantia"]], 1):
        c = ws3.cell(row=r3, column=ci, value=val)
        c.font = Font(size=10, bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="DC2626")
        c.border = border
        if ci in (3, 4, 5, 6):
            c.number_format = '"$"#,##0'
    for ci, w in enumerate([30, 10, 18, 16, 16, 14, 13], 1):
        ws3.column_dimensions[get_column_letter(ci)].width = w
    ws3.freeze_panes = "A2"

    # ── Hoja 4: Resumen ───────────────────────────────────────────────
    ws4 = wb.create_sheet("Resumen")
    filas_res = [
        ("— Alcance —", ""),
        ("Filtros aplicados", alcance),
        ("Origen", "OT reales" if origen == "reales" else "Automáticas"),
        ("Generado", fecha_gen),
        ("OT en el reporte", len(rows)),
        ("", ""),
        ("— Por fase —", ""),
    ]
    for fase_k, fase_lbl in _OT2_FASE_LABELS.items():
        # Mismo fix de tupla-no-dict que en la Hoja 1 (arriba): índice [3].
        n = sum(1 for f in rows
                if ((_OT2_ESTADO_META.get((f.get("estado") or "").lower())
                     or (None, None, None, None))[3]) == fase_k)
        filas_res.append((fase_lbl, n))
    filas_res += [("", ""), ("— Calidad de dato —", "")]
    filas_res.append(("Sin técnico asignado",
                      sum(1 for f in rows if not f.get("tecnico_nombre"))))
    filas_res.append(("Sin centro de costo",
                      sum(1 for f in rows if not f.get("centro_costo"))))
    filas_res.append(("Sin ticket de origen",
                      sum(1 for f in rows if not f.get("numero_ticket"))))
    # 2026-08-27 (Daniel): "si yo pregunto mañana o bajo un reporte, quiero
    # saber qué OT están comprometidas con centros de costo diferentes a
    # servicio técnico... yo me estaría armando un buen reporte" -- este es
    # el bloque que responde exactamente esa pregunta en una sola mirada.
    _pct_no_sstt = (fin_tot["no_sstt_cobrado"] / fin_tot["cobrado"] * 100.0
                    ) if fin_tot["cobrado"] else 0.0
    filas_res += [("", ""), ("— Finanzas —", "")]
    filas_res.append(("Monto cobrado total", fin_tot["cobrado"], True))
    filas_res.append(("Costo proveedor total", fin_tot["proveedor"], True))
    filas_res.append(("Costo despacho total", fin_tot["despacho"], True))
    filas_res.append(("Margen total", fin_tot["margen"], True))
    filas_res += [("", ""), ("— Fuera de Servicio Técnico —", "")]
    filas_res.append(("OT con centro Logística/Comercial/sin definir",
                      fin_tot["no_sstt_ot"]))
    filas_res.append(("Monto cobrado fuera de SSTT", fin_tot["no_sstt_cobrado"], True))
    filas_res.append(("Margen fuera de SSTT", fin_tot["no_sstt_margen"], True))
    filas_res.append(("% del monto cobrado que es fuera de SSTT",
                      f"{_pct_no_sstt:.1f}%"))
    if len(rows) >= _OT2_EXPORT_LIMIT:
        filas_res += [("", ""), ("⚠ Tope alcanzado",
                                 f"El reporte se cortó en {_OT2_EXPORT_LIMIT} "
                                 f"filas. Filtra para ver el resto.")]
    for i, fila in enumerate(filas_res, 1):
        k, v = fila[0], fila[1]
        es_moneda = len(fila) > 2 and fila[2]
        ck = ws4.cell(row=i, column=1, value=k)
        cv = ws4.cell(row=i, column=2, value=v)
        es_sep = str(k).startswith("—") or str(k).startswith("⚠")
        ck.font = Font(size=10, bold=True,
                       color="DC2626" if es_sep else "374151")
        cv.font = Font(size=10, bold=(k == "Margen fuera de SSTT" and isinstance(v, (int, float)) and v < 0))
        if es_moneda:
            cv.number_format = '"$"#,##0'
            if isinstance(v, (int, float)) and v < 0:
                cv.font = Font(size=10, bold=True, color="DC2626")
    ws4.column_dimensions["A"].width = 38
    ws4.column_dimensions["B"].width = 46

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    try:
        _mant_log("visita", 0, "reporte_ot_xlsx",
                  f"{len(rows)} OT exportadas a Excel ({alcance})")
    except Exception:
        pass
    fname = f"ILUS_OT_{_now.strftime('%Y%m%d_%H%M')}.xlsx"
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True, download_name=fname)


@app.route("/ot/api/lineas-zz/<tido>/<nudo>", methods=["GET"])
@_mant_required
def ot2_api_lineas_zz(tido, nudo):
    """Líneas ZZ de un documento del ERP — para valorizar la OT sin tipear.

    Daniel (26-08-2026): *"puedas extraer el ZZ instalación o el ZZ
    mantención, o cualquier item raro por si se inventan uno, para extraer
    el cobro del servicio"*. Por eso NO se filtra por una lista blanca de
    códigos: se devuelve TODA línea cuyo SKU empiece con `ZZ`, y se marca
    cuál es la sugerida según el tipo de OT (instalación → ZZINSTALACION,
    preventiva/correctiva → ZZMANTENCION). Si mañana Random inventa
    `ZZARMADO`, aparece igual y se puede elegir.

    Solo lectura sobre el ERP (REGLA #4.1): reusa `_mant_erp_doc_cached`,
    que ya cachea 5 min y pasa por `_cubicador_fetch`.

    Multidocumento: el frontend llama una vez por documento y une las
    listas — el orden lo decide quien está creando la OT.
    """
    tido = (tido or "").strip().upper()[:5]
    nudo = (nudo or "").strip()[:20]
    if not tido or not nudo:
        return _ot2_err("Falta el tipo o el número del documento.", "DOC_INCOMPLETO")

    tipo_ot = (request.args.get("tipo_ot") or "").strip().lower()
    sugerido = _OT2_LINEA_ZZ.get(tipo_ot)

    try:
        header, lineas = _mant_erp_doc_cached(tido, nudo)
    except Exception as e:
        print(f"[ot2_lineas_zz] {tido} {nudo}: {e}", flush=True)
        return _ot2_err("No pudimos consultar el documento en Random.",
                        "ERP_ERROR", http=502)
    if not header:
        return _ot2_err(f"No encontramos el documento {tido} {nudo} en Random.",
                        "DOC_NO_ENCONTRADO", http=404)

    zz = []
    for ln in (lineas or []):
        sku = (ln.get("sku") or "").strip().upper()
        if not sku.startswith("ZZ"):
            continue
        try:
            # 2026-08-30 (Daniel, caso real FCV 11382 — ZZINSTALACION y
            # ZZenvio llegaban en $0): esto leía "VATOLI"/"VANELI" en
            # MAYÚSCULA, que son nombres de columna SQL Server crudos —
            # pero `lineas` acá NO es la fila cruda de MAEDDO, es el dict
            # YA NORMALIZADO que arma _cubicador_fetch(), cuyo contrato
            # (ver docstring "NO TOCAR" de esa función) documenta el campo
            # de valor como `vaneli` en MINÚSCULA. "VATOLI" nunca existió
            # en ninguna otra parte del proyecto -- por eso esto SIEMPRE
            # devolvía 0, para cualquier documento, desde que se escribió.
            monto = int(round(float(ln.get("vaneli") or ln.get("VANELI")
                                    or ln.get("valor") or 0)))
        except (TypeError, ValueError):
            monto = 0
        zz.append({
            "sku": sku,
            "descripcion": (ln.get("descripcion") or ln.get("nombre")
                            or ln.get("DEEN") or "").strip()[:180],
            "monto": monto,
            "sugerida": bool(sugerido and sku == sugerido),
        })

    # La sugerida primero, después por monto de mayor a menor: lo más
    # probable queda arriba sin esconder el resto.
    zz.sort(key=lambda x: (not x["sugerida"], -x["monto"]))

    return jsonify({
        "ok": True, "tido": tido, "nudo": nudo,
        "cliente": (header.get("cliente") or header.get("razon_social") or ""),
        "lineas_zz": zz,
        "sugerido": sugerido,
        "total_lineas": len(lineas or []),
    })


# tipo_ot (OT 2.0) -> tipo_servicio de cat_clase_producto_tarifas. Solo los 4
# que tienen categoría de tarifa real (ver _CAT_TIPOS_SERVICIO_TARIFA en
# catalogo_module.py); el resto (inspección, levantamiento, cambio de
# equipo, movimiento de equipos, desinstalación) no tiene tarifa configurada
# todavía -- el estimador los deja sin monto en vez de inventar un cálculo.
_OT2_TIPO_A_TIPO_SERVICIO_COSTO = {
    "instalacion": "instalacion",
    "preventiva":  "mantencion",
    "correctiva":  "mantencion",
    "visita_tecnica": "visita_tecnica",
}


@app.route("/ot/api/estimar-costo", methods=["POST"])
@_mant_required
def ot2_api_estimar_costo():
    """Estimado de costo NETO de la OT según la clasificación real de los
    equipos elegidos -- Daniel 2026-08-29: "en base a los productos que
    tengas declarado, hagas un cálculo de cuánto costaría el servicio...
    dame el total neto, según el servicio que tengamos".

    Reusa el MISMO motor de precio del Cotizador (_tk_cotiz_calcular_item +
    _tk_cotiz_pricing_config, tickets_module.py) -- ni una fórmula nueva ni
    una segunda fuente de verdad para lo que cuesta una hora-técnico.

    Es un ESTIMADO informativo, no un documento: cuando la OT ya tiene un
    documento real asociado (factura/boleta/nota de venta), el monto que
    manda es el de la línea ZZ real de ese documento
    (GET /ot/api/lineas-zz/<tido>/<nudo>), no este cálculo.

    Nunca bloquea ni inventa: si el tipo de OT o alguna clasificación no
    tiene tarifa configurada, esa parte queda fuera del total con aviso
    (`sin_tarifa`), en vez de forzar un número.
    """
    d = request.get_json(silent=True) or {}
    tipo_ot = (d.get("tipo_ot") or "").strip().lower()
    tipo_servicio = _OT2_TIPO_A_TIPO_SERVICIO_COSTO.get(tipo_ot)
    try:
        maquina_ids = [int(x) for x in (d.get("maquina_ids") or []) if x]
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "IDs de equipo inválidos"}), 400
    if not tipo_servicio or not maquina_ids:
        return jsonify({"ok": True, "total_neto": None, "detalle": [], "sin_tarifa": [],
                         "motivo": "sin_tarifa_para_tipo" if not tipo_servicio else "sin_equipos"})

    placeholders = ",".join(["%s"] * len(maquina_ids))
    try:
        rows = mysql_fetchall(
            f"SELECT cc.slug AS slug, cc.nombre AS nombre "
            f"  FROM mant_maquinas m "
            f"  JOIN cat_productos cp ON cp.sku = m.sku "
            f"  JOIN cat_clases_producto cc ON cc.slug = cp.clase_producto AND cc.activo = 1 "
            f" WHERE m.id IN ({placeholders})",
            tuple(maquina_ids)) or []
    except Exception as e:
        print(f"[ot2_api_estimar_costo] resolver clases: {e}", flush=True)
        return jsonify({"ok": True, "total_neto": None, "detalle": [], "sin_tarifa": []})

    conteo, nombres = {}, {}
    for r in rows:
        conteo[r["slug"]] = conteo.get(r["slug"], 0) + 1
        nombres[r["slug"]] = r["nombre"]
    n_sin_clasificar = len(maquina_ids) - len(rows)

    if not conteo:
        return jsonify({"ok": True, "total_neto": None, "detalle": [], "sin_tarifa": [],
                         "n_equipos_sin_clasificar": n_sin_clasificar, "motivo": "sin_clasificacion"})

    try:
        cfg = _tk_cotiz_pricing_config()
    except Exception as e:
        print(f"[ot2_api_estimar_costo] pricing_config: {e}", flush=True)
        return jsonify({"ok": True, "total_neto": None, "detalle": [], "sin_tarifa": []})

    total, detalle, sin_tarifa = 0, [], []
    for slug, cant in conteo.items():
        try:
            item = _tk_cotiz_calcular_item(slug, tipo_servicio, cant, 0, cfg)
        except Exception as e:
            print(f"[ot2_api_estimar_costo] calcular '{slug}': {e}", flush=True)
            item = None
        if not item:
            sin_tarifa.append(nombres.get(slug, slug))
            continue
        total += item["total"]
        detalle.append({"clase": nombres.get(slug, slug), "cantidad": cant, "monto": round(item["total"])})

    return jsonify({
        "ok": True,
        "total_neto": round(total) if detalle else None,
        "detalle": detalle,
        "sin_tarifa": sin_tarifa,
        "n_equipos_sin_clasificar": n_sin_clasificar,
    })


# ── Panel de administración de pantallas ─────────────────────────────
#  Emitir la URL de un televisor es configuración, no operación diaria:
#  por eso superadmin. Es el primer panel de revocación de tokens del
#  proyecto (hoy /t/<token> y /firma-retiro/<token> son revocables en
#  teoría pero no tienen botón) — sirve de molde para los demás.

@app.route("/admin/pantallas", methods=["GET"])
@require_permission("superadmin")
def admin_pantallas():
    """Pantallas del monitor de oficina: crear, revocar, re-emparejar."""
    try:
        _ensure_ot_pantallas()
        rows = mysql_fetchall(
            "SELECT id, nombre, token, activo, device_id, device_bound_at, "
            "       last_seen_at, last_ip, created_by, created_at "
            "  FROM ot_pantallas ORDER BY activo DESC, id DESC") or []
    except Exception as e:
        print(f"[admin_pantallas] {e}", flush=True)
        flash("No pudimos leer las pantallas.", "danger")
        rows = []
    return render_template("admin/pantallas.html",
                           pantallas=[dict(r) for r in rows])


@app.route("/admin/pantallas/nueva", methods=["POST"])
@require_permission("superadmin")
def admin_pantallas_nueva():
    """Crea una pantalla y su URL única.

    El token nace sin dispositivo: se ata al primer navegador que abra la
    URL (confianza en el primer uso). Por eso hay que abrirla PRIMERO en
    el televisor, no en el computador — si se abre acá, queda atada acá.
    """
    nombre = (request.form.get("nombre") or "").strip()[:120]
    if not nombre:
        flash("Ponle un nombre a la pantalla (ej: TV Recepción).", "warning")
        return redirect(url_for("admin_pantallas"))
    token = secrets.token_urlsafe(30)[:40]
    try:
        _ensure_ot_pantallas()
        mysql_execute(
            "INSERT INTO ot_pantallas (nombre, token, created_by) VALUES (%s,%s,%s)",
            (nombre, token, current_username()))
        _mant_log("sistema", 0, "pantalla_tv_creada", f"{nombre}")
        flash(f'Pantalla "{nombre}" creada. Abre su enlace PRIMERO en el '
              f'televisor: queda atada al primer navegador que lo use.', "success")
    except Exception as e:
        print(f"[admin_pantallas_nueva] {e}", flush=True)
        flash("No pudimos crear la pantalla.", "danger")
    return redirect(url_for("admin_pantallas"))


@app.route("/admin/pantallas/<int:pid>/revocar", methods=["POST"])
@require_permission("superadmin")
def admin_pantallas_revocar(pid):
    """Mata el enlace al instante. Soft-delete (activo=0), convención del
    proyecto: preserva el historial de la pantalla."""
    try:
        row = mysql_fetchone("SELECT nombre FROM ot_pantallas WHERE id=%s", (pid,))
        mysql_execute("UPDATE ot_pantallas SET activo=0 WHERE id=%s", (pid,))
        _mant_log("sistema", 0, "pantalla_tv_revocada",
                  f"{(row or {}).get('nombre') or pid}")
        flash("Pantalla revocada. Su enlace dejó de funcionar.", "success")
    except Exception as e:
        print(f"[admin_pantallas_revocar] {e}", flush=True)
        flash("No pudimos revocar la pantalla.", "danger")
    return redirect(url_for("admin_pantallas"))


@app.route("/admin/pantallas/<int:pid>/reemparejar", methods=["POST"])
@require_permission("superadmin")
def admin_pantallas_reemparejar(pid):
    """Suelta el dispositivo sin cambiar la URL — para cambiar de televisor
    o si la pantalla quedó atada al navegador equivocado."""
    try:
        mysql_execute(
            "UPDATE ot_pantallas SET device_id=NULL, device_bound_at=NULL "
            " WHERE id=%s", (pid,))
        _mant_log("sistema", 0, "pantalla_tv_reemparejada", str(pid))
        flash("Listo. El próximo navegador que abra el enlace queda atado.",
              "success")
    except Exception as e:
        print(f"[admin_pantallas_reemparejar] {e}", flush=True)
        flash("No pudimos re-emparejar la pantalla.", "danger")
    return redirect(url_for("admin_pantallas"))


@app.route("/mantenciones/ots")
@app.route("/servicio-tecnico/ots")
@_mant_required
def mant_ots_list():
    """Listado global de Órdenes de Trabajo (visitas) con filtros.

    🔐 SEGURIDAD 2026-05-18 (Daniel) — filtro por rol:
      - tecnico / tecnico_externo: SIEMPRE `solo_mias` (no puede ver
        ajenas — refuerzo doble; cualquier intento se ignora server-side).
      - ejecutivo (ej. Aaron): por DEFAULT ve SOLO las OTs que él CREÓ
        (`created_by = self.username`). Puede pasar `?todas=1` para ver
        el resto del módulo (consultivo, sin ejecutar).
      - admin / superadmin: ve TODAS por default. Puede usar `?solo_mias=1`
        para filtrar SOLO sus asignadas (raramente útil para ellos).
      - Otros roles (editor, lector, vendedor) → no llegan acá porque el
        decorador @_mant_required ya los bloquea por permisos.
    """
    estado     = (request.args.get("estado") or "").strip().lower()
    tipo       = (request.args.get("tipo") or "").strip().lower()
    tecnico_id = request.args.get("tecnico_id")
    cliente_id = request.args.get("cliente_id")
    q          = (request.args.get("q") or "").strip()
    solo_mias  = request.args.get("solo_mias") == "1"
    ver_todas  = request.args.get("todas") == "1"
    # 🔎 FILTRO 2026-08-12 (Daniel, viendo el listado en vivo): "filtra lo
    # que se hace programado automáticamente... a menos que lo busque" --
    # sus ~72 OT de prueba (OT-2026-00001..00072, cliente "Juan Daniel
    # Aguilar Tejera") se perdían entre "ruido" generado SIN una decisión
    # humana por-OT: sugerencias del Agente aceptadas con un clic desde la
    # ficha del cliente, registros retroactivos, el seguimiento automático
    # tras una visita histórica, y las tandas del Plan Anual. Ver
    # `_OT_TITULOS_AUTO` más abajo para el detalle de qué NO cuenta como
    # ruido (Trabajo interno NO está acá -- lo crea a mano un supervisor,
    # solo que por otra razón tampoco tiene numero_ot).
    incluir_auto = request.args.get("incluir_auto") == "1"

    # ── Lógica por rol (matriz 2026-05-18) ──────────────────────────
    # FIX 2026-05-18 (Aaron Urbina): normalizamos vía `_rol_familia` para que
    # variantes dinámicas (ejecutivo_sstt, tecnico_externo, etc.) caigan en
    # la familia correcta.
    user = getattr(g, "user", None) or {}
    role_l = (user.get("role") or "").lower()
    role_fam = _rol_familia(role_l)
    es_tecnico   = (role_fam == "tecnico")
    es_ejecutivo = (role_fam == "ejecutivo")
    # Técnico: forzar solo_mias siempre (refuerzo IDOR — antes intentaba
    # manipular ?solo_mias=0 para ver ajenas).
    if es_tecnico:
        solo_mias = True

    # ── ORIGEN (chips "Mis OT / Automáticas / Todas") — Daniel 2026-08-14,
    #    antes de salir de viaje: "cuando yo entro acá necesito que me
    #    salgan las órdenes de trabajo que yo he hecho... las que yo hago a
    #    mano, quiero verlas; y poder filtrar las que están programadas
    #    [automáticas]". El listado le mezclaba sus OT hechas a mano con
    #    las tandas del Plan Anual / [PM] / registros retroactivos.
    #
    #    mias  → creadas por mí O asignadas a mí (misma identidad robusta
    #            del filtro del ejecutivo: FK + username + nombre legible).
    #    auto  → SOLO las generadas sin decisión humana por-OT (creador
    #            cron/sistema/vacío O título con marcador de flujo auto).
    #    todas → comportamiento histórico completo (con su checkbox
    #            incluir_auto intacto — REGLA #4.2, nada se quita).
    #
    #    DEFAULT: entrada "limpia" (sin ningún filtro en la URL) → mias.
    #    Si la URL YA trae un filtro explícito (estado/tipo/técnico/
    #    cliente/q/todas=1) → todas, para NO romper los deep-links que el
    #    resto del sistema genera (correos de aprobación con ?estado=...,
    #    accesos desde fichas con ?cliente_id=...): esos deben seguir
    #    mostrando lo que siempre mostraron. Supersede el default del
    #    ejecutivo del 2026-06-12 solo en la entrada limpia.
    #    Técnico: no aplica — su solo_mias forzado manda.
    _OT_TITULOS_AUTO = (
        "%(agendada por el Agente)%",
        "%(registro retroactivo)%",
        "%(sugerida por sistema)%",
        "%(Plan anual)%",
    )
    origen = (request.args.get("origen") or "").strip().lower()
    if origen not in ("mias", "auto", "todas"):
        origen = ""
    if es_tecnico or solo_mias:
        origen = ""
    elif not origen:
        _hay_filtro_explicito = bool(
            estado or tipo or tecnico_id or cliente_id or q or ver_todas
            or request.args.get("mias") == "1" or incluir_auto
        )
        origen = "todas" if _hay_filtro_explicito else "mias"

    # ── SOLO OT REALES (Daniel 2026-08-16, viendo el listado): "en Mis OT
    #    me dice que tengo veinte, pero no me filtra las que son orden de
    #    trabajo". El listado mezcla las OT con número real
    #    (OT-2026-000XX) con VISITAS que nunca recibieron número y que la
    #    pantalla muestra como "VS-00211" — un número de pantalla, no una
    #    OT. Este filtro deja solo las que de verdad son órdenes.
    #    2026-08-16, segunda pasada (Daniel, textual): "no quiero ver nada
    #    automático, a menos que yo lo seleccione... las automáticas me
    #    dicen VS nada más, quiero ver solamente las que dicen OT. Me
    #    molesta tener que hacerle seguimiento a eso". Por eso el filtro
    #    viene ACTIVADO por defecto: `?solo_ot=0` es el escape explícito
    #    para volver a verlas (nada se pierde, REGLA #4.2).
    solo_ot = request.args.get("solo_ot", "1") != "0"
    if solo_ot:
        where_solo_ot = "v.numero_ot IS NOT NULL AND TRIM(v.numero_ot) <> ''"
    else:
        where_solo_ot = None

    # ── FASE del trabajo (Daniel: "mostrarme un filtro que diga qué está
    #    creado, qué está en gestión y qué está realizado"). Agrupa los 14
    #    estados del ENUM en las 3 fases con las que él piensa el negocio.
    #    Reusa el mismo criterio del Kanban (_grupoKanban en el template)
    #    para que las dos vistas cuenten igual.
    _FASES = {
        "creada":    ("creada", "programada", "asignada", "reagendada"),
        "gestion":   ("en_curso", "en_ejecucion", "pendiente_info",
                      "pendiente_repuesto", "firmada_tecnico", "pendiente_aprobacion"),
        "realizada": ("completada", "cerrada"),
    }
    fase = (request.args.get("fase") or "").strip().lower()
    if fase not in _FASES:
        fase = ""

    # ── ORDEN (Daniel: "como la setenta y nueve, cincuenta y nueve, y
    #    dejarlas en ese orden"). Antes ordenaba por fecha_programada, así
    #    que los números salían salteados. Ahora manda el N° de OT
    #    descendente: como el formato es OT-AAAA-NNNNN con ceros a la
    #    izquierda y mismo prefijo, el orden alfabético descendente ES el
    #    numérico (79 > 59) y además respeta el año. Las visitas sin número
    #    van al final. `?orden=fecha` recupera el criterio anterior para
    #    quien lo prefiera — no se pierde (REGLA #4.2).
    orden = (request.args.get("orden") or "numero").strip().lower()
    if orden == "fecha":
        _orden_sql = " ORDER BY v.fecha_programada DESC, v.id DESC "
    else:
        orden = "numero"
        _orden_sql = (" ORDER BY (v.numero_ot IS NULL OR TRIM(v.numero_ot)='') ASC, "
                      "          v.numero_ot DESC, v.fecha_programada DESC, v.id DESC ")

    where = ["1=1"]
    params = []
    if where_solo_ot:
        where.append(where_solo_ot)
    if fase:
        _ph_fase = ",".join(["%s"] * len(_FASES[fase]))
        where.append(f"v.estado IN ({_ph_fase})")
        params.extend(_FASES[fase])

    # ── EJECUTIVO (Aaron) — filtrar a sus OTs (creadas + asignadas) por DEFAULT ──
    # Daniel: "el ejecutivo NO ejecuta — solo crea/supervisa". Por
    # default mostramos las OTs que él mismo creó (created_by =
    # username/nombre) **O las que tiene asignadas como técnico**.
    # Puede pasar ?todas=1 para ver el resto del módulo (útil para
    # coordinar), pero igualmente no puede ejecutarlas si no es responsable.
    #
    # FIX 2026-05-22 (Aaron Urbina ejecutivo_sstt — brecha listado vacío):
    # `created_by` es un VARCHAR que históricamente guardó lo que devolvió
    # `current_username()` — a veces el email (`username`), a veces el
    # nombre legible. Si los formatos no coinciden, el match LOWER(TRIM())
    # falla y el listado queda VACÍO aunque el calendario sí muestre la OT
    # (ya pasó con Aaron: created_by='Aaron Urbina' (nombre)
    # vs username='urbinaaaron65@gmail.com').
    # Solución defensiva: comparamos contra TODAS las identidades posibles
    # (username, nombre legible) Y además contra el nuevo `created_by_user_id`
    # (FK estable). Si la columna nueva existe → match exacto por id.
    # 2026-06-12 (Daniel) — el ejecutivo SSTT ahora ve TODAS las OTs por
    # defecto (para revisar/corregir en la ventana post-firma del técnico).
    # El filtro "solo mis creadas/asignadas" queda OPT-IN vía ?mias=1.
    # 2026-08-14: la identidad "creadas por mí / asignadas a mí" se calcula
    # SIEMPRE (no solo para el ejecutivo) porque ahora la usan tres cosas:
    # el filtro legacy del ejecutivo (?mias=1), el chip origen=mias de
    # Daniel, y los contadores de los chips. La construcción es la misma
    # de siempre — solo se separan las cláusulas de sus parámetros para
    # poder reusarlas en el COUNT.
    mias_clauses, mias_params = [], []
    if user and not solo_mias:
        username_actual = (user.get("username") or "").strip()
        nombre_actual = (user.get("nombre") or "").strip()
        user_id_actual = user.get("id")
        # Detectar si la columna `created_by_user_id` ya fue migrada.
        # Hacemos un SELECT cheap a INFORMATION_SCHEMA — si falla por
        # cualquier motivo, caemos al match legacy (solo string).
        _has_created_by_user_id = False
        try:
            _col_check = mysql_fetchone(
                "SELECT COUNT(*) AS n FROM INFORMATION_SCHEMA.COLUMNS "
                " WHERE TABLE_SCHEMA = DATABASE() "
                "   AND TABLE_NAME = 'mant_visitas' "
                "   AND COLUMN_NAME = 'created_by_user_id'"
            )
            _has_created_by_user_id = bool((_col_check or {}).get("n"))
        except Exception:
            _has_created_by_user_id = False

        # Match por FK estable (preferido — no depende del formato del string).
        if _has_created_by_user_id and user_id_actual:
            mias_clauses.append("v.created_by_user_id=%s")
            mias_params.append(int(user_id_actual))
        # Match legacy contra `created_by` por username (email) — compat con
        # OTs creadas antes de la migración del FK.
        if username_actual:
            mias_clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            mias_params.append(username_actual)
        # Match legacy contra `created_by` por nombre legible — para OTs donde
        # el string guardó el nombre en vez del email (caso Aaron OT-2026-00008,
        # created_by='Aaron Urbina' vs username='urbinaaaron65@gmail.com').
        if nombre_actual and nombre_actual.lower() != username_actual.lower():
            mias_clauses.append("LOWER(TRIM(v.created_by))=LOWER(TRIM(%s))")
            mias_params.append(nombre_actual)
        # Match como técnico asignado (principal o colaborador).
        if user_id_actual:
            mias_clauses.append("v.tecnico_user_id=%s")
            mias_params.append(int(user_id_actual))
            mias_clauses.append(
                "v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
                "         WHERE tecnico_user_id=%s)"
            )
            mias_params.append(int(user_id_actual))

    # Aplica el filtro de identidad: chip origen=mias (cualquier rol no
    # técnico) O el opt-in histórico del ejecutivo (?mias=1) — misma
    # cláusula, mismo comportamiento del bloque original.
    if mias_clauses and not solo_mias and (
        origen == "mias" or (es_ejecutivo and request.args.get("mias") == "1")
    ):
        where.append("(" + " OR ".join(mias_clauses) + ")")
        params.extend(mias_params)

    # Chip origen=auto: SOLO las OT generadas sin decisión humana por-OT.
    # Doble criterio (cualquiera de los dos la marca): creador no humano
    # (los mismos tokens de la auditoría de auto-creadas + NULL/vacío), o
    # el marcador estable de título que deja cada flujo automático.
    if origen == "auto" and not solo_mias:
        _toks_ph = ",".join(["%s"] * len(_AUTO_CREATED_BY_TOKENS))
        _marc_ph = " OR ".join(["v.titulo LIKE %s"] * len(_OT_TITULOS_AUTO))
        where.append(
            "(v.created_by IS NULL OR TRIM(v.created_by)='' "
            f" OR LOWER(TRIM(v.created_by)) IN ({_toks_ph}) OR ({_marc_ph}))"
        )
        params.extend(list(_AUTO_CREATED_BY_TOKENS))
        params.extend(list(_OT_TITULOS_AUTO))

    # Filtro "mis OTs": muestra TODAS las OTs donde el usuario aparece como
    # técnico, sea como principal (v.tecnico_user_id) o como colaborador en
    # mant_visita_tecnicos.tecnico_user_id (multi-técnico Fracttal).
    # Fallback legacy: si el usuario tiene email match en mant_tecnicos,
    # también ve OTs apuntadas a ese técnico legacy (compat con OTs viejas).
    if solo_mias and user:
        try:
            uid = user.get("id")
            me_tec = mysql_fetchone(
                "SELECT id FROM mant_tecnicos WHERE LOWER(TRIM(email))=LOWER(TRIM(%s)) "
                "AND COALESCE(activo,1)=1 LIMIT 1",
                (user.get("username") or user.get("correo") or user.get("email") or "",)
            ) if (user.get("username") or user.get("correo") or user.get("email")) else None

            if uid:
                # Match principal (v.tecnico_user_id) OR multi-técnico
                # (mant_visita_tecnicos.tecnico_user_id) OR legacy (mant_tecnicos)
                if me_tec:
                    where.append(
                        "(v.tecnico_user_id=%s "
                        " OR v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
                        "             WHERE tecnico_user_id=%s) "
                        " OR v.tecnico_id=%s)"
                    )
                    params.extend([int(uid), int(uid), int(me_tec["id"])])
                else:
                    where.append(
                        "(v.tecnico_user_id=%s "
                        " OR v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
                        "             WHERE tecnico_user_id=%s))"
                    )
                    params.extend([int(uid), int(uid)])
            elif me_tec:
                where.append("v.tecnico_id=%s")
                params.append(int(me_tec["id"]))
            else:
                # No tiene id de usuario ni técnico legacy → no muestra nada
                where.append("1=0")
            # Por defecto, técnico/ejecutivo solo oculta el HISTÓRICO archivado
            # (cerrada/cancelada/anulada). Antes era una lista BLANCA de 3 estados
            # que escondía OTs asignadas en pleno trabajo (creada, asignada,
            # en_ejecucion, firmada_tecnico, pendiente_*, completada) → el técnico
            # no veía su propia OT en la lista aunque sí salía en el calendario.
            # Lista NEGRA: todo el trabajo activo queda visible, coherente con el
            # calendario y la ficha. No toca el filtro de asignación (sin IDOR).
            if (uid or me_tec) and not estado:
                where.append("v.estado NOT IN ('cerrada','cancelada','anulada')")
        except Exception as e_tec:
            print(f"[mant_ots_list solo_mias] error: {e_tec}", flush=True)

    if estado in (
        "creada", "programada", "asignada", "en_curso", "en_ejecucion",
        "firmada_tecnico", "pendiente_info", "pendiente_repuesto",
        "pendiente_aprobacion", "completada", "cerrada", "cancelada",
        "anulada", "reagendada",
    ):
        where.append("v.estado=%s")
        params.append(estado)
    if tipo in ("preventiva", "correctiva", "garantia", "inspeccion", "levantamiento", "instalacion"):
        where.append("v.tipo=%s")
        params.append(tipo)
    if tecnico_id:
        try:
            params.append(int(tecnico_id))
            where.append("v.tecnico_id=%s")
        except (TypeError, ValueError):
            pass
    if cliente_id:
        try:
            params.append(int(cliente_id))
            where.append("v.cliente_id=%s")
        except (TypeError, ValueError):
            pass
    if q:
        # 2026-08-12: se agregó el contacto (de la ficha Y el declarado en
        # la propia OT, que puede diferir) -- Daniel busca sus pruebas por
        # "Juan Daniel Aguilar Tejera" (razón social) pero también por el
        # contacto "prueba", que antes esta búsqueda no encontraba.
        where.append(
            "(c.razon_social LIKE %s OR v.titulo LIKE %s OR v.numero_ot LIKE %s "
            " OR c.contacto_nombre LIKE %s OR v.contacto_nombre LIKE %s)"
        )
        like = f"%{q}%"
        params.extend([like, like, like, like, like])

    # 🔎 Ocultar por defecto el "ruido" no deliberado por OT individual (ver
    # comentario junto a `incluir_auto` más arriba). Se identifica por el
    # marcador estable que cada flujo pone en `titulo` -- ninguno de esos 4
    # flujos asigna numero_ot (confirmado en el código: _mant_intel_accion,
    # mant_visita_historica/crear_proxima, mant_planificador_generar_ots
    # SÍ asigna numero_ot pero el marcador de título sigue siendo único y
    # reconocible). Con `cliente_id IS NOT NULL` de guardia para NUNCA
    # tocar "Trabajo interno" (cliente_id NULL): esas OT las crea a
    # mano un supervisor y Daniel no pidió ocultarlas, solo las de agenda
    # automática. Se desactiva solo con `incluir_auto=1` O apenas hay una
    # búsqueda activa (`q`) -- "a menos que lo busque".
    # (2026-08-14: la tupla _OT_TITULOS_AUTO ahora se define una sola vez,
    # arriba junto al chip `origen`, porque también la usa origen=auto.)
    # El ocultamiento por defecto solo aplica en la vista completa: en
    # origen=mias no hay nada que ocultar (todo es del usuario) y en
    # origen=auto el ruido ES lo que se quiere ver.
    if not incluir_auto and not q and origen in ("", "todas"):
        marcadores = " OR ".join(["v.titulo LIKE %s"] * len(_OT_TITULOS_AUTO))
        where.append(f"NOT (v.cliente_id IS NOT NULL AND ({marcadores}))")
        params.extend(_OT_TITULOS_AUTO)

    ots = []
    kpis = {"total": 0, "programadas": 0, "completadas": 0, "atrasadas": 0}
    tecnicos = []
    fatal_error = None
    try:
        # ── PERF: en vez de 3 subqueries correlacionadas POR fila (~600 queries
        # con LIMIT 200), usamos LEFT JOIN a derivadas agregadas. Total: 1 query.
        sql = (
            "SELECT v.id, v.numero_ot, v.tipo, v.estado, v.titulo, v.descripcion, "
            "       v.fecha_programada, v.hora_inicio, v.hora_fin, v.costo, "
            "       v.cliente_id, c.razon_social, c.comuna AS cli_comuna, "
            "       c.direccion AS cli_direccion, "
            "       v.direccion_visita, v.contacto_nombre, v.contacto_cargo, v.contacto_tel, "
            "       v.tecnico_id, t.nombre AS tecnico_nombre, "
            "       v.created_by, "
            "       COALESCE(tar.n_tareas, 0)    AS n_tareas, "
            "       COALESCE(tar.n_completas, 0) AS n_completas, "
            "       COALESCE(fot.n_fotos, 0)     AS n_fotos "
            "  FROM mant_visitas v "
            # LEFT JOIN (era INNER) 2026-08-10: sin esto, las OT de Trabajo
            # de bodega (cliente_id NULL) nunca aparecían en el listado
            # principal — quedaban invisibles para admin/supervisor.
            "  LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
            "  LEFT JOIN mant_tecnicos t ON t.id=v.tecnico_id "
            "  LEFT JOIN ( "
            "       SELECT visita_id, "
            "              COUNT(*) AS n_tareas, "
            "              SUM(CASE WHEN completada=1 THEN 1 ELSE 0 END) AS n_completas "
            "         FROM mant_visita_tareas "
            "       GROUP BY visita_id"
            "  ) tar ON tar.visita_id = v.id "
            "  LEFT JOIN ( "
            "       SELECT visita_id, COUNT(*) AS n_fotos "
            "         FROM mant_visita_fotos "
            "       GROUP BY visita_id"
            "  ) fot ON fot.visita_id = v.id "
            f" WHERE {' AND '.join(where)} "
            f" {_orden_sql} "
            " LIMIT 200"
        )
        ots = mysql_fetchall(sql, tuple(params)) or []
        ots = [dict(o) for o in ots]
        # Normalizar campos no-JSON-safe (date/time/Decimal) para el JSON
        # de la vista (Kanban/Cards lo consumen client-side).
        for o in ots:
            for k in ('fecha_programada','hora_inicio','hora_fin'):
                if o.get(k) is not None:
                    o[k] = str(o[k])
            if o.get('costo') is not None:
                try: o['costo'] = float(o['costo'])
                except Exception: o['costo'] = None
    except Exception as e:
        # Fallback simple si subqueries fallan (ej. tablas no migradas aún)
        try:
            ots = mysql_fetchall(
                "SELECT v.id, v.numero_ot, v.tipo, v.estado, v.titulo, v.descripcion, "
                "       v.fecha_programada, v.hora_inicio, v.hora_fin, v.costo, "
                "       v.cliente_id, c.razon_social, c.comuna AS cli_comuna, "
                "       c.direccion AS cli_direccion, "
                "       v.direccion_visita, v.contacto_nombre, v.contacto_cargo, v.contacto_tel, "
                "       v.tecnico_id, v.tecnico AS tecnico_nombre, "
                "       v.created_by, "
                "       0 AS n_tareas, 0 AS n_completas, 0 AS n_fotos "
                "  FROM mant_visitas v "
                "  LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
                f" WHERE {' AND '.join(where)} "
                f" {_orden_sql} LIMIT 200",
                tuple(params)
            ) or []
            ots = [dict(o) for o in ots]
            for o in ots:
                for k in ('fecha_programada','hora_inicio','hora_fin'):
                    if o.get(k) is not None:
                        o[k] = str(o[k])
                if o.get('costo') is not None:
                    try: o['costo'] = float(o['costo'])
                    except Exception: o['costo'] = None
        except Exception as e2:
            fatal_error = f"{e} / fallback: {e2}"
            ots = []

    # KPIs respetan el MISMO filtro que la tabla — para que el técnico vea
    # SUS contadores (no los globales del sistema). Antes había un BUG donde
    # mostraba "1 TOTAL" pero la lista filtrada decía 0 (KPI no filtrado).
    try:
        # Reutilizamos el `where` ya construido (incluye solo_mias para tec).
        kpis_sql = (
            "SELECT "
            " COUNT(*) AS total, "
            " SUM(CASE WHEN v.estado='programada' THEN 1 ELSE 0 END) AS programadas, "
            " SUM(CASE WHEN v.estado='completada' THEN 1 ELSE 0 END) AS completadas, "
            " SUM(CASE WHEN v.estado='programada' AND v.fecha_programada < CURDATE() THEN 1 ELSE 0 END) AS atrasadas "
            "FROM mant_visitas v "
            "LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
            f"WHERE {' AND '.join(where)}"
        )
        kpis = mysql_fetchone(kpis_sql, tuple(params)) or kpis
    except Exception as e_kpi:
        print(f"[mant_ots_list kpis] error: {e_kpi}", flush=True)

    try:
        tecnicos = mysql_fetchall(
            "SELECT id, nombre FROM mant_tecnicos WHERE estado='activo' ORDER BY nombre"
        ) or []
        tecnicos = [dict(t) for t in tecnicos]
    except Exception:
        tecnicos = []

    # ── 2026-05-18 (Aaron Urbina fix) ─────────────────────────────
    # Inyectar `puede_aprobar` por OT y un flag global `puede_aprobar_global`
    # para el template. ANTES el template usaba `permissions.admin or
    # permissions.superadmin` literal → ejecutivo_sstt (rol dinámico) no
    # tenía permissions.admin=True, así que el botón "Revisar" jamás
    # aparecía aunque la matriz `_puede_ot_accion('aprobar')` sí lo
    # permitía. Ahora el flag se calcula server-side con la matriz
    # unificada y el template solo lo lee.
    #
    # Por performance NO recalculamos por OT (sería N+1 queries a
    # mant_visitas + mant_visita_tecnicos). En su lugar inferimos:
    #   - si es admin/superadmin/supervisor/ejecutivo (familia) → True
    #     para CUALQUIER OT (matchea la matriz exactamente).
    #   - si NO, fallback al check del creador (created_by ==
    #     user.username, case insensitive + trim).
    # El backend de aprobar-cierre revalida con `_puede_ot_accion`,
    # así que aunque alguien fuerce el botón, el server bloquea.
    puede_aprobar_global = _is_aprobador(user)
    _username_lower = (user.get("username") or "").strip().lower()
    _n_aprob = 0
    _n_pendientes = 0
    for _o in ots:
        if puede_aprobar_global:
            _o["puede_aprobar"] = True
        else:
            _created_by = (_o.get("created_by") or "").strip().lower()
            _o["puede_aprobar"] = bool(_created_by) and _created_by == _username_lower
        if _o.get("puede_aprobar"):
            _n_aprob += 1
        if (_o.get("estado") or "") == "pendiente_aprobacion":
            _n_pendientes += 1

    # 🔍 Log para diagnóstico (Daniel pidió poder ver en Railway logs por qué
    # aparece o no el botón "Revisar" para Aaron). Se emite SIEMPRE.
    print(
        f"[ots_list] user={user.get('username')} role={role_l}->{role_fam} "
        f"mostrando={len(ots)} pendientes_aprobacion={_n_pendientes} "
        f"con_puede_aprobar={_n_aprob} puede_aprobar_global={puede_aprobar_global} "
        f"es_tecnico={es_tecnico} es_ejecutivo={es_ejecutivo} "
        f"solo_mias={solo_mias} ver_todas={ver_todas}",
        flush=True
    )

    # ── Contadores por FASE (creada / gestión / realizada) ──────────────
    # Se calculan sobre el MISMO universo que la tabla está mostrando
    # (mismo `where`, pero sin el filtro de fase), para que los números de
    # las pestañas cuadren con lo que se ve al hacer clic.
    conteos_fase = None
    try:
        _w_sin_fase, _p_sin_fase = [], []
        _i = 0
        for _c in where:
            if _c.startswith("v.estado IN (") and fase:
                _i += len(_FASES[fase])
                continue
            _n = _c.count("%s")
            _w_sin_fase.append(_c)
            _p_sin_fase.extend(params[_i:_i + _n])
            _i += _n
        _cf_sql = (
            "SELECT "
            + ", ".join(
                f"SUM(CASE WHEN v.estado IN ({','.join(['%s'] * len(_est))}) THEN 1 ELSE 0 END) AS {_k}"
                for _k, _est in _FASES.items()
            )
            + " FROM mant_visitas v LEFT JOIN mant_clientes c ON c.id=v.cliente_id "
            + f" WHERE {' AND '.join(_w_sin_fase)}"
        )
        _cf_params = []
        for _est in _FASES.values():
            _cf_params.extend(_est)
        _cf_params.extend(_p_sin_fase)
        _cf = mysql_fetchone(_cf_sql, tuple(_cf_params)) or {}
        conteos_fase = {k: int(_cf.get(k) or 0) for k in _FASES}
    except Exception as _e_cf:
        print(f"[ots_list] conteos por fase fallaron: {_e_cf}", flush=True)

    # ── Contadores de los chips de origen (2026-08-14) ──────────────────
    # Un solo COUNT global con CASE — independiente del filtro activo, para
    # que cada chip muestre cuántas hay "del otro lado" sin tener que
    # hacer clic. Fail-open: si falla, los chips salen sin número.
    conteos_origen = None
    if origen:
        try:
            _cnt_sql = "SELECT COUNT(*) AS total"
            _cnt_params = []
            if mias_clauses:
                _cnt_sql += (", SUM(CASE WHEN (" + " OR ".join(mias_clauses)
                             + ") THEN 1 ELSE 0 END) AS mias")
                _cnt_params.extend(mias_params)
            _toks_ph = ",".join(["%s"] * len(_AUTO_CREATED_BY_TOKENS))
            _marc_ph = " OR ".join(["v.titulo LIKE %s"] * len(_OT_TITULOS_AUTO))
            _cnt_sql += (", SUM(CASE WHEN (v.created_by IS NULL OR TRIM(v.created_by)='' "
                         f" OR LOWER(TRIM(v.created_by)) IN ({_toks_ph}) OR ({_marc_ph})) "
                         "THEN 1 ELSE 0 END) AS auto")
            _cnt_params.extend(list(_AUTO_CREATED_BY_TOKENS))
            _cnt_params.extend(list(_OT_TITULOS_AUTO))
            _cnt_sql += " FROM mant_visitas v"
            _row_cnt = mysql_fetchone(_cnt_sql, tuple(_cnt_params)) or {}
            conteos_origen = {
                "total": int(_row_cnt.get("total") or 0),
                "mias": int(_row_cnt.get("mias") or 0) if mias_clauses else None,
                "auto": int(_row_cnt.get("auto") or 0),
            }
        except Exception as _e_cnt:
            print(f"[ots_list] conteos origen fallaron: {_e_cnt}", flush=True)

    return render_template(
        "mantenciones/ots_list.html",
        ots=ots,
        kpis=kpis,
        tecnicos=tecnicos,
        fatal_error=fatal_error,
        origen=origen,
        conteos_origen=conteos_origen,
        fase=fase,
        conteos_fase=conteos_fase,
        filtros={
            "estado": estado, "tipo": tipo,
            "tecnico_id": tecnico_id, "cliente_id": cliente_id, "q": q,
            "incluir_auto": incluir_auto,
            "solo_ot": solo_ot, "orden": orden, "fase": fase,
        },
        # 🔐 2026-05-18 — Flags de rol para el template (ocultar botones
        # de "Eliminar" / "Editar" que el rol no debería ver).
        es_tecnico=es_tecnico,
        es_ejecutivo=es_ejecutivo,
        ver_todas=ver_todas,
        solo_mias_activo=solo_mias,
        # 2026-05-18 (Aaron Urbina) — Permisos de aprobación inyectados
        # desde la matriz para que el template no use comparaciones de
        # rol literal que no soportan variantes dinámicas (ejecutivo_sstt).
        puede_aprobar_global=puede_aprobar_global,
    )


