@app.route("/mantenciones/api/visitas/<int:vid>/generar-informe", methods=["POST"])
@_mant_required
@_no_tecnico
def mant_visita_generar_informe(vid):
    """Crea un Informe Post Servicio PREFILLADO desde una OT (visita).
    "Subir la OT": toma ticket, Nº OT, cliente, equipos, checklist y
    observaciones de la OT y arma el borrador del informe — con trazabilidad
    TICKET / OT garantizada. Devuelve {ok, id, cliente_id} para abrir el editor.
    Todo es editable luego; la IA puede pulir la redacción."""
    v = mysql_fetchone(
        "SELECT v.*, COALESCE(u.nombre, u.username) AS tecnico_principal "
        "  FROM mant_visitas v "
        "  LEFT JOIN app_users u ON u.id = v.tecnico_user_id "
        " WHERE v.id=%s", (vid,)
    )
    if not v:
        return jsonify({"error": "OT no encontrada"}), 404
    v = dict(v)
    cid = v.get("cliente_id")
    # TODO(2026-08-10, Daniel — Trabajo de bodega sin cliente): una OT interna
    # (tipo='revision_interna') ahora puede tener cliente_id=NULL. El INSERT
    # INTO mant_reportes de más abajo pasa `cid` directo a la columna
    # mant_reportes.cliente_id, que sigue siendo NOT NULL (CREATE TABLE,
    # línea ~48599) — ese INSERT FALLARÁ (1048 Column cannot be null) si
    # alguien pulsa "Subir la OT" desde un Trabajo de bodega. NO se corrige
    # acá (requeriría además volver nullable mant_reportes.cliente_id y
    # revisar cada JOIN/plantilla que asuma cliente en el módulo de
    # Informes — fuera del alcance de esta tarea). Mientras tanto: o se
    # bloquea este botón en el frontend para OT sin cliente_id, o se hace esa
    # migración aparte antes de ofrecerlo.

    # Ticket asociado (trazabilidad)
    tk = mysql_fetchone(
        "SELECT numero_ticket, id, created_at FROM mant_tickets "
        " WHERE visita_id=%s ORDER BY id DESC LIMIT 1", (vid,)
    ) or {}
    ticket_num = str(tk.get("numero_ticket") or tk.get("id") or "").strip()
    ot_num = str(v.get("numero_ot") or v.get("id") or "").strip()

    # Tipo de OT → tipo de informe (mant_reportes.tipo: ENUM más chico que
    # mant_visitas.tipo — 'mantencion','instalacion','inspeccion',
    # 'visita_tecnica','garantia','otro'). NO se amplía ese ENUM acá (fuera
    # de alcance) — se mapea cada tipo de OT al valor EXISTENTE más cercano
    # en criterio de negocio:
    #   - cambio_equipo/desinstalacion → 'instalacion' (trabajo físico sobre
    #     el equipo, misma naturaleza que una instalación).
    #   - capacitacion/revision_interna → 'otro' (no son servicio técnico
    #     sobre un equipo de cliente; revision_interna además puede no
    #     tener cliente — ver TODO arriba).
    #   - repuesto → 'visita_tecnica' (visita a cambiar/instalar un repuesto
    #     puntual, no una instalación completa).
    #   - visita_correctiva → 'visita_tecnica' (mismo criterio que
    #     'correctiva', ya mapeada así).
    #   - control_calidad (tipo nuevo, Tarea 1) → 'inspeccion' (es una
    #     revisión/verificación de productos, misma naturaleza).
    _tipo_map = {"preventiva": "mantencion", "correctiva": "visita_tecnica",
                 "garantia": "garantia", "inspeccion": "inspeccion",
                 "instalacion": "instalacion", "levantamiento": "inspeccion",
                 "cambio_equipo": "instalacion", "desinstalacion": "instalacion",
                 "capacitacion": "otro", "revision_interna": "otro",
                 "repuesto": "visita_tecnica", "visita_correctiva": "visita_tecnica",
                 "control_calidad": "inspeccion"}
    tipo_rep = _tipo_map.get((v.get("tipo") or "").lower(), "visita_tecnica")

    # Equipos de la OT (defensivo con columnas que podrían no existir)
    mids = [r["maquina_id"] for r in (mysql_fetchall(
        "SELECT DISTINCT maquina_id FROM mant_visita_tareas "
        " WHERE visita_id=%s AND maquina_id IS NOT NULL", (vid,)
    ) or []) if r.get("maquina_id")]
    # Observación por equipo (de la revisión en terreno)
    obs_eq = {}
    for r in (mysql_fetchall(
        "SELECT maquina_id, observacion_tecnico FROM mant_visita_equipos WHERE visita_id=%s", (vid,)
    ) or []):
        if r.get("observacion_tecnico"):
            obs_eq[r["maquina_id"]] = r["observacion_tecnico"]
    # Repuestos por equipo (nombre + si es garantía)
    rep_eq = {}
    try:
        for r in (mysql_fetchall(
            "SELECT maquina_id, nombre, tipo FROM mant_repuestos "
            " WHERE visita_id=%s", (vid,)
        ) or []):
            mid = r.get("maquina_id")
            rep_eq.setdefault(mid, {"nombre": r.get("nombre"), "garantia": (r.get("tipo") == "garantia")})
    except Exception:
        pass

    maquinas = []
    for mid in mids:
        m = mysql_fetchone("SELECT * FROM mant_maquinas WHERE id=%s", (mid,)) or {}
        rinfo = rep_eq.get(mid, {})
        maquinas.append({
            "sku": m.get("sku") or "",
            "descripcion": m.get("nombre") or "",
            "cantidad": m.get("cantidad") or 1,
            "modelo": m.get("modelo") or "",
            "serie": m.get("serie") or "",
            "repuesto": rinfo.get("nombre") or "",
            "garantia": "si" if rinfo.get("garantia") else "no",
            "observacion": obs_eq.get(mid) or "",
        })

    # Trabajos realizados = checklist completado
    trabajos = [r["titulo"] for r in (mysql_fetchall(
        "SELECT titulo FROM mant_visita_tareas "
        " WHERE visita_id=%s AND COALESCE(completada,0)=1 AND titulo IS NOT NULL "
        " ORDER BY orden, id", (vid,)
    ) or []) if (r.get("titulo") or "").strip()]

    # Observaciones generales = diagnóstico / observaciones de cierre
    observaciones = []
    for campo in ("diagnostico", "observaciones"):
        val = (v.get(campo) or "").strip()
        if val:
            observaciones.append(val)

    def _to_date(x):
        if not x:
            return None
        try:
            return x.date().isoformat() if hasattr(x, "date") else str(x)[:10]
        except Exception:
            return str(x)[:10]

    asunto = (v.get("titulo") or "").strip() or f"Visita técnica — OT {ot_num}"
    antecedentes = (v.get("descripcion") or "").strip()

    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO mant_reportes
                   (cliente_id,tipo,estado,ticket_num,ot_num,visita_id,asunto,
                    tecnico_junior,tecnico_senior,fecha_solicitado,fecha_inicio,fecha_cierre,
                    antecedentes,objetivos,trabajos,observaciones,maquinas_json,
                    garantia_aplica,created_by)
                   VALUES (%s,%s,'borrador',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                (cid, tipo_rep, ticket_num, ot_num, vid, asunto,
                 "", v.get("tecnico_principal") or v.get("tecnico") or "",
                 _to_date(tk.get("created_at")) or _to_date(v.get("created_at")),
                 _to_date(v.get("fecha_programada")) or _to_date(v.get("hora_real_inicio")),
                 _to_date(v.get("cerrada_at")),
                 antecedentes,
                 json.dumps([], ensure_ascii=False),
                 json.dumps(trabajos, ensure_ascii=False),
                 json.dumps(observaciones, ensure_ascii=False),
                 json.dumps(maquinas, ensure_ascii=False),
                 1 if (v.get("tipo") == "garantia") else 0,
                 current_username())
            )
            rid = cur.lastrowid
        conn.commit()
        try:
            _mant_log("reporte", rid, "creado_desde_ot",
                      f"OT {ot_num} / Ticket {ticket_num} → {len(maquinas)} equipo(s)")
        except Exception: pass
        try: _save_reporte_html_snapshot(rid)
        except Exception: pass
        return jsonify({"ok": True, "id": rid, "cliente_id": cid,
                        "ticket_num": ticket_num, "ot_num": ot_num})
    finally:
        conn.close()


@app.route("/mantenciones/api/clientes/<int:cid>/reportes/redactar-ia", methods=["POST"])
@_mant_required
@_no_tecnico
def mant_reporte_redactar_ia(cid):
    """IA redacta el contenido narrativo del Informe Post Servicio.

    A partir de los datos crudos del borrador (asunto, antecedentes/solicitud,
    notas rápidas del técnico y máquinas intervenidas) genera objetivos,
    trabajos realizados, observaciones generales y una observación/recomendación
    por máquina, en tono profesional chileno. NO guarda nada: devuelve el JSON
    para que el usuario lo revise en el formulario y luego guarde."""
    if not _ia_enabled():
        return jsonify({"ok": False, "error": _IA_OFF_MSG}), 503
    cli = mysql_fetchone("SELECT razon_social FROM mant_clientes WHERE id=%s", (cid,))
    if not cli:
        return jsonify({"error": "Cliente no encontrado"}), 404
    d = request.get_json(silent=True) or {}
    tipo     = (d.get("tipo") or "mantencion").strip()
    asunto   = (d.get("asunto") or "").strip()
    ante     = (d.get("antecedentes") or "").strip()
    notas    = (d.get("notas") or "").strip()
    garantia = _parse_garantia_aplica(d.get("garantia_aplica"))
    maquinas = d.get("maquinas") or []
    if isinstance(maquinas, str):
        try: maquinas = json.loads(maquinas)
        except Exception: maquinas = []
    if not (asunto or ante or notas or maquinas):
        return jsonify({"error": "Faltan datos. Escribe al menos el asunto, la solicitud "
                                 "del cliente o unas notas para que la IA redacte."}), 400

    tipo_lbl = {"mantencion": "Mantención preventiva", "instalacion": "Instalación",
                "inspeccion": "Inspección técnica",
                "visita_tecnica": "Visita técnica / reparación",
                "otro": "Servicio técnico"}.get(tipo, "Servicio técnico")
    cobertura = ("Garantía (sin costo para el cliente)" if garantia
                 else "Servicio pagado (puede recomendarse cotización si corresponde)")

    # Resumen compacto y legible de las máquinas para el prompt.
    maq_txt = ""
    for i, m in enumerate(maquinas, 1):
        if not isinstance(m, dict):
            continue
        det = []
        if m.get("modelo"):   det.append(f"modelo {m['modelo']}")
        if m.get("serie"):    det.append(f"serie {m['serie']}")
        if m.get("repuesto"): det.append(f"repuesto declarado: {m['repuesto']}")
        if str(m.get("garantia") or "").strip():
            det.append(f"garantía: {m['garantia']}")
        linea = f"SKU {m.get('sku') or '—'} · {m.get('descripcion') or 'equipo sin descripción'}"
        if det:
            linea += " (" + "; ".join(det) + ")"
        maq_txt += f"  {i}. {linea}\n"
    maq_txt = maq_txt or "  (el técnico no declaró equipos específicos)\n"

    # ── PROMPT (sistema): rol experto + estilo + reglas anti-invención + few-shot.
    prompt_sistema = """Eres REDACTOR TÉCNICO SENIOR de ILUS Fitness (marca de Sport and Health \
Solutions SPA, Chile), experto en servicio técnico de equipamiento de gimnasio: trotadoras/cintas \
de correr, elípticas, bicicletas (spinning, vertical, recumbent) y máquinas de fuerza \
(selectorizadas, poleas, prensas).

MISIÓN: convertir las notas rápidas y desordenadas de un técnico en terreno —más los datos de los \
equipos— en un INFORME POST SERVICIO profesional, ordenado y listo para enviar al cliente. El \
técnico ahorra tiempo: tú redactas en limpio y con criterio técnico.

REGLAS DE ESTILO (obligatorias):
1. Español de Chile, formal y neutro. Tercera persona impersonal: "Se realiza", "Se verifica", \
"Se reemplaza", "Se recomienda". Nunca en primera persona.
2. Una idea por ítem; frases concretas y técnicas. Cero relleno, cero marketing, cero superlativos.
3. Terminología correcta del rubro: banda de trote, motor (AC/DC), placa controladora, \
consola/tarjeta, sensor de velocidad, rodamientos, piola o cable de acero, polea, sistema \
selectorizado, etc.
4. NUNCA inventes datos. No inventes seriales, SKUs, modelos, mediciones, valores ni repuestos que \
no aparezcan en la información entregada. Si un dato falta, no lo menciones. Mejor breve y veraz que \
largo e inventado.
5. Coherencia: los "trabajos" deben responder a los "objetivos"; las "observaciones" cierran con el \
estado final del equipo y recomendaciones accionables (próxima mantención, repuestos a cotizar, \
condiciones del lugar de instalación).
6. Cobertura: si el servicio es en GARANTÍA, no sugieras cobros al cliente; si es PAGADO, puedes \
recomendar cotizaciones cuando corresponda.

CRITERIO PROFESIONAL (sé inteligente, no un loro):
- Ordena y completa la REDACCIÓN y la ESTRUCTURA con criterio de un técnico competente: si las notas \
dicen "cambié el controlador y quedó andando", infiere y describe los pasos lógicos del procedimiento \
(desmontaje, reemplazo, prueba de funcionamiento) expresados con propiedad. PERO sigue PROHIBIDO \
inventar DATOS DUROS: seriales, SKUs, modelos, marcas, mediciones o valores en pesos solo si vienen.
- Agrega recomendaciones técnicas PERTINENTES al equipo cuando aporten valor real:
  · Trotadoras/cintas: lubricación y centrado de banda, limpieza interna, circuito eléctrico estable.
  · Máquinas de fuerza: inspección y tensado de piolas y poleas, lubricación de guías, ajuste de pernos.
  · Bicicletas/elípticas: consola, sistema de resistencia, rodamientos y pedales.
- Cierra con la próxima acción cuando aplique (p. ej. mantención preventiva sugerida cada 3 meses).

GUÍA SEGÚN EL TIPO DE SERVICIO:
- Mantención preventiva → revisión, limpieza, lubricación y ajustes; cierra con estado general y próxima mantención.
- Instalación → armado, nivelación, puesta en marcha, pruebas y entrega/capacitación al cliente.
- Reparación / visita técnica → estructura: diagnóstico → causa raíz → solución aplicada → resultado.
- Inspección → estado de cada componente y recomendaciones priorizadas.

SI HAY POCA INFORMACIÓN: redacta SOLO lo que las notas respaldan, de forma profesional y breve. No \
rellenes con relleno vacío; un informe corto es válido si la visita fue simple.

CONTENIDO A GENERAR:
- asunto_sugerido: título corto y profesional del informe (ej.: "Reemplazo de placa controladora — Trotadora X3-S").
- antecedentes: 1 a 3 frases que formalizan la solicitud o falla reportada por el cliente.
- objetivos: 2 a 5 ítems con lo que se buscaba lograr en la visita.
- trabajos: 3 a 8 ítems con las intervenciones efectivamente realizadas, en orden lógico.
- observaciones: 2 a 5 ítems con hallazgos, estado final y recomendaciones.
- maquinas: UNA entrada por cada equipo recibido, con su SKU intacto y una observación/recomendación \
técnica específica de ESE equipo.

EJEMPLO DE TONO (referencia de estilo, NO lo copies literal):
  antecedentes: "El cliente reporta que la trotadora no enciende al accionar el interruptor principal."
  trabajos: ["Se mide el voltaje en la toma de alimentación, verificando 220 V estables.",
             "Se reemplaza la placa controladora por una unidad nueva.",
             "Se ejecuta prueba de funcionamiento en velocidad baja, media y alta sin observaciones."]
  observaciones: ["Se recomienda conectar el equipo a un circuito eléctrico exclusivo para evitar caídas de tensión."]

SALIDA: responde SOLO con un JSON válido con EXACTAMENTE estas claves: asunto_sugerido, \
antecedentes, objetivos, trabajos, observaciones, maquinas. Sin ningún texto fuera del JSON."""

    # ── PROMPT (usuario): el contexto real del informe.
    prompt_usuario = f"""EMPRESA QUE EJECUTA EL SERVICIO: ILUS Fitness.
CLIENTE: {cli['razon_social']}
TIPO DE SERVICIO: {tipo_lbl}
COBERTURA: {cobertura}
ASUNTO ACTUAL: {asunto or '(vacío — propón uno en asunto_sugerido)'}
SOLICITUD / ANTECEDENTES DEL CLIENTE: {ante or '(no especificado)'}

NOTAS RÁPIDAS DEL TÉCNICO (materia prima; pueden venir incompletas o desordenadas):
-----
{notas or '(sin notas)'}
-----

EQUIPOS INTERVENIDOS:
{maq_txt}
Redacta el Informe Post Servicio en el JSON pedido, fiel a estas notas y datos."""

    resultado, err = _claude_call(
        prompt_usuario, prompt_sistema,
        max_tokens=3000, expect_json=True, tier="sonnet", temperature=0.35,
        log_endpoint="reporte_redactar_ia", log_entidad_tipo="cliente", log_entidad_id=cid,
    )
    if err:
        return jsonify({"error": f"Error IA: {err}"}), 503
    if not resultado or not isinstance(resultado, dict):
        return jsonify({"error": "La IA no devolvió un borrador válido. Reintenta."}), 503

    # Normalizar: listas de strings limpias.
    def _clean_list(v):
        if isinstance(v, str):
            v = [v]
        return [str(x).strip() for x in (v or []) if str(x).strip()]
    salida = {
        "asunto_sugerido": (resultado.get("asunto_sugerido") or "").strip(),
        "antecedentes": (resultado.get("antecedentes") or "").strip(),
        "objetivos":    _clean_list(resultado.get("objetivos")),
        "trabajos":     _clean_list(resultado.get("trabajos")),
        "observaciones": _clean_list(resultado.get("observaciones")),
        "maquinas": [
            {"sku": str(m.get("sku") or "").strip(),
             "observacion": str(m.get("observacion") or "").strip()}
            for m in (resultado.get("maquinas") or []) if isinstance(m, dict)
        ],
    }
    try:
        _mant_log("cliente", cid, "reporte_redactado_ia",
                  f"obj={len(salida['objetivos'])} trab={len(salida['trabajos'])}")
    except Exception:
        pass
    return jsonify({"ok": True, "resultado": salida})


@app.route("/mantenciones/api/reportes/<int:rid>", methods=["GET"])
@_mant_required
def mant_reporte_get(rid):
    r = mysql_fetchone("SELECT * FROM mant_reportes WHERE id=%s", (rid,))
    if not r: return jsonify({"error":"No encontrado"}), 404
    d = dict(r)
    for k in ("fecha_solicitado","fecha_inicio","fecha_cierre","ai_fecha","created_at","updated_at"):
        if d.get(k): d[k] = str(d[k])[:10]
    for k in ("objetivos","trabajos","observaciones","maquinas_json","fotos_json","ai_acciones"):
        d[k] = json.loads(d[k] or "[]")
    # Garantía transversal → bool limpio para el frontend (default False si la
    # columna aún no existe en esta instancia).
    d["garantia_aplica"] = bool(d.get("garantia_aplica"))
    # Adjuntos
    fotos = mysql_fetchall(
        "SELECT id,nombre,archivo_path,cloudinary_url,tipo,created_at FROM mant_contrato_adjuntos "
        "WHERE contrato_id=%s AND tipo='imagen' ORDER BY created_at", (rid,)
    )
    d["fotos"] = [{"id":f["id"],"nombre":f["nombre"],
                   "url": (f.get("cloudinary_url")
                           or f"/static/uploads/mantenciones/reportes/{f['archivo_path']}")} for f in fotos]
    return jsonify(d)


@app.route("/mantenciones/api/reportes/<int:rid>", methods=["PUT"])
@_mant_required
def mant_reporte_update(rid):
    # Permisos (Daniel 30/05/2026): el superadmin edita cualquier reporte. El
    # EJECUTIVO (Aarón) puede COMPLETAR su propio reporte mientras está en
    # 'borrador' (subir fotos, análisis IA, guardar contenido que él mismo creó).
    # NO puede editar reportes de otros ni ya emitidos/entregados.
    _rep_perm = mysql_fetchone("SELECT created_by, estado FROM mant_reportes WHERE id=%s", (rid,))
    _es_super = bool((getattr(g, 'permissions', {}) or {}).get('superadmin'))
    _es_creador_borrador = bool(
        _rep_perm
        and (_rep_perm.get('created_by') == current_username())
        and (str(_rep_perm.get('estado') or 'borrador') == 'borrador')
    )
    if not (_es_super or _es_creador_borrador):
        return jsonify({"error": "Solo el superadministrador puede editar reportes ya emitidos o de otros usuarios."}), 403
    d = request.get_json(silent=True) or {}
    allowed = ["tipo","estado","ticket_num","ot_num","visita_id","asunto",
               "tecnico_junior","tecnico_senior",
               "fecha_solicitado","fecha_inicio","fecha_cierre",
               "antecedentes","objetivos","trabajos","observaciones","maquinas_json",
               # Garantía transversal (separada del tipo de servicio)
               "garantia_aplica"]
    sets, vals = [], []
    for f in allowed:
        if f not in d: continue
        if f in ("objetivos","trabajos","observaciones","maquinas_json"):
            sets.append(f"{f}=%s")
            vals.append(json.dumps(d[f], ensure_ascii=False))
        elif f == "garantia_aplica":
            # Booleano: NO usar `or None` (False quedaría NULL). Coerción a 0/1.
            sets.append(f"{f}=%s")
            vals.append(1 if _parse_garantia_aplica(d[f]) else 0)
        else:
            sets.append(f"{f}=%s")
            vals.append(d[f] or None)
    if not sets: return jsonify({"error":"Sin campos"}), 400
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(f"UPDATE mant_reportes SET {','.join(sets)} WHERE id=%s", vals+[rid])
        conn.commit()
        # Regenerar snapshot HTML
        try: _save_reporte_html_snapshot(rid)
        except Exception: pass
        # Log
        rep_info = mysql_fetchone("SELECT cliente_id, asunto, ticket_num FROM mant_reportes WHERE id=%s", (rid,))
        campos_mod = ", ".join([f for f in allowed if f in d][:6])
        _mant_log("reporte", rid, "actualizado", f"campos: {campos_mod}")
        if rep_info:
            _mant_log("cliente", rep_info["cliente_id"], "reporte_actualizado",
                      f"#{rep_info.get('ticket_num') or rid} — {rep_info.get('asunto') or ''}")
        return jsonify({"ok": True})
    finally:
        conn.close()


