@app.route("/mantenciones/api/reportes/<int:rid>/fotos", methods=["POST"])
@_mant_required
def mant_reporte_foto_subir(rid):
    """Sube foto al registro fotográfico del reporte.

    Persiste en Cloudinary (almacenamiento permanente). El filesystem de Railway
    es EFÍMERO: lo guardado solo en local se pierde en cada deploy. Por eso la
    foto va primero a Cloudinary y el archivo local queda solo como respaldo."""
    f = request.files.get("foto")
    if not f or not f.filename:
        return jsonify({"error":"Sin archivo"}), 400
    ext = f.filename.rsplit(".",1)[-1].lower()
    if ext not in ALLOWED_REPORT_IMG:
        return jsonify({"error":"Tipo no permitido"}), 400
    fname  = secure_filename(f"rep{rid}_{int(time.time())}_{f.filename}")

    # 1) Cloudinary (persistente). Si no está configurado, caemos a local.
    cloud_url = None
    cloud_pid = None
    size = 0
    try:
        f.stream.seek(0)
        _res = _cloud_upload_image_full(
            f.stream, public_id=f"rep{rid}_{int(time.time())}", folder="ilus/reportes"
        )
        cloud_url = _res.get("url")
        cloud_pid = _res.get("public_id")
        size = _res.get("size", 0)
    except Exception as e_cld:
        print(f"[reporte_foto] Cloudinary no disponible, uso backup local: {e_cld}", flush=True)

    # 2) Respaldo local (no bloqueante; fallback si Cloudinary no estaba).
    try:
        f.stream.seek(0)
        fpath = os.path.join(MANT_REPORTES_UPLOADS, fname)
        f.save(fpath)
        if not size:
            try: size = os.path.getsize(fpath)
            except Exception: size = 0
    except Exception as e_loc:
        print(f"[reporte_foto] backup local falló: {e_loc}", flush=True)
        if not cloud_url:
            return jsonify({"error": "No se pudo guardar la foto. Reintenta."}), 502

    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO mant_contrato_adjuntos
                   (contrato_id,cliente_id,tipo,nombre,archivo_nombre,archivo_path,
                    cloudinary_url,cloudinary_public_id,
                    mime_type,tamaño_bytes,created_by)
                   SELECT %s,cliente_id,'imagen',%s,%s,%s,%s,%s,%s,%s,%s
                   FROM mant_reportes WHERE id=%s""",
                (rid, f.filename, f.filename, fname,
                 cloud_url, cloud_pid,
                 f"image/{ext}", size, current_username(), rid)
            )
            aid = cur.lastrowid
        conn.commit()
        # Log
        rep_info = mysql_fetchone("SELECT cliente_id FROM mant_reportes WHERE id=%s", (rid,))
        _mant_log("reporte", rid, "foto_subida", f.filename)
        if rep_info:
            _mant_log("cliente", rep_info["cliente_id"], "reporte_foto_subida",
                      f"reporte #{rid} — {f.filename}")
        url = cloud_url or f"/static/uploads/mantenciones/reportes/{fname}"
        return jsonify({"ok":True, "id":aid, "url":url, "nombre":f.filename})
    finally:
        conn.close()


@app.route("/mantenciones/api/reportes/<int:rid>/analizar-ia", methods=["POST"])
@_mant_required
def mant_reporte_analizar(rid):
    """Análisis IA del reporte: diagnóstico, acciones sugeridas, alertas."""
    if not _ia_enabled():
        return jsonify({"ok": False, "error": _IA_OFF_MSG}), 503
    r = mysql_fetchone("SELECT r.*, c.razon_social FROM mant_reportes r "
                       "JOIN mant_clientes c ON c.id=r.cliente_id WHERE r.id=%s", (rid,))
    if not r: return jsonify({"error":"No encontrado"}), 404

    maquinas  = json.loads(r.get("maquinas_json") or "[]")
    trabajos  = json.loads(r.get("trabajos") or "[]")
    obs       = json.loads(r.get("observaciones") or "[]")
    ai_key    = _get_ai_key()
    if not ai_key:
        return jsonify({"error":"API IA no configurada"}), 503

    prompt = f"""Eres el sistema de análisis técnico de ILUS Fitness (marca de Sport and Health Solutions SPA).
Analiza este Informe Post Servicio y genera un diagnóstico inteligente.

CLIENTE: {r['razon_social']}
TIPO: {r['tipo']}
TICKET: {r['ticket_num']}
TÉCNICO: {r['tecnico_junior']} / Senior: {r['tecnico_senior']}
FECHAS: {r['fecha_inicio']} → {r['fecha_cierre']}

ANTECEDENTES:
{r.get('antecedentes','')}

TRABAJOS REALIZADOS:
{chr(10).join(f'• {t}' for t in trabajos)}

OBSERVACIONES:
{chr(10).join(f'• {o}' for o in obs)}

EQUIPOS INTERVENIDOS:
{chr(10).join(f'• {m.get("sku","")} {m.get("descripcion","")} x{m.get("cantidad",1)}: {m.get("observacion","")}' for m in maquinas)}

Responde SOLO en JSON con esta estructura:
{{
  "diagnostico": "Diagnóstico técnico conciso (2-3 párrafos)",
  "estado_flota": "bueno|regular|critico",
  "indice_salud": 0-100,
  "acciones": [
    {{"urgencia":"alta|media|baja","tipo":"correctiva|preventiva|cotizacion|seguimiento|contrato",
      "titulo":"...", "descripcion":"...", "plazo":"...", "costo_estimado":null_o_numero}}
  ],
  "piezas_criticas": ["parte1","parte2"],
  "notificaciones_sugeridas": [
    {{"tipo":"email|sistema","titulo":"...","mensaje":"...","destinatario":"cliente|tecnico|admin"}}
  ],
  "requiere_cotizacion": true_o_false,
  "items_cotizacion": [{{"sku":"","descripcion":"","cant":1,"precio_unit":0}}]
}}"""

    try:
        import anthropic as _anthropic
        client = _anthropic.Anthropic(api_key=ai_key, timeout=60)
        msg = client.messages.create(
            model="claude-opus-4-5", max_tokens=2000,
            messages=[{"role":"user","content":prompt}]
        )
        raw = msg.content[0].text.strip()
        if raw.startswith("```"):
            raw = raw.split("```")[1]
            if raw.startswith("json"): raw = raw[4:]
        resultado = json.loads(raw)
    except Exception as e:
        return jsonify({"error":f"Error IA: {e}"}), 500

    # Guardar diagnóstico + crear notificaciones sugeridas automáticamente
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE mant_reportes SET ai_diagnostico=%s, ai_acciones=%s, "
                "ai_fecha=%s, ai_usuario=%s WHERE id=%s",
                (resultado.get("diagnostico",""),
                 json.dumps(resultado.get("acciones",[]), ensure_ascii=False),
                 datetime.now(), current_username(), rid)
            )
            # Crear notificaciones sugeridas automáticamente
            for n in resultado.get("notificaciones_sugeridas",[]):
                cur.execute(
                    """INSERT INTO mant_notificaciones
                       (cliente_id,entidad,entidad_id,tipo,titulo,mensaje,
                        canal,estado,created_by)
                       VALUES (%s,'reporte',%s,'ai_alerta',%s,%s,%s,'pendiente',%s)""",
                    (r["cliente_id"], rid, n.get("titulo",""),
                     n.get("mensaje",""), n.get("tipo","sistema"),
                     current_username())
                )
        conn.commit()
        _mant_log("reporte", rid, "analizado_ia",
                  f"salud={resultado.get('indice_salud')} estado={resultado.get('estado_flota')}")
        # Regenerar snapshot HTML con IA incorporada
        try: _save_reporte_html_snapshot(rid)
        except Exception: pass
        return jsonify({"ok":True, "resultado":resultado})
    finally:
        conn.close()


# ══════════════════════════════════════════════════════════════════════
#  REPORTES — exportación Word + envío email
# ══════════════════════════════════════════════════════════════════════

def _build_reporte_docx(rep, cliente):
    """Genera un DOCX corporativo del reporte. Devuelve bytes."""
    try:
        from docx import Document
        from docx.shared import Pt, RGBColor, Cm, Inches
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml.ns import qn
        from docx.oxml import OxmlElement
    except ImportError:
        # python-docx no instalado — construir HTML simulado descargable como .doc
        return None

    import io as _io
    doc = Document()

    # Márgenes
    for s in doc.sections:
        s.top_margin    = Cm(2.0)
        s.bottom_margin = Cm(2.0)
        s.left_margin   = Cm(2.0)
        s.right_margin  = Cm(2.0)

    # Estilo
    style = doc.styles['Normal']
    style.font.name = 'Calibri'
    style.font.size = Pt(10)

    # Título
    h = doc.add_paragraph()
    h.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = h.add_run("INFORME POST-SERVICIO")
    run.bold = True
    run.font.size = Pt(18)
    run.font.color.rgb = RGBColor(0xCC, 0x00, 0x00)
    sub = doc.add_paragraph()
    sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
    sr = sub.add_run(f"{ILUS_BRAND} — {ILUS_LEGAL}  |  RUT {ILUS_RUT}")
    sr.font.size = Pt(9)
    sr.font.color.rgb = RGBColor(0x6B, 0x72, 0x80)

    doc.add_paragraph()

    # Tabla cabecera (cliente / ticket / técnicos / fechas)
    tbl = doc.add_table(rows=4, cols=2)
    tbl.style = 'Light Grid Accent 2'
    info = [
        ("Cliente",      cliente.get('razon_social','—')),
        ("RUT",          cliente.get('rut','—')),
        ("Ticket",       rep.get('ticket_num','—')),
        ("Asunto",       rep.get('asunto','—')),
    ]
    for i,(k,v) in enumerate(info):
        tbl.cell(i,0).text = k
        tbl.cell(i,1).text = str(v)
    for row in tbl.rows:
        row.cells[0].paragraphs[0].runs[0].bold = True

    doc.add_paragraph()

    # Datos del servicio
    p = doc.add_paragraph()
    p.add_run("DATOS DEL SERVICIO").bold = True
    p.runs[0].font.size = Pt(11)
    p.runs[0].font.color.rgb = RGBColor(0xCC, 0x00, 0x00)

    svc = doc.add_table(rows=4, cols=2)
    svc.style = 'Light Grid Accent 2'
    svc_data = [
        ("Tipo",            rep.get('tipo','—')),
        ("Estado",          rep.get('estado','—')),
        ("Técnico Junior",  rep.get('tecnico_junior','—')),
        ("Técnico Senior",  rep.get('tecnico_senior','—')),
    ]
    for i,(k,v) in enumerate(svc_data):
        svc.cell(i,0).text = k
        svc.cell(i,1).text = str(v) if v else '—'
        svc.rows[i].cells[0].paragraphs[0].runs[0].bold = True

    doc.add_paragraph()

    # Antecedentes
    if rep.get('antecedentes'):
        doc.add_paragraph().add_run("ANTECEDENTES").bold = True
        doc.add_paragraph(rep['antecedentes'])

    # Listas (objetivos, trabajos, observaciones)
    for label, key in [("OBJETIVOS","objetivos"), ("TRABAJOS REALIZADOS","trabajos"), ("OBSERVACIONES","observaciones")]:
        items = rep.get(key) or []
        if isinstance(items, str):
            try: items = json.loads(items)
            except: items = []
        if items:
            doc.add_paragraph().add_run(label).bold = True
            for it in items:
                doc.add_paragraph(str(it), style='List Bullet')

    # Equipos / máquinas
    maquinas = rep.get('maquinas_json') or []
    if isinstance(maquinas, str):
        try: maquinas = json.loads(maquinas)
        except: maquinas = []
    if maquinas:
        doc.add_paragraph().add_run("EQUIPOS ATENDIDOS").bold = True
        mt = doc.add_table(rows=1, cols=4)
        mt.style = 'Light Grid Accent 2'
        hdr = mt.rows[0].cells
        for i,h in enumerate(['Equipo','SKU/Serie','Estado','Notas']):
            hdr[i].text = h
            hdr[i].paragraphs[0].runs[0].bold = True
        for m in maquinas:
            row = mt.add_row().cells
            row[0].text = str(m.get('nombre',''))
            row[1].text = str(m.get('sku','') or m.get('serie',''))
            row[2].text = str(m.get('estado','OK'))
            row[3].text = str(m.get('notas',''))

    # Análisis IA
    if rep.get('ai_diagnostico'):
        doc.add_paragraph()
        p = doc.add_paragraph()
        p.add_run("DIAGNÓSTICO TÉCNICO IA").bold = True
        p.runs[0].font.color.rgb = RGBColor(0x7C, 0x3A, 0xED)
        doc.add_paragraph(rep['ai_diagnostico'])

    acciones = rep.get('ai_acciones') or []
    if isinstance(acciones, str):
        try: acciones = json.loads(acciones)
        except: acciones = []
    if acciones:
        doc.add_paragraph().add_run("ACCIONES SUGERIDAS").bold = True
        for a in acciones:
            doc.add_paragraph(str(a), style='List Bullet')

    # Pie
    doc.add_paragraph()
    foot = doc.add_paragraph()
    foot.alignment = WD_ALIGN_PARAGRAPH.CENTER
    fr = foot.add_run(f"Generado el {_now_chile_str('%d/%m/%Y %H:%M')} — {ILUS_BRAND} · {ILUS_LEGAL}")
    fr.font.size = Pt(8)
    fr.font.color.rgb = RGBColor(0x9C, 0xA3, 0xAF)

    buf = _io.BytesIO()
    doc.save(buf)
    buf.seek(0)
    return buf.getvalue()


def _reporte_to_html(rep, cliente):
    """Genera HTML del reporte con estilos INLINE (email-safe; los clientes de
    correo descartan <style>). Para preview/snapshot en pantalla se usa el
    documento corporativo completo (_reporte_to_pdf_html)."""
    from markupsafe import escape as _esc
    def e(v):
        s = "" if v is None else str(v).strip()
        return str(_esc(s)) if s else "—"
    def e_raw(v):
        return str(_esc("" if v is None else str(v)))

    def _ls(items):
        if isinstance(items, str):
            try: items = json.loads(items)
            except Exception: items = []
        items = [i for i in (items or []) if str(i).strip()]
        if not items:
            return '<p style="margin:4px 0;color:#9ca3af;font-style:italic">Sin información registrada.</p>'
        lis = ''.join(
            f'<li style="margin-bottom:5px;color:#374151">{e_raw(i)}</li>' for i in items
        )
        return f'<ul style="margin:6px 0 4px 22px;padding:0">{lis}</ul>'

    def _sec(titulo):
        return (f'<div style="background:#0a0a0a;color:#fff;font-size:12px;font-weight:700;'
                f'letter-spacing:.6px;text-transform:uppercase;padding:6px 12px;'
                f'border-left:5px solid #dc2626;border-radius:6px;margin:18px 0 8px">{e_raw(titulo)}</div>')

    maq = rep.get('maquinas_json') or []
    if isinstance(maq, str):
        try: maq = json.loads(maq)
        except Exception: maq = []
    maq_html = ''
    if maq:
        filas = ''
        for m in maq:
            filas += (
                '<tr>'
                f'<td style="padding:7px 9px;border:1px solid #e5e7eb;font-size:12px">{e(m.get("sku"))}</td>'
                f'<td style="padding:7px 9px;border:1px solid #e5e7eb;font-size:12px">{e(m.get("descripcion"))}</td>'
                f'<td style="padding:7px 9px;border:1px solid #e5e7eb;font-size:12px;text-align:center">{e(m.get("cantidad") or 1)}</td>'
                f'<td style="padding:7px 9px;border:1px solid #e5e7eb;font-size:12px;text-align:center">{e(m.get("garantia"))}</td>'
                f'<td style="padding:7px 9px;border:1px solid #e5e7eb;font-size:12px;color:#374151">{e(m.get("observacion"))}</td>'
                '</tr>'
            )
        maq_html = (
            _sec("Máquinas / equipos intervenidos")
            + '<table style="width:100%;border-collapse:collapse;margin:6px 0 4px">'
            '<thead><tr style="background:#0a0a0a;color:#fff">'
            '<th style="text-align:left;padding:7px 9px;font-size:11px">SKU</th>'
            '<th style="text-align:left;padding:7px 9px;font-size:11px">Descripción</th>'
            '<th style="padding:7px 9px;font-size:11px">Cant.</th>'
            '<th style="padding:7px 9px;font-size:11px">Garantía</th>'
            '<th style="text-align:left;padding:7px 9px;font-size:11px">Observación</th>'
            f'</tr></thead><tbody>{filas}</tbody></table>'
        )

    ai_block = ''
    if rep.get('ai_diagnostico'):
        ai_block = (
            '<div style="background:#faf5ff;border:1px solid #ddd6fe;border-radius:10px;'
            'padding:14px 18px;margin:18px 0">'
            '<div style="font-size:11px;font-weight:800;color:#7c3aed;text-transform:uppercase;'
            'letter-spacing:.5px;margin-bottom:6px">Diagnóstico técnico (IA)</div>'
            f'<div style="font-size:13px;line-height:1.55;color:#374151">{e_raw(rep["ai_diagnostico"]).strip()}</div></div>'
        )

    tipo_lbl = {"mantencion": "Mantención", "instalacion": "Instalación",
                "inspeccion": "Inspección", "garantia": "Garantía",
                "otro": "Servicio Técnico"}.get((rep.get("tipo") or "").lower(), "Servicio Técnico")
    tecnicos = e(rep.get('tecnico_senior'))
    if rep.get('tecnico_junior'):
        tecnicos += f' · {e_raw(rep.get("tecnico_junior"))}'
    ante = (f'{_sec("Antecedentes")}<p style="font-size:13px;line-height:1.55;color:#374151;margin:4px 0">'
            f'{e_raw(rep["antecedentes"]).strip()}</p>') if rep.get('antecedentes') else ''

    def _kv(k, v):
        return (f'<tr><td style="padding:7px 10px;border:1px solid #e5e7eb;background:#f8fafc;'
                f'font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:.3px;'
                f'color:#374151;width:130px">{e_raw(k)}</td>'
                f'<td style="padding:7px 10px;border:1px solid #e5e7eb;font-size:12.5px">{v}</td></tr>')

    return f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Informe — {e(cliente.get('razon_social'))}</title></head>
<body style="font-family:'Segoe UI',-apple-system,Arial,sans-serif;color:#111827;max-width:740px;margin:0 auto;padding:0;background:#fff">
  <div style="background:#0a0a0a;border-radius:12px;padding:18px 22px;margin-bottom:16px;border-bottom:4px solid #dc2626">
    <div style="font-size:10px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:#f87171">{ILUS_BRAND} · {ILUS_TAGLINE}</div>
    <div style="font-size:20px;font-weight:900;color:#fff;letter-spacing:.4px">INFORME POST-SERVICIO</div>
    <div style="font-size:10px;color:#9ca3af;margin-top:4px">{ILUS_LEGAL} · RUT {ILUS_RUT}</div>
  </div>
  <table style="width:100%;border-collapse:collapse;margin-bottom:6px">
    {_kv('Cliente', e(cliente.get('razon_social')))}
    {_kv('RUT', e(cliente.get('rut')))}
    {_kv('N° Ticket', e(rep.get('ticket_num')))}
    {_kv('Tipo · Estado', f"{e_raw(tipo_lbl)} · {e((rep.get('estado') or '').title())}")}
    {_kv('Técnicos', tecnicos)}
  </table>
  <div style="font-size:13px;font-weight:700;color:#0a0a0a;margin:12px 0;padding:9px 14px;background:#f8fafc;border:1px solid #e5e7eb;border-left:4px solid #dc2626;border-radius:0 8px 8px 0">
    <span style="font-size:9px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:#dc2626;margin-right:8px">Asunto</span>{e(rep.get('asunto'))}
  </div>
  {ante}
  {_sec("Objetivos de la visita")}{_ls(rep.get('objetivos'))}
  {_sec("Trabajos realizados e intervenciones")}{_ls(rep.get('trabajos'))}
  {_sec("Observaciones generales post-visita")}{_ls(rep.get('observaciones'))}
  {maq_html}
  {ai_block}
  <div style="text-align:center;color:#9ca3af;font-size:11px;margin-top:28px;padding-top:14px;border-top:2px solid #dc2626">
    Documento generado el {_now_chile_str('%d/%m/%Y %H:%M')} · © {_now_chile_str('%Y')} {ILUS_BRAND} · {ILUS_LEGAL}
  </div>
</body></html>"""


# CSS del informe corporativo ILUS. String plano (NO f-string) → sin doblar
# llaves. Diseño 2026-05-30 (Daniel): paginado REAL en hojas carta con paged.js
# (cabecera + pie repetidos en cada hoja + numeración), logo grande, tarjetas y
# tablas. print-color-adjust fuerza que los fondos negros/rojos salgan al PDF.
_REPORTE_PDF_CSS = """
  :root{ --ilus-red:#dc2626; --ilus-red-d:#b91c1c; --ilus-black:#0a0a0a; --ink:#111827; --muted:#6b7280; --line:#e5e7eb; }
  *{ box-sizing:border-box; }
  html,body{ margin:0; padding:0; }
  body{ font-family:'Segoe UI',-apple-system,Roboto,Helvetica,Arial,sans-serif; color:var(--ink);
        font-size:11.5px; line-height:1.5; background:#eceff3;
        -webkit-print-color-adjust:exact; print-color-adjust:exact; }

  /* ── Hoja carta + cabecera/pie corrientes en CADA página (paged.js) ── */
  @page{
    size: Letter;
    margin: 3.15cm 1.9cm 2.15cm;
    @top-center{ content: element(rhead); }
    @bottom-left{ content: element(rfoot); }
    @bottom-right{ content: "Página " counter(page) " de " counter(pages);
                   font-size:8.5px; color:#9ca3af; font-family:'Segoe UI',Arial,sans-serif; }
  }
  .rh{ position: running(rhead); }
  .rf{ position: running(rfoot); }
  .rh-inner{ display:flex; align-items:center; justify-content:space-between; gap:16px; width:100%;
             background:linear-gradient(135deg,#0a0a0a 0%,#1c1c22 100%); border-radius:11px;
             padding:13px 20px; border-bottom:4px solid var(--ilus-red);
             box-shadow:0 4px 12px rgba(10,10,10,.22);
             -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .rh-brand{ display:flex; align-items:center; gap:16px; }
  .rep-logo{ height:70px; width:auto; max-width:250px; display:block; }
  .rep-logo-fallback{ height:70px; display:flex; align-items:center; color:#fff; padding-left:14px;
             border-left:4px solid var(--ilus-red); font-weight:900; letter-spacing:1px; font-size:32px; }
  .rh-eyebrow{ font-size:9px; font-weight:800; letter-spacing:1.4px; text-transform:uppercase; color:#f87171; margin-bottom:2px; }
  .rh-title{ font-size:18px; font-weight:900; color:#fff; letter-spacing:.4px; line-height:1.1; }
  .rh-sub{ font-size:9px; color:#9ca3af; margin-top:3px; }
  .rh-meta{ text-align:right; flex-shrink:0; }
  .rep-ticket{ font-size:10px; font-weight:800; color:#fff; background:var(--ilus-red); border-radius:6px;
             padding:4px 12px; display:inline-block; letter-spacing:.5px; box-shadow:0 2px 8px rgba(220,38,38,.4); }
  .rep-gar{ font-size:8.5px; font-weight:800; border-radius:6px; padding:3px 10px; display:inline-block;
             letter-spacing:.5px; margin-top:7px; border:1px solid transparent; }
  .rep-gar-si{ background:#dcfce7; color:#166534; border-color:#86efac; }
  .rep-gar-no{ background:#fee2e2; color:#991b1b; border-color:#fca5a5; }
  .rf-inner{ width:100%; font-size:8.5px; color:var(--muted); border-top:2px solid var(--ilus-red); padding-top:5px; }
  .rf-inner b{ color:var(--ilus-black); }

  /* ── Asunto ── */
  .rep-asunto{ font-size:12.5px; font-weight:700; color:var(--ilus-black);
             margin:0 0 12px; padding:9px 14px; background:#f8fafc;
             border:1px solid var(--line); border-left:4px solid var(--ilus-red);
             border-radius:0 8px 8px 0; }
  .rep-asunto-k{ display:inline-block; font-size:8.5px; font-weight:800; letter-spacing:.6px;
             text-transform:uppercase; color:var(--ilus-red); margin-right:10px; vertical-align:1px; }
  /* ── Chips de resumen ── */
  .rep-chips{ display:flex; flex-wrap:wrap; gap:7px; margin:0 0 16px; }
  .rep-chip{ display:inline-flex; align-items:center; gap:6px; background:#fff;
             border:1px solid var(--line); border-radius:50px; padding:3px 11px 3px 5px;
             font-size:9.5px; box-shadow:0 1px 2px rgba(0,0,0,.04); }
  .rep-chip-k{ background:var(--ilus-black); color:#fff; border-radius:50px; padding:2px 8px;
             font-size:8px; font-weight:800; letter-spacing:.4px; text-transform:uppercase; }
  .rep-chip-v{ font-weight:700; color:var(--ink); }
  .rep-chip-ok .rep-chip-k{ background:#166534; }
  .rep-chip-info .rep-chip-k{ background:#1d4ed8; }
  .rep-chip-warn .rep-chip-k{ background:#b45309; }
  /* ── Secciones ── */
  .rep-section{ margin-bottom:18px; break-inside:avoid; }
  .rep-section-bar{ background:var(--ilus-black); color:#fff; font-size:10px; font-weight:800;
             letter-spacing:.7px; text-transform:uppercase; padding:6px 12px 6px 16px;
             border-radius:7px 7px 0 0; position:relative; }
  .rep-section-bar::before{ content:''; position:absolute; left:0; top:0; bottom:0; width:5px;
             background:var(--ilus-red); border-radius:7px 0 0 0; }
  .rep-section-bar-soft{ background:#374151; }
  .rep-section > .rep-section-bar + *{ border:1px solid var(--line); border-top:none;
             border-radius:0 0 8px 8px; padding:13px 16px; margin-top:0; background:#fff; }
  /* ── Tablas ── */
  table{ border-collapse:collapse; width:100%; }
  .rep-kv{ margin:0; }
  .rep-kv th{ background:#f8fafc; color:#374151; text-align:left; font-size:9px;
             text-transform:uppercase; letter-spacing:.3px; font-weight:800;
             padding:6px 9px; border:1px solid var(--line); width:16%; vertical-align:top; }
  .rep-kv td{ padding:6px 9px; border:1px solid var(--line); width:34%; vertical-align:top; }
  .rep-table{ margin:0; }
  .rep-table thead th{ background:var(--ilus-black); color:#fff; font-size:9px;
             text-transform:uppercase; letter-spacing:.3px; padding:7px 9px; text-align:left;
             border:1px solid var(--ilus-black); }
  .rep-table tbody td{ padding:6px 9px; border:1px solid var(--line); vertical-align:top; }
  .rep-table tbody tr:nth-child(even) td{ background:#f9fafb; }
  .rep-center{ text-align:center; }
  .rep-badge{ display:inline-block; font-size:9px; font-weight:800; padding:2px 9px;
             border-radius:50px; letter-spacing:.3px; }
  .rep-badge-si{ background:#dcfce7; color:#166534; }
  .rep-badge-no{ background:#fee2e2; color:#991b1b; }
  .rep-badge-na{ background:#f3f4f6; color:#6b7280; }
  /* ── Listas y texto ── */
  .rep-list{ margin:2px 0; padding-left:20px; }
  .rep-list li{ margin-bottom:5px; }
  .rep-list li::marker{ color:var(--ilus-red); }
  .rep-text{ margin:2px 0; text-align:justify; }
  .rep-empty{ color:#9ca3af; font-style:italic; margin:2px 0; }
  /* ── Fotos ── */
  .rep-foto-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:11px; }
  .rep-foto{ margin:0; border:1px solid var(--line); border-radius:10px; overflow:hidden;
             background:#fff; box-shadow:0 2px 8px rgba(0,0,0,.06); break-inside:avoid; }
  .rep-foto img{ width:100%; height:148px; object-fit:cover; display:block; }
  .rep-foto figcaption{ font-size:8.5px; color:var(--muted); padding:5px 7px; text-align:center;
             border-top:1px solid #f3f4f6; }
  /* ── Barra imprimir (solo pantalla) ── */
  .rep-print-bar{ position:fixed; top:16px; right:16px; z-index:9999; }
  .rep-print-bar button{ background:var(--ilus-red); color:#fff; border:none; border-radius:10px;
             padding:11px 19px; font-weight:800; font-size:13px; cursor:pointer;
             box-shadow:0 6px 18px rgba(220,38,38,.45); }
  .rep-print-bar button:hover{ background:var(--ilus-red-d); }

  /* ── Pantalla: cada hoja carta que genera paged.js ── */
  .pagedjs_page{ background:#fff; box-shadow:0 8px 30px rgba(0,0,0,.18); margin:16px auto; }

  /* ── Fallback si paged.js NO carga (sin CDN): una hoja continua decente ── */
  body.no-paged{ padding:24px 12px; }
  body.no-paged .rep-doc{ max-width:21.6cm; margin:0 auto; background:#fff; padding:2.2cm 2.3cm;
             box-shadow:0 10px 40px rgba(0,0,0,.2); border-radius:10px; }
  body.no-paged .rh{ position:static; display:block; margin-bottom:16px; }
  body.no-paged .rf{ position:static; display:block; margin-top:20px; }

  @media print{
    body{ background:#fff; }
    .rep-print-bar{ display:none !important; }
    .pagedjs_page{ box-shadow:none; margin:0; }
    body.no-paged{ padding:0; }
    body.no-paged .rep-doc{ box-shadow:none; border-radius:0; padding:0; max-width:none; }
    .rep-section, .rep-foto{ break-inside:avoid; }
    thead{ display:table-header-group; }
  }
"""


# ── Identidad ILUS (Daniel 2026-05-30) ───────────────────────────────────
#   Razón social (entidad legal):  Sport and Health Solutions SPA
#   Marca comercial:               ILUS Fitness
#   Significado de ILUS:           I Like You Strong  (tagline)
ILUS_BRAND    = "ILUS Fitness"
ILUS_TAGLINE  = "I Like You Strong"
ILUS_LEGAL    = "Sport and Health Solutions SPA"
ILUS_RUT      = "76.996.964-0"
ILUS_CONTACTO = "contacto@sphs.cl"


def _ilus_logo_datauri():
    """Logo ILUS (transparente, 'ILUS.' blanco) embebido como data URI para que
    SIEMPRE renderice en PDF / preview / snapshot sin depender de que cargue un
    archivo estático (en file:// o tras un deploy). Prioriza la versión
    transparente (se funde con el hero oscuro); cae a la versión con fondo negro
    y, en último caso, a la ruta /static/Logo.png."""
    for _name in ("logo_dark_b64.txt", "logo_pdf.txt"):
        try:
            with open(os.path.join(BASE_DIR, "static", _name), "r", encoding="utf-8") as _f:
                _b64 = _f.read().strip()
            if _b64:
                return "data:image/png;base64," + _b64
        except Exception:
            continue
    return "/static/Logo.png"


def _paged_doc_scripts(auto_print=False):
    """Scripts para paginar el documento en hojas carta con paged.js (cabecera y
    pie repetidos + numeración). Degrada con elegancia: si el CDN no carga en 4s,
    marca <body class='no-paged'> (una hoja continua) y, si corresponde, imprime."""
    ap = "1" if auto_print else "0"
    # Botón flotante de imprimir: se inyecta por JS DESPUÉS de paginar para que
    # paged.js no lo meta dentro de una hoja.
    js_btn = (
        "function _ilusPB(){if(document.getElementById('ilusPB'))return;"
        "var b=document.createElement('button');b.textContent='\\u2b07 Descargar / Imprimir PDF';"
        "b.onclick=function(){window.print();};"
        "var d=document.createElement('div');d.id='ilusPB';d.className='rep-print-bar';"
        "d.appendChild(b);document.body.appendChild(d);}"
    )
    return (
        "<script>" + js_btn +
        "window.PagedConfig={auto:true,after:function(){_ilusPB();"
        "if(" + ap + "){setTimeout(function(){try{window.print();}catch(e){}},350);}"
        "}};</script>"
        '<script src="https://unpkg.com/pagedjs/dist/paged.polyfill.js"></script>'
        "<script>setTimeout(function(){"
        "if(!document.querySelector('.pagedjs_page')){"
        "document.body.classList.add('no-paged');_ilusPB();"
        + ("setTimeout(function(){try{window.print();}catch(e){}},300);" if auto_print else "")
        + "}},4000);</script>"
    )


def _reporte_to_pdf_html(rep, cliente, auto_print=True):
    """Genera HTML corporativo ILUS (formato informe técnico ISO) listo para
    imprimir a PDF desde el navegador (window.print()). NO requiere libs de
    sistema (weasyprint/wkhtmltopdf): el propio navegador genera el PDF.

    auto_print=True  → dispara window.print() al cargar (endpoint /pdf).
    auto_print=False → solo se ve el documento (preview / snapshot 'Ver HTML').

    Replica las secciones de los informes oficiales ILUS:
      - INFORME TÉCNICO POST-SERVICIO (mantención/instalación/inspección/otro)
      - APLICACIÓN DE GARANTÍA (variante para tipo='garantia')

    Todo el contenido dinámico se escapa (markupsafe) para evitar inyección
    de HTML desde los campos del reporte.
    """
    from markupsafe import escape as _esc

    def e(v):
        """Escapa a HTML seguro. None/'' → '—'."""
        if v is None:
            return "—"
        s = str(v).strip()
        return str(_esc(s)) if s else "—"

    def e_raw(v):
        """Escapa sin placeholder (para concatenar)."""
        return str(_esc("" if v is None else str(v)))

    def _as_list(items):
        if isinstance(items, str):
            try: items = json.loads(items)
            except Exception: items = []
        return items or []

    def _ul(items):
        items = _as_list(items)
        if not items:
            return '<p class="rep-empty">Sin información registrada.</p>'
        return ('<ul class="rep-list">'
                + ''.join(f'<li>{e_raw(it)}</li>' for it in items if str(it).strip())
                + '</ul>')

    def _txt(v):
        if v is None or not str(v).strip():
            return '<p class="rep-empty">Sin información registrada.</p>'
        # Respeta saltos de línea del texto plano
        return '<p class="rep-text">' + e_raw(v).replace("\n", "<br>") + '</p>'

    def _fecha_str(v):
        """DATE/datetime/str → 'dd/mm/aaaa' (o vacío)."""
        if not v:
            return ""
        try:
            if hasattr(v, "strftime"):
                return v.strftime("%d/%m/%Y")
        except Exception:
            pass
        s = str(v)[:10]
        # Reordena 'aaaa-mm-dd' → 'dd/mm/aaaa'
        if len(s) == 10 and s[4] == "-" and s[7] == "-":
            return f"{s[8:10]}/{s[5:7]}/{s[0:4]}"
        return s

    def _dir_cliente(c):
        partes = [c.get("direccion"), c.get("comuna"), c.get("ciudad")]
        return ", ".join(p.strip() for p in partes if p and str(p).strip())

    tipo      = (rep.get("tipo") or "mantencion").lower()
    es_garantia = (tipo == "garantia")
    # GARANTÍA TRANSVERSAL (Daniel 2026-05-30): flag SEPARADO del tipo. Fuente de
    # verdad = columna garantia_aplica; fallback al tipo legacy 'garantia' para
    # reportes viejos creados antes de la separación.
    garantia_aplica = bool(rep.get("garantia_aplica")) or es_garantia
    tipo_lbl  = {"mantencion": "Mantención", "instalacion": "Instalación",
                 "inspeccion": "Inspección", "garantia": "Garantía",
                 "otro": "Servicio Técnico"}.get(tipo, "Servicio Técnico")
    titulo    = ("APLICACIÓN DE GARANTÍA" if es_garantia
                 else "INFORME TÉCNICO POST-SERVICIO")
    rut_fmt   = _formato_rut_chile(cliente.get("rut", "")) or "—"
    # Badge de garantía para el encabezado del PDF.
    if garantia_aplica:
        gar_badge_html = ('<span class="rep-gar rep-gar-si">GARANTÍA: APLICA</span>')
    else:
        gar_badge_html = ('<span class="rep-gar rep-gar-no">GARANTÍA: NO APLICA</span>')

    # ── Tabla máquinas a intervenir (SKU, descripción, cantidad) ──────────
    maq = _as_list(rep.get("maquinas_json"))
    maq_rows = ""
    for m in maq:
        maq_rows += (
            "<tr>"
            f"<td>{e(m.get('sku'))}</td>"
            f"<td>{e(m.get('descripcion'))}</td>"
            f"<td class='rep-center'>{e(m.get('cantidad') or 1)}</td>"
            "</tr>"
        )
    if not maq_rows:
        maq_rows = "<tr><td colspan='3' class='rep-empty'>Sin equipos registrados.</td></tr>"

    # ── Tabla observaciones/recomendaciones por máquina ───────────────────
    obs_rows = ""
    for m in maq:
        gar = (str(m.get("garantia") or "").strip())
        gar_l = gar.lower()
        if gar_l in ("si", "sí", "true", "1", "yes"):
            gar_badge = '<span class="rep-badge rep-badge-si">SÍ</span>'
        elif gar_l in ("no", "false", "0"):
            gar_badge = '<span class="rep-badge rep-badge-no">NO</span>'
        elif gar:
            gar_badge = e(gar)
        else:
            gar_badge = '<span class="rep-badge rep-badge-na">—</span>'
        obs_rows += (
            "<tr>"
            f"<td>{e(m.get('descripcion') or m.get('sku'))}</td>"
            f"<td>{e(m.get('modelo'))}</td>"
            f"<td>{e(m.get('serie'))}</td>"
            f"<td>{e(m.get('repuesto'))}</td>"
            f"<td class='rep-center'>{gar_badge}</td>"
            f"<td>{e(m.get('observacion'))}</td>"
            "</tr>"
        )
    if not obs_rows:
        obs_rows = "<tr><td colspan='6' class='rep-empty'>Sin observaciones por máquina.</td></tr>"

    # ── Registro fotográfico ──────────────────────────────────────────────
    fotos = rep.get("fotos") or []
    fotos_html = ""
    if fotos:
        cells = "".join(
            f'<figure class="rep-foto"><img src="{e_raw(f.get("url"))}" alt="foto">'
            f'<figcaption>{e(f.get("nombre"))}</figcaption></figure>'
            for f in fotos
        )
        fotos_html = (
            '<div class="rep-section"><div class="rep-section-bar">REGISTRO FOTOGRÁFICO</div>'
            f'<div class="rep-foto-grid">{cells}</div></div>'
        )

    # ── Bloque IA (opcional) ──────────────────────────────────────────────
    ai_html = ""
    if rep.get("ai_diagnostico"):
        ai_html = (
            '<div class="rep-section"><div class="rep-section-bar rep-section-bar-soft">'
            'DIAGNÓSTICO TÉCNICO (ANÁLISIS ASISTIDO)</div>'
            f'{_txt(rep.get("ai_diagnostico"))}</div>'
        )

    # ── Cabecera: datos del solicitante / cliente ─────────────────────────
    if es_garantia:
        bloque_datos = f"""
      <div class="rep-section">
        <div class="rep-section-bar">INFORMACIÓN DEL SOLICITANTE</div>
        <table class="rep-kv">
          <tr><th>Razón Social</th><td>{e(cliente.get('razon_social'))}</td>
              <th>RUT</th><td>{e_raw(rut_fmt)}</td></tr>
          <tr><th>Contacto</th><td>{e(cliente.get('contacto_nombre'))}</td>
              <th>Teléfono</th><td>{e(cliente.get('contacto_tel'))}</td></tr>
          <tr><th>Correo</th><td>{e(cliente.get('contacto_email'))}</td>
              <th>Dirección</th><td>{e(_dir_cliente(cliente))}</td></tr>
        </table>
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">INFORMACIÓN DEL PRODUCTO</div>
        <table class="rep-kv">
          <tr><th>N° Factura / Boleta / OT</th><td>{e(rep.get('ticket_num'))}</td>
              <th>Fecha solicitud</th><td>{e(_fecha_str(rep.get('fecha_solicitado')))}</td></tr>
        </table>
        <table class="rep-table" style="margin-top:6px">
          <thead><tr><th>SKU</th><th>Producto con falla</th><th>Cantidad</th></tr></thead>
          <tbody>{maq_rows}</tbody>
        </table>
      </div>"""
        bloque_narrativo = f"""
      <div class="rep-section">
        <div class="rep-section-bar">DESCRIPCIÓN DEL PROBLEMA</div>
        {_txt(rep.get('antecedentes'))}
        {_ul(rep.get('observaciones'))}
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">GESTIÓN Y RESOLUCIÓN</div>
        {_ul(rep.get('trabajos'))}
      </div>"""
    else:
        bloque_datos = f"""
      <div class="rep-section">
        <div class="rep-section-bar">DATOS DEL CLIENTE</div>
        <table class="rep-kv">
          <tr><th>Razón Social</th><td>{e(cliente.get('razon_social'))}</td>
              <th>RUT</th><td>{e_raw(rut_fmt)}</td></tr>
          <tr><th>Contacto</th><td>{e(cliente.get('contacto_nombre'))}</td>
              <th>Teléfono</th><td>{e(cliente.get('contacto_tel'))}</td></tr>
          <tr><th>Correo</th><td>{e(cliente.get('contacto_email'))}</td>
              <th>Dirección</th><td>{e(_dir_cliente(cliente))}</td></tr>
        </table>
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">DATOS DEL SERVICIO</div>
        <table class="rep-kv">
          <tr><th>Tipo de servicio</th><td>{e_raw(tipo_lbl)}</td>
              <th>Estado</th><td>{e((rep.get('estado') or '').title())}</td></tr>
          <tr><th>Fecha solicitado</th><td>{e(_fecha_str(rep.get('fecha_solicitado')))}</td>
              <th>Fecha inicio</th><td>{e(_fecha_str(rep.get('fecha_inicio')))}</td></tr>
          <tr><th>Fecha cierre</th><td>{e(_fecha_str(rep.get('fecha_cierre')))}</td>
              <th>Garantía</th><td>{e_raw(gar_badge_html)}</td></tr>
          <tr><th>Técnico Senior</th><td>{e(rep.get('tecnico_senior'))}</td>
              <th>Técnico Junior</th><td>{e(rep.get('tecnico_junior'))}</td></tr>
        </table>
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">MÁQUINAS A INTERVENIR</div>
        <table class="rep-table">
          <thead><tr><th>SKU</th><th>Descripción</th><th>Cantidad</th></tr></thead>
          <tbody>{maq_rows}</tbody>
        </table>
      </div>"""
        bloque_narrativo = f"""
      <div class="rep-section">
        <div class="rep-section-bar">OBJETIVOS DE LA VISITA</div>
        {_ul(rep.get('objetivos'))}
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">TRABAJOS REALIZADOS E INTERVENCIONES</div>
        {_ul(rep.get('trabajos'))}
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">OBSERVACIONES GENERALES POST-VISITA</div>
        {_ul(rep.get('observaciones'))}
      </div>
      <div class="rep-section">
        <div class="rep-section-bar">OBSERVACIONES Y RECOMENDACIONES POR MÁQUINA</div>
        <table class="rep-table">
          <thead><tr><th>Máquina</th><th>Modelo</th><th>Serial</th><th>Repuesto</th>
            <th>Garantía</th><th>Observación</th></tr></thead>
          <tbody>{obs_rows}</tbody>
        </table>
      </div>"""

    asunto    = e(rep.get("asunto"))
    ticket    = e(rep.get("ticket_num"))
    logo_url  = _ilus_logo_datauri()
    gen_fecha = _now_chile_str("%d/%m/%Y %H:%M")
    año       = _now_chile_str("%Y")

    # ── Chips de resumen (glance rápido bajo el asunto) ───────────────────
    def _chip(label, value, cls=""):
        v = "" if value is None else str(value).strip()
        if not v or v == "—":
            return ""
        return (f'<span class="rep-chip {cls}">'
                f'<span class="rep-chip-k">{e_raw(label)}</span>'
                f'<span class="rep-chip-v">{e_raw(v)}</span></span>')
    _estado_cls = {"borrador": "rep-chip-warn", "emitido": "rep-chip-info",
                   "entregado": "rep-chip-ok"}.get((rep.get("estado") or "").lower(), "")
    chips_html = (
        '<div class="rep-chips">'
        + _chip("Tipo", tipo_lbl)
        + _chip("Estado", (rep.get("estado") or "").title(), _estado_cls)
        + _chip("Solicitado", _fecha_str(rep.get("fecha_solicitado")))
        + _chip("Inicio", _fecha_str(rep.get("fecha_inicio")))
        + _chip("Cierre", _fecha_str(rep.get("fecha_cierre")) or "Abierto")
        + _chip("Téc. Senior", rep.get("tecnico_senior"))
        + _chip("Téc. Junior", rep.get("tecnico_junior"))
        + "</div>"
    )

    _css = _REPORTE_PDF_CSS
    _scripts = _paged_doc_scripts(auto_print)

    return f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{titulo} · {e(cliente.get('razon_social'))}</title>
<style>{_css}</style></head>
<body>
  <div class="rep-doc">
    <div class="rh"><div class="rh-inner">
      <div class="rh-brand">
        <img class="rep-logo" src="{logo_url}" alt="ILUS"
             onerror="this.outerHTML='<div class=&quot;rep-logo-fallback&quot;>ILUS.</div>'">
        <div class="rh-txt">
          <div class="rh-eyebrow">{ILUS_BRAND} · {ILUS_TAGLINE}</div>
          <div class="rh-title">{titulo}</div>
          <div class="rh-sub">{ILUS_LEGAL} · RUT {ILUS_RUT}</div>
        </div>
      </div>
      <div class="rh-meta">
        <span class="rep-ticket">N° {ticket}</span>
        <div>{gar_badge_html}</div>
      </div>
    </div></div>
    <div class="rf"><div class="rf-inner">
      <b>{ILUS_BRAND}</b> · {ILUS_LEGAL} · {ILUS_CONTACTO} · Generado el {gen_fecha}
    </div></div>
    <div class="rep-content">
      <div class="rep-asunto"><span class="rep-asunto-k">Asunto</span>{asunto}</div>
      {chips_html}
      {bloque_datos}
      {bloque_narrativo}
      {ai_html}
      {fotos_html}
    </div>
  </div>
  {_scripts}
</body></html>"""


def _informe_ficha_html(d, ct, cliente, auto_print=True):
    """Informe de GESTIÓN del cliente (Agente ILUS, determinista, SIN IA).
    Compila el diagnóstico 360 (contrato, cláusulas, frecuencia, pagos, productos,
    historial) y DESTACA los dolores: garantías/gratuitas que debemos cubrir,
    fugas a terceros y servicios sin facturar. Vista imprimible → PDF en el navegador."""
    from markupsafe import escape as _esc

    def e(v):
        s = "" if v is None else str(v).strip()
        return str(_esc(s)) if s else "—"

    def e_raw(v):
        return str(_esc("" if v is None else str(v)))

    def _clp(v):
        try:
            n = float(v)
        except (TypeError, ValueError):
            return None
        if not n:
            return None
        return "$" + format(int(round(n)), ",d").replace(",", ".")

    def _ul(items):
        items = [i for i in (items or []) if str(i).strip()]
        if not items:
            return '<p class="rep-empty">Sin elementos.</p>'
        return '<ul class="rep-list">' + "".join(f"<li>{e_raw(i)}</li>" for i in items) + "</ul>"

    dc = d.get("diagnostico_contrato") or {}
    br = d.get("brecha_gratis") or {}
    fac = d.get("facturacion") or {}
    hist = d.get("historia") or {}
    mant = d.get("mantenciones") or {}
    eq = d.get("equipos") or {}
    val = d.get("valorizacion") or {}
    uni = d.get("universo") or {}
    dcli = d.get("datos_cliente") or {}

    try:
        score = int(float(d.get("score_salud") or 0))
    except Exception:
        score = 0
    score = max(0, min(100, score))
    riesgo = (d.get("nivel_riesgo") or "medio").lower()
    sc_color = "#16a34a" if score >= 70 else "#f59e0b" if score >= 40 else "#dc2626"
    sc_text = "Excelente" if score >= 80 else "Bueno" if score >= 60 else "Regular" if score >= 40 else "Crítico"
    rg_color, rg_label = {"alto": ("#dc2626", "ALTO"), "bajo": ("#16a34a", "BAJO")}.get(riesgo, ("#f59e0b", "MEDIO"))
    _dash = round(score * 2.764, 1)

    secciones = ""
    if d.get("resumen_ejecutivo"):
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Resumen ejecutivo del Agente</div>'
                      f'<p class="rep-text">{e_raw(d["resumen_ejecutivo"])}</p></div>')

    # DOLORES (lo más importante para ILUS) — destacado rojo
    dolores = []
    if (br.get("pendientes") or 0):
        _exp = _clp(br.get("exposicion_clp"))
        dolores.append(f"<b>Garantías/mantenciones gratuitas que debemos cubrir:</b> {br.get('pendientes')}"
                       + (f" — exposición {_exp}" if _exp else "") + ". " + e_raw(br.get("mensaje") or ""))
    _porcob = hist.get("por_cobertura") or {}
    _fuga = _porcob.get("Tercero (fuga)") or _porcob.get("Tercero") or 0
    if _fuga:
        dolores.append(f"<b>Fuga a terceros:</b> {_fuga} mantención(es) las hizo un técnico EXTERNO — "
                       "riesgo de cubrir garantía sin recibir el ingreso del servicio.")
    elif br.get("riesgo_fuga_tercero"):
        dolores.append("<b>Riesgo de fuga a terceros:</b> el patrón sugiere mantenciones con externos; conviene blindar la garantía.")
    if fac.get("pendientes"):
        _ant = fac.get("mas_antigua_dias")
        dolores.append(f"<b>Servicios sin facturar:</b> {fac['pendientes']} servicio(s) realizados sin cerrar la factura"
                       + (f" (el más antiguo lleva {_ant} días)" if _ant is not None else "") + ".")
    if dolores:
        secciones += ('<div class="rep-section"><div class="rep-section-bar" style="background:#dc2626">'
                      '⚠ Dolores / Exposición de ILUS</div><ul class="rep-list" style="margin-top:8px">'
                      + "".join(f"<li>{x}</li>" for x in dolores) + "</ul></div>")
    else:
        secciones += ('<div class="rep-section"><div class="rep-section-bar" style="background:#16a34a">'
                      '✓ Sin dolores detectados</div><p class="rep-text">No hay brechas de garantía, '
                      'fugas a terceros ni servicios sin facturar pendientes.</p></div>')

    # Contrato + cláusulas
    chips = ('<div class="rep-chips">'
             f'<span class="rep-chip"><span class="rep-chip-k">Estado</span><span class="rep-chip-v">{e_raw(dc.get("estado") or "—")}</span></span>'
             + (f'<span class="rep-chip"><span class="rep-chip-k">Frecuencia</span><span class="rep-chip-v">c/{dc.get("frecuencia_meses")} meses</span></span>' if dc.get("frecuencia_meses") else "")
             + (f'<span class="rep-chip"><span class="rep-chip-k">Valor anual</span><span class="rep-chip-v">{_clp(dc.get("valor_anual"))}</span></span>' if dc.get("valor_anual") else "")
             + f'<span class="rep-chip"><span class="rep-chip-k">Vigencia</span><span class="rep-chip-v">{e_raw(dc.get("vigencia_inicio") or "—")} → {e_raw(dc.get("vigencia_fin") or ("indefinido" if dc.get("es_indefinido") else "—"))}</span></span>'
             + "</div>")
    sec_ct = chips
    try:
        _clauses = json.loads(ct.get("ai_clausulas") or "[]")
    except Exception:
        _clauses = []
    try:
        _alertas = json.loads(ct.get("ai_alertas") or "[]")
    except Exception:
        _alertas = []
    if _alertas:
        sec_ct += '<div style="margin-top:10px;font-weight:800;color:#dc2626;font-size:11px">Alertas del contrato</div>' + _ul(_alertas)
    if _clauses:
        sec_ct += '<div style="margin-top:8px;font-weight:800;color:#0a0a0a;font-size:11px">Cláusulas relevantes</div>' + _ul(_clauses)
    if not d.get("tiene_contrato"):
        sec_ct += '<p class="rep-text" style="color:#dc2626">⚠ Este cliente NO tiene contrato registrado.</p>'
    secciones += '<div class="rep-section"><div class="rep-section-bar">Contrato</div>' + sec_ct + '</div>'

    # Facturación pendiente
    if fac.get("items"):
        rows = "".join(f"<tr><td>{e(it.get('fecha'))}</td><td>{e(it.get('tipo_label'))}</td>"
                       f"<td>{e(it.get('ef_label'))}</td><td>{e(it.get('cobertura_label'))}</td></tr>"
                       for it in fac["items"][:15])
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Facturación pendiente</div>'
                      '<table class="rep-kv"><tr><th>Fecha</th><th>Tipo</th><th>Estado</th><th>Cobertura</th></tr>'
                      + rows + "</table></div>")

    # Productos / equipos
    secciones += ('<div class="rep-section"><div class="rep-section-bar">Productos / equipos asociados</div>'
                  '<table class="rep-kv">'
                  f'<tr><th>Total equipos</th><td>{eq.get("total", 0)}</td><th>Críticos</th><td>{eq.get("criticos", 0)}</td></tr>'
                  f'<tr><th>Sin N° de serie</th><td>{eq.get("sin_serie", 0)}</td><th>Sin foto</th><td>{eq.get("sin_foto", 0)}</td></tr>'
                  "</table></div>")

    # Historial
    cob_rows = "".join(f"<tr><th>{e(k)}</th><td>{v}</td><th></th><td></td></tr>" for k, v in (_porcob.items() if _porcob else []))
    secciones += ('<div class="rep-section"><div class="rep-section-bar">Historial de gestiones</div>'
                  '<table class="rep-kv">'
                  f'<tr><th>Total gestiones</th><td>{uni.get("total_gestiones", 0)}</td><th>Realizadas</th><td>{uni.get("realizadas", 0)}</td></tr>'
                  f'<tr><th>Última gestión</th><td colspan="3">{e(uni.get("ultima_fecha"))}</td></tr>'
                  + cob_rows + "</table></div>")

    # Agenda / proyección
    secciones += ('<div class="rep-section"><div class="rep-section-bar">Agenda y proyección</div>'
                  '<table class="rep-kv">'
                  f'<tr><th>Próxima mantención</th><td>{e(mant.get("proxima_fecha"))}</td><th>Vencidas</th><td>{len(mant.get("vencidas") or [])}</td></tr>'
                  f'<tr><th>Realizadas</th><td>{mant.get("realizadas", 0)}</td><th>Esperadas a hoy</th><td>{mant.get("esperadas_a_hoy", 0)}</td></tr>'
                  "</table></div>")

    if val.get("pitch"):
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Propuesta comercial</div>'
                      f'<p class="rep-text">{e_raw(val["pitch"])}</p></div>')
    _acc = [a.get("titulo") for a in (d.get("acciones") or []) if a.get("titulo")]
    if _acc:
        secciones += '<div class="rep-section"><div class="rep-section-bar">Acciones recomendadas</div>' + _ul(_acc) + "</div>"
    if dcli.get("faltantes"):
        secciones += '<div class="rep-section"><div class="rep-section-bar">Datos de ficha por completar</div>' + _ul(dcli["faltantes"]) + "</div>"

    logo_url = _ilus_logo_datauri()
    gen_fecha = _now_chile_str("%d/%m/%Y %H:%M")
    rut_fmt = _formato_rut_chile(cliente.get("rut", "")) or "—"
    _scripts = _paged_doc_scripts(auto_print)
    razon = cliente.get("razon_social") or (d.get("cliente") or {}).get("razon_social") or "Cliente"

    return f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Informe de gestión · {e(razon)}</title>
<style>{_REPORTE_PDF_CSS}</style></head>
<body>
  <div class="rep-doc">
    <div class="rh"><div class="rh-inner">
      <div class="rh-brand">
        <img class="rep-logo" src="{logo_url}" alt="ILUS"
             onerror="this.outerHTML='<div class=&quot;rep-logo-fallback&quot;>ILUS.</div>'">
        <div class="rh-txt">
          <div class="rh-eyebrow">{ILUS_BRAND} · {ILUS_TAGLINE}</div>
          <div class="rh-title">INFORME DE GESTIÓN DEL CLIENTE</div>
          <div class="rh-sub">{ILUS_LEGAL} · RUT {ILUS_RUT} · Agente ILUS (determinista, sin IA)</div>
        </div>
      </div>
      <div class="rh-meta" style="display:flex;align-items:center;gap:12px">
        <svg viewBox="0 0 100 100" style="width:66px;height:66px">
          <circle cx="50" cy="50" r="44" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="9"></circle>
          <circle cx="50" cy="50" r="44" fill="none" stroke="{sc_color}" stroke-width="9"
                  stroke-dasharray="{_dash} {round(276.4 - _dash, 1)}"
                  transform="rotate(-90 50 50)" stroke-linecap="round"></circle>
          <text x="50" y="49" text-anchor="middle" style="font-size:27px;font-weight:900;fill:#fff">{score}</text>
          <text x="50" y="64" text-anchor="middle" style="font-size:9px;fill:rgba(255,255,255,.65)">de 100</text>
        </svg>
        <div style="text-align:left">
          <span style="display:inline-block;font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#fff;background:{sc_color};padding:3px 10px;border-radius:50px">{sc_text}</span><br>
          <span style="display:inline-block;margin-top:6px;font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#fff;background:{rg_color};padding:3px 10px;border-radius:50px">Riesgo {rg_label}</span>
        </div>
      </div>
    </div></div>
    <div class="rf"><div class="rf-inner">
      <b>{ILUS_BRAND}</b> · {ILUS_LEGAL} · Informe del Agente (determinista, sin IA) · {ILUS_CONTACTO} · Generado el {gen_fecha}
    </div></div>
    <div class="rep-content">
      <div class="rep-asunto"><span class="rep-asunto-k">Cliente</span>{e(razon)}</div>
      <div class="rep-section">
        <div class="rep-section-bar">Datos del cliente</div>
        <table class="rep-kv">
          <tr><th>Razón Social</th><td>{e(razon)}</td><th>RUT</th><td>{e_raw(rut_fmt)}</td></tr>
          <tr><th>Dirección</th><td>{e(cliente.get('direccion'))}</td><th>Comuna</th><td>{e(cliente.get('comuna'))}</td></tr>
          <tr><th>Contacto</th><td>{e(cliente.get('contacto_nombre'))}</td><th>Calidad ficha</th><td>{d.get('calidad_informacion','—')}%</td></tr>
        </table>
      </div>
      {secciones}
    </div>
  </div>
  {_scripts}
</body></html>"""


@app.route("/mantenciones/api/clientes/<int:cid>/informe-ficha", methods=["GET"])
@app.route("/servicio-tecnico/api/clientes/<int:cid>/informe-ficha", methods=["GET"])
@_mant_required
def mant_informe_ficha(cid):
    """Informe de gestión del cliente (Agente ILUS determinista). Vista imprimible → PDF."""
    cli = mysql_fetchone("SELECT * FROM mant_clientes WHERE id=%s", (cid,))
    if not cli:
        return "Cliente no encontrado", 404
    try:
        d = _cliente_inteligencia(cid, _reglas_cargar())
    except Exception as e:
        print(f"[informe_ficha] cid={cid}: {e}", flush=True)
        d = None
    if not d:
        return "No se pudo generar el informe de ficha.", 500
    ct = mysql_fetchone(
        "SELECT * FROM mant_contratos WHERE cliente_id=%s "
        "ORDER BY (estado='vigente') DESC, ai_analizado DESC, id DESC LIMIT 1", (cid,)) or {}
    try:
        _mant_log("cliente", cid, "informe_ficha")
    except Exception:
        pass
    return _informe_ficha_html(d, ct, cli)


@app.route("/mantenciones/api/clientes/<int:cid>/preguntar", methods=["POST"])
@_mant_required
def mant_cliente_preguntar(cid):
    """Agente CONVERSACIONAL determinista (sin IA): responde una pregunta puntual
    sobre el cliente usando el diagnóstico ya calculado (_cliente_inteligencia).
    Devuelve {ok, intent, respuesta, sugerencias}."""
    import agente_chat
    cli = mysql_fetchone("SELECT * FROM mant_clientes WHERE id=%s", (cid,))
    if not cli:
        return jsonify({"ok": False, "error": "Cliente no encontrado"}), 404
    body = request.get_json(silent=True) or {}
    pregunta = (body.get("pregunta") or "").strip()[:300]
    try:
        intel = _cliente_inteligencia(cid, _reglas_cargar()) or {}
    except Exception as e:
        print(f"[preguntar] cid={cid}: {e}", flush=True)
        intel = {}
    # Enriquecer el bloque cliente con datos de identidad (para preguntas de contacto)
    c = dict(intel.get("cliente") or {})
    if not c.get("razon_social"):
        c["razon_social"] = cli.get("razon_social")
    for k in ("rut", "direccion", "comuna", "contacto_nombre", "contacto"):
        if cli.get(k) and not c.get(k):
            c[k] = cli.get(k)
    intel["cliente"] = c
    r = agente_chat.responder(pregunta, intel)
    try:
        _mant_log("cliente", cid, "agente_pregunta", (pregunta or "")[:120])
    except Exception:
        pass
    return jsonify({"ok": True, **r})


# ── Señales de dolor para el informe POST-SERVICIO (diseñadas por panel de
#    especialistas: técnico senior + abogado garantías/SERNAC + comercial + redactor).
#    Determinista, SIN IA: son patrones de texto que se buscan en las observaciones
#    del técnico. base_legal: Ley 19.496 (SERNAC) art. 12/19/20/21. ──
_POSTSERV_SENALES = [
    {"patron": r"tercero|externo|tecnico de afuera|servicio externo|otra empresa|otro tecnico|lo vio otro|ya lo habian (revisado|reparado)|intervencion previa|lo arreglo el cliente|instalado por tercero",
     "dolor": "FUGA A TERCEROS (dolor #1): el cliente deriva trabajo facturable a externos mientras ILUS cubre garantías/preventivas gratis. Una intervención previa de un tercero pudo dañar el equipo o anular la garantía.",
     "recomendacion": "Marcar bandera interna 'posible intervención de tercero' (NO mostrar al cliente). Foto del estado. Verificar garantía del equipo; si está vigente dejar por escrito que la intervención no autorizada puede invalidarla. Escalar a comercial: ofrecer contrato integral con tarifa preferente."},
    {"patron": r"manipulad|destapad|abierto antes|sello roto|sin sello|precinto",
     "dolor": "Manipulación previa / sello de garantía violado: causal típica de rechazo de garantía e indicio de tercero.",
     "recomendacion": "Fotografiar el sello, registrar en 'Integridad de garantía', citar art. 21 Ley 19.496 y escalar a garantías ANTES de aprobar cobertura sin costo."},
    {"patron": r"repuesto generico|repuesto no original|pieza generica|no original",
     "dolor": "Pieza NO original instalada: degrada idoneidad (art. 12 Ley 19.496), puede anular garantía del fabricante y expone a ILUS a una falla posterior.",
     "recomendacion": "Registrar marca/origen del repuesto y quién lo suministró. Si fue aporte del cliente, dejar por escrito la advertencia de ILUS y su aceptación expresa."},
    {"patron": r"lo movieron de lugar|traslad|movido por",
     "dolor": "Traslado/movimiento del equipo por externos: puede causar daño y anular la garantía por manipulación inadecuada.",
     "recomendacion": "Registrar que el traslado fue por externos y el estado en que se recibió. Advertir por escrito el efecto sobre la garantía si el daño deriva del traslado."},
    {"patron": r"mal uso|uso indebido|sobrecarga|mala instalacion|instalado mal|golpe|caida|mojad|falta de mantencion|nunca le hicieron mantencion",
     "dolor": "Falla NO atribuible a defecto de fábrica (mal uso/mala instalación/mantención deficiente): si se procesa como garantía, ILUS asume un costo que es del cliente (art. 21 Ley 19.496).",
     "recomendacion": "Clasificar causa raíz como 'mal uso' con evidencia. Excluir de garantía, reclasificar cobertura a 'cliente' (pagable) y activar facturación. Dejar constancia escrita."},
    {"patron": r"fuera de garantia|sin garantia|garantia vencida|ya no tiene garantia|se vencio",
     "dolor": "Equipo fuera de garantía atendido por inercia como garantía/cortesía: trabajo gratis indebido (cruce de ambos dolores).",
     "recomendacion": "Cruzar fecha_fin_garantia antes de cerrar. Si venció: cambiar cobertura a 'cliente', generar cotización/factura, avisar al cliente por escrito y ofrecer contrato."},
    {"patron": r"sin factur|no factur|sin ot|sin orden|despues facturamos|queda pendiente facturar|de palabra|sin documento|sin respaldo|cobrar aparte",
     "dolor": "SERVICIOS SIN FACTURAR (dolor #2): servicio ejecutado sin respaldo formal / sin documento tributario. Trabajo facturable que se pierde.",
     "recomendacion": "No cerrar OT pagada sin OT/ticket. Verificar estado de facturación; gatillar 'regularizar factura' y alerta ALTA a administración: 'OT cerrada pendiente de facturar'."},
    {"patron": r"sin costo|no cobrar|gratis|cortesia|esta vez sin cargo|sin cargo",
     "dolor": "Servicio regalado sin trazabilidad: válido solo si es garantía/contrato real; si no, erosiona margen y se vuelve costumbre.",
     "recomendacion": "Validar que la gratuidad corresponda a contrato/garantía. Si es cortesía, registrar motivo + aprobador y cuantificar horas+repuestos regalados. Si la cobertura es 'cliente' y dice 'sin costo', escalar antes de cerrar."},
    {"patron": r"fuera de contrato|fuera de alcance|no estaba en contrato",
     "dolor": "Trabajo fuera del alcance del contrato: servicio extra que suele quedar sin facturar absorbido en la cuota.",
     "recomendacion": "Identificar el trabajo extra-contrato, valorizarlo y emitir cotización/OC adicional. No absorberlo en la cuota."},
    {"patron": r"falta repuesto|no habia repuesto|sin stock|pedir repuesto|se requiere repuesto|hay que volver|segunda visita|proxima visita|no se pudo terminar|requiere visita",
     "dolor": "Trabajo incompleto: equipo inoperativo, requiere segunda visita. Riesgo de no agendar/cobrar o de que el cliente llame a un tercero (fuga).",
     "recomendacion": "Crear OT de seguimiento (pendiente repuesto) vinculada, con SKU del equipo y fecha tentativa. Agendar de inmediato la visita de cierre y dejar la cotización lista si es facturable."},
    {"patron": r"recomiendo cambiar|se recomienda cambiar|conviene reemplazar|a punto de fallar|proxima a fallar|desgastad|al limite|vida util",
     "dolor": "Oportunidad de upsell / mantención predictiva que se pierde si queda solo en el texto libre; ventana para que el repuesto se fugue a un tercero.",
     "recomendacion": "Extraer la recomendación a 'próxima intervención sugerida' y abrir cotización ILUS del repuesto/equipo. Asignar seguimiento comercial. Toda recomendación de cambio debe generar un lead."},
    {"patron": r"fuera de servicio|no funciona|inoperativo|no enciende|dado de baja|no se puede reparar|irreparable",
     "dolor": "Equipo detenido: impacto operativo y riesgo de que el cliente busque reemplazo con la competencia.",
     "recomendacion": "Indicar de inmediato la vía de solución (repuesto + costo estimado o cotización de reemplazo ILUS) y convertir la urgencia en OT/cotización pagada antes de que la tome un tercero."},
]


def _postserv_norm(s):
    import unicodedata
    s = (s or "").lower()
    return "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")


def _postservicio_analisis(visita, equipos):
    """Análisis determinista (sin IA) de una visita realizada: dispara las señales
    de dolor sobre las observaciones del técnico + flags de cobertura/garantía."""
    partes = [visita.get("observaciones") or "", visita.get("descripcion") or ""]
    for e in (equipos or []):
        if e.get("observacion_tecnico"):
            partes.append(e["observacion_tecnico"])
    texto = _postserv_norm(" \n ".join(partes))
    alertas = []
    if texto.strip():
        for s in _POSTSERV_SENALES:
            try:
                if re.search(s["patron"], texto):
                    alertas.append({"dolor": s["dolor"], "recomendacion": s["recomendacion"]})
            except re.error:
                continue
    cob = (visita.get("cubierto_por") or "contrato").lower()
    costo = float(visita.get("costo") or 0)
    cobertura_nota = ""
    if cob == "garantia":
        cobertura_nota = ("ILUS cubrió este servicio SIN COSTO (garantía). Verificar que la garantía esté "
                          "vigente y que la causa esté cubierta; si no, reclasificar a 'Cliente paga' (facturable).")
    elif cob in ("cliente", "tercero") and costo > 0:
        cobertura_nota = ("Servicio FACTURABLE (lo paga el cliente). Asegurar que termine facturado — "
                          "no dejar la OT cerrada sin documento tributario.")
    from datetime import date as _d
    hoy = _d.today()
    gar_vencidas = []
    for e in (equipos or []):
        ffg = e.get("fecha_fin_garantia")
        if ffg and hasattr(ffg, "year") and ffg < hoy and cob == "garantia":
            gar_vencidas.append(e.get("nombre") or e.get("sku") or "equipo")
    estados = [(e.get("estado_revision") or "") for e in (equipos or [])]
    if any(x == "falla_detectada" for x in estados):
        veredicto, vcolor = "Falla detectada / requiere atención", "#dc2626"
    elif any(x in ("con_cambios", "saltado") for x in estados):
        veredicto, vcolor = "Operativo con observaciones", "#f59e0b"
    elif estados:
        veredicto, vcolor = "Equipo(s) operativo(s)", "#16a34a"
    else:
        veredicto, vcolor = "Servicio realizado", "#16a34a"
    return {"alertas": alertas, "cobertura_nota": cobertura_nota,
            "gar_vencidas": gar_vencidas, "veredicto": veredicto, "vcolor": vcolor}


def _informe_postservicio_html(visita, cliente, equipos, analisis, auto_print=True):
    """Informe POST-SERVICIO de una visita (Agente ILUS, determinista, sin IA).
    Diseño por panel de especialistas. Vista imprimible → PDF en el navegador."""
    from markupsafe import escape as _esc

    def e(v):
        s = "" if v is None else str(v).strip()
        return str(_esc(s)) if s else "—"

    def e_raw(v):
        return str(_esc("" if v is None else str(v)))

    def _clp(v):
        try:
            n = float(v)
        except (TypeError, ValueError):
            return None
        return ("$" + format(int(round(n)), ",d").replace(",", ".")) if n else None

    _tipo_label = {"preventiva": "Mantención preventiva", "correctiva": "Correctiva",
                   "garantia": "Garantía", "inspeccion": "Inspección",
                   "levantamiento": "Levantamiento", "instalacion": "Instalación"}
    _cob_label = {"contrato": "Contrato", "cliente": "Cliente paga", "garantia": "Garantía (gratis)",
                  "mixto": "Mixto", "tercero": "Tercero"}
    _cob_color = {"contrato": "#16a34a", "cliente": "#b45309", "garantia": "#dc2626",
                  "mixto": "#6b7280", "tercero": "#dc2626"}
    cob = (visita.get("cubierto_por") or "contrato").lower()
    tipo = (visita.get("tipo") or "").lower()
    fecha = visita.get("fecha_realizada") or visita.get("fecha_programada")
    ver = analisis.get("veredicto") or "Servicio realizado"
    vcolor = analisis.get("vcolor") or "#16a34a"

    secciones = ""

    # Resumen ejecutivo (determinista)
    _n_eq = len(equipos or [])
    resumen = (f"Se realizó una {_tipo_label.get(tipo, 'visita')} el {e(str(fecha)[:10])}"
               + (f", atendiendo {_n_eq} equipo(s)" if _n_eq else "")
               + f". Modalidad: {_cob_label.get(cob, cob)}. Estado final: {ver}.")
    secciones += ('<div class="rep-section"><div class="rep-section-bar">Resumen ejecutivo</div>'
                  f'<p class="rep-text">{e_raw(resumen)}</p></div>')

    # Observaciones del técnico (el corazón) — transcripción fiel
    obs = (visita.get("observaciones") or "").strip()
    if obs:
        cuerpo = f'<div style="white-space:pre-wrap;color:#1f2937;font-size:11.5px;line-height:1.5">{e_raw(obs)}</div>'
    else:
        cuerpo = '<p class="rep-empty">El técnico no registró observaciones de texto en esta visita.</p>'
    secciones += ('<div class="rep-section"><div class="rep-section-bar">Observaciones del técnico (en sus palabras)</div>'
                  '<div style="border-left:3px solid #0a0a0a;background:#f9fafb;border-radius:0 8px 8px 0;padding:11px 14px;margin-top:8px">'
                  '<div style="font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#6b7280;margin-bottom:5px">Registro en terreno</div>'
                  + cuerpo + '</div></div>')

    # Equipos atendidos
    if equipos:
        from datetime import date as _d2
        hoy = _d2.today()
        _est_lbl = {"verificado": ("Verificado", "#16a34a"), "con_cambios": ("Con cambios", "#b45309"),
                    "saltado": ("No revisado", "#6b7280"), "falla_detectada": ("Falla detectada", "#dc2626")}
        rows = ""
        for eq in equipos:
            nom = e(eq.get("nombre") or eq.get("sku") or "Equipo")
            serie = e(eq.get("serie"))
            ffg = eq.get("fecha_fin_garantia")
            if ffg and hasattr(ffg, "year"):
                gar = ('<span style="color:#16a34a;font-weight:800">SÍ</span>' if ffg >= hoy
                       else '<span style="color:#dc2626;font-weight:800">NO (vencida)</span>')
            else:
                gar = '<span style="color:#9ca3af">s/d</span>'
            est = (eq.get("estado_revision") or "").lower()
            elbl, ecol = _est_lbl.get(est, (est or "—", "#6b7280"))
            obs_eq = (eq.get("observacion_tecnico") or "").strip()
            rows += (f'<tr><td><b>{nom}</b>{(" · " + serie) if serie != "—" else ""}</td>'
                     f'<td class="rep-center">{gar}</td>'
                     f'<td><span style="color:{ecol};font-weight:700">{e_raw(elbl)}</span></td></tr>')
            if obs_eq:
                rows += (f'<tr><td colspan="3" style="color:#6b7280;font-size:10.5px;padding-top:0">'
                         f'↳ {e_raw(obs_eq)}</td></tr>')
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Equipos atendidos y estado</div>'
                      '<table class="rep-kv"><tr><th>Equipo</th><th class="rep-center">Garantía</th><th>Estado</th></tr>'
                      + rows + '</table></div>')

    # Cobertura y condición comercial
    if analisis.get("cobertura_nota"):
        _cn_red = cob in ("cliente", "tercero", "garantia")
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Cobertura y condición comercial</div>'
                      f'<p class="rep-text" style="color:{"#991b1b" if _cn_red else "#374151"}">{e_raw(analisis["cobertura_nota"])}</p></div>')

    # Alertas de riesgo (USO INTERNO) — las señales disparadas
    alertas = analisis.get("alertas") or []
    if alertas:
        cards = ""
        for al in alertas:
            cards += ('<div style="border:1px solid #fecaca;border-left:4px solid #dc2626;border-radius:0 8px 8px 0;'
                      'padding:9px 12px;margin-bottom:7px;background:#fff5f5">'
                      f'<div style="font-weight:800;color:#991b1b;font-size:11px">{e_raw(al.get("dolor"))}</div>'
                      f'<div style="color:#374151;font-size:10.5px;margin-top:3px"><b>Acción:</b> {e_raw(al.get("recomendacion"))}</div>'
                      '</div>')
        secciones += ('<div class="rep-section"><div class="rep-section-bar" style="background:#dc2626">'
                      '⚠ Alertas de riesgo — USO INTERNO (no mostrar al cliente)</div>'
                      f'<div style="margin-top:8px">{cards}</div></div>')

    logo_url = _ilus_logo_datauri()
    gen_fecha = _now_chile_str("%d/%m/%Y %H:%M")
    rut_fmt = _formato_rut_chile(cliente.get("rut", "")) or "—"
    _scripts = _paged_doc_scripts(auto_print)
    razon = cliente.get("razon_social") or "Cliente"

    return f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Informe post-servicio · {e(razon)}</title>
<style>{_REPORTE_PDF_CSS}</style></head>
<body>
  <div class="rep-doc">
    <div class="rh"><div class="rh-inner">
      <div class="rh-brand">
        <img class="rep-logo" src="{logo_url}" alt="ILUS"
             onerror="this.outerHTML='<div class=&quot;rep-logo-fallback&quot;>ILUS.</div>'">
        <div class="rh-txt">
          <div class="rh-eyebrow">{ILUS_BRAND} · {ILUS_TAGLINE}</div>
          <div class="rh-title">INFORME POST-SERVICIO</div>
          <div class="rh-sub">{ILUS_LEGAL} · RUT {ILUS_RUT} · Agente ILUS (sin IA)</div>
        </div>
      </div>
      <div class="rh-meta" style="text-align:right">
        <div style="font-size:8.5px;color:rgba(255,255,255,.6);text-transform:uppercase;letter-spacing:.4px">Estado final</div>
        <span style="display:inline-block;margin-top:5px;font-size:11px;font-weight:800;color:#fff;background:{vcolor};padding:5px 13px;border-radius:50px">{e_raw(ver)}</span>
      </div>
    </div></div>
    <div class="rf"><div class="rf-inner">
      <b>{ILUS_BRAND}</b> · {ILUS_LEGAL} · Informe del Agente (determinista, sin IA) · {ILUS_CONTACTO} · Generado el {gen_fecha}
    </div></div>
    <div class="rep-content">
      <div class="rep-asunto"><span class="rep-asunto-k">Servicio</span>{e(visita.get('titulo') or _tipo_label.get(tipo, 'Visita de servicio técnico'))}</div>
      <div class="rep-section">
        <div class="rep-section-bar">Identificación del servicio</div>
        <table class="rep-kv">
          <tr><th>Cliente</th><td>{e(razon)}</td><th>RUT</th><td>{e_raw(rut_fmt)}</td></tr>
          <tr><th>Dirección</th><td>{e(cliente.get('direccion'))}</td><th>Comuna</th><td>{e(cliente.get('comuna'))}</td></tr>
          <tr><th>Tipo</th><td>{e(_tipo_label.get(tipo, tipo))}</td><th>Fecha</th><td>{e(str(fecha)[:10] if fecha else None)}</td></tr>
          <tr><th>Técnico</th><td>{e(visita.get('tecnico'))}</td>
              <th>Cobertura</th><td><span style="color:{_cob_color.get(cob,'#374151')};font-weight:800">{e(_cob_label.get(cob, cob))}</span></td></tr>
        </table>
      </div>
      {secciones}
    </div>
  </div>
  {_scripts}
</body></html>"""


@app.route("/mantenciones/api/visitas/<int:vid>/informe-postservicio", methods=["GET"])
@app.route("/servicio-tecnico/api/visitas/<int:vid>/informe-postservicio", methods=["GET"])
@_mant_required
@_ot_can_view
def mant_informe_postservicio(vid):
    """Informe post-servicio de una visita realizada (Agente determinista). Imprimible → PDF.

    🔐 SEGURIDAD 2026-08-26: faltaba @_ot_can_view — exponía datos personales
    del cliente (RUT, dirección, contacto) de cualquier OT a cualquier usuario
    con permiso "mantenciones"."""
    v = mysql_fetchone(
        "SELECT v.*, c.razon_social, c.rut, c.direccion, c.comuna, c.contacto_nombre "
        "FROM mant_visitas v JOIN mant_clientes c ON c.id=v.cliente_id WHERE v.id=%s", (vid,))
    if not v:
        return "Visita no encontrada", 404
    try:
        equipos = mysql_fetchall(
            "SELECT ve.estado_revision, ve.razon_saltado, ve.observacion_tecnico, "
            "m.sku, m.nombre, m.serie, m.fecha_fin_garantia, m.estado AS maquina_estado "
            "FROM mant_visita_equipos ve LEFT JOIN mant_maquinas m ON m.id=ve.maquina_id "
            "WHERE ve.visita_id=%s ORDER BY ve.id", (vid,)) or []
    except Exception:
        equipos = []
    analisis = _postservicio_analisis(v, equipos)
    cli = {"razon_social": v.get("razon_social"), "rut": v.get("rut"),
           "direccion": v.get("direccion"), "comuna": v.get("comuna"),
           "contacto_nombre": v.get("contacto_nombre")}
    try:
        _mant_log("visita", vid, "informe_postservicio")
    except Exception:
        pass
    return _informe_postservicio_html(v, cli, equipos, analisis)


def _contrato_analisis_to_pdf_html(ct, cliente, auto_print=True):
    """Documento corporativo ILUS del Análisis 360° del contrato (Comité IA).
    Renderiza el JSON persistido en ai_analisis_json reusando el sistema de
    diseño del informe (_REPORTE_PDF_CSS). El navegador genera el PDF."""
    from markupsafe import escape as _esc

    def e(v):
        s = "" if v is None else str(v).strip()
        return str(_esc(s)) if s else "—"

    def e_raw(v):
        return str(_esc("" if v is None else str(v)))

    def _clp(v):
        try:
            n = float(v)
        except (TypeError, ValueError):
            return None
        if not n:
            return None
        return "$" + format(int(round(n)), ",d").replace(",", ".")

    def _ul(items):
        items = [i for i in (items or []) if str(i).strip()]
        if not items:
            return '<p class="rep-empty">Sin elementos.</p>'
        return '<ul class="rep-list">' + "".join(f"<li>{e_raw(i)}</li>" for i in items) + "</ul>"

    try:
        data = json.loads(ct.get("ai_analisis_json") or "{}")
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}

    # Fallback a columnas sueltas si no hay JSON 360 completo.
    resumen   = data.get("resumen") or ct.get("ai_resumen") or ""
    tipo_c    = data.get("tipo_contrato") or ct.get("ai_tipo_contrato") or ""
    try:    score = int(float(data.get("score") if data.get("score") is not None else (ct.get("ai_score") or 0)))
    except Exception: score = 0
    score = max(0, min(100, score))
    riesgo    = (data.get("nivel_riesgo") or ct.get("nivel_riesgo") or "medio").lower()
    sc_color  = "#16a34a" if score >= 70 else "#f59e0b" if score >= 40 else "#dc2626"
    sc_text   = "Excelente" if score >= 80 else "Bueno" if score >= 60 else "Regular" if score >= 40 else "Crítico"
    rg_map    = {"alto": ("#dc2626", "ALTO"), "bajo": ("#16a34a", "BAJO")}
    rg_color, rg_label = rg_map.get(riesgo, ("#f59e0b", "MEDIO"))
    _dash     = round(score * 2.764, 1)

    # ── Chips económicos ──
    def _chip(label, value):
        if not value:
            return ""
        return (f'<span class="rep-chip"><span class="rep-chip-k">{e_raw(label)}</span>'
                f'<span class="rep-chip-v">{e_raw(value)}</span></span>')
    chips = (
        '<div class="rep-chips">'
        + _chip("Monto mensual", _clp(data.get("costo_mensual")))
        + _chip("Costo total", _clp(data.get("costo_total")))
        + _chip("Por mantención", _clp(data.get("costo_por_mant")))
        + _chip("SLA", (str(data.get("sla_horas")) + " h") if data.get("sla_horas") else "")
        + _chip("Frecuencia", ("c/" + str(data.get("frecuencia_sugerida_meses")) + " meses") if data.get("frecuencia_sugerida_meses") else "")
        + _chip("Vigencia", ("Indefinido" if data.get("es_indefinido") else
                             (str(data.get("vigencia_inicio") or "") + " → " + str(data.get("vigencia_fin") or "")).strip(" →")))
        + "</div>"
    )

    secciones = ""

    # Resumen gerencial
    if resumen:
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Resumen gerencial</div>'
                      f'<p class="rep-text">{e_raw(resumen)}</p></div>')

    # Cobertura
    if data.get("cobertura_descripcion"):
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Cobertura</div>'
                      f'<p class="rep-text">{e_raw(data["cobertura_descripcion"])}</p></div>')

    # Exposición + escenarios
    exp = data.get("exposicion") or {}
    if exp.get("resumen") or exp.get("escenarios"):
        scn = ""
        for s in (exp.get("escenarios") or []):
            if not isinstance(s, dict):
                continue
            scn += ("<tr>"
                    f"<td>{e(s.get('riesgo'))}</td>"
                    f"<td>{e(s.get('impacto'))}</td>"
                    f"<td class='rep-center'>{e(s.get('probabilidad'))}</td>"
                    f"<td>{e(s.get('mitigacion'))}</td></tr>")
        tabla = ("<table class='rep-table' style='margin-top:8px'><thead><tr>"
                 "<th>Riesgo</th><th>Impacto</th><th>Prob.</th><th>Mitigación</th></tr></thead>"
                 f"<tbody>{scn}</tbody></table>") if scn else ""
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Exposición para ILUS</div>'
                      + (f'<p class="rep-text">{e_raw(exp.get("resumen"))}</p>' if exp.get("resumen") else "")
                      + tabla + "</div>")

    # Análisis de garantía
    gar = data.get("analisis_garantia") or {}
    if gar:
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Análisis de garantía</div>'
                      '<table class="rep-kv">'
                      f'<tr><th>¿Cubre garantía?</th><td>{"Sí" if gar.get("cubre_garantia") else "No"}</td>'
                      f'<th>¿Condicionada a mantención ILUS?</th><td>{"Sí" if gar.get("condicionada_a_mantencion_ilus") else "No"}</td></tr>'
                      + (f'<tr><th>Riesgo terceros</th><td colspan="3">{e(gar.get("riesgo_terceros"))}</td></tr>' if gar.get("riesgo_terceros") else "")
                      + (f'<tr><th>Recomendación</th><td colspan="3">{e(gar.get("recomendacion"))}</td></tr>' if gar.get("recomendacion") else "")
                      + '</table></div>')

    # Listas de hallazgos
    for titulo, key in (("Puntos críticos", "puntos_criticos"),
                        ("Cláusulas críticas / ausentes", "clausulas_criticas"),
                        ("Alertas accionables", "alertas"),
                        ("Mejoras prioritarias", "mejoras_prioritarias")):
        if data.get(key):
            secciones += (f'<div class="rep-section"><div class="rep-section-bar">{titulo}</div>'
                          f'{_ul(data.get(key))}</div>')

    # Cláusulas sugeridas (tarjetas)
    cls = data.get("clausulas_sugeridas") or []
    if cls:
        cards = ""
        for c in cls:
            if not isinstance(c, dict):
                continue
            cards += ('<div style="border:1px solid #e5e7eb;border-left:4px solid #dc2626;'
                      'border-radius:0 8px 8px 0;padding:10px 13px;margin-bottom:8px;background:#fff">'
                      f'<div style="font-weight:800;color:#0a0a0a;font-size:11.5px;margin-bottom:3px">{e(c.get("titulo"))}</div>'
                      f'<div style="color:#374151;white-space:pre-wrap">{e_raw(c.get("texto"))}</div>'
                      + (f'<div style="color:#6b7280;font-size:10px;margin-top:5px"><b>Por qué:</b> {e_raw(c.get("justificacion"))}</div>' if c.get("justificacion") else "")
                      + "</div>")
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Cláusulas sugeridas (listas para usar)</div>'
                      f'<div style="margin-top:8px">{cards}</div></div>')

    # Propuestas comerciales
    props = data.get("propuestas_comerciales") or []
    if props:
        cards = ""
        for p in props:
            if not isinstance(p, dict):
                continue
            prio = (p.get("prioridad") or "").lower()
            pc = "#dc2626" if prio == "alta" else "#16a34a" if prio == "baja" else "#b45309"
            cards += ('<div style="border:1px solid #e5e7eb;border-radius:8px;padding:10px 13px;margin-bottom:8px;background:#fff">'
                      f'<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:3px">'
                      f'<span style="font-weight:800;color:#0a0a0a;font-size:11.5px">{e(p.get("titulo"))}</span>'
                      + (f'<span style="font-size:9px;font-weight:800;text-transform:uppercase;color:#fff;background:{pc};padding:2px 9px;border-radius:50px">{e_raw(prio)}</span>' if prio else "")
                      + "</div>"
                      f'<div style="color:#374151">{e_raw(p.get("descripcion"))}</div>'
                      + (f'<div style="color:#166534;font-size:10px;margin-top:5px"><b>Impacto ingreso:</b> {e_raw(p.get("impacto_ingreso"))}</div>' if p.get("impacto_ingreso") else "")
                      + "</div>")
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Propuestas comerciales</div>'
                      f'<div style="margin-top:8px">{cards}</div></div>')

    # Rentabilidad
    rent = data.get("rentabilidad") or {}
    if rent and (rent.get("mrr_estimado_clp") or rent.get("margen_estimado") or rent.get("oportunidad_ingreso_clp")):
        secciones += ('<div class="rep-section"><div class="rep-section-bar">Rentabilidad</div>'
                      '<table class="rep-kv">'
                      f'<tr><th>MRR estimado</th><td>{e(_clp(rent.get("mrr_estimado_clp")) or "—")}</td>'
                      f'<th>Margen</th><td>{e(rent.get("margen_estimado"))}</td></tr>'
                      f'<tr><th>Oportunidad ingreso</th><td colspan="3">{e(_clp(rent.get("oportunidad_ingreso_clp")) or "—")}</td></tr>'
                      '</table></div>')

    logo_url  = _ilus_logo_datauri()
    gen_fecha = _now_chile_str("%d/%m/%Y %H:%M")
    rut_fmt   = _formato_rut_chile(cliente.get("rut", "")) or "—"
    _scripts  = _paged_doc_scripts(auto_print)

    return f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Análisis de contrato · {e(cliente.get('razon_social'))}</title>
<style>{_REPORTE_PDF_CSS}</style></head>
<body>
  <div class="rep-doc">
    <div class="rh"><div class="rh-inner">
      <div class="rh-brand">
        <img class="rep-logo" src="{logo_url}" alt="ILUS"
             onerror="this.outerHTML='<div class=&quot;rep-logo-fallback&quot;>ILUS.</div>'">
        <div class="rh-txt">
          <div class="rh-eyebrow">{ILUS_BRAND} · {ILUS_TAGLINE}</div>
          <div class="rh-title">ANÁLISIS DE CONTRATO</div>
          <div class="rh-sub">{ILUS_LEGAL} · RUT {ILUS_RUT} · Comité de Expertos IA</div>
        </div>
      </div>
      <div class="rh-meta" style="display:flex;align-items:center;gap:12px">
        <svg viewBox="0 0 100 100" style="width:66px;height:66px">
          <circle cx="50" cy="50" r="44" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="9"></circle>
          <circle cx="50" cy="50" r="44" fill="none" stroke="{sc_color}" stroke-width="9"
                  stroke-dasharray="{_dash} {round(276.4 - _dash, 1)}"
                  transform="rotate(-90 50 50)" stroke-linecap="round"></circle>
          <text x="50" y="49" text-anchor="middle" style="font-size:27px;font-weight:900;fill:#fff">{score}</text>
          <text x="50" y="64" text-anchor="middle" style="font-size:9px;fill:rgba(255,255,255,.65)">de 100</text>
        </svg>
        <div style="text-align:left">
          <span style="display:inline-block;font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#fff;background:{sc_color};padding:3px 10px;border-radius:50px">{sc_text}</span><br>
          <span style="display:inline-block;margin-top:6px;font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#fff;background:{rg_color};padding:3px 10px;border-radius:50px">Riesgo {rg_label}</span>
        </div>
      </div>
    </div></div>
    <div class="rf"><div class="rf-inner">
      <b>{ILUS_BRAND}</b> · {ILUS_LEGAL} · Análisis asistido por IA · {ILUS_CONTACTO} · Generado el {gen_fecha}
    </div></div>
    <div class="rep-content">
      <div class="rep-asunto"><span class="rep-asunto-k">Contrato</span>{e(ct.get('nombre') or tipo_c or 'Contrato de servicio')}</div>
      <div class="rep-section">
        <div class="rep-section-bar">Datos del cliente y contrato</div>
        <table class="rep-kv">
          <tr><th>Razón Social</th><td>{e(cliente.get('razon_social'))}</td><th>RUT</th><td>{e_raw(rut_fmt)}</td></tr>
          <tr><th>Tipo de contrato</th><td>{e(tipo_c)}</td><th>Frecuencia ERP</th><td>{e((str(ct.get('frecuencia_meses')) + ' meses') if ct.get('frecuencia_meses') else None)}</td></tr>
        </table>
      </div>
      {chips}
      {secciones}
    </div>
  </div>
  {_scripts}
</body></html>"""


@app.route("/mantenciones/api/contratos/<int:ctid>/analisis/pdf", methods=["GET"])
@app.route("/servicio-tecnico/api/contratos/<int:ctid>/analisis/pdf", methods=["GET"])
@_mant_required
def mant_contrato_analisis_pdf(ctid):
    """Vista imprimible del Análisis 360° del contrato (el navegador genera el PDF)."""
    ct = mysql_fetchone(
        "SELECT ct.*, cl.razon_social, cl.rut FROM mant_contratos ct "
        "JOIN mant_clientes cl ON cl.id=ct.cliente_id WHERE ct.id=%s", (ctid,)
    )
    if not ct:
        return "Contrato no encontrado", 404
    if not ct.get("ai_analizado"):
        return ("Este contrato aún no tiene análisis IA. Analízalo primero "
                "desde la ficha del cliente.", 404)
    cliente = {"razon_social": ct.get("razon_social", ""), "rut": ct.get("rut", "")}
    try: _mant_log("contrato", ctid, "exportar_analisis_pdf")
    except Exception: pass
    return _contrato_analisis_to_pdf_html(dict(ct), cliente)


@app.route("/mantenciones/api/reportes/<int:rid>/analizar", methods=["POST"])
@_mant_required
def mant_reporte_analizar_reglas(rid):
    """Agente interno (REGLAS, sin IA / sin tokens): valida que el informe esté
    completo (ticket + OT + documento obligatorios) y genera diagnóstico +
    recomendaciones por reglas. Guarda y devuelve {ok, completo, faltantes, analisis}."""
    rep, cliente = _load_reporte_full(rid)
    if not rep:
        return jsonify({"error": "Informe no encontrado"}), 404
    analisis = _reporte_analisis_reglas(rep, cliente)
    try:
        mysql_execute(
            "UPDATE mant_reportes SET analisis_reglas_json=%s, analisis_reglas_at=NOW() WHERE id=%s",
            (json.dumps(analisis, ensure_ascii=False), rid)
        )
    except Exception as e:
        print(f"[reporte_analizar_reglas] {e}", flush=True)
    try:
        _mant_log("reporte", rid, "analizado_interno",
                  f"completo={analisis['completo']} idx={analisis['indice_completitud']}%")
    except Exception:
        pass
    return jsonify({"ok": True, "completo": analisis["completo"],
                    "faltantes": analisis["faltantes"], "analisis": analisis})


@app.route("/mantenciones/api/reportes/<int:rid>/ot-doc", methods=["POST"])
@_mant_required
@_no_tecnico
def mant_reporte_ot_doc(rid):
    """Adjunta el PDF de la OT al informe (obligatorio para avanzar)."""
    if not mysql_fetchone("SELECT id FROM mant_reportes WHERE id=%s", (rid,)):
        return jsonify({"error": "Informe no encontrado"}), 404
    f = (request.files.get("doc") or request.files.get("file")
         or request.files.get("archivo"))
    if not f or not f.filename:
        return jsonify({"error": "No se recibió ningún archivo"}), 400
    ext = (f.filename.rsplit(".", 1)[-1] if "." in f.filename else "").lower()
    if ext != "pdf":
        return jsonify({"error": "El documento de la OT debe ser un archivo PDF"}), 400
    url = None
    try:
        if _gcs_ready():
            res = _cloud_upload_raw(f.stream, public_id=f"otdoc_rep{rid}", folder="ilus/informes_ot")
            url = res.get("url")
        else:
            from werkzeug.utils import secure_filename as _sf
            sub = os.path.join(UPLOAD_FOLDER, "mantenciones", "reportes")
            os.makedirs(sub, exist_ok=True)
            fname = f"otdoc_{rid}_{_sf(f.filename)}"
            f.save(os.path.join(sub, fname))
            url = f"/static/uploads/mantenciones/reportes/{fname}"
    except Exception as e:
        print(f"[reporte_ot_doc] {e}", flush=True)
        return jsonify({"error": "No se pudo subir el documento"}), 500
    mysql_execute("UPDATE mant_reportes SET ot_doc_url=%s, ot_doc_nombre=%s WHERE id=%s",
                  (url, f.filename[:300], rid))
    try: _mant_log("reporte", rid, "ot_doc_adjuntado", f.filename[:120])
    except Exception: pass
    return jsonify({"ok": True, "url": url, "nombre": f.filename})


@app.route("/mantenciones/api/clientes/<int:cid>/visita-id", methods=["GET"])
@_mant_required
def mant_cliente_visita_id(cid):
    """Resuelve el id de una OT (visita) del cliente a partir de su N° de OT
    (numero_ot, id o coincidencia parcial). Para 'Generar informe desde OT'."""
    ot = (request.args.get("ot") or "").strip()
    if not ot:
        return jsonify({"error": "Falta el N° de OT"}), 400
    cond_id = int(ot) if ot.isdigit() else -1
    v = mysql_fetchone(
        "SELECT id, numero_ot FROM mant_visitas "
        " WHERE cliente_id=%s AND (id=%s OR numero_ot=%s OR numero_ot LIKE %s) "
        " ORDER BY id DESC LIMIT 1",
        (cid, cond_id, ot, f"%{ot}")
    )
    if not v:
        return jsonify({"ok": False, "error": f"No se encontró una OT '{ot}' para este cliente."}), 404
    return jsonify({"ok": True, "vid": v["id"], "numero_ot": v.get("numero_ot")})


@app.route("/mantenciones/api/reportes/<int:rid>/pdf", methods=["GET"])
@_mant_required
def mant_reporte_pdf(rid):
    """PDF del Informe Post Servicio en formato ILUS (estilo Word).

    Genera un PDF REAL (Playwright, hoja carta) con el template
    reporte_informe_pdf.html. Si Chromium no está disponible en el server,
    cae con elegancia a la vista imprimible HTML (window.print()).
    Forzar la vista imprimible: ?print=1.
    Accesible para todos los roles con permiso de mantenciones.
    """
    rep, cliente = _load_reporte_full(rid)
    if not rep:
        return "Reporte no encontrado", 404
    # FIX 2026-06-02 (Daniel — "visualizar documentos no funciona"): el PDF/vista
    # del informe SIEMPRE se genera. La obligatoriedad de N° ticket + N° OT +
    # documento de la OT se valida en el "agente interno" (POST /analizar) y al
    # emitir — NO se bloquea la VISUALIZACIÓN (antes esto rompía la vista de
    # informes existentes que aún no tenían esos datos).
    try:
        _mant_log("reporte", rid, "exportar_pdf")
    except Exception:
        pass
    if request.args.get("print") != "1":
        try:
            pdf_bytes = _reporte_informe_pdf_bytes(rep, cliente)
            _ot = (rep.get("ot_num") or "").strip()
            _tk = (rep.get("ticket_num") or "").strip()
            fname = ("Informe" + (f"_OT{_ot}" if _ot else "")
                     + (f"_T{_tk}" if _tk else f"_{rid}") + ".pdf").replace(" ", "")
            resp = make_response(pdf_bytes)
            resp.headers["Content-Type"] = "application/pdf"
            resp.headers["Content-Disposition"] = f'inline; filename="{fname}"'
            return resp
        except PDFEngineUnavailable as e:
            print(f"[reporte_pdf] Playwright no disponible, fallback HTML: {e}", flush=True)
        except Exception as e:
            print(f"[reporte_pdf] error generando PDF, fallback HTML: {e}", flush=True)
    # Fallback: vista imprimible del navegador (no requiere Chromium server-side)
    return _reporte_to_pdf_html(rep, cliente)


@app.route("/mantenciones/api/reportes/<int:rid>/word", methods=["GET"])
@_mant_required
def mant_reporte_word(rid):
    """Descarga el reporte como DOCX."""
    r = mysql_fetchone(
        "SELECT r.*, c.razon_social, c.rut FROM mant_reportes r "
        "JOIN mant_clientes c ON c.id=r.cliente_id WHERE r.id=%s", (rid,)
    )
    if not r: return jsonify({"error":"No encontrado"}), 404
    rep = dict(r)
    cliente = {"razon_social": rep.pop("razon_social",""), "rut": rep.pop("rut","")}
    # Decode JSON fields
    for k in ("objetivos","trabajos","observaciones","maquinas_json","ai_acciones"):
        if rep.get(k):
            try: rep[k] = json.loads(rep[k])
            except: rep[k] = []
    docx_bytes = _build_reporte_docx(rep, cliente)
    if not docx_bytes:
        return jsonify({"error":"python-docx no instalado en el servidor"}), 503
    fname = f"informe_{rid}_{cliente.get('razon_social','cliente').replace(' ','_')[:40]}.docx"
    resp = make_response(docx_bytes)
    resp.headers["Content-Type"] = "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    resp.headers["Content-Disposition"] = f'attachment; filename="{fname}"'
    _mant_log("reporte", rid, "exportar_word")
    return resp


@app.route("/mantenciones/api/reportes/<int:rid>/html", methods=["GET"])
@app.route("/servicio-tecnico/api/reportes/<int:rid>/html", methods=["GET"])
@_mant_required
def mant_reporte_html(rid):
    """Devuelve preview HTML del reporte (mismo formato corporativo que el PDF)."""
    rep, cliente = _load_reporte_full(rid)
    if not rep: return "Reporte no encontrado", 404
    return _reporte_to_pdf_html(rep, cliente, auto_print=False)


@app.route("/mantenciones/api/reportes/<int:rid>/enviar", methods=["POST"])
@_mant_required
def mant_reporte_enviar(rid):
    """Envía el reporte por email al cliente o a destinatarios custom."""
    d = request.get_json(silent=True) or {}
    r = mysql_fetchone(
        "SELECT r.*, c.razon_social, c.rut, c.contacto_email, c.contacto_nombre "
        "FROM mant_reportes r JOIN mant_clientes c ON c.id=r.cliente_id WHERE r.id=%s", (rid,)
    )
    if not r: return jsonify({"error":"No encontrado"}), 404
    rep = dict(r)
    cliente = {
        "razon_social": rep.pop("razon_social",""),
        "rut":          rep.pop("rut",""),
        "contacto_email": rep.pop("contacto_email",""),
        "contacto_nombre": rep.pop("contacto_nombre",""),
    }
    for k in ("objetivos","trabajos","observaciones","maquinas_json","ai_acciones"):
        if rep.get(k):
            try: rep[k] = json.loads(rep[k])
            except: rep[k] = []

    # FIX 2026-06-11: (a) el ternario anterior tenía mal la precedencia —
    # si el cliente no tenía contacto_email, descartaba TAMBIÉN los
    # 'destinatarios' explícitos del body; (b) el default ahora son TODOS
    # los emails del cliente (contacto + contacto2 + empresa), no solo uno.
    destinatarios = d.get("destinatarios") or _mant_get_cliente_emails(r["cliente_id"]) \
        or ([cliente["contacto_email"]] if cliente["contacto_email"] else [])
    destinatarios = [str(e).strip() for e in destinatarios if e and "@" in str(e)]
    if not destinatarios:
        return jsonify({"error":"Sin destinatarios válidos. Configura email del cliente o pasa 'destinatarios'."}), 400

    asunto = d.get("asunto") or f"Informe post-servicio {rep.get('ticket_num') or '#'+str(rid)} — {cliente['razon_social']}"
    mensaje_extra = d.get("mensaje","").strip()

    # Construir HTML del email — siempre con la plantilla corporativa
    html_reporte = _reporte_to_html(rep, cliente)
    # Texto de acompañamiento EDITABLE desde /comunicaciones (mantenciones /
    # 'ot_completada'); si no hay plantilla, cae al texto actual (REGLA #4.2).
    # El informe en sí (html_reporte) y el adjunto Word se conservan siempre.
    _intro = (
        f"<p>Estimado/a {cliente['contacto_nombre'] or cliente['razon_social']},</p>"
        f"<p>Adjunto encontrarás el informe de servicio realizado. {mensaje_extra}</p>"
        f"<p>Saludos,<br><strong>Equipo {ILUS_BRAND}</strong></p>"
    )
    try:
        # FIX 2026-07-25 (auditoría Comunicaciones): la plantilla real de
        # 'ot_completada' (comm_templates) usa {{tipo_mantencion}}, {{tecnico}}
        # y {{maquina}} además de {{ot}}/{{cliente}} -- antes esta llamada NO
        # las pasaba, así que _render_comm_template las borraba en silencio
        # (barrido de seguridad) y el correo llegaba con esas 3 filas vacías
        # (mismo patrón de bug que _tr_notificar_cliente en transporte).
        _tipo_rep_label = {
            "mantencion":     "Mantención",
            "instalacion":    "Instalación",
            "inspeccion":     "Inspección",
            "visita_tecnica": "Visita técnica",
            "garantia":       "Garantía",
            "otro":           "Servicio",
        }.get(rep.get("tipo"), rep.get("tipo") or "Servicio")
        _tecs_rep = ", ".join(
            t for t in [rep.get("tecnico_junior"), rep.get("tecnico_senior")] if (t or "").strip()
        ) or "—"
        try:
            _maqs_rep = rep.get("maquinas_json") or []
            _maq_rep_str = ", ".join(
                (m.get("descripcion") or m.get("sku") or "").strip()
                for m in _maqs_rep if isinstance(m, dict) and (m.get("descripcion") or m.get("sku"))
            ) or "—"
        except Exception:
            _maq_rep_str = "—"
        _it = _render_comm_template("ot_completada", "email", {
            "cliente": cliente.get("contacto_nombre") or cliente.get("razon_social") or "",
            "ot": rep.get("ticket_num") or f"#{rid}",
            "mensaje_extra": mensaje_extra,
            "tipo_mantencion": _tipo_rep_label,
            "tecnico": _tecs_rep,
            "maquina": _maq_rep_str,
        }, modulo="mantenciones")
        if _it and (_it[1] or "").strip():
            if (_it[0] or "").strip():
                asunto = _it[0].strip()
            _intro = _it[1]
    except Exception:
        pass
    body_email = (
        f"{_intro}"
        f"<hr style='border:none;border-top:1px solid #eaecf0;margin:18px 0'>"
        f"{html_reporte}"
    )
    html_email = _comm_render_email_document(asunto, body_email, "Informe de servicio")

    # Adjunto Word
    attachments = []
    try:
        docx_bytes = _build_reporte_docx(rep, cliente)
        if docx_bytes:
            attachments.append({
                "filename": f"informe_{rep.get('ticket_num') or rid}.docx",
                "content_type": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                "content": docx_bytes,
            })
    except Exception as exc:
        print(f"[REPORTE WORD] {exc}")

    # Enviar UNO POR UNO por destinatario (FIX 2026-06-11):
    # antes se mandaba un solo email con to_addr=", ".join(destinatarios)
    # — SMTP/Resend tratan eso como UNA casilla inválida con comas y el
    # informe no llegaba a nadie cuando había 2+ destinatarios. Además,
    # _send_ilus_email_real ahora SÍ acepta attachments (el adjunto Word
    # nunca llegaba: TypeError tragado).
    res = _mant_send_email_multi(r["cliente_id"], asunto, html_email,
                                 evento="reporte_servicio",
                                 emails=destinatarios,
                                 attachments=attachments)
    sent = bool(res["enviados"])
    err = None
    if not sent:
        err = ("Llave de paso de Mantenciones cerrada — envío bloqueado"
               if res["bloqueados"] else
               "No se pudo enviar a ningún destinatario (revisa configuración SMTP/Resend)")

    # Log
    _mant_log("reporte", rid, "enviar_email",
              f"to={','.join(destinatarios)} enviados={len(res['enviados'])} "
              f"bloqueados={res['bloqueados']} fallidos={res['fallidos']} "
              f"adjuntos={len(attachments)} err={err or '-'}")

    if sent:
        # Crear notificación de envío
        try:
            mysql_execute(
                "INSERT INTO mant_notificaciones (cliente_id,entidad,entidad_id,tipo,titulo,mensaje,canal,estado,destinatario,fecha_envio,created_by) "
                "VALUES (%s,'reporte',%s,'sla',%s,%s,'email','enviada',%s,NOW(),%s)",
                (r["cliente_id"], rid, f"Informe enviado al cliente",
                 f"Informe {rep.get('ticket_num') or rid} enviado a {', '.join(res['enviados'])}",
                 ", ".join(res["enviados"]), current_username())
            )
        except Exception: pass

    return jsonify({"ok": sent, "destinatarios": destinatarios,
                    "enviados": res["enviados"], "bloqueados": res["bloqueados"],
                    "fallidos": res["fallidos"], "error": err})


# ── ADJUNTOS DE CONTRATOS (multi-archivo) ─────────────────────────────

ALLOWED_ADJUNTO_TIPOS = {
    "pdf":"contrato","doc":"contrato","docx":"contrato",
    "jpg":"imagen","jpeg":"imagen","png":"imagen","gif":"imagen","webp":"imagen",
    "xlsx":"solicitud","xls":"solicitud",
}

@app.route("/mantenciones/api/contratos/<int:ctid>/adjuntos", methods=["GET"])
@_mant_required
def mant_adjuntos_list(ctid):
    """Lista adjuntos del contrato con URL servible.

    FIX 2026-05-22: antes siempre devolvía /static/uploads/... incluso cuando
    el adjunto tenía cloudinary_url. En Railway con filesystem efímero, los
    /static/uploads/ se pierden tras deploy → adjunto aparece pero al click
    da 404. Ahora preferimos cloudinary_url cuando existe.
    """
    rows = mysql_fetchall(
        "SELECT id,tipo,nombre,archivo_nombre,mime_type,tamaño_bytes,descripcion,"
        "       cloudinary_url,created_by,created_at "
        "FROM mant_contrato_adjuntos WHERE contrato_id=%s ORDER BY created_at DESC", (ctid,)
    )
    def _fmt(r):
        d = dict(r)
        d["created_at"] = str(d["created_at"])[:16] if d.get("created_at") else ""
        # Cloudinary primero (persistente). Si no hay, filesystem efímero.
        cld = d.get("cloudinary_url") or ""
        if cld:
            d["url"] = cld
            d["persistente"] = True
        else:
            d["url"] = f"/static/uploads/mantenciones/{d['archivo_nombre']}"
            d["persistente"] = False
        return d
    return jsonify([_fmt(r) for r in rows])


@app.route("/mantenciones/api/contratos/<int:ctid>/adjuntos", methods=["POST"])
@_mant_required
def mant_adjunto_subir(ctid):
    """Sube un adjunto al contrato (anexo, externo, otro tipo).

    Acepta form fields:
      archivo:         file (requerido)
      tipo:            ENUM (contrato/imagen/solicitud/cotizacion/reporte/otro/externo/anexo)
                       Si no viene, se infiere del mime type.
      subtipo_externo: si tipo='externo' o 'anexo', sub-categoría
                       (visita_externa, ot_externa, anexo_contrato, otro)
      nombre:          nombre legible (sino usa filename original)
      descripcion:     texto libre

    Storage: Cloudinary primero (persistente), filesystem como fallback.
    """
    ct = mysql_fetchone("SELECT cliente_id FROM mant_contratos WHERE id=%s", (ctid,))
    if not ct: return jsonify({"error":"Contrato no encontrado"}), 404
    f = request.files.get("archivo")
    if not f or not f.filename: return jsonify({"error":"Sin archivo"}), 400
    ext  = f.filename.rsplit(".",1)[-1].lower()
    if ext not in ALLOWED_ADJUNTO:
        return jsonify({"error":f"Tipo .{ext} no permitido"}), 400

    # Tipo explícito desde form, sino inferido por mime
    tipo_form = (request.form.get("tipo") or "").strip().lower()
    if tipo_form in ("contrato","imagen","solicitud","cotizacion","reporte","otro","externo","anexo"):
        tipo = tipo_form
    else:
        tipo = ALLOWED_ADJUNTO_TIPOS.get(ext, "otro")
    subtipo_externo = (request.form.get("subtipo_externo") or "").strip()[:80] or None

    fname = secure_filename(f"ct{ctid}_{int(time.time())}_{f.filename}")

    # ── Cloudinary primero (persistente) ─────────────────────────────
    cloud_url = None
    cloud_pid = None
    if _gcs_ready():
        try:
            f.stream.seek(0)
            folder = f"ilus/contratos/adjuntos/{tipo}"
            public_id = f"adj_{ctid}_{int(time.time())}"
            res = _cloud_upload_raw(f.stream, public_id, folder=folder)
            cloud_url = res["url"]
            cloud_pid = res["public_id"]
            print(f"[mant_adjunto] Cloudinary OK ct={ctid} tipo={tipo} url={cloud_url}", flush=True)
        except Exception as e_cld:
            print(f"[mant_adjunto] Cloudinary FAIL ct={ctid}: {e_cld} — fallback filesystem", flush=True)

    # ── Filesystem fallback ──────────────────────────────────────────
    try:
        f.stream.seek(0)
    except Exception:
        pass
    fpath = os.path.join(MANT_UPLOADS, fname)
    size = 0
    try:
        f.save(fpath)
        size = os.path.getsize(fpath)
    except Exception as e_save:
        if not cloud_url:
            return jsonify({"error": f"No se pudo guardar: {e_save}"}), 500
        print(f"[mant_adjunto] filesystem save fail (Cloudinary OK): {e_save}", flush=True)

    nombre = request.form.get("nombre") or f.filename
    descripcion = request.form.get("descripcion","")
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO mant_contrato_adjuntos
                   (contrato_id,cliente_id,tipo,subtipo_externo,nombre,archivo_nombre,archivo_path,
                    cloudinary_url,cloudinary_public_id,
                    mime_type,tamaño_bytes,descripcion,created_by)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                (ctid, ct["cliente_id"], tipo, subtipo_externo, nombre, fname, fname,
                 cloud_url, cloud_pid,
                 f.content_type or f"application/{ext}", size,
                 descripcion, current_username())
            )
            aid = cur.lastrowid
        conn.commit()
        _mant_log("contrato", ctid, "adjunto_subido", f"{tipo} · {nombre}")
        _mant_log("cliente", ct["cliente_id"], "adjunto_contrato", f"{tipo} · {nombre}")
        # URL del frontend: Cloudinary si está disponible, sino filesystem
        url_final = cloud_url or f"/static/uploads/mantenciones/{fname}"
        return jsonify({
            "ok": True, "id": aid, "nombre": nombre,
            "url": url_final, "tipo": tipo,
            "subtipo_externo": subtipo_externo,
            "persistente": bool(cloud_url),
            "storage": "cloudinary" if cloud_url else "filesystem"
        })
    finally:
        conn.close()


@app.route("/mantenciones/api/adjuntos/<int:aid>/archivo")
@_mant_required
def mant_adjunto_archivo(aid):
    """Sirve el archivo de un adjunto (anexo, externo, foto, etc).

    PROXY 2026-05-26 (Daniel — visor universal en tab Documentos):
      Antes el frontend abría la URL de Cloudinary directa y el browser
      descargaba (Cloudinary fuerza Content-Disposition attachment en
      recursos raw). Ahora proxeamos con headers inline para que el
      visor del modal lo renderice correctamente.

    Seguridad por rol:
      - Cualquier rol con permiso mantenciones puede VER (preview inline).
      - Solo SUPERADMIN puede DESCARGAR (?download=1).
        Bloqueo server-side: roles inferiores reciben 403 si intentan
        descargar, aunque el botón no aparezca en UI.
    """
    from flask import redirect as _redir, Response as _Resp

    adj = mysql_fetchone(
        "SELECT id, contrato_id, cliente_id, tipo, nombre, archivo_nombre, "
        "       mime_type, cloudinary_url, cloudinary_public_id "
        "  FROM mant_contrato_adjuntos WHERE id=%s",
        (aid,)
    )
    if not adj:
        return "Adjunto no encontrado", 404

    as_dl = request.args.get("download") == "1"
    if as_dl and not (g.permissions or {}).get("superadmin"):
        return ("Solo el superadministrador puede descargar archivos "
                "del módulo de mantenciones."), 403

    nombre = adj.get("nombre") or adj.get("archivo_nombre") or f"adjunto_{aid}"
    fname  = adj.get("archivo_nombre") or ""
    ext    = (fname.rsplit(".", 1)[-1].lower() if "." in fname else "").strip()

    # Map de MIME por extensión (para forzar Content-Type correcto cuando
    # Cloudinary devuelve octet-stream).
    mime_map = {
        "pdf":  "application/pdf",
        "jpg":  "image/jpeg", "jpeg": "image/jpeg",
        "png":  "image/png", "gif": "image/gif", "webp": "image/webp",
        "doc":  "application/msword",
        "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "xls":  "application/vnd.ms-excel",
        "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "ppt":  "application/vnd.ms-powerpoint",
        "pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    }

    # ── PRIORIDAD 1: Cloudinary (proxy con headers correctos) ──────────
    cld_url = (adj.get("cloudinary_url") or "").strip()
    if cld_url:
        # GCS: el adjunto vive en NUESTRO bucket (/f/key) → servir directo.
        if cld_url.startswith("/f/") and _gcs_ready():
            try:
                data = _gcs_bucket().blob(cld_url[3:]).download_as_bytes()
                import mimetypes as _mt2
                ctype = (mime_map.get(ext) or adj.get("mime_type")
                         or _mt2.guess_type(cld_url)[0] or "application/octet-stream")
                resp = _Resp(data, status=200)
                resp.headers["Content-Type"] = ctype
                resp.headers["Content-Disposition"] = (
                    f'attachment; filename="{nombre}"' if as_dl else f'inline; filename="{nombre}"')
                resp.headers["Cache-Control"] = "private, max-age=86400"
                resp.headers["X-Frame-Options"] = "SAMEORIGIN"
                resp.headers["Content-Security-Policy"] = "frame-ancestors 'self'"
                return resp
            except Exception as _ge2:
                print(f"[mant_adjunto_archivo] aid={aid} GCS error: {_ge2}", flush=True)
        if as_dl:
            sep = "&" if "?" in cld_url else "?"
            return _redir(f"{cld_url}{sep}fl_attachment=true", code=302)
        # Preview inline: proxy con headers reescritos
        try:
            import requests as _rq
            upstream_headers = {}
            if request.headers.get("Range"):
                upstream_headers["Range"] = request.headers["Range"]
            r_up = _rq.get(cld_url, headers=upstream_headers,
                           stream=True, timeout=30, allow_redirects=True)
            if r_up.status_code not in (200, 206):
                r_up.close()
                raise RuntimeError(f"Cloudinary HTTP {r_up.status_code}")

            ctype = (mime_map.get(ext)
                     or adj.get("mime_type")
                     or r_up.headers.get("Content-Type")
                     or "application/octet-stream")

            def _stream():
                try:
                    for chunk in r_up.iter_content(chunk_size=64 * 1024):
                        if chunk:
                            yield chunk
                finally:
                    r_up.close()

            resp = _Resp(_stream(), status=r_up.status_code)
            resp.headers["Content-Type"] = ctype
            resp.headers["Content-Disposition"] = f'inline; filename="{nombre}"'
            if r_up.headers.get("Content-Length"):
                resp.headers["Content-Length"] = r_up.headers["Content-Length"]
            if r_up.headers.get("Content-Range"):
                resp.headers["Content-Range"] = r_up.headers["Content-Range"]
            resp.headers["Accept-Ranges"] = r_up.headers.get("Accept-Ranges", "bytes")
            resp.headers["X-Frame-Options"] = "SAMEORIGIN"
            resp.headers["Content-Security-Policy"] = "frame-ancestors 'self'"
            resp.headers["Cache-Control"] = "private, max-age=86400, immutable"
            _etag = adj.get("cloudinary_public_id") or f"adj-{aid}"
            resp.headers["ETag"] = f'"{_etag}"'
            if request.headers.get("If-None-Match") == f'"{_etag}"':
                _r304 = _Resp(status=304)
                _r304.headers["ETag"] = f'"{_etag}"'
                _r304.headers["Cache-Control"] = "private, max-age=86400, immutable"
                return _r304
            return resp
        except Exception as _e_p:
            print(f"[mant_adjunto_archivo] aid={aid} proxy FAIL: {_e_p}; "
                  f"intentando disco", flush=True)

    # ── PRIORIDAD 2: Filesystem local (fallback) ────────────────────────
    if not fname:
        return "Adjunto sin archivo en ningún canal", 404
    full_path = os.path.join(MANT_UPLOADS, fname)
    if not os.path.exists(full_path):
        return "Adjunto no encontrado en disco", 404

    from flask import send_from_directory, make_response
    resp = make_response(send_from_directory(
        MANT_UPLOADS, fname,
        as_attachment=as_dl,
        download_name=nombre if as_dl else None,
    ))
    if as_dl:
        resp.headers["Content-Disposition"] = f'attachment; filename="{nombre}"'
    else:
        resp.headers["Content-Disposition"] = f'inline; filename="{nombre}"'
    if mime_map.get(ext):
        resp.headers["Content-Type"] = mime_map[ext]
    resp.headers["X-Frame-Options"] = "SAMEORIGIN"
    resp.headers["Content-Security-Policy"] = "frame-ancestors 'self'"
    resp.headers["Cache-Control"] = "private, max-age=300"
    return resp


@app.route("/mantenciones/api/adjuntos/<int:aid>", methods=["DELETE"])
@_mant_required
def mant_adjunto_del(aid):
    # SEGURIDAD 2026-05-26: solo superadmin puede eliminar adjuntos.
    # Otros roles (ejecutivo, técnico) NO pueden destruir documentos del cliente.
    if not (g.permissions or {}).get("superadmin"):
        return jsonify({
            "error": ("Solo el superadministrador puede eliminar archivos "
                      "del módulo de mantenciones."),
            "error_codigo": "REQUIERE_SUPERADMIN",
        }), 403
    adj = mysql_fetchone(
        "SELECT archivo_nombre, nombre, contrato_id, cliente_id, tipo, "
        "       cloudinary_public_id "
        "  FROM mant_contrato_adjuntos WHERE id=%s",
        (aid,)
    )
    if not adj: return jsonify({"error":"No encontrado"}),404
    # Borrar de Cloudinary si está ahí
    if adj.get("cloudinary_public_id"):
        try:
            _cloud_delete_raw(adj["cloudinary_public_id"])
        except Exception as e:
            print(f"[mant_adjunto_del] cloudinary delete falló aid={aid}: {e}", flush=True)
    # Borrar archivo local si existe
    try:
        fpath = os.path.join(MANT_UPLOADS, adj["archivo_nombre"])
        if os.path.exists(fpath): os.remove(fpath)
    except Exception: pass
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM mant_contrato_adjuntos WHERE id=%s",(aid,))
        conn.commit()
        label = f"{adj.get('tipo') or 'archivo'} · {adj.get('nombre') or aid}"
        if adj.get("contrato_id"):
            _mant_log("contrato", adj["contrato_id"], "adjunto_eliminado", label)
        if adj.get("cliente_id"):
            _mant_log("cliente", adj["cliente_id"], "adjunto_eliminado", label)
        return jsonify({"ok":True})
    finally:
        conn.close()


