@app.route("/mantenciones/api/repuestos/<int:rid>/asignar-ticket", methods=["POST"])
@_mant_required
def mant_repuesto_asignar_ticket(rid):
    """Liga un repuesto (mant_repuestos) a un ticket existente (tk_tickets).
    2026-07-12 (Daniel): "cuando abro un ticket quiero ver el repuesto y
    el contacto del proveedor ahí mismo". body: {ticket_id: int|None}
    ticket_id=None desvincula (permite corregir una asignación errada)."""
    try:
        d = request.get_json(silent=True) or {}
        ticket_id = d.get("ticket_id")
        rep = mysql_fetchone("SELECT id, nombre FROM mant_repuestos WHERE id=%s", (rid,))
        if not rep:
            return jsonify({"ok": False, "error": "Repuesto no encontrado"}), 404
        if ticket_id in (None, "", 0, "0"):
            mysql_execute("UPDATE mant_repuestos SET ticket_id=NULL WHERE id=%s", (rid,))
            _mant_log("repuesto", rid, "desasignar_ticket", rep.get("nombre") or "")
            return jsonify({"ok": True, "ticket_id": None})
        try:
            ticket_id = int(ticket_id)
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "ticket_id inválido"}), 400
        tk = mysql_fetchone("SELECT id, numero_ticket FROM tk_tickets WHERE id=%s", (ticket_id,))
        if not tk:
            return jsonify({"ok": False, "error": "Ticket no encontrado"}), 404
        mysql_execute("UPDATE mant_repuestos SET ticket_id=%s WHERE id=%s", (ticket_id, rid))
        _mant_log("repuesto", rid, "asignar_ticket",
                  f"{rep.get('nombre') or ''} -> ticket {tk.get('numero_ticket') or ticket_id}")
        return jsonify({"ok": True, "ticket_id": ticket_id, "numero_ticket": tk.get("numero_ticket")})
    except Exception as e:
        print(f"[mant_repuesto_asignar_ticket] CRASH rid={rid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "Error interno", "error_codigo": "INTERNAL_CRASH"}), 500


@app.route("/mantenciones/api/repuestos/solicitar", methods=["POST"])
@_mant_required
def mant_repuesto_solicitar():
    """2026-07-13 (Daniel): "toda solicitud de repuesto SIEMPRE crea un
    ticket automáticamente" — no opcional. Crea el ticket (tk_tickets,
    tipo 'spare_parts') y la fila en mant_repuestos ligada a él en una
    sola operación desde el punto de vista del usuario. Body:
      {marca, familia, nombre, cantidad, motivo, maquina_ids: [int,...],
       cliente_id: int|None}
    Si viene UNA sola máquina, además de mant_repuesto_maquinas se setea
    también la columna legacy maquina_id (código viejo que la lee directo
    sigue funcionando). Si falla el 2º paso (repuesto), se revierte el
    ticket recién creado para no dejar un ticket huérfano sin repuesto."""
    try:
        d = request.get_json(silent=True) or {}
        nombre = (d.get("nombre") or "").strip()
        if not nombre:
            return jsonify({"ok": False, "error": "Nombre del repuesto obligatorio"}), 400
        marca = (d.get("marca") or "").strip()[:120]
        familia = (d.get("familia") or "").strip()[:150]
        motivo = (d.get("motivo") or "").strip()
        cliente_id = d.get("cliente_id") or None
        try:
            cantidad = float(d.get("cantidad") or 1)
        except (TypeError, ValueError):
            cantidad = 1.0
        if cantidad <= 0:
            cantidad = 1.0
        maquina_ids = d.get("maquina_ids") or []
        if not isinstance(maquina_ids, list):
            maquina_ids = [maquina_ids]
        maquina_ids = [int(m) for m in maquina_ids if str(m).strip().isdigit()]

        user = current_username() or "sistema"

        # Descripción auto-generada: marca + nombre + motivo (lo que pidió
        # Daniel para que el ticket se entienda sin abrir el repuesto).
        partes_desc = [p for p in (marca, nombre) if p]
        descripcion = " — ".join(partes_desc) if partes_desc else nombre
        if motivo:
            descripcion += f"\n\nMotivo: {motivo}"
        titulo = f"Solicitud de repuesto: {nombre}"[:300]

        from tickets_module import _chile_now_year

        conn = get_mysql()
        ticket_id = None
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "INSERT INTO tk_tickets "
                    "(origen, estado, tipo, prioridad, titulo, descripcion, "
                    " marca, producto, created_by, asignado_a) "
                    "VALUES ('backoffice','open','spare_parts','media',%s,%s,%s,%s,%s,%s)",
                    (titulo, descripcion, marca or None, nombre[:400], user, user),
                )
                ticket_id = cur.lastrowid
                cur.execute(
                    "UPDATE tk_tickets SET numero_ticket = "
                    "CONCAT('TK-', %s, '-', LPAD(id,5,'0')) WHERE id=%s",
                    (_chile_now_year(), ticket_id),
                )
            conn.commit()
        finally:
            conn.close()

        # Paso 2: crear el repuesto ligado al ticket recién creado. Si algo
        # falla acá, revertimos el ticket huérfano (no queda a mitad de camino).
        try:
            fields = {
                "cliente_id": cliente_id,
                "nombre": nombre[:400],
                "marca": marca or None,
                "familia": familia or None,
                "cantidad": cantidad,
                "motivo": motivo or None,
                "tipo": "reposicion",
                "estado": "cotizado",
                "estado_seguimiento": "pending",
                "responsable": user,
                "ticket_id": ticket_id,
                "maquina_id": maquina_ids[0] if len(maquina_ids) == 1 else None,
                "created_by": user,
            }
            cols = [c for c in fields if fields[c] is not None]
            vals = [fields[c] for c in cols]
            conn2 = get_mysql()
            try:
                with conn2.cursor() as cur2:
                    cur2.execute(
                        f"INSERT INTO mant_repuestos ({','.join(cols)}) "
                        f"VALUES ({','.join(['%s']*len(cols))})",
                        tuple(vals)
                    )
                    repuesto_id = cur2.lastrowid
                    for mid in maquina_ids:
                        try:
                            cur2.execute(
                                "INSERT IGNORE INTO mant_repuesto_maquinas (repuesto_id, maquina_id) "
                                "VALUES (%s,%s)", (repuesto_id, mid)
                            )
                        except Exception as e_rm:
                            print(f"[mant_repuesto_solicitar] mant_repuesto_maquinas {mid}: {e_rm}", flush=True)
                conn2.commit()
            finally:
                conn2.close()
        except Exception as e_rep:
            print(f"[mant_repuesto_solicitar] fallo repuesto, revirtiendo ticket {ticket_id}: {e_rep}", flush=True)
            try:
                mysql_execute("DELETE FROM tk_tickets WHERE id=%s", (ticket_id,))
            except Exception as e_rb:
                print(f"[mant_repuesto_solicitar] no se pudo revertir ticket {ticket_id}: {e_rb}", flush=True)
            return jsonify({"ok": False, "error": "No se pudo crear el repuesto"}), 500

        # FIX 2 (2026-07-19): mismo fix de fondo que tk_api_cotizacion_generar_ticket
        # (tickets_module.py) -- NO releer numero_ticket por el pool (mysql_fetchone)
        # despues de un commit hecho en otra conexion (conn de arriba, ya cerrada):
        # el pool por-request usa REPEATABLE READ y puede devolver NULL aunque el
        # UPDATE ya este comprometido. El numero es deterministico -> se arma en
        # Python, mismo formato que el UPDATE de la linea de arriba.
        numero_ticket = f"TK-{_chile_now_year()}-{ticket_id:05d}"
        _mant_log("repuesto", repuesto_id, "solicitar", f"{nombre} -> ticket {numero_ticket}")
        return jsonify({
            "ok": True,
            "repuesto_id": repuesto_id,
            "ticket_id": ticket_id,
            "numero_ticket": numero_ticket,
        })
    except Exception as e:
        print(f"[mant_repuesto_solicitar] CRASH: {e}", flush=True)
        return jsonify({"ok": False, "error": "Error interno", "error_codigo": "INTERNAL_CRASH"}), 500


@app.route("/mantenciones/api/repuestos/desde-erp", methods=["POST"])
@_mant_required
def mant_repuesto_crear_desde_erp():
    """2026-07-12 (Daniel): botón "Buscar en ERP" de la vista central de
    Repuestos (/repuestos) usa el modal compartido tkaOpen({mode:'seleccionar'})
    de templates/tickets/_tka_modal.html. Recibe los items ya elegidos por el
    usuario en el modal (misma forma que entrega su onSeleccionar) y crea UNA
    fila en mant_repuestos por cada uno. Es un camino ADITIVO desde la vista
    central: no toca el CRUD por ficha de cliente (Regla #4.2). cliente_id
    queda NULL a propósito -- esta vista no tiene contexto de cliente."""
    try:
        d = request.get_json(silent=True) or {}
        items = d.get("items") or []
        if not isinstance(items, list) or not items:
            return jsonify({"ok": False, "error": "Sin items seleccionados"}), 400
        creados = []
        for it in items:
            if not isinstance(it, dict):
                continue
            sku = (it.get("sku") or "").strip()[:120]
            nombre = (it.get("nombre") or "").strip()[:400] or sku or "Repuesto sin nombre"
            try:
                cantidad = float(it.get("qty") or 1)
            except (TypeError, ValueError):
                cantidad = 1.0
            if cantidad <= 0:
                # 2026-07-12: sin este clamp, un qty negativo/0 del modal
                # (o de un caller malformado) quedaba tal cual en
                # mant_repuestos.cantidad, ensuciando costeo/inventario.
                # Mismo criterio que Cotizaciones (tickets_module.py).
                cantidad = 1.0
            fields = {
                "cliente_id":  None,
                "sku":         sku,
                "nombre":      nombre,
                "cantidad":    cantidad,
                "estado":      "cotizado",
                "codigo_repuesto": sku or None,
                "created_by":  current_username(),
            }
            cols = list(fields.keys())
            # 2026-07-12: cada item corre su propia conexion/commit (ya era
            # asi) -- pero si un item de la mitad de la lista fallaba (ej.
            # timeout de BD), la excepcion escapaba sin capturarse y
            # abortaba TODO el request con 500, dejando los items ya
            # comprometidos como "fantasma" (el cliente no sabe que se
            # crearon y puede reintentar el batch completo, duplicando).
            # Ahora cada item es independiente: si uno falla, se cuenta
            # como error y se sigue con el resto (hallazgo de la
            # simulacion de trafico 2026-07-12).
            try:
                conn = get_mysql()
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            f"INSERT INTO mant_repuestos ({','.join(cols)}) "
                            f"VALUES ({','.join(['%s']*len(cols))})",
                            tuple(fields[c] for c in cols)
                        )
                        new_id = cur.lastrowid
                    conn.commit()
                finally:
                    conn.close()
                _mant_log("repuesto", new_id, "crear_desde_erp", f"{nombre} (SKU {sku or 's/d'})")
                creados.append(new_id)
            except Exception as e_item:
                print(f"[mant_repuesto_crear_desde_erp] item fallido sku={sku}: {e_item}", flush=True)
                continue
        if not creados:
            return jsonify({"ok": False, "error": "Ningún item pudo crearse"}), 400
        return jsonify({"ok": True, "creados": len(creados), "ids": creados})
    except Exception as e:
        print(f"[mant_repuesto_crear_desde_erp] CRASH: {e}", flush=True)
        return jsonify({"ok": False, "error": "Error interno", "error_codigo": "INTERNAL_CRASH"}), 500


