# ══════════════════════════════════════════════════════════════════════
#  BODEGA DE REPUESTOS — inventario físico real (2026-08-07, Daniel)
#  Distinto de mant_repuestos (seguimiento comercial arriba). Ver
#  comentario de cabecera de _ensure_repuestos_bodega_tables() en el
#  bloque de migraciones para el porqué del diseño.
# ══════════════════════════════════════════════════════════════════════

def _repstock_fmt(r):
    d = dict(r)
    d["cantidad"] = float(d.get("cantidad") or 0)
    d["costo_unitario"] = float(d.get("costo_unitario") or 0)
    d["stock_minimo"] = float(d["stock_minimo"]) if d.get("stock_minimo") is not None else None
    d["bajo_minimo"] = (d["stock_minimo"] is not None and d["cantidad"] <= d["stock_minimo"])
    d["created_at"] = str(d.get("created_at"))[:16] if d.get("created_at") else ""
    d["updated_at"] = str(d.get("updated_at"))[:16] if d.get("updated_at") else ""
    return d


# Sync de marcas de repuesto desde el ERP Random (2026-08-07, Daniel:
# "la marca debe venir del ERP" — campo I.14 del diccionario oficial:
# MAEPR.MRPR = 'Código de Marca de producto'; catálogo en TABMR.NOKOMR).
# OJO: NO reusar _marcas_catalogo() de Mantenciones — esa consulta TABFM
# (SUPER FAMILIA) primero y corta con break, así que devuelve familias
# etiquetadas como marcas. Acá se consulta la marca DE VERDAD.
# Best-effort + cache por proceso: si el ERP no responde, el desplegable
# sigue funcionando con lo ya sincronizado en mant_repuestos_marcas.
_repstock_marcas_sync_ts = 0.0


def _repstock_sync_marcas_erp():
    global _repstock_marcas_sync_ts
    if time.time() - _repstock_marcas_sync_ts < 3600:
        return
    try:
        filas = []
        for _sql in (
            # 1º el catálogo formal de marcas (nombre legible NOKOMR)
            "SELECT DISTINCT TOP 200 RTRIM(NOKOMR) AS m FROM TABMR WHERE NOKOMR IS NOT NULL",
            # 2º fallback: marcas realmente usadas en el maestro de productos
            "SELECT DISTINCT TOP 200 RTRIM(MRPR) AS m FROM MAEPR WHERE MRPR IS NOT NULL",
        ):
            try:
                filas = _random_sql_query(_sql, max_rows=200) or []
                if filas:
                    break
            except Exception:
                continue
        nuevas = 0
        for f in filas:
            nombre = (f.get("m") or "").strip()[:120]
            if not nombre:
                continue
            try:
                mysql_execute(
                    "INSERT IGNORE INTO mant_repuestos_marcas (nombre) VALUES (%s)",
                    (nombre,)
                )
                nuevas += 1
            except Exception:
                pass
        _repstock_marcas_sync_ts = time.time()
        if filas:
            print(f"[repstock_marcas] sync ERP ok: {len(filas)} marcas", flush=True)
    except Exception as e:
        # Nunca romper la página por el ERP — se usa lo local.
        _repstock_marcas_sync_ts = time.time() - 3000  # reintenta en ~10 min
        print(f"[repstock_marcas] sync ERP falló: {e}", flush=True)


def _repstock_sku_prefijo(marca_nombre):
    """DRAX de 'Drax', FREE de 'Freemotion', LIFE de 'Life Fitness'...
    Solo A-Z0-9, 4 caracteres, 'GEN' si no hay marca."""
    limpio = "".join(c for c in (marca_nombre or "").upper() if c.isalnum())
    return (limpio[:4] or "GEN")


def _repstock_next_sku(marca_nombre, conn):
    """SKU automático REP-<MARCA>-0001, numerado por marca. Atómico por el
    row-lock de escritura del ON DUPLICATE KEY UPDATE (mismo patrón que
    _next_ot_number_atomic — jamás SELECT MAX(), que bajo REPEATABLE READ
    duplica números en concurrencia; bug real documentado en memoria).
    Usa la MISMA conexión del INSERT del repuesto: si el caller hace
    rollback, el número también se revierte."""
    pref = _repstock_sku_prefijo(marca_nombre)
    with conn.cursor() as cur:
        cur.execute(
            "INSERT INTO mant_repstock_secuencia (prefijo, n) VALUES (%s, LAST_INSERT_ID(1)) "
            "ON DUPLICATE KEY UPDATE n = LAST_INSERT_ID(n + 1)",
            (pref,)
        )
        cur.execute("SELECT LAST_INSERT_ID() AS n")
        row = cur.fetchone()
        n = int(row["n"]) if row and row.get("n") else 1
    return f"REP-{pref}-{n:04d}"


def _repstock_contexto_bodega():
    """Todo lo que la pestaña "Bodega" necesita para pintarse. Se llama
    tanto desde /repuestos (donde vive de verdad, Daniel 2026-08-07) como
    desde /repuestos/bodega (URL directa, se conserva)."""
    _repstock_sync_marcas_erp()  # marcas desde MAEPR.MRPR, best-effort + cache 1h
    q = (request.args.get("bq") or "").strip()
    marca_id = request.args.get("marca_id") or ""
    ubicacion_id = request.args.get("ubicacion_id") or ""
    solo_bajo_minimo = request.args.get("bajo_minimo") == "1"
    # 2026-08-08 (Daniel: "quiero filtrar por lo que no tiene costo... es
    # para atacar el caso de qué es lo que no está asociado, qué máquina no
    # tiene modelo"): dos filtros nuevos para el levantamiento de bodega,
    # mismo patrón que bajo_minimo (querystring persistente, WHERE dinámico).
    solo_sin_costo = request.args.get("sin_costo") == "1"
    solo_sin_modelo = request.args.get("sin_modelo") == "1"
    try:
        page = max(1, int(request.args.get("bpage") or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        page_size = int(request.args.get("bsize") or 100)
    except (TypeError, ValueError):
        page_size = 100
    if page_size not in (100, 200, 500):
        page_size = 100

    where = ["r.activo=1"]
    params = []
    if q:
        where.append("(r.sku LIKE %s OR r.descripcion LIKE %s OR r.codigo_fabricante LIKE %s)")
        like = f"%{q}%"
        params += [like, like, like]
    if marca_id.isdigit():
        where.append("r.marca_id=%s"); params.append(int(marca_id))
    if ubicacion_id.isdigit():
        where.append("r.ubicacion_id=%s"); params.append(int(ubicacion_id))
    if solo_bajo_minimo:
        where.append("r.stock_minimo IS NOT NULL AND r.cantidad <= r.stock_minimo")

    # Conteos "cuántos hay bajo este filtro" para los badges de Sin costo /
    # Sin modelo asociado — se calculan sobre el WHERE de arriba (búsqueda +
    # marca + ubicación + bajo_minimo) SIN el propio filtro que describen,
    # para que el número sea "cuántos aparecerían si lo marco ahora" y no
    # se quede pegado en 0 cuando el filtro ya está activo.
    where_base_sql = " AND ".join(where)
    bod_count_sin_costo = (mysql_fetchone(
        f"SELECT COUNT(*) AS n FROM mant_repuestos_stock r WHERE {where_base_sql} "
        f"AND (r.costo_unitario IS NULL OR r.costo_unitario = 0)", tuple(params)
    ) or {}).get("n", 0)
    bod_count_sin_modelo = (mysql_fetchone(
        f"SELECT COUNT(*) AS n FROM mant_repuestos_stock r WHERE {where_base_sql} "
        f"AND NOT EXISTS (SELECT 1 FROM mant_repuestos_stock_modelos rm WHERE rm.repuesto_id = r.id)",
        tuple(params)
    ) or {}).get("n", 0)

    if solo_sin_costo:
        where.append("(r.costo_unitario IS NULL OR r.costo_unitario = 0)")
    if solo_sin_modelo:
        where.append("NOT EXISTS (SELECT 1 FROM mant_repuestos_stock_modelos rm WHERE rm.repuesto_id = r.id)")
    where_sql = " AND ".join(where)

    total = (mysql_fetchone(
        f"SELECT COUNT(*) AS n FROM mant_repuestos_stock r WHERE {where_sql}", tuple(params)
    ) or {}).get("n", 0)
    total_pages = max(1, -(-total // page_size))
    page = min(page, total_pages)
    offset = (page - 1) * page_size

    rows = mysql_fetchall(
        f"SELECT r.*, m.nombre AS marca_nombre, "
        f"       u.codigo AS ubicacion_codigo, u.nombre AS ubicacion_nombre, "
        f"       c.razon_social AS cliente_nombre, t.numero_ticket AS ticket_numero, "
        f"       pv.nombre AS proveedor_nombre, pv.contacto_nombre AS proveedor_contacto, "
        f"       pv.telefono AS proveedor_telefono, pv.email AS proveedor_email "
        f"  FROM mant_repuestos_stock r "
        f"  LEFT JOIN mant_repuestos_marcas m ON m.id = r.marca_id "
        f"  LEFT JOIN mant_repuestos_ubicaciones u ON u.id = r.ubicacion_id "
        f"  LEFT JOIN mant_clientes c ON c.id = r.cliente_id "
        f"  LEFT JOIN tk_tickets t ON t.id = r.ticket_id "
        f"  LEFT JOIN mant_proveedores_repuesto pv ON pv.id = r.proveedor_id "
        f" WHERE {where_sql} ORDER BY r.sku ASC LIMIT %s OFFSET %s",
        tuple(params) + (page_size, offset)
    ) or []
    bod_repuestos = [_repstock_fmt(r) for r in rows]

    modelos_por_repuesto = {}
    fotos_por_repuesto = {}
    ids = [r["id"] for r in bod_repuestos]
    if ids:
        ph = ",".join(["%s"] * len(ids))
        mrows = mysql_fetchall(
            f"SELECT rm.repuesto_id, p.id AS producto_id, p.sku AS producto_sku, "
            f"       p.nombre AS producto_nombre, p.clase_producto "
            f"  FROM mant_repuestos_stock_modelos rm "
            f"  JOIN cat_productos p ON p.id = rm.producto_id "
            f" WHERE rm.repuesto_id IN ({ph}) ORDER BY p.nombre",
            tuple(ids)
        ) or []
        for m in mrows:
            modelos_por_repuesto.setdefault(m["repuesto_id"], []).append(dict(m))
        frows = mysql_fetchall(
            f"SELECT id, repuesto_id, gcs_key, orden FROM mant_repuestos_stock_fotos "
            f" WHERE repuesto_id IN ({ph}) ORDER BY repuesto_id, orden",
            tuple(ids)
        ) or []
        for f in frows:
            fotos_por_repuesto.setdefault(f["repuesto_id"], []).append(
                {"id": f["id"], "url": "/f/" + f["gcs_key"], "orden": f["orden"]}
            )

    return {
        "bod_repuestos": bod_repuestos,
        "modelos_por_repuesto": modelos_por_repuesto,
        "fotos_por_repuesto": fotos_por_repuesto,
        "marcas": mysql_fetchall(
            "SELECT id, nombre FROM mant_repuestos_marcas WHERE activo=1 ORDER BY nombre"
        ) or [],
        "ubicaciones": mysql_fetchall(
            "SELECT id, codigo, nombre FROM mant_repuestos_ubicaciones WHERE activo=1 ORDER BY codigo"
        ) or [],
        "bod_q": q, "bod_marca_id": marca_id, "bod_ubicacion_id": ubicacion_id,
        "bod_bajo_minimo": solo_bajo_minimo,
        "bod_sin_costo": solo_sin_costo, "bod_sin_modelo": solo_sin_modelo,
        "bod_count_sin_costo": bod_count_sin_costo, "bod_count_sin_modelo": bod_count_sin_modelo,
        "bod_page": page, "bod_page_size": page_size,
        "bod_total": total, "bod_total_pages": total_pages,
    }


