def _repstock_dim_float(v):
    """Convierte una medida física (largo/ancho/alto/peso_kg) a float o
    None -- NUNCA lanza ni tumba la request completa (2026-08-25, a
    diferencia de cantidad/costo_unitario/stock_minimo que sí son
    obligatorios). Vacío, no-numérico o negativo -> se guarda NULL, no
    error 400: un repuesto sin estos datos sigue siendo válido."""
    if v in (None, "", "null"):
        return None
    try:
        v = float(v)
    except (TypeError, ValueError):
        return None
    return v if v >= 0 else None


def _repstock_bultos_int(v):
    """Igual que _repstock_dim_float pero para bultos (entero, mínimo 1) --
    2026-08-25 (2, Daniel: "además de pedir las medidas, el peso y el
    bulto"). Vacío/invalido/menor a 1 -> None (la etiqueta ya asume 1
    bulto por defecto cuando el dato no está cargado)."""
    if v in (None, "", "null"):
        return None
    try:
        v = int(float(v))
    except (TypeError, ValueError):
        return None
    return v if v >= 1 else None


@app.route("/mantenciones/api/repuestos-stock", methods=["POST"])
@_mant_required
def repstock_crear():
    """Alta de repuesto. El SKU NO se tipea a mano: o se genera automático
    (REP-<MARCA>-0001, bloqueado en la UI — Daniel 2026-08-07: "bloqueamos
    el SKU y agrégame un SKU genérico conectado al repuesto y a la marca"),
    o se sustituye por el SKU real de la bodega 18 del ERP Random cuando el
    repuesto se creó desde un resultado del sondeo (Daniel 2026-08-08:
    "sustituir el SKU automático... para que sea el mismo código que en el
    ERP, no hacer doble trabajo"). En ambos casos el SKU llega por una
    ACCIÓN del sistema (auto-generar o elegir un resultado verificado),
    nunca por texto libre del usuario -- no contradice el bloqueo del 07.
    Obligatorios: descripción, cantidad y stock mínimo. Costo opcional."""
    d = request.get_json(silent=True) or {}
    descripcion = (d.get("descripcion") or "").strip()[:400]
    if not descripcion:
        return jsonify({"ok": False, "error": "La descripción es obligatoria"}), 400
    if d.get("cantidad") in (None, "", "null"):
        return jsonify({"ok": False, "error": "La cantidad es obligatoria"}), 400
    if d.get("stock_minimo") in (None, "", "null"):
        return jsonify({"ok": False, "error": "El stock mínimo es obligatorio"}), 400
    try:
        cantidad = float(d.get("cantidad"))
        stock_minimo = float(d.get("stock_minimo"))
        costo_unitario = float(d.get("costo_unitario")) if d.get("costo_unitario") not in (None, "", "null") else 0
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "Cantidad/stock mínimo/costo deben ser números"}), 400
    if cantidad < 0 or stock_minimo < 0:
        return jsonify({"ok": False, "error": "Cantidad y stock mínimo no pueden ser negativos"}), 400
    marca_id = d.get("marca_id") or None
    marca_nombre = None
    marca_proveedor_id = None
    if marca_id:
        _m = mysql_fetchone(
            "SELECT nombre, proveedor_id FROM mant_repuestos_marcas WHERE id=%s", (marca_id,))
        marca_nombre = (_m or {}).get("nombre")
        marca_proveedor_id = (_m or {}).get("proveedor_id")
    ubicacion_id = d.get("ubicacion_id") or None
    cliente_id = d.get("cliente_id") or None
    ticket_id = d.get("ticket_id") or None
    # Proveedor: si el caller no mandó uno explícito, se hereda el de la
    # marca (Daniel 2026-08-08: "cuando yo llame a la marca, ya ahí
    # tenemos que asociarlo"). Sigue siendo editable por repuesto -- el
    # proveedor NO queda "atado" a la marca, solo se sugiere por defecto.
    proveedor_id = d.get("proveedor_id") or marca_proveedor_id or None
    # SKU real del ERP (bodega 18), si el repuesto se creó desde un
    # resultado del sondeo -- reemplaza el auto-generado. Viene del propio
    # sondeo (repstock_sondeo_erp), no de texto libre: se valida igual con
    # el mismo whitelist de caracteres que usan los SKU internos.
    sku_erp = (d.get("sku_erp") or "").strip()[:100]
    if sku_erp and not re.match(r'^[A-Za-z0-9._\-\/]+$', sku_erp):
        sku_erp = ""
    conn = get_mysql()
    try:
        if sku_erp:
            existente = mysql_fetchone("SELECT id FROM mant_repuestos_stock WHERE sku=%s", (sku_erp,))
            if existente:
                return jsonify({"ok": False, "error": f"Ya existe un repuesto con el SKU {sku_erp} (id {existente['id']})"}), 409
            sku = sku_erp
        else:
            # SKU atómico en la MISMA transacción del INSERT: si algo falla,
            # el rollback también devuelve el correlativo (sin huecos).
            sku = _repstock_next_sku(marca_nombre, conn)
        fields = {
            "sku": sku, "descripcion": descripcion, "cantidad": cantidad,
            "ubicacion_id": ubicacion_id, "marca_id": marca_id,
            "proveedor_id": proveedor_id,
            "costo_unitario": costo_unitario,
            "codigo_fabricante": (d.get("codigo_fabricante") or "").strip()[:120] or None,
            "stock_minimo": stock_minimo,
            "cliente_id": cliente_id, "ticket_id": ticket_id,
            "notas": (d.get("notas") or "").strip() or None,
            "largo": _repstock_dim_float(d.get("largo")),
            "ancho": _repstock_dim_float(d.get("ancho")),
            "alto": _repstock_dim_float(d.get("alto")),
            "peso_kg": _repstock_dim_float(d.get("peso_kg")),
            "bultos": _repstock_bultos_int(d.get("bultos")),
            "created_by": current_username(),
        }
        cols = list(fields.keys())
        with conn.cursor() as cur:
            cur.execute(
                f"INSERT INTO mant_repuestos_stock ({','.join(cols)}) "
                f"VALUES ({','.join(['%s'] * len(cols))})",
                tuple(fields[c] for c in cols)
            )
            new_id = cur.lastrowid
        conn.commit()
        _mant_log("repuesto_stock", new_id, "crear", f"{sku} — {descripcion}")
        return jsonify({"ok": True, "id": new_id, "sku": sku, "proveedor_id": proveedor_id})
    except Exception as e:
        conn.rollback()
        print(f"[repstock_crear] ERROR: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo crear el repuesto."}), 400
    finally:
        conn.close()


@app.route("/mantenciones/api/repuestos-stock/<int:rid>", methods=["PUT"])
@_mant_required
def repstock_editar(rid):
    # El SKU es autogenerado e inmutable (2026-08-07): si llega en el body
    # se ignora en silencio — cambiarlo rompería etiquetas ya impresas.
    d = request.get_json(silent=True) or {}
    d.pop("sku", None)
    if "descripcion" in d:
        d["descripcion"] = (d.get("descripcion") or "").strip()[:400]
        if not d["descripcion"]:
            return jsonify({"ok": False, "error": "La descripción no puede quedar vacía"}), 400
    allowed = ["descripcion", "cantidad", "ubicacion_id", "marca_id", "proveedor_id",
               "costo_unitario", "codigo_fabricante", "stock_minimo", "notas",
               "cliente_id", "ticket_id", "largo", "ancho", "alto", "peso_kg", "bultos"]
    sets, vals = [], []
    for f in allowed:
        if f in d:
            v = d[f]
            if f in ("cantidad", "costo_unitario", "stock_minimo"):
                try:
                    v = float(v) if v not in (None, "", "null") else None
                except (TypeError, ValueError):
                    return jsonify({"ok": False, "error": f"'{f}' debe ser numérico"}), 400
            elif f in ("largo", "ancho", "alto", "peso_kg"):
                # Medidas físicas opcionales (2026-08-25): a diferencia de
                # cantidad/costo/stock_minimo de arriba, un valor inválido
                # o vacío NUNCA tumba el guardado completo -- se persiste
                # NULL y sigue.
                v = _repstock_dim_float(v)
            elif f == "bultos":
                v = _repstock_bultos_int(v)
            elif v in ("", "null"):
                v = None
            sets.append(f"{f}=%s"); vals.append(v)
    if not sets:
        return jsonify({"ok": False, "error": "Sin campos para actualizar"}), 400
    sets.append("updated_by=%s"); vals.append(current_username())
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE mant_repuestos_stock SET {','.join(sets)} WHERE id=%s",
                vals + [rid]
            )
        conn.commit()
        _mant_log("repuesto_stock", rid, "editar")
        return jsonify({"ok": True})
    except Exception as e:
        conn.rollback()
        print(f"[repstock_editar] rid={rid} ERROR: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar el repuesto."}), 400
    finally:
        conn.close()


