@app.route("/repuestos/bodega/etiquetas")
@_mant_required
def repstock_etiquetas():
    """Imprime etiquetas de repuestos (SKU + descripción + ubicación +
    barcode) — motor propio del módulo de repuestos, NO el de Catálogo/
    Etiquetas (Daniel, 2026-08-07: "solo del módulo de repuestos, el
    módulo de catálogo es otra cosa"). Reusa los mismos 2 formatos físicos
    y el mismo pipeline Playwright que ya existe (_label_format/_pw_pdf)."""
    ids_raw = (request.args.get("ids") or "").strip()
    ids = [int(x) for x in ids_raw.split(",") if x.strip().isdigit()]
    if not ids:
        return jsonify({"ok": False, "error": "Sin repuestos seleccionados"}), 400
    fmt = request.args.get("fmt") or "100x150"
    ph = ",".join(["%s"] * len(ids))
    rows = mysql_fetchall(
        f"SELECT r.sku, r.descripcion, r.codigo_fabricante, "
        f"       r.largo, r.ancho, r.alto, r.peso_kg, r.bultos, "
        f"       u.codigo AS ubicacion_codigo, m.nombre AS marca_nombre "
        f"  FROM mant_repuestos_stock r "
        f"  LEFT JOIN mant_repuestos_ubicaciones u ON u.id = r.ubicacion_id "
        f"  LEFT JOIN mant_repuestos_marcas m ON m.id = r.marca_id "
        f" WHERE r.id IN ({ph}) ORDER BY r.sku",
        tuple(ids)
    ) or []
    if not rows:
        return jsonify({"ok": False, "error": "Repuestos no encontrados"}), 404
    label_format = _label_format(fmt)
    fecha = _now_chile_str("%d-%m-%Y %H:%M")
    html = render_template(
        "repuesto_label_standalone.html",
        repuestos=[dict(r) for r in rows], fecha=fecha,
        fmt=label_format["key"], label_format=label_format,
        logo_url=_logo_data_url(),
    )
    pdf_bytes = _pw_pdf(
        html, width=label_format["w"], height=label_format["h"],
        wait_fn=(
            "() => {"
            "  const codes = Array.from(document.querySelectorAll('.barcode'));"
            "  return codes.length > 0 && codes.every(c => c.dataset.rendered === '1');"
            "}"
        ),
    )
    resp = make_response(pdf_bytes)
    resp.headers["Content-Type"] = "application/pdf"
    # download=1 (2026-08-25, botón "Descargar PDF" de la vista previa,
    # mismo patrón que labels_pdf_preview del módulo de Catálogo) -> fuerza
    # attachment; sin el parámetro sigue abriendo inline como siempre.
    disposition = "attachment" if request.args.get("download") == "1" else "inline"
    resp.headers["Content-Disposition"] = f"{disposition}; filename=etiquetas-repuestos.pdf"
    return resp


@app.route("/repuestos/bodega/imprimir")
@_mant_required
def repuestos_print_labels():
    """Vista previa de impresión de etiquetas de repuestos -- mismo patrón
    UX que print_labels.html (Etiquetas/Catálogo): toolbar + vista previa
    HTML en vivo + panel de tamaño/acciones (2026-08-25, Daniel: "quiero...
    que actue como el modulo de etiquetas"). A diferencia de aquel, acá se
    imprime una LISTA de repuestos distintos por id (no los bultos de UN
    producto), así que no hay concepto de "copias por bulto" -- cada
    repuesto imprime 1 etiqueta. El PDF real lo sigue generando
    repstock_etiquetas() (mismo pipeline Playwright de siempre); esta vista
    solo arma la previsualización y apunta los botones a esa misma ruta."""
    ids_raw = (request.args.get("ids") or "").strip()
    ids = [int(x) for x in ids_raw.split(",") if x.strip().isdigit()]
    if not ids:
        flash("Selecciona al menos un repuesto para imprimir etiquetas.", "warning")
        return redirect(url_for("repuestos_bodega_list"))
    fmt = request.args.get("fmt") or "100x150"
    label_format = _label_format(fmt)
    ph = ",".join(["%s"] * len(ids))
    rows = mysql_fetchall(
        f"SELECT r.id, r.sku, r.descripcion, r.codigo_fabricante, "
        f"       r.largo, r.ancho, r.alto, r.peso_kg, r.bultos, "
        f"       u.codigo AS ubicacion_codigo, m.nombre AS marca_nombre "
        f"  FROM mant_repuestos_stock r "
        f"  LEFT JOIN mant_repuestos_ubicaciones u ON u.id = r.ubicacion_id "
        f"  LEFT JOIN mant_repuestos_marcas m ON m.id = r.marca_id "
        f" WHERE r.id IN ({ph}) ORDER BY r.sku",
        tuple(ids)
    ) or []
    if not rows:
        flash("Repuestos no encontrados.", "danger")
        return redirect(url_for("repuestos_bodega_list"))
    fecha = _now_chile_str("%d-%m-%Y %H:%M")
    rows = [dict(r) for r in rows]
    ids_csv = ",".join(str(r["id"]) for r in rows)
    response = make_response(render_template(
        "repuesto_print_labels.html",
        repuestos=rows, fecha=fecha,
        fmt=label_format["key"], label_format=label_format,
        logo_url=_logo_data_url(), ids_csv=ids_csv,
    ))
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    return response


@app.route("/mantenciones/api/repuestos-stock/exportar-excel")
@_mant_required
def repstock_exportar_excel():
    """Export Excel "bien coqueto" de la Bodega de Repuestos (Daniel
    2026-08-08: "un Excel bien coqueto donde se bajen hasta las imágenes
    de cada producto, y cada detalle para poder hacer búsqueda o entregar
    para que lo modifique. O lo integren a Random" — el Excel se comparte
    MANUALMENTE con Random si hace falta; ILUS jamás escribe al ERP, esto
    es 100% lectura de mant_repuestos_stock, tabla propia de ILUS).

    Respeta EXACTAMENTE el mismo WHERE dinámico que _repstock_contexto_bodega
    (bq/marca_id/ubicacion_id/bajo_minimo/sin_costo/sin_modelo) — si Daniel
    filtró "sin modelo asociado" y descarga, el Excel trae solo esos.

    Mismo lenguaje visual que mant_clientes_reporte_xlsx (header negro
    #0A0A0A + texto blanco, bordes grises finos, zebra, freeze_panes,
    autofilter) — Regla #2 de CLAUDE.md. Una fila por repuesto con foto
    embebida (miniatura cacheada de 160px, NUNCA el original de 1600px) en
    la primera columna; una foto rota jamás debe tumbar la exportación
    completa de los demás repuestos (try/except individual)."""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
        from openpyxl.drawing.image import Image as XLImage
    except Exception:
        flash("Falta la librería openpyxl para generar el Excel.", "danger")
        return redirect(request.referrer or url_for("repuestos_bodega_list"))

    # ── Mismos filtros y MISMO WHERE dinámico que _repstock_contexto_bodega
    # (parametrizado con %s, nunca f-string con el valor del usuario) ──
    q = (request.args.get("bq") or "").strip()
    marca_id = request.args.get("marca_id") or ""
    ubicacion_id = request.args.get("ubicacion_id") or ""
    solo_bajo_minimo = request.args.get("bajo_minimo") == "1"
    solo_sin_costo = request.args.get("sin_costo") == "1"
    solo_sin_modelo = request.args.get("sin_modelo") == "1"

    where = ["r.activo=1"]
    params = []
    if q:
        where.append("(r.sku LIKE %s OR r.descripcion LIKE %s OR r.codigo_fabricante LIKE %s)")
        like = f"%{q}%"
        params += [like, like, like]
    if marca_id.isdigit():
        where.append("r.marca_id=%s"); params.append(int(marca_id))
    if ubicacion_id.isdigit():
        where.append("r.ubicacion_id=%s"); params.append(int(ubicacion_id))
    if solo_bajo_minimo:
        where.append("r.stock_minimo IS NOT NULL AND r.cantidad <= r.stock_minimo")
    if solo_sin_costo:
        where.append("(r.costo_unitario IS NULL OR r.costo_unitario = 0)")
    if solo_sin_modelo:
        where.append("NOT EXISTS (SELECT 1 FROM mant_repuestos_stock_modelos rm WHERE rm.repuesto_id = r.id)")
    where_sql = " AND ".join(where)

    rows = mysql_fetchall(
        f"SELECT r.*, m.nombre AS marca_nombre, "
        f"       u.codigo AS ubicacion_codigo, u.nombre AS ubicacion_nombre, "
        f"       c.razon_social AS cliente_nombre, t.numero_ticket AS ticket_numero, "
        f"       pv.nombre AS proveedor_nombre "
        f"  FROM mant_repuestos_stock r "
        f"  LEFT JOIN mant_repuestos_marcas m ON m.id = r.marca_id "
        f"  LEFT JOIN mant_repuestos_ubicaciones u ON u.id = r.ubicacion_id "
        f"  LEFT JOIN mant_clientes c ON c.id = r.cliente_id "
        f"  LEFT JOIN tk_tickets t ON t.id = r.ticket_id "
        f"  LEFT JOIN mant_proveedores_repuesto pv ON pv.id = r.proveedor_id "
        f" WHERE {where_sql} ORDER BY r.sku ASC",
        tuple(params)
    ) or []
    rows = [dict(r) for r in rows]

    ids = [r["id"] for r in rows]
    modelos_por_repuesto = {}
    fotos_por_repuesto = {}
    if ids:
        ph = ",".join(["%s"] * len(ids))
        mrows = mysql_fetchall(
            f"SELECT rm.repuesto_id, p.nombre AS producto_nombre "
            f"  FROM mant_repuestos_stock_modelos rm "
            f"  JOIN cat_productos p ON p.id = rm.producto_id "
            f" WHERE rm.repuesto_id IN ({ph}) ORDER BY p.nombre",
            tuple(ids)
        ) or []
        for m in mrows:
            modelos_por_repuesto.setdefault(m["repuesto_id"], []).append(m["producto_nombre"])
        # Ordenadas por 'orden' -> la [0] de cada repuesto es la foto principal
        # (mismo criterio que usa la tabla en pantalla, rfotos[0]).
        frows = mysql_fetchall(
            f"SELECT repuesto_id, gcs_key FROM mant_repuestos_stock_fotos "
            f" WHERE repuesto_id IN ({ph}) ORDER BY repuesto_id, orden",
            tuple(ids)
        ) or []
        for f in frows:
            fotos_por_repuesto.setdefault(f["repuesto_id"], []).append(f["gcs_key"])

    # ── Estilo: MISMO lenguaje visual que mant_clientes_reporte_xlsx ──
    BLACK, LGRAY, REDL = "0A0A0A", "F5F5F5", "FEE2E2"
    thin = Side(style="thin", color="E5E7EB")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    def _hdr(cell, val):
        cell.value = val
        cell.font = Font(bold=True, color="FFFFFF", size=9)
        cell.fill = PatternFill("solid", fgColor=BLACK)
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = border

    try:
        from zoneinfo import ZoneInfo
        _now = datetime.now(ZoneInfo("America/Santiago"))
    except Exception:
        _now = datetime.now()
    fecha_gen = _now.strftime("%d/%m/%Y %H:%M")

    filtros_desc = []
    if q:
        filtros_desc.append(f'búsqueda "{q}"')
    if marca_id.isdigit():
        _m = mysql_fetchone("SELECT nombre FROM mant_repuestos_marcas WHERE id=%s", (int(marca_id),))
        if _m:
            filtros_desc.append(f"marca {_m['nombre']}")
    if ubicacion_id.isdigit():
        _u = mysql_fetchone("SELECT codigo FROM mant_repuestos_ubicaciones WHERE id=%s", (int(ubicacion_id),))
        if _u:
            filtros_desc.append(f"ubicación {_u['codigo']}")
    if solo_bajo_minimo:
        filtros_desc.append("bajo stock mínimo")
    if solo_sin_costo:
        filtros_desc.append("sin costo")
    if solo_sin_modelo:
        filtros_desc.append("sin modelo asociado")
    alcance_txt = (" · ".join(filtros_desc)) if filtros_desc else "todos los repuestos activos"

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Repuestos"

    # 2026-08-08 (Daniel: "un recuadro por la foto uno, la dos y la tres, y
    # si no las tiene vacía nomás -- viene la columna vacía"): 3 columnas de
    # foto en vez de 1 sola (mant_repuestos_stock_fotos permite hasta 3 por
    # repuesto). Slot sin foto = celda en blanco, SIN texto "Sin foto" --
    # corrección explícita de Daniel sobre el diseño anterior.
    FOTO_COLS = 3
    headers = (
        ["Foto 1", "Foto 2", "Foto 3"] +
        ["SKU", "Descripción", "Código fabricante", "Cantidad (un.)", "Stock mínimo (un.)",
         "Ubicación", "Marca", "Costo unitario", "Proveedor", "Modelos compatibles",
         "Cliente asociado", "Ticket asociado", "Notas", "Creado por", "Fecha creación"]
    )
    NCOLS = len(headers)
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=NCOLS)
    tcell = ws.cell(row=1, column=1,
                    value=f"ILUS · Bodega de Repuestos  —  {alcance_txt}  —  {len(rows)} repuestos  —  generado {fecha_gen}")
    tcell.font = Font(bold=True, size=13, color="FFFFFF")
    tcell.fill = PatternFill("solid", fgColor=BLACK)
    tcell.alignment = Alignment(horizontal="left", vertical="center")
    ws.row_dimensions[1].height = 26

    for ci, h in enumerate(headers, 1):
        _hdr(ws.cell(row=2, column=ci), h)
    ws.row_dimensions[2].height = 30

    bucket = _gcs_bucket()

    def _foto_bytes(gcs_key):
        """Bytes de una miniatura de 160px para embeber en el Excel — mismo
        cache que /f/<key>?w=160 (ver _thumb_key/serve_archivo): si no está
        generada, la genera y la cachea igual que esa ruta. NUNCA levanta
        excepción hacia afuera: una foto rota no debe tumbar el resto."""
        if not bucket or not gcs_key:
            return None
        tkey = _thumb_key(gcs_key, 160)
        try:
            return bucket.blob(tkey).download_as_bytes()
        except Exception:
            pass  # miniatura aún no cacheada -> generar abajo
        try:
            orig = bucket.blob(gcs_key).download_as_bytes()
        except Exception as e_dl:
            print(f"[repstock_exportar_excel] no se pudo bajar original {gcs_key}: {e_dl}", flush=True)
            return None
        try:
            tdata, _ct = _img_resize_bytes(orig, max_dim=160, quality=78)
        except Exception as e_rs:
            print(f"[repstock_exportar_excel] no se pudo redimensionar {gcs_key}: {e_rs}", flush=True)
            return None
        try:
            bucket.blob(tkey).upload_from_string(tdata, content_type="image/jpeg")
        except Exception as e_up:
            print(f"[repstock_exportar_excel] no se pudo cachear miniatura {tkey}: {e_up}", flush=True)
        return tdata

    def _foto_celda_vacia(r_idx, col, bg):
        # 2026-08-08 (Daniel, corrigiendo el diseño anterior: "si no las
        # tiene vacía nomás, viene la columna vacía"): SIN texto "Sin foto"
        # -- solo borde+fondo parejo con el resto de la fila.
        c = ws.cell(row=r_idx, column=col)
        c.border = border
        c.fill = PatternFill("solid", fgColor=bg)

    r_idx = 3
    for rep in rows:
        # 2026-08-08 (Daniel: "esa cantidad... tiene que ser un uno nomás,
        # es unidades" -- mismo pedido que en la tabla en pantalla, pero acá
        # el valor debe seguir siendo NUMÉRICO (no texto "3 un.") para que
        # sirva de verdad "para poder hacer búsqueda" en Excel -- sumar,
        # filtrar, ordenar. La unidad va en el ENCABEZADO ("Cantidad (un.)"),
        # no pegada al dato.
        cantidad = round(float(rep.get("cantidad") or 0))
        stock_minimo = round(float(rep["stock_minimo"])) if rep.get("stock_minimo") is not None else None
        bajo_minimo = stock_minimo is not None and cantidad <= stock_minimo
        costo_unitario = float(rep.get("costo_unitario") or 0)
        ubic = rep.get("ubicacion_codigo") or ""
        if ubic and rep.get("ubicacion_nombre"):
            ubic += " — " + rep["ubicacion_nombre"]
        modelos_txt = ", ".join(modelos_por_repuesto.get(rep["id"], []))
        creado_fmt = chile_fmt_filter(rep.get("created_at")) if rep.get("created_at") else ""

        vals = [
            None, None, None,  # Foto 1/2/3 -> imagen embebida o celda vacía, no texto
            rep.get("sku") or "",
            rep.get("descripcion") or "",
            rep.get("codigo_fabricante") or "",
            cantidad,
            stock_minimo,
            ubic,
            rep.get("marca_nombre") or "",
            costo_unitario,
            rep.get("proveedor_nombre") or "",
            modelos_txt,
            rep.get("cliente_nombre") or "",
            rep.get("ticket_numero") or "",
            rep.get("notas") or "",
            rep.get("created_by") or "",
            creado_fmt,
        ]
        bg = LGRAY if r_idx % 2 == 0 else "FFFFFF"
        # Columnas Foto 1/2/3: border+fill parejo con el resto de la fila
        # aunque el valor (imagen o celda vacía) se resuelva aparte, abajo.
        for fc in range(1, FOTO_COLS + 1):
            fcell = ws.cell(row=r_idx, column=fc)
            fcell.border = border
            fcell.fill = PatternFill("solid", fgColor=bg)
        for ci, val in enumerate(vals, 1):
            if ci <= FOTO_COLS:
                continue  # columnas Foto se resuelven aparte (imagen o celda vacía)
            cell = ws.cell(row=r_idx, column=ci, value=val)
            cell.font = Font(size=9)
            cell.alignment = Alignment(
                horizontal="center" if ci in (7, 8, 11) else "left",
                vertical="center", wrap_text=(ci in (5, 13, 16)))
            cell.border = border
            fill = REDL if (ci == 7 and bajo_minimo) else bg
            cell.fill = PatternFill("solid", fgColor=fill)
            if ci in (7, 8) and val is not None:
                cell.number_format = "0"
            if ci == 11 and val:
                cell.number_format = '"$"#,##0'
        ws.row_dimensions[r_idx].height = 50

        # ── Fotos embebidas (hasta 3) — try/except individual por foto: UNA
        # foto rota NUNCA debe tumbar la exportación completa de los demás
        # repuestos NI de las otras fotos del mismo repuesto. ──
        fotos = fotos_por_repuesto.get(rep["id"], [])
        for slot in range(FOTO_COLS):
            col = slot + 1
            if slot >= len(fotos):
                _foto_celda_vacia(r_idx, col, bg)
                continue
            try:
                img_bytes = _foto_bytes(fotos[slot])
                if img_bytes:
                    img = XLImage(io.BytesIO(img_bytes))
                    max_box = 60
                    w, h = (img.width or max_box), (img.height or max_box)
                    scale = min(max_box / w, max_box / h) if w and h else 1
                    img.width = max(1, round(w * scale))
                    img.height = max(1, round(h * scale))
                    ws.add_image(img, f"{get_column_letter(col)}{r_idx}")
                else:
                    _foto_celda_vacia(r_idx, col, bg)
            except Exception as e_img:
                print(f"[repstock_exportar_excel] foto rota repuesto id={rep.get('id')} slot={slot}: {e_img}", flush=True)
                _foto_celda_vacia(r_idx, col, bg)

        r_idx += 1

    widths = [10, 10, 10, 20, 40, 18, 14, 16, 16, 18, 14, 22, 30, 22, 14, 30, 16, 16]
    for ci, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(ci)].width = w
    ws.freeze_panes = "B3"
    ws.auto_filter.ref = f"A2:{get_column_letter(NCOLS)}{max(2, r_idx - 1)}"

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)

    _mant_log("repuesto_stock", 0, "exportar_excel",
              f"{len(rows)} repuestos exportados a Excel ({alcance_txt})")

    fname = f"Repuestos_ILUS_{_now.strftime('%Y-%m-%d')}.xlsx"
    return send_file(
        buf,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        as_attachment=True,
        download_name=fname,
    )


# ══════════════════════════════════════════════════════════════════════
#  FINANZAS DEL CLIENTE — agregados de ingresos/costos/margen
# ══════════════════════════════════════════════════════════════════════

@app.route("/mantenciones/api/clientes/<int:cid>/finanzas")
@_mant_required
def mant_cliente_finanzas(cid):
    """Devuelve agregados financieros del cliente para los últimos N meses."""
    meses = int(request.args.get("meses") or 12)
    if meses <= 0:
        fecha_corte = "1900-01-01"
    else:
        fecha_corte = (datetime.now().date() - timedelta(days=meses*31)).isoformat()

    # Repuestos
    rep_rows = mysql_fetchall(
        "SELECT tipo, cantidad, costo_unitario, precio_venta, fecha "
        "FROM mant_repuestos WHERE cliente_id=%s AND (fecha IS NULL OR fecha >= %s)",
        (cid, fecha_corte)
    )
    rep_venta_total = 0
    rep_costo_total = 0
    garantia_costo  = 0
    for r in rep_rows:
        c = float(r["cantidad"] or 0)
        cu = float(r["costo_unitario"] or 0)
        pv = float(r["precio_venta"] or 0)
        if r["tipo"] == "venta":
            rep_venta_total += pv * c
            rep_costo_total += cu * c
        elif r["tipo"] == "garantia":
            garantia_costo += cu * c
        else:  # reposicion / consumo
            rep_costo_total += cu * c

    # Visitas con costo
    visitas = mysql_fetchall(
        "SELECT tipo, estado, costo, fecha_programada FROM mant_visitas "
        "WHERE cliente_id=%s AND fecha_programada >= %s",
        (cid, fecha_corte)
    )
    visitas_costo = sum(float(v["costo"] or 0) for v in visitas if v.get("costo"))
    visitas_count = len([v for v in visitas if v.get("estado")=="completada"])

    # Contrato — estimación lineal (monto_mensual × meses_vigentes)
    contrato_estimado = 0
    contratos = mysql_fetchall(
        "SELECT monto_mensual, fecha_inicio, fecha_vencimiento, es_indefinido "
        "FROM mant_contratos WHERE cliente_id=%s AND estado='vigente'", (cid,)
    )
    hoy = datetime.now().date()
    for ct in contratos:
        m = float(ct["monto_mensual"] or 0)
        if m <= 0: continue
        fi = ct.get("fecha_inicio") or hoy
        if isinstance(fi, datetime): fi = fi.date()
        meses_vigentes = max(0, min(meses or 12, ((hoy.year - fi.year)*12 + hoy.month - fi.month)))
        contrato_estimado += m * meses_vigentes

    ingresos_total = rep_venta_total + visitas_costo + contrato_estimado
    costos_total   = rep_costo_total + garantia_costo
    margen         = ingresos_total - costos_total
    ticket_prom    = (ingresos_total / visitas_count) if visitas_count else 0

    # Por mes (últimos 12)
    months_es = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']
    por_mes = []
    for i in range(11,-1,-1):
        ref_year, ref_month = hoy.year, hoy.month - i
        while ref_month <= 0: ref_month += 12; ref_year -= 1
        ingreso_mes = 0
        for r in rep_rows:
            if r.get("fecha") and r["tipo"]=="venta":
                fr = r["fecha"]
                if isinstance(fr, datetime): fr = fr.date()
                if fr.year == ref_year and fr.month == ref_month:
                    ingreso_mes += float(r["precio_venta"] or 0) * float(r["cantidad"] or 0)
        for v in visitas:
            if v.get("fecha_programada") and v.get("estado")=="completada":
                fv = v["fecha_programada"]
                if isinstance(fv, datetime): fv = fv.date()
                if fv.year == ref_year and fv.month == ref_month:
                    ingreso_mes += float(v["costo"] or 0)
        por_mes.append({"label": months_es[ref_month-1], "year": ref_year, "ingreso": round(ingreso_mes,2)})

    return jsonify({
        "ingresos_total":  round(ingresos_total, 2),
        "costos_total":    round(costos_total, 2),
        "margen":          round(margen, 2),
        "garantia_costo":  round(garantia_costo, 2),
        "visitas_count":   visitas_count,
        "ticket_promedio": round(ticket_prom, 2),
        "repuestos_venta": round(rep_venta_total, 2),
        "visitas_costo":   round(visitas_costo, 2),
        "contrato_estimado": round(contrato_estimado, 2),
        "por_mes":         por_mes,
    })


# ══════════════════════════════════════════════════════════════════════
#  DOCUMENTOS DEL CLIENTE — listado unificado de adjuntos
# ══════════════════════════════════════════════════════════════════════

@app.route("/mantenciones/api/clientes/<int:cid>/documentos")
@_mant_required
def mant_cliente_documentos(cid):
    """Devuelve TODOS los documentos asociados al cliente (multi-fuente).

    SEGURIDAD 2026-05-26: solo superadmin puede ver botón de descarga o
    eliminar. Otros roles (ejecutivo, técnico) reciben deletable=false y
    downloadable=false. El flag se respeta en frontend; además, los
    endpoints destructivos validan server-side.
    """
    items = []
    es_super = bool((g.permissions or {}).get("superadmin"))

    # 1. Adjuntos (contratos + multi-archivo + externos + anexos)
    rows = mysql_fetchall(
        "SELECT id,tipo,subtipo_externo,nombre,archivo_nombre,mime_type,tamaño_bytes,"
        "       cloudinary_url,cloudinary_public_id,created_by,created_at "
        "  FROM mant_contrato_adjuntos WHERE cliente_id=%s", (cid,)
    )
    for r in rows:
        # URL: SIEMPRE usar nuestro proxy (fuerza inline + valida superadmin
        # en download). NO exponer la URL directa de Cloudinary.
        url = f"/mantenciones/api/adjuntos/{r['id']}/archivo"
        fuente_label = "Adjunto"
        if r.get("tipo") == "externo":
            fuente_label = "Doc. Externo"
            if r.get("subtipo_externo"):
                fuente_label += f" · {r['subtipo_externo'].replace('_',' ').title()}"
        elif r.get("tipo") == "anexo":
            fuente_label = "Anexo Contrato"
        # Mime hint para que el visor decida estrategia rápido
        _arch_nombre = r.get("archivo_nombre") or ""
        _ext = _arch_nombre.rsplit(".", 1)[-1].lower() if "." in _arch_nombre else ""
        _mime_hint = {
            "pdf": "application/pdf",
            "jpg": "image/jpeg", "jpeg": "image/jpeg",
            "png": "image/png", "gif": "image/gif", "webp": "image/webp",
            "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "doc": "application/msword",
            "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "xls": "application/vnd.ms-excel",
        }.get(_ext, r.get("mime_type") or "")
        _archivo_tipo = {
            "pdf": "pdf",
            "jpg": "imagen", "jpeg": "imagen", "png": "imagen",
            "gif": "imagen", "webp": "imagen",
            "docx": "docx", "doc": "doc",
            "xlsx": "xlsx", "xls": "xls",
        }.get(_ext, "")
        items.append({
            "kind":   "adjunto",
            "id":     r["id"],
            "tipo":   r["tipo"],
            "subtipo_externo": r.get("subtipo_externo"),
            "nombre": r["nombre"] or r.get("archivo_nombre"),
            "url":    url,
            "mime_type":    _mime_hint,
            "archivo_tipo": _archivo_tipo,
            "size_kb": round((r.get("tamaño_bytes") or 0)/1024) if r.get("tamaño_bytes") else None,
            "created_by": r.get("created_by"),
            "created_at": str(r["created_at"])[:16] if r.get("created_at") else "",
            "fuente": fuente_label,
            "persistente": bool(r.get("cloudinary_url")),
            "deletable":    es_super,   # solo superadmin
            "downloadable": es_super,   # solo superadmin
            "has_cloud":    bool(r.get("cloudinary_url")),
        })

    # 2. Reportes con HTML guardado
    rep_rows = mysql_fetchall(
        "SELECT id, ticket_num, asunto, html_path, html_generated_at, created_by "
        "FROM mant_reportes WHERE cliente_id=%s AND html_path IS NOT NULL", (cid,)
    )
    for r in rep_rows:
        items.append({
            "kind":   "reporte_html",
            "id":     r["id"],
            "tipo":   "reporte",
            "nombre": f"Informe {r.get('ticket_num') or r['id']} — {r.get('asunto') or 'Sin asunto'}",
            "url":    f"/static/{r['html_path']}",
            "mime_type": "text/html",
            "archivo_tipo": "html",
            "size_kb": None,
            "created_by": r.get("created_by"),
            "created_at": str(r["html_generated_at"])[:16] if r.get("html_generated_at") else "",
            "fuente": "Reporte (HTML)",
            "deletable":    False,
            "downloadable": es_super,
            "has_cloud":    False,
        })

    # 3. Contratos — archivo principal de cada contrato del cliente.
    #    FIX 2026-05-13: antes solo se listaban contratos que tenían archivo
    #    (archivo_path o cloudinary_url). Ahora listamos TODOS para que el tab
    #    "Documentos" sea espejo completo del tab "Contratos". Si un contrato
    #    no tiene archivo, lo mostramos igualmente con un flag `sin_archivo`
    #    para que el frontend pueda renderizar un placeholder informativo
    #    en vez de un link roto.
    # FIX 2026-05-14: la columna es fecha_vencimiento (no vencimiento).
    # El typo previo causaba HTTP 500 al cargar el tab Documentos.
    ct_rows = mysql_fetchall(
        "SELECT id,nombre,archivo_nombre,archivo_path,archivo_tipo,"
        "       cloudinary_url,cloudinary_public_id,estado,fecha_vencimiento,"
        "       created_by,created_at "
        "  FROM mant_contratos WHERE cliente_id=%s "
        " ORDER BY created_at DESC", (cid,)
    )
    for r in ct_rows:
        tiene_archivo = bool(r.get("archivo_path") or r.get("cloudinary_url"))
        # Nombre: priorizar el dado por el usuario, luego archivo, luego ID
        nm = r.get("nombre") or r.get("archivo_nombre") or f"Contrato #{r['id']}"
        # Estado opcional como sufijo
        if r.get("estado"):
            estado_lbl = r["estado"].replace("_", " ").title()
            if estado_lbl not in nm:
                nm = f"{nm} ({estado_lbl})"
        # Hint MIME para el viewer del frontend.
        # Como la URL es /api/contratos/X/archivo (sin extensión visible),
        # el frontend no puede detectar tipo desde la URL. Por eso le
        # pasamos `mime_type` explícito basado en archivo_tipo de la BD.
        _tipo_archivo_bd = (r.get("archivo_tipo") or "").lower()
        if _tipo_archivo_bd == "pdf":
            _mime = "application/pdf"
        elif _tipo_archivo_bd in ("word", "doc", "docx"):
            _mime = "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        else:
            _mime = ""
        items.append({
            "kind":   "contrato_principal",
            "id":     r["id"],
            "tipo":   "contrato",
            "nombre": nm,
            # Si tiene archivo: usar endpoint /contratos/<id>/archivo (proxy inline).
            # Si NO tiene: url null + flag sin_archivo para que el frontend muestre placeholder.
            "url":    (f"/mantenciones/api/contratos/{r['id']}/archivo" if tiene_archivo else None),
            "mime_type": _mime,
            "archivo_tipo": _tipo_archivo_bd,  # hint para el visor del frontend
            "size_kb": None,
            "created_by": r.get("created_by"),
            "created_at": str(r["created_at"])[:16] if r.get("created_at") else "",
            "fuente": "Contrato principal",
            "persistente": bool(r.get("cloudinary_url")),
            "deletable":    es_super,
            "downloadable": es_super,
            "has_cloud":    bool(r.get("cloudinary_url")),
            "sin_archivo": (not tiene_archivo),
        })

    # Ordenar por created_at desc
    items.sort(key=lambda x: x.get("created_at",""), reverse=True)
    return jsonify(items)


@app.route("/mantenciones/api/clientes/<int:cid>/evidencias", methods=["GET"])
@_mant_required
def mant_cliente_evidencias(cid):
    """FASE 6 — Tab "Evidencias" de la ficha del cliente.
    Devuelve todas las fotos del cliente unificadas en timeline:
    - mant_visita_fotos (evidencia de OTs ejecutadas)
    - mant_maquina_fotos (galería permanente de equipos)
    - mant_levantamiento_fotos (levantamientos fotográficos)

    Cada foto incluye: url Cloudinary, tipo, descripción, fecha, usuario,
    equipo al que pertenece (si aplica), origen (OT/levantamiento/galería).

    Filtros opcionales:
      ?origen=ot|levantamiento|galeria
      ?maquina_id=N (solo fotos de ese equipo)
    """
    origen = (request.args.get("origen") or "").strip().lower()
    maquina_id = request.args.get("maquina_id")
    try: maquina_id = int(maquina_id) if maquina_id else None
    except Exception: maquina_id = None

    fotos = []

    # 1. Fotos de visitas/OT
    if not origen or origen == "ot":
        rows_vf = mysql_fetchall(
            "SELECT vf.id, vf.archivo_path, vf.cloudinary_url, vf.tipo_foto, "
            "       vf.descripcion, vf.tomada_por, vf.tomada_at, "
            "       vf.visita_id, vf.maquina_id, "
            "       v.numero_ot, v.titulo AS visita_titulo, v.tipo AS visita_tipo, "
            "       v.estado AS visita_estado, "
            "       m.nombre AS maquina_nombre, m.serie AS maquina_serie "
            "  FROM mant_visita_fotos vf "
            "  JOIN mant_visitas v ON v.id = vf.visita_id "
            "  LEFT JOIN mant_maquinas m ON m.id = vf.maquina_id "
            " WHERE v.cliente_id=%s "
            + (" AND vf.maquina_id=%s" if maquina_id else "")
            + " ORDER BY vf.tomada_at DESC LIMIT 500",
            ((cid, maquina_id) if maquina_id else (cid,))
        ) or []
        for r in rows_vf:
            # FIX 2026-08-27: archivo_path YA trae "uploads/mantenciones/"
            # -- anteponerlo de nuevo duplicaba el segmento y rompía (404)
            # la foto para cualquiera que la abriera desde este timeline.
            url = r.get("cloudinary_url") or (f"/static/{r['archivo_path']}" if r.get("archivo_path") else "")
            if not url: continue
            fotos.append({
                "id": r["id"],
                "url": url,
                "tipo_foto": r.get("tipo_foto") or "general",
                "descripcion": r.get("descripcion") or "",
                "tomada_por": r.get("tomada_por") or "",
                "fecha": str(r["tomada_at"])[:16] if r.get("tomada_at") else "",
                "origen": "ot",
                "origen_label": f"OT {r.get('numero_ot') or '#'+str(r['visita_id'])}",
                "origen_url": f"/mantenciones/ot/{r['visita_id']}",
                "visita_titulo": r.get("visita_titulo") or "",
                "visita_tipo": r.get("visita_tipo") or "",
                "visita_estado": r.get("visita_estado") or "",
                "maquina_id": r.get("maquina_id"),
                "maquina_nombre": r.get("maquina_nombre") or "",
                "maquina_serie": r.get("maquina_serie") or "",
                "persistente": bool(r.get("cloudinary_url")),
            })

    # 2. Fotos de máquinas (galería permanente)
    if not origen or origen == "galeria":
        sql_mf = (
            "SELECT mf.id, mf.archivo_path, mf.cloudinary_url, mf.tipo_foto, "
            "       mf.descripcion, mf.tomada_por, mf.created_at, "
            "       mf.maquina_id, mf.levantamiento_id, "
            "       m.nombre AS maquina_nombre, m.serie AS maquina_serie "
            "  FROM mant_maquina_fotos mf "
            "  JOIN mant_maquinas m ON m.id = mf.maquina_id "
            " WHERE m.cliente_id=%s "
        )
        params_mf = [cid]
        if maquina_id:
            sql_mf += " AND mf.maquina_id=%s "
            params_mf.append(maquina_id)
        sql_mf += " ORDER BY mf.created_at DESC LIMIT 500"
        rows_mf = mysql_fetchall(sql_mf, tuple(params_mf)) or []
        for r in rows_mf:
            # Mismo fix de doble prefijo (mant_maquina_fotos también guarda
            # archivo_path con el prefijo ya incluido).
            url = r.get("cloudinary_url") or (f"/static/{r['archivo_path']}" if r.get("archivo_path") else "")
            if not url: continue
            fotos.append({
                "id": r["id"],
                "url": url,
                "tipo_foto": r.get("tipo_foto") or "general",
                "descripcion": r.get("descripcion") or "",
                "tomada_por": r.get("tomada_por") or "",
                "fecha": str(r["created_at"])[:16] if r.get("created_at") else "",
                "origen": "galeria" if not r.get("levantamiento_id") else "levantamiento",
                "origen_label": (
                    f"Levantamiento #{r['levantamiento_id']}" if r.get("levantamiento_id")
                    else "Galería del equipo"
                ),
                "origen_url": (
                    f"/mantenciones/clientes/{cid}?lev={r['levantamiento_id']}"
                    if r.get("levantamiento_id") else f"/mantenciones/clientes/{cid}"
                ),
                "maquina_id": r.get("maquina_id"),
                "maquina_nombre": r.get("maquina_nombre") or "",
                "maquina_serie": r.get("maquina_serie") or "",
                "persistente": bool(r.get("cloudinary_url")),
            })

    # Ordenar timeline cronológico desc
    fotos.sort(key=lambda x: x.get("fecha", ""), reverse=True)

    # Estadísticas para badges en UI
    total = len(fotos)
    por_origen = {}
    por_maquina = {}
    for f_ in fotos:
        por_origen[f_["origen"]] = por_origen.get(f_["origen"], 0) + 1
        if f_.get("maquina_id"):
            mid = f_["maquina_id"]
            por_maquina[mid] = por_maquina.get(mid, 0) + 1

    return jsonify({
        "ok": True,
        "fotos": fotos[:500],  # límite duro
        "total": total,
        "por_origen": por_origen,
        "por_maquina": por_maquina,
    })


# ══════════════════════════════════════════════════════════════════════
# TAB "COTIZACIONES" DE LA FICHA — 2026-08-30 (Daniel, dictado: "la ficha
# del cliente debe ser un HUB de trazabilidad completo... productos, OT,
# visitas, fechas, fotos, responsables, todo").
#
# La ficha ya tenía un hook de ESCRITURA hacia Cotizaciones (botón
# "Generar cotización" que abre /tickets/cotizaciones?desde_cliente=<cid>,
# PR-5 2026-07-23) pero nunca leía de vuelta el historial: si a este
# cliente ya le habían cotizado algo desde el módulo Tickets, la ficha no
# lo mostraba en ningún lado. Este endpoint cierra ese loop.
#
# tk_cotizaciones vive en MySQL igual que mant_clientes, pero es una
# tabla de OTRO módulo (Tickets/Cotizador) sin FK a mant_clientes — el
# único cruce posible es por RUT, y los RUT llegan con formato
# inconsistente entre ambos módulos (con/sin puntos, con/sin dígito
# verificador). Por eso NO se compara con `=` en SQL: se usa
# `_rut_cuerpo()` (mismo criterio ya usado en tickets_module.py para
# resolver cliente_id desde un ticket, línea ~7262) para comparar solo el
# cuerpo del RUT en Python, sobre un lote acotado (LIMIT 3000 — muy por
# encima del volumen real de tk_cotizaciones hoy).
# ══════════════════════════════════════════════════════════════════════
@app.route("/mantenciones/api/clientes/<int:cid>/cotizaciones", methods=["GET"])
@_mant_required
def mant_cliente_cotizaciones(cid):
    """Historial de cotizaciones (tk_cotizaciones, módulo Cotizador de
    Tickets) generadas para este cliente, cruzadas por cuerpo de RUT.

    Paginado server-side (REGLA #4.3 — "toda tabla se pagina como
    Etiquetas"): ?page=N&per_page=M (default 1 / 20, tope 100).
    """
    cliente = mysql_fetchone("SELECT rut FROM mant_clientes WHERE id=%s", (cid,))
    if not cliente:
        return jsonify({"ok": False, "error": "Cliente no encontrado"}), 404

    try:
        page = max(1, int(request.args.get("page", 1)))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = int(request.args.get("per_page", 20))
    except (TypeError, ValueError):
        per_page = 20
    per_page = min(max(per_page, 5), 100)

    rut_cuerpo_cliente = _rut_cuerpo(cliente.get("rut"))
    if not rut_cuerpo_cliente:
        # Cliente sin RUT registrado: no hay con qué cruzar. No es un error,
        # es simplemente "sin cotizaciones que mostrar".
        return jsonify({
            "ok": True, "cotizaciones": [], "total": 0,
            "page": 1, "per_page": per_page, "total_pages": 1,
            "sin_rut": True,
        })

    rows = mysql_fetchall(
        "SELECT c.id, c.numero_cotizacion, c.estado, c.empresa, c.rut, c.total, "
        "       c.created_at, c.valida_hasta, c.ticket_id, tk.numero_ticket "
        "  FROM tk_cotizaciones c "
        "  LEFT JOIN tk_tickets tk ON tk.id = c.ticket_id "
        " WHERE COALESCE(c.eliminada,0)=0 "
        "   AND c.rut IS NOT NULL AND c.rut <> '' "
        " ORDER BY c.created_at DESC "
        " LIMIT 3000"
    ) or []

    matched = [r for r in rows if _rut_cuerpo(r.get("rut")) == rut_cuerpo_cliente]
    matched.sort(key=lambda r: r.get("created_at") or datetime.min, reverse=True)

    total = len(matched)
    total_pages = max(1, -(-total // per_page))  # ceil sin importar math
    page = min(page, total_pages)
    start = (page - 1) * per_page
    pagina = matched[start:start + per_page]

    hoy = datetime.now().date()
    cotizaciones = []
    for r in pagina:
        vh = r.get("valida_hasta")
        vh_date = vh.date() if hasattr(vh, "date") else vh
        vencida = bool(vh_date and vh_date < hoy and r.get("estado") in ("draft", "sent"))
        cotizaciones.append({
            "id": r["id"],
            "numero_cotizacion": r.get("numero_cotizacion") or f"#{r['id']}",
            "estado": r.get("estado") or "draft",
            "vencida": vencida,
            "empresa": r.get("empresa") or "",
            "total": int(r.get("total") or 0),
            # Formateadas a hora Chile EN EL BACKEND (REGLA #6) — el JSON
            # nunca lleva un timestamp crudo que el frontend deba reinterpretar.
            "fecha_fmt": chile_fmt_filter(r.get("created_at"), "%d/%m/%Y %H:%M") if r.get("created_at") else "—",
            "valida_hasta_fmt": vh_date.strftime("%d/%m/%Y") if vh_date else None,
            "ticket_id": r.get("ticket_id"),
            "numero_ticket": r.get("numero_ticket") or "",
            "url_ver": url_for("tk_cotizacion_ver", cid=r["id"]),
        })

    return jsonify({
        "ok": True,
        "cotizaciones": cotizaciones,
        "total": total,
        "page": page,
        "per_page": per_page,
        "total_pages": total_pages,
    })


@app.route("/mantenciones/api/clientes/<int:cid>/documentos", methods=["POST"])
@_mant_required
def mant_cliente_documento_subir(cid):
    """Sube un documento suelto al cliente como adjunto general.

    Form fields:
      archivo:         file (requerido)
      tipo:            'contrato'|'imagen'|'reporte'|'otro'|'externo'|'anexo' (opcional)
      subtipo_externo: si tipo='externo'→'visita_externa'|'ot_externa'|'otro'
                       si tipo='anexo'→'anexo_contrato'
      nombre:          nombre legible (sino usa filename)

    Storage: Cloudinary primero (persistente), filesystem como fallback.
    """
    f = request.files.get("archivo")
    if not f or not f.filename: return jsonify({"error":"Sin archivo"}), 400
    ext = f.filename.rsplit(".",1)[-1].lower() if "." in f.filename else ""
    if ext not in ALLOWED_ADJUNTO: return jsonify({"error":"Tipo no permitido"}), 400

    # Tipo explícito desde form
    tipo_form = (request.form.get("tipo") or "").strip().lower()
    if tipo_form in ("contrato","imagen","solicitud","cotizacion","reporte","otro","externo","anexo"):
        tipo = tipo_form
    else:
        tipo = ALLOWED_ADJUNTO_TIPOS.get(ext, "otro")
    subtipo_externo = (request.form.get("subtipo_externo") or "").strip()[:80] or None

    fname = secure_filename(f"cli{cid}_{int(time.time())}_{f.filename}")

    # ── Cloudinary primero ───────────────────────────────────────────
    cloud_url = None
    cloud_pid = None
    if _gcs_ready():
        try:
            f.stream.seek(0)
            folder = f"ilus/contratos/adjuntos/{tipo}"
            public_id = f"cli_{cid}_{int(time.time())}"
            res = _cloud_upload_raw(f.stream, public_id, folder=folder)
            cloud_url = res["url"]
            cloud_pid = res["public_id"]
            print(f"[mant_documento] Cloudinary OK cid={cid} tipo={tipo}", flush=True)
        except Exception as e_cld:
            print(f"[mant_documento] Cloudinary FAIL cid={cid}: {e_cld}", flush=True)

    # ── Filesystem fallback ──────────────────────────────────────────
    try:
        f.stream.seek(0)
    except Exception:
        pass
    fpath = os.path.join(MANT_UPLOADS, fname)
    size = 0
    try:
        f.save(fpath)
        size = os.path.getsize(fpath)
    except Exception as e_save:
        if not cloud_url:
            return jsonify({"error": f"No se pudo guardar: {e_save}"}), 500

    nombre = (request.form.get("nombre") or f.filename)[:300]

    # Crear contrato dummy si no existe (para satisfacer FK)
    ct = mysql_fetchone("SELECT id FROM mant_contratos WHERE cliente_id=%s ORDER BY id LIMIT 1", (cid,))
    if not ct:
        conn = get_mysql()
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO mant_contratos (cliente_id,nombre,estado,es_indefinido,created_by) "
                "VALUES (%s,'Contenedor de documentos','indefinido',1,%s)",
                (cid, current_username())
            )
            ct_id = cur.lastrowid
        conn.commit(); conn.close()
    else:
        ct_id = ct["id"]

    mysql_execute(
        "INSERT INTO mant_contrato_adjuntos "
        "(contrato_id,cliente_id,tipo,subtipo_externo,nombre,archivo_nombre,archivo_path,"
        " cloudinary_url,cloudinary_public_id,mime_type,tamaño_bytes,created_by) "
        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
        (ct_id, cid, tipo, subtipo_externo, nombre, fname, fname,
         cloud_url, cloud_pid, f.mimetype or '', size, current_username())
    )
    _mant_log("documento", cid, "subir", f"{tipo} · {nombre}")
    return jsonify({
        "ok": True,
        "tipo": tipo,
        "subtipo_externo": subtipo_externo,
        "persistente": bool(cloud_url),
        "storage": "cloudinary" if cloud_url else "filesystem"
    })


@app.route("/mantenciones/api/documentos/<kind>/<int:did>", methods=["DELETE"])
@_mant_required
@_no_tecnico
def mant_documento_del(kind, did):
    if kind == "adjunto":
        adj = mysql_fetchone(
            "SELECT archivo_nombre, nombre, cliente_id FROM mant_contrato_adjuntos WHERE id=%s",
            (did,)
        )
        if adj:
            try:
                fp = os.path.join(MANT_UPLOADS, adj["archivo_nombre"])
                if os.path.exists(fp): os.remove(fp)
            except Exception: pass
            mysql_execute("DELETE FROM mant_contrato_adjuntos WHERE id=%s",(did,))
            if adj.get("cliente_id"):
                _mant_log("cliente", adj["cliente_id"], "documento_eliminado",
                          adj.get("nombre") or f"adjunto #{did}")
            return jsonify({"ok":True})
    return jsonify({"error":"Tipo no eliminable o no encontrado"}), 400


# ══════════════════════════════════════════════════════════════════════
#  EMAIL MANUAL — enviar email arbitrario al cliente con trazabilidad
# ══════════════════════════════════════════════════════════════════════

@app.route("/mantenciones/api/clientes/<int:cid>/email-manual", methods=["POST"])
@_mant_required
def mant_email_manual(cid):
    d = request.get_json(silent=True) or {}
    destinatario = (d.get("destinatario") or "").strip()
    asunto       = (d.get("asunto") or "").strip()
    mensaje      = (d.get("mensaje") or "").strip()
    if not (destinatario and asunto and mensaje):
        return jsonify({"error":"Completa destinatario, asunto y mensaje"}), 400
    if "@" not in destinatario:
        return jsonify({"error":"Email no válido"}), 400

    cliente = mysql_fetchone("SELECT razon_social FROM mant_clientes WHERE id=%s",(cid,))
    if not cliente: return jsonify({"error":"Cliente no encontrado"}), 404

    # Envolver SIEMPRE con la plantilla corporativa (formato del preview)
    body = (
        f"<p>{mensaje.replace(chr(10), '<br>')}</p>"
        f"<hr style='border:none;border-top:1px solid #e5e7eb;margin:18px 0'>"
        f"<p style='font-size:.78rem;color:#9ca3af'>Enviado por {current_username()}</p>"
    )
    html = _comm_render_email_document(asunto, body, cliente.get("razon_social",""))

    sent = False; err = None
    try:
        sent = _send_ilus_email(destinatario, asunto, html,
                                evento="mant_sla_manual", modulo="mantenciones")
    except Exception as exc: err = str(exc)

    # Registrar en notificaciones
    try:
        mysql_execute(
            "INSERT INTO mant_notificaciones "
            "(cliente_id,entidad,entidad_id,tipo,titulo,mensaje,canal,estado,destinatario,fecha_envio,created_by) "
            "VALUES (%s,'cliente',%s,'sla',%s,%s,'email',%s,%s,NOW(),%s)",
            (cid, cid, asunto, mensaje[:1000],
             'enviada' if sent else 'fallida', destinatario, current_username())
        )
    except Exception: pass
    _mant_log("cliente", cid, "email_manual",
              f"to={destinatario} ok={sent} err={err or '-'}")
    return jsonify({"ok": bool(sent), "error": err})


