@app.route("/mantenciones/api/notificaciones/<int:nid>/enviar", methods=["POST"])
@_mant_required
def mant_notif_enviar(nid):
    """Envía la notificación por email usando Resend."""
    notif = mysql_fetchone(
        "SELECT n.*,c.contacto_email,c.razon_social FROM mant_notificaciones n "
        "LEFT JOIN mant_clientes c ON c.id=n.cliente_id WHERE n.id=%s", (nid,)
    )
    if not notif: return jsonify({"error":"No encontrado"}), 404

    destinatario = notif.get("destinatario") or notif.get("contacto_email","")
    if not destinatario:
        return jsonify({"error":"Sin email destinatario"}), 400

    # 2026-06-14 (Daniel): migrado al maestro ILUS (antes HTML inline con diseño
    # viejo #CC0000 y campos sin escapar → riesgo XSS). markupsafe escapa
    # titulo/mensaje/cliente (vienen de mant_notificaciones).
    from markupsafe import escape as _esc
    _titulo  = str(notif.get('titulo') or 'Notificación')
    _mensaje = str(_esc(notif.get('mensaje') or '')).replace("\n", "<br>")
    html_body = _ilus_email_master({
        "subject":          _brand_subject(_titulo),
        "status_label":     "Servicio Técnico",
        "title":            _titulo,
        "subtitle":         "Servicio Técnico · ILUS Fitness",
        "customer_name":    notif.get('razon_social') or "",
        "message":          _mensaje,
    })

    try:
        # Pasa por el wrapper para respetar kill switch global + llave por módulo
        resultado = _send_ilus_email(
            destinatario,
            f"[ILUS Servicio Técnico] {notif['titulo']}",
            html_body,
            evento="mant_notificacion", modulo="mantenciones",
        )
        conn = get_mysql()
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE mant_notificaciones SET estado='enviada',fecha_envio=%s WHERE id=%s",
                    (datetime.now(), nid)
                )
            conn.commit()
        finally:
            conn.close()
        return jsonify({"ok":True})
    except Exception as e:
        return jsonify({"error":str(e)}), 500


