def _tarea_respaldo_texto(tipo_ot, nombre_equipo):
    """(titulo, descripcion) de la tarea de respaldo por equipo."""
    nombre_equipo = (nombre_equipo or 'equipo')[:240]
    if (tipo_ot or '') == 'levantamiento':
        return (f"📷 Documentar: {nombre_equipo}",
                "Capturar fotos generales del equipo + N° serie + placa + "
                "datos técnicos.")
    label = _TIPO_OT_LABEL.get(tipo_ot or '', 'Servicio')
    return (f"🔧 {label}: {nombre_equipo}",
            f"{label} del equipo. Registrar trabajo realizado, estado final "
            f"y fotos de respaldo.")


# ═════════════════════════════════════════════════════════════════════
# MOTOR DE OT — reconstruido 2026-08-13 (Daniel: "reconstruye el motor de
# OT desde cero... vamos con todo, construyamos ya"). Reemplaza la
# función monolítica de ~1200 líneas (con parches fechados apilados uno
# sobre otro desde 2026-05-16) por piezas chicas, cada una con una sola
# responsabilidad. MISMO contrato público: mismo nombre de función, misma
# firma `_mant_lev_crear_ot_core(cid, data, ticket_id=None)`, mismo
# payload de entrada, misma forma de respuesta -- los 2 callers
# (mant_lev_crear_o_listar en este archivo, tk_api_generar_ot en
# tickets_module.py) NO cambian ni una línea.
#
# Comportamiento preservado 1:1 (inventario hecho leyendo la función
# vieja completa, línea por línea, antes de escribir esto):
#   - limpieza de levantamientos huérfanos del cliente
#   - 14 tipos de OT válidos, tarea_tipo seguro para el ENUM angosto de
#     mant_visita_tareas.tipo
#   - descubrimiento solo tiene sentido para tipo_ot='levantamiento'
#   - equipos del ticket sin ficha: alta automática en mant_maquinas para
#     8 tipos (instalacion/correctiva/preventiva/visita_tecnica/
#     inspeccion/garantia/cambio_equipo/visita_correctiva) con
#     trazabilidad en mant_logs; exclusión reportada para el resto (salvo
#     cliente_nuevo); inclusión tal cual para levantamiento
#   - error EQUIPO_SIN_FICHA / SIN_EQUIPOS si no queda ningún equipo
#   - agenda (fecha/horas/rango), multi-técnico, plantilla_id override,
#     aplica_garantia (nunca en levantamiento), dirección, contacto,
#     acceso y logística
#   - plantillas_por_equipo (maquina_id real) y plantillas_por_ticket_
#     equipo (equipos sin ficha, prefijo "teq_<id>")
#   - transacción atómica: mant_levantamientos (si aplica) + items,
#     numero_ot atómico, mant_visitas con prefijo de título por tipo,
#     modalidad de cobro, multi-técnico en mant_visita_tecnicos, vínculo
#     con el ticket -- todo o nada
#   - checklist (post-commit, defensivo, cada pieza en su propia conexión
#     para que un fallo puntual no tumbe toda la respuesta): la plantilla
#     estándar/por-clasificación SIEMPRE se aplica (fix 2026-08-13), las
#     extra explícitas suman encima y solo cuentan si de verdad tienen
#     ítems (fix 2026-08-13), la plantilla NUNCA adivina con el checklist
#     de otra máquina (fix 2026-08-13, lista explícita
#     _PLANTILLA_GENERICA_NOMBRES), tarea de respaldo genérica para
#     equipos sin ficha, red de seguridad final si items_plantilla sigue
#     en 0 tras todo lo anterior
#   - auditoría en mant_logs, respuesta con mensaje legible por tipo real
# ═════════════════════════════════════════════════════════════════════

_OT_TIPOS_VALIDOS = (
    "levantamiento", "instalacion", "preventiva", "correctiva",
    "visita_tecnica", "inspeccion", "garantia", "cambio_equipo",
    "desinstalacion", "capacitacion", "repuesto", "revision_interna",
    "visita_correctiva", "control_calidad",
    # 2026-08-19 (Daniel): trasladar equipos dentro del gimnasio.
    "movimiento_equipos",
)

# Mismos 8 tipos que _TKOT_TIPOS_FUERZAN_CLIENTE_NUEVO (tickets_ficha.js):
# donde un equipo nuevo tiene sentido de negocio. Deliberadamente sin
# 'levantamiento' (tiene su propio flujo de descubrimiento, que sigue
# existiendo intacto como una opción más, no la única) ni 'desinstalacion'
# (quitar algo que nunca existió no tiene sentido).
_TIPOS_OT_DAN_ALTA_EQUIPO = (
    "instalacion", "correctiva", "preventiva", "visita_tecnica",
    "inspeccion", "garantia", "cambio_equipo", "visita_correctiva",
)

_OT_TIPO_PREFIJO = {
    'levantamiento':  '[LEV]',
    'instalacion':    '[INST]',
    'preventiva':     '[PM]',
    'correctiva':     '[CM]',
    'visita_tecnica': '[VT]',
    'inspeccion':     '[INSP]',
    'garantia':       '[GAR]',
}

_OT_TIPO_LABEL_MENSAJE = {
    'levantamiento':    'Levantamiento',
    'instalacion':      'Instalación',
    'preventiva':       'Mantención preventiva',
    'correctiva':       'Mantención correctiva',
    'visita_tecnica':   'Visita técnica',
    'inspeccion':       'Inspección',
    'garantia':         'Garantía',
    'cambio_equipo':    'Cambio de equipo',
    'desinstalacion':   'Desinstalación',
    'capacitacion':     'Capacitación',
    'repuesto':         'Repuesto',
    'revision_interna': 'Trabajo de bodega',
    'visita_correctiva': 'Visita correctiva',
    'control_calidad':  'Control de calidad',
}


def _ot_resolver_tipo(data):
    """(tipo_ot, tarea_tipo). tipo_ot inválido o ausente -> 'levantamiento'."""
    tipo_ot = (data.get("tipo_ot") or "levantamiento").strip().lower()
    if tipo_ot not in _ot_tipos_todos():
        tipo_ot = "levantamiento"
    return tipo_ot, _tarea_tipo_seguro(tipo_ot)


def _ot_dar_alta_equipo_automatica(cid, et, nombre_et, tipo_ot, ticket_id):
    """Crea la ficha del equipo en mant_maquinas + trazabilidad en
    mant_logs. Retorna el id nuevo, o None si el alta falla (el caller
    cae al camino de exclusión/cliente_nuevo de siempre, sin romper la OT
    por esto)."""
    try:
        mysql_execute(
            "INSERT INTO mant_maquinas "
            "(cliente_id, sku, nombre, serie, cantidad, estado, created_by) "
            "VALUES (%s,%s,%s,%s,1,'activo',%s)",
            (cid, (et.get("sku") or "").strip()[:100] or None, nombre_et,
             (et.get("serie") or "").strip()[:100] or None,
             current_username() or "sistema")
        )
        row = mysql_fetchone("SELECT LAST_INSERT_ID() AS id")
        maquina_id = (row or {}).get("id")
    except Exception as e:
        print(f"[lev_crear] alta automática de máquina falló para "
              f"'{nombre_et}' (tipo '{tipo_ot}'): {e}", flush=True)
        return None
    if maquina_id:
        _mant_log(
            "maquina", maquina_id, "creada_por_ot",
            f"Alta automática por OT de tipo '{tipo_ot}'"
            f"{f' (ticket #{ticket_id})' if ticket_id else ''}: "
            f"equipo declarado en el ticket, sin ficha previa."
        )
    return maquina_id


def _ot_resolver_equipos(cid, data, tipo_ot, ticket_id):
    """Arma la lista de equipos de la OT desde equipo_ids (fichas ya
    existentes, elegidas a mano) + equipos_ticket (declarados en un
    ticket, con o sin ficha). Devuelve dict:
      equipo_ids           -- list[int], incluye las altas automáticas
      equipos_ticket_clean -- list[dict], equipos sin ficha que SÍ entran
                               a la OT (maquina_id=None)
      equipos_excluidos    -- list[dict], equipos sin ficha que NO
                               califican para alta automática ni para
                               cliente_nuevo -- se reportan, no bloquean
                               el resto de la OT
      altas_automaticas    -- dict {ticket_equipo_id: nuevo_maquina_id}.
                               El frontend elige la plantilla ANTES de
                               que exista ficha, usando la key teq_<id>
                               (plantillas_por_ticket_equipo); acá recién
                               se sabe el maquina_id real. El caller debe
                               remapear esa selección a plantillas_por_equipo
                               con este dict -- si no, un equipo nuevo
                               jamás podría cumplir "elige tu plantilla"
                               porque el id que le pertenece no existía
                               todavía cuando el usuario eligió (2026-08-13).
    """
    equipo_ids = []
    for x in (data.get("equipo_ids") or []):
        try:
            equipo_ids.append(int(x))
        except (TypeError, ValueError):
            pass
    cliente_es_nuevo = bool(data.get("cliente_nuevo"))
    equipos_ticket_clean = []
    equipos_excluidos = []
    altas_automaticas = {}
    equipos_ticket_raw = data.get("equipos_ticket") or []
    if isinstance(equipos_ticket_raw, list):
        for et in equipos_ticket_raw:
            if not isinstance(et, dict):
                continue
            nombre_et = (et.get("nombre") or "").strip()[:300]
            if not nombre_et:
                continue
            try:
                maquina_id_et = int(et["maquina_id"]) if et.get("maquina_id") else None
            except (TypeError, ValueError):
                maquina_id_et = None

            if maquina_id_et is None and tipo_ot in _TIPOS_OT_DAN_ALTA_EQUIPO:
                nuevo_id = _ot_dar_alta_equipo_automatica(cid, et, nombre_et, tipo_ot, ticket_id)
                if nuevo_id:
                    equipo_ids.append(nuevo_id)
                    try:
                        teq_previo = int(et["id"]) if et.get("id") else None
                    except (TypeError, ValueError):
                        teq_previo = None
                    if teq_previo:
                        altas_automaticas[teq_previo] = nuevo_id
                    continue
                # alta falló -- sigue de largo, cae al camino normal de abajo

            if maquina_id_et is None and tipo_ot != "levantamiento" and not cliente_es_nuevo:
                equipos_excluidos.append({
                    "nombre": nombre_et,
                    "sku": (et.get("sku") or "").strip()[:120] or None,
                    "serie": (et.get("serie") or "").strip()[:120] or None,
                    "motivo": "sin_ficha",
                })
                continue

            try:
                ticket_equipo_id_et = int(et["id"]) if et.get("id") else None
            except (TypeError, ValueError):
                ticket_equipo_id_et = None
            equipos_ticket_clean.append({
                "id": maquina_id_et,
                "ticket_equipo_id": ticket_equipo_id_et,
                "nombre": nombre_et,
                "sku": (et.get("sku") or "").strip()[:120] or None,
                "serie": (et.get("serie") or "").strip()[:120] or None,
                "doc_fecha": None,
            })
    return {
        "equipo_ids": equipo_ids,
        "equipos_ticket_clean": equipos_ticket_clean,
        "equipos_excluidos": equipos_excluidos,
        "altas_automaticas": altas_automaticas,
    }


def _ot_resolver_agenda(data):
    return {
        "fecha_prog": (data.get("fecha_programada") or "").strip()[:10] or _now_chile_str('%Y-%m-%d'),
        "hora_ini": (data.get("hora_inicio") or "").strip()[:5] or None,
        "hora_fin": (data.get("hora_fin") or "").strip()[:5] or None,
        "fecha_fin": (data.get("fecha_fin") or "").strip()[:10] or None,
    }


def _ot_resolver_tecnicos(data):
    """(tecnico_ids: list[int], tecnico_principal: int|None)."""
    tecnico_ids = data.get("tecnico_ids") or []
    if not tecnico_ids and data.get("tecnico_id"):
        tecnico_ids = [data.get("tecnico_id")]
    limpio = []
    for tid in tecnico_ids:
        try:
            limpio.append(int(tid))
        except Exception:
            pass
    return limpio, (limpio[0] if limpio else None)


def _ot_resolver_plantilla_override(data):
    """plantilla_id explícita del caller, validada activa. None si no
    vino, no existe, o está inactiva -- nunca bloquea la creación."""
    try:
        pid_raw = data.get("plantilla_id")
        if not pid_raw:
            return None
        pid_int = int(pid_raw)
        row = mysql_fetchone(
            "SELECT id FROM mant_tarea_plantillas "
            " WHERE id=%s AND COALESCE(activa,1)=1 LIMIT 1",
            (pid_int,))
        return pid_int if row else None
    except (TypeError, ValueError):
        return None
    except Exception as e:
        print(f"[lev_crear] validar plantilla_id override falló: {e}", flush=True)
        return None


def _ot_resolver_plantillas_payload(data):
    """plantillas_por_equipo (payload crudo, Paso 5) separado en dos
    dicts según la clave: numérica = maquina_id real; 'teq_<id>' =
    ticket_equipo_id (equipo sin ficha, ver _tkotEqKey en
    tickets_ficha.js)."""
    por_equipo, por_ticket_equipo = {}, {}
    raw = data.get("plantillas_por_equipo") or {}
    if isinstance(raw, dict):
        for mid_str, plist in raw.items():
            try:
                ids_int = [int(p) for p in (plist or []) if p]
                if not ids_int:
                    continue
                if isinstance(mid_str, str) and mid_str.startswith("teq_"):
                    por_ticket_equipo[int(mid_str[4:])] = ids_int
                else:
                    por_equipo[int(mid_str)] = ids_int
            except (TypeError, ValueError):
                continue
    return por_equipo, por_ticket_equipo


def _plantillas_con_items(pids):
    """Subset de `pids` que de verdad tienen al menos 1 item en
    mant_tarea_plantilla_items. Una plantilla vacía NUNCA cuenta como
    checklist real -- mismo criterio en toda la app (antes duplicado en
    _plantilla_estandar_para_tipo, _ot_resolver_checklist paso 1 y ahora
    también _ot_validar_plantillas_elegidas)."""
    pids = sorted({int(p) for p in pids if p})
    if not pids:
        return set()
    try:
        ph = ",".join(["%s"] * len(pids))
        rows = mysql_fetchall(
            f"SELECT plantilla_id, COUNT(*) AS n FROM mant_tarea_plantilla_items "
            f" WHERE plantilla_id IN ({ph}) GROUP BY plantilla_id",
            tuple(pids)) or []
        return {r["plantilla_id"] for r in rows if int(r.get("n") or 0) > 0}
    except Exception as e:
        print(f"[plantillas_con_items] falló para {pids}: {e}", flush=True)
        return set()


def _ot_validar_plantillas_elegidas(tipo_ot, equipo_ids, equipos_ticket_clean,
                                     plantilla_id_override, plantillas_por_equipo,
                                     plantillas_por_ticket_equipo):
    """Daniel 2026-08-13, en vivo, probando OTs reales: "no quiero nada
    automático, todo lo debe escoger el usuario y si no escoge no lo debe
    dejar avanzar". Se llama ANTES de tocar la base de datos -- si falta
    algo, la OT ni se empieza a crear (a diferencia de las redes de
    seguridad de _ot_resolver_checklist, que rellenan DESPUÉS de crear).

    Devuelve None si está todo elegido, o un dict (ok:False, ...) listo
    para responder 400 sin crear nada.

    'levantamiento' queda afuera a propósito: no varía por clasificación
    de equipo, siempre usa el mismo checklist fotográfico estándar
    (_PLANTILLA_ESTANDAR_NOMBRE['levantamiento']) -- exigir una "elección"
    ahí sería puro trámite sin ninguna decisión real detrás.
    """
    if tipo_ot == "levantamiento":
        return None

    pendientes = []
    for mid in equipo_ids:
        pendientes.append(("equipo", mid, plantillas_por_equipo.get(mid) or []))
    for et in equipos_ticket_clean:
        if et.get("id"):
            pendientes.append(("equipo", et["id"], plantillas_por_equipo.get(et["id"]) or []))
        elif et.get("ticket_equipo_id"):
            teq = et["ticket_equipo_id"]
            pendientes.append(("ticket_equipo", teq, plantillas_por_ticket_equipo.get(teq) or []))
    if not pendientes:
        return None

    todos_los_pids = {pid for _, _, pids in pendientes for pid in pids}
    if plantilla_id_override:
        todos_los_pids.add(plantilla_id_override)
    pids_con_items = _plantillas_con_items(todos_los_pids)
    override_ok = bool(plantilla_id_override and plantilla_id_override in pids_con_items)

    sin_elegir = [
        (tipo_clave, clave) for tipo_clave, clave, pids in pendientes
        if not any(p in pids_con_items for p in pids) and not override_ok
    ]
    if not sin_elegir:
        return None

    mids_equipo = [c for t, c in sin_elegir if t == "equipo"]
    nombres = []
    if mids_equipo:
        try:
            ph = ",".join(["%s"] * len(mids_equipo))
            rows = mysql_fetchall(
                f"SELECT nombre FROM mant_maquinas WHERE id IN ({ph})", tuple(mids_equipo)) or []
            nombres = [r["nombre"] for r in rows]
        except Exception as e:
            print(f"[validar_plantillas_elegidas] leer nombres falló: {e}", flush=True)
    nombres += [f"equipo sin ficha #{c}" for t, c in sin_elegir if t == "ticket_equipo"]
    return {
        "ok": False,
        "error": (
            "Elige una plantilla de checklist para cada equipo antes de crear "
            "la OT (o una plantilla general en el Paso 1). Falta para: "
            f"{', '.join(nombres) if nombres else f'{len(sin_elegir)} equipo(s)'}."
        ),
        "error_codigo": "PLANTILLA_SIN_ELEGIR",
        "equipos_sin_plantilla": len(sin_elegir),
    }


def _ot_tribool(val):
    """true/false/null/"si"/"no"/"1"/"0" -> 1/0/None."""
    if val is None or val == "":
        return None
    if isinstance(val, bool):
        return 1 if val else 0
    s = str(val).strip().lower()
    if s in ("1", "true", "si", "sí", "yes", "y"):
        return 1
    if s in ("0", "false", "no", "n"):
        return 0
    return None


def _ot_resolver_direccion_contacto_acceso(data):
    try:
        lat = float(data.get("direccion_lat")) if data.get("direccion_lat") is not None else None
    except (TypeError, ValueError):
        lat = None
    try:
        lng = float(data.get("direccion_lng")) if data.get("direccion_lng") is not None else None
    except (TypeError, ValueError):
        lng = None
    return {
        "direccion_visita": (data.get("direccion_visita") or "").strip()[:400] or None,
        "direccion_lat": lat,
        "direccion_lng": lng,
        "direccion_place_id": (data.get("direccion_place_id") or "").strip()[:200] or None,
        "contacto_nombre": (data.get("contacto_nombre") or "").strip()[:200] or None,
        "contacto_cargo": (data.get("contacto_cargo") or "").strip()[:120] or None,
        "contacto_tel": (data.get("contacto_tel") or "").strip()[:50] or None,
        "contacto_email": (data.get("contacto_email") or "").strip()[:200] or None,
        "contacto_origen": (data.get("contacto_origen") or "").strip()[:40] or None,
        "acceso_ascensor": _ot_tribool(data.get("acceso_ascensor")),
        "acceso_estacionamiento": _ot_tribool(data.get("acceso_estacionamiento")),
        "acceso_piso": (data.get("acceso_piso") or "").strip()[:50] or None,
        "acceso_notas": (data.get("acceso_notas") or "").strip()[:2000] or None,
    }


def _ot_limpiar_huerfanos(cid):
    """Cancela levantamientos huérfanos (borrador/en_curso sin OT viva)
    del cliente. Nunca bloquea la creación por esto."""
    try:
        huerfanos = mysql_fetchall(
            "SELECT l.id "
            "  FROM mant_levantamientos l "
            "  LEFT JOIN mant_visitas v ON v.id = l.visita_id "
            " WHERE l.cliente_id=%s "
            "   AND l.estado IN ('borrador','en_curso') "
            "   AND (v.id IS NULL OR v.estado IN ('cancelada','anulada'))",
            (cid,)
        ) or []
        if huerfanos:
            ids = [int(r["id"]) for r in huerfanos]
            ph = ",".join(["%s"] * len(ids))
            mysql_execute(
                f"UPDATE mant_levantamientos SET estado='cancelado', "
                f"        fecha_cierre=NOW() "
                f" WHERE id IN ({ph})",
                tuple(ids)
            )
            print(f"[lev_crear] {len(ids)} levantamiento(s) huérfano(s) auto-cancelados: {ids}", flush=True)
    except Exception as e:
        print(f"[lev_crear] limpieza huérfanos falló: {e}", flush=True)


def _ot_aplicar_plantilla_a_equipos(visita_id, tarea_tipo, plantilla_id, mq_ids):
    """Clona los items de la plantilla como tareas de la OT para CADA
    máquina de mq_ids. DEDUP por (visita_id, plantilla_id, maquina_id):
    si ya existe, se salta esa máquina -- evita duplicar cuando la misma
    plantilla se aplica dos veces (estándar + extra explícita). Retorna
    n items creados; nunca lanza (best-effort, en su propia conexión)."""
    if not plantilla_id or not mq_ids:
        return 0
    items_plant = mysql_fetchall(
        "SELECT * FROM mant_tarea_plantilla_items "
        "WHERE plantilla_id=%s ORDER BY orden, id",
        (plantilla_id,)
    ) or []
    if not items_plant:
        return 0
    conn2 = get_mysql()
    n_added = 0
    try:
        with conn2.cursor() as cur2:
            cur2.execute(
                "SELECT COALESCE(MAX(orden),0) AS mx "
                "FROM mant_visita_tareas WHERE visita_id=%s",
                (visita_id,)
            )
            next_orden = int((cur2.fetchone() or {}).get("mx") or 0)
            for mq_id in mq_ids:
                cur2.execute(
                    "SELECT COUNT(*) AS n FROM mant_visita_tareas "
                    " WHERE visita_id=%s AND plantilla_id=%s AND maquina_id=%s",
                    (visita_id, plantilla_id, mq_id)
                )
                if ((cur2.fetchone() or {}).get("n") or 0) > 0:
                    print(f"[lev_crear] DEDUP — plantilla {plantilla_id} ya aplicada "
                          f"a máquina {mq_id} en visita {visita_id}, skip", flush=True)
                    continue
                m_row = mysql_fetchone(
                    "SELECT nombre, serie FROM mant_maquinas WHERE id=%s", (mq_id,))
                m_nombre = m_row.get("nombre") if m_row else f"#{mq_id}"
                for it in items_plant:
                    next_orden += 1
                    sufijo = m_nombre
                    if m_row and m_row.get("serie"):
                        sufijo += f" (S/N: {m_row['serie']})"
                    titulo_full = f"{it['titulo']} — {sufijo}"[:300]
                    cur2.execute(
                        "INSERT INTO mant_visita_tareas "
                        "(visita_id, orden, titulo, descripcion, tipo, "
                        " maquina_id, plantilla_id, tipo_respuesta, target_field, "
                        " obligatoria, requiere_foto, unidad, rango_min, rango_max, "
                        " opciones_lista_json, estado_trabajo, created_by) "
                        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,"
                        "        %s,%s,%s,%s,%s,'pendiente',%s)",
                        (visita_id, next_orden, titulo_full,
                         it.get("descripcion"), tarea_tipo, mq_id, plantilla_id,
                         it.get("tipo_respuesta") or "check",
                         # target_field: mapeo respuesta -> campo de la ficha del
                         # equipo. Sin esto, el checklist aplicado AL CREAR la OT
                         # no alimentaba la ficha.
                         it.get("target_field"),
                         it.get("obligatoria") or 0,
                         it.get("requiere_foto") or 0,
                         it.get("unidad"), it.get("rango_min"), it.get("rango_max"),
                         it.get("opciones_lista_json"), current_username())
                    )
                    n_added += 1
        conn2.commit()
    finally:
        conn2.close()
    return n_added


def _ot_aplicar_plantilla_a_equipo_sin_ficha(visita_id, tarea_tipo, plantilla_id, m):
    """Igual que _ot_aplicar_plantilla_a_equipos, pero para un equipo
    declarado en el ticket que TODAVÍA no tiene fila en mant_maquinas
    (m['id'] es None). No hay ficha de la que leer nombre/serie -- se usan
    los datos del propio ticket; las tareas quedan con maquina_id=NULL."""
    if not plantilla_id:
        return 0
    items_plant = mysql_fetchall(
        "SELECT * FROM mant_tarea_plantilla_items "
        "WHERE plantilla_id=%s ORDER BY orden, id",
        (plantilla_id,)
    ) or []
    if not items_plant:
        return 0
    sufijo = (m.get("nombre") or "equipo")[:240]
    if m.get("serie"):
        sufijo += f" (S/N: {m['serie']})"
    conn3 = get_mysql()
    n_added = 0
    try:
        with conn3.cursor() as cur3:
            cur3.execute(
                "SELECT COALESCE(MAX(orden),0) AS mx "
                "FROM mant_visita_tareas WHERE visita_id=%s", (visita_id,))
            next_orden = int((cur3.fetchone() or {}).get("mx") or 0)
            for it in items_plant:
                next_orden += 1
                titulo_full = f"{it['titulo']} — {sufijo}"[:300]
                cur3.execute(
                    "INSERT INTO mant_visita_tareas "
                    "(visita_id, orden, titulo, descripcion, tipo, "
                    " maquina_id, plantilla_id, tipo_respuesta, target_field, "
                    " obligatoria, requiere_foto, unidad, rango_min, rango_max, "
                    " opciones_lista_json, estado_trabajo, created_by) "
                    "VALUES (%s,%s,%s,%s,%s,NULL,%s,%s,%s,%s,"
                    "        %s,%s,%s,%s,%s,'pendiente',%s)",
                    (visita_id, next_orden, titulo_full,
                     it.get("descripcion"), tarea_tipo, plantilla_id,
                     it.get("tipo_respuesta") or "check", it.get("target_field"),
                     it.get("obligatoria") or 0, it.get("requiere_foto") or 0,
                     it.get("unidad"), it.get("rango_min"), it.get("rango_max"),
                     it.get("opciones_lista_json"), current_username())
                )
                n_added += 1
        conn3.commit()
    finally:
        conn3.close()
    return n_added


def _ot_resolver_checklist(cid, visita_id, tipo_ot, tarea_tipo, maquinas, equipo_ids,
                            plantilla_id_override, plantillas_por_equipo,
                            plantillas_por_ticket_equipo):
    """Aplica TODO el checklist de la OT ya creada (post-commit,
    defensivo -- cada pieza en su propia conexión, un fallo puntual no
    tumba la respuesta). Retorna items_plantilla (int, total de tareas
    creadas por plantilla, sin contar la tarea de respaldo legacy que
    pudo haberse insertado dentro de la transacción principal).

    Orden real de negocio:
      1. Selección explícita del Paso 5 -- solo cuenta si de verdad tiene
         ítems (una plantilla recién creada y vacía NO cuenta -- fix
         2026-08-13).
      2. Plantilla estándar/por-clasificación del tipo -- se aplica para
         cada equipo que NO tenga una selección explícita válida (fix
         2026-08-13 #2, Daniel en vivo: "debe predominar SOLAMENTE la
         plantilla que selecciona el usuario en el modal" -- el intento
         anterior la dejaba aditiva para no volver a dejar OTs sin
         checklist, pero terminaba sumando UN SEGUNDO checklist encima del
         que el usuario sí eligió a mano para ese equipo puntual). Un
         equipo con selección explícita vacía (sin ítems) SIGUE cayendo
         acá -- la protección original no se pierde, solo se vuelve
         exclusiva por equipo en vez de "siempre todos".
         Nunca adivina con el checklist de otra máquina (fix 2026-08-13,
         _plantilla_estandar_para_tipo ya solo mira su lista explícita de
         genéricas reales).
      3. Extra por equipo (maquina_id real) y por ticket_equipo (equipo
         sin ficha) -- deduplicado por (visita_id, plantilla_id,
         maquina_id). Para equipos SIN selección explícita esto no agrega
         nada (plantillas_por_equipo no trae esa key); para los que SÍ
         tienen, es lo único que se les aplica (paso 2 ya los excluyó).
      4. Equipos sin ficha que no recibieron ninguna plantilla extra:
         tarea genérica "📋 {tipo}: {nombre}".
      5. Red de seguridad final: si tras todo lo anterior no se creó
         NINGUNA tarea, tarea de respaldo por cada equipo con ficha real
         (caso Vitacura 2026-05-22 -- plantilla resuelta pero vacía).
    """
    items_plantilla = 0

    # 1) Validar que las plantillas explícitas (Paso 5) de verdad tengan
    #    ítems -- si no, no cuentan para decidir si "ya hay checklist" NI
    #    para excluir al equipo del paso 2 (fix 2026-08-13 #2: el chequeo
    #    pasa a ser por plantilla_id individual, no solo agregado, porque
    #    el paso 2 necesita saber CUÁL equipo tiene una selección válida).
    #    Nota: en el flujo normal esto ya no debería encontrar ninguna
    #    vacía -- _ot_validar_plantillas_elegidas la rechaza ANTES de crear
    #    la OT -- pero se mantiene como red de seguridad para llamadas que
    #    no pasan por ese gate (o datos legacy).
    ids_explicitas = sorted({
        pid for pids in list(plantillas_por_equipo.values())
        + list(plantillas_por_ticket_equipo.values())
        for pid in pids
    })
    pids_con_items = _plantillas_con_items(ids_explicitas)
    if ids_explicitas:
        vacias = [pid for pid in ids_explicitas if pid not in pids_con_items]
        if vacias:
            print(f"[lev_crear] plantillas explícitas {vacias} NO tienen items "
                  f"-- se ignoran, el equipo cae a la estándar/por-clasificación.", flush=True)
    explicitas_con_items = bool(pids_con_items)

    # Equipos (maquina_id real) con AL MENOS una selección explícita VÁLIDA
    # -- se excluyen del paso 2: para ellos manda solo lo que el usuario
    # eligió (paso 3 más abajo), no se les suma la estándar/por-clasificación.
    mids_con_seleccion_valida = {
        mid for mid, pids in plantillas_por_equipo.items()
        if any(pid in pids_con_items for pid in pids)
    }

    # 2) Resolver plantilla estándar/por-clasificación SOLO para equipos
    #    CON ficha que el usuario NO seleccionó a mano (ver arriba).
    # 🔒 2026-08-28 (Daniel, caso OT-2026-00125, misma noche): "si no está
    # gestionado, no lo asigne, solamente déjalo sin clasificar hasta que
    # alguien lo clasifique... si avanza y no tiene clasificación, hay que
    # restringir ese avance". Aplica SOLO a instalación/mantención/visitas
    # (confirmado explícito: "el trabajo interno no aplica a los demás hasta
    # el momento") -- para esas categorías, un producto sin clasificar YA NO
    # cae al checklist genérico de ~30 ítems (eso era lo que dejaba OT-125
    # con 8 equipos en el checklist equivocado sin ninguna señal de que
    # faltaba clasificar). En su lugar queda en `equipos_sin_clasificar`
    # (ver más abajo: se excluye de TODA capa de fallback, incluida la red
    # de seguridad final, y se marca en mant_visita_equipos para que siga
    # visible en la OT como "Sin clasificar" en vez de desaparecer.
    _categoria_gate = _categoria_admin_para_tipo(tipo_ot)
    _gate_sin_clasificar_activo = _categoria_gate in ("instalacion", "mantencion", "visitas")
    equipos_sin_clasificar = set()
    resolucion_por_equipo = {}
    try:
        if plantilla_id_override:
            for mm in maquinas:
                if mm.get("id") and mm["id"] not in mids_con_seleccion_valida:
                    resolucion_por_equipo[mm["id"]] = plantilla_id_override
        else:
            fallback_cache = {"val": None, "computed": False}
            def _fallback_tipo_ot():
                if not fallback_cache["computed"]:
                    fallback_cache["val"] = _plantilla_estandar_para_tipo(tipo_ot)
                    fallback_cache["computed"] = True
                return fallback_cache["val"]
            for mm in maquinas:
                mid = mm.get("id")
                if not mid or mid in mids_con_seleccion_valida:
                    continue
                plant_id = None
                try:
                    plant_id = _plantilla_por_clasificacion_sku(mm.get("sku"), tipo_ot)
                except Exception as e:
                    print(f"[lev_crear] resolver plantilla por clasificación falló "
                          f"para maquina {mid}: {e}", flush=True)
                if not plant_id and _gate_sin_clasificar_activo:
                    equipos_sin_clasificar.add(mid)
                    continue
                resolucion_por_equipo[mid] = plant_id or _fallback_tipo_ot()
        tiene_plantillas = any(resolucion_por_equipo.values()) or explicitas_con_items
    except Exception as e:
        print(f"[lev_crear] resolución de plantilla por equipo falló: {e}", flush=True)
        resolucion_por_equipo = {}
        tiene_plantillas = explicitas_con_items

    # 3) Aplicar la estándar/por-clasificación, agrupada por plantilla_id
    #    (un mismo tipo de OT con una trotadora y una bicicleta aplica DOS
    #    checklists distintos, no uno elegido a ciegas). Los equipos con
    #    selección explícita válida (mids_con_seleccion_valida) NUNCA
    #    entran acá -- ni siquiera vía "faltantes".
    if visita_id and equipo_ids:
        try:
            resolucion = dict(resolucion_por_equipo)
            faltantes = [mid for mid in equipo_ids
                         if mid not in resolucion and mid not in mids_con_seleccion_valida
                         and mid not in equipos_sin_clasificar]
            if faltantes:
                plant_fallback = plantilla_id_override or _plantilla_estandar_para_tipo(tipo_ot)
                for mid in faltantes:
                    resolucion[mid] = plant_fallback
            grupos = {}
            for mid, plant_id in resolucion.items():
                if plant_id:
                    grupos.setdefault(plant_id, []).append(mid)
            if grupos:
                for plant_id, mids_grupo in grupos.items():
                    n = _ot_aplicar_plantilla_a_equipos(visita_id, tarea_tipo, plant_id, mids_grupo)
                    items_plantilla += n
                    print(f"[lev_crear] plantilla {plant_id} aplicada a "
                          f"{len(mids_grupo)} equipo(s) → {n} tarea(s) "
                          f"(tipo '{tipo_ot}')", flush=True)
            else:
                print(f"[lev_crear] sin plantilla (ni por clasificación ni estándar) "
                      f"para el tipo '{tipo_ot}' — se usará la tarea de respaldo "
                      f"por equipo", flush=True)
        except Exception as e:
            print(f"[lev_crear] aplicar plantilla estándar falló: {e}", flush=True)

    # 4) Extra por equipo CON ficha (maquina_id real) -- para los mids en
    #    mids_con_seleccion_valida, esto es la ÚNICA plantilla que reciben
    #    (paso 2 ya los excluyó de la estándar/por-clasificación).
    if visita_id and plantillas_por_equipo:
        try:
            for mid, pids in plantillas_por_equipo.items():
                if mid not in equipo_ids:
                    continue
                for pid in pids:
                    try:
                        n_extra = _ot_aplicar_plantilla_a_equipos(visita_id, tarea_tipo, pid, [mid])
                        items_plantilla += n_extra
                        print(f"[lev_crear] plantilla explícita {pid} (equipo {mid}) "
                              f"→ {n_extra} tarea(s)", flush=True)
                    except Exception as e:
                        print(f"[lev_crear] plantilla extra {pid} para mid {mid} falló: {e}", flush=True)
        except Exception as e:
            print(f"[lev_crear] plantillas extra fallaron: {e}", flush=True)

    # 5) Extra por equipo SIN ficha (ticket_equipo_id). Solo indexa
    #    entradas de `maquinas` sin id real -- nunca confía en un
    #    ticket_equipo_id ajeno al de esta misma OT.
    equipos_ticket_con_extra = set()
    if visita_id and plantillas_por_ticket_equipo:
        try:
            equipos_by_teq = {
                m.get("ticket_equipo_id"): m for m in maquinas
                if not m.get("id") and m.get("ticket_equipo_id")
            }
            for teq_id, pids in plantillas_por_ticket_equipo.items():
                m = equipos_by_teq.get(teq_id)
                if not m:
                    continue
                for pid in pids:
                    try:
                        n = _ot_aplicar_plantilla_a_equipo_sin_ficha(visita_id, tarea_tipo, pid, m)
                        items_plantilla += n
                        if n:
                            equipos_ticket_con_extra.add(teq_id)
                    except Exception as e:
                        print(f"[lev_crear] plantilla extra {pid} para ticket_equipo "
                              f"{teq_id} falló: {e}", flush=True)
        except Exception as e:
            print(f"[lev_crear] plantillas extra (equipos sin ficha) fallaron: {e}", flush=True)

    # 6) Equipos sin ficha que NO recibieron plantilla extra: tarea
    #    genérica -- sin esto quedarían con 0 tareas (las de arriba solo
    #    cubren equipo_ids reales).
    equipos_sin_maquina = [
        m for m in maquinas if not m.get("id")
        and m.get("ticket_equipo_id") not in equipos_ticket_con_extra
    ]
    if visita_id and equipos_sin_maquina:
        try:
            conn_tk = get_mysql()
            try:
                with conn_tk.cursor() as cur_tk:
                    cur_tk.execute(
                        "SELECT COALESCE(MAX(orden),0) AS mx "
                        "FROM mant_visita_tareas WHERE visita_id=%s", (visita_id,))
                    orden = int((cur_tk.fetchone() or {}).get("mx") or 0)
                    for m in equipos_sin_maquina:
                        orden += 1
                        nombre_tk = (m.get("nombre") or "equipo")[:240]
                        titulo_tk = f"📋 {tipo_ot.capitalize()}: {nombre_tk}"
                        if m.get("serie"):
                            titulo_tk += f" (S/N: {m['serie']})"
                        cur_tk.execute(
                            "INSERT INTO mant_visita_tareas "
                            "(visita_id, orden, titulo, descripcion, maquina_id, "
                            " tipo, tipo_respuesta, obligatoria, requiere_foto, "
                            " estado_trabajo, created_by) "
                            "VALUES (%s,%s,%s,%s,NULL,%s,'foto',1,1,'pendiente',%s)",
                            (visita_id, orden, titulo_tk[:300],
                             "Equipo declarado en el ticket, sin ficha previa en "
                             "Mantenciones (cliente/equipo nuevo).",
                             tarea_tipo, current_username() or 'sistema')
                        )
                        items_plantilla += 1
                conn_tk.commit()
            finally:
                conn_tk.close()
        except Exception as e:
            print(f"[lev_crear] tareas equipos sin ficha (ticket) fallaron: {e}", flush=True)

    # 7) Red de seguridad final (caso Vitacura 2026-05-22): si tras TODO
    #    lo anterior no se creó ninguna tarea Y la OT no tiene ninguna
    #    tarea legacy tampoco, cada equipo con ficha real recibe su tarea
    #    de respaldo. Idempotente: solo corre si de verdad hay 0 tareas.
    #
    # 2026-08-13 (hallazgo "importante" de la verificación adversarial):
    # antes esto releía mant_maquinas filtrando SOLO por equipo_ids, que
    # deja afuera los equipos que llegaron por `equipos_ticket` con
    # maquina_id YA EXISTENTE (ficha previa) -- esos entran a `maquinas`
    # pero nunca a `equipo_ids` (ver _ot_resolver_equipos). El código viejo
    # sí los cubría (su fallback pre-commit recorría TODOS los elementos de
    # `maquinas` con id real). Se filtra directo sobre `maquinas` -- ya
    # disponible en memoria, sin re-consultar -- para igualar esa cobertura.
    if visita_id and items_plantilla == 0:
        try:
            existentes = mysql_fetchone(
                "SELECT COUNT(*) AS n FROM mant_visita_tareas WHERE visita_id=%s",
                (visita_id,)) or {}
            maqs = []
            vistos_fb = set()
            for m in maquinas:
                mid = m.get("id")
                if mid and mid not in vistos_fb and mid not in equipos_sin_clasificar:
                    vistos_fb.add(mid)
                    maqs.append(m)
            maqs.sort(key=lambda m: m["id"])
            if int(existentes.get("n") or 0) == 0 and maqs:
                conn_fb = get_mysql()
                try:
                    with conn_fb.cursor() as cur_fb:
                        for idx, m in enumerate(maqs, 1):
                            t_fb, d_fb = _tarea_respaldo_texto(tipo_ot, m.get("nombre"))
                            cur_fb.execute(
                                "INSERT INTO mant_visita_tareas "
                                "(visita_id, orden, titulo, descripcion, maquina_id, "
                                " tipo, tipo_respuesta, obligatoria, requiere_foto, "
                                " estado_trabajo, created_by) "
                                "VALUES (%s,%s,%s,%s,%s,%s,'foto',1,1,'pendiente',%s)",
                                (visita_id, idx, t_fb, d_fb, m["id"], tarea_tipo,
                                 current_username() or 'sistema')
                            )
                            items_plantilla += 1
                    conn_fb.commit()
                    print(f"[lev_crear] fallback aplicado vid={visita_id} "
                          f"({len(maqs)} tarea(s) de respaldo) — plantilla del "
                          f"tipo '{tipo_ot}' sin items.", flush=True)
                finally:
                    conn_fb.close()
        except Exception as e:
            print(f"[lev_crear] fallback safety-net falló: {e}", flush=True)

    # 8) Equipos deliberadamente sin plantilla (producto sin clasificar,
    #    ver punto 2 más arriba): sin esto desaparecerían de la OT, porque
    #    ot2_detalle solo lista equipos con tareas O con fila en
    #    mant_visita_equipos (ni una cosa ni la otra sin este INSERT).
    #    ON DUPLICATE por si el equipo ya tenía fila por otro motivo (no se
    #    pisa estado_revision/observación existentes, solo se prende el flag).
    if visita_id and equipos_sin_clasificar:
        try:
            for mid in equipos_sin_clasificar:
                mysql_execute(
                    "INSERT INTO mant_visita_equipos (visita_id, maquina_id, sin_clasificar) "
                    "VALUES (%s, %s, 1) "
                    "ON DUPLICATE KEY UPDATE sin_clasificar=1",
                    (visita_id, mid)
                )
            print(f"[lev_crear] {len(equipos_sin_clasificar)} equipo(s) marcados "
                  f"sin_clasificar (sin checklist genérico) en vid={visita_id}", flush=True)
        except Exception as e:
            print(f"[lev_crear] marcar equipos_sin_clasificar falló: {e}", flush=True)

    return items_plantilla


def _ot_crear_registro(conn, cur, cid, tipo_ot, tarea_tipo, titulo, notas, descubrimiento,
                        equipo_ids, equipos_ticket_clean, agenda, tecnico_ids,
                        tecnico_principal, aplica_garantia, dir_contacto):
    """Corre DENTRO de la transacción principal (mismo cursor `cur`, mismo
    `conn` que hace conn.commit()/rollback() el caller). Crea, si aplica,
    mant_levantamientos + items, y SIEMPRE la OT espejo en mant_visitas +
    multi-técnico. Retorna dict: visita_id, lev_id, numero_ot, maquinas,
    n_items.

    DOS FASES CON MANEJO DE ERRORES DISTINTO (bug real encontrado por
    verificación adversarial 2026-08-13 -- ver git blame/historial de este
    comentario si hace falta el detalle completo del hallazgo):

    FASE 1 -- levantamiento + items + total_equipos: SIN try/except
    propio, A PROPÓSITO. Si algo acá falla, la excepción debe PROPAGAR
    hasta el try/except del caller (_mant_lev_crear_ot_core) para abortar
    TODA la transacción (rollback + 500 real) -- exactamente igual que el
    código original, donde estas sentencias vivían fuera de cualquier
    try. NO envolver esta fase en un try/except que la trague: la primera
    versión de esta reconstrucción sí lo hizo, y eso convertía un fallo
    real de base de datos en un HTTP 200 {"ok":true, ...:null} mintiendo
    éxito, mientras un levantamiento a medio poblar podía quedar
    comiteado sin auditar.

    FASE 2 -- OT espejo (mant_visitas + multi-técnico): "blanda" a
    propósito, mismo alcance exacto que el `except Exception as e_ot` del
    código original. Si algo acá falla, lev_id/numero_ot/maquinas/n_items
    YA CALCULADOS en la Fase 1 se devuelven igual, con visita_id=None --
    el levantamiento queda comiteado (huérfano; se autolimpia solo en la
    siguiente llamada a _ot_limpiar_huerfanos) pero esta función NO
    lanza, y el caller puede auditar/responder con los datos reales que
    sí existen en vez de perderlos."""
    tecnico_nombre = ""
    if tecnico_principal:
        u = mysql_fetchone(
            "SELECT COALESCE(nombre, username) AS nm FROM app_users WHERE id=%s",
            (tecnico_principal,))
        if u:
            tecnico_nombre = u["nm"]
    if not tecnico_nombre:
        tecnico_nombre = current_username() or ""

    # ── Levantamiento (solo si tipo_ot='levantamiento') ──
    lev_id = None
    if tipo_ot == "levantamiento":
        if _LEV_MODALIDAD_CAPTURA_COL_EXISTE:
            cur.execute(
                "INSERT INTO mant_levantamientos "
                "(cliente_id, tecnico, titulo, notas, estado, created_by, modalidad_captura) "
                "VALUES (%s,%s,%s,%s,'en_curso',%s,%s)",
                (cid, tecnico_nombre[:190], titulo, notas, current_username() or 'sistema',
                 'descubrimiento' if descubrimiento else 'ficha')
            )
        else:
            cur.execute(
                "INSERT INTO mant_levantamientos "
                "(cliente_id, tecnico, titulo, notas, estado, created_by) "
                "VALUES (%s,%s,%s,%s,'en_curso',%s)",
                (cid, tecnico_nombre[:190], titulo, notas, current_username() or 'sistema')
            )
        lev_id = cur.lastrowid

    # ── Equipos: mant_maquinas reales (equipo_ids) + equipos del ticket
    #    sin ficha (equipos_ticket_clean). n_items SIEMPRE se calcula,
    #    para CUALQUIER tipo de OT -- el INSERT en mant_levantamiento_
    #    items (columna NOT NULL con FK) solo corre si lev_id existe. ──
    maquinas = []
    if equipo_ids:
        ph = ",".join(["%s"] * len(equipo_ids))
        cur.execute(
            f"SELECT id, nombre, sku, serie, doc_fecha FROM mant_maquinas "
            f"WHERE id IN ({ph}) AND cliente_id=%s",
            tuple(list(equipo_ids) + [cid])
        )
        maquinas = cur.fetchall() or []
    if equipos_ticket_clean:
        maquinas = list(maquinas) + equipos_ticket_clean
    n_items = len(maquinas)
    if lev_id:
        for m in maquinas:
            cur.execute(
                "INSERT INTO mant_levantamiento_items "
                "(levantamiento_id, maquina_id, nombre_snap, sku_snap, serie_snap, fecha_documento) "
                "VALUES (%s,%s,%s,%s,%s,%s)",
                (lev_id, m.get("id"), m.get("nombre"), m.get("sku"), m.get("serie"), m.get("doc_fecha"))
            )
        cur.execute(
            "UPDATE mant_levantamientos SET total_equipos=%s WHERE id=%s",
            (n_items, lev_id)
        )

    # ── Número de OT atómico, en la MISMA transacción del INSERT de abajo.
    #    Try/except propio e independiente (fallback al número por
    #    timestamp) -- NO es parte del alcance "blando" de la Fase 2 de
    #    abajo, ya tenía su propio fallback en el código original. ──
    try:
        numero_ot = _next_ot_number_atomic(conn)
    except Exception:
        numero_ot = f"LEV-{int(time.time())}"

    # ══ FASE 2 -- OT espejo (mant_visitas + multi-técnico): "blanda" ══
    # Ver docstring de la función para el porqué de este alcance exacto.
    visita_id = None
    try:
        visita_id = _ot_crear_visita_espejo(
            conn, cur, cid, tipo_ot, tarea_tipo, titulo, notas, n_items,
            numero_ot, agenda, tecnico_ids, tecnico_principal, lev_id,
            aplica_garantia, dir_contacto,
        )
    except Exception as e_ot:
        print(f"[lev_crear] no se pudo crear OT espejo: {e_ot}", flush=True)
        visita_id = None

    return {
        "visita_id": visita_id, "lev_id": lev_id, "numero_ot": numero_ot,
        "maquinas": maquinas, "n_items": n_items,
    }


def _ot_crear_visita_espejo(conn, cur, cid, tipo_ot, tarea_tipo, titulo, notas, n_items,
                             numero_ot, agenda, tecnico_ids, tecnico_principal, lev_id,
                             aplica_garantia, dir_contacto):
    """FASE 2 de _ot_crear_registro, extraída aparte para que su try/except
    "blando" (en el caller) tenga un límite claro y visible: TODO lo de
    acá adentro es tolerante a fallos desde la perspectiva del caller,
    NADA de la Fase 1 (levantamiento/items, ya ejecutada antes de
    llamar a esta función) lo es. Retorna visita_id (lastrowid)."""
    tipo_prefix = _OT_TIPO_PREFIJO.get(tipo_ot, '[OT]')
    if aplica_garantia:
        tipo_prefix = tipo_prefix + ' 🛡️'
    if tipo_ot == 'levantamiento':
        modalidad = 'sin_costo'
    elif aplica_garantia:
        modalidad = 'garantia'
    else:
        modalidad = 'pagado'

    u_creador = getattr(g, "user", None) or {}
    try:
        cre_uid = int(u_creador.get("id")) if u_creador.get("id") else None
    except (TypeError, ValueError):
        cre_uid = None

    descripcion = (
        f"OT tipo {tipo_ot} con {n_items} equipo(s). "
        f"{'Multi-técnico (' + str(len(tecnico_ids)) + ' asignados)' if len(tecnico_ids) > 1 else ''}"
    )
    # NOTA: fecha_realizada, estado y prioridad son LITERALES en el SQL
    # (NULL / 'programada' / 'media'), NO parámetros -- una OT recién
    # creada nunca trae fecha_realizada poblada (solo se llena al
    # CERRARLA), siempre nace 'programada' y en prioridad 'media'. No se
    # deben mezclar con los %s reales: escribir el SQL a mano acá, en vez
    # de armar el conteo de placeholders con una fórmula genérica, es lo
    # que evita que ese detalle se pierda en un futuro cambio.
    _visita_vals_base = (
        numero_ot, cid, f"{tipo_prefix} {titulo}"[:200],
        agenda["fecha_prog"], agenda["fecha_fin"], agenda["hora_ini"], agenda["hora_fin"],
        tipo_ot, modalidad,
        descripcion, tecnico_principal, lev_id, current_username(),
        dir_contacto["direccion_visita"], dir_contacto["direccion_lat"],
        dir_contacto["direccion_lng"], dir_contacto["direccion_place_id"],
        dir_contacto["contacto_nombre"], dir_contacto["contacto_cargo"],
        dir_contacto["contacto_tel"], dir_contacto["contacto_email"], dir_contacto["contacto_origen"],
        dir_contacto["acceso_ascensor"], dir_contacto["acceso_estacionamiento"],
        dir_contacto["acceso_piso"], dir_contacto["acceso_notas"],
    )
    try:
        # created_by_user_id: FK estable a app_users.id (2026-05-22). Si la
        # migración no corrió aún en este entorno, cae al INSERT sin esa
        # columna -- nunca bloquea la creación de la OT por esto.
        cur.execute(
            "INSERT INTO mant_visitas "
            "(numero_ot, cliente_id, titulo, fecha_programada, "
            " fecha_realizada, fecha_fin, hora_inicio, hora_fin, "
            " tipo, estado, modalidad_cobro, prioridad, "
            " descripcion, tecnico_user_id, levantamiento_id, created_by, created_by_user_id, "
            " direccion_visita, direccion_lat, direccion_lng, direccion_place_id, "
            " contacto_nombre, contacto_cargo, contacto_tel, contacto_email, contacto_origen, "
            " acceso_ascensor, acceso_estacionamiento, acceso_piso, acceso_notas) "
            "VALUES (%s,%s,%s,%s,NULL,%s,%s,%s,"
            " %s,'programada',%s,'media',"
            " %s,%s,%s,%s,%s,"
            " %s,%s,%s,%s,"
            " %s,%s,%s,%s,%s,"
            " %s,%s,%s,%s)",
            # created_by_user_id va DESPUÉS de created_by en la lista de
            # columnas (no después de modalidad_cobro) -- índice 13 de
            # _visita_vals_base es current_username() (created_by).
            _visita_vals_base[:13] + (cre_uid,) + _visita_vals_base[13:]
        )
    except Exception as e_ins:
        print(f"[lev_crear] INSERT con created_by_user_id falló ({e_ins}); "
              f"reintentando sin la columna", flush=True)
        cur.execute(
            "INSERT INTO mant_visitas "
            "(numero_ot, cliente_id, titulo, fecha_programada, "
            " fecha_realizada, fecha_fin, hora_inicio, hora_fin, "
            " tipo, estado, modalidad_cobro, prioridad, "
            " descripcion, tecnico_user_id, levantamiento_id, created_by, "
            " direccion_visita, direccion_lat, direccion_lng, direccion_place_id, "
            " contacto_nombre, contacto_cargo, contacto_tel, contacto_email, contacto_origen, "
            " acceso_ascensor, acceso_estacionamiento, acceso_piso, acceso_notas) "
            "VALUES (%s,%s,%s,%s,NULL,%s,%s,%s,"
            " %s,'programada',%s,'media',"
            " %s,%s,%s,%s,"
            " %s,%s,%s,%s,"
            " %s,%s,%s,%s,%s,"
            " %s,%s,%s,%s)",
            _visita_vals_base
        )
    visita_id = cur.lastrowid
    if lev_id:
        cur.execute("UPDATE mant_levantamientos SET visita_id=%s WHERE id=%s", (visita_id, lev_id))

    if tecnico_ids:
        for tuid in tecnico_ids:
            try:
                cur.execute(
                    "INSERT IGNORE INTO mant_visita_tecnicos "
                    "(visita_id, tecnico_id, tecnico_user_id, rol) "
                    "VALUES (%s, NULL, %s, %s)",
                    (visita_id, tuid, 'lider' if tuid == tecnico_principal else 'tecnico')
                )
            except Exception as e:
                print(f"[lev_crear] mant_visita_tecnicos insert falló para uid={tuid}: {e}", flush=True)

    return visita_id


def _mant_lev_crear_ot_core(cid, data, ticket_id=None):
    """Nucleo compartido de creacion de Levantamiento/OT. Usado por:
      - POST /mantenciones/api/clientes/<cid>/levantamientos (modal real
        de Mantenciones, #modalLevSelector).
      - Wrapper "Generar OT" de Tickets (tickets_module.tk_api_generar_ot),
        que arma el mismo payload y pasa `ticket_id` para vincular
        tk_tickets.visita_id DENTRO de la misma transaccion.

    Devuelve (payload:dict, http_status:int) -- el caller HTTP hace
    jsonify(payload), status.
    """
    _ot_limpiar_huerfanos(cid)

    titulo = (data.get("titulo") or "").strip()[:200] or f"Levantamiento {_now_chile_str('%d/%m/%Y')}"
    notas = (data.get("notas") or "").strip()
    tipo_ot, tarea_tipo = _ot_resolver_tipo(data)
    descubrimiento = bool(data.get("descubrimiento")) and tipo_ot == "levantamiento"

    eq = _ot_resolver_equipos(cid, data, tipo_ot, ticket_id)
    equipo_ids = eq["equipo_ids"]
    equipos_ticket_clean = eq["equipos_ticket_clean"]
    equipos_excluidos = eq["equipos_excluidos"]
    altas_automaticas = eq["altas_automaticas"]

    if not equipo_ids and not descubrimiento and not equipos_ticket_clean:
        if equipos_excluidos:
            return {
                "ok": False,
                "error": (
                    f"Ningún equipo pudo agregarse: {len(equipos_excluidos)} "
                    "producto(s) no tienen ficha registrada para este cliente. Fuera de "
                    "un levantamiento, ILUS no crea tareas para equipos sin ficha -- "
                    "regístralos primero en la ficha del cliente, o genera un "
                    "Levantamiento por descubrimiento para conocerlos en terreno."
                ),
                "error_codigo": "EQUIPO_SIN_FICHA",
                "equipos_excluidos": equipos_excluidos,
            }, 400
        return {
            "ok": False,
            "error": "Debes seleccionar al menos 1 equipo para el levantamiento.",
            "error_codigo": "SIN_EQUIPOS",
        }, 400

    agenda = _ot_resolver_agenda(data)
    tecnico_ids, tecnico_principal = _ot_resolver_tecnicos(data)
    plantilla_id_override = _ot_resolver_plantilla_override(data)
    plantillas_por_equipo, plantillas_por_ticket_equipo = _ot_resolver_plantillas_payload(data)
    # El usuario elige la plantilla ANTES de que exista ficha (key teq_<id>,
    # ver _ot_resolver_plantillas_payload); si ese equipo se dio de alta
    # automática en _ot_resolver_equipos recién arriba, remapear su
    # elección al maquina_id real -- si no, _ot_validar_plantillas_elegidas
    # de más abajo lo vería como "sin elegir" aunque el usuario sí eligió.
    for _teq_previo, _mid_nuevo in altas_automaticas.items():
        if _teq_previo in plantillas_por_ticket_equipo:
            plantillas_por_equipo[_mid_nuevo] = plantillas_por_ticket_equipo.pop(_teq_previo)
    aplica_garantia = bool(data.get("aplica_garantia")) and tipo_ot != 'levantamiento'
    dir_contacto = _ot_resolver_direccion_contacto_acceso(data)

    # 2026-08-13 (Daniel, en vivo: "no quiero nada automático, todo lo debe
    # escoger el usuario y si no escoge no lo debe dejar avanzar"): valida
    # ANTES de tocar la base de datos -- si falta una plantilla, la OT ni
    # se empieza a crear (a diferencia de las redes de seguridad de
    # _ot_resolver_checklist, que rellenan DESPUÉS de crear).
    err_plantillas = _ot_validar_plantillas_elegidas(
        tipo_ot, equipo_ids, equipos_ticket_clean, plantilla_id_override,
        plantillas_por_equipo, plantillas_por_ticket_equipo)
    if err_plantillas:
        return err_plantillas, 400

    # 2026-08-13 (verificación adversarial -- bug real encontrado y
    # corregido): este try/except es el ÚNICO nivel de manejo "duro" de
    # errores acá -- si algo dentro de _ot_crear_registro escapa (Fase 1,
    # levantamiento/items: SIN try propio a propósito, ver su docstring),
    # DEBE llegar hasta el except de más abajo (rollback + 500 real),
    # exactamente igual que el código original. NO agregar un try/except
    # intermedio alrededor de esta llamada: eso fue lo que convertía
    # fallos reales de base de datos en un HTTP 200 mintiendo éxito. El
    # manejo "blando" de la OT espejo (Fase 2) ya vive DENTRO de
    # _ot_crear_registro, con el alcance exacto del `e_ot` original.
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            registro = _ot_crear_registro(
                conn, cur, cid, tipo_ot, tarea_tipo, titulo, notas, descubrimiento,
                equipo_ids, equipos_ticket_clean, agenda, tecnico_ids,
                tecnico_principal, aplica_garantia, dir_contacto,
            )
            visita_id = registro["visita_id"]
            lev_id = registro["lev_id"]
            numero_ot = registro["numero_ot"]
            maquinas = registro["maquinas"]
            n_items = registro["n_items"]

            if ticket_id and visita_id:
                try:
                    cur.execute(
                        "UPDATE tk_tickets SET visita_id=%s WHERE id=%s",
                        (visita_id, ticket_id)
                    )
                except Exception as e:
                    print(f"[lev_crear] link tk_tickets.visita_id fallo "
                          f"(ticket_id={ticket_id}): {e}", flush=True)

        conn.commit()

        if ticket_id and visita_id:
            try:
                _tk_set_estado_automatico = globals().get("_tk_set_estado_automatico")
                if _tk_set_estado_automatico:
                    _tk_set_estado_automatico(
                        ticket_id, "ot_generated", f"OT {numero_ot} generada", visita_id=visita_id)
            except Exception as e:
                print(f"[lev_crear] sync estado ticket (ot_generated) fallo "
                      f"(ticket_id={ticket_id}): {e}", flush=True)

        items_plantilla = _ot_resolver_checklist(
            cid, visita_id, tipo_ot, tarea_tipo, maquinas, equipo_ids,
            plantilla_id_override, plantillas_por_equipo, plantillas_por_ticket_equipo,
        ) if visita_id else 0

        try:
            if lev_id:
                _mant_log("levantamiento", lev_id, "creado",
                          f"{n_items} equipo(s) · OT {numero_ot or '—'} · "
                          f"{len(tecnico_ids)} técnico(s) · {items_plantilla} items plantilla")
            elif visita_id:
                _mant_log("visita", visita_id, "creada",
                          f"OT tipo {tipo_ot} · {n_items} equipo(s) · "
                          f"{len(tecnico_ids)} técnico(s) · {items_plantilla} items plantilla")
        except Exception:
            pass

        tipo_ot_label = _OT_TIPO_LABEL_MENSAJE.get(tipo_ot, tipo_ot.replace('_', ' ').capitalize())
        resp = {
            "ok": True,
            "id": lev_id,
            "n_items": n_items,
            "visita_id": visita_id,
            "numero_ot": numero_ot if visita_id else None,
            "ot_url": f"/mantenciones/ot/{visita_id}" if visita_id else None,
            "tecnicos_asignados": len(tecnico_ids),
            "items_plantilla_aplicados": items_plantilla,
            "mensaje": (
                f"{tipo_ot_label}: OT creada con {n_items} equipo(s) e items de "
                f"plantilla aplicados ({items_plantilla} tareas). "
                f"La OT quedó programada para {agenda['fecha_prog']}"
                + (f" {agenda['hora_ini']}" if agenda['hora_ini'] else "")
                + f" — número {numero_ot}."
            ),
        }
        if equipos_excluidos:
            resp["equipos_excluidos"] = equipos_excluidos
        return resp, 200
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        return {"ok": False, "error": str(e)}, 500
    finally:
        try:
            conn.close()
        except Exception:
            pass



@app.route("/mantenciones/api/levantamientos/<int:lid>", methods=["GET", "PATCH", "DELETE"])
@_mant_required
def mant_lev_detalle(lid):
    """GET: detalle + items + fotos.  PATCH: actualizar metadata.  DELETE: cancelar."""
    lev = mysql_fetchone("SELECT * FROM mant_levantamientos WHERE id=%s", (lid,))
    if not lev:
        return jsonify({"ok": False, "error": "Levantamiento no encontrado"}), 404

    # FIX seguridad (peritaje C2 — IDOR): antes solo @_mant_required (permiso
    # genérico) dejaba a cualquier técnico ver/editar/cancelar el levantamiento
    # de un colega adivinando el id. Ver `_lev_puede_accion` línea ~32943.
    _accion_lev = "ver" if request.method == "GET" else "ejecutar"
    if not _lev_puede_accion(lid, _accion_lev, lev_row=lev):
        return _lev_403_response(_accion_lev)

    if request.method == "DELETE":
        if lev["estado"] == "cerrado":
            return jsonify({"ok": False, "error": "No se puede eliminar un levantamiento cerrado"}), 400
        mysql_execute("UPDATE mant_levantamientos SET estado='cancelado' WHERE id=%s", (lid,))
        try: _mant_log("levantamiento", lid, "cancelado", "")
        except Exception: pass
        return jsonify({"ok": True})

    if request.method == "PATCH":
        d = request.get_json(silent=True) or {}
        sets, vals = [], []
        for k in ("titulo", "tecnico", "notas"):
            if k in d:
                sets.append(f"{k}=%s")
                vals.append((d[k] or "")[:500])
        if sets:
            vals.append(lid)
            mysql_execute(f"UPDATE mant_levantamientos SET {', '.join(sets)} WHERE id=%s", tuple(vals))
        return jsonify({"ok": True})

    # GET: items + fotos
    items = mysql_fetchall(
        "SELECT * FROM mant_levantamiento_items WHERE levantamiento_id=%s ORDER BY id",
        (lid,)
    ) or []
    # Fotos por item (1 query batch)
    fotos = mysql_fetchall(
        "SELECT id, item_id, cloudinary_url, tipo_foto, descripcion, created_at "
        "  FROM mant_levantamiento_fotos WHERE levantamiento_id=%s ORDER BY id",
        (lid,)
    ) or []
    fotos_por_item = {}
    for f in fotos:
        fotos_por_item.setdefault(f["item_id"], []).append({
            "id": f["id"],
            "url": f["cloudinary_url"],
            "tipo": f["tipo_foto"],
            "descripcion": f.get("descripcion") or "",
            "created_at": str(f["created_at"])[:16] if f.get("created_at") else "",
        })
    for it in items:
        it["fotos"] = fotos_por_item.get(it["id"], [])
        it["estado_label"] = _lev_estado_label(it.get("estado_capturado", "operativo"))
        # 'modificado_at' (trazabilidad de edición 2026-07-06) también es
        # DATETIME — sin normalizar, jsonify() falla en cuanto un item tenga
        # esta columna poblada (justo el caso que acabamos de habilitar).
        # FIX 2026-08-08 (Daniel: "la fecha está en formato gringo, y la hora
        # no corresponde a la región de Santiago"): antes se hacía
        # str(dt)[:16], que entrega el UTC crudo de MySQL en formato ISO
        # ("2026-08-08 18:53"). REGLA #6: todo datetime de UI pasa por
        # chile_fmt_filter -> "08/08/2026 14:53" en hora de Santiago.
        for k in ('created_at', 'updated_at', 'modificado_at'):
            if it.get(k): it[k] = chile_fmt_filter(it[k])

    lev = dict(lev)
    for k in ('fecha_inicio', 'fecha_cierre', 'created_at', 'updated_at'):
        if lev.get(k): lev[k] = str(lev[k])[:16]
    return jsonify({"ok": True, "levantamiento": lev, "items": items})


@app.route("/mantenciones/api/erp/doc-info", methods=["POST"])
@_mant_required
def mant_erp_doc_info():
    """Consulta liviana de un documento del ERP (read-only, REGLA #4.1) para
    que el TÉCNICO asocie un equipo a su factura de origen desde terreno
    (Daniel 2026-06-23). Devuelve datos mínimos + análisis de RUT contra el
    cliente del levantamiento (informativo, no bloqueante).
    body: {tipo: FCV|FCE|BLV|BLE|GDV|NVV|NVI, numero, lid?}"""
    d = request.get_json(silent=True) or {}
    tipo = (d.get("tipo") or "FCV").strip().upper()[:5]
    # 2026-08-08 (Daniel): agrega NVV/NVI -- notas de venta, mismos TIDOs
    # ya usados en otros buscadores ERP (ver _RANDOM_TIDOS_VENTA).
    if tipo not in ("FCV", "FCE", "BLV", "BLE", "GDV", "NVV", "NVI"):
        tipo = "FCV"
    numero = re.sub(r"[^0-9]", "", str(d.get("numero") or ""))
    if not numero:
        return jsonify({"ok": False, "error": "Indica el número del documento."}), 400
    # SQL Server primero, REST de Random como respaldo (ver _erp_doc_lookup).
    doc, _fuente, _respondio, _erp_err = _erp_doc_lookup(tipo, numero)
    if not doc:
        print(f"[erp_doc_info] {tipo} {numero} sin documento "
              f"(respondio={_respondio} err={_erp_err})", flush=True)
        if not _respondio:
            return jsonify({
                "ok": False,
                "error": "El ERP de Random no está respondiendo en este momento. "
                         "Vuelve a intentar en unos minutos.",
            }), 502
        return jsonify({
            "ok": False,
            "error": f"No encontramos {tipo} N° {numero} en el ERP. Revisa el número.",
        }), 404
    analisis = None
    try:
        lid = int(d.get("lid") or 0)
        if lid:
            _lc = mysql_fetchone(
                "SELECT c.rut FROM mant_levantamientos l "
                "JOIN mant_clientes c ON c.id=l.cliente_id WHERE l.id=%s", (lid,))
            if _lc and _lc.get("rut"):
                analisis = _rut_analisis_comparacion(_lc["rut"], doc.get("cliente_rut"))
    except Exception:
        analisis = None
    try:
        _monto = float(doc.get("valor_bruto") or 0) or None
    except (TypeError, ValueError):
        _monto = None
    return jsonify({"ok": True, "doc": {
        "tipo": tipo, "numero": numero,
        "fecha": str(doc.get("fecha") or "")[:10],
        "cliente_nombre": doc.get("cliente_nombre") or "",
        "cliente_rut": doc.get("cliente_rut") or "",
        "monto": _monto,
    }, "analisis": analisis})


def _ot_destino_coords(v):
    """(lat,lng) del destino real de la OT para la geocerca, o (None,None)
    si no hay ninguna coordenada guardada. (None,None) NO es un error:
    significa que la geocerca es inaplicable para esa OT/cliente -> se deja
    pasar (fail-open), nunca se bloquea al técnico por un dato faltante que
    no eligió él."""
    if v.get("direccion_lat") is not None and v.get("direccion_lng") is not None:
        try:
            return float(v["direccion_lat"]), float(v["direccion_lng"])
        except (TypeError, ValueError):
            pass
    c = mysql_fetchone(
        "SELECT direccion_lat, direccion_lng FROM mant_clientes WHERE id=%s",
        (v.get("cliente_id"),)) or {}
    if c.get("direccion_lat") is not None and c.get("direccion_lng") is not None:
        try:
            return float(c["direccion_lat"]), float(c["direccion_lng"])
        except (TypeError, ValueError):
            pass
    return None, None


def _lev_gate_finalizar(v, d):
    """Geocerca del modal de levantamiento — SOLO se evalúa al finalizar un
    equipo (payload con finalizar:true), nunca en el autoguardado de texto
    ni de fotos (Daniel 2026-08-08: "la ubicación solo se pide al botón
    final"). Devuelve (ok:bool, gps:dict con lo que hay que persistir,
    error:(body,status)|None).

    Fail-open explícito en 3 casos — cada uno deliberado, no un accidente:
      - la regla ot_geofence_lev_activo está apagada (default)
      - el rol es de gestión (admin/supervisor/ejecutivo/superadmin) —
        mismo criterio que ya exime _lev_puede_accion en todo lo demás
      - la OT/cliente no tiene coordenadas guardadas -> gps_dentro_rango
        queda NULL y PASA (nunca comparar con `!= 1`, siempre aceptar NULL)
    """
    R = _reglas_cargar() or {}
    activo = bool(R.get("ot_geofence_lev_activo"))
    radio = max(50, int(R.get("ot_geofence_lev_radio_m") or 500))
    accmax = max(30, int(R.get("ot_geofence_lev_accuracy_max_m") or 500))

    rol = _rol_familia((getattr(g, "user", None) or {}).get("role"))
    exento = rol in ("admin", "supervisor", "ejecutivo", "superadmin")

    gps = {"gps_lat": None, "gps_lng": None, "gps_accuracy_m": None,
           "gps_dist_m": None, "gps_dentro_rango": None,
           "gps_origen": "sin_gps", "gps_captured_at": None}

    lat, lng = d.get("gps_lat"), d.get("gps_lng")
    acc = d.get("gps_accuracy_m")
    dlat, dlng = _ot_destino_coords(v)

    if lat is not None and lng is not None:
        try:
            gps["gps_lat"] = float(lat)
            gps["gps_lng"] = float(lng)
        except (TypeError, ValueError):
            lat = lng = None
    if lat is not None and lng is not None:
        gps["gps_accuracy_m"] = int(acc) if acc not in (None, "") else None
        gps["gps_captured_at"] = datetime.utcnow()
        gps["gps_origen"] = "tecnico"
        if dlat is not None and dlng is not None:
            dist = _haversine_m(gps["gps_lat"], gps["gps_lng"], dlat, dlng)
            if dist is not None:
                gps["gps_dist_m"] = int(dist)
                gps["gps_dentro_rango"] = 1 if dist <= radio else 0
        else:
            gps["gps_origen"] = "sin_destino"

    if not activo:
        return True, gps, None
    if exento:
        gps["gps_origen"] = "exento_gestion"
        return True, gps, None

    if lat is None or lng is None:
        return False, gps, ({
            "ok": False, "error_codigo": "GPS_REQUERIDO",
            "error": "Necesitamos tu ubicación para cerrar este equipo. "
                     "Activa el GPS y vuelve a tocar «Guardar equipo». "
                     "Lo que escribiste y las fotos ya quedaron guardados.",
        }, 400)

    if gps["gps_accuracy_m"] is not None and gps["gps_accuracy_m"] > accmax:
        return False, gps, ({
            "ok": False, "error_codigo": "GPS_IMPRECISO",
            "accuracy_m": gps["gps_accuracy_m"], "accuracy_max_m": accmax,
            "error": f"La señal GPS está muy imprecisa (±{gps['gps_accuracy_m']} m). "
                     f"Acércate a una ventana o sal un momento y reintenta.",
        }, 400)

    # Fail-open explícito: NULL (sin destino) siempre pasa. Nunca usar `!= 1`.
    if gps["gps_dentro_rango"] is None:
        try:
            _mant_log("visita", v.get("id"), "geofence_sin_destino",
                      "Equipo finalizado sin validar geocerca: la OT/cliente no tiene "
                      "coordenadas cargadas.")
        except Exception:
            pass
        return True, gps, None

    if gps["gps_dentro_rango"] == 0:
        dm = gps["gps_dist_m"] or 0
        legible = f"{dm/1000:.1f} km" if dm >= 1000 else f"{dm} m"
        return False, gps, ({
            "ok": False, "error_codigo": "GPS_FUERA_RANGO",
            "dist_m": dm, "radio_m": radio,
            "error": f"Estás a ~{legible} del sitio (límite {radio} m). "
                     f"Acércate y vuelve a tocar «Guardar equipo». "
                     f"Tu trabajo quedó guardado, no se pierde nada.",
        }, 403)

    return True, gps, None


@app.route("/mantenciones/api/levantamientos/<int:lid>/items", methods=["POST"])
@_mant_required
def mant_lev_item_crear(lid):
    """Agregar un equipo al levantamiento (puede ser una máquina existente o crear ad-hoc).
    FASE 4: si el levantamiento tiene OT espejo (visita_id), también se crea
    automáticamente una tarea tipo='foto' en la OT para ese equipo, así el
    técnico ve el nuevo equipo en su checklist sin pasos adicionales.
    """
    lev = mysql_fetchone(
        "SELECT id, cliente_id, estado, visita_id FROM mant_levantamientos WHERE id=%s",
        (lid,)
    )
    if not lev:
        return jsonify({"ok": False, "error": "Levantamiento no encontrado"}), 404
    if lev["estado"] == "cerrado":
        return jsonify({"ok": False, "error": "Levantamiento cerrado — no acepta más equipos"}), 400
    # FIX seguridad (mismo IDOR ya cerrado en mant_lev_item_update, línea
    # ~85315): antes solo @_mant_required dejaba a cualquier técnico crear
    # equipos en el levantamiento de OTRA OT adivinando el lid.
    if not _lev_puede_accion(lid, "ejecutar", lev_row=lev):
        return _lev_403_response("ejecutar")

    d = request.get_json(silent=True) or {}

    # ── Candado REAL de "quién puede agregar equipos" ───────────────────
    # PASO 7 (2026-08-12, plan "el levantamiento es un tipo más"): el
    # candado de arriba (antes de este cambio) nunca podía dar False --
    # `_v_lev` casi siempre resolvía `_ot_es_levantamiento()` a True porque
    # el propio `levantamiento_id` de la OT apunta de vuelta a `lid`
    # (el levantamiento con el que se entró al endpoint). Era código
    # muerto. Daniel, textual: "el técnico ni nadie puede agregar
    # productos que no estén en una factura cobrada, a menos que sea un
    # levantamiento para conocer al cliente" -- confirma que el candado
    # debe ser ESTRICTO.
    #
    # 7a: criterio nuevo — SOLO se permite si la OT es tipo='levantamiento'
    #     Y su modalidad_captura (Paso 3) es 'descubrimiento'.
    # 7b: aplica a TODOS los roles, no solo técnico (Daniel: "si hay que
    #     limitar todo a una factura por favor, o a menos que provenga de
    #     la ficha de productos" -- sin excepción por rol).
    # 7d: modalidad_captura IS NULL (legacy, de antes del Paso 3) se trata
    #     como "NO es descubrimiento" -- lectura fail-closed correcta.
    _v_lev = None
    if lev.get("visita_id"):
        _v_lev = mysql_fetchone(
            "SELECT id, tipo FROM mant_visitas WHERE id=%s",
            (lev["visita_id"],)
        )
    _puede_agregar = True
    _motivo_bloqueo = None
    if not lev.get("visita_id"):
        # Sin OT espejo el levantamiento es autónomo (flujo de
        # levantamiento puro) => se permite, es su caso de uso (Daniel
        # 2026-06-23).
        pass
    elif ((_v_lev or {}).get("tipo") or "").strip().lower() != "levantamiento":
        _puede_agregar = False
        _motivo_bloqueo = "La OT vinculada no es de tipo levantamiento."
    else:
        try:
            _lev_mod = mysql_fetchone(
                "SELECT modalidad_captura FROM mant_levantamientos WHERE id=%s", (lid,))
            _modalidad = (_lev_mod or {}).get("modalidad_captura")
            if _modalidad != "descubrimiento":
                _puede_agregar = False
                _motivo_bloqueo = (
                    "El levantamiento no es de modalidad 'descubrimiento' "
                    f"(modalidad_captura={_modalidad!r})."
                )
        except Exception as _e_modcap:
            # 7c (CORRECCIÓN DE FABLE, confirmada por Daniel como la
            # interpretación correcta): SOLO para el error específico de
            # columna inexistente (1054 -- el ALTER del Paso 3 aún no
            # llegó a este entorno, recordar que prod corre con
            # ILUS_SKIP_MIGRATIONS=1) se trata como "comportamiento aún no
            # desplegado" y se permite -- NO se convierte el except
            # genérico en fail-open. Cualquier OTRO error mantiene
            # fail-closed (403), sin excepciones.
            _msg_e = str(_e_modcap).lower()
            if "1054" in _msg_e or "unknown column" in _msg_e:
                print(f"[lev_item_crear][gate] lid={lid}: modalidad_captura aún no "
                      f"desplegada en este entorno -- se permite sin el gate nuevo "
                      f"(comportamiento pre-Paso 7).", flush=True)
            else:
                print(f"[lev_item_crear][gate] lid={lid}: {_e_modcap}", flush=True)
                _puede_agregar = False
                _motivo_bloqueo = "No se pudo validar la modalidad del levantamiento."

    if not _puede_agregar:
        # EXCEPCIÓN CONFIRMADA por Daniel: "debe considerarse una pequeña
        # flexibilidad al super admin." Mismo patrón ya aprobado para la
        # corrección retroactiva de garantía (mant_visita_update, ver
        # "CORRECCIÓN RETROACTIVA DE GARANTÍA" / garantia_retroactiva):
        # flag + motivo obligatorio (>=10 caracteres) + auditoría en
        # mant_logs. Solo superadmin (_puede_superadmin, mismo mecanismo
        # de permisos que usa el resto del módulo -- g.permissions).
        _es_superadmin = bool((getattr(g, "permissions", {}) or {}).get("superadmin"))
        _override = bool(d.get("override_superadmin"))
        if _es_superadmin and _override:
            _motivo_override = (d.get("override_motivo") or "").strip()
            if len(_motivo_override) < 10:
                return jsonify({
                    "ok": False,
                    "error": "Para agregar un equipo fuera de un levantamiento por "
                             "descubrimiento, indica el motivo (mínimo 10 caracteres).",
                    "error_codigo": "OVERRIDE_MOTIVO_REQUERIDO",
                }), 400
            _mant_log(
                "levantamiento", lid, "equipo_agregado_override_superadmin",
                f"{current_username() or 'superadmin'} agregó equipo saltando el "
                f"candado ({_motivo_bloqueo}) · motivo: {_motivo_override[:500]}"
            )
            # Sigue el flujo normal de creación más abajo (permitido).
        elif _es_superadmin:
            # Superadmin SIN el override explícito: se le avisa que puede
            # forzarlo, pero no se le abre la puerta en silencio.
            return jsonify({
                "ok": False,
                "error": f"{_motivo_bloqueo} Como superadmin puedes forzarlo con un "
                         "motivo (override_superadmin=true + override_motivo).",
                "error_codigo": "TECNICO_NO_AGREGA_EQUIPOS",
            }), 403
        else:
            return jsonify({
                "ok": False,
                "error": f"{_motivo_bloqueo} Trabaja sobre los equipos ya asociados a "
                         "la factura, o pide que se genere un Levantamiento por "
                         "descubrimiento para conocer al cliente.",
                "error_codigo": "TECNICO_NO_AGREGA_EQUIPOS",
            }), 403

    maquina_id = d.get("maquina_id")
    nombre = (d.get("nombre") or "").strip()[:300]
    # client_uid (Daniel 2026-08-08): generado en el navegador al abrir un
    # equipo NUEVO, viaja en todos los POST/autoguardados de ese equipo
    # mientras no exista iid todavía. Junto a la UNIQUE KEY
    # uq_lev_item_uid, sirve para que un reintento de red (4G inestable,
    # doble-tap) resuelva al MISMO row en vez de crear un duplicado.
    client_uid = (d.get("client_uid") or "").strip()[:40] or None

    # 2026-08-09 (Daniel: "el equipo no está... se anula cualquier
    # obligatoriedad de completar, porque no existe"): con este estado, el
    # nombre no es exigible -- puede ser el primer campo que se autoguarda.
    if not maquina_id and not nombre and (d.get("estado_capturado") != "no_encontrado"):
        return jsonify({"ok": False, "error": "Indica una máquina existente o un nombre nuevo"}), 400

    # Ad-hoc (equipo DESCUBIERTO en terreno): acepta sku/serie del payload
    # (levantamiento puro 2026-06-23 — el técnico bautiza el equipo con
    # nombre + serie sugerida editable + sku opcional).
    snap = {"nombre": nombre,
            "sku": (d.get("sku") or "").strip()[:120],
            "serie": (d.get("serie") or "").strip()[:120]}
    if maquina_id:
        m = mysql_fetchone(
            "SELECT nombre, sku, serie FROM mant_maquinas WHERE id=%s AND cliente_id=%s",
            (maquina_id, lev["cliente_id"])
        )
        if not m:
            return jsonify({"ok": False, "error": "Máquina no pertenece al cliente"}), 400
        snap = {"nombre": m.get("nombre") or nombre,
                "sku": m.get("sku") or "",
                "serie": m.get("serie") or ""}

    _est_cap = d.get("estado_capturado") or "operativo"
    if _est_cap not in ('operativo','advertencia','fuera_servicio',
                        'en_reparacion','dado_baja','no_encontrado'):
        _est_cap = "operativo"
    # Factura de origen del equipo (opcional — verificada vía /api/erp/doc-info)
    _doc_origen = None
    _doc_fecha = None
    _dt_doc = (d.get("doc_tido") or "").strip().upper()[:5]
    _dn_doc = re.sub(r"[^0-9]", "", str(d.get("doc_numero") or ""))
    if _dt_doc and _dn_doc:
        _doc_origen = f"{_dt_doc} {_dn_doc}"[:80]
        _df = str(d.get("doc_fecha") or "").strip()[:10]
        _doc_fecha = _df if re.match(r"^\d{4}-\d{2}-\d{2}$", _df) else None
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            colision = False
            try:
                try:
                    cur.execute(
                        "INSERT INTO mant_levantamiento_items "
                        "(levantamiento_id, maquina_id, nombre_snap, sku_snap, serie_snap, "
                        " estado_capturado, ubicacion, observaciones, anomalias, "
                        " doc_origen, fecha_documento, es_borrador, client_uid) "
                        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1,%s)",
                        (lid, maquina_id, snap["nombre"], snap["sku"], snap["serie"],
                         _est_cap,
                         (d.get("ubicacion") or "").strip()[:200],
                         (d.get("observaciones") or "").strip() or None,
                         (d.get("anomalias") or "").strip() or None,
                         _doc_origen, _doc_fecha, client_uid)
                    )
                except Exception as _e_full:
                    # Fallback SOLO si alguna columna (doc_origen o las nuevas
                    # de es_borrador/client_uid, si _ensure_lev_items_gps_cols
                    # aun no corrio con ILUS_SKIP_MIGRATIONS=1) no existe todavia.
                    # Cualquier OTRO error (lock timeout, data-too-long, etc.)
                    # se re-lanza: no queremos descartar en silencio la factura
                    # que el técnico verificó ni enmascarar un fallo real.
                    _msg = str(_e_full).lower()
                    if not ("doc_origen" in _msg or "es_borrador" in _msg
                            or "client_uid" in _msg or "unknown column" in _msg
                            or "1054" in _msg):
                        raise
                    print(f"[lev_item_crear] columna(s) no disponibles ({_e_full}); "
                          f"fallback minimo", flush=True)
                    cur.execute(
                        "INSERT INTO mant_levantamiento_items "
                        "(levantamiento_id, maquina_id, nombre_snap, sku_snap, serie_snap, "
                        " estado_capturado, ubicacion, observaciones, anomalias) "
                        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                        (lid, maquina_id, snap["nombre"], snap["sku"], snap["serie"],
                         _est_cap,
                         (d.get("ubicacion") or "").strip()[:200],
                         (d.get("observaciones") or "").strip() or None,
                         (d.get("anomalias") or "").strip() or None)
                    )
                iid = cur.lastrowid
            except Exception as _e_ins:
                # Carrera de creación (Daniel 2026-08-08): dos campos/fotos del
                # MISMO equipo nuevo dispararon su propio POST casi a la vez.
                # uq_lev_item_uid rechaza el 2º con Duplicate entry -- en vez
                # de perderlo, se aplica su payload sobre el row que YA se
                # creó (nunca un SELECT mudo que descarte el 2º dato).
                _msg = str(_e_ins)
                if not (client_uid and ("1062" in _msg or "Duplicate entry" in _msg)):
                    raise
                _existente = mysql_fetchone(
                    "SELECT id FROM mant_levantamiento_items "
                    "WHERE levantamiento_id=%s AND client_uid=%s",
                    (lid, client_uid))
                if not _existente:
                    raise
                iid = _existente["id"]
                colision = True
                _ubic = (d.get("ubicacion") or "").strip()[:200]
                cur.execute(
                    "UPDATE mant_levantamiento_items SET "
                    "  nombre_snap = CASE WHEN %s <> '' THEN %s ELSE nombre_snap END, "
                    "  sku_snap    = CASE WHEN %s <> '' THEN %s ELSE sku_snap END, "
                    "  serie_snap  = CASE WHEN %s <> '' THEN %s ELSE serie_snap END, "
                    "  ubicacion   = CASE WHEN %s <> '' THEN %s ELSE ubicacion END, "
                    "  observaciones = COALESCE(NULLIF(%s,''), observaciones), "
                    "  anomalias     = COALESCE(NULLIF(%s,''), anomalias) "
                    "WHERE id=%s",
                    (snap["nombre"], snap["nombre"], snap["sku"], snap["sku"],
                     snap["serie"], snap["serie"], _ubic, _ubic,
                     (d.get("observaciones") or "").strip(),
                     (d.get("anomalias") or "").strip(), iid)
                )
            cur.execute(
                "UPDATE mant_levantamientos SET total_equipos = "
                "(SELECT COUNT(*) FROM mant_levantamiento_items WHERE levantamiento_id=%s) "
                "WHERE id=%s",
                (lid, lid)
            )
            # FASE 4: sincronizar con la OT espejo (si existe).
            # Crear una tarea tipo='foto' por el nuevo equipo si:
            #   - hay OT espejo (visita_id)
            #   - hay maquina_id (no ad-hoc sin equipo identificado)
            #   - no existe ya una tarea para esa máquina en la OT
            if lev.get("visita_id") and maquina_id:
                cur.execute(
                    "SELECT id FROM mant_visita_tareas "
                    "WHERE visita_id=%s AND maquina_id=%s LIMIT 1",
                    (lev["visita_id"], maquina_id)
                )
                ya_existe = cur.fetchone()
                if not ya_existe:
                    # Calcular siguiente `orden`
                    cur.execute(
                        "SELECT COALESCE(MAX(orden),0)+1 AS o FROM mant_visita_tareas "
                        "WHERE visita_id=%s",
                        (lev["visita_id"],)
                    )
                    next_orden = (cur.fetchone() or {}).get("o", 1)
                    cur.execute(
                        "INSERT INTO mant_visita_tareas "
                        "(visita_id, orden, titulo, descripcion, maquina_id, "
                        " tipo, tipo_respuesta, obligatoria, requiere_foto, "
                        " estado_trabajo, created_by) "
                        "VALUES (%s,%s,%s,%s,%s,'levantamiento','foto',1,1,"
                        " 'pendiente',%s)",
                        (lev["visita_id"], next_orden,
                         f"📷 Documentar: {snap['nombre'][:240]}",
                         "Capturar fotos generales + N° serie + placa + datos técnicos.",
                         maquina_id, current_username() or 'sistema')
                    )
        conn.commit()
        return jsonify({"ok": True, "id": iid, "colision": colision})
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        try: conn.close()
        except Exception: pass


_LEV_ESTADOS_EDITABLES = ('creada', 'programada', 'asignada', 'en_curso',
                          'en_ejecucion', 'reagendada')


@app.route("/mantenciones/api/levantamiento-items/<int:iid>", methods=["PATCH", "DELETE"])
@_mant_required
def mant_lev_item_update(iid):
    """Actualizar o eliminar un equipo descubierto en terreno.

    REGLA (Daniel 2026-07-06, ENDURECIDA 2026-07-08 — ventana de corrección
    + trazabilidad): "somos seres humanos y nos podemos equivocar" — MIENTRAS
    la OT no esté firmada por el técnico (estado en _LEV_ESTADOS_EDITABLES),
    el equipo se puede editar y eliminar libremente. Una vez firmada:
      - PATCH (editar): BLOQUEADO para TODOS — el registro queda congelado,
        es la fuente de verdad de lo que el técnico reportó en terreno.
      - DELETE: BLOQUEADO para TODOS, incluido superadmin (2026-07-08: Daniel
        endureció la regla — "solo se podrá visualizar por todas las
        personas, tanto superadministrador como ejecutivo y técnico"; antes
        superadmin tenía una excepción para casos excepcionales, ya no).
    Toda edición ANTES de firmar también queda auditada campo a campo en
    mant_logs — para proteger al técnico si alguien alega que él reportó
    algo distinto a lo que terminó quedando (REGLA #5 CLAUDE.md: audit log
    en acción destructiva/sensible, antes no después).
    """
    item = mysql_fetchone(
        "SELECT * FROM mant_levantamiento_items WHERE id=%s", (iid,)
    )
    if not item:
        return jsonify({"ok": False, "error": "Item no encontrado"}), 404

    # FIX seguridad (peritaje C2 — IDOR): antes solo @_mant_required dejaba a
    # cualquier técnico editar/eliminar equipos descubiertos por OTRO técnico
    # en su propia OT, adivinando el id. Ver `_lev_puede_accion` línea ~32943.
    if not _lev_puede_accion(item["levantamiento_id"], "ejecutar"):
        return _lev_403_response("ejecutar")

    # FIX 2026-08-10 (OT-2026-00042): antes buscaba la visita por el campo
    # FORWARD (mant_visitas.levantamiento_id=%s) — si el link estaba solo en
    # el sentido reverse (dato legacy/desincronización histórica), esta
    # consulta no encontraba la visita, `_visita_estado` quedaba vacío y
    # `_editable` daba False (el equipo se veía "congelado" cuando en
    # realidad la OT seguía editable). Acá el caller YA conoce con certeza
    # el levantamiento_id del item, así que se resuelve la visita por el
    # sentido reverse que SÍ es seguro: mant_levantamientos.visita_id.
    v = mysql_fetchone(
        "SELECT vv.estado FROM mant_levantamientos lv "
        "  LEFT JOIN mant_visitas vv ON vv.id = lv.visita_id "
        " WHERE lv.id=%s", (item["levantamiento_id"],)
    )
    _visita_estado = (v or {}).get("estado") or ""
    _editable = _visita_estado in _LEV_ESTADOS_EDITABLES
    user = current_username() or "sistema"

    if request.method == "DELETE":
        # 2026-08-08 (Daniel): "el técnico no tiene por qué borrar máquina".
        # El botón de basura se oculta en la UI para el técnico, pero eso es
        # cosmético: acá se bloquea de verdad. Editar SÍ puede (corregir lo
        # que él mismo capturó); eliminar queda para admin/supervisor/
        # ejecutivo/superadmin, que es quien audita el levantamiento.
        if _rol_familia((getattr(g, "user", None) or {}).get("role")) == "tecnico":
            return jsonify({
                "ok": False,
                "error": "No puedes eliminar equipos. Si capturaste uno por error, "
                         "edítalo o avisa al supervisor para que lo quite.",
                "error_codigo": "LEV_TECNICO_SIN_DELETE",
            }), 403
        if not _editable:
            return jsonify({
                "ok": False,
                "error": "Esta OT ya fue firmada por el técnico — los equipos descubiertos "
                         "quedaron congelados. Nadie puede eliminarlos, solo visualizarlos.",
                "error_codigo": "LEV_CONGELADO",
            }), 403
        # Snapshot completo ANTES de borrar (el row se pierde) — trazabilidad.
        _snap = (f"nombre='{item.get('nombre_snap')}' sku='{item.get('sku_snap')}' "
                 f"serie='{item.get('serie_snap')}' estado='{item.get('estado_capturado')}' "
                 f"anomalias='{(item.get('anomalias') or '')[:200]}'")
        try:
            _mant_log("levantamiento_item", iid, "eliminado",
                      f"{user} eliminó equipo descubierto (OT estado={_visita_estado}) — {_snap}")
        except Exception:
            pass
        mysql_execute("DELETE FROM mant_levantamiento_items WHERE id=%s", (iid,))
        mysql_execute(
            "UPDATE mant_levantamientos SET total_equipos = "
            "(SELECT COUNT(*) FROM mant_levantamiento_items WHERE levantamiento_id=%s) "
            "WHERE id=%s",
            (item["levantamiento_id"], item["levantamiento_id"])
        )
        return jsonify({"ok": True})

    # ── PATCH ──
    if not _editable:
        return jsonify({
            "ok": False,
            "error": "Esta OT ya fue firmada por el técnico — los equipos descubiertos "
                     "quedaron congelados y no se pueden editar.",
            "error_codigo": "LEV_CONGELADO",
        }), 403

    d = request.get_json(silent=True) or {}
    # Alias amigables (mismos nombres que ya usa el payload de CREACIÓN del
    # modal de terreno) → columna real de la tabla. Así el frontend reusa el
    # MISMO payload para crear (POST) y editar (PATCH) sin duplicar lógica.
    _alias = {"nombre": "nombre_snap", "sku": "sku_snap", "serie": "serie_snap"}
    d2 = {_alias.get(k, k): v for k, v in d.items()}
    # FIX (revisión adversarial 2026-07-06): el payload de levdGuardar() SIEMPRE
    # incluye doc_tido/doc_numero/doc_fecha (vacíos si el usuario no tocó la
    # sección de factura, ej. al editar solo el nombre). Antes, "vacío" se
    # traducía a doc_origen=None, BORRANDO en silencio una factura ya asociada
    # en CUALQUIER edición que no reconfirmara la factura. Ahora solo se toca
    # doc_origen/fecha_documento si el usuario aportó un valor real — si vino
    # vacío, NO se incluye la key y el valor existente en la BD queda intacto.
    _dt = (d.get("doc_tido") or "").strip().upper()[:5]
    _dn = re.sub(r"[^0-9]", "", str(d.get("doc_numero") or ""))
    if _dt and _dn:
        d2["doc_origen"] = f"{_dt} {_dn}"[:80]
    else:
        d2.pop("doc_tido", None); d2.pop("doc_numero", None)
    _df = str(d.get("doc_fecha") or "").strip()[:10]
    if re.match(r"^\d{4}-\d{2}-\d{2}$", _df):
        d2["fecha_documento"] = _df
    else:
        d2.pop("doc_fecha", None)
    d = d2

    # Geocerca de 500m (Daniel 2026-08-08): SOLO se evalúa en la transición
    # borrador -> finalizado (payload con finalizar:true sobre un item que
    # aún está en borrador). Un PATCH normal de autoguardado (sin
    # finalizar, o sobre un item YA finalizado) recorre exactamente el
    # camino de HOY, sin tocar GPS — "la ubicación solo se pide al botón
    # final", nunca en cada campo que se autoguarda.
    quiere_finalizar = bool(d.get("finalizar"))
    ya_finalizado = int(item.get("es_borrador") if item.get("es_borrador") is not None else 0) == 0
    aplica_gate = quiere_finalizar and not ya_finalizado
    gps_set = {}
    if aplica_gate:
        _v_gate = mysql_fetchone(
            "SELECT v.id, v.cliente_id, v.direccion_lat, v.direccion_lng "
            "  FROM mant_visitas v WHERE v.levantamiento_id=%s LIMIT 1",
            (item["levantamiento_id"],)) or {}
        _ok_gate, gps_set, _err_gate = _lev_gate_finalizar(_v_gate, d)
        if not _ok_gate:
            _body, _code = _err_gate
            return jsonify(_body), _code
        gps_set["es_borrador"] = 0

    sets, vals, cambios = [], [], []
    estados_validos = ('operativo','advertencia','fuera_servicio','en_reparacion','dado_baja','no_encontrado')
    # Campos editables del item (incluye snap de identidad para el modo
    # edición del modal de terreno + los campos ya existentes de calidad fitness)
    for k in (
        "nombre_snap", "sku_snap", "serie_snap", "doc_origen",
        "estado_capturado", "ubicacion", "horas_uso", "anomalias", "observaciones",
        "completado",
        "fecha_documento", "marca", "modelo", "anio_fabricacion",
        "voltaje", "ultima_intervencion", "componentes_json",
    ):
        if k in d:
            v_new = d[k]
            if k == "estado_capturado" and v_new not in estados_validos:
                continue
            if k in ("horas_uso", "anio_fabricacion"):
                try: v_new = int(v_new) if v_new not in (None, "") else None
                except Exception: continue
            if k in ("fecha_documento", "ultima_intervencion"):
                # Espera string YYYY-MM-DD o None. Si viene "", lo guardamos como NULL.
                if v_new in ("", None): v_new = None
            if k == "completado":
                v_new = 1 if v_new else 0
            if k in ("nombre_snap","sku_snap","serie_snap","ubicacion",
                     "observaciones","anomalias","doc_origen") and isinstance(v_new, str):
                v_new = v_new.strip() or None
            # Defensa en profundidad: el modal ya exige nombre obligatorio,
            # pero el servidor no debe confiar solo en eso — un nombre_snap
            # vacío hace que el equipo se salte en silencio la materialización
            # a mant_maquinas al cerrar la OT (WHERE nombre_snap <> '').
            # 2026-08-09: excepción cuando el equipo se declaró "no está" —
            # ahí el nombre nunca fue obligatorio (mira el estado que YA
            # tiene guardado el item, no solo lo que viene en este payload,
            # porque estado_capturado y nombre_snap suelen autoguardarse en
            # PATCH separados).
            _estado_efectivo = d.get("estado_capturado", item.get("estado_capturado"))
            if k == "nombre_snap" and v_new is None and _estado_efectivo != "no_encontrado":
                return jsonify({"ok": False, "error": "El nombre del equipo no puede quedar vacío."}), 400
            v_old = item.get(k)
            if str(v_old if v_old is not None else "") != str(v_new if v_new is not None else ""):
                cambios.append(f"{k}: '{v_old if v_old is not None else '—'}' → "
                                f"'{v_new if v_new is not None else '—'}'")
            sets.append(f"{k}=%s")
            vals.append(v_new)
    if not sets and not gps_set:
        return jsonify({"ok": True, "noop": True})
    # 2026-07-06 (revisión adversarial): modificado_por/modificado_at solo se
    # estampan si HUBO un cambio real — si no, un guardado sin tocar nada
    # ensuciaría la trazabilidad ("editado por X") que esta función existe
    # para proteger.
    if cambios:
        sets.append("modificado_por=%s"); vals.append(user)
        sets.append("modificado_at=NOW()")
    for _gk, _gv in gps_set.items():
        sets.append(f"{_gk}=%s")
        vals.append(_gv)
    vals.append(iid)
    mysql_execute(f"UPDATE mant_levantamiento_items SET {', '.join(sets)} WHERE id=%s", tuple(vals))
    if cambios:
        try:
            _mant_log("levantamiento_item", iid, "editado",
                      f"{user} editó equipo descubierto: " + " · ".join(cambios))
        except Exception:
            pass
    if aplica_gate:
        try:
            _mant_log("levantamiento_item", iid, "finalizado",
                      f"{user} finalizó equipo (GPS origen={gps_set.get('gps_origen')}, "
                      f"dist_m={gps_set.get('gps_dist_m')})")
        except Exception:
            pass
    return jsonify({
        "ok": True, "modificado_por": user,
        "es_borrador": 0 if aplica_gate else int(item.get("es_borrador") or 0),
        "gps_dist_m": gps_set.get("gps_dist_m"),
    })


@app.route("/mantenciones/api/levantamiento-items/<int:iid>/fotos", methods=["POST"])
@_mant_required
def mant_lev_item_subir_foto(iid):
    """Sube una foto del item al almacenamiento y la asocia a la máquina si aplica."""
    item = mysql_fetchone(
        "SELECT li.*, l.cliente_id FROM mant_levantamiento_items li "
        "JOIN mant_levantamientos l ON l.id = li.levantamiento_id "
        "WHERE li.id=%s",
        (iid,)
    )
    if not item:
        return jsonify({"ok": False, "error": "Item no encontrado"}), 404
    # FIX seguridad (mismo IDOR ya cerrado en mant_lev_item_update): antes
    # solo @_mant_required dejaba a cualquier técnico subir una foto a un
    # equipo de OTRA OT adivinando el iid.
    if not _lev_puede_accion(item["levantamiento_id"], "ejecutar"):
        return _lev_403_response("ejecutar")

    f = request.files.get("foto") or request.files.get("archivo")
    if not f or not f.filename:
        return jsonify({"ok": False, "error": "Sin archivo"}), 400

    tipo_foto = (request.form.get("tipo_foto") or "general").strip().lower()[:60]
    descripcion = (request.form.get("descripcion") or "").strip()[:300]

    if not _gcs_ready():
        return jsonify({"ok": False, "error": _STORAGE_OFF_MSG}), 503

    # Huella del contenido ANTES de subir (Daniel 2026-08-09): permite
    # detectar la misma foto repetida y no contarla como evidencia nueva.
    # _foto_sha256 deja el stream rebobinado, así que el upload no se afecta.
    _hash = _foto_sha256(f.stream)
    _dup_de = None
    if _hash:
        try:
            _prev = mysql_fetchone(
                "SELECT id FROM mant_levantamiento_fotos "
                " WHERE levantamiento_id=%s AND foto_hash=%s LIMIT 1",
                (item["levantamiento_id"], _hash)
            )
            if _prev:
                _dup_de = int(_prev["id"])
        except Exception as _dup_e:
            print(f"[lev_foto][dup_check] {_dup_e}", flush=True)

    try:
        f.stream.seek(0)
        public_id = f"lev_{item['levantamiento_id']}_item_{iid}_{int(time.time())}"
        folder = f"ilus/mant/levantamientos/{item['levantamiento_id']}"
        res = _cloud_upload_image_full(f.stream, public_id, folder=folder)
    except Exception as e:
        print(f"[lev_foto] iid={iid}: {e}", flush=True)
        return jsonify({"ok": False, "error": "No se pudo guardar la foto. Intenta de nuevo."}), 500

    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO mant_levantamiento_fotos "
                "(item_id, levantamiento_id, maquina_id, cloudinary_url, "
                " cloudinary_public_id, tipo_foto, descripcion, bytes, tomada_por, foto_hash) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                (iid, item["levantamiento_id"], item.get("maquina_id"),
                 res["url"], res["public_id"], tipo_foto, descripcion,
                 res.get("size", 0), current_username() or 'tecnico', _hash)
            )
            fid = cur.lastrowid
            # Actualizar contadores
            cur.execute(
                "UPDATE mant_levantamiento_items SET n_fotos = "
                "(SELECT COUNT(*) FROM mant_levantamiento_fotos WHERE item_id=%s) "
                "WHERE id=%s", (iid, iid)
            )
            cur.execute(
                "UPDATE mant_levantamientos SET total_fotos = "
                "(SELECT COUNT(*) FROM mant_levantamiento_fotos WHERE levantamiento_id=%s) "
                "WHERE id=%s", (item["levantamiento_id"], item["levantamiento_id"])
            )
            # Si tiene máquina asociada, también copiar a mant_maquina_fotos
            # para que aparezca en la ficha del equipo (timeline).
            # FIX 2026-05-21: archivo_path es NOT NULL en mant_maquina_fotos
            # (CREATE TABLE original) — pasamos string vacío, y usamos
            # tomada_at (no created_at, que es el alias agregado por migración).
            if item.get("maquina_id"):
                try:
                    # Anti-duplicado: si ya existe foto con esta cloudinary_url
                    # para esta máquina, no duplicamos (Daniel reportó fotos
                    # del levantamiento no aparecían — el INSERT podía fallar
                    # silenciosamente por NOT NULL constraint en archivo_path).
                    cur.execute(
                        "SELECT id FROM mant_maquina_fotos "
                        " WHERE maquina_id=%s AND cloudinary_url=%s LIMIT 1",
                        (item["maquina_id"], res["url"])
                    )
                    if not cur.fetchone():
                        cur.execute(
                            "INSERT INTO mant_maquina_fotos "
                            "(maquina_id, archivo_path, cloudinary_url, cloudinary_public_id, "
                            " levantamiento_id, descripcion, tomada_por, tomada_at) "
                            "VALUES (%s, '', %s, %s, %s, %s, %s, NOW())",
                            (item["maquina_id"], res["url"], res["public_id"],
                             item["levantamiento_id"],
                             f"[{tipo_foto}] {descripcion}".strip()[:500],
                             current_username() or 'tecnico')
                        )
                        print(f"[lev_foto] copiada a mant_maquina_fotos "
                              f"m={item['maquina_id']} lev={item['levantamiento_id']}",
                              flush=True)
                except Exception as e_mf:
                    print(f"[promover-lev] foto saltada porque INSERT "
                          f"a mant_maquina_fotos falló: {e_mf} "
                          f"(m={item.get('maquina_id')} lev={item.get('levantamiento_id')} "
                          f"url={res.get('url','')[:80]})",
                          flush=True)
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        return jsonify({"ok": False, "error": f"Error guardando en BD: {e}"}), 500
    finally:
        try: conn.close()
        except Exception: pass

    # Registrar evento en timeline del equipo
    if item.get("maquina_id"):
        _lev_registrar_evento(
            item["maquina_id"], item["cliente_id"],
            "foto_agregada", f"Nueva foto ({tipo_foto}) durante levantamiento #{item['levantamiento_id']}",
            "mant_levantamientos", item["levantamiento_id"],
            {"item_id": iid, "tipo_foto": tipo_foto}
        )

    return jsonify({
        "ok": True,
        "id": fid,
        "url": res["url"],
        "tipo_foto": tipo_foto,
        # Daniel 2026-08-09: la foto SE GUARDA igual (puede ser legítimo
        # repetir una toma), pero el frontend avisa que ya existía la misma
        # imagen en esta OT y NO cuenta doble como evidencia al cerrar.
        "duplicada": bool(_dup_de),
        "duplicada_de": _dup_de,
    })


@app.route("/mantenciones/api/levantamiento-fotos/<int:fid>", methods=["DELETE"])
@_mant_required
def mant_lev_foto_del(fid):
    """Elimina una foto del levantamiento (también de Cloudinary).

    Mismo gate que `mant_lev_item_update` (Daniel 2026-07-06, ENDURECIDO
    2026-07-08): mientras la OT no esté firmada por el técnico, cualquiera
    con acceso puede corregir (incluida una foto mal tomada); tras firmar,
    BLOQUEADO PARA TODOS (incluido superadmin) — solo visualización. Evita
    que alguien borre evidencia fotográfica del reporte del técnico sin
    dejar rastro server-side, aunque el frontend ya oculte el botón en ese caso.
    """
    foto = mysql_fetchone(
        "SELECT cloudinary_public_id, item_id, levantamiento_id "
        "  FROM mant_levantamiento_fotos WHERE id=%s",
        (fid,)
    )
    if not foto:
        return jsonify({"ok": False, "error": "Foto no encontrada"}), 404

    # FIX seguridad (peritaje C2 — IDOR): antes solo @_mant_required dejaba a
    # cualquier técnico borrar evidencia fotográfica de la OT de OTRO técnico
    # adivinando el id. Ver `_lev_puede_accion` línea ~32943.
    if not _lev_puede_accion(foto["levantamiento_id"], "ejecutar"):
        return _lev_403_response("ejecutar")

    # FIX 2026-08-10 (OT-2026-00042): mismo bug que en mant_lev_item_update —
    # buscar la visita por el campo FORWARD (mant_visitas.levantamiento_id)
    # falla cuando el link solo existe en el sentido reverse. Se resuelve
    # por mant_levantamientos.visita_id, que acá el caller ya conoce con
    # certeza vía foto["levantamiento_id"].
    v = mysql_fetchone(
        "SELECT vv.estado FROM mant_levantamientos lv "
        "  LEFT JOIN mant_visitas vv ON vv.id = lv.visita_id "
        " WHERE lv.id=%s", (foto["levantamiento_id"],)
    )
    _editable = ((v or {}).get("estado") or "") in _LEV_ESTADOS_EDITABLES
    if not _editable:
        return jsonify({
            "ok": False,
            "error": "Esta OT ya fue firmada por el técnico — las fotos quedaron "
                     "congeladas. Nadie puede eliminarlas, solo visualizarlas.",
            "error_codigo": "LEV_CONGELADO",
        }), 403
    try:
        _mant_log("levantamiento_item", foto["item_id"], "foto_eliminada",
                  f"{current_username() or 'sistema'} eliminó foto id={fid}")
    except Exception:
        pass

    if foto.get("cloudinary_public_id"):
        try:
            _uploader_destroy(foto["cloudinary_public_id"], resource_type="image")
        except Exception as e:
            print(f"[lev_foto_del] Cloudinary delete fail: {e}", flush=True)

    mysql_execute("DELETE FROM mant_levantamiento_fotos WHERE id=%s", (fid,))
    # Recontar
    mysql_execute(
        "UPDATE mant_levantamiento_items SET n_fotos = "
        "(SELECT COUNT(*) FROM mant_levantamiento_fotos WHERE item_id=%s) "
        "WHERE id=%s", (foto["item_id"], foto["item_id"])
    )
    mysql_execute(
        "UPDATE mant_levantamientos SET total_fotos = "
        "(SELECT COUNT(*) FROM mant_levantamiento_fotos WHERE levantamiento_id=%s) "
        "WHERE id=%s", (foto["levantamiento_id"], foto["levantamiento_id"])
    )
    return jsonify({"ok": True})


@app.route("/mantenciones/api/levantamientos/<int:lid>/cerrar", methods=["POST"])
@_mant_required
def mant_lev_cerrar(lid):
    """Cierra el levantamiento + la OT espejo de forma auditable (Fase 4).

    Acciones al cerrar:
    1. Levantamiento → estado='cerrado', fecha_cierre, closed_by.
    2. Por cada item con máquina → evento en timeline del equipo.
    3. OT espejo (si existe):
       a. Vincula las fotos del levantamiento (mant_maquina_fotos donde
          levantamiento_id = lid) como evidencia de la OT (mant_visita_fotos
          con tipo='levantamiento'), marcando la tarea correspondiente.
       b. Marca cada tarea de la OT como completada (estado_trabajo='completada')
          y guarda observaciones desde el item del levantamiento.
       c. OT pasa a estado='cerrada' (no solo 'completada' — es el estado
          auditable final del modelo Fracttal).
       d. diagnostico auto-generado con resumen del levantamiento.
       e. cerrada_por = usuario actual, cerrada_at = NOW().

    🔐 SEGURIDAD 2026-08-26 (Daniel — auditoría OT 2.0): faltaba
    `_lev_puede_accion` — a diferencia de sus rutas hermanas (GET/PATCH/DELETE
    en mant_lev_detalle, POST /items en mant_lev_item_crear), este endpoint
    solo tenía @_mant_required: cualquier usuario con permiso "mantenciones"
    podía cerrar el levantamiento (y su OT espejo) de otro técnico adivinando
    el id. Mismo patrón que el IDOR de mayo 2026, ver `_lev_puede_accion`.
    """
    lev = mysql_fetchone("SELECT * FROM mant_levantamientos WHERE id=%s", (lid,))
    if not lev:
        return jsonify({"ok": False, "error": "No encontrado"}), 404
    if not _lev_puede_accion(lid, "ejecutar", lev_row=lev):
        return _lev_403_response("ejecutar")
    if lev["estado"] == "cerrado":
        return jsonify({"ok": False, "error": "Ya estaba cerrado"}), 400

    user = current_username() or 'sistema'
    mysql_execute(
        "UPDATE mant_levantamientos SET estado='cerrado', fecha_cierre=NOW(), closed_by=%s "
        "WHERE id=%s",
        (user, lid)
    )
    # 2026-06-23 — Levantamiento PURO: materializar SINCRÓNICO los equipos
    # descubiertos en terreno (items sin maquina_id → mant_maquinas) ANTES
    # de leer los items, para que el timeline, la vinculación de fotos y la
    # promoción posterior los traten como equipos existentes.
    if lev.get("visita_id"):
        try:
            _mat = _lev_materializar_equipos_nuevos(lev["visita_id"], usuario=user)
            if _mat.get("creados"):
                print(f"[lev_cerrar] {_mat['creados']} equipo(s) descubiertos "
                      f"materializados en mant_maquinas", flush=True)
        except Exception as _e_mat:
            print(f"[lev_cerrar] materializar descubiertos: {_e_mat}", flush=True)
    # Registrar evento por cada equipo levantado
    items = mysql_fetchall(
        "SELECT id, maquina_id, n_fotos, estado_capturado, nombre_snap, "
        "       ubicacion, observaciones "
        "FROM mant_levantamiento_items "
        "WHERE levantamiento_id=%s AND maquina_id IS NOT NULL",
        (lid,)
    ) or []
    for it in items:
        _lev_registrar_evento(
            it["maquina_id"], lev["cliente_id"],
            "levantamiento",
            f"Levantamiento #{lid} cerrado · estado: {_lev_estado_label(it.get('estado_capturado'))} · {it.get('n_fotos',0)} foto(s)",
            "mant_levantamientos", lid,
            {"estado": it.get("estado_capturado"), "n_fotos": it.get("n_fotos", 0)}
        )

    fotos_vinculadas = 0
    tareas_cerradas = 0
    # Si tiene OT espejo: cierre auditable completo
    if lev.get("visita_id"):
        vid = lev["visita_id"]
        try:
            # 3.a — Vincular fotos del levantamiento como evidencia de la OT.
            # Fuente: mant_levantamiento_fotos (tabla específica del levantamiento,
            # tiene item_id que mapea directo a la máquina vía mant_levantamiento_items).
            # Se replican como filas en mant_visita_fotos apuntando a la tarea
            # correspondiente y manteniendo el cloudinary_url (sin re-uploadear).
            fotos_lev = mysql_fetchall(
                "SELECT lf.id, lf.maquina_id, lf.cloudinary_url, lf.descripcion, "
                "       lf.tomada_por, lf.tipo_foto "
                "FROM mant_levantamiento_fotos lf "
                "WHERE lf.levantamiento_id=%s",
                (lid,)
            ) or []
            conn = get_mysql()
            try:
                with conn.cursor() as cur:
                    # Mapeo maquina_id → tarea_id de la OT espejo
                    cur.execute(
                        "SELECT id, maquina_id FROM mant_visita_tareas "
                        "WHERE visita_id=%s AND maquina_id IS NOT NULL",
                        (vid,)
                    )
                    tareas_oot = cur.fetchall() or []
                    map_mq_tarea = {t["maquina_id"]: t["id"] for t in tareas_oot}

                    for f in fotos_lev:
                        # Saltar si ya existe la vinculación (evita duplicados al
                        # cerrar idempotente).
                        cloudinary_url = f.get("cloudinary_url") or ""
                        if not cloudinary_url:
                            continue
                        cur.execute(
                            "SELECT id FROM mant_visita_fotos "
                            "WHERE visita_id=%s "
                            "  AND COALESCE(cloudinary_url,'')=%s "
                            "LIMIT 1",
                            (vid, cloudinary_url)
                        )
                        if cur.fetchone():
                            continue
                        tid_mq = map_mq_tarea.get(f.get("maquina_id"))
                        # mant_visita_fotos.archivo_path es NOT NULL, así que
                        # le pasamos el cloudinary_url como path también (ambas
                        # apuntan al mismo recurso persistente).
                        cur.execute(
                            "INSERT INTO mant_visita_fotos "
                            "(visita_id, tarea_id, maquina_id, archivo_path, "
                            " cloudinary_url, tipo_foto, descripcion, tomada_por) "
                            "VALUES (%s,%s,%s,%s,%s,'levantamiento',%s,%s)",
                            (vid, tid_mq, f.get("maquina_id"),
                             cloudinary_url,  # archivo_path = url para compat
                             cloudinary_url,
                             (f.get("descripcion") or '')[:500],
                             (f.get("tomada_por") or user)[:190])
                        )
                        fotos_vinculadas += 1

                    # 3.b — Marcar tareas como completadas con observación del item
                    for it in items:
                        tid_mq = map_mq_tarea.get(it["maquina_id"])
                        if not tid_mq:
                            continue
                        obs = (it.get("observaciones") or "").strip()
                        ubic = (it.get("ubicacion") or "").strip()
                        est = _lev_estado_label(it.get("estado_capturado"))
                        observ_final = f"Estado capturado: {est}"
                        if ubic: observ_final += f" · Ubicación: {ubic}"
                        if obs: observ_final += f" · {obs[:300]}"
                        cur.execute(
                            "UPDATE mant_visita_tareas SET "
                            "  completada=1, completada_at=NOW(), completada_por=%s, "
                            "  estado_trabajo='completada', "
                            "  observaciones=%s "
                            "WHERE id=%s",
                            (user, observ_final[:1000], tid_mq)
                        )
                        tareas_cerradas += 1

                    # 3.c, 3.d, 3.e — Cerrar OT auditable
                    diagnostico_auto = (
                        f"Levantamiento fotográfico #{lid} cerrado el "
                        f"{_now_chile_str('%d/%m/%Y %H:%M')}. "
                        f"{len(items)} equipo(s) documentado(s) · "
                        f"{lev.get('total_fotos',0)} foto(s) capturadas · "
                        f"{fotos_vinculadas} foto(s) vinculadas a esta OT."
                    )
                    cur.execute(
                        "UPDATE mant_visitas SET "
                        "  estado='cerrada', "
                        "  fecha_realizada=COALESCE(fecha_realizada, CURDATE()), "
                        "  hora_real_fin=COALESCE(hora_real_fin, NOW()), "
                        "  cerrada_at=COALESCE(cerrada_at, NOW()), "
                        "  cerrada_por=%s, "
                        "  diagnostico=COALESCE(NULLIF(diagnostico,''), %s) "
                        "WHERE id=%s",
                        (user, diagnostico_auto, vid)
                    )
                conn.commit()
            finally:
                conn.close()
            # ── Promoción levantamiento → ficha de equipo (async) ──
            # La OT espejo del levantamiento ya está cerrada y suele ser
            # tipo='levantamiento'. Promovemos datos a mant_maquinas.
            try:
                _promover_levantamiento_async(vid, usuario=user)
            except Exception:
                pass
        except Exception as e_ot:
            print(f"[lev_cerrar] error procesando OT espejo: {e_ot}", flush=True)

    try: _mant_log("levantamiento", lid, "cerrado",
                   f"{len(items)} equipo(s) · {lev.get('total_fotos',0)} foto(s) · "
                   f"{fotos_vinculadas} vinculadas a OT · {tareas_cerradas} tareas cerradas")
    except Exception: pass
    return jsonify({
        "ok": True,
        "items_procesados": len(items),
        "visita_cerrada": bool(lev.get("visita_id")),
        "visita_id": lev.get("visita_id"),
        "fotos_vinculadas_a_ot": fotos_vinculadas,
        "tareas_cerradas": tareas_cerradas,
    })


@app.route("/mantenciones/api/levantamientos/<int:lid>/rematerializar", methods=["POST"])
@_mant_required
def mant_lev_rematerializar(lid):
    """Reparación manual bajo demanda: re-intenta materializar a mant_maquinas
    los equipos descubiertos que quedaron huérfanos (maquina_id IS NULL) en un
    levantamiento cuya OT ya cerró. Caso real: OT-2026-00031, 11 equipos
    nunca llegaron a la ficha del cliente porque el hilo de materialización
    en el cierre corría sin app.app_context() (fix aplicado en
    _lev_promover_full_async, 2026-07-08).

    Complementa el backfill automático de boot (_ensure_lev_backfill_
    materializacion, corre solo al desplegar) con un botón que no depende de
    un redeploy: útil si aparece otro caso similar entre despliegues. Corre
    SÍNCRONO dentro del propio request (contexto Flask válido de por sí,
    a diferencia del hilo en background) — reusa la misma función que ya usa
    el cierre normal y el backfill, sin duplicar lógica.
    """
    lev = mysql_fetchone("SELECT * FROM mant_levantamientos WHERE id=%s", (lid,))
    if not lev:
        return jsonify({"ok": False, "error": "Levantamiento no encontrado."}), 404
    vid = lev.get("visita_id")
    if not vid:
        return jsonify({"ok": False, "error": "Este levantamiento no tiene una OT asociada."}), 400

    u = getattr(g, "user", None) or {}
    if not _puede_ot_accion(vid, "aprobar", u):
        return jsonify({"ok": False, "error": "No tienes permiso para reparar esta OT."}), 403

    try:
        pendientes = mysql_fetchone(
            "SELECT COUNT(*) AS n FROM mant_levantamiento_items "
            "WHERE levantamiento_id=%s AND maquina_id IS NULL "
            "  AND COALESCE(nombre_snap,'') <> '' AND COALESCE(es_borrador,0) = 0 "
            "  AND COALESCE(estado_capturado,'') <> 'no_encontrado'",
            (lid,)
        )
    except Exception:
        pendientes = mysql_fetchone(
            "SELECT COUNT(*) AS n FROM mant_levantamiento_items "
            "WHERE levantamiento_id=%s AND maquina_id IS NULL AND COALESCE(nombre_snap,'') <> ''",
            (lid,)
        )
    if not pendientes or not pendientes.get("n"):
        return jsonify({"ok": True, "creados": 0, "errores": 0,
                         "mensaje": "No hay equipos pendientes de materializar — todo al día."})

    user = current_username() or "sistema"
    out = _lev_materializar_equipos_nuevos(vid, usuario=user)
    try:
        _mant_log("visita", vid, "levantamiento_rematerializado_manual",
                   f"{out.get('creados', 0)} equipo(s) materializado(s) manualmente por "
                   f"{user} (pendientes antes={pendientes['n']}, errores={out.get('errores', 0)})")
    except Exception:
        pass
    return jsonify({"ok": True, "creados": out.get("creados", 0), "errores": out.get("errores", 0)})


def _mant_maquinas_para_etiqueta(ids):
    """Trae los equipos (mant_maquinas) que van a imprimirse, YA excluidos
    los pisos/accesorios -- Daniel 2026-08-30: "el número de serie deberá
    ser impreso y generar etiquetas, siempre excluyendo los pisos y los
    accesorios". El filtro se aplica ACÁ (no solo ocultando el botón en el
    frontend) para que nadie pueda saltárselo armando la URL a mano.

    Sin clasificar (repetible=None) -> se PERMITE igual, mismo criterio
    conservador que usa el resto del proyecto (_equipo_lleva_serie_individual,
    la ficha del cliente): no bloquear por falta de dato.

    Devuelve (rows, excluidos) -- `excluidos` es la cantidad de ids pedidos
    que SÍ eran piso/accesorio y se descartaron, para que el caller pueda
    avisar en vez de fallar en silencio."""
    ids = [int(x) for x in (ids or []) if str(x).strip().isdigit()]
    if not ids:
        return [], 0
    ph = ",".join(["%s"] * len(ids))
    rows = mysql_fetchall(
        f"SELECT m.id, m.nombre, m.sku, m.serie, m.marca, m.modelo, "
        f"       m.ubicacion_sala, m.cantidad, m.estado, "
        f"       c.razon_social AS cliente_nombre, c.rut AS cliente_rut, "
        f"       c.id AS cliente_id "
        f"  FROM mant_maquinas m "
        f"  JOIN mant_clientes c ON c.id = m.cliente_id "
        f" WHERE m.id IN ({ph}) "
        f" ORDER BY m.nombre",
        tuple(ids)
    ) or []
    rows = [dict(r) for r in rows]
    clasif_map = _inc_clasificacion_skus_batch([r.get("sku") for r in rows])
    permitidos = []
    for r in rows:
        rep = (clasif_map.get((r.get("sku") or "").strip()) or {}).get("repetible")
        if rep is True:
            continue  # piso/accesorio -- NUNCA se imprime etiqueta de equipo
        permitidos.append(r)
    excluidos = len(rows) - len(permitidos)
    return permitidos, excluidos


@app.route("/mantenciones/maquinas/etiquetas")
@_mant_required
def mant_maquinas_etiquetas_pdf():
    """Genera el PDF de etiqueta(s) de EQUIPO para uno o varios
    mant_maquinas.id -- 3ra variante del mismo motor de etiquetas del
    proyecto (Catálogo/Productos y Bodega de Repuestos son las otras dos),
    reusando _label_format()/_pw_pdf() tal cual (Daniel 2026-08-30: "el
    número de serie deberá ser impreso y generar etiquetas, siempre
    excluyendo los pisos y los accesorios").

    El código de barras/caja principal de la etiqueta es el N° DE SERIE
    (identifica esta unidad física exacta), no el SKU (que identifica el
    modelo y se repite en muchas unidades) -- ver
    templates/maquina_label_standalone.html."""
    ids_raw = (request.args.get("ids") or "").strip()
    ids = [int(x) for x in ids_raw.split(",") if x.strip().isdigit()]
    if not ids:
        return jsonify({"ok": False, "error": "Sin equipos seleccionados"}), 400
    fmt = request.args.get("fmt") or "100x50"
    rows, _excluidos = _mant_maquinas_para_etiqueta(ids)
    if not rows:
        return jsonify({"ok": False, "error": "Ningún equipo válido para etiqueta "
                         "(pisos y accesorios no llevan etiqueta de equipo)."}), 404
    label_format = _label_format(fmt)
    fecha = _now_chile_str("%d-%m-%Y %H:%M")
    html = render_template(
        "maquina_label_standalone.html",
        maquinas=rows, fecha=fecha,
        fmt=label_format["key"], label_format=label_format,
        logo_url=_logo_data_url(),
    )
    pdf_bytes = _pw_pdf(
        html, width=label_format["w"], height=label_format["h"],
        wait_fn=(
            "() => {"
            "  const codes = Array.from(document.querySelectorAll('.barcode'));"
            "  return codes.length > 0 && codes.every(c => c.dataset.rendered === '1');"
            "}"
        ),
    )
    resp = make_response(pdf_bytes)
    resp.headers["Content-Type"] = "application/pdf"
    disposition = "attachment" if request.args.get("download") == "1" else "inline"
    resp.headers["Content-Disposition"] = f"{disposition}; filename=etiquetas-equipos.pdf"
    return resp


@app.route("/mantenciones/maquinas/imprimir")
@app.route("/servicio-tecnico/maquinas/imprimir")
@_mant_required
def mant_maquinas_print_labels():
    """Vista previa de impresión de etiquetas de equipo -- mismo patrón UX
    que repuestos_print_labels()/print_labels.html: toolbar + vista previa
    HTML en vivo + panel de tamaño/acciones. El PDF real lo sigue generando
    mant_maquinas_etiquetas_pdf() (mismo pipeline Playwright); esta vista
    solo arma la previsualización y apunta los botones a esa misma ruta."""
    ids_raw = (request.args.get("ids") or "").strip()
    ids = [int(x) for x in ids_raw.split(",") if x.strip().isdigit()]
    if not ids:
        flash("Selecciona al menos un equipo para imprimir etiquetas.", "warning")
        return redirect(url_for("mant_index"))
    fmt = request.args.get("fmt") or "100x50"
    label_format = _label_format(fmt)
    rows, excluidos = _mant_maquinas_para_etiqueta(ids)
    if not rows:
        flash("Los equipos seleccionados son pisos/accesorios y no llevan "
              "etiqueta de equipo, o no se encontraron.", "danger")
        return redirect(url_for("mant_index"))
    if excluidos:
        flash(f"{excluidos} equipo(s) seleccionado(s) son piso/accesorio y se "
              f"excluyeron automáticamente (no llevan etiqueta de equipo).", "warning")
    fecha = _now_chile_str("%d-%m-%Y %H:%M")
    ids_csv = ",".join(str(r["id"]) for r in rows)
    cliente_id = rows[0].get("cliente_id") if len(set(r.get("cliente_id") for r in rows)) == 1 else None
    response = make_response(render_template(
        "maquina_print_labels.html",
        maquinas=rows, fecha=fecha,
        fmt=label_format["key"], label_format=label_format,
        logo_url=_logo_data_url(), ids_csv=ids_csv,
        cliente_id=cliente_id,
    ))
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    return response


@app.route("/mantenciones/maquinas/<int:mid>")
@app.route("/servicio-tecnico/maquinas/<int:mid>")
@_mant_required
def mant_maquina_ficha(mid):
    """Ficha completa del equipo del cliente con:
    - Datos del equipo (foto, marca, modelo, año, voltaje, ubicación)
    - Historial completo de OTs gestionadas (cronológico)
    - Galería de fotos cronológica
    - Stats: cuántas OTs, cuántas fotos, primera/última visita, técnicos
    - Audit log: cambios en serie + eventos

    Permisos: si role=tecnico, solo puede ver equipos que pertenecen a
    una OT que tiene asignada (como principal o colaborador).
    """
    eq = mysql_fetchone(
        "SELECT m.*, c.razon_social, c.id AS cliente_id, c.direccion AS cli_direccion, "
        "       c.comuna AS cli_comuna, c.email_empresa AS cli_email, "
        "       c.tel_empresa AS cli_tel "
        "  FROM mant_maquinas m "
        "  JOIN mant_clientes c ON c.id = m.cliente_id "
        " WHERE m.id=%s",
        (mid,)
    )
    if not eq:
        flash("Equipo no encontrado.", "danger")
        return redirect(url_for("mant_clientes"))
    eq = dict(eq)

    # Permisos: técnico/tecnico_externo solo ve equipos que están en OTs asignadas a él
    # 🔐 SEGURIDAD (2026-05-17): se añadió tecnico_externo (antes solo tecnico).
    u = getattr(g, "user", None) or {}
    role_u = (u.get("role") or "").lower()
    if role_u in ("tecnico", "tecnico_externo"):
        uid = u.get("id")
        autorizado = mysql_fetchone(
            "SELECT 1 FROM mant_visita_tareas vt "
            "  JOIN mant_visitas v ON v.id = vt.visita_id "
            " WHERE vt.maquina_id=%s "
            "   AND (v.tecnico_user_id=%s "
            "        OR v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
            "                    WHERE tecnico_user_id=%s)) "
            " LIMIT 1",
            (mid, uid, uid)
        )
        if not autorizado:
            print(
                f"[SECURITY] {uid} ({u.get('username')}) intento abrir ficha "
                f"equipo mid={mid} sin OT asignada (role={role_u})",
                flush=True
            )
            flash("Este equipo no está en ninguna OT asignada a ti.", "warning")
            return redirect(url_for("mant_ots_list"))

    # 🔒 2026-08-30 (Daniel, por voz): "al consultar cada producto, deberá
    # indicar cada diagnóstico con el responsable, con fecha y hora — qué
    # técnico lo hizo, cuál fue su diagnóstico". El QUIÉN (revisado_por) es
    # el mismo tipo de dato "quién hizo qué tarea puntual" que Daniel ya
    # pidió reservar SOLO para superadmin esta misma noche (ver
    # _es_superadmin_ficha en mant_ficha ~app.py:61430 y es_superadmin_flag
    # en mant_ot_ejecutar ~app.py:81907 — "jamás se enteren o lo vean los
    # técnicos o los demás"). Se calcula UNA vez acá y se usa para no
    # popular el campo sensible en el dict que arma `ots` más abajo: nunca
    # se confía en esconderlo solo en el template.
    _es_superadmin_ficha = bool((g.permissions or {}).get("superadmin"))

    # Historial COMPLETO de intervenciones (cronológico DESC) — Daniel:
    # "Igual sí me gustaría saber dentro de la ficha, parte, si es que
    # le hicieron mantención, cuándo, quién lo hizo, quién lo gestionó,
    # por qué, todo." — Esto incluye TODAS las OTs (no solo
    # levantamientos), con info enriquecida: diagnóstico, observaciones,
    # número de fotos por equipo y flag de si el levantamiento se aplicó
    # a esta ficha.
    #
    # 2026-08-30 (Daniel, por voz): "quiero ver el detalle de ESE producto
    # ahí" — v.diagnostico es el diagnóstico de TODA la OT (se repite igual
    # en la ficha de cada equipo que tocó esa OT). Se agrega, vía LEFT JOIN
    # a mant_visita_equipos (filtrado por ESTE mid), el diagnóstico
    # ESPECÍFICO que el técnico dejó sobre este equipo en esa visita
    # (observacion_tecnico/estado_revision/revisado_at/revisado_por). Es
    # aditivo: v.diagnostico/v.observaciones NO se tocan.
    # Las columnas de `ve` van con MAX() (nunca hay más de 1 fila por
    # visita_id+maquina_id, UNIQUE KEY uq_visita_maquina) para no chocar
    # con ONLY_FULL_GROUP_BY -- a diferencia del JOIN a `u` (arriba), que
    # sí calza en la excepción de MySQL por unirse contra su PRIMARY KEY,
    # `ve` se une por una UNIQUE KEY compuesta que MySQL no infiere sola.
    ots_rows = mysql_fetchall(
        "SELECT DISTINCT v.id, v.numero_ot, v.titulo, v.fecha_programada, "
        "       v.hora_inicio, v.hora_fin, v.tipo, v.estado, v.descripcion, "
        "       v.observaciones, v.diagnostico, "
        "       v.modalidad_cobro, v.cerrada_at, v.created_by, "
        "       COALESCE(u.nombre, u.username) AS tecnico_nombre, "
        "       (SELECT COUNT(*) FROM mant_visita_fotos f "
        "          WHERE f.visita_id=v.id AND f.maquina_id=%s) AS fotos_count, "
        "       (SELECT MAX(ml.aplicado_a_ficha) "
        "          FROM mant_maquina_levantamientos ml "
        "         WHERE ml.visita_id=v.id AND ml.maquina_id=%s) AS lev_aplicado, "
        "       MAX(ve.observacion_tecnico) AS diag_equipo, "
        "       MAX(ve.estado_revision) AS diag_estado, "
        "       MAX(ve.revisado_at) AS diag_revisado_at, "
        "       MAX(ve.revisado_por) AS diag_revisado_por, "
        "       MAX(ve.razon_saltado) AS diag_razon_saltado "
        "  FROM mant_visitas v "
        "  JOIN mant_visita_tareas t ON t.visita_id = v.id "
        "  LEFT JOIN app_users u ON u.id = v.tecnico_user_id "
        "  LEFT JOIN mant_visita_equipos ve "
        "         ON ve.visita_id = v.id AND ve.maquina_id = %s "
        " WHERE t.maquina_id=%s "
        " GROUP BY v.id "
        " ORDER BY v.fecha_programada DESC, v.id DESC LIMIT 100",
        (mid, mid, mid, mid)
    ) or []
    # ── PERF 2026-05-18 (audit Daniel) ─────────────────────────────
    # Antes: N+1 — 1 query por cada OT en `ots_rows` para traer su primera
    # foto. Para una ficha con 100 OTs eran 100 queries extras.
    # Ahora: 1 sola query batched que trae la primera foto por OT vía
    # subquery con MIN(created_at). Luego dict lookup en Python.
    fotos_por_ot = {}
    try:
        ot_ids = [int(r["id"]) for r in ots_rows if r.get("id")]
        if ot_ids:
            # Placeholder list para IN (...)
            # FIX 2026-05-21: usar tomada_at en vez de created_at (la columna
            # se llama tomada_at en mant_visita_fotos según CREATE TABLE).
            ph = ",".join(["%s"] * len(ot_ids))
            rows_foto = mysql_fetchall(
                f"SELECT f.visita_id, f.archivo_path "
                f"  FROM mant_visita_fotos f "
                f"  JOIN mant_visita_tareas t ON t.id = f.tarea_id "
                f"  JOIN (SELECT f2.visita_id, MIN(f2.tomada_at) AS minc "
                f"          FROM mant_visita_fotos f2 "
                f"          JOIN mant_visita_tareas t2 ON t2.id = f2.tarea_id "
                f"         WHERE f2.visita_id IN ({ph}) AND t2.maquina_id=%s "
                f"         GROUP BY f2.visita_id) x "
                f"    ON x.visita_id = f.visita_id AND x.minc = f.tomada_at "
                f" WHERE t.maquina_id=%s ",
                tuple(ot_ids) + (mid, mid)
            ) or []
            for rf in rows_foto:
                if rf.get("visita_id") and rf["visita_id"] not in fotos_por_ot:
                    fotos_por_ot[rf["visita_id"]] = rf.get("archivo_path")
    except Exception:
        pass

    ots = []
    for r in ots_rows:
        d = dict(r)
        if d.get("fecha_programada"):
            d["fecha_programada"] = str(d["fecha_programada"])[:10]
        if d.get("hora_inicio"):
            d["hora_inicio"] = str(d["hora_inicio"])[:5]
        if d.get("hora_fin"):
            d["hora_fin"] = str(d["hora_fin"])[:5]
        if d.get("cerrada_at"):
            d["cerrada_at"] = str(d["cerrada_at"])[:16]
        d["fotos_count"] = int(d.get("fotos_count") or 0)
        d["lev_aplicado"] = bool(d.get("lev_aplicado"))
        # Foto destacada (batched arriba — sin queries individuales)
        d["foto_destacada"] = fotos_por_ot.get(d["id"])
        # Diagnóstico específico de ESTE equipo en esta visita (puede venir
        # NULL: OT vieja o equipo agregado sin pasar por el checklist nuevo
        # con mant_visita_equipos — el LEFT JOIN simplemente no trae fila).
        d["diag_equipo"] = d.get("diag_equipo") or ""
        d["diag_estado"] = d.get("diag_estado") or ""
        d["diag_razon_saltado"] = d.get("diag_razon_saltado") or ""
        # diag_revisado_at se deja como datetime crudo (no stringificado):
        # el template lo formatea con |chile_fmt (REGLA #6, nunca ISO crudo).
        # 🔒 diag_revisado_por (el QUIÉN) se oculta acá si no es superadmin —
        # ver _es_superadmin_ficha más arriba. Nunca viaja al HTML para
        # nadie más, ni con DevTools.
        if not _es_superadmin_ficha:
            d["diag_revisado_por"] = ""
        ots.append(d)

    # Fotos cronológicas del equipo (de mant_maquina_fotos — capturadas
    # por el técnico en el modo ejecución como foto principal del equipo)
    # FIX 2026-05-21: orden por tomada_at (created_at puede no existir en
    # filas viejas si la migración aún no corrió).
    # TODO (2026-08-10, alcance OT-2026-00042): esta sección solo lee
    # mant_maquina_fotos (la galería "promovida"). Si un equipo se capturó
    # en un levantamiento cuyo link con la OT quedó solo en sentido reverse
    # y la promoción a galería nunca corrió para ese caso, sus fotos de
    # mant_levantamiento_fotos no aparecen acá. Se dejó fuera de este fix
    # a propósito por el alcance (reestructurar esta sección para sumar la
    # tercera fuente toca el JSON que ya consume el template de la ficha).
    # El helper de lectura ya existe listo para reusar cuando se aborde:
    # _ot_equipos_y_fotos(vid)["lev_fotos_idx"] / ["lev_items"].
    # ── Galería del equipo: las DOS fuentes ───────────────────────────
    #
    # REGRESIÓN CORREGIDA (2026-08-19). Al cerrar la contaminación del
    # levantamiento (commit 720c482/b6c3344), las OT de instalación,
    # preventiva e inspección dejaron de escribir en mant_levantamiento_fotos,
    # y como mant_maquina_fotos SOLO se puebla por el carril del
    # levantamiento (al cerrar la OT), las fotos que el técnico toma en
    # esos tipos —los más frecuentes— dejaron de verse en la ficha del
    # equipo. El fix del levantamiento era correcto; el efecto colateral
    # sobre la galería, no.
    #
    # Se resuelve LEYENDO las dos tablas en vez de volver a escribir en la
    # ficha: mant_maquina_fotos (promovidas al cerrar) + mant_visita_fotos
    # (tomadas en cualquier OT, estén o no cerradas). Así la foto se ve al
    # instante y la ficha permanente sigue sin ser pisada por una OT que
    # no es un levantamiento — que es justo lo que Daniel pidió separar.
    #
    # ⚠️ A PROPÓSITO no se toca `calidad_ficha` (~app.py:92805) ni el JSON
    # que lo alimenta: ese score 0-100 decide qué equipos necesitan
    # levantamiento, y 22 de sus puntos dependen de fotos. Si contara
    # también estas, cientos de fichas subirían de nota sin que nadie
    # hubiera capturado un dato nuevo, y el módulo dejaría de señalar el
    # trabajo que falta. Se muestran las fotos; no se cambia el indicador.
    # El UNION va en try: mant_visita_fotos.cloudinary_url se agregó por un
    # ALTER del bloque condicional (app.py:50720), que NO corre con
    # ILUS_SKIP_MIGRATIONS=1. Si en algún ambiente esa columna faltara, la
    # ficha del equipo NO puede caerse: degrada a las fotos promovidas,
    # que es exactamente como estaba antes.
    _sql_union = (
        "SELECT id, archivo_path, cloudinary_url, descripcion, tomada_por, "
        "       tomada_at AS created_at, NULL AS visita_id, 'ficha' AS fuente "
        "  FROM mant_maquina_fotos WHERE maquina_id=%s "
        "UNION ALL "
        "SELECT id, archivo_path, cloudinary_url, descripcion, tomada_por, "
        "       tomada_at AS created_at, visita_id, 'ot' AS fuente "
        "  FROM mant_visita_fotos "
        " WHERE maquina_id=%s AND COALESCE(cloudinary_url, archivo_path, '') <> '' "
        " ORDER BY created_at DESC LIMIT 200"
    )
    try:
        fotos_rows = mysql_fetchall(_sql_union, (mid, mid)) or []
    except Exception as _e_fotos:
        print(f"[maquina_ficha] galeria union: {_e_fotos}", flush=True)
        fotos_rows = mysql_fetchall(
            "SELECT id, archivo_path, cloudinary_url, descripcion, tomada_por, "
            "       tomada_at AS created_at, NULL AS visita_id, 'ficha' AS fuente "
            "  FROM mant_maquina_fotos WHERE maquina_id=%s "
            " ORDER BY tomada_at DESC LIMIT 200", (mid,)) or []
    fotos, _vistas = [], set()
    for r in fotos_rows:
        # FIX 2026-08-27: archivo_path YA trae "uploads/mantenciones/"
        # (mant_visita_fotos_subir / mant_maquina_fotos_subir) --
        # anteponerlo de nuevo duplicaba el segmento y rompía (404) la
        # imagen para cualquier foto que hubiera caído al respaldo de
        # filesystem en vez de GCS. Mismo bug replicado en varios lugares
        # del archivo (ver mant_maquina_ficha_tecnica_json más abajo).
        url = r.get("cloudinary_url") or (
            f"/static/{r['archivo_path']}"
            if r.get("archivo_path") else ""
        )
        if not url or url in _vistas:
            continue  # la misma foto puede estar promovida Y en la visita
        _vistas.add(url)
        fotos.append({
            "id": r["id"],
            "url": url,
            "descripcion": r.get("descripcion") or "",
            "tomada_por": r.get("tomada_por") or "",
            "created_at": str(r["created_at"])[:16] if r.get("created_at") else "",
            "fuente": r.get("fuente") or "ficha",
            "visita_id": r.get("visita_id"),
        })

    # Audit log: eventos del equipo
    eventos_rows = mysql_fetchall(
        "SELECT id, tipo, descripcion, fecha_evento, created_by "
        "  FROM mant_maquina_eventos WHERE maquina_id=%s "
        " ORDER BY fecha_evento DESC LIMIT 50",
        (mid,)
    ) or []
    eventos = []
    for e in eventos_rows:
        d = dict(e)
        if d.get("fecha_evento"):
            d["fecha_evento"] = str(d["fecha_evento"])[:16]
        eventos.append(d)

    # Stats compactas (incluye breakdown para card de historial)
    _estados_abiertos = ("programada", "en_curso", "en_ejecucion", "pendiente_aprobacion")
    stats = {
        "total_ots": len(ots),
        "total_fotos": len(fotos),
        "ots_cerradas": sum(1 for o in ots if o.get("estado") == "cerrada"),
        "ots_abiertas": sum(1 for o in ots if o.get("estado") in _estados_abiertos),
        "ots_canceladas": sum(1 for o in ots if o.get("estado") == "cancelada"),
        "primera_visita": ots[-1]["fecha_programada"] if ots else None,
        "ultima_visita": ots[0]["fecha_programada"] if ots else None,
        "tecnicos": list({o.get("tecnico_nombre") for o in ots if o.get("tecnico_nombre")}),
        # Conteo por tipo para chips/filtros
        "por_tipo": {},
    }
    for _o in ots:
        _t = (_o.get("tipo") or "otro").lower()
        stats["por_tipo"][_t] = stats["por_tipo"].get(_t, 0) + 1

    # ── Levantamientos de esta máquina (último + historial) ──
    # Daniel pidió que en la ficha del equipo se vea la información
    # que rellenó el técnico SOLAMENTE durante el levantamiento de
    # ficha. Otras OTs (preventiva, correctiva, etc.) quedan en el
    # historial pero no se mezclan acá.
    levantamientos = []
    try:
        lev_rows = mysql_fetchall(
            "SELECT ml.id, ml.visita_id, ml.fecha_levantamiento, ml.tecnico_nombre, "
            "       ml.datos_json, ml.fotos_count, ml.observaciones, "
            "       ml.aplicado_a_ficha, ml.aplicado_at, ml.created_at, "
            "       v.numero_ot, v.titulo AS ot_titulo "
            "  FROM mant_maquina_levantamientos ml "
            "  LEFT JOIN mant_visitas v ON v.id = ml.visita_id "
            " WHERE ml.maquina_id=%s "
            " ORDER BY ml.fecha_levantamiento DESC, ml.id DESC "
            " LIMIT 50",
            (mid,)
        ) or []
        for r in lev_rows:
            d = dict(r)
            if d.get("fecha_levantamiento"):
                d["fecha_levantamiento"] = str(d["fecha_levantamiento"])[:10]
            if d.get("aplicado_at"):
                d["aplicado_at"] = str(d["aplicado_at"])[:16]
            if d.get("created_at"):
                d["created_at"] = str(d["created_at"])[:16]
            # Parsear datos_json para mostrarlos como lista
            d["datos"] = []
            if d.get("datos_json"):
                try:
                    d["datos"] = json.loads(d["datos_json"]) or []
                except Exception:
                    d["datos"] = []
            d.pop("datos_json", None)
            # Adjuntar fotos de la OT vinculadas a este equipo
            try:
                fr = mysql_fetchall(
                    "SELECT id, archivo_path, cloudinary_url, descripcion, tomada_por, tomada_at "
                    "  FROM mant_visita_fotos "
                    " WHERE visita_id=%s AND maquina_id=%s "
                    " ORDER BY tomada_at ASC LIMIT 12",
                    (d["visita_id"], mid)
                ) or []
                # FIX 2026-06-02 (Daniel): priorizar cloudinary_url. En Railway el
                # filesystem es efímero → las fotos viven en Cloudinary y archivo_path
                # queda vacío. Antes se filtraba por archivo_path y se descartaban TODAS
                # las fotos de Cloudinary → la ficha no mostraba ninguna foto del levant.
                _lev_fotos = []
                for f in fr:
                    _u = f.get("cloudinary_url") or (
                        f"/static/{f['archivo_path']}" if f.get("archivo_path") else ""
                    )
                    if not _u:
                        continue
                    _lev_fotos.append({
                        "url": _u,
                        "descripcion": f.get("descripcion") or "",
                        "tomada_por": f.get("tomada_por") or "",
                        "tomada_at": str(f["tomada_at"])[:16] if f.get("tomada_at") else "",
                    })
                d["fotos"] = _lev_fotos
            except Exception:
                d["fotos"] = []
            d["numero_ot"] = d.get("numero_ot") or f"VS-{d['visita_id']:05d}"
            levantamientos.append(d)
    except Exception as _e_lev:
        # La tabla puede no existir si la migración no corrió todavía
        print(f"[maquina_ficha] no se pudo cargar levantamientos m={mid}: {_e_lev}",
              flush=True)
        levantamientos = []
    ultimo_levantamiento = levantamientos[0] if levantamientos else None

    # ── Flag is_admin: el template muestra controles override de foto ──
    # (superadmin U admin — a propósito NO se reusa para el diagnóstico por
    # equipo: ese dato exige superadmin ESTRICTO, ver _es_superadmin_ficha).
    perms = g.get("permissions") or {}
    is_admin = bool(perms.get("superadmin") or perms.get("admin"))

    return render_template(
        "mantenciones/maquina_ficha.html",
        equipo=eq,
        ots=ots,
        fotos=fotos,
        eventos=eventos,
        stats=stats,
        levantamientos=levantamientos,
        ultimo_levantamiento=ultimo_levantamiento,
        is_admin=is_admin,
        es_superadmin=_es_superadmin_ficha,
    )


@app.route("/mantenciones/api/maquinas/<int:mid>/timeline")
@_mant_required
def mant_maquina_timeline(mid):
    """Timeline de la 'ficha potente' del equipo: eventos + fotos + visitas."""
    eventos = mysql_fetchall(
        "SELECT id, tipo, descripcion, fecha_evento, referencia_tabla, referencia_id, "
        "       metadata_json, created_by "
        "  FROM mant_maquina_eventos WHERE maquina_id=%s "
        " ORDER BY fecha_evento DESC LIMIT 100",
        (mid,)
    ) or []
    for e in eventos:
        if e.get("fecha_evento"):
            e["fecha_evento"] = str(e["fecha_evento"])[:16]
        if e.get("metadata_json"):
            try: e["metadata"] = json.loads(e["metadata_json"])
            except Exception: e["metadata"] = None
        e.pop("metadata_json", None)
    return jsonify({"ok": True, "eventos": eventos})


@app.route("/mantenciones/api/maquinas/<int:mid>/historial-ots")
@_mant_required
def mant_maquina_historial_ots(mid):
    """Historial de OTs ejecutadas sobre este equipo.
    Une con mant_visita_tareas (donde la tarea tiene maquina_id=mid) y devuelve
    cada OT distinta con fecha, hora, tipo, estado, técnico responsable y
    usuario que la cerró.
    """
    rows = mysql_fetchall(
        """SELECT DISTINCT v.id, v.numero_ot, v.titulo, v.fecha_programada,
                  v.hora_inicio, v.hora_fin, v.hora_real_inicio, v.hora_real_fin,
                  v.tipo, v.estado, v.descripcion, v.tecnico,
                  v.cerrada_at, v.created_by,
                  COALESCE(u.nombre, u.username) AS tecnico_nombre,
                  u.username AS tecnico_username
             FROM mant_visitas v
             JOIN mant_visita_tareas t ON t.visita_id=v.id
             LEFT JOIN app_users u ON u.id=v.tecnico_user_id
            WHERE t.maquina_id=%s
            ORDER BY v.fecha_programada DESC, v.id DESC
            LIMIT 100""",
        (mid,)
    ) or []
    out = []
    for r in rows:
        out.append({
            "id":              r["id"],
            "numero_ot":       r.get("numero_ot") or f"VS-{r['id']:05d}",
            "titulo":          r.get("titulo") or "",
            "fecha":           str(r["fecha_programada"])[:10] if r.get("fecha_programada") else "",
            "hora_inicio":     str(r["hora_inicio"])[:5] if r.get("hora_inicio") else "",
            "hora_fin":        str(r["hora_fin"])[:5] if r.get("hora_fin") else "",
            "hora_real_ini":   str(r["hora_real_inicio"])[:16] if r.get("hora_real_inicio") else "",
            "hora_real_fin":   str(r["hora_real_fin"])[:16] if r.get("hora_real_fin") else "",
            "tipo":            r.get("tipo") or "",
            "estado":          r.get("estado") or "",
            "descripcion":     r.get("descripcion") or "",
            "tecnico":         r.get("tecnico_nombre") or r.get("tecnico") or "",
            "tecnico_username": r.get("tecnico_username") or "",
            "creado_por":      r.get("created_by") or "",
            "cerrada_at":      str(r["cerrada_at"])[:16] if r.get("cerrada_at") else "",
            # Link directo a la ficha OT
            "url":             f"/mantenciones/ot/{r['id']}",
        })
    return jsonify({"ok": True, "ots": out, "total": len(out)})


# ════════════════════════════════════════════════════════════════════════
# FICHA TÉCNICA INLINE (JSON) — usado en el modal "Ver ficha técnica"
# del flujo de levantamiento (ot_ejecutar.html) y desde la ficha del
# cliente, tab Equipos. Snapshot completo con trazabilidad profunda.
#
# Daniel (2026-05-21): "Cuántas veces se ha visitado este equipo (no el
# cliente, el equipo específico) + historial cambios serial + estado +
# galería de fotos por visita + alertas dinámicas + contratos relacionados".
#
# Performance: queries críticas indexadas (mant_visita_tareas.maquina_id,
# mant_maquina_fotos.maquina_id, mant_maquina_audit.maquina_id). Para
# fichas con >20 OTs históricas, se usa paginación implícita (LIMIT 100
# en historial + LIMIT 50 en seriales/estados).
# ════════════════════════════════════════════════════════════════════════

# ─────────────────────────────────────────────────────────────────────
# ENDPOINT BATCH FICHA TÉCNICA (Daniel 2026-05-26 audit DevTools):
# El frontend mostraba 51 fetch (uno por máquina × 3.6s) = N+1 grave.
# Este endpoint devuelve un dict {id: ficha_resumida} de muchos equipos
# en UNA sola request, con datos LIGHT suficientes para la tabla.
# El detalle profundo (todas las tabs) sigue en el endpoint individual.
# ─────────────────────────────────────────────────────────────────────
@app.route("/mantenciones/api/maquinas/ficha-tecnica-batch")
@_mant_required
def mant_maquinas_ficha_tecnica_batch():
    """Versión LIGHT batch para la tabla de equipos del cliente.

    Query: ?ids=1,2,3,4,5 (máximo 200 ids)

    Devuelve { ok, items: { "1": {nombre, foto_url, score, ...}, ... } }

    Para datos profundos (historial, alertas, revisiones), usar el
    endpoint individual /api/maquinas/<mid>/ficha-tecnica.
    """
    ids_param = (request.args.get("ids") or "").strip()
    if not ids_param:
        return jsonify({"ok": True, "items": {}})
    try:
        ids = [int(x) for x in ids_param.split(",") if x.strip()]
        ids = list(dict.fromkeys(ids))[:200]  # dedup + cap
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "ids inválidos"}), 400
    if not ids:
        return jsonify({"ok": True, "items": {}})

    placeholders = ",".join(["%s"] * len(ids))

    # 1 query — datos básicos de los equipos
    eq_rows = mysql_fetchall(
        f"SELECT id, cliente_id, nombre, sku, serie, marca, modelo, "
        f"       estado, estado_op, foto_url, familia_equipo, "
        f"       ubicacion_sala, anio_fabricacion, fecha_fin_garantia "
        f"  FROM mant_maquinas WHERE id IN ({placeholders})",
        tuple(ids)
    ) or []

    # 1 query — última foto por equipo (Cloudinary o disco)
    fotos_map = {}
    try:
        rows_f = mysql_fetchall(
            f"SELECT maquina_id, MAX(tomada_at) AS ultima, "
            f"       COUNT(*) AS n_fotos "
            f"  FROM mant_maquina_fotos WHERE maquina_id IN ({placeholders}) "
            f" GROUP BY maquina_id",
            tuple(ids)
        ) or []
        for r in rows_f:
            fotos_map[r["maquina_id"]] = {
                "ultima_foto": str(r["ultima"])[:10] if r.get("ultima") else "",
                "n_fotos": int(r.get("n_fotos") or 0),
            }
    except Exception:
        pass

    # 1 query — última revisión por equipo (estado + fecha)
    rev_map = {}
    try:
        rows_r = mysql_fetchall(
            f"SELECT maquina_id, estado_revision, revisado_por, revisado_at "
            f"  FROM mant_visita_equipos "
            f" WHERE maquina_id IN ({placeholders}) "
            f"   AND revisado_at IS NOT NULL "
            f" ORDER BY revisado_at DESC",
            tuple(ids)
        ) or []
        for r in rows_r:
            mid_r = r["maquina_id"]
            if mid_r not in rev_map:  # tomar solo la más reciente
                rev_map[mid_r] = {
                    "ultima_revision_fecha": str(r["revisado_at"])[:10] if r.get("revisado_at") else "",
                    "ultima_revision_estado": r.get("estado_revision") or "",
                    "ultima_revision_por": r.get("revisado_por") or "",
                }
    except Exception:
        pass

    items = {}
    hoy = datetime.now().date()
    for eq in eq_rows:
        mid = eq["id"]
        # Score de calidad LIGHT (criterios rápidos sin queries extras)
        fotos_data = fotos_map.get(mid, {})
        rev_data   = rev_map.get(mid, {})
        score = 0
        if eq.get("foto_url"):           score += 12
        if eq.get("serie"):              score += 10
        if eq.get("sku"):                score += 8
        if eq.get("familia_equipo") and eq.get("familia_equipo") != "otros": score += 8
        if eq.get("ubicacion_sala"):     score += 8
        if eq.get("marca") or eq.get("modelo"): score += 8
        if eq.get("anio_fabricacion"):   score += 6
        if fotos_data.get("n_fotos", 0) > 0:    score += 10
        if rev_data.get("ultima_revision_fecha"): score += 10
        if eq.get("fecha_fin_garantia"): score += 4
        # +16 puntos no calculables en batch (contrato, observaciones)
        # se considera "perfecto" al 84 en batch
        estado_calidad = (
            "completa" if score >= 70
            else "buena" if score >= 50
            else "revisar_datos" if score >= 30
            else "incompleta"
        )
        items[str(mid)] = {
            "id":         mid,
            "nombre":     eq.get("nombre") or "",
            "sku":        eq.get("sku") or "",
            "serie":      eq.get("serie") or "",
            "marca":      eq.get("marca") or "",
            "modelo":     eq.get("modelo") or "",
            "familia":    eq.get("familia_equipo") or "",
            "ubicacion":  eq.get("ubicacion_sala") or "",
            "estado":     eq.get("estado") or "activo",
            "foto_url":   eq.get("foto_url") or "",
            "n_fotos":    fotos_data.get("n_fotos", 0),
            "ultima_foto":          fotos_data.get("ultima_foto", ""),
            "ultima_revision_fecha":  rev_data.get("ultima_revision_fecha", ""),
            "ultima_revision_estado": rev_data.get("ultima_revision_estado", ""),
            "ultima_revision_por":    rev_data.get("ultima_revision_por", ""),
            "calidad_score":   score,
            "calidad_estado":  estado_calidad,
        }
    return jsonify({"ok": True, "items": items, "count": len(items)})


# ── Cache 60s del JSON ficha-tecnica por máquina (Daniel 2026-05-27) ──
# Live audit: 7-9 queries × 400ms latencia red = 3.2s por click en ojo.
# El dict completo es ~3KB. Cachear 60s por maquina_id corta esto a ~10ms.
# Invalidación: llamar _ft_cache_invalidar(mid) tras editar el equipo.
_FT_JSON_CACHE = {}  # mid -> (data_dict, ts)
_FT_JSON_LOCK  = threading.Lock()
_FT_JSON_TTL   = 60


def _ft_cache_invalidar(mid=None):
    """Llamar tras editar equipo / agregar foto / cambiar serie / nueva OT."""
    with _FT_JSON_LOCK:
        if mid is None:
            _FT_JSON_CACHE.clear()
        else:
            _FT_JSON_CACHE.pop(int(mid), None)


@app.route("/mantenciones/api/maquinas/<int:mid>/ficha-tecnica")
@_mant_required
def mant_maquina_ficha_tecnica_json(mid):
    """Snapshot JSON profundo de la ficha técnica del equipo.
    Cacheado 60s por maquina_id (audit DevTools: era 3.2s por click).

    Estructura devuelta:
      - equipo       → datos básicos + cliente + ubicación + garantía
      - stats        → contadores y métricas (visitas, fotos, edad, días desde última)
      - historial_visitas    → últimas 100 OTs sobre este equipo
      - historial_seriales   → audit log de cambios de N° serie
      - historial_estado     → audit log de cambios de estado
      - fotos_galeria        → galería permanente del equipo (mant_maquina_fotos)
      - contratos_relacionados → contratos vigentes del cliente
      - alertas      → alertas dinámicas calculadas
    """
    # Cache hit (rápido y seguro: la ficha cambia con frecuencia DE MINUTOS)
    _now_ft = time.time()
    with _FT_JSON_LOCK:
        _entry_ft = _FT_JSON_CACHE.get(mid)
    if _entry_ft and (_now_ft - _entry_ft[1]) < _FT_JSON_TTL:
        return jsonify(_entry_ft[0])

    eq = mysql_fetchone(
        "SELECT m.*, c.razon_social, c.rut AS cli_rut, c.direccion AS cli_direccion, "
        "       c.comuna AS cli_comuna "
        "  FROM mant_maquinas m "
        "  JOIN mant_clientes c ON c.id = m.cliente_id "
        " WHERE m.id=%s",
        (mid,)
    )
    if not eq:
        return jsonify({"ok": False, "error": "Equipo no encontrado"}), 404
    eq = dict(eq)

    # Permisos: técnico solo ve si la máquina está en una OT asignada a él.
    u = getattr(g, "user", None) or {}
    role_u = (u.get("role") or "").lower()
    if role_u in ("tecnico", "tecnico_externo"):
        uid = u.get("id")
        autorizado = mysql_fetchone(
            "SELECT 1 FROM mant_visita_tareas vt "
            "  JOIN mant_visitas v ON v.id = vt.visita_id "
            " WHERE vt.maquina_id=%s "
            "   AND (v.tecnico_user_id=%s "
            "        OR v.id IN (SELECT visita_id FROM mant_visita_tecnicos "
            "                    WHERE tecnico_user_id=%s)) "
            " LIMIT 1",
            (mid, uid, uid)
        )
        if not autorizado:
            return jsonify({"ok": False, "error": "Equipo no asignado a tus OTs"}), 403

    hoy = datetime.now().date()
    cliente_id = eq.get("cliente_id")

    # F-LEV 2026-06-10 (Daniel): si el equipo NO tiene N° de serie, SUGERIR la
    # serie ILUS que se generaría (la "que ya viene de cuando se crea el
    # producto"). El técnico la acepta con un click en el modal de captura.
    #
    # 2026-08-20 — se agregan tres datos NUEVOS al lado, sin tocar el
    # contrato de `serie_sugerida`: sigue siendo string o None porque el
    # modal hace String(e.serie_sugerida) y lo graba tal cual con un click
    # (static/mantenciones_ot_ejecutar.js). Devolver otra cosa acá escribiría
    # basura en el campo que alimenta la etiqueta de garantía.
    #
    # Por qué hacían falta: medido ese día, 179 de 179 equipos ya tenían
    # serie genérica, así que la condición "si NO tiene serie" era falsa
    # siempre y este bloque nunca corría. El banner existía y no se veía
    # nunca. Lo que falta no es rellenar un vacío: es poder REEMPLAZAR el
    # genérico por el de la placa, que es lo que Daniel pidió.
    _serie_actual = (eq.get("serie") or "").strip()
    try:
        _lleva_serie, _motivo_no_serie = _equipo_lleva_serie_individual(eq)
    except Exception:
        # Ante cualquier problema, asumimos que SÍ lleva: es preferible
        # preguntar de más que dejar una máquina sin identificar. Y nunca
        # a costa de tumbar la ficha con el técnico en terreno.
        _lleva_serie, _motivo_no_serie = True, ""
    eq["serie_lleva_individual"] = bool(_lleva_serie)
    eq["serie_no_aplica_motivo"] = _motivo_no_serie or ""
    eq["serie_es_provisoria"] = _serie_es_provisoria(_serie_actual)

    if _lleva_serie and not _serie_actual:
        try:
            eq["serie_sugerida"] = _generar_serie_ilus(cliente_id, eq.get("sku") or "")
        except Exception:
            eq["serie_sugerida"] = None

    # ── 1. Fotos galería: mant_maquina_fotos (promovidas) UNION
    #    mant_visita_fotos (tomadas en CUALQUIER OT, promovida o no) ──
    # FIX 2026-08-27 (Daniel: "las fotos que tengan se puede asignar afuera
    # en la parte de fotografía del equipo"): esta sección SOLO leía
    # mant_maquina_fotos, que se puebla recién cuando se PROMUEVE un
    # levantamiento al cerrar la OT (_promover_levantamiento_a_maquina).
    # Una foto tomada durante una OT en curso -- o una OT que nunca fue un
    # levantamiento -- vive en mant_visita_fotos y nunca llegaba acá, aunque
    # el propio tab que consume este JSON (_ftRenderFotos en mant_ficha.js)
    # promete: "cuando un técnico capture fotos del equipo en una OT...
    # aparecerán aquí". Se aplica el MISMO patrón ya probado en
    # mant_maquina_ficha (arriba en este archivo, ~línea 98896, corregido
    # 2026-08-19 por esta misma causa) -- se REUSA la consulta en vez de
    # reescribir la lógica o duplicar filas en otra tabla (más seguro: no
    # hay que decidir qué pasa si la foto original se borra).
    # ORDER BY tomada_at (existe desde la migración inicial). NO usamos
    # created_at porque puede no estar poblado en filas viejas.
    _sql_ft_fotos = (
        "SELECT id, archivo_path, cloudinary_url, descripcion, tipo_foto, "
        "       tomada_por, tomada_at, visita_origen, levantamiento_id "
        "  FROM mant_maquina_fotos WHERE maquina_id=%s "
        "UNION ALL "
        "SELECT id, archivo_path, cloudinary_url, descripcion, tipo_foto, "
        "       tomada_por, tomada_at, visita_id AS visita_origen, "
        "       NULL AS levantamiento_id "
        "  FROM mant_visita_fotos "
        " WHERE maquina_id=%s AND COALESCE(cloudinary_url, archivo_path, '') <> '' "
        " ORDER BY tomada_at DESC LIMIT 50"
    )
    try:
        fotos_rows = mysql_fetchall(_sql_ft_fotos, (mid, mid)) or []
    except Exception as _e_ft_fotos:
        # Degradación segura: si mant_visita_fotos.cloudinary_url no existe
        # todavía en este ambiente (columna agregada por un ALTER
        # condicional que ILUS_SKIP_MIGRATIONS=1 salta, ver app.py:50720),
        # la ficha NO se cae -- vuelve al comportamiento anterior (solo la
        # galería ya promovida).
        print(f"[ficha_tecnica_json] galeria union mid={mid}: {_e_ft_fotos}", flush=True)
        fotos_rows = mysql_fetchall(
            "SELECT id, archivo_path, cloudinary_url, descripcion, tipo_foto, "
            "       tomada_por, tomada_at, visita_origen, levantamiento_id "
            "  FROM mant_maquina_fotos WHERE maquina_id=%s "
            " ORDER BY tomada_at DESC LIMIT 50",
            (mid,)
        ) or []
    fotos_galeria = []
    _ft_fotos_vistas = set()
    foto_principal_url = (eq.get("foto_url") or "").strip()
    for r in fotos_rows:
        # FIX 2026-08-27: archivo_path YA incluye el prefijo "uploads/
        # mantenciones/" (así lo guardan mant_visita_fotos_subir y
        # mant_maquina_fotos_subir) -- anteponerlo de nuevo duplicaba el
        # segmento y la URL resultante siempre daba 404 (imagen rota) para
        # cualquier foto que hubiera caído al respaldo de filesystem en vez
        # de Google Cloud Storage.
        url = r.get("cloudinary_url") or (
            f"/static/{r['archivo_path']}"
            if r.get("archivo_path") else ""
        )
        if not url or url in _ft_fotos_vistas:
            continue  # la misma foto puede estar promovida Y en la visita
        _ft_fotos_vistas.add(url)
        # Para la primera (más reciente) que tenga visita_origen, marcamos
        # como referencia para la "última foto del último levantamiento"
        if not foto_principal_url and url:
            foto_principal_url = url
        fotos_galeria.append({
            "id": r["id"],
            "url": url,
            "tipo_foto": r.get("tipo_foto") or "principal",
            "descripcion": r.get("descripcion") or "",
            "tomada_por": r.get("tomada_por") or "",
            "fecha": str(r["tomada_at"])[:16] if r.get("tomada_at") else "",
            "visita_origen": r.get("visita_origen"),
            "levantamiento_id": r.get("levantamiento_id"),
        })

    # ── 2. Historial de visitas (TODAS las OTs con tareas sobre este equipo) ──
    visitas_rows = mysql_fetchall(
        "SELECT DISTINCT v.id, v.numero_ot, v.titulo, v.tipo, v.estado, "
        "       v.fecha_programada, v.cerrada_at, v.observaciones, v.diagnostico, "
        "       v.factura_tido, v.factura_nudo, "
        "       COALESCE(u.nombre, u.username) AS tecnico_nombre, "
        "       (SELECT COUNT(*) FROM mant_visita_fotos f "
        "          WHERE f.visita_id=v.id AND f.maquina_id=%s) AS fotos_count "
        "  FROM mant_visitas v "
        "  JOIN mant_visita_tareas t ON t.visita_id=v.id "
        "  LEFT JOIN app_users u ON u.id=v.tecnico_user_id "
        " WHERE t.maquina_id=%s "
        " GROUP BY v.id "
        " ORDER BY v.fecha_programada DESC, v.id DESC LIMIT 100",
        (mid, mid)
    ) or []
    historial_visitas = []
    n_preventivas = 0
    n_correctivas = 0
    n_levantamientos = 0
    ultima_fecha = None
    ultima_tipo = None
    ultima_preventiva = None
    for r in visitas_rows:
        tipo_v = (r.get("tipo") or "").lower()
        if tipo_v == "preventiva":
            n_preventivas += 1
            if not ultima_preventiva and r.get("fecha_programada"):
                ultima_preventiva = r["fecha_programada"]
        elif tipo_v == "correctiva":
            n_correctivas += 1
        elif tipo_v == "levantamiento":
            n_levantamientos += 1
        if ultima_fecha is None and r.get("fecha_programada"):
            ultima_fecha = r["fecha_programada"]
            ultima_tipo = r.get("tipo") or ""
        factura = None
        if r.get("factura_tido") and r.get("factura_nudo"):
            factura = {"tido": r["factura_tido"], "nudo": r["factura_nudo"]}
        historial_visitas.append({
            "id": r["id"],
            "numero_ot": r.get("numero_ot") or f"VS-{r['id']:05d}",
            "titulo": r.get("titulo") or "",
            "fecha": str(r["fecha_programada"])[:10] if r.get("fecha_programada") else "",
            "tipo": r.get("tipo") or "",
            "estado": r.get("estado") or "",
            "tecnico": r.get("tecnico_nombre") or "",
            "observaciones": (r.get("observaciones") or "")[:300],
            "diagnostico": (r.get("diagnostico") or "")[:300],
            "fotos_count": int(r.get("fotos_count") or 0),
            "cerrada_at": str(r["cerrada_at"])[:16] if r.get("cerrada_at") else "",
            "factura": factura,
            "url": f"/mantenciones/ot/{r['id']}",
        })

    # ── 3. Historial de seriales (mant_maquina_audit, campo='serie') ──
    historial_seriales = []
    try:
        ser_rows = mysql_fetchall(
            "SELECT fecha, valor_antes, valor_nuevo, motivo, usuario "
            "  FROM mant_maquina_audit "
            " WHERE maquina_id=%s AND campo='serie' "
            " ORDER BY fecha DESC LIMIT 50",
            (mid,)
        ) or []
        for r in ser_rows:
            historial_seriales.append({
                "fecha": str(r["fecha"])[:16] if r.get("fecha") else "",
                "valor_anterior": r.get("valor_antes") or "",
                "valor_nuevo": r.get("valor_nuevo") or "",
                "razon": r.get("motivo") or "",
                "usuario": r.get("usuario") or "",
            })
    except Exception:
        historial_seriales = []

    # ── 4. Historial de estado (mant_maquina_audit, campo='estado') ──
    historial_estado = []
    try:
        est_rows = mysql_fetchall(
            "SELECT fecha, valor_antes, valor_nuevo, motivo, usuario "
            "  FROM mant_maquina_audit "
            " WHERE maquina_id=%s AND campo IN ('estado','estado_op','dado_baja') "
            " ORDER BY fecha DESC LIMIT 50",
            (mid,)
        ) or []
        for r in est_rows:
            historial_estado.append({
                "fecha": str(r["fecha"])[:16] if r.get("fecha") else "",
                "estado_anterior": r.get("valor_antes") or "",
                "estado_nuevo": r.get("valor_nuevo") or "",
                "razon": r.get("motivo") or "",
                "usuario": r.get("usuario") or "",
            })
    except Exception:
        historial_estado = []

    # ── 5. Contratos relacionados (vigentes / por vencer) ──
    contratos = []
    try:
        c_rows = mysql_fetchall(
            "SELECT id, nombre, fecha_inicio, fecha_vencimiento, es_indefinido, "
            "       estado, monto_mensual, sla_horas "
            "  FROM mant_contratos "
            " WHERE cliente_id=%s "
            "   AND estado IN ('vigente','indefinido','por_vencer') "
            " ORDER BY fecha_inicio DESC LIMIT 10",
            (cliente_id,)
        ) or []
        for r in c_rows:
            dias_restantes = None
            if r.get("fecha_vencimiento") and not r.get("es_indefinido"):
                fv = r["fecha_vencimiento"]
                if isinstance(fv, datetime):
                    fv = fv.date()
                try:
                    dias_restantes = (fv - hoy).days
                except Exception:
                    dias_restantes = None
            contratos.append({
                "id": r["id"],
                "nombre": r.get("nombre") or "",
                "fecha_inicio": str(r["fecha_inicio"])[:10] if r.get("fecha_inicio") else "",
                "fecha_vencimiento": str(r["fecha_vencimiento"])[:10] if r.get("fecha_vencimiento") else "",
                "es_indefinido": bool(r.get("es_indefinido")),
                "estado": r.get("estado") or "vigente",
                "dias_restantes": dias_restantes,
            })
    except Exception:
        contratos = []

    # ── 6. STATS calculadas ────────────────────────────────────────
    dias_desde_ultima = None
    if ultima_fecha:
        f_ult = ultima_fecha
        if isinstance(f_ult, datetime):
            f_ult = f_ult.date()
        try:
            dias_desde_ultima = (hoy - f_ult).days
        except Exception:
            dias_desde_ultima = None

    edad_anios = None
    if eq.get("anio_fabricacion"):
        try:
            edad_anios = round(hoy.year - int(eq["anio_fabricacion"]) +
                              (hoy.month - 1) / 12.0, 1)
        except Exception:
            edad_anios = None

    dias_en_garantia = None
    if eq.get("fecha_fin_garantia"):
        fg = eq["fecha_fin_garantia"]
        if isinstance(fg, datetime):
            fg = fg.date()
        try:
            dias_en_garantia = (fg - hoy).days
        except Exception:
            dias_en_garantia = None

    stats = {
        "n_visitas_total": len(historial_visitas),
        "n_visitas_preventivas": n_preventivas,
        "n_visitas_correctivas": n_correctivas,
        "n_levantamientos": n_levantamientos,
        "n_fotos_total": len(fotos_galeria),
        "n_cambios_serial": len(historial_seriales),
        "n_cambios_estado": len(historial_estado),
        "ultima_visita_fecha": str(ultima_fecha)[:10] if ultima_fecha else None,
        "ultima_visita_tipo": ultima_tipo or "",
        "dias_desde_ultima_visita": dias_desde_ultima,
        "edad_anios": edad_anios,
        "dias_en_garantia": dias_en_garantia,
    }

    # ── 7. ALERTAS dinámicas ───────────────────────────────────────
    alertas = []
    # Garantía
    if dias_en_garantia is not None:
        if dias_en_garantia < 0:
            alertas.append({
                "severidad": "warning",
                "icono": "shield-x",
                "texto": f"Garantía vencida hace {abs(dias_en_garantia)} día(s)",
            })
        elif dias_en_garantia <= 30:
            alertas.append({
                "severidad": "warning",
                "icono": "shield-exclamation",
                "texto": f"Garantía vence en {dias_en_garantia} día(s)",
            })
    # Visitas preventivas
    if not n_preventivas and len(historial_visitas) > 0:
        alertas.append({
            "severidad": "info",
            "icono": "calendar-x",
            "texto": "Este equipo nunca ha tenido una mantención preventiva",
        })
    elif n_preventivas and dias_desde_ultima is not None and dias_desde_ultima > 120:
        alertas.append({
            "severidad": "warning",
            "icono": "clock-history",
            "texto": f"Sin visita preventiva en {dias_desde_ultima // 30} mes(es)",
        })
    # Serial cambiado recientemente
    if historial_seriales:
        try:
            f_cambio = historial_seriales[0].get("fecha")
            if f_cambio:
                f_d = datetime.strptime(f_cambio[:10], "%Y-%m-%d").date()
                dias_cambio = (hoy - f_d).days
                if dias_cambio <= 60:
                    alertas.append({
                        "severidad": "info",
                        "icono": "info-circle",
                        "texto": f"Serial cambiado hace {dias_cambio} día(s) — verificar coincidencia con activo físico",
                    })
        except Exception:
            pass
    # Estado: si está dado de baja
    if (eq.get("estado") or "").lower() == "baja":
        alertas.append({
            "severidad": "danger",
            "icono": "x-octagon",
            "texto": "Equipo dado de baja",
        })
    elif (eq.get("estado_op") or "").lower() in ("critico", "fuera_servicio"):
        alertas.append({
            "severidad": "danger",
            "icono": "exclamation-triangle",
            "texto": f"Estado operacional: {eq.get('estado_op')}",
        })
    # Sin fotos
    if not fotos_galeria and len(historial_visitas) > 0:
        alertas.append({
            "severidad": "info",
            "icono": "image",
            "texto": "Sin fotos en la galería del equipo — captura una en la próxima visita",
        })

    # ── 8. Datos del equipo (formateados) ──────────────────────────
    out_eq = {
        "id": eq["id"],
        "cliente_id": cliente_id,
        "razon_social": eq.get("razon_social") or "",
        "cli_rut": eq.get("cli_rut") or "",
        "cli_direccion": eq.get("cli_direccion") or "",
        "cli_comuna": eq.get("cli_comuna") or "",
        "nombre": eq.get("nombre") or "",
        "sku": eq.get("sku") or "",
        "serie": eq.get("serie") or "",
        "serie_actual": eq.get("serie") or "",
        # 2026-08-20 — el bloque que calcula estos 4 valores escribía sobre
        # `eq`, pero lo que viaja al navegador es este `out_eq`, armado
        # campo por campo. Por eso `serie_sugerida` (2026-06-10) llevaba
        # meses calculándose y NUNCA llegaba al modal: el banner "Serie
        # sugerida · Usar" existía en el JS y no podía aparecer jamás.
        # Detectado al verificar en producción, no en revisión de código.
        # `serie_sugerida` va como string o None a propósito: el modal hace
        # String(...) y lo graba con un click en el campo que alimenta la
        # etiqueta de garantía.
        "serie_sugerida": eq.get("serie_sugerida"),
        "serie_lleva_individual": eq.get("serie_lleva_individual", True),
        "serie_no_aplica_motivo": eq.get("serie_no_aplica_motivo") or "",
        "serie_es_provisoria": eq.get("serie_es_provisoria", False),
        "marca": eq.get("marca") or "",
        "modelo": eq.get("modelo") or "",
        "anio_fabricacion": eq.get("anio_fabricacion"),
        "voltaje": eq.get("voltaje") or "",
        "ubicacion_sala": eq.get("ubicacion_sala") or "",
        "ubicacion_cliente": eq.get("ubicacion_cliente") or "",
        "familia_equipo": eq.get("familia_equipo") or "",
        "fecha_instalacion": str(eq["fecha_instalacion"])[:10] if eq.get("fecha_instalacion") else "",
        "fecha_fin_garantia": str(eq["fecha_fin_garantia"])[:10] if eq.get("fecha_fin_garantia") else "",
        "estado": eq.get("estado") or "activo",
        "estado_op": eq.get("estado_op") or "operativo",
        # 2026-06-10 (Daniel): el front precarga el toggle "En plan" del
        # formulario de edicion desde este campo (default 1 si viene null).
        "aplica_mantencion": 1 if (eq.get("aplica_mantencion") if eq.get("aplica_mantencion") is not None else 1) else 0,
        "estado_capturado": eq.get("estado_capturado") or "",
        "tiene_dano": bool(eq.get("tiene_dano")),
        "observaciones": eq.get("observaciones") or "",
        "foto_url": eq.get("foto_url") or "",
        "foto_principal_url": foto_principal_url,
        "tag_1": eq.get("tag_1") or "",
        "tag_2": eq.get("tag_2") or "",
        "ultima_intervencion": str(eq["ultima_intervencion"])[:10] if eq.get("ultima_intervencion") else "",
        "visitas_count": int(eq.get("visitas_count") or 0),
        "doc_origen": eq.get("doc_origen") or "",
        "doc_fecha": str(eq["doc_fecha"])[:10] if eq.get("doc_fecha") else "",
        # 2026-05-26 (Daniel) — Datos físicos visibles en tab Resumen
        "peso_kg": float(eq["peso_kg"]) if eq.get("peso_kg") is not None else None,
        "dimensiones": eq.get("dimensiones") or "",
        "color": eq.get("color") or "",
    }

    # ── 9. (2026-05-21 Daniel) — Última revisión + timeline desde
    #       mant_visita_equipos. Da contexto inmediato al usuario sobre
    #       el estado real del equipo en la última visita.
    ultima_revision = None
    revisiones_counters = {
        "total": 0, "verificado": 0, "con_cambios": 0,
        "saltado": 0, "falla_detectada": 0,
    }
    revisiones_timeline = []
    try:
        rev_rows = mysql_fetchall(
            "SELECT ve.visita_id, ve.estado_revision, ve.razon_saltado, "
            "       ve.observacion_tecnico, ve.revisado_at, ve.revisado_por, "
            "       v.numero_ot, v.tipo AS visita_tipo, v.fecha_programada, "
            "       v.estado AS visita_estado "
            "  FROM mant_visita_equipos ve "
            "  JOIN mant_visitas v ON v.id = ve.visita_id "
            " WHERE ve.maquina_id=%s "
            " ORDER BY COALESCE(ve.revisado_at, v.fecha_programada) DESC, ve.id DESC "
            " LIMIT 50",
            (mid,)
        ) or []
        for _r in rev_rows:
            _est = (_r.get("estado_revision") or "verificado").lower()
            revisiones_counters["total"] += 1
            revisiones_counters[_est] = revisiones_counters.get(_est, 0) + 1
            revisiones_timeline.append({
                "visita_id":       _r["visita_id"],
                "numero_ot":       _r.get("numero_ot") or f"VS-{_r['visita_id']:05d}",
                "tipo_visita":     _r.get("visita_tipo") or "",
                "estado_visita":   _r.get("visita_estado") or "",
                "fecha":           str(_r["fecha_programada"])[:10] if _r.get("fecha_programada") else "",
                "revisado_at":     str(_r["revisado_at"])[:16] if _r.get("revisado_at") else "",
                "revisado_por":    _r.get("revisado_por") or "",
                "estado_revision": _est,
                "razon_saltado":   _r.get("razon_saltado") or "",
                "observacion":     _r.get("observacion_tecnico") or "",
                "url_ot":          f"/mantenciones/ot/{_r['visita_id']}",
            })
        if revisiones_timeline:
            ultima_revision = revisiones_timeline[0]
    except Exception as _e_rev:
        print(f"[ficha-tecnica] revisiones load error: {_e_rev}", flush=True)

    # ── CALIDAD DE FICHA 2026-05-26 (Daniel — Ficha técnica CMMS) ──
    # Score 0-100 con criterios objetivos. Daniel quiere ver de un vistazo
    # qué equipos tienen ficha completa vs incompleta para priorizar
    # levantamientos pendientes. Cada criterio aporta puntos:
    _cal_score = 0
    _cal_checks = []
    def _cal_add(criterio, puntos, cumple):
        nonlocal _cal_score
        if cumple:
            _cal_score += puntos
        _cal_checks.append({
            "criterio": criterio, "puntos": puntos, "cumple": bool(cumple)
        })
    _cal_add("Foto principal cargada", 12, bool(foto_principal_url or fotos_galeria))
    _cal_add("Número de serie informado", 10, bool(eq.get("serie")))
    _cal_add("SKU informado", 8, bool(eq.get("sku")))
    _cal_add("Categoría / familia", 8, bool(eq.get("familia_equipo") and eq.get("familia_equipo") != "otros"))
    _cal_add("Ubicación informada", 8, bool(eq.get("ubicacion_sala") or eq.get("ubicacion_cliente")))
    _cal_add("Marca / modelo", 8, bool(eq.get("marca") or eq.get("modelo")))
    _cal_add("Año de fabricación", 6, bool(eq.get("anio_fabricacion")))
    _cal_add("Contrato vigente asociado", 12, bool(contratos))
    _cal_add("Al menos una foto en galería", 10, len(fotos_galeria) >= 1)
    _cal_add("Al menos un levantamiento/revisión", 10, bool(revisiones_timeline) or bool(historial_visitas))
    _cal_add("Observaciones registradas", 4, bool(eq.get("observaciones")))
    _cal_add("Fecha de garantía conocida", 4, bool(eq.get("fecha_fin_garantia") or eq.get("fecha_instalacion")))
    _cal_score = min(100, _cal_score)
    _cal_estado = (
        "completa" if _cal_score >= 80
        else "buena" if _cal_score >= 60
        else "revisar_datos" if _cal_score >= 40
        else "incompleta"
    )
    calidad_ficha = {
        "score": _cal_score,
        "estado": _cal_estado,
        "criterios": _cal_checks,
        "pendientes": [c["criterio"] for c in _cal_checks if not c["cumple"]],
    }

    _ft_response = {
        "ok": True,
        "equipo": out_eq,
        "stats": stats,
        "historial_visitas": historial_visitas,
        "historial_seriales": historial_seriales,
        "historial_estado": historial_estado,
        "fotos_galeria": fotos_galeria,
        "contratos_relacionados": contratos,
        "alertas": alertas,
        # 2026-05-26 (Daniel — ficha CMMS) — calidad de información
        "calidad_ficha": calidad_ficha,
        # 2026-05-21 (Daniel) — trazabilidad por equipo
        "ultima_revision": ultima_revision,
        "revisiones_timeline": revisiones_timeline,
        "revisiones_counters": revisiones_counters,
        # Compatibilidad backward — endpoints antiguos esperan estos campos
        "fotos": fotos_galeria[:8],
        "contratos": contratos,
        "ots": [
            {
                "id": h["id"],
                "numero_ot": h["numero_ot"],
                "titulo": h["titulo"],
                "tipo": h["tipo"],
                "estado": h["estado"],
                "fecha": h["fecha"],
                "tecnico": h["tecnico"],
                "url": h["url"],
            }
            for h in historial_visitas[:5]
        ],
        "ficha_url": f"/mantenciones/maquinas/{mid}",
    }
    # Guardar en cache (TTL 60s) — siguiente click en ese equipo es instantáneo
    with _FT_JSON_LOCK:
        _FT_JSON_CACHE[mid] = (_ft_response, time.time())
    return jsonify(_ft_response)


# ════════════════════════════════════════════════════════════════════════
# SYNC fotos del levantamiento → galería del equipo (Daniel 2026-05-26)
# Soluciona el caso histórico donde el INSERT a mant_maquina_fotos pudo
# fallar silenciosamente (try/except en upload de foto del levantamiento)
# y dejó las fotos huérfanas en mant_levantamiento_fotos.
# Anti-duplicado por cloudinary_url. Idempotente.
# ════════════════════════════════════════════════════════════════════════
@app.route("/mantenciones/api/maquinas/<int:mid>/sync-fotos-lev", methods=["POST"])
@_mant_required
def mant_maquina_sync_fotos_lev(mid):
    """Copia fotos huérfanas de mant_levantamiento_fotos → mant_maquina_fotos."""
    eq = mysql_fetchone("SELECT id, cliente_id FROM mant_maquinas WHERE id=%s", (mid,))
    if not eq:
        return jsonify({"ok": False, "error": "Equipo no encontrado"}), 404

    # 1) Fotos del levantamiento que apuntan a este equipo
    huerfanas = mysql_fetchall(
        """
        SELECT lf.id, lf.levantamiento_id, lf.cloudinary_url, lf.cloudinary_public_id,
               lf.tipo_foto, lf.descripcion, lf.tomada_por, lf.tomada_at
          FROM mant_levantamiento_fotos lf
         WHERE lf.maquina_id = %s
           AND lf.cloudinary_url IS NOT NULL
           AND lf.cloudinary_url <> ''
           AND NOT EXISTS (
                 SELECT 1 FROM mant_maquina_fotos mf
                  WHERE mf.maquina_id = lf.maquina_id
                    AND mf.cloudinary_url = lf.cloudinary_url
               )
        """,
        (mid,)
    ) or []

    # 2) Fotos de visitas que apuntan a este equipo (alternativo)
    huerfanas_vis = mysql_fetchall(
        """
        SELECT vf.id, vf.visita_id, vf.cloudinary_url, vf.cloudinary_public_id,
               vf.tipo_foto, vf.descripcion, vf.subida_por AS tomada_por, vf.created_at AS tomada_at
          FROM mant_visita_fotos vf
         WHERE vf.maquina_id = %s
           AND vf.cloudinary_url IS NOT NULL
           AND vf.cloudinary_url <> ''
           AND NOT EXISTS (
                 SELECT 1 FROM mant_maquina_fotos mf
                  WHERE mf.maquina_id = vf.maquina_id
                    AND mf.cloudinary_url = vf.cloudinary_url
               )
        """,
        (mid,)
    ) or []

    copiadas = 0
    errores = []
    conn = get_mysql()
    try:
        with conn.cursor() as cur:
            for f in huerfanas:
                try:
                    cur.execute(
                        """
                        INSERT INTO mant_maquina_fotos
                          (maquina_id, archivo_path, cloudinary_url, cloudinary_public_id,
                           levantamiento_id, tipo_foto, descripcion, tomada_por, tomada_at)
                        VALUES (%s, '', %s, %s, %s, %s, %s, %s, %s)
                        """,
                        (
                            mid,
                            f["cloudinary_url"],
                            f.get("cloudinary_public_id") or "",
                            f.get("levantamiento_id"),
                            (f.get("tipo_foto") or "principal")[:30],
                            (f.get("descripcion") or "")[:500],
                            (f.get("tomada_por") or "sync")[:190],
                            f.get("tomada_at"),
                        )
                    )
                    copiadas += 1
                except Exception as e_one:
                    errores.append(f"lev_foto#{f['id']}: {str(e_one)[:120]}")
            for f in huerfanas_vis:
                try:
                    cur.execute(
                        """
                        INSERT INTO mant_maquina_fotos
                          (maquina_id, archivo_path, cloudinary_url, cloudinary_public_id,
                           visita_origen, tipo_foto, descripcion, tomada_por, tomada_at)
                        VALUES (%s, '', %s, %s, %s, %s, %s, %s, %s)
                        """,
                        (
                            mid,
                            f["cloudinary_url"],
                            f.get("cloudinary_public_id") or "",
                            f.get("visita_id"),
                            (f.get("tipo_foto") or "principal")[:30],
                            (f.get("descripcion") or "")[:500],
                            (f.get("tomada_por") or "sync")[:190],
                            f.get("tomada_at"),
                        )
                    )
                    copiadas += 1
                except Exception as e_one:
                    errores.append(f"vis_foto#{f['id']}: {str(e_one)[:120]}")
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        return jsonify({"ok": False, "error": f"Error en sync: {str(e)[:200]}"}), 500
    finally:
        try: conn.close()
        except Exception: pass

    return jsonify({
        "ok": True,
        "copiadas": copiadas,
        "candidatas_lev": len(huerfanas),
        "candidatas_vis": len(huerfanas_vis),
        "errores": errores[:5],   # primeros 5 errores si hubo
    })


# ════════════════════════════════════════════════════════════════════════
# PATCH equipo — Edición desde el modal "Ficha técnica" (Daniel 2026-05-21)
# Permite cambiar serial / estado / observaciones / ubicación con audit log
# automático. Whitelist estricto de campos editables.
# AMPLIADO 2026-07-08 (Daniel): también nombre y SKU, auditados sin motivo
# obligatorio (corrige errores de tipeo del técnico en terreno).
# ════════════════════════════════════════════════════════════════════════
@app.route("/mantenciones/api/maquinas/<int:mid>", methods=["PATCH"])
@_mant_required
def mant_maquina_patch(mid):
    """Actualiza campos editables del equipo con auditoría completa.

    Campos permitidos (whitelist):
      nombre, sku, serie, marca, modelo, voltaje, anio_fabricacion,
      ubicacion_sala, observaciones, estado, estado_op,
      fecha_instalacion, fecha_fin_garantia, tag_1, tag_2

    Cada cambio en un campo CRÍTICO (nombre, sku, serie, estado, estado_op)
    genera un insert en mant_maquina_audit con valor_antes / valor_nuevo /
    motivo / usuario / fecha. Requiere `motivo` (≥5 chars) SOLO para
    serie/estado (cambios operativamente delicados). 'nombre' y 'sku'
    quedan auditados automáticamente SIN exigir motivo — 2026-07-08
    (Daniel): un técnico escribió mal el nombre de un equipo en terreno
    ("B8sicleta de Spinning..." en vez de "Bicicleta...") y ni Daniel ni
    Aarón podían corregirlo desde la ficha. El pedido explícito es
    trazabilidad automática (quién/cuándo/antes→después), no fricción
    para quien corrige un error de tipeo.
    """
    eq = mysql_fetchone(
        "SELECT id, cliente_id, nombre, sku, serie, marca, modelo, voltaje, "
        "       anio_fabricacion, ubicacion_sala, observaciones, "
        "       estado, estado_op, fecha_instalacion, fecha_fin_garantia, "
        "       tag_1, tag_2, COALESCE(aplica_mantencion,1) AS aplica_mantencion, "
        "       familia_equipo, peso_kg, dimensiones, color "
        "  FROM mant_maquinas WHERE id=%s",
        (mid,)
    )
    if not eq:
        return jsonify({"ok": False, "error": "Equipo no encontrado"}), 404

    # Permisos: técnico/tecnico_externo NO puede editar la ficha desde acá.
    # Solo admin/superadmin/ejecutivo. La edición durante una OT pasa por
    # /api/visitas/<vid>/equipo/<mid>/datos (controlado por _tecnico_owns_visita).
    u = getattr(g, "user", None) or {}
    role_u = (u.get("role") or "").lower()
    if role_u in ("tecnico", "tecnico_externo"):
        return jsonify({
            "ok": False,
            "error": "Solo administrador, ejecutivo o supervisor puede editar "
                     "la ficha del equipo. Si necesitas cambiar algo, hazlo "
                     "desde la OT donde estás trabajando.",
        }), 403

    d = request.get_json(silent=True) or {}
    motivo = (d.get("motivo") or "").strip()[:500]

    # Whitelist con tipo y longitud máxima. 'nombre' y 'sku' respetan el
    # tamaño real de las columnas (VARCHAR(400) / VARCHAR(100) en
    # mant_maquinas — mismo maxlen usado en el resto del código, ej.
    # _lev_materializar_equipos_nuevos) para que el truncado sea consistente.
    str_fields = {
        "serie": 100, "marca": 120, "modelo": 120, "voltaje": 40,
        "ubicacion_sala": 200, "observaciones": 5000,
        "tag_1": 80, "tag_2": 80,
        "dimensiones": 120, "color": 60,
        "nombre": 400, "sku": 100,
    }
    estado_values = ("activo", "inactivo", "baja")
    estado_op_values = ("operativo", "advertencia", "critico",
                        "fuera_servicio", "en_mantencion", "en_reparacion")
    sets, vals, cambios_criticos = [], [], []

    # Campos que quedan auditados en mant_maquina_audit sin exigir motivo
    # (a diferencia de 'serie', que sí lo exige justo abajo). Ver docstring.
    _campos_audit_libre = ("nombre", "sku")

    # Campos string
    for k, maxlen in str_fields.items():
        if k in d:
            v_nuevo = (str(d.get(k) or "").strip())[:maxlen] or None
            v_antes = eq.get(k) or None
            # El nombre es la identidad visible del equipo: el front ya lo
            # exige no-vacío, pero blindamos también acá por si alguien
            # llama al PATCH directo (Postman, integración futura, etc.)
            # sin pasar por el modal.
            if k == "nombre" and not v_nuevo:
                return jsonify({
                    "ok": False,
                    "error": "El nombre del equipo no puede quedar vacío.",
                }), 400
            sets.append(f"{k}=%s"); vals.append(v_nuevo)
            if (v_antes or "") != (v_nuevo or ""):
                if k == "serie":
                    if len(motivo) < 5:
                        return jsonify({
                            "ok": False,
                            "error": "El cambio de N° serie requiere un motivo "
                                     "de al menos 5 caracteres.",
                        }), 400
                    cambios_criticos.append(("serie", v_antes, v_nuevo))
                elif k in _campos_audit_libre:
                    cambios_criticos.append((k, v_antes, v_nuevo))

    # Estado / estado_op (validar enum)
    if "estado" in d:
        v_nuevo = (str(d.get("estado") or "").strip().lower()) or None
        if v_nuevo not in (None,) + estado_values:
            return jsonify({"ok": False, "error": f"Estado inválido: {v_nuevo}"}), 400
        v_antes = (eq.get("estado") or "").lower() or None
        if v_antes != v_nuevo:
            if len(motivo) < 5:
                return jsonify({
                    "ok": False,
                    "error": "El cambio de estado del equipo requiere un motivo "
                             "de al menos 5 caracteres.",
                }), 400
            cambios_criticos.append(("estado", v_antes, v_nuevo))
        sets.append("estado=%s"); vals.append(v_nuevo)

    if "estado_op" in d:
        v_nuevo = (str(d.get("estado_op") or "").strip().lower()) or None
        if v_nuevo not in (None,) + estado_op_values:
            return jsonify({"ok": False, "error": f"Estado operacional inválido: {v_nuevo}"}), 400
        v_antes = (eq.get("estado_op") or "").lower() or None
        if v_antes != v_nuevo:
            cambios_criticos.append(("estado_op", v_antes, v_nuevo))
        sets.append("estado_op=%s"); vals.append(v_nuevo)

    # Numéricos
    if "anio_fabricacion" in d:
        try:
            v = int(d["anio_fabricacion"]) if d["anio_fabricacion"] not in (None, "") else None
        except (TypeError, ValueError):
            v = None
        sets.append("anio_fabricacion=%s"); vals.append(v)

    if "peso_kg" in d:
        try:
            v = round(float(d["peso_kg"]), 2) if d["peso_kg"] not in (None, "") else None
        except (TypeError, ValueError):
            v = None
        sets.append("peso_kg=%s"); vals.append(v)

    # Horómetro (2026-08-06, grúas SPHS): cada cuántas horas toca la pauta
    # técnica de la marca. NULL = este equipo no se rastrea por horas.
    if "horometro_pauta_horas" in d:
        try:
            v = int(d["horometro_pauta_horas"]) if d["horometro_pauta_horas"] not in (None, "") else None
            if v is not None and v <= 0:
                v = None
        except (TypeError, ValueError):
            v = None
        sets.append("horometro_pauta_horas=%s"); vals.append(v)

    # Familia / categoría del equipo
    _familias_ok = ("cardio","selectorizado","carga_libre","racks_estructuras",
                    "bancos","accesorios","bicicletas","trotadoras","otros")
    if "familia_equipo" in d:
        v = (str(d.get("familia_equipo") or "").strip().lower()) or None
        if v and v not in _familias_ok:
            return jsonify({"ok": False, "error": f"Categoría inválida: {v}"}), 400
        sets.append("familia_equipo=%s"); vals.append(v)

    # Fechas (validar formato ISO)
    for f in ("fecha_instalacion", "fecha_fin_garantia"):
        if f in d:
            raw = (str(d.get(f) or "").strip()) or None
            if raw:
                try:
                    datetime.strptime(raw, "%Y-%m-%d")
                except ValueError:
                    return jsonify({"ok": False, "error": f"Formato inválido en {f} (usa YYYY-MM-DD)"}), 400
            sets.append(f"{f}=%s"); vals.append(raw)

    # aplica_mantencion (0/1): "En plan" vs "Sin mantención". El front lo
    # manda junto al resto de la edición. NO requiere motivo (no es crítico),
    # pero sí dejamos rastro en mant_logs si cambia (igual que el toggle
    # individual PUT .../aplica-mantencion → accion 'aplica_mantencion' si/no).
    cambio_aplica = None
    if "aplica_mantencion" in d:
        v_nuevo = 1 if d.get("aplica_mantencion") in (1, True, "1", "true", "True") else 0
        v_antes = 1 if int(eq.get("aplica_mantencion") or 1) else 0
        sets.append("aplica_mantencion=%s"); vals.append(v_nuevo)
        if v_antes != v_nuevo:
            cambio_aplica = (v_antes, v_nuevo)

    if not sets:
        return jsonify({"ok": False, "error": "Sin campos para actualizar"}), 400

    vals.append(mid)
    try:
        mysql_execute(
            f"UPDATE mant_maquinas SET {','.join(sets)} WHERE id=%s",
            tuple(vals)
        )
    except Exception as e:
        # FIX 2026-07-08 (Daniel — OT-2026-00031, "el serial siempre debe
        # ser único"): un choque contra uq_cliente_serie (cliente_id,
        # serie) devolvía el error crudo de MySQL al cliente. La edición
        # MANUAL de serie SÍ debe poder fallar cuando el usuario elige a
        # propósito una serie que ya existe (a diferencia de la creación
        # automática, acá es una decisión consciente) — solo mejoramos el
        # mensaje, no el comportamiento de fondo (REGLA #4: no exponer
        # detalles internos de MySQL al cliente).
        msg = str(e)
        print(f"[mant_maquina_patch] UPDATE mid={mid} falló: {msg}", flush=True)
        if "uq_cliente_serie" in msg or "Duplicate entry" in msg:
            return jsonify({
                "ok": False,
                "error": "Ya existe un equipo con esa serie para este cliente. "
                         "Cada N° de serie debe ser único.",
                "error_codigo": "SERIE_DUPLICADA",
            }), 409
        return jsonify({"ok": False, "error": f"Error guardando: {e}"}), 500

    # Audit log para cambios críticos
    usuario = current_username() or "sistema"
    for campo, antes, nuevo in cambios_criticos:
        try:
            mysql_execute(
                "INSERT INTO mant_maquina_audit "
                "(maquina_id, cliente_id, campo, valor_antes, valor_nuevo, "
                " motivo, usuario) VALUES (%s,%s,%s,%s,%s,%s,%s)",
                (mid, eq.get("cliente_id"), campo,
                 antes or "", nuevo or "",
                 motivo or "(sin motivo registrado)",
                 usuario[:190])
            )
        except Exception as _e_aud:
            print(f"[mant_maquina_patch] audit {campo} fallo: {_e_aud}",
                  flush=True)

    # Audit log general
    try:
        cambios_resumen = ", ".join([f"{c}: '{a}' → '{n}'" for c, a, n in cambios_criticos]) \
                        or "edición general"
        _mant_log("maquina", mid, "ficha_editada", cambios_resumen[:500])
    except Exception:
        pass

    # Audit del cambio de aplica_mantencion (mismo formato que el toggle
    # individual: accion 'aplica_mantencion', detalle 'si'/'no').
    if cambio_aplica is not None:
        try:
            _mant_log("maquina", mid, "aplica_mantencion",
                      "si" if cambio_aplica[1] else "no")
        except Exception:
            pass

    return jsonify({
        "ok": True,
        "cambios_criticos": [
            {"campo": c, "antes": a, "nuevo": n}
            for c, a, n in cambios_criticos
        ],
        "actualizado_en": _now_chile_str("%d/%m/%Y %H:%M"),
    })


